<#
.SYNOPSIS
    Completion Navigator build and authoring toolkit.

.DESCRIPTION
    Manages the Completion Navigator WoW addon from PowerShell instead of by
    hand-editing Lua. Place this file in the addon folder:

        ...\_retail_\Interface\AddOns\CompletionNavigator\cn.ps1

    Then run commands from that folder:

        .\cn.ps1 init
        .\cn.ps1 new module Pets
        .\cn.ps1 cmd pets -Module Pets -Usage "<petID>" -Help "Check a pet."
        .\cn.ps1 event PET_JOURNAL_LIST_UPDATE -Module Pets
        .\cn.ps1 sync
        .\cn.ps1 check

.NOTES
    Completion Navigator
    Author: Travis A. Bryan I
    Copyright (c) 2026 Dam Beaver Studios, LLC. Released under the MIT License.
    Owned, published and maintained by Dam Beaver Studios, LLC.

    The addon folder lives under C:\Program Files (x86)\... on this machine,
    which is ACL-protected. Run PowerShell as Administrator, or move the addon
    to a writable location and symlink it back.
#>

[CmdletBinding()]
param(
    [Parameter(Position = 0)] [string] $Command = 'help',
    [Parameter(Position = 1)] [string] $Target,
    [Parameter(Position = 2)] [string] $Value,

    [string] $Name,
    [string] $Usage,
    [string] $Help,
    [string] $Module,
    [int]    $Order = 50,
    [string] $Expansion,
    [int]    $MapID,
    [double] $X,
    [double] $Y,
    [string] $Requires,
    [string] $Email,
    [switch] $Force,

    # Retrying a release whose build failed: delete the tag, here and on the
    # remote, and cut it again. Distinct from -Force, which overrides checks.
    [switch] $Retag,

    # `ci -Watch` follows a run to completion instead of the author
    # re-running the command every thirty seconds, which is how an
    # unauthenticated API budget of sixty an hour gets spent in ten minutes.
    [switch] $Watch
)

$ErrorActionPreference = 'Stop'

$script:Root       = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
$script:BackupDir  = Join-Path $script:Root '_backups'
$script:TocPath    = Join-Path $script:Root 'CompletionNavigator.toc'
$script:BeginMark  = '# CN:FILES:BEGIN -- managed by cn.ps1 sync; do not edit by hand.'
$script:EndMark    = '# CN:FILES:END'
$script:AppendMark = '-- CN:APPEND'
$script:DataMark   = '-- CN:DATA:QUESTS'

# The version of the addon source embedded in THIS file. Written by the
# generator from Core.lua, so it can never drift from what gets scaffolded.
#
# This exists because a stale cn.ps1 is otherwise invisible: it scaffolds a
# previous release over a newer tree, reports success, and every downstream
# step then fails for reasons that look unrelated.
$script:ToolkitVersion = '0.89.0'

# The repository the CI commands ask about. Derived from the git remote when
# there is one, so a fork does not report the upstream's builds.
$script:Repo = 'Dam-Beaver-Studios-LLC/CompletionNavigator'

# Fixed load order for root-level files. Anything not listed here sorts after
# these, alphabetically, inside its own folder group.
$script:RootOrder = @(
    'Core.lua',
    'Database.lua',
    'Objectives.lua',
    'Dependencies.lua',
    'Character.lua',
    'Events.lua',
    'Commands.lua',
    'Scoring.lua',
    'Routing.lua',
    'UI.lua'
)

# Providers must load before Data: Data files call CN.Static.Register* at
# file scope, and CN.Static is created by Providers\StaticData.lua.
$script:FolderOrder = @('Providers', 'Data', 'Modules')

$Embedded = [ordered]@{}

$Embedded['Core.lua'] = @'
-- Core.lua
-- Completion Navigator :: namespace, logging, and registries.
--
-- Load order: FIRST. Nothing may be added above this file.
--
-- This file intentionally contains no gameplay logic. It exists so that
-- every other file can register itself declaratively:
--
--   CN:RegisterCommand{ ... }
--   CN:RegisterEvent("EVENT_NAME", handler)
--   CN:RegisterModule("Quests")
--
-- That makes the codebase append-only for tooling purposes: adding a
-- command or an event never requires editing a dispatcher.

local ADDON_NAME, CN = ...

_G.CompletionNavigator = CN

CN.name        = ADDON_NAME
CN.version     = "0.89.0"
CN.dbVersion   = 34

-- Where the addon's own textures live. Referenced by the .toc IconTexture
-- line and the minimap button.
CN.MEDIA_PATH  = "Interface\\AddOns\\CompletionNavigator\\Media\\"

------------------------------------------------------------
-- REGISTRIES
------------------------------------------------------------

CN.modules     = {}   -- [name]  = module table
CN.commands    = {}   -- [name]  = command definition
CN.commandList = {}   -- ordered list of command definitions (for /cn help)
CN.eventTable  = {}   -- [event] = { handler, handler, ... }
CN.initHooks   = {}   -- functions run on ADDON_LOADED, after the DB exists
CN.loginHooks  = {}   -- functions run on PLAYER_LOGIN
CN.logoutHooks = {}   -- functions run on PLAYER_LOGOUT

------------------------------------------------------------
-- OUTPUT
------------------------------------------------------------

-- THE ADDON'S NAME ONCE PER ANSWER, NOT ONCE PER LINE.
--
-- Every line went out with "Completion Navigator: " in front of it, and this
-- addon answers in blocks: `/cn next` is four to six lines, `/cn help` is
-- twenty, `/cn uistatus` is twelve. Twenty-two characters of chrome per line
-- turned every answer into a wall of the addon's own name, in a chat frame
-- the player is also using for the game.
--
-- The headline carries the name. Continuations are indented under it, which
-- is what a block of related lines has looked like in every medium for four
-- hundred years, and costs three characters instead of twenty-two.
local PREFIX       = "|cff5dd2fbCompletion Navigator|r: "
local CONTINUATION = "   "
local DEBUG_PREFIX = "|cff8a8f96Completion Navigator Debug|r: "

function CN.Print(message)
    DEFAULT_CHAT_FRAME:AddMessage(PREFIX .. tostring(message))
end

-- A continuation of the line above: same answer, no repeated identity.
function CN.PrintLine(message)
    DEFAULT_CHAT_FRAME:AddMessage(CONTINUATION .. tostring(message))
end

-- The common shape: one headline and its detail. Saves every caller from
-- deciding which of the two to use, and makes the block structure visible in
-- the source as well as on screen.
function CN.PrintBlock(headline, lines)
    CN.Print(headline)

    for _, line in ipairs(lines or {}) do
        CN.PrintLine(line)
    end
end

function CN.DebugPrint(message)
    if CN.db and CN.db.settings and CN.db.settings.debug then
        DEFAULT_CHAT_FRAME:AddMessage(DEBUG_PREFIX .. tostring(message))
    end
end

-- IS ANYBODY LISTENING? 0.63.0.
--
-- `DebugPrint` checks the setting AFTER the caller has already built the
-- string, because Lua evaluates arguments at the call site. The hot one is
-- `CN.InvalidateCandidates`, which runs once per subscribed event -- and the
-- subscribed set includes `QUEST_LOG_UPDATE`, `CRITERIA_UPDATE` and
-- `UPDATE_FACTION`, all firehoses while questing. Four concatenations and
-- three intermediate strings, tens of times a second, for output nobody can
-- see.
--
-- Callers on a hot path ask first and build second.
function CN.Debugging()
    return (CN.db and CN.db.settings and CN.db.settings.debug) and true or false
end

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

-- Colorized yes/no used throughout the completion output.
function CN.YesNo(value)
    -- Sentence case, not shouting. "YES" beside sentence-case labels was the
    -- loudest thing in the addon's output and it was answering the smallest
    -- questions.
    if value then
        return CN.Good("yes")
    end

    return CN.Bad("no")
end

------------------------------------------------------------
-- MODULE REGISTRY
------------------------------------------------------------

-- Returns a table that a module file can hang its functions on.
-- Calling it twice with the same name returns the same table, so module
-- files can be split later without breaking references.
function CN:RegisterModule(name)
    if CN.modules[name] then
        return CN.modules[name]
    end

    local module = {
        name   = name,
        Print  = CN.Print,
        Debug  = CN.DebugPrint,
    }

    CN.modules[name] = module

    return module
end

function CN:GetModule(name)
    return CN.modules[name]
end

------------------------------------------------------------
-- COMMAND REGISTRY
------------------------------------------------------------

-- definition = {
--     name    = "quest",              -- required, lowercase
--     aliases = { "q" },              -- optional
--     args    = "<questID>",          -- optional, shown in /cn help
--     help    = "Check a quest.",     -- optional, shown in /cn help
--     order   = 50,                   -- optional sort weight for help
--     handler = function(args) end,   -- required
-- }
function CN:RegisterCommand(definition)
    if type(definition) ~= "table" then
        return
    end

    if not definition.name or type(definition.handler) ~= "function" then
        Print("Internal error: malformed command registration.")
        return
    end

    definition.name  = string.lower(definition.name)
    definition.order = definition.order or 100

    -- A NAME CLAIMED TWICE IS A COMMAND THAT DOES SOMETHING ELSE.
    --
    -- Registration used to overwrite silently, so whichever file loaded last
    -- won and `/cn help` went on describing the loser. `/cn zones` was
    -- registered by Loremaster as a command and, further down the same file,
    -- as an ALIAS of `/cn loremaster` -- so it printed the quest-completion
    -- report while the help text, and the store page, described the zone
    -- ranking. `/cn show` was claimed by both the window and the filters.
    --
    -- Recorded rather than refused: refusing would change which command wins
    -- at load time, and the answer to a collision is to fix it, not to
    -- reshuffle it. `/cn selftest` names them.
    CN.commandCollisions = CN.commandCollisions or {}

    local function Claim(name, kind)
        local held = CN.commands[name]

        if held and held ~= definition then
            table.insert(CN.commandCollisions, {
                name  = name,
                kind  = kind,
                from  = held.name,
                to    = definition.name,
            })
        end

        CN.commands[name] = definition
    end

    Claim(definition.name, "name")

    if definition.aliases then
        for _, alias in ipairs(definition.aliases) do
            Claim(string.lower(alias), "alias")
        end
    end

    table.insert(CN.commandList, definition)
end

------------------------------------------------------------
-- EVENT REGISTRY
------------------------------------------------------------

-- Multiple files may register the same event. Every handler is called
-- with (event, ...) in registration order.
function CN:RegisterEvent(event, handler)
    if type(event) ~= "string" or type(handler) ~= "function" then
        return
    end

    if not CN.eventTable[event] then
        CN.eventTable[event] = {}
    end

    table.insert(CN.eventTable[event], handler)

    -- Events.lua may not have created the frame yet; if it has, register
    -- with the client immediately.
    if CN.eventFrame then
        CN.RegisterWithClient(event)
    end
end

-- ONE BAD EVENT NAME MUST NOT BE A LUA ERROR ON EVERY LOGIN.
--
-- The client throws on an unknown event rather than ignoring it, and this
-- addon registers around forty of them across thirty files. A single typo --
-- or an invented name that reads plausibly, which is what happened with
-- `NEW_TAXI_NODE` -- produced an error box at load for every player.
--
-- Refusing to register is the correct outcome; erroring is not. The name is
-- kept so `/cn errors` can name it, because an event silently doing nothing
-- is its own kind of invisible.
CN.rejectedEvents = CN.rejectedEvents or {}

function CN.RegisterWithClient(event)
    if not CN.eventFrame or not CN.eventFrame.RegisterEvent then
        return false
    end

    local ok, err = pcall(CN.eventFrame.RegisterEvent, CN.eventFrame, event)

    if not ok then
        CN.rejectedEvents[event] = tostring(err)

        local errors = CN.modules and CN.modules.Errors

        if errors and errors.Record then
            pcall(errors.Record, "RegisterEvent",
                "the client does not have an event called " .. tostring(event))
        end

        return false
    end

    return true
end

------------------------------------------------------------
-- LIFECYCLE HOOKS
------------------------------------------------------------

function CN:OnInitialize(handler)
    table.insert(CN.initHooks, handler)
end

function CN:OnLogin(handler)
    table.insert(CN.loginHooks, handler)
end

function CN:OnLogout(handler)
    table.insert(CN.logoutHooks, handler)
end

function CN.RunHooks(list, ...)
    for _, handler in ipairs(list) do
        local ok, err = pcall(handler, ...)

        if not ok then
            CN.PrintLine("Error: " .. tostring(err))
        end
    end
end

------------------------------------------------------------
-- SHARED UTILITIES
------------------------------------------------------------

-- Recursively fills missing keys in destination from source.
function CN.CopyDefaults(source, destination)
    if type(destination) ~= "table" then
        destination = {}
    end

    for key, value in pairs(source) do
        if type(value) == "table" then
            destination[key] = CN.CopyDefaults(value, destination[key])
        elseif destination[key] == nil then
            destination[key] = value
        end
    end

    return destination
end

-- Normalizes user input into a positive integer ID, or nil.
function CN.ToID(text)
    local id = tonumber(text)

    if not id then
        return nil
    end

    id = math.floor(id)

    if id <= 0 then
        return nil
    end

    return id
end

function CN.CountKeys(tbl)
    local count = 0

    if type(tbl) ~= "table" then
        return 0
    end

    for _ in pairs(tbl) do
        count = count + 1
    end

    return count
end

-- 1234567 -> "1,234,567".
--
-- Reputation numbers are the one place this addon prints figures large
-- enough to be misread, and "42000 to go" reads as a different order of
-- magnitude than "42,000 to go" at a glance.
-- ONE GRAMMAR FOR "MEASURED" VERSUS "ESTIMATED".
--
-- The addon prints a lot of numbers and, until 0.43.0, said how much it
-- trusted each one in a slightly different way every time: "(estimated)"
-- here, "time unknown" there, a grey parenthetical somewhere else. A reader
-- cannot learn three conventions, so in practice they learn none and treat
-- every number as equally solid -- which is the opposite of what all that
-- careful hedging was for.
--
-- Three states, one shape, used everywhere:
--
--   measured  -- from this player's own data, printed plain
--   estimated -- a real calculation on a seeded input, marked
--   unknown   -- not knowable, and the number is not printed at all
CN.confidence = {
    MEASURED  = "measured",
    ESTIMATED = "estimated",
    UNKNOWN   = "unknown",
}

-- Wraps a value in the convention. Returns the text to print.
function CN.WithConfidence(text, level)
    -- Translated. This is the convention every number in the addon is
    -- wrapped in, so leaving it in English left the single most repeated
    -- qualifier a non-English player sees untranslated -- while the word sat
    -- translated in all ten locale files.
    --
    -- CN.L is not available while Core.lua is loading, so the lookup happens
    -- here at call time rather than at file scope.
    if level == CN.confidence.UNKNOWN or text == nil then
        return "|cff8a8f96" .. CN.L["unknown"] .. "|r"
    end

    if level == CN.confidence.ESTIMATED then
        return text .. " |cff8a8f96(" .. CN.L["estimated"] .. ")|r"
    end

    return text
end

-- Convenience for the common case: a boolean "was this measured".
function CN.ConfidenceFor(measured)
    return measured and CN.confidence.MEASURED or CN.confidence.ESTIMATED
end

-- LANGUAGE COMPATIBILITY.
--
-- Everything in this block exists because the game and the test suite run
-- different languages. WoW is Lua 5.1; the suite is 5.4. Anything that
-- behaves differently between them is a defect waiting for a player to find,
-- and 0.43.1 shipped after exactly that happened -- see CN.Atan2 below.
--
-- The rule these enforce is simple: if a construct means two things, the
-- addon uses neither directly. It uses one of these.

-- unpack moved to table.unpack in 5.2. The game still has the global.
CN.Unpack = rawget(table, "unpack") or unpack

-- MODULO ON NEGATIVE NUMBERS.
--
-- `math.fmod` truncates toward zero and `%` floors, so they disagree in sign
-- for negative operands -- and bearings are negative half the time. 5.1 and
-- 5.4 also differ in whether math.fmod accepts floats cleanly.
--
-- This is the floored version, which is what every angle in this addon wants:
-- the result carries the sign of the divisor, so wrapping an angle into a
-- range never produces the wrong half of the circle.
function CN.Mod(value, divisor)
    if not value or not divisor or divisor == 0 then
        return 0
    end

    return value - (math.floor(value / divisor) * divisor)
end

-- THE SINGLE MOST IMPORTANT FUNCTION IN THIS FILE.
--
-- World of Warcraft runs Lua 5.1. The offline test suite runs Lua 5.4. In 5.3
-- and later, `math.atan(y, x)` is the two-argument arctangent; in 5.1 it is
-- the one-argument one and the SECOND ARGUMENT IS SILENTLY IGNORED.
--
--     Lua 5.4:  math.atan(1, 0) == 1.5707963  (90 degrees -- correct)
--     Lua 5.1:  math.atan(1, 0) == 0.7853981  (45 degrees -- atan(1))
--
-- No error. No warning. A number that looks entirely reasonable.
--
-- Every bearing this addon computed IN GAME from 0.19.0 to 0.43.0 was
-- therefore atan(dx), with the north-south component of the direction thrown
-- away -- which is why the arrow never pointed behind the player, and why
-- "it does not turn around when I walk past the destination" was reported
-- three times and "fixed" three times against a test suite where the code was
-- genuinely correct.
--
-- This is the eighth instance in this project of the same class of defect:
-- the test environment modelling the world more simply, or differently, than
-- the world. It is the worst one, because the difference was not in a stub I
-- wrote -- it was in the language itself.
--
-- Use CN.Atan2 for every bearing. Never math.atan with two arguments.
--
-- Assigned rather than wrapped: a wrapper would contain the two-argument call
-- itself, and the suite's rule against that expression is worth more than the
-- one function call it costs. Where math.atan2 exists -- the game, and every
-- Lua before 5.4 -- it is used. Where it does not, math.atan IS the
-- two-argument form, so passing both through is correct.
CN.Atan2 = math.atan2 or math.atan

-- THE SELF-TEST REGISTRY LIVES HERE, NOT IN THE MODULE THAT USES IT.
--
-- It was in Modules/SelfTest.lua, which meant any module registering a check
-- had to load after it -- an invisible constraint that held in the .toc I
-- maintain by hand and broke the moment the toolkit scaffolded the tree in a
-- different order. The failure was a runtime error on load, in a module that
-- has nothing to do with self-tests.
--
-- A registry belongs where everything can see it. The checks stay where they
-- make sense.
CN.selfTests = CN.selfTests or {}

function CN.RegisterSelfTest(definition)
    if type(definition) ~= "table" or type(definition.run) ~= "function" then
        return false
    end

    definition.order = definition.order or (#CN.selfTests + 1)

    table.insert(CN.selfTests, definition)

    return true
end

-- AN EVENT THAT FIRES MANY TIMES A SECOND, ANSWERED ONCE.
--
-- `UPDATE_FACTION` fires on nearly every reputation tick -- this addon says
-- so in three separate files -- and two handlers used it to bump a
-- generation counter. `CN.decoratorGeneration` is the ONE thing that defeats
-- the unchanged-provider shortcut, so bumping it on every tick meant that
-- while a player was questing, i.e. gaining reputation continuously, the
-- shortcut was permanently off and every provider re-decorated on every pass:
-- the measured 0.007 ms to 0.221 ms regression the shortcut exists to remove,
-- back in full, plus a five-decorator sweep over every candidate.
--
-- LEADING EDGE PLUS A TRAILING RUN, not a plain throttle. The first tick is
-- answered immediately, because the common case is one event and a plain
-- throttle would delay it; a burst collapses to one more run at the end,
-- because the LAST tick of a burst is the one that crossed a rank.
--
-- Returns whether the work ran now, so a caller that needs to know can tell.
local debounced = {}

function CN.Debounce(key, seconds, work)
    if type(key) ~= "string" or type(work) ~= "function" then
        return false
    end

    local now   = (GetTime and GetTime()) or (time and time()) or 0
    local state = debounced[key]

    if state and (now - state.ranAt) < seconds then
        -- Inside the window. One trailing run is enough however many events
        -- arrive, so a pending timer is never replaced by a second one.
        if not state.pending and C_Timer and C_Timer.After then
            state.pending = true

            -- The timer's closure holds THIS state table, and
            -- `CN.ForgetDebounces` replaces the whole registry -- so without
            -- this check a forgotten timer would fire against an orphan while
            -- a fresh state, seeing `pending = false`, scheduled a second
            -- one: the work would run twice inside one window, which is the
            -- single thing this function exists to prevent.
            C_Timer.After(seconds - (now - state.ranAt), function()
                if debounced[key] ~= state then
                    return
                end

                state.pending = false
                state.ranAt   = (GetTime and GetTime()) or (time and time()) or 0

                -- `CN.Guard` if Errors.lua has loaded, which it has by the
                -- time any event fires; pcall otherwise, because a callback
                -- that throws inside a timer is invisible.
                if CN.Guard then
                    CN.Guard("Debounce:" .. key, work)
                else
                    pcall(work)
                end
            end)
        end

        return false
    end

    debounced[key] = { ranAt = now, pending = false }

    work()

    return true
end

-- For the tests, and for a reload: a stale timestamp would swallow the first
-- event of a new session.
function CN.ForgetDebounces()
    debounced = {}
end

-- HOW OLD A STORED NUMBER IS, IN WORDS A PLAYER USES.
--
-- `Session.FormatDuration` is the right shape for "this will take 40m" and
-- the wrong one for "this was read four days ago", which it renders as
-- "97h 12m". Anything the addon keeps between sessions is measured in days,
-- so this stops at days and rounds toward the coarser unit: the point of the
-- line is "is this stale", not "how stale to the minute".
--
-- Returns nil rather than a word when there is no stamp, so a caller can tell
-- "never" from "just now" -- they are different answers and the second is a
-- lie about the first.
function CN.Ago(stamp, now)
    stamp = tonumber(stamp)

    if not stamp or stamp <= 0 then
        return nil
    end

    now = tonumber(now) or (time and time()) or 0

    local seconds = now - stamp

    -- A clock that moved backwards -- a timezone change, a client restart
    -- across one -- must not print a negative age.
    if seconds < 60 then
        return "just now"
    end

    if seconds < 3600 then
        return math.floor(seconds / 60) .. "m ago"
    end

    if seconds < 86400 then
        return math.floor(seconds / 3600) .. "h ago"
    end

    local days = math.floor(seconds / 86400)

    return days .. CN.Pluralize(days, " day ago", " days ago")
end

function CN.Comma(number)
    number = tonumber(number)

    if not number then
        return "0"
    end

    local negative = number < 0

    local text = tostring(math.floor(math.abs(number) + 0.5))

    local formatted = text

    while true do
        local replaced

        formatted, replaced = string.gsub(formatted, "^(%d+)(%d%d%d)", "%1,%2")

        if replaced == 0 then
            break
        end
    end

    return (negative and "-" or "") .. formatted
end

-- A text progress bar, for chat.
--
-- Deliberately only ever called with a fraction the client vouched for.
-- There is no overload that takes "roughly" -- a bar is the most confident
-- shape information can take, and the addon does not spend that confidence
-- on a guess.
function CN.ProgressBar(fraction, width)
    width = width or 20

    if type(fraction) ~= "number" then
        return string.rep("-", width)
    end

    if fraction < 0 then fraction = 0 end
    if fraction > 1 then fraction = 1 end

    local filled = math.floor(fraction * width + 0.5)

    -- A FULL BAR IS A CLAIM, AND ROUNDING MUST NOT MAKE IT. 0.61.0.
    --
    -- At width 20 anything from 0.975 up rounded to twenty filled cells, so
    -- an achievement 39 of 40 done drew the same bar as one that was finished
    -- -- in a list whose whole job is telling you what is still outstanding.
    -- Same at the bottom: 0.024 drew an empty bar for real progress.
    if filled >= width and fraction < 1 then
        filled = width - 1
    end

    if filled <= 0 and fraction > 0 then
        filled = 1
    end

    return string.rep("=", filled) .. string.rep("-", width - filled)
end

-- A COMPLETION PERCENTAGE THAT DOES NOT LIE AT EITHER END.
--
-- Four places rendered their own, and every one of them rounded: 999 of
-- 1,000 printed "100%" next to a row that was still on the outstanding list,
-- and 1 of 400 printed "0%" for work already done. Both are the addon
-- contradicting itself on the same line, and both are exactly the cases a
-- completionist notices, because the last percent is the part they are here
-- for.
--
-- Round normally in the middle; clamp away from 100 and 0 at the ends.
-- `decimals` defaults to 0.
function CN.PercentText(fraction, decimals)
    if type(fraction) ~= "number" then
        return "--%"
    end

    decimals = decimals or 0

    if fraction < 0 then fraction = 0 end
    if fraction > 1 then fraction = 1 end

    local scale   = 10 ^ decimals
    local percent = math.floor(fraction * 100 * scale + 0.5) / scale

    if percent >= 100 and fraction < 1 then
        percent = 100 - (1 / scale)
    end

    if percent <= 0 and fraction > 0 then
        percent = 1 / scale
    end

    return string.format("%." .. decimals .. "f%%", percent)
end

-- "1 piece(s) left" IS WHAT AN UNFINISHED SENTENCE LOOKS LIKE.
--
-- Twenty-odd lines across the addon wrote "(s)" rather than deciding, and the
-- ones a player reads most are the worst of them -- "3 piece(s) left" is on
-- the row that is supposed to persuade them the set is nearly done. The
-- debug-only ones can stay lazy; the ones a player sees cannot.
--
-- `CN.Count(3, "piece")` -> "3 pieces"
-- `CN.Count(1, "piece")` -> "1 piece"
-- `CN.Count(2, "entry", "entries")` for the irregulars.
function CN.Count(number, singular, plural)
    number = tonumber(number) or 0

    local word = singular

    if number ~= 1 then
        word = plural or (singular .. "s")
    end

    return CN.Comma(number) .. " " .. word
end

-- The word alone, where the caller has already written the number (a
-- coloured count, usually).
-- `CN.Pluralize(3, "")` is "s" and `CN.Pluralize(1, "")` is "" -- which is
-- what twenty-two call sites were writing by hand as
-- `CN.Pluralize(n, "", "s")`, each of them a place the next grammar change
-- would have had to find. 0.64.0.
function CN.Pluralize(number, singular, plural)
    if (tonumber(number) or 0) == 1 then
        return singular
    end

    return plural or (singular .. "s")
end

-- THE CLIENT'S TOKENS ARE FOR CODE. THE CLIENT'S NAMES ARE FOR PLAYERS.
--
-- `UnitClass` and `UnitRace` return a localized name AND an uppercase token,
-- and the token is what everything in this addon stores, because a token is
-- stable and a name is not. That is correct -- and it means anything that
-- prints one is printing "class only: WARRIOR, PALADIN" at somebody.
--
-- The client keeps the mapping back. `LOCALIZED_CLASS_NAMES_MALE` covers the
-- classes; races come back from `C_CreatureInfo`. Where neither answers, the
-- token is title-cased rather than shouted, which is wrong in a small way
-- instead of a loud one.
-- Built once, from the client, in whatever locale it is running in.
--
-- `C_CreatureInfo.GetRaceInfo` hands back `clientFileString` (the token this
-- addon stores) alongside `raceName` (what a player calls it), so the map is
-- read out of the game rather than hard-coded -- a hard-coded race table goes
-- stale on the next allied race, and the token is the part that must not.
--
-- The scan is bounded and the gaps in the id space are ordinary; it runs at
-- most once per session and only when something actually needs to print a
-- race.
CN.raceScanCeiling = 100

local raceNames

function CN.RaceNamesByToken()
    if raceNames then
        return raceNames
    end

    raceNames = {}

    if not C_CreatureInfo or not C_CreatureInfo.GetRaceInfo then
        return raceNames
    end

    for id = 1, CN.raceScanCeiling do
        local ok, info = pcall(C_CreatureInfo.GetRaceInfo, id)

        if ok and type(info) == "table"
            and info.clientFileString and info.raceName then

            raceNames[string.upper(info.clientFileString)] = info.raceName
        end
    end

    return raceNames
end

-- For the harness, and for anything that changes locale mid-session.
function CN.ForgetRaceNames()
    raceNames = nil
end

-- Alliance and Horde, in the player's language.
--
-- `UnitFactionGroup` returns an English token like every other one, and it
-- was printed raw beside a class run through `CN.TokenLabel` -- one localized
-- word and one untranslated token in the same seven characters. The client
-- keeps both names in globals it has always had. 0.64.0.
CN.factionGlobals = {
    Alliance = "FACTION_ALLIANCE",
    Horde    = "FACTION_HORDE",
    Neutral  = "FACTION_STANDING_LABEL4",
}

-- "Renown 12", in the client's language. `RENOWN_LEVEL_LABEL` is the game's
-- own global for the word; absent, the English word is better than nothing
-- and better than an empty string. 0.65.0.
function CN.RenownLabel(level)
    local word = _G.RENOWN_LEVEL_LABEL

    if type(word) ~= "string" or word == "" then
        word = "Renown "
    end

    -- The client's string already ends in a space in every locale that ships
    -- it; a locale that ever stops doing so must not produce "Renown12".
    if word:sub(-1) ~= " " then
        word = word .. " "
    end

    return word .. tostring(level or 0)
end

function CN.FactionLabel(token)
    if type(token) ~= "string" or token == "" then
        return ""
    end

    local global = CN.factionGlobals[token]

    if global and _G[global] and _G[global] ~= "" then
        return _G[global]
    end

    return token
end

-- WHAT THE PLAYER WOULD READ IF THE COLOURS WERE NOT THERE. 0.66.0.
--
-- Colour openers, their `|r` closers and inline textures, removed. The idiom
-- was written out by hand in two files, one of which also stripped textures
-- and one of which did not -- so the sort key and the mount source line
-- disagreed about what a string says. A rule written twice drifts.
function CN.Strip(text)
    text = tostring(text or "")

    text = text:gsub("|c%x%x%x%x%x%x%x%x", "")
    text = text:gsub("|r", "")
    text = text:gsub("|T.-|t", "")

    return text
end

-- WHAT A ROW SAYS, WITH THE MARKUP TAKEN OFF. 0.77.0.
--
-- Hoisted out of `UI/List.lua`, where it was a local that the list's own
-- filter used and the cross-tab search did not -- so `/cn find` and the
-- "Also on:" counts searched the RAW text, colour codes and all, while the
-- tab you were standing on searched this. Typing any hex fragment reported a
-- match on every row of every tab and none on the one in front of you.
--
-- Leading markers go too: "  ", "x ", "> ", "! ", "12. ". A row is what it
-- says, not how it is decorated or where it sits in a list.
function CN.SortKey(text)
    text = CN.Strip(text)

    text = text:gsub("^[%s%p%d]+", "")

    return string.lower(text)
end

-- WHAT A ROW SAYS, FOR SEARCHING IT. 0.78.0.
--
-- The name and the value column need different treatment and 0.77.0 gave
-- them the same one. `CN.SortKey` strips LEADING punctuation and digits,
-- which is right for a name -- "  12. Kill Ten Rats" sorts under K -- and
-- destructive for the value column, which is where the numbers live:
--
--   "6 left"  -> "left"     "85%"     -> ""
--   "40 / 60" -> ""         "1,234"   -> ""
--
-- So filtering the window by any number matched nothing, and the "Also on:"
-- counts were computed from the same erased text -- which is the mismatch
-- that change was written to remove, still there for every numeric row.
--
-- One helper, used by the filter and by the cross-tab search, so the two
-- cannot drift again.
function CN.SearchKey(text, value)
    return CN.SortKey(text) .. " " .. string.lower(CN.Strip(value))
end


function CN.TokenLabel(token)
    if type(token) ~= "string" or token == "" then
        return tostring(token)
    end

    -- Class tokens are uppercase and race tokens are not ("NightElf"), so
    -- both maps are keyed uppercase and both lookups normalize. Getting this
    -- wrong is silent: the fall-through below produces something that reads
    -- almost right, which is the worst kind of wrong to debug.
    local upper = string.upper(token)

    local classes = _G.LOCALIZED_CLASS_NAMES_MALE

    if type(classes) == "table" and classes[upper] then
        return classes[upper]
    end

    local races = CN.RaceNamesByToken()

    if races[upper] then
        return races[upper]
    end

    -- Title case from a SHOUTED_TOKEN, underscores to spaces.
    local words = {}

    for word in string.gmatch(token, "[^_]+") do
        table.insert(words,
            string.upper(string.sub(word, 1, 1))
                .. string.lower(string.sub(word, 2)))
    end

    if #words == 0 then
        return token
    end

    return table.concat(words, " ")
end

-- "a, b and c" -- the shape a person writes, from the shape code holds.
-- Every caller that used `table.concat(list, ", ")` on something a player
-- reads was producing a list and calling it a sentence.
function CN.Series(list, conjunction)
    if type(list) ~= "table" or #list == 0 then
        return ""
    end

    if #list == 1 then
        return tostring(list[1])
    end

    conjunction = conjunction or "and"

    if #list == 2 then
        return tostring(list[1]) .. " " .. conjunction .. " " .. tostring(list[2])
    end

    local head = {}

    for index = 1, #list - 1 do
        table.insert(head, tostring(list[index]))
    end

    return table.concat(head, ", ") .. " " .. conjunction .. " "
        .. tostring(list[#list])
end

-- A RESULT HELD AGAINST A GENERATION.
--
-- The addon has three of these written by hand already -- the shortlist
-- cache, the report cache, the route cache -- and every one of them is the
-- same six lines: hold the answer, hold the generation it was built at,
-- rebuild when they differ.
--
-- The tabs are the reason this one exists. The Collections and Scans tabs
-- call `Summary()` on eight collection modules on every two-second refresh,
-- and each of those walks its whole store to produce two integers that cannot
-- have changed unless the player collected something -- which fires an event
-- the addon already subscribes to. Measured at retail scale: 3.28 ms and
-- 4.40 ms per refresh, every two seconds, for the life of the window.
--
-- `build` is called only when the generation has moved. A generation of nil
-- means "do not cache this", which is how a caller opts out without a branch.
local memos = {}

-- WHAT COMES BACK IS THE CACHE, NOT A COPY OF IT. 0.67.0.
--
-- 0.66.0 split the Scans tab into a memoized half and a live half, and then
-- appended the live rows onto the table this returns -- which is the cached
-- table. Standing still, the generation does not move, so the same table came
-- back every two seconds and grew by five rows each time: half a minute in,
-- the tab listed "Quests in your log" fifteen times.
--
-- The cache cannot stop a caller mutating what it is handed, but it can NOTICE
-- and refuse to serve the damage: an array whose length has changed since it
-- was stored is not the value that was built. Rebuilt, and reported through
-- `/cn errors`, so the next one of these is a bug report rather than a
-- mystery.
--
-- Length only. Deep-comparing a memoized table on every hit would cost more
-- than the walk the memo exists to avoid, and every mutation of this shape --
-- there has been exactly one -- has been an append.
CN.memoMutations = 0

function CN.Memo(key, generation, build)
    if generation == nil then
        return build()
    end

    local held = memos[key]

    if held and held.generation == generation then
        if held.count == nil or held.count == #held.value then
            return held.value
        end

        CN.memoMutations = CN.memoMutations + 1

        local errors = CN.modules and CN:GetModule("Errors")

        if errors and errors.Record then
            errors.Record("a memoized value was modified by its reader",
                tostring(key) .. ": built with " .. tostring(held.count)
                .. " entries, found " .. tostring(#held.value))
        end
    end

    local value = build()

    memos[key] = {
        generation = generation,
        value      = value,
        -- ARRAY-SHAPED MEMOS ONLY, AND DELIBERATELY SO. 0.68.0.
        --
        -- `#value` is zero for a hash table and zero on every read of one, so
        -- this catches an append to a LIST and nothing else -- eight of the
        -- eleven memos in this addon return hash tables and are not covered.
        --
        -- Counting keys instead was tried and reverted: several memoized
        -- summaries are legitimately annotated by their readers, so a key
        -- count fires eighteen times a session and defeats the caching it
        -- exists to protect. A cache that rebuilds constantly is a worse
        -- outcome than a guard with a stated limit, and an append to a
        -- returned list is the shape this has actually taken.
        count      = type(value) == "table" and #value or nil,
    }

    return value
end

function CN.ForgetMemos(key)
    if key then
        memos[key] = nil
    else
        memos = {}
    end
end

-- Bumped by anything that can change what a collection Summary answers.
-- Maintained in Scoring.lua, next to the other generation counters, so there
-- is one place to look for all of them.
CN.collectionGeneration = 0

function CN.Trim(text)
    if not text then
        return ""
    end

    return (text:gsub("^%s+", ""):gsub("%s+$", ""))
end
'@

$Embedded['Design.lua'] = @'
-- Design.lua
-- Completion Navigator :: the addon's one palette, one grid, one type scale.
--
-- WHY THIS FILE EXISTS.
--
-- Before 0.54.0 there was no palette. There were three, plus five hundred and
-- forty-three inline hex codes across the tree: five near-identical greys
-- doing one job, three reds, two greens, two golds, and the brand blue
-- written in two different casings. `Modules/Tooltips.lua` kept a fourth set
-- as RGB triples, only one of which matched anything else.
--
-- Every one of those choices was defensible where it was made. Together they
-- read as four people's work, which is the one thing a single-author addon
-- should never look like.
--
-- THE RULE.
--
-- Nothing outside this file defines a colour. Call sites should use the
-- wrappers below.
--
-- WHAT IS ACTUALLY ENFORCED, precisely, because a rule stated more strongly
-- than it is checked is a rule nobody trusts twice: the harness reads every
-- `.lua` named in the `.toc`, collects every `|cffRRGGBB` literal in it, and
-- fails if any one of them is a code that is not in `CN.C`. It does NOT fail
-- on the literal itself -- roughly five hundred of them remain in the tree,
-- all spelling out a palette colour by hand. Writing one more of those is
-- untidy. Writing a NEW colour is the thing that cost sixteen colours last
-- time, and that is the thing the check catches.
--
-- A second check requires every pair of roles to differ by more than 0.05 in
-- RGB distance, so a palette cannot quietly become five greys again either.
--
-- WHAT THE COLOURS MEAN.
--
-- Eight roles, and no more -- plus DISABLED, which is a control state rather
-- than a voice. If something does not fit one of them, the answer is almost
-- always that it should read as body text.
--
--   BRAND    the addon's own voice, and the value the player asked for
--   ACCENT   a thing to type, and a section heading
--   PRIMARY  names and headings on a dark panel
--   BODY     ordinary text
--   MUTED    hints, units, parentheticals, "why not"
--   GOOD     done, collected, unlocked
--   WARN     needs attention -- a cap about to be hit, something waiting
--   BAD      blocked, failed, not collected

local ADDON_NAME, CN = ...

------------------------------------------------------------
-- THE PALETTE
------------------------------------------------------------

CN.C = {
    -- Sampled from the addon's own logo, and the reason everything else is
    -- cool-toned: a warm grey beside this blue reads as dirty.
    BRAND   = "5dd2fb",

    -- Replaces both `ffff00` (139 uses, pure yellow -- aggressive on a dark
    -- chat background) and `ffd100` (24 uses). One gold.
    ACCENT  = "ffc74f",

    PRIMARY = "f2f4f6",
    BODY    = "c8ccd2",

    -- Replaces `999999` (290 uses), `808080`, `cccccc` and `666666`. Pulled
    -- very slightly toward the brand blue so a hint stops reading as
    -- "disabled" next to it.
    MUTED   = "8a8f96",

    -- Replaces `73b873` and `00ff00`. Pure green is a colour from 1998 and
    -- the muted one was already in use for "done" in two modules.
    GOOD    = "73b873",

    -- DEEPER THAN ACCENT, DELIBERATELY.
    --
    -- These two were the same gold, which meant "here is a command you can
    -- type" and "this is about to be wasted" looked identical -- and the
    -- second is the only thing in the addon that is genuinely time-critical.
    -- A palette that does not carry a distinction is not carrying it.
    WARN    = "f0932b",

    -- Replaces `ff4444` and `f56b61`. Dark enough to read on the light
    -- parchment of a tooltip as well as on a dark panel.
    BAD     = "e2564c",

    -- Not a role: the grey a disabled control draws itself in.
    DISABLED = "5a5f66",
}

------------------------------------------------------------
-- WRAPPERS
------------------------------------------------------------

-- One per role, so a call site never types a hex code. Nil-safe, because half
-- of what gets wrapped is a number or a value that may not exist.
local function Wrap(role)
    return function(text)
        return "|cff" .. CN.C[role] .. tostring(text) .. "|r"
    end
end

CN.Brand    = Wrap("BRAND")
CN.Accent   = Wrap("ACCENT")
CN.Primary  = Wrap("PRIMARY")
CN.Body     = Wrap("BODY")
CN.Muted    = Wrap("MUTED")
CN.Good     = Wrap("GOOD")
CN.Warn     = Wrap("WARN")
CN.Bad      = Wrap("BAD")

-- Good or bad from a boolean, which is most of what the addon prints about
-- state. Saves the ternary at ninety call sites.
function CN.State(condition, text)
    if condition then
        return CN.Good(text)
    end

    return CN.Bad(text)
end

------------------------------------------------------------
-- THE SAME COLOURS AS NUMBERS
------------------------------------------------------------

-- `AddLine`, `SetTextColor` and `SetVertexColor` all want three floats.
-- Tooltips.lua kept its own set of triples that had drifted from the hex
-- codes everything else used; now there is one source and two shapes of it.
--
-- Computed on first use and held, because these are read on every tooltip.
local rgb = {}

CN.RGB = setmetatable({}, {
    __index = function(_, role)
        local held = rgb[role]

        if held then
            return held
        end

        local hex = CN.C[role]

        if not hex then
            return { 1, 1, 1 }
        end

        held = {
            tonumber(hex:sub(1, 2), 16) / 255,
            tonumber(hex:sub(3, 4), 16) / 255,
            tonumber(hex:sub(5, 6), 16) / 255,
        }

        rgb[role] = held

        return held
    end,
})

-- The three floats directly, for the very common
-- `SetTextColor(CN.Rgb("MUTED"))` shape.
function CN.Rgb(role)
    local triple = CN.RGB[role]

    return triple[1], triple[2], triple[3]
end

------------------------------------------------------------
-- SPACING
------------------------------------------------------------

-- A four-pixel grid, and only these values. Sampled before this file existed,
-- the window used 2, 4, 6, 8, 12, 14, 16, 26, 30, 32, 34, 38, 52, 58, 64,
-- 104, 136 and 190 -- which is not a grid, it is a series of individually
-- reasonable decisions.
CN.SPACE = {
    XS = 4,
    S  = 8,
    M  = 12,
    L  = 16,
    XL = 24,
}

------------------------------------------------------------
-- TYPE
------------------------------------------------------------

-- Font objects by ROLE rather than by name, so a panel asks for a heading
-- instead of remembering which of GameFontNormal and GameFontNormalLarge the
-- tab next door happened to pick. Nine of the eleven tabs disagreed.
--
-- MUTED is for labels only. It was carrying real information in five places,
-- at roughly 2.8:1 contrast on the panel's own background -- below the
-- accessibility floor for any text size, and about six physical pixels tall
-- at 0.64 UI scale on a large monitor. Anything that carries information uses
-- SMALL and takes its colour from CN.C.MUTED instead.
CN.FONT = {
    TITLE = "GameFontNormalLarge",
    HEAD  = "GameFontNormal",
    BODY  = "GameFontHighlightLeft",
    SMALL = "GameFontHighlightSmall",
    LABEL = "GameFontDisableSmall",

    -- THE TWO ROLES THAT WERE MISSING, WHICH IS WHY SIX WIDGETS STILL NAMED
    -- A FONT OBJECT DIRECTLY.
    --
    -- The five roles above covered the window and nothing else, so the arrow,
    -- the map pins, the follow frame, the heads-up line and the welcome
    -- screen went on typing `GameFont*` -- and drifted, because a name is not
    -- a decision. A role nobody can express is a role everybody works around.
    --
    -- CAPTION: emphasised text at small size. A button's own label, and the
    -- word under a map pin.
    CAPTION = "GameFontNormalSmall",

    -- LEAD: the one number on screen that is read at a glance while moving.
    -- Exactly one widget uses it -- the arrow's distance -- and that is the
    -- point of it having a name.
    LEAD    = "GameFontHighlightLarge",
}

------------------------------------------------------------
-- TEXT SIZE
------------------------------------------------------------

-- THE WINDOW WAS FIXED-SIZE TEXT. 0.66.0.
--
-- `/cn scale` and the "Size" button scale the whole FRAME: the window, the
-- arrow and the heads-up line all grow together, which is the right control
-- for "this addon is too small on my monitor" and the wrong one for "I cannot
-- read this". A player who wants larger text and the same window had no way
-- to ask, and the only accessibility work that had landed -- the colourblind
-- arrow -- does nothing for them.
--
-- Text size is a separate axis. It derives a font object per role at the
-- requested size from the client's own template, so the addon keeps whatever
-- font the player's client uses rather than naming one.
CN.textScales = { 1.0, 1.15, 1.3, 1.5 }

function CN.TextScale()
    local settings = CN.Settings and CN.Settings()

    local scale = settings and tonumber(settings.textScale)

    if not scale or scale < 1 or scale > 2 then
        return 1
    end

    return scale
end

-- Derived once per role per size and kept, because a font object is a client
-- resource and rebuilding one per font string per refresh is not free.
local derivedFonts = {}

function CN.FontObject(role)
    local template = CN.FONT[role] or CN.FONT.BODY

    local scale = CN.TextScale()

    if scale <= 1.001 or not CreateFont then
        return template
    end

    local key = tostring(role) .. "@" .. tostring(scale)

    if derivedFonts[key] then
        return derivedFonts[key]
    end

    local base = _G and _G[template]

    if not base or not base.GetFont then
        return template
    end

    local file, size, flags = base:GetFont()

    if not file or not size then
        return template
    end

    local made, object = pcall(CreateFont,
        "CompletionNavigatorFont" .. tostring(role) .. tostring(scale * 100))

    if not made or not object or not object.SetFont then
        return template
    end

    object:SetFont(file, math.floor(size * scale + 0.5), flags)

    -- Colour and justification come from the template, or the derived font
    -- would silently reset every label in the window to white and centred.
    if object.SetTextColor and base.GetTextColor then
        pcall(function() object:SetTextColor(base:GetTextColor()) end)
    end

    if object.SetJustifyH and base.GetJustifyH then
        pcall(function() object:SetJustifyH(base:GetJustifyH()) end)
    end

    derivedFonts[key] = object

    return object
end

-- EVERY FONT STRING THE ADDON MAKES, REMEMBERED WITH ITS ROLE.
--
-- Changing the size has to reach text that already exists: the window builds
-- its tabs once and keeps them, so rebuilding is not on the table and
-- re-applying is. Weak keys, so a font string the client has finished with is
-- not held alive by this list.
local textStrings = setmetatable({}, { __mode = "k" })

-- APPLIED IN BOTH DIRECTIONS. 0.67.0.
--
-- At scale 1 `CN.FontObject` returns the template NAME, and this only acted
-- on a table -- so raising the size worked and lowering it did nothing at
-- all. Every label kept whatever enlarged font it was last given, while the
-- button and the command both reported 100%. The Settings button cycles
-- 1.5 back round to 1.0, which is the normal way a player met this.
local function ApplyRole(fontString, role)
    local object = CN.FontObject(role)

    if type(object) == "string" then
        object = _G and _G[object]
    end

    if type(object) == "table" and fontString.SetFontObject then
        pcall(fontString.SetFontObject, fontString, object)
    end
end

-- The one way this addon makes a piece of text. Every `CreateFontString` in
-- the window went through `CN.FONT.ROLE` directly, which is a template NAME --
-- correct, and unreachable afterwards.
function CN.Label(parent, layer, role)
    if not parent or not parent.CreateFontString then
        return nil
    end

    local fontString = parent:CreateFontString(nil, layer or "ARTWORK",
        CN.FONT[role] or CN.FONT.BODY)

    if not fontString then
        return nil
    end

    textStrings[fontString] = role

    ApplyRole(fontString, role)

    return fontString
end

-- TEXT DRAWN OVER THE WORLD IS SIZED, NOT FONT-OBJECTED. 0.67.0.
--
-- `CN.Outline` sets an explicit face, size and OUTLINE flag, because a font
-- object cannot carry an outline -- so the arrow's distance readout, the
-- heads-up line, the follow frame and the map pin numbers would ignore a font
-- object even once they were registered. They are remembered separately, with
-- the size they were asked for, and re-outlined at the new scale.
local outlined = setmetatable({}, { __mode = "k" })

-- A FONT STRING THE CLIENT MADE, NOT THIS ADDON. 0.67.0.
--
-- A templated button or checkbox arrives with its own label already built, so
-- `CN.Label` never sees it -- and in the game every button label, checkbox
-- label and tab caption in the window stayed at 100% while the rows around
-- them grew. Adopting one is the same registration, from the other end.
function CN.AdoptLabel(fontString, role)
    if not fontString or not fontString.SetFontObject then
        return nil
    end

    textStrings[fontString] = role or "BODY"

    ApplyRole(fontString, role or "BODY")

    return fontString
end

function CN.RefreshTextScale()
    local touched = 0

    for fontString, role in pairs(textStrings) do
        ApplyRole(fontString, role)

        touched = touched + 1
    end

    for fontString, spec in pairs(outlined) do
        CN.Outline(fontString, spec.size, spec.role)

        touched = touched + 1
    end

    return touched
end

function CN.SetTextScale(scale)
    scale = tonumber(scale)

    if not scale or scale < 1 or scale > 2 then
        return false
    end

    local settings = CN.Settings and CN.Settings()

    if not settings then
        return false
    end

    settings.textScale = (scale > 1.001) and scale or nil

    CN.RefreshTextScale()

    return true
end

------------------------------------------------------------
-- TEXT THAT IS DRAWN OVER THE WORLD
------------------------------------------------------------

-- NOTHING THE ADDON DRAWS OVER THE 3D WORLD HAD AN OUTLINE.
--
-- The arrow's distance readout, the heads-up line, the follow frame and the
-- numbers on the map pins were all bare `GameFont*` strings with the standard
-- one-pixel drop shadow. That is enough over a dark UI panel. It is not
-- enough over Northrend snow, Uldum sand, Bastion's white marble, or a spell
-- effect -- and the distance readout is the number a player reads while
-- running, which is exactly when the background is moving and unpredictable.
--
-- An outline is one call and it is the difference between "readable at a
-- glance" and "readable if the ground happens to be dark".
-- HOW MUCH ROOM THE HOVER X TAKES ALONG A FRAME'S TOP-RIGHT EDGE. 0.78.0.
--
-- 0.77.0 hardcoded 16 in the control and `Modules/Hud.lua` restated 18 in
-- another file so its label could clear the button -- one number, two places.
-- Alpha 0 does NOT disable mouse input, which is exactly why the room has to
-- be reserved: the two frames that did not reserve it had a live click in
-- their top-right corner that stopped the route or hid the arrow, with
-- nothing drawn there.
CN.CLOSE_WIDTH = 18

-- A HOVER X ON A FRAME DRAWN OVER THE WORLD. 0.77.0.
--
-- The heads-up line got one when a player asked for it in as many words: a
-- frame that appears over the world and cannot be dismissed from itself is a
-- frame people uninstall the addon to be rid of. The other two frames this
-- addon draws over the world -- the follow list and the waypoint arrow -- are
-- also mouse-enabled and draggable, and neither said so nor offered a way
-- out. The follow frame could only be dismissed by knowing `/cn follow`; the
-- arrow ate world clicks in a 56x56 footprint with nothing on screen
-- explaining why.
--
-- Hoisted rather than copied, because that is three sites for one control.
--
-- `onClose` is what the x does; `tooltip` is what the whole frame says on
-- hover. Both optional: a frame with no tooltip still gets its x.
function CN.AttachCloseControl(frame, onClose, tooltip, closeTooltip)
    if not frame or not CreateFrame then
        return nil
    end

    local close = CreateFrame("Button", nil, frame)

    close:SetSize(CN.CLOSE_WIDTH - 2, CN.CLOSE_WIDTH - 2)
    close:SetPoint("TOPRIGHT", -2, -2)

    -- A DRAG STARTED IN THAT CORNER STILL MOVES THE FRAME.
    --
    -- The button takes the mouse, so without this the top-right corner is a
    -- dead zone for dragging -- and the tooltip promises the frame can be
    -- dragged.
    close:RegisterForDrag("LeftButton")

    close:SetScript("OnDragStart", function()
        if frame.StartMoving then
            frame:StartMoving()
        end
    end)

    close:SetScript("OnDragStop", function()
        local stop = frame:GetScript("OnDragStop")

        if stop then
            stop(frame)
        end
    end)

    close.label = CN.Label(close, "OVERLAY", "SMALL")
    close.label:SetPoint("CENTER")
    close.label:SetText(CN.Muted("x"))

    CN.Outline(close.label, 11, "MUTED")

    -- Only while the mouse is over the frame. A permanent X on something
    -- whose whole job is to be glanced at is one more thing to read.
    close:SetAlpha(0)

    close:SetScript("OnEnter", function(self)
        self:SetAlpha(1)

        self.label:SetText(CN.Bad("x"))
    end)

    close:SetScript("OnLeave", function(self)
        self.label:SetText(CN.Muted("x"))

        if not frame:IsMouseOver() then
            self:SetAlpha(0)
        end
    end)

    close:SetScript("OnClick", function()
        if onClose then
            onClose()
        end
    end)

    if CN.UI and CN.UI.AttachTooltip then
        if closeTooltip then
            CN.UI.AttachTooltip(close, closeTooltip)
        end

        if tooltip then
            CN.UI.AttachTooltip(frame, tooltip)
        end
    end

    frame.close = close

    -- The X appears with the cursor and goes with it.
    frame:HookScript("OnEnter", function()
        close:SetAlpha(1)
    end)

    frame:HookScript("OnLeave", function()
        if not close:IsMouseOver() then
            close:SetAlpha(0)
        end
    end)

    return close
end

-- WHERE A FRAME THE PLAYER MOVED SHOULD GO BACK. 0.77.0.
--
-- `GetPoint` returns `point, relativeTo, relativePoint, x, y`. Three of the
-- four movable frames in this addon discarded the THIRD return and then
-- restored with `SetPoint(point, UIParent, point, x, y)` -- substituting the
-- anchor for the relative point.
--
-- `StopMovingOrSizing` re-anchors a frame as it sees fit and does not promise
-- the two corners match. When they differ, the saved offsets are re-applied
-- against a different corner of the screen, so the frame comes back a screen
-- away from where it was left and is then pinned to an edge by
-- `SetClampedToScreen`. It drags, and it does not stay -- which is the
-- reported complaint, half-answered.
--
-- `UI.SavePosition` got this right and its three siblings did not, so it is
-- one function now rather than a rule written four times.
function CN.SaveFramePosition(frame)
    if not frame or not frame.GetPoint then
        return nil
    end

    local point, _, relativePoint, x, y = frame:GetPoint()

    if not point then
        return nil
    end

    return {
        point         = point,
        relativePoint = relativePoint or point,
        x             = x or 0,
        y             = y or 0,
    }
end

-- `fallback` is used when nothing has been saved yet, and takes the same
-- shape. Cleared first, because a frame that is already anchored somewhere
-- accumulates points rather than moving.
function CN.RestoreFramePosition(frame, saved, fallback)
    if not frame or not frame.SetPoint then
        return
    end

    local placement = (type(saved) == "table" and saved.point and saved)
        or fallback or {}

    frame:ClearAllPoints()

    frame:SetPoint(
        placement.point or "CENTER",
        UIParent,
        placement.relativePoint or placement.point or "CENTER",
        placement.x or 0,
        placement.y or 0)
end

function CN.Outline(fontString, size, role)
    if not fontString or not fontString.SetFont then
        return false
    end

    local face = fontString.GetFont and fontString:GetFont()

    if not face and GameFontNormal and GameFontNormal.GetFont then
        face = GameFontNormal:GetFont()
    end

    if not face then
        return false
    end

    -- REMEMBERED AT THE SIZE IT WAS ASKED FOR, and scaled on the way out, so
    -- the text-size setting reaches the four widgets it was written for.
    local asked = size or 12

    outlined[fontString] = { size = asked, role = role }

    local applied = pcall(fontString.SetFont, fontString, face,
        math.floor(asked * CN.TextScale() + 0.5), "OUTLINE")

    if not applied then
        return false
    end

    -- The outline replaces the shadow; keeping both smears the glyph.
    if fontString.SetShadowOffset then
        pcall(fontString.SetShadowOffset, fontString, 0, 0)
    end

    if role and fontString.SetTextColor then
        fontString:SetTextColor(CN.Rgb(role))
    end

    return true
end

------------------------------------------------------------
-- PUNCTUATION
------------------------------------------------------------

-- ONE DASH, USED ONE WAY.
--
-- Sixty-five player-facing strings used `--` as a stand-in for an em dash and
-- others used a plain hyphen for the same job, sometimes in adjacent lines of
-- the same panel. WoW's fonts render U+2014 correctly in every shipped
-- locale, so there was never a technical reason for the substitute.
--
-- `CN.DASH` separates a clause from its aside. `CN.DOT` separates two facts of
-- equal weight -- "Nagrand · 12 stops · 34m". Small things, and they are most
-- of what separates a hobby addon's chat output from a product's.
CN.DASH = "\226\128\148"
CN.DOT  = "\194\183"

-- Wraps an aside in the dash and the muted colour in one call, which is the
-- single commonest shape in the addon's output.
function CN.Aside(text)
    return " " .. CN.Muted(CN.DASH .. " " .. tostring(text))
end

------------------------------------------------------------
-- THE BLOCK
------------------------------------------------------------

-- ONE RENDERER FOR THE SHAPE EVERY COMMAND IN THIS ADDON ALREADY HAD.
--
-- The 0.59.0 interface audit named this as the single most valuable change
-- available and it has been deferred twice. The finding, restated: 126
-- commands, and almost every one of them answers in the same shape -- a
-- headline, a list of things, a value per thing, a note when the list was cut
-- short, a sentence when it is empty. Each one built that shape by hand.
--
-- The result was not ugly so much as INCONSISTENT, which is worse, because a
-- player learns a layout once and then has to relearn it per command:
--
--   * Some lists said "... and 4 more", some "and 4 more", some nothing at
--     all and simply stopped.
--   * The value -- the count, the percentage, the time left, the thing the
--     player is actually scanning for -- was sometimes gold, sometimes muted,
--     sometimes inline in the sentence, sometimes in brackets at the end.
--   * An empty list was sometimes a muted sentence, sometimes a headline with
--     nothing under it, and sometimes silence.
--   * Truncation limits ranged from 5 to 20 with no reason behind any of them.
--
-- `CN.PrintRows` is that shape, once. Every call site that adopts it gets the
-- same grammar, and changing the grammar becomes one edit rather than 126.
--
-- ON COLUMNS. WoW's chat font is proportional, so true column alignment with
-- spaces is not available -- padding to a width produces a ragged edge that
-- looks like a bug rather than a table. What IS available, and is what the
-- eye actually uses to scan a list, is a consistent POSITION and a consistent
-- COLOUR: the label reads in body, the value trails it in accent, every row,
-- every command. That is the column.
--
--   rows[i] = {
--       text    = "Nerub-ar Palace",     -- required
--       value   = "6 left",              -- optional, trails in accent
--       state   = "GOOD",                -- optional palette role for `value`
--       note    = "resets in 2d 3h",     -- optional, muted aside
--       marker  = ">",                   -- optional leading glyph
--   }
--
--   options = {
--       limit = 12,                      -- rows shown before "and N more"
--       more  = "/cn instances",         -- what to type to see the rest
--       empty = "Nothing on a lockout.", -- shown instead of the rows
--       total = 40,                      -- overrides #rows in "and N more"
--   }
--
-- Returns how many rows were printed, so a caller can decide whether it has
-- said anything at all.
CN.blockLimit = 12

function CN.PrintRows(headline, rows, options)
    options = options or {}

    rows = rows or {}

    if headline then
        CN.Print(headline)
    end

    if #rows == 0 then
        if options.empty then
            CN.PrintLine(CN.Muted(options.empty))
        end

        return 0
    end

    local limit = options.limit or CN.blockLimit

    local shown = 0

    for index = 1, math.min(limit, #rows) do
        local row = rows[index]

        if type(row) == "string" then
            row = { text = row }
        end

        local line = ""

        if row.marker then
            line = CN.Muted(row.marker) .. " "
        end

        line = line .. CN.Body(row.text)

        if row.value ~= nil and row.value ~= "" then
            local paint = CN.C[row.state or "ACCENT"] and (row.state or "ACCENT")
                or "ACCENT"

            line = line .. "  |cff" .. CN.C[paint]
                .. tostring(row.value) .. "|r"
        end

        if row.note then
            line = line .. CN.Aside(row.note)
        end

        CN.PrintLine(line)

        shown = shown + 1
    end

    local total = options.total or #rows

    if total > shown then
        CN.PrintLine(CN.Muted(CN.DASH .. " and "
            .. CN.Count(total - shown, "more row")
            .. (options.more and (", " .. options.more) or "")))
    end

    return shown
end

return CN.C
'@

$Embedded['Database.lua'] = @'
-- Database.lua
-- Completion Navigator :: SavedVariables schema, defaults, and migration.
--
-- Anything that must survive /reload or logout lives in
-- CompletionNavigatorDB. Add new persistent tables to DEFAULTS below and
-- bump CN.dbVersion in Core.lua when the shape changes in a way that
-- requires a migration step.

local ADDON_NAME, CN = ...

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- DEFAULT DATABASE
------------------------------------------------------------

CN.defaults = {
    -- Kept in step with CN.dbVersion so a fresh install never looks like
    -- an old database that needs migrating.
    version = CN.dbVersion,

    settings = {
        -- `enabled` REMOVED. It sat here reading like a master on/off switch
        -- and nothing anywhere read it, so setting it false did nothing at
        -- all. A setting that is present and inert is worse than one that is
        -- absent: it invites somebody to rely on it.
        debug        = false,
        priorityMode = "balanced",

        -- Off by default: taking over the waypoint uninvited is hostile,
        -- and TomTom arrows are shared with every other addon.
        autoWaypoint = false,

        -- Addon lines on item and unit tooltips. On by default: these are
        -- additive and read-only, unlike the waypoint.
        tooltips     = true,

        -- The on-screen navigation arrow. On by default, but it only appears
        -- once something is actually being tracked, so it is never in the way
        -- of a player who has not asked for navigation.
        arrow        = true,

        -- Numbered route pins on the world map. On by default: like tooltip
        -- lines they are additive and read-only, they appear only on a map
        -- the player deliberately opened, and they are the only place the
        -- routing engine's work is visible.
        mapPins      = true,

        -- Follow mode. OFF by default and firmly so: it takes over the
        -- waypoint and puts a frame on screen, which is the most intrusive
        -- thing this addon can do. It is started deliberately or not at all.
        follow       = false,

        -- Announcing rares out loud is the noisiest thing this addon could
        -- do, so it is opt-in. Unsolicited sound is worse than an uninvited
        -- waypoint, and the waypoint is already off by default.
        rareAlerts   = false,

        -- Minimap button placement is an angle in degrees around the
        -- minimap edge, so it survives UI scale and minimap size changes.
        minimap = {
            hide  = false,
            angle = 225,
        },
    },

    account = {
        ignoredObjectives  = {},
        deferredObjectives = {},

        questMetadata      = {},
        discoveredQuests   = {},
        loremaster         = {},
        taskDurations      = {},
    },

    characters = {},
}

------------------------------------------------------------
-- MIGRATIONS
------------------------------------------------------------

-- Each entry migrates FROM the given version TO version + 1.
-- Never destroy user completion history here.
CN.migrations = {
    -- 1 -> 2. The collection modules introduced account tables that older
    -- databases do not have, and the minimap settings moved under a nested
    -- table. CopyDefaults fills both in, so this migration exists to prove
    -- the ladder runs and to normalize anything defaults cannot fix.
    [1] = function(db)
        db.account = db.account or {}

        -- Tables added after the schema was first written. Creating them
        -- here means no module has to guard against their absence.
        for _, key in ipairs({
            "pets", "mounts", "toys", "appearances", "titleNames",
            "achievements", "achievementTotals", "recipeNames",
            "reputations", "factionNames", "questHarvest", "questLocations",
            "collectionScans",
        }) do
            db.account[key] = db.account[key] or {}
        end

        db.settings = db.settings or {}

        -- Very early builds stored the minimap flag flat. Move it, and do
        -- not lose the player's choice in the process.
        if type(db.settings.minimap) ~= "table" then
            local wasHidden = db.settings.minimap == true or db.settings.hideMinimap == true

            db.settings.minimap = {
                hide  = wasHidden and true or false,
                angle = db.settings.minimapAngle or 225,
            }
        end

        db.settings.hideMinimap  = nil
        db.settings.minimapAngle = nil
    end,

    -- 2 -> 3. Per-character setting overrides.
    --
    -- Nothing to convert: every existing setting stays exactly where it is,
    -- account-wide, and characters start with no overrides at all. This entry
    -- exists so the ladder is explicit about the shape change rather than
    -- relying on absence, and so the assertion below documents the intent.
    [2] = function(db)
        db.characters = db.characters or {}

        for _, character in pairs(db.characters) do
            if type(character) == "table" then
                character.settings = character.settings or {}
            end
        end
    end,

    -- 3 -> 4. Observed prerequisites gained a confidence count.
    --
    -- The old shape was a flat array of candidate quest IDs, overwritten on
    -- every sighting, so it carried no idea of how often or on how many
    -- characters an ordering had held. The new shape counts by character.
    --
    -- Existing observations are preserved and credited to one unknown
    -- character each. That is deliberately BELOW the promotion threshold:
    -- data gathered before the addon knew how to count characters must not
    -- be promoted to a prerequisite on the strength of a count it never
    -- actually made.
    [3] = function(db)
        db.account = db.account or {}

        local harvest = db.account.questHarvest

        if type(harvest) ~= "table" then
            return
        end

        for _, record in pairs(harvest) do
            if type(record) == "table" and type(record.maybeRequires) == "table" then
                record.observed = record.observed or {}

                for _, prerequisiteID in ipairs(record.maybeRequires) do
                    record.observed[prerequisiteID] = record.observed[prerequisiteID]
                        or { seen = 1, characters = { ["migrated"] = true } }
                end

                record.maybeRequires = nil
            end
        end
    end,

    -- 4 -> 5: stop carrying a copy of the client's item cache.
    --
    -- Vendor rows stored every item's NAME as well as its ID. The client
    -- knows every item name already, so this was a duplicate of its cache
    -- written to disk, rewritten on every logout and re-parsed on every
    -- login -- and at retail scale it was the single largest thing this addon
    -- saved.
    --
    -- Dropped in place rather than waiting for a rescan, so the saving
    -- arrives on the next login rather than the next time the player happens
    -- to reopen every merchant they have ever visited.
    [4] = function(db)
        db.account = db.account or {}

        local vendors = db.account.vendors

        if type(vendors) ~= "table" then
            return
        end

        local dropped = 0

        for _, record in pairs(vendors) do
            if type(record) == "table" and type(record.items) == "table" then
                for _, item in pairs(record.items) do
                    if type(item) == "table" and item.name then
                        item.name = nil
                        dropped = dropped + 1
                    end
                end
            end
        end

        if dropped > 0 then
            CN.DebugPrint("Dropped " .. dropped
                .. " cached item names the client already knows.")
        end
    end,

    -- 5 -> 6: the same argument, applied to the two remaining stores.
    --
    -- Achievements kept a name and a point value for every tracked row;
    -- pets kept a name for all eighteen hundred. Both come back from the
    -- client instantly, and both were being written to disk on every logout
    -- and parsed again on every login.
    --
    -- Stripped in place so the space is reclaimed on the next login rather
    -- than on the next full rescan.
    [5] = function(db)
        db.account = db.account or {}

        local dropped = 0

        local function strip(store, fields)
            if type(store) ~= "table" then
                return
            end

            for _, record in pairs(store) do
                if type(record) == "table" then
                    for _, field in ipairs(fields) do
                        if record[field] ~= nil then
                            record[field] = nil
                            dropped = dropped + 1
                        end
                    end
                end
            end
        end

        strip(db.account.achievements, { "name", "points", "lastSeen" })
        strip(db.account.pets, { "name", "firstSeen", "lastSeen" })
        strip(db.account.toys, { "firstSeen", "lastSeen" })
        strip(db.account.achievementTotals, { "lastSeen" })

        if dropped > 0 then
            CN.DebugPrint("Dropped " .. dropped
                .. " stored values the client already knows.")
        end
    end,

    -- 6 -> 7. Five stores arrived between 0.40.0 and 0.43.0 and none needed a
    -- migration, so the version never moved -- which meant the ladder could
    -- not be used to enforce anything about them either.
    --
    -- The remembered quest pins are the one that matters: they are written on
    -- every scan of a map, capped by a constant in the module, and the cap
    -- was enforced only at the moment of writing. A database that grew past
    -- it under an older build, or through a version where the constant was
    -- larger, stayed large forever. Trim on the way in instead of trusting
    -- that it never happened.
    -- 8 -> 9. Three stores change shape, all of them for speed and all of
    -- them measured.
    --
    -- `ignoredObjectives` and `deferredObjectives` were keyed on a "TYPE:id"
    -- string, and the two functions that read them are called twice per
    -- candidate -- four thousand times each per rebuild at retail scale. So
    -- the moment a player used Ignore once, every rebuild built eight
    -- thousand strings to look up a table with one row in it: +2.2 ms per
    -- rebuild, a 53% increase, for exactly the people the feature is for.
    -- Nested by type, the lookup is two hash indexes and no string at all.
    --
    -- `flightRoutes` was keyed the same way and read once per surviving pair
    -- inside the travel search -- about a thousand times per journey estimate
    -- on a real continent. Node ids are integers, so the pair packs into one
    -- number exactly.
    [8] = function(db)
        db.account = db.account or {}

        for _, name in ipairs({ "ignoredObjectives", "deferredObjectives" }) do
            local store = db.account[name]

            if type(store) == "table" then
                local nested, moved, dropped = {}, 0, 0

                for key, entry in pairs(store) do
                    -- Already nested (a type name maps to a table of ids)
                    -- is left alone, so re-running is harmless.
                    local objectiveType, id =
                        string.match(tostring(key), "^(.-):(.+)$")

                    if objectiveType and id then
                        nested[objectiveType] = nested[objectiveType] or {}
                        nested[objectiveType][tonumber(id) or id] = entry
                        moved = moved + 1
                    elseif type(entry) == "table" then
                        -- Already nested: a type name mapping to a table of
                        -- ids. Carried across as it is.
                        nested[key] = entry
                    else
                        -- AND THE THIRD CASE, WHICH USED TO BE FOLDED INTO
                        -- THE SECOND AND PRODUCED A STORE NOTHING COULD READ.
                        --
                        -- A key with no colon whose value is not a table is
                        -- neither an old flat row nor a new nested one. The
                        -- old branch copied it straight across, so the
                        -- migrated store came out as a mix of `[type] =
                        -- table` and `[junk] = true` -- and `Ignored()`
                        -- indexes `store[type][id]`, which throws on the
                        -- second shape the moment anything of that name is
                        -- filtered.
                        --
                        -- There is nothing to recover here: the value carries
                        -- no id. Dropped, and counted.
                        dropped = dropped + 1
                    end
                end

                db.account[name] = nested

                if moved > 0 then
                    CN.DebugPrint("Renested " .. moved .. " row(s) in "
                        .. name .. ".")
                end

                if dropped > 0 then
                    CN.DebugPrint("Dropped " .. dropped
                        .. " unreadable row(s) from " .. name .. ".")
                end
            end
        end

        local routes = db.account.flightRoutes

        if type(routes) == "table" then
            local packed, moved = {}, 0

            local stride = 1000000

            for key, count in pairs(routes) do
                local from, to = string.match(tostring(key), "^(%d+):(%d+)$")

                if from and to then
                    packed[(tonumber(from) * stride) + tonumber(to)] = count
                    moved = moved + 1
                else
                    packed[key] = count
                end
            end

            db.account.flightRoutes = packed

            if moved > 0 then
                CN.DebugPrint("Repacked " .. moved .. " flight route key(s).")
            end
        end
    end,

    -- 9 -> 10. Preference rows for types the addon can never credit.
    --
    -- Every type a provider emits was counted as "shown"; only the five the
    -- client announces a completion for could ever be counted as "acted". The
    -- other thirteen accumulated sightings against a numerator that was nailed
    -- to zero, crossed the observation threshold, and settled permanently on
    -- the 0.80 floor -- while `/cn learned` reported "you rarely act on
    -- these", which the addon had no way to know.
    --
    -- 0.55.0 stops counting them. These rows are the residue: they cannot be
    -- corrected, because the sightings they hold were never paired with
    -- anything, and leaving them would keep them on screen. Dropped.
    --
    -- Quests, achievements, pets, mounts, toys and the two quest refinements
    -- are kept -- those were being measured properly.
    [9] = function(db)
        -- NOT `db.characters = {}`.
        --
        -- Replacing a corrupt value silently DESTROYS every character profile
        -- and then reports success, so `/cn navdiag` gives a clean bill of
        -- health over a database that just lost the lot. Nothing here is
        -- worth that. A missing table is created; a table that is something
        -- else is a fault, and this release already has machinery for
        -- recording a fault safely -- the `pcall` in `Migrate` catches this,
        -- files it, and stops the ladder.
        if db.characters == nil then
            db.characters = {}
        end

        if type(db.characters) ~= "table" then
            error("db.characters is a " .. type(db.characters)
                .. ", not a table" .. CN.DASH .. "refusing to replace it")
        end

        local keep = {
            QUEST = true, ACHIEVEMENT = true, PET = true, MOUNT = true,
            TOY = true, QUEST_CAMPAIGN = true, QUEST_SIDE = true,
        }

        local dropped = 0

        for _, character in pairs(db.characters) do
            local store = type(character) == "table" and character.preference

            if type(store) == "table" then
                for objectiveType in pairs(store) do
                    if not keep[objectiveType] then
                        store[objectiveType] = nil
                        dropped = dropped + 1
                    end
                end
            end
        end

        if dropped > 0 then
            CN.DebugPrint("Dropped " .. dropped
                .. " preference row(s) the addon could never have credited.")
        end
    end,

    -- 10 -> 11. The bank was a per-character fact in an account-wide table.
    --
    -- `db.account.bank` was written wholesale by whichever character last
    -- opened a bank and read by every character as its own -- so `/cn bags`
    -- on an alt reported items it cannot reach, and opening the bank on that
    -- alt destroyed the main's record. Exactly the defect migration 7 removed
    -- from `questStatus`, in exactly the same shape.
    --
    -- Dropped rather than migrated: there is no field anywhere saying whose
    -- bank it was, so it cannot be attributed, and the next time the player
    -- stands at a bank it is replaced by a correct one. Guessing an owner
    -- would be inventing a fact.
    [10] = function(db)
        db.account = db.account or {}

        if type(db.account.bank) == "table" then
            local held = CN.CountKeys(db.account.bank)

            db.account.bank = nil

            CN.DebugPrint("Dropped an account-wide bank record holding "
                .. tostring(held) .. " row(s); it belonged to one character "
                .. "and was read by all of them.")
        end
    end,

    -- 11 -> 12. The bank stores gained a per-container shape.
    --
    -- The flat store said WHAT was in a bank and not WHICH CONTAINER it was
    -- in, and the container is what makes "this tab has not been described"
    -- separable from "this tab is empty". There is nothing in the old rows
    -- that can be attributed, so they are dropped rather than guessed at --
    -- and the next time the player stands at a bank they are replaced by a
    -- record that keeps its own attribution.
    [11] = function(db)
        db.account    = db.account or {}
        db.characters = db.characters or {}

        local dropped = 0

        local function Flatten(store)
            if type(store) ~= "table" or store.containers ~= nil then
                return
            end

            for key in pairs(store) do
                store[key] = nil
            end

            dropped = dropped + 1
        end

        Flatten(db.account.warbandBank)

        for _, character in pairs(db.characters) do
            if type(character) == "table" then
                Flatten(character.bank)
            end
        end

        if dropped > 0 then
            CN.DebugPrint("Reset " .. dropped .. " bank record(s) that could "
                .. "not say which container each item was in.")
        end
    end,

    -- 12 -> 13. Three fields per discovered quest, all of them write-only.
    --
    -- `discoveredQuests[id]` held `{ firstSeen, lastSeen, source }` and every
    -- reader in the tree -- the completion scan, the breakdown, the window,
    -- `/cn queststatus` -- counts or iterates KEYS. On a mature account that
    -- is tens of thousands of three-field tables rewritten in full on every
    -- logout for information nothing has ever asked for.
    --
    -- Deliberately NOT capped, unlike the two stores beside it. `questPins`
    -- and `questHarvest` have ceilings because a stale pin and a stale
    -- ordering are worth less than a fresh one, so dropping the oldest loses
    -- nothing. A discovery is not like that: the set is what "this account
    -- has seen this quest offered" MEANS, the client will not re-supply it,
    -- and a ceiling would quietly make `/cn queststatus` and the harvest
    -- ordering answer a smaller question than the one asked. As booleans the
    -- store is a fraction of its former size, and `/cn dbsize` reports it.
    --
