                    appearances[id] = nil
                    appearances["set:" .. id] = entry

                    rekeyed = rekeyed + 1
                end
            end
        end

        if rekeyed > 0 then
            CN.DebugPrint("Moved " .. rekeyed .. " hidden or deferred "
                .. "appearance set(s) onto their own key.")
        end
    end,

    -- 15 -> 16. TWO MORE FIELDS THE CLIENT HANDS BACK FOR FREE.
