        local names, zones = 0, 0

        for _, store in ipairs({ db.account.mounts, db.account.toys }) do
            for _, record in pairs(store or {}) do
                if type(record) == "table" and record.name ~= nil then
                    record.name = nil

                    names = names + 1
                end
            end
        end

