                and record.mapID then

                record.zone = nil

                zones = zones + 1
            end
        end

        if names > 0 or zones > 0 then
            CN.DebugPrint("Dropped " .. names .. " collectible name(s) and "
                .. zones .. " vendor zone name(s) the client re-supplies.")
        end
    end,

