$Embedded['Providers\Blizzard.lua'] = @'
-- Providers/Blizzard.lua
-- Completion Navigator :: thin, defensive wrappers over Blizzard APIs.
--
-- Every call into the client goes through this FILE SET. Blizzard renames and
-- removes APIs between patches; keeping the surface area together means a
-- patch break is a contained fix rather than a hunt through the addon.
--
-- Split into three in 0.45.0, at 2,250 lines, when "keep it in one file"
-- stopped meaning "easy to find" and started meaning "search, do not scroll":
--
--   Blizzard.lua             quests, reputation, character, map
--   BlizzardCollections.lua  pets, mounts, toys, appearances, titles
--   BlizzardWorld.lua        professions, the vault, currencies, instances
--
-- Divided by what the client is asked ABOUT, because that is also how patches
-- break things -- a collections patch breaks collection APIs. `CN.Blizzard`
-- remains a single table; only the source is divided.

local ADDON_NAME, CN = ...

local Blizzard = {}

CN.Blizzard = Blizzard

------------------------------------------------------------
-- QUESTS
------------------------------------------------------------

function Blizzard.IsQuestCompletedByCharacter(questID)
    if not questID then
        return false
    end

    if C_QuestLog and C_QuestLog.IsQuestFlaggedCompleted then
        return C_QuestLog.IsQuestFlaggedCompleted(questID) and true or false
    end

    return false
end

function Blizzard.HasAccountQuestAPI()
    return (C_QuestLog and C_QuestLog.IsQuestFlaggedCompletedOnAccount) and true or false
end

function Blizzard.IsQuestCompletedOnAccount(questID)
    if not questID then
        return false
    end

    if C_QuestLog and C_QuestLog.IsQuestFlaggedCompletedOnAccount then
        return C_QuestLog.IsQuestFlaggedCompletedOnAccount(questID) and true or false
    end

    return false
end

-- Returns a title if the client already has it cached. Otherwise requests
-- an asynchronous load and returns nil; QUEST_DATA_LOAD_RESULT follows.
function Blizzard.GetQuestTitle(questID, requestIfMissing)
    if not questID then
        return nil
    end

    if C_QuestLog and C_QuestLog.GetTitleForQuestID then
        local title = C_QuestLog.GetTitleForQuestID(questID)

        if title and title ~= "" then
            return title
        end
    end

    if requestIfMissing and C_QuestLog and C_QuestLog.RequestLoadQuestByID then
        CN.pendingQuestLoads = CN.pendingQuestLoads or {}
        CN.pendingQuestLoads[questID] = true

        C_QuestLog.RequestLoadQuestByID(questID)
    end

    return nil
end

function Blizzard.GetQuestLogEntries()
    local entries = {}

    if not C_QuestLog or not C_QuestLog.GetNumQuestLogEntries then
        return entries
    end

    local count = C_QuestLog.GetNumQuestLogEntries()

    -- pcall'd like every other call in this file set. This one was neither
    -- existence-checked nor protected, in a file whose header promises that
    -- "every call into the client goes through this FILE SET" precisely so a
    -- patch break is a contained fix rather than a broken quest log.
    for index = 1, count do
        local gotInfo, info = pcall(C_QuestLog.GetInfo, index)

        if gotInfo and info and not info.isHeader
            and info.questID and info.questID > 0 then
            table.insert(entries, info)
        end
    end

    return entries
end

-- Scans the map's quest POIs for one quest. This is the source that
-- actually covers ordinary quests; GetNextWaypoint only answers for quests
-- Blizzard has given an explicit waypoint.
function Blizzard.GetQuestPOIOnMap(questID, uiMapID)
    if not questID or not uiMapID or not C_QuestLog or not C_QuestLog.GetQuestsOnMap then
        return nil, nil
    end

    local ok, quests = pcall(C_QuestLog.GetQuestsOnMap, uiMapID)

    if not ok or type(quests) ~= "table" then
        return nil, nil
    end

    for _, info in ipairs(quests) do
        if info.questID == questID and info.x and info.y then
            return info.x, info.y
        end
    end

    return nil, nil
end

-- Every quest POI the client would draw on a map, with its flags.
--
-- This is where the quests you have NOT accepted live. `isQuestStart` marks
-- the exclamation-mark pins -- a quest offered by an NPC standing there -- and
-- `inProgress` distinguishes those from the ones already in your log.
--
-- The addon read this API from the beginning and threw all of that away: it
-- only ever asked "where is this specific quest I already have?". So every
-- quest available in the zone was structurally invisible, which is exactly
-- what a player noticed in game.
function Blizzard.GetQuestPOIsOnMap(uiMapID)
    if not uiMapID or not C_QuestLog or not C_QuestLog.GetQuestsOnMap then
        return {}
    end

    local ok, quests = pcall(C_QuestLog.GetQuestsOnMap, uiMapID)

    if not ok or type(quests) ~= "table" then
        return {}
    end

    local pois = {}

    for _, info in ipairs(quests) do
        if type(info) == "table" and info.questID then
            table.insert(pois, {
                questID      = info.questID,
                x            = info.x,
                y            = info.y,
                mapID        = info.mapID or uiMapID,
                isQuestStart = info.isQuestStart and true or false,
                inProgress   = info.inProgress and true or false,
                isDaily      = info.isDaily and true or false,
                isMeta       = info.isMeta and true or false,
                tagType      = info.questTagType,
            })
        end
    end

    return pois
end

-- Returns mapID, x, y for the next thing the player must physically do for
-- this quest, trying every source the client exposes before giving up.
function Blizzard.GetQuestWaypoint(questID, preferredMapID)
    if not questID then
        return nil, nil, nil
    end

    -- 1. An explicit waypoint, if the quest has one.
    if C_QuestLog and C_QuestLog.GetNextWaypoint then
        local mapID, x, y = C_QuestLog.GetNextWaypoint(questID)

        if mapID and x and y then
            return mapID, x, y
        end
    end

    local playerMap = C_Map and C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player")

    local candidateMaps = {}

    if preferredMapID then
        table.insert(candidateMaps, preferredMapID)
    end

    if playerMap and playerMap ~= preferredMapID then
        table.insert(candidateMaps, playerMap)
    end

    local zoneMap = Blizzard.GetQuestZone(questID)

    if zoneMap and zoneMap ~= playerMap and zoneMap ~= preferredMapID then
        table.insert(candidateMaps, zoneMap)
    end

    for _, mapID in ipairs(candidateMaps) do
        -- 2. The quest's next waypoint expressed on this specific map.
        if C_QuestLog and C_QuestLog.GetNextWaypointForMap then
            local x, y = C_QuestLog.GetNextWaypointForMap(questID, mapID)

            if x and y then
                return mapID, x, y
            end
        end

        -- 3. The quest's POI blip on this map.
        local x, y = Blizzard.GetQuestPOIOnMap(questID, mapID)

        if x and y then
            return mapID, x, y
        end

        -- 4. World-quest style task location.
        if C_TaskQuest and C_TaskQuest.GetQuestLocation then
            local taskX, taskY = C_TaskQuest.GetQuestLocation(questID, mapID)

            if taskX and taskY then
                return mapID, taskX, taskY
            end
        end
    end

    return zoneMap or playerMap, nil, nil
end

-- Blizzard's own quest tracking arrow. The correct answer when we have no
-- coordinates but the game does: it knows where its own quests are.
function Blizzard.SuperTrackQuest(questID)
    if not questID or not C_SuperTrack then
        return false
    end

    if C_SuperTrack.SetSuperTrackedQuestID then
        C_SuperTrack.SetSuperTrackedQuestID(questID)
        return true
    end

    return false
end

function Blizzard.IsQuestInLog(questID)
    if not questID or not C_QuestLog or not C_QuestLog.GetLogIndexForQuestID then
        return false
    end

    return C_QuestLog.GetLogIndexForQuestID(questID) ~= nil
end

function Blizzard.IsQuestReadyForTurnIn(questID)
    if C_QuestLog and C_QuestLog.ReadyForTurnIn then
        return C_QuestLog.ReadyForTurnIn(questID) and true or false
    end

    return false
end

function Blizzard.IsQuestComplete(questID)
    if C_QuestLog and C_QuestLog.IsComplete then
        return C_QuestLog.IsComplete(questID) and true or false
    end

    return false
end

-- Returns completed, total for a quest's objectives.
function Blizzard.GetQuestObjectiveProgress(questID)
    if not C_QuestLog or not C_QuestLog.GetQuestObjectives then
        return 0, 0
    end

    local objectives = C_QuestLog.GetQuestObjectives(questID)

    if not objectives then
        return 0, 0
    end

    local done, total = 0, 0

    for _, objective in ipairs(objectives) do
        total = total + 1

        if objective.finished then
            done = done + 1
        end
    end

    return done, total
end

-- Objectives that are COUNTING something, with where they stand.
--
-- "3/12 Sunscale Feathers" is a different piece of advice from "not started"
-- and from "finished", and the addon has only ever known the middle one
-- existed in aggregate. Returns an array of:
--   { text, type, done, required, remaining, finished }
function Blizzard.GetCountingObjectives(questID)
    local rows = {}

    if not C_QuestLog or not C_QuestLog.GetQuestObjectives then
        return rows
    end

    local ok, objectives = pcall(C_QuestLog.GetQuestObjectives, questID)

    if not ok or type(objectives) ~= "table" then
        return rows
    end

    for _, objective in ipairs(objectives) do
        local required = objective.numRequired or 0

        if required > 1 then
            local done = objective.numFulfilled or 0

            table.insert(rows, {
                text      = objective.text,
                type      = objective.type,
                done      = done,
                required  = required,
                remaining = math.max(0, required - done),
                finished  = objective.finished and true or false,
            })
        end
    end

    return rows
end

function Blizzard.GetQuestZone(questID)
    if C_TaskQuest and C_TaskQuest.GetQuestZoneID then
        local mapID = C_TaskQuest.GetQuestZoneID(questID)

        if mapID then
            return mapID
        end
    end

    if C_QuestLog and C_QuestLog.GetQuestAdditionalHighlights then
        local mapID = C_QuestLog.GetQuestAdditionalHighlights(questID)

        if mapID then
            return mapID
        end
    end

    return nil
end

------------------------------------------------------------
-- REPUTATION
------------------------------------------------------------

-- Retail moved everything to C_Reputation / C_MajorFactions in 11.0.
-- GetFactionInfoByID is gone; never reintroduce it.

function Blizzard.GetNumFactions()
    if C_Reputation and C_Reputation.GetNumFactions then
        return C_Reputation.GetNumFactions()
    end

    return 0
end

function Blizzard.GetFactionByIndex(index)
    if C_Reputation and C_Reputation.GetFactionDataByIndex then
        return C_Reputation.GetFactionDataByIndex(index)
    end

    return nil
end

function Blizzard.GetFactionByID(factionID)
    if C_Reputation and C_Reputation.GetFactionDataByID then
        return C_Reputation.GetFactionDataByID(factionID)
    end

    return nil
end

-- True when the standing is shared across the Warband rather than earned
-- per character. This is the single most important flag for deciding
-- which character should do reputation work.
function Blizzard.IsAccountWideReputation(factionID)
    if C_Reputation and C_Reputation.IsAccountWideReputation then
        return C_Reputation.IsAccountWideReputation(factionID) and true or false
    end

    return false
end

function Blizzard.IsMajorFaction(factionID)
    if C_Reputation and C_Reputation.IsMajorFaction then
        return C_Reputation.IsMajorFaction(factionID) and true or false
    end

    return false
end

function Blizzard.GetMajorFactionData(factionID)
    if C_MajorFactions and C_MajorFactions.GetMajorFactionData then
        return C_MajorFactions.GetMajorFactionData(factionID)
    end

    return nil
end

function Blizzard.HasMaximumRenown(factionID)
    if C_MajorFactions and C_MajorFactions.HasMaximumRenown then
        return C_MajorFactions.HasMaximumRenown(factionID) and true or false
    end

    return false
end

function Blizzard.IsFactionParagon(factionID)
    if C_Reputation and C_Reputation.IsFactionParagon then
        return C_Reputation.IsFactionParagon(factionID) and true or false
    end

    return false
end

-- Returns currentValue, threshold, rewardQuestID, hasRewardPending.
function Blizzard.GetParagonInfo(factionID)
    if C_Reputation and C_Reputation.GetFactionParagonInfo then
        return C_Reputation.GetFactionParagonInfo(factionID)
    end

    return nil
end

-- Friendship-style reputations (Brann, tenders, and similar) do not use
-- the standard 1-8 reaction scale.
function Blizzard.GetFriendshipReputation(factionID)
    if C_GossipInfo and C_GossipInfo.GetFriendshipReputation then
        local info = C_GossipInfo.GetFriendshipReputation(factionID)

        if info and info.friendshipFactionID and info.friendshipFactionID > 0 then
            return info
        end
    end

    return nil
end

function Blizzard.GetStandingLabel(reaction)
    if not reaction then
        return "Unknown"
    end

    return _G["FACTION_STANDING_LABEL" .. reaction] or ("Standing " .. reaction)
end

-- The faction list only reports rows whose headers are expanded, so a
-- complete scan has to expand everything and then put it back.
function Blizzard.WithAllFactionsExpanded(scan)
    -- CAPTURED AND RESTORED BY THE SAME KEY.
    --
    -- The capture keyed on `data.factionID or index` and the restore matched
    -- on `data.factionID` alone, which fails in both directions depending on
    -- what the client puts in `factionID` for a header row. A header with no
    -- id was recorded under an index and could never be matched again, so
    -- every collapsed header stayed permanently open after one `/cn repscan`.
    -- A header with `factionID = 0` -- which is what the fixture itself uses
    -- -- collided with every other header on `collapsed[0]`, so one collapsed
    -- header made the restore collapse them ALL, including the ones the
    -- player deliberately had open.
    --
    -- Keyed on the name, which headers always have and which is stable across
    -- the index shifting that expanding causes. A row with neither an id nor
    -- a name is not restored at all, which is the honest outcome: guessing
    -- is what produced both failures above.
    local collapsed = {}

    local function Key(data)
        if not data then
            return nil
        end

        if data.factionID and data.factionID ~= 0 then
            return "id:" .. tostring(data.factionID)
        end

        if data.name and data.name ~= "" then
            return "name:" .. tostring(data.name)
        end

        return nil
    end

    if C_Reputation and C_Reputation.GetNumFactions then
        for index = C_Reputation.GetNumFactions(), 1, -1 do
            local data = Blizzard.GetFactionByIndex(index)

            if data and data.isCollapsed then
                local key = Key(data)

                if key then
                    collapsed[key] = true
                end
            end
        end
    end

    if C_Reputation and C_Reputation.ExpandAllFactionHeaders then
        C_Reputation.ExpandAllFactionHeaders()
    end

    local ok, err = pcall(scan)

    if C_Reputation and C_Reputation.CollapseFactionHeader then
        for index = Blizzard.GetNumFactions(), 1, -1 do
            local data = Blizzard.GetFactionByIndex(index)
            local key  = Key(data)

            if key and collapsed[key] then
                C_Reputation.CollapseFactionHeader(index)
            end
        end
    end

    if not ok then
        error(err, 0)
    end
end

------------------------------------------------------------
-- CHARACTER
------------------------------------------------------------

function Blizzard.GetProfessions()
    local result = {}

    if not GetProfessions then
        return result
    end

    -- GetProfessions returns nil for any slot the character lacks, and
    -- ipairs stops at the first nil. A character without Archaeology would
    -- silently lose Fishing and Cooking. Index the slots explicitly.
    local slots = { GetProfessions() }

    for slot = 1, 5 do
        local index = slots[slot]

        if index then
            local name, _, rank, maxRank, _, _, skillLineID = GetProfessionInfo(index)

            if name then
                table.insert(result, {
                    name        = name,
                    rank        = rank,
                    maxRank     = maxRank,
                    skillLineID = skillLineID,
                })
            end
        end
    end

    return result
end

------------------------------------------------------------
-- MAP
------------------------------------------------------------

function Blizzard.GetMapName(mapID)
    if not mapID or not C_Map or not C_Map.GetMapInfo then
        return nil
    end

    local info = C_Map.GetMapInfo(mapID)

    return info and info.name or nil
end

------------------------------------------------------------
'@

$Embedded['Providers\BlizzardCollections.lua'] = @'
-- Providers/BlizzardCollections.lua
-- Completion Navigator :: pets, mounts, toys, appearances and titles.
--
-- SPLIT OUT OF Providers/Blizzard.lua IN 0.45.0.
--
-- That file had grown to 2,250 lines and held every call this addon makes
-- into the client. The original argument for one file was sound -- a patch
-- that renames an API is a one-file fix rather than a hunt -- and it stopped
-- being true somewhere around the point where finding the function you wanted
-- required a search rather than a scroll.
--
-- The three files divide by what the client is being asked ABOUT, which is
-- also how patches break things: a collections patch breaks collection APIs.
-- `CN.Blizzard` is still one table; only the source is divided.

local ADDON_NAME, CN = ...

local Blizzard = CN.Blizzard

-- BATTLE PETS
------------------------------------------------------------

-- The pet journal reports only what the player's current filters allow, so
-- any complete scan must widen the filters and then put them back.
--
-- IT PUT BACK THE SEARCH BOX AND NOTHING ELSE.
--
-- The comment above has said "and then put them back" since this was
-- written, and the code restored one of the four things it changed. A player
-- with their journal filtered to, say, uncollected wild pets ran `/cn setup`
-- once and had it silently reset to show everything -- permanently, with no
-- undo, and with no message saying so. That is the addon reaching into the
-- player's interface and changing a setting they chose, which is the one
-- thing this project's standing rule forbids outright: it prompts, it does
-- not act.
--
-- Restoring the checkbox states needs to read them first, and the client
-- will only answer for the two collected filters -- there is no getter for
-- source or type checks. So those are widened only if the scan would
-- otherwise see nothing, and are restored to "all checked", which is the
-- journal's own default and the state the overwhelming majority of players
-- are in. Stated here rather than hidden, because it is the one place this
-- file cannot be exact.
function Blizzard.WithAllPetsShown(scan)
    if not C_PetJournal then
        return
    end

    local search = C_PetJournal.GetSearchFilter and C_PetJournal.GetSearchFilter() or ""

    local collected, uncollected

    if C_PetJournal.IsFilterChecked and LE_PET_JOURNAL_FILTER_COLLECTED then
        local gotCollected, wasCollected =
            pcall(C_PetJournal.IsFilterChecked, LE_PET_JOURNAL_FILTER_COLLECTED)

        local gotUncollected, wasUncollected =
            pcall(C_PetJournal.IsFilterChecked, LE_PET_JOURNAL_FILTER_NOT_COLLECTED)

        -- EXPLICIT IFS. `got and was or nil` cannot express false: when the
        -- filter is off, `false or nil` is nil, the restore is skipped, and
        -- the filter the player turned off stays on. That is the whole bug
        -- this block exists to fix, reintroduced by the idiom -- and it is
        -- the second time this exact and/or trap has shipped in this addon.
        if gotCollected then
            collected = wasCollected and true or false
        end

        if gotUncollected then
            uncollected = wasUncollected and true or false
        end
    end

    if C_PetJournal.SetSearchFilter then
        C_PetJournal.SetSearchFilter("")
    end

    if C_PetJournal.SetFilterChecked and LE_PET_JOURNAL_FILTER_COLLECTED then
        C_PetJournal.SetFilterChecked(LE_PET_JOURNAL_FILTER_COLLECTED, true)
        C_PetJournal.SetFilterChecked(LE_PET_JOURNAL_FILTER_NOT_COLLECTED, true)
    end

    -- THE COMMENT ABOVE SAID "ONLY IF THE SCAN WOULD OTHERWISE SEE NOTHING".
    -- THE CODE DID IT UNCONDITIONALLY, EVERY TIME.
    --
    -- Source and type checks have no getter, so widening them cannot be
    -- undone -- which makes an unconditional widen a permanent change to a
    -- setting the player chose. And the pet scan runs on a thirty-second
    -- throttle off PET_JOURNAL_LIST_UPDATE, so a player with the Pet Journal
    -- open and filtered to, say, Drop-source Beasts had those filters wiped
    -- twice a minute while they were using it. By an addon whose standing
    -- rule is that it prompts and does not act.
    --
    -- The honest version, at last. The journal's own count answers the
    -- question before anything is changed: with the collected filters already
    -- widened above, a count of zero can only mean the source or type checks
    -- are hiding everything. Only then is the widening justified -- and the
    -- player is told, because it is not recoverable.
    if select(1, Blizzard.GetNumPets()) == 0 then
        local widened = false

        if C_PetJournal.SetAllPetSourcesChecked then
            C_PetJournal.SetAllPetSourcesChecked(true)
            widened = true
        end

        if C_PetJournal.SetAllPetTypesChecked then
            C_PetJournal.SetAllPetTypesChecked(true)
            widened = true
        end

        if widened then
            CN.Print("Your Pet Journal's source and type filters were hiding "
                .. "every pet, so they were set to show everything. The "
                .. "client does not let an addon read those checkboxes, so "
                .. "they cannot be put back" .. CN.DASH .. "set them again in the journal "
                .. "if you had them narrowed.")
        end
    end

    local ok, err = pcall(scan)

    -- Put back everything that was read, whether the scan threw or not.
    if C_PetJournal.SetSearchFilter then
        C_PetJournal.SetSearchFilter(search or "")
    end

    if C_PetJournal.SetFilterChecked and LE_PET_JOURNAL_FILTER_COLLECTED then
        if collected ~= nil then
            pcall(C_PetJournal.SetFilterChecked,
                LE_PET_JOURNAL_FILTER_COLLECTED, collected)
        end

        if uncollected ~= nil then
            pcall(C_PetJournal.SetFilterChecked,
                LE_PET_JOURNAL_FILTER_NOT_COLLECTED, uncollected)
        end
    end

    if not ok then
        error(err, 0)
    end
end

function Blizzard.GetNumPets()
    if C_PetJournal and C_PetJournal.GetNumPets then
        return C_PetJournal.GetNumPets()
    end

    return 0, 0
end

function Blizzard.GetPetByIndex(index)
    if not C_PetJournal or not C_PetJournal.GetPetInfoByIndex then
        return nil
    end

    local petID, speciesID, owned, customName, level, favorite, isRevoked,
          speciesName, icon, petType, companionID, tooltip, description,
          isWild, canBattle, isTradeable, isUnique, obtainable =
          C_PetJournal.GetPetInfoByIndex(index)

    if not speciesID then
        return nil
    end

    return {
        petID       = petID,
        speciesID   = speciesID,
        owned       = owned and true or false,
        level       = level,
        favorite    = favorite and true or false,
        name        = speciesName,
        icon        = icon,
        petType     = petType,
        isWild      = isWild and true or false,
        canBattle   = canBattle and true or false,
        obtainable  = obtainable ~= false,
        description = description,
    }
end

-- A pet's name, from the client's own journal.
--
-- Exists so the addon can stop keeping its own copy of eighteen hundred pet
-- names on disk. The journal answers instantly and is always current, which a
-- saved copy is not.
function Blizzard.GetPetName(speciesID)
    if not speciesID or not C_PetJournal or not C_PetJournal.GetPetInfoBySpeciesID then
        return nil
    end

    local ok, name = pcall(C_PetJournal.GetPetInfoBySpeciesID, speciesID)

    if ok and name and name ~= "" then
        return name
    end

    return nil
end

function Blizzard.GetPetCollectedCount(speciesID)
    if C_PetJournal and C_PetJournal.GetNumCollectedInfo then
        return C_PetJournal.GetNumCollectedInfo(speciesID)
    end

    return 0, 0
end

------------------------------------------------------------
-- MOUNTS
------------------------------------------------------------

function Blizzard.GetMountIDs()
    if C_MountJournal and C_MountJournal.GetMountIDs then
        return C_MountJournal.GetMountIDs()
    end

    return {}
end

-- A toy's name, live. `C_ToyBox.GetToyInfo` returns itemID, name, icon,
-- isFavorite, hasFanfare, quality -- and answers instantly, which is why the
-- addon has no business keeping a copy of it on disk.
function Blizzard.GetToyName(itemID)
    if not C_ToyBox or not C_ToyBox.GetToyInfo or not itemID then
        return nil
    end

    local ok, _, name = pcall(C_ToyBox.GetToyInfo, itemID)

    if ok and type(name) == "string" and name ~= "" then
        return name
    end

    return nil
end

function Blizzard.GetMountByID(mountID)
    if not C_MountJournal or not C_MountJournal.GetMountInfoByID then
        return nil
    end

    local name, spellID, icon, isActive, isUsable, sourceType, isFavorite,
          isFactionSpecific, faction, shouldHideOnChar, isCollected =
          C_MountJournal.GetMountInfoByID(mountID)

    if not name then
        return nil
    end

    local source, description

    if C_MountJournal.GetMountInfoExtraByID then
        local _, extraDescription, extraSource = C_MountJournal.GetMountInfoExtraByID(mountID)

        description = extraDescription
        source      = extraSource
    end

    return {
        mountID           = mountID,
        name              = name,
        spellID           = spellID,
        icon              = icon,
        sourceType        = sourceType,
        isFactionSpecific = isFactionSpecific and true or false,
        faction           = faction,
        hiddenOnCharacter = shouldHideOnChar and true or false,
        isCollected       = isCollected and true or false,
        source            = source,
        description       = description,
    }
end

------------------------------------------------------------
-- TOYS
------------------------------------------------------------

-- Same filter problem as the pet journal, and until 0.49.0 the same failure
-- to put anything back -- this one restored nothing at all, not even the
-- search string it cleared.
function Blizzard.WithAllToysShown(scan)
    if not C_ToyBox then
        return
    end

    local collected, uncollected

    -- Explicit, for the reason spelled out in WithAllPetsShown above.
    if C_ToyBox.GetCollectedShown then
        local got, was = pcall(C_ToyBox.GetCollectedShown)

        if got then
            collected = was and true or false
        end
    end

    if C_ToyBox.GetUncollectedShown then
        local got, was = pcall(C_ToyBox.GetUncollectedShown)

        if got then
            uncollected = was and true or false
        end
    end

    if C_ToyBox.SetFilterString then
        C_ToyBox.SetFilterString("")
    end

    if C_ToyBox.SetCollectedShown then
        C_ToyBox.SetCollectedShown(true)
    end

    if C_ToyBox.SetUncollectedShown then
        C_ToyBox.SetUncollectedShown(true)
    end

    -- SAME RULE AS THE PET JOURNAL, AND FOR THE SAME REASON.
    --
    -- `SetAllSourceTypeFilters` has no getter either, so widening it is
    -- permanent. It was done unconditionally and never restored. With the
    -- collected and uncollected filters already widened above, a filtered
    -- count of zero can only be the source-type checks, and that is the one
    -- case where changing them beats returning an empty collection.
    if Blizzard.GetNumToys() == 0 and C_ToyBox.SetAllSourceTypeFilters then
        C_ToyBox.SetAllSourceTypeFilters(true)

        CN.Print("Your Toy Box's source filters were hiding every toy, so "
            .. "they were set to show everything. The client does not let an "
            .. "addon read them, so they cannot be put back.")
    end

    local ok, err = pcall(scan)

    -- NOT A RESTORE, AND NO LONGER PRETENDING TO BE ONE.
    --
    -- There is no `GetFilterString`, so the search box's contents were never
    -- captured and this line cleared it a second time. It stays -- an addon
    -- that leaves a search string behind would hide the player's own toys --
    -- but it is described accurately: the box is left empty, not restored.
    if C_ToyBox.SetFilterString then
        C_ToyBox.SetFilterString("")
    end

    if collected ~= nil and C_ToyBox.SetCollectedShown then
        pcall(C_ToyBox.SetCollectedShown, collected)
    end

    if uncollected ~= nil and C_ToyBox.SetUncollectedShown then
        pcall(C_ToyBox.SetUncollectedShown, uncollected)
    end

    if not ok then
        error(err, 0)
    end
end

function Blizzard.GetNumToys()
    if C_ToyBox and C_ToyBox.GetNumFilteredToys then
        return C_ToyBox.GetNumFilteredToys()
    end

    if C_ToyBox and C_ToyBox.GetNumToys then
        return C_ToyBox.GetNumToys()
    end

    return 0
end

function Blizzard.GetToyByIndex(index)
    if not C_ToyBox or not C_ToyBox.GetToyFromIndex then
        return nil
    end

    local itemID = C_ToyBox.GetToyFromIndex(index)

    if not itemID or itemID == 0 then
        return nil
    end

    local _, name, icon = C_ToyBox.GetToyInfo(itemID)

    return {
        itemID    = itemID,
        name      = name,
        icon      = icon,
        collected = PlayerHasToy and PlayerHasToy(itemID) and true or false,
    }
end

------------------------------------------------------------
-- APPEARANCES (TRANSMOG)
------------------------------------------------------------

-- Appearance counts are reported per category. Individual appearance
-- enumeration is enormous; the per-category totals are what a completion
-- dashboard actually needs.
function Blizzard.GetAppearanceCategories()
    local categories = {}

    if not C_TransmogCollection then
        return categories
    end

    local names = C_TransmogCollection.GetCategoryInfo
        and Enum and Enum.TransmogCollectionType

    if not names then
        return categories
    end

    for _, categoryID in pairs(Enum.TransmogCollectionType) do
        if type(categoryID) == "number" then
            local name = C_TransmogCollection.GetCategoryInfo(categoryID)

            if name then
                local collected = C_TransmogCollection.GetCategoryCollectedCount
                    and C_TransmogCollection.GetCategoryCollectedCount(categoryID) or 0

                local total = C_TransmogCollection.GetCategoryTotal
                    and C_TransmogCollection.GetCategoryTotal(categoryID) or 0

                if total and total > 0 then
                    table.insert(categories, {
                        categoryID = categoryID,
                        name       = name,
                        collected  = collected,
                        total      = total,
                    })
                end
            end
        end
    end

    table.sort(categories, function(a, b) return a.name < b.name end)

    return categories
end

------------------------------------------------------------
-- TITLES
------------------------------------------------------------

function Blizzard.GetTitles()
    local titles = {}

    if not GetNumTitles then
        return titles
    end

    for index = 1, GetNumTitles() do
        local name = GetTitleName and GetTitleName(index)

        if name and name ~= "" then
            table.insert(titles, {
                titleID = index,
                name    = (name:gsub("^%s+", ""):gsub("%s+$", "")),
                known   = IsTitleKnown and IsTitleKnown(index) and true or false,
            })
        end
    end

    return titles
end

------------------------------------------------------------
-- ACHIEVEMENTS
------------------------------------------------------------

function Blizzard.GetAchievementCategories()
    if GetCategoryList then
        return GetCategoryList()
    end

    return {}
end

function Blizzard.GetCategoryCounts(categoryID)
    if not GetCategoryNumAchievements then
        return 0, 0
    end

    local total, completed = GetCategoryNumAchievements(categoryID, true)

    return total or 0, completed or 0
end

function Blizzard.GetAchievementInCategory(categoryID, index)
    if not GetAchievementInfo then
        return nil
    end

    local id, name, points, completed, _, _, _, description, flags, icon =
        GetAchievementInfo(categoryID, index)

    if not id then
        return nil
    end

    return {
        achievementID = id,
        name          = name,
        points        = points or 0,
        completed     = completed and true or false,
        description   = description,
        icon          = icon,
        flags         = flags,
    }
end

-- Points for one achievement, live from the client.
--
-- The addon stopped storing points in 0.36.0 because the client answers
-- instantly and a copy on disk was dead weight. That was right, and it left
-- one caller reading a field that no longer exists -- so this is the
-- replacement it should have had at the time.
function Blizzard.GetAchievementPoints(achievementID)
    if not GetAchievementInfo or not achievementID then
        return nil
    end

    local ok, _, _, points = pcall(GetAchievementInfo, achievementID)

    if not ok then
        return nil
    end

    return points
end

-- WHETHER THE ACCOUNT HAS EARNED IT, BY ID. 0.70.0.
--
-- The only route to this was `GetAchievementInCategory`, which walks a
-- category by index -- so a caller that has an achievement ID and wants one
-- boolean had to either walk the tree or derive it from criteria counts.
-- Deriving it is wrong: criteria progress is per CHARACTER and the earned
-- flag is per ACCOUNT, and 0.69.0 shipped exactly that mistake.
--
-- `GetAchievementInfo(id)` answers directly. Fourth return is the flag.
function Blizzard.IsAchievementEarned(achievementID)
    if not GetAchievementInfo or not achievementID then
        return nil
    end

    local ok, id, _, _, completed = pcall(GetAchievementInfo, achievementID)

    -- NOT ANSWERING IS NOT ANSWERING "NO". 0.71.0.
    --
    -- `GetAchievementInfo` does not throw for an id it cannot answer about --
    -- it returns nothing -- so `ok` is true, `completed` is nil, and this
    -- returned FALSE. The `pcall` guard could only ever catch a hard error,
    -- and the case the nil contract was written for fell straight through it.
    --
    -- The caller writes the result into an account-wide earned flag whenever
    -- it is not nil, so one `CRITERIA_UPDATE` in the seconds after a loading
    -- screen un-earned a zone the account had finished -- which is the defect
    -- 0.70.0's changelog says it fixed, arriving through a different door.
    --
    -- The first return is the id: if the client answered at all, that is
    -- there.
    if not ok or not id then
        return nil
    end

    return completed and true or false
end

-- Returns completedCriteria, totalCriteria for one achievement.
-- The achievement's name, straight from the client.
--
-- Needed because a player can pin an achievement the addon has never scanned,
-- and answering them with "Achievement 12345" is the addon admitting it did
-- not look.
-- An achievement CATEGORY's name, from the client. `GetCategoryInfo` returns
-- name, parentID, flags. Added in 0.64.0 because Loremaster was persisting the
-- localized category string and grouping on it.
function Blizzard.GetCategoryName(categoryID)
    if not GetCategoryInfo or not categoryID then
        return nil
    end

    local ok, name = pcall(GetCategoryInfo, categoryID)

    if ok and type(name) == "string" and name ~= "" then
        return name
    end

    return nil
end

-- A title's name by id. The hidden-objectives list read this from disk with
-- no live path at all.
function Blizzard.GetTitleName(titleID)
    if not GetTitleName or not titleID then
        return nil
    end

    local ok, name = pcall(GetTitleName, titleID)

    -- TRIMMED, LIKE ITS SIBLING TWO HUNDRED LINES UP. 0.82.0.
    --
    -- The client hands back title fragments padded for concatenation --
    -- " the Explorer", "Ambassador " -- which is why `Blizzard.GetTitles`
    -- strips them. This function was added later, for the one path that had
    -- no live lookup, and did not. `Titles.NameOf` has no store fallback by
    -- design, so this IS the name: `/cn title` printed a leading space, and
    -- the addon matched on the trimmed string while displaying the padded
    -- one. The harness could not see it -- its fixture is already trimmed.
    if ok and type(name) == "string" then
        name = (name:gsub("^%s+", ""):gsub("%s+$", ""))

        if name ~= "" then
            return name
        end
    end

    return nil
end

-- A specialization's name, in the reader's language, from its stable id.
--
-- The addon stores the ID per character and resolves the WORD here, rather
-- than persisting whatever language the alt happened to be levelled in --
-- the rule six migrations in this project exist to enforce.
function Blizzard.GetSpecName(specID)
    if not GetSpecializationInfoByID or not specID then
        return nil
    end

    local ok, _, name = pcall(GetSpecializationInfoByID, specID)

    if ok and type(name) == "string" and name ~= "" then
        return name
    end

    return nil
end

function Blizzard.GetAchievementName(achievementID)
    if not GetAchievementInfo or not achievementID then
        return nil
    end

    local ok, _, name = pcall(GetAchievementInfo, achievementID)

    if ok and name and name ~= "" then
        return name
    end

    return nil
end

function Blizzard.GetAchievementProgress(achievementID)
    if not GetAchievementNumCriteria or not GetAchievementCriteriaInfo then
        return 0, 0
    end

    local total = GetAchievementNumCriteria(achievementID) or 0
    local done  = 0

    -- A SINGLE COUNTING CRITERION IS NOT A SINGLE STEP.
    --
    -- "Complete 100 quests in Hallowfall" is reported by the client as ONE
    -- criterion carrying a quantity and a requirement. Counting rows gave
    -- 0 of 1 -- so a hundred-quest zone grind was filed as "not started, 1
    -- to do", sorted to the front of `/cn zones` as the smallest job
    -- available, awarded the "a small remainder is a session" bonus, and
    -- emitted as a recommendation reading "1 of 1 left in this zone".
    --
    -- The quantity is right there on the same call this function already
    -- makes; it was being discarded. When a single criterion carries a real
    -- requirement, that requirement IS the denominator.
    if total == 1 then
        local _, _, criteriaCompleted, quantity, required =
            GetAchievementCriteriaInfo(achievementID, 1)

        if type(required) == "number" and required > 1 then
            return math.min(quantity or 0, required), required
        end

        return criteriaCompleted and 1 or 0, 1
    end

    for index = 1, total do
        local _, _, criteriaCompleted = GetAchievementCriteriaInfo(achievementID, index)

        if criteriaCompleted then
            done = done + 1
        end
    end

    return done, total
end

function Blizzard.GetAchievementTotals()
    if GetNumCompletedAchievements then
        local total, completed = GetNumCompletedAchievements(true)
        return total or 0, completed or 0
    end

    return 0, 0
end

