'@

$Embedded['Providers\BlizzardWorld.lua'] = @'
-- Providers/BlizzardWorld.lua
-- Completion Navigator :: professions, the vault, currencies, instances and the world.
--
-- SPLIT OUT OF Providers/Blizzard.lua IN 0.45.0.
--
-- That file had grown to 2,250 lines and held every call this addon makes
-- into the client. The original argument for one file was sound -- a patch
-- that renames an API is a one-file fix rather than a hunt -- and it stopped
-- being true somewhere around the point where finding the function you wanted
-- required a search rather than a scroll.
--
-- The three files divide by what the client is being asked ABOUT, which is
-- also how patches break things: a collections patch breaks collection APIs.
-- `CN.Blizzard` is still one table; only the source is divided.

local ADDON_NAME, CN = ...

local Blizzard = CN.Blizzard

-- PROFESSIONS AND RECIPES
------------------------------------------------------------

function Blizzard.GetProfessionSkillLines()
    local lines = {}

    if not GetProfessions then
        return lines
    end

    -- Same nil-hole problem as above: index the five slots explicitly
    -- rather than iterating, or missing professions truncate the list.
    local slots = { GetProfessions() }

    for slot = 1, 5 do
        local index = slots[slot]

        if index then
            local name, _, rank, maxRank, _, _, skillLineID, _, _, _ = GetProfessionInfo(index)

            if name and skillLineID then
                table.insert(lines, {
                    name        = name,
                    rank        = rank,
                    maxRank     = maxRank,
                    skillLineID = skillLineID,
                })
            end
        end
    end

    return lines
end

-- Recipe enumeration only works while a trade skill window is open. This
-- is a hard client restriction, not a choice; callers must handle false.
function Blizzard.IsTradeSkillReady()
    if C_TradeSkillUI and C_TradeSkillUI.IsTradeSkillReady then
        return C_TradeSkillUI.IsTradeSkillReady() and true or false
    end

    return false
end

function Blizzard.GetOpenTradeSkillLine()
    if C_TradeSkillUI and C_TradeSkillUI.GetBaseProfessionInfo then
        local info = C_TradeSkillUI.GetBaseProfessionInfo()

        if info and info.professionID then
            return info.professionID, info.professionName
        end
    end

    if C_TradeSkillUI and C_TradeSkillUI.GetTradeSkillLine then
        return C_TradeSkillUI.GetTradeSkillLine()
    end

    return nil, nil
end

function Blizzard.GetAllRecipeIDs()
    if C_TradeSkillUI and C_TradeSkillUI.GetAllRecipeIDs then
        local ok, ids = pcall(C_TradeSkillUI.GetAllRecipeIDs)

        if ok and type(ids) == "table" then
            return ids
        end
    end

    return {}
end

function Blizzard.GetRecipeInfo(recipeID)
    if not C_TradeSkillUI or not C_TradeSkillUI.GetRecipeInfo then
        return nil
    end

    local ok, info = pcall(C_TradeSkillUI.GetRecipeInfo, recipeID)

    if not ok or type(info) ~= "table" then
        return nil
    end

    return info
end

------------------------------------------------------------
-- TIME-SENSITIVE CONTENT
------------------------------------------------------------

function Blizzard.GetSecondsUntilDailyReset()
    if GetQuestResetTime then
        local ok, seconds = pcall(GetQuestResetTime)

        if ok and type(seconds) == "number" and seconds > 0 then
            return seconds
        end
    end

    return nil
end

function Blizzard.GetSecondsUntilWeeklyReset()
    if C_DateAndTime and C_DateAndTime.GetSecondsUntilWeeklyReset then
        local ok, seconds = pcall(C_DateAndTime.GetSecondsUntilWeeklyReset)

        if ok and type(seconds) == "number" and seconds > 0 then
            return seconds
        end
    end

    return nil
end

------------------------------------------------------------
-- GREAT VAULT
------------------------------------------------------------

-- The weekly reward chest. Three rows -- raid, dungeons, world -- each with
-- three thresholds, and you pick ONE item from everything unlocked.
--
-- This is the only system in the game that hands the addon all three things
-- it normally has to guess at: a hard deadline, a known denominator, and a
-- known reward. Everywhere else the addon reports counts because a percentage
-- would need a denominator the client will not supply; here the thresholds
-- are fixed and the client reports progress against them, so "3 of 4" is a
-- fact rather than an estimate.
--
-- The enum has been renamed across expansions, so the row type is resolved by
-- probing rather than assumed.
local function ThresholdEnum()
    if not Enum then
        return {}
    end

    return Enum.WeeklyRewardChestThresholdType
        or Enum.WeeklyRewardChestThreshold
        or {}
end

function Blizzard.HasWeeklyRewards()
    return C_WeeklyRewards ~= nil and C_WeeklyRewards.GetActivities ~= nil
end

-- Maps the client's row enum onto stable names of our own, so nothing
-- downstream depends on Blizzard's numbering.
function Blizzard.WeeklyRewardRowName(activityType)
    local enum = ThresholdEnum()

    if enum.Raid and activityType == enum.Raid then
        return "RAID"
    end

    -- Mythic+ is called "Activities" in the enum, which is uselessly generic.
    if enum.Activities and activityType == enum.Activities then
        return "DUNGEON"
    end

    if enum.World and activityType == enum.World then
        return "WORLD"
    end

    -- Older builds exposed a PvP row; treat it as world content rather than
    -- dropping it, so nothing silently disappears.
    if enum.RankedPvP and activityType == enum.RankedPvP then
        return "PVP"
    end

    return "UNKNOWN"
end

-- Returns an array of rows:
--   { row, index, threshold, progress, level, unlocked, rewardID }
function Blizzard.GetWeeklyRewardActivities()
    if not Blizzard.HasWeeklyRewards() then
        return {}
    end

    local ok, activities = pcall(C_WeeklyRewards.GetActivities)

    if not ok or type(activities) ~= "table" then
        return {}
    end

    local rows = {}

    for _, activity in ipairs(activities) do
        if type(activity) == "table" then
            local threshold = activity.threshold or 0
            local progress  = activity.progress or 0

            table.insert(rows, {
                row       = Blizzard.WeeklyRewardRowName(activity.type),
                index     = activity.index,
                threshold = threshold,
                progress  = progress,
                level     = activity.level,
                unlocked  = threshold > 0 and progress >= threshold,
                rewardID  = activity.id,
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.row ~= b.row then
            return a.row < b.row
        end

        return (a.threshold or 0) < (b.threshold or 0)
    end)

    return rows
end

function Blizzard.HasAvailableWeeklyRewards()
    if not C_WeeklyRewards then
        return false
    end

    if C_WeeklyRewards.HasAvailableRewards then
        local ok, available = pcall(C_WeeklyRewards.HasAvailableRewards)

        if ok then
            return available and true or false
        end
    end

    return false
end

function Blizzard.IsWorldQuest(questID)
    if C_QuestLog and C_QuestLog.IsWorldQuest then
        local ok, result = pcall(C_QuestLog.IsWorldQuest, questID)

        return ok and result and true or false
    end

    return false
end

-- Seconds remaining on a world quest, or nil when it is not time-limited.
function Blizzard.GetQuestTimeLeft(questID)
    if not C_TaskQuest then
        return nil
    end

    if C_TaskQuest.GetQuestTimeLeftSeconds then
        local ok, seconds = pcall(C_TaskQuest.GetQuestTimeLeftSeconds, questID)

        if ok and type(seconds) == "number" and seconds > 0 then
            return seconds
        end
    end

    if C_TaskQuest.GetQuestTimeLeftMinutes then
        local ok, minutes = pcall(C_TaskQuest.GetQuestTimeLeftMinutes, questID)

        if ok and type(minutes) == "number" and minutes > 0 then
            return minutes * 60
        end
    end

    return nil
end

-- World quests currently up on a map. The field naming has changed between
-- versions (questId vs questID), so both are accepted.
function Blizzard.GetWorldQuestsOnMap(uiMapID)
    local results = {}

    if not uiMapID or not C_TaskQuest or not C_TaskQuest.GetQuestsForPlayerByMapID then
        return results
    end

    local ok, tasks = pcall(C_TaskQuest.GetQuestsForPlayerByMapID, uiMapID)

    if not ok or type(tasks) ~= "table" then
        return results
    end

    for _, task in ipairs(tasks) do
        local questID = task.questID or task.questId

        if questID then
            table.insert(results, {
                questID = questID,
                mapID   = task.mapID or uiMapID,
                x       = task.x,
                y       = task.y,
                inArea  = task.inProgress,
            })
        end
    end

    return results
end

function Blizzard.GetWorldQuestInfo(questID)
    local info = {}

    if C_TaskQuest and C_TaskQuest.GetQuestInfoByQuestID then
        local ok, title, factionID = pcall(C_TaskQuest.GetQuestInfoByQuestID, questID)

        if ok then
            info.title     = title
            info.factionID = factionID
        end
    end

    if C_QuestLog and C_QuestLog.GetQuestTagInfo then
        local ok, tag = pcall(C_QuestLog.GetQuestTagInfo, questID)

        if ok and type(tag) == "table" then
            info.tagName        = tag.tagName
            info.worldQuestType = tag.worldQuestType
            info.quality        = tag.quality
            info.isElite        = tag.isElite
        end
    end

    return info
end

-- Calendar events happening today. Requires the calendar to have been
-- opened at least once; the call is cheap and safe to repeat.
function Blizzard.GetTodaysEvents()
    local events = {}

    if not C_Calendar or not C_DateAndTime then
        return events
    end

    pcall(function()
        if C_Calendar.OpenCalendar then
            C_Calendar.OpenCalendar()
        end
    end)

    local ok, today = pcall(C_DateAndTime.GetCurrentCalendarTime)

    if not ok or type(today) ~= "table" or not today.monthDay then
        return events
    end

    local gotCount, count = pcall(C_Calendar.GetNumDayEvents, 0, today.monthDay)

    if not gotCount or type(count) ~= "number" then
        return events
    end

    for index = 1, count do
        local gotEvent, event = pcall(C_Calendar.GetDayEvent, 0, today.monthDay, index)

        if gotEvent and type(event) == "table" and event.title then
            -- sequenceType is "ONGOING" or "START" while an event is live.
            local ongoing = event.sequenceType == "ONGOING"
                or event.sequenceType == "START"
                or event.sequenceType == ""

            -- WHEN IT ENDS, where the calendar says so.
            --
            -- Without this an active event is just a name, and the ranking
            -- has nothing to weigh: "Timewalking is on" and "Timewalking ends
            -- in four hours" are different pieces of advice. Some builds omit
            -- the end time entirely, and nil is then the right answer rather
            -- than a guessed week.
            local endsAt, endsIn

            -- Gated on the end time itself, which is all this block reads.
            -- It used to also require C_DateAndTime.GetSecondsUntilWeeklyReset
            -- -- a function it never calls -- so on any build lacking that
            -- unrelated API every calendar event silently lost its deadline,
            -- and with it the urgency weighting and the "ends in" line.
            if type(event.endTime) == "table" and event.endTime.monthDay then

                local finish = event.endTime

                local nowStamp = time()

                local okStamp, stamp = pcall(time, {
                    year  = finish.year   or 0,
                    month = finish.month  or 1,
                    day   = finish.monthDay,
                    hour  = finish.hour   or 0,
                    min   = finish.minute or 0,
                })

                if okStamp and stamp and stamp > nowStamp then
                    endsAt = stamp
                    endsIn = stamp - nowStamp
                end
            end

            -- THE ABSOLUTE TIME AS WELL AS THE RELATIVE ONE.
            --
            -- `endsIn` is computed here, at SCAN time, and the caller caches
            -- the whole list for thirty minutes -- so a deadline could be
            -- half an hour stale on the heaviest-weighted term in the
            -- scorer, whose steep ramp lives entirely inside the last two
            -- hours. "Ends in 40m" printed ten minutes after it ended.
            --
            -- `endsAt` does not go stale, so the reader can derive a fresh
            -- `endsIn` from it however long the list has been held.
            table.insert(events, {
                title        = event.title,
                -- The client supplies one on retail; carried through so the
                -- consumer can key on it rather than on a translated title.
                -- Nil elsewhere, and the consumer composes a stable key from
                -- the three type fields in that case.
                eventID      = event.eventID,
                eventType    = event.eventType,
                calendarType = event.calendarType,
                sequenceType = event.sequenceType,
                ongoing      = ongoing,
                endsAt       = endsAt,
                endsIn       = endsIn,
            })
        end
    end

    return events
end

------------------------------------------------------------
-- VIGNETTES (RARES AND TREASURES)
------------------------------------------------------------

-- Vignettes are the skull and chest icons the client puts on the minimap.
-- They are the only live signal that a rare is actually up right now, which
-- is what makes them worth more than any static rare database.
function Blizzard.GetVignettes(uiMapID)
    local results = {}

    if not C_VignetteInfo or not C_VignetteInfo.GetVignettes then
        return results
    end

    local ok, guids = pcall(C_VignetteInfo.GetVignettes)

    if not ok or type(guids) ~= "table" then
        return results
    end

    for _, guid in ipairs(guids) do
        local gotInfo, info = pcall(C_VignetteInfo.GetVignetteInfo, guid)

        if gotInfo and type(info) == "table" and info.name then
            local entry = {
                guid        = guid,
                vignetteID  = info.vignetteID,
                name        = info.name,
                atlas       = info.atlasName,
                objectGUID  = info.objectGUID,
                isDead      = info.isDead and true or false,
                onMinimap   = info.onMinimap,
                inFogOfWar  = info.inFogOfWar,
            }

            if uiMapID and C_VignetteInfo.GetVignettePosition then
                local gotPosition, position =
                    pcall(C_VignetteInfo.GetVignettePosition, guid, uiMapID)

                if gotPosition and position and position.GetXY then
                    local x, y = position:GetXY()

                    entry.mapID = uiMapID
                    entry.x     = x
                    entry.y     = y
                end
            end

            table.insert(results, entry)
        end
    end

    return results
end

-- Treasure chests and rare creatures use different atlas art. The atlas
-- name is the only reliable discriminator the client exposes.
function Blizzard.ClassifyVignette(atlasName)
    if type(atlasName) ~= "string" then
        return "UNKNOWN"
    end

    local lower = string.lower(atlasName)

    if string.find(lower, "chest", 1, true)
        or string.find(lower, "treasure", 1, true)
        or string.find(lower, "lootcontainer", 1, true) then
        return "TREASURE"
    end

    if string.find(lower, "vignetteskull", 1, true)
        or string.find(lower, "vignetteboss", 1, true)
        or string.find(lower, "elite", 1, true) then
        return "RARE"
    end

    if string.find(lower, "vignette", 1, true) then
        return "RARE"
    end

    return "UNKNOWN"
end

------------------------------------------------------------
-- CURRENCIES
------------------------------------------------------------

function Blizzard.GetCurrencyList()
    local results = {}

-- The currency id for a row of the currency list.
--
-- GetCurrencyListInfo returns a display record with no id in it. The link is
-- the only thing that carries one, and it has to be dug out of the hyperlink
-- -- `|Hcurrency:2245|h[Flightstones]|h` -- because the client offers no
-- direct accessor. Guarded and pcall'd at every step: this runs once per
-- currency on every scan, and a client that will not produce a link should
-- cost the row, not the scan.
local function CurrencyIDFromList(index)
    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyListLink then
        return nil
    end

    local ok, link = pcall(C_CurrencyInfo.GetCurrencyListLink, index)

    if not ok or type(link) ~= "string" then
        return nil
    end

    return tonumber(string.match(link, "currency:(%d+)"))
end

    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyListSize then
        return results
    end

    -- A COLLAPSED HEADER HIDES ITS ROWS FROM THE COUNT.
    --
    -- `GetCurrencyListSize` counts only rows under EXPANDED headers, exactly
    -- like the faction list. The reputation path has handled this since
    -- 0.30.0 with `WithAllFactionsExpanded`; the currency path never did, and
    -- there was no `ExpandCurrencyList` call anywhere in the addon. A player
    -- who had collapsed an expansion group in their Currency tab lost every
    -- currency underneath it from `/cn currencies`, from `/cn clock` and from
    -- the weekly-cap warnings, with nothing on screen saying so.
    --
    -- Expanded, scanned, put back -- the same shape, and the same obligation:
    -- what this addon changes to read, it changes back.
    local collapsed = {}

    if C_CurrencyInfo.ExpandCurrencyList then
        local counted, initial = pcall(C_CurrencyInfo.GetCurrencyListSize)

        if counted and type(initial) == "number" then
            for index = initial, 1, -1 do
                local asked, row = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)

                if asked and type(row) == "table" and row.isHeader
                    and row.isHeaderExpanded == false then

                    table.insert(collapsed, row.name)

                    pcall(C_CurrencyInfo.ExpandCurrencyList, index, true)
                end
            end
        end
    end

    local ok, size = pcall(C_CurrencyInfo.GetCurrencyListSize)

    if not ok or type(size) ~= "number" then
        return results
    end

    for index = 1, size do
        local gotInfo, info = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)


        if gotInfo and type(info) == "table" and not info.isHeader and info.name then
            -- THE LIST ROW DOES NOT CARRY AN ID.
            --
            -- CurrencyDisplayInfo -- what GetCurrencyListInfo returns -- has
            -- a name, quantities and flags and NO currencyID. Reading one
            -- gave nil for every row, and Currencies.Scan drops any row
            -- without an id, so the character currency store has always been
            -- empty and `/cn currencies` has always said "no currency data
            -- yet". The stub returned fixture tables that did carry the
            -- field, so the suite never saw it.
            --
            -- The id comes from the list LINK. Kept tolerant of a client that
            -- does supply it directly, because being wrong in that direction
            -- costs nothing.
            local currencyID = info.currencyID or CurrencyIDFromList(index)

            table.insert(results, {
                currencyID   = currencyID,
                name         = info.name,
                quantity     = info.quantity or 0,
                maxQuantity  = info.maxQuantity or 0,
                totalEarned  = info.totalEarned or 0,
                quality      = info.quality,
                discovered   = info.discovered ~= false,

                -- Weekly caps are the actionable part: a capped currency is
                -- earning potential being thrown away every week it sits.
                canEarnPerWeek     = info.canEarnPerWeek and true or false,
                earnedThisWeek     = info.quantityEarnedThisWeek or 0,
                maxWeeklyQuantity  = info.maxWeeklyQuantity or 0,

                useTotalEarnedForMaxQty = info.useTotalEarnedForMaxQty and true or false,

                -- Warband currencies. The client flags them and the addon
                -- ignored the flag until 0.43.0, so one capped on your main
                -- was recommended again on every alt.
                -- TRANSFERABLE IS NOT SHARED. 0.63.0.
                --
                -- `isAccountTransferable` means the balance can be MOVED
                -- between characters, for a fee, one deliberate action at a
                -- time. `isAccountWide` means every character sees the same
                -- balance. Treating the first as the second told the ranking
                -- that a currency belonging to exactly one character was
                -- everybody's -- so `Warband.Decorate` short-circuited to
                -- "account-wide" and dropped the character verdict, and the
                -- row printed "(Warband)".
                --
                -- Both are carried, because the second one is worth SAYING --
                -- "you can move this to the character who needs it" is useful
                -- and is not the same sentence.
                accountWide     = info.isAccountWide and true or false,
                transferable    = info.isAccountTransferable and true or false,
            })
        end
    end

    -- Put the headers back the way the player had them.
    if #collapsed > 0 and C_CurrencyInfo.ExpandCurrencyList then
        local wanted = {}

        for _, name in ipairs(collapsed) do
            wanted[name] = true
        end

        local counted, final = pcall(C_CurrencyInfo.GetCurrencyListSize)

        if counted and type(final) == "number" then
            for index = final, 1, -1 do
                local asked, row = pcall(C_CurrencyInfo.GetCurrencyListInfo, index)

                if asked and type(row) == "table" and row.isHeader
                    and row.name and wanted[row.name] then

                    pcall(C_CurrencyInfo.ExpandCurrencyList, index, false)
                end
            end
        end
    end

    return results
end

function Blizzard.GetCurrency(currencyID)
    if not C_CurrencyInfo or not C_CurrencyInfo.GetCurrencyInfo then
        return nil
    end

    local ok, info = pcall(C_CurrencyInfo.GetCurrencyInfo, currencyID)

    if not ok or type(info) ~= "table" then
        return nil
    end

    return info
end

------------------------------------------------------------
-- EXPLORATION
------------------------------------------------------------

-- Blizzard exposes explored overlay textures but never a total, so a raw
-- "percent explored" cannot be computed from the map API. The Exploration
-- achievement category does carry per-subzone criteria, which is the only
-- countable exploration data the client offers.
CN_EXPLORATION_CATEGORY = 97

function Blizzard.GetExplorationAchievements()
    local results = {}

    if not GetCategoryNumAchievements then
        return results
    end

    local total = Blizzard.GetCategoryCounts(CN_EXPLORATION_CATEGORY)

    for index = 1, total do
        local achievement =
            Blizzard.GetAchievementInCategory(CN_EXPLORATION_CATEGORY, index)

        if achievement then
            local done, criteria =
                Blizzard.GetAchievementProgress(achievement.achievementID)

            table.insert(results, {
                achievementID = achievement.achievementID,
                name          = achievement.name,
                completed     = achievement.completed,
                done          = done,
                criteria      = criteria,
            })
        end
    end

    return results
end

-- The unfinished criteria of one achievement, by name. For exploration
-- achievements these are the subzone names still undiscovered.
function Blizzard.GetIncompleteCriteria(achievementID, limit)
    local missing = {}

    if not GetAchievementNumCriteria or not GetAchievementCriteriaInfo then
        return missing
    end

    local total = GetAchievementNumCriteria(achievementID) or 0

    for index = 1, total do
        local ok, description, _, completed =
            pcall(GetAchievementCriteriaInfo, achievementID, index)

        if ok and not completed and description and description ~= "" then
            table.insert(missing, description)

            if limit and #missing >= limit then
                break
            end
        end
    end

    return missing
end

-- Every criterion, with its state, not only the missing ones.
--
-- GetIncompleteCriteria answers "what is left". A chain needs "what is the
-- whole path, and where on it am I" -- the done ones are what make progress
-- legible, and dropping them means the player sees five things left and no
-- sense of whether that is five out of six or five out of fifty.
--
-- `limit` BOUNDS THE LIST, NOT THE COUNT. FIXED IN 0.61.0.
--
-- The loop used to `break` at the limit, so a caller that passed 25 and then
-- counted the returned rows was counting a WINDOW and calling it a total.
-- Chase.lua did exactly that: "Glory of the Dragonflight Raider" has 31
-- criteria, so an achievement 9 of 31 done printed 9/25 -- 36% for something
-- 29% done -- and the moment a player crossed 25 criteria it printed 100%
-- with steps still outstanding. Every meta achievement in the game is past
-- the cap, and metas are precisely what a chase list is for.
--
-- The walk is cheap and bounded by the client (no achievement has more than
-- a few dozen criteria), so it now always completes and the limit is applied
-- only to what is APPENDED. The second return value carries the honest
-- figures.
--
-- Returns: criteria, summary
--   summary = { total = n, completed = c, truncated = bool }
function Blizzard.GetAchievementCriteriaList(achievementID, limit)
    local criteria = {}
    local summary  = { total = 0, completed = 0, truncated = false }

    if not GetAchievementNumCriteria or not GetAchievementCriteriaInfo then
        return criteria, summary
    end

    local count = GetAchievementNumCriteria(achievementID) or 0

    for index = 1, count do
        local ok, description, _, completed, quantity, required =
            pcall(GetAchievementCriteriaInfo, achievementID, index)

        if ok and description and description ~= "" then
            completed = completed and true or false

            summary.total = summary.total + 1

            if completed then
                summary.completed = summary.completed + 1
            end

            if limit and #criteria >= limit then
                summary.truncated = true
            else
                table.insert(criteria, {
                    index       = index,
                    description = description,
                    completed   = completed,
                    quantity    = quantity,
                    required    = required,
                })
            end
        end
    end

    return criteria, summary
end

-- How much standing remains before the next rank, and what that rank is.
--
-- Reputation is one of the few things in the game with a denominator the
-- client will actually vouch for, which is why it gets a real number here
-- while most of this addon refuses to invent one.
function Blizzard.GetReputationRemaining(factionID)
    local data = Blizzard.GetFactionByID(factionID)

    if not data then
        return nil
    end

    local current   = data.currentStanding or data.currentReactionThreshold
    local threshold = data.nextReactionThreshold
    local floor     = data.currentReactionThreshold

    if not current or not threshold or not floor then
        return nil
    end

    local earned = current - floor
    local needed = threshold - floor

    if needed <= 0 then
        return nil
    end

    return {
        earned    = earned,
        needed    = needed,
        remaining = math.max(0, needed - earned),
        standing  = data.reaction,
        name      = data.name,

        -- The rank being worked toward, so a band can be reported as a band
        -- -- "11,999 of 12,000 to Revered" -- rather than as a fraction of a
        -- goal the client will not vouch for.
        nextRankName = data.nextReactionName or data.nextRank,
    }
end

-- Every way the game knows of to obtain an appearance.
--
-- An appearance is not one item. It is a set of sources -- a drop here, a
-- vendor there, a quest reward -- and "which of these can I actually still
-- get" is the question a transmog hunter is asking.
function Blizzard.GetAppearanceSources(appearanceID)
    local sources = {}

    if not C_TransmogCollection or not C_TransmogCollection.GetAppearanceSources then
        return sources
    end

    local ok, results = pcall(C_TransmogCollection.GetAppearanceSources, appearanceID)

    if not ok or type(results) ~= "table" then
        return sources
    end

    for _, source in ipairs(results) do
        table.insert(sources, {
            sourceID    = source.sourceID,
            name        = source.name,
            collected   = source.isCollected and true or false,
            sourceType  = source.sourceType,
            itemID      = source.itemID,
        })
    end

    return sources
end

------------------------------------------------------------
-- MAP TOPOLOGY
------------------------------------------------------------

-- The map you are standing on is not necessarily the map a quest giver is
-- registered against.
--
-- GetBestMapForUnit answers with the most SPECIFIC map containing you, which
-- in a city or a cave is a small child map. Quest starts belonging to the
-- surrounding zone are registered on the PARENT, so a player standing in
-- front of an exclamation mark in a city can be told there is nothing here.
-- Reported from live play, exactly that way.
function Blizzard.GetMapInfo(mapID)
    if not mapID or not C_Map or not C_Map.GetMapInfo then
        return nil
    end

    local ok, info = pcall(C_Map.GetMapInfo, mapID)

    return ok and info or nil
end

-- WHICH ZONE THE PLAYER IS IN, AS AN ID. 0.73.0.
--
-- `GetBestMapForUnit` answers with the most SPECIFIC map containing you: in
-- Dornogal it says Dornogal, in a cave it says the cave. That is the right
-- answer for "where exactly am I" and the wrong one for "which zone is this",
-- and three releases running have used it for the second question:
--
--   0.70.0 matched achievements against `GetMapName(GetBestMapForUnit())`,
--          so nothing matched indoors;
--   0.71.0 matched on `GetZoneText()` and then CACHED under the same wrong
--          id, so the cache never converged and wrote a different value on
--          each side of a doorway;
--   0.72.0 dropped the id entirely and keyed on the zone NAME, which is
--          right for the match and cannot separate Outland's Nagrand from
--          Draenor's -- a distinction `Exploration` documents by name and
--          which had been held, until then, by the id.
--
-- The answer to the actual question is up the parent chain: the first
-- ancestor the client itself calls a zone. `mapType` 3 is Zone; 4 and above
-- are dungeon and micro maps, which is where a capital's interior lives. Two
-- or three hops, no allocation, and unlike a name it cannot be duplicated.
--
-- Falls back to the specific map when the walk finds no zone above it, so a
-- caller always gets the best available identity rather than nothing.
Blizzard.zoneMapType = 3

-- MEMOIZED, BECAUSE THE MAP GRAPH DOES NOT MOVE. 0.74.0.
--
-- Each walk is up to eight `pcall(C_Map.GetMapInfo)` calls and each of those
-- ALLOCATES A TABLE in the client. This is called from the zone lookup, which
-- runs in the `CRITERIA_UPDATE` debounce body, on every candidate-provider
-- rebuild, and from the Journey tab's two-second refresh -- so the same two
-- or three maps were being walked over and over for an answer that is fixed
-- for the life of the client.
--
-- Not cleared on anything: a map's parent is a property of the game's data,
-- not of where the player is standing.
local zoneOf = {}

function Blizzard.ZoneMapID(mapID)
    if not mapID then
        return nil
    end

    local held = zoneOf[mapID]

    if held ~= nil then
        return held
    end

    -- A FALLBACK IS NOT AN ANSWER, AND MUST NOT BE REMEMBERED AS ONE.
    -- 0.75.0.
    --
    -- `ResolveZoneMapID` returns the input unchanged on four paths, one of
    -- which is "the client would not answer" -- `GetMapInfo` returns nil
    -- while `C_Map` is still coming up. 0.74.0 could not tell that apart from
    -- a real result and cached it, "not cleared on anything", so one failed
    -- resolve at a cold moment pinned a building's map to itself for the rest
    -- of the session -- defeating the entire purpose of this function, and
    -- silently filing that room's candidate list under the room.
    local answer, resolved = Blizzard.ResolveZoneMapID(mapID)

    if resolved then
        zoneOf[mapID] = answer
    end

    return answer
end

-- THE INSTANCE ABOVE A MAP, WHICH IS NOT ITS ZONE. 0.81.0.
--
-- `ZoneMapID` walks UP to the first ancestor the client calls a zone, and in
-- a dungeon or raid whose map parents into its outdoor zone -- most modern
-- ones, as `Loremaster.lua` records -- that answer is the zone OUTSIDE the
-- instance. Anything comparing "am I in the same place as that" at zone level
-- therefore says yes to the world quest on the other side of the door.
--
-- This walks the same chain and keeps the LOWEST map the client calls a
-- dungeon or finer (`mapType` above Zone), which is the instance's own
-- identity. Nil when the map is not inside an instance at all, so an outdoor
-- objective can never compare equal to one that is.
--
-- Memoised in the same table shape and for the same reason as `ZoneMapID`:
-- the map graph is game data and does not move.
local instanceOf = {}

function Blizzard.InstanceMapID(mapID)
    if not mapID then
        return nil
    end

    local held = instanceOf[mapID]

    if held ~= nil then
        return held or nil
    end

    local current, found, guard = mapID, nil, 0

    while current and guard < 8 do
        local info = Blizzard.GetMapInfo(current)

        -- A REFUSAL IS NOT AN ANSWER, AND IS NOT REMEMBERED AS ONE -- the
        -- same cold-client trap `ZoneMapID` documents above.
        if not info then
            return nil
        end

        if (info.mapType or 0) > Blizzard.zoneMapType then
            found = current
        else
            break
        end

        local parentID = info.parentMapID

        if not parentID or parentID <= 0 then
            break
        end

        current = parentID
        guard   = guard + 1
    end

    instanceOf[mapID] = found or false

    return found
end

function Blizzard.ResolveZoneMapID(mapID)
    local current = mapID
    local guard   = 0

    while current and guard < 8 do
        local info = Blizzard.GetMapInfo(current)

        -- The one path that is a REFUSAL rather than a result: the client
        -- had nothing to say. Everything else below is a real answer about
        -- the map graph and is worth keeping.
        if not info then
            return mapID, false
        end

        if (info.mapType or 0) == Blizzard.zoneMapType then
            return current, true
        end

        -- Above a zone: a continent or the world. The specific map is the
        -- closest thing to a zone identity there is.
        if (info.mapType or 0) < Blizzard.zoneMapType then
            return mapID, true
        end

        local parentID = info.parentMapID

        if not parentID or parentID <= 0 then
            return mapID, true
        end

        current = parentID
        guard   = guard + 1
    end

    return mapID, true
end

function Blizzard.GetMapChildren(mapID)
    if not mapID or not C_Map or not C_Map.GetMapChildrenInfo then
        return {}
    end

    local ok, children = pcall(C_Map.GetMapChildrenInfo, mapID)

    if not ok or type(children) ~= "table" then
        return {}
    end

    return children
end

-- Every map worth asking about when the question is "what is around me":
-- the map itself, its parent, and the parent's other children. Ordered
-- nearest-first and deduplicated.
function Blizzard.RelatedMapIDs(mapID)
    local ordered, seen = {}, {}

    local function add(id)
        if id and not seen[id] then
            seen[id] = true
            table.insert(ordered, id)
        end
    end

    add(mapID)

    local info = Blizzard.GetMapInfo(mapID)

    local parentID = info and info.parentMapID

    -- A continent or world map has thousands of descendants; walking those
    -- would be a scan, not a lookup. Zone and below only.
    if parentID and parentID > 0 then
        local parent = Blizzard.GetMapInfo(parentID)

        -- 3 = zone, 4 = dungeon/micro. Anything broader is a continent.
        if parent and (parent.mapType or 0) >= 3 then
            add(parentID)

            for _, child in ipairs(Blizzard.GetMapChildren(parentID)) do
                add(child.mapID)
            end
        end
    end

    for _, child in ipairs(Blizzard.GetMapChildren(mapID)) do
        add(child.mapID)
    end

    return ordered
end

------------------------------------------------------------
-- QUEST COMPLETION HISTORY
------------------------------------------------------------

-- Every quest this character has ever completed.
--
-- This is a real number the client will vouch for, unlike anything the addon
-- counts about itself, and it is the number a player who has done three
-- hundred quests in a weekend actually wants to see.
function Blizzard.GetAllCompletedQuestIDs()
    if not C_QuestLog or not C_QuestLog.GetAllCompletedQuestIDs then
        return nil
    end

    local ok, ids = pcall(C_QuestLog.GetAllCompletedQuestIDs)

    -- AN EMPTY LIST EARLY IN A LOGIN IS "NOT YET", NOT "NONE". 0.62.0.
    --
    -- The client returns an EMPTY TABLE, not nil, before it has finished
    -- loading quest data. This accepted any table, so `Progress.BeginSession`
    -- snapshotted a lifetime baseline of zero at `PLAYER_LOGIN`, and when the
    -- real list arrived every quest the character had ever completed counted
    -- as done "this session": `/cn progress` printed "This session: 34,812"
    -- and a per-hour rate derived from it.
    --
    -- The nil path was handled and the empty-table path was not, which is the
    -- same shape as the map that was always square: the case the fixture
    -- could not express.
    --
    -- Zero completed quests is a real state for a brand-new character, so it
    -- is not an error -- it is UNKNOWN until the client says something. The
    -- caller re-asks; nothing here has to guess.
    if ok and type(ids) == "table" and #ids > 0 then
        return ids
    end

    return nil
end

-- Quests offered by the NPC currently being spoken to.
--
-- The most reliable "there is a quest right here" signal there is: the player
-- is standing in the conversation. Map data can be missing or registered
-- against a map we did not think to ask about; this cannot be wrong.
function Blizzard.GetGossipAvailableQuests()
    local offered = {}

    if not C_GossipInfo then
        return offered
    end

    local sources = {}

    if C_GossipInfo.GetAvailableQuests then
        table.insert(sources, C_GossipInfo.GetAvailableQuests)
    end

    for _, source in ipairs(sources) do
        local ok, quests = pcall(source)

        if ok and type(quests) == "table" then
            for _, quest in ipairs(quests) do
                if type(quest) == "table" and quest.questID then
                    table.insert(offered, {
                        questID   = quest.questID,
                        title     = quest.title,
                        isDaily   = quest.frequency == 2 or quest.isDaily,
                        isRepeatable = quest.repeatable and true or false,
                    })
                end
            end
        end
    end

    return offered
end

-- Quests the questgiver window is offering right now (the non-gossip case:
-- an NPC with a single quest opens the detail frame directly).
function Blizzard.GetActiveQuestOffer()
    if not GetQuestID then
        return nil
    end

    local ok, questID = pcall(GetQuestID)

    if ok and questID and questID > 0 then
        return questID
    end

    return nil
end

-- Bonus objectives and world quests keyed to a map. These are "available"
-- in every sense a player means, and they are not quest starts.
function Blizzard.GetTaskQuestsOnMap(uiMapID)
    local tasks = {}

    if not uiMapID or not C_TaskQuest or not C_TaskQuest.GetQuestsForPlayerByMapID then
        return tasks
    end

    local ok, results = pcall(C_TaskQuest.GetQuestsForPlayerByMapID, uiMapID)

    if not ok or type(results) ~= "table" then
        return tasks
    end

    for _, task in ipairs(results) do
        if type(task) == "table" and task.questId then
            table.insert(tasks, {
                questID = task.questId,
                x       = task.x,
                y       = task.y,
                mapID   = task.mapID or uiMapID,
                inProgress = task.inProgress and true or false,
            })
        end
    end

    return tasks
end

------------------------------------------------------------
-- CAMPAIGNS
------------------------------------------------------------

-- The main story, as distinct from everything else.
--
-- A player working through an expansion says "the story" and "the side
-- quests" and means two genuinely different things; the client knows which
-- is which and the addon should stop pretending they are one pile.
function Blizzard.GetCampaignID(questID)
    if not questID or not C_CampaignInfo or not C_CampaignInfo.GetCampaignID then
        return nil
    end

    local ok, campaignID = pcall(C_CampaignInfo.GetCampaignID, questID)

    if ok and campaignID and campaignID > 0 then
        return campaignID
    end

    return nil
end

function Blizzard.GetCampaignInfo(campaignID)
    if not campaignID or not C_CampaignInfo or not C_CampaignInfo.GetCampaignInfo then
        return nil
    end

    local ok, info = pcall(C_CampaignInfo.GetCampaignInfo, campaignID)

    return ok and info or nil
end

function Blizzard.GetCampaignChapters(campaignID)
    if not campaignID or not C_CampaignInfo or not C_CampaignInfo.GetChapterIDs then
        return {}
    end

    local ok, chapters = pcall(C_CampaignInfo.GetChapterIDs, campaignID)

    return (ok and type(chapters) == "table") and chapters or {}
end

function Blizzard.IsQuestCampaign(questID)
    return Blizzard.GetCampaignID(questID) ~= nil
end

------------------------------------------------------------
-- MERCHANTS
------------------------------------------------------------

-- Vendor inventories are only readable while the merchant window is open,
-- exactly like trade skill recipes. Everything here is opportunistic.
function Blizzard.GetMerchantItems()
    local items = {}

    if not GetMerchantNumItems then
        return items
    end

    local ok, count = pcall(GetMerchantNumItems)

    if not ok or type(count) ~= "number" then
        return items
    end

    for index = 1, count do
        local gotInfo, name, texture, price, quantity, numAvailable,
              isPurchasable, isUsable, extendedCost =
              pcall(GetMerchantItemInfo, index)

        if gotInfo and name then
            local itemID

            if C_MerchantFrame and C_MerchantFrame.GetItemInfo then
                local gotItem, info = pcall(C_MerchantFrame.GetItemInfo, index)

                if gotItem and type(info) == "table" then
                    itemID = info.itemID
                end
            end

            if not itemID and GetMerchantItemLink then
                local gotLink, link = pcall(GetMerchantItemLink, index)

                if gotLink and type(link) == "string" then
                    itemID = tonumber(link:match("item:(%d+)"))
                end
            end

            table.insert(items, {
                index         = index,
                itemID        = itemID,
                name          = name,
                price         = price,
                available     = numAvailable,
                isPurchasable = isPurchasable and true or false,
                extendedCost  = extendedCost and true or false,
            })
        end
    end

    return items
end

-- The creature ID behind any unit token. The GUID carries it, and it is the
-- only stable identifier for an NPC.
function Blizzard.GetUnitNPCID(unit)
    if not unit or not UnitExists or not UnitExists(unit) then
        return nil, nil
    end

    local name = UnitName and UnitName(unit) or nil

    local guid = UnitGUID and UnitGUID(unit)

    if not guid then
        return nil, name
    end

    -- GUID form: Creature-0-serverID-instanceID-zoneUID-npcID-spawnUID
    --
    -- The extra parentheses matter: select(6, ...) returns every value from
    -- position 6 onward, so without them tonumber receives the spawn UID as
    -- its `base` argument and throws.
    local npcID = tonumber((select(6, strsplit("-", guid))))

    return npcID, name
end

-- The NPC currently being interacted with.
function Blizzard.GetInteractingNPC()
    return Blizzard.GetUnitNPCID("npc")
end

------------------------------------------------------------
-- ITEM IDENTITY
------------------------------------------------------------

-- Items that teach a collectible do not announce themselves as such; each
-- collection API has its own item lookup. All three are optional and all
-- three have changed shape before, so each is probed rather than assumed.

function Blizzard.GetMountFromItem(itemID)
    if not itemID or not C_MountJournal or not C_MountJournal.GetMountFromItem then
        return nil
    end

    return C_MountJournal.GetMountFromItem(itemID)
end

function Blizzard.GetPetSpeciesFromItem(itemID)
    if not itemID or not C_PetJournal or not C_PetJournal.GetPetInfoByItemID then
        return nil, nil
    end

    -- ELEVEN RETURNS, AND NONE OF THEM IS A SPECIES ID. 0.86.0.
    --
    -- This unpacked thirteen values and read the thirteenth as a species id,
    -- with the fourth -- the COMPANION id -- as a fallback "in case the
    -- position moved". `C_PetJournal.GetPetInfoByItemID` returns exactly the
    -- eleven-field pet-info tail: name, icon, petType, companionID, source,
    -- description, isWild, canBattle, isTradeable, isUnique, obtainable.
    -- That is the same tail `Blizzard.GetPetByIndex` unpacks from position 8
    -- of `GetPetInfoByIndex` -- a call that lists `speciesID` and
    -- `companionID` as DIFFERENT fields, in this addon's own code.
    --
    -- So the species id was nil on every client and the live half of the
    -- fallback was a companion id, looked up in a store keyed by species.
    -- Every caged pet in a bag missed: no `/cn bags` row, no candidate, no
    -- tooltip line -- the headline example in `Inventory.lua`'s own header.
    --
    -- The offline stub returned thirteen values with an invented species id
    -- at the end, so the only path that can run in game had never once been
    -- executed by a test.
    --
    -- The NAME is the one species fact this call really hands back, and the
    -- module that owns the store already resolves a species from one.
    local name = C_PetJournal.GetPetInfoByItemID(itemID)

    if type(name) ~= "string" or name == "" then
        return nil, nil
    end

    local pets = CN:GetModule("Pets")

    -- AN EXACT MATCH, NOT A SEARCH. See `Pets.SpeciesByName`: this is called
    -- from every item tooltip and from the bag sweep, and `Pets.Resolve` is
    -- a substring scan over the whole journal.
    return pets and pets.SpeciesByName and pets.SpeciesByName(name) or nil,
        name
end

-- Returns true/false only for items that actually have an appearance, and nil
-- for everything else.
--
-- The gate matters. PlayerHasTransmogByItemInfo answers false for a stack of
-- ore just as readily as for an unlearned tabard, so using it alone would
-- stamp "appearance not yet known" on every trade good in the game.
function Blizzard.HasTransmogByItem(itemID)
    if not itemID or not C_TransmogCollection then
        return nil
    end

    if not C_TransmogCollection.GetItemInfo then
        return nil
    end

    local ok, appearanceID = pcall(C_TransmogCollection.GetItemInfo, itemID)

    if not ok or not appearanceID then
        return nil
    end

    if C_TransmogCollection.PlayerHasTransmogByItemInfo then
        local hasOk, has = pcall(C_TransmogCollection.PlayerHasTransmogByItemInfo, itemID)

        if hasOk then
            return has and true or false
        end
    end

    return nil
end

function Blizzard.GetItemName(itemID)
    if not itemID then
        return nil
    end

    if C_Item and C_Item.GetItemNameByID then
        return C_Item.GetItemNameByID(itemID)
    end

    if GetItemInfo then
        return (GetItemInfo(itemID))
    end

    return nil
end

------------------------------------------------------------
-- SAVED INSTANCES
------------------------------------------------------------

-- What you are locked to this week, straight from the client.
--
-- NEVER PERSISTED. A lockout is a fact with an expiry on it, the client
-- always knows it, and a stale copy on disk would be worse than no copy at
-- all: "you have 6 of 8 bosses down in there" is actively harmful advice
-- after the reset it did not know about.
--
-- Returns an array of:
--   { name, id, reset, difficultyID, difficulty, defeated, encounters,
--     locked, extended, raid }
function Blizzard.GetSavedInstances()
    local results = {}

    if not GetNumSavedInstances or not GetSavedInstanceInfo then
        return results
    end

    local ok, count = pcall(GetNumSavedInstances)

    if not ok or not count then
        return results
    end

    for index = 1, count do
        -- POSITION 11 IS THE TOTAL AND 12 IS THE PROGRESS, NOT THE REVERSE.
        --
        -- The client returns ... difficultyName, numEncounters,
        -- encounterProgress. This read them the other way round, so a raid
        -- with six of eight bosses down came back as defeated=8, encounters=6
        -- -- which made `remaining` clamp to zero, `complete` true, and the
        -- provider return NOTHING. The Instances module's whole stated purpose
        -- is that a part-finished lockout is the cheapest progress in the
        -- game, and it has never once produced a candidate.
        --
        -- The stub had the same belief written into its fixture comment, so
        -- the suite agreed. Eighth time in this project that a stub and the
        -- code shared one wrong assumption.
        -- TWO DIFFERENT ID SPACES, AND THE ADDON USED THE WRONG ONE.
        --
        -- Return #2 is the LOCKOUT id -- a large opaque save identifier. The
        -- Encounter Journal's instance id is return #14. The addon stored #2
        -- as `id` and then handed it to `EJ_SelectInstance` and
        -- `EJ_GetEncounterInfoByIndex`, which have never heard of it: in game
        -- the boss list came back empty on the first iteration and
        -- `RemainingBosses` always answered "the Adventure Guide has no boss
        -- list for this instance".
        --
        -- The fixture put Encounter Journal instance ids in slot 2, so the
        -- stub and the code shared one wrong belief and the self-test asserted
        -- against it. Ninth time in this project.
        --
        -- Both are kept now, under names that say which is which, and the
        -- journal is asked with the journal's id.
        local gotInfo, name, lockoutID, reset, difficultyID, locked, extended,
            _, isRaid, _, difficultyName, encounters, defeated, _,
            journalInstanceID =
                pcall(GetSavedInstanceInfo, index)

        if gotInfo and name then
            table.insert(results, {
                name         = name,
                id           = lockoutID,
                instanceID   = journalInstanceID,
                reset        = reset,
                difficultyID = difficultyID,
                difficulty   = difficultyName,
                locked       = locked and true or false,
                extended     = extended and true or false,
                raid         = isRaid and true or false,
                defeated     = defeated or 0,
                encounters   = encounters or 0,
            })
        end
    end

    return results
end

------------------------------------------------------------
-- THE ENCOUNTER JOURNAL
------------------------------------------------------------

-- READING THIS API CHANGES WHAT THE PLAYER IS LOOKING AT.
--
-- EJ_SelectInstance and EJ_SelectEncounter are not queries. They set the
-- journal's current selection, which is the same selection the Adventure
-- Guide window is displaying. Scanning it while that window is open would
-- move the player's view out from under them -- an addon reaching into the
-- interface and changing what somebody is reading, which is exactly the kind
-- of thing this addon does not do.
--
-- So: refuse while the journal is visible, and put the selection back
-- afterwards when it is not.
function Blizzard.HasEncounterJournal()
    return EJ_SelectInstance ~= nil
        and EJ_GetEncounterInfoByIndex ~= nil
        and EJ_GetInstanceInfo ~= nil
end

function Blizzard.IsEncounterJournalOpen()
    return EncounterJournal ~= nil
        and EncounterJournal.IsShown ~= nil
        and EncounterJournal:IsShown() and true or false
end

local function WithJournal(work)
    if not Blizzard.HasEncounterJournal() then
        return nil, "the Adventure Guide is not available"
    end

    if Blizzard.IsEncounterJournalOpen() then
        return nil, "the Adventure Guide is open" .. CN.DASH .. "close it and try again"
    end

    local restoreInstance

    if EJ_GetCurrentInstance then
        local gotCurrent, current = pcall(EJ_GetCurrentInstance)

        if gotCurrent then
            restoreInstance = current
        end
    end

    local ok, result = pcall(work)

    -- Put it back even when the work threw, or the player's next visit to
    -- the Adventure Guide opens on whatever this addon was reading last.
    --
    -- AND "NOTHING WAS SELECTED" IS A STATE TO RESTORE.
    --
    -- The restore was guarded on `restoreInstance`, and
    -- `EJ_GetCurrentInstance` returns nil whenever the player has not opened
    -- the Adventure Guide this session -- which is the ordinary case, since
    -- this function refuses to run at all while the window is up. So on
    -- virtually every real invocation nothing was restored and the player's
    -- next visit opened on whatever this addon read last: exactly the outcome
    -- the comment above says it exists to prevent.
    if restoreInstance then
        if EJ_SelectInstance then
            pcall(EJ_SelectInstance, restoreInstance)
        end
    elseif EJ_ClearSearch then
        -- Nothing was selected before, so nothing should be selected after.
        -- Clearing the search is the only lever the client offers for that,
        -- and it also drops the search string this addon may have set.
        pcall(EJ_ClearSearch)
    end

    if not ok then
        return nil, tostring(result)
    end

    return result
end

Blizzard.WithEncounterJournal = WithJournal

-- Bosses in an instance, in the order the journal lists them:
--   { encounterID, name, order }
function Blizzard.GetInstanceEncounters(instanceID)
    if not instanceID then
        return {}
    end

    local encounters = WithJournal(function()
        EJ_SelectInstance(instanceID)

        local list = {}

        local index = 1

        while true do
            local name, _, encounterID = EJ_GetEncounterInfoByIndex(index, instanceID)

            if not name then
                break
            end

            table.insert(list, {
                encounterID = encounterID,
                name        = name,
                order       = index,
            })

            index = index + 1

            -- No instance in the game has anything like this many bosses.
            -- The guard is against an API that returns a name forever.
            if index > 40 then
                break
            end
        end

        return list
    end)

    return encounters or {}
end

-- Where does this drop?
--
-- Uses the journal's own search rather than building a reverse index of every
-- item in the game. An index would be tens of thousands of rows to answer a
-- question the player asks a handful of times a session, and it would be
-- stale the day a patch changed a loot table. The search is what the
-- Adventure Guide itself uses.
--
-- Returns an array of { instanceID, instance, encounterID, encounter }.
function Blizzard.SearchEncounterJournal(text, limit)
    if not text or text == "" then
        return {}
    end

    if not EJ_SetSearch or not EJ_GetSearchResult or not EJ_GetNumSearchResults then
        return {}
    end

    limit = limit or 8

    local results = WithJournal(function()
        EJ_SetSearch(text)

        local found = {}

        -- THE SEARCH IS ASYNCHRONOUS.
        --
        -- `EJ_SEARCH_RESULT_UPDATE` exists because `EJ_SetSearch` does not
        -- finish before it returns; Blizzard's own Encounter Journal listens
        -- for it. Read in the same frame, `EJ_GetNumSearchResults` answers
        -- zero on a cold search. The caller then memoised that zero for the
        -- session, so a second query after the results arrived still got
        -- nothing back.
        --
        -- There is no synchronous form to switch to, so the fix is on the
        -- caching side: a zero here is "not yet", not "nothing", and is
        -- reported as such rather than remembered. The stub answered
        -- synchronously, so no test could reach this.
        local total = EJ_GetNumSearchResults() or 0

        for index = 1, math.min(total, limit) do
            local id, stype, _, _, _, instanceID = EJ_GetSearchResult(index)

            -- Type 1 is an encounter in every build that has exposed this.
            if stype == 1 and id then
                local instanceName

                if instanceID and EJ_GetInstanceInfo then
                    instanceName = EJ_GetInstanceInfo(instanceID)
                end

                local encounterName = EJ_GetEncounterInfo and EJ_GetEncounterInfo(id)

                -- The journal's current difficulty, where the build exposes
                -- it. Reported rather than assumed: a nil here means the
                -- client did not say, which is different from "any".
                local difficulty

                if EJ_GetDifficulty and GetDifficultyInfo then
                    local gotDifficulty, difficultyID = pcall(EJ_GetDifficulty)

                    if gotDifficulty and difficultyID then
                        local gotName, name = pcall(GetDifficultyInfo, difficultyID)

                        if gotName then
                            difficulty = name
                        end
                    end
                end

                table.insert(found, {
                    encounterID = id,
                    encounter   = encounterName,
                    instanceID  = instanceID,
                    instance    = instanceName,
                    difficulty  = difficulty,
                })
            end
        end

        if EJ_ClearSearch then
            EJ_ClearSearch()
        end

        return found
    end)

    return results or {}
end

function Blizzard.GetInstanceName(instanceID)
    if not instanceID or not EJ_GetInstanceInfo then
        return nil
    end

    local ok, name = pcall(EJ_GetInstanceInfo, instanceID)

    return ok and name or nil
end
'@

$Embedded['Providers\StaticData.lua'] = @'
-- Providers/StaticData.lua
-- Completion Navigator :: access layer for the curated static database.
--
-- Data/*.lua files call CN.Static.Register* to contribute rows. Nothing
-- reads those tables directly; everything goes through the accessors here
-- so the storage shape can change without touching consumers.

local ADDON_NAME, CN = ...

local Static = {}

CN.Static = Static

Static.quests    = {}
Static.recipes   = {}
Static.vendors   = {}
Static.rares     = {}
Static.treasures = {}

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

-- record = { name =, mapID =, x =, y =, expansion =, requires = {}, unlocks = {} }
function Static.RegisterQuest(questID, record)
    if not questID or type(record) ~= "table" then
        return
    end

    Static.quests[questID] = record
end

function Static.RegisterQuests(records)
    for questID, record in pairs(records) do
        Static.RegisterQuest(questID, record)
    end
end

function Static.RegisterRecipe(itemID, record)
    Static.recipes[itemID] = record
end

function Static.RegisterVendor(npcID, record)
    Static.vendors[npcID] = record
end

function Static.RegisterRare(npcID, record)
    Static.rares[npcID] = record
end

function Static.RegisterTreasure(id, record)
    Static.treasures[id] = record
end

------------------------------------------------------------
-- ACCESS
------------------------------------------------------------

-- CONTRIBUTED CHAINS.
--
-- Held apart from the curated table so that the difference between "checked"
-- and "widely observed" survives being written to disk, and so /cn why can
-- say which one it is quoting.
Static.community = Static.community or {}

function Static.RegisterCommunity(records)
    if type(records) ~= "table" then
        return 0
    end

    local added = 0

    for questID, record in pairs(records) do
        if type(record) == "table" and type(record.requires) == "table" then
            Static.community[questID] = record

            added = added + 1
        end
    end

    return added
end

function Static.GetCommunity(questID)
    return Static.community[questID]
end

function Static.CommunityCount()
    local count = 0

    for _ in pairs(Static.community) do
        count = count + 1
    end

    return count
end

function Static.GetQuest(questID)
    return Static.quests[questID]
end

-- ELIGIBILITY, from curated data.
--
-- The client only draws quest pins the character qualifies for, so gating is
-- normally handled by simply not seeing it. That is fine while the player is
-- standing there and useless the moment they ask "why can nobody in my
-- Warband do this?" -- which is exactly what /cn why and /cn alts are for.
--
-- Returns eligible, reason. A record with no gating fields is eligible, and
-- says so with a nil reason rather than an empty claim.
function Static.QuestEligibility(questID, character)
    local record = Static.quests[questID]

    if not record then
        return true, nil
    end

    character = character or CN.character or {}

    -- THE REASON AS A TOKEN, AS WELL AS AS A SENTENCE. 0.64.0.
    --
    -- The caller in Quests.lua recovered WHY a quest was blocked by
    -- pattern-matching this English prose -- `find("^race")`,
    -- `find("Alliance")`. Since 0.61.0 the class and race lists in that
    -- sentence are run through the client's LOCALIZED names, so the string is
    -- already half-translated and the parser survives only because the label
    -- prefixes happen to still be English.
    --
    -- The reason is known here, exactly, at the moment the sentence is built.
    -- Throwing it away and reconstructing it from the display text is the
    -- "branch on a localized string" rule broken by a longer road: the first
    -- translation of "race only" would silently reclassify every race-gated
    -- quest as class-gated, and `/cn alts` would name the wrong alt.
    --
    -- Third return: a stable token. The sentence is unchanged.
    if record.faction and character.faction
        and record.faction ~= character.faction then

        -- THE FACTION HELPER, NOT THE CLASS ONE. 0.82.0.
        --
        -- `CN.TokenLabel` resolves class and race tokens and knows nothing
        -- about factions, so it fell through to its title-caser and printed
        -- the English token. `CN.FactionLabel` is backed by the client's own
        -- `FACTION_ALLIANCE`/`FACTION_HORDE` globals and was added for the
        -- Warband roster, then extended to `Modules/Mounts.lua` under a note
        -- saying that file "was not converted". This is the third place, and
        -- it was not converted either -- so a German client read "Alliance
        -- only" three lines under a correctly translated class list.
        return false, CN.FactionLabel(record.faction) .. " only", "FACTION"
    end

    if record.minLevel and character.level
        and character.level < record.minLevel then

        return false, "level " .. record.minLevel .. " required", "LEVEL"
    end

    local function allowed(list, value, label)
        if type(list) ~= "table" or #list == 0 or not value then
            return true
        end

        for _, entry in ipairs(list) do
            if entry == value then
                return true
            end
        end

        -- "class only: WARRIOR, PALADIN" IS A DATABASE ROW, NOT A SENTENCE.
        -- 0.61.0.
        --
        -- These are the client's uppercase tokens, and they went straight
        -- onto the player's screen. The client already holds the localized
        -- names for exactly these tokens; using them costs one table lookup
        -- and turns the line into something a player reads rather than
        -- decodes.
        local words = {}

        for _, entry in ipairs(list) do
            table.insert(words, CN.TokenLabel(entry))
        end

        return false, label .. " only: " .. CN.Series(words)
    end

    local okClass, classReason = allowed(record.classes, character.class, "class")

    if not okClass then
        return false, classReason, "CLASS"
    end

    local okRace, raceReason = allowed(record.races, character.race, "race")

    if not okRace then
        return false, raceReason, "RACE"
    end

    return true, nil, nil
end

-- Where a quest is HANDED IN, which is not where it is picked up and is not
-- what the client's moving "next waypoint" reports once you are part-way
-- through it.
function Static.GetQuestTurnIn(questID)
    local record = Static.quests[questID]

    if not record or not record.turnInMapID then
        return nil
    end

    return record.turnInMapID, record.turnInX, record.turnInY
end

function Static.GetQuestName(questID)
    local record = Static.quests[questID]

    return record and record.name or nil
end

function Static.GetQuestLocation(questID)
    local record = Static.quests[questID]

    if not record then
        return nil, nil, nil
    end

    return record.mapID, record.x, record.y
end

function Static.Count()
    return CN.CountKeys(Static.quests),
           CN.CountKeys(Static.recipes),
           CN.CountKeys(Static.vendors),
           CN.CountKeys(Static.rares),
           CN.CountKeys(Static.treasures)
end
'@

$Embedded['Providers\TomTom.lua'] = @'
-- Providers/TomTom.lua
-- Completion Navigator :: TomTom waypoint provider.
--
-- TomTom stays the navigation engine. Completion Navigator only decides
-- which waypoint is worth setting.

local ADDON_NAME, CN = ...

local provider = {}

local active = {}

function provider.IsAvailable()
    return _G.TomTom ~= nil and _G.TomTom.AddWaypoint ~= nil
end

-- Returns `placed, why` -- and `why` is a SENTENCE FOR THE PLAYER in both
-- directions, never a handle. 0.79.0.
--
-- This used to return the uid on success, and the native provider returns a
-- caveat ("the arrow is set; the game does not allow a map pin here"). One
-- position, two meanings -- and 0.78.0 started PRINTING the second return on
-- success, so every `/cn go` for a TomTom user printed `table: 0x...` under
-- the headline. It reads as a crash.
--
-- The uid is already tracked in `active`, which is what `ClearAll` walks, so
-- returning it was giving the caller something it had no use for.
function provider.SetWaypoint(mapID, x, y, title)
    if not provider.IsAvailable() then
        return false, "TomTom is not loaded"
    end

    local uid = _G.TomTom:AddWaypoint(mapID, x, y, {
        title       = title or "Completion Navigator",
        persistent  = false,
        minimap     = true,
        world       = true,
        crazy       = true,
    })

    if not uid then
        return false, "TomTom refused the waypoint"
    end

    table.insert(active, uid)

    return true
end

function provider.ClearAll()
    if not provider.IsAvailable() then
        return false
    end

    local removed = #active

    for _, uid in ipairs(active) do
        pcall(_G.TomTom.RemoveWaypoint, _G.TomTom, uid)
    end

    active = {}

    return removed > 0
end

CN.RegisterWaypointProvider("TomTom", provider, 10)

------------------------------------------------------------
-- BLIZZARD MAP PIN FALLBACK
------------------------------------------------------------

local blizzardProvider = {}

function blizzardProvider.IsAvailable()
    return C_Map ~= nil and C_Map.SetUserWaypoint ~= nil
end

-- WHETHER THIS ACTUALLY WORKED IS NOW REPORTED.
--
-- This returned nothing at all, and every early return was silent -- so
-- `CN.SetWaypoint` discarded the result, returned `true` unconditionally, and
-- `/cn go` printed "Waypoint set: <name>" whether or not a pin appeared.
--
-- And the client refuses more often than the addon assumed. User waypoints
-- cannot be placed on dungeon and raid maps, on the cosmic and continent
-- maps, or on several instanced maps -- `C_Map.CanSetUserWaypointOnMap`
-- exists to say so and was called nowhere in this addon. In every one of
-- those cases the player was told a waypoint had been set and then sent to
-- look for an arrow that was never there.
function blizzardProvider.SetWaypoint(mapID, x, y)
    if not blizzardProvider.IsAvailable() then
        return false
    end

    if C_Map.CanSetUserWaypointOnMap then
        local asked, allowed = pcall(C_Map.CanSetUserWaypointOnMap, mapID)

        if asked and not allowed then
            return false, "the game does not allow a waypoint on this map"
        end
    end

    local point = UiMapPoint and UiMapPoint.CreateFromCoordinates(mapID, x, y)

    if not point then
        return false, "the client would not build a map point"
    end

    -- Guarded, as the identical call in Navigation.lua already was. Same API,
    -- and it was pcall'd in one place and bare in the other.
    local placed = pcall(C_Map.SetUserWaypoint, point)

    if not placed then
        return false, "the client refused the waypoint"
    end

    -- WHOSE PIN THIS IS.
    --
    -- There is exactly one user waypoint, and it belongs to the player unless
    -- this addon put it there. Remembering that is what lets ClearAll below
    -- refuse to delete a pin somebody placed by hand.
    blizzardProvider.owned = { mapID = mapID, x = x, y = y }

    if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
        C_SuperTrack.SetSuperTrackedUserWaypoint(true)
    end

    return true
end

function blizzardProvider.ClearAll()
    if not C_Map or not C_Map.ClearUserWaypoint then
        return false
    end

    -- ONLY IF IT IS OURS.
    --
    -- `ClearUserWaypoint` removes THE user waypoint -- there is one, and it
    -- is the player's. `/cn clearway`, stopping follow mode and every
    -- provider switch called it unconditionally, so an addon whose standing
    -- rule is that it does not act deleted a pin the player had placed by
    -- hand. The TomTom provider next door has always done this correctly: it
    -- tracks the UIDs it created and removes only those.
    if not blizzardProvider.owned then
        return false
    end

    -- And only if it is still the one we set. A player who has moved the pin
    -- since owns it again.
    if C_Map.GetUserWaypoint then
        local asked, current = pcall(C_Map.GetUserWaypoint)

        if asked and current then
            -- THE MAP WAS THE WHOLE COMPARISON, AND IT IS THE PART THAT
            -- DOES NOT CHANGE. FIXED IN 0.61.0.
            --
            -- The comment above says "a player who has moved the pin since
            -- owns it again" -- and then the code checked only the map id.
            -- Moving a pin almost always leaves it on the SAME map: that is
            -- what moving a pin means. So the one case this guard exists for
            -- was the one case it could not detect, and `/cn clearway` went
            -- on deleting a hand-placed pin in the zone the player was
            -- standing in. It caught only the case where the player had
            -- placed a pin in a different zone entirely, which is rare and
            -- which the map-id check would have caught by accident.
            --
            -- The coordinates are compared with a tolerance because the
            -- client round-trips them through its own packing and hands back
            -- values that differ in the last few digits. A hundredth of a map
            -- unit is well inside "the player did not move this" and well
            -- outside any deliberate drag.
            local owned = blizzardProvider.owned

            local sameMap = current.uiMapID == owned.mapID

            local samePlace = sameMap
                and owned.x and owned.y
                and current.position
                and math.abs((current.position.x or -1) - owned.x) < 0.01
                and math.abs((current.position.y or -1) - owned.y) < 0.01

            -- No position from the client is not evidence the pin moved, so
            -- the map check stands alone in that case rather than the
            -- addon refusing to clean up after itself forever.
            if current.position and not samePlace then
                blizzardProvider.owned = nil

                return false
            end

            if not sameMap then
                blizzardProvider.owned = nil

                return false
            end
        end
    end

    pcall(C_Map.ClearUserWaypoint)

    blizzardProvider.owned = nil

    return true
end

CN.RegisterWaypointProvider("Blizzard", blizzardProvider, 20)
'@

$Embedded['Providers\ATT.lua'] = @'
-- Providers/ATT.lua
-- Completion Navigator :: AllTheThings interoperability.
--
-- ATT is the largest completion data corpus in the ecosystem. Duplicating it
-- would be pointless and rude; reading it when the player already has it
-- installed is the right relationship. Completion Navigator stays the
-- decision layer.
--
-- IMPORTANT: third-party addon APIs are not stable and are not documented as
-- public contracts. Every entry point below is probed at runtime and wrapped
-- in pcall. If ATT changes shape, this provider reports itself unavailable
-- and the addon carries on with its own data. It must never take the addon
-- down with it.
--
-- Run /cn providers in game to see exactly which entry points resolved.

local ADDON_NAME, CN = ...

local ATT = {}

CN.ATT = ATT

-- Candidate globals, newest naming first.
local GLOBALS = { "AllTheThings", "ATTC", "ATT" }

local resolved   = nil
local probeNotes = {}

local function Root()
    if resolved then
        return resolved
    end

    for _, name in ipairs(GLOBALS) do
        local candidate = _G[name]

        if type(candidate) == "table" then
            resolved = candidate

            table.insert(probeNotes, "global: " .. name)

            return resolved
        end
    end

    return nil
end

function ATT.IsAvailable()
    return Root() ~= nil
end

------------------------------------------------------------
-- SEARCH
------------------------------------------------------------

-- ATT's field search is the one entry point that has survived several
-- rewrites. It returns an array of "groups" describing everything ATT knows
-- about that ID.
local function Search(field, id)
    local root = Root()

    if not root or not id then
        return nil
    end

    local search = root.SearchForField or root.SearchForFieldContainer

    if type(search) ~= "function" then
        return nil
    end

    local ok, results = pcall(search, field, id)

    if not ok or type(results) ~= "table" then
        return nil
    end

    return results
end

ATT.Search = Search

------------------------------------------------------------
-- QUEST DATA
------------------------------------------------------------

-- Walks the groups ATT returns for a quest and pulls out whatever is useful.
-- Every field is optional; ATT groups are heterogeneous.
function ATT.GetQuestData(questID)
    local groups = Search("questID", questID)

    if not groups or #groups == 0 then
        return nil
    end

    local data = { source = "ATT" }

    for _, group in ipairs(groups) do
        if type(group) == "table" then
            if not data.name and type(group.name) == "string" and group.name ~= "" then
                data.name = group.name
            end

            if not data.mapID then
                data.mapID = group.mapID or group.coord and group.coord[3] or nil
            end

            -- ATT stores coordinates as {x, y, mapID} in `coord`, or a list
            -- of those in `coords`. Values are 0-100.
            local coord = group.coord

            if not coord and type(group.coords) == "table" then
                coord = group.coords[1]
            end

            if not data.x and type(coord) == "table" and coord[1] and coord[2] then
                data.x     = coord[1] / 100
                data.y     = coord[2] / 100
                data.mapID = coord[3] or data.mapID
            end

            if not data.requires and type(group.sourceQuests) == "table"
                and #group.sourceQuests > 0 then

                data.requires = {}

                for _, prerequisiteID in ipairs(group.sourceQuests) do
                    if type(prerequisiteID) == "number" then
                        table.insert(data.requires, prerequisiteID)
                    end
                end

                if #data.requires == 0 then
                    data.requires = nil
                end
            end

            -- FIRST WINS, like every other field in this loop.
            --
            -- The guard tested `data.lvl`, which nothing in this file ever
            -- assigns, so it was always true and the LAST matching group won
            -- -- alone among the six fields merged here, all of which use
            -- `if not data.<field>`. Two ATT groups with different level
            -- requirements produced whichever happened to be iterated last,
            -- and that feeds the "too low level" block reason.
            if data.requiresLevel == nil and type(group.lvl) == "number" then
                data.requiresLevel = group.lvl
            end
        end
    end

    if not (data.name or data.requires or data.x) then
        return nil
    end

    return data
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function ATT.Describe()
    local root = Root()

    if not root then
        return "not installed"
    end

    local entries = {}

    for _, note in ipairs(probeNotes) do
        table.insert(entries, note)
    end

    table.insert(entries, "SearchForField: "
        .. (type(root.SearchForField) == "function" and "yes" or "no"))

    return table.concat(entries, ", ")
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

CN.RegisterQuestDataProvider("ATT", {
    IsAvailable  = ATT.IsAvailable,
    GetQuestData = ATT.GetQuestData,
    Describe     = ATT.Describe,
    priority     = 20,
})
'@

$Embedded['Providers\BtWQuests.lua'] = @'
-- Providers/BtWQuests.lua
-- Completion Navigator :: BtWQuests interoperability.
--
-- BtWQuests knows quest chains. Completion Navigator knows what you have
-- done and where you are. The useful combination is: given the chain, which
-- link is the next one you can actually act on.
--
-- Same caution as the ATT provider: this reads another addon's internals,
-- which are not a published contract. Every access is probed and wrapped, so
-- a BtWQuests update can make this provider go quiet but cannot break
-- Completion Navigator.
--
-- /cn providers reports exactly what resolved.

local ADDON_NAME, CN = ...

local BtW = {}

CN.BtWQuests = BtW

local probeNotes = {}

local function Database()
    -- The database has lived in a couple of places across versions.
    local candidates = {
        _G.BtWQuestsDatabase,
        _G.BtWQuests and _G.BtWQuests.Database,
        _G.BtWQuests and _G.BtWQuests.database,
    }

    -- A NUMERIC LOOP, NOT ipairs.
    --
    -- The first slot is nil whenever the global is absent -- which the
    -- comment above says is the normal case on recent versions -- and ipairs
    -- stops at the first nil. So the two fallbacks this list exists to
    -- provide were unreachable in exactly the situation they were written
    -- for, and the provider reported BtWQuests as unavailable to anyone
    -- running a version that had moved it.
    --
    -- The interpreters do not even agree on how long the list is: 5.4 says
    -- two, the game's 5.1 says zero. BlizzardWorld.lua already avoids this
    -- with a numeric loop and a comment naming "the same nil-hole problem".
    for index = 1, 3 do
        local candidate = candidates[index]

        if type(candidate) == "table" then
            if #probeNotes == 0 then
                table.insert(probeNotes, "database slot " .. index)
            end

            return candidate
        end
    end

    return nil
end

function BtW.IsAvailable()
    return _G.BtWQuests ~= nil and Database() ~= nil
end

------------------------------------------------------------
-- QUEST LOOKUP
------------------------------------------------------------

local function GetQuestItem(questID)
    local database = Database()

    if not database or not questID then
        return nil
    end

    local getter = database.GetQuestByID or database.GetQuest

    if type(getter) ~= "function" then
        return nil
    end

    local ok, item = pcall(getter, database, questID)

    if not ok or type(item) ~= "table" then
        return nil
    end

    return item
end

BtW.GetQuestItem = GetQuestItem

-- Normalizes whatever shape prerequisites come back in into a flat array of
-- quest IDs. BtWQuests expresses them as condition tables, which may nest.
local function CollectQuestIDs(node, out, depth)
    if type(node) ~= "table" or depth > 4 then
        return
    end

    if type(node.questID) == "number" then
        out[node.questID] = true
    end

    if type(node.id) == "number" and node.type == "quest" then
        out[node.id] = true
    end

    for _, child in pairs(node) do
        if type(child) == "table" then
            CollectQuestIDs(child, out, depth + 1)
        end
    end
end

function BtW.GetQuestData(questID)
    local item = GetQuestItem(questID)

    if not item then
        return nil
    end

    local data = { source = "BtWQuests" }

    -- Name.
    local nameGetter = item.GetName

    if type(nameGetter) == "function" then
        local ok, name = pcall(nameGetter, item)

        if ok and type(name) == "string" and name ~= "" then
            data.name = name
        end
    elseif type(item.name) == "string" then
        data.name = item.name
    end

    -- Prerequisites.
    local prerequisites = item.prerequisites or item.restrictions

    local getter = item.GetPrerequisites

    if type(getter) == "function" then
        local ok, result = pcall(getter, item)

        if ok and type(result) == "table" then
            prerequisites = result
        end
    end

    if type(prerequisites) == "table" then
        local ids = {}

        CollectQuestIDs(prerequisites, ids, 0)

        ids[questID] = nil   -- never list a quest as its own prerequisite

        local list = {}

        for id in pairs(ids) do
            table.insert(list, id)
        end

        table.sort(list)

        if #list > 0 then
            data.requires = list
        end
    end

    if not (data.name or data.requires) then
        return nil
    end

    return data
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function BtW.Describe()
    if not _G.BtWQuests then
        return "not installed"
    end

    local database = Database()

    if not database then
        return "loaded, but no database found"
    end

    local entries = {}

    for _, note in ipairs(probeNotes) do
        table.insert(entries, note)
    end

    table.insert(entries, "GetQuestByID: "
        .. (type(database.GetQuestByID) == "function" and "yes" or "no"))

    return table.concat(entries, ", ")
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

CN.RegisterQuestDataProvider("BtWQuests", {
    IsAvailable  = BtW.IsAvailable,
    GetQuestData = BtW.GetQuestData,
    Describe     = BtW.Describe,
    priority     = 30,
})
'@

$Embedded['Providers\HandyNotes.lua'] = @'
-- Providers/HandyNotes.lua
-- Completion Navigator :: HandyNotes interoperability.
--
-- HandyNotes and its plugins hold coordinates for treasures, rares, vendors
-- and collectibles that no Blizzard API reports. Where vignettes only tell
-- you about something in range, HandyNotes knows where things are before you
-- get near them.
--
-- Same caution as the other external providers: this reads another addon's
-- internals, which are not a published contract. Every access is probed and
-- wrapped, so a HandyNotes update can make this go quiet but cannot break
-- Completion Navigator. /cn providers reports what resolved.

local ADDON_NAME, CN = ...

local Print = CN.Print

local HandyNotes = {}

CN.HandyNotes = HandyNotes

local function Root()
    local candidate = _G.HandyNotes

    if type(candidate) == "table" then
        return candidate
    end

    return nil
end

function HandyNotes.IsAvailable()
    return Root() ~= nil
end

------------------------------------------------------------
-- PLUGINS
------------------------------------------------------------

-- HandyNotes itself holds almost no data. The plugins do, and they register
-- with the parent under names like "HandyNotes_Treasures".
function HandyNotes.GetPlugins()
    local root = Root()

    if not root then
        return {}
    end

    local names = {}

    -- Ace-style addon with a plugin registry.
    local iterate = root.IteratePlugins

    if type(iterate) == "function" then
        -- THE WHOLE TRIPLET, NOT JUST THE FIRST RETURN.
        --
        -- `IteratePlugins` is a `pairs`-style stateful iterator: it returns
        -- `next`, the table, and the control value. Capturing only the first
        -- and writing `for name in iterator` calls `next(nil, nil)`, which
        -- throws "bad argument #1 to 'next' (table expected, got nil)" -- so
        -- this integration could not work for any player who actually has
        -- HandyNotes installed.
        --
        -- The stub in the test suite was a single self-contained closure,
        -- which is the one shape that makes the broken form work. Stub more
        -- forgiving than the client, again.
        local ok, step, state, control = pcall(iterate, root)

        if ok and type(step) == "function" then
            local safe = 0

            for name in step, state, control do
                table.insert(names, name)

                safe = safe + 1

                if safe > 200 then
                    break
                end
            end
        end
    end

    if #names == 0 and type(root.plugins) == "table" then
        for name in pairs(root.plugins) do
            table.insert(names, name)
        end
    end

    table.sort(names)

    return names
end

------------------------------------------------------------
-- NODE LOOKUP
------------------------------------------------------------

-- Asks every registered plugin what it knows about a map. Plugin node
-- iterators are HandyNotes' documented extension point, so this is the most
-- stable surface available -- but it is still another addon's internals.
function HandyNotes.GetNodesOnMap(uiMapID)
    local root = Root()

    if not root or not uiMapID then
        return {}
    end

    local nodes = {}

    local iterate = root.IteratePlugins

    if type(iterate) ~= "function" then
        return nodes
    end

    local ok, step, state, control = pcall(iterate, root)

    if not ok or type(step) ~= "function" then
        return nodes
    end

    local pluginCount = 0

    for name, handler in step, state, control do
        pluginCount = pluginCount + 1

        if pluginCount > 50 then
            break
        end

        if type(handler) == "table" and type(handler.GetNodes2) == "function" then
            -- Same triplet, same reason: a plugin's node iterator is also
            -- a `pairs`-style return. This one was inside a pcall, so it
            -- failed to a debug line instead of an error -- silently, which
            -- is how a whole feature can be broken and look empty.
            local gotNodes, nodeStep, nodeState, nodeControl =
                pcall(handler.GetNodes2, handler, uiMapID, false)

            if gotNodes and type(nodeStep) == "function" then
                local safe = 0

                -- HandyNotes coords pack x and y into one integer.
                local success = pcall(function()
                    for coord, node in nodeStep, nodeState, nodeControl do
                        safe = safe + 1

                        if safe > 500 then
                            break
                        end

                        if type(coord) == "number" then
                            local x = math.floor(coord / 10000) / 10000
                            local y = (coord % 10000) / 10000

                            table.insert(nodes, {
                                plugin = name,
                                x      = x,
                                y      = y,
                                mapID  = uiMapID,
                                label  = type(node) == "table" and node.label or nil,
                            })
                        end
                    end
                end)

                if not success then
                    CN.DebugPrint("HandyNotes plugin " .. tostring(name)
                        .. " node iteration failed.")
                end
            end
        end
    end

    return nodes
end

------------------------------------------------------------
-- DIAGNOSTICS
------------------------------------------------------------

function HandyNotes.Describe()
    local root = Root()

    if not root then
        return "not installed"
    end

    local plugins = HandyNotes.GetPlugins()

    if #plugins == 0 then
        return "loaded, no plugins registered"
    end

    local noun = (#plugins == 1) and " plugin" or " plugins"

    if #plugins <= 3 then
        return #plugins .. noun .. ": " .. table.concat(plugins, ", ")
    end

    return #plugins .. noun
end

------------------------------------------------------------
-- REGISTRATION
------------------------------------------------------------

-- Registered as a quest data provider so it appears in /cn providers, even
-- though it answers about locations rather than quests. It never claims to
-- know a quest, so it can never contribute wrong prerequisite data.
CN.RegisterQuestDataProvider("HandyNotes", {
    IsAvailable  = HandyNotes.IsAvailable,
    GetQuestData = function() return nil end,
    Describe     = HandyNotes.Describe,
    priority     = 90,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

-- `GetNodesOnMap` is seventy lines and the stated reason this file exists,
-- and until 0.53.0 nothing called it: no provider, no command, no test. It
-- was written, documented, shipped, and never run -- and because it sat
-- behind a broken iterator it could not have worked if it had been.
--
-- Read-only and on request. HandyNotes nodes are another addon's data about
-- the same world, so they are shown rather than folded into the ranking:
-- this addon does not know how that plugin decides what to draw, and
-- inheriting somebody else's opinion silently is not the same as having one.
CN:RegisterCommand{
    name    = "handynotes",
    aliases = { "hn" },
    order   = 78,
    help    = "What HandyNotes plugins are drawing on this map.",
    handler = function()
        if not HandyNotes.IsAvailable() then
            Print("HandyNotes is not installed, or has not loaded.")
            return
        end

        Print("HandyNotes: " .. HandyNotes.Describe())

        local mapID = CN.GetPlayerPosition()

        if not mapID then
            Print("|cff8a8f96The client will not say which map you are on.|r")
            return
        end

        local nodes = HandyNotes.GetNodesOnMap(mapID)

        if #nodes == 0 then
            Print("|cff8a8f96No plugin is drawing anything on this map.|r")
            return
        end

        local rows = {}

        for _, node in ipairs(nodes) do
            table.insert(rows, {
                text  = tostring(node.label or "unnamed"),
                value = string.format("%.1f, %.1f",
                    (node.x or 0) * 100, (node.y or 0) * 100),
                state = "MUTED",
                note  = tostring(node.plugin),
            })
        end

        CN.PrintRows(CN.Count(#nodes, "node") .. " on this map:", rows,
            { limit = 20 })

        Print("|cff8a8f96Shown, not scored: this is another addon's view of "
            .. "the same world.|r")
    end,
}
'@

$Embedded['Modules\Quests.lua'] = @'
-- Modules/Quests.lua
-- Completion Navigator :: quest subsystem.
--
-- Roadmap position: automatic discovery, event-driven refresh, persistent
-- metadata and status, source-ranked metadata writes.

local ADDON_NAME, CN = ...

local Quests = CN:RegisterModule("Quests")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

CN.pendingQuestLoads = CN.pendingQuestLoads or {}

------------------------------------------------------------
-- COMPLETION STATE
------------------------------------------------------------

function Quests.IsCompletedByCharacter(questID)
    return Blizzard.IsQuestCompletedByCharacter(questID)
end

function Quests.IsCompletedOnAccount(questID)
    return Blizzard.IsQuestCompletedOnAccount(questID)
end

-- Kept for backwards compatibility with the single-file prototype.
CN.IsQuestCompletedByCharacter = Quests.IsCompletedByCharacter
CN.IsQuestCompletedOnAccount   = Quests.IsCompletedOnAccount

------------------------------------------------------------
-- METADATA
------------------------------------------------------------

-- Writes a name only when the incoming source is at least as
-- authoritative as the stored one. Manual entries never clobber Blizzard.
-- A ROW IS A STRING UNLESS IT HAS SOMETHING ELSE TO SAY. 0.61.0.
--
-- `questMetadata` is the largest store in the addon: 708 KB of a 2.0 MB
-- SavedVariables file, and the game rewrites that file in full on every
-- logout. Every row was a two-field TABLE -- `{ name = ..., source = ... }`
-- -- and on an established account 30,000 of them said `source = "blizzard"`,
-- which is the default and carries no information.
--
-- The name itself does have to be kept. `GetTitleForQuestID` answers only for
-- quests the CLIENT has cached, and returns nil with an async request for
-- everything else -- so without this store the addon shows "Quest 84213" for
-- anything the player has not looked at this session. That is a real thing
-- the client will not re-supply on demand, and the standing rule permits it.
--
-- What the rule does NOT permit is the wrapper. So a row is now the name
-- itself, and only a name the PLAYER typed -- which must survive being
-- offered a Blizzard one -- keeps a table to say so. That is a handful of
-- rows against thirty thousand.
--
-- Both readers below accept either shape, and migration 15 collapses the
-- existing ones on first login.
-- A BARE STRING IS THE CLIENT'S NAME, AND ONLY THE CLIENT'S. 0.63.0.
--
-- 0.61.0 collapsed the row to a bare string for everything except a name the
-- player typed, and taught this to report a bare string as source
-- "blizzard". That threw away provenance for two other sources -- a title
-- read from a gossip window ("offered") and one read from a map pin
-- ("available") -- and did something worse than lose a label: because
-- "blizzard" is rank 1, the TOP of `CN.sourceRank`, a guess captured from a
-- map pin outranked the authoritative quest-log title that arrived later, and
-- `IsBetterSource` refused to correct it. `/cn cache 12345` then reported the
-- guess as having come from the client.
--
-- The saving was never in dropping the source; it was in dropping the
-- WRAPPER for the overwhelmingly common case. So the common case keeps the
-- bare string and every other source keeps its table -- a handful of rows
-- against thirty thousand, which is the same arithmetic that justified the
-- change in the first place.
--
-- "offered" and "available" are ranked now, too. They were absent from the
-- ladder entirely, which made them rank 99: worse than anything, including
-- each other.
local function NameFrom(record)
    if type(record) == "string" then
        return record, "blizzard"
    end

    if type(record) == "table" then
        return record.name, record.source
    end

    return nil, nil
end

Quests.NameFrom = NameFrom

-- Writes a name only when the incoming source is at least as
-- authoritative as the stored one. Manual entries never clobber Blizzard.
function Quests.SetMetadata(questID, name, source)
    if not questID or not name or name == "" then
        return false
    end

    local metadata = CN.Account("questMetadata")

    local heldName, heldSource = NameFrom(metadata[questID])

    source = source or "manual"

    if heldName and not CN.IsBetterSource(source, heldSource) then
        DebugPrint("Kept existing " .. tostring(heldSource)
            .. " name for quest " .. questID .. "; rejected " .. source .. ".")
        return false
    end

    -- `questID` duplicated the key this is filed under and `lastSeen` had no
    -- reader. The same fields migration 5 stripped from achievements, pets
    -- and toys.
    -- The bare string means "the client's own title for this quest", which
    -- is the overwhelmingly common case and the one worth optimising -- and
    -- the two sources that mean it are the top two ranks, so collapsing them
    -- together loses no decision. Every other source keeps its label, which
    -- is the part 0.61.0 threw away.
    if source == "blizzard" or source == "questlog" then
        metadata[questID] = name
    else
        metadata[questID] = { name = name, source = source }
    end

    return true
end

-- Kept in the table shape callers already expect, built on read rather than
-- stored. Two fields on a handful of lookups is not worth 708 KB on disk.
function Quests.GetMetadata(questID)
    local name, source = NameFrom(CN.Account("questMetadata")[questID])

    if not name then
        return nil
    end

    return { name = name, source = source }
end

-- Resolution order: cache -> live client -> static data -> async request.
function Quests.GetName(questID, requestIfMissing)
    if not questID then
        return nil
    end

    local cached = Quests.GetMetadata(questID)

    if cached and cached.name then
        return cached.name
    end

    local title = Blizzard.GetQuestTitle(questID, false)

    if title then
        Quests.SetMetadata(questID, title, "blizzard")
        return title
    end

    local static = CN.Static.GetQuestName(questID)

    if static then
        Quests.SetMetadata(questID, static, "static")
        return static
    end

    if requestIfMissing then
        Blizzard.GetQuestTitle(questID, true)
    end

    return nil
end

CN.GetQuestName = Quests.GetName

------------------------------------------------------------
-- DISCOVERY
------------------------------------------------------------

function Quests.RecordDiscovered(questID, source)
    questID = CN.ToID(questID)

    if not questID then
        return false
    end

    local discovered = CN.Account("discoveredQuests")
    local existing   = discovered[questID]

    -- ONE FACT, WHICH IS ALL ANYTHING EVER READ.
    --
    -- This stored `{ firstSeen, lastSeen, source }`, and every reader in the
    -- tree -- the completion scan, the breakdown, the window, the two
    -- commands -- counts or iterates keys. Three fields per row, rewritten in
    -- full on every logout, for information nothing has ever asked for. See
    -- migration 12.
    discovered[questID] = true

    -- The Remaining tab's quest figure counts completed quests among the
    -- DISCOVERED set, so a new discovery is one of the two edges it has to be
    -- told about. One client call about one id; see the note there.
    local breakdown = CN:GetModule("Breakdown")

    if breakdown and breakdown.NoteQuestDiscovered then
        breakdown.NoteQuestDiscovered(questID)
    end

    if not existing then
        DebugPrint("Discovered quest " .. questID .. " (" .. tostring(source or "manual") .. ").")
    end

    return existing == nil
end

CN.RecordDiscoveredQuest = Quests.RecordDiscovered

-- Quests you could walk up to and accept right now, on one map.
--
-- These are the exclamation marks. Until 0.23.0 the addon could not see them
-- at all: it read the quest LOG, which by definition contains only quests you
-- have already taken. "What should I do next?" cannot be answered honestly
-- while the answer "pick up that quest twenty yards away" is invisible.
------------------------------------------------------------
-- LIFECYCLE PHASE
------------------------------------------------------------

-- A quest is not one place. It is three, in order:
--
--   PICKUP  -- the exclamation mark, where you accept it
--   ACTIVE  -- wherever its objectives actually are
--   TURNIN  -- the question mark, where you hand it back
--
-- Treating a quest as a single point is why an addon sends you back and forth:
-- it cannot tell that two quests share a giver, or that four you are carrying
-- all hand in at the same NPC. Naming the phase is what makes batching
-- possible at all.
CN.questPhases = {
    PICKUP = "PICKUP",
    ACTIVE = "ACTIVE",
    TURNIN = "TURNIN",
}

CN.questPhaseVerbs = {
    PICKUP = "pick up",
    ACTIVE = "work on",
    TURNIN = "turn in",
}

function Quests.Phase(questID)
    if not questID then
        return nil
    end

    if Blizzard.IsQuestReadyForTurnIn(questID) then
        return CN.questPhases.TURNIN
    end

    if Blizzard.IsQuestInLog(questID) then
        return CN.questPhases.ACTIVE
    end

    if Quests.IsCompletedByCharacter(questID) then
        return nil
    end

    return CN.questPhases.PICKUP
end

function Quests.PhaseVerb(phase)
    return CN.questPhaseVerbs[phase] or "do"
end

-- Quests offered near you that you have not taken.
--
-- REPORTED FROM LIVE PLAY: "I'm literally standing in front of one to pick
-- up" while this returned zero. Three separate reasons that can happen, and
-- the old version was vulnerable to all three:
--
--   1. WRONG MAP. GetBestMapForUnit answers with the most specific map you
--      are standing on -- a city, a cave, a building interior. Quest starts
--      belonging to the surrounding zone are registered against the PARENT
--      map, so asking only about your own map misses them. This is the most
--      likely cause and the cheapest to fix: ask the neighbourhood.
--   2. THE MAP SIMPLY DOES NOT SAY. A giver whose pin the client has not
--      loaded is invisible to every map query. The only thing that cannot be
--      wrong is the conversation itself, so talking to an NPC now records
--      what they offered.
--
-- Sources are unioned and each result says where it came from, because when
-- this is wrong again the first question will be "which source found it".
-- `quiet` MEANS "READ, DO NOT RECORD". 0.70.0.
--
-- This writes: every quest-start pin it walks past is filed into the
-- remembered store, which is a SavedVariable, and each new one moves the
-- shortlist revision. That is right when the player is playing, and wrong
-- when something is merely reading -- `/cn find` refreshes every tab so the
-- search has rows to look at, and the Journey tab's refresh reaches here, so
-- typing a search with the window shut wrote pins to disk and forced a
-- shortlist rebuild.
--
-- The same distinction `CN.Recommend(limit, quiet)` draws one file over, for
-- the same reason and from the same command.
function Quests.AvailableOnMap(mapID, quiet)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local found, seen = {}, {}

    local function consider(poi, source)
        if not poi or not poi.questID or seen[poi.questID] then
            return
        end

        if Blizzard.IsQuestInLog(poi.questID) then
            return
        end

        if Quests.IsCompletedByCharacter(poi.questID) then
            return
        end

        seen[poi.questID] = true

        poi.source = source

        table.insert(found, poi)
    end

    -- 1. Every map in the neighbourhood, not just the one under your feet.
    for _, relatedID in ipairs(Blizzard.RelatedMapIDs(mapID)) do
        for _, poi in ipairs(Blizzard.GetQuestPOIsOnMap(relatedID)) do
            if poi.isQuestStart and not poi.inProgress then
                consider(poi, "map")

                if not quiet then
                    Quests.RememberOffer(poi)
                end
            end
        end
    end

    -- 2. Anything an NPC has actually offered us, remembered from the
    --    conversation. Only kept while it is still plausibly nearby.
    --
    -- ON THE MAP IT WAS SEEN ON. 0.89.0.
    --
    -- This function takes a map and the source above honours it; this one did
    -- not, so anything a gossip window offered in the last fifteen minutes
    -- was reported as being on whatever map was asked about. The provider
    -- then wrote "available to pick up in this zone" on a row whose travel
    -- cost was computed against the PREVIOUS zone -- the sentence and the
    -- number on one row contradicting each other -- `/cn available` counted
    -- it, and walking into an empty zone within fifteen minutes of a
    -- conversation fired "3 quests here you have not picked up".
    local nearby = {}

    for _, relatedID in ipairs(Blizzard.RelatedMapIDs(mapID)) do
        nearby[relatedID] = true
    end

    for questID, record in pairs(Quests.RecentOffers()) do
        if record.mapID and nearby[record.mapID] then
            consider({
                questID = questID,
                mapID   = record.mapID,
                x       = record.x,
                y       = record.y,
            }, "offered")
        end
    end

    table.sort(found, function(a, b) return a.questID < b.questID end)

    return found
end

-- QUESTS THREE ZONES AWAY.
--
-- The client's POI list only answers for a map, and only for the map the
-- player is looking at -- so "what is waiting for me in Azj-Kahet?" was
-- structurally unanswerable and the addon said so in its own scope-limits
-- note. It still cannot enumerate a zone it has never seen; what it can do
-- is remember what it HAS seen.
--
-- Every quest start observed on any map is recorded, so a zone the player
-- walked through last week can still be reported on. Bounded, and pruned
-- when a quest is completed or picked up, because a remembered pin for a
-- quest already in the log is worse than no pin.
Quests.rememberedCap = 600

local function Remembered()
    return CN.Account("questPins")
end

-- A COUNTER, NOT A COUNT. 0.67.0.
--
-- The off-map shortlist keyed its revision on `CN.CountKeys(Remembered())`,
-- which is a walk of up to six hundred rows -- the exact walk 0.65.0 took OFF
-- this path -- performed on every call, from a provider on the
-- `QUEST_LOG_UPDATE` firehose. Worse, walking into new content adds ids
-- continuously, so the count moved constantly and the shortlist rebuilt every
-- two seconds: a full store walk plus one travel estimate per remembered map,
-- and a travel estimate is four client conversions and a scan of the flight
-- network.
--
-- One integer, bumped by the only two things that change what is in the
-- store.
Quests.pinRevision = 0

Quests.Remembered = Remembered

function Quests.RememberOffer(poi)
    if not poi or not poi.questID or not poi.mapID then
        return false
    end

    local store = Remembered()

    -- Only what the client cannot re-derive instantly: no names, no
    -- timestamps beyond the one that makes pruning possible.
    local isNew = store[poi.questID] == nil

    if isNew then
        Quests.pinRevision = Quests.pinRevision + 1
    end

    store[poi.questID] = {
        mapID = poi.mapID,
        x     = poi.x and math.floor(poi.x * 1000 + 0.5) / 1000 or nil,
        y     = poi.y and math.floor(poi.y * 1000 + 0.5) / 1000 or nil,
    }

    -- THE CEILING IS TESTED WHEN THE SET GREW, NOT ON EVERY SIGHTING.
    --
    -- `CN.CountKeys` walks the whole six-hundred-entry store, and this runs
    -- once per quest-start pin on every related map -- about thirty pins
    -- across four maps in a quest hub, so eighteen thousand table iterations
    -- for one boolean, from a provider on the `QUEST_LOG_UPDATE` firehose.
    --
    -- A store that did not gain a key cannot have crossed its ceiling, and
    -- the caller above already knows whether this id was new. 0.65.0.
    if isNew and CN.CountKeys(store) > Quests.rememberedCap then
        Quests.PruneRemembered()
    end

    return true
end

------------------------------------------------------------
-- QUESTS BEYOND THE MAP YOU ARE STANDING ON
------------------------------------------------------------

-- THE STORE WAS ALREADY BEING FILLED. NOTHING OFFERED FROM IT. 0.66.0.
--
-- `questPins` has recorded where every quest-start pin the player has ever
-- ridden past lives, and pruned itself, since it was added -- and it was read
-- only to answer "where is this quest" for a quest something ELSE had already
-- proposed. So the addon's answer to "what next?" was, for available quests,
-- bounded by the borders of the zone the player happened to be standing in:
-- it could see a quest twenty yards away and not one in the next zone, and it
-- would recommend a rare across the continent instead.
--
-- This is the largest coverage gap in the backlog and the data for it was
-- already on disk.
--
-- BOUNDED BY ZONE, NOT BY QUEST. Travel cost is a property of where a zone
-- is, and the pins in one zone share it -- so the cost is asked once per
-- MAP, of which a player has a few dozen, rather than once per pin, of which
-- they have up to six hundred. The nearest few zones contribute; the rest do
-- not, because a list that offers everything is not a recommendation.
Quests.offMapZones = 3
Quests.offMapCap   = 20

-- Which remembered maps are worth reaching, cheapest first. One representative
-- point per map is enough to price it: zones are not large compared to the
-- distance between them.
function Quests.NearbyRememberedMaps(playerMap)
    local byMap = {}

    -- THE NEIGHBOURHOOD, NOT THE EXACT MAP. 0.67.0.
    --
    -- Pins are recorded against every RELATED map -- `AvailableOnMap` walks
    -- `RelatedMapIDs`, which adds the parent zone and all its children -- and
    -- `GetBestMapForUnit` answers with the city's own map when the player is
    -- standing in one. So a quest giver twenty yards away in Dornogal, whose
    -- pin was filed against Isle of Dorn, came back through the OFF-map
    -- branch: priced as a journey, penalised a point, and captioned
    -- "available to pick up in Isle of Dorn" while the player stood in it.
    local here = {}

    if playerMap then
        here[playerMap] = true

        for _, related in ipairs(Blizzard.RelatedMapIDs(playerMap) or {}) do
            here[related] = true
        end
    end

    local function Skip(mapID)
        return here[mapID] == true
    end

    for questID, record in pairs(Remembered()) do
        local mapID = record.mapID

        -- BY CHARACTER, NOT BY ACCOUNT. 0.67.0.
        --
        -- `PruneRemembered` uses the account check deliberately -- WHERE a
        -- quest is does not depend on who is asking -- and this borrowed it,
        -- which is the opposite question. So a player whose main had cleared
        -- a continent rolled an alt and was offered nothing at all from it:
        -- `/cn unpicked` correctly listed twenty-two quests in a zone and
        -- `/cn next` never mentioned one of them. The in-zone sibling,
        -- `AvailableOnMap`, has always used the character check.
        if mapID and not Skip(mapID)
            and not Quests.IsCompletedByCharacter(questID)
            and not Blizzard.IsQuestInLog(questID) then

            byMap[mapID] = byMap[mapID] or {}

            table.insert(byMap[mapID], {
                questID = questID,
                mapID   = mapID,
                x       = record.x,
                y       = record.y,
            })
        end
    end

    local maps = {}

    for mapID, pins in pairs(byMap) do
        table.sort(pins, function(a, b) return a.questID < b.questID end)

        -- A PIN THAT HAS COORDINATES, NOT MERELY THE LOWEST ID. 0.68.0.
        --
        -- `RememberOffer` stores `x` and `y` only when the client gave them,
        -- and it does not always. Pricing a zone from a pin with no position
        -- makes `Travel.CostFor` refuse, `CN.TravelCost` fall through to its
        -- pessimism constant, and the zone sort last -- so up to twenty
        -- available quests one flight point away silently never appeared,
        -- while a farther zone whose lowest-id pin happened to have
        -- coordinates did.
        local sample

        for _, pin in ipairs(pins) do
            if pin.x and pin.y then
                sample = pin
                break
            end
        end

        -- No pin in the whole zone has a position. The zone is still worth
        -- offering -- the quests are real -- but nothing here can price the
        -- journey, so it is not pretended: it sorts last on the same constant
        -- the scorer uses for an unknown location, which is what that
        -- constant is for.
        -- AN EXPLICIT BRANCH, BECAUSE `CN.TravelCost` NEVER REFUSES. 0.69.0.
        --
        -- Written as an `and ... or` it reads as protection against a nil
        -- cost -- which cannot happen, and which this file says cannot happen
        -- a thousand lines down. A guard that cannot fire is one nobody can
        -- reason about, and it would silently swallow the day `CN.TravelCost`
        -- learns to refuse.
        local cost

        if sample then
            cost = CN.TravelCost(mapID, sample.x, sample.y)
        else
            cost = CN.unknownLocationCost
        end

        table.insert(maps, {
            mapID = mapID,
            cost  = cost,
            pins  = pins,
        })
    end

    -- ORDERED, AND ORDERED TOTALLY. Ties are broken on the map id so two
    -- clients with the same data produce the same list -- the same reason
    -- the candidate providers are ordered by registration.
    table.sort(maps, function(a, b)
        if a.cost ~= b.cost then
            return a.cost < b.cost
        end

        return a.mapID < b.mapID
    end)

    return maps
end

-- The offers themselves, capped. Shortlisted because the walk above is over
-- the whole remembered store and the provider it feeds runs every two
-- seconds; the revision changes when the store or the player's map does,
-- which is exactly when the answer can differ.
function Quests.OffMapOffers()
    local playerMap = CN.GetPlayerPosition()

    if not playerMap then
        return {}
    end

    -- AND WHERE THE PLAYER IS, COARSELY. 0.67.0.
    --
    -- The revision carried the map and not the position, so the "three
    -- cheapest zones" ordering was taken once on entering a zone and never
    -- re-costed: fly to the far side of it, or learn a flight point, and the
    -- addon went on pricing the journey from where you landed. A tenth of a
    -- map is coarse enough that walking does not thrash it and fine enough
    -- that crossing a zone re-asks.
    local _, playerX, playerY = CN.GetPlayerPosition()

    local revision = tostring(playerMap)
        .. ":" .. tostring(Quests.pinRevision)
        .. ":" .. tostring(math.floor((playerX or 0) * 10))
        .. ":" .. tostring(math.floor((playerY or 0) * 10))

    local list = CN.Shortlist("quests:offmap", revision, function()
        local offers = {}

        for index, map in ipairs(Quests.NearbyRememberedMaps(playerMap)) do
            if index > Quests.offMapZones then
                break
            end

            for _, pin in ipairs(map.pins) do
                if #offers >= Quests.offMapCap then
                    break
                end

                table.insert(offers, pin)
            end
        end

        return offers
    end)

    return list
end

-- Drops anything no longer worth remembering: completed, in the log, or --
-- if still over the cap after that -- the lowest quest IDs, which are the
-- oldest content and the least likely to be what the player is working on.
function Quests.PruneRemembered()
    local store = Remembered()

    local dropped = 0

    -- ACCOUNT COMPLETION, NOT THIS CHARACTER'S.
    --
    -- `Remembered()` is an account-wide store of WHERE a quest is, and where
    -- a quest is does not depend on who is asking. Pruning it on
    -- `IsCompletedByCharacter` meant one character finishing a zone deleted
    -- the remembered locations for every other character who still had it to
    -- do -- the same wrong-scope defect as the quest-status store, in the
    -- other direction.
    -- AND NOT ON THIS CHARACTER'S QUEST LOG. 0.74.0.
    --
    -- The paragraph above states the rule -- where a quest is does not depend
    -- on who is asking -- and the next clause used to break it:
    -- `IsQuestInLog` answers for the character currently logged in, and this
    -- deletes from the ACCOUNT store.
    --
    -- Under 0.72.0 the sweep ran only when the store crossed its six-hundred
    -- row cap, so the damage was rare. 0.73.0 wired it to every login, which
    -- made it routine: log in on a main holding twenty-five quests and
    -- twenty-five pickup locations vanish for the whole account, so an alt
    -- that still needs them is no longer offered them and the location is
    -- unrecoverable until somebody rides past the giver again. Abandoning a
    -- quest lost its pin the same way.
    --
    -- Account completion is the correct test and stays. "In MY log" is a
    -- per-character question and already belongs to the per-character read
    -- filters, which have it -- and to `QUEST_ACCEPTED`, which drops the pin
    -- for the character that picked it up without speaking for the others.
    for questID in pairs(store) do
        if Quests.IsCompletedOnAccount(questID) then
            store[questID] = nil
            dropped = dropped + 1
        end
    end

    local remaining = CN.CountKeys(store)

    if remaining > Quests.rememberedCap then
        local ids = {}

        for questID in pairs(store) do
            table.insert(ids, questID)
        end

        table.sort(ids)

        for index = 1, remaining - Quests.rememberedCap do
            store[ids[index]] = nil
            dropped = dropped + 1
        end
    end

    if dropped > 0 then
        Quests.pinRevision = Quests.pinRevision + 1
    end

    return dropped
end

-- What is waiting in a zone the player is not standing in.
function Quests.RememberedInZone(mapID)
    local waiting = {}

    if not mapID then
        return waiting
    end

    for questID, record in pairs(Remembered()) do
        if record.mapID == mapID
            and not Quests.IsCompletedByCharacter(questID)
            and not Blizzard.IsQuestInLog(questID) then

            table.insert(waiting, {
                questID = questID,
                mapID   = record.mapID,
                x       = record.x,
                y       = record.y,
            })
        end
    end

    table.sort(waiting, function(a, b) return a.questID < b.questID end)

    return waiting
end

-- Every zone with something remembered in it, most first.
function Quests.RememberedZones()
    local byZone = {}

    for questID, record in pairs(Remembered()) do
        if not Quests.IsCompletedByCharacter(questID)
            and not Blizzard.IsQuestInLog(questID) then

            byZone[record.mapID] = (byZone[record.mapID] or 0) + 1
        end
    end

    local zones = {}

    for zoneID, count in pairs(byZone) do
        table.insert(zones, {
            mapID = zoneID,
            name  = Blizzard.GetMapName(zoneID),
            count = count,
        })
    end

    table.sort(zones, function(a, b)
        if a.count ~= b.count then
            return a.count > b.count
        end

        return (a.mapID or 0) < (b.mapID or 0)
    end)

    return zones
end

-- THE EVENT HANDS YOU THE ID. USE IT. 0.72.0.
--
-- This ran the full sweep on every turn-in: a walk of the remembered store,
-- capped at 600 rows, with `IsQuestCompletedOnAccount` and `IsQuestInLog` --
-- two client calls -- on each, plus a `CN.CountKeys` pass. Twelve hundred
-- client calls to remove one entry, at the end of every quest, and four times
-- over in the bursts at the end of a chain.
--
-- The one quest that just changed is the argument. The full sweep runs where
-- a sweep belongs: once at login, from `RememberOffer` when the store crosses
-- its cap, and here when the client does not say which quest it was.
--
-- 0.72.0's version of this note claimed a login hook that did not exist. It
-- does now.
CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    if not questID then
        -- No id: the client did not say which. Fall back to the sweep rather
        -- than leaving a stale pin on the map.
        Quests.PruneRemembered()
        return
    end

    -- AND ONLY WHEN THE ACCOUNT IS DONE WITH IT. 0.74.0.
    --
    -- 0.72.0 replaced the full sweep here with a single-id removal, which was
    -- right about the cost and wrong about the scope in the same way
    -- `PruneRemembered` was: one character handing a quest in does not mean
    -- the account is finished with it, and this store is where the addon
    -- remembers, for every character, WHERE that quest is picked up. A main
    -- clearing a zone erased the map for every alt behind it.
    --
    -- Asking the account question about the one id that changed keeps the
    -- whole saving -- one client call instead of twelve hundred -- and gets
    -- the scope right, which is what the store is for.
    if not Quests.IsCompletedOnAccount(questID) then
        return
    end

    local store = Remembered()

    if store[questID] then
        store[questID] = nil
        Quests.pinRevision = Quests.pinRevision + 1
    end
end)

CN:RegisterCommand{
    -- RENAMED. "Waiting" reads as "waiting on a timer", which is what
    -- `/cn now` and `/cn clock` do -- three commands about deadlines, and
    -- this one is not about deadlines at all.
    name    = "unpicked",
    aliases = { "waiting" },
    args    = "[zone name]",
    order   = 23,
    help    = "Quests you have walked past and never picked up, by zone.",
    handler = function(args)
        args = CN.Trim(args or "")

        local zones = Quests.RememberedZones()

        if #zones == 0 then
            Print("Nothing remembered yet.")
            Print("|cff8a8f96The addon records quest starts as it sees them. "
                .. "Walk through a zone once and it can tell you what you "
                .. "left behind in it.|r")
            return
        end

        if args ~= "" then
            for _, zone in ipairs(zones) do
                if zone.name and string.lower(zone.name):find(string.lower(args), 1, true) then
                    CN.PrintLine(zone.name .. ": " .. zone.count .. " left behind")

                    for index, entry in ipairs(Quests.RememberedInZone(zone.mapID)) do
                        if index > 20 then
                            CN.PrintLine("  |cff8a8f96... and more|r")
                            break
                        end

                        CN.PrintLine("  " .. (Quests.GetName(entry.questID)
                            or ("quest " .. entry.questID)))
                    end

                    return
                end
            end

            Print("Nothing remembered in a zone matching \"" .. args .. "\".")
            return
        end

        Print("Quests you have seen and not taken:")

        for index, zone in ipairs(zones) do
            if index > 12 then
                CN.PrintLine("  |cff8a8f96... and " .. (#zones - 12) .. " more zones|r")
                break
            end

            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            CN.PrintLine("  " .. CN.Body(tostring(zone.name or zone.mapID))
                .. CN.Aside(tostring(zone.count)))
        end

        Print("|cff8a8f96This is what the addon has actually seen, not every "
            .. "quest in the game" .. CN.DASH .. "the client only lists pins for the map "
            .. "you are looking at.|r")
    end,
}

-- HOW FAR IS "HERE".
--
-- Searching the parent map and its siblings is what fixed a player being told
-- zero while standing in front of a quest giver. It also means the answer now
-- spans a whole zone, so calling it "here" overstates it -- the addon would
-- be pointing at something a four-minute ride away and using a word that
-- means arm's reach.
--
-- Split by distance where coordinates exist, and say the honest word for
-- each. Anything without coordinates is reported as "in this zone", because
-- that is the strongest claim the data supports.
CN.nearbyYards = 300

function Quests.SplitAvailableByDistance(available, mapID)
    local near, zone = {}, {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    local nav = CN:GetModule("Navigation")

    for _, poi in ipairs(available or {}) do
        local yards

        if nav and nav.DistanceYards and playerX and playerY
            and poi.x and poi.y and (poi.mapID or mapID) == playerMap then

            yards = nav.DistanceYards(playerMap, playerX, playerY, poi.x, poi.y)
        end

        poi.yards = yards

        if yards and yards <= CN.nearbyYards then
            table.insert(near, poi)
        else
            table.insert(zone, poi)
        end
    end

    return near, zone
end

-- World quests and bonus objectives, deliberately counted SEPARATELY.
--
-- They are available in the dictionary sense, and they are not what a player
-- means by "quests I can pick up here" -- there is no exclamation mark and
-- nobody to talk to. Folding them into that number makes it stop matching
-- what is on the screen, which is the entire complaint this code exists to
-- answer.
function Quests.TasksOnMap(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local tasks = {}

    for _, task in ipairs(Blizzard.GetTaskQuestsOnMap(mapID)) do
        if not Quests.IsCompletedByCharacter(task.questID) then
            table.insert(tasks, task)
        end
    end

    return tasks
end

------------------------------------------------------------
-- WHAT AN NPC ACTUALLY OFFERED
------------------------------------------------------------

-- A conversation cannot be wrong about what it is offering. Map data can.
local recentOffers = {}

Quests.offerMemorySeconds = 900

function Quests.RecentOffers()
    local now = time()

    for questID, record in pairs(recentOffers) do
        if now - (record.at or 0) > Quests.offerMemorySeconds then
            recentOffers[questID] = nil
        end
    end

    return recentOffers
end

function Quests.NoteOffered(questID, title)
    if not questID or Quests.IsCompletedByCharacter(questID) then
        return false
    end

    if Blizzard.IsQuestInLog(questID) then
        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    recentOffers[questID] = {
        at    = time(),
        mapID = mapID,
        x     = x,
        y     = y,
    }

    if title and title ~= "" then
        Quests.SetMetadata(questID, title, "offered")
    end

    if mapID and x and y then
        Quests.SetLocation(questID, mapID, x, y, "offered")
    end

    Quests.RecordDiscovered(questID, "offered")

    DebugPrint("Noted quest " .. questID .. " offered by an NPC here.")

    return true
end

function Quests.ForgetOffer(questID)
    if questID then
        recentOffers[questID] = nil
    end
end

-- Talking to someone is the single most reliable moment to learn that a
-- quest exists here, so take it every time.
CN:RegisterEvent("GOSSIP_SHOW", function()
    for _, offer in ipairs(Blizzard.GetGossipAvailableQuests()) do
        Quests.NoteOffered(offer.questID, offer.title)
    end
end)

CN:RegisterEvent("QUEST_DETAIL", function()
    Quests.NoteOffered(Blizzard.GetActiveQuestOffer(), GetTitleText and GetTitleText())
end)

-- AND THE PIN IS DELIBERATELY NOT DROPPED HERE. Reverted in 0.74.0.
--
-- 0.73.0 added a pin removal to this handler on the grounds that a quest in
-- the log is no longer waiting to be picked up. True of THIS character, and
-- `Remembered()` is an account-wide store of WHERE a quest is -- so a main
-- accepting a quest deleted the location an alt still needed, and nothing
-- could recover it short of somebody riding past the giver again.
--
-- That is the identical wrong-scope defect this file's own `PruneRemembered`
-- header describes and warns about, written one release after the warning was
-- read. "In my log" is a per-character question, and the per-character read
-- filters already ask it at every read.
CN:RegisterEvent("QUEST_ACCEPTED", function(_, questID)
    Quests.ForgetOffer(questID)
end)

------------------------------------------------------------
-- DIAGNOSIS
------------------------------------------------------------

-- When a player says "it says zero and I am standing in front of one", the
-- useful reply is not a guess. It is a listing of every map that was asked,
-- what each one answered, and why each answer was rejected.
function Quests.AvailableDiagnostic(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    local report = {
        mapID  = mapID,
        maps   = {},
        counts = { start = 0, inLog = 0, completed = 0, notStart = 0, task = 0, offered = 0 },
    }

    if not mapID then
        return report
    end

    for _, relatedID in ipairs(Blizzard.RelatedMapIDs(mapID)) do
        local pois = Blizzard.GetQuestPOIsOnMap(relatedID)

        local row = {
            mapID = relatedID,
            name  = Blizzard.GetMapName(relatedID),
            pois  = #pois,
            starts = 0,
            usable = 0,
        }

        for _, poi in ipairs(pois) do
            if poi.isQuestStart and not poi.inProgress then
                row.starts = row.starts + 1

                if Blizzard.IsQuestInLog(poi.questID) then
                    report.counts.inLog = report.counts.inLog + 1
                elseif Quests.IsCompletedByCharacter(poi.questID) then
                    report.counts.completed = report.counts.completed + 1
                else
                    row.usable = row.usable + 1
                    report.counts.start = report.counts.start + 1
                end
            else
                report.counts.notStart = report.counts.notStart + 1
            end
        end

        table.insert(report.maps, row)
    end

    report.counts.task    = #Blizzard.GetTaskQuestsOnMap(mapID)
    report.counts.offered = CN.CountKeys(Quests.RecentOffers())

    return report
end

-- How many quests are on offer here that you have not taken.
--
-- This is the number a player means by "new", and it took a fourteen-year-old
-- to say so plainly. The addon used to report how many quests it had written
-- into its own database for the first time -- a scanner statistic, correct and
-- useless, which drops to zero forever once a zone has been walked. He read
-- "0 new" in a zone with exclamation marks visible on his screen and
-- concluded, reasonably, that the addon was broken.
--
-- A number shown to a player has to be about the player's world. If it is
-- about the addon's bookkeeping it belongs in debug output.
-- THE QUIET FLAG GOES THROUGH. 0.84.0.
--
-- This could not forward it, so every caller wanting a count also filed
-- every quest pin it walked past into a SavedVariable. `Quests.AvailableOnMap`
-- takes `quiet` for exactly that reason and the Journey tab passes it; the
-- Scans tab called this instead and had no way to.
function Quests.AvailableCount(mapID, quiet)
    return #Quests.AvailableOnMap(mapID, quiet)
end

------------------------------------------------------------
-- SAYING SO WHEN IT IS WORTH SAYING
------------------------------------------------------------

-- THE ADDON KNEW AND SAID NOTHING.
--
-- Walking into a zone with seven unpicked quests in it is the single most
-- common moment at which "what should I do next?" has an obvious answer, and
-- the addon computed that number on arrival and kept it to itself until
-- somebody thought to type `/cn zone`.
--
-- This is a prompt, not an action: it names a number and a command. It does
-- not accept a quest, move a waypoint, or open anything.
--
-- Bounded three ways, because a line that appears too often is a line people
-- turn off: once per zone per session, only when there are enough of them to
-- be worth a detour, and never while the player is busy.
Quests.arrivalMinimum = 3

-- ONCE PER SESSION WAS TOO ONCE.
--
-- The latch was a permanent per-session flag, so a player who logs in at nine
-- and plays until two is told about a zone the first time they enter it and
-- never again -- including after clearing it, flying to another continent,
-- and coming back four hours later to the quests they left behind. That is
-- the moment the prompt is most useful and the one moment it could not fire.
--
-- A timestamp instead of a boolean, and a long window. Long enough that
-- crossing a zone border twice while running a loop cannot re-prompt; short
-- enough that a genuine return counts as a return.
local announcedZones = {}

Quests.arrivalMemorySeconds = 7200

-- Called when the PLAYER asks the addon to rediscover what is out there --
-- `/cn discoveractive`, or the Quests tab's rescan button. The latch is a
-- record of what they have already been told, and somebody deliberately
-- asking to be told again is the one thing that clearly overrides it.
--
-- DELIBERATELY NOT CALLED FROM `DiscoverActive` ITSELF. That runs off
-- `QUEST_LOG_UPDATE` on a ten-second throttle, so wiping the latch there
-- would have replaced a seven-thousand-second window with a ten-second one --
-- and stepping into a cave and back out would re-prompt. A worse bug than the
-- one it was meant to fix, dressed as a fix.
function Quests.ForgetArrivals()
    announcedZones = {}
end

function Quests.AnnounceArrival(mapID)
    mapID = mapID or CN.GetPlayerPosition()

    if not mapID then
        return false
    end

    local announcedAt = announcedZones[mapID]

    local now = (time and time()) or 0

    if announcedAt and (now - announcedAt) < Quests.arrivalMemorySeconds then
        return false
    end

    -- In a fight is not a moment for a suggestion, and neither is a flight
    -- path: `ZONE_CHANGED_NEW_AREA` fires for every zone a taxi crosses, so a
    -- cross-continent flight was prompting about zones being flown OVER --
    -- and latching out the zone actually being flown to.
    if InCombatLockdown and InCombatLockdown() then
        return false
    end

    if UnitOnTaxi and UnitOnTaxi("player") then
        return false
    end

    local available = Quests.AvailableOnMap(mapID)

    -- THE LATCH IS SET ONLY IF SOMETHING WAS SAID.
    --
    -- It used to be set before the threshold test, and this runs on a
    -- three-second timer whose own comment concedes the quest pins may not
    -- have arrived. So a slow load meant the count was short, the zone was
    -- marked announced for the session, and the prompt never fired for it --
    -- silently, and for the zones a player most wants it in.
    if #available < Quests.arrivalMinimum then
        return false
    end

    announcedZones[mapID] = now

    local zone = Blizzard.GetMapName(mapID) or "This zone"

    CN.PrintBlock(zone .. ": " .. CN.Brand(#available)
        .. " quest" .. CN.Pluralize(#available, "")
        .. " here you have not picked up",
        {
            CN.Accent("/cn zone")
                .. CN.Muted(" routes them, nearest first."),
        })

    return true
end

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Delayed: the map is not reliable in the frame the event fires, and the
    -- quest pins arrive after it.
    --
    -- The map is captured NOW rather than read at fire time. Read three
    -- seconds later it resolves against wherever the player happens to be,
    -- which on a taxi is a different zone entirely.
    if not C_Timer or not C_Timer.After then
        return
    end

    local arrivedAt = CN.GetPlayerPosition()

    if not arrivedAt then
        return
    end

    C_Timer.After(3, function()
        -- Still there? A player who zoned again inside three seconds is not
        -- being told about the zone they left.
        if CN.GetPlayerPosition() ~= arrivedAt then
            return
        end

        pcall(Quests.AnnounceArrival, arrivedAt)
    end)
end)

function Quests.DiscoverActive()
    local entries = Blizzard.GetQuestLogEntries()

    if #entries == 0 and not C_QuestLog then
        Print("Quest Log API is unavailable.")
        return 0, 0
    end


    local seen = 0
    local new  = 0

    for _, info in ipairs(entries) do
        if Quests.RecordDiscovered(info.questID, "questlog") then
            new = new + 1
        end

        if info.title and info.title ~= "" then
            Quests.SetMetadata(info.questID, info.title, "questlog")
        end

        seen = seen + 1
    end

    -- Quests offered in this zone but not yet accepted.
    --
    -- Without these, "new" settled at zero permanently after the first scan:
    -- the only thing being discovered was your own quest log, which stops
    -- changing the moment you have scanned it once.
    for _, poi in ipairs(Quests.AvailableOnMap()) do
        if Quests.RecordDiscovered(poi.questID, "available") then
            new = new + 1
        end

        local title = Blizzard.GetQuestTitle(poi.questID, true)

        if title and title ~= "" then
            Quests.SetMetadata(poi.questID, title, "available")
        end

        if poi.x and poi.y then
            Quests.SetLocation(poi.questID, poi.mapID, poi.x, poi.y, "available")
        end

        seen = seen + 1
    end

    return seen, new
end

------------------------------------------------------------
-- STATUS
------------------------------------------------------------

-- ASKED, NOT REMEMBERED.
--
-- This used to write the answer into an account-wide `questStatus` table.
-- Both fields come from a free synchronous client call, so there was nothing
-- to gain by storing them -- and `IsQuestFlaggedCompleted` answers for the
-- character asking, so storing it account-wide meant a main's four thousand
-- completions were read back as every alt's. `/cn breakdown` on a fresh alt
-- reported the main's progress, and scanning on the alt destroyed the main's
-- record.
--
-- Migration 7 drops the store. The name is kept because callers want the pair
-- of answers, and asking through one function keeps the two questions
-- together.
function Quests.RecordStatus(questID)
    return Quests.IsCompletedByCharacter(questID),
        Quests.IsCompletedOnAccount(questID)
end

function Quests.ScanKnown()
    local scanned, byCharacter, onAccount = 0, 0, 0

    for questID in pairs(CN.Account("discoveredQuests")) do
        local characterCompleted, accountCompleted = Quests.RecordStatus(questID)

        scanned = scanned + 1

        if characterCompleted then
            byCharacter = byCharacter + 1
        end

        if accountCompleted then
            onAccount = onAccount + 1
        end
    end

    -- The only setup step that does not go through `CN.MarkScanned`, because
    -- it scans nothing collectible -- but the setup record still has to know
    -- it ran, or the login reminder asks for it forever.
    if CN.NoteSetupStep then
        CN.NoteSetupStep("quests")
    end

    -- AND THE COUNTER THE SCANS TAB MEMOISES ITS ROWS AGAINST. 0.84.0.
    --
    -- `CN.MarkScanned` bumps it for every other setup step, and this is the
    -- one step that deliberately does not go through it -- so the row the
    -- Scans tab draws for this scan stayed marked stale, with its old age,
    -- however many times the player clicked it. The Collections tab reads
    -- the same timestamp uncached and immediately said "just now", so two
    -- tabs of one window reported different ages for the same fact.
    if CN.NoteCollectionChanged then
        CN.NoteCollectionChanged()
    end

    return scanned, byCharacter, onAccount
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

-- Curated static data first, then whatever external addons know, then
-- anything harvested from this account's own play. Static wins because it is
-- the only source this addon controls and ships.
function Quests.GetRecord(questID)
    local static = CN.Static.GetQuest(questID)

    if static and (static.requires or static.obsolete or static.requiresLevel) then
        return static, "static"
    end

    local external = CN.QueryQuestDataProviders(questID)

    if external and (external.requires or external.requiresLevel) then
        return external, table.concat(external.providers or { "external" }, "+")
    end

    local harvested = CN.Account("questHarvest")[questID]

    if harvested and harvested.requires then
        return harvested, "harvested"
    end

    return static, static and "static" or nil
end

CN.RegisterEligibilityChecker(CN.objectiveTypes.QUEST, function(questID)
    local states = CN.objectiveStates

    if Quests.IsCompletedByCharacter(questID) then
        return states.COMPLETED, "Already completed by this character", nil
    end

    local static = Quests.GetRecord(questID)

    if static then
        if static.obsolete then
            return states.UNOBTAINABLE, CN.blockReasons.OBSOLETE, nil
        end

        if static.requires then
            for _, prerequisiteID in ipairs(static.requires) do
                if not Quests.IsCompletedByCharacter(prerequisiteID) then
                    return states.LOCKED,
                           CN.blockReasons.PREREQUISITE_QUEST,
                           Quests.GetName(prerequisiteID) or ("quest " .. prerequisiteID)
                end
            end
        end



        if static.requiresLevel and UnitLevel("player") < static.requiresLevel then
            return states.LOCKED, CN.blockReasons.LEVEL_TOO_LOW, tostring(static.requiresLevel)
        end

        if static.requiresFaction and CN.character
            and CN.character.faction ~= static.requiresFaction then
            return states.INELIGIBLE, CN.blockReasons.WRONG_FACTION, static.requiresFaction
        end
    end

    -- CURATED GATING (0.43.0).
    --
    -- Class, race, faction and level, from the static database. The client
    -- handles this implicitly by not drawing a pin you do not qualify for,
    -- which works while you are standing there and answers nothing when you
    -- ask "could any of my characters do this?" -- which is precisely what
    -- /cn alts is for.
    -- THE TOKEN, NOT THE SENTENCE. 0.64.0.
    --
    -- This recovered the block reason by pattern-matching the English display
    -- prose the eligibility check builds -- and since 0.61.0 that prose is
    -- partly localized, so the parser was one translation away from telling
    -- `/cn alts` that a race-gated quest was class-gated. The reason is
    -- returned as a stable token now; see the note there.
    local eligible, gateReason, gate = CN.Static.QuestEligibility(questID)

    if not eligible then
        local byGate = {
            CLASS   = CN.blockReasons.WRONG_CLASS,
            RACE    = CN.blockReasons.WRONG_RACE,
            LEVEL   = CN.blockReasons.LEVEL_TOO_LOW,
            FACTION = CN.blockReasons.WRONG_FACTION,
        }

        return states.INELIGIBLE,
            byGate[gate] or CN.blockReasons.WRONG_CLASS,
            gateReason
    end

    -- Prerequisites nobody curated, inferred from repeated observation
    -- across characters.
    --
    -- Reported as LIKELY_PREREQUISITE, never as PREREQUISITE_QUEST. The
    -- addon has watched an ordering hold on several characters; that is
    -- strong evidence and it is still not the same claim as knowing. It
    -- must not be possible to mistake one for the other in the output.
    local dependency = CN.GetDependency(
        CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID))

    if dependency and dependency.observedRequires then
        local harvest = CN:GetModule("Harvest")

        for _, prerequisiteID in ipairs(dependency.observedRequires) do
            if not Quests.IsCompletedByCharacter(prerequisiteID) then
                local name = Quests.GetName(prerequisiteID)
                    or ("quest " .. prerequisiteID)

                -- WHERE THE EDGE CAME FROM DECIDES WHAT THE LINE CAN CLAIM.
                --
                -- An imported chain was never observed by this player, so
                -- the harvest store has nothing for it and the character
                -- count came back zero -- "seen first on 0 characters",
                -- printed as evidence. Say which kind of edge it is.
                if dependency.origin == "contributed" then
                    return states.LOCKED,
                           CN.blockReasons.LIKELY_PREREQUISITE,
                           name .. " (from an imported chain, not from your "
                               .. "own play)"
                end

                local characters = harvest
                    and harvest.Confidence(harvest.Store()[questID], prerequisiteID)
                    or 0

                return states.LOCKED,
                       CN.blockReasons.LIKELY_PREREQUISITE,
                       name .. " (seen first on " .. characters
                           .. " characters)"
            end
        end
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- LOCATION
------------------------------------------------------------

-- Coordinates the player supplied by hand, for quests the client will not
-- answer for. Persisted account-wide: a location is a fact about the world,
-- not about one character.
local function Overrides()
    return CN.Account("questLocations")
end

Quests.Overrides = Overrides

-- `source` says where the coordinates came from: nil or "manual" for a
-- player typing them, "offered" for a quest giver's gossip, "available" for a
-- map pin. Two callers have always passed it and this function has always
-- ignored it -- the parameter was not even declared -- so `/cn where`
-- attributed machine-learned coordinates to the player, and the block comment
-- above describing this store as "coordinates the player supplied by hand"
-- was false in both directions.
function Quests.SetLocation(questID, mapID, x, y, source)
    if not questID or not mapID or not x or not y then
        return false
    end

    -- Accept either 0-1 or 0-100; the map API wants 0-1.
    if x > 1 then x = x / 100 end
    if y > 1 then y = y / 100 end

    if x <= 0 or x >= 1 or y <= 0 or y >= 1 then
        return false
    end

    Overrides()[questID] = {
        mapID  = mapID,
        x      = x,
        y      = y,
        setAt  = time(),
        source = source,
    }

    return true
end

-- Live client data first, then the player's own override, then curated
-- static data. Live wins because it tracks the quest's *current* step.
function Quests.GetLocation(questID)
    local mapID, x, y = Blizzard.GetQuestWaypoint(questID)

    -- A CURATED TURN-IN BEATS THE CLIENT'S MOVING WAYPOINT.
    --
    -- `Static.GetQuestTurnIn` has existed since the three-phase quest model
    -- was designed -- "a quest is a pick up, a do, and a turn in" -- with a
    -- documented schema, and was called by nothing at all: the harness's dead
    -- code check listed it by name. So the third phase, the one the design
    -- rests on, has always used the client's waypoint, which points at
    -- whatever the quest currently wants rather than at the person who takes
    -- it back.
    --
    -- Only when the quest is actually ready to hand in. Before that the
    -- client's waypoint is the better answer, because it moves with the work.
    if CN.Static and CN.Static.GetQuestTurnIn
        and Blizzard.IsQuestReadyForTurnIn
        and Blizzard.IsQuestReadyForTurnIn(questID) then

        local turnMap, turnX, turnY = CN.Static.GetQuestTurnIn(questID)

        if turnMap and turnX and turnY then
            return turnMap, turnX, turnY, "turn-in"
        end
    end

    if mapID and x and y then
        return mapID, x, y, "blizzard"
    end

    local override = Overrides()[questID]

    if override and override.mapID and override.x and override.y then
        return override.mapID, override.x, override.y, override.source or "manual"
    end

    local staticMap, staticX, staticY = CN.Static.GetQuestLocation(questID)

    if staticMap and staticX and staticY then
        return staticMap, staticX, staticY, "static"
    end

    return mapID or staticMap, nil, nil, nil
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Quests", function()
    local candidates = {}

    -- The coordinates are no longer needed here: travel cost is asked for
    -- by map and point, and CN.TravelCost reads the player's position itself
    -- so that every provider costs a journey the same way.
    local playerMap = CN.GetPlayerPosition()

    local seen = {}

    local function add(questID, name, isActive, availablePOI)
        if not questID or seen[questID] then
            return
        end

        if CN.IsIgnored(CN.objectiveTypes.QUEST, questID)
            or CN.IsDeferred(CN.objectiveTypes.QUEST, questID) then
            return
        end

        seen[questID] = true

        local mapID, x, y, source = Quests.GetLocation(questID)

        local reasons = {}
        local value   = 1

        -- NIL, NOT ZERO.
        --
        -- Zero means "you are standing on it", and `CN.IsPlaceless` reads a
        -- travelCost of zero exactly that way. `playerMap` is nil for a
        -- second or two after every loading screen -- `Travel.CostFor` says
        -- so in its own comment -- and neither branch below ran in that case,
        -- so every located quest in the log was scored as though the player
        -- were standing on top of it. It healed on the next rebuild, but
        -- arriving in a zone is precisely when somebody types `/cn next`.
        local travel, costed

        -- An available quest carries its own pin, which is more current than
        -- anything recorded earlier.
        if availablePOI then
            mapID  = availablePOI.mapID or mapID
            x      = availablePOI.x or x
            y      = availablePOI.y or y
            source = "available"

            -- Weighted above an accepted quest you have not started: going to
            -- get a quest is cheap, it is right here, and it unlocks
            -- everything that quest leads to.
            value = value + 2

            if availablePOI.offMap then
                -- Named, not "in this zone", because it is not. The zone is
                -- what makes it worth saying: "somewhere else" is not an
                -- instruction and the route needs a destination.
                local zone = CN.Blizzard.GetMapName(availablePOI.mapID)

                table.insert(reasons, "available to pick up in "
                    .. (zone or ("map " .. tostring(availablePOI.mapID))))

                -- One point, not three: going to get a quest in the next zone
                -- is still worth doing, and still not as good as one you can
                -- see from here.
                value = value - 1
            else
                table.insert(reasons, "available to pick up in this zone")
            end

            if availablePOI.isDaily then
                table.insert(reasons, "daily")
            end
        end

        -- A DEADLINE THE ADDON ALREADY KNEW AND WAS NOT ATTACHING.
        --
        -- 0.28.0 added an urgency curve that weights anything carrying
        -- `expiresIn`, and then only world quests and the Vault set it. A
        -- daily disappears at the daily reset and a weekly at the weekly one;
        -- both are knowable to the minute, and neither was being said. The
        -- headline feature of that release was close to inert.
        local expiry

        if availablePOI and availablePOI.isDaily then
            expiry = Blizzard.GetSecondsUntilDailyReset()
        elseif isActive and Blizzard.IsQuestInLog(questID) then
            local timeLeft = Blizzard.GetQuestTimeLeft(questID)

            if timeLeft and timeLeft > 0 then
                expiry = timeLeft
            end
        end

        if isActive then
            if Blizzard.IsQuestReadyForTurnIn(questID) then
                value = value + 3
                table.insert(reasons, "ready to turn in")
            else
                local done, total = Blizzard.GetQuestObjectiveProgress(questID)

                if total > 0 and done > 0 then
                    value = value + 1
                    table.insert(reasons, done .. " of " .. total .. " objectives already done")
                end
            end
        end

        local static = CN.Static.GetQuest(questID)

        if static and static.unlocks and #static.unlocks > 0 then
            value = value + #static.unlocks
            table.insert(reasons, "unlocks " .. #static.unlocks
                .. (#static.unlocks == 1 and " further quest"
                    or " further quests"))
        end

        if mapID and playerMap then
            if mapID == playerMap then
                table.insert(reasons, "in your current zone")
            end

            -- COSTED AS THE JOURNEY YOU WOULD ACTUALLY MAKE.
            --
            -- Before 0.42.0 this was a straight line within the zone and a
            -- flat 25 for anywhere else -- so the zone over the ridge and the
            -- far side of the continent cost exactly the same, and a zone
            -- with a flight master in it cost the same as one without.
            -- `CN.TravelCost` never answers nil, so the old `or travel`
            -- could only ever read the nil this starts as -- which luacheck
            -- correctly called reading an uninitialised variable.
            local measured, fromTravel = CN.TravelCost(mapID, x, y)

            travel = measured
            costed = fromTravel or nil

            if fromTravel and mapID ~= playerMap then
                table.insert(reasons, "another zone, costed by how long the "
                    .. "journey actually takes")
            end
        elseif not mapID then
            -- "I DO NOT KNOW WHERE THIS IS" IS ONE PRICE, SET IN ONE PLACE.
            --
            -- This hard-coded 5 while `CN.unknownLocationCost` is 8 -- raised
            -- from 3 in 0.57.0 with a long note explaining that anything
            -- below the cost of crossing a zone lets "no idea where this is"
            -- outrank "I can see it from here". The highest-volume provider
            -- in the addon was bypassing that decision, so a quest with NO
            -- location was cheaper than one in your own zone whose
            -- coordinates had not resolved yet.
            travel = CN.unknownLocationCost
        end

        table.insert(candidates, CN.NewObjective({
            id                = questID,
            type              = CN.objectiveTypes.QUEST,
            name              = name or Quests.GetName(questID) or ("Quest " .. questID),
            mapID             = mapID,
            x                 = x,
            y                 = y,
            source            = source,
            phase             = Quests.Phase(questID),
            state             = CN.objectiveStates.AVAILABLE,
            completionValue   = value,
            travelCost        = travel,
            travelCosted      = costed,
            expiresIn         = expiry,
            reasons           = reasons,
        }))
    end

    for _, info in ipairs(Blizzard.GetQuestLogEntries()) do
        add(info.questID, info.title, true)
    end

    -- Quests standing in this zone waiting to be picked up.
    --
    -- This is the fix for the most basic possible complaint: the addon showed
    -- only quests you had already accepted, so it could never tell you to go
    -- and get one. Picking up a quest twenty yards away is often the single
    -- best next action available, and it was invisible.
    for _, poi in ipairs(Quests.AvailableOnMap(playerMap)) do
        local name = Quests.GetName(poi.questID)
            or Blizzard.GetQuestTitle(poi.questID, true)
            or ("Quest " .. poi.questID)

        add(poi.questID, name, false, poi)
    end

    -- AND THE ZONES NEXT DOOR. 0.66.0. See `Quests.OffMapOffers`.
    --
    -- Weighted BELOW a quest available in this zone -- it is a real journey
    -- and the travel cost already says so -- but above nothing, which is what
    -- it was worth before.
    for _, pin in ipairs(Quests.OffMapOffers()) do
        -- FILTERED AGAIN HERE, AND ON PURPOSE. The shortlist's revision moves
        -- when the store grows or the player changes map, and neither of
        -- those happens when a quest is accepted or turned in -- so without
        -- this the addon would go on recommending the player go and pick up
        -- a quest they are already carrying. Twenty checks; the shortlist
        -- exists to keep the six-hundred-row walk off this path, not these.
        if not seen[pin.questID]
            and not Quests.IsCompletedByCharacter(pin.questID)
            and not Blizzard.IsQuestInLog(pin.questID) then
            local name = Quests.GetName(pin.questID)
                or Blizzard.GetQuestTitle(pin.questID, true)
                or ("Quest " .. pin.questID)

            add(pin.questID, name, false, {
                questID  = pin.questID,
                mapID    = pin.mapID,
                x        = pin.x,
                y        = pin.y,
                offMap   = true,
            })
        end
    end

    -- Curated quests that are not in the log and not yet completed.
    for questID, record in pairs(CN.Static.quests) do
        if not record.obsolete and not Quests.IsCompletedByCharacter(questID) then
            local state = CN.Explain(CN.objectiveTypes.QUEST, questID)

            if state == CN.objectiveStates.AVAILABLE then
                add(questID, record.name, false)
            end
        end
    end

    return candidates
end, { events = { "QUEST_ACCEPTED", "QUEST_TURNED_IN", "QUEST_REMOVED", "QUEST_LOG_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 2 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_DATA_LOAD_RESULT", function(event, questID, success)
    if not CN.pendingQuestLoads[questID] then
        return
    end

    CN.pendingQuestLoads[questID] = nil

    if not success then
        DebugPrint("Quest " .. tostring(questID) .. " metadata was unavailable from Blizzard.")
        return
    end

    local title = Blizzard.GetQuestTitle(questID, false)

    if title then
        Quests.SetMetadata(questID, title, "blizzard")
        Print("Quest " .. questID .. " - " .. title)
    else
        DebugPrint("Quest " .. questID .. " loaded, but no title was returned.")
    end
end)

CN:RegisterEvent("QUEST_ACCEPTED", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordDiscovered(questID, "questlog")

    local title = Blizzard.GetQuestTitle(questID, true)

    if title then
        Quests.SetMetadata(questID, title, "questlog")
    end

    Quests.RecordStatus(questID)

    DebugPrint("Quest accepted: " .. questID)
end)

CN:RegisterEvent("QUEST_TURNED_IN", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordDiscovered(questID, "questlog")
    Quests.RecordStatus(questID)

    DebugPrint("Quest turned in: " .. questID)
end)

CN:RegisterEvent("QUEST_REMOVED", function(event, questID)
    if not questID then
        return
    end

    Quests.RecordStatus(questID)

    DebugPrint("Quest removed from log: " .. questID)
end)

-- QUEST_LOG_UPDATE fires constantly; throttle a full rescan.
local lastLogScan = 0

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    local now = time()

    if now - lastLogScan < 10 then
        return
    end

    lastLogScan = now

    local seen, new = Quests.DiscoverActive()

    if new > 0 then
        DebugPrint("Quest Log scan discovered " .. new .. " new quests (" .. seen .. " active).")
    end
end)

CN:OnLogin(function()
    local seen, new = Quests.DiscoverActive()

    DebugPrint("Login quest scan: " .. seen .. " active, "
        .. new .. " newly recorded.")

    -- THE LOGIN SWEEP 0.72.0's COMMENT PROMISED AND DID NOT WRITE. 0.73.0.
    --
    -- 0.72.0 replaced the full `PruneRemembered` on every turn-in with a
    -- single-id removal, which was right -- twelve hundred client calls to
    -- forget one pin -- and justified it by saying "the login hook covers
    -- anything completed elsewhere". There was no login hook. `OnLogin` here
    -- called only `DiscoverActive`.
    --
    -- What was actually lost is the eviction of rows dead for a reason other
    -- than a turn-in: a quest ACCEPTED into the log, and a quest completed by
    -- another character on the account. Those sat until the store happened to
    -- cross its cap of six hundred, and every read filtered them at two
    -- client calls a row -- so the cost the change removed from the turn-in
    -- reappeared on the read path, which runs far more often.
    --
    -- Once, at login, is where a sweep of a persisted store belongs.
    local dropped = Quests.PruneRemembered()

    if dropped > 0 then
        DebugPrint("Pruned " .. dropped .. " remembered quest location(s).")
    end
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "quest",
    aliases = { "q" },
    args    = "<questID>",
    order   = 20,
    help    = "Check whether a quest is completed.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            Print("Usage: /cn quest <questID>")
            return
        end

        Quests.RecordDiscovered(questID, "manual")

        local characterCompleted, accountCompleted = Quests.RecordStatus(questID)

        local name = Quests.GetName(questID, true)

        if name then
            Print("Quest " .. questID .. " - " .. name .. ":")
        else
            Print("Quest " .. questID .. ":")
        end

        Print("Character completion: " .. CN.YesNo(characterCompleted))

        if Blizzard.HasAccountQuestAPI() then
            Print("Account/Warband completion: " .. CN.YesNo(accountCompleted))
        else
            Print("Account/Warband completion: |cffffc74fAPI unavailable|r")
        end

        local state, reason, detail = CN.Explain(CN.objectiveTypes.QUEST, questID)

        Print("State: " .. CN.StateLabel(state)
            .. (reason and (" " .. CN.DASH .. " " .. reason) or "")
            .. (detail and (" (" .. detail .. ")") or ""))
    end,
}

CN:RegisterCommand{
    name    = "cache",
    args    = "<questID>",
    order   = 21,
    help    = "Show cached quest metadata.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            Print("Usage: /cn cache <questID>")
            return
        end

        local cached = Quests.GetMetadata(questID)

        if cached and cached.name then
            Print("Cached quest " .. questID .. ": " .. cached.name
                .. " |cff8a8f96[" .. tostring(cached.source) .. "]|r")
        else
            Print("No cached metadata for quest " .. questID .. ".")
        end
    end,
}

CN:RegisterCommand{
    name    = "setquest",
    args    = "<questID> <name>",
    order   = 22,
    help    = "Manually save quest metadata.",
    handler = function(args)
        local questIDText, name = args:match("^(%d+)%s+(.+)$")

        local questID = CN.ToID(questIDText)

        if not questID or not name or name == "" then
            Print("Usage: /cn setquest <questID> <name>")
            return
        end

        if Quests.SetMetadata(questID, name, "manual") then
            Print("Saved quest " .. questID .. ": " .. name)
        else
            Print("Kept the existing, more authoritative name for quest " .. questID .. ".")
        end
    end,
}

CN:RegisterCommand{
    name    = "queststatus",
    args    = "<questID>",
    order   = 23,
    help    = "Show this character's completion state for a quest.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            Print("Usage: /cn queststatus <questID>")
            return
        end

        local characterCompleted, accountCompleted = Quests.RecordStatus(questID)

        Print("Quest " .. questID .. ", as the client answers right now:")
        Print("Character completion: " .. CN.YesNo(characterCompleted))
        Print("Account/Warband completion: " .. CN.YesNo(accountCompleted))
    end,
}

CN:RegisterCommand{
    name    = "scanquests",
    order   = 24,
    help    = "Scan known quest IDs for completion.",
    handler = function()
        local scanned, byCharacter, onAccount = Quests.ScanKnown()

        Print("Scanned " .. scanned .. " known quests.")
        Print("Character completed: " .. byCharacter)
        Print("Account/Warband completed: " .. onAccount)
    end,
}

CN:RegisterCommand{
    name    = "discovered",
    order   = 25,
    help    = "Show the number of discovered quests.",
    handler = function()
        Print("Discovered quests: " .. CN.CountKeys(CN.Account("discoveredQuests")))
        Print("Cached quest names: " .. CN.CountKeys(CN.Account("questMetadata")))
    end,
}

CN:RegisterCommand{
    name    = "available",
    aliases = { "pickup", "offered" },
    -- NO ARGUMENTS. This read "[zone name is not needed; uses the zone you
    -- are in]" -- a note, rendered by the help printer as an argument spec,
    -- so `/cn help` showed `/cn available [zone name is not needed; uses the
    -- zone you are in]`. The note belongs in the help text.
    order   = 13,
    help    = "List the quests offered in the zone you are in that you have "
        .. "not accepted.",
    handler = function()
        local mapID = select(1, CN.GetPlayerPosition())

        local available = Quests.AvailableOnMap(mapID)

        if #available == 0 then
            Print("Nothing here is offering you a quest you have not taken.")
            Print("|cff8a8f96That counts quest starts the map is showing. A "
                .. "giver you have not walked past yet is not on the map, so "
                .. "it is not counted.|r")
            return
        end

        local near, zone = Quests.SplitAvailableByDistance(available, mapID)

        if #near > 0 then
            Print(#near .. " quest" .. CN.Pluralize(#near, "")
                .. " available right here:")
        else
            Print(#available .. " quest" .. CN.Pluralize(#available, "")
                .. " available in this zone, none within "
                .. CN.nearbyYards .. "yd:")
        end

        for _, poi in ipairs(#near > 0 and near or zone) do
            local title = Quests.GetName(poi.questID)
                or Blizzard.GetQuestTitle(poi.questID, true)
                or ("Quest " .. poi.questID)

            local where = ""

            if poi.x and poi.y then
                where = string.format(" |cff8a8f96(%.1f, %.1f)|r",
                    poi.x * 100, poi.y * 100)
            end

            CN.PrintLine("  |cffffc74f" .. title .. "|r" .. where)
        end

        if #near > 0 and #zone > 0 then
            Print("|cff8a8f96Plus " .. #zone
                .. " further out in this zone.|r")
        end

        local tasks = Quests.TasksOnMap(mapID)

        if #tasks > 0 then
            Print("|cff8a8f96Also " .. #tasks .. " world quest"
                .. CN.Pluralize(#tasks, "")
                .. " or bonus objective in this zone" .. CN.DASH .. "no giver to talk "
                .. "to.|r")
        end

        Print("|cff8a8f96These are in your recommendations and in |r/cn zone"
            .. "|cff8a8f96 too.|r")
    end,
}

CN:RegisterCommand{
    name    = "whyzero",
    aliases = { "diagquests" },
    order   = 29,
    help    = "Explain why the available-quest count is what it is.",
    handler = function()
        local report = Quests.AvailableDiagnostic()

        if not report.mapID then
            Print("The client will not say which map you are on.")
            return
        end

        Print("Available-quest diagnosis for map " .. report.mapID
            .. " (" .. tostring(Blizzard.GetMapName(report.mapID) or "?") .. "):")

        for _, row in ipairs(report.maps) do
            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            CN.PrintLine("  " .. CN.Body(tostring(row.name or row.mapID))
                .. CN.Aside(row.pois .. " pins, " .. row.starts
                    .. " starts, " .. row.usable .. " usable"))
        end

        Print("Rejected: " .. report.counts.inLog .. " already in your log, "
            .. report.counts.completed .. " already completed, "
            .. report.counts.notStart .. " not quest starts.")

        Print("Other sources: " .. report.counts.task .. " bonus/world, "
            .. report.counts.offered .. " remembered from conversations.")

        if report.counts.start == 0 and report.counts.offered == 0 then
            Print("|cffffc74fIf you can see an exclamation mark from here, the "
                .. "client has not published that pin to any of the maps "
                .. "above. Talk to the NPC once and it will be remembered.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "discoveractive",
    order   = 26,
    help    = "Discover quests currently in the Quest Log.",
    handler = function()
        -- Somebody asking to be told what is out there overrides the record
        -- of having already told them.
        Quests.ForgetArrivals()

        local seen, recorded = Quests.DiscoverActive()

        local available = Quests.AvailableCount()

        Print("Quests: " .. seen .. " in your log, "
            .. "|cffffc74f" .. available .. "|r available to pick up nearby.")

        DebugPrint(recorded .. " newly recorded in the database.")
    end,
}

CN:RegisterCommand{
    name    = "where",
    args    = "<questID>",
    order   = 28,
    help    = "Show what location is known for a quest.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            Print("Usage: /cn where <questID>")
            return
        end

        local mapID, x, y, source = Quests.GetLocation(questID)

        Print("Quest " .. questID .. " - "
            .. (Quests.GetName(questID, true) or "unknown name"))

        if mapID and x and y then
            Print(string.format("Location: map %d at %.1f, %.1f |cff8a8f96[%s]|r",
                mapID, x * 100, y * 100, tostring(source)))
        elseif mapID then
            Print("Map " .. mapID .. " |cffffc74f(no coordinates)|r")
        else
            Print("|cffe2564cNo location is known.|r")
        end

        Print("In your quest log: " .. CN.YesNo(Blizzard.IsQuestInLog(questID)))
    end,
}

CN:RegisterCommand{
    name    = "setloc",
    args    = "<questID> <mapID> <x> <y>",
    order   = 29,
    help    = "Record coordinates for a quest by hand.",
    handler = function(args)
        local questID, mapID, x, y =
            args:match("^(%d+)%s+(%d+)%s+([%d%.]+)%s+([%d%.]+)$")

        questID = CN.ToID(questID)
        mapID   = CN.ToID(mapID)
        x       = tonumber(x)
        y       = tonumber(y)

        if not questID or not mapID or not x or not y then
            Print("Usage: /cn setloc <questID> <mapID> <x> <y>")
            -- `/cn where` WANTS A QUEST ID AND ANSWERS ABOUT THAT QUEST'S
            -- MAP, so it could never answer "what map am I on" -- and the
            -- fallback was a raw Lua dump. `/cn where am i` prints the id now.
            CN.PrintLine(CN.Muted("Coordinates may be 0-1 or 0-100. ")
                .. CN.Accent("/cn where am i")
                .. CN.Muted(" prints the map id you are standing on."))
            return
        end

        if Quests.SetLocation(questID, mapID, x, y) then
            Print("Saved location for quest " .. questID .. ".")
        else
            Print("Those coordinates are out of range.")
        end
    end,
}

CN:RegisterCommand{
    name    = "why",
    args    = "[questID]",
    order   = 27,
    help    = "Why the current recommendation, or why a quest is not offered.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            -- BARE `/cn why` ANSWERS THE OBVIOUS READING OF THE WORD.
            --
            -- It used to print a usage line. "Why" reads as "why did you
            -- recommend that", and the addon computes exactly that -- it
            -- prints it inline under `/cn next` and had no way to ask for it
            -- again afterwards. Meanwhile the command called `why` answered a
            -- different question entirely.
            --
            -- Both now, split on whether there is an id.
            local objective = CN.currentRecommendation

            if not objective then
                local results = CN.Recommend(1)

                objective = results and results[1]
            end

            if not objective then
                CN.PrintBlock("Nothing is being recommended, so there is "
                    .. "nothing to explain.", CN.ExplainEmptyList())

                return
            end

            CN.PrintBlock(
                "Why " .. CN.Primary(tostring(objective.name or objective.id))
                    .. CN.Aside(CN.TypeBadge(objective.type)),
                CN.ExplainRecommendation(objective))

            CN.PrintLine(CN.Accent("/cn why <questID>")
                .. CN.Muted(" answers why a quest is not offered to you."))

            return
        end

        local state, reason, detail = CN.Explain(CN.objectiveTypes.QUEST, questID)

        Print("Quest " .. questID .. " - " .. (Quests.GetName(questID, true) or "unknown name"))
        Print("State: " .. CN.StateLabel(state))

        if reason then
            Print("Reason: " .. reason .. (detail and (" (" .. detail .. ")") or ""))
        end

        local record, source = Quests.GetRecord(questID)

        if record and source then
            Print("Data source: |cff8a8f96" .. source .. "|r")
        else
            -- `/cn setloc` records COORDINATES and nothing else, so it
            -- cannot add the prerequisite data this line is about. Naming it
            -- here sent the player to a command that could not solve the
            -- stated problem.
            Print("|cff8a8f96No prerequisite data for this quest. "
                .. "Install AllTheThings or BtWQuests, or let the addon "
                .. "learn the ordering by playing" .. CN.DASH .. "|cffffc74f/cn harvest|r"
                .. "|cff8a8f96 shows what it has seen so far.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Reputations.lua'] = @'
-- Modules/Reputations.lua
-- Completion Navigator :: reputation, Renown, and Paragon subsystem.
--
-- The point of this module is not to show standings. The game already does
-- that. The point is to record WHERE each standing lives -- account-wide or
-- on one specific character -- because that is what decides which character
-- should do a piece of reputation work.
--
-- Storage split:
--   CN.Account("reputations")[factionID]        account-wide standings
--   character.reputations[factionID]            character-specific standings
--   CN.Account("factionNames")[factionID]       shared name cache
--
-- That split is what lets an offline alt be evaluated as a candidate.

local ADDON_NAME, CN = ...

local Reputations = CN:RegisterModule("Reputations")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function AccountStore()
    return CN.Account("reputations")
end

local function NameStore()
    return CN.Account("factionNames")
end

local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.reputations = character.reputations or {}

    return character.reputations
end

Reputations.AccountStore   = AccountStore
Reputations.CharacterStore = CharacterStore

------------------------------------------------------------
-- STANDING MODEL
------------------------------------------------------------

-- Normalizes the three different standing systems (classic 1-8 reactions,
-- friendship reputations, and Renown) into one comparable shape.
local function BuildRecord(data)
    local factionID = data.factionID

    local record = {
        factionID   = factionID,
        name        = data.name,
        reaction    = data.reaction,
        -- `standing` IS NOT STORED. 0.72.0. See `StandingText`.
        current     = (data.currentStanding or 0) - (data.currentReactionThreshold or 0),
        maximum     = (data.nextReactionThreshold or 0) - (data.currentReactionThreshold or 0),
        raw         = data.currentStanding,
        accountWide = Blizzard.IsAccountWideReputation(factionID),

        -- NO TIMESTAMP. 0.82.0. Nothing reads a reputation record's
        -- `lastSeen`; same dead field, same reason, as `mounts` above.
    }

    local friendship = Blizzard.GetFriendshipReputation(factionID)

    if friendship then
        record.kind     = "FRIENDSHIP"
        -- THE ONE STANDING THAT MUST BE KEPT, AND NAMED SO IT IS OBVIOUS.
        --
        -- A friendship's rank is a free-text string the client supplies -- "Best
        -- Friend", "Trusted" -- and it supplies it only for the character
        -- currently logged in. There is no number to re-derive it from, so
        -- this is the single case where the word itself is the data, and it
        -- is what lets the Warband view say where an ALT stands. It is
        -- deliberately not called `standing`, so that nothing reaches for it
        -- as though it were the general case.
        record.friendshipStanding = friendship.reaction
        record.current  = (friendship.standing or 0) - (friendship.reactionThreshold or 0)
        record.maximum  = (friendship.nextThreshold or 0) - (friendship.reactionThreshold or 0)
    elseif Blizzard.IsMajorFaction(factionID) then
        local major = Blizzard.GetMajorFactionData(factionID)

        record.kind = "RENOWN"

        if major then
            record.renown     = major.renownLevel
            record.current    = major.renownReputationEarned
            record.maximum    = major.renownLevelThreshold
            record.expansion  = major.expansionID
            record.unlocked   = major.isUnlocked
            record.maxedOut   = Blizzard.HasMaximumRenown(factionID)
            -- THE CLIENT'S OWN WORD FOR IT. 0.65.0.
            --
            -- Every other `standing` on a record is localized -- the client's
            -- `FACTION_STANDING_LABEL<n>` for a standard faction, its own
            -- friendship reaction for a friendship one -- and this one was
            -- hardcoded English AND persisted, so an alt's row was also
            -- frozen at whatever language that character last scanned in. A
            -- German player read "Standing: Renown 12" for one faction and
            -- "Standing: Ehrfürchtig" for the next.
            --
            -- Same defect 0.64.0 fixed for Alliance and Horde on the Warband
            -- roster, one file over. `RENOWN_LEVEL_LABEL` is a client global.
            record.renownLevel = major.renownLevel or 0
        end
    else
        record.kind = "STANDARD"
    end

    if Blizzard.IsFactionParagon(factionID) then
        local value, threshold, questID, pending = Blizzard.GetParagonInfo(factionID)

        -- PARAGON VALUE IS CUMULATIVE. THE BAR IS NOT. FIXED IN 0.61.0.
        --
        -- `C_Reputation.GetFactionParagonInfo` returns the total reputation
        -- earned since the faction went Paragon, ACROSS every cache already
        -- collected -- it does not reset. The addon stored it raw and printed
        -- it against the threshold, so a player three caches in read
        -- "Paragon: 34500/10000". Nonsense on its face, and worse than
        -- nonsense as a progress source: anything reading it as a fraction
        -- saw 345% and clamped to a full bar forever.
        --
        -- The threshold is the size of ONE cycle, so the position inside the
        -- current cycle is the remainder, and the number of completed cycles
        -- is the quotient -- which is itself worth showing, because "you have
        -- had eleven caches out of this" is exactly the kind of thing a
        -- completionist wants to know.
        --
        -- One subtlety: when a cache is PENDING the value has already crossed
        -- the threshold and the remainder has wrapped to near zero. Showing a
        -- nearly empty bar next to "REWARD READY" reads as a contradiction,
        -- so a pending cycle is reported as full.
        local within, cycles = value, 0

        if type(value) == "number" and type(threshold) == "number"
            and threshold > 0 then

            cycles = math.floor(value / threshold)
            within = value % threshold

            if pending then
                -- The finished cycle, not the one it has already rolled into.
                within = threshold
                cycles = math.max(0, cycles - 1)
            end
        end

        record.paragon = {
            -- What to draw and print.
            value     = within,
            threshold = threshold,

            -- How many caches this faction has already produced.
            cycles    = cycles,

            -- Kept because it is the only thing the client actually said,
            -- and `/cn navdiag` compares stored values against live ones.
            rawValue  = value,

            questID   = questID,
            pending   = pending and true or false,
        }
    end

    return record
end

Reputations.BuildRecord = BuildRecord

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Reputations.Scan()
    local accountStore   = AccountStore()
    local characterStore = CharacterStore()
    local nameStore      = NameStore()

    local total, accountWide, characterSpecific, pendingParagon = 0, 0, 0, 0

    Blizzard.WithAllFactionsExpanded(function()
        for index = 1, Blizzard.GetNumFactions() do
            local data = Blizzard.GetFactionByIndex(index)

            -- Plain headers carry no standing; headers WITH rep do.
            local hasStanding = data
                and data.factionID
                and data.factionID > 0
                and ((not data.isHeader) or data.isHeaderWithRep)

            if hasStanding then
                local record = BuildRecord(data)

                nameStore[data.factionID] = record.name

                -- ONE SCOPE PER FACTION, AND THE OTHER ONE IS DELETED.
                --
                -- `Reputations.Get` returns the account record whenever one
                -- exists, and `Scan` only ever ADDED -- so a faction Blizzard
                -- moved from account-wide to character-specific in a patch
                -- kept its stale account row winning forever, and every
                -- character read whichever character last scanned it.
                -- Blizzard has moved factions in both directions across
                -- patches.
                --
                -- Writing one scope now clears the other, so the store can
                -- never hold two answers for one faction.
                if record.accountWide then
                    accountStore[data.factionID] = record

                    if characterStore then
                        characterStore[data.factionID] = nil
                    end

                    accountWide = accountWide + 1
                elseif characterStore then
                    characterStore[data.factionID] = record
                    accountStore[data.factionID]   = nil

                    characterSpecific = characterSpecific + 1
                end

                if record.paragon and record.paragon.pending then
                    pendingParagon = pendingParagon + 1
                end

                total = total + 1
            end
        end
    end)

    if CN.character then
        CN.character.reputationsScanned = time()
    end

    CN.MarkScanned("reputations")

    return total, accountWide, characterSpecific, pendingParagon
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

function Reputations.Get(factionID, character)
    local account = AccountStore()[factionID]

    if account then
        return account, "account"
    end

    local store = CharacterStore(character)

    if store and store[factionID] then
        return store[factionID], "character"
    end

    return nil, nil
end

-- Accepts a faction ID or a case-insensitive name fragment.
function Reputations.Resolve(text)
    local factionID = CN.ToID(text)

    if factionID then
        return factionID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    -- NAMED LIVE, LIKE TITLES AND CURRENCIES. 0.70.0.
    --
    -- Migration 18 converted `Titles.Resolve` and `Currencies.Resolve` off
    -- their persisted name stores, because a store fills with names frozen at
    -- whatever language last scanned -- so a player who changed client
    -- language could not find their own by name. This is the third `Resolve`
    -- of the same shape and it was not converted: `/cn rep Ehrenfeste` and
    -- `/cn goal reputation Ehrenfeste` answered nothing, in the same session
    -- where `/cn hidden` -- which asks the client first -- printed the German
    -- name correctly.
    --
    -- The store is still the fallback: unlike titles and currencies, the
    -- client will not name a faction the character has never encountered.
    for id in pairs(NameStore()) do
        local name = Reputations.NameOf(id)

        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil, matches
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id, matches
end

------------------------------------------------------------
-- WARBAND
------------------------------------------------------------

-- A RECORD'S STANDING, DERIVED, NOT READ. 0.66.0.
--
-- Migration 18 dropped `standing` from every Renown record, because it had
-- been persisted as hardcoded English. That was right, and the WRITER was
-- given `CN.RenownLabel` in the same release -- but four readers went on
-- printing the field through `tostring`, which renders a missing value as the
-- four-letter word. Only the logged-in character's rows are rewritten at
-- login, so every ALT's major-faction row printed `Best character:
-- Ravencrest-Zeddicus (nil)` in `/cn rep`, `/cn who rep` and `/cn alts` until
-- that alt was played.
--
-- Tenth application of one rule: derive what the client can name, in the
-- language of whoever is READING it, from the number that was worth keeping.
function Reputations.StandingText(record)
    if type(record) ~= "table" then
        return nil
    end

    if record.kind == "RENOWN" then
        return CN.RenownLabel(record.renownLevel or record.renown or 0)
    end

    -- ONLY THE ONE THE CLIENT CANNOT RE-SUPPLY. 0.72.0.
    --
    -- This read `record.standing` in preference to deriving, and
    -- `BuildRecord` wrote that field on every scan -- including for RENOWN,
    -- which migration 18 exists to strip. So the migration was undone by the
    -- next `/cn repscan`, and every alt's row was frozen at the language and
    -- the rank that character last scanned in: a German player reading
    -- "Ehrfürchtig" for one faction and "Renown 12" for the next, which is
    -- the exact symptom 0.65.0 and 0.66.0 were both written to end.
    --
    -- `reaction` and `renownLevel` are numbers and are kept. The word is
    -- derived, in the language of whoever is reading it.
    if record.kind == "FRIENDSHIP" and record.friendshipStanding
        and record.friendshipStanding ~= "" then

        return record.friendshipStanding
    end

    return Blizzard.GetStandingLabel(record.reaction)
end

-- A FACTION'S NAME, FROM THE CLIENT, FALLING BACK TO THE STORE. 0.70.0.
--
-- Eleventh of these; see `Achievements.NameOf` for the first. The fallback is
-- real here in a way it was not for titles and currencies: `GetFactionByID`
-- answers for factions the character has met, and the store is how the addon
-- can still name one an alt has never encountered.
function Reputations.NameOf(factionID)
    local data = Blizzard.GetFactionByID and Blizzard.GetFactionByID(factionID)

    if data and data.name and data.name ~= "" then
        return data.name
    end

    return NameStore()[factionID]
end

-- Returns the best-standing character for a character-specific faction, so
-- the recommendation engine can say "switch to this alt instead".
function Reputations.BestCharacterFor(factionID)
    if AccountStore()[factionID] then
        return nil, nil, CN.scopes.ACCOUNT
    end

    local bestKey, bestRecord

    for key, character in CN.Characters() do
        local record = character.reputations and character.reputations[factionID]

        if record then
            local better

            if not bestRecord then
                better = true
            elseif (record.renown or 0) ~= (bestRecord.renown or 0) then
                better = (record.renown or 0) > (bestRecord.renown or 0)
            elseif (record.reaction or 0) ~= (bestRecord.reaction or 0) then
                better = (record.reaction or 0) > (bestRecord.reaction or 0)
            else
                better = (record.raw or 0) > (bestRecord.raw or 0)
            end

            if better then
                bestKey    = key
                bestRecord = record
            end
        end
    end

    return bestKey, bestRecord, nil
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Reputations.Summary()
    local account   = AccountStore()
    local character = CharacterStore() or {}

    local counts = {
        account          = CN.CountKeys(account),
        character        = CN.CountKeys(character),
        renown           = 0,
        maxedRenown      = 0,
        paragonPending   = 0,
        exalted          = 0,
    }

    local function tally(store)
        for _, record in pairs(store) do
            if record.kind == "RENOWN" then
                counts.renown = counts.renown + 1

                if record.maxedOut then
                    counts.maxedRenown = counts.maxedRenown + 1
                end
            end

            if record.reaction and record.reaction >= 8 then
                counts.exalted = counts.exalted + 1
            end

            if record.paragon and record.paragon.pending then
                counts.paragonPending = counts.paragonPending + 1
            end
        end
    end

    tally(account)
    tally(character)

    return counts
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.REPUTATION, function(factionID)
    local states = CN.objectiveStates

    local record, scope = Reputations.Get(factionID)

    if not record then
        return states.UNKNOWN, "No standing recorded; run /cn repscan", nil
    end

    if record.kind == "RENOWN" then
        if record.unlocked == false then
            return states.LOCKED, CN.blockReasons.CAMPAIGN_INCOMPLETE,
                   Reputations.NameOf(factionID)
        end

        if record.maxedOut and not (record.paragon and record.paragon.pending) then
            return states.COMPLETED, "Maximum Renown reached",
                   Reputations.NameOf(factionID)
        end

        return states.AVAILABLE, nil, nil
    end

    if record.reaction and record.reaction >= 8
        and not (record.paragon and record.paragon.pending) then
        return states.COMPLETED, "Exalted", Reputations.NameOf(factionID)
    end

    if scope == "character" then
        local bestKey, bestRecord = Reputations.BestCharacterFor(factionID)

        if bestKey and bestKey ~= CN.characterKey and bestRecord then
            local mine = record.reaction or 0

            if (bestRecord.reaction or 0) > mine then
                return states.REQUIRES_OTHER_CHARACTER,
                       CN.blockReasons.BETTER_CHARACTER,
                       bestKey .. " is "
                           .. tostring(Reputations.StandingText(bestRecord))
            end
        end
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Reputations", function()
    -- SCORE FIRST, ALLOCATE SECOND.
    --
    -- The previous version built a full objective -- table, reasons array,
    -- formatted strings -- for every faction that was not yet exalted, then
    -- threw all but sixty of them away. At retail scale that is five hundred
    -- allocations to keep sixty, on every rebuild, and it was the single most
    -- expensive provider in the addon at nearly three milliseconds.
    --
    -- Evaluating is arithmetic on fields that already exist. Only the
    -- survivors are built.
    local scored = {}

    local function evaluate(record, accountWide)
        if not record or not record.factionID then
            return nil
        end

        if CN.IsIgnored(CN.objectiveTypes.REPUTATION, record.factionID)
            or CN.IsDeferred(CN.objectiveTypes.REPUTATION, record.factionID) then
            return nil
        end

        local value = 1

        if record.paragon and record.paragon.pending then
            value = value + 3
        elseif record.kind == "RENOWN" and record.maxedOut then
            return nil
        elseif record.reaction and record.reaction >= 8 then
            return nil
        end

        if accountWide then
            value = value + 1
        end

        if record.maximum and record.maximum > 0 and record.current then
            if (record.current / record.maximum) >= 0.75 then
                value = value + 1
            end
        end

        return value
    end

    local function build(record, accountWide, value)
        local reasons = {}

        if record.paragon and record.paragon.pending then
            table.insert(reasons, "a Paragon reward is waiting to be collected")
        end

        if accountWide then
            table.insert(reasons, "account-wide, so any character's progress counts")
        end

        if record.maximum and record.maximum > 0 and record.current then
            local fraction = record.current / record.maximum

            if fraction >= 0.75 then
                table.insert(reasons, string.format(
                    "%s of the way to the next standing",
                    CN.PercentText(fraction)))
            end
        end

        return CN.NewObjective({
            id              = record.factionID,
            type            = CN.objectiveTypes.REPUTATION,
            -- NAMED LIVE. 0.71.0: the store holds whatever language last
            -- scanned, and only factions THIS character has met are
            -- rewritten -- so an account-wide row met by the main kept its
            -- old name on every other character and in every other language.
            name            = Reputations.NameOf(record.factionID),
            accountWide     = accountWide,
            completionValue = value,
            reasons         = reasons,
        })
    end

    -- AND THE WRAPPERS WENT TOO. 0.61.0.
    --
    -- 0.57.0 stopped BUILDING five hundred objectives to keep sixty, which
    -- was the expensive half. What it left behind was five hundred little
    -- `{ record, accountWide, value }` tables -- one per surviving faction,
    -- allocated on every rebuild, existing only to be sorted and then
    -- dropped. Measured at retail scale: 138 KB of the 482 KB this addon
    -- allocated per cold rebuild came from this one loop.
    --
    -- An index array with two parallel flat arrays sorts exactly as well and
    -- allocates three tables instead of five hundred. The comparator reads
    -- the same two fields; it just reaches them by index.
    local order       = {}
    local scoredValue = {}
    local scoredWide  = {}

    local function gather(store, accountWide)
        for _, record in pairs(store or {}) do
            local value = evaluate(record, accountWide)

            if value then
                local slot = #scored + 1

                scored[slot]      = record
                scoredValue[slot] = value
                scoredWide[slot]  = accountWide

                order[#order + 1] = slot
            end
        end
    end

    gather(AccountStore(), true)
    gather(CharacterStore(), false)

    -- Highest value first, ties broken by faction so the cut is stable
    -- between rebuilds rather than shuffling.
    table.sort(order, function(a, b)
        if scoredValue[a] == scoredValue[b] then
            return (scored[a].factionID or 0) < (scored[b].factionID or 0)
        end

        return scoredValue[a] > scoredValue[b]
    end)

    local limit = math.min(#order, CN.providerCandidateCap)

    local candidates = {}

    for index = 1, limit do
        local slot = order[index]

        candidates[index] =
            build(scored[slot], scoredWide[slot], scoredValue[slot])
    end

    CN.providerTruncation["Reputations"] = {
        considered = #order,
        dropped    = #order - limit,
    }

    return candidates
end, { events = { "UPDATE_FACTION" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- UPDATE_FACTION fires on nearly every reputation tick. Throttle hard.
local lastScan = 0

CN:RegisterEvent("UPDATE_FACTION", function()
    local now = time()

    if now - lastScan < 15 then
        return
    end

    lastScan = now

    local total = Reputations.Scan()

    DebugPrint("Reputation scan: " .. total .. " factions.")
end)

CN:RegisterEvent("MAJOR_FACTION_RENOWN_LEVEL_CHANGED", function(event, factionID, newLevel)
    lastScan = 0

    DebugPrint("Renown changed for faction " .. tostring(factionID)
        .. " to " .. tostring(newLevel) .. ".")

    Reputations.Scan()
end)

CN:RegisterEvent("MAJOR_FACTION_UNLOCKED", function(event, factionID)
    lastScan = 0

    Reputations.Scan()

    DebugPrint("Major faction unlocked: " .. tostring(factionID))
end)

CN:OnLogin(function()
    local total, accountWide, characterSpecific = Reputations.Scan()

    DebugPrint("Login reputation scan: " .. total .. " factions ("
        .. accountWide .. " account-wide, " .. characterSpecific .. " character).")
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "repscan",
    order   = 40,
    help    = "Rescan every reputation and record its scope.",
    handler = function()
        local total, accountWide, characterSpecific, paragon = Reputations.Scan()

        Print("Scanned " .. total .. " factions.")
        Print("Account-wide: " .. accountWide)
        Print("Character-specific: " .. characterSpecific)

        if paragon > 0 then
            Print("Paragon rewards waiting: |cff73b873" .. paragon .. "|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "reps",
    order   = 41,
    help    = "Summarize reputation progress.",
    handler = function()
        local counts = Reputations.Summary()

        if counts.account + counts.character == 0 then
            Print("No reputation data yet. Run /cn repscan.")
            return
        end

        Print("Account-wide factions: " .. counts.account)
        Print("Character-specific factions: " .. counts.character)
        Print("Renown factions: " .. counts.renown
            .. " (" .. counts.maxedRenown .. " maxed)")
        Print("Exalted: " .. counts.exalted)

        if counts.paragonPending > 0 then
            Print("Paragon rewards waiting: |cff73b873" .. counts.paragonPending .. "|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "rep",
    args    = "<factionID or name>",
    order   = 42,
    help    = "Show one faction's standing and scope.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn rep <factionID or name>")
            return
        end

        local factionID, matches = Reputations.Resolve(args)

        if not factionID then
            Print("No known faction matches: " .. args)
            Print("Run /cn repscan first if you have not this session.")
            return
        end

        local record, scope = Reputations.Get(factionID)

        if not record then
            Print("No standing recorded for faction " .. factionID .. ".")
            return
        end

        Print(Reputations.NameOf(factionID) .. " |cff8a8f96(" .. factionID .. ")|r")
        Print("Standing: " .. tostring(Reputations.StandingText(record))
            .. " - " .. tostring(record.current) .. "/" .. tostring(record.maximum))
        Print("Scope: " .. (record.accountWide
            and "|cff73b873account-wide (Warband)|r"
            or "|cffffc74fcharacter-specific|r"))

        if record.kind == "RENOWN" then
            Print("Renown: " .. tostring(record.renown)
                .. (record.maxedOut and " |cff73b873(maximum)|r" or ""))
        end

        if record.paragon then
            local cycles = record.paragon.cycles or 0

            Print("Paragon: " .. tostring(record.paragon.value)
                .. "/" .. tostring(record.paragon.threshold)
                .. (cycles > 0 and CN.Muted(
                    "  (" .. cycles .. (cycles == 1
                        and " cache already earned)"
                        or " caches already earned)")) or "")
                .. (record.paragon.pending and " |cff73b873REWARD READY|r" or ""))
        end

        if scope == "character" then
            local bestKey, bestRecord = Reputations.BestCharacterFor(factionID)

            if bestKey and bestKey ~= CN.characterKey and bestRecord then
                Print("Best character: " .. bestKey
                    .. " (" .. tostring(Reputations.StandingText(bestRecord))
                    .. ")")
            end
        end

        if matches and #matches > 1 then
            Print("|cff8a8f96" .. (#matches - 1) .. " other name match(es); use the ID to be exact.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "paragon",
    order   = 43,
    help    = "List Paragon rewards ready to collect.",
    handler = function()
        local found = 0

        local function report(store, scopeLabel)
            for factionID, record in pairs(store) do
                if record.paragon and record.paragon.pending then
                    CN.PrintLine(Reputations.NameOf(factionID)
                        .. " |cff8a8f96(" .. scopeLabel .. ")|r"
                        .. " - reward ready")
                    found = found + 1
                end
            end
        end

        report(AccountStore(), "account")

        local characterStore = CharacterStore()

        if characterStore then
            report(characterStore, "character")
        end

        if found == 0 then
            Print("No Paragon rewards are waiting.")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Achievements.lua'] = @'
-- Modules/Achievements.lua
-- Completion Navigator :: achievements and their criteria.
--
-- Achievements are account-wide in retail, so completion lives in account
-- storage. Only incomplete achievements are stored in detail: keeping a row
-- for all ~3000 completed ones would triple the SavedVariables file to say
-- something the client can answer instantly.
--
-- The useful signal here is *near-completion*: an achievement sitting at
-- 9 of 10 criteria is worth far more attention than one at 0 of 10, and
-- nothing else in the addon surfaces that.

local ADDON_NAME, CN = ...

local Achievements = CN:RegisterModule("Achievements")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- An achievement's name, from the client, falling back to whatever an older
-- database still carries.
--
-- Names and point values used to be stored for every tracked achievement --
-- 394 KB at retail scale, in a file the game rewrites on every logout, and
-- every byte of it re-derivable from `GetAchievementInfo` in microseconds.
local function NameOf(achievementID, record)
    local live = CN.Blizzard.GetAchievementName(achievementID)

    if live then
        return live
    end

    return (record and record.name) or ("Achievement " .. tostring(achievementID))
end

local function Store()
    return CN.Account("achievements")
end

Achievements.Store  = Store
Achievements.NameOf = NameOf

-- CRITERIA PROGRESS IS THE CHARACTER'S; THE EARNED FLAG IS THE ACCOUNT'S.
-- 0.74.0.
--
-- The third and last store with this defect. `Loremaster` was split in
-- 0.61.0 and `Exploration` in 0.64.0, each with a paragraph explaining that a
-- criterion counted by questing or killing is counted per character while the
-- achievement itself is earned account-wide. This file was written the same
-- way and never revisited, so `record.done` held whichever character scanned
-- last.
--
-- What that does to a player: `IsNearlyDone` drives the shortlist, which
-- drives `/cn next`. An alt at 2 of 40 inherited the main's 38 of 40, was
-- told it was two criteria from finishing something it had barely started,
-- and was sent across the world to do it.
--
-- Same shape as the two siblings: `progress` keyed by character, with the
-- flat field kept as the current character's value so an older database still
-- reads correctly and nothing downstream had to change.
function Achievements.DoneFor(record, characterKey)
    if type(record) ~= "table" then
        return 0
    end

    characterKey = characterKey or CN.characterKey or CN.GetCharacterKey()

    if record.progress and record.progress[characterKey] ~= nil then
        return record.progress[characterKey]
    end

    -- Only the CURRENT character may fall back to the flat field: it holds
    -- whoever scanned last, which is the defect, and attributing it to a
    -- named other character would tell the same lie somewhere new.
    if characterKey == (CN.characterKey or CN.GetCharacterKey()) then
        return record.done or 0
    end

    return nil
end

-- THE ONE WRITER, so the scan and the criteria sweep cannot record progress
-- differently, and so both file it under the character it belongs to.
function Achievements.NoteProgress(record, done)
    if type(record) ~= "table" or done == nil then
        return
    end

    local key = CN.characterKey or CN.GetCharacterKey()

    record.progress = record.progress or {}
    record.progress[key] = done

    -- `record.done` IS NOT WRITTEN. 0.75.0.
    --
    -- 0.74.0 introduced this function to split the store per character and
    -- then wrote the flat field anyway, which is the field `DoneFor` falls
    -- back to for a character that has no reading of its own -- so the split
    -- existed and changed nothing. `Loremaster` stopped writing it in 0.66.0
    -- and `Exploration` carries a paragraph on why.
end

-- Bumped whenever the store is rewritten, so the candidate provider knows
-- when its shortlist is stale. See CN.Shortlist.
Achievements.revision = 0

-- Within two criteria of finished. Everything else is a project rather than
-- a next action, and there are three thousand of them.
Achievements.nearlyDoneThreshold = 2

local function IsNearlyDone(record)
    local criteria = record and record.criteria or 0

    if criteria <= 0 then
        return false
    end

    local remaining = criteria - (Achievements.DoneFor(record) or 0)

    return remaining > 0 and remaining <= Achievements.nearlyDoneThreshold
end

Achievements.IsNearlyDone = IsNearlyDone

-- The shortlist: only the rows a provider could possibly use.
function Achievements.Shortlist()
    return CN.Shortlist("Achievements", Achievements.revision, function()
        local list = {}

        for achievementID, record in pairs(Store()) do
            if IsNearlyDone(record) then
                table.insert(list, { id = achievementID, record = record })
            end
        end

        -- Deterministic order, so the cut is stable between rebuilds.
        table.sort(list, function(a, b) return a.id < b.id end)

        return list
    end)
end

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

-- Walking every category is a few thousand calls. That is fine on demand,
-- but it must never run on a frequent event.
function Achievements.Scan()
    if not GetCategoryList then
        return 0, 0, 0
    end

    local store = Store()

    -- NOT WIPED ANY MORE. 0.75.0.
    --
    -- `Wipe` emptied the ACCOUNT store and refilled it from the character
    -- running the scan, so every other character's criteria readings were
    -- destroyed on every `/cn achievescan` -- which is the whole thing the
    -- per-character split added in 0.74.0 exists to keep. The split was
    -- inert: the scan never called its writer, and the writer wrote the flat
    -- field the split was meant to retire.
    --
    -- Rows the client no longer returns are dropped explicitly below instead,
    -- which is what the wipe was actually for.
    local seen = {}

    -- How many rows the criteria API actually answered about. See the guard
    -- below: a scan that answered for nothing must not prune, stamp, or
    -- record itself.
    local answered = 0

    -- Which categories the client actually populated this time.
    local answeringCategories = {}

    -- Achievements the client reported no criteria for, held back until the
    -- guard below has decided whether the criteria API answered at all. See
    -- the note at the gate.
    local criteriaLess = {}

    Achievements.revision = Achievements.revision + 1

    local scanned, completed, nearlyDone = 0, 0, 0

    for _, categoryID in ipairs(Blizzard.GetAchievementCategories()) do
        local total = Blizzard.GetCategoryCounts(categoryID)

        -- `achievementTotals` IS NOT WRITTEN ANY MORE. 0.64.0.
        --
        -- A per-category snapshot of numbers `GetAchievementTotals` answers
        -- in one call, persisted, re-parsed at every login, rewritten at
        -- every logout -- and read by nothing at all. `Achievements.Summary`
        -- takes its totals live; the only other reference in the tree is the
        -- field-stripper in a migration.
        --
        -- The same class migrations 4, 5, 14, 15 and 16 exist to remove.

        for index = 1, total do
            local achievement = Blizzard.GetAchievementInCategory(categoryID, index)

            if achievement then
                scanned = scanned + 1

                -- REACHED, NOT STORED. 0.76.0.
                --
                -- 0.75.0 marked a row seen only inside the branch that
                -- stored it -- and that branch is gated on THIS character's
                -- progress. So on an alt, every achievement the main had
                -- progress on and the alt did not was neither stored nor
                -- marked, and the prune below deleted the row, taking the
                -- main's readings with it.
                --
                -- `/cn achievescan` on a fresh alt therefore destroyed the
                -- main's criteria data for nearly every achievement: exactly
                -- the loss 0.75.0 removed the store wipe to prevent, brought
                -- straight back as a character-relative prune.
                --
                -- The prune's job is to drop what the GAME no longer returns.
                -- That is what this records.
                seen[achievement.achievementID] = true

                -- AND WHICH CATEGORY ANSWERED. See the prune below: the walk
                -- is per category and 0.76.0 gated the prune on a whole-store
                -- counter, so one expansion answering licensed the deletion
                -- of every row in the ones that did not.
                answeringCategories[categoryID] = true

                if achievement.completed then
                    completed = completed + 1
                else
                    local done, criteria =
                        Blizzard.GetAchievementProgress(achievement.achievementID)

                    -- THE CLIENT ANSWERING IS THE CLIENT ANSWERING. 0.86.0.
                    --
                    -- `answered` is this scan's test for "did the criteria
                    -- API refuse", and it was incremented only inside the
                    -- store gate below -- which is reached only when the row
                    -- has PROGRESS. So a character with no progress on any
                    -- incomplete achievement was indistinguishable from a
                    -- client that answered nothing: the scan took the refusal
                    -- path, recorded nothing, never stamped itself done, and
                    -- never called `MarkScanned`.
                    --
                    -- That character is a fresh alt -- exactly the one the
                    -- per-character scan record exists for -- and the result
                    -- was a login reminder that nagged for the life of the
                    -- character, with no command that could clear it.
                    --
                    -- An achievement at 0 of 12 is a real answer.
                    if criteria and criteria > 0 then
                        answered = answered + 1
                    end

                    -- Store only what is unfinished, and only if there is
                    -- real progress or it is small enough to be actionable.
                    --
                    -- A ZERO IS NOT AN ANSWER UNTIL THE SWEEP HAS HAD ONE.
                    -- 0.89.0.
                    --
                    -- `GetAchievementProgress` answers `0, 0` when the
                    -- criteria API is cold, which the note above calls
                    -- routine for a window after logging in -- and when it is
                    -- cold it is cold for EVERY row. So a cold `/cn setup`
                    -- took this branch for every incomplete achievement in
                    -- the game and wrote a `criteria = 0` row for each.
                    --
                    -- Those rows were then unrepairable: a later warm scan
                    -- reads `criteria = 12, done = 0`, and this gate is false
                    -- for both halves, so the branch is never entered again.
                    -- The prune keeps them, because they are in `seen`. The
                    -- result was thousands of junk rows rewritten to disk on
                    -- every logout, in the store whose own header says
                    -- keeping a row for each completed achievement would
                    -- triple the saved-variables file -- and `/cn achievements`
                    -- printing "Tracked in progress: 3000".
                    --
                    -- The refusal check below already knows whether the API
                    -- answered at all. Hold the criteria-less rows until it
                    -- has decided.
                    if criteria == 0 then
                        table.insert(criteriaLess, {
                            achievementID = achievement.achievementID,
                            categoryID    = categoryID,
                            done          = done,
                        })
                    elseif done > 0 then
                        -- THROUGH THE ONE WRITER, AND ON TOP OF WHAT IS
                        -- ALREADY THERE. 0.75.0.
                        --
                        -- This built a fresh table literal, so it never
                        -- created a `progress` entry at all -- the split
                        -- added in 0.74.0 had no writer -- and it discarded
                        -- every other character's reading in the same
                        -- statement.
                        local held = store[achievement.achievementID] or {}

                        held.achievementID = achievement.achievementID
                        held.categoryID    = categoryID

                        -- NOT OVER GOOD DATA WITH NOTHING. 0.76.0.
                        --
                        -- `GetAchievementProgress` answers `0, 0` when the
                        -- criteria API is unavailable, which is routine for a
                        -- window after logging in -- and `/cn setup`, by this
                        -- addon's own note, is most often run exactly then.
                        -- This wrote the refusal straight in: a stored 40
                        -- became 0, `IsNearlyDone` went false, and the row
                        -- left the shortlist.
                        --
                        -- The guard `Exploration` has carried since 0.61.0,
                        -- `Loremaster` since 0.71.0, and that this file's own
                        -- criteria sweep four hundred lines down already had.
                        --
                        -- IT MOVED UP A LEVEL IN 0.89.0. A zero no longer
                        -- reaches this branch at all: it is held back until
                        -- the sweep has proved the criteria API answers, and
                        -- written by the loop after that guard, which is
                        -- where the "never overwrite a stored count with a
                        -- refusal" test now lives. `criteria` is positive
                        -- here by construction, so the two arms that used to
                        -- stand here would both be dead code.
                        held.criteria = criteria

                        Achievements.NoteProgress(held, done)

                        store[achievement.achievementID] = held

                        -- THROUGH THE ONE RULE. 0.62.0.
                        --
                        -- This and `Summary` each hardcoded
                        -- `done >= criteria - 2`, neither guarded
                        -- `remaining > 0`, and `IsNearlyDone` -- the rule the
                        -- provider actually uses -- reads a published
                        -- threshold field. Three copies, one of them
                        -- authoritative: changing the threshold silently
                        -- desynchronised what `/cn achievescan` and
                        -- `/cn achievements` report from the shortlist the
                        -- addon works off, and both counted finished
                        -- achievements as nearly finished.
                        if IsNearlyDone(held) then
                            nearlyDone = nearlyDone + 1
                        end
                    end
                end
            end
        end
    end

    -- AND A SCAN THE CLIENT WOULD NOT ANSWER FOR CHANGES NOTHING. 0.76.0.
    --
    -- Pruning, stamping and recording all follow from having read something.
    -- A cold scan that read nothing would otherwise delete every row it could
    -- not confirm, mark itself done, and silence the reminder that would have
    -- sent the player back.
    if answered == 0 then
        DebugPrint("Achievement scan answered for nothing; not recording it.")

        return scanned, completed, nearlyDone, 0
    end

    -- THE CRITERIA-LESS ROWS, now that the sweep has proved the API answers.
    -- A genuinely criteria-less achievement is a real thing and belongs in
    -- the store; a whole client's worth of zeros is not.
    for _, row in ipairs(criteriaLess) do
        local held = store[row.achievementID] or {}

        held.achievementID = row.achievementID
        held.categoryID    = row.categoryID

        -- A stored `criteria > 0` is never overwritten with a zero.
        if held.criteria == nil then
            held.criteria = 0

            Achievements.NoteProgress(held, row.done)
        end

        store[row.achievementID] = held
    end

    -- ROWS THE CLIENT NO LONGER RETURNS, dropped explicitly. This is what the
    -- wipe at the top used to accomplish, without taking every other
    -- character's readings with it.
    -- PER CATEGORY, NOT PER SCAN. Corrected in 0.77.0; see the sibling in
    -- `Modules/Loremaster.lua` for the whole argument. A row whose category
    -- did not answer is not a row the game has stopped returning -- it is a
    -- row nobody asked about -- and a row with no stored category has nothing
    -- to check against.
    for achievementID, record in pairs(store) do
        local categoryID = type(record) == "table" and record.categoryID

        if not seen[achievementID] and categoryID
            and answeringCategories[categoryID] then

            store[achievementID] = nil
        end
    end

    -- AND THE SCAN IS RECORDED PER CHARACTER. 0.75.0.
    --
    -- `CN.MarkScanned` is account-wide, and `Setup.HasRun` reads account-wide
    -- stamps -- so an alt that had never scanned was never prompted to, and
    -- silently read whatever the main's scan had left. `Loremaster` records
    -- who scanned, for exactly this reason; this is that.
    CN.Account("achievementScans")[CN.characterKey or CN.GetCharacterKey()] =
        time()

    CN.MarkScanned("achievements")

    return scanned, completed, nearlyDone, answered
end

-- Whether THIS character has ever read its own criteria progress.
function Achievements.HasScanned(characterKey)
    characterKey = characterKey or CN.characterKey or CN.GetCharacterKey()

    return CN.Account("achievementScans")[characterKey] ~= nil
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Achievements.Summary()
    local total, completed = Blizzard.GetAchievementTotals()

    local counts = {
        total       = total,
        completed   = completed,
        inProgress  = 0,
        nearlyDone  = 0,
    }

    -- `pointsLeft` REMOVED. `record.points` has been nil since 0.36.0 --
    -- migration 5 stripped it as something the client re-supplies -- so this
    -- summed to zero on every client, permanently. Two other readers of the
    -- same field were fixed at the time and this one was missed. Nothing
    -- displayed it, so it was dead state rather than a wrong number on
    -- screen; it is gone rather than revived, because a points total the
    -- addon would have to rebuild from the client is a question the
    -- Achievements panel already answers.
    for _, record in pairs(Store()) do
        counts.inProgress = counts.inProgress + 1

        -- The same one rule. See the note in `Scan`.
        if IsNearlyDone(record) then
            counts.nearlyDone = counts.nearlyDone + 1
        end
    end

    return counts
end

-- Incomplete achievements sorted by how close they are to finishing.
function Achievements.Closest(limit)
    local rows = {}

    -- THE NAME WENT ON THE RECORD, AND THE RECORD IS ON DISK. FIXED 0.61.0.
    --
    -- `record` here is the live SavedVariables row -- `Store()` hands back
    -- the saved table itself, not a copy -- so writing `resolvedName` onto it
    -- persisted a client-supplied achievement name into the player's
    -- database, permanently, for every achievement this function ever
    -- touched. 0.36.0 deliberately STOPPED storing achievement names for
    -- exactly this reason, and this line quietly put them back one `/cn
    -- closest` at a time.
    --
    -- Both callers resolve the name themselves anyway. The only thing that
    -- ever read `resolvedName` was the comparator two lines below, so the
    -- names live in a local for the length of the sort and are then gone.
    --
    -- The addon's standing rule, restated: persist only what the client
    -- cannot re-supply. A name it hands over instantly is the clearest case
    -- there is.
    local names = {}

    -- AND THE REMAINDER, HOISTED OUT OF THE COMPARATOR. 0.75.0.
    --
    -- 0.74.0 routed "every reader of `record.done`" through `DoneFor` and
    -- missed this one, so the list was ORDERED by whichever character scanned
    -- last while each row DISPLAYED this character's own figure -- `/cn
    -- closest` printing "3 / 40" above "38 / 40" under the heading "closest
    -- to completion". Computed once per row here rather than O(n log n) times
    -- inside the sort.
    local left = {}

    for achievementID, record in pairs(Store()) do
        local done = Achievements.DoneFor(record) or 0

        -- AND NOTHING LEFT IS NOT CLOSEST TO FINISHING. 0.89.0.
        --
        -- `Loremaster.Closest` and `Exploration.Closest` have carried
        -- `done < criteria` since 0.71.0, whose note says in as many words
        -- that the rule is written twice and the third copy is elsewhere.
        -- This is the third copy, and it never got the guard.
        --
        -- The client is slow to flip `completed`, and `ACHIEVEMENT_EARNED` is
        -- what deletes the row here -- so a row at 12 of 12 sorts to the very
        -- front of a list headed "closest to completion" and the addon sends
        -- the player to finish something with nothing left in it.
        if record.criteria and record.criteria > 0 and done > 0
            and done < record.criteria then

            names[record] = NameOf(achievementID, record) or ""
            left[record]  = record.criteria - done

            table.insert(rows, record)
        end
    end

    table.sort(rows, function(a, b)
        local aLeft = left[a] or 0
        local bLeft = left[b] or 0

        if aLeft == bLeft then
            return (names[a] or "") < (names[b] or "")
        end

        return aLeft < bLeft
    end)

    local results = {}

    for index = 1, math.min(limit or 10, #rows) do
        table.insert(results, rows[index])
    end

    return results
end

function Achievements.Resolve(text)
    local achievementID = CN.ToID(text)

    if achievementID then
        return achievementID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, record in pairs(Store()) do
        local name = NameOf(id, record)

        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.ACHIEVEMENT, function(achievementID)
    local states = CN.objectiveStates
    local record = Store()[achievementID]

    if not record then
        -- Absent from the incomplete store means either completed or never
        -- scanned. Ask the client rather than guessing.
        local info = GetAchievementInfo and select(4, GetAchievementInfo(achievementID))

        if info then
            return states.COMPLETED, "Already earned", nil
        end

        return states.UNKNOWN, "No achievement data; run /cn achievescan", nil
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only near-complete achievements become candidates. A zero-progress
-- achievement is a project, not a next action, and flooding the
-- recommendation list with thousands of them would bury everything else.
-- The criteria line always; the points line only when the client will say.
local function PointReasons(achievementID, remaining, criteria)
    local reasons = {
        remaining .. " of " .. criteria .. " criteria left",
    }

    local points = Blizzard.GetAchievementPoints
        and Blizzard.GetAchievementPoints(achievementID)

    if type(points) == "number" and points > 0 then
        table.insert(reasons, points .. " achievement points")
    end

    return reasons
end

CN.RegisterCandidateProvider("Achievements", function()
    -- Iterates the shortlist, not the store. At retail scale that is a dozen
    -- rows instead of three thousand, and the three thousand were being
    -- rejected identically on every single rebuild.
    local shortlist = {}

    for _, entry in ipairs(Achievements.Shortlist()) do
        shortlist[entry.id] = entry.record
    end

    local candidates, considered, dropped = CN.CollectBounded(shortlist, nil,
        function(achievementID, record)
            local criteria = record.criteria or 0

            if criteria <= 0 then
                return nil
            end

            local remaining = criteria - (Achievements.DoneFor(record) or 0)

            -- A zero-progress achievement is a project, not a next action.
            if remaining <= 0 or remaining > Achievements.nearlyDoneThreshold then
                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.ACHIEVEMENT, achievementID)
                or CN.IsDeferred(CN.objectiveTypes.ACHIEVEMENT, achievementID) then
                return nil
            end

            return 3 - remaining
        end,
        function(achievementID, record, value)
            local remaining = (record.criteria or 0)
                - (Achievements.DoneFor(record) or 0)

            return CN.NewObjective({
                id              = achievementID,
                type            = CN.objectiveTypes.ACHIEVEMENT,
                name            = NameOf(achievementID, record),
                accountWide     = true,
                completionValue = value,
                -- POINTS ARE READ LIVE, OR NOT MENTIONED.
                --
                -- `record.points` has been nil since 0.36.0 stopped storing
                -- it -- this file says so in a comment a hundred lines below,
                -- where two other readers were fixed. This one was missed,
                -- and `or 0` turned an absent number into a confident false
                -- statement: every near-complete achievement in the addon has
                -- been reporting "0 achievement points".
                --
                -- Silence beats a wrong number. That is the same rule this
                -- addon applies to every denominator it cannot vouch for.
                reasons         = PointReasons(achievementID, remaining,
                    record.criteria),
            })
        end)

    CN.providerTruncation["Achievements"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "ACHIEVEMENT_EARNED", "CRITERIA_UPDATE" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("ACHIEVEMENT_EARNED", function(event, achievementID)
    if achievementID then
        Store()[achievementID] = nil

        -- THE SHORTLIST HOLDS THE ROW THE STORE JUST RELEASED.
        --
        -- `CN.Shortlist` returns its held list whenever the revision matches,
        -- and the revision moved only on a full scan or when a criteria tick
        -- crossed the nearly-done boundary. Deleting the store row without
        -- moving it left the shortlist holding a strong reference to an
        -- orphaned record -- so ACHIEVEMENT_EARNED invalidated the provider,
        -- the provider rebuilt, asked for the shortlist, got the cached one
        -- back, and emitted the achievement the player had just earned as a
        -- candidate again. It stayed at the top of `/cn next` until something
        -- unrelated moved the revision.
        Achievements.revision = Achievements.revision + 1

        DebugPrint("Achievement earned: " .. tostring(achievementID))
    end
end)

-- Criteria updates fire constantly during play. Refresh the tracked rows
-- rather than rescanning thousands of achievements, and throttle even that.

-- Published rather than a literal, so the throttle is a knob the suite can
-- turn. A guard nothing can reach is a guard nothing tests.
Achievements.criteriaSweepSeconds = 5

-- THROUGH `CN.Debounce`, LIKE BOTH ITS SIBLINGS. 0.72.0.
--
-- This was a hand-rolled leading-edge throttle with NO TRAILING RUN -- the
-- exact shape `UI.RequestRefresh` documents as wrong and replaced, and the
-- shape the two other `CRITERIA_UPDATE` handlers in this addon
-- (`Exploration`, `Loremaster`) already avoid.
--
-- A single discovery fires several criteria updates in a row. The first was
-- answered against pre-move state and the rest were DROPPED -- including the
-- one that actually crossed the `IsNearlyDone` boundary -- so an achievement
-- reaching 38 of 40 stayed off the shortlist until an unrelated criteria
-- update happened along more than five seconds later. `CN.Debounce` gives the
-- leading answer AND one trailing run, which is what makes the last update in
-- a burst the one that counts.
CN:RegisterEvent("CRITERIA_UPDATE", function()
    CN.Debounce("Achievements.criteria",
        Achievements.criteriaSweepSeconds, function()

        -- AND THE RANKING IS TOLD. 0.73.0.
        --
        -- The trailing run is the one that matters -- it is the whole reason
        -- 0.72.0 moved this onto `CN.Debounce` -- and it bumped
        -- `Achievements.revision`, which busts the SHORTLIST cache and
        -- nothing else. The provider is marked dirty by its own
        -- `CRITERIA_UPDATE` subscription, which fires DURING the burst, five
        -- seconds before this runs. So a row crossing the "nearly done"
        -- boundary still did not reach `/cn next` until an unrelated criteria
        -- update happened along -- the exact case 0.72.0's note claims to
        -- have fixed.
        --
        -- `Exploration` and `Loremaster` both invalidate from inside their
        -- debounced bodies. This was the missed sibling, one release after
        -- the throttle was copied from them.
        local crossed = false

        -- THE SHORTLIST, NOT THE WHOLE STORE. 0.62.0.
        --
        -- This walked every incomplete tracked achievement and called
        -- `GetAchievementProgress` on each -- and that function makes one client
        -- call PER CRITERION. At retail scale it is several hundred rows of five
        -- to forty criteria: a few thousand client calls, every five seconds, for
        -- as long as CRITERIA_UPDATE keeps firing, which is continuously while
        -- questing or raiding. Measured on the game's own Lua 5.1: 21.4 ms per
        -- sweep, more than a frame, twelve times a minute.
        --
        -- Only rows near the boundary can change what the addon SHOWS: the
        -- provider reads the shortlist, and a row at 3 of 40 moving to 4 of 40
        -- changes nothing anybody sees until it is within the threshold. So the
        -- sweep covers the shortlist plus anything the player has pinned as a
        -- goal, which is a dozen rows rather than several hundred.
        --
        -- The rest are picked up by the next full scan, exactly as before -- this
        -- store has always been a snapshot refreshed on demand.
        local store = Store()

        local watched = {}

        for _, entry in ipairs(Achievements.Shortlist()) do
            watched[entry.id] = true
        end

        local goals = CN:GetModule("Goals")

        if goals and goals.List then
            for _, goal in ipairs(goals.List() or {}) do
                if goal and goal.type == CN.objectiveTypes.ACHIEVEMENT and goal.id then
                    watched[goal.id] = true
                end
            end
        end

        for achievementID, record in pairs(store) do
            if watched[achievementID]
                and record.criteria and record.criteria > 0 then

                -- BOTH RETURNS, BECAUSE A REFUSAL LOOKS LIKE ZERO. 0.67.0.
                --
                -- `GetAchievementProgress` answers `0, 0` when the criteria API
                -- is unavailable -- early in a loading screen, or before the
                -- achievement UI has loaded -- and this discarded the second
                -- return, so a refusal was written into the store as real
                -- progress. One `CRITERIA_UPDATE` at the wrong moment rewrote
                -- every watched row to zero, `IsNearlyDone` went false, and an
                -- achievement at 38 of 40 dropped out of `/cn next` until a full
                -- `/cn achievescan`, which nothing runs on its own.
                --
                -- `Exploration.RefreshCurrentZone` guards this exact case, under
                -- the header "NOT OVER GOOD DATA WITH NOTHING". The guard was
                -- never carried to the sibling.
                local done, criteria = Blizzard.GetAchievementProgress(achievementID)

                if criteria and criteria > 0
                    and done ~= (Achievements.DoneFor(record) or 0) then

                    local wasNear = IsNearlyDone(record)

                    Achievements.NoteProgress(record, done)

                    -- Only a change that crosses the shortlist boundary can
                    -- change what the provider would produce. Bumping the
                    -- revision on every criteria tick would rebuild the
                    -- shortlist constantly and give back the saving.
                    if wasNear ~= IsNearlyDone(record) then
                        Achievements.revision = Achievements.revision + 1
                        crossed = true
                    end
                end
            end
        end

        if crossed then
            CN.InvalidateProvider("Achievements")
        end
    end)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "achievescan",
    order   = 64,
    help    = "Scan every achievement category.",
    handler = function()
        Print("Scanning achievements; this takes a moment.")

        local scanned, completed, nearlyDone, answered = Achievements.Scan()

        -- A COUNT IS NOT A RESULT. 0.87.0.
        --
        -- `Scan` returns early when the criteria API answered about nothing:
        -- it does not prune, does not stamp the per-character record, and
        -- does not call `MarkScanned`. Both callers threw that fourth value
        -- away and printed three confident numbers over a store that had
        -- recorded nothing -- so the login reminder went on nagging and the
        -- player was never told to try again.
        --
        -- `/cn scanlore` was given this sentence in 0.72.0 and the "Rescan
        -- zones" button beside this one in 0.73.0, under a note reading "a
        -- rescan the client refused looked exactly like one that worked".
        -- Third caller, same shape.
        if (answered or 0) == 0 then
            Print("The game would not answer about achievement criteria just "
                .. "now. Try again in a few seconds.")

            return
        end

        Print("Scanned " .. scanned .. " achievements.")
        Print("Completed: " .. completed)
        Print("Within two criteria of finishing: " .. nearlyDone)
    end,
}

CN:RegisterCommand{
    name    = "achievements",
    aliases = { "achieve" },
    order   = 65,
    help    = "Summarize achievement progress.",
    handler = function()
        local counts = Achievements.Summary()

        if counts.total == 0 and counts.inProgress == 0 then
            Print("No achievement data yet. Run /cn achievescan.")
            return
        end

        Print("Achievements: " .. counts.completed .. " / " .. counts.total
            .. " (" .. CN.PercentText(
                counts.total > 0 and (counts.completed / counts.total) or 0, 1)
            .. ")")

        Print("Tracked in progress: " .. counts.inProgress)
        Print("Within two criteria of finishing: " .. counts.nearlyDone)

        local closest = Achievements.Closest(5)

        local rows = {}

        for _, record in ipairs(closest) do
            table.insert(rows, {
                text  = NameOf(record.achievementID or 0, record),
                value = (Achievements.DoneFor(record) or 0)
                    .. " / " .. record.criteria,
            })
        end

        CN.PrintRows(nil, rows, { limit = 5 })
    end,
}

CN:RegisterCommand{
    name    = "closest",
    args    = "[count]",
    order   = 66,
    help    = "List the achievements closest to completion.",
    handler = function(args)
        local limit   = CN.ToID(args) or 10
        local closest = Achievements.Closest(limit)

        if #closest == 0 then
            Print("No achievements in progress. Run /cn achievescan.")
            return
        end

        local rows = {}

        for _, record in ipairs(closest) do
            -- `points` HAS BEEN NIL SINCE 0.36.0.
            --
            -- That release stopped storing it, correctly -- the client
            -- returns it instantly and a copy on disk was dead weight. Two
            -- other places were updated to read it live or to tolerate its
            -- absence with `or 0`; this one was missed, so the command threw
            -- for anybody whose database had been migrated. It was invisible
            -- because the error is caught by the command dispatcher, printed
            -- once, and looks like a client hiccup.
            --
            -- Read live, and say nothing about points when the client will
            -- not say either.
            local points = record.points
                or Blizzard.GetAchievementPoints(record.achievementID)

            table.insert(rows, {
                text  = NameOf(record.achievementID or 0, record),
                value = (Achievements.DoneFor(record) or 0)
                    .. " / " .. record.criteria,
                note  = points and CN.Count(points, "point") or nil,
            })
        end

        CN.PrintRows(nil, rows, { limit = limit })
    end,
}
'@

$Embedded['Modules\Pets.lua'] = @'
-- Modules/Pets.lua
-- Completion Navigator :: battle pet collection.
--
-- Pets are account-wide, so everything here lives in account storage. The
-- journal is filtered by whatever the player last set in the UI, which is
-- why the scan widens the filters and restores them afterwards.

local ADDON_NAME, CN = ...

local Pets = CN:RegisterModule("Pets")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

-- A pet's name, from the client, falling back to anything an older database
-- still carries.
--
-- The name used to be stored for all eighteen hundred pets -- 274 KB of a
-- file the game rewrites on every logout, duplicating a journal the client
-- keeps in memory anyway. Persist only what the client cannot re-supply.
local function NameOf(speciesID, record)
    local live = CN.Blizzard.GetPetName(speciesID)

    if live then
        return live
    end

    -- Databases written before 0.36.0 still hold one.
    return (record and record.name) or ("Pet " .. tostring(speciesID))
end

local function Store()
    return CN.Account("pets")
end

Pets.Store  = Store
Pets.NameOf = NameOf

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Pets.Scan()
    if not C_PetJournal then
        return 0, 0, 0
    end

    local store = Store()

    local seen, owned, missing = 0, 0, 0

    -- Which species this scan has already counted. See the note below.
    local counted = {}

    Blizzard.WithAllPetsShown(function()
        local total = select(1, Blizzard.GetNumPets())

        for index = 1, total do
            local pet = Blizzard.GetPetByIndex(index)

            if pet and pet.speciesID then
                local collected, limit = Blizzard.GetPetCollectedCount(pet.speciesID)

                store[pet.speciesID] = {
                    speciesID  = pet.speciesID,
                    petType    = pet.petType,
                    isWild     = pet.isWild,
                    canBattle  = pet.canBattle,
                    obtainable = pet.obtainable,
                    collected  = (collected or 0) > 0,
                    count      = collected or 0,
                    limit      = limit or 3,
                }

                -- ONE COUNT PER SPECIES, NOT PER JOURNAL ROW. 0.62.0.
                --
                -- `GetNumPets` returns DISPLAYED ENTRIES, and an owned
                -- species appears once per copy held -- which is exactly why
                -- `GetPetCollectedCount` returns `collected, limit`. These
                -- counters incremented per entry while `store` is keyed per
                -- species, so a player holding duplicates got two commands
                -- that disagreed about the same journal:
                --
                --   /cn petscan -> "Scanned 2,146 pets. Collected: 1,104"
                --   /cn pets    -> "known to the journal: 1,842. Collected: 802"
                --
                -- Counted off the store, which is the thing the rest of the
                -- addon reads.
                if not counted[pet.speciesID] then
                    counted[pet.speciesID] = true

                    seen = seen + 1

                    if (collected or 0) > 0 then
                        owned = owned + 1
                    elseif pet.obtainable then
                        missing = missing + 1
                    end
                end
            end
        end
    end)

    -- The name index is now stale. See `Pets.NameIndex`.
    Pets.nameRevision = (Pets.nameRevision or 0) + 1

    CN.MarkScanned("pets")

    return seen, owned, missing
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Pets.Summary()
    local store = Store()

    local counts = {
        known       = 0,
        collected   = 0,
        missing     = 0,
        unobtainable = 0,
        wildMissing = 0,
        maxed       = 0,
    }

    for _, record in pairs(store) do
        counts.known = counts.known + 1

        if record.collected then
            counts.collected = counts.collected + 1

            if record.count and record.limit and record.count >= record.limit then
                counts.maxed = counts.maxed + 1
            end
        elseif record.obtainable == false then
            counts.unobtainable = counts.unobtainable + 1
        else
            counts.missing = counts.missing + 1

            if record.isWild then
                counts.wildMissing = counts.wildMissing + 1
            end
        end
    end

    return counts
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

-- SPECIES BY EXACT NAME, IN ONE LOOKUP. 0.87.0.
--
-- `Pets.Resolve` is a substring search over every species the journal has --
-- roughly eighteen hundred rows, lowercasing each name, allocating a table
-- per match and sorting the result. That is the right shape for a player
-- typing `/cn chase pet frost`, and the wrong one for a tooltip.
--
-- 0.86.0 correctly stopped reading a species id the client does not return
-- and started resolving the NAME instead -- and routed the tooltip and the
-- bag sweep through that search. This addon has removed exactly that from
-- two other hot paths and left a note each time: "twenty-five hundred
-- iterations and five thousand string allocations to answer a question about
-- one item... three per cent of a frame, per mouseover, and a bag sweep
-- fires dozens a second."
--
-- A caged pet's item name IS the species name, so the hot path wants an
-- exact match and nothing else. Built once per scan, on the counter the
-- store already bumps, in the same idiom `Professions.NameIndex` uses.
-- ON THE REVISION THIS STORE BUMPS, NOT THE COLLECTION COUNTER. 0.87.0.
--
-- The first version of this index keyed on `CN.collectionGeneration`, on the
-- reasoning that it is "the counter the store already bumps". It is not:
-- twelve client events move it -- a quest turn-in, a reputation tick, a
-- transmog, entering the world -- and none of them writes the pet store.
-- Each rebuild is one protected client call per species, so on an
-- eighteen-hundred-species account the index was rebuilt at roughly TWICE
-- the cost of the single search it exists to replace, in the tooltip path
-- that fires dozens of times a second.
--
-- `Professions.nameRevision` is the idiom this claimed to copy, and it is
-- bumped only where its store is written. So is this.
Pets.nameRevision = Pets.nameRevision or 0

function Pets.NameIndex()
    return CN.Shortlist("PetNames", Pets.nameRevision, function()
        local index = {}

        for id in pairs(Store()) do
            -- THE JOURNAL'S OWN NAME, NOT `NameOf`'s PLACEHOLDER. 0.87.0.
            --
            -- `NameOf` never returns nil: it falls back to "Pet 1234" for a
            -- species the client has not named yet. So a gate on "is this a
            -- non-empty string" cannot tell a cold journal from a loaded
            -- one, and an index built in the seconds after login -- against
            -- a store that is already full, because it is persisted -- was
            -- eighteen hundred placeholders that match no item name.
            --
            -- `Inventory.KindOf` refuses to cache exactly this miss one
            -- layer up; caching it here would have defeated that.
            local name = CN.Blizzard.GetPetName(id)

            if type(name) == "string" and name ~= "" then
                index[string.lower(name)] = id
            end
        end

        return index
    end)
end

function Pets.SpeciesByName(text)
    if type(text) ~= "string" or text == "" then
        return nil
    end

    return Pets.NameIndex()[string.lower(text)]
end

function Pets.Resolve(text)
    local speciesID = CN.ToID(text)

    if speciesID and Store()[speciesID] then
        return speciesID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, record in pairs(Store()) do
        local name = NameOf(id, record)

        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id, matches
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.PET, function(speciesID)
    local states = CN.objectiveStates
    local record = Store()[speciesID]

    if not record then
        return states.UNKNOWN, "No pet data; run /cn petscan", nil
    end

    if record.collected then
        return states.COMPLETED, "Already collected", NameOf(speciesID, record)
    end

    if record.obtainable == false then
        return states.UNOBTAINABLE, CN.blockReasons.UNOBTAINABLE, NameOf(speciesID, record)
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Wild pets are the only ones this addon can currently point at, because a
-- wild pet's location is a zone rather than a vendor or a boss drop. Vendor
-- and drop sources need the static database.
-- Retail has around 1800 species, of which most players are missing several
-- hundred. Emitting one objective per missing pet meant allocating a thousand
-- tables per rebuild so that at most a handful could ever rank -- and they all
-- score identically anyway, since none of them carries a location. Take the
-- best of them instead, and report what was dropped.
CN.RegisterCandidateProvider("Pets", function()
    local candidates, considered, dropped = CN.CollectBounded(Store(), nil,
        function(speciesID, record)
            if record.collected or record.obtainable == false then
                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.PET, speciesID)
                or CN.IsDeferred(CN.objectiveTypes.PET, speciesID) then
                return nil
            end

            -- A wild pet is something you can go and catch; anything else is
            -- a wish. That is the whole ranking.
            return record.isWild and 2 or 1
        end,
        function(speciesID, record, value)
            local reasons = {}

            if record.isWild then
                table.insert(reasons, "wild pet, catchable in the world")
            end

            return CN.NewObjective({
                id              = speciesID,
                type            = CN.objectiveTypes.PET,
                name            = NameOf(speciesID, record),
                accountWide     = true,
                completionValue = value,
                reasons         = reasons,
            })
        end)

    CN.providerTruncation["Pets"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "NEW_PET_ADDED" } })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

local lastScan = 0

CN:RegisterEvent("NEW_PET_ADDED", function()
    lastScan = 0
    Pets.Scan()
    DebugPrint("Pet added; journal rescanned.")
end)

CN:RegisterEvent("PET_JOURNAL_LIST_UPDATE", function()
    local now = time()

    if now - lastScan < 30 then
        return
    end

    lastScan = now

    local seen = Pets.Scan()

    DebugPrint("Pet journal scan: " .. seen .. " species.")
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "petscan",
    order   = 50,
    help    = "Scan the pet journal.",
    handler = function()
        local seen, owned, missing = Pets.Scan()

        -- THE THREE NUMBERS ADD UP. 0.82.0.
        --
        -- `missing` counts only species the client calls OBTAINABLE, so an
        -- unobtainable uncollected species landed in `seen` and in neither
        -- of the other two: "Scanned 1,842. Collected: 802  Missing: 940",
        -- which is 1,742. `/cn pets`, run a second later, accounted for all
        -- of them -- the surviving half of the 0.62.0 defect this file
        -- documents, where the store-side count was fixed and the printed
        -- arithmetic was not.
        local counts = Pets.Summary()

        Print("Scanned " .. CN.Count(seen, "pet species", "pet species") .. ".")
        Print("Collected: " .. owned .. "   Missing: " .. missing
            .. ((counts and (counts.unobtainable or 0) > 0)
                and ("   Unobtainable: " .. counts.unobtainable) or ""))
    end,
}

CN:RegisterCommand{
    name    = "pets",
    order   = 51,
    help    = "Summarize battle pet collection.",
    handler = function()
        local counts = Pets.Summary()

        if counts.known == 0 then
            Print("No pet data yet. Run /cn petscan.")
            return
        end

        Print("Pets known to the journal: " .. counts.known)
        Print("Collected: " .. counts.collected .. " (" .. counts.maxed .. " at max count)")
        Print("Missing and obtainable: " .. counts.missing
            .. " (" .. counts.wildMissing .. " wild)")

        if counts.unobtainable > 0 then
            Print("Missing but unobtainable: " .. counts.unobtainable)
        end
    end,
}

CN:RegisterCommand{
    name    = "pet",
    args    = "<speciesID or name>",
    order   = 52,
    help    = "Show one pet's collection state.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn pet <speciesID or name>")
            return
        end

        local speciesID = Pets.Resolve(args)

        if not speciesID then
            Print("No known pet matches: " .. args)
            return
        end

        local record = Store()[speciesID]

        Print(NameOf(speciesID, record) .. " |cff8a8f96(" .. speciesID .. ")|r")
        Print("Collected: " .. CN.YesNo(record.collected)
            .. (record.collected and (" (" .. record.count .. "/" .. record.limit .. ")") or ""))
        Print("Wild: " .. CN.YesNo(record.isWild)
            .. "   Battle pet: " .. CN.YesNo(record.canBattle))

        if record.obtainable == false then
            Print("|cffe2564cCurrently unobtainable.|r")
        end
    end,
}

-- AND ONCE AT LOGIN. 0.62.0.
--
-- This store relied entirely on `NEW_PET_ADDED`, which covers
-- collections made while this session is running and nothing collected in a
-- session where the addon was not loaded. The store is persisted account-wide,
-- so a player who turns addons off for a raid night, collects three, and turns
-- them back on is recommended things they already own until they happen to run
-- the scan by hand.
--
-- `Appearances.lua` made exactly this argument in 0.58.0 and the same argument
-- applies verbatim here; three stores were left behind.
--
-- Guarded and quiet: this is a journal walk, and a client that refuses it must
-- not take the login sequence with it.
CN:OnLogin(function()
    CN.Guard("Pets.Scan", Pets.Scan)
end)
'@

$Embedded['Modules\Mounts.lua'] = @'
-- Modules/Mounts.lua
-- Completion Navigator :: mount collection.
--
-- Mounts are account-wide, but a mount can be faction-locked or hidden on
-- the current character. Both matter for "which character should get this",
-- so both are recorded rather than filtered away at scan time.

local ADDON_NAME, CN = ...

local Mounts = CN:RegisterModule("Mounts")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function Store()
    return CN.Account("mounts")
end

Mounts.Store = Store

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Mounts.Scan()
    if not C_MountJournal then
        return 0, 0, 0
    end

    local store = Store()

    local seen, collected, missing = 0, 0, 0

    for _, mountID in ipairs(Blizzard.GetMountIDs()) do
        local mount = Blizzard.GetMountByID(mountID)

        if mount then
            store[mountID] = {
                mountID           = mountID,

                -- `name` IS NOT STORED. 0.63.0.
                --
                -- Around nine hundred localized names the journal returns
                -- instantly, in the language the player is reading. Stored,
                -- they froze: a player who changed client language could not
                -- find their own mounts with `/cn mount <name>` and the row
                -- printed the old locale's name. 0.62.0 dropped `source` from
                -- these same rows on the same rule and left the name.
                --
                -- `Mounts.NameOf` below is the one reader, matching
                -- `Pets.NameOf` and `Achievements.NameOf`.
                spellID           = mount.spellID,
                sourceType        = mount.sourceType,

                -- `source` IS NOT STORED ANY MORE. 0.62.0.
                --
                -- It is the journal's multi-line LOCALIZED source prose, for
                -- around nine hundred rows -- by far the largest thing this
                -- addon still wrote to disk that the client hands back
                -- instantly from `GetMountInfoExtraByID`. Migrations 4, 5 and
                -- 14 stripped item names, achievement names and points, pet
                -- names and harvest zones on exactly this rule.
                --
                -- Nothing needs it stored now that ranking reads the numeric
                -- `sourceType`: the two places that DISPLAY it read it live,
                -- through `Mounts.SourceText` below.
                isFactionSpecific = mount.isFactionSpecific,
                faction           = mount.faction,
                collected         = mount.isCollected,

                -- NO TIMESTAMPS. 0.82.0.
                --
                -- Nothing has ever read a mount record's `firstSeen` or
                -- `lastSeen`. Migration 5 stripped exactly these two fields
                -- from `pets` and `toys` for exactly this reason, and
                -- migration 31 caught `appearances` under a header naming
                -- itself "THE STORE MIGRATION 5 MISSED". `mounts` is the
                -- largest of the four and was missed by both -- two fresh
                -- integers on roughly nine hundred rows, written at every
                -- login and serialized at every logout.
            }

            seen = seen + 1

            if mount.isCollected then
                collected = collected + 1
            else
                missing = missing + 1
            end
        end
    end

    CN.MarkScanned("mounts")

    return seen, collected, missing
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only mounts with a KNOWN SOURCE become recommendations.
--
-- Retail has roughly 900 mounts and most players are missing hundreds. An
-- objective that says "collect this mount" and nothing else is not a next
-- action, it is a list -- and /cn breakdown and the Collections tab already
-- read the store directly for that. What makes a mount actionable is the
-- journal's source text: "Vendor: X", "Quest: Y", "Drop: Z".
-- WHERE A MOUNT COMES FROM, AS A NUMBER. 0.62.0.
--
-- `C_MountJournal.GetMountInfoByID` returns a numeric `sourceType` alongside
-- the localized source sentence, and the addon has been storing it, unused,
-- since it started reading mounts. These are the client's own values; an enum
-- is the same number in every language, which the sentence is not.
--
-- Unknown values rank as "we do not know", not as "worthless" -- a source the
-- client adds in a future patch must not be silently buried.
Mounts.sourceTypes = {
    [0]  = "UNKNOWN",
    [1]  = "DROP",
    [2]  = "QUEST",
    [3]  = "VENDOR",
    [4]  = "PROFESSION",
    [5]  = "PET_STORE",
    [6]  = "ACHIEVEMENT",
    [7]  = "WORLD_EVENT",
    [8]  = "PROMOTION",
    [9]  = "TCG",
    [10] = "BLACK_MARKET",
    [11] = "TRADING_POST",
    [12] = "DISCOVERY",
}

-- Something you can walk up to and buy or complete beats something with a
-- drop chance, which beats everything else.
Mounts.sourceValues = {
    VENDOR      = 3,
    QUEST       = 3,
    ACHIEVEMENT = 3,
    PROFESSION  = 3,
    WORLD_EVENT = 3,
    DROP        = 2,
    DISCOVERY   = 2,
}

function Mounts.SourceValue(record)
    local kind = record and Mounts.sourceTypes[record.sourceType]

    if kind then
        return Mounts.sourceValues[kind] or 1
    end

    -- THE PRE-0.62.0 FALLBACK COULD NEVER RUN. 0.82.0.
    --
    -- This matched English words in `record.source` and was justified by
    -- "databases from before 0.62.0 carry the sentence and no type... the old
    -- English match is better than nothing FOR THOSE ROWS". Migration 15 sets
    -- `record.source = nil` on every row of `db.account.mounts`, and
    -- migrations run on ADDON_LOADED -- strictly before any scan or rebuild.
    -- So the branch was unreachable on every client, always, and the promise
    -- it made to upgrading players could not be kept by construction.
    --
    -- It was also a localized string being BRANCHED on, which this project
    -- forbids outright.
    return 1
end

-- A mount's name, from the client.
--
-- The `record` argument is kept for the call sites that pass one; the stored
-- fallback it used to consult was deleted from every row by migration 16, so
-- reading it was reading nil. 0.82.0.
function Mounts.NameOf(mountID)
    local live = CN.Blizzard.GetMountByID and CN.Blizzard.GetMountByID(mountID)

    if live and live.name and live.name ~= "" then
        return live.name
    end

    return "Mount " .. tostring(mountID)
end

-- The journal's source sentence, live. See the note in `Scan`.
--
-- No stored fallback: migration 15 removed `source` from every row, so the
-- one this used to read was always nil. 0.82.0.
function Mounts.SourceText(mountID)
    local live = CN.Blizzard.GetMountByID and CN.Blizzard.GetMountByID(mountID)

    if live and live.source and live.source ~= "" then
        return live.source
    end

    return nil
end

CN.RegisterCandidateProvider("Mounts", function()
    local playerFaction = UnitFactionGroup and UnitFactionGroup("player") or nil

    local candidates, considered, dropped = CN.CollectBounded(Store(), nil,
        function(mountID, record)
            if record.collected then
                return nil
            end

            -- A mount locked to the other faction cannot be earned on this
            -- account's characters of this faction; saying "go get it" is
            -- worse than silence.
            if record.isFactionSpecific and record.faction and playerFaction then
                local wanted = (record.faction == 0) and "Horde" or "Alliance"

                if wanted ~= playerFaction then
                    return nil
                end
            end

            -- SOMETHING KNOWN ABOUT WHERE IT COMES FROM, IN ANY FORM.
            --
            -- This required the localized `source` sentence to be non-empty,
            -- which is the same locale trap as the ranking below: a client
            -- that returns a source TYPE and an empty prose line -- which
            -- happens -- had every one of its mounts dropped from the list.
            if (record.sourceType == nil or record.sourceType == 0)
                and not Mounts.SourceText(mountID) then

                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.MOUNT, mountID)
                or CN.IsDeferred(CN.objectiveTypes.MOUNT, mountID) then
                return nil
            end

            -- THE NUMBER, NOT THE SENTENCE. FIXED IN 0.62.0.
            --
            -- This ranked mounts by searching the journal's `sourceText` for
            -- the English words "vendor", "quest" and "drop". That string is
            -- LOCALIZED -- "Händler:", "Quête :", "Botín:" -- so on every
            -- non-English client every uncollected mount fell through to 1,
            -- and a vendor mount two zones away ranked identically to a
            -- one-per-cent raid drop. `/cn next` stopped preferring the
            -- actionable one for roughly half the player base.
            --
            -- The client hands over a numeric `sourceType` from the same call
            -- and the addon has been STORING it, unused, since it started
            -- reading mounts. An enum is the same number in every locale.
            return Mounts.SourceValue(record)
        end,
        function(mountID, record, value)
            return CN.NewObjective({
                id              = mountID,
                type            = CN.objectiveTypes.MOUNT,
                name            = Mounts.NameOf(mountID, record),
                accountWide     = true,
                completionValue = value,
                reasons         = { Mounts.SourceText(mountID, record)
                    or "the journal does not say where this comes from" },
            })
        end)

    CN.providerTruncation["Mounts"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "NEW_MOUNT_ADDED" } })

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

-- faction is 0 for Horde and 1 for Alliance in the mount journal.
--
-- THIS TABLE IS A TOKEN MAP AND IS USED AS ONE. It is compared against
-- `character.faction`, which is stored in the same English tokens, and that
-- comparison is correct. What is NOT correct is printing the token: 0.64.0
-- gave the Warband roster `CN.FactionLabel`, backed by the client's own
-- `FACTION_ALLIANCE` / `FACTION_HORDE` globals, and this file -- the other
-- place a faction reaches the player -- was not converted. A German player
-- read "Faction: Alliance" beside "Sammelbar: nein". 0.66.0.
local FACTION_NAMES = { [0] = "Horde", [1] = "Alliance" }

function Mounts.IsUsableByCharacter(record, character)
    if not record.isFactionSpecific then
        return true
    end

    character = character or CN.character

    if not character or not character.faction then
        return true
    end

    return FACTION_NAMES[record.faction] == character.faction
end

CN.RegisterEligibilityChecker(CN.objectiveTypes.MOUNT, function(mountID)
    local states = CN.objectiveStates
    local record = Store()[mountID]

    if not record then
        return states.UNKNOWN, "No mount data; run /cn mountscan", nil
    end

    if record.collected then
        return states.COMPLETED, "Already collected", Mounts.NameOf(mountID, record)
    end

    if not Mounts.IsUsableByCharacter(record) then
        local token = FACTION_NAMES[record.faction]

        return states.REQUIRES_OTHER_CHARACTER,
               CN.blockReasons.WRONG_FACTION,
               token and CN.FactionLabel(token) or "the other faction"
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Mounts.Summary()
    local counts = {
        known        = 0,
        collected    = 0,
        missing      = 0,
        wrongFaction = 0,
    }

    for _, record in pairs(Store()) do
        counts.known = counts.known + 1

        if record.collected then
            counts.collected = counts.collected + 1
        else
            counts.missing = counts.missing + 1

            if not Mounts.IsUsableByCharacter(record) then
                counts.wrongFaction = counts.wrongFaction + 1
            end
        end
    end

    return counts
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

function Mounts.Resolve(text)
    local mountID = CN.ToID(text)

    if mountID and Store()[mountID] then
        return mountID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, record in pairs(Store()) do
        local heldName = Mounts.NameOf(id, record)

        if heldName and string.find(string.lower(heldName), needle, 1, true) then
            table.insert(matches, { id = id, name = heldName })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id, matches
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("NEW_MOUNT_ADDED", function()
    Mounts.Scan()
    DebugPrint("Mount added; journal rescanned.")
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "mountscan",
    order   = 53,
    help    = "Scan the mount journal.",
    handler = function()
        local seen, collected, missing = Mounts.Scan()

        Print("Scanned " .. seen .. " mounts.")
        Print("Collected: " .. collected .. "   Missing: " .. missing)
    end,
}

CN:RegisterCommand{
    name    = "mounts",
    order   = 54,
    help    = "Summarize mount collection.",
    handler = function()
        local counts = Mounts.Summary()

        if counts.known == 0 then
            Print("No mount data yet. Run /cn mountscan.")
            return
        end

        Print("Mounts known to the journal: " .. counts.known)
        Print("Collected: " .. counts.collected .. "   Missing: " .. counts.missing)

        if counts.wrongFaction > 0 then
            Print("Missing and locked to the other faction: " .. counts.wrongFaction)
        end
    end,
}

CN:RegisterCommand{
    name    = "mount",
    args    = "<mountID or name>",
    order   = 55,
    help    = "Show one mount's collection state.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn mount <mountID or name>")
            return
        end

        local mountID = Mounts.Resolve(args)

        if not mountID then
            Print("No known mount matches: " .. args)
            return
        end

        local record = Store()[mountID]

        Print(Mounts.NameOf(mountID, record)
            .. " |cff8a8f96(" .. mountID .. ")|r")
        Print("Collected: " .. CN.YesNo(record.collected))

        local sourceText = Mounts.SourceText(mountID, record)

        if sourceText and sourceText ~= "" then
            Print("Source: " .. CN.Strip(sourceText))
        end

        if record.isFactionSpecific then
            local token = FACTION_NAMES[record.faction]

            Print("Faction: " .. (token and CN.FactionLabel(token) or "unknown")
                .. (Mounts.IsUsableByCharacter(record) and "" or " |cffe2564c(not this character)|r"))
        end
    end,
}

-- AND ONCE AT LOGIN. 0.62.0.
--
-- This store relied entirely on `NEW_MOUNT_ADDED`, which covers
-- collections made while this session is running and nothing collected in a
-- session where the addon was not loaded. The store is persisted account-wide,
-- so a player who turns addons off for a raid night, collects three, and turns
-- them back on is recommended things they already own until they happen to run
-- the scan by hand.
--
-- `Appearances.lua` made exactly this argument in 0.58.0 and the same argument
-- applies verbatim here; three stores were left behind.
--
-- Guarded and quiet: this is a journal walk, and a client that refuses it must
-- not take the login sequence with it.
CN:OnLogin(function()
    CN.Guard("Mounts.Scan", Mounts.Scan)
end)
'@

$Embedded['Modules\Toys.lua'] = @'
-- Modules/Toys.lua
-- Completion Navigator :: toy box.
--
-- Account-wide. The toy box, like the pet journal, only reports what the
-- player's current filters allow, so the scan widens them first.

local ADDON_NAME, CN = ...

local Toys = CN:RegisterModule("Toys")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- A toy's name, from the client, falling back to an older database's copy.
function Toys.NameOf(itemID)
    local live = CN.Blizzard.GetToyName and CN.Blizzard.GetToyName(itemID)

    if live then
        return live
    end

    -- Migration 16 deleted `name` from every toy row, so the stored
    -- fallback this used to consult was always nil. 0.82.0.
    return "Toy " .. tostring(itemID)
end

local function Store()
    return CN.Account("toys")
end

Toys.Store = Store

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Toys.Scan()
    if not C_ToyBox then
        return 0, 0, 0
    end

    local store = Store()

    local seen, collected, missing = 0, 0, 0

    Blizzard.WithAllToysShown(function()
        local total = Blizzard.GetNumToys()

        for index = 1, total do
            local toy = Blizzard.GetToyByIndex(index)

            if toy and toy.itemID then
                store[toy.itemID] = {
                    itemID    = toy.itemID,

                    -- `name` IS NOT STORED. 0.63.0. Same rule and the same
                    -- reason as mounts next door: the toy box answers
                    -- instantly, in the player's own language, and a stored
                    -- copy freezes at whatever locale last scanned.
                    collected = toy.collected,
                }

                seen = seen + 1

                if toy.collected then
                    collected = collected + 1
                else
                    missing = missing + 1
                end
            end
        end
    end)

    CN.MarkScanned("toys")

    return seen, collected, missing
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Toys.Summary()
    local counts = { known = 0, collected = 0, missing = 0 }

    for _, record in pairs(Store()) do
        counts.known = counts.known + 1

        if record.collected then
            counts.collected = counts.collected + 1
        else
            counts.missing = counts.missing + 1
        end
    end

    return counts
end

function Toys.Resolve(text)
    local itemID = CN.ToID(text)

    if itemID and Store()[itemID] then
        return itemID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for id, record in pairs(Store()) do
        local heldName = Toys.NameOf(id)

        if heldName and string.find(string.lower(heldName), needle, 1, true) then
            table.insert(matches, { id = id, name = heldName })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Toys are the one collection whose IDs line up with the vendor database:
-- both are keyed by item ID, so "which recorded vendor sells this toy" is an
-- exact join rather than a guess. That turns an uncollected toy into an
-- objective with real coordinates.
--
-- Toys with no recorded seller are deliberately NOT emitted. The toy box has
-- no source field, so without a vendor there is nothing to say beyond "you do
-- not have this", which the Collections tab already covers.
CN.RegisterCandidateProvider("Toys", function()
    local vendors = CN:GetModule("Vendors")

    if not vendors then
        return {}
    end

    local playerMap = select(1, CN.GetPlayerPosition())

    -- ONE LOOKUP PER ITEM, LIKE THE TRAVEL COST BESIDE IT. 0.72.0.
    --
    -- 0.71.0 collapsed the double `CN.TravelCost` call in this provider and
    -- walked past the identical duplication one line above it.
    -- `CN.CollectBounded` runs `evaluate` for every row in the store and
    -- `build` for every survivor, and both closures asked
    -- `FirstLocatedSeller` the same question -- which walks the npc list,
    -- allocates a table, and makes a `GetMapName` client call. Over the whole
    -- toy box, on every rebuild.
    --
    -- "A fix that lands at one call site is not finished" is a standing rule
    -- here, and this is the call site it named.
    local sellers = {}

    local function SellerFor(itemID)
        local held = sellers[itemID]

        if held == nil then
            held = vendors.FirstLocatedSeller(itemID) or false
            sellers[itemID] = held
        end

        return held or nil
    end

    local candidates, considered, dropped = CN.CollectBounded(Store(), nil,
        function(itemID, record)
            if record.collected then
                return nil
            end

            if CN.IsIgnored(CN.objectiveTypes.TOY, itemID)
                or CN.IsDeferred(CN.objectiveTypes.TOY, itemID) then
                return nil
            end

            local seller = SellerFor(itemID)

            if not seller then
                return nil
            end

            return (seller.mapID == playerMap) and 3 or 2
        end,
        function(itemID, record, value)
            local seller = SellerFor(itemID)

            if not seller then
                return nil
            end

            local reasons = { "sold by " .. tostring(seller.name) }

            if seller.zone then
                table.insert(reasons, "in " .. seller.zone)
            end

            -- ONE CALL, BOTH ANSWERS. 0.71.0.
            --
            -- 0.70.0 added the confidence flag here with a second
            -- `CN.TravelCost` call inside a `select(2, ...)`, and the travel
            -- model deliberately does not cache a refusal -- so for any
            -- seller it could not route, both calls ran a full estimate:
            -- four client conversions and a scan of the flight network,
            -- twice, per row, in the two highest-volume located providers.
            --
            -- Worse than the cost: the two calls are independent, so a
            -- coordinate conversion that failed between them produced a row
            -- with a real measured journey and no flag saying so -- silently
            -- losing its distance line and its deadline guard.
            local travel, costed = CN.TravelCost(seller.mapID, seller.x, seller.y)

            return CN.NewObjective({
                id              = itemID,
                type            = CN.objectiveTypes.TOY,
                name            = Toys.NameOf(itemID),
                mapID           = seller.mapID,
                x               = seller.x,
                y               = seller.y,
                zone            = seller.zone,
                accountWide     = true,
                completionValue = value,
                -- COSTED, NOT GUESSED. This charged a flat 25 for anything
                -- outside the current zone while holding the seller's exact
                -- coordinates -- so a vendor ninety seconds away in the next
                -- zone was charged twenty-five where a quest at the identical
                -- spot was charged three. A systematic twenty-two point
                -- penalty against exactly the collection types this file
                -- exists to surface.
                travelCost      = travel,
                travelCosted    = costed or nil,
                reasons         = reasons,
            })
        end)

    CN.providerTruncation["Toys"] = { considered = considered, dropped = dropped }

    return candidates
end, { -- `ZONE_CHANGED_NEW_AREA` because this provider reads the player's
    -- position: it scores a vendor in your current zone above one elsewhere
    -- and stamps a travel cost from where you are standing. Every other
    -- located provider declares it; this was the only one that did not, so
    -- flying to another zone left every toy carrying the cost it had in the
    -- last one until a loading screen happened along.
    events = { "NEW_TOY_ADDED", "MERCHANT_SHOW", "ZONE_CHANGED_NEW_AREA" }, cooldown = 5 })

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.TOY, function(itemID)
    local states = CN.objectiveStates
    local record = Store()[itemID]

    if not record then
        return states.UNKNOWN, "No toy data; run /cn toyscan", nil
    end

    if record.collected then
        return states.COMPLETED, "Already collected", Toys.NameOf(itemID)
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("NEW_TOY_ADDED", function()
    Toys.Scan()
    DebugPrint("Toy added; toy box rescanned.")
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "toyscan",
    order   = 56,
    help    = "Scan the toy box.",
    handler = function()
        local seen, collected, missing = Toys.Scan()

        Print("Scanned " .. seen .. " toys.")
        Print("Collected: " .. collected .. "   Missing: " .. missing)
    end,
}

CN:RegisterCommand{
    name    = "toys",
    order   = 57,
    help    = "Summarize toy collection.",
    handler = function()
        local counts = Toys.Summary()

        if counts.known == 0 then
            Print("No toy data yet. Run /cn toyscan.")
            return
        end

        Print("Toys known to the toy box: " .. counts.known)
        Print("Collected: " .. counts.collected .. "   Missing: " .. counts.missing)
    end,
}

CN:RegisterCommand{
    name    = "toy",
    args    = "<itemID or name>",
    order   = 58,
    help    = "Show one toy's collection state.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn toy <itemID or name>")
            return
        end

        local itemID = Toys.Resolve(args)

        if not itemID then
            Print("No known toy matches: " .. args)
            return
        end

        local record = Store()[itemID]

        Print(Toys.NameOf(itemID)
            .. " |cff8a8f96(" .. itemID .. ")|r")
        Print("Collected: " .. CN.YesNo(record.collected))
    end,
}

-- AND ONCE AT LOGIN. 0.62.0.
--
-- This store relied entirely on `NEW_TOY_ADDED`, which covers
-- collections made while this session is running and nothing collected in a
-- session where the addon was not loaded. The store is persisted account-wide,
-- so a player who turns addons off for a raid night, collects three, and turns
-- them back on is recommended things they already own until they happen to run
-- the scan by hand.
--
-- `Appearances.lua` made exactly this argument in 0.58.0 and the same argument
-- applies verbatim here; three stores were left behind.
--
-- Guarded and quiet: this is a journal walk, and a client that refuses it must
-- not take the login sequence with it.
CN:OnLogin(function()
    CN.Guard("Toys.Scan", Toys.Scan)
end)
'@

$Embedded['Modules\Appearances.lua'] = @'
-- Modules/Appearances.lua
-- Completion Navigator :: transmog appearance progress.
--
-- Deliberately category-level rather than item-level. Enumerating every
-- appearance source is tens of thousands of entries and would bloat
-- SavedVariables for no decision-making benefit: the useful question is
-- "which slot am I furthest from finishing", not "which of 40,000 sources
-- do I lack". Per-item work belongs to a wardrobe addon.

local ADDON_NAME, CN = ...

local Appearances = CN:RegisterModule("Appearances")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("appearances")
end

Appearances.Store = Store

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Appearances.Scan()
    if not C_TransmogCollection then
        return 0
    end

    local store      = Store()
    local categories = Blizzard.GetAppearanceCategories()

    for _, category in ipairs(categories) do
        local held = store[category.categoryID]

        -- A ZERO FROM A CLIENT THAT HAS NOT LOADED THE WARDROBE IS NOT A
        -- MEASUREMENT.
        --
        -- `GetCategoryCollectedCount` falls back to zero when the collection
        -- is not ready, and this scan now runs at login -- so overwriting a
        -- scanned "184 of 260" with "0 of 260" would make the addon
        -- recommend every slot the player has already finished, until
        -- something transmoggable happened to fire the collection event.
        --
        -- Keeping the higher of the two is the honest reading: a count can
        -- only go up, and a refusal reads as zero.
        local collected = category.collected or 0

        if held and (held.collected or 0) > collected then
            collected = held.collected
        end

        -- NO `lastSeen`. 0.80.0.
        --
        -- Nothing has ever read an appearance record's `lastSeen`. Migration
        -- 5 stripped exactly this field from `achievements`, `pets`, `toys`
        -- and `achievementTotals` -- under a header about values "being
        -- written to disk on every logout and parsed again on every login" --
        -- and this store was the one it missed. Stripping alone would not
        -- have held anyway, because the writer here was never changed: the
        -- login scan and the ten-minute rescan would have put it straight
        -- back.
        store[category.categoryID] = {
            categoryID = category.categoryID,
            name       = category.name,
            collected  = collected,
            total      = category.total,
        }
    end

    CN.MarkScanned("appearances")

    return #categories
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Appearances.Summary()
    local counts = {
        categories = 0,
        collected  = 0,
        total      = 0,
        complete   = 0,
    }

    for _, record in pairs(Store()) do
        counts.categories = counts.categories + 1
        counts.collected  = counts.collected + (record.collected or 0)
        counts.total      = counts.total + (record.total or 0)

        if record.total and record.total > 0 and record.collected >= record.total then
            counts.complete = counts.complete + 1
        end
    end

    return counts
end

-- Categories sorted by how many appearances remain, most first.
function Appearances.Remaining()
    local rows = {}

    for _, record in pairs(Store()) do
        local remaining = (record.total or 0) - (record.collected or 0)

        if remaining > 0 then
            table.insert(rows, {
                name      = record.name,
                collected = record.collected,
                total     = record.total,
                remaining = remaining,
            })
        end
    end

    table.sort(rows, function(a, b) return a.remaining > b.remaining end)

    return rows
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- How many slots are worth surfacing. Beyond a few, "your least complete
-- slot" stops being a next action and becomes a table.
Appearances.candidateSlots = 3

-- Appearances are tracked per category, not per item -- enumerating every
-- appearance source is tens of thousands of entries. So the objective here is
-- the honest one the data supports: which slot is furthest from done.
--
-- It is deliberately low-valued. "Your chest slot is least complete" is a
-- direction to point yourself in, not a task, and it should never outrank
-- something with coordinates or a deadline.
CN.RegisterCandidateProvider("Appearances", function()
    local rows = {}

    for categoryID, record in pairs(Store()) do
        local total     = record.total or 0
        local collected = record.collected or 0

        if total > 0
            and collected < total
            and not CN.IsIgnored(CN.objectiveTypes.APPEARANCE, categoryID)
            and not CN.IsDeferred(CN.objectiveTypes.APPEARANCE, categoryID) then

            table.insert(rows, {
                categoryID = categoryID,
                name       = record.name,
                collected  = collected,
                total      = total,
                remaining  = total - collected,
                fraction   = collected / total,
            })
        end
    end

    -- Least complete first; ties by ID so the list does not reshuffle.
    table.sort(rows, function(a, b)
        if a.fraction ~= b.fraction then
            return a.fraction < b.fraction
        end

        return a.categoryID < b.categoryID
    end)

    local candidates = {}

    for index = 1, math.min(Appearances.candidateSlots, #rows) do
        local row = rows[index]

        table.insert(candidates, CN.NewObjective({
            id              = row.categoryID,
            type            = CN.objectiveTypes.APPEARANCE,
            name            = tostring(row.name) .. " appearances",
            accountWide     = true,
            completionValue = 1,
            reasons         = {
                row.collected .. " of " .. row.total .. " collected",
                row.remaining .. " remaining in this slot",
            },
        }))
    end

    CN.providerTruncation["Appearances"] = {
        considered = #rows,
        dropped    = math.max(0, #rows - #candidates),
    }

    return candidates
end, { events = { "TRANSMOG_COLLECTION_UPDATED" }, cooldown = 10 })

------------------------------------------------------------
-- KEEPING UP
------------------------------------------------------------

-- THE ONE SETUP STEP WITH NO REFRESH PATH AT ALL.
--
-- Every other scan has something that renews it: an event, a login hook, or
-- a command a player has a reason to run. Appearances had the provider's
-- invalidation -- which rebuilds the CANDIDATES from the store -- and nothing
-- that ever rebuilt the STORE. So it was read once by `/cn setup` and then
-- silently rotted: a month of collecting left the addon recommending
-- appearances the player already had.
--
-- Throttled hard, because the transmog event fires on every piece looted and
-- the scan walks every category.
Appearances.rescanSeconds = 600

local lastRescan = 0

-- AND ONCE AT LOGIN, which is the one path this store did not have.
--
-- Every other setup-scanned store -- currencies, reputations, titles,
-- professions, quests -- refreshes itself on login. This one relied on
-- `TRANSMOG_COLLECTION_UPDATED`, which covers appearances collected while
-- this session is running and nothing collected on another character or in a
-- session where the addon was not loaded. A player who logs in and loots
-- nothing transmoggable never fires it, and the counts stay as they were
-- whenever `/cn setup` last ran -- which is the "silently rotted" state this
-- file's own header describes.
CN:OnLogin(function()
    -- Protected and quiet: this is a journal walk, and a client that refuses
    -- it must not take the login sequence with it.
    CN.Guard("Appearances.Scan", Appearances.Scan)
end)

CN:RegisterEvent("TRANSMOG_COLLECTION_UPDATED", function()
    local now = time()

    if (now - lastRescan) < Appearances.rescanSeconds then
        return
    end

    lastRescan = now

    pcall(Appearances.Scan)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "appearancescan",
    aliases = { "transmogscan" },
    order   = 59,
    help    = "Scan transmog appearance categories.",
    handler = function()
        local categories = Appearances.Scan()

        Print("Scanned " .. categories .. " appearance categories.")
    end,
}

CN:RegisterCommand{
    name    = "appearances",
    aliases = { "transmog" },
    order   = 60,
    help    = "Summarize transmog appearance progress.",
    handler = function()
        local counts = Appearances.Summary()

        if counts.categories == 0 then
            Print("No appearance data yet. Run /cn appearancescan.")
            return
        end

        Print("Appearances: " .. counts.collected .. " / " .. counts.total
            .. " (" .. CN.PercentText(
                counts.total > 0 and (counts.collected / counts.total) or 0, 1)
            .. ")")

        Print("Categories complete: " .. counts.complete .. " / " .. counts.categories)

        local rows = Appearances.Remaining()

        for index = 1, math.min(5, #rows) do
            local row = rows[index]

            CN.PrintLine("  " .. row.name .. ": " .. row.collected .. " / " .. row.total
                .. " |cff8a8f96(" .. row.remaining .. " left)|r")
        end

        if #rows > 5 then
            Print("  |cff8a8f96... and " .. (#rows - 5) .. " more categories.|r")
        end
    end,
}
'@

$Embedded['Modules\Titles.lua'] = @'
-- Modules/Titles.lua
-- Completion Navigator :: player titles.
--
-- Titles are character-specific, not account-wide: the client's IsTitleKnown
-- answers for the logged-in character only. Storing them per character is
-- what lets the Warband layer say which alt already has one.

local ADDON_NAME, CN = ...

local Titles = CN:RegisterModule("Titles")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

-- Known/unknown is per character. Names are not stored at all: see
-- `Titles.NameOf`.
local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.titles = character.titles or {}

    return character.titles
end

Titles.CharacterStore = CharacterStore

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Titles.Scan()
    local mine = CharacterStore()

    if not mine then
        return 0, 0
    end

    local seen, known = 0, 0

    for _, title in ipairs(Blizzard.GetTitles()) do
        -- `titleNames` IS NOT WRITTEN ANY MORE. 0.65.0.
        --
        -- 0.64.0 gave the hidden-objectives list a live client path for
        -- titles and left this writer alone, so the store went on filling
        -- with names frozen at whatever language last scanned -- and
        -- `Titles.Resolve` searched only that store, so a player who changed
        -- client language could not find their own titles by name.
        --
        -- Eighth store to lose a name it did not need to keep.

        mine[title.titleID] = title.known or nil

        seen = seen + 1

        if title.known then
            known = known + 1
        end
    end

    CN.MarkScanned("titles")

    if CN.character then
        CN.character.titlesKnown = known
    end

    return seen, known
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

-- `known` IS THE CLIENT'S OWN LIST LENGTH, NOT A STORED COUNT. 0.65.0.
--
-- It used to be `CountKeys(titleNames)` -- the store this version stopped
-- writing. Left alone it would have been zero on every character forever,
-- which is the number `/cn titles` and the Titles breakdown both branch on:
-- both would have told a player who had just scanned to go and scan.
--
-- `scanned` is what "no data yet" actually means. The client always knows how
-- many titles exist; only whether THIS character's known/unknown flags have
-- been read is a thing the addon has to remember.
function Titles.Summary()
    local mine = CharacterStore() or {}

    local counts = {
        known     = #(Blizzard.GetTitles and Blizzard.GetTitles() or {}),
        onThisOne = CN.CountKeys(mine),
        onAccount = 0,
        scanned   = (CN.Account("collectionScans") or {}).titles ~= nil,
    }

    -- A title counted once if any character has it.
    local anyCharacter = {}

    for _, character in CN.Characters() do
        if character.titles then
            for titleID in pairs(character.titles) do
                anyCharacter[titleID] = true
            end
        end
    end

    counts.onAccount = CN.CountKeys(anyCharacter)

    return counts
end

-- Which characters, if any, already have a title.
function Titles.WhoHas(titleID)
    local holders = {}

    for key, character in CN.Characters() do
        if character.titles and character.titles[titleID] then
            table.insert(holders, key)
        end
    end

    table.sort(holders)

    return holders
end

-- A title's name, from the client. Eighth of these; see `Achievements.NameOf`
-- for the first. 0.65.0.
--
-- NO FALLBACK TO A STORE, for the reason spelled out in `Currencies.NameOf`:
-- `CN.Account(key)` creates the table it is asked for, so a reader left
-- pointing at `titleNames` puts back the store migration 18 deleted.
function Titles.NameOf(titleID)
    local live = Blizzard.GetTitleName and Blizzard.GetTitleName(titleID)

    if live and live ~= "" then
        return live
    end

    return "Title " .. tostring(titleID)
end

-- OVER THE CLIENT'S WHOLE LIST, NOT OVER WHAT THIS CHARACTER HOLDS. 0.66.0.
--
-- 0.65.0 moved this off the `titleNames` store, which held every title the
-- scan had seen, and onto the character store -- which `Scan` writes only for
-- titles this character KNOWS. Both resolution paths then returned an id only
-- when the logged-in character already had the title, so `/cn title
-- Loremaster` on an alt answered "No known title matches" for a title the
-- main holds. The command's own help is "Show which characters have a title",
-- which is a question about the OTHER characters.
--
-- It also made one branch of the command unreachable: `WhoHas` always
-- includes the current character, so "Not earned by any known character"
-- could never print.
--
-- `Blizzard.GetTitles()` is the full list and is free.
function Titles.Resolve(text)
    local titleID = CN.ToID(text)

    if titleID then
        return titleID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for _, title in ipairs(Blizzard.GetTitles()) do
        local name = title.name or Titles.NameOf(title.titleID)

        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = title.titleID, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- WHY THERE IS NO CANDIDATE PROVIDER HERE
------------------------------------------------------------

-- Every other collection module contributes recommendations. Titles
-- deliberately does not, and this comment exists so that absence reads as a
-- decision rather than an oversight.
--
-- A recommendation has to name an action. The client exposes a title's name
-- and whether this character has it, and nothing else -- no source, no
-- coordinates, no criteria. "You do not have Loremaster" is a fact, not a next
-- action, and emitting it would push a row with no location and no route into
-- a list whose entire purpose is to be actionable.
--
-- Titles are still fully tracked and reported: /cn titles, /cn who title, the
-- Collections tab and /cn breakdown all read this store directly. And a title
-- someone actually wants can be pinned with /cn goal title <id>, which is the
-- correct place for "I have decided I want this even though the addon cannot
-- tell me how to get it".

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

CN.RegisterEligibilityChecker(CN.objectiveTypes.TITLE, function(titleID)
    local states = CN.objectiveStates
    local mine   = CharacterStore()

    if mine and mine[titleID] then
        return states.COMPLETED, "Already earned by this character",
               Titles.NameOf(titleID)
    end

    local holders = Titles.WhoHas(titleID)

    if #holders > 0 then
        return states.REQUIRES_OTHER_CHARACTER,
               CN.blockReasons.BETTER_CHARACTER,
               table.concat(holders, ", ")
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("KNOWN_TITLES_UPDATE", function()
    local seen, known = Titles.Scan()

    DebugPrint("Title scan: " .. known .. " known of " .. seen .. ".")
end)

CN:OnLogin(function()
    Titles.Scan()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "titlescan",
    order   = 61,
    help    = "Scan this character's titles.",
    handler = function()
        local seen, known = Titles.Scan()

        Print("Scanned " .. seen .. " titles.")
        Print("Known by this character: " .. known)
    end,
}

CN:RegisterCommand{
    name    = "titles",
    order   = 62,
    help    = "Summarize title progress.",
    handler = function()
        local counts = Titles.Summary()

        if not counts.scanned then
            Print("No title data yet. Run /cn titlescan.")
            return
        end

        Print("Titles in the game: " .. counts.known)
        Print("Known by this character: " .. counts.onThisOne)
        Print("Known by any character: " .. counts.onAccount)
    end,
}

CN:RegisterCommand{
    name    = "title",
    args    = "<titleID or name>",
    order   = 63,
    help    = "Show which characters have a title.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn title <titleID or name>")
            return
        end

        local titleID = Titles.Resolve(args)

        if not titleID then
            Print("No known title matches: " .. args)
            return
        end

        Print(Titles.NameOf(titleID) .. " |cff8a8f96(" .. titleID .. ")|r")

        local holders = Titles.WhoHas(titleID)

        if #holders == 0 then
            Print("Not earned by any known character.")
        else
            Print("Earned by: " .. table.concat(holders, ", "))
        end
    end,
}
'@

$Embedded['Modules\Professions.lua'] = @'
-- Modules/Professions.lua
-- Completion Navigator :: professions, skill levels, and recipes.
--
-- Two important constraints shape this module.
--
-- 1. Professions are character-specific. Which alt has Alchemy at what
--    skill is exactly the Warband question, so profession state is stored
--    on the character profile.
--
-- 2. Recipe enumeration ONLY works while a trade skill window is open.
--    C_TradeSkillUI.GetAllRecipeIDs returns nothing otherwise. This is a
--    hard client restriction, not a design choice, so recipes are captured
--    opportunistically whenever the player opens a profession and are then
--    persisted. The addon tells the player which professions it is still
--    waiting to see rather than silently reporting zero.

local ADDON_NAME, CN = ...

local Professions = CN:RegisterModule("Professions")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.professions = character.professions or {}

    return character.professions
end

-- Recipes are keyed by skill line, then recipe ID. Known-ness is per
-- character, so it lives under the character; the recipe's name is shared.
local function RecipeNames()
    return CN.Account("recipeNames")
end

local function CharacterRecipes(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.recipes = character.recipes or {}

    return character.recipes
end

Professions.CharacterStore   = CharacterStore
Professions.RecipeNames      = RecipeNames
Professions.CharacterRecipes = CharacterRecipes

------------------------------------------------------------
-- PROFESSION SCAN
------------------------------------------------------------

function Professions.Scan()
    local store = CharacterStore()

    if not store then
        return 0
    end

    local lines = Blizzard.GetProfessionSkillLines()

    for _, line in ipairs(lines) do
        local existing = store[line.skillLineID]

        -- WHAT WAS CAPTURED SURVIVES THE RESCAN.
        --
        -- This rebuilt the row wholesale and carried over only
        -- `recipesSeen`, so opening your Alchemy window (which records how
        -- many recipes you know of how many there are) and then logging out
        -- lost both numbers -- Scan runs on every login. The display branches
        -- on `recipesSeen` alone, so it then printed "(nil of nil recipes)".
        --
        -- Rank and name come from the client and are refreshed; the recipe
        -- counts come from a window the player has to open and cannot be.
        store[line.skillLineID] = {
            skillLineID  = line.skillLineID,
            name         = line.name,
            rank         = line.rank,
            maxRank      = line.maxRank,
            recipesSeen  = existing and existing.recipesSeen or false,
            recipeTotal  = existing and existing.recipeTotal or nil,
            recipeKnown  = existing and existing.recipeKnown or nil,
            recipesAt    = existing and existing.recipesAt or nil,
        }
    end

    if CN.character then
        CN.character.professionsScanned = time()
    end

    -- The Professions provider reads this store, and nothing told it the
    -- store had been rewritten -- so a scan left the recommendations built
    -- from the state before it.
    CN.MarkScanned("professions")

    return #lines
end

------------------------------------------------------------
-- RECIPE CAPTURE
------------------------------------------------------------

-- Called when a trade skill window is open and ready. Everything about
-- this function is opportunistic by necessity.
function Professions.CaptureOpenProfession()
    if not Blizzard.IsTradeSkillReady() then
        return false, 0, 0
    end

    local skillLineID, professionName = Blizzard.GetOpenTradeSkillLine()

    if not skillLineID then
        return false, 0, 0
    end

    local names    = RecipeNames()
    local mine     = CharacterRecipes()
    local store    = CharacterStore()

    if not mine or not store then
        return false, 0, 0
    end

    local recipeIDs = Blizzard.GetAllRecipeIDs()

    local seen, known = 0, 0

    for _, recipeID in ipairs(recipeIDs) do
        local info = Blizzard.GetRecipeInfo(recipeID)

        if info then
            seen = seen + 1

            -- ONLY WHEN A NAME ACTUALLY CHANGES. 0.89.0.
            --
            -- The write is idempotent -- almost every pass sets a key to the
            -- value it already holds -- and the revision moved anyway, once
            -- per recipe, about 2,500 times per capture. This runs from
            -- `TRADE_SKILL_LIST_UPDATE`, which `Scoring.lua` classifies as
            -- bursty, so the next tooltip after every list update rebuilt the
            -- whole index: 2,500 iterations and 2,500 `string.lower`
            -- allocations. That is the per-mouseover cost this index was
            -- written to remove, reintroduced at the one moment the player is
            -- hovering items in their profession window.
            if info.name and info.name ~= "" then
                if names[recipeID] ~= info.name then
                    names[recipeID] = info.name

                    -- The name index is now stale.
                    Professions.nameRevision =
                        (Professions.nameRevision or 0) + 1
                end
            end

            if info.learned then
                known = known + 1

                mine[recipeID] = skillLineID
            else
                mine[recipeID] = nil
            end
        end
    end

    store[skillLineID] = store[skillLineID] or {
        skillLineID = skillLineID,
        name        = professionName,
    }

    store[skillLineID].recipesSeen  = true
    store[skillLineID].recipeTotal  = seen
    store[skillLineID].recipeKnown  = known
    store[skillLineID].recipesAt    = time()

    CN.MarkScanned("recipes")

    return true, seen, known
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Professions.Summary(character)
    local store = CharacterStore(character) or {}

    local rows = {}

    for _, record in pairs(store) do
        table.insert(rows, record)
    end

    table.sort(rows, function(a, b) return (a.name or "") < (b.name or "") end)

    return rows
end

-- Professions this character has but whose recipe list has never been seen.
function Professions.AwaitingRecipeCapture(character)
    local waiting = {}

    for _, record in pairs(CharacterStore(character) or {}) do
        if not record.recipesSeen then
            table.insert(waiting, record.name or ("skill line " .. record.skillLineID))
        end
    end

    table.sort(waiting)

    return waiting
end

-- Which characters know a recipe, for the Warband question.
function Professions.WhoKnows(recipeID)
    local holders = {}

    for key, character in CN.Characters() do
        if character.recipes and character.recipes[recipeID] then
            table.insert(holders, key)
        end
    end

    table.sort(holders)

    return holders
end

-- Best character for a profession, by skill rank.
function Professions.BestCharacterFor(skillLineID)
    local bestKey, bestRecord

    for key, character in CN.Characters() do
        local record = character.professions and character.professions[skillLineID]

        if record and (not bestRecord or (record.rank or 0) > (bestRecord.rank or 0)) then
            bestKey    = key
            bestRecord = record
        end
    end

    return bestKey, bestRecord
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A profession below its cap is one of the few completion objectives that is
-- unambiguously actionable: you know the skill, you know the number, and the
-- work is entirely in your hands.
--
-- Character-scoped on purpose. Professions do not carry across a Warband, and
-- pretending otherwise would put an alt's blacksmithing in front of you.
CN.RegisterCandidateProvider("Professions", function()
    local store = CharacterStore()

    if not store then
        return {}
    end

    local candidates = {}

    for skillLineID, record in pairs(store) do
        local rank    = record.rank or 0
        local maxRank = record.maxRank or 0

        local remaining = maxRank - rank

        if maxRank > 0
            and remaining > 0
            and not CN.IsIgnored(CN.objectiveTypes.PROFESSION, skillLineID)
            and not CN.IsDeferred(CN.objectiveTypes.PROFESSION, skillLineID) then

            local fraction = rank / maxRank

            -- Nearly finished is worth more than barely started: the last few
            -- points are the ones a nudge actually completes.
            local value = (fraction >= 0.9) and 3 or (fraction >= 0.5) and 2 or 1

            local reasons = {
                rank .. " of " .. maxRank .. ", " .. remaining .. " to go",
            }

            if not record.recipesSeen then
                table.insert(reasons,
                    "open its window once so recipes can be recorded")
            end

            table.insert(candidates, CN.NewObjective({
                id              = skillLineID,
                type            = CN.objectiveTypes.PROFESSION,
                name            = record.name,
                accountWide     = false,
                characterSpecific = true,
                completionValue = value,
                reasons         = reasons,
            }))
        end
    end

    local kept, dropped = CN.CapCandidates(candidates)

    CN.providerTruncation["Professions"] = {
        considered = #kept + dropped,
        dropped    = dropped,
    }

    return kept
end, { events = { "TRADE_SKILL_LIST_UPDATE" }, cooldown = 5 })

CN.RegisterEligibilityChecker(CN.objectiveTypes.RECIPE, function(recipeID)
    local states = CN.objectiveStates
    local mine   = CharacterRecipes()

    if mine and mine[recipeID] then
        return states.COMPLETED, "Already known by this character", RecipeNames()[recipeID]
    end

    local holders = Professions.WhoKnows(recipeID)

    if #holders > 0 then
        return states.REQUIRES_OTHER_CHARACTER,
               CN.blockReasons.BETTER_CHARACTER,
               table.concat(holders, ", ")
    end

    return states.UNKNOWN, "No recipe data; open the profession window once", nil
end)

CN.RegisterEligibilityChecker(CN.objectiveTypes.PROFESSION, function(skillLineID)
    local states = CN.objectiveStates
    local store  = CharacterStore()
    local record = store and store[skillLineID]

    if not record then
        local bestKey = Professions.BestCharacterFor(skillLineID)

        if bestKey then
            return states.REQUIRES_OTHER_CHARACTER,
                   CN.blockReasons.MISSING_PROFESSION,
                   bestKey
        end

        return states.INELIGIBLE, CN.blockReasons.MISSING_PROFESSION, nil
    end

    if record.maxRank and record.rank and record.rank >= record.maxRank then
        return states.COMPLETED, "Skill is maxed for this expansion", record.name
    end

    return states.AVAILABLE, nil, nil
end)

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("TRADE_SKILL_SHOW", function()
    -- The list is not populated yet at SHOW; wait for the list update.
    DebugPrint("Trade skill window opened.")
end)

CN:RegisterEvent("TRADE_SKILL_LIST_UPDATE", function()
    local captured, seen, known = Professions.CaptureOpenProfession()

    if captured then
        DebugPrint("Captured " .. seen .. " recipes (" .. known .. " known).")
    end
end)

CN:RegisterEvent("SKILL_LINES_CHANGED", function()
    Professions.Scan()
end)

CN:OnLogin(function()
    Professions.Scan()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "profscan",
    order   = 70,
    help    = "Rescan this character's professions.",
    handler = function()
        local count = Professions.Scan()

        Print("Found " .. count .. " professions on this character.")

        local waiting = Professions.AwaitingRecipeCapture()

        if #waiting > 0 then
            Print("Recipe lists not captured yet for: " .. table.concat(waiting, ", "))
            Print("Open each profession window once; the client only exposes "
                .. "recipes while that window is open.")
        end
    end,
}

CN:RegisterCommand{
    name    = "professions",
    aliases = { "profs" },
    order   = 71,
    help    = "Show profession skill and recipe counts.",
    handler = function()
        local rows = Professions.Summary()

        if #rows == 0 then
            Print("No professions recorded. Run /cn profscan.")
            return
        end

        for _, record in ipairs(rows) do
            local line = record.name .. ": " .. tostring(record.rank)
                .. " / " .. tostring(record.maxRank)

            if record.recipesSeen then
                line = line .. " |cff8a8f96(" .. tostring(record.recipeKnown)
                    .. " of " .. tostring(record.recipeTotal) .. " recipes)|r"
            else
                line = line .. " |cffffc74f(recipes not captured)|r"
            end

            CN.PrintLine(line)
        end

        local waiting = Professions.AwaitingRecipeCapture()

        if #waiting > 0 then
            Print("Open the profession window once for: " .. table.concat(waiting, ", "))
        end
    end,
}

CN:RegisterCommand{
    name    = "recipes",
    order   = 72,
    help    = "Summarize recipe knowledge across the Warband.",
    handler = function()
        local names = RecipeNames()
        local total = CN.CountKeys(names)

        if total == 0 then
            Print("No recipes recorded yet.")
            Print("Open each profession window once with the addon loaded.")
            return
        end

        Print("Recipes seen: " .. total)

        for key, character in CN.Characters() do
            local count = CN.CountKeys(character.recipes)

            if count > 0 then
                CN.PrintLine("  " .. key .. ": " .. count .. " known")
            end
        end
    end,
}

CN:RegisterCommand{
    name    = "recipe",
    args    = "<recipeID or name>",
    order   = 73,
    help    = "Show which characters know a recipe.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn recipe <recipeID or name>")
            return
        end

        local names    = RecipeNames()
        local recipeID = CN.ToID(args)

        if not recipeID or not names[recipeID] then
            local needle = string.lower(args)

            for id, name in pairs(names) do
                if name and string.find(string.lower(name), needle, 1, true) then
                    recipeID = id
                    break
                end
            end
        end

        if not recipeID or not names[recipeID] then
            Print("No known recipe matches: " .. args)
            return
        end

        Print(names[recipeID] .. " |cff8a8f96(" .. recipeID .. ")|r")

        local holders = Professions.WhoKnows(recipeID)

        if #holders == 0 then
            Print("Not known by any recorded character.")
        else
            Print("Known by: " .. table.concat(holders, ", "))
        end
    end,
}

------------------------------------------------------------
-- NAME LOOKUP
------------------------------------------------------------

-- Lowercased recipe name -> recipeID.
--
-- WHY THIS EXISTS. The item tooltip needed to answer "is this item a recipe
-- I know?", and the only way it could was to walk every recipe name looking
-- for a match -- two string allocations and a substring search per entry,
-- twenty-five hundred of them, on EVERY mouseover. Measured at 0.54ms per
-- tooltip, which is three per cent of a frame for hovering one item, and
-- sweeping a bag or an auction list fires dozens in a second.
--
-- Built once against a revision the scanner bumps, and consulted with two
-- hash lookups.
Professions.nameRevision = Professions.nameRevision or 0

function Professions.NameIndex()
    return CN.Shortlist("RecipeNames", Professions.nameRevision, function()
        local index = {}

        for recipeID, name in pairs(RecipeNames()) do
            if type(name) == "string" and name ~= "" then
                index[string.lower(name)] = recipeID
            end
        end

        return index
    end)
end

-- The words the game puts in front of a recipe's name on the item that
-- teaches it. "Recipe: Flask of Testing" teaches "Flask of Testing".
Professions.teachingPrefixes = {
    "recipe: ", "pattern: ", "plans: ", "formula: ", "schematic: ",
    "design: ", "technique: ", "manuscript: ", "method: ", "glyph: ",
}

-- The separators every locale puts between the teaching word and the recipe
-- name. The WORD is translated; the punctuation is not, and French puts a
-- space before its colon. Two lookups at worst, and only on an item whose
-- name did not match a recipe outright.
Professions.teachingSeparators = { ": ", " : ", "\239\188\154" }

-- The recipe an item teaches, or nil. O(1) rather than O(every recipe).
function Professions.RecipeForItem(itemName)
    -- AN ITEM ID IS NOT A RECIPE ID. 0.80.0.
    --
    -- This began "the item IS the recipe, which is the cheapest case", and
    -- indexed `recipeNames` -- whose only writer is `CaptureOpenProfession`,
    -- writing `names[recipeID]` from `C_TradeSkillUI.GetAllRecipeIDs` -- with
    -- an ITEM id. Two unrelated number spaces, one table.
    --
    -- `Filters.lua` describes this exact collision three files over: "a
    -- trade-skill recipe id from Professions -- which is what `recipeNames`
    -- is keyed by", and warns that such a number, "where it happens to
    -- collide with a real item", names something wholly unrelated. This was
    -- the same collision run backwards, and it did more damage than a wrong
    -- name: the second return is the "matched by name" flag, and returning
    -- `false` told the tooltip the guess was an EXACT id match, so the
    -- caveat that would have warned the player was suppressed.
    --
    -- The consequence was a "Recipe: not known by this character" block, and
    -- a roster of which alts know it, on a stack of ore. The name lookup
    -- below is the only correct answer and was always there.
    if type(itemName) ~= "string" or itemName == "" then
        return nil
    end

    local index = Professions.NameIndex()

    local needle = string.lower(itemName)

    local direct = index[needle]

    if direct then
        return direct
    end

    -- Strip a teaching prefix and try again. This replaces a scan over every
    -- recipe with one lookup per known prefix.
    for _, prefix in ipairs(Professions.teachingPrefixes) do
        if string.sub(needle, 1, #prefix) == prefix then
            local taught = index[string.sub(needle, #prefix + 1)]

            if taught then
                return taught
            end
        end
    end

    -- AND THE PREFIX LIST IS ENGLISH, WHICH THE ITEM NAME IS NOT. 0.62.0.
    --
    -- "Recipe: Flask of Testing" is "Rezept: Fläschchen ..." on a German
    -- client, so every teaching item fell through and the tooltip join --
    -- "you already know this", "Zeddicus knows it" -- was silently dead for
    -- roughly half the player base. Third defect of this shape found in this
    -- addon; the rule is the same each time.
    --
    -- The separator is not localized even where the word is: every locale the
    -- game ships writes these as "<word><separator> <recipe name>". So the
    -- prefix is found STRUCTURALLY -- take what follows the first separator
    -- and ask whether it names a recipe -- and the English list above stays
    -- only as the fast path that avoids this work on an English client.
    for _, separator in ipairs(Professions.teachingSeparators) do
        local at = string.find(needle, separator, 1, true)

        if at then
            local taught = index[CN.Trim(string.sub(needle, at + #separator))]

            if taught then
                return taught
            end
        end
    end

    return nil
end
'@

$Embedded['Modules\Harvest.lua'] = @'
-- Modules/Harvest.lua
-- Completion Navigator :: build the static database from your own play.
--
-- The curated database is the addon's bottleneck: prerequisite forensics,
-- zone percentages and unlock scoring all need quest records that nobody has
-- typed in yet. External providers help only if the player has those addons
-- installed.
--
-- This module needs nothing. Every quest you pick up gets its name, zone,
-- coordinates and level recorded permanently, account-wide. Playing the game
-- fills the database.
--
-- /cn export then emits it as a Data\Quests.lua block, so what you harvest
-- can be committed and shipped to everyone.

local ADDON_NAME, CN = ...

local Harvest = CN:RegisterModule("Harvest")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("questHarvest")
end

Harvest.Store = Store

-- The map's name, derived rather than remembered.
function Harvest.Zone(record)
    if type(record) ~= "table" or not record.mapID then
        return nil
    end

    return Blizzard.GetMapName(record.mapID)
end

-- A CEILING, BECAUSE THIS IS THE LARGEST THING THE ADDON SAVES.
--
-- Every quest accepted, turned in, or seen at login gets a permanent record,
-- and there was no cap and no prune. Migration 6 gave `questPins` a ceiling
-- of 600 for exactly this reason and did not touch this store, whose rows are
-- larger.
Harvest.cap = 2000

-- HYSTERESIS, WHICH IS NOT OPTIONAL AT THE CEILING.
--
-- "Count before allocating" fixed the case below the cap and did nothing at
-- it: once the store holds `cap + 1` rows, EVERY capture builds a 2001-row
-- array and sorts it to drop exactly one row -- and `Capture` runs in a loop
-- over the whole quest log at login. Measured: 82 ms of blocked frames for
-- forty captures, against 1.6 ms below the cap. It also threw away the unlock
-- inversion forty times in the process.
--
-- Let it overshoot by a tenth, then prune back to the cap. One sort per two
-- hundred captures instead of one per capture, for two hundred rows of slack
-- on a store that holds two thousand. `Session.offerMemoryCap` has had this
-- since 0.28.0 for the same reason.
Harvest.pruneSlack = 200

-- AND THE EVICTION ORDER WAS BACKWARDS FOR THE PLAYER MOST LIKELY TO HIT IT.
--
-- It dropped the lowest quest ids, on the reasoning that a low id is old
-- content nobody is working on. That reasoning describes a max-level
-- character doing current content. It describes the exact opposite of a
-- levelling alt, whose entire quest log is low ids -- so the store threw away
-- the records for the zones that character is standing in, kept the main's
-- endgame chains, and did it again on the next capture.
--
-- Least-recently-seen instead. `lastSeen` is stamped on every capture, so it
-- means "the addon has not touched this quest in a while" regardless of which
-- expansion it belongs to -- which is the actual question. A record with no
-- `lastSeen` is from before it was recorded and goes first.
--
-- Ties break on the quest id so the result is deterministic; two records
-- written in the same second must not evict in table order, which is not an
-- order.
function Harvest.Prune()
    local store = Store()

    -- COUNT FIRST, ALLOCATE SECOND.
    --
    -- `Prune` runs at the end of every `Capture`, and `Capture` runs in a loop
    -- over the whole quest log at login. Building the sort array before
    -- checking the cap meant two thousand table allocations per captured
    -- quest, thrown away immediately in the overwhelmingly common case where
    -- there is nothing to prune. `Session.Prune` and `Preference.Prune` both
    -- check a cheap counter first, for exactly this reason.
    local held = 0

    for _ in pairs(store) do
        held = held + 1
    end

    if held <= (Harvest.cap + Harvest.pruneSlack) then
        return 0
    end

    local rows = {}

    for questID, record in pairs(store) do
        table.insert(rows, {
            id   = questID,
            seen = (type(record) == "table" and record.lastSeen) or 0,
        })
    end

    table.sort(rows, function(a, b)
        if a.seen == b.seen then
            return a.id < b.id
        end

        return a.seen < b.seen
    end)

    local dropped = #rows - Harvest.cap

    for index = 1, dropped do
        store[rows[index].id] = nil
    end

    -- THROUGH `NoteUnlocksChanged`, NOT BY TOUCHING THE COUNTER.
    --
    -- That function's own header explains why bumping `unlockGeneration`
    -- alone is not enough: the Unlocks decorator only consults it if
    -- `Decorate` runs at all, and the unchanged-provider shortcut skips
    -- that. So after a prune dropped rows, quests kept an `unlockValue` --
    -- weight 1.5, the second-heaviest term -- and a `/cn why` sentence
    -- reading "4 quests you have seen come after this one", derived from
    -- records that no longer existed.
    Harvest.NoteUnlocksChanged()

    DebugPrint("Pruned " .. dropped .. " least-recently-seen harvested "
        .. "quest(s) over the ceiling.")

    return dropped
end

------------------------------------------------------------
-- CAPTURE
------------------------------------------------------------

-- Records everything currently knowable about a quest. Safe to call
-- repeatedly: fields are only filled in, never blanked, because the client
-- answers for a quest in the log and goes quiet once it is turned in.
function Harvest.Capture(questID, reason)
    questID = CN.ToID(questID)

    if not questID then
        return false
    end

    local store  = Store()
    local record = store[questID] or { questID = questID, firstSeen = time() }

    local changed = false

    local function set(field, value)
        if value ~= nil and record[field] == nil then
            record[field] = value
            changed = true
        end
    end

    local quests = CN:GetModule("Quests")

    if quests then
        set("name", quests.GetName(questID, false))
    end

    local mapID, x, y = Blizzard.GetQuestWaypoint(questID)

    set("mapID", mapID)

    if x and y then
        set("x", math.floor(x * 10000 + 0.5) / 10000)
        set("y", math.floor(y * 10000 + 0.5) / 10000)
    end

    -- ZONE IS NOT STORED. It is `GetMapName(record.mapID)`, which the client
    -- answers for free and forever -- the same duplication migrations 4 and 5
    -- removed from items, achievements and pets. The coordinates genuinely
    -- are not re-suppliable after a turn-in and stay; the name of the map
    -- they are on always is.
    --
    -- Read back through Harvest.Zone below, so nothing that wants it has to
    -- know where it comes from.

    -- The level the character was when the quest became available is a
    -- usable lower bound on the quest's own level requirement.
    if record.observedLevel == nil then
        record.observedLevel = UnitLevel("player")
        changed = true
    end

    if CN.character and record.faction == nil then
        record.faction = CN.character.faction
        changed = true
    end

    -- Anything an installed provider knows, captured once so it survives
    -- that addon being uninstalled later.
    if not record.requires then
        local external = CN.QueryQuestDataProviders(questID)

        if external then
            set("name", external.name)
            set("mapID", external.mapID)
            set("x", external.x)
            set("y", external.y)
            set("requiresLevel", external.requiresLevel)

            if external.requires then
                record.requires  = external.requires

                Harvest.NoteUnlocksChanged()

                -- `requiresFrom`: which addons answered. It was written as
                -- `requiredBy`, a name meaning the opposite -- the quests
                -- this one unlocks -- and read by nothing, so the misnomer
                -- had no effect beyond misleading the next reader.
                record.requiresFrom = external.providers
                changed = true
            end
        end
    end

    record.lastSeen = time()
    record.reason   = record.reason or reason

    store[questID] = record

    Harvest.Prune()

    if changed then
        DebugPrint("Harvested quest " .. questID
            .. (record.name and (" (" .. record.name .. ")") or ""))
    end

    return changed
end

------------------------------------------------------------
-- INFERRED PREREQUISITES
------------------------------------------------------------

-- When a quest is accepted, every quest completed immediately beforehand is a
-- *candidate* prerequisite. One observation is a correlation and nothing more.
--
-- What turns correlation into something usable is REPETITION ACROSS
-- CHARACTERS. If quest B follows quest A on one character, that is the order
-- you happened to play. If it follows on three characters, that is the game
-- telling you A gates B -- because independent playthroughs do not agree by
-- accident, and an alt cannot inherit the coincidence.
--
-- So observations accumulate per prerequisite, counted by distinct character,
-- and only cross into the dependency graph once enough characters agree. Even
-- then they are labelled as observed, never as fact, and curated data always
-- wins over them.
local recentTurnIns = {}

-- How many DISTINCT characters must show the same ordering. Two is a
-- coincidence you could plausibly hit; three is a pattern.
Harvest.confidenceThreshold = 3

-- Forgets recent turn-ins.
--
-- Called on login: a quest accepted in this session must not be correlated
-- with one turned in before the last logout. The 300-second window mostly
-- covers that already, but "mostly" is how a false prerequisite gets recorded
-- and then repeated on other characters until it looks confident.
function Harvest.ResetRecent()
    recentTurnIns = {}
end

function Harvest.NoteTurnIn(questID)
    -- A TURN-IN WITH NO ID IS NOT A TURN-IN. 0.73.0.
    --
    -- The client always names the quest, so this was latent -- but the id is
    -- used as a TABLE KEY a few lines down, in `observed[entry.questID]`, and
    -- a nil key throws rather than degrading. A harness dispatch without one
    -- found it, and the rule here is that a stub must not be more forgiving
    -- than the client: if the addon can be reached with no id, it must
    -- survive being reached with no id.
    if not questID then
        return
    end

    table.insert(recentTurnIns, 1, { questID = questID, at = time() })

    for index = #recentTurnIns, 6, -1 do
        table.remove(recentTurnIns, index)
    end
end

-- observed[prereqID] = { seen = n, characters = { [key] = true } }
local function Observations(record)
    record.observed = record.observed or {}

    return record.observed
end

Harvest.Observations = Observations

function Harvest.NoteAccepted(questID)
    local record = Store()[questID]

    if not record then
        return
    end

    local observed = Observations(record)

    local characterKey = CN.characterKey or "unknown"

    for _, entry in ipairs(recentTurnIns) do
        -- Only within a short window; anything older is coincidence.
        if time() - entry.at <= 300 and entry.questID ~= questID then
            local candidate = observed[entry.questID]

            if not candidate then
                candidate = { seen = 0, characters = {} }
                observed[entry.questID] = candidate
            end

            candidate.seen = candidate.seen + 1

            -- Counted by character, not by sighting: doing the same chain
            -- twice on one character is still one character's opinion.
            candidate.characters[characterKey] = true
        end
    end
end

-- How many distinct characters have shown this ordering.
function Harvest.Confidence(record, prerequisiteID)
    local observed = record and record.observed

    local candidate = observed and observed[prerequisiteID]

    if not candidate then
        return 0
    end

    return CN.CountKeys(candidate.characters or {})
end

-- Prerequisites confident enough to act on, for one quest.
function Harvest.ConfidentPrerequisites(questID)
    local record = Store()[questID]

    if not record or not record.observed then
        return {}
    end

    local confident = {}

    for prerequisiteID in pairs(record.observed) do
        if Harvest.Confidence(record, prerequisiteID) >= Harvest.confidenceThreshold then
            table.insert(confident, prerequisiteID)
        end
    end

    table.sort(confident)

    return confident
end

-- Everything currently confident, across every harvested quest.
function Harvest.AllConfident()
    local edges = {}

    for questID, record in pairs(Store()) do
        local confident = Harvest.ConfidentPrerequisites(questID)

        if #confident > 0 then
            edges[questID] = confident
        end
    end

    return edges
end

-- Feeds confident observations into the dependency graph.
--
-- They go in under `observedRequires`, NOT `requires`. The eligibility checker
-- reads both but reports them differently, so "you have not done X" and "on
-- three of your characters X came first" never read as the same claim.
function Harvest.PublishConfident()
    local published, recorded = 0, 0

    -- The store is reached through `WriteObservedPrerequisites` below, which
    -- owns the rule about when a stored inference may be rewritten.
    for questID, prerequisites in pairs(Harvest.AllConfident()) do
        -- SAYING WHOSE OBSERVATION THIS IS. 0.82.0.
        --
        -- `CN.AddDependency` merges field by field and clears nothing, and
        -- `Modules/Contribute.lua` writes `origin = "contributed"` through
        -- the same door -- earlier in the `.toc`, so its login hook runs
        -- first. This publisher then overwrote `observedRequires` and left
        -- that origin standing, so the player's OWN three-character
        -- observation was reported by `/cn why` as "from an imported chain,
        -- not from your own play" -- a false provenance claim in the one
        -- place `Contribute.lua` calls "the whole safety model".
        CN.AddDependency(CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID), {
            observedRequires = prerequisites,
            origin           = "harvested",
        })

        published = published + 1

        -- AND WRITE IT FLAT, so the toolkit can fold it into Data\Quests.lua
        -- without having to understand the nested evidence table.
        --
        -- Until 0.42.0 the confident sets existed only in memory and in the
        -- dependency graph, which meant the shipped static data could never
        -- learn anything from real play -- the whole point of harvesting.
        --
        -- UNDER ITS OWN NAME, NOT `requires`.
        --
        -- Writing it as `requires` was the first attempt and it was wrong: the
        -- eligibility checker reads that field as curated fact, so /cn why
        -- stopped saying "on three of your characters X came first" and
        -- started saying "X is required" -- inference masquerading as
        -- authority, through a door I had just built for it. The existing
        -- test for that distinction caught it.
        -- WRITE-ONCE MEANT NEVER-CORRECTED. 0.63.0.
        --
        -- `not record.observedRequires` made the stored copy permanent: later
        -- play that widened or contradicted the observed set updated the
        -- in-memory graph and could never rewrite the row -- and the row is
        -- what the toolkit folds into the shipped data file. A chain observed
        -- twice early and disproved later kept the wrong answer for the life
        -- of the account.
        --
        -- The guard it should have been is "only when the answer changed",
        -- which keeps the write cheap without freezing it. `AllConfident`
        -- already applies the confidence threshold, so what arrives here is
        -- an observation the addon is prepared to stand behind.
        if Harvest.WriteObservedPrerequisites(questID, prerequisites) then
            recorded = recorded + 1
        end
    end

    if recorded > 0 then
        DebugPrint("Recorded " .. recorded
            .. " observed prerequisite set(s) for export.")
    end

    if published > 0 then
        DebugPrint("Published " .. published .. " observed prerequisite set(s).")
    end

    return published
end

CN:OnLogin(function()
    Harvest.ResetRecent()
    Harvest.PublishConfident()
end)

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Harvest.Summary()
    local counts = {
        total       = 0,
        named       = 0,
        located     = 0,
        withRequires = 0,
        withGuesses = 0,
    }

    for _, record in pairs(Store()) do
        counts.total = counts.total + 1

        if record.name then counts.named = counts.named + 1 end
        if record.x and record.y then counts.located = counts.located + 1 end
        if record.requires then counts.withRequires = counts.withRequires + 1 end
        -- `record.observed`, not `record.maybeRequires`. The old field was
        -- deleted by database migration 3 and nothing has written it since,
        -- so this counter reported zero guesses on every database in
        -- existence -- including every database that was full of them. The
        -- reader outlived the field by four schema versions because nothing
        -- ever asserted on the number it produced.
        if record.observed and next(record.observed) then
            counts.withGuesses = counts.withGuesses + 1
        end
    end

    return counts
end

------------------------------------------------------------
-- EXPORT
------------------------------------------------------------

-- Emits harvested rows in the exact shape Data\Quests.lua expects, so the
-- output can be pasted straight in and committed.
-- `CN.DASH` IS A CHAT GLYPH AND MUST NEVER REACH GENERATED SOURCE. 0.66.0.
--
-- A sweep that replaced the em-dash-as-`--` idiom across the addon reached
-- inside the three quoted strings here, which were deliberately emitting a
-- Lua COMMENT MARKER into the file this function generates. The result was an
-- export that could not be pasted into `Data/Quests.lua` at all: every
-- located row carried a line reading `" .. CN.DASH .. "Eversong Woods`, the
-- file failed to parse, and the addon did not load. The whole contribution
-- workflow this function exists for was broken. Asserted now by LOADING the
-- export rather than by looking at it.
function Harvest.BuildExport(onlyLocated)
    local rows = {}

    for questID, record in pairs(Store()) do
        if not onlyLocated or (record.x and record.y) then
            table.insert(rows, record)
        end
    end

    table.sort(rows, function(a, b) return a.questID < b.questID end)

    local lines = {}

    for _, record in ipairs(rows) do
        table.insert(lines, "    [" .. record.questID .. "] = {")

        if record.name then
            table.insert(lines, '        name      = "'
                .. record.name:gsub('"', '\\"') .. '",')
        end

        local zone = Harvest.Zone(record)

        if zone then
            table.insert(lines, "        -- " .. zone)
        end

        if record.mapID then
            table.insert(lines, "        mapID     = " .. record.mapID .. ",")
        end

        if record.x and record.y then
            table.insert(lines, "        x         = " .. record.x .. ",")
            table.insert(lines, "        y         = " .. record.y .. ",")
        end

        if record.requiresLevel then
            table.insert(lines, "        requiresLevel = " .. record.requiresLevel .. ",")
        end

        if record.requires and #record.requires > 0 then
            table.insert(lines, "        requires  = { "
                .. table.concat(record.requires, ", ") .. " },")
        end

        -- Confident observations become real rows; everything below the
        -- threshold stays a comment for a human to confirm. The distinction
        -- survives into the exported file, so curation never has to guess
        -- which lines were inferred.
        --
        -- `observedRequires`, NOT `requires`. Two things were wrong with
        -- writing it as `requires`. It emitted the key a second time in the
        -- same table constructor, so a quest that had both a provider answer
        -- and three-character agreement lost the provider's list entirely --
        -- Lua keeps the last assignment. And it is exactly the door
        -- PublishConfident closes thirty lines above, in a comment calling it
        -- "inference masquerading as authority": the runtime path was fixed
        -- and the export path -- the one that actually ships inference to
        -- other players -- still wrote it under the curated name.
        local confident = Harvest.ConfidentPrerequisites(record.questID)

        if #confident > 0 then
            table.insert(lines, "        -- observed on "
                .. Harvest.confidenceThreshold .. "+ characters")
            table.insert(lines, "        observedRequires = { "
                .. table.concat(confident, ", ") .. " },")
        end

        local unconfirmed = {}

        for prerequisiteID in pairs(record.observed or {}) do
            local seen = Harvest.Confidence(record, prerequisiteID)

            if seen < Harvest.confidenceThreshold then
                table.insert(unconfirmed, prerequisiteID .. " (" .. seen .. ")")
            end
        end

        table.sort(unconfirmed)

        if #unconfirmed > 0 then
            table.insert(lines, "        -- unconfirmed, character count in "
                .. "brackets: " .. table.concat(unconfirmed, ", "))
        end

        table.insert(lines, "    },")
    end

    return table.concat(lines, "\n"), #rows
end

------------------------------------------------------------
-- EXPORT WINDOW
------------------------------------------------------------

local exportFrame

local function ShowExport(text, count)
    if not exportFrame then
        exportFrame = CN.UI.SafeCreateFrame("Frame", "CompletionNavigatorExportFrame",
            UIParent, "BasicFrameTemplateWithInset")

        exportFrame:SetSize(600, 420)
        exportFrame:SetPoint("CENTER")
        exportFrame:SetMovable(true)
        exportFrame:EnableMouse(true)
        exportFrame:RegisterForDrag("LeftButton")
        exportFrame:SetScript("OnDragStart", exportFrame.StartMoving)
        exportFrame:SetScript("OnDragStop", exportFrame.StopMovingOrSizing)
        exportFrame:SetFrameStrata("DIALOG")

        if exportFrame.TitleText then
            exportFrame.TitleText:SetText("Completion Navigator - Export")
        end

        local scroll = CN.UI.SafeCreateFrame("ScrollFrame", nil, exportFrame,
            "UIPanelScrollFrameTemplate")

        scroll:SetPoint("TOPLEFT", 12, -32)
        scroll:SetPoint("BOTTOMRIGHT", -32, 40)

        local edit = CreateFrame("EditBox", nil, scroll)

        edit:SetMultiLine(true)
        edit:SetFontObject(CN.FONT.SMALL)
        edit:SetWidth(540)
        edit:SetAutoFocus(false)
        edit:SetScript("OnEscapePressed", function() exportFrame:Hide() end)

        scroll:SetScrollChild(edit)

        exportFrame.edit = edit

        local hint = CN.Label(exportFrame, "ARTWORK", "LABEL")
        hint:SetPoint("BOTTOMLEFT", 14, 14)
        hint:SetText("Ctrl+A then Ctrl+C, and paste into Data\\Quests.lua")

        table.insert(UISpecialFrames, "CompletionNavigatorExportFrame")
    end

    exportFrame.edit:SetText(text)
    exportFrame.edit:HighlightText()
    exportFrame.edit:SetFocus()
    exportFrame:Show()

    Print("Exported " .. count .. " harvested quests.")
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_ACCEPTED", function(event, questID)
    Harvest.Capture(questID, "accepted")
    Harvest.NoteAccepted(questID)
end)

CN:RegisterEvent("QUEST_TURNED_IN", function(event, questID)
    -- Capture before noting: the client still answers for it right now, and
    -- stops shortly afterwards.
    Harvest.Capture(questID, "turnedin")
    Harvest.NoteTurnIn(questID)
end)

-- Quests already in the log when the addon loads would otherwise be missed.
CN:OnLogin(function()
    for _, info in ipairs(Blizzard.GetQuestLogEntries()) do
        Harvest.Capture(info.questID, "login")
    end
end)

