-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "harvest",
    order   = 80,
    help    = "Show what has been harvested from play.",
    handler = function()
        local counts = Harvest.Summary()

        if counts.total == 0 then
            Print("Nothing harvested yet. Pick up and turn in quests with the addon loaded.")
            return
        end

        Print("Harvested quests: " .. counts.total)
        Print("  with names: " .. counts.named)
        Print("  with coordinates: " .. counts.located)
        Print("  with confirmed prerequisites: " .. counts.withRequires)
        Print("  with unconfirmed prerequisite guesses: " .. counts.withGuesses)
        Print("Use |cffffc74f/cn export|r to emit them as Data\\Quests.lua rows.")
    end,
}

CN:RegisterCommand{
    name    = "harvestnow",
    order   = 81,
    help    = "Harvest every quest currently in the log.",
    handler = function()
        local captured = 0

        for _, info in ipairs(Blizzard.GetQuestLogEntries()) do
            if Harvest.Capture(info.questID, "manual") then
                captured = captured + 1
            end
        end

        Print("Harvested " .. captured .. " quests from the current log.")
    end,
}

CN:RegisterCommand{
    name    = "export",
    args    = "[all]",
    order   = 82,
    help    = "Emit harvested quests as Data\\Quests.lua rows.",
    handler = function(args)
        local onlyLocated = string.lower(args or "") ~= "all"

        local text, count = Harvest.BuildExport(onlyLocated)

        if count == 0 then
            Print("Nothing to export yet."
                .. (onlyLocated and " Try |cffffc74f/cn export all|r to include "
                    .. "quests with no coordinates." or ""))
            return
        end

        ShowExport(text, count)
    end,
}

CN:RegisterCommand{
    name    = "providers",
    order   = 83,
    help    = "Show which external data addons were detected.",
    handler = function()
        Print("Quest data providers:")

        for _, entry in ipairs(CN.questDataOrder) do
            local provider = CN.questDataProviders[entry.name]

            local ok, isAvailable = pcall(provider.IsAvailable)

            local status = (ok and isAvailable)
                and "|cff73b873available|r"
                or "|cff8a8f96unavailable|r"

            local detail = ""

            if provider.Describe then
                local described, text = pcall(provider.Describe)

                if described and text then
                    detail = " |cff8a8f96(" .. text .. ")|r"
                end
            end

            CN.PrintLine("  " .. entry.name .. ": " .. status .. detail)
        end

        Print("Waypoint providers:")

        for _, entry in ipairs(CN.waypointOrder) do
            local provider = CN.waypointProviders[entry.name]

            local ok, isAvailable = pcall(provider.IsAvailable)

            CN.PrintLine("  " .. entry.name .. ": "
                .. ((ok and isAvailable) and "|cff73b873available|r" or "|cff8a8f96unavailable|r"))
        end
    end,
}

CN:RegisterCommand{
    name    = "lookup",
    args    = "<questID>",
    order   = 84,
    help    = "Ask every external provider about a quest.",
    handler = function(args)
        local questID = CN.ToID(args)

        if not questID then
            Print("Usage: /cn lookup <questID>")
            return
        end

        local data = CN.QueryQuestDataProviders(questID)

        if not data then
            Print("No external provider knows quest " .. questID .. ".")
            Print("Run |cffffc74f/cn providers|r to see what is installed.")
            return
        end

        Print("Quest " .. questID .. " |cff8a8f96via "
            .. table.concat(data.providers or {}, ", ") .. "|r")

        if data.name then Print("  name: " .. data.name) end

        if data.mapID then
            Print("  map: " .. data.mapID
                .. (data.x and string.format(" at %.1f, %.1f", data.x * 100, data.y * 100) or ""))
        end

        if data.requiresLevel then Print("  level: " .. data.requiresLevel) end

        if data.requires then
            Print("  requires: " .. table.concat(data.requires, ", "))
        end
    end,
}

------------------------------------------------------------
-- WHAT A QUEST UNLOCKS
------------------------------------------------------------

-- A SCORING TERM WITH ONE PRODUCER OUT OF TWENTY-TWO.
--
-- `unlockValue` carries a weight of 1.5 -- the second-heaviest term in the
-- scorer, above urgency and well above travel. Exactly one provider ever set
-- it: `Modules/Inventory.lua`, which writes a flat 1 for an item that teaches
-- something. Every quest, reputation, renown, profession and dungeon in the
-- addon contributed zero to "what it unlocks", for ever -- so the term did
-- not rank anything, it just sat in the explanation printing 0.00 and made
-- the arithmetic look thorough.
--
-- The addon already collects the evidence. `observedRequires` records, per
-- quest, which quests were seen completed before it across the player's own
-- characters. Invert that and you have, for a given quest, how many other
-- quests have been observed to sit behind it. That is what "unlocks" means,
-- measured, from this account's own play.
--
-- NO INVENTION. A quest nothing has been observed behind scores zero, exactly
-- as it does today. This raises a quest only on evidence the player generated
-- themselves, and `/cn why` names the count.

-- Rebuilt when the harvest changes rather than on every scoring pass: the
-- inversion is a full walk of a store that can hold two thousand rows, and
-- the ranking scores two hundred candidates.
Harvest.unlockGeneration = Harvest.unlockGeneration or 0

local unlockIndex, unlockIndexGeneration

-- Above this many, one more unlocked quest tells the ranking nothing it did
-- not already know, and a hub quest with forty followers must not out-score
-- everything else in the zone on its own.
Harvest.unlockCap = 6

-- AND SAY SO LOUDLY ENOUGH THAT SOMETHING ACTUALLY REDECORATES.
--
-- Bumping the counter was the whole of this, and the decorator only consults
-- the counter if `Decorate` runs at all -- which the unchanged-provider
-- shortcut skips, which is the normal case. So the count the release claims
-- to have unfrozen stayed frozen: the guard was correct and unreachable.
--
-- `CN.decoratorGeneration` is exactly the hook. The reuse condition requires
-- `entry.decorated == CN.decoratorGeneration`, so bumping it makes every
-- provider re-decorate on its next rebuild, and invalidating the candidates
-- makes that rebuild happen.
-- The stored copy of an observed ordering. Returns whether it changed.
--
-- Published because the rule it enforces -- rewrite only when the answer
-- actually moved, rather than never -- is the whole of the 0.63.0 fix, and a
-- rule only reachable through a full observation sweep is a rule nothing
-- tests directly.
function Harvest.WriteObservedPrerequisites(questID, prerequisites)
    local record = CN.Account("questHarvest")[questID]

    if not record or type(prerequisites) ~= "table" or #prerequisites == 0 then
        return false
    end

    if CN.SameIDList(record.observedRequires, prerequisites) then
        return false
    end

    record.observedRequires = prerequisites

    -- The unlock index is an inversion of exactly this field.
    Harvest.NoteUnlocksChanged()

    return true
end

function Harvest.NoteUnlocksChanged()
    Harvest.unlockGeneration = Harvest.unlockGeneration + 1

    CN.NoteDecoratorsChanged()
end

function Harvest.UnlockIndex()
    if unlockIndex and unlockIndexGeneration == Harvest.unlockGeneration then
        return unlockIndex
    end

    local index = {}

    for _, record in pairs(Store()) do
        if type(record) == "table" then
            -- Both sources, and deduplicated per record: a prerequisite named
            -- by the external provider AND observed in play is one unlock,
            -- not two.
            local counted = {}

            -- NOT `ipairs({ record.requires, record.observedRequires })`.
            --
            -- A record with no `requires` makes that a table whose first
            -- element is nil, and `ipairs` stops at the hole -- so the
            -- observed list, which is the one this addon actually harvests,
            -- would be skipped for every record that has no external data.
            -- Which is nearly all of them.
            local function Count(list)
                for _, prerequisiteID in ipairs(list or {}) do
                    if not counted[prerequisiteID] then
                        counted[prerequisiteID] = true

                        index[prerequisiteID] = (index[prerequisiteID] or 0) + 1
                    end
                end
            end

            Count(record.requires)
            Count(record.observedRequires)
        end
    end

    unlockIndex           = index
    unlockIndexGeneration = Harvest.unlockGeneration

    return index
end

-- How many quests this account has observed sitting behind a given quest.
function Harvest.UnlockCount(questID)
    questID = CN.ToID(questID)

    if not questID then
        return 0
    end

    return Harvest.UnlockIndex()[questID] or 0
end

CN.RegisterCandidateDecorator("Unlocks", function(objective)
    if not objective or objective.type ~= CN.objectiveTypes.QUEST then
        return
    end

    -- A provider that has its own opinion keeps it. This fills a gap; it does
    -- not overrule anybody.
    if objective.unlockValue ~= nil and objective.unlockGeneration == nil then
        return
    end

    -- MEASURED AGAINST THE GENERATION, NOT AGAINST NIL.
    --
    -- A plain "already set, leave it" froze the first answer for the session:
    -- since 0.55.0 a provider's tables are REUSED across rebuilds, so the
    -- objective carrying a count of two still carried two after ten more
    -- quests were harvested behind it -- on a weight-1.5 term, with `/cn why`
    -- stating a number the addon knew was wrong.
    if objective.unlockGeneration == Harvest.unlockGeneration then
        return
    end

    objective.unlockGeneration = Harvest.unlockGeneration
    objective.unlockValue      = nil

    local count = Harvest.UnlockCount(objective.id)

    if count <= 0 then
        CN.ClearDecoratorReason(objective, "unlocks")

        return
    end

    -- Scaled to the same 0..1 range every other term uses, so the weight in
    -- `CN.scoreWeights` means what it says.
    objective.unlockValue = math.min(1, count / Harvest.unlockCap)

    -- Through the keyed mechanism, so the sentence is REPLACED when the count
    -- changes and WITHDRAWN when it goes to zero -- rather than appended to
    -- once per rebuild, which is what an unkeyed insert does now that tables
    -- are reused.
    CN.AddDecoratorReason(objective, "unlocks", count == 1
        and "one quest you have seen comes after this one"
        or (count .. " quests you have seen come after this one"))
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Opportunities.lua'] = @'
-- Modules/Opportunities.lua
-- Completion Navigator :: things that expire.
--
-- The scoring formula gives limitedTimeBonus the heaviest weight of any
-- term (3.0), and until this module existed nothing ever set it. The engine
-- was built to prioritise content that disappears and had no idea what
-- disappears.
--
-- That is the whole point of the module: a world quest with two hours left
-- and a permanent quest in the same zone are not equally urgent, and the
-- recommendation should say so.

local ADDON_NAME, CN = ...

local Opportunities = CN:RegisterModule("Opportunities")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local HOUR = 3600
local DAY  = 86400

------------------------------------------------------------
-- URGENCY
------------------------------------------------------------

-- URGENCY IS THE SCORER'S, AND ONLY THE SCORER'S. 0.88.0.
--
-- `Opportunities.Urgency` lived here, with a header saying it was "now only
-- for callers that have no `expiresIn` to give -- world EVENTS, below". The
-- world-event branch reads `event.endsIn and 0 or 1`, a literal, and has done
-- since 0.63.0: the named caller did not call it, and nothing else in the
-- addon did either.
--
-- Removed rather than kept, because a comment asserting a live contract that
-- does not hold is how the next reader rebuilds a wrong model of the scoring.
-- One deadline, one curve: `expiresIn` and `CN.UrgencyBonus`, which is what
-- `/cn urgency` plots.


-- THE BARE FIGURE, WITH NO CLAUSE ATTACHED.
--
-- `FormatTimeLeft` returns strings that already end in " left", and three
-- callers prepend "in " -- so the Now tab's header read "Resets: daily in 4h
-- left, weekly in 3d left", on every visit, and "daily in unknown time left"
-- when the client would not answer. A formatter that owns the preposition
-- cannot be reused with a different one.
--
-- Same shape as `Vault.FormatReset`, which is what the Vault tab uses for the
-- same clock -- two formats for one quantity in one window.
function Opportunities.FormatSpan(seconds)
    if not seconds then
        return nil
    end

    if seconds <= 0 then
        return nil
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h"
    end

    return math.floor(seconds / DAY) .. "d"
end

function Opportunities.FormatTimeLeft(seconds)
    -- "UNKNOWN" AND "EXPIRED" ARE DIFFERENT ANSWERS.
    --
    -- `Blizzard.GetQuestTimeLeft` returns nil when the client will not say,
    -- and this collapsed that into "expired". The sort puts unknowns LAST
    -- using `or math.huge`, so a live world quest appeared at the bottom of a
    -- list headed "soonest to expire", labelled expired -- contradicting
    -- itself on the same screen.
    --
    -- The addon has a convention for exactly this and it is used here now.
    if not seconds then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time left"
    end

    if seconds <= 0 then
        return "expired"
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m left"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h left"
    end

    return math.floor(seconds / DAY) .. "d left"
end

------------------------------------------------------------
-- WORLD QUESTS
------------------------------------------------------------

-- World quests are the largest source of expiring content and the addon
-- could not see a single one before this.
function Opportunities.GetWorldQuests(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    if not mapID then
        return {}
    end

    local results = {}

    for _, task in ipairs(Blizzard.GetWorldQuestsOnMap(mapID)) do
        local questID = task.questID

        if not Blizzard.IsQuestCompletedByCharacter(questID)
            and not CN.IsIgnored(CN.objectiveTypes.QUEST, questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, questID) then

            local secondsLeft = Blizzard.GetQuestTimeLeft(questID)
            local info        = Blizzard.GetWorldQuestInfo(questID)

            table.insert(results, {
                questID     = questID,
                mapID       = task.mapID,
                x           = task.x,
                y           = task.y,
                name        = info.title or CN.GetQuestName(questID) or ("World quest " .. questID),
                tagName     = info.tagName,
                isElite     = info.isElite,
                secondsLeft = secondsLeft,
            })
        end
    end

    table.sort(results, function(a, b)
        return (a.secondsLeft or math.huge) < (b.secondsLeft or math.huge)
    end)

    return results
end

------------------------------------------------------------
-- RESETS
------------------------------------------------------------

function Opportunities.GetResets()
    return {
        daily  = Blizzard.GetSecondsUntilDailyReset(),
        weekly = Blizzard.GetSecondsUntilWeeklyReset(),
    }
end

------------------------------------------------------------
-- WORLD EVENTS
------------------------------------------------------------

-- Calendar reads are relatively expensive and the answer changes daily, not
-- minute to minute.
local eventCache, eventCachedAt = nil, 0

-- KEYED ON SOMETHING THE CLIENT'S LANGUAGE CANNOT CHANGE.
--
-- `id = event.title` was a localized string, and Instances.lua carries a
-- header describing that same defect as fixed for lockouts, in as many words:
-- every ignore was lost the day the player changed client language.
--
-- THE FALLBACK STILL HAS TO IDENTIFY THE EVENT. A triple of eventType,
-- calendarType and sequenceType is a description of a KIND of event, not of
-- one -- two ongoing holidays on the same day compose the identical key, and
-- the aggregate dedups on it, so one of them is silently dropped. That is
-- exactly the collapse this was meant to fix. The title goes back into the
-- fallback: it is not stable across languages, but a key that is unstable is
-- better than a key that is not unique, and where the client supplies an
-- eventID neither problem arises.
--
-- `> 0` rather than truthiness: zero is truthy in Lua, so an eventID of 0
-- would give every holiday the same id.
function Opportunities.EventKey(event)
    if type(event) ~= "table" then
        return nil
    end

    if type(event.eventID) == "number" and event.eventID > 0 then
        return event.eventID
    end

    return tostring(event.eventType or "?")
        .. ":" .. tostring(event.calendarType or "?")
        .. ":" .. tostring(event.sequenceType or "?")
        .. ":" .. tostring(event.title or "?")
end

function Opportunities.GetActiveEvents(force)
    -- A DEADLINE IS DERIVED AT READ TIME, NOT AT SCAN TIME.
    --
    -- `endsIn` is a countdown, computed when the calendar was read, and this
    -- list is held for thirty minutes. So the addon printed "ends in 40m"
    -- about an event that had finished ten minutes earlier, and the urgency
    -- ramp -- weight 4.0, and steepest inside the last two hours -- was fed a
    -- figure that could be half an hour wrong exactly where it matters most.
    -- `expiresIn` is an identity field, so the frozen value also let the
    -- provider take the reuse shortcut and nothing corrected it.
    --
    -- `endsAt` is an absolute stamp and cannot go stale.
    -- ENDED IS NOT "NO KNOWN END". 0.88.0.
    --
    -- This correctly nils `endsIn` once the stamp has passed, and left the
    -- row in a cache that lives for thirty minutes. The provider reads a nil
    -- `endsIn` as "an event the client will not date" and awards the flat
    -- bonus for it -- which is worth three points, where a live event three
    -- hours out earns about one and a third. So one nil field ranked a
    -- FINISHED holiday above every event still running, and `/cn now` went
    -- on listing it as active, for up to half an hour.
    --
    -- An event that has ended leaves the list.
    local function Freshen(events)
        local now = time()

        local live = {}

        for _, event in ipairs(events) do
            local keep = true

            if event.endsAt then
                local left = event.endsAt - now

                event.endsIn = (left > 0) and left or nil

                keep = left > 0
            end

            if keep then
                table.insert(live, event)
            end
        end

        return live
    end

    if not force and eventCache and (time() - eventCachedAt) < 1800 then
        return Freshen(eventCache)
    end

    local active = {}

    for _, event in ipairs(Blizzard.GetTodaysEvents()) do
        if event.ongoing then
            table.insert(active, event)
        end
    end

    eventCache    = active
    eventCachedAt = time()

    return Freshen(active)
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Opportunities", function()
    local candidates = {}

    -- Only the map is needed now: travel cost is computed by CN.TravelCost,
    -- which reads the player's position itself so every provider costs a
    -- journey the same way.
    local playerMap = CN.GetPlayerPosition()

    for _, worldQuest in ipairs(Opportunities.GetWorldQuests(playerMap)) do
        local reasons = {}

        if worldQuest.secondsLeft then
            table.insert(reasons, "world quest, "
                .. Opportunities.FormatTimeLeft(worldQuest.secondsLeft))
        else
            table.insert(reasons, "world quest")
        end

        if worldQuest.tagName then
            table.insert(reasons, worldQuest.tagName)
        end

        -- Costed through the real travel model rather than a straight line
        -- and a flat out-of-zone penalty, the same way quests have been
        -- since 0.42.0. World quests are exactly where this matters: they
        -- are scattered across a continent and they expire.
        -- `costed` SAYS WHETHER THE MODEL ANSWERED. See `Rares`. 0.70.0.
        local travel, costed = CN.TravelCost(worldQuest.mapID,
            worldQuest.x, worldQuest.y)

        if worldQuest.mapID == playerMap then
            table.insert(reasons, "in your current zone")
        end

        table.insert(candidates, CN.NewObjective({
            id               = worldQuest.questID,
            type             = CN.objectiveTypes.QUEST,
            name             = worldQuest.name,
            mapID            = worldQuest.mapID,
            x                = worldQuest.x,
            y                = worldQuest.y,
            state            = CN.objectiveStates.AVAILABLE,
            completionValue  = 1,
            -- NOT `limitedTimeBonus`. See the note on `Opportunities.Urgency`:
            -- setting both charged one deadline through two curves, and only
            -- one of them appears in `/cn urgency`.
            travelCost       = travel,
            travelCosted     = costed or nil,
            expiresIn        = worldQuest.secondsLeft,
            reasons          = reasons,
        }))
    end

    -- ACTIVE EVENTS (0.43.0).
    --
    -- The calendar has been read since 0.20.0 and its answers went into
    -- `/cn events` and nowhere else. A holiday or a Timewalking week is a
    -- deadline in exactly the sense the ranking already understands -- it is
    -- gone on a known date and it is not coming back for a year -- so it
    -- belongs in the list rather than in a separate command.
    for _, event in ipairs(Opportunities.GetActiveEvents()) do
        -- THE KEY IS WORKED OUT FIRST, because two things need it.
        --
        -- The ignore and defer guards read one key and the objective was
        -- built with another, so `CN.IsIgnored` looked up a title while
        -- `CN.SetIgnored` had stored an id: hiding a world event did nothing
        -- at all, for ever. Before 0.59.0 the two happened to be the same
        -- string, which is how a change to one of them broke the other.
        local id = Opportunities.EventKey(event)

        if not CN.IsIgnored(CN.objectiveTypes.CURRENCY, id)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, id) then

            local reasons = { "world event, on now" }

            if event.endsIn then
                table.insert(reasons, "ends in "
                    .. Opportunities.FormatTimeLeft(event.endsIn))
            end

            -- Deliberately modest. The addon knows the event is running; it
            -- does not know which of its quests you have done, so claiming
            -- this is your most valuable next action would be a guess.
            table.insert(candidates, CN.NewObjective({
                id               = id,
                type             = CN.objectiveTypes.CURRENCY,
                name             = event.title,
                completionValue  = 2,

                -- THE SAME DOUBLE CHARGE AS THE WORLD QUEST ABOVE. 0.63.0.
                --
                -- This set both terms too, so a Timewalking week was scored
                -- through two independently tuned curves. `expiresIn` is the
                -- one `/cn urgency` plots and the one every other deadline in
                -- the addon uses.
                --
                -- The flat 1 for an event with no known end is kept: an event
                -- the client will not date is still a limited-time thing, and
                -- that is what this term means when there is no deadline to
                -- charge.
                limitedTimeBonus = event.endsIn and 0 or 1,
                travelCost       = CN.placelessCost,
                expiresIn        = event.endsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
-- A COOLDOWN, ON EVENTS THAT ARE NOT SINGLE MOMENTS. 0.79.0.
--
-- `QUEST_LOG_UPDATE` fires constantly -- `Modules/Quests.lua` throttles its
-- own handler for that event to ten seconds and says so -- and
-- `CRITERIA_UPDATE` is the canonical chatty one, which `Achievements` and
-- `Loremaster` both give a cooldown and this did not.
--
-- The same defect 0.78.0 fixed for `Modules/Currencies.lua`, left standing
-- two files over. Freshness costs nothing here: a world quest window is
-- hours long and a zone's exploration criteria do not move faster than the
-- player walks.
end, { events = { "QUEST_LOG_UPDATE", "ZONE_CHANGED_NEW_AREA" },
       volatile = true, cooldown = 30 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    -- World quest availability changes constantly; nothing to persist, the
    -- candidate provider reads live each time it is asked.
end)

CN:OnLogin(function()
    -- Warm the calendar so the first /cn events call has data.
    Opportunities.GetActiveEvents(true)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "now",
    aliases = { "opportunities" },
    order   = 15,
    help    = "Show everything expiring soon.",
    handler = function()
        local resets = Opportunities.GetResets()

        if resets.daily then
            Print("Daily reset: " .. Opportunities.FormatTimeLeft(resets.daily))
        end

        if resets.weekly then
            Print("Weekly reset: " .. Opportunities.FormatTimeLeft(resets.weekly))
        end

        local events = Opportunities.GetActiveEvents()

        if #events > 0 then
            Print("Active events:")

            for _, event in ipairs(events) do
                CN.PrintLine("  " .. event.title)
            end
        end

        local worldQuests = Opportunities.GetWorldQuests()

        if #worldQuests == 0 then
            Print("No world quests available on your current map.")
            return
        end

        Print("World quests here (" .. #worldQuests .. "), soonest to expire:")

        for index = 1, math.min(#worldQuests, 10) do
            local worldQuest = worldQuests[index]

            CN.PrintLine("  " .. index .. ". " .. worldQuest.name
                .. " |cff8a8f96(" .. Opportunities.FormatTimeLeft(worldQuest.secondsLeft)
                .. (worldQuest.tagName and (", " .. worldQuest.tagName) or "") .. ")|r")
        end

        if #worldQuests > 10 then
            Print("  |cff8a8f96... and " .. (#worldQuests - 10) .. " more.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "events",
    order   = 16,
    help    = "List world events active today.",
    handler = function()
        local events = Opportunities.GetActiveEvents(true)

        if #events == 0 then
            Print("No world events detected as active today.")
            Print("|cff8a8f96The calendar may not have loaded yet; open it once and retry.|r")
            return
        end

        -- WHEN IT ENDS, NOT THE CLIENT'S OWN TOKEN. 0.88.0.
        --
        -- This printed `sequenceType` -- the raw enum string the provider
        -- branches on, "ONGOING" for every row in a list already filtered to
        -- ongoing events. The addon's internals, in brackets, saying nothing
        -- the header did not; the shape `Modules/Filters.lua` records fixing
        -- three separate times.
        --
        -- Meanwhile the one fact worth having -- how long is left, which the
        -- provider two hundred lines up already computes and RANKS on -- was
        -- dropped.
        for _, event in ipairs(events) do
            CN.PrintLine("  " .. event.title
                .. (event.endsIn
                    and CN.Aside(Opportunities.FormatTimeLeft(event.endsIn))
                    or ""))
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Warband.lua'] = @'
-- Modules/Warband.lua
-- Completion Navigator :: which character should do this.
--
-- The per-character data already exists: reputations, titles, professions
-- and recipes are stored on the character that owns them. What was missing
-- is anything that reads across all of them and answers the question the
-- whole design was built around.
--
-- This module also feeds `characterSuitability`, the second scoring term
-- that was weighted in the formula but never set by anything. An objective
-- your current character is poorly suited to should rank below one they can
-- act on now, and the reason should say why.

local ADDON_NAME, CN = ...

local Warband = CN:RegisterModule("Warband")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- ROSTER
------------------------------------------------------------

function Warband.Roster()
    local rows = {}

    for key, character in CN.Characters() do
        table.insert(rows, {
            key      = key,
            name     = character.name,
            realm    = character.realm,
            class    = character.class,
            race     = character.race,
            level    = character.level,
            faction  = character.faction,
            -- RESOLVED HERE, NOT STORED. 0.82.0. See `Character.lua`.
            spec     = CN.Blizzard.GetSpecName(character.specID),
            lastSeen = character.lastSeen,
            isCurrent = (key == CN.characterKey),

            professions  = CN.CountKeys(character.professions),
            recipes      = CN.CountKeys(character.recipes),
            titles       = CN.CountKeys(character.titles),
            reputations  = CN.CountKeys(character.reputations),
        })
    end

    table.sort(rows, function(a, b)
        if (a.level or 0) ~= (b.level or 0) then
            return (a.level or 0) > (b.level or 0)
        end

        return (a.key or "") < (b.key or "")
    end)

    return rows
end

------------------------------------------------------------
-- WHO SHOULD DO THIS
------------------------------------------------------------

-- Answers for any objective type that has per-character state. Returns
-- bestKey, detail, scope -- where scope explains why the answer is what it
-- is, including "account-wide" meaning the question does not apply.
--
-- THE SCOPE IS A TOKEN. 0.65.0.
--
-- Three places branch on `scope == "account-wide"` and three others PRINT the
-- same value to the player. That is a string doing two jobs, and the addon
-- has ten locale tables: the first translation of that sentence turns all
-- three guards false at once, and `/cn alts` starts recommending a loading
-- screen to switch characters for account-wide progress -- which the file
-- that does the recommending says "must never become a suggestion to switch".
--
-- The tokens are these, and `CN.ScopeText` turns one into a sentence.
CN.scopes = {
    ACCOUNT   = "account-wide",
    CHARACTER = "character",
    UNKNOWN   = "unknown",
}

function CN.ScopeText(scope)
    if scope == CN.scopes.ACCOUNT then
        return CN.L["account-wide"]
    end

    return scope
end
-- THE FRESHEST HOLDER, NOT THE ALPHABETICALLY FIRST.
--
-- `WhoKnows` and `WhoHas` both `table.sort` their holders, which orders them
-- by realm-name and by nothing else. So a deleted alt called Aaathrowaway
-- came back ahead of a main called Zeddicus -- and `Suitability`, seeing a
-- record older than the staleness line, dropped the penalty entirely and
-- concluded nobody was better suited, when somebody played yesterday already
-- knew the thing.
--
-- Fresh first, then alphabetical among equals so the answer is stable.
local function Freshest(holders)
    if type(holders) ~= "table" or #holders == 0 then
        return nil
    end

    local alts = CN:GetModule("Alts")

    if not alts or not alts.AgeDays then
        return holders[1]
    end

    local best, bestAge

    for _, key in ipairs(holders) do
        local record = CN.db and CN.db.characters and CN.db.characters[key]

        -- No stamp is not evidence of age. Treated as fresh, which is the
        -- fail-open direction -- the same one `Suitability` takes.
        local age = alts.AgeDays(record) or 0

        if not best or age < bestAge then
            best, bestAge = key, age
        end
    end

    return best or holders[1]
end

Warband.Freshest = Freshest

-- Returns `bestKey, detail, scope, switchable`.
--
-- THE FOURTH RETURN, AND WHY IT HAD TO EXIST. 0.79.0.
--
-- Two consumers ask this one question and mean different things by it.
--
-- `Warband.Suitability` is a score adjuster: "is this worth doing on THIS
-- character". A recipe another character already knows is worth less here,
-- so it wants the holder and the answer is right.
--
-- `Alts.Assignments` is `/cn alts`, whose entire job is "should you be
-- playing somebody else". For a recipe or a title, the holder is the
-- character who has ALREADY done it -- switching to them cannot do it again,
-- and titles in particular are per-character and unrepeatable. So that
-- surface printed, under the header "Bob could do 2 of these":
--
--     Flask of Alchemical Chaos   already knows it: Bob, Carol
--
-- The addon contradicting itself on one line, in the command written to stop
-- the player wondering.
--
-- `switchable` is false when the named character is the one who has already
-- done it. Absent means true, so every other branch is unchanged.
function Warband.WhoShould(objectiveType, id)
    local types = CN.objectiveTypes

    if objectiveType == types.REPUTATION then
        local module = CN:GetModule("Reputations")

        if not module then
            return nil, nil, "no reputation data"
        end

        local bestKey, bestRecord, accountWide = module.BestCharacterFor(id)

        if accountWide then
            return nil, nil, CN.scopes.ACCOUNT
        end

        if bestKey then
            return bestKey,
                   tostring(module.StandingText(bestRecord)),
                   "highest standing"
        end

        return nil, nil, "no character has this faction recorded"
    end

    if objectiveType == types.RECIPE then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local holders = module.WhoKnows(id)

        -- SOMEBODY ALREADY HAS IT, SO THERE IS NOBODY TO SWITCH TO. 0.79.0.
        --
        -- This returned the holder as the character who SHOULD do it, with
        -- "already knows it" as the reason -- so `/cn alts`, whose entire job
        -- is "should you be playing somebody else", printed
        --
        --     Flask of Alchemical Chaos   already knows it: Bob, Carol
        --
        -- under the header "Bob could do 2 of these". The function answered
        -- "who has this" to a question that asked "who should do this".
        --
        -- A recipe one character knows is not work for another character;
        -- whether some THIRD character with the profession could also learn
        -- it is a question this data cannot answer, and inventing an answer
        -- is worse than saying there is nothing to switch for.
        if #holders > 0 then
            return Freshest(holders), table.concat(holders, ", "),
                "already known by another character", false
        end

        return nil, nil, "no character knows this recipe"
    end

    if objectiveType == types.TITLE then
        local module = CN:GetModule("Titles")

        if not module then
            return nil, nil, "no title data"
        end

        local holders = module.WhoHas(id)

        -- AND A TITLE CANNOT BE EARNED TWICE. 0.79.0. Same correction as the
        -- recipe branch above: switching to the character who already has it
        -- cannot earn it again, so there is nothing to switch for.
        if #holders > 0 then
            return Freshest(holders), table.concat(holders, ", "),
                "already earned by another character", false
        end

        return nil, nil, "no character has this title"
    end

    if objectiveType == types.PROFESSION then
        local module = CN:GetModule("Professions")

        if not module then
            return nil, nil, "no profession data"
        end

        local bestKey, bestRecord = module.BestCharacterFor(id)

        if bestKey then
            return bestKey,
                   tostring(bestRecord and bestRecord.rank) .. " skill",
                   "highest skill"
        end

        return nil, nil, "no character has this profession"
    end

    if objectiveType == types.PET or objectiveType == types.MOUNT
        or objectiveType == types.TOY or objectiveType == types.ACHIEVEMENT
        or objectiveType == types.APPEARANCE then
        return nil, nil, CN.scopes.ACCOUNT
    end

    return nil, nil, "not tracked per character"
end

------------------------------------------------------------
-- SUITABILITY
------------------------------------------------------------

-- Positive when the logged-in character is the right one, negative when
-- somebody else is. Fed into the scoring formula so recommendations stop
-- pointing at work this character cannot usefully do.
function Warband.Suitability(objectiveType, id)
    -- The second return -- the list of character names -- is deliberately
    -- not bound: see the note above this function's return for why it must
    -- not appear in the sentence. 0.79.0.
    -- THE FOURTH RETURN, HERE TOO. 0.88.0.
    --
    -- For a recipe or a title the named character is the HOLDER: switching
    -- to them cannot do it again, and a title cannot be earned twice at all.
    -- `WhoShould` returns `switchable = false` to say so, `Alts` honoured it
    -- in 0.79.0 and `Goals` in 0.84.0 -- and this, the third caller, went on
    -- stamping "Bob is better suited -- already known by another character"
    -- onto the objective through `Warband.Decorate`, which puts it in
    -- `/cn next`, `/cn why`, the Next tab, the map pin and the heads-up line.
    --
    -- It also applied a two-point penalty, ranking DOWN the one character who
    -- can still learn the recipe.
    local bestKey, _, scope, switchable = Warband.WhoShould(objectiveType, id)

    if scope == CN.scopes.ACCOUNT or not bestKey or switchable == false then
        return 0, nil
    end

    if bestKey == CN.characterKey then
        return 1, "you are the best character for this"
    end

    -- A MONTH-OLD SNAPSHOT IS NOT A CHARACTER.
    --
    -- `Alts.staleDays` is 30 and its own comment says why: "Past this, the
    -- addon still reports what it knows but stops making suggestions from
    -- it. A month-old snapshot of a character is a description of a character
    -- that may not exist in that form any more."
    --
    -- The Alts SUGGESTION path honoured that. This one -- which silently
    -- reorders every list, at a penalty of two points, and prints the other
    -- character's name as the reason -- did not, and nothing anywhere in the
    -- addon ever removes a character from the roster. So a deleted or
    -- transferred alt went on penalising every recipe, reputation, title and
    -- profession objective it used to cover, for ever.
    local alts = CN:GetModule("Alts")

    -- `CN.db.characters[key]`, not `CN.Characters()[key]`: that function
    -- returns an ITERATOR, and Alts.lua reads the table directly for the same
    -- reason two files over.
    local record = CN.db and CN.db.characters and CN.db.characters[bestKey]

    if alts and alts.AgeDays and alts.staleDays then
        local age = alts.AgeDays(record)

        if age and age > alts.staleDays then
            return 0, nil
        end
    end

    -- THE SCOPE SENTENCE, NOT A LIST OF NAMES. 0.79.0.
    --
    -- `detail` is a comma-separated list of characters, and this rendered it
    -- as though it explained something: "Bob is better suited (Bob, Carol)".
    -- `scope` is the written reason and is what belongs in a `/cn why` line.
    return -2, bestKey .. " is better suited"
        .. (scope and (" " .. CN.DASH .. " " .. tostring(scope)) or "")
end

-- Applied to every candidate before scoring, so no module has to remember
-- to do it.
function Warband.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    -- WITHDRAWN HERE TOO. This was the one branch in the file that returned
    -- without cleaning up, so an objective that became account-wide kept a
    -- verdict about a character that no longer needs to do it.
    if objective.accountWide then
        objective.characterSuitability = nil

        CN.ClearDecoratorReason(objective, "warband")

        return objective
    end

    local suitability, reason = Warband.Suitability(objective.type, objective.id)

    if suitability == 0 then
        -- No verdict now means no sentence now. Withdrawn rather than left
        -- behind, the same way every adjuster reason has been since 0.51.0.
        objective.characterSuitability = nil

        CN.ClearDecoratorReason(objective, "warband")
    else
        objective.characterSuitability = suitability

        if reason then
            -- Through the keyed mechanism, so the sentence is replaced when
            -- the verdict changes and withdrawn when it stops applying --
            -- rather than appended once per rebuild now that a provider's
            -- tables are reused.
            CN.AddDecoratorReason(objective, "warband", reason)
        end
    end

    return objective
end

CN.RegisterCandidateDecorator("Warband", Warband.Decorate)

------------------------------------------------------------
-- COVERAGE
------------------------------------------------------------

-- What the Warband collectively has, versus what any one character has.
-- This is the number that matters for account completion; a single
-- character's totals understate it.
function Warband.Coverage()
    local professions, recipes, titles = {}, {}, {}

    local characters = 0

    for _, character in CN.Characters() do
        characters = characters + 1

        for skillLineID in pairs(character.professions or {}) do
            professions[skillLineID] = true
        end

        for recipeID in pairs(character.recipes or {}) do
            recipes[recipeID] = true
        end

        for titleID in pairs(character.titles or {}) do
            titles[titleID] = true
        end
    end

    return {
        characters  = characters,
        professions = CN.CountKeys(professions),
        recipes     = CN.CountKeys(recipes),
        titles      = CN.CountKeys(titles),
    }
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "warband",
    aliases = { "roster" },
    order   = 17,
    help    = "Show every known character and what they cover.",
    handler = function()
        local rows = Warband.Roster()

        if #rows == 0 then
            Print("No characters recorded yet.")
            return
        end

        Print("Warband (" .. #rows .. " character"
            .. CN.Pluralize(#rows, "") .. "):")

        for _, row in ipairs(rows) do
            local marker = row.isCurrent and "|cff73b873>|r " or "  "

            -- AND THE SPEC, WHICH WAS COLLECTED AND NEVER SHOWN. 0.82.0.
            --
            -- `Roster()` has carried a `spec` field since 0.62.0 and nothing
            -- read it, so the addon has been writing a specialization to disk
            -- every login and never telling anybody. "Which of these is my
            -- tank" is a Warband question, and this is the Warband list.
            CN.PrintLine(marker .. row.key
                .. " |cff8a8f96" .. tostring(row.level) .. " "
                .. (row.spec and (row.spec .. " ") or "")
                .. CN.TokenLabel(row.class or "?")
                .. (row.faction
                    and (" " .. CN.FactionLabel(row.faction)) or "") .. "|r")

            CN.PrintLine("      professions " .. row.professions
                .. ", recipes " .. row.recipes
                .. ", titles " .. row.titles
                .. ", reputations " .. row.reputations)
        end

        local coverage = Warband.Coverage()

        -- THE CAVEAT BELONGS ON THE NUMBER, NOT ONLY ON THE ONE-CHARACTER
        -- CASE.
        --
        -- `CN.Characters()` holds the characters that have logged in with
        -- this addon installed, which for most people is a fraction of the
        -- account. With three of ten alts seen the figure was printed as
        -- plain fact and only the `#rows == 1` case was hedged.
        Print("Combined coverage across the " .. #rows .. " character"
            .. CN.Pluralize(#rows, "") .. " this addon has seen: "
            .. coverage.professions .. " professions, "
            .. coverage.recipes .. " recipes, " .. coverage.titles .. " titles.")

        if #rows == 1 then
            Print("|cffffc74fOnly one character has been seen. Log in on your alts "
                .. "with the addon loaded to make these comparisons useful.|r")
        else
            Print("|cff8a8f96An alt that has never logged in with the addon "
                .. "loaded is not in this total.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "who",
    args    = "<type> <id>",
    order   = 18,
    help    = "Which character should do something. Types: rep, recipe, title, profession.",
    handler = function(args)
        local kind, value = args:match("^(%S+)%s+(.+)$")

        if not kind or not value then
            -- NAMES RESOLVE FOR TWO OF THE FOUR, AND THE USAGE LINE SAID
            -- FOUR. `RECIPE` and `PROFESSION` have no resolver, so a name
            -- there fell through to "Could not resolve" -- which reads as
            -- "that recipe does not exist" rather than "give me the id".
            Print("Usage: /cn who <rep|title> <id or name>")
            Print("|cff8a8f96       /cn who <recipe|profession> <id>|r")
            Print("|cff8a8f96Recipes and professions are looked up by id "
                .. "only; |cffffc74f/cn recipes|r|cff8a8f96 lists yours.|r")
            return
        end

        kind = string.lower(kind)

        local types = CN.objectiveTypes

        local map = {
            rep        = types.REPUTATION,
            reputation = types.REPUTATION,
            recipe     = types.RECIPE,
            title      = types.TITLE,
            profession = types.PROFESSION,
            prof       = types.PROFESSION,
        }

        local objectiveType = map[kind]

        if not objectiveType then
            Print("Unknown type: " .. kind)
            Print("Use one of: rep, recipe, title, profession")
            return
        end

        -- Resolve names to IDs through the owning module where possible.
        local id = CN.ToID(value)

        if not id then
            if objectiveType == types.REPUTATION then
                local module = CN:GetModule("Reputations")
                id = module and module.Resolve(value)
            elseif objectiveType == types.TITLE then
                local module = CN:GetModule("Titles")
                id = module and module.Resolve(value)
            end
        end

        if not id then
            if objectiveType == types.RECIPE
                or objectiveType == types.PROFESSION then

                Print("Recipes and professions are looked up by id, not by "
                    .. "name: " .. value)
                Print("|cff8a8f96|cffffc74f/cn recipes|r|cff8a8f96 lists the "
                    .. "ones this addon knows about, with their ids.|r")
            else
                Print("Could not resolve: " .. value)
            end

            return
        end

        local bestKey, detail, scope = Warband.WhoShould(objectiveType, id)

        if scope == CN.scopes.ACCOUNT then
            Print("That is account-wide; any character counts.")
            return
        end

        if not bestKey then
            -- The SENTENCE, from the token. See `CN.scopes` above: the same
            -- string was doing both jobs, so translating it would have turned
            -- three guards false at once. 0.65.0.
            Print(CN.ScopeText(scope) .. ".")
            return
        end

        -- BOTH FACTS, EACH IN ITS OWN PLACE. 0.79.0.
        --
        -- This printed `detail` -- the list of characters -- in the
        -- parentheses and threw `scope`, the sentence that explains the
        -- answer, away entirely.
        if bestKey == CN.characterKey then
            Print("This character is the best one for it.")
        else
            Print("Best character: " .. bestKey)
        end

        if scope then
            CN.PrintLine(CN.Muted(tostring(scope)))
        end

        if detail and detail ~= bestKey then
            CN.PrintLine(CN.Muted("Held by: " .. tostring(detail)))
        end
    end,
}

-- WHEN ANOTHER CHARACTER'S PICTURE CHANGES, SAY SO LOUDLY ENOUGH.
--
-- `Warband.Decorate` stamps `characterSuitability` and the "your Druid could
-- do four of these" sentence, and a provider whose rows are unchanged takes
-- the unchanged-provider shortcut and is never re-decorated -- which 0.57.0
-- made the common case. So logging in on an alt, or that alt learning a
-- profession, never reached the rows already on the list.
--
-- `CN.decoratorGeneration` is the hook that defeats the shortcut; Goals,
-- Harvest and Session all use it for the same reason.
--
-- DEBOUNCED, because `UPDATE_FACTION` is in this list and it fires on nearly
-- every reputation tick -- which this addon states in three other files, one
-- of which gives its own provider a five-second cooldown for exactly this
-- reason. Bumping `decoratorGeneration` on every tick turns the
-- unchanged-provider shortcut permanently off while the player is questing,
-- which is when they are gaining reputation continuously and also when they
-- most want `/cn next` to be fast.
-- Five seconds, matching the Reputations provider's own cooldown: the two
-- are answering the same burst.
Warband.rescanSeconds = 5

for _, event in ipairs({
    "PLAYER_ENTERING_WORLD", "UPDATE_FACTION", "SKILL_LINES_CHANGED",
}) do
    CN:RegisterEvent(event, function()
        CN.Debounce("Warband.suitability", Warband.rescanSeconds, function()
            -- Both halves: the counter defeats the identical-list reuse,
            -- and the invalidation is what makes a clean provider rebuild so
            -- that reuse is reached at all. See CN.NoteDecoratorsChanged.
            CN.NoteDecoratorsChanged()
        end)
    end)
end

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Rares.lua'] = @'
-- Modules/Rares.lua
-- Completion Navigator :: rares and treasures.
--
-- Most rare-tracking addons ship a static database of where rares spawn.
-- That answers "where is it", which is only half the question, and it goes
-- stale every patch.
--
-- This module leads with the client's vignette data instead, because a
-- vignette is the one live signal that a rare is *up right now*. Something
-- that exists this minute and may be dead in five is exactly the kind of
-- objective the opportunity scoring was built for.
--
-- Everything seen is also recorded permanently, so the addon accumulates its
-- own spawn database from play -- same approach as quest harvesting, and it
-- never goes stale because it comes from the live game.

local ADDON_NAME, CN = ...

local Rares = CN:RegisterModule("Rares")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

-- Everything ever seen, keyed by vignetteID. Account-wide: where a rare
-- spawns is a fact about the world.
local function Store()
    return CN.Account("rares")
end

-- Which vignettes this character has already dealt with. Rares are usually
-- once-per-character, so this is character state, not account state.
local function CharacterKills(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.raresKilled = character.raresKilled or {}

    return character.raresKilled
end

Rares.Store          = Store
Rares.CharacterKills = CharacterKills

------------------------------------------------------------
-- LIVE STATE
------------------------------------------------------------

-- Vignettes currently visible, classified and located.
-- EVERY VIGNETTE THE CLIENT REPORTS, DEAD ONES INCLUDED. 0.78.0.
--
-- `GetActive` used to filter the dead out AND drop the flag from the rows it
-- built, so `VignetteWork` -- which reads `vignette.isDead` to record that a
-- rare was seen already dead -- could never see one. `wasDead` was therefore
-- false for every row, and the branch in `NoteDisappearances` commented as
-- "needs no inference at all" was unreachable.
--
-- `GetActive` now filters THIS list, so the rows it returns are the same
-- tables and do carry the flag; what it removes is the dead ones.
--
-- So every clear fell through to the "it vanished within 150 yards of me"
-- guess, and a rare somebody else killed, or one tagged and finished while
-- the player rode past two hundred yards away, was never marked cleared --
-- and the addon went on recommending it.
--
-- The filter belongs to the two surfaces that want live rares. The learning
-- pass wants what the client actually said.
function Rares.GetAll(mapID)
    local seen = {}

    for _, vignette in ipairs(Blizzard.GetVignettes(mapID)) do
        table.insert(seen, {
            guid       = vignette.guid,
            vignetteID = vignette.vignetteID,
            name       = vignette.name,
            kind       = Blizzard.ClassifyVignette(vignette.atlas),
            mapID      = vignette.mapID,
            x          = vignette.x,
            y          = vignette.y,
            inFogOfWar = vignette.inFogOfWar,
            isDead     = vignette.isDead and true or false,
        })
    end

    return seen
end

function Rares.GetActive(mapID)
    mapID = mapID or select(1, CN.GetPlayerPosition())

    local active = {}

    for _, vignette in ipairs(Rares.GetAll(mapID)) do
        if not vignette.isDead then
            table.insert(active, vignette)
        end
    end

    table.sort(active, function(a, b)
        if a.kind ~= b.kind then
            return a.kind < b.kind
        end

        return (a.name or "") < (b.name or "")
    end)

    return active
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

-- HOW LONG A GAP MAKES THE NEXT SIGHTING A NEW ONE. See `Rares.Record`.
-- Longer than any fight, shorter than any respawn.
Rares.sightingGap = 10 * 60

function Rares.Record(vignette)
    if not vignette or not vignette.vignetteID then
        return false
    end

    local store    = Store()
    local existing = store[vignette.vignetteID]

    local record = existing or {
        vignetteID = vignette.vignetteID,
        firstSeen  = time(),
        sightings  = 0,
    }

    record.name      = vignette.name or record.name
    record.kind      = vignette.kind or record.kind

    -- A SIGHTING IS AN ENCOUNTER, NOT AN EVENT DISPATCH. 0.66.0.
    --
    -- This counter was incremented once per vignette per dispatch, and
    -- `VIGNETTE_MINIMAP_UPDATED` fires several times a second while anything
    -- is moving in range -- this file's own provider comment says so, which
    -- is why the PROVIDER has a five-second cooldown and this handler had
    -- none. Its one reader is the goal plan, so `/cn goal` told a player who
    -- had met a rare twice that they had seen it 1,847 times, and the number
    -- climbed while they stood there.
    --
    -- An encounter is a sighting after a gap. Ten minutes is longer than any
    -- fight and shorter than any respawn.
    local previous = record.lastSeen or 0

    if time() - previous >= Rares.sightingGap then
        record.sightings = (record.sightings or 0) + 1
    end

    record.lastSeen  = time()

    -- Keep the first coordinates seen; rares roam, and the spawn point is
    -- more useful than wherever it happened to be standing.
    if vignette.mapID and vignette.x and vignette.y then
        if not record.mapID then
            record.mapID = vignette.mapID
            record.x     = math.floor(vignette.x * 10000 + 0.5) / 10000
            record.y     = math.floor(vignette.y * 10000 + 0.5) / 10000
            -- `zone` IS NOT STORED. 0.62.0.
            --
            -- It was written on every sighting and read by nothing: the map
            -- id is already on the row and the client derives the name from
            -- it instantly. Migration 7 deleted this exact field from
            -- `questHarvest` with that exact note, and this copy survived.
        end
    end

    store[vignette.vignetteID] = record

    return existing == nil
end

------------------------------------------------------------
-- KILL TRACKING
------------------------------------------------------------

-- A vignette that was present and is now gone, while the player was nearby,
-- is very likely dealt with. This is inference, so it is recorded as
-- "cleared by this character" rather than presented as fact.
local lastSeenGuids = {}

-- HOW CLOSE YOU HAVE TO HAVE BEEN FOR "IT VANISHED" TO MEAN "IT DIED".
--
-- `GetVignettes` returns what is IN RANGE, and a vignette leaves that list
-- for two completely different reasons: somebody killed it, or you rode away
-- from it. The old code could not tell them apart and assumed the first, so
-- riding past a rare marked it cleared -- permanently, with no expiry and no
-- command to undo it. The addon then refused to ever offer that rare to that
-- character again, which is the worst possible failure for a module whose job
-- is to say a rare is up.
--
-- A vignette that goes out of range does so at the edge of the range. One
-- that dies does so wherever it was standing, which for a player who killed
-- it is close. This is still inference, but it is inference that distinguishes
-- the two cases instead of collapsing them.
Rares.clearedWithinYards = 150

-- AND THE INFERENCE EXPIRES.
--
-- Some rares are once per character and some are daily or weekly, and the
-- client does not say which. Remembering forever is right for the first group
-- and permanently wrong for the second; remembering until the weekly reset is
-- approximately right for both, and self-corrects either way.
Rares.rememberSeconds = 7 * 24 * 60 * 60

local function ClearedUntil()
    local seconds = Blizzard.GetSecondsUntilWeeklyReset
        and Blizzard.GetSecondsUntilWeeklyReset()

    if type(seconds) == "number" and seconds > 0 then
        return time() + seconds
    end

    return time() + Rares.rememberSeconds
end

-- Recorded when the client itself says the vignette is dead, which needs no
-- inference at all, and when one vanishes from close range.
function Rares.NoteCleared(vignetteID, name)
    local kills = CharacterKills()

    if not kills or not vignetteID then
        return false
    end

    kills[vignetteID] = ClearedUntil()

    DebugPrint("Marking cleared: " .. tostring(name or vignetteID))

    return true
end

-- The sighting set, so a test can put the module in the state a real
-- VIGNETTE_MINIMAP_UPDATED would have left it in and then drive the real
-- comparison. Writing to `lastSeenGuids` from outside is the alternative, and
-- a test that reaches around the module proves nothing about the module.
function Rares.SetLastSeen(seen)
    lastSeenGuids = seen or {}
end

function Rares.NoteDisappearances(currentGuids)
    local kills = CharacterKills()

    if not kills then
        return
    end

    for guid, entry in pairs(lastSeenGuids) do
        if not currentGuids[guid] and entry.vignetteID then
            if entry.wasDead then
                Rares.NoteCleared(entry.vignetteID, entry.name)
            elseif entry.yards and entry.yards <= Rares.clearedWithinYards then
                Rares.NoteCleared(entry.vignetteID, entry.name)
            else
                DebugPrint("Vignette out of range, not marking cleared: "
                    .. tostring(entry.name))
            end
        end
    end
end

function Rares.IsClearedByCharacter(vignetteID)
    local kills = CharacterKills()

    if not kills then
        return false
    end

    local entry = kills[vignetteID]

    if entry == nil then
        return false
    end

    -- LEGACY ENTRIES ARE RETIRED, NOT CONVERTED. The comment here used to
    -- claim they were treated as "expires one week after it was written",
    -- and the code has always treated the number as the expiry itself --
    -- so an entry written before 0.53.0, which holds the time the vignette
    -- VANISHED and is therefore always in the past, is dropped on first read.
    --
    -- That is the right outcome and the comment was the thing that was
    -- wrong. Most of those entries are the false positives described above,
    -- the rule they were written under is gone, and a rare offered once more
    -- than it needed to be is a smaller error than one silently never offered
    -- again. Corrected rather than implemented, in 0.67.0: converting them
    -- would mean adding a week to genuine expiries that have already passed,
    -- which resurrects exactly the stale clears this expiry exists to end.
    local expires = type(entry) == "number" and entry or 0

    if expires < time() then
        kills[vignetteID] = nil

        return false
    end

    return true
end

-- The player's own escape hatch, because inference that cannot be corrected
-- is just a wrong answer with a longer life.
function Rares.ForgetCleared()
    local kills = CharacterKills()

    if not kills then
        return 0
    end

    local count = CN.CountKeys(kills)

    for key in pairs(kills) do
        kills[key] = nil
    end

    return count
end

------------------------------------------------------------
-- SUMMARY
------------------------------------------------------------

function Rares.Summary()
    local counts = {
        known     = 0,
        rares     = 0,
        treasures = 0,
        located   = 0,
        cleared   = 0,
    }

    for vignetteID, record in pairs(Store()) do
        counts.known = counts.known + 1

        if record.kind == "TREASURE" then
            counts.treasures = counts.treasures + 1
        else
            counts.rares = counts.rares + 1
        end

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        -- THROUGH THE RULE, NOT THE RAW TABLE. 0.66.0.
        --
        -- A cleared entry is a timestamp, and `IsClearedByCharacter` is the
        -- one place that knows an expired one no longer counts -- it prunes
        -- as it reads. Testing the table for truthiness counted entries that
        -- had already expired, so after a weekly reset `/cn raredb` reported
        -- 40 rares cleared while `/cn rares` was correctly offering all 40
        -- again. The addon contradicting itself about its own state.
        if Rares.IsClearedByCharacter(vignetteID) then
            counts.cleared = counts.cleared + 1
        end
    end

    return counts
end

------------------------------------------------------------
-- ELIGIBILITY
------------------------------------------------------------

-- FOR BOTH TYPES THIS FILE EMITS. 0.78.0.
--
-- The provider below produces `RARE` and `TREASURE` rows from one store, and
-- only `RARE` had a checker -- so roughly half of what this module puts on
-- the list resolved to `UNKNOWN` in `CN.Explain`. `/cn why` on a treasure
-- said nothing useful, and the auto-advance staleness test had to fall
-- through to a linear scan of the whole candidate list every time.
--
-- One closure, registered twice, with wording that fits either.
local function Eligibility(vignetteID)
    local states = CN.objectiveStates
    local record = Store()[vignetteID]

    if not record then
        return states.UNKNOWN, "Never seen this one", nil
    end

    if Rares.IsClearedByCharacter(vignetteID) then
        return states.COMPLETED, "Cleared by this character", record.name
    end

    -- AND A ROW THE CLIENT IS NOT REPORTING RIGHT NOW IS NOT AVAILABLE.
    -- 0.79.0.
    --
    -- These two types are the only ones in the addon whose objectives exist
    -- only while the client says so: a rare that despawned, or a treasure
    -- somebody else looted, is gone with no event to say it.
    --
    -- Before 0.78.0 `TREASURE` had no checker at all, so the staleness test
    -- fell through to "is this still a candidate", which caught exactly that.
    -- Registering a checker without a liveness test took the fallback away
    -- and left the waypoint pointed at something that is not there -- which
    -- is the failure `Routing.lua` describes for the seven checker-less types
    -- and was written to end.
    --
    -- `UNKNOWN` is the honest answer: the store remembers this thing, and
    -- whether it is up right now is a question only the client can answer.
    local mapID = select(1, CN.GetPlayerPosition())

    if mapID then
        for _, vignette in ipairs(Rares.GetAll(mapID)) do
            if vignette.vignetteID == vignetteID and not vignette.isDead then
                return states.AVAILABLE, nil, nil
            end
        end

        return states.UNKNOWN, "Not up right now", record.name
    end

    return states.AVAILABLE, nil, nil
end

CN.RegisterEligibilityChecker(CN.objectiveTypes.RARE, Eligibility)
CN.RegisterEligibilityChecker(CN.objectiveTypes.TREASURE, Eligibility)

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only what is actually up right now becomes a candidate. A rare that is
-- not spawned is not a next action, and the whole point of using vignettes
-- is knowing the difference.
CN.RegisterCandidateProvider("Rares", function()
    local candidates = {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    for _, vignette in ipairs(Rares.GetActive(playerMap)) do
        local objectiveType = vignette.kind == "TREASURE"
            and CN.objectiveTypes.TREASURE
            or CN.objectiveTypes.RARE

        local id = vignette.vignetteID

        if id
            and not Rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(objectiveType, id)
            and not CN.IsDeferred(objectiveType, id) then

            local reasons = {}

            table.insert(reasons, vignette.kind == "TREASURE"
                and "treasure is up right now"
                or "rare is up right now")

            -- THROUGH THE TRAVEL MODEL, LIKE EVERY OTHER LOCATED PROVIDER.
            --
            -- This did raw Pythagoras on normalized map units and multiplied
            -- by ten, which asserts three things that are not true: that a
            -- map unit is the same number of yards north-south as east-west
            -- (the bearing defect of 0.40.0, in a different file), that every
            -- zone is about 2,100 yards across, and that the player is on
            -- foot. Quests, opportunities, vendors, toys and goals all go
            -- through `CN.TravelCost`, which knows the zone's real scale, the
            -- flight network and the player's own measured speed.
            --
            -- Left NIL rather than zero when there are no coordinates: zero
            -- means "you are standing on it", and `CN.IsPlaceless` reads it
            -- that way, so a rare the client would not place was scored as
            -- free AND exempt from the unknown-location cost.
            -- `costed` SAYS WHETHER THE MODEL ANSWERED. 0.70.0.
            --
            -- `CN.TravelCost` never refuses -- on a miss it hands back the
            -- constant the scorer ranks an unknown location with -- and every
            -- caller but one threw the second return away. So nothing
            -- downstream could tell a twenty-minute flight from "I could not
            -- work this out", and `/cn list` printed the second as the first.
            local travel, costed

            if vignette.x and vignette.y then
                travel, costed = CN.TravelCost(vignette.mapID, vignette.x, vignette.y)

                if playerX and playerY then
                    table.insert(reasons, "in your current zone")
                end
            end

            table.insert(candidates, CN.NewObjective({
                id               = id,
                type             = objectiveType,
                name             = vignette.name,
                mapID            = vignette.mapID,
                x                = vignette.x,
                y                = vignette.y,
                accountWide      = false,
                travelCosted     = costed or nil,
                state            = CN.objectiveStates.AVAILABLE,
                completionValue  = 2,

                -- Up now, gone when someone else kills it. That is exactly
                -- what the limited-time term is for.
                limitedTimeBonus = 1.5,

                travelCost       = travel,
                reasons          = reasons,
            }))
        end
    end

    return candidates
-- A COOLDOWN, BECAUSE VIGNETTE EVENTS FIRE CONSTANTLY IN THE OPEN WORLD.
--
-- `VIGNETTE_MINIMAP_UPDATED` fires several times a second while anything is
-- moving in range, and with no cooldown this provider was marked dirty
-- continuously -- and every dirty rebuild used to bump the aggregate
-- generation, which forces a full re-score of everything.
--
-- Five seconds costs nothing in freshness: a rare that appeared two seconds
-- ago is still there, and the alert path that announces one is a separate
-- event handler that is not throttled by this at all.
end, { events = { "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED", "ZONE_CHANGED_NEW_AREA" },
       volatile = true, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- ONE SWEEP, ONCE A SECOND. 0.66.0.
--
-- This ran on `VIGNETTE_MINIMAP_UPDATED` AND `VIGNETTES_UPDATED` with no
-- debounce at all -- several times a second while anything moves in range --
-- and each run did TWO full `GetVignettes` sweeps of the same map, a distance
-- calculation per row, two position reads, and a SavedVariables write per
-- rare. Flying across a zone with eight vignettes up, that is roughly 34
-- pcall'd client calls and 16 table allocations several times a second.
--
-- The second sweep was reading exactly what the first had already read.
local function VignetteWork()
    local mapID = select(1, CN.GetPlayerPosition())

    -- EVERY VIGNETTE, NOT THE LIVE ONES. 0.78.0. See `Rares.GetAll`: this
    -- reads `isDead` a few lines down, and `GetActive` had already removed
    -- every row that would have carried it.
    local active = Rares.GetAll(mapID)

    local currentGuids = {}

    for _, vignette in ipairs(active) do
        currentGuids[vignette.guid] = true

        -- A CORPSE IS NOT AN ENCOUNTER. 0.79.0.
        --
        -- 0.78.0 switched this walk to the unfiltered list so the dead flag
        -- would survive -- correctly -- and went on recording every row,
        -- dead ones included. `Record` bumps `sightings` after a ten-minute
        -- gap, and that counter is shown in the goal plan, so riding past
        -- the same corpse on three days read as three encounters.
        --
        -- The header on that counter says it exists because `/cn goal` once
        -- told a player who had met a rare twice that they had seen it 1,847
        -- times. The dead flag is needed for the disappearance inference
        -- below, not for the count.
        if not vignette.isDead then
            Rares.Record(vignette)
        end
    end

    Rares.NoteDisappearances(currentGuids)

    -- Rebuild the seen set for the next comparison, carrying the two facts
    -- that let the next comparison tell a kill from a departure: whether the
    -- client had already flagged it dead, and how far away it was.
    local nextSeen = {}

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    local travel = CN:GetModule("Travel")

    for _, vignette in ipairs(active) do
        local yards

        if travel and travel.YardsBetween and playerMap and playerX
            and vignette.mapID and vignette.x then

            yards = travel.YardsBetween(playerMap, playerX, playerY,
                vignette.mapID, vignette.x, vignette.y)
        end

        nextSeen[vignette.guid] = {
            vignetteID = vignette.vignetteID,
            name       = vignette.name,
            wasDead    = vignette.isDead and true or false,
            yards      = yards,
        }
    end

    lastSeenGuids = nextSeen
end

-- Exposed unthrottled so the offline harness and `/cn selftest` can drive it
-- directly; the game only ever reaches it through the debounce below.
Rares.VignetteWork = VignetteWork

local function OnVignetteUpdate()
    CN.Debounce("Rares.vignettes", 1, VignetteWork)
end

CN:RegisterEvent("VIGNETTE_MINIMAP_UPDATED", OnVignetteUpdate)
CN:RegisterEvent("VIGNETTES_UPDATED", OnVignetteUpdate)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    -- Vignettes from the previous zone are meaningless now.
    lastSeenGuids = {}
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "rares",
    order   = 74,
    help    = "Show rares and treasures up right now.",
    handler = function()
        local active = Rares.GetActive()

        if #active == 0 then
            Print("Nothing is up nearby.")
            Print("|cff8a8f96Vignettes only appear for content in range; "
                .. "move around the zone.|r")
            return
        end

        Print("Up right now (" .. #active .. "):")

        for index, vignette in ipairs(active) do
            local cleared = vignette.vignetteID
                and Rares.IsClearedByCharacter(vignette.vignetteID)

            CN.PrintLine("  " .. index .. ". " .. tostring(vignette.name)
                .. " |cff8a8f96[" .. tostring(vignette.kind) .. "]|r"
                .. (cleared and " |cff8a8f96(already cleared)|r" or "")
                .. (vignette.x and string.format(" |cff8a8f96%.1f, %.1f|r",
                    vignette.x * 100, vignette.y * 100) or ""))
        end

        Print("|cffffc74f/cn rare <number>|r to set a waypoint.")
        Print("|cff8a8f96\"already cleared\" is inferred from a vignette that "
            .. "vanished while you were next to it, and it expires at the "
            .. "weekly reset. /cn rareforget clears it now.|r")
    end,
}

CN:RegisterCommand{
    name    = "rareforget",
    order   = 77,
    help    = "Forget which rares this character is assumed to have cleared.",
    handler = function()
        local count = Rares.ForgetCleared()

        if count == 0 then
            Print("Nothing was being treated as cleared on this character.")
            return
        end

        Print(count .. " cleared for this character, forgotten. They will be "
            .. "offered again.")

        CN.InvalidateCandidates()
    end,
}

CN:RegisterCommand{
    name    = "rare",
    args    = "<number>",
    order   = 75,
    help    = "Navigate to something that is up right now.",
    handler = function(args)
        local index = CN.ToID(args)

        if not index then
            Print("Usage: /cn rare <number from /cn rares>")
            return
        end

        local active = Rares.GetActive()
        local vignette = active[index]

        if not vignette then
            Print("There is no number " .. index .. " in the current list.")
            return
        end

        CN.NavigateToObjective({
            id    = vignette.vignetteID,
            type  = vignette.kind == "TREASURE"
                and CN.objectiveTypes.TREASURE
                or CN.objectiveTypes.RARE,
            name  = vignette.name,
            mapID = vignette.mapID,
            x     = vignette.x,
            y     = vignette.y,
        })
    end,
}

CN:RegisterCommand{
    name    = "raredb",
    order   = 76,
    help    = "Summarize every rare and treasure recorded from play.",
    handler = function()
        local counts = Rares.Summary()

        if counts.known == 0 then
            Print("Nothing recorded yet. Rares and treasures are captured "
                .. "automatically as you encounter them.")
            return
        end

        Print("Recorded: " .. counts.known
            .. " (" .. counts.rares .. " rares, " .. counts.treasures .. " treasures)")
        Print("With coordinates: " .. counts.located)
        Print("Cleared by this character: " .. counts.cleared)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Currencies.lua'] = @'
-- Modules/Currencies.lua
-- Completion Navigator :: currencies, caps, and wasted earning potential.
--
-- A currency total on its own is not a decision. What matters is whether you
-- are at a cap, because a capped currency is earning potential you are
-- throwing away, and a weekly cap you have not filled resets in a few days
-- whether you use it or not.
--
-- Both of those are time-sensitive, which is why this module contributes to
-- the opportunity side of the scoring rather than sitting in a list.

local ADDON_NAME, CN = ...

local Currencies = CN:RegisterModule("Currencies")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- Currency quantities are character state; which currencies exist is not.
-- A currency's name, from the client. Seventh store to get one of these; see
-- `Achievements.NameOf` for the first. 0.65.0.
--
-- NO FALLBACK TO A STORE. `CN.Account(key)` CREATES the table it is asked
-- for, so any reader left pointing at `currencyNames` resurrects the store
-- migration 18 deleted -- an empty one, on every login, forever. The client
-- answers this instantly and in the player's own language; there is nothing
-- for a fallback to add.
function Currencies.NameOf(currencyID)
    local info = CN.Blizzard.GetCurrency and CN.Blizzard.GetCurrency(currencyID)

    if info and info.name and info.name ~= "" then
        return info.name
    end

    return "Currency " .. tostring(currencyID)
end

local function CharacterStore(character)
    character = character or CN.character

    if not character then
        return nil
    end

    character.currencies = character.currencies or {}

    return character.currencies
end

Currencies.CharacterStore = CharacterStore

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

-- A CURRENCY THE CLIENT HAS STOPPED LISTING IS NOT A CURRENCY YOU CAN SPEND.
--
-- `GetCurrencyList` is the currency UI tree, and things leave it: a season
-- ends, an expansion's currency is retired, one migrates to the Warband. The
-- store was write-only-grow -- one row per currency ever seen, never removed
-- -- and `Capped` walked all of it with no freshness check.
--
-- So a currency capped last season kept producing "at cap, further earning is
-- wasted until you spend it", every five seconds because this provider is
-- volatile, with a fresh weekly urgency bonus every reset, for the life of
-- the character. The player could not satisfy it and could not make it go
-- away except with `/cn ignore`.
--
-- A serial per sweep is the whole fix: a row the last scan did not see is not
-- reported on. `lastSeen` was already being written and was read by nothing
-- anywhere in the tree, which is why this went unnoticed.
-- PERSISTED, or a reload would leave every row looking stale until the login
-- scan ran -- a window in which `/cn currencies` would report nothing at all.
local function Serials()
    local account = CN.Account()

    account.currencyScans = account.currencyScans or {}

    return account.currencyScans
end

-- The counter for a NAMED character, not always the logged-in one.
--
-- `Capped`, `WeeklyUnfilled` and `Summary` all accept an explicit character,
-- and comparing an alt's rows against the current character's counter filters
-- every one of them out -- so an alt would have reported zero capped
-- currencies and zero unfilled weeklies. No caller passes one today, which is
-- the only reason this was latent rather than live.
-- REALM FIRST, LIKE EVERY OTHER CHARACTER KEY IN THE ADDON. 0.62.0.
--
-- `CN.GetCharacterKey` is `realm .. "-" .. name`, and this built
-- `name .. "-" .. realm` -- so the key matched nothing, `CurrentSerial` came
-- back 0, and the paragraph above describes precisely the symptom that
-- produces. The comment was written about the bug being fixed; the code kept
-- it. Latent only because nothing passes a character yet, which is the reason
-- to correct it now rather than when the first caller trips over it.
--
-- Built through the one function that owns the format, so the two cannot
-- drift again.
local function KeyFor(character)
    if character and character.name and character.realm then
        return CN.CharacterKeyFor(character.realm, character.name)
    end

    return CN.characterKey or "?"
end

local function CurrentSerial(character)
    return Serials()[KeyFor(character)] or 0
end

local function NextSerial()
    local key = CN.characterKey or "?"

    Serials()[key] = CurrentSerial() + 1

    return Serials()[key]
end

Currencies.CurrentSerial = CurrentSerial

-- A row is current if the last sweep saw it.
--
-- NO EXEMPTION FOR ROWS WRITTEN BEFORE SERIALS EXISTED. The first version of
-- this treated an unstamped row as current "until the next scan rewrites
-- them" -- and the premise is wrong in exactly the case the feature is for:
-- a currency the client no longer lists is precisely the row the next scan
-- will NOT rewrite. So the fix worked on a fresh install and did nothing at
-- all for anybody upgrading, which is everybody.
--
-- Migration 13 stamps every existing row with serial 0 instead, and the
-- login scan then stamps the live ones with 1. Nothing is lost: the login
-- scan runs before anything reads this.
local function IsCurrent(record, character)
    if type(record) ~= "table" then
        return false
    end

    return record.serial == CurrentSerial(character)
end

Currencies.IsCurrent = IsCurrent

-- When the last sweep ran. Declared here, ABOVE its first use: a local
-- declared below the line that assigns it is not the same variable -- the
-- assignment creates a global and the throttle silently stops working.
local lastScan = 0

-- Every scan stamps the throttle, whichever path asked for it. Before this,
-- the login scan and the manual one both left the timestamp alone, so the
-- next coin picked up ran a second full sweep. 0.65.0.
function Currencies.Scan()
    local mine = CharacterStore()

    if not mine then
        lastScan = time()

        return 0, 0, 0
    end

    local list = Blizzard.GetCurrencyList()

    -- A REFUSAL IS NOT AN EMPTY CURRENCY LIST. 0.88.0.
    --
    -- THE SERIAL *IS* THE PRUNE: `IsCurrent` compares a row's serial against
    -- the current one, and `Capped`, `WeeklyUnfilled` and `CurrentCount` all
    -- gate on it. Bumping it with nothing to stamp therefore retires every
    -- stored currency at once -- while the rows sit intact on disk.
    --
    -- `Blizzard.GetCurrencyList` answers with an empty table on four ordinary
    -- refusal paths, one of which is a size of zero -- which is what the
    -- client returns while currency data is still streaming at login, which
    -- is exactly when `CN:OnLogin` runs this.
    --
    -- `Achievements` has carried this guard since 0.76.0, `Exploration` since
    -- 0.61.0 and `Loremaster` since 0.71.0, and the note on the first of them
    -- says why: "a cold scan that read nothing would otherwise delete every
    -- row it could not confirm". Fourth writer of the same idea, no guard.
    --
    -- The throttle is not stamped either, so the next coin picked up retries
    -- rather than waiting out a minute on an answer that was never given.
    if #list == 0 then
        DebugPrint("Currency sweep answered for nothing; not recording it.")

        return 0, 0, 0
    end

    lastScan = time()

    local serial = NextSerial()

    local seen, atCap, weeklyRemaining = 0, 0, 0

    for _, currency in ipairs(list) do
        if currency.currencyID then
            -- `currencyNames` IS NOT WRITTEN ANY MORE. 0.65.0.
            --
            -- 0.64.0 gave every reader a live client path and left the writer
            -- alone, so the store kept filling with names frozen at whatever
            -- language last scanned -- and `Currencies.Resolve`, which
            -- searches only the store, could not find a player's own
            -- currencies by name after a language change.
            --
            -- Seventh store to lose a name it did not need to keep.

            -- THE CAP APPLIES TO WHAT THE CLIENT SAYS IT APPLIES TO. 0.62.0.
            --
            -- `useTotalEarnedForMaxQty` is read from the client in
            -- BlizzardWorld.lua and was then neither stored nor consulted, so
            -- every currency was tested as `quantity >= maxQuantity`. For the
            -- currencies whose cap is on LIFETIME or SEASONAL earnings, a
            -- player who has hit the cap and then spent the balance was told
            -- they were not capped -- so `/cn currencies` and the currency
            -- provider stayed silent about earning that is now being thrown
            -- away, which is the one thing this row exists to warn about.
            -- The reason string read "at cap: 1200 / 2500", which is its own
            -- contradiction.
            local against = currency.useTotalEarnedForMaxQty
                and (currency.totalEarned or 0)
                or currency.quantity

            local capped = currency.maxQuantity > 0
                and against >= currency.maxQuantity

            local weeklyLeft = 0

            if currency.maxWeeklyQuantity > 0 then
                weeklyLeft = math.max(0,
                    currency.maxWeeklyQuantity - currency.earnedThisWeek)
            end

            mine[currency.currencyID] = {
                currencyID        = currency.currencyID,
                quantity          = currency.quantity,
                maxQuantity       = currency.maxQuantity,
                totalEarned       = currency.totalEarned,
                earnedThisWeek    = currency.earnedThisWeek,
                maxWeeklyQuantity = currency.maxWeeklyQuantity,
                capped            = capped,

                -- Which quantity the cap is measured against, so every
                -- reader agrees with the flag above rather than recomputing
                -- it from the wrong field.
                cappedAgainst     = against,
                usesTotalEarned   = currency.useTotalEarnedForMaxQty or nil,
                accountWide       = currency.accountWide or nil,
                weeklyRemaining   = weeklyLeft,
                lastSeen          = time(),

                -- Which sweep last saw it. See the header above `Scan`.
                serial            = serial,
            }

            seen = seen + 1

            if capped then
                atCap = atCap + 1
            end

            if weeklyLeft > 0 then
                weeklyRemaining = weeklyRemaining + 1
            end
        end
    end

    CN.MarkScanned("currencies")

    return seen, atCap, weeklyRemaining
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Currencies.Capped(character)
    local capped = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.capped and IsCurrent(record, character) then
            table.insert(capped, {
                currencyID = currencyID,
                name       = Currencies.NameOf(currencyID),
                -- THE NUMBERS THE CAP WAS MEASURED AGAINST. 0.63.0.
                --
                -- 0.62.0 fixed the DETECTION -- a currency whose cap applies
                -- to lifetime earnings is tested against `totalEarned` -- and
                -- then this function went on exporting `quantity` and
                -- `maxQuantity` for display. So the fix produced a row that
                -- was correctly flagged and then printed its own
                -- contradiction: "At cap - spend these: Foo 100 / 2500".
                --
                -- `cappedAgainst` was stored by that release and read by
                -- nothing, which is what a half-finished fix looks like in a
                -- grep. It is the display value now, and `held` carries the
                -- balance separately for anything that wants to say how much
                -- there is to spend.
                quantity   = record.cappedAgainst or record.quantity,
                maximum    = record.maxQuantity,
                held       = record.quantity,
                earned     = record.totalEarned,

                -- So a reader can say WHY the two differ rather than leaving
                -- the player to work it out.
                usesTotalEarned = record.usesTotalEarned or nil,

                -- CARRIED THROUGH, WHICH IT WAS NOT.
                --
                -- The candidate provider reads `accountWide` off these rows
                -- under a long comment explaining that ignoring the flag was
                -- "the exact mistake the Warband work exists to prevent" --
                -- and this function, the only thing that builds those rows,
                -- never copied it. The flag was read from the client
                -- correctly, stored correctly, and dropped here. So a
                -- Warband currency capped on your main was still recommended
                -- on every alt, which is precisely the behaviour 0.43.0
                -- claimed to have fixed.
                accountWide = record.accountWide and true or false,
            })
        end
    end

    table.sort(capped, function(a, b) return (a.name or "") < (b.name or "") end)

    return capped
end

function Currencies.WeeklyUnfilled(character)
    local rows = {}

    for currencyID, record in pairs(CharacterStore(character) or {}) do
        if record.weeklyRemaining and record.weeklyRemaining > 0
            and IsCurrent(record, character) then
            table.insert(rows, {
                currencyID = currencyID,
                name       = Currencies.NameOf(currencyID),
                remaining  = record.weeklyRemaining,
                earned     = record.earnedThisWeek,
                maximum    = record.maxWeeklyQuantity,
            })
        end
    end

    table.sort(rows, function(a, b) return (a.remaining or 0) > (b.remaining or 0) end)

    return rows
end

function Currencies.Summary(character)
    return {
        -- COUNTED OVER THE SAME POPULATION AS THE OTHER TWO. 0.64.0.
        --
        -- `known` counted every row in the store while `capped` and
        -- `weeklyUnfilled` counted only rows the client still lists -- so
        -- `/cn breakdown` printed `known - capped`, a subtraction across two
        -- different populations, and could report more capped currencies than
        -- known ones.
        known           = Currencies.CurrentCount(character),
        capped          = #Currencies.Capped(character),
        weeklyUnfilled  = #Currencies.WeeklyUnfilled(character),
    }
end

-- How many rows the client still lists. See the note in `Summary`.
function Currencies.CurrentCount(character)
    local count = 0

    for _, record in pairs(CharacterStore(character) or {}) do
        if IsCurrent(record, character) then
            count = count + 1
        end
    end

    return count
end

function Currencies.Resolve(text)
    local currencyID = CN.ToID(text)

    if currencyID and CharacterStore() and CharacterStore()[currencyID] then
        return currencyID
    end

    if not text or text == "" then
        return nil
    end

    local needle  = string.lower(text)
    local matches = {}

    -- SEARCHED OVER WHAT THIS CHARACTER HAS, NAMED LIVE. 0.65.0.
    --
    -- This searched the stored name table, which no longer fills -- and even
    -- before that it was frozen at the last scan's language, so a player who
    -- changed client language could not find their own currencies by name.
    for id in pairs(CharacterStore() or {}) do
        local name = Currencies.NameOf(id)

        if name and string.find(string.lower(name), needle, 1, true) then
            table.insert(matches, { id = id, name = name })
        end
    end

    if #matches == 0 then
        return nil
    end

    table.sort(matches, function(a, b) return #a.name < #b.name end)

    return matches[1].id
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A capped currency is not a place to travel to, so these carry no
-- coordinates. They surface as high-priority advisories: stop earning this
-- and go spend it.
CN.RegisterCandidateProvider("Currencies", function()
    local candidates = {}

    for _, currency in ipairs(Currencies.Capped()) do
        if not CN.IsIgnored(CN.objectiveTypes.CURRENCY, currency.currencyID)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, currency.currencyID) then

            -- ACCOUNT-WIDE CURRENCIES ARE ACCOUNT-WIDE (0.43.0).
            --
            -- The client flags these and the addon ignored the flag, so a
            -- Warband currency capped on one character was recommended again
            -- on every other one -- the exact mistake the Warband work exists
            -- to prevent, in the one store that had not been told about it.
            local shared = currency.accountWide

            table.insert(candidates, CN.NewObjective({
                id               = currency.currencyID,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Spend " .. tostring(currency.name)
                    .. (shared and " (Warband)" or ""),
                accountWide      = shared and true or false,
                completionValue  = 2,

                -- ONE DEADLINE, ONE CURVE. 0.89.0. `expiresIn` below is the
                -- weekly reset and the note beside it says why -- so this
                -- charged the same reset a second time, through a shape
                -- `/cn urgency` does not plot. Fifth row in the addon to do
                -- it; a sweep in the harness now covers every provider.
                limitedTimeBonus = 0,
                travelCost       = 0,

                -- A capped currency is not "expiring", but every hour spent
                -- at cap is earning thrown away, and the weekly reset is when
                -- that waste is realised. Treating the reset as its deadline
                -- makes the urgency curve say the true thing: this matters
                -- more on Monday night than on Wednesday morning.
                expiresIn        = CN.Blizzard.GetSecondsUntilWeeklyReset(),

                reasons          = {
                    "at cap: " .. tostring(currency.quantity)
                        .. " / " .. tostring(currency.maximum)
                        .. (currency.usesTotalEarned and " earned" or ""),
                    "further earning is wasted until you spend it",
                },
            }))
        end
    end

    return candidates
-- A COOLDOWN, BECAUSE THIS EVENT FIRES ON EVERY COIN PICKED UP. 0.78.0.
--
-- This file's own note six lines down says exactly that, which is why the
-- SCAN is throttled to sixty seconds -- and the provider had no cooldown at
-- all, so it was marked dirty and rebuilt on every firing, each rebuild
-- walking the whole character store through `Capped()` and making a live
-- client call per capped row.
--
-- Thirty seconds costs nothing in freshness: capped-ness cannot change
-- faster than the sixty-second scan that computes it. `Modules/Rares.lua`
-- sets 5 for the same reason and `Modules/Orders.lua` sets 30.
end, { events = { "CURRENCY_DISPLAY_UPDATE" }, volatile = true, cooldown = 30 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- SIXTY SECONDS, NOT TEN, AND NOT WHILE THE PLAYER IS LOOKING. 0.64.0.
--
-- `CURRENCY_DISPLAY_UPDATE` fires on every coin picked up, so a ten-second
-- guard meant this ran continuously through an evening -- and it is not a
-- cheap read. Each sweep makes three passes over the whole currency list,
-- recovers an id per row by building and matching a hyperlink, rewrites about
-- a hundred and fifty tables into SavedVariables, and bumps the collection
-- generation.
--
-- It also EXPANDS AND RE-COLLAPSES the player's currency headers to see rows
-- the client hides, which is the one place in this addon that changes
-- something the player can see. It puts them back -- but a player with the
-- Currency tab open watched their collapsed groups pop open and shut every
-- ten seconds, which is the addon acting rather than prompting.
--
-- So: a minute rather than ten seconds, and never while the frame whose state
-- it disturbs is on screen. A currency total that is at most a minute stale
-- costs nothing; the sweep costs a visible flicker.
Currencies.rescanSeconds = 60

-- `IsVisible`, NOT `IsShown`, AND ONLY THE CURRENCY PANEL. 0.67.0.
--
-- `IsShown` reports a region's own flag, not whether the player can see it:
-- a child of a hidden parent still answers true. `TokenFrame` is a panel
-- INSIDE `CharacterFrame`, so pressing C, clicking Currency and pressing Esc
-- left its flag set forever -- and from that moment this returned true on
-- every path, `SweepIfDue` refused on every path, and the store froze at
-- login for the rest of the session. A currency capped that evening was
-- never reported, which is the one thing this module exists to warn about.
--
-- The `or _G.CharacterFrame` fallback made it worse rather than safer: with
-- `Blizzard_TokenUI` not yet loaded it answered about the character sheet,
-- which is a different window that this sweep does not disturb.
local function CurrencyFrameOpen()
    local frame = _G.TokenFrame

    if not frame or not frame.IsVisible then
        return false
    end

    return frame:IsVisible() and true or false
end

Currencies.IsFrameOpen = CurrencyFrameOpen

-- THE ONE PLACE THAT DECIDES WHETHER A SWEEP RUNS NOW. 0.66.0.
--
-- The throttle, the open-frame deferral and the scan were spread across an
-- event handler, so the only way to reach the deferral was to dispatch a
-- currency event -- which is why the promise below ("as soon as the player
-- closes the window") was made by a comment and kept by nothing.
function Currencies.SweepIfDue()
    if time() - lastScan < Currencies.rescanSeconds then
        return false
    end

    -- Deferred rather than skipped: `lastScan` is not advanced, so the sweep
    -- happens at the next opportunity instead of a minute after this one.
    if CurrencyFrameOpen() then
        return false
    end

    Currencies.Scan()

    return true
end

-- THE LOGIN SCAN ALREADY IS THE PROMPT SWEEP. 0.66.0.
--
-- There was a `PLAYER_ENTERING_WORLD` handler here that cleared the throttle,
-- justified as "a player who reloads mid-session should not then wait a
-- minute". It could never serve that case: `PLAYER_LOGIN` runs the login
-- hooks -- including this module's `Scan()` -- and it fires BEFORE
-- `PLAYER_ENTERING_WORLD`, on a reload as on a fresh login. So the order was
-- always: sweep, stamp the throttle, throw the stamp away. The next coin
-- picked up in the first minute ran the whole three-pass sweep again, which
-- is the same double sweep 0.65.0 fixed on the manual path, arriving by the
-- other door.
--
-- What DOES need collecting is the deferral: see the frame hook below.

CN:RegisterEvent("CURRENCY_DISPLAY_UPDATE", function()
    Currencies.SweepIfDue()
end)

-- AND THE DEFERRAL IS ACTUALLY COLLECTED. 0.66.0.
--
-- The deferral above says the sweep "happens as soon as the player closes the
-- window". Nothing made that true: the only thing that reached it was the
-- next `CURRENCY_DISPLAY_UPDATE`, which arrives when the player next gains a
-- currency -- so a player who opened the Currency tab, read it, closed it and
-- went to a raid carried a store that could be an hour stale, and `/cn
-- currencies` answered from it.
--
-- No client event announces that frame closing, so the frame itself is asked.
-- Hooked once, at login, guarded, and silent if the frame does not exist --
-- the same shape every other optional client surface in this addon gets.
-- HOOKED WHEN THE FRAME EXISTS, WHICH IS NOT AT LOGIN. 0.67.0.
--
-- `Blizzard_TokenUI` is loaded on demand, so at `PLAYER_LOGIN` there is no
-- `TokenFrame` -- and the first version of this fell back to
-- `CharacterFrame`, hooked THAT, and set the "done" flag, so the frame it was
-- written for never got a hook at all and closing the character sheet swept
-- currencies instead.
--
-- Retried on `ADDON_LOADED`, which is how the client announces exactly this.
local hookedCurrencyFrame = false

function Currencies.HookFrame()
    if hookedCurrencyFrame then
        return true
    end

    local frame = _G.TokenFrame

    if not frame or not frame.HookScript then
        return false
    end

    local ok = pcall(frame.HookScript, frame, "OnHide", function()
        pcall(Currencies.SweepIfDue)
    end)

    hookedCurrencyFrame = ok and true or false

    return hookedCurrencyFrame
end

CN:RegisterEvent("ADDON_LOADED", function()
    Currencies.HookFrame()
end)

CN:OnLogin(function()
    Currencies.HookFrame()
end)

CN:OnLogin(function()
    Currencies.Scan()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "currencies",
    aliases = { "currency" },
    order   = 77,
    help    = "Show currency caps and unfilled weekly earning.",
    handler = function()
        local counts = Currencies.Summary()

        if counts.known == 0 then
            Print("No currency data yet. Run /cn currencyscan.")
            return
        end

        Print("Currencies tracked: " .. counts.known)

        local capped = Currencies.Capped()

        if #capped > 0 then
            Print("|cffe2564cAt cap (" .. #capped .. ") - spend these:|r")

            -- CAPPED, AND SAYING SO -- like the list below it. 0.79.0.
            --
            -- 0.78.0 added "and N more" to the weekly list and left this one
            -- unbounded, so a player deep into an expansion had twenty-plus
            -- rows dumped into chat. The two halves of one command were
            -- inconsistent in opposite directions.
            for index, currency in ipairs(capped) do
                if index > 8 then
                    break
                end

                CN.PrintLine("  " .. tostring(currency.name)
                    .. " |cff8a8f96" .. currency.quantity
                    .. " / " .. currency.maximum
                    -- A cap on lifetime earning and a balance are different
                    -- numbers, and a player who has spent theirs will
                    -- otherwise read this as a bug.
                    .. (currency.usesTotalEarned
                        and (" earned, " .. tostring(currency.held)
                            .. " held")
                        or "")
                    .. "|r")
            end

            if #capped > 8 then
                CN.PrintLine(CN.Muted("  ... and " .. (#capped - 8)
                    .. " more"))
            end
        end

        local weekly = Currencies.WeeklyUnfilled()

        if #weekly > 0 then
            Print("Weekly earning still available (" .. #weekly .. "):")

            for index = 1, math.min(#weekly, 8) do
                local currency = weekly[index]

                CN.PrintLine("  " .. tostring(currency.name)
                    .. " |cff8a8f96" .. currency.earned .. " / " .. currency.maximum
                    .. ", " .. currency.remaining .. " left this week|r")
            end

            -- A CAP NOBODY CAN SEE READS AS "THAT WAS EVERYTHING". 0.78.0.
            --
            -- The headline announced the real count and the list stopped at
            -- eight with nothing said, so a player with fourteen was told
            -- fourteen and shown eight. Three other commands print "and N
            -- more" for the same shape and `Design.lua`'s own header names
            -- this inconsistency.
            if #weekly > 8 then
                CN.PrintLine(CN.Muted("  ... and " .. (#weekly - 8)
                    .. " more"))
            end
        end

        if #capped == 0 and #weekly == 0 then
            Print("Nothing capped, nothing left to earn this week.")
        end
    end,
}

CN:RegisterCommand{
    name    = "currencyscan",
    order   = 78,
    help    = "Rescan currencies for this character.",
    handler = function()
        -- A SCAN THE PLAYER ASKED FOR RE-ARMS THE TIMER -- AFTERWARDS.
        --
        -- 0.64.0 wrote this and put it in the wrong place: resetting the
        -- timestamp BEFORE scanning sets it to zero, which makes the throttle
        -- test false for the next sixty seconds and guarantees the very
        -- double sweep the comment says it prevents. Pick up one coin a
        -- second after a manual scan and the whole three-pass read ran again,
        -- headers and all.
        --
        -- The timestamp belongs to the scan, so `Scan` stamps it itself now
        -- and every path -- manual, automatic, login -- is throttled the same
        -- way. 0.65.0.
        local seen, atCap, weekly = Currencies.Scan()

        Print("Scanned " .. seen .. " currencies.")
        Print("At cap: " .. atCap .. "   With weekly earning left: " .. weekly)
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Breakdown.lua'] = @'
-- Modules/Breakdown.lua
-- Completion Navigator :: "why isn't this 100%?"
--
-- Every other module answers what it tracks. None of them answer the
-- question a completionist actually asks, which is why a category is not
-- finished and what specifically is in the way.
--
-- Two rules shape this module.
--
-- 1. A percentage is only shown where the denominator is trustworthy. The
--    client knows exactly how many mounts exist; nobody knows how many
--    quests exist. Where the denominator is unknown, counts are shown and
--    the reason is stated, rather than inventing a number that looks
--    authoritative and is not.
--
-- 2. Every line says what to do next, not just what is missing. "4 vendor
--    recipes" is trivia; "4 recipes, open the profession window to see
--    which" is an instruction.

local ADDON_NAME, CN = ...

local Breakdown = CN:RegisterModule("Breakdown")

local Print = CN.Print

-- "1 are locked" reads as a bug even when the number is right.
--
-- Through the shared pluralizer, like everything else. This was the last
-- private copy of the idea; 0.64.0 removed the other one from this file and
-- left this. 0.65.0.
local function Are(count)
    return CN.Pluralize(count, "is", "are")
end

-- THROUGH THE SHARED ONE. 0.64.0.
--
-- This file kept a private copy of the pluralizer while `CN.Pluralize` had
-- exactly one caller and twenty-two other places hand-rolled the same
-- expression. Nothing was wrong -- it is the one-fix-one-call-site shape
-- pre-loaded, and the next grammar change would have landed in one of
-- twenty-three places.
local Plural = CN.Pluralize

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

-- Each category reports: collected, total (or nil when unknowable),
-- remaining lines, and the next action.
Breakdown.categories = {}

function Breakdown.Register(definition)
    if type(definition) ~= "table" or not definition.name then
        return
    end

    definition.order = definition.order or 100

    table.insert(Breakdown.categories, definition)

    table.sort(Breakdown.categories, function(a, b)
        if a.order == b.order then
            return a.name < b.name
        end

        return a.order < b.order
    end)
end

------------------------------------------------------------
-- REPORT
------------------------------------------------------------

local function Percentage(collected, total)
    if not total or total <= 0 then
        return nil
    end

    return collected / total * 100
end

-- CACHED, because the Remaining tab asks for it every two seconds and
-- nothing in it changes except when a collection does.
--
-- Measured: 0.63 ms per call, of which 0.24 ms walks three thousand
-- achievement rows and 0.16 ms walks eighteen hundred pets -- to produce
-- numbers that are identical until the player collects something, and every
-- collection already fires an event this addon subscribes to.
Breakdown.generation = 0

local reportCache, reportGeneration

function Breakdown.NoteChanged()
    Breakdown.generation = Breakdown.generation + 1
end

-- TWO LISTS OF "WHAT CHANGES A COLLECTION COUNT", AND THEY DRIFTED. 0.62.0.
--
-- This file kept its own event list and `Scoring.lua` kept another for
-- `CN.collectionGeneration`. The second one gained the profession, title and
-- level events in 0.61.0 and this one did not -- and this file reports a
-- Recipes row and a Titles row. So a player learned forty recipes in their
-- Alchemy window, the Collections tab moved, and `/cn breakdown` and the
-- Remaining tab went on serving the old figure until some unrelated pet or
-- quest event happened along. `CN.MarkScanned` bumped one counter and not the
-- other, so `/cn profscan` followed by `/cn breakdown` reported the pre-scan
-- count.
--
-- There is now ONE list, in Scoring.lua, and this cache reads it. A rule
-- written down twice is a rule that drifts; this project has now found that
-- shape in the invalidator, the window's refresh events, the collection
-- generation and here.
local function CacheKey()
    return Breakdown.generation .. ":" .. tostring(CN.collectionGeneration or 0)
end

-- `force` IS NOT A LUXURY.
--
-- The cache is keyed on a generation bumped by nine collection events, and
-- most of what this report counts is not a collection: harvested quests,
-- captured recipes, scanned vendors. So the Remaining tab's own Refresh
-- button -- whose tooltip says "counts what is left again" -- could not
-- recount, and a row that says "run /cn harvest" went on showing the old
-- number after the player ran it.
--
-- Anything that ASKED for a recount gets one.
function Breakdown.Report(categoryName, force)
    -- AND A FORCED RECOUNT RECOUNTS THE QUESTS TOO. 0.61.0.
    --
    -- The quest figure is maintained incrementally against a snapshot taken
    -- once, and both edges are credited as they happen -- a discovery and a
    -- turn-in. That is correct for ordinary play and is exactly what this
    -- parameter exists to override: the player pressed Refresh, or ran a
    -- scan, and is asking to be told the truth rather than the remembered
    -- answer.
    --
    -- Same rule as the paragraph above, applied to the one figure in this
    -- file that does not live in `reportCache`.
    if force then
        Breakdown.ForgetQuestCounts()
    end

    if not categoryName and not force then
        if reportCache and reportGeneration == CacheKey() then
            return reportCache
        end
    end

    local rows = {}

    for _, category in ipairs(Breakdown.categories) do
        if not categoryName
            or string.lower(category.name) == string.lower(categoryName) then

            local ok, result = pcall(category.report)

            if ok and type(result) == "table" then
                result.name  = category.name
                result.order = category.order

                table.insert(rows, result)
            elseif not ok then
                -- A category that throws was dropped with no trace, so if
                -- every one of them threw the report said "Nothing to report
                -- yet. Run the scans first." -- which sends the player to do
                -- work that will not help.
                local errors = CN:GetModule("Errors")

                if errors and errors.Record then
                    pcall(errors.Record, "breakdown:" .. tostring(category.name),
                        tostring(result))
                end
            end
        end
    end

    if not categoryName then
        reportCache      = rows
        reportGeneration = CacheKey()
    end

    return rows
end

------------------------------------------------------------
-- BUILT-IN CATEGORIES
------------------------------------------------------------

Breakdown.Register{
    name  = "Mounts",
    order = 10,
    report = function()
        local module = CN:GetModule("Mounts")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.wrongFaction > 0 then
            table.insert(reasons, counts.wrongFaction .. " " .. Are(counts.wrongFaction)
                .. " locked to the opposite faction")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn mountscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Pets",
    order = 11,
    report = function()
        local module = CN:GetModule("Pets")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.unobtainable > 0 then
            table.insert(reasons, counts.unobtainable .. " " .. Are(counts.unobtainable)
                .. " no longer obtainable and can never be collected")
        end

        if counts.wildMissing > 0 then
            table.insert(reasons, counts.wildMissing .. " " .. Are(counts.wildMissing) .. " "
                .. Plural(counts.wildMissing, "a wild pet", "wild pets")
                .. " you can catch in the world")
        end

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            reasons   = reasons,
            action    = counts.known == 0 and "/cn petscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Toys",
    order = 12,
    report = function()
        local module = CN:GetModule("Toys")

        if not module then return nil end

        local counts = module.Summary()

        return {
            collected = counts.collected,
            total     = counts.known,
            remaining = counts.missing,
            action    = counts.known == 0 and "/cn toyscan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Appearances",
    order = 13,
    report = function()
        local module = CN:GetModule("Appearances")

        if not module then return nil end

        local counts = module.Summary()
        local rows   = module.Remaining()

        local reasons = {}

        for index = 1, math.min(3, #rows) do
            table.insert(reasons, rows[index].name .. ": "
                .. rows[index].remaining .. " left")
        end

        return {
            collected = counts.collected,
            total     = counts.total,
            remaining = counts.total - counts.collected,
            reasons   = reasons,
            action    = counts.categories == 0 and "/cn appearancescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Achievements",
    order = 14,
    report = function()
        local module = CN:GetModule("Achievements")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.nearlyDone > 0 then
            table.insert(reasons, counts.nearlyDone .. " " .. Are(counts.nearlyDone)
                .. " within two criteria of finishing")
        end

        return {
            collected = counts.completed,
            total     = counts.total,
            remaining = counts.total - counts.completed,
            reasons   = reasons,
            -- SCAN STATE IS NOT THE LIVE TOTAL.
            --
            -- `counts.total` comes from the client, so it is never zero and
            -- this branch could never fire: a player who has never scanned
            -- saw a healthy "1200 / 3400 (35.3%)" with no in-progress rows and
            -- no prompt to scan. The scan is what fills `inProgress`, so that
            -- is what says whether it has run.
            action    = counts.inProgress == 0 and "/cn achievescan"
                or (counts.nearlyDone > 0 and "/cn closest" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Titles",
    order = 15,
    report = function()
        local module = CN:GetModule("Titles")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.onAccount > counts.onThisOne then
            local elsewhere = counts.onAccount - counts.onThisOne

            table.insert(reasons, elsewhere .. " " .. Are(elsewhere)
                .. " held by another character, not this one")
        end

        return {
            collected = counts.onAccount,
            total     = counts.known,
            remaining = counts.known - counts.onAccount,
            reasons   = reasons,
            action    = (not counts.scanned) and "/cn titlescan" or nil,
        }
    end,
}

Breakdown.Register{
    name  = "Reputations",
    order = 16,
    report = function()
        local module = CN:GetModule("Reputations")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.paragonPending > 0 then
            table.insert(reasons, counts.paragonPending .. " " .. Plural(counts.paragonPending, "has", "have")
                .. " a Paragon reward waiting to be collected")
        end

        if counts.character > 0 then
            table.insert(reasons, counts.character .. " " .. Are(counts.character)
                .. " character-specific, so an alt may be further ahead")
        end

        -- Total factions in the game is not knowable from the client.
        return {
            collected = counts.exalted + counts.maxedRenown,
            total     = nil,
            remaining = nil,
            unknownTotal = "the client does not expose how many factions exist",
            reasons   = reasons,
            action    = (counts.account + counts.character) == 0
                and "/cn repscan"
                or (counts.paragonPending > 0 and "/cn paragon" or nil),
        }
    end,
}

Breakdown.Register{
    name  = "Recipes",
    order = 17,
    report = function()
        local module = CN:GetModule("Professions")

        if not module then return nil end

        local waiting = module.AwaitingRecipeCapture()

        local reasons = {}

        if #waiting > 0 then
            table.insert(reasons, "recipe lists not captured for: "
                .. table.concat(waiting, ", "))
        end

        local known = 0

        for _, record in ipairs(module.Summary()) do
            known = known + (record.recipeKnown or 0)
        end

        return {
            collected    = known,
            total        = nil,
            unknownTotal = "recipes are only countable while a profession window is open",
            reasons      = reasons,
            action       = #waiting > 0 and "open each profession window once" or nil,
        }
    end,
}

-- THIRTY THOUSAND CLIENT CALLS, FOR A NUMBER THAT MOVES BY ONE. 0.61.0.
--
-- This walked every quest the addon has ever discovered -- around 30,000 on
-- an established account -- calling `IsQuestFlaggedCompleted` on each, and it
-- ran on every invalidated Remaining refresh. Measured on the game's own Lua
-- 5.1 at that scale: 13.65 ms, which is most of a frame, for a figure that
-- changes by exactly one when a quest is handed in.
--
-- It is now counted once and then MAINTAINED. A turn-in adds one; a rescan
-- that grows the discovered set recounts. The count is per character, because
-- `IsQuestFlaggedCompleted` answers for the character asking -- the same
-- mistake this category's own comment says it was fixing.
--
-- Held in memory, not on disk: it is derived from something the client
-- re-supplies for free, so persisting it would be the other standing rule
-- broken to fix this one.
local questCounts = {}

function Breakdown.ForgetQuestCounts()
    questCounts = {}
end

function Breakdown.CompletedQuestCount()
    local quests = CN:GetModule("Quests")

    if not quests or not quests.IsCompletedByCharacter then
        return 0
    end

    local key = CN.characterKey or CN.GetCharacterKey()

    local discovered = CN.Account("discoveredQuests")

    local held = questCounts[key]

    -- THE SET GROWING IS NOT A REASON TO RECOUNT ALL OF IT. 0.63.0.
    --
    -- The key was the SIZE of the discovered set, and `RecordDiscovered`
    -- fires from map sweeps, gossip and the quest log -- dozens of new ids on
    -- walking into fresh content. So with the Remaining tab open the sequence
    -- "enter a new zone, hand in a quest" put the whole 30,000-entry walk
    -- back, once per turn-in, for as long as the player was somewhere new.
    -- That is the 13.7 ms this cache was written to remove, returning exactly
    -- where questing puts a player most often.
    --
    -- A newly discovered quest is almost never already completed -- it was
    -- just offered -- and where it is, `NoteDiscovered` below asks the client
    -- about that ONE id, which is a single call rather than thirty thousand.
    -- So the snapshot is now keyed on nothing but its own existence, and both
    -- edges of the count are maintained incrementally: discoveries in, and
    -- turn-ins in.
    --
    -- `Breakdown.ForgetQuestCounts` remains the way to demand a real recount,
    -- and the Remaining tab's Refresh button passes `force` to reach it.
    if held then
        return held.completed
    end

    local completed = 0

    -- The set of ids this figure includes, so a later turn-in cannot credit
    -- one of them twice. Built here rather than lazily: the walk is happening
    -- anyway and the alternative is a second walk later.
    local counted = {}

    for questID in pairs(discovered) do
        if quests.IsCompletedByCharacter(questID) then
            completed = completed + 1

            counted[questID] = true
        end
    end

    questCounts[key] = {
        completed = completed,
        counted   = counted,
    }

    return completed
end

-- Called when a quest is discovered. One client call, not thirty thousand.
--
-- A quest the addon has just seen offered is almost never already completed,
-- but "almost never" is not never -- a repeatable, or a quest first seen on a
-- character who did it years ago. Asking about the one id keeps the snapshot
-- exact without the walk.
function Breakdown.NoteQuestDiscovered(questID)
    local key = CN.characterKey or CN.GetCharacterKey()

    local held = questCounts[key]

    if not held or not questID then
        return
    end

    held.counted = held.counted or {}

    if held.counted[questID] then
        return
    end

    local quests = CN:GetModule("Quests")

    if not quests or not quests.IsCompletedByCharacter then
        return
    end

    if not quests.IsCompletedByCharacter(questID) then
        return
    end

    held.counted[questID] = true
    held.completed        = held.completed + 1
end

-- Called from the turn-in hook. Cheap, exact, and it does not touch the
-- 30,000-entry walk.
--
-- "+1 ON EVERY TURN-IN" IS WRONG, AND WRONG IN THE COMMON CASE.
--
-- The first version of this incremented for any turn-in of a discovered
-- quest. Most turn-ins in a modern evening are REPEATABLE -- a token hand-in,
-- an assault, a holiday daily -- and `IsQuestFlaggedCompleted` stays false for
-- those, so they contribute nothing to the true count while adding one here
-- every single time. Twenty hand-ins is twenty phantom completions, and the
-- Remaining tab could report more quests completed than discovered.
--
-- A daily crossing its reset mid-session is the same shape, once.
--
-- So the client is asked about the ONE quest that just changed -- which is a
-- single call, not a thirty-thousand-entry walk -- and the credit is only
-- taken if the answer moved. `counted` remembers which ids this figure
-- already includes, so a second turn-in of the same quest cannot add a second
-- one.
function Breakdown.NoteQuestCompleted(questID)
    local key = CN.characterKey or CN.GetCharacterKey()

    local held = questCounts[key]

    if not held or not questID then
        return
    end

    -- Only a quest the addon had already discovered was in the denominator
    -- this count walks; one it has not seen will be picked up by the size
    -- change when it is discovered.
    if not CN.Account("discoveredQuests")[questID] then
        return
    end

    held.counted = held.counted or {}

    if held.counted[questID] then
        return
    end

    local quests = CN:GetModule("Quests")

    if not quests or not quests.IsCompletedByCharacter then
        return
    end

    -- The client is the authority on whether this actually completed. A
    -- repeatable quest answers false here and is correctly not credited.
    if not quests.IsCompletedByCharacter(questID) then
        return
    end

    held.counted[questID] = true
    held.completed        = held.completed + 1
end

Breakdown.Register{
    name  = "Quests",
    order = 18,
    report = function()
        local discovered = CN.CountKeys(CN.Account("discoveredQuests"))

        -- ASKED OF THE CLIENT, FOR THIS CHARACTER.
        --
        -- This counted an account-wide `questStatus` store whose
        -- `characterCompleted` flag belonged to whichever character last
        -- scanned, so a fresh alt was shown the main's progress. The client
        -- answers per character, for free, and `discoveredQuests` is the set
        -- worth asking about.
        local completed = Breakdown.CompletedQuestCount()

        return {
            collected    = completed,
            total        = nil,
            unknownTotal = "no API reports how many quests exist; "
                .. "only quests this addon has seen can be counted",
            reasons      = {
                discovered .. " quests discovered so far",
                CN.CountKeys(CN.Account("questHarvest")) .. " harvested with location data",
            },
            action = "/cn harvest",
        }
    end,
}

Breakdown.Register{
    name  = "Currencies",
    order = 19,
    report = function()
        local module = CN:GetModule("Currencies")

        if not module then return nil end

        local counts = module.Summary()

        local reasons = {}

        if counts.capped > 0 then
            table.insert(reasons, counts.capped .. " " .. Are(counts.capped)
                .. " at cap; further earning is wasted")
        end

        if counts.weeklyUnfilled > 0 then
            table.insert(reasons, counts.weeklyUnfilled .. " still " .. Plural(counts.weeklyUnfilled, "has", "have")
                .. " weekly earning available")
        end

        return {
            collected      = counts.known - counts.capped,
        collectedLabel = "not at cap",
            total        = nil,
            unknownTotal = "currencies are a state to manage, not a set to complete",
            reasons      = reasons,
            action       = counts.capped > 0 and "/cn currencies" or nil,
        }
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintRow(row)
    local percentage = Percentage(row.collected, row.total)

    if percentage then
        Print(string.format("|cffffc74f%s|r  %d / %d  (%s)",
            row.name, row.collected, row.total,
            CN.PercentText(percentage / 100, 1)))
    else
        -- THE LABEL THE ROW ASKED FOR. 0.79.0.
        --
        -- "collected" is right for a set you are completing and wrong for a
        -- state you are managing: the currencies row passes the count of
        -- currencies NOT at cap, and this rendered it as "Currencies 12
        -- collected" -- one line above its own note saying currencies are not
        -- a set to complete.
        Print(string.format("|cffffc74f%s|r  %d %s",
            row.name, row.collected or 0, row.collectedLabel or "collected"))

        if row.unknownTotal then
            Print("    |cff8a8f96no percentage: " .. row.unknownTotal .. "|r")
        end
    end

    for _, reason in ipairs(CN.Reasons(row)) do
        CN.PrintLine("    " .. reason)
    end

    if row.action then
        Print("    |cffffc74f-> " .. row.action .. "|r")
    end
end

CN:RegisterCommand{
    name    = "breakdown",
    aliases = { "remaining" },
    args    = "[category]",
    order   = 19,
    help    = "Explain what is left in each category, and why.",
    handler = function(args)
        local requested = args ~= "" and args or nil

        local rows = Breakdown.Report(requested)

        if #rows == 0 then
            if requested then
                Print("No category matches: " .. requested)

                local names = {}

                for _, category in ipairs(Breakdown.categories) do
                    table.insert(names, category.name)
                end

                Print("Try: " .. table.concat(names, ", "))
            else
                Print("Nothing to report yet. Run the scans first.")
            end

            return
        end

        Print("What is left, and why:")

        for _, row in ipairs(rows) do
            PrintRow(row)
        end

        if not requested then
            Print("|cff8a8f96/cn breakdown <category> for one at a time.|r")
        end
    end,
}

-- EVERY EVENT THAT CAN CHANGE A COUNT IN HERE.
--
-- The report walks three thousand achievement rows and eighteen hundred pets
-- to produce numbers that are identical until the player collects something
-- -- and every collection already announces itself. The Remaining tab asked
-- for it every two seconds.
--
-- TWO OF THEM ARE TICKERS, NOT ANNOUNCEMENTS. `UPDATE_FACTION` fires on
-- nearly every reputation tick and `CURRENCY_DISPLAY_UPDATE` on every coin
-- picked up, so while a player was earning anything the Remaining tab's
-- two-second refresh found the 0.63 ms report cache stale on every single
-- tick -- which is the cache doing nothing at all, in the one place it was
-- written for. The other seven fire when something is genuinely collected
-- and stay immediate.
local bursty = {
    UPDATE_FACTION          = true,
    CURRENCY_DISPLAY_UPDATE = true,

    -- AND TURN-INS COME IN RUNS. 0.61.0.
    --
    -- A campaign chain, a bonus objective, a world-quest cluster: four to
    -- eight of these arrive within a couple of seconds, and each one made the
    -- next Remaining refresh walk every store in the addon again for a report
    -- that differs by one row. The exact count is maintained incrementally by
    -- `NoteQuestCompleted` above, which runs BEFORE this debounce and is not
    -- subject to it -- so the number stays right while the expensive recount
    -- of everything else waits for the run to finish.
    QUEST_TURNED_IN         = true,
}

Breakdown.burstSeconds = 5

for _, event in ipairs({
    "NEW_PET_ADDED", "NEW_MOUNT_ADDED", "NEW_TOY_ADDED",
    "ACHIEVEMENT_EARNED", "TRANSMOG_COLLECTION_UPDATED",
    "QUEST_TURNED_IN", "UPDATE_FACTION", "CURRENCY_DISPLAY_UPDATE",
    "PLAYER_ENTERING_WORLD",
}) do
    local burst = bursty[event]

    CN:RegisterEvent(event, function(_, questID)
        if event == "QUEST_TURNED_IN" then
            Breakdown.NoteQuestCompleted(questID)
        end

        -- NOT CLEARED ON PLAYER_ENTERING_WORLD, though the first draft was.
        --
        -- That event fires on every instance zone-in and every loading
        -- screen, so clearing there rebuilt the thirty-thousand-entry walk
        -- several times an evening -- which is the exact cost this cache was
        -- written to remove. The clear was there to handle a character
        -- switch, and it was never needed for that: the count is keyed by
        -- character key, so another character simply reads its own entry, and
        -- switching characters in this game ends the session anyway.

        if burst then
            CN.Debounce("Breakdown." .. event, Breakdown.burstSeconds,
                Breakdown.NoteChanged)
            return
        end

        Breakdown.NoteChanged()
    end)
end

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Exploration.lua'] = @'
-- Modules/Exploration.lua
-- Completion Navigator :: map exploration.
--
-- The map API exposes which overlay textures you have revealed but never how
-- many exist, so a genuine "percent explored" cannot be computed from it.
-- The Exploration achievement category does carry one criterion per subzone,
-- which is the only countable exploration data the client offers -- and each
-- unfinished criterion is the literal name of a place you have not been.
--
-- That turns out to be the more useful shape anyway: "Eversong Woods, 3 of
-- 12 subzones, missing Sunsail Anchorage" is actionable. "78% explored" is
-- not.

local ADDON_NAME, CN = ...

local Exploration = CN:RegisterModule("Exploration")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("exploration")
end

Exploration.Store = Store

-- A NAME, LIVE. 0.64.0.
--
-- The stored name is an achievement name in whatever language last scanned,
-- and `ForCurrentZone` matches it against `GetZoneText()`, which is live. So a
-- player who changed client language had the whole Exploration feature
-- disappear until they happened to rescan -- which is verbatim the failure
-- 0.62.0 describes as fixed. That release corrected the COMPARISON and left
-- the stored side frozen: one half of the defect.
--
-- Same resolver shape as `Achievements.NameOf`, `Pets.NameOf`, `Mounts.NameOf`
-- and `Toys.NameOf`. Fifth store to get one.
function Exploration.NameOf(achievementID, record)
    local live = Blizzard.GetAchievementName
        and Blizzard.GetAchievementName(achievementID)

    if live and live ~= "" then
        return live
    end

    return (record and record.name)
        or ("Achievement " .. tostring(achievementID))
end

-- PROGRESS THROUGH A ZONE IS ONE CHARACTER'S. 0.64.0.
--
-- `done` and `completed` were written into an ACCOUNT store keyed by the
-- achievement id alone -- exactly the defect fixed in `Loremaster` in 0.61.0,
-- in the identically-shaped sibling store the fix never reached. It is worse
-- here, because `RefreshCurrentZone` is wired to `ZONE_CHANGED_NEW_AREA`, so
-- it does not even take a scan: an alt flying through a zone overwrites the
-- main's progress on the way past.
--
-- The split follows what the game scopes. The achievement's NAME and its
-- criteria COUNT are properties of the achievement. How much of it you have
-- explored is yours.
function Exploration.DoneFor(record, characterKey)
    if type(record) ~= "table" then
        return 0
    end

    characterKey = characterKey or CN.characterKey or CN.GetCharacterKey()

    if record.progress and record.progress[characterKey] then
        return record.progress[characterKey].done or 0,
            record.progress[characterKey].completed and true or false
    end

    -- Only the CURRENT character may fall back to the flat field, which holds
    -- whoever wrote last -- naming another character as its owner would be
    -- telling the same lie somewhere new.
    if characterKey == (CN.characterKey or CN.GetCharacterKey()) then
        return record.done or 0, record.completed and true or false
    end

    return nil, nil
end

-- The one writer, so the two places that record progress cannot drift.
function Exploration.NoteProgress(record, done, completed)
    if type(record) ~= "table" then
        return
    end

    local key = CN.characterKey or CN.GetCharacterKey()

    record.progress      = record.progress or {}
    record.progress[key] = {
        done      = done,
        completed = completed and true or false,
    }

    -- THE FLAT FIELD IS NO LONGER WRITTEN. 0.66.0.
    --
    -- It was kept as a fallback for databases written before migration 17
    -- introduced the per-character dimension, and `DoneFor` still READS it
    -- for exactly that reason. But it was also still being written -- by
    -- whoever was logged in, on every `ZONE_CHANGED_NEW_AREA` -- so the
    -- fallback did not return old data, it returned a fresh lie: a brand-new
    -- alt who had never set foot in Eversong Woods was told "Explore Eversong
    -- Woods (9/12)" because the main had flown through it that morning. The
    -- per-character split was bypassed on the exact read path it exists for.
    --
    -- Reading it stays; writing it stops. Old databases still work, and the
    -- field decays out of the store as characters rescan.
end

------------------------------------------------------------
-- SCAN
------------------------------------------------------------

function Exploration.Scan()
    local store = Store()

    local seen, complete = 0, 0

    for _, achievement in ipairs(Blizzard.GetExplorationAchievements()) do
        local held = store[achievement.achievementID] or {}

        held.achievementID = achievement.achievementID
        held.criteria      = achievement.criteria

        -- `lastSeen` IS NOT STORED. 0.89.0.
        --
        -- Nothing anywhere reads an exploration record's `lastSeen`. This is
        -- the field migration 5 stripped from four stores, migration 31 from
        -- appearances and migration 32 from mounts and reputations -- three
        -- sweeps, none of which reached this one, whose writer went on
        -- putting it back on every scan.
        held.lastSeen = nil

        -- `name` IS NOT STORED. See `Exploration.NameOf`.
        held.name = nil

        Exploration.NoteProgress(held, achievement.done, achievement.completed)

        store[achievement.achievementID] = held

        seen = seen + 1

        if achievement.completed then
            complete = complete + 1
        end
    end

    CN.MarkScanned("exploration")

    return seen, complete
end

------------------------------------------------------------
-- QUERIES
------------------------------------------------------------

function Exploration.Summary()
    local counts = {
        zones     = 0,
        complete  = 0,
        criteria  = 0,
        done      = 0,
    }

    for _, record in pairs(Store()) do
        local done, completed = Exploration.DoneFor(record)

        counts.zones    = counts.zones + 1
        counts.criteria = counts.criteria + (record.criteria or 0)
        counts.done     = counts.done + (done or 0)

        if completed then
            counts.complete = counts.complete + 1
        end
    end

    return counts
end

-- Zones with the fewest subzones left, so the cheapest wins come first.
function Exploration.Closest(limit)
    local rows = {}

    for achievementID, record in pairs(Store()) do
        local done, completed = Exploration.DoneFor(record)

        done = done or 0

        -- AND SOMETHING ACTUALLY LEFT. 0.71.0, the same correction as
        -- `Loremaster.Closest`: a row whose criteria are all done but whose
        -- flag has not caught up is not the closest thing to finishing.
        if not completed and (record.criteria or 0) > 0
            and done < record.criteria then
            table.insert(rows, {
                achievementID = record.achievementID,
                name          = Exploration.NameOf(achievementID, record),
                done          = done,
                criteria      = record.criteria,
                remaining     = record.criteria - done,
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.remaining == b.remaining then
            return (a.name or "") < (b.name or "")
        end

        return a.remaining < b.remaining
    end)

    local results = {}

    for index = 1, math.min(limit or 10, #rows) do
        table.insert(results, rows[index])
    end

    return results
end

-- The exploration achievement matching the zone the player is standing in,
-- matched on name because no API maps a UiMapID to its achievement.
-- THE MAP FIRST, THE NAME ONLY AS A FALLBACK.
--
-- This was a substring match over an UNORDERED walk of every exploration
-- achievement the account has, returning the first hit. Retail has two zones
-- called Nagrand and two called Shadowmoon Valley, each with its own "Explore
-- ..." achievement -- both contain the needle, and which one came back was
-- arbitrary and could differ between sessions.
--
-- That was cosmetic while nothing wrote through it. As of this release
-- `RefreshCurrentZone` DOES write through it, so finishing Draenor's Nagrand
-- would stamp `completed = true` on Outland's record, which then vanishes
-- from the list permanently -- only a full `/cn explorescan` rewrites it, and
-- nothing runs one on its own.
--
-- So: the map id, recorded when the record is next refreshed, is the key.
-- The name match survives as the way a record acquires its map id the first
-- time, and is now exact rather than a substring.
-- STAMPED WITH THE ZONE, AND ONLY WHEN THE ZONE IS UNAMBIGUOUS. 0.74.0.
--
-- The sibling in `Modules/Loremaster.lua` had this defect corrected three
-- times over, and this file -- the one it was copied FROM -- was never
-- touched. Two things were wrong here:
--
--   1. `CN.GetPlayerPosition()` is `GetBestMapForUnit`, the most SPECIFIC map
--      containing the player: a building or a cave indoors. So the stamp
--      recorded the wrong id, the fast path missed as soon as the player
--      walked outside, the walk re-ran and re-stamped, and a SavedVariable
--      was written on every threshold crossed. The cache never converged.
--
--   2. Worse, and this one loses data: the id was learned from an unordered
--      `pairs` walk that returned the FIRST name match. With two records both
--      named "Explore Nagrand", which one came back was hash order -- so
--      Outland's record could be permanently bound to Draenor's map, and
--      `RefreshCurrentZone` writes through this lookup. This character's
--      exploration progress and the account's `completed` flag then went into
--      the wrong continent's record.
--
--      That is the exact failure this function's own header names as the
--      reason the map key exists, produced by the way the key was learned.
--
-- `Blizzard.ZoneMapID` answers with the zone rather than the room, and the
-- walk now collects every match and refuses to learn anything when there is
-- more than one. An ambiguous zone keeps answering by the deterministic
-- ordering and simply never writes a binding it cannot justify.
function Exploration.ForCurrentZone()
    local mapID = Blizzard.ZoneMapID
        and Blizzard.ZoneMapID(CN.GetPlayerPosition())

    local store = Store()

    if mapID then
        for _, record in pairs(store) do
            if record.mapID == mapID then
                return record
            end
        end
    end

    local zone = GetZoneText and GetZoneText()

    if not zone or zone == "" then
        return nil
    end

    local needle = string.lower(zone)

    -- THE EXACT MATCH COULD NEVER MATCH. FIXED IN 0.62.0.
    --
    -- `record.name` is an achievement name -- "Explore Eversong Woods" -- and
    -- the needle is a ZONE name, "Eversong Woods". 0.59.0 tightened a working
    -- substring match into an exact one to resolve the two Shadowmoon
    -- Valleys, and in doing so made it compare two strings that are never
    -- equal on any client. Its own comment says the two forms differ.
    --
    -- Everything downstream died silently: `ForCurrentZone` returned nil in
    -- every zone, so the Exploration provider emitted nothing ever, `/cn
    -- exploration` never printed its "This zone" block, and `record.mapID` --
    -- the learned fast path that resolves the ambiguity permanently -- is
    -- only written inside the branch that never ran, so it could never be
    -- learned either.
    --
    -- The harness did not catch it because its fixture fabricates a store row
    -- named after `GetZoneText()` when the lookup fails, which is a stub being
    -- more forgiving than the client. That row is gone and the fixture now
    -- carries the achievement name the client actually returns.
    --
    -- What replaces it keeps the tightening that was wanted. The zone name
    -- must appear as a WHOLE WORD RUN inside the achievement name, anchored
    -- at the end -- "Explore Nagrand" matches "Nagrand", and "Explore
    -- Shadowmoon Valley" matches "Shadowmoon Valley" and not "Shadowmoon".
    -- The genuine duplicate-name case is then resolved by `mapID`, learned on
    -- the first successful lookup, exactly as intended.
    local function Names(candidate)
        if not candidate then
            return false
        end

        candidate = string.lower(candidate)

        if candidate == needle then
            return true
        end

        -- Ends with the zone name, preceded by a space.
        return string.sub(candidate, -(#needle + 1)) == (" " .. needle)
    end

    local matched, matchedID, count = nil, nil, 0

    for achievementID, record in pairs(store) do
        if Names(Exploration.NameOf(achievementID, record)) then
            count = count + 1

            -- Deterministic, so which one is answered with does not depend on
            -- hash order even before anything is learned: the lower id wins.
            if not matchedID or achievementID < matchedID then
                matched, matchedID = record, achievementID
            end
        end
    end

    if matched and mapID and count == 1 then
        -- Learned, so the ambiguity is resolved once rather than every time
        -- -- and only where there was no ambiguity to begin with.
        matched.mapID = mapID
    end

    return matched
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Only the zone the player is already in. Exploration elsewhere is a
-- project, and the criteria carry no coordinates to route to.
CN.RegisterCandidateProvider("Exploration", function()
    local candidates = {}

    local record = Exploration.ForCurrentZone()

    local done, completed = Exploration.DoneFor(record)

    if record and not completed and (record.criteria or 0) > 0 then
        local remaining = record.criteria - (done or 0)

        if remaining > 0
            and not CN.IsIgnored(CN.objectiveTypes.EXPLORATION, record.achievementID)
            and not CN.IsDeferred(CN.objectiveTypes.EXPLORATION, record.achievementID) then

            local reasons = {
                CN.Count(remaining, "subzone")
                    .. " left in this zone",
            }

            local missing = Blizzard.GetIncompleteCriteria(record.achievementID, 3)

            if #missing > 0 then
                table.insert(reasons, "missing: " .. table.concat(missing, ", "))
            end

            table.insert(candidates, CN.NewObjective({
                id              = record.achievementID,
                type            = CN.objectiveTypes.EXPLORATION,
                -- THROUGH THE ACCESSOR. 0.65.0.
                --
                -- `record.name` has been nil since 0.64.0 stopped storing it
                -- and migration 17 deleted it from disk -- and that release
                -- wired the replacement accessor into `Closest` and missed
                -- this, the one place whose output the player actually reads.
                -- So every exploration row rendered as its achievement id:
                -- "1. 1275" in `/cn next`, on the map pin, in the heads-up
                -- line, and "Ignored: nil" when it was hidden.
                name            = Exploration.NameOf(record.achievementID,
                    record),
                accountWide     = true,
                completionValue = math.max(1, 4 - remaining),
                travelCost      = 0,
                reasons         = reasons,
            }))
        end
    end

    return candidates
-- A COOLDOWN ON THE CHATTIEST EVENT THERE IS. 0.79.0.
--
-- `Scoring.lua` names `CRITERIA_UPDATE` as the canonical case a cooldown
-- exists for; `Achievements` and `Loremaster` both give it five seconds and
-- this, the third handler of the same event, had none. Exploration criteria
-- do not move faster than the player walks.
end, { events = { "CRITERIA_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- REFRESH IT WHEN IT CHANGES, NOT ONLY WHEN YOU ARRIVE.
--
-- The provider declared `CRITERIA_UPDATE` -- which is exactly the event that
-- fires when you discover a subzone -- and rebuilt on it, reading the same
-- persisted record it had read on entering the zone. So "3 subzones left"
-- was frozen at 3 for as long as the player explored, and only moved when
-- they left the zone and came back.
--
-- Throttled, because a discovery fires several criteria updates in a row and
-- this is a client call per zone. `CN.Debounce` answers the first
-- immediately, which is the one the player is watching for.
Exploration.refreshSeconds = 2

local function RefreshCurrentZone()
    local record = Exploration.ForCurrentZone()

    if not record then
        return false
    end

    local done, criteria = Blizzard.GetAchievementProgress(record.achievementID)

    -- NOT OVER GOOD DATA WITH NOTHING.
    --
    -- `GetAchievementProgress` answers `0, 0` when the criteria API is
    -- unavailable, which is a refusal rather than a measurement -- and this
    -- writes straight into the persisted store. Overwriting a scanned "9
    -- criteria, 4 done" with "0 of 0" loses the record and makes the zone
    -- disappear from the list.
    if not criteria or criteria <= 0 then
        return false
    end

    record.criteria = criteria

    -- AND WRITE `completed`, which nothing did.
    --
    -- `Exploration.Closest` filters on `not record.completed` and sorts by
    -- what is left, ascending -- so a zone finished this session sat at the
    -- top of that list reading "0 left" for ever, because the only writer of
    -- the flag was the full scan.
    -- SET AND CLEARED, both. A patch that adds a subzone to a zone you had
    -- finished must be able to un-finish it; a flag that only ever goes one
    -- way is a flag that is wrong for the rest of the account's life.
    --
    -- THROUGH THE ONE WRITER, so this and the scan cannot record progress
    -- differently -- and so both file it under the character it belongs to.
    -- This function is wired to `ZONE_CHANGED_NEW_AREA`, so before 0.64.0 an
    -- alt flying through a zone overwrote the main's progress in passing.
    -- MOVED, NOT MERELY READABLE. 0.72.0.
    --
    -- This returned true whenever the criteria API answered at all, and the
    -- `CRITERIA_UPDATE` handler below turns that into
    -- `CN.InvalidateProvider("Exploration")` -- so every debounce window
    -- while questing threw away the provider's cached rows and rebuilt them,
    -- whether or not a single number had changed. `Loremaster` was given the
    -- `before ~= done` test in 0.71.0; the sibling it was copied FROM never
    -- got it.
    local before = Exploration.DoneFor(record)

    Exploration.NoteProgress(record, done, done and done >= criteria)

    return before ~= done
end

Exploration.RefreshCurrentZone = RefreshCurrentZone

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", RefreshCurrentZone)

CN:RegisterEvent("CRITERIA_UPDATE", function()
    CN.Debounce("Exploration.criteria", Exploration.refreshSeconds, function()
        if RefreshCurrentZone() then
            CN.InvalidateProvider("Exploration")
        end
    end)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "explorescan",
    order   = 67,
    help    = "Scan exploration achievements.",
    handler = function()
        local seen, complete = Exploration.Scan()

        Print("Scanned " .. seen .. " exploration achievements.")
        Print("Complete: " .. complete)
    end,
}

CN:RegisterCommand{
    name    = "exploration",
    aliases = { "explore" },
    args    = "[count]",
    order   = 68,
    help    = "Show zones with the least exploration left.",
    handler = function(args)
        local counts = Exploration.Summary()

        if counts.zones == 0 then
            Print("No exploration data yet. Run /cn explorescan.")
            return
        end

        Print("Exploration: " .. counts.complete .. " / " .. counts.zones .. " zones")

        if counts.criteria > 0 then
            -- NO PERCENTAGE. This file's own header says a genuine "percent
            -- explored" is uncomputable and that "78% explored is not
            -- [useful]" -- and then printed one, computed against the sum of
            -- criteria in the achievements this addon happens to have stored.
            -- Not the world; not even every zone, since a zone with no
            -- exploration achievement contributes nothing to either side.
            -- A player reads "73.0%" as the world.
            --
            -- The raw counts are honest and are what remains.
            Print(string.format("Subzones discovered: %d of %d in the "
                .. "exploration achievements this addon has scanned",
                counts.done, counts.criteria))
        end

        local here = Exploration.ForCurrentZone()

        if here then
            -- THROUGH THE PER-CHARACTER ACCESSOR. 0.65.0.
            --
            -- `Summary`, `Closest` and the provider all go through
            -- `DoneFor`; this read the flat fields, which hold whichever
            -- character wrote last. So an alt could type `/cn exploration`
            -- and read another character's numbers on the "This zone" line
            -- while "Closest to finishing" three lines below showed its own.
            local hereDone, hereComplete = Exploration.DoneFor(here)

            if hereComplete then
                Print("This zone: |cff73b873fully explored|r")
            else
                Print("This zone: " .. (hereDone or 0)
                    .. " / " .. (here.criteria or 0))

                local missing = Blizzard.GetIncompleteCriteria(here.achievementID, 6)

                for _, name in ipairs(missing) do
                    CN.PrintLine("  missing: " .. name)
                end
            end
        end

        local closest = Exploration.Closest(CN.ToID(args) or 5)

        if #closest > 0 then
            Print("Closest to finishing:")

            for _, row in ipairs(closest) do
                CN.PrintLine("  " .. row.name .. " |cff8a8f96("
                    .. row.done .. "/" .. row.criteria .. ")|r")
            end
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Filters.lua'] = @'
-- Modules/Filters.lua
-- Completion Navigator :: managing what you told the addon to hide.
--
-- Ignore and defer have existed since the first build, and until now there
-- was no way to see either list or undo anything in them. Ignoring something
-- by accident meant it was gone permanently with no recourse, which is a
-- bug wearing a feature's clothes.
--
-- Defer also only offered one hour. The spec asked for a real set of
-- durations, and "until the weekly reset" is the one that actually matches
-- how the game works.

local ADDON_NAME, CN = ...

local Filters = CN:RegisterModule("Filters")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local HOUR = 3600
local DAY  = 86400

------------------------------------------------------------
-- DURATIONS
------------------------------------------------------------

-- Ordered, because they are offered as a list.
--
-- REACHABLE AT LAST. 0.88.0.
--
-- This table had no reader anywhere in the addon: every deferral in the tree
-- was a hardcoded 3600, and there was no command that took a duration -- so
-- the only thing a player could ever do was put something off for an hour.
-- The file header says why the table was written: "Defer also only offered
-- one hour... 'until the weekly reset' is the one that actually matches how
-- the game works."
--
-- Two of the rows could not have worked as written either. `seconds = nil` in
-- a table constructor stores nothing at all, so "until reset" was
-- indistinguishable from a malformed row; and `math.huge` renders through
-- `FormatRemaining` as "infd", which is what `/cn hidden` would have printed
-- the day somebody wired it up. Both are resolved rather than stored now.
Filters.durations = {
    { key = "hour",    label = "1 hour",        seconds = HOUR },
    { key = "day",     label = "Today",         seconds = DAY },
    { key = "tomorrow",label = "Tomorrow",      seconds = 2 * DAY },
    { key = "week",    label = "This week",     seconds = 7 * DAY },
    { key = "reset",   label = "Until reset",   computed = "weeklyReset" },
    { key = "forever", label = "Until I undo it", seconds = math.huge },
}

-- Seconds for a named duration, resolving the one that depends on the clock.
-- Falls back to an hour, which is what every caller used to hardcode.
function Filters.DurationSeconds(key)
    for _, duration in ipairs(Filters.durations) do
        if duration.key == key then
            if duration.computed == "weeklyReset" then
                return CN.Blizzard.GetSecondsUntilWeeklyReset() or DAY
            end

            return duration.seconds
        end
    end

    return HOUR
end

-- The labels, for a command's help and for anything that offers the choice.
function Filters.DurationKeys()
    local keys = {}

    for _, duration in ipairs(Filters.durations) do
        table.insert(keys, duration.key)
    end

    return keys
end

------------------------------------------------------------
-- TYPE FILTERING
------------------------------------------------------------

-- Which KINDS of objective the recommendation list may contain.
--
-- Distinct from ignore and defer, which hide one specific objective. This is a
-- standing preference about what you want to be told about at all: someone
-- levelling wants quests, someone finishing a collection does not.
--
-- Only DISABLED types are stored. That way a type added in a later release is
-- enabled by default rather than silently invisible to everyone who upgraded,
-- which is the failure mode of storing an allow-list.
local function HiddenTypes()
    local settings = CN.Settings()

    if not settings then
        return {}
    end

    settings.hiddenTypes = settings.hiddenTypes or {}

    return settings.hiddenTypes
end

Filters.HiddenTypes = HiddenTypes

-- Bumped whenever the filter changes, so the ranked list knows to rebuild
-- without invalidating the providers, which have not changed at all.
CN.typeFilterGeneration = 0

local function Bump()
    CN.typeFilterGeneration = (CN.typeFilterGeneration or 0) + 1
end

function Filters.IsTypeEnabled(objectiveType)
    if not objectiveType then
        return true
    end

    local hidden = HiddenTypes()

    if next(hidden) == nil then
        return true
    end

    return not hidden[objectiveType]
end

function Filters.SetTypeEnabled(objectiveType, enabled)
    if not objectiveType then
        return false
    end

    local hidden = HiddenTypes()

    if enabled then
        hidden[objectiveType] = nil
    else
        hidden[objectiveType] = true
    end

    Bump()

    return true
end

function Filters.ToggleType(objectiveType)
    local enabled = Filters.IsTypeEnabled(objectiveType)

    Filters.SetTypeEnabled(objectiveType, not enabled)

    return not enabled
end

function Filters.EnableAllTypes()
    local hidden = HiddenTypes()

    local count = CN.CountKeys(hidden)

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    Bump()

    return count
end

-- Everything except this one.
function Filters.OnlyType(objectiveType)
    local hidden = HiddenTypes()

    for key in pairs(hidden) do
        hidden[key] = nil
    end

    for _, known in ipairs(Filters.TypeOrder()) do
        if known ~= objectiveType then
            hidden[known] = true
        end
    end

    Bump()

    return true
end

-- The types worth offering, in a stable order. Deliberately not every entry in
-- CN.objectiveTypes: VENDOR and COLLECTIBLE are internal plumbing rather than
-- things anyone would choose to be shown.
function Filters.TypeOrder()
    local types = CN.objectiveTypes

    return {
        types.QUEST,
        types.ACHIEVEMENT,
        types.REPUTATION,
        types.PET,
        types.MOUNT,
        types.TOY,
        types.APPEARANCE,
        types.RECIPE,
        types.PROFESSION,
        types.RARE,
        types.TREASURE,
        types.EXPLORATION,
        types.TITLE,
        types.CURRENCY,
        types.INSTANCE,
    }
end

-- Friendly names live in Objectives.lua now, beside the enum they name, so
-- that everything which prints a type can reach them -- most of the places
-- that do load long before this file. These two are kept as the names the
-- rest of this module already uses.
Filters.typeLabels = CN.typeLabels

Filters.TypeLabel = CN.TypeLabel

-- Accepts what a person would actually type.
function Filters.ResolveType(text)
    if not text or text == "" then
        return nil
    end

    local needle = string.lower(CN.Trim(text))

    for _, objectiveType in ipairs(Filters.TypeOrder()) do
        if string.lower(objectiveType) == needle
            or string.lower(Filters.TypeLabel(objectiveType)) == needle then
            return objectiveType
        end

        -- "quest" should match QUEST, "pet" should match PET.
        if string.lower(Filters.TypeLabel(objectiveType)):find(needle, 1, true) then
            return objectiveType
        end
    end

    return nil
end

function Filters.HiddenTypeCount()
    return CN.CountKeys(HiddenTypes())
end

-- Exposed on CN so the scoring layer can consult it without knowing that a
-- Filters module exists.
function CN.IsObjectiveTypeEnabled(objectiveType)
    return Filters.IsTypeEnabled(objectiveType)
end

------------------------------------------------------------
-- READING THE LISTS
------------------------------------------------------------

-- Objective keys are "TYPE:id". Splitting them back out is what lets the
-- lists show a name rather than an opaque string.
local function SplitKey(key)
    local objectiveType, id = string.match(tostring(key), "^(.-):(.+)$")

    return objectiveType, tonumber(id) or id
end

Filters.SplitKey = SplitKey

-- Best-effort name for anything the addon might have hidden.
function Filters.DescribeObjective(objectiveType, id)
    local types = CN.objectiveTypes

    local numericID = tonumber(id)

    if objectiveType == types.QUEST and numericID then
        return CN.GetQuestName(numericID) or ("Quest " .. numericID)
    end

    -- Cached name first, then ask the client.
    --
    -- Names used to come only from a previous scan, so pinning something the
    -- addon had not seen yet produced "Faction 2600" -- which is the addon
    -- telling the player it does not know what they just asked for. The
    -- client knows. Ask it.
    -- THE CLIENT FIRST, THE STORE SECOND. 0.64.0.
    --
    -- This asked the STORE first and the client only when the store was
    -- empty, which is backwards and is the opposite of what the pet, mount
    -- and achievement branches below do. A stored name is frozen at whatever
    -- language last scanned, so `/cn hidden` listed old-locale faction names
    -- beside correctly re-localized pet names in the same list.
    if objectiveType == types.REPUTATION and numericID then
        local data = CN.Blizzard.GetFactionByID(numericID)

        if data and data.name then
            return data.name
        end

        return CN.Account("factionNames")[numericID]
            or ("Faction " .. numericID)
    end

    if objectiveType == types.PET and numericID then
        -- The client's journal first: since 0.36.0 the addon no longer keeps
        -- its own copy of every pet name on disk.
        local live = CN.Blizzard.GetPetName(numericID)

        if live then
            return live
        end

        local record = CN.Account("pets")[numericID]

        return (record and record.name) or ("Pet " .. numericID)
    end

    if objectiveType == types.MOUNT and numericID then
        -- The same order as every other branch. It is inert today only
        -- because migration 16 emptied the stored field -- which is to say
        -- the rule was written down twice in one function and the two copies
        -- disagreed, waiting for the next release to reinstate a name. 0.65.0.
        local mounts = CN:GetModule("Mounts")

        if mounts and mounts.NameOf then
            return mounts.NameOf(numericID)
        end

        return "Mount " .. numericID
    end

    if objectiveType == types.TOY and numericID then
        -- CLIENT FIRST, LIKE ITS FOUR NEIGHBOURS. 0.65.0.
        --
        -- 0.64.0 flipped the reputation, currency, recipe and title branches
        -- to ask the client first and left this one reading a field 0.63.0
        -- had stopped writing -- so a hidden toy was unnameable, and
        -- `/cn unhide <name>` could not match it.
        local toys = CN:GetModule("Toys")

        if toys and toys.NameOf then
            return toys.NameOf(numericID)
        end

        return "Toy " .. numericID
    end

    -- THE BADGE, NOT THE ENUM. 0.66.0.
    --
    -- Every other branch in this function produces a title-cased placeholder
    -- -- "Quest 123", "Toy 123", "Faction 123". This one concatenated the raw
    -- uppercase token, so `/cn hidden` listed `RARE 5487` as the name of the
    -- thing the player had hidden: the addon's own internals, which is the
    -- exact defect the APPEARANCE branch below was written to fix.
    --
    -- It broke a second thing at a distance. `Goals.List` decides whether the
    -- describer has learned a real name by comparing against the placeholder
    -- it expects -- "Rare 5487" -- and `"RARE 5487"` never equalled it, so a
    -- pinned rare's placeholder was written over the stored name.
    if (objectiveType == types.RARE or objectiveType == types.TREASURE) and numericID then
        local record = CN.Account("rares")[numericID]

        return record and record.name
            or (CN.TypeBadge(objectiveType) .. " " .. numericID)
    end

    -- APPEARANCE COVERS TWO ID SPACES, AND SAYS WHICH. 0.61.0.
    --
    -- Transmog sets and appearance categories are both filed under
    -- APPEARANCE, distinguished by a `set:` prefix since the two collided.
    -- Without a branch here, a hidden set showed up in `/cn hidden` as
    -- "APPEARANCE set:2314" -- the addon's own internals, offered to the
    -- player as the name of the thing they hid.
    if objectiveType == types.APPEARANCE then
        local setID = type(id) == "string" and tonumber(id:match("^set:(%d+)$"))

        if setID then
            -- The addon's own reader, not a fresh client call: `Sets.All`
            -- already holds a name per set and is cached until a transmog is
            -- collected. Asking the client again here would be a second way
            -- to get the same answer, which is how the two drift.
            local sets = CN:GetModule("Sets")

            for _, set in ipairs(sets and (sets.All()) or {}) do
                if set.setID == setID and set.name then
                    return set.name
                end
            end

            return "Appearance set " .. setID
        end

        if numericID then
            local categories = CN.Blizzard.GetAppearanceCategories
                and CN.Blizzard.GetAppearanceCategories() or nil

            if type(categories) == "table" then
                for _, category in ipairs(categories) do
                    if category.categoryID == numericID and category.name then
                        return category.name
                    end
                end
            end

            return "Appearance slot " .. numericID
        end
    end

    if objectiveType == types.ACHIEVEMENT and numericID then
        local record = CN.Account("achievements")[numericID]

        if record and record.name then
            return record.name
        end

        return CN.Blizzard.GetAchievementName(numericID)
            or ("Achievement " .. numericID)
    end

    -- AND THESE TWO HAD NO LIVE PATH AT ALL. 0.64.0.
    --
    -- Migration 16's header says it removed "the last of the names the client
    -- hands back for free", and these were still being read from disk with no
    -- fallback to the client that answers instantly.
    -- THROUGH THE MODULE, NOT A SECOND COPY OF IT. 0.65.0.
    --
    -- These two each carried their own live-then-store lookup, written before
    -- `Currencies.NameOf` and `Titles.NameOf` existed. Two copies of one rule
    -- drift, and these had already: both still ended at a name store that
    -- migration 18 deletes -- and `CN.Account(key)` CREATES the table it is
    -- asked for, so reading it here put the store back, empty, every login.
    if objectiveType == types.CURRENCY and numericID then
        local currencyModule = CN:GetModule("Currencies")

        if currencyModule and currencyModule.NameOf then
            return currencyModule.NameOf(numericID)
        end

        return "Currency " .. numericID
    end

    -- AND THE THIRD OF THE THREE. 0.66.0.
    --
    -- The note above says "these two had no live path at all" and then gave
    -- CURRENCY and TITLE one. RECIPE is the third member of that group and
    -- was left asking disk first with no client fallback -- the only branch
    -- in this function that does. A hidden vendor recipe read back as
    -- "Recipe 194424" until a profession window had been opened, and after a
    -- client-language change it showed the previous locale's name beside pet
    -- and mount names that had correctly re-localized.
    --
    -- BUT THE STORE FIRST, BECAUSE RECIPE IS THREE ID SPACES. 0.67.0.
    --
    -- 0.66.0 put the client's item lookup ahead of the store on the grounds
    -- that every other branch asks the client first. Every other branch has
    -- ONE id space. This type carries three: a merchant itemID from Vendors,
    -- a trade-skill recipe id from Professions -- which is what
    -- `recipeNames` is keyed by -- and a crafting orderID from Orders.
    --
    -- `GetItemName` on a trade-skill recipe id returns nil, or, where the
    -- number happens to collide with a real item, the name of a wholly
    -- unrelated one -- and being asked first, it BEAT the correct stored
    -- name. So a hidden Alchemy recipe that read back correctly in 0.65.0
    -- read back as some other item entirely, and `/cn unhide <name>` could
    -- not match what the list had printed.
    --
    -- The store is keyed by the one id space that has a name recorded for it;
    -- the client is asked for everything else.
    if objectiveType == types.RECIPE and numericID then
        local stored = CN.Account("recipeNames")[numericID]

        if stored and stored ~= "" then
            return stored
        end

        local live = CN.Blizzard.GetItemName and CN.Blizzard.GetItemName(numericID)

        if live and live ~= "" then
            return live
        end

        return "Recipe " .. numericID
    end

    if objectiveType == types.TITLE and numericID then
        local titleModule = CN:GetModule("Titles")

        if titleModule and titleModule.NameOf then
            return titleModule.NameOf(numericID)
        end

        return "Title " .. numericID
    end

    -- THE SYNTHETIC IDS, BY NAME. 0.79.0.
    --
    -- A handful of rows stand for an ACTION rather than for a thing with an
    -- id -- claiming the vault, collecting a finished crafting order -- and
    -- carry a string id so the filter stores can key on them. 0.78.0 gave
    -- those rows working hide-and-defer guards, which made this display path
    -- reachable for the first time, and it rendered them as "Currency vault"
    -- and "Recipe claim": the addon's own internals offered to the player as
    -- the name of the thing they hid.
    --
    -- Named here rather than by reaching into the modules, because the whole
    -- point of this function is that it answers for a store row long after
    -- the provider that made it has stopped producing one.
    -- ALL OF THEM, NOT THE TWO THAT WERE KNOWN. 0.83.0.
    --
    -- 0.79.0 added this table for the two singleton rows that existed then
    -- and 0.82.0 made a third hideable without adding it, so `/cn hidden`
    -- read "Currency mail [Currency mail]" -- naming the row twice, in the
    -- addon's internal vocabulary, in the one list a player consults to
    -- decide what to restore. Two more were open the whole time: the
    -- keystone row, and the Great Vault's five per-row ids.
    --
    -- Every string id any provider emits belongs here. A test now sweeps
    -- the live candidate list for one that does not.
    local synthetic = {
        mail     = "Expiring mail",
        vault    = "Collect your Great Vault reward",
        claim    = "Collect your finished crafting order",
        keystone = "Your Mythic+ keystone",
        RAID     = "Great Vault: raid progress",
        DUNGEON  = "Great Vault: dungeon progress",
        WORLD    = "Great Vault: world progress",
        PVP      = "Great Vault: PvP progress",
        UNKNOWN  = "Great Vault progress",
    }

    if type(id) == "string" and synthetic[id] then
        return synthetic[id]
    end

    -- A PREFIXED ID IS STILL A ROW WITH A NAME. 0.83.0. `Modules/Orders.lua`
    -- keys a crafting order as "order:<n>" so it cannot be mistaken for a
    -- recipe id; without this the hidden list would read "Recipe order:412".
    if type(id) == "string" then
        local orderID = id:match("^order:(%d+)$")

        if orderID then
            return "Crafting order " .. orderID
        end
    end

    -- THE BADGE, NOT THE ENUM, FOR EVERYTHING THAT REACHES HERE. 0.67.0.
    --
    -- Every branch above produces a title-cased placeholder, and this last
    -- line -- which catches every id that is not a number, such as the
    -- crafting-order row whose id is the string "claim" -- produced
    -- "RECIPE claim". The addon's own internals offered to the player as the
    -- name of the thing they hid, which is the defect two branches above were
    -- rewritten to fix.
    return CN.TypeBadge(objectiveType) .. " " .. tostring(id)
end

-- The stores are nested by type since 0.54.0 -- see CN.IsIgnored for why --
-- so these walk them through `CN.EachFiltered` rather than splitting a string
-- key back apart. `key` is kept on the row because the UI and `/cn unhide`
-- both address a row by it.
function Filters.ListIgnored()
    local rows = {}

    for objectiveType, id, entry in CN.EachFiltered(CN.Account("ignoredObjectives")) do
        table.insert(rows, {
            key   = CN.ObjectiveKey(objectiveType, id),
            type  = objectiveType,
            id    = id,
            name  = Filters.DescribeObjective(objectiveType, id),
            since = entry and entry.since,
        })
    end

    table.sort(rows, function(a, b) return (a.name or "") < (b.name or "") end)

    return rows
end

function Filters.ListDeferred()
    local rows = {}

    local now = time()

    for objectiveType, id, entry in CN.EachFiltered(CN.Account("deferredObjectives")) do
        local remaining

        if entry and entry.until_ then
            remaining = entry.until_ - now
        end

        table.insert(rows, {
            key       = CN.ObjectiveKey(objectiveType, id),
            type      = objectiveType,
            id        = id,
            name      = Filters.DescribeObjective(objectiveType, id),
            remaining = remaining,
            expired   = remaining ~= nil and remaining <= 0,
        })
    end

    table.sort(rows, function(a, b)
        return (a.remaining or math.huge) < (b.remaining or math.huge)
    end)

    return rows
end

------------------------------------------------------------
-- UNDO
------------------------------------------------------------

function Filters.Restore(key)
    local objectiveType, id = SplitKey(key)

    if not objectiveType then
        return false
    end

    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local removed = false

    if ignored[objectiveType] and ignored[objectiveType][id] ~= nil then
        ignored[objectiveType][id] = nil
        removed = true

        if next(ignored[objectiveType]) == nil then
            ignored[objectiveType] = nil
        end
    end

    if deferred[objectiveType] and deferred[objectiveType][id] ~= nil then
        deferred[objectiveType][id] = nil
        removed = true

        if next(deferred[objectiveType]) == nil then
            deferred[objectiveType] = nil
        end
    end

    -- Same reason as CN.SetIgnored: the list a provider built is the list the
    -- player sees, and un-hiding something has to rebuild it.
    if removed and CN.InvalidateCandidates then
        CN.InvalidateCandidates()
    end

    return removed
end

function Filters.RestoreAll()
    local ignored  = CN.Account("ignoredObjectives")
    local deferred = CN.Account("deferredObjectives")

    local count = 0

    for _ in CN.EachFiltered(ignored) do
        count = count + 1
    end

    for _ in CN.EachFiltered(deferred) do
        count = count + 1
    end

    for objectiveType in pairs(ignored) do
        ignored[objectiveType] = nil
    end

    for objectiveType in pairs(deferred) do
        deferred[objectiveType] = nil
    end

    if count > 0 and CN.InvalidateCandidates then
        CN.InvalidateCandidates()
    end

    return count
end

-- Deferrals that have run out are dead weight in SavedVariables.
function Filters.PruneExpired()
    local deferred = CN.Account("deferredObjectives")

    local now, pruned = time(), 0

    for objectiveType, byType in pairs(deferred) do
        for id, entry in pairs(byType) do
            if entry and entry.until_ and entry.until_ <= now then
                byType[id] = nil
                pruned = pruned + 1
            end
        end

        if next(byType) == nil then
            deferred[objectiveType] = nil
        end
    end

    return pruned
end

-- A DEFERRAL THAT EXPIRES HAS TO WAKE SOMETHING UP.
--
-- Setting one invalidates the candidates -- `Objectives.lua` explains why, at
-- length. Nothing fires when one runs out. Every provider consults
-- `CN.IsDeferred` at BUILD time, so the deferral is baked into the cached
-- list; and the providers a deferral is most often used on -- Mounts, Pets,
-- Toys, Sets, Appearances -- are not volatile and subscribe only to their own
-- collection events.
--
-- So: right-click the heads-up line to put a mount off for an hour, and an
-- hour later it does not come back. `/cn hidden` reports the deferral as
-- expired while the objective is still missing from the list, which is the
-- addon contradicting itself about its own state.
--
-- A slow ticker, and only when it actually pruned something. Sixty seconds
-- is well inside the resolution anybody defers anything at.
Filters.pruneSeconds = 60

local pruneTicker

function Filters.StartPruneTicker()
    if pruneTicker or not C_Timer or not C_Timer.NewTicker then
        return false
    end

    pruneTicker = C_Timer.NewTicker(Filters.pruneSeconds, function()
        -- Guarded: a repeating callback that throws is a repeating error box.
        CN.Guard("Filters.PruneExpired", Filters.SweepExpired)
    end)

    return true
end

-- Prunes, and tells the ranking if anything came back. Split out so the
-- ticker and the tests call the same thing.
function Filters.SweepExpired()
    local pruned = Filters.PruneExpired()

    if pruned > 0 then
        DebugPrint("Pruned " .. pruned .. " expired deferral(s).")

        -- Something is actionable again that was not a moment ago, which is
        -- exactly what a deliberate invalidation means.
        CN.InvalidateCandidates()
    end

    return pruned
end

CN:OnLogin(function()
    Filters.SweepExpired()

    Filters.StartPruneTicker()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function FormatRemaining(seconds)
    if not seconds then
        return "indefinitely"
    end

    -- AND SO IS THE SENTINEL FOR IT. 0.88.0. `math.huge` divided by an hour
    -- is still infinite, so this printed "infd" for the one duration whose
    -- whole meaning is that it does not run out.
    if seconds == math.huge then
        return "indefinitely"
    end

    if seconds <= 0 then
        return "expired"
    end

    if seconds < HOUR then
        return math.floor(seconds / 60) .. "m"
    end

    if seconds < DAY then
        return math.floor(seconds / HOUR) .. "h"
    end

    return math.floor(seconds / DAY) .. "d"
end

Filters.FormatRemaining = FormatRemaining

CN:RegisterCommand{
    name    = "hidden",
    aliases = { "ignored" },
    order   = 20,
    help    = "Show everything you have ignored or deferred.",
    handler = function()
        local ignored  = Filters.ListIgnored()
        local deferred = Filters.ListDeferred()

        if #ignored == 0 and #deferred == 0 then
            Print("Nothing is hidden.")
            return
        end

        if #ignored > 0 then
            Print("Ignored (" .. #ignored .. "):")

            for _, row in ipairs(ignored) do
                -- THE BADGE, NOT THE ENUM. `row.type` is the internal name --
                -- "COLLECTIBLE", "EXPLORATION" -- and this is a list a player
                -- reads to decide what to restore.
                CN.PrintLine(row.name .. " " .. CN.Muted("["
                    .. CN.TypeBadge(row.type) .. " " .. tostring(row.id)
                    .. "]"))
            end
        end

        if #deferred > 0 then
            Print("Deferred (" .. #deferred .. "):")

            for _, row in ipairs(deferred) do
                -- AND THE ID, WHICH WAS MISSING.
                --
                -- The footer two lines below says `/cn unhide <id>` restores
                -- one, and `Filters.Restore` matches on the id -- so a
                -- deferred objective could not be restored individually,
                -- because the only place its id would have appeared did not
                -- print it. Every other row in this command carried one.
                CN.PrintLine(row.name .. " " .. CN.Muted("["
                    .. CN.TypeBadge(row.type) .. " " .. tostring(row.id)
                    .. CN.DOT .. " " .. FormatRemaining(row.remaining)
                    .. " left]"))
            end
        end

        Print("|cffffc74f/cn unhide <id>|r to restore one, "
            .. "|cffffc74f/cn unhide all|r for everything.")
    end,
}

-- PUTTING SOMETHING OFF FOR LONGER THAN AN HOUR. 0.88.0.
--
-- The duration table above has existed for many releases with no reader:
-- every deferral in the addon was a hardcoded hour, and there was no command
-- that took a duration. "Until reset" -- the one the file header calls the
-- duration that actually matches how the game works -- had never been
-- available to anybody.
--
-- Defers the CURRENT recommendation by default, because that is the thing a
-- player has just been told to do and is deciding not to.
CN:RegisterCommand{
    name    = "defer",
    aliases = { "later", "snooze" },
    args    = "[hour|day|tomorrow|week|reset|forever]",
    order   = 22,
    help    = "Put the current recommendation off for longer than an hour.",
    handler = function(args)
        local objective = CN.currentRecommendation

        if not objective or not objective.type or not objective.id then
            Print("Nothing is being recommended right now. "
                .. "Run |cffffc74f/cn next|r first.")
            return
        end

        local key = string.lower(CN.Trim(args or ""))

        if key == "" then
            key = "hour"
        end

        local matched

        for _, duration in ipairs(Filters.durations) do
            if duration.key == key then
                matched = duration
            end
        end

        if not matched then
            Print("Durations: |cffffc74f"
                .. table.concat(Filters.DurationKeys(), "|r, |cffffc74f")
                .. "|r.")
            return
        end

        local seconds = Filters.DurationSeconds(key)

        CN.SetDeferred(objective.type, objective.id, seconds)

        CN.InvalidateCandidates()

        Print("Deferred: " .. tostring(objective.name or objective.id)
            .. CN.Aside(matched.label .. CN.DOT .. " "
                .. FormatRemaining(seconds)))

        Print("|cff8a8f96|cffffc74f/cn unhide " .. tostring(objective.id)
            .. "|r brings it back sooner.|r")
    end,
}

CN:RegisterCommand{
    name    = "unhide",
    aliases = { "restore" },
    args    = "<id or all>",
    order   = 21,
    help    = "Undo an ignore or a deferral.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn unhide <id or all>")
            return
        end

        if string.lower(args) == "all" then
            local count = Filters.RestoreAll()

            Print("Restored " .. count .. " hidden objective"
                .. CN.Pluralize(count, "") .. ".")
            return
        end

        local wanted = tostring(CN.ToID(args) or args)

        local restored = 0

        -- Match on the id alone, since the player sees ids and not the
        -- internal TYPE:id key.
        for _, row in ipairs(Filters.ListIgnored()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    CN.PrintLine("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        for _, row in ipairs(Filters.ListDeferred()) do
            if tostring(row.id) == wanted then
                if Filters.Restore(row.key) then
                    CN.PrintLine("Restored: " .. row.name)
                    restored = restored + 1
                end
            end
        end

        if restored == 0 then
            Print("Nothing hidden matches: " .. args)
            Print("Run |cffffc74f/cn hidden|r to see the list.")
        end
    end,
}

------------------------------------------------------------
-- MODES
------------------------------------------------------------

-- Applying a mode is two existing operations performed together, plus a
-- record of what was on before so it can be undone.
function Filters.ApplyMode(name)
    local mode = CN.modes[name]

    if not mode then
        return false, "No such mode."
    end

    local settings = CN.Settings()

    -- Remember what to go back to. One level deep on purpose: an undo stack
    -- for a display preference is a feature nobody asked for.
    --
    -- BUT ONLY IF THERE IS NOT ALREADY A MODE ON.
    --
    -- This captured unconditionally, so switching from one focus straight to
    -- another overwrote the player's real settings with the FIRST focus's
    -- settings. `/cn mode leveling`, then `/cn mode collecting`, then
    -- `/cn mode off` left you in the levelling filter -- thirteen types
    -- hidden -- while printing "Previous filters and weighting restored" and
    -- recording no active mode. There was then no single command that got you
    -- back.
    --
    -- One level deep means one level: the state before the first focus, kept
    -- until a focus is actually cleared.
    if not settings.mode then
        settings.modePrevious = {
            profile = settings.priorityMode,
            hidden  = {},
        }

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            if not Filters.IsTypeEnabled(objectiveType) then
                table.insert(settings.modePrevious.hidden, objectiveType)
            end
        end
    end

    settings.priorityMode = mode.profile or "balanced"

    Filters.EnableAllTypes()

    if mode.show then
        local wanted = {}

        for _, objectiveType in ipairs(mode.show) do
            wanted[objectiveType] = true
        end

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            if not wanted[objectiveType] then
                Filters.SetTypeEnabled(objectiveType, false)
            end
        end
    end

    settings.mode = name

    CN.InvalidateCandidates()

    return true, mode
end

function Filters.CurrentMode()
    local settings = CN.Settings()

    return settings and settings.mode, settings and CN.modes[settings.mode]
end

function Filters.ClearMode()
    local settings = CN.Settings()

    local previous = settings.modePrevious

    -- NOTHING TO CLEAR MEANS NOTHING TO CHANGE.
    --
    -- This called EnableAllTypes unconditionally and only then looked for
    -- something to restore -- so `/cn mode off` with no focus active unhid
    -- everything the player had hidden by hand with `/cn show`, and then
    -- printed "Previous filters and weighting restored". Hidden types live in
    -- SavedVariables, so the loss was permanent.
    --
    -- The suite only ever called this after ApplyMode, which is the one path
    -- where there is something to restore.
    if not previous and not settings.mode then
        return false
    end

    Filters.EnableAllTypes()

    if previous then
        settings.priorityMode = previous.profile or "balanced"

        for _, objectiveType in ipairs(previous.hidden or {}) do
            Filters.SetTypeEnabled(objectiveType, false)
        end
    end

    settings.mode         = nil
    settings.modePrevious = nil

    CN.InvalidateCandidates()

    return true
end

CN:RegisterCommand{
    -- `types` promoted. "Show" sounds like "show me things" and means the
    -- objective-type filter; the alias was already the accurate word. The old
    -- name stays, because it is in the docs and in people's macros.
    name    = "types",
    aliases = { "show" },
    args    = "[type, only <type>, or all]",
    order   = 17,
    help    = "Choose which kinds of objective appear in recommendations.",
    handler = function(args)
        args = CN.Trim(args or "")

        local lowered = string.lower(args)

        if lowered == "all" then
            local restored = Filters.EnableAllTypes()

            Print("Showing every type again"
                .. (restored > 0 and (" (" .. restored .. " restored)") or "") .. ".")

        elseif lowered:match("^only%s+") then
            local wanted = Filters.ResolveType(lowered:gsub("^only%s+", ""))

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffc74f/cn show|r lists them.")
                return
            end

            Filters.OnlyType(wanted)

            Print("Showing only " .. Filters.TypeLabel(wanted) .. ".")

        elseif args ~= "" then
            local wanted = Filters.ResolveType(args)

            if not wanted then
                Print("Not a type: " .. args)
                Print("|cffffc74f/cn show|r lists them.")
                return
            end

            local nowEnabled = Filters.ToggleType(wanted)

            Print(Filters.TypeLabel(wanted) .. ": " .. CN.YesNo(nowEnabled))
        end

        local hiddenCount = Filters.HiddenTypeCount()

        Print("Recommendation types"
            .. (hiddenCount > 0 and (" |cffffc74f" .. hiddenCount .. " hidden|r") or ""))

        for _, objectiveType in ipairs(Filters.TypeOrder()) do
            local enabled = Filters.IsTypeEnabled(objectiveType)

            CN.PrintLine("  " .. CN.YesNo(enabled) .. " " .. Filters.TypeLabel(objectiveType)
                .. " |cff8a8f96" .. string.lower(objectiveType) .. "|r")
        end

        Print("|cff8a8f96/cn show pets|r toggles one, |cff8a8f96/cn show only quests|r "
            .. "narrows to one, |cff8a8f96/cn show all|r restores everything.")

        if hiddenCount > 0 then
            Print("|cff8a8f96Hidden types still appear in /cn breakdown and the "
                .. "Collections tab; this only filters recommendations.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "percharacter",
    aliases = { "perchar" },
    args    = "[setting]",
    order   = 18,
    help    = "Make a setting apply to this character only.",
    handler = function(args)
        args = CN.Trim(args or "")

        local settings = CN.Settings()

        if args ~= "" then
            -- MATCHED WITHOUT CASE, BECAUSE THE KEYS ARE camelCase.
            --
            -- This lowercased the argument and then looked it up in a table
            -- keyed `priorityMode`, `autoWaypoint`, `mapPins` -- so those
            -- three could never be set by any input, and the command rejected
            -- the exact spelling its own help line prints. Three of the six
            -- overridable settings were unreachable, including the one the
            -- feature was built for: a levelling alt wanting a different
            -- priority mode from a max-level main.
            local key

            for name in pairs(CN.characterOverridable) do
                if string.lower(name) == string.lower(args) then
                    key = name
                    break
                end
            end

            if not key then
                Print("That setting cannot be set per character: " .. args)

                local names = {}

                for name in pairs(CN.characterOverridable) do
                    table.insert(names, name)
                end

                table.sort(names)

                Print("|cff8a8f96Overridable: " .. table.concat(names, ", ") .. "|r")
                return
            end

            args = key

            if CN.IsOverridden(args) then
                CN.ClearOverride(args)

                Print(args .. " now follows the account setting again ("
                    .. tostring(settings[args]) .. ").")
            else
                -- Seed the override with whatever this character sees now, so
                -- taking control never changes the current behaviour.
                local ok, message = CN.SetOverride(args, settings[args])

                if not ok then
                    Print(message)
                    return
                end

                Print(args .. " is now set for this character only ("
                    .. tostring(settings[args]) .. ").")
            end
        end

        Print("Settings for " .. tostring(CN.characterKey or "this character") .. ":")

        -- EVERY OVERRIDABLE SETTING, NOT A HAND-COPIED FOUR OF THEM.
        --
        -- `CN.characterOverridable` also carries `mapPins` and `follow`, and
        -- the rejection branch above already enumerates the whole table -- so
        -- overriding `mapPins` was accepted and then never listed, and the
        -- status view gave no sign it existed.
        local overridable = {}

        for key in pairs(CN.characterOverridable or {}) do
            table.insert(overridable, key)
        end

        table.sort(overridable)

        for _, key in ipairs(overridable) do
            local overridden = CN.IsOverridden(key)

            CN.PrintLine("  " .. key .. " = " .. tostring(settings[key])
                .. (overridden
                    and " |cffffc74fthis character only|r"
                    or " |cff8a8f96account-wide|r"))
        end

        Print("|cff8a8f96/cn perchar priorityMode|r toggles whether a setting "
            .. "is shared or per character.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Vendors.lua'] = @'
-- Modules/Vendors.lua
-- Completion Navigator :: who sells what, and where they stand.
--
-- This is the module the flagship example in the design needs:
--
--   Recipe X is sold by Vendor A. Vendor A is in <zone> at <coords>.
--   The recipe requires Revered with Faction B. This character is Honored.
--   Another character is already Revered and has the profession.
--   -> Switch to that character and buy it.
--
-- Every other piece of that already exists. The missing link was that
-- nothing knew where anything is sold.
--
-- Vendor inventories are only readable while the merchant window is open --
-- the same client restriction as trade skill recipes. So this records every
-- vendor you talk to, permanently and account-wide, and the database grows
-- as you play rather than shipping stale.

local ADDON_NAME, CN = ...

local Vendors = CN:RegisterModule("Vendors")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("vendors")
end

-- Reverse index: itemID -> { npcID, npcID, ... }. Rebuilt from the vendor
-- store rather than persisted, so it can never drift out of sync with it.
local itemIndex = nil

Vendors.Store = Store

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

function Vendors.CaptureOpenMerchant()
    local npcID, npcName = Blizzard.GetInteractingNPC()

    if not npcID then
        return false, 0
    end

    local items = Blizzard.GetMerchantItems()

    if #items == 0 then
        return false, 0
    end

    local store  = Store()
    local record = store[npcID] or { npcID = npcID, firstSeen = time() }

    record.name     = npcName or record.name
    record.lastSeen = time()

    local mapID, x, y = CN.GetPlayerPosition()

    -- Keep the first location seen; vendors do not move, and later readings
    -- are just wherever you happened to be standing when you opened the
    -- window a second time.
    if mapID and x and y and not record.mapID then
        record.mapID = mapID
        record.x     = math.floor(x * 10000 + 0.5) / 10000
        record.y     = math.floor(y * 10000 + 0.5) / 10000

        -- `zone` IS NOT STORED. 0.63.0.
        --
        -- The map id is right there and the client derives the name from it
        -- instantly, in the language the player is reading. Stored, it froze:
        -- a player who changed client language, or a zone Blizzard renamed,
        -- kept the old name in every tooltip until they happened to reopen
        -- that merchant.
        --
        -- Third copy of the rule migration 7 applied to `questHarvest` and
        -- 0.62.0 applied to rares. Derived at the one place that builds
        -- seller rows, below.
    end

    -- WHAT NOT TO WRITE TO DISK.
    --
    -- This used to store every item's NAME alongside its ID. The client
    -- already knows every item name and hands it back from its own cache in
    -- microseconds; storing them again made this the largest thing the addon
    -- wrote, at roughly twenty-four kilobytes per vendor. The whole
    -- SavedVariables file is rewritten on every logout and re-parsed on every
    -- login, so that is a cost paid twice per session for data the client was
    -- always going to give us for free.
    --
    -- The rule this establishes, and the reason it is worth writing down:
    -- persist only what the client CANNOT tell us. Names, collected states
    -- and completion flags are all re-derivable instantly. Cross-character
    -- knowledge, observations gathered over time and the player's own choices
    -- are not, and those are what this database is actually for.
    record.items = {}

    -- A NUMBER, NOT A TABLE.
    --
    -- Each item used to get a table of its own to hold two fields. A table
    -- per item costs far more in a saved-variables file than the value it
    -- carries, and a large vendor sells hundreds of items. Prices are stored
    -- directly; the handful bought with an extended cost -- tokens, currency
    -- -- are listed separately, because they are the exception.
    --
    -- Price is kept at all because the client only reports it while the
    -- merchant window is open, so unlike the item's name it genuinely cannot
    -- be recovered later.
    record.extendedCost = nil

    for _, item in ipairs(items) do
        if item.itemID then
            record.items[item.itemID] = item.price or 0

            if item.extendedCost then
                record.extendedCost = record.extendedCost or {}
                record.extendedCost[item.itemID] = true
            end
        end
    end

    record.itemCount = CN.CountKeys(record.items)

    store[npcID] = record

    -- The reverse index is now stale.
    Vendors.ForgetItemIndex()

    CN.MarkScanned("vendors")

    return true, record.itemCount
end

------------------------------------------------------------
-- LOOKUP
------------------------------------------------------------

local function BuildItemIndex()
    local index = {}

    for npcID, record in pairs(Store()) do
        for itemID in pairs(record.items or {}) do
            index[itemID] = index[itemID] or {}
            table.insert(index[itemID], npcID)
        end
    end

    itemIndex = index

    return index
end

-- Published, because the recipe provider wants the same set: the items some
-- known vendor actually sells. Built on demand and held until the vendor
-- store changes, exactly as `FirstLocatedSeller` already relied on.
function Vendors.ItemIndex()
    return itemIndex or BuildItemIndex()
end

-- The one writer of the vendor store outside this file is a test, and a
-- reverse index nothing can invalidate is a cache that lies. Published for
-- the same reason `Sets.Forget` is.
function Vendors.ForgetItemIndex()
    itemIndex = nil
end

-- The candidate provider asks this question thousands of times per rebuild,
-- once per known recipe, and almost always gets no answer. WhoSells allocates
-- a result array every time it is called; this does not allocate at all until
-- there is something to return.
-- A SELLER ROW, WITH ITS ZONE DERIVED. 0.65.0.
--
-- `FirstLocatedSeller` handed back the raw store record, and migration 16
-- dropped `zone` from those rows because the map id derives it. `WhoSells`
-- was given the live derivation and the three consumers of THIS function were
-- not -- so a recommended recipe read "sold by Zen'shiri" with the zone line
-- silently gone, and the objective's own `zone` field was nil.
--
-- One shape for a seller, built in one place.
function Vendors.SellerFrom(record, npcID)
    if type(record) ~= "table" then
        return nil
    end

    return {
        npcID = npcID,
        name  = record.name,
        zone  = record.mapID and CN.Blizzard.GetMapName(record.mapID)
            or record.zone,
        mapID = record.mapID,
        x     = record.x,
        y     = record.y,
    }
end

function Vendors.FirstLocatedSeller(itemID)
    if not itemID then
        return nil
    end

    local index = itemIndex or BuildItemIndex()

    local npcIDs = index[itemID]

    if not npcIDs then
        return nil
    end

    local store = Store()

    for _, npcID in ipairs(npcIDs) do
        local record = store[npcID]

        if record and record.mapID and record.x and record.y then
            return Vendors.SellerFrom(record, npcID), npcID
        end
    end

    return nil
end

-- What a vendor charges for an item, in the shape callers expect, whichever
-- shape the store happens to be in. Old databases keep working until the
-- next merchant visit rewrites the row.
function Vendors.PriceOf(record, itemID)
    local stored = record and record.items and record.items[itemID]

    if stored == nil then
        return nil
    end

    if type(stored) == "table" then
        return stored.price, stored.extendedCost and true or false
    end

    return stored, (record.extendedCost and record.extendedCost[itemID]) or false
end

function Vendors.WhoSells(itemID)
    if not itemID then
        return {}
    end

    local index = itemIndex or BuildItemIndex()

    local sellers = {}

    for _, npcID in ipairs(index[itemID] or {}) do
        local record = Store()[npcID]

        if record then
            -- Through the one builder, so this and `FirstLocatedSeller`
            -- cannot describe a seller differently again. 0.65.0.
            local seller = Vendors.SellerFrom(record, npcID)

            seller.price = Vendors.PriceOf(record, itemID)

            table.insert(sellers, seller)
        end
    end

    return sellers
end

-- Finds an item by name across every recorded vendor. This is what makes
-- "who sells Flask of Testing" work without knowing an item ID.
--
-- RETURNS THE NAME AS WELL, because both callers print a headline. 0.66.0.
-- This function already resolved the name -- it holds it in `bestName` to
-- pick the shortest match -- and then threw it away, so `/cn sells Traveler's
-- Tundra Mount` answered "Item 44554 is sold by:": the addon reciting the
-- number it had just looked up from the words the player typed.
function Vendors.FindItem(text)
    if not text or text == "" then
        return nil, {}, nil
    end

    local itemID = CN.ToID(text)

    if itemID then
        local named = Blizzard.GetItemName(itemID)

        return itemID, Vendors.WhoSells(itemID),
               (named ~= "" and named) or nil
    end

    local needle  = string.lower(text)
    local matches = {}

    for npcID, record in pairs(Store()) do
        for id in pairs(record.items or {}) do
            -- Resolved from the client's item cache rather than from a copy
            -- of it kept on disk. Unknown names are skipped rather than
            -- guessed; the client fills its cache as items are seen.
            local name = Blizzard.GetItemName(id)

            if name and string.find(string.lower(name), needle, 1, true) then
                matches[id] = name
            end
        end
    end

    local bestID, bestName

    for id, name in pairs(matches) do
        if not bestName or #name < #bestName then
            bestID, bestName = id, name
        end
    end

    if not bestID then
        return nil, {}, nil
    end

    return bestID, Vendors.WhoSells(bestID), bestName
end

function Vendors.Summary()
    local counts = { vendors = 0, items = 0, located = 0 }

    local uniqueItems = {}

    for _, record in pairs(Store()) do
        counts.vendors = counts.vendors + 1

        if record.x and record.y then
            counts.located = counts.located + 1
        end

        for itemID in pairs(record.items or {}) do
            uniqueItems[itemID] = true
        end
    end

    counts.items = CN.CountKeys(uniqueItems)

    return counts
end

------------------------------------------------------------
-- RECIPE LINKING
------------------------------------------------------------

-- The payoff: a recipe this character does not know, sold by a vendor whose
-- location is recorded, becomes an objective with real coordinates.
CN.RegisterCandidateProvider("Vendors", function()
    local professions = CN:GetModule("Professions")

    if not professions then
        return {}
    end

    local known = professions.CharacterRecipes() or {}
    local names = professions.RecipeNames()

    local playerMap = select(1, CN.GetPlayerPosition())

    -- WALK WHAT CAN PRODUCE A ROW, NOT WHAT CANNOT. 0.61.0.
    --
    -- This walked `RecipeNames` -- every recipe the addon has ever seen a
    -- name for, 2,503 of them on an established account -- and asked
    -- `FirstLocatedSeller` about each. The answer is nil for all but a
    -- handful, because a recipe only produces a row if some vendor in the
    -- player's own captured vendor data sells it. Measured: 2,503 index
    -- lookups per rebuild to emit one candidate.
    --
    -- The item index is the set of items a KNOWN vendor sells, which is the
    -- necessary condition. It is built from the vendor store either way --
    -- `FirstLocatedSeller` builds it on its first call -- so iterating it
    -- costs nothing extra and skips the 2,400 recipes that could never have
    -- qualified.
    --
    -- The name is still required, so the check moves inside rather than
    -- disappearing: a recipe with a seller and no name has nothing to put on
    -- a row.
    local sellable = Vendors.ItemIndex()

    -- ONE LOOKUP PER ITEM. 0.72.0. See the note in `Modules/Toys.lua`: the
    -- same duplication, in the same shape, missed by the same fix.
    local sellers = {}

    local function SellerFor(itemID)
        local held = sellers[itemID]

        if held == nil then
            held = Vendors.FirstLocatedSeller(itemID) or false
            sellers[itemID] = held
        end

        return held or nil
    end

    -- THE JOIN IS BY NAME, BECAUSE THE TWO SIDES ARE DIFFERENT ID SPACES.
    -- 0.81.0.
    --
    -- This provider indexed `known` and `names` -- both keyed by TRADE-SKILL
    -- RECIPE ID, written by `Professions.CaptureOpenProfession` from
    -- `C_TradeSkillUI.GetAllRecipeIDs` -- with a MERCHANT ITEM ID from the
    -- vendor store. Two unrelated number spaces, one lookup.
    --
    -- 0.80.0 removed exactly this collision from `Professions.RecipeForItem`
    -- and did not come looking for its siblings, which is rule 30 in this
    -- project's backlog and the shape it keeps finding. `Filters.lua` names
    -- both spaces in the same sentence, three files over.
    --
    -- The consequence was worse than a wrong name: the provider produced a
    -- row ONLY when a vendor's item id happened to equal a captured recipe
    -- id. Every genuine vendor-sold recipe was invisible -- the whole point
    -- of this provider -- and each accidental collision was a ranked row
    -- named after an unrelated recipe, with `/cn go` coordinates to a vendor
    -- selling something else.
    --
    -- Memoised for the same reason `SellerFor` is: `evaluate` and `build`
    -- both ask, for every item a known vendor sells.
    local recipeOf = {}

    local function RecipeFor(itemID)
        local held = recipeOf[itemID]

        if held == nil then
            held = professions.RecipeForItem(
                CN.Blizzard.GetItemName and CN.Blizzard.GetItemName(itemID))
                or false

            recipeOf[itemID] = held
        end

        return held or nil
    end

    local candidates, considered, dropped = CN.CollectBounded(sellable, nil,
        function(itemID)
            local recipeID = RecipeFor(itemID)

            -- The recipe must exist, must have a name, and must not already
            -- be known by this character.
            if not recipeID or known[recipeID] or not names[recipeID] then
                return nil
            end

            -- HIDDEN BY THE ID THE ROW WILL CARRY. 0.82.0. See the note on
            -- the objective's `id` below: 0.81.0 fixed the join and left the
            -- identity in the item-id space, so a hide written here could
            -- not be read by the eligibility checker.
            if CN.IsIgnored(CN.objectiveTypes.RECIPE, recipeID)
                or CN.IsDeferred(CN.objectiveTypes.RECIPE, recipeID) then
                return nil
            end

            local seller = SellerFor(itemID)

            if not seller then
                return nil
            end

            -- A recipe you can walk to in this zone beats one across the
            -- continent, and that is the only distinction worth ranking here.
            return (seller.mapID == playerMap) and 3 or 2
        end,
        -- THE SECOND ARGUMENT IS THE SOURCE'S VALUE, AND THE SOURCE CHANGED.
        --
        -- `CN.CollectBounded` calls `build(id, source[id], value)`. While the
        -- source was `RecipeNames` that second argument was the name; now the
        -- source is the item index, it is the ARRAY OF NPC IDS that sell the
        -- item. Assigning it to `name` did not throw -- every reader wraps the
        -- name in `tostring` -- it rendered `table: 0x...` on the recommended
        -- row, in the HUD, on the map pin and in the data-broker feed.
        --
        -- A defect that shows a table address to the player and passes every
        -- test, because nothing asserts what a recipe row is CALLED. The name
        -- comes from `names`, which `evaluate` above has already required to
        -- be present.
        function(itemID)
            local seller = SellerFor(itemID)

            if not seller then
                return nil
            end

            local recipeID = RecipeFor(itemID)

            if not recipeID then
                return nil
            end

            local recipeName = names[recipeID]

            local reasons = { "sold by " .. tostring(seller.name) }

            if seller.zone then
                table.insert(reasons, "in " .. seller.zone)
            end

            -- ONE CALL, BOTH ANSWERS. 0.71.0.
            --
            -- 0.70.0 added the confidence flag here with a second
            -- `CN.TravelCost` call inside a `select(2, ...)`, and the travel
            -- model deliberately does not cache a refusal -- so for any
            -- seller it could not route, both calls ran a full estimate:
            -- four client conversions and a scan of the flight network,
            -- twice, per row, in the two highest-volume located providers.
            --
            -- Worse than the cost: the two calls are independent, so a
            -- coordinate conversion that failed between them produced a row
            -- with a real measured journey and no flag saying so -- silently
            -- losing its distance line and its deadline guard.
            local travel, costed = CN.TravelCost(seller.mapID, seller.x, seller.y)

            return CN.NewObjective({
                -- THE ROW IS THE RECIPE, NOT THE ITEM. 0.82.0.
                --
                -- 0.81.0 fixed the JOIN in this provider -- a merchant item
                -- id was being indexed into two trade-skill-keyed tables --
                -- and stopped one function short: the objective it built
                -- still carried the ITEM id as its identity.
                --
                -- `Professions.lua` registers the RECIPE eligibility checker,
                -- and it indexes `character.recipes`, written from
                -- `C_TradeSkillUI.GetAllRecipeIDs`. So `CN.Explain` on one of
                -- these rows asked a recipe-id table an item-id question --
                -- the identical collision, one call later. On a number that
                -- happened to collide it answered COMPLETED and the arrow was
                -- silently retired from a recipe the player had not bought,
                -- naming an unrelated one as the reason.
                --
                -- The merchant item is kept beside it, because that is what
                -- the player buys and what the vendor store is keyed by.
                id              = recipeID,
                itemID          = itemID,
                type            = CN.objectiveTypes.RECIPE,
                name            = recipeName,
                mapID           = seller.mapID,
                x               = seller.x,
                y               = seller.y,
                completionValue = 2,
                -- COSTED, NOT GUESSED. This charged a flat 25 for anything
                -- outside the current zone while holding the seller's exact
                -- coordinates -- so a vendor ninety seconds away in the next
                -- zone was charged twenty-five where a quest at the identical
                -- spot was charged three. A systematic twenty-two point
                -- penalty against exactly the collection types this file
                -- exists to surface.
                travelCost      = travel,
                travelCosted    = costed or nil,
                reasons         = reasons,
            })
        end)

    CN.providerTruncation["Vendors"] = { considered = considered, dropped = dropped }

    return candidates
end, { events = { "MERCHANT_SHOW", "TRADE_SKILL_LIST_UPDATE", "ZONE_CHANGED_NEW_AREA" }, cooldown = 5 })

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("MERCHANT_SHOW", function()
    local captured, count = Vendors.CaptureOpenMerchant()

    if captured then
        DebugPrint("Recorded vendor with " .. count .. " items.")
    end
end)

-- DEBOUNCED, BECAUSE THIS FIRES ON EVERY PURCHASE. 0.88.0.
--
-- `MERCHANT_UPDATE` fires again whenever a merchant's stock changes -- every
-- buy of a limited-quantity item, and repeatedly while the frame is open --
-- and each capture re-reads EVERY item on the merchant at two or three
-- client calls apiece, rebuilds the row, discards the reverse index over the
-- whole account vendor store, and calls `CN.MarkScanned`, which invalidates
-- this provider and bumps the counter guarding three tabs' memoised
-- summaries. Twenty purchases from a big vendor was twenty of all that.
--
-- Every other chatty handler in the addon is throttled and says so:
-- currencies at sixty seconds, rares at one, the breakdown at five,
-- exploration at two. This was the one that was not swept.
Vendors.recaptureSeconds = 2

CN:RegisterEvent("MERCHANT_UPDATE", function()
    CN.Debounce("Vendors.merchant", Vendors.recaptureSeconds,
        Vendors.CaptureOpenMerchant)
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vendors",
    order   = 79,
    help    = "Summarize recorded vendors.",
    handler = function()
        local counts = Vendors.Summary()

        if counts.vendors == 0 then
            Print("No vendors recorded yet.")
            Print("|cff8a8f96Open a merchant window and the addon records "
                .. "what they sell and where they stand.|r")
            return
        end

        Print("Vendors recorded: " .. counts.vendors
            .. " (" .. counts.located .. " with coordinates)")
        Print("Distinct items seen: " .. counts.items)
    end,
}

CN:RegisterCommand{
    name    = "sells",
    aliases = { "whosells" },
    args    = "<itemID or name>",
    order   = 80,
    help    = "Find which recorded vendor sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn sells <itemID or name>")
            return
        end

        local itemID, sellers, itemName = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            Print("|cff8a8f96Only vendors you have opened are known.|r")
            return
        end

        Print(tostring(itemName or ("Item " .. itemID))
            .. " |cff8a8f96(" .. itemID .. ")|r is sold by:")

        for index, seller in ipairs(sellers) do
            CN.PrintLine("  " .. index .. ". " .. tostring(seller.name)
                .. (seller.zone and (" |cff8a8f96in " .. seller.zone .. "|r") or "")
                .. (seller.x and string.format(" |cff8a8f96%.1f, %.1f|r",
                    seller.x * 100, seller.y * 100) or ""))
        end

        Print("|cffffc74f/cn tovendor " .. itemID .. "|r to set a waypoint.")
    end,
}

CN:RegisterCommand{
    name    = "tovendor",
    args    = "<itemID or name>",
    order   = 81,
    help    = "Navigate to a vendor that sells something.",
    handler = function(args)
        if args == "" then
            Print("Usage: /cn tovendor <itemID or name>")
            return
        end

        local itemID, sellers, itemName = Vendors.FindItem(args)

        if not itemID or #sellers == 0 then
            Print("Nothing recorded matches: " .. args)
            return
        end

        for _, seller in ipairs(sellers) do
            if seller.mapID and seller.x and seller.y then
                CN.NavigateToObjective({
                    id    = seller.npcID,
                    type  = CN.objectiveTypes.VENDOR,
                    name  = seller.name
                        .. (itemName and (" (" .. itemName .. ")") or ""),
                    mapID = seller.mapID,
                    x     = seller.x,
                    y     = seller.y,
                })

                return
            end
        end

        Print("No recorded seller has coordinates yet.")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Tooltips.lua'] = @'
-- Modules/Tooltips.lua
-- Completion Navigator :: what the addon knows, shown where you are looking.
--
-- Everything in this addon already knows whether you own a toy, which of your
-- characters knows a recipe, and which vendor sells an item. Until now you had
-- to go and ask. A tooltip is where that question actually gets asked -- while
-- hovering the thing in a vendor list, a loot window or the auction house.
--
-- The line-building functions are deliberately separate from the hooks: the
-- lines are pure data, so they can be tested offline, and the hooks are a thin
-- adapter over whichever tooltip API the client is running.

local ADDON_NAME, CN = ...

local Tooltips = CN:RegisterModule("Tooltips")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

-- THE SAME PALETTE AS EVERYTHING ELSE, IN THE SHAPE A TOOLTIP WANTS.
--
-- These were four hand-written triples, of which exactly one matched the hex
-- codes the rest of the addon used for the same four meanings. A player
-- hovering an item saw a slightly different green from the one in the window
-- for "collected", and nothing in the code said which was right.
local GREEN  = CN.RGB.GOOD
local RED    = CN.RGB.BAD
local YELLOW = CN.RGB.WARN
local GREY   = CN.RGB.MUTED

local HEADER = "Completion Navigator"

local function Enabled()
    local settings = CN.Settings()

    return settings and settings.tooltips ~= false
end

Tooltips.Enabled = Enabled

------------------------------------------------------------
-- LINE BUILDERS
------------------------------------------------------------

local function Add(lines, text, color)
    table.insert(lines, { text = text, color = color or GREY })
end

local function CollectedLine(lines, label, collected)
    if collected then
        Add(lines, label .. ": collected", GREEN)
    else
        Add(lines, label .. ": not collected", RED)
    end
end

-- Toys are keyed by item ID in both the toy box and our own store, so this is
-- the one collection lookup that needs no translation.
local function ToyLines(lines, itemID)
    local record = CN.Account("toys")[itemID]

    if record then
        CollectedLine(lines, "Toy", record.collected)
        return true
    end

    -- No scan yet, but the client can still answer for this one item.
    if PlayerHasToy and C_ToyBox and C_ToyBox.GetToyInfo then
        local _, name = C_ToyBox.GetToyInfo(itemID)

        if name then
            CollectedLine(lines, "Toy", PlayerHasToy(itemID))
            return true
        end
    end

    return false
end

local function MountLines(lines, itemID)
    local mountID = Blizzard.GetMountFromItem(itemID)

    if not mountID then
        return false
    end

    local record = CN.Account("mounts")[mountID]

    if record then
        CollectedLine(lines, "Mount", record.collected)

        if record.isFactionSpecific and record.faction then
            Add(lines, "Faction-locked", YELLOW)
        end

        return true
    end

    local mount = Blizzard.GetMountByID(mountID)

    if mount then
        CollectedLine(lines, "Mount", mount.isCollected)
        return true
    end

    return false
end

local function PetLines(lines, itemID)
    local speciesID = Blizzard.GetPetSpeciesFromItem(itemID)

    if not speciesID then
        return false
    end

    local record = CN.Account("pets")[speciesID]

    local count, limit

    if record then
        count, limit = record.count, record.limit
    else
        count, limit = Blizzard.GetPetCollectedCount(speciesID)
    end

    count = count or 0

    -- NO FABRICATED DENOMINATOR.
    --
    -- `limit or 3` invented the cap when neither the store nor the client
    -- supplied it, and then printed "collected 2 of 3" as though the 3 had
    -- been read from somewhere. Three is the right number today; it is still
    -- a made-up total in a module that refuses them everywhere else.
    if count > 0 and limit and limit > 0 then
        Add(lines, "Battle pet: collected " .. count .. " of " .. limit, GREEN)
    elseif count > 0 then
        Add(lines, "Battle pet: collected " .. count, GREEN)
    else
        Add(lines, "Battle pet: not collected", RED)
    end

    return true
end

local function AppearanceLines(lines, itemID)
    local has = Blizzard.HasTransmogByItem(itemID)

    if has == nil then
        return false
    end

    if has then
        Add(lines, "Appearance: already known", GREEN)
    else
        Add(lines, "Appearance: not yet known", RED)
    end

    return true
end

-- Recipes are the messy case. The trade skill API keys recipes by recipe ID
-- while a vendor sells an item ID, and the two are not the same number --
-- which is exactly why the resolver takes a NAME and nothing else. There is
-- no exact id path, because there is no id the two spaces share; the answer
-- is a name match and is labelled as one rather than dressed up as certainty.
local function RecipeLines(lines, itemName)
    local professions = CN:GetModule("Professions")

    if not professions then
        return false
    end

    local mine = professions.CharacterRecipes() or {}

    -- ONE INDEXED LOOKUP, NOT A SCAN.
    --
    -- This used to walk every recipe name the addon knew -- lowercasing each
    -- one and searching it -- on every single item tooltip. At retail scale
    -- that is twenty-five hundred iterations and five thousand string
    -- allocations to answer a question about one item, measured at 0.54ms:
    -- three per cent of a frame, per mouseover, and a bag sweep fires dozens
    -- a second.
    -- BY NAME, WHICH IS THE ONLY WAY. 0.80.0. The id branch this used to
    -- take first indexed a recipe-id table with an item id; see the note in
    -- `Professions.RecipeForItem`. Every match is a name match now, so the
    -- caveat below is unconditional rather than a flag the resolver returns.
    local recipeID = professions.RecipeForItem(itemName)

    if not recipeID then
        return false
    end

    if mine[recipeID] then
        Add(lines, "Recipe: known by this character", GREEN)
    else
        Add(lines, "Recipe: not known by this character", RED)

        local holders = professions.WhoKnows(recipeID) or {}

        if #holders > 0 then
            Add(lines, "Known by: " .. table.concat(holders, ", "), YELLOW)
        end
    end

    Add(lines, "matched by name", GREY)

    return true
end

local function VendorLines(lines, itemID)
    local vendors = CN:GetModule("Vendors")

    if not vendors then
        return false
    end

    local sellers = vendors.WhoSells(itemID)

    if #sellers == 0 then
        return false
    end

    for index, seller in ipairs(sellers) do
        if index > 3 then
            Add(lines, "and " .. (#sellers - 3) .. " more recorded seller"
                .. CN.Pluralize((#sellers - 3), ""), GREY)
            break
        end

        local text = "Sold by " .. tostring(seller.name or seller.npcID)

        if seller.zone then
            text = text .. " in " .. seller.zone
        end

        if seller.x and seller.y then
            text = text .. string.format(" (%.1f, %.1f)", seller.x * 100, seller.y * 100)
        end

        Add(lines, text, YELLOW)
    end

    return true
end

-- The whole item block, as data. Returns an array of { text, color }.
function Tooltips.ItemLines(itemID, itemName)
    local lines = {}

    if not itemID or not CN.db then
        return lines
    end

    itemName = itemName or Blizzard.GetItemName(itemID)

    local collectible = false

    collectible = ToyLines(lines, itemID)         or collectible
    collectible = MountLines(lines, itemID)       or collectible
    collectible = PetLines(lines, itemID)         or collectible
    collectible = RecipeLines(lines, itemName)    or collectible

    -- Appearance state is noise on something that is not gear, so it is only
    -- consulted when nothing else claimed the item.
    if not collectible then
        AppearanceLines(lines, itemID)
    end

    VendorLines(lines, itemID)

    -- WHY IT MATTERS, not only that it is tracked (0.43.0).
    --
    -- Every line above answers "do I have this?". None of them answered the
    -- question a player actually hovers an item to ask, which is "should I
    -- care?" -- and the addon knows, because it has already ranked the thing
    -- and written down its reasons.
    --
    -- One line, the top reason only. A tooltip that grows a paragraph is a
    -- tooltip people turn off.
    if collectible then
        local goals = CN:GetModule("Goals")

        local mountID = Blizzard.GetMountFromItem(itemID)
        local speciesID = Blizzard.GetPetSpeciesFromItem(itemID)

        -- TOYS TOO, which hovered silently.
        --
        -- The "why you should care" line fired only for mounts and pets,
        -- because those are the two the client will resolve from an item id
        -- into a collection id. A toy IS its item id -- that is the key the
        -- addon's own store uses -- so it was one branch away the whole time.
        local isToy = CN.Account("toys")[itemID] ~= nil

        -- AN APPEARANCE IS NOT ADDRESSABLE BY ITEM ID. 0.80.0.
        --
        -- This branch was added beside the toy one on the assumption that an
        -- appearance "IS its item id" the same way. It is not, and nothing in
        -- this addon has ever keyed one that way: `Appearances.lua` emits
        -- APPEARANCE rows keyed by `categoryID` -- a slot, roughly 0 to 30 --
        -- and `Sets.lua` emits them keyed by the STRING "set:<id>", prefixed
        -- deliberately in 0.61.0 to keep those two id spaces apart.
        --
        -- So `CN.FindCandidate(APPEARANCE, itemID)` could never match, and
        -- `Goals.IsGoal(APPEARANCE, ...)` could never be true either --
        -- `Goals.types` has no appearance entry at all, so an APPEARANCE goal
        -- cannot be created by any command. The line has never once appeared
        -- for an appearance, and the cost was a full candidate walk on every
        -- gear mouseover to arrive at nil.
        --
        -- Restoring it means giving an appearance an id a tooltip can build.
        -- The appearance lines ABOVE this block, which read the client
        -- directly, are unaffected and still work.
        local goalType = (mountID and CN.objectiveTypes.MOUNT)
            or (speciesID and CN.objectiveTypes.PET)
            or (isToy and CN.objectiveTypes.TOY)
            or nil

        local goalID = mountID or speciesID or itemID

        if goals and goalType and goalID and goals.IsGoal
            and goals.IsGoal(goalType, goalID) then

            Add(lines, "You are chasing this.", CN.RGB.BRAND)
        else
            local candidate = CN.FindCandidate and goalType
                and CN.FindCandidate(goalType, goalID)

            local reason = candidate and CN.FirstReason(candidate)

            if reason then
                Add(lines, reason, GREY)
            end

            -- ONE MORE LINE, WHERE IT SAYS SOMETHING THE FIRST DID NOT.
            --
            -- 0.43.0 added the top reason, which answers "should I care?".
            -- The second question a player asks of a collectible is "where
            -- does it come from?", and the addon has known that since 0.41.0
            -- without ever putting it where the mouse already is.
            local instances = CN:GetModule("Instances")

            if instances and itemName then
                local ok, source = pcall(instances.DescribeSource, itemName)

                if ok and source then
                    Add(lines, "Drops from " .. source, GREY)
                end
            end
        end
    end

    return lines
end

-- Unit tooltips answer a narrower question: have I shopped here, and is this
-- creature one the addon is tracking as a rare.
function Tooltips.UnitLines(npcID)
    local lines = {}

    if not npcID or not CN.db then
        return lines
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local record = vendors.Store()[npcID]

        if record then
            Add(lines, "Recorded vendor: " .. (record.itemCount or 0) .. " items", YELLOW)

            if not record.mapID then
                Add(lines, "no coordinates recorded yet", GREY)
            end
        end
    end

    -- The rare database is keyed by vignette ID, not creature ID, so there is
    -- deliberately nothing to say here about rares. Adding a guess would be
    -- worse than the silence.

    return lines
end

------------------------------------------------------------
-- RENDERING
------------------------------------------------------------

function Tooltips.Render(tooltip, lines)
    if not tooltip or not tooltip.AddLine or #lines == 0 then
        return 0
    end

    tooltip:AddLine(" ")
    tooltip:AddLine(HEADER, CN.Rgb("BRAND"))

    for _, line in ipairs(lines) do
        tooltip:AddLine(line.text, line.color[1], line.color[2], line.color[3])
    end

    if tooltip.Show then
        tooltip:Show()
    end

    return #lines
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

-- Which tooltip API resolved, reported by /cn tooltips so a silent hook is
-- diagnosable rather than mysterious.
Tooltips.backend = "none"

local function OnItemTooltip(tooltip, itemID, itemName)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        Tooltips.Render(tooltip, Tooltips.ItemLines(itemID, itemName))
    end)

    if not ok then
        DebugPrint("Item tooltip failed: " .. tostring(err))
    end
end

local function OnUnitTooltip(tooltip, unit)
    if not Enabled() then
        return
    end

    local ok, err = pcall(function()
        local npcID = Blizzard.GetUnitNPCID(unit or "mouseover")

        Tooltips.Render(tooltip, Tooltips.UnitLines(npcID))
    end)

    if not ok then
        DebugPrint("Unit tooltip failed: " .. tostring(err))
    end
end

Tooltips.OnItemTooltip = OnItemTooltip
Tooltips.OnUnitTooltip = OnUnitTooltip

function Tooltips.Install()
    if Tooltips.installed then
        return Tooltips.backend
    end

    -- Modern retail: every tooltip is data-driven and post-processed. Post
    -- calls run after the tooltip is rebuilt, so lines are added once per
    -- render rather than accumulating.
    if TooltipDataProcessor
        and TooltipDataProcessor.AddTooltipPostCall
        and Enum and Enum.TooltipDataType then

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item,
            function(tooltip, data)
                local itemID, itemName

                if data then
                    itemID = data.id
                end

                if TooltipUtil and TooltipUtil.GetDisplayedItem then
                    local name, _, id = TooltipUtil.GetDisplayedItem(tooltip)

                    itemName = name
                    itemID   = itemID or id
                end

                OnItemTooltip(tooltip, itemID, itemName)
            end)

        TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Unit,
            function(tooltip, data)
                local unit

                if TooltipUtil and TooltipUtil.GetDisplayedUnit then
                    unit = select(2, TooltipUtil.GetDisplayedUnit(tooltip))
                end

                OnUnitTooltip(tooltip, unit)
            end)

        Tooltips.installed = true
        Tooltips.backend   = "TooltipDataProcessor"

        return Tooltips.backend
    end

    -- Older clients. Kept because the addon is expected to load on more than
    -- one flavour, and a missing hook here is silent otherwise.
    if GameTooltip and GameTooltip.HookScript then
        GameTooltip:HookScript("OnTooltipSetItem", function(self)
            local name, link = self:GetItem()

            local itemID = link and tonumber(link:match("item:(%d+)"))

            OnItemTooltip(self, itemID, name)
        end)

        GameTooltip:HookScript("OnTooltipSetUnit", function(self)
            local _, unit = self:GetUnit()

            OnUnitTooltip(self, unit)
        end)

        Tooltips.installed = true
        Tooltips.backend   = "OnTooltipSet"

        return Tooltips.backend
    end

    Tooltips.backend = "none"

    return Tooltips.backend
end

CN:OnLogin(function()
    Tooltips.Install()

    DebugPrint("Tooltip backend: " .. tostring(Tooltips.backend))
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "tooltips",
    args    = "[on or off]",
    order   = 82,
    help    = "Toggle addon lines on item and unit tooltips.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args))

        if args == "on" then
            settings.tooltips = true
        elseif args == "off" then
            settings.tooltips = false
        elseif args ~= "" then
            Print("Usage: /cn tooltips [on or off]")
            return
        else
            -- Default is on, so nil counts as enabled.
            settings.tooltips = (settings.tooltips == false)
        end

        Print("Tooltip lines: " .. CN.YesNo(settings.tooltips ~= false))
        Print("|cff8a8f96Backend: " .. tostring(Tooltips.backend) .. "|r")

        if Tooltips.backend == "none" then
            Print("|cff8a8f96No tooltip API resolved, so nothing will be added.|r")
        end
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Setup.lua'] = @'
-- Modules/Setup.lua
-- Completion Navigator :: the first five minutes.
--
-- Every recommendation this addon makes is only as good as what it has
-- scanned, and until now a new install had to discover eleven separate scan
-- commands to get there. Worse, it looked broken in the meantime: an empty
-- database and a confident "nothing actionable is known yet" read as a bug
-- rather than as a first run.
--
-- /cn setup runs every scan in order, one per frame, and then reports what
-- the client genuinely could not answer -- recipes and vendors, which are
-- readable only while their windows are open, and so can never be batched.

local ADDON_NAME, CN = ...

local Setup = CN:RegisterModule("Setup")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- STEPS
------------------------------------------------------------

-- Ordered so the cheap scans report first and the journal scans -- which
-- open and filter collection UIs -- come last.
-- A UNIT PER STEP, because the numbers are not the same quantity.
--
-- `Setup.Report` printed each scan's first return value and nothing else, and
-- three of them count something other than what the label says:
-- `Appearances.Scan` returns the number of slot CATEGORIES (about seventeen),
-- `Professions.Scan` the number of profession LINES (two to four), and the
-- rest return thousands of rows. So a player who had just told the addon to
-- read their transmog was shown "Appearances: 17" beside "Mounts: 1104" and
-- concluded it had found seventeen appearances.
Setup.steps = {
    { key = "reputations", label = "Reputations", module = "Reputations", fn = "Scan",     unit = "factions" },
    { key = "currencies",  label = "Currencies",  module = "Currencies",  fn = "Scan",     unit = "currencies" },
    { key = "titles",      label = "Titles",      module = "Titles",      fn = "Scan",     unit = "titles" },
    { key = "professions", label = "Professions", module = "Professions", fn = "Scan",     unit = "profession lines" },
    { key = "exploration", label = "Exploration", module = "Exploration", fn = "Scan",     unit = "zones" },
    -- LOREMASTER WAS MISSING FROM THIS LIST. 0.67.0.
    --
    -- Its store is per-character for `progress` and account-wide for
    -- everything else, and it scans on login only when the store is EMPTY --
    -- which after the first character it never is. So a new character had no
    -- `progress` row of its own for any zone and read whatever the last
    -- character to scan had recorded. Eleven collections were offered on the
    -- setup screen and the twelfth, which is the one with a per-character
    -- dimension, was not.
    { key = "loremaster",  label = "Loremaster",  module = "Loremaster",  fn = "Scan",     unit = "quest achievements", measured = true, retry = "scanlore", perCharacter = "HasScanned" },
    { key = "quests",      label = "Quests",      module = "Quests",      fn = "ScanKnown",unit = "quests checked" },
    { key = "achievements",label = "Achievements",module = "Achievements",fn = "Scan",     unit = "achievements", measured = true, measuredAt = 4, retry = "achievescan", perCharacter = "HasScanned" },
    { key = "toys",        label = "Toys",        module = "Toys",        fn = "Scan",     unit = "toys" },
    { key = "mounts",      label = "Mounts",      module = "Mounts",      fn = "Scan",     unit = "mounts" },
    { key = "pets",        label = "Battle pets", module = "Pets",        fn = "Scan",     unit = "species" },
    { key = "appearances", label = "Appearances", module = "Appearances", fn = "Scan",     unit = "slot categories" },
}

function Setup.RunStep(step)
    local module = CN:GetModule(step.module)

    if not module or type(module[step.fn]) ~= "function" then
        return false, "module not loaded"
    end

    local ok, first, second, third, fourth = pcall(module[step.fn])

    if not ok then
        return false, tostring(first)
    end

    -- A SCAN THAT MEASURED NOTHING DID NOT SUCCEED. 0.73.0.
    --
    -- `Loremaster.Scan` has returned `scanned, measured` since 0.72.0 --
    -- `scanned` being how many rows the walk REACHED and `measured` how many
    -- the client actually answered about. `/cn scanlore` was taught to check
    -- the second; this, the other caller, discarded it.
    --
    -- So `/cn setup` printed "Loremaster: 412 quest achievements" over a
    -- store that had recorded nothing, counted the step as a success, and
    -- stamped `completedAt` -- which silences the login reminder and makes
    -- `/cn setup check` report a clean bill. Setup is most often run in the
    -- first moments after logging in, which is exactly when the criteria API
    -- refuses.
    -- REPORTED AS NOT READY, NOT AS BROKEN. 0.74.0.
    --
    -- 0.73.0 returned this through the failure path, so `Setup.Report`
    -- printed it in the "bad" colour and followed it with "A failure is a
    -- defect, not a missing feature. /cn errors has the detail." Nothing was
    -- recorded in Errors, so that command was empty -- and this file's own
    -- note says setup is most often run in the first moments after logging
    -- in, which is exactly when the criteria API refuses. The common path was
    -- presented as a bug report the player could not act on.
    -- WHICH RETURN CARRIES "how many rows the client answered about".
    -- 0.86.0.
    --
    -- The guard above was written for `Loremaster.Scan`, which returns
    -- `scanned, measured`. 0.73.0 then gave `measured = true` to the
    -- Achievements step as well -- and `Achievements.Scan` returns
    -- `scanned, completed, nearlyDone, answered`, so the second value there
    -- is the COMPLETED count: four figures on any real account, and never
    -- zero. The not-ready branch could not fire for the one other step that
    -- asked for it.
    --
    -- Same consequence as the defect above, on the other scan: "/cn setup"
    -- run in the first seconds after login reported success over a store
    -- that recorded nothing, stamped `completedAt`, and left `/cn setup
    -- check` answering "Not scanned yet" -- the addon contradicting itself
    -- on its own onboarding screen, with nothing telling the player to
    -- try again.
    local measured = second

    if step.measuredAt == 3 then
        measured = third
    elseif step.measuredAt == 4 then
        measured = fourth
    end

    if step.measured and measured == 0 then
        return nil, "the game was not ready yet"
    end

    return true, first
end

------------------------------------------------------------
-- RUN
------------------------------------------------------------

Setup.running = false

-- Spreading the steps across frames matters: several of these walk the entire
-- pet journal or achievement tree, and doing all eleven inside one frame is a
-- visible stutter on a login that is already busy.
function Setup.Run(onComplete)
    if Setup.running then
        Print("Setup is already running.")
        return false
    end

    Setup.running = true

    local results = {}
    local index   = 0

    -- THE WHOLE BODY IS GUARDED, NOT JUST THE STEP.
    --
    -- `RunStep` was pcall'd and nothing else was -- and steps two onward run
    -- inside `C_Timer.After` callbacks, outside the slash command's own
    -- pcall. So a throw in the bookkeeping, in `Setup.Report`, or in
    -- `Setup.Outstanding` stopped the chain dead AND left `Setup.running`
    -- true, which makes `/cn setup` answer "Setup is already running." for
    -- the rest of the session with no way back short of a reload.
    local function step()
        local ran, err = pcall(function()
            index = index + 1

            local entry = Setup.steps[index]

            if not entry then
                Setup.running = false

                -- COMPLETION IS RECORDED ONLY IF SOMETHING COMPLETED.
                --
                -- This was stamped unconditionally, so a run in which every
                -- scan failed was remembered as a successful setup: the login
                -- reminder stopped, `Setup.HasRun()` went true forever, and
                -- `/cn setup check` answered "Everything the addon can read
                -- on its own is scanned."
                local failed, notReady = 0, 0

                for _, row in ipairs(results) do
                    if row.ok == nil then
                        notReady = notReady + 1
                    elseif not row.ok then
                        failed = failed + 1
                    end
                end

                -- AND A RUN THAT WAS NOT READY IS NOT A RUN THAT FINISHED.
                -- 0.74.0.
                --
                -- Stamping this silences the login reminder, so a setup that
                -- ran while the game was still warming up would have been the
                -- last one the player was ever prompted for.
                if failed + notReady < #results and notReady == 0 then
                    CN.Account("setup").completedAt = time()
                end

                Setup.Report(results)

                if onComplete then
                    pcall(onComplete, results)
                end

                return
            end

            local ok, value = Setup.RunStep(entry)

            table.insert(results, {
                label = entry.label,
                ok    = ok,
                value = ok and value or nil,
                error = (not ok) and value or nil,
            })

            if C_Timer and C_Timer.After then
                C_Timer.After(0, step)
            else
                step()
            end
        end)

        if not ran then
            Setup.running = false

            local errors = CN:GetModule("Errors")

            if errors and errors.Record then
                pcall(errors.Record, "Setup.Run", tostring(err))
            end

            Print("Setup stopped after " .. index .. " of "
                .. #Setup.steps .. " scans: " .. tostring(err))
            Print("|cff8a8f96/cn setup runs it again from the start.|r")
        end
    end

    Print("Running setup: " .. #Setup.steps .. " scans.")

    step()

    return true
end

-- THE HEADLINE FIRST, WHICH IS WHAT A HEADLINE IS.
--
-- This printed eleven continuations, THEN the "Setup complete" headline, then
-- two more headlines -- so the block read bottom-up and stamped the addon's
-- name three times in one answer.
function Setup.Report(results)
    local scanned, absent, broke, waiting = 0, 0, 0, 0

    local units = {}

    -- AND WHICH COMMAND RETRIES EACH ONE. 0.87.0. The not-ready sentence
    -- below named `/cn scanlore` for every step, because Loremaster was the
    -- only one that could reach it -- until 0.86.0 made the achievement scan
    -- reachable too, and sent the player to a command that cannot fix it.
    local retry = {}

    for _, step in ipairs(Setup.steps) do
        units[step.label] = step.unit
        retry[step.label] = step.retry
    end

    local lines = {}

    for _, result in ipairs(results) do
        if result.ok then
            scanned = scanned + 1

            local value = "done"

            if type(result.value) == "number" then
                value = CN.Comma(result.value)

                local unit = units[result.label]

                if unit then
                    value = value .. " " .. unit
                end
            end

            table.insert(lines, result.label .. ": " .. value)
        elseif result.ok == nil then
            -- A THIRD STATE: THE GAME WAS NOT READY. 0.74.0.
            --
            -- Neither a success nor a defect. The criteria API refuses for a
            -- window after logging in, which is when setup is usually run,
            -- and 0.73.0 rendered that through the failure branch -- red,
            -- with a pointer to an empty `/cn errors`. What the player needs
            -- is one sentence saying to try again in a moment.
            waiting = waiting + 1

            table.insert(lines, result.label .. ": "
                .. CN.Muted(tostring(result.error) .. CN.DASH
                    .. "try ") .. CN.Accent("/cn "
                        .. (retry[result.label] or "setup"))
                .. CN.Muted(" in a moment."))
        elseif result.error == "module not loaded" then
            -- "UNAVAILABLE" AND "IT THREW" ARE DIFFERENT STATEMENTS.
            --
            -- Every failure was reported with the word "unavailable", so a
            -- module that raised a Lua error was presented to the player as a
            -- subsystem this client does not have -- nothing to look into,
            -- nothing to report.
            absent = absent + 1

            table.insert(lines, result.label .. ": "
                .. CN.Muted("not available on this client"))
        else
            broke = broke + 1

            table.insert(lines, result.label .. ": "
                .. CN.Bad("failed: " .. tostring(result.error)))
        end
    end

    if broke > 0 then
        table.insert(lines, CN.Muted("A failure is a defect, not a missing "
            .. "feature. ") .. CN.Accent("/cn errors") .. CN.Muted(" has the "
            .. "detail."))
    end

    for _, line in ipairs(Setup.Outstanding()) do
        table.insert(lines, CN.Accent(line))
    end

    table.insert(lines, "Now try " .. CN.Accent("/cn next") .. ".")

    CN.PrintBlock("Setup complete: " .. scanned .. " scanned"
        .. (absent > 0 and (", " .. absent .. " unavailable") or "")
        .. (waiting > 0 and (", " .. waiting .. " not ready") or "")
        .. (broke > 0 and (", " .. broke .. " failed") or "") .. ".", lines)
end

------------------------------------------------------------
-- WHAT SETUP CANNOT DO
------------------------------------------------------------

-- Two subsystems are readable only while their window is open. Saying so is
-- the difference between "this addon does not track recipes" and "open your
-- profession window once".
function Setup.Outstanding()
    local lines = {}

    local professions = CN:GetModule("Professions")

    if professions and professions.AwaitingRecipeCapture then
        local awaiting = professions.AwaitingRecipeCapture()

        if awaiting and #awaiting > 0 then
            local names = {}

            for _, entry in ipairs(awaiting) do
                table.insert(names, tostring(entry))
            end

            table.insert(lines, "Open each profession window once to record recipes: "
                .. table.concat(names, ", "))
        end
    end

    local vendors = CN:GetModule("Vendors")

    if vendors then
        local counts = vendors.Summary()

        if counts.vendors == 0 then
            table.insert(lines,
                "No vendors recorded yet; they are captured as you open merchant windows.")
        end
    end

    return lines
end

-- PER STEP, NOT ONE FLAG FOR ELEVEN OF THEM.
--
-- `HasRun` was a single account-wide `completedAt` stamp that only
-- `Setup.Run` ever set, and it was wrong in four separate ways at once:
--
--   * Four of the eleven scans run themselves at login. The reminder still
--     told a player nothing had been scanned while the addon was reading
--     their reputations, currencies, titles and professions.
--   * The Collections tab's "Scan everything" button runs six of them and
--     did not satisfy the flag, so a player who used the window instead of
--     chat was nagged forever.
--   * `Appearances` has no refresh path at all -- no event, no login hook --
--     so after the first setup it silently rotted.
--   * And the nag could not say WHICH scans were missing, because it did not
--     know.
--
-- A stamp per step answers all four, and lets the reminder name what it
-- actually wants.
local function Steps()
    local record = CN.Account("setup")

    record.steps = record.steps or {}

    return record.steps
end

Setup.Steps = Steps

-- Called by every path that completes a scan, including the window's buttons
-- and the modules that scan themselves at login.
function CN.NoteSetupStep(key)
    if type(key) ~= "string" then
        return false
    end

    Steps()[string.lower(key)] = time()

    return true
end

function Setup.StepDone(key)
    return Steps()[string.lower(tostring(key))] ~= nil
end

-- What has never been read. The reminder's whole content.
--
-- Named for the scans, distinct from `Setup.Outstanding` above, which is
-- about the two subsystems no scan can ever reach.
-- A STEP THAT READS SOMETHING PER CHARACTER IS DONE PER CHARACTER. 0.76.0.
--
-- `Setup.StepDone` reads account-wide stamps, so once ANY character had run
-- a step, every other character was treated as having run it -- and for the
-- two stores whose readings are per character, that is exactly wrong. An alt
-- was never listed as needing a scan and silently read whatever the main's
-- had left behind.
--
-- 0.75.0 added `Achievements.HasScanned` for this and never called it; the
-- store behind it was written and read by nothing, which is the shape five
-- migrations in this addon exist to clean up.
local function StepDoneHere(step)
    if step.perCharacter then
        local module = CN:GetModule(step.module)

        local answers = module and module[step.perCharacter]

        if type(answers) == "function" then
            return answers() and true or false
        end
    end

    return Setup.StepDone(step.key) or Setup.StepDone(step.module)
end

Setup.StepDoneHere = StepDoneHere

function Setup.NeverScanned()
    local missing = {}

    for _, step in ipairs(Setup.steps) do
        if not StepDoneHere(step) then
            table.insert(missing, step.label)
        end
    end

    return missing
end

function Setup.HasRun()
    local record = CN.Account("setup")

    -- AND NOT WHEN A PER-CHARACTER STEP IS OUTSTANDING. 0.76.0.
    --
    -- `completedAt` is account-wide, so a main that had run setup silenced
    -- the reminder for every alt that never had -- including the two steps
    -- whose readings belong to the character that made them.
    for _, step in ipairs(Setup.steps) do
        if step.perCharacter and not StepDoneHere(step) then
            return false
        end
    end

    -- The old flag still counts, so an existing install is not told to run
    -- setup again for want of stamps it could not have written.
    if record and record.completedAt then
        return true
    end

    return #Setup.NeverScanned() == 0
end

------------------------------------------------------------
-- FIRST-RUN PROMPT
------------------------------------------------------------

-- Prompt, never act. Running eleven scans uninvited on someone's login is the
-- same discourtesy as seizing their waypoint.
--
-- BUT: the prompt used to fire once, ever. It was recorded as "prompted" the
-- first time and never spoken again, so a player who missed that single line
-- in a busy login -- which is most of them -- had an addon that quietly knew
-- nothing about their collections for the rest of its installed life, and no
-- way to find out why it seemed thin.
--
-- A required first step is worth saying every login until it has been done.
-- Once done, it is never mentioned again. That is the difference between a
-- reminder and nagging: a reminder stops when the thing is finished.
Setup.remindSeconds = 8

function Setup.RemindIfNeeded()
    if Setup.HasRun() then
        return false
    end

    -- NAMES WHAT IS ACTUALLY MISSING.
    --
    -- This said "has not scanned your collections yet" while four subsystems
    -- had scanned themselves eight seconds earlier and `/cn reps`, `/cn
    -- currencies`, `/cn titles` and `/cn professions` were all answering with
    -- real data. The addon was telling a new player it was blind while it was
    -- looking straight at them.
    local missing = Setup.NeverScanned()

    if #missing == 0 then
        return false
    end

    local named = missing

    if #named > 4 then
        named = { missing[1], missing[2], missing[3],
                  (#missing - 3) .. " more" }
    end

    CN.PrintBlock(
        CN.Count(#missing, "thing")
            .. " here " .. CN.Pluralize(#missing, "has", "have")
            .. " never been read: "
            .. CN.Muted(string.lower(table.concat(named, ", "))),
        {
            CN.Accent("/cn setup") .. CN.Muted(" reads all of them, once, and "
                .. "takes a few seconds."),
        })

    local account = CN.Account("setup")

    account.prompts = (account.prompts or 0) + 1

    return true
end

------------------------------------------------------------
-- WHEN THE ADDON CANNOT SEE SOMETHING
------------------------------------------------------------

-- Two subsystems are readable only while their window is open, so the addon
-- can be fully set up and still blind to a profession the player levelled
-- last week. It knew that and only said so immediately after a manual scan,
-- which is the one moment the player is least likely to need telling.
--
-- Said again periodically, and never more than this often, because the fix
-- is "open a window some time" rather than anything urgent.
Setup.outstandingIntervalDays = 7

function Setup.RemindOutstanding()
    if not Setup.HasRun() then
        return false
    end

    local lines = Setup.Outstanding()

    if #lines == 0 then
        return false
    end

    local account = CN.Account("setup")

    local last = account.outstandingRemindedAt or 0

    if (time() - last) < (Setup.outstandingIntervalDays * 86400) then
        return false
    end

    account.outstandingRemindedAt = time()

    -- `CN.Print` ALREADY PREFIXES THE ADDON'S NAME, so this rendered as
    -- "Completion Navigator: Completion Navigator cannot see everything yet:".
    Print("There are things it still cannot see:")

    for _, line in ipairs(lines) do
        CN.PrintLine(CN.Accent(line))
    end

    return true
end

CN:OnLogin(function()
    local function speak()
        if Setup.RemindIfNeeded() then
            return
        end

        Setup.RemindOutstanding()
    end

    -- Delayed, so it lands after the login chatter rather than inside it.
    if C_Timer and C_Timer.After then
        C_Timer.After(Setup.remindSeconds, speak)
    else
        speak()
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "setup",
    aliases = { "scanall" },
    args    = "[check]",
    order   = 5,
    help    = "Scan every subsystem once. Run this first.",
    handler = function(args)
        if string.lower(CN.Trim(args or "")) == "check" then
            -- Report without scanning. "What can you not see?" is a
            -- different question from "go and look again", and answering the
            -- first by doing the second is why people stop asking.
            if not Setup.HasRun() then
                Print("Not scanned yet. Type |cffffc74f/cn setup|r.")
                return
            end

            local lines = Setup.Outstanding()

            if #lines == 0 then
                Print("Everything the addon can read on its own is scanned.")
                return
            end

            Print("Still outside what the addon can read on its own:")

            for _, line in ipairs(lines) do
                CN.PrintLine("  |cffffc74f" .. line .. "|r")
            end

            return
        end

        Setup.Run()
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Goals.lua'] = @'
-- Modules/Goals.lua
-- Completion Navigator :: what you are actually working toward.
--
-- Everything else in this addon answers "what should I do next?" from the
-- whole field of what is available. That is the right default, and it is the
-- wrong answer when you have decided you want one specific thing.
--
-- A goal is a target you pin. Once pinned:
--
--   * it becomes a candidate in its own right, even when nothing else would
--     have surfaced it -- an uncollected mount is not normally actionable,
--     but if you have decided you want it, it is;
--   * anything that plausibly leads to it is weighted up, and says so;
--   * /cn goal prints what is actually known about getting it -- the source,
--     where it is, which of your characters is best placed, and what the
--     next concrete step is.
--
-- Goals are account-wide. Deciding you want a mount is not a fact about the
-- character you happened to be playing when you decided it.

local ADDON_NAME, CN = ...

local Goals = CN:RegisterModule("Goals")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

local function Store()
    return CN.Account("goals")
end

Goals.Store = Store

-- How many goals are worth having at once. Beyond a handful, "goal" stops
-- meaning anything and the weighting stops discriminating.
Goals.limit = 10

------------------------------------------------------------
-- TYPES
------------------------------------------------------------

-- Which objective types can be pinned, and what the user types for each.
Goals.types = {
    quest       = CN.objectiveTypes.QUEST,
    achievement = CN.objectiveTypes.ACHIEVEMENT,
    mount       = CN.objectiveTypes.MOUNT,
    pet         = CN.objectiveTypes.PET,
    toy         = CN.objectiveTypes.TOY,
    recipe      = CN.objectiveTypes.RECIPE,
    title       = CN.objectiveTypes.TITLE,
    rep         = CN.objectiveTypes.REPUTATION,
    reputation  = CN.objectiveTypes.REPUTATION,
    rare        = CN.objectiveTypes.RARE,
    currency    = CN.objectiveTypes.CURRENCY,

    -- NO `appearance` ENTRY, DELIBERATELY. 0.89.0.
    --
    -- Not an oversight, and not a gap worth closing as written. Every
    -- APPEARANCE row this addon produces is keyed `"set:<setID>"` (Sets) or
    -- by a transmog categoryID (Appearances), while `Blizzard.GetAppearanceSources`
    -- -- the only client call that can build a path to one -- takes an
    -- appearance VISUAL id, which is a third kind of number. A goal made from
    -- any of the three would decorate nothing and chase the wrong id, so the
    -- dead builder in `Modules/Chase.lua` was deleted rather than wired up.
    -- `Modules/Tooltips.lua` reached the same conclusion in 0.80.0.
}

local function ResolveType(text)
    if not text then
        return nil
    end

    return Goals.types[string.lower(text)]
end

Goals.ResolveType = ResolveType

local function Key(objectiveType, id)
    return CN.ObjectiveKey(objectiveType, id)
end

------------------------------------------------------------
-- MANAGING GOALS
------------------------------------------------------------

-- INVALIDATING THE CANDIDATES WAS NOT ENOUGH, AND THE COMMENT SAID IT WAS.
--
-- A goal changes the WEIGHT of rows that are otherwise unchanged, and
-- `userPreference` is not one of the fields the identity comparison looks at
-- -- deliberately, since no provider writes it. So a provider whose rows had
-- not changed took the unchanged-provider shortcut, `Goals.Decorate` never
-- ran, and `/cn goal` did nothing to a quest already in your log while
-- `/cn ungoal` left the +8 and the sentence behind. Both persisted until the
-- owning provider's list actually changed -- which, standing at a vendor
-- managing your goal list, is never.
--
-- `CN.decoratorGeneration` is the hook that defeats the shortcut, and it is
-- what `Harvest.NoteUnlocksChanged` uses one file over for the same reason.
function Goals.NoteChanged()
    Goals.zoneGeneration = (Goals.zoneGeneration or 0) + 1

    -- DELIBERATE: pinning or unpinning is the player acting, and no
    -- provider's cooldown may delay it -- 0.57.0 records that seeing nothing
    -- happen for two seconds reads as the feature being broken.
    --
    -- `NoteDecoratorsChanged` invalidates as well as bumping, so the second
    -- call this used to make is now redundant.
    CN.NoteDecoratorsChanged(true)
end

function Goals.IsGoal(objectiveType, id)
    if not objectiveType or not id then
        return false
    end

    local store = Store()

    if not store or next(store) == nil then
        return false
    end

    return store[Key(objectiveType, id)] ~= nil
end

function Goals.Add(objectiveType, id)
    if not objectiveType or not id then
        return false, "A goal needs a type and an ID."
    end

    local store = Store()

    local key = Key(objectiveType, id)

    if store[key] then
        return false, "That is already a goal."
    end

    if CN.CountKeys(store) >= Goals.limit then
        return false, "You already have " .. Goals.limit
            .. " goals. Clear one first."
    end

    local filters = CN:GetModule("Filters")

    local name = filters and filters.DescribeObjective(objectiveType, id)
        or (objectiveType .. " " .. tostring(id))

    store[key] = {
        type  = objectiveType,
        id    = id,
        name  = name,
        since = time(),
    }

    Goals.NoteChanged()

    return true, name
end

function Goals.Remove(objectiveType, id)
    local store = Store()

    local key = Key(objectiveType, id)

    if not store[key] then
        return false
    end

    local name = store[key].name

    store[key] = nil

    Goals.NoteChanged()

    return true, name
end

function Goals.Clear()
    local store = Store()

    local count = CN.CountKeys(store)

    for key in pairs(store) do
        store[key] = nil
    end

    Goals.NoteChanged()

    return count
end

-- Ordered oldest first, so the list is stable and numbering means something
-- between calls.
function Goals.List()
    local list = {}

    local filters = CN:GetModule("Filters")

    for key, goal in pairs(Store()) do
        -- RE-RESOLVED, NOT FROZEN.
        --
        -- The name was worked out once when the goal was pinned and then
        -- persisted -- and for currencies, recipes, titles, toys and rares
        -- the describer can only answer from a cache the scans fill. Pin one
        -- before the relevant scan and the placeholder was kept forever:
        -- "Currency 3008" in `/cn goals`, in `/cn chase`, and after every
        -- future login, even once the client could name it.
        --
        -- `/cn chase <type> <id>` pins automatically, so hitting this needs
        -- no unusual sequence at all. It undoes, for exactly the cache-only
        -- types, the fix recorded in Filters.lua: "The client knows. Ask it."
        local name = goal.name

        if filters and filters.DescribeObjective then
            local ok, described = pcall(filters.DescribeObjective,
                goal.type, goal.id)

            if ok and described and described ~= "" then
                local placeholder = tostring(goal.type):sub(1, 1)
                    .. tostring(goal.type):sub(2):lower() .. " " .. tostring(goal.id)

                -- Only when the describer has learned something real: a
                -- second placeholder is not an improvement on the first.
                if described ~= placeholder or not name then
                    name = described
                end
            end
        end

        table.insert(list, {
            key   = key,
            type  = goal.type,
            id    = goal.id,
            name  = name,
            since = goal.since or 0,
        })
    end

    table.sort(list, function(a, b)
        if a.since ~= b.since then
            return a.since < b.since
        end

        return tostring(a.key) < tostring(b.key)
    end)

    return list
end

------------------------------------------------------------
-- WHAT IS KNOWN ABOUT GETTING IT
------------------------------------------------------------

-- Everything the addon can say about how to obtain one goal. Deliberately
-- honest: where nothing is known, it says so and names what would make it
-- knowable, rather than inventing a route.
--
-- Returns a table:
--   name, source, mapID, x, y, zone, steps (array of strings),
--   done (boolean), character (string or nil)
function Goals.Plan(goal)
    local plan = {
        name  = goal.name,
        steps = {},
    }

    local types = CN.objectiveTypes

    local function step(text)
        table.insert(plan.steps, text)
    end

    ------------------------------------------------------------
    -- Is it already done?
    ------------------------------------------------------------

    local state, reason = CN.Explain(goal.type, goal.id)

    if state == CN.objectiveStates.COMPLETED then
        plan.done = true

        step(reason or "Already complete.")

        return plan
    end

    ------------------------------------------------------------
    -- Where is it?
    ------------------------------------------------------------

    if goal.type == types.QUEST then
        local quests = CN:GetModule("Quests")

        if quests then
            local mapID, x, y, source = quests.GetLocation(goal.id)

            plan.mapID, plan.x, plan.y = mapID, x, y
            plan.source = source

            if mapID then
                plan.zone = Blizzard.GetMapName(mapID)
            end
        end

        if state == CN.objectiveStates.LOCKED and reason then
            step(reason)
        end
    end

    if goal.type == types.MOUNT then
        local record = CN.Account("mounts")[goal.id]

        if record then
            -- LIVE. 0.65.0.
            --
            -- 0.62.0 stopped storing `mounts[id].source` and its own comment
            -- says "the two places that DISPLAY it read it live" -- this was
            -- the third, so a mount goal simply lost its "Source:" line and
            -- the matching reason on the `/cn next` row.
            local mounts = CN:GetModule("Mounts")

            plan.source = mounts and mounts.SourceText
                and mounts.SourceText(goal.id, record)

            if record.isFactionSpecific then
                step("Faction-locked. Only obtainable on one faction.")
            end
        end
    end

    if goal.type == types.PET then
        local record = CN.Account("pets")[goal.id]

        if record and record.isWild then
            step("Wild pet: find and capture it in the world.")
        end
    end

    if goal.type == types.RECIPE then
        local vendors = CN:GetModule("Vendors")

        if vendors then
            local seller = vendors.FirstLocatedSeller(goal.id)

            if seller then
                plan.source = "Sold by " .. tostring(seller.name)
                plan.mapID, plan.x, plan.y = seller.mapID, seller.x, seller.y
                plan.zone = seller.zone

                step("Buy it from " .. tostring(seller.name)
                    .. (seller.zone and (" in " .. seller.zone) or "") .. ".")
            else
                step("No recorded vendor sells this. Open merchants to record them.")
            end
        end
    end

    if goal.type == types.RARE or goal.type == types.TREASURE then
        local record = CN.Account("rares")[goal.id]

        if record then
            plan.mapID, plan.x, plan.y = record.mapID, record.x, record.y

            -- DERIVED, like the quest branch above. 0.65.0. Migration 15
            -- dropped `rares[id].zone` on the grounds that it was "read by
            -- nothing" -- and this read it, so the line became
            -- "Location known: map 2022" where it used to name the zone.
            plan.zone = record.mapID and CN.Blizzard.GetMapName(record.mapID)
                or record.zone

            -- SAID ONLY WHEN THERE IS A COUNT. 0.69.0.
            --
            -- Migration 19 deleted every stored sighting count because a
            -- missing number is better than a confidently wrong one, and
            -- this substituted 1 for the missing one -- telling a player who
            -- had farmed a rare weekly for a year that they had seen it once.
            -- 0.68.0 fixed the identical claim on the tooltip and left this
            -- sibling, which is the shape this project keeps finding.
            if record.sightings then
                step("Seen " .. record.sightings .. " time"
                    .. CN.Pluralize(record.sightings, "") .. " here.")
            end
        end
    end

    if goal.type == types.ACHIEVEMENT then
        local record = CN.Account("achievements")[goal.id]

        if record and record.criteria then
            -- THIS CHARACTER'S FIGURE. 0.75.0.
            --
            -- The last of the readers 0.74.0 meant to route through
            -- `DoneFor` and missed. A player who pinned an achievement on an
            -- alt was told "2 of 40 criteria left" for something they had
            -- barely started, because the flat field holds whichever
            -- character scanned last.
            local achievements = CN:GetModule("Achievements")

            -- `record.done` IS GONE. Migration 26 removed it and nothing
            -- writes it any more, so the old fallback was a reader of a
            -- field that cannot exist -- the shape this project keeps
            -- finding.
            local done = (achievements and achievements.DoneFor
                and achievements.DoneFor(record)) or 0

            local remaining = (record.criteria or 0) - done

            step(remaining .. " of " .. record.criteria .. " criteria left.")

            for _, criterion in ipairs(Blizzard.GetIncompleteCriteria(goal.id, 5) or {}) do
                step("Missing: " .. criterion)
            end
        end
    end

    if goal.type == types.REPUTATION then
        -- FROM THE CLIENT, NOT FROM THE STORE THE ANSWER SORTS INTO. 0.66.0.
        --
        -- `Reputations.Scan` files a faction into exactly one store: an
        -- account-wide record goes in the account store and is DELETED from
        -- the character store, and the reverse. So `CN.Account("reputations")
        -- [id]` was non-nil only for account-wide factions -- `accountWide`
        -- was always true there and the `else` branch could never run. The
        -- sentence about progress not carrying across a Warband never once
        -- appeared for the factions it is the entire point of.
        --
        -- `Chase.lua` asks the client the same question correctly, one file
        -- over. Two copies of one rule; this is the copy that drifted.
        if Blizzard.IsAccountWideReputation(goal.id) then
            step("Account-wide: any character's progress counts.")
        else
            step("Character-specific: progress does not carry across your Warband.")
        end
    end

    ------------------------------------------------------------
    -- Who should do it?
    ------------------------------------------------------------

    local warband = CN:GetModule("Warband")

    if warband then
        -- THE FOURTH RETURN. 0.84.0.
        --
        -- 0.79.0 added `switchable` to `Warband.WhoShould` and taught
        -- `Alts.Assignments` to honour it; this sibling was not swept. For a
        -- recipe or a title the named character is the HOLDER -- switching to
        -- them cannot earn it again, and a title cannot be earned twice at
        -- all -- so the Goals tab drew "Best character: Bob" under a goal Bob
        -- had already finished, and `/cn goals` printed "Best character: Bob
        -- (already known by another character)", contradicting itself inside
        -- one line. That is the exact sentence 0.79.0 removed from
        -- `/cn alts`, still being printed by the tab beside it.
        local ok, best, _, why, switchable =
            pcall(warband.WhoShould, goal.type, goal.id)

        if ok and best and switchable ~= false then
            plan.character = best

            step("Best character: " .. tostring(best)
                .. (why and (" (" .. why .. ")") or ""))
        end
    end

    ------------------------------------------------------------
    -- Fall back to honesty.
    ------------------------------------------------------------

    if plan.mapID and plan.x and plan.y then
        step("Location known: " .. (plan.zone or ("map " .. plan.mapID))
            .. string.format(" (%.1f, %.1f)", plan.x * 100, plan.y * 100))
    elseif #plan.steps == 0 then
        step("Nothing is known about how to obtain this yet.")
        step("The addon learns sources from play: open vendors, scan "
            .. "collections, and travel.")
    end

    return plan
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A goal is actionable by definition. Most goals would never surface on their
-- own -- an uncollected mount is not a next action for most people -- which is
-- exactly the point of having said you want it.
CN.RegisterCandidateProvider("Goals", function()
    local candidates = {}

    for _, goal in ipairs(Goals.List()) do
        if not CN.IsIgnored(goal.type, goal.id)
            and not CN.IsDeferred(goal.type, goal.id) then

            local plan = Goals.Plan(goal)

            if not plan.done then
                local reasons = { "you set this as a goal" }

                if plan.source then
                    table.insert(reasons, plan.source)
                end

                local travel, costed

                if plan.mapID then
                    -- Costed like everything else, rather than a flat
                    -- penalty for "not here" while holding the coordinates.
                    -- `costed` says whether the model answered. 0.70.0.
                    travel, costed = CN.TravelCost(plan.mapID, plan.x, plan.y)
                end

                table.insert(candidates, CN.NewObjective({
                    id              = goal.id,
                    type            = goal.type,
                    name            = goal.name,
                    mapID           = plan.mapID,
                    x               = plan.x,
                    y               = plan.y,
                    zone            = plan.zone,
                    accountWide     = true,
                    completionValue = 6,
                    travelCost      = travel,
                    travelCosted    = costed or nil,
                    reasons         = reasons,
                }))
            end
        end
    end

    return candidates
end, {
    -- THE EVENTS OF EVERY SYSTEM A GOAL CAN BE ABOUT.
    --
    -- `Goals.Plan` asks `CN.Explain` whether the goal is done, and a goal can
    -- be a quest, a mount, a pet, a toy, an achievement or a reputation. This
    -- declared one event -- the zone change -- so finishing the thing you had
    -- pinned did not take it off the list: the row carries a completionValue
    -- of six, so it stayed near the top of `/cn list` and on the route.
    --
    -- Worse, `Follow.Remaining` decides a stop is finished by asking whether
    -- its objectives are still candidates, so follow mode stuck on a goal the
    -- player had already completed until they crossed a zone boundary.
    --
    -- Same shape as the Inventory defect reported from play in 0.59.0, and
    -- the reason the harness now checks this structurally.
    events = {
        "ZONE_CHANGED_NEW_AREA",
        "QUEST_TURNED_IN", "QUEST_REMOVED", "QUEST_ACCEPTED",
        "NEW_MOUNT_ADDED", "NEW_PET_ADDED", "NEW_TOY_ADDED",
        "ACHIEVEMENT_EARNED", "UPDATE_FACTION",
    },
    cooldown = 2,
})

------------------------------------------------------------
-- WEIGHTING
------------------------------------------------------------

-- Anything that leads to a goal is worth more than it would be otherwise.
-- "Leads to" is deliberately narrow -- three relationships the addon can
-- actually establish, rather than a guess dressed up as a plan.
-- Which maps hold an unfinished goal. Rebuilt when the goal list changes,
-- not when a candidate asks.
local goalZones, goalZoneGeneration = nil, -1

local function GoalZones()
    local generation = Goals.zoneGeneration or 0

    if goalZones and goalZoneGeneration == generation then
        return goalZones
    end

    local zones = {}

    for _, goal in ipairs(Goals.List()) do
        local ok, plan = pcall(Goals.Plan, goal)

        if ok and plan and plan.mapID and not plan.done then
            zones[plan.mapID] = true
        end
    end

    goalZones           = zones
    goalZoneGeneration  = generation

    return zones
end

Goals.zoneGeneration = 0

-- What pinning something is worth, and what leading to something pinned is
-- worth. Named rather than written into the arithmetic, so the decorator can
-- take its own contribution back out again.
Goals.goalPreference        = 8
Goals.unlocksGoalPreference = 5
Goals.zonePreference        = 2

function Goals.Decorate(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return objective
    end

    local store = Store()

    -- NOTHING PINNED MEANS NOTHING PINNED, INCLUDING WHAT WAS.
    --
    -- Returning early here left the last pin's preference and sentence on
    -- every cached objective it had ever been stamped on -- so `/cn goal
    -- remove` took the goal out of the list and left its weighting behind.
    if not store or next(store) == nil then
        return Goals.Withdraw(objective)
    end

    -- 1. It IS a goal.
    if Goals.IsGoal(objective.type, objective.id) then
        -- SET, NEVER ADD TO ITSELF.
        --
        -- This read the field and incremented it, which was harmless only
        -- while every rebuild produced fresh objective tables. Since 0.55.0
        -- repaired the unchanged-provider shortcut, a provider's tables are
        -- REUSED across rebuilds -- so a pinned goal's preference compounded
        -- by eight on every rebuild, without bound: 8, 16, 24, 32. After
        -- twenty quest turn-ins the goal outweighed everything else on the
        -- list by thirty to one, `/cn next` returned it and nothing could
        -- ever displace it -- including a world boss about to despawn -- and
        -- `/cn breakdown` showed the inflated number as though it were
        -- deliberate. Only a reload cleared it.
        --
        -- `goalPreference` records what this decorator contributed, so the
        -- contribution can be replaced rather than repeated, and so a
        -- provider's own preference underneath it survives.
        local own = (objective.userPreference or 0)
            - (objective.goalPreference or 0)

        objective.goalPreference = Goals.goalPreference
        objective.userPreference = own + Goals.goalPreference

        -- `objective.isGoal` was set here, cleared in Withdraw, set again in
        -- the provider above, and read by nothing anywhere in the tree. What
        -- consumers actually ask is `CN.Reasons(objective)`, which carries
        -- the sentence below -- so the flag was a second, silent answer to a
        -- question already answered, with its own lifetime to get wrong.
        CN.AddDecoratorReason(objective, "goal", "this is one of your goals")

        return objective
    end

    -- 2. It unlocks a goal, per the dependency graph.
    if objective.type == CN.objectiveTypes.QUEST then
        local dependency = CN.GetDependency(CN.ObjectiveKey(objective.type, objective.id))

        if dependency and dependency.unlocks then
            for _, unlocked in ipairs(dependency.unlocks) do
                -- Dependency edges are stored as keys, but static data writes
                -- plain quest IDs. Accept both.
                local unlockedID = tonumber(unlocked)
                    or tonumber(tostring(unlocked):match(":(%d+)$"))

                if unlockedID and Goals.IsGoal(CN.objectiveTypes.QUEST, unlockedID) then
                    -- Same rule as above: replace this decorator's own
                    -- contribution rather than adding to it again.
                    local own = (objective.userPreference or 0)
                        - (objective.goalPreference or 0)

                    objective.goalPreference = Goals.unlocksGoalPreference
                    objective.userPreference = own
                        + Goals.unlocksGoalPreference

                    CN.AddDecoratorReason(objective, "goal",
                        "unlocks a goal")

                    return objective
                end
            end
        end
    end

    -- 3. It is in the same zone as a located goal. Weak, and weighted weakly:
    --    being in the right place is worth something, but it is not progress.
    --
    -- THE ZONES ARE WORKED OUT ONCE, NOT ONCE PER OBJECTIVE.
    --
    -- This looped every pinned goal and called Goals.Plan inside the
    -- decorator, and the decorator runs once per candidate. Goals.Plan asks
    -- the client for a map name, a vendor location, incomplete criteria and a
    -- Warband verdict -- so ten goals against a few hundred candidates was
    -- thousands of client calls per rebuild, on the path a 0.4x refactor
    -- restructured specifically to stop doing work per objective.
    --
    -- The answer only changes when the goals do, which the invalidation
    -- below already announces.
    if objective.mapID then
        local zones = GoalZones()

        if zones[objective.mapID] then
            local own = (objective.userPreference or 0)
                - (objective.goalPreference or 0)

            objective.goalPreference = Goals.zonePreference
            objective.userPreference = own + Goals.zonePreference

            CN.AddDecoratorReason(objective, "goal",
                "in the same zone as a goal")

            return objective
        end
    end

    -- None of the three applied, so anything a previous pass stamped is no
    -- longer true.
    return Goals.Withdraw(objective)
end

-- Takes back everything this decorator contributed, so an objective that
-- stops being a goal -- or stops leading to one -- stops carrying its weight
-- and its sentence. Every adjuster in this addon has done this since 0.51.0;
-- the decorators did not, because until 0.55.0 their tables were thrown away
-- between passes and the question never arose.
function Goals.Withdraw(objective)
    if type(objective) ~= "table" then
        return objective
    end

    if objective.goalPreference then
        objective.userPreference = (objective.userPreference or 0)
            - objective.goalPreference

        objective.goalPreference = nil
    end

    CN.ClearDecoratorReason(objective, "goal")

    return objective
end

CN.RegisterCandidateDecorator("Goals", Goals.Decorate)

------------------------------------------------------------
-- OUTPUT
------------------------------------------------------------

local function PrintPlan(index, goal)
    local plan = Goals.Plan(goal)

    Print(index .. ". |cffffc74f" .. tostring(plan.name) .. "|r"
        .. " |cff8a8f96(" .. tostring(goal.type) .. " " .. tostring(goal.id) .. ")|r"
        .. (plan.done and " |cff73b873done|r" or ""))

    if plan.source then
        Print("   Source: " .. tostring(plan.source))
    end

    for _, step in ipairs(plan.steps) do
        CN.PrintLine("   - " .. step)
    end

    if plan.character then
        Print("   Best character: |cffffc74f" .. tostring(plan.character) .. "|r")
    end

    if plan.mapID and plan.x and plan.y then
        Print("   |cffffc74f/cn gogoal " .. index .. "|r to set a waypoint.")
    end
end

Goals.PrintPlan = PrintPlan

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "goal",
    args    = "<type> <name or id>",
    order   = 12,
    help    = "Pin something as a goal. Types: quest, achievement, mount, pet, toy, recipe, title, rep, rare, currency.",
    handler = function(args)
        -- Everything after the first word is the thing, because a name has
        -- spaces in it. `^(%S+)%s+(%S+)$` accepted only a single word, so
        -- even once names were resolvable "Reins of the Black Drake" could
        -- not be typed.
        local typeText, idText =
            string.match(CN.Trim(args or ""), "^(%S+)%s+(.+)$")

        if not typeText then
            CN.PrintBlock("Usage: " .. CN.Accent("/cn goal <type> <name or id>"), {
                CN.Muted("e.g. ") .. CN.Accent("/cn goal mount Invincible"),
                CN.Muted("Types: quest, achievement, mount, pet, toy, recipe, "
                    .. "title, rep, rare, currency"),
                CN.Accent("/cn goals") .. CN.Muted(" lists what you have pinned."),
            })

            return
        end

        local objectiveType = ResolveType(typeText)

        if not objectiveType then
            Print("Not a goal type: " .. typeText)
            Print("|cff8a8f96Types: quest, achievement, mount, pet, toy, recipe, "
                .. "title, rep, rare, currency|r")
            return
        end

        local id, why = CN.ResolveObjective(objectiveType, idText)

        if not id then
            Print(why or ("Not an ID: " .. idText))
            return
        end

        local added, message = Goals.Add(objectiveType, id)

        if not added then
            Print(message)
            return
        end

        Print("Goal set: |cffffc74f" .. tostring(message) .. "|r")
        Print("|cff8a8f96See the path with |cffffc74f/cn chase " .. typeText
            .. " " .. idText .. "|r")

        local list = Goals.List()

        for index, goal in ipairs(list) do
            if goal.type == objectiveType and goal.id == id then
                PrintPlan(index, goal)
                break
            end
        end
    end,
}

CN:RegisterCommand{
    name    = "goals",
    order   = 13,
    help    = "List your goals and what is known about reaching them.",
    handler = function()
        local list = Goals.List()

        if #list == 0 then
            Print("No goals set.")
            Print("|cffffc74f/cn goal mount 1234|r pins something to work toward.")
            Print("|cff8a8f96A goal becomes actionable even when nothing else "
                .. "would have surfaced it, and anything leading to it ranks higher.|r")
            return
        end

        Print("Goals (" .. #list .. " of " .. Goals.limit .. "):")

        for index, goal in ipairs(list) do
            PrintPlan(index, goal)
        end
    end,
}

CN:RegisterCommand{
    name    = "ungoal",
    args    = "<number or all>",
    order   = 14,
    help    = "Remove a goal.",
    handler = function(args)
        args = CN.Trim(args or "")

        if string.lower(args) == "all" then
            local count = Goals.Clear()

            Print("Cleared " .. CN.Count(count, "goal") .. ".")
            return
        end

        local index = CN.ToID(args)

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn ungoal <number or all>")

            if #list > 0 then
                Print("|cff8a8f96Numbers come from |cffffc74f/cn goals|r.|r")
            end

            return
        end

        local goal = list[index]

        local removed, name = Goals.Remove(goal.type, goal.id)

        if removed then
            Print("Goal removed: " .. tostring(name))
        end
    end,
}

CN:RegisterCommand{
    name    = "gogoal",
    args    = "<number>",
    order   = 15,
    help    = "Navigate to a goal.",
    handler = function(args)
        local index = CN.ToID(CN.Trim(args or ""))

        local list = Goals.List()

        if not index or not list[index] then
            Print("Usage: /cn gogoal <number>")
            return
        end

        local goal = list[index]
        local plan = Goals.Plan(goal)

        if not (plan.mapID and plan.x and plan.y) then
            Print("No location is known for " .. tostring(plan.name) .. ".")

            for _, step in ipairs(plan.steps) do
                CN.PrintLine("  - " .. step)
            end

            return
        end

        CN.NavigateToObjective({
            id    = goal.id,
            type  = goal.type,
            name  = plan.name,
            mapID = plan.mapID,
            x     = plan.x,
            y     = plan.y,
        })
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Chase.lua'] = @'
-- Modules/Chase.lua
-- Completion Navigator :: what stands between you and the thing you want.
--
-- `/cn goal` has always been able to say "I want that" and re-weight the
-- list accordingly. What it could never say is what the PATH is. A player
-- chasing a mount got a line saying the mount was a goal, and nothing about
-- which four things had to happen first, how many of them were already done,
-- or which one to go and do now.
--
-- This is that path. Chase turns a goal into an ordered chain of steps, each
-- one carrying a state -- done, next, blocked, or simply outstanding -- and,
-- where the game will tell us, a real count.
--
-- ON NUMBERS. The addon's standing rule is that it does not invent a
-- denominator. That rule is doing real work here, because a progress bar is
-- exactly the kind of thing that begs to be faked. So:
--
--   * Achievement criteria, appearance sources, and reputation standing have
--     denominators the client vouches for. Those get a fraction.
--   * A mount whose source is a sentence of English does not. It gets the
--     sentence, and no bar.
--
-- Showing "1 of 1 steps" for something we know nothing about would be a lie
-- told in a font that looks like a fact.

local ADDON_NAME, CN = ...

local Chase = CN:RegisterModule("Chase")

local Print = CN.Print

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STEP STATES
------------------------------------------------------------

-- Ordered by how much the player needs to look at them.
Chase.states = {
    NEXT    = "NEXT",     -- go and do this one
    TODO    = "TODO",     -- outstanding, but not the immediate move
    BLOCKED = "BLOCKED",  -- cannot be done yet, and we know why
    DONE    = "DONE",     -- already behind you
    NOTE    = "NOTE",     -- context, not a step
}

Chase.stateLabels = {
    NEXT    = "next",
    TODO    = "to do",
    BLOCKED = "blocked",
    DONE    = "done",
    NOTE    = "",
}

-- THE ROLE PER STATE, NOT A SECOND PALETTE.
--
-- This held five hand-written RGB triples, three of them colours Design.lua
-- says were retired -- a complete second palette in a file that is not
-- allowed to have one, and read by nothing: the same five states are declared
-- again with palette codes in the Goals tab. Roles are named here so the two
-- cannot drift, and so the one place that renders them has something to ask.
Chase.stateRoles = {
    NEXT    = "BRAND",
    TODO    = "BODY",
    BLOCKED = "BAD",
    DONE    = "GOOD",
    NOTE    = "MUTED",
}

-- And as a wrapped string, for chat and for a list label.
function Chase.StateText(state, text)
    local role = Chase.stateRoles[state] or "BODY"

    return "|cff" .. CN.C[role] .. tostring(text) .. "|r"
end

local function NewStep(state, text, extra)
    local step = extra or {}

    step.state = state
    step.text  = text

    return step
end

------------------------------------------------------------
-- PER-TYPE CHAINS
------------------------------------------------------------

-- Each builder returns steps and, optionally, a progress table:
--   { done = n, total = m, unit = "criteria" }
--
-- Returning no progress table is a positive statement -- "the game does not
-- give me a trustworthy count here" -- not an oversight.

local builders = {}

builders.ACHIEVEMENT = function(goal)
    local steps = {}

    -- THE SECOND RETURN IS THE HONEST COUNT. 0.61.0.
    --
    -- The list is capped at 25 rows because a chain with sixty lines in it is
    -- not a chain any more, it is a wall. But the PROGRESS must describe the
    -- achievement, not the window -- see the note on
    -- `Blizzard.GetAchievementCriteriaList`, which used to break out of its
    -- own loop at the cap and hand back a total of 25 for a 31-criterion
    -- meta. This printed 36% for something 29% done, and 100% for anything
    -- whose first 25 criteria happened to be finished.
    local criteria, summary = Blizzard.GetAchievementCriteriaList(goal.id, 25)

    criteria = criteria or {}
    summary  = summary or { total = #criteria, completed = 0 }

    if summary.total == 0 then
        return steps, nil
    end

    local first = true

    for _, criterion in ipairs(criteria) do
        local text = criterion.description

        -- Some criteria carry their own counter. Where they do, it is the
        -- most useful thing on the line.
        if criterion.required and criterion.required > 1 and criterion.quantity then
            text = string.format("%s (%d/%d)",
                text, criterion.quantity, criterion.required)
        end

        if criterion.completed then
            table.insert(steps, NewStep(Chase.states.DONE, text))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, text))
        end
    end

    -- SAY SO WHEN THE LIST IS SHORTER THAN THE ACHIEVEMENT.
    --
    -- Without this the last visible row reads as the end of the chain, and a
    -- player who counts the rows gets the same wrong denominator by hand that
    -- the code used to compute.
    if summary.truncated then
        table.insert(steps, NewStep(Chase.states.NOTE, string.format(
            "%d more criteria not shown.",
            summary.total - #criteria)))
    end

    return steps, {
        done  = summary.completed,
        total = summary.total,
        unit  = "criteria",
    }
end

builders.REPUTATION = function(goal)
    local steps = {}

    local standing = Blizzard.GetReputationRemaining(goal.id)

    if not standing then
        return steps, nil
    end

    if Blizzard.IsAccountWideReputation(goal.id) then
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Account-wide: any character's progress counts."))
    else
        table.insert(steps, NewStep(Chase.states.NOTE,
            "Character-specific: progress does not carry across your Warband."))
    end

    table.insert(steps, NewStep(Chase.states.NEXT, string.format(
        "%s reputation to the next rank", CN.Comma(standing.remaining))))

    -- NO FRACTION, BECAUSE THIS ONE IS NOT A FRACTION OF THE GOAL.
    --
    -- `earned` and `needed` describe the CURRENT RANK ONLY -- how far into
    -- Honored you are, not how far along the ladder to Exalted. Returning
    -- them as done/total made `/cn chase` draw a full bar and print "100%"
    -- for somebody standing at 21,000 of the 42,000 the ladder needs, and
    -- made `Chase.All` -- which sorts by exactly that fraction -- rank a
    -- faction one point short of Honored above an appearance genuinely eighty
    -- percent collected.
    --
    -- The client will vouch for progress inside a band and not for progress
    -- across the ladder, so the band is reported as a count, with the rank
    -- named, and no denominator is invented for the rest. That is this
    -- addon's standing rule, applied to the one place that was breaking it
    -- most visibly.
    return steps, {
        done         = nil,
        total        = nil,
        unit         = "reputation",
        bandEarned   = standing.earned,
        bandNeeded   = standing.needed,
        nextRank     = standing.nextRankName,
        unknownTotal = "the client reports progress inside a rank, not "
            .. "across the whole standing",
    }
end

-- NO APPEARANCE BUILDER. 0.89.0.
--
-- Thirty-five lines walking an appearance's sources sat here, unreachable
-- since the file was written: a builder is keyed on `goal.type`, goals are
-- created only through `Goals.Add`, and `Goals.types` has no appearance
-- entry. `Modules/Tooltips.lua` recorded that fact in 0.80.0 and deleted its
-- own unreachable branch; this pair was not swept with it.
--
-- Wiring it up is not the fix either. It called
-- `Blizzard.GetAppearanceSources(goal.id)`, which takes an appearance VISUAL
-- id, while every APPEARANCE row the addon produces is keyed `"set:<setID>"`
-- or by a transmog categoryID -- three different numbers. A goal made from
-- any of them would chase the wrong one. Dead code that reads as a live
-- feature is worse than an absent one, so it is gone.
builders.QUEST = function(goal)
    local steps = {}

    local dependencies = CN.GetPrerequisites and CN.GetPrerequisites(goal.id)

    if type(dependencies) ~= "table" or #dependencies == 0 then
        return steps, nil
    end

    local done = 0
    local first = true

    for _, questID in ipairs(dependencies) do
        local name = Blizzard.GetQuestTitle(questID, true)
            or ("Quest " .. tostring(questID))

        if CN.IsQuestComplete and CN.IsQuestComplete(questID) then
            done = done + 1

            table.insert(steps, NewStep(Chase.states.DONE, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        else
            local state = Chase.states.TODO

            if first then
                state = Chase.states.NEXT
                first = false
            end

            table.insert(steps, NewStep(state, name,
                { objectiveType = CN.objectiveTypes.QUEST, objectiveID = questID }))
        end
    end

    return steps, { done = done, total = #dependencies, unit = "prerequisites" }
end

Chase.builders = builders

-- Which goals are worth asking the Adventure Guide about. A reputation does
-- not drop from a boss, and searching for one costs a journal round-trip to
-- learn nothing.
Chase.instanceSourceTypes = {
    [CN.objectiveTypes.MOUNT]      = true,
    [CN.objectiveTypes.PET]        = true,
    [CN.objectiveTypes.TOY]        = true,
    [CN.objectiveTypes.TITLE]      = true,
}

------------------------------------------------------------
-- THE CHAIN
------------------------------------------------------------

-- The full picture for one goal: where it is, what remains, how far along
-- you are, and which single step to go and do.
function Chase.Chain(goal)
    local chain = {
        name  = goal and goal.name,
        type  = goal and goal.type,
        id    = goal and goal.id,
        steps = {},
    }

    if type(goal) ~= "table" or not goal.type or not goal.id then
        return chain
    end

    local goals = CN:GetModule("Goals")

    -- Location, source and "who should do it" already exist. Reuse them
    -- rather than growing a second, subtly different answer.
    local plan = goals and goals.Plan(goal) or {}

    chain.done      = plan.done
    chain.source    = plan.source
    chain.mapID     = plan.mapID
    chain.x         = plan.x
    chain.y         = plan.y
    chain.zone      = plan.zone
    chain.character = plan.character

    if chain.done then
        table.insert(chain.steps, NewStep(Chase.states.DONE, "Already complete."))

        chain.progress = { done = 1, total = 1, unit = "steps" }

        return chain
    end

    local builder = builders[goal.type]

    if builder then
        local ok, steps, progress = pcall(builder, goal)

        if ok and type(steps) == "table" then
            chain.steps    = steps
            chain.progress = progress
        end
    end

    -- IF IT DROPS FROM A BOSS, SAY WHICH BOSS.
    --
    -- Before this, a raid mount produced a chain whose only content was the
    -- mount journal's source line -- prose, no boss, no instance, and no idea
    -- whether the player was already locked out of the thing this week. That
    -- is the one failure this feature exists to prevent: a goal with no path
    -- to it.
    --
    -- Deliberately additive. The step is appended to whatever the builder
    -- produced rather than replacing it, because the journal's answer is a
    -- location and the builder's answer is the requirement, and a player
    -- needs both.
    local instances = CN:GetModule("Instances")

    if instances and chain.name and Chase.instanceSourceTypes[goal.type] then
        local ok, description, first = pcall(instances.DescribeSource, chain.name)

        if ok and description and first then
            local lockout = first.instance and instances.LockoutFor(first.instance)

            if lockout and lockout.complete then
                table.insert(chain.steps, NewStep(Chase.states.BLOCKED,
                    "Drops from " .. description,
                    {
                        note = "you are saved to " .. first.instance
                            .. " and it is cleared" .. CN.DASH .. "resets in "
                            .. instances.FormatReset(lockout.resetsIn),
                    }))
            else
                local state = Chase.states.TODO

                -- Only claim the immediate move if nothing else has.
                if not Chase.NextStep(chain) then
                    state = Chase.states.NEXT
                end

                local step = NewStep(state, "Kill " .. description, {
                    encounterID = first.encounterID,
                    instanceID  = first.instanceID,
                })

                if lockout then
                    step.note = lockout.remaining .. " of " .. lockout.encounters
                        .. " left on your lockout"
                end

                table.insert(chain.steps, step)
            end
        end
    end

    -- Nothing structured? Fall back to what the existing planner knows, which
    -- is prose rather than a chain -- and say so, rather than dressing a
    -- sentence up as a step.
    if #chain.steps == 0 then
        for _, text in ipairs(plan.steps or {}) do
            table.insert(chain.steps, NewStep(Chase.states.NOTE, text))
        end

        if chain.mapID and chain.x and chain.y then
            table.insert(chain.steps, 1,
                NewStep(Chase.states.NEXT, "Travel to " ..
                    (chain.zone or ("map " .. tostring(chain.mapID))), {
                    mapID = chain.mapID,
                    x     = chain.x,
                    y     = chain.y,
                }))
        end
    end

    chain.next = Chase.NextStep(chain)

    return chain
end

-- The one step to go and do. Nil when everything outstanding is blocked or
-- unknown, which is itself worth saying out loud.
function Chase.NextStep(chain)
    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.NEXT then
            return step
        end
    end

    for _, step in ipairs(chain and chain.steps or {}) do
        if step.state == Chase.states.TODO then
            return step
        end
    end

    return nil
end

-- A single line for chat: where you are, and what to do about it.
function Chase.Summarize(chain)
    if not chain or not chain.name then
        return "Nothing to chase."
    end

    if chain.done then
        return tostring(chain.name) .. " is complete."
    end

    local parts = {}

    if chain.progress and chain.progress.total and chain.progress.total > 0 then
        table.insert(parts, string.format("%s of %s %s",
            CN.Comma(chain.progress.done or 0),
            CN.Comma(chain.progress.total),
            chain.progress.unit or "steps"))

    elseif chain.progress and chain.progress.bandNeeded then
        -- A band with the rank named, rather than a fraction of the goal
        -- that the client will not vouch for. "11,999 of 12,000 to Revered"
        -- is a fact; "100%" of a half-finished ladder is not.
        table.insert(parts, string.format("%s of %s %s%s",
            CN.Comma(chain.progress.bandEarned or 0),
            CN.Comma(chain.progress.bandNeeded),
            chain.progress.unit or "steps",
            chain.progress.nextRank
                and (" to " .. tostring(chain.progress.nextRank)) or ""))
    end

    local nextStep = chain.next or Chase.NextStep(chain)

    if nextStep then
        table.insert(parts, "next: " .. tostring(nextStep.text))
    elseif #parts == 0 then
        return tostring(chain.name)
            .. CN.DASH .. "the game does not say how this is obtained."
    end

    return tostring(chain.name) .. " " .. CN.DASH .. " " .. table.concat(parts, ", ")
end

-- Percent complete, or nil. Nil is a real answer and callers must render it
-- as "unknown" rather than as zero.
function Chase.Fraction(chain)
    local progress = chain and chain.progress

    if not progress or not progress.total or progress.total <= 0 then
        return nil
    end

    local fraction = (progress.done or 0) / progress.total

    if fraction < 0 then return 0 end
    if fraction > 1 then return 1 end

    return fraction
end

-- Every goal, chained, with the NEAREST-FINISHED first.
--
-- The header used to say the opposite -- "least-finished first: the thing you
-- are furthest from is the thing most in need of a plan" -- while the
-- comparator eight lines below, and its own inline comment, did and described
-- the reverse. Two comments in one function, disagreeing.
--
-- The code is right and the header was wrong. Everything else in this addon
-- ranks the nearly-finished thing above the barely-begun one: a set two
-- pieces short, a quest three kills from done, a lockout part-way through.
-- A goal you are eighty percent through is the one worth an evening; one you
-- have not started is a decision, not a next action.
function Chase.All()
    local goals = CN:GetModule("Goals")

    if not goals then
        return {}
    end

    local chains = {}

    for _, goal in ipairs(goals.List()) do
        table.insert(chains, Chase.Chain(goal))
    end

    table.sort(chains, function(a, b)
        local left  = Chase.Fraction(a)
        local right = Chase.Fraction(b)

        -- Finished goals sink. Unmeasurable ones sit between measurable
        -- progress and completion, because "no idea" is more actionable than
        -- "done" and less actionable than "you are 80% there".
        local leftDone  = a.done and 1 or 0
        local rightDone = b.done and 1 or 0

        if leftDone ~= rightDone then
            return leftDone < rightDone
        end

        if left and right then
            return left > right
        end

        if left or right then
            return left ~= nil
        end

        return tostring(a.name) < tostring(b.name)
    end)

    return chains
end

------------------------------------------------------------
-- NAVIGATION
------------------------------------------------------------

-- Go to the next step of a chain, not to the goal itself.
--
-- Those differ, and the difference is the whole point: the mount is in a
-- dungeon you cannot enter yet, but the attunement quest is forty yards away.
function Chase.NavigateNext(chain)
    local step = chain and (chain.next or Chase.NextStep(chain))

    if step and step.objectiveType and step.objectiveID then
        local located = CN.FindCandidate
            and CN.FindCandidate(step.objectiveType, step.objectiveID)

        if located then
            return CN.NavigateToObjective(located)
        end
    end

    -- SAY SOMETHING. 0.79.0. The Goals tab's "Next step" button reached
    -- these two lines and produced no chat output whatsoever, so a player
    -- who clicked it had no way to tell whether anything had happened.
    if step and step.mapID and step.x and step.y then
        return CN.SetWaypointAndSay(step.mapID, step.x, step.y, step.text,
            "Next step: " .. tostring(step.text or "here"))
    end

    if chain and chain.mapID and chain.x and chain.y then
        return CN.SetWaypointAndSay(chain.mapID, chain.x, chain.y, chain.name,
            "Waypoint set: " .. tostring(chain.name or "that goal"))
    end

    Print("No location is known for the next step of "
        .. tostring(chain and chain.name or "that goal") .. ".")

    return false
end

------------------------------------------------------------
-- HOW LONG IS THIS GOING TO TAKE
------------------------------------------------------------

-- The addon already measures two things and never multiplied them together:
-- how long each kind of objective takes this player (Session, from watching)
-- and how long it takes to get anywhere (Travel, from flight paths and
-- measured speed). A chain is a list of steps of known types in known places.
--
-- RULES, WHICH ARE THE SAME RULES AS EVERYWHERE ELSE IN THIS ADDON.
--
--   * A step whose type has never been timed is COUNTED as unknown, reported
--     as such, and charged at the average of the steps that have been timed
--     -- because it still has to happen, and pretending it is free would
--     understate the chain rather than widen the range.
--   * The result is a RANGE, not a figure. Anybody who has played knows that
--     "four hours" is a claim nobody can make; "three to six hours" is one
--     the data actually supports.
--   * If more steps are unknown than known, no estimate is offered at all.
--     Half an answer stated confidently is worse than "not enough to say".

-- How wide the range is either side of the estimate. Chosen to be honest
-- rather than flattering: task times in this game vary by more than a third
-- depending on competition for mobs, group size and luck.
Chase.estimateSpread = 0.4

-- Below this proportion of steps timed, say nothing.
Chase.estimateCoverage = 0.5

function Chase.Estimate(chain)
    if type(chain) ~= "table" or #(chain.steps or {}) == 0 then
        return nil
    end

    local session = CN:GetModule("Session")

    if not session or not session.TypicalSeconds then
        return nil
    end

    local seconds, timed, unknown = 0, 0, 0

    for _, step in ipairs(chain.steps) do
        -- Notes are context and done steps are behind you; neither is work.
        if step.state ~= Chase.states.DONE and step.state ~= Chase.states.NOTE then
            local objectiveType = step.objectiveType or chain.type

            local typical = objectiveType and session.TypicalSeconds(objectiveType)

            if typical then
                seconds = seconds + typical
                timed   = timed + 1
            else
                unknown = unknown + 1
            end
        end
    end

    local outstanding = timed + unknown

    if outstanding == 0 then
        return nil
    end

    -- TRAVEL, LEG BY LEG (0.43.0).
    --
    -- The first version costed one journey -- player to the next step -- and
    -- said so. That understated any chain whose steps are in different
    -- places, which is most of them: a chain across three zones is three
    -- journeys, and pretending it is one makes the estimate confidently short
    -- in exactly the cases where the player most needs it to be right.
    --
    -- Walked in the order the steps are listed, which is the order the addon
    -- would route them, starting from where the player actually is. Steps
    -- with no location contribute no travel rather than a guessed hop.
    local travelSeconds = 0

    local travel = CN:GetModule("Travel")

    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    if travel and playerMap then
        -- NEAREST-FIRST, not listed-order.
        --
        -- 0.42.0 costed one journey; 0.43.0 costed every leg but walked them
        -- in the order the steps happened to be listed, which is the order a
        -- criteria list came back in -- no relation to geography. On a chain
        -- whose steps are scattered that overstates the total badly.
        --
        -- This is the same greedy nearest-neighbour walk the zone router
        -- uses, and it is an ESTIMATE either way: the point is not to find
        -- the optimal tour, it is to stop pretending the player will walk a
        -- deliberately silly one.
        local pending = {}

        for _, step in ipairs(chain.steps) do
            if step.state ~= Chase.states.DONE
                and step.state ~= Chase.states.NOTE then

                local toMap = step.mapID or chain.mapID
                local toX   = step.x or chain.x
                local toY   = step.y or chain.y

                if toMap and toX and toY then
                    table.insert(pending, { mapID = toMap, x = toX, y = toY })
                end
            end
        end

        local fromMap, fromX, fromY = playerMap, playerX, playerY

        while #pending > 0 and fromX do
            local bestIndex, bestSeconds

            for index, target in ipairs(pending) do
                local leg = travel.EstimateSeconds(
                    fromMap, fromX, fromY, target.mapID, target.x, target.y)

                if leg and (not bestSeconds or leg < bestSeconds) then
                    bestIndex, bestSeconds = index, leg
                end
            end

            if not bestIndex then
                break
            end

            local chosen = table.remove(pending, bestIndex)

            travelSeconds = travelSeconds + bestSeconds

            fromMap, fromX, fromY = chosen.mapID, chosen.x, chosen.y
        end
    end

    -- THE BOUNDARY THE RULE BELOW ACTUALLY STATES. 0.89.0.
    --
    -- "no estimate at all is offered unless more steps are timed than are
    -- not" -- and at exactly half, two timed and two untimed, `0.5 < 0.5` is
    -- false, so the guard passed and `/cn chase` printed a confident range in
    -- which half the total was extrapolation.
    if timed == 0 or (timed / outstanding) <= Chase.estimateCoverage then
        return {
            seconds     = nil,
            timed       = timed,
            unknown     = unknown,
            travel      = travelSeconds,
            enough      = false,
        }
    end

    -- Steps that have never been timed still have to happen. Charging them at
    -- the average of the ones that have is the least-wrong option available,
    -- and it widens the range rather than hiding in it.
    --
    -- The RULES block at the top of this section used to say the opposite --
    -- that an untimed step "contributes nothing" -- which would have meant
    -- quoting four hours for a chain whose second half the addon has simply
    -- never watched. The guard that makes this honest is the one above: no
    -- estimate at all is offered unless more steps are timed than are not,
    -- and the count of untimed ones is reported alongside the number.
    local perStep = seconds / timed

    local total = seconds + (unknown * perStep) + travelSeconds

    return {
        seconds = total,
        low     = total * (1 - Chase.estimateSpread),
        high    = total * (1 + Chase.estimateSpread),
        timed   = timed,
        unknown = unknown,
        travel  = travelSeconds,
        enough  = true,
    }
end

function Chase.DescribeEstimate(chain)
    local estimate = Chase.Estimate(chain)

    if not estimate then
        return nil
    end

    local session = CN:GetModule("Session")

    local function format(seconds)
        return session and session.FormatDuration
            and session.FormatDuration(seconds)
            or (math.floor((seconds or 0) / 60) .. "m")
    end

    if not estimate.enough then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time |cff8a8f96-- "
            .. estimate.unknown .. " of "
            .. (estimate.timed + estimate.unknown)
            .. " steps are kinds of thing this addon has not watched you do "
            .. "often enough to time|r"
    end

    -- THROUGH THE CONVENTION, like every other number this addon prints.
    --
    -- "roughly X to Y" was a fourth grammar for hedging, alongside
    -- `CN.WithConfidence`, "(searched on Normal)" and a bare number -- and
    -- the whole point of a convention is that a player learns it once. A
    -- range IS an estimate; saying so with the addon's own word for it costs
    -- nothing and means the word keeps meaning one thing.
    local text = CN.WithConfidence(
        format(estimate.low) .. " to " .. format(estimate.high),
        CN.confidence.ESTIMATED)

    if estimate.travel > 60 then
        text = text .. " " .. CN.Muted("including " .. format(estimate.travel)
            .. " to get there")
    end

    if estimate.unknown > 0 then
        text = text .. " " .. CN.Muted("(" .. estimate.unknown
            .. (estimate.unknown == 1 and " step untimed, charged at the "
                or " steps untimed, charged at the ")
            .. "rate of the rest)")
    end

    return text
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

local function PrintChain(chain)
    Print(Chase.Summarize(chain))

    local fraction = Chase.Fraction(chain)

    if fraction then
        Print(string.format("  |cff5dd2fb%s|r %s",
            CN.ProgressBar and CN.ProgressBar(fraction, 20) or "",
            CN.PercentText(fraction)))
    end

    local shown = 0

    for _, step in ipairs(chain.steps) do
        if shown >= 12 then
            CN.PrintLine("  |cff8a8f96... and " .. (#chain.steps - shown) .. " more|r")
            break
        end

        -- THE THIRD DECLARATION OF THE SAME FIVE STATES, now the only one.
        --
        -- This file held one as RGB triples, the Goals tab held one as
        -- palette hex, and this chain of `elseif`s held a third -- so a state
        -- could be given a colour in one place and keep two old ones.
        local label = Chase.stateLabels[step.state] or ""

        CN.PrintLine(Chase.StateText(step.state,
            "  " .. (label ~= "" and ("[" .. label .. "] ") or "")
            .. tostring(step.text)))

        shown = shown + 1
    end

    local estimate = Chase.DescribeEstimate(chain)

    if estimate then
        Print("  |cffffc74fTime:|r " .. estimate)
    end

    if chain.character then
        Print("  |cff8a8f96Best character: " .. tostring(chain.character) .. "|r")
    end
end

Chase.PrintChain = PrintChain

CN:RegisterCommand{
    name    = "chase",
    aliases = { "chain", "path" },
    args    = "[<type> <name or id>, or nothing for all goals]",
    order   = 16,
    help    = "Show what stands between you and a goal, step by step.",
    handler = function(args)
        args = CN.Trim(args or "")

        local goals = CN:GetModule("Goals")

        if not goals then
            Print("The Goals module is not loaded.")
            return
        end

        if args ~= "" then
            -- BY NAME, NOT ONLY BY ID.
            --
            -- The store page leads with `/cn chase rep 2600`, and nobody
            -- knows that faction 2600 is the Severed Threads. Meanwhile
            -- `/cn rep`, `/cn mount`, `/cn pet`, `/cn toy`, `/cn title` and
            -- `/cn recipe` had all accepted names for releases -- the
            -- resolvers existed, and the flagship feature did not call them.
            --
            -- The name may contain spaces, so the split takes the first word
            -- as the type and everything after it as the thing.
            local typeText, idText = string.match(args, "^(%S+)%s+(.+)$")

            local objectiveType = typeText and goals.ResolveType(typeText)

            local id, why

            if objectiveType then
                id, why = CN.ResolveObjective(objectiveType, idText)
            end

            if not objectiveType or not id then
                CN.PrintBlock("Usage: " .. CN.Accent("/cn chase <type> <name or id>"), {
                    CN.Muted("e.g. ") .. CN.Accent("/cn chase mount Invincible"),
                    CN.Muted("Types: quest, achievement, mount, pet, toy, "
                        .. "recipe, title, rep, rare, currency"),
                })

                if why then
                    CN.PrintLine(CN.Muted(why))
                end

                return
            end

            -- Chasing something you have not pinned pins it. Asking for the
            -- path to a thing is the clearest possible statement that you
            -- want it, and making the player run two commands to say so once
            -- is the addon being pedantic at the player's expense.
            if not goals.IsGoal(objectiveType, id) then
                goals.Add(objectiveType, id)
            end

            for _, goal in ipairs(goals.List()) do
                if goal.type == objectiveType and goal.id == id then
                    PrintChain(Chase.Chain(goal))
                    return
                end
            end

            Print("Could not pin that as a goal.")
            return
        end

        local chains = Chase.All()

        if #chains == 0 then
            Print("Nothing pinned. Try |cffffc74f/cn chase mount 1234|r, or")
            Print("|cffffc74f/cn goal <type> <id>|r to pin something first.")
            return
        end

        for _, chain in ipairs(chains) do
            PrintChain(chain)
        end
    end,
}

return Chase
'@

$Embedded['Modules\Progress.lua'] = @'
-- Modules/Progress.lua
-- Completion Navigator :: how much you have actually done.
--
-- REPORTED FROM LIVE PLAY: "It doesn't show how many quests I've completed
-- anymore, which I kinda liked seeing. But my first weekend, I did 350+
-- quests, so I think I can definitely do even more."
--
-- That is the whole design brief in two sentences, and the second one is the
-- important half. He is not asking for a statistic. He is asking for the
-- thing that made him want to beat his own number -- and 0.26.1 took it away
-- while fixing something else, which is a fair trade only if it comes back
-- better.
--
-- Better means: a number the client will vouch for, rather than a count of
-- rows this addon happened to write. `C_QuestLog.GetAllCompletedQuestIDs`
-- returns every quest this character has ever finished. That is the real
-- lifetime total, it is correct on a fresh install with no scan history, and
-- it does not saturate.
--
-- On top of it, the numbers that make a session feel like progress: what you
-- have done since you logged in, what you have done today, and the rate.
-- Those the addon does have to keep itself, so they are stored per character
-- and reset on the game's own clock rather than on a timer of our invention.

local ADDON_NAME, CN = ...

local Progress = CN:RegisterModule("Progress")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- STORAGE
------------------------------------------------------------

local function Store()
    local character = CN.character

    if not character then
        return nil
    end

    character.progress = character.progress or {}

    return character.progress
end

Progress.Store = Store

-- Where the session began. Held in memory only: a session is by definition
-- the thing that ends when you log out.
local sessionStart = {
    completed = nil,
    at        = nil,
}

------------------------------------------------------------
-- THE REAL TOTAL
------------------------------------------------------------

-- Lifetime quests completed by this character, straight from the client.
-- Nil, not zero, when the client will not say -- an unknown total and a
-- total of none are different facts.
--
-- CACHED, and it needed to be.
--
-- `C_QuestLog.GetAllCompletedQuestIDs` does not hand back a number. It builds
-- and returns a table containing every quest the character has ever finished
-- -- tens of thousands of entries for anyone who has played a while, and this
-- addon is aimed squarely at people who have. The Journey tab called it on
-- every refresh to display one integer, allocating and discarding the
-- player's entire quest history to count it.
--
-- The count only changes when a quest is turned in, and the addon already
-- gets told when that happens. So: read it once, keep the number, and throw
-- the cache away on the event that can change it.
-- INVALIDATION, and a trap I walked into while writing it.
--
-- The obvious event list is "anything that could change the count", which
-- includes QUEST_LOG_UPDATE. That event fires many times a second during
-- normal play, so hooking it handed the entire saving straight back -- the
-- benchmark went from 0.000ms to 0.244ms, which is to say back to uncached.
-- A cache invalidated by a firehose is not a cache.
--
-- So: invalidate precisely on the events that certainly change the number,
-- and bound the staleness for anything that slips through. A count that is
-- at most a minute out of date is not a problem; a count that costs the
-- player's entire quest history to display is.
local lifetimeCache = { value = nil, valid = false, at = 0 }

Progress.lifetimeMaxAgeSeconds = 60

function Progress.InvalidateLifetime()
    lifetimeCache.valid = false
    lifetimeCache.value = nil
end

function Progress.LifetimeCompleted()
    if lifetimeCache.valid
        and (time() - lifetimeCache.at) < Progress.lifetimeMaxAgeSeconds then

        return lifetimeCache.value
    end

    local ids = Blizzard.GetAllCompletedQuestIDs()

    -- A NIL ANSWER IS NOT A SETTLED ONE. 0.63.0.
    --
    -- This cached nil as valid, on the argument that a client refusing to
    -- answer is a stable fact. It is not: the ONE moment the client refuses
    -- is early in a login, before quest data has loaded -- and that is
    -- precisely when `BeginSession` takes its baseline. So the baseline was
    -- nil for the whole session, and the branch that reports quests completed
    -- by any means -- including ones the addon saw no event for -- never ran
    -- once.
    --
    -- 0.62.0 taught this to tell "not yet" from "none", and then cached the
    -- "not yet". Nil is left uncached so the next ask gets the real answer,
    -- at a cost of one client call per refresh for the few seconds a login
    -- lasts.
    if not ids then
        lifetimeCache.valid = false
        lifetimeCache.value = nil

        return nil
    end

    lifetimeCache.value = #ids
    lifetimeCache.valid = true
    lifetimeCache.at    = time()

    return lifetimeCache.value
end

------------------------------------------------------------
-- DAY BOUNDARIES
------------------------------------------------------------

-- "Today" means the game's day, which turns over at the daily reset rather
-- than at your local midnight. Using local midnight would show a player a
-- number that disagrees with everything else the game tells them.
function Progress.CurrentDayKey()
    local seconds = Blizzard.GetSecondsUntilDailyReset()

    -- BOTH BRANCHES ON THE SAME SCALE.
    --
    -- The fallback returned `20260822` where the primary returns about
    -- `20687` -- a day index and a calendar number, two different kinds of
    -- integer. One nil answer from the client, which happens during a loading
    -- screen or early in a login, read as a day rollover: the player's count
    -- for today was moved into "yesterday" mid-session and today restarted at
    -- one. The next genuine reset then compared against a key on the wrong
    -- scale and did it again.
    --
    -- Without the reset time the day boundary is unknowable, so the fallback
    -- uses the same day-index arithmetic with no offset. It can be off by
    -- one against the game's day; it cannot be off by six orders of
    -- magnitude.
    --
    -- SAME SCALE WAS NOT ENOUGH. 0.61.0.
    --
    -- The two branches are now the same KIND of integer, which fixed the six-
    -- orders-of-magnitude version of this bug. They are still not the same
    -- NUMBER: `time() / 86400` and `(time() + seconds) / 86400` land on
    -- different day indices for every hour of the day after the reset offset
    -- pushes past midnight UTC -- which is most of the day, for most realms.
    --
    -- So the smaller version of the original bug survived: one nil answer
    -- during a loading screen still flipped the key, moved today's count into
    -- yesterday, and restarted today at one. A player who zoned into a
    -- dungeon watched their daily total reset, which is precisely the
    -- complaint the first fix was written for.
    --
    -- The reset instant is an ABSOLUTE time and it does not move. Read it
    -- once and it can be carried forward through any number of silent
    -- moments, rolled forward a day at a time as it passes. The client's
    -- silence stops being an event.
    local now = time()

    if seconds then
        Progress.knownResetAt = now + seconds
    elseif Progress.knownResetAt then
        -- Carried forward. A day at a time, so a session left running over
        -- several resets still lands on the right one.
        while Progress.knownResetAt <= now do
            Progress.knownResetAt = Progress.knownResetAt + 86400
        end
    else
        -- NEVER READ ONE THIS SESSION, AND THE FALLBACK MUST NOT BE A
        -- DIFFERENT KIND OF ANSWER.
        --
        -- The first version of this returned `math.floor(now / 86400)` while
        -- the normal path returns `math.floor((now + secondsToReset) / 86400)`
        -- -- and those land on different day indices for most of the day on
        -- most realms. So the original bug survived, narrowed: a quest handed
        -- in during the seconds before the client first answers was filed
        -- under one key, the client then answered, the key moved, and the
        -- rollover branch dutifully shovelled today's count into "yesterday"
        -- and restarted today at one. That is the complaint this was written
        -- to fix, in a smaller window.
        --
        -- The fix is to assume a boundary rather than to assume none. The
        -- reset is somewhere in the next 24 hours by definition, so half a
        -- day is the estimate with the smallest worst-case error -- and it is
        -- REMEMBERED, so every reader this session agrees with every other.
        -- The moment the client speaks, the branch above replaces it with the
        -- real instant.
        --
        -- Replacing an estimate with the truth can still move the key once,
        -- which is a real rollover as far as `NoteCompleted` is concerned. So
        -- the estimate is recorded, and the rollover check below skips a
        -- transition out of it: one provisional key, promoted, not a day
        -- boundary crossed.
        Progress.knownResetAt   = now + 43200
        Progress.resetIsEstimate = true

        return math.floor(Progress.knownResetAt / 86400)
    end

    -- Reached only via the two branches above; the client has now spoken at
    -- some point this session.
    --
    -- WRITTEN AS AN `if`, NOT AS `seconds and false or held`.
    --
    -- That idiom cannot produce `false`: `seconds and false` is `false`, and
    -- `false or held` is `held` -- so the flag stayed true forever and the
    -- provisional key was never promoted. It is the single most common Lua
    -- trap there is and I walked straight into it while fixing a different
    -- bug; the suite caught it because the assertion was written first.
    if seconds then
        Progress.resetIsEstimate = false
    end

    -- The reset that is coming, as an absolute time, identifies the day
    -- unambiguously without needing to know the server's timezone.
    return math.floor(Progress.knownResetAt / 86400)
end

-- Whether the day key this session has handed out so far was the estimate
-- rather than the client's own reset instant. In memory deliberately: see
-- `RollDay`.
local estimatedKey = false

-- ONE ROLLOVER, IN ONE PLACE. 0.61.0.
--
-- The day-boundary rule was written out twice -- once in `NoteCompleted` and
-- once in `BeginSession` -- and 0.61.0 was about to make that three times.
-- This project has now found the same "two copies of a rule, one of which
-- nobody updates" defect in the invalidator, the window's refresh events and
-- the collection generation. It is not going to be introduced here on
-- purpose.
--
-- Returns the current day key, having rolled the store over if the day has
-- genuinely changed.
function Progress.RollDay(store)
    local today = Progress.CurrentDayKey()

    if not store then
        return today
    end

    -- A PROVISIONAL KEY BEING REPLACED IS NOT A NEW DAY.
    --
    -- Before the client has said when the reset is, the key is an estimate
    -- (see `CurrentDayKey`). When the real instant arrives the key can move
    -- once, and shovelling today's count into "yesterday" over that is the
    -- exact bug this whole area exists to prevent. Adopt the corrected key
    -- and keep the count.
    --
    -- THE FLAG IS SESSION STATE, NOT SAVED STATE. This lived on `store` for
    -- one draft, and `store` is SavedVariables -- so a session that ended
    -- while the key was still provisional left the flag set on disk, and the
    -- FOLLOWING day's login promoted a genuinely stale key instead of rolling
    -- it over. The player would come back the next morning and find
    -- yesterday's number labelled "today", which is the bug the login
    -- rollover exists to prevent, reintroduced by the fix for a different
    -- one. It is a local, and a new session starts with it clear.
    if store.dayKey ~= today and estimatedKey
        and not Progress.resetIsEstimate then

        store.dayKey = today
    end

    estimatedKey = Progress.resetIsEstimate and true or false

    if store.dayKey ~= today then
        -- A new day. Keep yesterday so "yesterday you did 84" is possible
        -- later, but do not accumulate an unbounded history.
        store.previousDay    = store.today or 0
        store.previousDayKey = store.dayKey
        store.today          = 0
        store.dayKey         = today
    end

    return today
end

------------------------------------------------------------
-- RECORDING
------------------------------------------------------------

-- Called when the client tells us a quest was turned in.
function Progress.NoteCompleted(questID)
    local store = Store()

    if not store then
        return
    end

    local today = Progress.RollDay(store)

    store.today   = (store.today or 0) + 1
    store.session = (store.session or 0) + 1

    -- `store.total` IS NOT WRITTEN ANY MORE. 0.78.0.
    --
    -- Incremented on every turn-in and read by nothing: `Progress.Summary`
    -- takes its lifetime figure from `Progress.LifetimeCompleted()`, which is
    -- the client's own count and which this file's header calls "the real
    -- lifetime total".
    --
    -- Sixth store to lose a field it did not need to keep -- `record.done`,
    -- `zone`, `currencyNames`, `achievementTotals` and the achievement flat
    -- field were the others -- and migration 29 removes it.

    if (store.best or 0) < store.today then
        store.best    = store.today
        store.bestDay = today
    end

    DebugPrint("Quest " .. tostring(questID) .. " completed; "
        .. store.today .. " today.")
end

function Progress.BeginSession()
    local store = Store()

    if store then
        store.session = 0

        -- Roll the day over at login too, so a player who logs in the next
        -- morning does not see yesterday's number labelled "today".
        Progress.RollDay(store)
    end

    -- TAKEN ONCE THE CLIENT CAN ANSWER, NOT ONCE. 0.63.0.
    --
    -- `BeginSession` runs at `PLAYER_LOGIN`, which is inside the window where
    -- the client has not finished loading quest data and correctly answers
    -- "not yet". So the baseline was nil, and stayed nil for the session --
    -- and the branch in `Summary` that reports quests completed by ANY means,
    -- including ones the addon saw no event for, could never run.
    --
    -- Asked here, and asked again by `Progress.NoteBaseline` below when the
    -- client first has an answer. Set once, then left alone: a baseline that
    -- moved would make "this session" shrink.
    sessionStart.completed = Progress.LifetimeCompleted()
    sessionStart.at        = time()
end

-- What the session started from, for anything that needs to reason about the
-- baseline rather than the delta.
function Progress.SessionBaseline()
    return sessionStart.completed
end

-- The first real answer becomes the baseline, if login was too early for one.
--
-- Cheap: it returns immediately once a baseline exists, which is after the
-- first successful ask.
function Progress.NoteBaseline()
    if sessionStart.completed then
        return
    end

    local lifetime = Progress.LifetimeCompleted()

    if not lifetime then
        return
    end

    sessionStart.completed = lifetime

    -- The session began when the player logged in, not when the client
    -- finally answered; `at` was set correctly by `BeginSession` and is left
    -- alone, so the rate is measured over the real session.
    DebugPrint("Session baseline taken late: " .. lifetime
        .. " lifetime completions.")
end

------------------------------------------------------------
-- THE NUMBERS
------------------------------------------------------------

-- Everything worth showing, in one table. Fields are nil rather than zero
-- when the client has not answered, so callers can tell the difference.
function Progress.Summary()
    -- The one place every reader passes through, so the late baseline needs
    -- no event of its own.
    Progress.NoteBaseline()

    local store = Store() or {}

    local summary = {
        lifetime = Progress.LifetimeCompleted(),
        today    = store.today or 0,
        session  = store.session or 0,
        best     = store.best or 0,
        previous = store.previousDay,

        -- What the session started from. Published because "this session"
        -- being a client delta rather than the addon's own tally is a real
        -- distinction, and `/cn navdiag` and the Journey tab both need to be
        -- able to say which one they are showing.
        baseline = Progress.SessionBaseline(),
    }

    -- Prefer the client's own delta for the session where we have it: it
    -- counts quests completed by any means, including ones the addon did not
    -- see an event for.
    if summary.baseline and summary.lifetime then
        local delta = summary.lifetime - summary.baseline

        if delta >= 0 then
            summary.session = math.max(summary.session, delta)
        end
    end

    if sessionStart.at then
        summary.sessionSeconds = time() - sessionStart.at

        -- A rate needs enough time behind it to mean anything. Five minutes
        -- in, "240 quests per hour" is arithmetic, not information.
        if summary.sessionSeconds >= 600 and summary.session > 0 then
            summary.perHour = summary.session / (summary.sessionSeconds / 3600)
        end
    end

    return summary
end

function Progress.Describe()
    local summary = Progress.Summary()

    local parts = {}

    if summary.lifetime then
        table.insert(parts, CN.Comma(summary.lifetime) .. " quests completed")
    end

    table.insert(parts, summary.today .. " today")

    if summary.session > 0 and summary.session ~= summary.today then
        table.insert(parts, summary.session .. " this session")
    end

    if summary.perHour then
        table.insert(parts, string.format("%.0f/hour", summary.perHour))
    end

    return table.concat(parts, ", ")
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Progress.InvalidateLifetime()

    Progress.NoteCompleted(questID)
end)

-- Abandoning a quest cannot lower the completed count, but a fresh login on
-- a different character certainly changes it, and so does the client
-- finishing its initial data load.
CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    Progress.InvalidateLifetime()
end)

-- Deliberately NOT hooked to QUEST_LOG_UPDATE. See the note on the cache:
-- that event fires constantly and hooking it removed the entire benefit.
-- Anything completed by a route the addon cannot see is picked up by the
-- staleness bound instead.

CN:OnLogin(function()
    Progress.BeginSession()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "progress",
    aliases = { "done", "stats" },
    order   = 11,
    help    = "How many quests you have completed: lifetime, today, this session.",
    handler = function()
        local summary = Progress.Summary()

        if summary.lifetime then
            Print("|cffffc74f" .. CN.Comma(summary.lifetime)
                .. "|r quests completed on this character.")
        else
            Print("The client will not report a lifetime total right now.")
        end

        Print("Today: |cffffc74f" .. summary.today .. "|r"
            .. (summary.best > 0 and ("   |cff8a8f96best day: "
                .. summary.best .. "|r") or ""))

        if summary.session > 0 then
            local line = "This session: |cffffc74f" .. summary.session .. "|r"

            if summary.perHour then
                line = line .. string.format(
                    "   |cff8a8f96%.0f per hour|r", summary.perHour)
            end

            Print(line)
        end

        if summary.previous then
            Print("|cff8a8f96Previous day: " .. summary.previous .. "|r")
        end
    end,
}

return Progress
'@

$Embedded['Modules\Loremaster.lua'] = @'
-- Modules/Loremaster.lua
-- Completion Navigator :: finishing zones, continents and expansions.
--
-- FROM A PLAYER'S OWN STATED PLAN:
--
--   "Once I finish the story this weekend, I'm gonna do all the side quests
--    on the continent I'm currently on. Then I'll move from one continent to
--    another. After that, I'm gonna switch timelines and work backwards to
--    the previous expansion... Basically, I'm gonna try to complete every
--    main quest and side quest in the entire game."
--
-- That is a two-year project measured in zones and continents, and the addon
-- had nothing to say about it. It could tell him what to do in the next
-- hundred yards and nothing about where he was in the campaign.
--
-- THE DENOMINATOR PROBLEM, AND WHY THIS WORKS ANYWAY.
--
-- The client will not tell you how many quests exist in a zone. Counting
-- "quests I know about" would produce a denominator that grows as you play,
-- so your percentage would go DOWN as you did more -- which is worse than no
-- percentage at all, and this addon has a standing rule against inventing
-- one.
--
-- But the game already ships the exact tracker this player needs: the quest
-- achievements. "Loremaster of Khaz Algar", the per-zone story achievements,
-- the exploration-style quest counts. Those have criteria the client
-- enumerates and vouches for. So the progress here is real, and it is real
-- because we did not compute it -- we read it.

local ADDON_NAME, CN = ...

local Loremaster = CN:RegisterModule("Loremaster")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local Blizzard = CN.Blizzard

-- Blizzard's "Quests" achievement category. A stable constant for many
-- years, and everything below degrades to "nothing found" rather than to an
-- error if it ever moves.
Loremaster.questCategoryID = 96

-- Published rather than literals, so the retry is a knob the suite can turn.
Loremaster.coldRetrySeconds    = 10
Loremaster.maximumColdAttempts = 3
Loremaster.coldAttempts        = 0

------------------------------------------------------------
-- THE CATEGORY TREE
------------------------------------------------------------

-- Every category descending from Quests: one per expansion, and below those,
-- per continent. Walked rather than hardcoded, so a new expansion needs no
-- code.
function Loremaster.QuestCategories()
    local categories = {}

    if not GetCategoryList or not GetCategoryInfo then
        return categories
    end

    local ok, list = pcall(GetCategoryList)

    if not ok or type(list) ~= "table" then
        return categories
    end

    -- Parentage is only one level per lookup, so resolve to a root by
    -- walking upward. Cheap: the tree is three deep at most.
    local function rootOf(categoryID)
        local guard = 0
        local current = categoryID

        while current and guard < 8 do
            local name, parent = GetCategoryInfo(current)

            if not name then
                return nil
            end

            if current == Loremaster.questCategoryID then
                return current
            end

            if not parent or parent <= 0 then
                return nil
            end

            current = parent
            guard   = guard + 1
        end

        return nil
    end

    for _, categoryID in ipairs(list) do
        if rootOf(categoryID) == Loremaster.questCategoryID then
            local name, parent = GetCategoryInfo(categoryID)

            table.insert(categories, {
                categoryID = categoryID,
                name       = name,
                parentID   = parent,
            })
        end
    end

    return categories
end

------------------------------------------------------------
-- SCANNING
------------------------------------------------------------

local function Records()
    return CN.Account("loremaster")
end

Loremaster.Records = Records

-- The achievement's name, and its category's, from the client. See the note
-- in `Scan`. The stored fallbacks keep an older database readable until its
-- first rescan.
function Loremaster.NameOf(achievementID, record)
    local live = Blizzard.GetAchievementName
        and Blizzard.GetAchievementName(achievementID)

    if live and live ~= "" then
        return live
    end

    return (record and record.name)
        or ("Achievement " .. tostring(achievementID))
end

function Loremaster.CategoryOf(record)
    if type(record) ~= "table" then
        return "Other"
    end

    if record.categoryID and Blizzard.GetCategoryName then
        local live = Blizzard.GetCategoryName(record.categoryID)

        if live and live ~= "" then
            return live
        end
    end

    return record.category or "Other"
end

-- THE STORE HAD NO CHARACTER DIMENSION, AND SAID IT DID. FIXED IN 0.61.0.
--
-- `Loremaster.Scan`'s own comment says the store exists "so the Warband view
-- can show what other characters have finished". It could not: every row was
-- written into the ACCOUNT store under the achievement id alone, so whichever
-- character logged in last overwrote every other character's progress.
--
-- Two players on two characters saw the second one's numbers attributed to
-- both, and the Warband column that this was built for showed the same figure
-- in every row. Nothing caught it because the fixture has one character, and
-- one character cannot overwrite anybody.
--
-- The split follows what the game actually scopes:
--
--   name, category, criteria  -- properties of the achievement. Account.
--   completed                 -- achievements are earned account-wide. Account.
--   done                      -- criteria progress on quest achievements is
--                                CHARACTER-specific. Per character.
--
-- `progress` is a table keyed by character key. `record.done` is kept as the
-- current character's value so nothing downstream had to change shape, and so
-- a database written by an older version still reads correctly until the
-- migration runs.
function Loremaster.DoneFor(record, characterKey)
    if type(record) ~= "table" then
        return 0
    end

    characterKey = characterKey or CN.characterKey or CN.GetCharacterKey()

    if record.progress and record.progress[characterKey] ~= nil then
        return record.progress[characterKey]
    end

    -- No per-character figure: either this character has never scanned, or
    -- the row predates the split. Only the CURRENT character may fall back to
    -- the flat field, because that field holds whoever scanned last -- which
    -- is exactly the bug, and attributing it to a named other character would
    -- keep telling the lie in a new place.
    if characterKey == (CN.characterKey or CN.GetCharacterKey()) then
        return record.done or 0
    end

    return nil
end

-- Reads every quest achievement and stores what the client says about it.
-- Stored rather than recomputed because walking the achievement tree is not
-- something to do on every frame, and because it lets the Warband view show
-- what other characters have finished.
function Loremaster.Scan(fromRetry)
    local store = Records()

    -- COUNTED ONLY WHEN THE RETRY ITSELF IS COLD. 0.75.0.
    --
    -- 0.74.0 incremented on every cold scan and reset only on one that
    -- measured something, so three cold scans anywhere in a session -- `/cn
    -- setup` at login plus two presses of "Rescan zones", which is exactly
    -- what the addon's own messages tell the player to do -- left the counter
    -- spent, and every later cold scan scheduled nothing. The retry died
    -- silently at the moment the player started trying harder.
    --
    -- A scan the player asked for is a fresh start; only the retry chain
    -- counts against itself.
    if not fromRetry then
        Loremaster.coldAttempts = 0
    end

    local scanned = 0

    -- How many rows the client actually answered about. See the marker at
    -- the bottom: a scan that measured nothing must not record itself.
    local measured = 0

    -- Which ids the category walk reached this time, and which CATEGORIES
    -- actually answered. See the prune below: the second is what makes the
    -- first safe to delete against.
    local seen = {}

    local answeringCategories = {}

    for _, category in ipairs(Loremaster.QuestCategories()) do
        local total = select(1, Blizzard.GetCategoryCounts(category.categoryID))

        for index = 1, (total or 0) do
            local achievement = Blizzard.GetAchievementInCategory(
                category.categoryID, index)

            if achievement and achievement.achievementID then
                local id = achievement.achievementID

                local done, criteria = Blizzard.GetAchievementProgress(id)

                local held = store[id] or {}

                -- NEITHER NAME IS STORED. 0.64.0.
                --
                -- Both are LOCALIZED strings the client answers instantly,
                -- and both were being branched on: `ByCategory` groups on the
                -- stored category and `ForZone` substring-matches the stored
                -- achievement name against a LIVE zone name. So a player who
                -- switched client language read English achievement names
                -- under English headings, and `ForZone` matched nothing at
                -- all -- the "This zone" block and the already-here bonus in
                -- `/cn zones` simply disappeared until a rescan.
                --
                -- Sixth store to lose a name it did not need to keep;
                -- migrations 4, 5, 14, 15 and 16 were the others.
                held.categoryID = category.categoryID
                held.completed = achievement.completed and true or false

                -- THE FLAT FIELD IS NO LONGER WRITTEN. 0.66.0. See the same
                -- change in `Exploration.NoteProgress`.
                --
                -- It was kept so pre-migration databases still read, and
                -- `DoneFor` still reads it for that reason -- but writing it
                -- here meant the fallback returned whoever scanned last
                -- rather than something old, so an alt with no entry of its
                -- own was handed the main's criteria count as its own.
                -- NOT OVER GOOD DATA WITH NOTHING. 0.70.0.
                --
                -- `GetAchievementProgress` answers `0, 0` when the criteria
                -- API is unavailable, and this wrote that straight in --
                -- `Closest` filters on `criteria > 0`, so one scan at a cold
                -- moment emptied the whole Journey tab and `/cn zones`, and
                -- stamped the Scans tab "just now" on the way.
                --
                -- The guard `Exploration` has carried since 0.61.0, that
                -- `Achievements` was given in 0.68.0, and that this file's
                -- OWN new sibling forty lines down has -- in the third
                -- writer, thirty lines from the comment naming the other two.
                if criteria and criteria > 0 then
                    held.criteria = criteria

                    held.progress = held.progress or {}
                    held.progress[CN.characterKey or CN.GetCharacterKey()] = done

                    measured = measured + 1
                end

                store[id] = held

                seen[id] = true

                answeringCategories[category.categoryID] = true

                scanned = scanned + 1
            end
        end
    end

    -- AND ONLY WHEN IT MEASURED SOMETHING. 0.71.0.
    --
    -- The marker was written unconditionally, so a scan that ran at a moment
    -- the criteria API would not answer -- which is routine at `PLAYER_LOGIN`
    -- and is the reason the guard above exists -- recorded nothing, stamped
    -- itself as done, and put "just now" on the Scans tab. The login rescan
    -- then never fired again for that character, and `/cn zones` reported
    -- "not started" for every zone it had fully quested, permanently.
    --
    -- The 0.69.0 condition it replaced was accidentally repairing this on the
    -- next login; 0.70.0 removed the repair along with its cost.
    -- INVALIDATED BEFORE THE EARLY RETURN, NOT AFTER IT. 0.73.0.
    --
    -- `Scan` writes `store[id]` for every row it reaches whether or not the
    -- criteria API answered, so the set of records can change on a scan that
    -- measured nothing -- and the invalidation sat below the early return, so
    -- the one scan most likely to have run against a cold client was the one
    -- scan that left a stale index behind.
    Loremaster.ForgetZoneIndex()

    if measured == 0 then
        DebugPrint("Loremaster scan measured nothing; not recording it.")

        -- AND IT TRIES AGAIN. 0.74.0.
        --
        -- 0.73.0 correctly stopped such a scan from recording itself and then
        -- left the player with nothing: the store is no longer EMPTY, because
        -- the walk wrote a row for everything it reached, so the "no data
        -- yet, running a scan" branch never fires again -- and `Closest`
        -- filters on `criteria > 0`, so the Journey tab shows a bare "Here"
        -- row and no zone list, silently, until the next login.
        --
        -- The condition is known to be transient; this file says so in four
        -- separate comments. A retry is the obvious affordance and costs one
        -- timer. Bounded, so a client that will never answer is not asked
        -- forever.
        Loremaster.coldAttempts = (Loremaster.coldAttempts or 0) + 1

        if Loremaster.coldAttempts <= Loremaster.maximumColdAttempts
            and C_Timer and C_Timer.After then

            C_Timer.After(Loremaster.coldRetrySeconds, function()
                CN.Guard("Loremaster.Scan", function()
                    local retried, got = Loremaster.Scan(true)

                    -- AND THE PLAYER IS TOLD IT WORKED. 0.75.0.
                    --
                    -- `/cn setup` and the Rescan button both say "try again
                    -- in a moment" while a retry is already scheduled, and
                    -- 0.74.0's retry succeeded in silence -- leaving the
                    -- player looking at a stale empty list with nothing to
                    -- say the addon had recovered.
                    if (got or 0) > 0 then
                        -- MEASURED, NOT REACHED. 0.76.0. `retried` counts the
                        -- rows the walk went past; a retry against a
                        -- half-warm client that read 40 of 412 announced
                        -- "412". The same mistake fixed at `/cn scanlore` in
                        -- 0.72.0 and at the Rescan button in 0.74.0,
                        -- reproduced in the third site one release later.
                        Print("Zone progress read: " .. got .. " of "
                            .. retried .. " quest achievements. The game is "
                            .. "answering now.")

                        if CN.UI and CN.UI.RequestRefresh then
                            CN.UI.RequestRefresh()
                        end
                    end
                end)
            end)
        end

        -- AND IT SAYS SO OUT LOUD. 0.72.0.
        --
        -- 0.71.0 stopped the marker and went on returning `scanned`, which
        -- counts every row the walk REACHED -- so `/cn scanlore` at a cold
        -- moment printed "Quest achievements scanned: 412" over a store that
        -- had recorded nothing, and the Journey tab stayed empty. A count is
        -- not a result.
        return scanned, 0
    end

    -- WHO HAS SCANNED, RECORDED RATHER THAN INFERRED. 0.70.0.
    --
    -- The login rescan asked "does every row carry this character's
    -- progress?" -- and `Scan` writes progress only for achievements the
    -- category walk returns, so any row it cannot reach this session (a
    -- category the client has not populated yet at login, an achievement
    -- retired in a patch) keeps that entry nil for ever. The condition was
    -- then true on every login of every character, and each firing is the
    -- full tree walk this file says is "why it was never put on an event".
    --
    -- A marker says what actually happened.
    CN.Account("loremasterScans")[CN.characterKey or CN.GetCharacterKey()] =
        time()

    CN.MarkScanned("loremaster")

    Loremaster.coldAttempts = 0

    -- A ROW THE GAME NO LONGER RETURNS IS DELETED. 0.76.0.
    --
    -- This store was write-only for its whole life: `Scan` added rows and
    -- nothing ever removed one, so an achievement retired in a game patch
    -- kept its row for the life of the account -- and the client will never
    -- name that row again.
    --
    -- That one fact is the reason 0.75.0 had to invent a session-local
    -- "which rows has the client ever named" table, exclude those rows from
    -- the "was this walk decisive" test, and add a rule that the walk which
    -- DISCOVERS a refusal must not settle. All of it worked around a dead row
    -- that should not have been there -- and the two-walk settling rule was
    -- itself wrong: two walks inside one cold window marked the whole store
    -- retired and then cached a match list with the zone's own achievement
    -- missing, for the rest of the session.
    --
    -- Deleting the dead row removes the workaround and the defect in the
    -- workaround together. `everNamed` is gone; the test is `named == rows`
    -- again, which is exact.
    --
    -- Only after a scan that measured something, so a cold client never
    -- deletes anything. `progress` for other characters goes with the row,
    -- and that is correct: the achievement no longer exists.
    -- PER CATEGORY, NOT PER SCAN. Corrected in 0.77.0, before it shipped
    -- twice.
    --
    -- 0.76.0 gated this on a whole-store counter and the walk is per
    -- CATEGORY. `QuestCategories` silently drops any category the client has
    -- not populated, and `GetCategoryCounts` answers 0 for one it has not
    -- filled -- so the ordinary half-warm client, where one expansion answers
    -- and three do not, produced `measured > 0` and then deleted every row in
    -- the three that stayed quiet, taking every character's progress with
    -- them. The comment eight lines up warns about exactly that shape as a
    -- stale nil; this had turned it into a delete.
    --
    -- A row is only a candidate for deletion when the category it belongs to
    -- ANSWERED this time. A row with no stored category is never deleted:
    -- there is nothing to check it against.
    for id, record in pairs(store) do
        local categoryID = type(record) == "table" and record.categoryID

        if not seen[id] and categoryID and answeringCategories[categoryID] then
            store[id] = nil
        end
    end

    -- AND A BINDING TO AN ACHIEVEMENT THAT NO LONGER EXISTS IS DROPPED.
    -- 0.75.0.
    --
    -- A game patch can retire a quest achievement. The binding for it would
    -- otherwise sit on disk for the life of the account, excluding nothing
    -- and describing nothing -- dead state that the next reader has to
    -- discover is dead. Only after a scan that measured something, so a cold
    -- client never deletes anything.
    local bindings = Loremaster.Bindings()

    for achievementID in pairs(bindings) do
        if not store[achievementID] then
            bindings[achievementID] = nil
        end
    end

    DebugPrint("Loremaster scan: " .. scanned .. " quest achievements.")

    return scanned, measured
end

------------------------------------------------------------
-- GROUPING
------------------------------------------------------------

-- Quest achievements grouped by the category they live in -- which is to say,
-- by expansion and continent, because that is how Blizzard files them and
-- how the player thinks about them.
function Loremaster.ByCategory(includeCompleted)
    local groups, order = {}, {}

    for id, record in pairs(Records()) do
        if includeCompleted or not record.completed then
            local key = Loremaster.CategoryOf(record)

            if not groups[key] then
                groups[key] = {}
                table.insert(order, key)
            end

            table.insert(groups[key], {
                id        = id,
                name      = Loremaster.NameOf(id, record),
                completed = record.completed,
                done      = Loremaster.DoneFor(record) or 0,
                criteria  = record.criteria or 0,
            })
        end
    end

    table.sort(order)

    for _, key in pairs(order) do
        table.sort(groups[key], function(a, b)
            local left  = (a.criteria or 0) > 0 and (a.done / a.criteria) or -1
            local right = (b.criteria or 0) > 0 and (b.done / b.criteria) or -1

            if left ~= right then
                return left > right
            end

            return tostring(a.name) < tostring(b.name)
        end)
    end

    return groups, order
end

-- The ones worth finishing next: started, not finished, closest first.
-- An untouched zone is not "nearly done", so it sorts below one you have
-- already put an evening into.
-- The zones nearest to finished.
--
-- TWO BUGS LIVED HERE.
--
-- The first: this sorted candidates carefully by completion fraction and then
-- handed the list to CN.CapCandidates, which re-sorts by `completionValue` --
-- a field these rows do not have. Every row therefore compared equal and the
-- tie-break took over, silently reordering the whole list alphabetically by
-- achievement ID whenever there were more rows than the limit. The careful
-- ordering above it was thrown away exactly when it mattered.
--
-- The second was worse for anyone actually working through content: rows with
-- `done == 0` were excluded, so a zone you had never set foot in could never
-- be recommended. For a player sweeping a continent, the untouched zones are
-- precisely the ones they need to be pointed at.
--
-- Untouched zones are now included and ranked separately, because "you are
-- 90% through this one" and "you have not started this one" are different
-- suggestions and blending them by fraction would bury every fresh zone under
-- every half-finished one forever.
-- NAMES ARE RESOLVED FOR THE ROWS THAT SURVIVE, NOT FOR THE STORE. 0.72.0.
--
-- Both `Loremaster.NameOf` and `Loremaster.CategoryOf` are `pcall` plus a
-- client call, and this resolved both for EVERY unfinished record before
-- sorting and throwing all but `limit` away. Several hundred rows on a mature
-- account, twice each, on a function the Journey tab calls from every
-- `UI.Refresh` -- which data events drive as often as every two seconds.
--
-- Sorting on the numbers, truncating, and naming what is left makes that
-- O(limit) client calls instead of O(store). The tie-breaks that used the
-- name now use the id, which is stable, free, and just as deterministic.
--
-- AND THE UNTOUCHED HALF IS NO LONGER TRUNCATED AWAY.
--
-- The two lists were concatenated and cut from the end, so an account with
-- `limit` or more partly-done zones lost every untouched one -- and
-- `NextZones` asks for 50, which is an ordinary number of started zones for
-- the completionist this file was written for. The header below says a zone
-- you have never set foot in must be recommendable; it was not, for exactly
-- the players it was written for. Each half now keeps its own share.
function Loremaster.Closest(limit, freshShare)
    local started, untouched = {}, {}

    for id, record in pairs(Records()) do
        local done = Loremaster.DoneFor(record) or 0

        -- NOTHING LEFT IS NOT "CLOSEST TO FINISHING". 0.71.0.
        --
        -- The candidate provider has always carried this rule -- `if
        -- remaining <= 0 ... return` -- and the two DISPLAY paths did not, so
        -- a row whose criteria are all done but whose earned flag is stale
        -- sorted to the top of `/cn zones` with the reason "100% done --
        -- finishing is cheaper than starting", and to the top of the Journey
        -- tab's "closest to finished" printed as 60/60 in the unfinished
        -- colour. The addon telling the player, first, to go and finish a
        -- zone with nothing in it.
        --
        -- The same rule written twice, and the third copy is in `Exploration`
        -- with the same omission.
        if not record.completed and (record.criteria or 0) > 0
            and done < record.criteria then

            local row = {
                id       = id,
                record   = record,
                done     = done,
                criteria = record.criteria,
                fraction = done / record.criteria,
            }

            if row.done > 0 then
                table.insert(started, row)
            else
                table.insert(untouched, row)
            end
        end
    end

    local function byProgress(a, b)
        if a.fraction ~= b.fraction then
            return a.fraction > b.fraction
        end

        return (a.criteria - a.done) < (b.criteria - b.done)
    end

    table.sort(started, byProgress)

    -- Smallest first among the untouched: a fresh zone with twenty quests is
    -- a better next step than one with ninety.
    table.sort(untouched, function(a, b)
        if a.criteria ~= b.criteria then
            return a.criteria < b.criteria
        end

        return a.id < b.id
    end)

    -- Truncate. Deliberately NOT CN.CapCandidates: that re-sorts, and the
    -- ordering above is the entire product of this function.
    limit = limit or 10

    -- RESERVED ONLY WHEN THE CALLER ASKS FOR IT. 0.73.0.
    --
    -- 0.72.0 applied the reserve to every caller, and two of the three are
    -- headed "Closest to finished" -- the Journey tab and `/cn loremaster`.
    -- So a player with plenty of half-done zones read three rows of `0 / 120`
    -- with an empty bar under that heading, while three genuinely nearly-done
    -- zones were pushed off the list to make room for them.
    --
    -- `NextZones` is the caller the reserve was written for: it is the one
    -- that scores untouched zones on their own terms and labels them "not
    -- started, N to do". It asks for the reserve explicitly now.
    local fresh = math.min(#untouched, freshShare or 0)

    local room = math.max(0, limit - fresh)

    local ordered = {}

    for index = 1, math.min(#started, room) do
        table.insert(ordered, started[index])
    end

    -- AND THE FILL RESPECTS THE SHARE TOO. 0.74.0.
    --
    -- 0.73.0 made the RESERVE opt-in and left the FILL unbounded, so any
    -- account with fewer started zones than the limit -- a new player, an
    -- alt, anyone mid-expansion -- still read rows of `0 / 120` with an empty
    -- bar under a heading that says "Closest to finished". Less common than
    -- before, and the same wrong thing.
    --
    -- Both callers already receive `#started` and `#untouched` and can say
    -- "Not started" over their own section; see the Journey tab.
    for index = 1, math.min(#untouched, fresh, limit - #ordered) do
        table.insert(ordered, untouched[index])
    end

    -- The client calls, at last, and only for what is being shown.
    for _, row in ipairs(ordered) do
        row.name     = Loremaster.NameOf(row.id, row.record)
        row.category = Loremaster.CategoryOf(row.record)
        row.record   = nil
    end

    return ordered, #started, #untouched
end

-- WHICH RECORD THIS ZONE IS, LEARNED BY MAP ID. Rewritten in 0.71.0.
--
-- Three releases have claimed to fix a reported symptom -- "the completion of
-- a quest does not appear to remove it from the journey" -- and none of them
-- worked. 0.69.0 listened for the wrong event. 0.70.0 fixed the event and
-- introduced this lookup, which was inert in two separate ways:
--
--   1. It keyed on `GetMapName(GetBestMapForUnit(...))`, which answers with
--      the CITY when the player is standing in one -- and this file's own
--      neighbour says so in as many words. No achievement contains
--      "Dornogal", so the whole path did nothing for any turn-in made in a
--      capital, which is where campaign turn-ins happen.
--
--   2. It refused whenever two achievements contained the zone name, on the
--      grounds that duplicate ZONE names are ambiguous -- and every modern
--      zone ships a story achievement AND a "Sojourner of <Zone>" companion,
--      so it refused everywhere. `ForZone` picked one happily for display, so
--      the tab showed a count that nothing ever moved.
--
-- `Exploration.ForCurrentZone` has solved this since 0.62.0 and this is that
-- solution, not a third invention: the zone name must appear as a whole word
-- run anchored at the END of the achievement name.
--
-- WHAT 0.71.0 THEN GOT WRONG ABOUT REMEMBERING THE ANSWER, fixed in 0.72.0.
--
-- It matched on `GetZoneText()` -- correctly -- and then cached the answer
-- under `CN.GetPlayerPosition()`, which is `GetBestMapForUnit`: the CITY map
-- indoors. That is the same wrong value defect (1) above is about, moved from
-- the match to the memory of it, and it is the fourth time this one map call
-- has been used for a question it does not answer.
--
-- Three things followed. The cache never converged, because walking out of a
-- building missed and re-stamped a different id, so the walk it exists to
-- avoid ran on every threshold. The stamp was PERSISTED, so it wrote a
-- SavedVariable on every zone transition. And because "unfinished first" can
-- change its mind when the story achievement completes, one zone could end up
-- with two records holding two map ids -- the completed one indoors and the
-- companion outdoors -- so the tab showed a different achievement depending
-- on which side of a doorway the player stood. Exactly the hash-order
-- symptom 0.71.0 set out to remove, reintroduced by the fix for it.
--
-- The key is now the zone name, which is what the match was actually made on,
-- and the cache is SESSION-LOCAL. A name is a display string and this file
-- never branches on it -- it is a cache key, and the walk that fills it is
-- the same walk that would run without it. Nothing about a localized string
-- is worth writing to disk, and a session is exactly as long as the answer
-- stays true.
local zoneIndex = {}


-- Only a change to WHICH RECORDS EXIST invalidates this -- a scan. Earning
-- an achievement does not, because the winner is chosen fresh on every
-- lookup; see the note inside `ZoneRecord`.
function Loremaster.ForgetZoneIndex()
    zoneIndex = {}
end

-- NO LOADING-SCREEN WIPE. 0.74.0. See the acceptance test in `ZoneRecord`:
-- refusing to remember an indecisive walk is cheaper and more direct than
-- remembering it and then throwing the whole index away on an event.

-- WHICH OF TWO LEGITIMATE ZONE MATCHES IS THE ZONE'S OWN. 0.71.0.
--
-- Every modern zone has more than one achievement whose name ends in the zone
-- name: the story one and its "Sojourner of <Zone>" companion, at least. Both
-- are legitimate matches, so SOMETHING has to choose, and what it must not
-- choose by is whichever `pairs` reached first -- that shows a different zone
-- achievement on different logins with nothing having changed, and it is the
-- reason this is a named function with its own test rather than four lines
-- inside a loop where only the hash order could observe it.
--
-- The order, in full:
--   1. an unfinished one beats a finished one -- the tab is about what is
--      left, and a completed zone achievement has nothing left to say;
--   2. then the SHORTER name, which is the one about the zone rather than
--      about the zone plus a side collection;
--   3. then the lower ID, so that two achievements with names of equal length
--      still resolve the same way every time.
--
-- Every step is total and deterministic; there is no path that returns "I
-- cannot tell", because refusing is what made 0.70.0 do nothing everywhere.
-- WHICH ACHIEVEMENT A ZONE IS, LEARNED FROM EVIDENCE. 0.74.0.
--
-- WHY THE 0.73.0 ANSWER WAS INERT.
--
-- 0.73.0 broke the tie between two zones sharing a name by comparing the
-- achievement's category name with the name of the continent the player is
-- standing on. The premise was that the quest category tree is
-- Quests > continent. It is not. On retail the children of category 96 are
-- EXPANSIONS -- "Warlords of Draenor", "Burning Crusade", "Legion" -- and
-- only Classic has a continent level beneath it. So for every collision the
-- release was written for:
--
--   Draenor's Nagrand   continent "Draenor"      category "Warlords of Draenor"
--   Outland's Nagrand    continent "Outland"      category "Burning Crusade"
--   Legion Dalaran       continent "Broken Isles" category "Legion"
--
-- neither side matched, both answers were false, and the branch never fired.
-- A release whose headline was "zone identity, for the fourth and last time"
-- shipped a comparison that could not fire in any case it was written for --
-- and, where it COULD fire, fired wrongly: the only categories that ever
-- match a continent name are Classic's two, and the test sat ABOVE the
-- unfinished-beats-finished rule, so a Cataclysm-revamped zone lost to
-- anything filed under "Kalimdor".
--
-- It was also two localized strings being compared to decide a branch, which
-- is the one thing this project has a standing rule against, in the one place
-- the rule warns about.
--
-- WHAT REPLACES IT.
--
-- There is no client call that says which zone a quest achievement belongs
-- to. There is, however, evidence: when the player's criteria progress on
-- exactly one candidate MOVES while they are standing in a given zone, that
-- candidate is that zone's achievement. Nothing else can produce that.
--
-- So the binding is learned rather than derived, filed under the zone's own
-- map id -- which cannot be duplicated -- and it is the only thing in this
-- store that IS persisted, because it is the one fact here the client cannot
-- hand back. Until the evidence arrives the ordering below is unchanged:
-- deterministic, stable across logins, and occasionally wrong about which of
-- two Nagrands you meant. That is honest, and it stops being wrong the first
-- time the player turns a quest in there.
-- WHICH ZONE AN ACHIEVEMENT BELONGS TO, LEARNED FROM EVIDENCE. 0.75.0.
--
-- INVERTED FROM 0.74.0, WHICH HAD THE RELATION THE WRONG WAY ROUND.
--
-- 0.74.0 stored zone -> achievement and let a binding PROMOTE that
-- achievement above every other rule. Two things went wrong with that, and
-- both of them fired in ordinary play rather than in the rare case the
-- mechanism was written for:
--
--   1. The learning path ran in EVERY zone, because its guard was "more than
--      one candidate" -- and this file says two paragraphs further up that
--      every modern zone has at least two: its story achievement and its
--      "Sojourner of <Zone>" companion. Those are not rivals; they are both
--      this zone's. So the first quest of either kind, turned in alone, bound
--      the zone to whichever it happened to be. Once a bound Sojourner was
--      earned, the "Here" row showed it green at 24/24 for ever while the
--      zone's Loremaster achievement sat at 30 of 60, unmentioned, and the
--      provider stopped offering the zone at all.
--
--   2. It was absolute. A binding outranked unfinished-beats-finished, which
--      is the rule that makes the tab about what is LEFT.
--
-- The relation that is actually true is the other one: an achievement belongs
-- to a zone. Stored that way it EXCLUDES rather than promotes -- a candidate
-- known to belong to a different zone map is not a candidate here -- and
-- everything else is left to the ordering that was already correct.
--
-- That makes the two cases behave differently, which is the point:
--
--   Two Nagrands: Outland's achievement is learned to belong to Outland's
--   map, so standing in Draenor's it is excluded and Draenor's is all that
--   is left. This is the case the mechanism exists for.
--
--   Story and Sojourner: both belong to the SAME map, so neither is ever
--   excluded and the shortest-name rule decides, exactly as before. The
--   mechanism cannot do harm here, by construction, rather than by a guard
--   somebody has to remember.
--
-- Self-healing, too: a binding is re-learned from newer evidence, so a wrong
-- one corrects itself the next time a quest is handed in. `/cn zones forget`
-- clears them all for a player who wants to start over.
local function Bindings()
    return CN.Account("achievementZones")
end

Loremaster.Bindings = Bindings

-- Whether THIS character has ever read its own criteria progress. The
-- sibling of `Achievements.HasScanned`, and the reason `loremasterScans`
-- exists; `Setup` asks both now rather than reading an account-wide stamp.
function Loremaster.HasScanned(characterKey)
    characterKey = characterKey or CN.characterKey or CN.GetCharacterKey()

    return CN.Account("loremasterScans")[characterKey] ~= nil
end

function Loremaster.ForgetBindings()
    -- Forgetting what was learned also forgets that it was attempted, so
    -- `/cn zones forget` starts the learning over rather than waiting out a
    -- throttle for a zone whose answer the player has just discarded.
    Loremaster.ForgetLearningAttempts()

    local store = Bindings()

    local cleared = 0

    for key in pairs(store) do
        store[key] = nil
        cleared = cleared + 1
    end

    return cleared
end

-- The zone map this achievement has been shown to belong to, or nil.
function Loremaster.ZoneOfAchievement(achievementID)
    if not achievementID then
        return nil
    end

    return Bindings()[achievementID]
end

-- LEARNED ONLY FROM A READING THAT ACTUALLY CHANGED, against a baseline that
-- was actually recorded. Re-learned from newer evidence rather than held.
function Loremaster.Bind(achievementID, zoneMapID)
    if not achievementID or not zoneMapID then
        return false
    end

    if Bindings()[achievementID] == zoneMapID then
        return false
    end

    Bindings()[achievementID] = zoneMapID

    return true
end

function Loremaster.BetterZoneMatch(record, name, id, best, bestName, bestID)
    -- A HELD CANDIDATE WITH NO NAME IS NOT A HELD CANDIDATE. 0.72.0.
    --
    -- This is called from one place with three variables that are always set
    -- together, so the `not best` test was enough -- but it is a published
    -- function with its own test, which is an invitation to call it from a
    -- second place, and `#bestName` on a nil throws rather than degrading.
    if not best or not bestName or not bestID then
        return true
    end

    -- NO BINDING RULE HERE ANY MORE. 0.75.0.
    --
    -- 0.74.0 put one at the top, absolute, and it promoted the wrong
    -- achievement in every ordinary zone -- see the header on `Bindings`. A
    -- candidate known to belong somewhere else is now removed from the list
    -- BEFORE this function sees it, which is a filter rather than a
    -- preference, and leaves this ordering as it was when it was correct.
    local heldDone = best.completed and true or false
    local mineDone = record.completed and true or false

    if heldDone ~= mineDone then
        return not mineDone
    end

    if #name ~= #bestName then
        return #name < #bestName
    end

    return id < bestID
end

-- `zone` is the name to match on and `key` is what the answer is filed
-- under. Both default to the zone the player is standing in. A caller asking
-- about SOMEWHERE ELSE must supply both, because the player's own zone id is
-- not an identity for a zone they are not in -- which is how the first draft
-- of this filed Eversong Woods' answer under Isle of Dorn.
local function ZoneRecord(zone, key)
    if not zone then
        zone = GetZoneText and GetZoneText()

        key = key or (Blizzard.ZoneMapID
            and Blizzard.ZoneMapID(CN.GetPlayerPosition()))
    end

    if not zone or zone == "" then
        return nil
    end

    key = key or zone

    local store = Records()

    -- WHAT IS CACHED IS THE MATCH, NOT THE WINNER.
    --
    -- The two halves of this answer age differently. WHICH achievements are
    -- named after this zone depends only on their names, which do not change
    -- while the client is running -- and finding them is the whole expense:
    -- a walk of the store with a `pcall` and a client call per row. WHICH of
    -- those is the zone's own depends on `completed`, which changes the
    -- instant the player earns one.
    --
    -- Caching the winner, as the first draft of this did, made the second
    -- fact as stale as the first: earning the story achievement left the tab
    -- showing it at 60/60 while its companion sat open and unmentioned, until
    -- the next login. Caching only the candidate list keeps the expensive
    -- half and re-decides the cheap half every time -- a loop over two or
    -- three entries with no client calls in it.
    -- FILED UNDER THE ZONE'S OWN MAP ID WHERE THERE IS ONE. 0.73.0.
    --
    -- The name is what the match is MADE on and stays so. It is the wrong
    -- thing to file the result under: two zones called Nagrand would share
    -- one entry, and a player walking from one to the other would be handed
    -- the other one's candidate list. `Blizzard.ZoneMapID` walks up to the
    -- first ancestor the client itself calls a zone, so it answers with the
    -- ZONE even when the player is standing in a building inside it -- which
    -- is the distinction the last three releases kept getting wrong.
    local needle = string.lower(zone)

    -- A COMPOSITE KEY, NOT AN EXCLUSIVE ONE. 0.75.0.
    --
    -- 0.74.0 filed the match list under the map id and rejected it on read
    -- when the stored needle differed. In a dungeon or raid whose map parents
    -- into its outdoor zone -- most modern ones -- `ZoneMapID` answers with
    -- the ZONE and `GetZoneText` with the instance, so those two always
    -- differ: every lookup inside missed AND overwrote the outdoor zone's
    -- good entry with the instance's empty one, and walking back out missed
    -- and re-stamped. The index never converged, in the places
    -- `CRITERIA_UPDATE` fires hardest -- which is the exact failure the
    -- caching scheme before it was replaced for.
    --
    -- Putting the needle IN the key keeps both properties instead of trading
    -- one for the other: two Nagrands still get separate entries because
    -- their map ids differ, and a dungeon and the zone around it each hold
    -- their own.
    -- THE KEY AND THE VALUE COME FROM DIFFERENT CLIENT CALLS. 0.74.0.
    --
    -- `key` comes from the map and `matches` is derived entirely from the
    -- NAME, and the two can disagree: during a loading screen the map is nil
    -- and the key falls back to the name, so one zone acquires two entries;
    -- and `ForZone(mapID)` resolves the name of a micro map while keying on
    -- the ZONE above it, which files an empty match list under the enclosing
    -- zone -- making that zone's achievement vanish from the tab until the
    -- entry is dropped.
    --
    -- Storing the needle beside the list makes the pairing an invariant that
    -- is checked rather than an assumption that holds until it does not.
    local slot = tostring(key) .. "|" .. needle

    local held = zoneIndex[slot]

    local matches = held and held.zone == needle and held.matches or nil

    if not matches then

        local function Names(candidate)
            if not candidate then
                return false
            end

            candidate = string.lower(candidate)

            if candidate == needle then
                return true
            end

            -- Ends with the zone name, preceded by a space: "Loremaster of
            -- Nagrand" matches "Nagrand", and an achievement about Shadowmoon
            -- Valley does not match "Shadowmoon".
            return string.sub(candidate, -(#needle + 1)) == (" " .. needle)
        end

        matches = {}

        -- HOW MANY ROWS THE CLIENT ACTUALLY NAMED. See the guard below.
        local named, rows = 0, 0

        for id, record in pairs(store) do
            rows = rows + 1

            local live = Blizzard.GetAchievementName
                and Blizzard.GetAchievementName(id)

            if live and live ~= "" then
                named = named + 1
            end

            -- THE ANSWER ALREADY IN HAND, NOT A SECOND CALL FOR IT. 0.74.0.
            --
            -- 0.73.0 added the counter above and then called
            -- `Loremaster.NameOf`, which asks the client for the very same
            -- name again -- a second `pcall(GetAchievementInfo)` per row, on
            -- the walk this file calls "the whole expense". It doubled the
            -- cost of the thing it was written to make safe.
            local heldName = (live and live ~= "" and live)
                or Loremaster.NameOf(id, record)

            if Names(heldName) then
                table.insert(matches, { id = id, name = heldName })
            end
        end

        -- A WALK THE CLIENT REFUSED IS NOT AN ANSWER, AND MUST NOT BE KEPT.
        -- 0.73.0.
        --
        -- Achievement names are not stored -- since 0.64.0 they are asked for
        -- every time -- so when the client will not answer, which is routine
        -- for a window after a loading screen and is what every other guard
        -- in this file exists for, every row resolves to "Achievement 12345"
        -- and nothing matches. 0.72.0 then cached that empty result
        -- deliberately, for the session.
        --
        -- The Loremaster provider declares `ZONE_CHANGED_NEW_AREA`, so its
        -- first rebuild after a loading screen runs this walk at exactly that
        -- cold moment. One badly-timed zone change and the Journey tab's
        -- "Here" row, the "This zone" block, the provider's rows and the
        -- turn-in refresh were all silently gone until the next login.
        -- REMEMBERED ONLY WHEN THE CLIENT ANSWERED FOR EVERY ROW. 0.74.0.
        --
        -- 0.73.0 tested `named == 0`, which misses the case that actually
        -- happens. The client warming up answers for SOME rows and not
        -- others, so the walk finds a few names, misses the zone's own, and
        -- caches a wrong answer that an `== 0` guard waves straight through.
        --
        -- 0.73.0 covered that by wiping the whole index on
        -- `PLAYER_ENTERING_WORLD` -- every loading screen, portal, hearth and
        -- boat -- each one paying for a full store walk in the first seconds
        -- after the screen clears, which is precisely when the client is
        -- least able to answer. An event that undoes a bad decision after the
        -- fact, at the moment the bad decision is most likely.
        --
        -- The exact test is not a ratio, which would be a number picked out
        -- of the air. It is: did the client answer for everything it was
        -- asked about? If so this walk is as good as any later one and is
        -- worth keeping. If not, the answer is still RETURNED -- a partial
        -- list is more likely right than nothing, and refusing would blank
        -- the tab -- but it is not committed to memory, so the next lookup
        -- asks again rather than inheriting a guess.
        -- REMEMBERED ONLY WHEN THE CLIENT ANSWERED FOR EVERY ROW. 0.76.0.
        --
        -- Exactly 0.74.0's test, restored. 0.75.0 had to loosen it because
        -- this store kept rows for achievements retired in a game patch,
        -- which the client will never name -- so "every row answered" was
        -- permanently false and the cache permanently empty.
        --
        -- What replaced it was worse: rows the client refused were marked
        -- provisionally retired and excluded from the denominator, so TWO
        -- walks inside one cold window -- which is the ordinary case, since
        -- the provider rebuild and the tab refresh both land in the same
        -- second after a loading screen -- marked the whole store retired and
        -- then cached a match list missing the zone's own achievement, for
        -- the rest of the session.
        --
        -- `Scan` deletes rows the game no longer returns now, so the exact
        -- test is reachable again and the workaround is gone.
        --
        -- The answer is still RETURNED when the walk is not decisive -- a
        -- partial list beats a blank tab -- it is simply not committed, so
        -- the next lookup asks again rather than inheriting a guess.
        local decisive = (named == rows)

        if not decisive then
            DebugPrint("Loremaster zone walk: the client named " .. named
                .. " of " .. rows .. "; answering but not remembering it.")
        end

        -- Sorted so the list itself does not carry hash order into anything
        -- that reads it, and remembered even when EMPTY: a dungeon, a raid
        -- and a capital have no achievement named after them, and those are
        -- the places `CRITERIA_UPDATE` fires hardest, so caching only the
        -- hits would leave the full walk running on the events that can
        -- least afford it.
        table.sort(matches, function(a, b) return a.id < b.id end)

        if decisive then
            zoneIndex[slot] = { zone = needle, matches = matches }
        end
    end

    -- A CANDIDATE KNOWN TO BELONG SOMEWHERE ELSE IS NOT A CANDIDATE HERE.
    -- 0.75.0.
    --
    -- The only thing a binding does. Nothing is promoted, so a binding
    -- learned in an unambiguous zone -- where both candidates belong to this
    -- same map -- excludes neither and changes nothing.
    local here = type(key) == "number" and key or nil

    local best, bestID, bestName

    for _, match in ipairs(matches) do
        local record = store[match.id]

        local belongsTo = here and Loremaster.ZoneOfAchievement(match.id)

        if record and (not belongsTo or belongsTo == here)
            and Loremaster.BetterZoneMatch(record, match.name, match.id,
                                           best, bestName, bestID) then

            best, bestID, bestName = record, match.id, match.name
        end
    end

    return best, bestID, matches, key
end

Loremaster.ZoneRecord = ZoneRecord

-- ONE LOOKUP, USED BY THE DISPLAY AND BY THE WRITE. 0.71.0.
--
-- `ForZone` had its own copy of the name match, and 0.70.0 added a second,
-- stricter one for the write path -- so the tab picked a record and the
-- refresh picked nothing, and the number on screen was one nothing could
-- move. Two copies of one rule, drifted before the release that added the
-- second one had shipped.
--
-- The `mapID` argument survives for callers that ask about a zone they are
-- not standing in; the current-zone case, which is every caller today, goes
-- through the learned index.
function Loremaster.ForZone(mapID)
    local record, id

    -- ONE MATCH, ONE ORDERING, ONE PLACE. 0.72.0.
    --
    -- This branch used to carry its own copy of both: a PLAIN SUBSTRING test
    -- where the current-zone path anchors at the end, and an inlined
    -- duplicate of `BetterZoneMatch`. So a caller asking about "Shadowmoon"
    -- got Shadowmoon Valley, and the two orderings were already free to
    -- drift -- in a release whose notes say "one lookup now".
    --
    -- It was also unreachable: every caller in the addon passes nothing.
    -- Untested code that gives a different answer from its neighbour, sitting
    -- where the next caller will find it.
    if mapID and mapID ~= CN.GetPlayerPosition() then
        -- RESOLVED FIRST, SO A MAP WITH NO NAME IS AN ANSWER OF NONE. 0.73.0.
        --
        -- `ZoneRecord` defaults a nil argument to `GetZoneText()`, so passing
        -- the result of a failed `GetMapName` straight in handed a caller
        -- asking about zone X the record for the zone the player is standing
        -- in, with nothing saying so.
        local named = Blizzard.GetMapName(mapID)

        if not named or named == "" then
            return nil
        end

        record, id = ZoneRecord(named,
            (Blizzard.ZoneMapID and Blizzard.ZoneMapID(mapID)) or mapID)
    else
        record, id = ZoneRecord()
    end

    if not record or not id then
        return nil
    end

    return {
        id        = id,
        name      = Loremaster.NameOf(id, record),
        completed = record.completed,
        done      = Loremaster.DoneFor(record) or 0,
        criteria  = record.criteria or 0,
    }
end

------------------------------------------------------------
-- WHICH ZONE NEXT
------------------------------------------------------------

-- The addon could answer "what next" and "where in this zone", and had
-- nothing at all to say about "which zone".
--
-- That is the question somebody working through a continent asks every time
-- they finish one, and answering it badly is worse than not answering: the
-- wrong zone is twenty minutes of flying and a level range that wastes the
-- quests. So it is built from things the client will actually vouch for --
-- how much of each zone's quest achievement is done, how big what remains
-- is, and whether the zone feeds something you said you were chasing -- and
-- it says which of those reasons applied.

-- A zone you are most of the way through beats a fresh one, because
-- finishing is cheaper than starting and leaves fewer loose ends behind.
Loremaster.nearlyDoneFraction = 0.6

function Loremaster.NextZones(limit)
    -- The one caller that wants room held for zones not yet begun; see the
    -- note on `Closest`. A quarter of the list, which is the share a player
    -- sweeping a continent needs and the two "closest to finished" surfaces
    -- must not have.
    local rows = Loremaster.Closest(50, 12)

    local chased = {}

    -- Anything pinned as a goal makes the zone that serves it worth more.
    local goals = CN:GetModule("Goals")

    if goals then
        for _, goal in ipairs(goals.List()) do
            if goal.type == CN.objectiveTypes.ACHIEVEMENT then
                chased[goal.id] = true
            end
        end
    end

    local currentZone = Loremaster.ForZone()

    -- THE ZONE YOU ARE STANDING IN IS ALWAYS A CANDIDATE. 0.72.0.
    --
    -- "You are already here" is worth two points and costs nothing to act on,
    -- and it could only be awarded to a zone that had already survived the
    -- truncation above -- so on the account with the most zones in progress,
    -- which is the one that most needs the advice, the cheapest suggestion
    -- available was the one most likely to be cut before it could be made.
    local carrying = false

    for _, row in ipairs(rows) do
        if currentZone and row.id == currentZone.id then
            carrying = true
            break
        end
    end

    if currentZone and not carrying and (currentZone.criteria or 0) > 0
        and not currentZone.completed
        and currentZone.done < currentZone.criteria then

        table.insert(rows, {
            id       = currentZone.id,
            name     = currentZone.name,
            category = Loremaster.CategoryOf(Records()[currentZone.id]),
            done     = currentZone.done,
            criteria = currentZone.criteria,
            fraction = currentZone.done / currentZone.criteria,
        })
    end

    local scored = {}

    for _, row in ipairs(rows) do
        local reasons = {}

        local value = 0

        if row.fraction >= Loremaster.nearlyDoneFraction then
            value = value + 3
            table.insert(reasons, string.format(
                "%s done" .. CN.DASH .. "finishing is cheaper than starting",
                CN.PercentText(row.fraction)))
        elseif row.done > 0 then
            value = value + 1
            table.insert(reasons, string.format("%d of %d done",
                row.done, row.criteria))
        else
            table.insert(reasons, string.format(
                "not started, %d to do", row.criteria))
        end

        if chased[row.id] then
            value = value + 4
            table.insert(reasons, "you are chasing this")
        end

        -- The zone you are standing in costs nothing to reach.
        if currentZone and currentZone.id == row.id then
            value = value + 2
            table.insert(reasons, "you are already here")
        end

        -- A small remainder is a session; a large one is a project.
        local remaining = row.criteria - row.done

        if remaining <= 5 then
            value = value + 1
            table.insert(reasons, remaining .. " left")
        end

        table.insert(scored, {
            id        = row.id,
            name      = row.name,
            done      = row.done,
            criteria  = row.criteria,
            fraction  = row.fraction,
            remaining = remaining,
            value     = value,
            here      = currentZone and currentZone.id == row.id or false,
            reasons   = reasons,
        })
    end

    table.sort(scored, function(a, b)
        if a.value ~= b.value then
            return a.value > b.value
        end

        if a.fraction ~= b.fraction then
            return a.fraction > b.fraction
        end

        return tostring(a.name) < tostring(b.name)
    end)

    limit = limit or 5

    while #scored > limit do
        table.remove(scored)
    end

    return scored
end

CN:RegisterCommand{
    name    = "zones",
    aliases = { "nextzone", "wherenext" },
    args    = "[forget]",
    order   = 15,
    help    = "Which zone to work on next, and why.",
    handler = function(args)
        -- A WAY OUT OF A WRONG BINDING. 0.75.0.
        --
        -- 0.74.0 published `ForgetBindings` with a comment saying it was
        -- there "so `/cn reset` can clear what was learned" -- and there is
        -- no `/cn reset` in this addon and nothing called it. A persisted
        -- store that can be wrong, with no way for the player to clear it,
        -- is the shape this project has written five migrations to undo.
        --
        -- Bindings also re-learn themselves from newer evidence, so this is
        -- a shortcut rather than the only repair; but a player who can see
        -- the wrong answer should not have to wait for the right quest.
        if string.lower(CN.Trim(args or "")) == "forget" then
            -- ZONES, NOT BINDINGS. 0.76.0.
            --
            -- The store is keyed by ACHIEVEMENT, so the count was of
            -- bindings: three achievements learned in one zone printed
            -- "Forgot 3 learned zones." for one zone, and an account that
            -- had learned nothing read "Forgot 0 learned zones" followed by
            -- "They are learned again as you quest."
            local zones = {}

            for _, zoneMapID in pairs(Loremaster.Bindings()) do
                zones[zoneMapID] = true
            end

            local count = CN.CountKeys(zones)

            Loremaster.ForgetBindings()
            Loremaster.ForgetZoneIndex()

            if count == 0 then
                Print("Nothing had been learned yet.")
                Print("|cff8a8f96A zone is learned when you turn something "
                    .. "in there.|r")
                return
            end

            Print("Forgot what was learned about " .. count
                .. CN.Pluralize(count, " zone.", " zones."))
            Print("|cff8a8f96They are learned again as you quest.|r")
            return
        end

        local rows = Loremaster.NextZones(6)

        if #rows == 0 then
            Print("No unfinished zone achievements are recorded yet.")
            -- `/cn loremaster scan` is not a command. `loremaster` treats
            -- any argument that is not `all` or `zone` as a NAME FILTER, so
            -- that line sent the player to "Nothing matched."
            Print("|cff8a8f96Run |cffffc74f/cn scanlore|r"
                .. "|cff8a8f96 to read them from the game.|r")
            return
        end

        Print("Zones worth doing next:")

        for index, row in ipairs(rows) do
            CN.PrintLine(string.format("  %d. %s%s|r  |cff8a8f96%d/%d|r",
                index,
                row.here and "|cff5dd2fb" or "|cffffc74f",
                tostring(row.name),
                row.done, row.criteria))

            CN.PrintLine("     " .. CN.Muted(table.concat(CN.Reasons(row), "; ")))
        end

        Print("|cff8a8f96Ordered by what is cheapest to finish, not by size. "
            .. "Zones you have not started are included" .. CN.DASH .. "an earlier version "
            .. "left them out entirely.|r")
    end,
}

------------------------------------------------------------
-- THE STORY, AS DISTINCT FROM EVERYTHING ELSE
------------------------------------------------------------

-- "Finish the story, then do the side quests" is how players actually talk,
-- and the client knows which quests are campaign quests. Splitting the zone's
-- work along that line costs one API call per quest and matches the plan the
-- player already has in their head.
-- `quiet` is passed straight through to `Quests.AvailableOnMap`: this is a
-- read, and the Journey tab's refresh runs with the window closed whenever
-- somebody types `/cn find`. 0.70.0.
function Loremaster.SplitZoneWork(mapID, quiet)
    local quests = CN:GetModule("Quests")

    if not quests then
        return { story = {}, side = {} }
    end

    local split = { story = {}, side = {} }

    for _, poi in ipairs(quests.AvailableOnMap(mapID, quiet)) do
        if Blizzard.IsQuestCampaign(poi.questID) then
            table.insert(split.story, poi)
        else
            table.insert(split.side, poi)
        end
    end

    return split
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- A zone achievement you are most of the way through is a genuine next
-- action: three quests from Loremaster is worth knowing about while you are
-- standing in the zone, and worthless as a line in a list of four hundred.
CN.RegisterCandidateProvider("Loremaster", function()
    local candidates = {}

    local zone = Loremaster.ForZone()

    if not zone or zone.completed or (zone.criteria or 0) == 0 then
        return candidates
    end

    local remaining = zone.criteria - zone.done

    if remaining <= 0 or remaining > 10 then
        return candidates
    end

    -- THE ONE PROVIDER THAT DID NOT HONOUR THE IGNORE LIST.
    --
    -- Twenty-one of the twenty-two check these at build time; nothing
    -- downstream filters an ignored objective, so a provider that skips the
    -- check makes Ignore a silent no-op for its rows.
    --
    -- Worse here than elsewhere: this emits a real achievement id in the same
    -- namespace the Achievements provider uses, so hiding a zone achievement
    -- removed it from Achievements, this re-emitted it, and the aggregate
    -- kept it. The player hid something and it stayed.
    if CN.IsIgnored(CN.objectiveTypes.ACHIEVEMENT, zone.id)
        or CN.IsDeferred(CN.objectiveTypes.ACHIEVEMENT, zone.id) then

        return candidates
    end

    local mapID = select(1, CN.GetPlayerPosition())

    table.insert(candidates, CN.NewObjective({
        id              = zone.id,
        type            = CN.objectiveTypes.ACHIEVEMENT,
        name            = zone.name,
        mapID           = mapID,
        accountWide     = false,
        completionValue = 4,
        reasons         = {
            remaining .. " of " .. zone.criteria .. " left in this zone",
        },
    }))

    return candidates
end, { events = { "ZONE_CHANGED_NEW_AREA", "CRITERIA_UPDATE" }, cooldown = 5 })

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

local function PrintAchievement(entry, indent)
    local bar = ""

    if (entry.criteria or 0) > 0 then
        local fraction = entry.done / entry.criteria

        bar = " |cff5dd2fb" .. CN.ProgressBar(fraction, 12) .. "|r "
            .. entry.done .. "/" .. entry.criteria
    end

    Print((indent or "  ")
        .. (entry.completed and "|cff73b873" or "|cffffc74f")
        .. tostring(entry.name) .. "|r" .. bar)
end

CN:RegisterCommand{
    name    = "loremaster",
    -- "zones" REMOVED. It was registered as its own command 120 lines up --
    -- "Which zone to work on next, and why" -- and this alias, loading later,
    -- overwrote it. So `/cn zones` printed the quest-completion-by-zone
    -- report while `/cn help` and the store page both described the zone
    -- ranking, and the real command was reachable only as `/cn nextzone`.
    aliases = { "lore" },
    args    = "[all, zone, or a name to filter]",
    order   = 12,
    help    = "Quest completion by zone, continent and expansion.",
    handler = function(args)
        args = CN.Trim(args or "")

        if CN.CountKeys(Records()) == 0 then
            Print("No quest achievements scanned yet. Running a scan now.")
            Loremaster.Scan()
        end

        if string.lower(args) == "zone" or args == "" then
            local zone = Loremaster.ForZone()

            if zone then
                Print("This zone:")
                PrintAchievement(zone)
            end

            local split = Loremaster.SplitZoneWork()

            if #split.story > 0 or #split.side > 0 then
                Print("Available here: |cffffc74f" .. #split.story
                    .. "|r story, |cffffc74f" .. #split.side .. "|r side.")
            end

            if args ~= "" then
                return
            end

            local closest = Loremaster.Closest(8)

            if #closest > 0 then
                Print("Closest to finished:")

                for _, entry in ipairs(closest) do
                    PrintAchievement(entry)
                end
            end

            -- AND ZONES NOT YET BEGUN, SAID TO BE THAT. 0.74.0.
            --
            -- They used to fill whatever room the list above left, printed
            -- under "Closest to finished" reading `0 / 120` -- which is the
            -- one thing they are not. Shown, and labelled.
            local unstarted = {}

            for _, entry in ipairs(Loremaster.Closest(4, 4)) do
                if (entry.done or 0) == 0 then
                    table.insert(unstarted, entry)
                end
            end

            if #unstarted > 0 then
                Print("Not started:")

                for _, entry in ipairs(unstarted) do
                    PrintAchievement(entry)
                end
            end

            if #closest == 0 and #unstarted == 0 then
                Print("Nothing left to finish, and nothing new to begin.")
            end

            Print("|cff8a8f96/cn loremaster all|r lists everything by expansion.")

            return
        end

        local includeCompleted = string.lower(args) == "all"

        local filter = (not includeCompleted) and string.lower(args) or nil

        local groups, order = Loremaster.ByCategory(includeCompleted)

        local shown = 0

        for _, key in ipairs(order) do
            if not filter or string.find(string.lower(key), filter, 1, true) then
                CN.PrintLine("|cffffc74f" .. key .. "|r")

                for _, entry in ipairs(groups[key]) do
                    PrintAchievement(entry, "    ")
                    shown = shown + 1
                end
            end
        end

        if shown == 0 then
            Print("Nothing matched. Try |cffffc74f/cn loremaster all|r.")
        end
    end,
}

CN:RegisterCommand{
    name    = "scanlore",
    order   = 27,
    help    = "Rescan quest achievements by zone and expansion.",
    handler = function()
        local scanned, measured = Loremaster.Scan()

        if measured == 0 then
            Print("The game would not answer about criteria just now"
                .. CN.DASH .. "nothing was recorded.")
            Print("|cff8a8f96Try again in a few seconds; this is usual for "
                .. "the first moments after a loading screen.|r")
            return
        end

        Print("Quest achievements scanned: " .. scanned
            .. "   Measured: " .. measured)
    end,
}

-- SCANNED WHEN THE STORE IS EMPTY, OR WHEN IT IS INCOMPLETE. 0.68.0.
--
-- "Empty" was the only trigger, and after the first character it is never
-- empty again -- so a store that lost a field, or one written by a version
-- that did not record something this one reads, stayed wrong for the life of
-- the account unless the player found `/cn scanlore`. Migration 20 produced
-- exactly that state and the addon had no way back out of it.
--
-- A row with no `completed` flag is the shape of that damage, and it is also
-- the shape of a row written before the flag existed. Both want the same
-- thing.
-- THE ZONE YOU ARE IN, WHEN YOU HAND SOMETHING IN. 0.69.0.
--
-- The store was written by `Loremaster.Scan` and by nothing else, and `Scan`
-- ran at login, on `/cn scanlore`, and from the Journey tab's "Rescan zones"
-- button. So turning in a quest moved nothing: the Journey tab went on
-- reading the count it had at login, and the zone the player had just
-- advanced still said what it said an hour ago.
--
-- That is a reported symptom -- "the completion of a quest does not appear to
-- remove it from the journey" -- and it is not the recommendation list, which
-- has always been invalidated on `QUEST_TURNED_IN`. It is this store, which
-- nothing invalidated at all.
--
-- ONE ACHIEVEMENT, NOT THE TREE. A full scan walks every quest achievement in
-- the game and is why it was never put on an event. The zone the player is
-- standing in is the only row a turn-in can move, and refreshing it is two
-- client calls -- the same shape `Exploration.RefreshCurrentZone` has used
-- since 0.61.0, in the sibling store this fix never reached.
--


-- CRITERIA PROGRESS ONLY. THE EARNED FLAG IS NOT DERIVED FROM IT. 0.70.0.
--
-- 0.69.0 wrote `record.completed = (done >= criteria)`, and those two
-- quantities are scoped differently: criteria progress is what THIS character
-- has done, and the earned flag belongs to the ACCOUNT. So an alt at 3 of 12
-- standing in a zone the main had finished cleared the account's flag on the
-- way past, and `/cn zones` began recommending a zone already earned -- the
-- exact symptom two migrations were written to repair, reintroduced by the
-- code repairing it.
--
-- The client answers the account question directly, so it is asked directly.
-- WHICH ZONE A CANDIDATE BELONGS TO, FROM EVIDENCE. 0.74.0, corrected in
-- 0.75.0.
--
-- Run before the write below, because the write is what destroys the
-- evidence: once this character's progress has been brought up to date,
-- "which one moved" can no longer be asked.
--
-- WHAT 0.74.0 CALLED EVIDENCE AND WAS NOT.
--
-- It compared the live figure with `DoneFor`, which answers 0 for any row
-- this character has never scanned -- and `Scan` is skipped at login once
-- this character has a scan marker, so most rows on most characters have no
-- reading at all. `CRITERIA_UPDATE` is global: it fires for a pet battle, a
-- raid criterion, anything. So a character holding 12 of 64 on Outland's
-- Nagrand, standing in DRAENOR'S Nagrand, saw "12 ~= 0" on the Outland row
-- for any criteria update anywhere and bound the wrong zone, permanently.
--
-- "Different from a number nobody recorded" is not movement. A candidate is
-- only a mover now when this character HAS a recorded reading for it and the
-- live figure is HIGHER -- progress going backwards is not evidence either.
--
-- One mover is evidence. Two is not evidence about either of them, so
-- nothing is learned and the ordering keeps answering until a moment comes
-- along where exactly one moves.
-- WHEN THIS ZONE WAS LAST ASKED. See the throttle below.
local learnedAt = {}

function Loremaster.ForgetLearningAttempts()
    learnedAt = {}
end

Loremaster.learnIntervalSeconds = 30

local function LearnZoneBinding(matches, key)
    if type(key) ~= "number" or not matches or #matches < 2 then
        return false
    end

    local store = Records()

    local characterKey = CN.characterKey or CN.GetCharacterKey()

    -- NOTHING TO LEARN, NOTHING TO ASK. 0.76.0.
    --
    -- The loop below calls `GetAchievementProgress`, which makes one client
    -- call PER CRITERION -- so two candidates of forty criteria is eighty
    -- calls. `#matches >= 2` is true in every modern zone (a story
    -- achievement and its Sojourner companion), so this ran everywhere, on
    -- every criteria burst, every two seconds while questing, to re-derive an
    -- answer that changes at most once per zone.
    local unknown = false

    for _, match in ipairs(matches) do
        if Loremaster.ZoneOfAchievement(match.id) ~= key then
            unknown = true
            break
        end
    end

    if not unknown then
        return false
    end

    local now = time()

    if learnedAt[key] and now - learnedAt[key] < Loremaster.learnIntervalSeconds then
        return false
    end

    learnedAt[key] = now

    local moved, movers = nil, 0

    for _, match in ipairs(matches) do
        local record = store[match.id]

        -- A READING THIS CHARACTER ACTUALLY MADE, not a zero standing in for
        -- one it never made.
        local before = record and record.progress
            and record.progress[characterKey]

        if before ~= nil then
            local done, criteria = Blizzard.GetAchievementProgress(match.id)

            if criteria and criteria > 0 and done then
                if done > before then
                    moved  = match.id
                    movers = movers + 1
                end

                -- AND THE BASELINE IS BROUGHT UP TO DATE. 0.76.0.
                --
                -- `RefreshCurrentZone` writes a fresh reading only for the
                -- WINNER, and nothing else ever updated a loser's -- so the
                -- other Nagrand's row went stale the moment the player
                -- quested there and stayed stale for ever.
                --
                -- Two things followed, both in ordinary play. Nothing could
                -- ever be learned, because the stale row read higher than its
                -- baseline on the next update and counted as a second mover.
                -- And the wrong thing could be learned: a criteria update
                -- from anywhere -- a pet battle, a raid -- with only the
                -- stale row above its baseline gave one mover, and bound a
                -- phantom.
                --
                -- A comparison is only evidence against a baseline something
                -- maintains. This maintains it.
                record.progress[characterKey] = done
            end
        end
    end

    if movers ~= 1 then
        return false
    end

    if Loremaster.Bind(moved, key) then
        DebugPrint("Learned that achievement " .. moved
            .. " belongs to zone map " .. key .. ".")

        return true
    end

    return false
end

Loremaster.LearnZoneBinding = LearnZoneBinding

function Loremaster.RefreshCurrentZone()
    -- ONE WALK, NOT TWO. 0.75.0.
    --
    -- 0.74.0 called `ZoneRecord()` once purely to populate two module-level
    -- variables, learned from those, and called it again for the answer --
    -- two full store walks with a client call per row, inside the
    -- `CRITERIA_UPDATE` debounce body, every two seconds while questing.
    -- `ZoneRecord` returns its candidate list now, so there is nothing to go
    -- and fetch.
    local record, id, matches, zoneMap = ZoneRecord()

    -- CAPTURED BEFORE THE LEARNING PASS. 0.76.0.
    --
    -- That pass now writes each candidate's fresh reading back as its
    -- baseline, the winner included -- so reading `before` after it would
    -- always find the number that had just been written, `before ~= done`
    -- would be permanently false, and the `CN.InvalidateProvider` that makes
    -- a turn-in reach the ranking would never fire again.
    local before = record and (Loremaster.DoneFor(record) or 0)

    local learned = LearnZoneBinding(matches, zoneMap)

    if not record or not id then
        return learned
    end

    local done, criteria = Blizzard.GetAchievementProgress(id)

    -- NOT OVER GOOD DATA WITH NOTHING. A refusal from the criteria API
    -- answers `0, 0`, and writing that in loses the row -- the guard
    -- `Exploration` carries, and the one `Achievements` was given in 0.68.0
    -- after it did exactly this.
    if not criteria or criteria <= 0 then
        return learned
    end

    local key = CN.characterKey or CN.GetCharacterKey()

    record.criteria = criteria

    record.progress = record.progress or {}
    record.progress[key] = done

    -- ASKED, NOT INFERRED. And left alone when the client will not answer,
    -- rather than guessed at from the numbers above.
    local earned = Blizzard.IsAchievementEarned and Blizzard.IsAchievementEarned(id)

    if earned ~= nil then
        record.completed = earned
    end

    return learned or before ~= done
end

-- `CRITERIA_UPDATE`, NOT `QUEST_TURNED_IN`. 0.70.0.
--
-- 0.69.0 wired this to the turn-in, which fires BEFORE the client has moved
-- the criteria -- and `CN.Debounce` is leading-edge, so the single-turn-in
-- case ran once, immediately, and read the number it already had. The fix for
-- a reported symptom did nothing for the ordinary form of it.
--
-- `CRITERIA_UPDATE` is the event that fires when the criteria actually move,
-- and it is what the sibling this was modelled on has always used. Reading
-- one file and copying half of it is how this project keeps producing the
-- same defect.
--
-- AND IT TELLS THE RANKING. A store change that dispatches nothing leaves the
-- provider's cached row saying "8 of 12 left" until a zone change -- which is
-- the other half `Exploration` does and this did not.
CN:RegisterEvent("CRITERIA_UPDATE", function()
    CN.Debounce("Loremaster.zone", 2, function()
        local ok, moved = pcall(Loremaster.RefreshCurrentZone)

        if ok and moved then
            CN.InvalidateProvider("Loremaster")
        end
    end)
end)

CN:OnLogin(function()
    local records = Records()

    if CN.CountKeys(records) == 0 then
        Loremaster.Scan()

        return
    end

    -- AND ON THIS CHARACTER'S OWN DIMENSION. 0.69.0.
    --
    -- `completed` is account-wide, so once ANY character has repaired it no
    -- other character ever triggers a rescan again -- and `progress` is
    -- per-character, which is precisely what an alt is missing. So the first
    -- character to log in after an upgrade fixed the store for itself and
    -- locked every other character out of the repair: `/cn zones` reported
    -- "not started, 120 to do" for zones an alt had fully quested.
    --
    -- ASKED OF A MARKER, NOT OF THE ROWS. 0.70.0. The first version walked
    -- the store looking for a row missing this character's progress -- and
    -- `Scan` only writes progress for rows the category walk returns, so a
    -- row it cannot reach keeps that entry nil for ever and the condition was
    -- true on every login, of every character, for the life of the account.
    -- A full tree walk per login, to discover that a retired achievement is
    -- still retired.
    local key = CN.characterKey or CN.GetCharacterKey()

    if not CN.Account("loremasterScans")[key] then
        Loremaster.Scan()

        return
    end

    -- The account-wide half stays a row check: it repairs a store that lost
    -- the flag, which is a thing that happened once, to everybody.
    for _, record in pairs(records) do
        if type(record) == "table" and record.completed == nil then
            Loremaster.Scan()

            return
        end
    end
end)

return Loremaster
'@

$Embedded['Modules\Follow.lua'] = @'
-- Modules/Follow.lua
-- Completion Navigator :: stop consulting the addon, start following it.
--
-- Everything this addon knows is currently something you have to ASK for.
-- You type a command, read a list, close it, and play from memory. The
-- routing engine computes stops, orders them, improves the order, and then
-- hands all of that to a player who has to carry it in their head.
--
-- Follow mode makes it present. One small frame showing the stop you are
-- walking to and what you do when you get there, ticking things off as the
-- game reports them, advancing to the next stop when this one is clear, with
-- the arrow already pointed the right way.
--
-- THE RULE THIS FILE IS BUILT AROUND: a co-pilot that fights you is worse
-- than no co-pilot.
--
--   * Off by default. It is started deliberately and stopped with one word.
--   * It never re-points the waypoint while you are walking to something.
--     Advancing happens when the current stop is DONE, not on a timer.
--   * If you wander off and do something it did not suggest, it re-plans
--     around where you actually are rather than herding you back.
--   * It says nothing in chat while it runs. A frame that updates silently
--     is a companion; one that narrates is a nuisance.

local ADDON_NAME, CN = ...

local Follow = CN:RegisterModule("Follow")

local Print      = CN.Print

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- STATE
------------------------------------------------------------

Follow.active = false

-- The stop currently being walked to, and what it held when we set out.
local current = {
    hub        = nil,
    objectives = nil,
    startedAt  = nil,
}

local frame

Follow.recheckSeconds = 3

------------------------------------------------------------
-- WHAT IS LEFT AT THIS STOP
------------------------------------------------------------

-- An objective is done when it is no longer a candidate.
--
-- Deliberately defined by absence rather than by watching for completion
-- events. Events are per-type and there are eleven types; absence is one
-- rule that covers all of them, including the ones added later, and it is
-- also correct when something is finished by means the addon never saw.
-- The live index, memoised against the candidate generation.
--
-- PERFORMANCE, AND A BUG I SHIPPED IN 0.27.0: a single redraw calls this
-- three times -- once to test whether the stop is finished, once for the
-- header, once for the body -- and each call walked the entire candidate list
-- and built a fresh set of several thousand keys. Three full scans, three
-- throwaway tables, every three seconds, for an answer that cannot have
-- changed between them.
--
-- The candidate list already publishes a generation number that increments
-- when anything is rebuilt. Keyed on that, this is built once per actual
-- change instead of once per question.
local liveIndex = { generation = -1, keys = nil }

local function LiveKeys()
    -- COLLECT FIRST, THEN MEMOISE ON WHAT COLLECTING PRODUCED.
    --
    -- This read the generation, compared it to the memo, and returned early
    -- before calling CollectCandidates -- while stamping the memo with the
    -- generation from BEFORE the collect that followed it. Two things then
    -- went wrong together.
    --
    -- Marking a provider dirty deliberately does not advance the generation:
    -- only an actual rebuild does, and only CollectCandidates rebuilds. So
    -- once the stamp converged, this function stopped calling
    -- CollectCandidates, which meant nothing here ever rebuilt, which meant
    -- the generation could never advance, which meant the memo stayed valid
    -- forever. Follow mode stopped noticing that a stop was finished and sat
    -- on it -- unstuck only if something unrelated happened to collect, such
    -- as the heads-up display's timer, which is off by default.
    --
    -- Collecting when nothing is stale costs about two microseconds. Guarding
    -- it was never worth this.
    local candidates = CN.CollectCandidates() or {}

    local generation = 0

    if CN.GetCandidateCacheState then
        local ok, state = pcall(CN.GetCandidateCacheState)

        if ok and state then
            generation = state.generation or 0
        end
    end

    if liveIndex.keys and liveIndex.generation == generation then
        return liveIndex.keys
    end

    local keys = {}

    for _, candidate in ipairs(candidates) do
        keys[tostring(candidate.type) .. ":" .. tostring(candidate.id)] = true
    end

    liveIndex.generation = generation
    liveIndex.keys       = keys

    return keys
end

Follow.LiveKeys = LiveKeys

function Follow.Remaining(objectives)
    local remaining = {}

    if type(objectives) ~= "table" then
        return remaining
    end

    local live = LiveKeys()

    for _, objective in ipairs(objectives) do
        local key = tostring(objective.type) .. ":" .. tostring(objective.id)

        if live[key] then
            table.insert(remaining, objective)
        end
    end

    return remaining
end

function Follow.IsStopComplete()
    if not current.objectives then
        return false
    end

    return #Follow.Remaining(current.objectives) == 0
end

------------------------------------------------------------
-- CHOOSING A STOP
------------------------------------------------------------

-- The next stop is the first stop of a route built from where you are
-- STANDING, recomputed rather than remembered.
--
-- Remembering the route and walking down it would be cheaper and wrong: the
-- player who took a detour, took a flight path, or died and released is no
-- longer on the route that was computed, and the honest answer is to look at
-- where they are now.
function Follow.NextStop()
    local mapID, x, y = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return nil
    end

    -- THE TOTAL MOVES, BECAUSE THE ROUTE DOES.
    --
    -- The route is rebuilt from live candidates on every call, so accepting
    -- five quests in three new places lengthens it. A denominator frozen at
    -- the start therefore produced "Stop 9 of 8 cleared", fired the "Route
    -- complete" flourish at stop 8 and then again at 9, 10 and 11 while
    -- stops remained, and left the heads-up display -- which clamps -- stuck
    -- on "stop 8 of 8" for the rest of the session.
    --
    -- What the player is being told is how far through the CURRENT route
    -- they are, so the total is what is currently there plus what has already
    -- been cleared. It can grow; that is honest, because the work grew.
    local total = #hubs + (Follow.completed or 0)

    if total > (Follow.startedWith or 0) then
        Follow.startedWith = total

        -- The route grew, so it is no longer a finished route: the
        -- completion moment is available again.
        if total > (Follow.completed or 0) then
            Follow.celebrated = false
        end
    end

    for _, hub in ipairs(hubs) do
        local remaining = Follow.Remaining(hub.objectives)

        if #remaining > 0 then
            return hub, remaining
        end
    end

    return nil
end

function Follow.SetStop(hub, objectives)
    current.hub        = hub
    current.objectives = objectives or (hub and hub.objectives)
    current.startedAt  = time()

    if hub and hub.mapID and hub.x and hub.y then
        local label = CN.DescribeHub and CN.DescribeHub(hub) or "Next stop"

        -- SILENT ON SUCCESS, NOT ON REFUSAL. 0.79.0.
        --
        -- This file does not narrate -- the frame is the surface, and the
        -- header says so. But it discarded the provider's caveat too, so a
        -- hub advance inside an instance placed nothing and reported
        -- nothing, and the frame went on pointing at a waypoint that was
        -- never set. `false` keeps the headline off and lets the refusal
        -- through.
        CN.SetWaypointAndSay(hub.mapID, hub.x, hub.y, label, false)
    end
end

-- Advance only when there is a reason to.
--
-- `force` exists for the player asking out loud ("/cn follow next"), which is
-- a different thing from the addon deciding on its own.
-- PROGRESS THE PLAYER CAN SEE.
--
-- Follow mode has always advanced silently: the waypoint moved, and that was
-- the only evidence anything had happened. Somebody walking a route for
-- twenty minutes had no sense of getting anywhere, which is the difference
-- between a tool that feels like it is working with you and one that feels
-- like a timer.
--
-- Counted per run rather than persisted -- "how far through tonight's route
-- am I" is a question about tonight.
Follow.completed = 0
Follow.startedWith = 0

-- Whether this route has already had its completion moment. Reset when a
-- route starts, and when the total grows past what was already cleared --
-- because a route that has more stops in it than it did is not a route that
-- has been finished.
Follow.celebrated = false

-- How long to wait before searching again when the last search found nothing
-- routable here. A forced advance -- the player asking -- ignores it.
Follow.emptySearchSeconds = 15
Follow.lastEmptySearch    = 0

function Follow.NoteStopCleared()
    Follow.completed = Follow.completed + 1

    local total = Follow.startedWith

    -- Translated. This is the string 0.48.1 made a build failure over for
    -- having no translations at all -- and then it was printed as an English
    -- literal anyway, so the ten locale files that carry it were never
    -- consulted.
    local text = CN.L["Stop cleared"]

    if total > 0 then
        text = string.format(CN.L["Stop %d of %d cleared"],
            Follow.completed, total)
    end

    Print("|cff73b873" .. text .. "|r")

    Follow.Cue("stop")

    -- A COMPLETION MOMENT, when there is genuinely nothing left. The route
    -- finishing is the only thing this addon does that is worth a small
    -- flourish, and it happens rarely enough to stay one.
    -- ONCE PER ROUTE, NOT ONCE PER STOP PAST THE END.
    --
    -- `completed >= total` is true for every clear after the last one, so a
    -- route whose total shrank -- or a player who cleared something outside
    -- the counted set -- got the flourish again on every stop. 0.50.0 fixed
    -- the "Stop 9 of 8" half of this by letting the total grow; the
    -- celebration half was left firing repeatedly.
    if total > 0 and Follow.completed >= total and not Follow.celebrated then
        Follow.celebrated = true

        -- TRANSLATED ALL THE WAY THROUGH. 0.78.0.
        --
        -- 0.77.0 fixed the plural and left the half-translation it was citing
        -- as the defect: `CN.Count` hardcodes "stop"/"stops" and ", all
        -- done." was a literal, so a German client read "Route abgeschlossen.
        -- 12 stops, all done."
        --
        -- Both halves are keys now, and the singular is its own key rather
        -- than a format string with a 1 in it, because a language that
        -- inflects differently at one cannot be served by substitution.
        local tail = total == 1
            and CN.L["All 1 stop done."]
            or string.format(CN.L["All %d stops done."], total)

        Print("|cff5dd2fb" .. CN.L["Route complete."] .. "|r " .. tail)

        Follow.Celebrate()
    end

    return Follow.completed
end

-- Sound and a flash, both OFF by default, because unsolicited noise is the
-- most intrusive thing an addon can do and this addon's standing rule is that
-- nothing is taken over without being asked.
-- THREE MOMENTS, NOT ONE.
--
-- `/cn cues` was described as sound and a flash "when a route finishes", and
-- that is all it did -- while the two moments a player actually wants marking
-- are the smaller ones: arriving somewhere, and clearing a stop. A cue that
-- fires once an hour is a cue nobody has an opinion about.
--
-- Quieter for the small moments than for the big one. A route finishing is
-- worth a noise; arriving at the third of eight camps is worth a tap.
Follow.cueSounds = {
    route   = "UI_QUEST_ROLLING_FORWARD_01",
    stop    = "IG_QUEST_LIST_SELECT",
    arrival = "IG_QUEST_LIST_OPEN",
}

function Follow.Cue(moment)
    local settings = CN.Settings()

    if not settings or not settings.cues then
        return false
    end

    local sound = Follow.cueSounds[moment or "route"]

    if PlaySound and SOUNDKIT and sound and SOUNDKIT[sound] then
        pcall(PlaySound, SOUNDKIT[sound])
    end

    -- The flash belongs to the route, not to every arrival: a frame that
    -- blinks every time you reach a camp is a frame people turn off.
    if moment == "route" and UIFrameFlash and frame then
        pcall(UIFrameFlash, frame, 0.3, 0.3, 1.2, false, 0, 0)
    end

    return true
end

function Follow.Celebrate()
    return Follow.Cue("route")
end

function Follow.Advance(force)
    if not Follow.active then
        return false
    end

    -- NOT DURING A FIGHT.
    --
    -- Advancing mid-combat re-points the arrow and the waypoint at the next
    -- camp while the player is being hit by something at this one. It is the
    -- single most intrusive moment the addon could pick, and there is no
    -- version of "you finished that stop" that is urgent enough to deliver
    -- during a fight. The stop is still finished thirty seconds later.
    --
    -- A forced advance -- the player pressing the button -- is still obeyed.
    -- They can see their own screen.
    if not force and InCombatLockdown and InCombatLockdown() then
        Follow.deferred = true

        return false
    end

    if not force and current.hub and not Follow.IsStopComplete() then
        -- Still work here. Do not move the waypoint out from under someone
        -- who is walking toward it.
        return false
    end

    -- NOTHING TO ROUTE TO IS NOT A REASON TO KEEP ROUTING.
    --
    -- When no hub is found, `current.hub` is cleared -- and the guard above
    -- then lets every subsequent call fall straight through to NextStop,
    -- which builds a full zone route with a 2-opt pass and bumps the ranking
    -- generation. QUEST_LOG_UPDATE is not throttled on this path, so standing
    -- somewhere with nothing routable -- a capital city, a dungeon, a
    -- battleground, a flight -- rebuilt the route on every one of them.
    --
    -- Measured: with a live stop, twenty events cost zero route builds; with
    -- none, twenty events cost twenty.
    if not force and not current.hub then
        local now = time()

        if (now - (Follow.lastEmptySearch or 0)) < Follow.emptySearchSeconds then
            return false
        end

        Follow.lastEmptySearch = now
    end

    local hub, remaining = Follow.NextStop()

    if not hub then
        current.hub        = nil
        current.objectives = nil

        return false
    end

    -- Do not re-set the waypoint for the stop we are already on.
    if current.hub
        and current.hub.x == hub.x
        and current.hub.y == hub.y
        and not force then

        current.objectives = remaining

        return false
    end

    -- Something was actually finished if we are moving on from a stop we
    -- were already on and were not forced.
    if current.hub and not force then
        Follow.NoteStopCleared()
    end

    Follow.SetStop(hub, remaining)

    return true
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

Follow.maxLines = 6

-- What the frame should say, computed separately from the frame itself so it
-- can be asserted without a client.
function Follow.Lines()
    local lines = {}

    if not current.hub then
        table.insert(lines, { text = "Nothing left to route here.", state = "NOTE" })

        return lines
    end

    local remaining = Follow.Remaining(current.objectives)

    local quests = CN:GetModule("Quests")

    local shown = 0

    local open = {}

    for _, objective in ipairs(remaining) do
        open[tostring(objective.type) .. ":" .. tostring(objective.id)] = true
    end

    for _, objective in ipairs(current.objectives or {}) do
        local stillOpen =
            open[tostring(objective.type) .. ":" .. tostring(objective.id)] == true

        if shown >= Follow.maxLines then
            table.insert(lines, {
                text  = "and " .. (#current.objectives - shown) .. " more",
                state = "NOTE",
            })
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, {
            text  = verb .. ": " .. tostring(objective.name or objective.id),
            state = stillOpen and "OPEN" or "DONE",
        })

        shown = shown + 1
    end

    return lines
end

function Follow.HeaderText()
    if not current.hub then
        return "Completion Navigator"
    end

    local remaining = #Follow.Remaining(current.objectives)

    local total = #(current.objectives or {})

    -- "Stop: 3 of 5 left" reads at a glance as "stop 3 of 5", and the
    -- heads-up line says "stop 4 of 12" about a different quantity -- hubs in
    -- the route rather than objectives at this one. Two frames, one activity,
    -- two numbers that look like the same number. This one counts what is
    -- left HERE and says so.
    return string.format("%d of %d left here", remaining, total)
end

local function BuildFrame()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorFollow", UIParent)

    frame:SetSize(240, 120)
    frame:SetFrameStrata("MEDIUM")
    frame:SetMovable(true)
    frame:EnableMouse(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetClampedToScreen(true)

    CN.RestoreFramePosition(frame, Settings().followPosition,
        { point = "TOPLEFT", relativePoint = "TOPLEFT", x = 40, y = -200 })

    -- Panelled and marked, for the reason spelled out in Modules/Hud.lua:
    -- text drawn over the world with no ground under it reads as text that
    -- has come loose from something. Slightly more opaque than the heads-up
    -- line because this one carries a list.
    if CN.UI and CN.UI.PaintPanel then
        CN.UI.PaintPanel(frame, 0.04, 0.05, 0.07, 0.70)
    end

    local rule = frame:CreateTexture(nil, "ARTWORK")
    rule:SetPoint("TOPLEFT")
    rule:SetPoint("BOTTOMLEFT")
    rule:SetWidth(2)
    rule:SetColorTexture(CN.Rgb("BRAND"))
    rule:SetAlpha(0.9)

    local inset = CN.SPACE.M

    frame.header = CN.Label(frame, "OVERLAY", "HEAD")
    frame.header:SetPoint("TOPLEFT", inset, -CN.SPACE.S)

    -- AND A RIGHT-EDGE STOP, so the header does not run under the hover x.
    -- 0.78.0.
    --
    -- Alpha 0 does not disable mouse input, so without this the right end of
    -- the header row is a click that stops the route -- with nothing drawn
    -- there to say so. `Modules/Hud.lua` reserves the same width for the same
    -- reason.
    frame.header:SetPoint("TOPRIGHT", -(inset + CN.CLOSE_WIDTH), -CN.SPACE.S)
    frame.header:SetJustifyH("LEFT")

    frame.body = CN.Label(frame, "OVERLAY", "SMALL")
    frame.body:SetPoint("TOPLEFT", frame.header, "BOTTOMLEFT", 0, -CN.SPACE.S)
    frame.body:SetJustifyH("LEFT")
    frame.body:SetJustifyV("TOP")

    CN.Outline(frame.header, 13, "PRIMARY")
    CN.Outline(frame.body, 11, "BODY")

    frame:SetScript("OnDragStart", function(self) self:StartMoving() end)

    frame:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        Settings().followPosition = CN.SaveFramePosition(self)
            or Settings().followPosition
    end)

    -- AND A WAY OUT OF IT. 0.77.0.
    --
    -- This frame is drawn over the world, is mouse-enabled and draggable, and
    -- said neither -- so the only way to be rid of it was to know `/cn
    -- follow`. The heads-up line got a hover x when a player asked for one;
    -- this is the same control, from the same helper.
    CN.AttachCloseControl(frame,
        function()
            Follow.Stop()

            CN.Print("Follow mode off. " .. CN.Aside(CN.Accent("/cn follow")
                .. " starts it again"))
        end,
        "The stop you are walking to. Drag to move it. The x stops "
        .. "following.",
        "Stop following. /cn follow starts it again.")

    frame:Hide()

    return frame
end

Follow.BuildFrame = BuildFrame

function Follow.Redraw()
    if not frame then
        return
    end

    frame.header:SetText(Follow.HeaderText())

    local rendered = {}

    for _, line in ipairs(Follow.Lines()) do
        local colour = "|cffc8ccd2"

        if line.state == "DONE" then
            colour = "|cff73b873"
        elseif line.state == "NOTE" then
            colour = "|cff8a8f96"
        end

        table.insert(rendered, colour
            .. (line.state == "DONE" and "x " or "- ")
            .. line.text .. "|r")
    end

    frame.body:SetText(table.concat(rendered, "\n"))
end

------------------------------------------------------------
-- THE LOOP
------------------------------------------------------------

local ticker

-- Driven by events, with a slow clock as a backstop rather than as the
-- mechanism. Position changes with no event attached -- walking into range of
-- something -- are the only reason the clock exists at all.
local function Tick()
    if not Follow.active then
        return
    end

    Follow.Advance(false)
    Follow.Redraw()
end

function Follow.Start()
    if Follow.active then
        return false
    end

    Follow.active = true

    Follow.completed  = 0
    Follow.celebrated = false

    -- How many stops there were when the route started, so progress can be
    -- reported as a fraction rather than as a running count that means
    -- nothing on its own.
    local mapID, x, y = CN.GetPlayerPosition()

    local hubs

    if mapID and CN.BuildZoneRoute then
        local _, _, built = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

        hubs = built
    end

    -- COUNTED WHEN THE MAP WILL ANSWER, NOT BEFORE.
    --
    -- Start() also runs from the login hook when follow mode was left on, and
    -- at PLAYER_LOGIN the map API has nothing to say yet -- so the total was
    -- fixed at zero for the whole session. Every "Stop 3 of 8 cleared"
    -- degraded to a bare "Stop cleared", and the completion moment, which
    -- needs a total to compare against, was unreachable for any session that
    -- resumed follow rather than typing the command.
    --
    -- Zero means "not counted yet" rather than "no stops", so the first
    -- advance that finds a route sets it.
    Follow.startedWith = (type(hubs) == "table") and #hubs or 0

    Settings().follow = true

    BuildFrame()

    if frame then
        frame:Show()
    end

    Follow.Advance(true)
    Follow.Redraw()

    if C_Timer and C_Timer.NewTicker and not ticker then
        -- Guarded, for the reason spelled out on Session's ticker: a
        -- repeating callback that throws is a repeating error box.
        ticker = C_Timer.NewTicker(Follow.recheckSeconds, function()
            CN.Guard("Follow.Tick", Tick)
        end)
    end

    return true
end

function Follow.Stop()
    Follow.active = false

    Settings().follow = false

    current.hub        = nil
    current.objectives = nil

    if ticker then
        ticker:Cancel()
        ticker = nil
    end

    if frame then
        frame:Hide()
    end

    -- OFF MEANS OFF.
    --
    -- Setting a stop puts a waypoint on the map, draws the on-screen arrow
    -- and starts Navigation's own ticker. Stopping hid this module's frame
    -- and cancelled this module's ticker and left all three of those running
    -- -- so `/cn follow off` left an arrow pointing at a route that was no
    -- longer being followed, indefinitely.
    --
    -- The suite started follow mode and read its lines; it never asked what
    -- was still on screen after stopping it.
    if CN.ClearWaypoints then
        pcall(CN.ClearWaypoints)
    end

    -- And a deferral is about the route that was being walked. Left set, it
    -- fired into the next combat-free moment of a session that was no longer
    -- following anything, and survived into the next Start().
    Follow.deferred = false

    return true
end

function Follow.Toggle()
    if Follow.active then
        Follow.Stop()
        return false
    end

    Follow.Start()

    return true
end

function Follow.CurrentStop()
    return current.hub, current.objectives
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- Something finished. Check whether it emptied the stop; the check is cheap
-- and the alternative is a co-pilot that lags behind the player.
local function OnSomethingChanged()
    if Follow.active then
        Follow.Advance(false)
        Follow.Redraw()
    end
end

CN:RegisterEvent("QUEST_TURNED_IN", OnSomethingChanged)
CN:RegisterEvent("QUEST_ACCEPTED", OnSomethingChanged)
CN:RegisterEvent("QUEST_LOG_UPDATE", OnSomethingChanged)

-- A new zone invalidates the route entirely, so re-plan rather than advance.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if Follow.active then
        Follow.Advance(true)
        Follow.Redraw()
    end
end)

CN:OnLogin(function()
    if Settings().follow then
        Follow.Start()
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "follow",
    aliases = { "copilot", "run" },
    args    = "[on, off, next, or nothing to toggle]",
    order   = 10,
    help    = "Follow the route: current stop on screen, advancing as you finish.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "off" or args == "stop" then
            Follow.Stop()
            Print("Follow mode off.")
            return
        end

        if args == "next" or args == "skip" then
            if not Follow.active then
                Print("Follow mode is not running. |cffffc74f/cn follow|r starts it.")
                return
            end

            Follow.Advance(true)
            Follow.Redraw()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Moved on: " .. (CN.DescribeHub(hub) or "next stop") .. ".")
            else
                Print("Nothing left to route here.")
            end

            return
        end

        if args == "on" or args == "" then
            if args == "" and Follow.active then
                Follow.Stop()
                Print("Follow mode off.")
                return
            end

            Follow.Start()

            local hub = Follow.CurrentStop()

            if hub then
                Print("Following. First stop: "
                    .. (CN.DescribeHub(hub) or "ahead") .. ".")
                Print("|cff8a8f96It advances when the stop is clear. "
                    .. "|cffffc74f/cn follow off|r|cff8a8f96 stops.|r")
            else
                Print("Following, but nothing here needs doing.")
            end

            return
        end

        Print("Usage: /cn follow [on | off | next]")
    end,
}

-- Whatever was held back during the fight happens the moment it ends.
CN:RegisterEvent("PLAYER_REGEN_ENABLED", function()
    if Follow.active and Follow.deferred then
        Follow.deferred = false

        Follow.Advance()
    end
end)

return Follow
'@

$Embedded['Modules\Session.lua'] = @'
-- Modules/Session.lua
-- Completion Navigator :: "I have forty minutes. What should I do?"
--
-- The single most common shape a play session actually has, and the addon
-- had nothing to say about it. It could rank everything and route between
-- stops, and it could not answer the one question a person with a job and a
-- bedtime asks before logging in.
--
-- WHY THIS IS HARD TO DO HONESTLY.
--
-- A plan that fits in forty minutes requires knowing how long things take,
-- and the client does not say. The tempting move is to make numbers up --
-- "quests take four minutes" -- and present them in a font that looks like
-- measurement. This addon has a standing rule against exactly that.
--
-- So the estimate is built from two halves, and only one of them is guessed:
--
--   TRAVEL is computed. The router already knows the real yard distance
--   between stops, and this module measures how fast you actually move by
--   watching your position. That is arithmetic on observations.
--
--   TASK TIME is learned. Every completion is timed against when the
--   objective was first offered as the current stop, and the median per type
--   is kept. Until a type has been seen enough times, it has NO estimate and
--   the plan says so rather than inventing one.
--
-- A plan therefore starts out honest and vague -- "these stops, distance
-- known, duration not yet" -- and sharpens as it watches you play. That is
-- slower to become useful than a table of invented constants, and it is the
-- only version that is ever true.

local ADDON_NAME, CN = ...

local Session = CN:RegisterModule("Session")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- MEASURED TRAVEL SPEED
------------------------------------------------------------

-- Yards per second. Seeded with a walking-speed figure that is immediately
-- replaced by measurement; it exists so the first plan is not divided by nil.
Session.defaultSpeed = 7

Session.minSamples = 5

-- THE CLOCK.
--
-- `time()` returns whole seconds. Sampling a ten-second interval with a
-- one-second ruler is up to ten per cent of error baked into every estimate
-- the planner produces, and it silently discarded every task that finished
-- within the same second it was offered -- which, in the offline suite, was
-- all of them. `GetTime()` is the client's fractional monotonic clock and is
-- the right instrument for measuring a duration.
--
-- Kept behind a function so the offline harness can drive it.
function Session.Now()
    if GetTime then
        return GetTime()
    end

    return os.clock()
end

-- Speed is kept in three buckets, not one.
--
-- A single median across mounted and unmounted travel is a number that is
-- wrong in both states: too slow to plan a mounted route, too fast to plan a
-- walk around a town.
--
-- 0.43.0 added the third, and it was the same mistake one level down: flying
-- yourself was landing in `mounted` beside a ground mount, so the median was
-- dragged upward by however much the player skyrides and every ground
-- estimate inherited it. Three medians are three honest answers.
local speed = {
    lastMapID  = nil,
    lastX      = nil,
    lastY      = nil,
    lastAt     = nil,
    lastMounted = nil,
    lastFlying = nil,
    samples    = { mounted = {}, onFoot = {}, flying = {} },
}

-- SAMPLES SURVIVE A RELOAD.
--
-- They did not. Speed was measured into a table that lived and died with the
-- session, so every `/reload` -- which a player does several times an hour --
-- threw away the measurements and put the planner back on a guessed constant.
-- The addon was permanently five samples from being useful and never got
-- there.
--
-- Stored per character, because a druid in travel form and a warrior on foot
-- are different measurements and averaging them helps nobody.
local function Persisted()
    local character = CN.character

    if not character then
        return nil
    end

    character.speedSamples = character.speedSamples or {}

    character.speedSamples.mounted = character.speedSamples.mounted or {}
    character.speedSamples.onFoot  = character.speedSamples.onFoot or {}
    character.speedSamples.flying  = character.speedSamples.flying or {}

    return character.speedSamples
end

Session.Persisted = Persisted

-- THE SANITY BAND, PER BUCKET.
--
-- It was a single range -- above half a yard a second, below sixty -- written
-- when there were two buckets and both were ground travel. Sixty is a
-- perfectly good ceiling for running and riding, and it is BELOW the speed a
-- player actually flies at.
--
-- So when 0.43.0 added the flying bucket, every genuine flying sample was
-- silently discarded as implausible, the bucket never filled, and the flying
-- estimate stayed permanently seeded. The feature would have looked like it
-- was working and never learned anything. Caught by a test that assumed a
-- realistic flying speed.
Session.speedBands = {
    onFoot  = { 0.5, 60 },
    mounted = { 0.5, 60 },

    -- Skyriding sustains well past sixty and bursts higher. The upper bound
    -- is the same one Travel uses for a taxi: fast enough to be a loading
    -- screen rather than a mount.
    flying  = { 0.5, 200 },
}

function Session.IsPlausibleSpeed(value, bucket)
    local band = Session.speedBands[bucket or "onFoot"]
        or Session.speedBands.onFoot

    return value > band[1] and value < band[2]
end

function Session.LoadSamples()
    local stored = Persisted()

    if not stored then
        return 0
    end

    local loaded = 0

    for _, bucket in ipairs({ "mounted", "onFoot", "flying" }) do
        speed.samples[bucket] = {}

        for _, value in ipairs(stored[bucket] or {}) do
            if type(value) == "number" and Session.IsPlausibleSpeed(value, bucket) then
                table.insert(speed.samples[bucket], value)
                loaded = loaded + 1
            end
        end
    end

    -- Write the cleaned set back.
    --
    -- SavedVariables are a file on disk that other things can touch and that
    -- survives every future version of this addon. Filtering junk on read and
    -- leaving it in place means filtering the same junk on every login
    -- forever; cleaning it means the corruption is dealt with once.
    Session.SaveSamples()

    return loaded
end

function Session.SaveSamples()
    local stored = Persisted()

    if not stored then
        return false
    end

    -- ALL THREE BUCKETS, INCLUDING THE ONE THAT WAS MISSING.
    --
    -- `flying` was left out of this list while Persisted() creates it and
    -- LoadSamples reads it, so measured flight speed survived until logout
    -- and then vanished. Travel.HasFlying needs five flying samples before it
    -- will consider a self-flown route at all, so after any reload the addon
    -- silently went back to costing every journey on the ground -- the
    -- feature 0.43.0 was built around, off, permanently, for everyone.
    --
    -- The suite tested disk-to-memory for all three and memory-to-disk for
    -- two. A round trip is not tested by testing each half against a
    -- different fixture.
    for _, bucket in ipairs({ "mounted", "onFoot", "flying" }) do
        stored[bucket] = {}

        for _, value in ipairs(speed.samples[bucket]) do
            table.insert(stored[bucket], value)
        end
    end

    return true
end

Session.speedSampleCap = 40

-- A TAXI IS NOT A GROUND MOUNT. 0.89.0.
--
-- `Flying` twelve lines below excludes the taxi, under a comment saying that
-- movement "belongs to Travel's flight-speed measurement rather than to this
-- one". It was excluded from `flying` and then caught by `mounted`, which
-- returned true on a taxi -- so every flight that stayed inside one map was
-- filed as a ground-mount speed sample. `Session.Observe`'s own header claims
-- it discards a flight path, and `Modules/Travel.lua` states as fact that
-- "Session already discards taxi movement when learning running speed".
-- Neither was true.
--
-- Nothing downstream caught it either: `mounted` stays true for the whole
-- flight so the bucket never changes, and the plausibility band for `mounted`
-- is 0.5 to 60 yards a second, which admits every flight speed in the game.
--
-- It matters because `Session.Speed("onFoot")` falls back to the `mounted`
-- median below `minSamples`, and `Travel.EstimateSeconds` uses that for the
-- run-the-whole-way option and for both walking legs of every flight route --
-- which feeds `/cn plan`'s budget, `CN.SecondsNeeded` and the urgency term's
-- "can I still get there" test. 0.43.0 records fixing exactly this one level
-- down, for self-flight, and not for the taxi.
local function Mounted()
    if UnitOnTaxi and UnitOnTaxi("player") then
        return false
    end

    if IsMounted and IsMounted() then
        return true
    end

    return false
end

Session.IsMounted = Mounted

-- Flying yourself, which is not the same as being on a flight path and not
-- the same as a ground mount. On a taxi the client also reports the player as
-- flying, and that movement belongs to Travel's flight-speed measurement
-- rather than to this one -- so it is excluded here.
local function Flying()
    if UnitOnTaxi and UnitOnTaxi("player") then
        return false
    end

    return (IsFlying and IsFlying()) and true or false
end

Session.IsFlying = Flying

-- Which bucket the player's current movement belongs in.
function Session.Bucket()
    if Flying() then
        return "flying"
    end

    if Mounted() then
        return "mounted"
    end

    return "onFoot"
end

-- Called on a slow clock. Measures the distance covered since the last look.
--
-- Deliberately discards anything implausible: a teleport, a flight path, a
-- hearthstone or a zone change would otherwise register as a very fast
-- player and make every estimate useless.
function Session.Observe()
    local mapID, x, y = CN.GetPlayerPosition()

    local now     = Session.Now()
    local mounted = Mounted()
    local flying  = Flying()

    if not mapID or not x or not y then
        return nil
    end

    local previousMap, previousX, previousY, previousAt, previousMounted =
        speed.lastMapID, speed.lastX, speed.lastY, speed.lastAt, speed.lastMounted

    -- Read BEFORE it is overwritten. The first version of the flying check
    -- compared the new value against itself, which is always equal, so taking
    -- off mid-interval produced a sample that was half ground speed and half
    -- flight speed and was filed under whichever the player ended in.
    local previousFlying = speed.lastFlying

    speed.lastMapID, speed.lastX, speed.lastY = mapID, x, y
    speed.lastAt, speed.lastMounted = now, mounted
    speed.lastFlying = flying

    if previousMap ~= mapID or not previousAt then
        return nil
    end

    -- Mounting halfway through an interval makes the sample a blend of both
    -- speeds and belongs to neither bucket. The same is true of taking off.
    if previousMounted ~= mounted or previousFlying ~= flying then
        return nil
    end

    local elapsed = now - previousAt

    if elapsed <= 0 or elapsed > 30 then
        return nil
    end

    local nav = CN:GetModule("Navigation")

    if not nav or not nav.DistanceYards then
        return nil
    end

    local yards = nav.DistanceYards(mapID, previousX, previousY, x, y)

    if not yards or yards <= 0 then
        return nil
    end

    local observed = yards / elapsed

    -- A player on foot does about 7 yards a second; mounted, roughly 14 to
    -- 20; flying, a great deal more. The ceiling is per bucket for exactly
    -- that reason -- see Session.speedBands.
    local bucketName = flying and "flying"
        or (mounted and "mounted" or "onFoot")

    if not Session.IsPlausibleSpeed(observed, bucketName) then
        return nil
    end

    local bucket = speed.samples[bucketName]

    table.insert(bucket, observed)

    while #bucket > Session.speedSampleCap do
        table.remove(bucket, 1)
    end

    -- Written straight through. A measurement kept only in memory is a
    -- measurement thrown away at the next reload, which is what this used
    -- to do.
    Session.SaveSamples()

    return observed, mounted
end

-- The median, not the mean: standing still for a minute should not halve the
-- estimate, and one flight path should not double it.
local function Median(values)
    if #values == 0 then
        return nil
    end

    local sorted = {}

    for index = 1, #values do
        sorted[index] = values[index]
    end

    table.sort(sorted)

    local middle = math.floor(#sorted / 2) + 1

    if #sorted % 2 == 1 then
        return sorted[middle]
    end

    return (sorted[middle - 1] + sorted[middle]) / 2
end

Session.Median = Median

-- The speed to plan with.
--
-- Defaults to however the player is travelling right now, because that is
-- the best available guess at how they will travel next. Falls back to the
-- other bucket rather than to a constant: measured-but-wrong-state beats
-- unmeasured.
function Session.Speed(mounted)
    local bucket

    if mounted == nil then
        bucket = Session.Bucket()
    elseif mounted == true then
        bucket = "mounted"
    elseif mounted == false then
        bucket = "onFoot"
    else
        -- A caller that names a bucket outright: Travel asks for "flying"
        -- when it is costing a journey the player would fly themselves,
        -- which has nothing to do with how they happen to be moving now.
        bucket = mounted
    end

    local preferred = speed.samples[bucket] or {}

    if #preferred >= Session.minSamples then
        return Median(preferred), true
    end

    -- Fall back through the other buckets rather than to a constant:
    -- measured-but-wrong-state beats unmeasured. Ordered nearest-first, so a
    -- missing flying median falls to mounted before it falls to walking.
    local fallbacks = {
        flying  = { "mounted", "onFoot" },
        mounted = { "flying", "onFoot" },
        onFoot  = { "mounted", "flying" },
    }

    for _, name in ipairs(fallbacks[bucket] or {}) do
        local other = speed.samples[name] or {}

        if #other >= Session.minSamples then
            return Median(other), false
        end
    end

    return Session.defaultSpeed, false
end

function Session.SpeedSampleCount(mounted)
    if mounted == nil then
        return #speed.samples.mounted + #speed.samples.onFoot
            + #speed.samples.flying
    end

    if mounted == true then
        return #speed.samples.mounted
    end

    if mounted == false then
        return #speed.samples.onFoot
    end

    return #(speed.samples[mounted] or {})
end

-- The in-memory samples themselves. Exposed so that a round trip through
-- disk can be tested as a round trip -- testing each half against a fixture
-- the other half never produced is how a bucket that was loaded but never
-- saved stayed broken for four releases.
function Session.Samples()
    return speed.samples
end

function Session.SpeedBuckets()
    return {
        mounted = Median(speed.samples.mounted),
        onFoot  = Median(speed.samples.onFoot),
        flying  = Median(speed.samples.flying),
    }
end

------------------------------------------------------------
-- LEARNED TASK DURATION
------------------------------------------------------------

local function Durations()
    return CN.Account("taskDurations")
end

Session.Durations = Durations

Session.minDurationSamples = 4
Session.durationSampleCap  = 25

-- The shortest a thing can be said to have taken once its journey is removed.
--
-- A floor rather than a discard, and a very small one. Discarding every
-- sample where the journey estimate exceeded the whole elapsed span would
-- throw away precisely the fast objectives -- biasing the learned time
-- upward, which is the error this subtraction exists to remove. A floored
-- sample says "the work itself was negligible next to getting there", which
-- for a quest handed in on arrival is exactly true.
Session.minimumWorkSeconds = 0.05

-- How long an objective can sit on the list and still be called instant.
--
-- A minute. Long enough to cover "it was already in front of me and I clicked
-- it", short enough that no real piece of work fits inside it -- and it is
-- measured from the clock rather than inferred from the travel model, which
-- is the whole point of the gate it guards.
Session.instantSpanSeconds = 60

-- When each objective was first put in front of the player. A completion
-- timed from here is "how long it took once it was the thing to do", which is
-- the number a plan needs.
-- BOUNDED, because it was not.
--
-- Every objective the addon decorated used to get an entry here and only a
-- completion removed one. Cross a dozen zones and it accumulates a timestamp
-- for everything that ever scrolled past -- a slow leak I shipped in 0.28.0.
--
-- Two bounds now: entries expire, and the table is capped. Neither costs
-- accuracy, because an entry older than the expiry window would have been
-- rejected as implausible at completion time anyway.
local offeredAt = {}
local offeredCount = 0

Session.offerMemoryCap     = 400
Session.offerMemorySeconds = 1800

-- HYSTERESIS, and why it is not optional.
--
-- Pruning the moment the table reaches its cap means every subsequent insert
-- triggers a full sweep of four hundred entries. Recommend(25) does twenty
-- five inserts, so a single call became ten thousand iterations -- measured
-- at 1.5ms, up from 0.02ms. A fix for a memory leak that costs seventy times
-- the CPU is not a fix.
--
-- So: let it overshoot by a quarter, then prune back to the cap. Sweeps
-- happen once per hundred inserts instead of once per insert, and the table
-- is still bounded, which was the entire point.
Session.offerMemorySlack = 0.25

local function Prune(force)
    local trigger = Session.offerMemoryCap
        * (1 + Session.offerMemorySlack)

    if not force and offeredCount <= trigger then
        return 0
    end

    local now = Session.Now()

    local removed = 0

    for key, record in pairs(offeredAt) do
        if now - record.at > Session.offerMemorySeconds then
            offeredAt[key] = nil
            removed = removed + 1
        end
    end

    offeredCount = offeredCount - removed

    -- Still over cap after expiring? Drop the oldest until it fits. A
    -- timestamp we cannot afford to keep is worth less than a bounded table.
    if offeredCount > Session.offerMemoryCap then
        local ordered = {}

        for key, record in pairs(offeredAt) do
            table.insert(ordered, { key = key, at = record.at })
        end

        table.sort(ordered, function(a, b) return a.at < b.at end)

        local excess = offeredCount - Session.offerMemoryCap

        for index = 1, excess do
            offeredAt[ordered[index].key] = nil
            removed = removed + 1
        end

        offeredCount = offeredCount - excess
    end

    return removed
end

Session.Prune = Prune

function Session.OfferedCount()
    return offeredCount
end

function Session.NoteOffered(objective)
    if type(objective) ~= "table" or not objective.type or not objective.id then
        return
    end

    local key = tostring(objective.type) .. ":" .. tostring(objective.id)

    -- WHAT THE JOURNEY WAS EXPECTED TO COST, RECORDED WITH THE CLOCK.
    --
    -- The elapsed span between "this was recommended" and "this was finished"
    -- contains the walk to it. The planner then ADDS a separately computed
    -- travel leg to a sum of those spans, so the journey was counted twice --
    -- and once per objective at a stop, which is worst exactly where the
    -- router is trying to reward batching. Four quests six minutes away came
    -- out at thirty-six minutes against a true twelve, reported confident.
    --
    -- Subtracting the addon's own estimate makes the stored number a WORK
    -- time, which is what every consumer already assumes it is. Using the
    -- addon's own model rather than a measurement keeps the two consistent
    -- even where the model is imperfect: the same quantity is removed here
    -- and added back there.
    -- AND WHETHER THAT ESTIMATE IS WORTH ANYTHING, which 0.55.0 did not ask.
    --
    -- An objective with no known location has no travel cost, and this
    -- recorded zero -- which says "you were standing on it". The whole span
    -- then went into the store as WORK time, inflating every estimate for
    -- that type. An objective whose cost saturates at the ceiling records
    -- `Travel.maximumCost` (40) x `CN.secondsPerCostPoint` (30) = 1200
    -- seconds, and 1200 is also the span this addon rejects as implausible --
    -- so the window in which a saturated sample could produce anything but
    -- the floor was arithmetically EMPTY. Every cross-continent completion
    -- stored 0.05 seconds, the median collapsed to 0.05, and `/cn plan`
    -- reported a zone as four minutes of work.
    --
    -- Three states, not two:
    --
    --   a real cost        subtract it
    --   no cost at all     nothing to subtract; an objective with no location
    --                      is not a journey, and the planner adds no leg for
    --                      it either, so zero is the consistent answer
    --   a SATURATED cost   the model saying "far away, I stopped counting" --
    --                      not a measurement, and not subtractable
    -- THROUGH THE ONE FUNCTION THAT OWNS THE RULE. 0.70.0.
    --
    -- This was a second copy of "is this cost a measurement", written before
    -- `CN.SecondsNeeded` existed and then left in place when it did -- and
    -- the comment on that function names THIS one as the authority it was
    -- copied from. The two disagreed immediately: a quest with no known
    -- location carries `CN.unknownLocationCost`, which this subtracted as
    -- four minutes of journey from a measured span, biasing the learned work
    -- time down. That is the class of error the paragraph above exists to
    -- prevent.
    --
    -- `CN.SecondsNeeded` is nil for anything that was not costed and for
    -- anything at the clamp, which is exactly the two cases described above.
    local travelSeconds = CN.SecondsNeeded and CN.SecondsNeeded(objective)

    local travelKnown = travelSeconds ~= nil

    if not travelSeconds then
        travelSeconds = 0

        -- NO JOURNEY AT ALL IS A KNOWN ZERO; A JOURNEY NOBODY MEASURED IS
        -- NOT. That is the distinction the paragraph above draws, and it is
        -- the whole reason this is not simply `travelCost or 0`: an objective
        -- with no travel cost is placeless -- there is nothing to subtract
        -- and nothing unknown about it -- while one carrying a constant the
        -- router invented has a journey whose length nobody established.
        local cost = objective.travelCost

        -- AND A ROW WITH NO PLACE IN IT HAS NO JOURNEY TO SUBTRACT. 0.72.0.
        --
        -- Several providers set a small hand-picked `travelCost` -- 2 or 3 --
        -- for something that has no coordinates at all: an instance lockout,
        -- the vault, a thing you are waiting on. It is a ranking nudge, not a
        -- measurement, so it carries no `travelCosted` flag and 0.71.0's move
        -- to `CN.SecondsNeeded` began rejecting every one of those samples.
        --
        -- Permanently, and silently: `Session.TypicalSeconds("INSTANCE")`
        -- could never become non-nil again, so `/cn plan` reported "not
        -- measured" for those rows for the life of the account. The version
        -- before this kept the samples with a small bias; this version kept
        -- none.
        --
        -- The question that actually matters is the one `EstimateHub` asks:
        -- will the planner add a travel leg back for this row? It prices a
        -- hub from its coordinates, so a row without them gets nothing added
        -- and needs nothing subtracted. A row WITH coordinates and no
        -- confident cost is still rejected, which is what the paragraph above
        -- is for.
        -- PLACELESS MEANS NO MAP AT ALL, NOT "NO POINT ON A MAP". 0.73.0.
        --
        -- 0.72.0 wrote this as "not (mapID and x and y)", which is true for a
        -- row that HAS a map and no coordinates -- and `Quests.GetLocation`
        -- returns exactly that shape whenever a quest's POI has not resolved,
        -- which is common and temporary. `CN.TravelCost(mapID, nil, nil)`
        -- answers with the routing constant, so such a row was recorded as a
        -- KNOWN ZERO journey: ten minutes of flying plus five of questing
        -- became fifteen minutes of QUEST work, in the highest-volume type
        -- feeding `/cn plan`'s headline figure.
        --
        -- Worse, it sticks: the held estimate is only ever revised DOWNWARD,
        -- and zero is the floor, so a quest first seen before its POI
        -- resolved stayed pinned at "known, zero journey" for the rest of its
        -- life on the list even after it acquired real coordinates.
        --
        -- The rows this clause exists for -- instances, the vault, the
        -- waiting list, sets, orders, inventory -- carry no `mapID` at all.
        travelKnown = cost == nil or cost == 0
            or (objective.mapID == nil
                and objective.x == nil and objective.y == nil)
    end

    local held = offeredAt[key]

    -- THE CLOCK IS STAMPED ONCE; THE JOURNEY IS RE-STAMPED AS IT SHORTENS.
    --
    -- This returned early the moment the key existed, so the travel estimate
    -- was frozen at whatever it was the FIRST time the objective appeared on
    -- the list -- from wherever the addon thought you were then. Fly to that
    -- zone, quest for eight minutes, hand it in, and the sample was compared
    -- against a journey cost from the continent you left. Those samples were
    -- rejected, so a whole class of ordinary completions taught nothing and
    -- the ones that survived were the ones where the work outlasted a
    -- generous estimate -- which biases the median LONG, the mirror of the
    -- defect 0.55.0 fixed.
    --
    -- The SMALLEST estimate seen while it was on the list is the right one:
    -- it is how far you had left to go at the closest you got, which is the
    -- part of the span that was actually journey. `at` is never touched --
    -- that is the measurement.
    if held then
        if travelKnown and (not held.known or travelSeconds < held.travel) then
            held.travel = travelSeconds
            held.known  = true
        end

        return
    end

    offeredAt[key] = {
        at     = Session.Now(),
        travel = travelSeconds,
        known  = travelKnown,
    }
    offeredCount   = offeredCount + 1

    Prune()
end

function Session.NoteCompleted(objectiveType, id)
    if not objectiveType or not id then
        return nil
    end

    local key = tostring(objectiveType) .. ":" .. tostring(id)

    local started = offeredAt[key]

    if offeredAt[key] then
        offeredAt[key] = nil
        offeredCount   = offeredCount - 1
    end

    if not started then
        return nil
    end

    -- THE FLOOR AND THE DISCARD USED TO CANCEL EACH OTHER OUT.
    --
    -- Until 0.55.0 this subtracted the journey first, clamped anything short
    -- up to `Session.minimumWorkSeconds`, and then threw away everything at or
    -- below 0.05 -- the same number the clamp had just produced. Every sample
    -- the floor exists to preserve was floored and then discarded, which is
    -- the precise bias the floor was written to remove, and `/cn plan` read
    -- long, confidently, in every version that shipped it.
    --
    -- THREE QUANTITIES, IN THE RIGHT ORDER. The mistake was doing all the
    -- reasoning on one variable that had already been adjusted.
    --
    --   `span`    how long the objective was actually on the list. This is
    --             the only quantity plausibility can be judged on: it comes
    --             from the clock and from nothing the addon guessed.
    --
    --   `elapsed` the span with the addon's own travel estimate removed, so
    --             the planner can add a real leg back without counting the
    --             journey twice.
    --
    --   the floor which applies to `elapsed` alone.
    local span = Session.Now() - started.at

    -- A clock that went backwards. `GetTime` is monotonic, so this means the
    -- offer was recorded against a different clock -- a reload, or a stored
    -- timestamp that outlived the session it was taken in.
    --
    -- NOT `<= 0`. Zero is an objective offered and completed inside one frame,
    -- which is a real thing -- accepting a quest from an item that completes
    -- it -- and it is precisely what the floor below is for. Rejecting it
    -- would reintroduce the bias this release exists to remove.
    if span < 0 then
        return nil
    end

    -- A SATURATED JOURNEY ESTIMATE IS NOT A JOURNEY ESTIMATE.
    --
    -- The stored number is meant to be WORK time, which is the span with the
    -- journey taken out. When the cost hit its own ceiling there is nothing
    -- honest to take out, and no way to tell a two-minute quest reached after
    -- ten minutes of flying from a twelve-minute quest. The addon's standing
    -- rule is to report nothing rather than to invent a denominator.
    if not started.known then
        return nil
    end

    -- Over twenty minutes was not "doing the thing", it was living your life
    -- with the thing still on the list. Judged on the SPAN: judging it on the
    -- travel-adjusted figure let a forty-minute span with a twenty-five minute
    -- estimated journey through as a confident fifteen-minute sample.
    if span > 1200 then
        return nil
    end

    -- The journey out, which the caller will add back separately.
    local elapsed = span - (started.travel or 0)

    -- THE FLOOR IS FOR THINGS THAT WERE GENUINELY INSTANT, AND ONLY THOSE.
    --
    -- 0.55.0 floored every sample whose journey estimate exceeded the span.
    -- That is right for the case it was written for -- a quest handed in on
    -- arrival, where the work really was negligible -- and wrong for the case
    -- that is far more common: `NoteOffered` stamps the cost ONCE, from
    -- wherever the addon thought you were when the objective first entered
    -- the list, and never revises it. Fly to that zone, quest for eight
    -- minutes, hand it in, and the sample is compared against a journey cost
    -- from the continent you left. Every one of those became 0.05 seconds.
    --
    -- Filed by type and taken as a median over 25 samples, enough of them
    -- pin the median at the floor -- and then `/cn plan` reports a zone as
    -- four minutes of work, confidently, because 0.05 is not nil.
    --
    -- So the floor is gated on the SPAN, which is a measurement and not an
    -- estimate. Under a minute on the list is instant however far the model
    -- thought you had to go. Over a minute with an estimate that swallowed
    -- the whole span means the estimate was stale, the split is unknowable,
    -- and the sample is dropped rather than flattened.
    if elapsed < Session.minimumWorkSeconds then
        if span > Session.instantSpanSeconds then
            return nil
        end

        elapsed = Session.minimumWorkSeconds
    end

    local store = Durations()

    store[objectiveType] = store[objectiveType] or {}

    table.insert(store[objectiveType], elapsed)

    Session.NoteDurationsChanged()

    while #store[objectiveType] > Session.durationSampleCap do
        table.remove(store[objectiveType], 1)
    end

    DebugPrint(objectiveType .. " took " .. elapsed .. "s ("
        .. #store[objectiveType] .. " samples).")

    return elapsed
end

-- Seconds this type usually takes, or NIL when the addon has not watched it
-- often enough to have an opinion. Nil is a real answer here and every
-- caller must handle it rather than substituting a guess.
-- MEMOISED PER TYPE, because it is asked per CANDIDATE.
--
-- The Session decorator asks this for every objective it decorates, and it
-- copies and sorts up to twenty-five samples to answer. Sixty pets is sixty
-- copies-and-sorts for one number, and the cost scales with the length of the
-- candidate list rather than with the nineteen objective types there are.
--
-- The store only changes when a completion is recorded, which is the same
-- shape `Preference.Multiplier` has used since 0.54.0.
Session.durationGeneration = 0

local typicalCache, typicalGeneration = {}, nil

function Session.NoteDurationsChanged()
    Session.durationGeneration = Session.durationGeneration + 1

    -- AND SAY SO WHERE THE DECORATOR WILL HEAR IT.
    --
    -- The Session decorator stamps `estimatedTime` onto candidates, and a
    -- provider whose rows are unchanged takes the unchanged-provider
    -- shortcut and is never re-decorated -- which 0.57.0 made the COMMON
    -- case. So a duration the addon had just learned was never applied to
    -- anything already on the list, and `/cn mode fastest`'s second lever
    -- stayed inert. `CN.decoratorGeneration` is the only thing that defeats
    -- that shortcut; Goals and Harvest already use it.
    -- Both halves. See CN.NoteDecoratorsChanged: bumping the counter alone
    -- cannot make a provider that is not already stale re-decorate.
    CN.NoteDecoratorsChanged()
end

function Session.TypicalSeconds(objectiveType)
    if not objectiveType then
        return nil
    end

    if typicalGeneration ~= Session.durationGeneration then
        typicalCache     = {}
        typicalGeneration = Session.durationGeneration
    end

    local samples = Durations()[objectiveType]

    -- KEYED ON THE SAMPLE COUNT AS WELL AS THE GENERATION.
    --
    -- `NoteDurationsChanged` catches every write this file makes. It cannot
    -- catch a write from somewhere else -- a future importer, a fixture, a
    -- `/cn` command that seeds the store -- and a memo that is silently wrong
    -- about a learned duration is the sort of defect this project keeps
    -- finding. The count is one length operation and it makes the memo
    -- self-correcting rather than dependent on everybody remembering.
    local held = typicalCache[objectiveType]

    local count = samples and #samples or 0

    if held ~= nil and held.count == count then
        return held.median
    end

    if not samples or count < Session.minDurationSamples then
        typicalCache[objectiveType] = { count = count, median = nil }

        return nil
    end

    local median = Median(samples)

    typicalCache[objectiveType] = { count = count, median = median }

    return median
end

function Session.HasEnoughData()
    for _, samples in pairs(Durations()) do
        if #samples >= Session.minDurationSamples then
            return true
        end
    end

    return false
end

------------------------------------------------------------
-- THE PLAN
------------------------------------------------------------

-- Estimates a stop: travel to it, plus the work at it.
--
-- Returns seconds and a confidence flag. `false` means part of this was not
-- measured, and callers must say so out loud.
function Session.EstimateHub(hub, fromX, fromY)
    local confident = true

    local travelSeconds = 0

    -- ASK TRAVEL, WHICH KNOWS ABOUT FLIGHT PATHS.
    --
    -- This used to be a straight line at running speed between two points on
    -- the same map, and gave up entirely when the maps differed -- so a stop
    -- one zone away was either uncosted or costed as though you would run
    -- there in a straight line through the mountains.
    local travel = CN:GetModule("Travel")

    local playerMap = CN.GetPlayerPosition()

    if travel and hub.mapID and hub.x and hub.y and fromX and fromY and playerMap then
        local seconds, sure = travel.EstimateSeconds(
            playerMap, fromX, fromY, hub.mapID, hub.x, hub.y)

        if seconds then
            travelSeconds = seconds

            if not sure then
                confident = false
            end
        else
            confident = false
        end
    else
        confident = false
    end

    local workSeconds = 0

    for _, objective in ipairs(hub.objectives or {}) do
        local typical = Session.TypicalSeconds(objective.type)

        if typical then
            workSeconds = workSeconds + typical
        else
            confident = false
        end
    end

    return travelSeconds + workSeconds, confident, travelSeconds, workSeconds
end

-- Builds a route and takes stops from the front of it until the budget is
-- spent.
--
-- Takes from the FRONT rather than choosing the best-fitting subset. The
-- route is already ordered to minimise walking; cherry-picking stops out of
-- it produces a plan that fits the clock and makes you cross the zone twice.
-- HOW LONG YOU ACTUALLY PLAY.
--
-- `/cn plan` has always needed a number, and its example has always been
-- thirty minutes -- a figure chosen because it sounds reasonable, not because
-- anybody plays in thirty-minute units. The addon watches how long sessions
-- run anyway; asking it is cheaper than asking the player.
--
-- Stored per character, capped, and used only as the DEFAULT: an explicit
-- number always wins, because "I have twenty minutes" is a fact about tonight
-- that no amount of history overrides.
Session.lengthSampleCap = 20
Session.minLengthSamples = 3

local sessionStartedAt = nil

local function Lengths()
    local character = CN.character

    if not character then
        return nil
    end

    character.sessionLengths = character.sessionLengths or {}

    return character.sessionLengths
end

Session.Lengths = Lengths

function Session.BeginSession()
    sessionStartedAt = Session.Now()
end

-- Called at logout and on a reload. A reload is not the end of a session, but
-- there is no way to tell one from the other at the moment it happens -- so
-- very short sessions are discarded rather than counted, which handles the
-- reload case without needing to detect it.
Session.minCountableMinutes = 8

function Session.EndSession()
    local lengths = Lengths()

    if not lengths or not sessionStartedAt then
        return false
    end

    local minutes = (Session.Now() - sessionStartedAt) / 60

    sessionStartedAt = nil

    if minutes < Session.minCountableMinutes or minutes > 720 then
        return false
    end

    table.insert(lengths, math.floor(minutes + 0.5))

    while #lengths > Session.lengthSampleCap do
        table.remove(lengths, 1)
    end

    return true
end

-- Returns minutes and whether it was measured.
function Session.TypicalSessionMinutes()
    local lengths = Lengths()

    if not lengths or #lengths < Session.minLengthSamples then
        return 30, false
    end

    return math.floor(Median(lengths) + 0.5), true
end

CN:OnLogin(function()
    Session.BeginSession()
end)

CN:RegisterEvent("PLAYER_LOGOUT", function()
    Session.EndSession()
end)

function Session.Plan(minutes)
    local requested = tonumber(minutes)

    -- THE RANKING KNOWS WHERE YOU ARE; THE PLANNER DID NOT.
    --
    -- 0.43.0 taught the ranking about being dead and being in an instance,
    -- and the session planner carried on laying out a walking route through
    -- the open world regardless -- which is a plan the player cannot start.
    local group = CN:GetModule("Group")

    local situation = group and group.Situation()

    -- INSIDE IS INSIDE, ALONE OR NOT. 0.81.0.
    --
    -- This asked `Situation() == "instanced"`, which 0.80.0 correctly
    -- narrowed to mean "in an instance WITH A GROUP" -- and in doing so
    -- opened this hole: a player soloing an old raid was handed a walking
    -- route through the open world, which is still a plan they cannot start
    -- without a loading screen. The planner's question is about the doorway,
    -- not about the company.
    local inside = group and group.InsideInstance and group.InsideInstance()

    if situation == "dead" or inside then
        return {
            minutes   = math.floor(((requested
                or Session.TypicalSessionMinutes()) or 0) + 0.5),
            stops     = {},
            seconds   = 0,
            confident = true,
            skipped   = 0,
            -- The WORD is what blocked the plan, not the social state:
            -- a solo player inside an instance is "solo", and reporting
            -- that as the reason would read as a bug.
            blocked   = (situation == "dead") and "dead" or "instanced",
            notice    = group and group.Notice(),
        }
    end

    -- No number given: use however long this character usually plays, rather
    -- than a round thirty that was only ever a placeholder.
    --
    -- ROUNDED HERE, so the budget and the headline are the same number.
    --
    -- Lua 5.3 and later make `/` always produce a float, so `/cn plan 12.5`
    -- gave `minutes = 12.5` and `string.format("%dm", 12.5)` -- an error on
    -- 5.4, and on the game's 5.1 a silent "12m" printed above a plan built
    -- against 750 seconds. Rounding only the DISPLAY fixed the throw and left
    -- the disagreement, in the other direction: "13m" above a 12.5-minute
    -- plan. One quantity, one rounding, at the top.
    local budgetMinutes = math.floor(((requested
        or Session.TypicalSessionMinutes()) or 0) + 0.5)

    -- A request that rounds to nothing is not a plan. `/cn plan 0.4` passed
    -- the command's own `<= 0` guard and produced a zero-minute budget.
    if budgetMinutes < 1 then
        budgetMinutes = 1
    end

    local budget = budgetMinutes * 60

    local mapID, x, y = CN.GetPlayerPosition()

    local plan = {
        -- The number the budget above was built from, not a second derivation
        -- of it -- and the budget itself beside it, so the invariant that the
        -- headline describes the plan is one a test can state rather than
        -- infer. `/cn plan 12.5` printed "13m" above a plan built against
        -- twelve and a half, and nothing could see the difference.
        minutes       = budgetMinutes,
        budgetSeconds = budget,
        stops     = {},
        seconds   = 0,
        confident = true,
        skipped   = 0,
    }

    if not mapID then
        return plan
    end

    local _, _, hubs = CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    if type(hubs) ~= "table" then
        return plan
    end

    local currentX, currentY = x or 0.5, y or 0.5

    for _, hub in ipairs(hubs) do
        local seconds, confident, travel, work =
            Session.EstimateHub(hub, currentX, currentY)

        -- STOP AT THE FIRST STOP THAT DOES NOT FIT.
        --
        -- This used to `continue` past an overrunning hub and keep testing
        -- later ones, which is exactly the cherry-picking the comment above
        -- this function forbids -- and it forbids it for a good reason: the
        -- route is ordered to minimise walking, so skipping the middle of it
        -- and taking the far end makes you cross the zone twice to save a
        -- number on a screen.
        --
        -- It was also arithmetically wrong even on its own terms: the skipped
        -- hub's position was not advanced past, so every later hub's travel
        -- leg was costed from wherever the last ACCEPTED stop was, which is
        -- not where the player would be.
        -- THE FIRST STOP IS NOT EXEMPT FROM THE CLOCK.
        --
        -- `#plan.stops > 0` meant stop one was admitted whatever it cost, so
        -- `/cn plan 5` against a forty-five minute hub printed "1 stop, about
        -- 45m of the 5m you have" with nothing flagging that the budget had
        -- been blown ninefold. Taking it is still often the right call --
        -- there may be nothing smaller -- but the player has to be told, not
        -- shown a plan that silently is not a plan.
        if plan.seconds + seconds > budget and #plan.stops > 0 then
            plan.skipped = plan.skipped + 1

            break
        else
            table.insert(plan.stops, {
                hub       = hub,
                seconds   = seconds,
                travel    = travel,
                work      = work,
                summary   = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                confident = confident,
            })

            plan.seconds = plan.seconds + seconds

            if not confident then
                plan.confident = false
            end

            currentX, currentY = hub.x or currentX, hub.y or currentY
        end
    end

    -- `skipped` counts the stop that did not fit plus everything behind it,
    -- because that is what the player is not doing tonight. Counting only the
    -- one that overran would report "1 skipped" for a route with nine stops
    -- left in it.
    if plan.skipped > 0 then
        plan.skipped = #hubs - #plan.stops
    end

    -- Said out loud when the only thing available does not fit.
    plan.overran = plan.seconds > budget

    return plan
end

-- SHORT IS NOT FREE.
--
-- Rounded to whole minutes, a twenty-five second stop rendered as "0m" in
-- `/cn plan` and `/cn travel`, which reads as costing nothing rather than as
-- costing very little. Under a minute is reported in seconds.
function Session.FormatDuration(seconds)
    if not seconds or seconds <= 0 then
        return "0m"
    end

    if seconds < 60 then
        return math.max(1, math.floor(seconds + 0.5)) .. "s"
    end

    local minutes = math.floor(seconds / 60 + 0.5)

    if minutes < 60 then
        return minutes .. "m"
    end

    return string.format("%dh %dm", math.floor(minutes / 60), minutes % 60)
end

------------------------------------------------------------
-- WIRING
------------------------------------------------------------

-- The clock starts when something is RECOMMENDED, not when it is collected.
--
-- 0.28.0 hung this on a candidate decorator, which meant a timestamp was
-- taken for every objective the addon knew about on every rebuild -- two
-- hundred at retail scale, the overwhelming majority of which the player
-- never saw and no plan ever used. Wrong on cost and wrong on meaning: an
-- objective sitting at rank 180 has not been "offered" to anybody.
--
-- Recommend() is the moment something is actually put in front of a player.
function Session.NoteRecommended(list)
    for index = 1, math.min(#list, Session.timedRecommendations) do
        Session.NoteOffered(list[index])
    end

    return list
end

Session.timedRecommendations = 25

if CN.RegisterRecommendationHook then
    CN.RegisterRecommendationHook("SessionTiming", Session.NoteRecommended)
end

CN:RegisterEvent("QUEST_TURNED_IN", function(_, questID)
    Session.NoteCompleted(CN.objectiveTypes.QUEST, questID)
end)

CN:RegisterEvent("NEW_PET_ADDED", function()
    -- The client does not say which pet, so nothing can be timed here
    -- honestly. Left deliberately unhandled rather than attributing the
    -- elapsed time to a guess.
end)

local ticker

CN:OnLogin(function()
    Session.LoadSamples()

    Session.Observe()

    if C_Timer and C_Timer.NewTicker and not ticker then
        -- GUARDED. A C_Timer callback that throws goes to the client's own
        -- error handler, and a REPEATING ticker means a repeating error box:
        -- one bad observation and the player gets a popup every ten seconds
        -- for the rest of the session. Navigation's ticker has been guarded
        -- since 0.34.0; the four others were not.
        ticker = C_Timer.NewTicker(10, function()
            CN.Guard("Session.Observe", Session.Observe)
        end)
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "plan",
    aliases = { "time", "budget" },
    args    = "<minutes>",
    order   = 13,
    help    = "What fits in the time you actually have.",
    handler = function(args)
        local minutes = tonumber(CN.Trim(args or ""))

        if not minutes or minutes <= 0 then
            -- No number is no longer a usage error. The addon has watched how
            -- long this character plays; asking it beats asking the player,
            -- and a player who wanted a specific number can still say one.
            local typical, measured = Session.TypicalSessionMinutes()

            minutes = typical

            -- ONE UNIT PER QUANTITY. This said "Planning 45 minutes" and
            -- then "3 stops, about 32m of the 45m you have" four lines
            -- later -- the same quantity, two units, in one command.
            Print("Planning " .. Session.FormatDuration(minutes * 60)
                .. " " .. CN.DASH .. " "
                .. (measured
                    and ("|cff8a8f96your usual session on this character|r")
                    or ("|cff8a8f96a default; play a few sessions and this "
                        .. "becomes your own figure|r")))
        end

        local plan = Session.Plan(minutes)

        if plan.blocked then
            -- Not "nothing to plan around": there is plenty, and the player
            -- cannot start any of it from where they are. Saying the first
            -- when the second is true is how an addon earns a reputation for
            -- not paying attention.
            Print(plan.notice or "Not while you are in the middle of that.")
            Print("|cff8a8f96The plan is waiting; ask again when you are back "
                .. "in the world.|r")
            return
        end

        if #plan.stops == 0 then
            Print("Nothing here to plan around.")
            return
        end

        -- THE SUM OF NUMBERS TOO UNCERTAIN TO SHOW IS NOT A CERTAIN NUMBER.
        --
        -- Each individual stop below refuses to print a duration it is not
        -- confident in, and this headline printed their total as a plain
        -- figure regardless. One convention, both lines.
        Print(string.format("%d stop%s, about %s of the %dm you have:",
            #plan.stops,
            CN.Pluralize(#plan.stops, ""),
            CN.WithConfidence(Session.FormatDuration(plan.seconds),
                CN.ConfidenceFor(plan.confident)),
            plan.minutes))

        for index, stop in ipairs(plan.stops) do
            CN.PrintLine(string.format("  %d. |cffffc74f%s|r |cff8a8f96%s|r",
                index,
                tostring(stop.summary or "stop"),
                stop.confident and Session.FormatDuration(stop.seconds)
                    or (CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " time")))
        end

        if plan.skipped > 0 then
            Print("|cff8a8f96" .. plan.skipped
                .. (plan.skipped == 1 and " further stop did not fit.|r"
                    or " further stops did not fit.|r"))
        end

        if plan.overran then
            Print("|cffffc74fThe nearest stop is longer than the time you "
                .. "have.|r |cff8a8f96Nothing smaller was available, so it "
                .. "is shown anyway" .. CN.DASH .. "but it will not fit.|r")
        end

        if not plan.confident then
            -- THE COUNT MUST BE THE COUNT BEHIND THE RATE.
            --
            -- `Speed()` answers from one bucket; `SpeedSampleCount()` with no
            -- argument summed all three. So the line justifying confidence in
            -- a 62 yd/s flying median cited forty-six samples, forty of which
            -- were on-foot readings at seven that had no part in it --
            -- overstating the evidence sevenfold in the one place whose whole
            -- job is to say how much evidence there is.
            local bucket = Session.Bucket()

            local rate, measured = Session.Speed(bucket)

            Print("|cffffc74fSome of this is not measured yet.|r "
                .. "|cff8a8f96Travel speed: "
                .. (measured and string.format("%.0f yd/s from %d %s samples",
                        rate, Session.SpeedSampleCount(bucket), bucket)
                    or "still learning")
                .. ". Task times are learned from your own play, so the "
                .. "estimate sharpens as you go rather than starting from "
                .. "numbers nobody measured.|r")
        end
    end,
}

------------------------------------------------------------
-- HOW LONG A THING TAKES, AS A SCORING TERM
------------------------------------------------------------

-- THE LEVER `/cn mode fastest` HAS ALWAYS ADVERTISED AND NEVER HAD.
--
-- `estimatedTime` is a declared scoring weight, summed on every objective,
-- printed by `/cn order`, and overridden by the `fastest` profile to -1.5 --
-- and nothing in the addon has ever set the field. So the mode's second lever
-- did nothing: `/cn mode fastest` was a travel-cost change wearing the name
-- of something broader.
--
-- The data to fill it has been collected since 0.41.0. This is the wiring.
--
-- SCALED, NOT RAW. A raw duration in seconds would swamp every other term --
-- a twenty-minute dungeon would arrive at 1200 against a completion value of
-- 5. The term is the duration in units of the typical objective, so 1 means
-- "about as long as things usually take", 3 means "three times as long", and
-- an objective the addon has never timed contributes nothing rather than a
-- guess. The addon does not invent a duration it has not watched.
Session.timeScaleSeconds = 300

function Session.TimeCost(objectiveType)
    local typical = Session.TypicalSeconds(objectiveType)

    if not typical or typical <= 0 then
        return nil
    end

    return typical / Session.timeScaleSeconds
end

-- A DECORATOR RECEIVES ONE OBJECTIVE, NOT A LIST.
--
-- This took `candidates` and iterated it, which yields nothing when handed a
-- single objective table -- so the field was never set on anything and
-- `/cn mode fastest` kept the inert second lever that 0.48.0 recorded as
-- fixed. Two mistakes in one edit: this, and the block landing INSIDE
-- Session.Speed because the anchor `return Session` also matched
-- `return Session.defaultSpeed`. Everything here was therefore defined only
-- as a side effect of calling Speed(), and re-registered on every call that
-- fell through all three buckets -- fifty-seven registrations of the same
-- decorator in one session.
--
-- The harness asserted that TimeCost exists and then hand-built objectives
-- with estimatedTime already set, testing the scorer against a fixture the
-- producer never made. That is precisely the trap this file's own comment
-- about the flying speed bucket warns about.
CN.RegisterCandidateDecorator("Session", function(objective)
    if type(objective) == "table" and objective.type then
        objective.estimatedTime = Session.TimeCost(objective.type)
    end
end)


return Session
'@

$Embedded['Modules\Alts.lua'] = @'
-- Modules/Alts.lua
-- Completion Navigator :: which character should be doing this.
--
-- The addon has known the answer for a while and had no way to volunteer it.
-- `Warband.WhoShould` answers one objective at a time, when asked, buried in
-- `/cn why`. The question a player actually has is the other way round:
--
--   "Is the character I am logged into the right one to be playing tonight?"
--
-- Nothing answered that. Every recommendation was implicitly "do this, here,
-- now, as you", even when the honest answer was "your Druid is two quests
-- from the same reward and this reputation does not carry across anyway".
--
-- WHAT THIS CAN AND CANNOT KNOW.
--
-- Everything here is built from what each character recorded the last time it
-- logged in. That is a real limitation and it is not a small one: a character
-- last seen three weeks ago is described as it was three weeks ago. The addon
-- says so rather than presenting stale data as current, and weights a
-- recommendation down as it ages -- a suggestion to switch to a character
-- whose data predates a patch is worth less than one about yesterday's.
--
-- It also refuses to recommend switching for anything account-wide. If the
-- progress carries across the Warband, the character doing it is irrelevant
-- and saying otherwise would be advice that costs a loading screen and buys
-- nothing.

local ADDON_NAME, CN = ...

local Alts = CN:RegisterModule("Alts")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- STALENESS
------------------------------------------------------------

-- How old a character's data is, in days.
function Alts.AgeDays(character)
    if not character or not character.lastSeen then
        return nil
    end

    return (time() - character.lastSeen) / 86400
end

-- Past this, the addon still reports what it knows but stops making
-- suggestions from it. A month-old snapshot of a character is a description
-- of a character that may not exist in that form any more.
Alts.staleDays = 30

function Alts.DescribeAge(character)
    local days = Alts.AgeDays(character)

    if not days then
        return "never seen"
    end

    if days < 1 then
        return "today"
    end

    if days < 2 then
        return "yesterday"
    end

    if days < 14 then
        return string.format("%d days ago", math.floor(days))
    end

    return string.format("%d weeks ago", math.floor(days / 7))
end

------------------------------------------------------------
-- WHAT IS WORTH SWITCHING FOR
------------------------------------------------------------

-- Only character-specific work can justify a switch. Account-wide progress
-- is, by definition, indifferent to who does it.
-- `QUEST` REMOVED. 0.79.0.
--
-- `Warband.WhoShould` has no quest branch: it falls through to "not tracked
-- per character" with a nil key, so this entry could never produce a
-- suggestion. A configuration line that reads as a supported feature and is
-- not one -- the shape this project keeps finding as a dead reader, here as a
-- dead switch.
--
-- The addon does not know which character a quest belongs to. Restoring the
-- entry means giving `WhoShould` a quest branch first.
Alts.switchableTypes = {
    REPUTATION = true,
    RECIPE     = true,
    PROFESSION = true,
    TITLE      = true,
}

-- One assignment: a character, a reason, and what it is for.
local function NewAssignment(key, character, objective, reason)
    return {
        key       = key,
        name      = character and character.name or key,
        realm     = character and character.realm,
        class     = character and character.class,
        level     = character and character.level,
        ageDays   = Alts.AgeDays(character),
        objective = objective,
        reason    = reason,
    }
end

-- For each of the top recommendations, ask whether somebody else should be
-- doing it.
--
-- Bounded deliberately: this walks the roster per objective, and answering
-- for two hundred candidates would cost more than the answer is worth. The
-- things a player will actually do next are the things worth asking about.
Alts.considered = 20

function Alts.Assignments()
    local assignments = {}

    if not CN.Recommend then
        return assignments
    end

    local warband = CN:GetModule("Warband")

    if not warband or not warband.WhoShould then
        return assignments
    end

    local seen = {}

    -- QUIETLY: this asks "which character should do each of these" and
    -- prints a handful of names. Nothing here is shown to the player as a
    -- recommendation, and counting twenty rows as offered -- and starting a
    -- work clock on each -- is the defect 0.68.0 added `quiet` for. 0.69.0.
    for _, objective in ipairs(CN.Recommend(Alts.considered, true) or {}) do
        if Alts.switchableTypes[objective.type] then
            local ok, bestKey, detail, scope, switchable =
                pcall(warband.WhoShould, objective.type, objective.id)

            -- "account-wide" is a real answer meaning the question does not
            -- apply, and must never become a suggestion to switch.
            --
            -- AND NEITHER MUST "that character has already done it". 0.79.0.
            --
            -- For a recipe or a title the named character is the HOLDER, and
            -- switching to them cannot do it again -- a title in particular
            -- is per-character and unrepeatable. This surface printed
            -- "already knows it: Bob, Carol" under "Bob could do 2 of
            -- these". See `Warband.WhoShould`'s fourth return.
            if ok and bestKey and switchable ~= false
                and scope ~= CN.scopes.ACCOUNT
                and bestKey ~= CN.characterKey then

                local character = CN.db and CN.db.characters
                    and CN.db.characters[bestKey]

                local age = Alts.AgeDays(character)

                if not age or age <= Alts.staleDays then
                    local key = bestKey .. "|" .. tostring(objective.type)
                        .. "|" .. tostring(objective.id)

                    if not seen[key] then
                        seen[key] = true

                        table.insert(assignments,
                            -- THE SENTENCE, THEN THE NAMES. 0.79.0. This
                            -- was `scope .. ": " .. detail`, which reads as
                            -- a label followed by a value when the two are a
                            -- reason and a list of characters.
                            NewAssignment(bestKey, character, objective,
                                detail and (scope .. " (" .. detail .. ")")
                                    or scope))
                    end
                end
            end
        end
    end

    return assignments
end

-- Grouped by character, because "switch to this one" is the decision, and
-- three reasons to switch to the same character is a stronger case than one.
function Alts.ByCharacter()
    local grouped, order = {}, {}

    for _, assignment in ipairs(Alts.Assignments()) do
        if not grouped[assignment.key] then
            grouped[assignment.key] = {
                key     = assignment.key,
                name    = assignment.name,
                realm   = assignment.realm,
                class   = assignment.class,
                level   = assignment.level,
                ageDays = assignment.ageDays,
                items   = {},
            }

            table.insert(order, assignment.key)
        end

        table.insert(grouped[assignment.key].items, assignment)
    end

    local rows = {}

    for _, key in ipairs(order) do
        table.insert(rows, grouped[key])
    end

    -- The strongest case first: most reasons, then freshest data.
    table.sort(rows, function(a, b)
        if #a.items ~= #b.items then
            return #a.items > #b.items
        end

        return (a.ageDays or math.huge) < (b.ageDays or math.huge)
    end)

    return rows
end

------------------------------------------------------------
-- THE VERDICT
------------------------------------------------------------

-- Should you be playing somebody else?
--
-- Answers "no" far more often than "yes", and that is correct. A tool that
-- suggests a loading screen every time you log in is a tool people turn off.
Alts.minimumReasons = 2

function Alts.Verdict()
    local rows = Alts.ByCharacter()

    if #rows == 0 then
        return nil, "This character is the right one for everything on the list."
    end

    local best = rows[1]

    if #best.items < Alts.minimumReasons then
        return nil, string.format(
            "Nothing worth a loading screen. %s could do 1 of these, which is "
            .. "not enough to switch for.", tostring(best.name))
    end

    return best, string.format("%s could do %d of these.",
        tostring(best.name), #best.items)
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "alts",
    -- No aliases. `who` and `warband` were declared here and both are real
    -- commands registered by Modules/Warband.lua, which loads later and
    -- overwrote them -- so these two entries have never resolved to anything
    -- in this file, while the help listed all three side by side as if they
    -- were different answers.
    aliases = { "alt", "characters" },
    order   = 12,
    help    = "Which character should be doing what, and whether to switch.",
    handler = function()
        local warband = CN:GetModule("Warband")

        if not warband then
            Print("The Warband module is not loaded.")
            return
        end

        local roster = warband.Roster()

        if #roster <= 1 then
            Print("Only this character has been seen. Log in on another and "
                .. "it will be recorded.")
            return
        end

        local best, verdict = Alts.Verdict()

        Print(verdict)

        if best then
            Print("|cffffc74f" .. tostring(best.name) .. "|r"
                .. (best.level and (" (" .. best.level .. ")") or "")
                .. " |cff8a8f96last played "
                .. Alts.DescribeAge({ lastSeen = time() - ((best.ageDays or 0) * 86400) })
                .. "|r")

            for _, item in ipairs(best.items) do
                CN.PrintLine("  |cffffc74f" .. tostring(item.objective.name)
                    .. "|r |cff8a8f96" .. tostring(item.reason) .. "|r")
            end
        end

        Print(" ")
        Print("Your Warband:")

        for _, row in ipairs(roster) do
            local character = CN.db and CN.db.characters
                and CN.db.characters[row.key]

            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            -- Three widths in one line, in a proportional font, produced
            -- three ragged edges rather than three columns.
            CN.PrintLine("  "
                .. (row.isCurrent and "|cff73b873" or "|cfff2f4f6")
                .. tostring(row.name) .. "|r"
                .. CN.Aside(tostring(row.level or "?") .. " "
                    .. CN.TokenLabel(row.class or ""))
                .. " |cff8a8f96" .. Alts.DescribeAge(character) .. "|r")
        end

        Print("|cff8a8f96Everything here is what each character recorded the "
            .. "last time it logged in.|r")
    end,
}

return Alts
'@

$Embedded['Modules\Vault.lua'] = @'
-- Modules/Vault.lua
-- Completion Navigator :: the Great Vault.
--
-- The weekly reward chest. Three rows -- raid, dungeons, world -- each with
-- three thresholds, and you choose ONE item from everything unlocked.
--
-- This module matters more than its size suggests, because the Great Vault is
-- the only system in the game that hands the addon all three things it
-- normally has to guess at:
--
--   * a hard deadline      -- the weekly reset, which the client reports
--   * a known denominator  -- the thresholds are fixed
--   * a known reward       -- the client reports the item level
--
-- Everywhere else this addon reports counts rather than percentages, because
-- a percentage needs a denominator the client will not supply. Here it will.
-- "3 of 4 dungeons" is a fact, and "one more Heroic before Tuesday unlocks a
-- second reward" is a genuine next action rather than an estimate.
--
-- The nearly-there row is the whole point. A row sitting one activity short of
-- a threshold is the highest-value, most time-boxed objective the addon can
-- offer; a row already at its cap is worth nothing this week.

local ADDON_NAME, CN = ...

local Vault = CN:RegisterModule("Vault")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- ROWS
------------------------------------------------------------

Vault.rowLabels = {
    RAID    = "Raid",
    DUNGEON = "Dungeons",
    WORLD   = "World",
    PVP     = "PvP",
    UNKNOWN = "Other",
}

-- What the player would actually go and do to advance each row. Naming the
-- action is the difference between a progress bar and a recommendation.
Vault.rowActions = {
    RAID    = "defeat another raid boss",
    DUNGEON = "run another Heroic or higher dungeon",
    WORLD   = "complete another Delve, weekly quest or zone event",
    PVP     = "complete another rated PvP match",
    UNKNOWN = "complete another qualifying activity",
}

local ROW_ORDER = { "RAID", "DUNGEON", "WORLD", "PVP", "UNKNOWN" }

------------------------------------------------------------
-- READING THE VAULT
------------------------------------------------------------

-- Collapses the flat activity list into one entry per row:
--
--   { row, label, progress, unlocked, tiers, next, remaining, capped }
--
-- `next` is the next unmet threshold; `remaining` is how many activities
-- away it is. Both nil when the row is capped.
function Vault.Rows()
    local activities = Blizzard.GetWeeklyRewardActivities()

    if #activities == 0 then
        return {}
    end

    local byRow = {}

    for _, activity in ipairs(activities) do
        local row = byRow[activity.row]

        if not row then
            row = {
                row      = activity.row,
                label    = Vault.rowLabels[activity.row] or activity.row,
                progress = 0,
                unlocked = 0,
                tiers    = {},
            }

            byRow[activity.row] = row
        end

        -- Every tier of a row reports the same progress figure; taking the
        -- maximum is defensive rather than necessary.
        row.progress = math.max(row.progress, activity.progress or 0)

        table.insert(row.tiers, {
            threshold = activity.threshold,
            progress  = activity.progress,
            level     = activity.level,
            unlocked  = activity.unlocked,
        })

        if activity.unlocked then
            row.unlocked = row.unlocked + 1
        end
    end

    local rows = {}

    for _, name in ipairs(ROW_ORDER) do
        local row = byRow[name]

        if row then
            table.sort(row.tiers, function(a, b)
                return (a.threshold or 0) < (b.threshold or 0)
            end)

            for _, tier in ipairs(row.tiers) do
                if not tier.unlocked and not row.next then
                    row.next      = tier.threshold
                    row.remaining = math.max(0, (tier.threshold or 0) - row.progress)
                end
            end

            row.capped = row.next == nil

            table.insert(rows, row)
        end
    end

    return rows
end

function Vault.IsAvailable()
    return Blizzard.HasWeeklyRewards()
end

-- Total reward choices unlocked across every row.
function Vault.Summary()
    local rows = Vault.Rows()

    local summary = {
        rows     = #rows,
        unlocked = 0,
        closest  = nil,
        resetsIn = Blizzard.GetSecondsUntilWeeklyReset(),
        claimable = Blizzard.HasAvailableWeeklyRewards(),
    }

    for _, row in ipairs(rows) do
        summary.unlocked = summary.unlocked + row.unlocked

        if not row.capped and row.remaining then
            if not summary.closest or row.remaining < summary.closest.remaining then
                summary.closest = row
            end
        end
    end

    return summary
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

local function FormatReset(seconds)
    if not seconds then
        return nil
    end

    local days  = math.floor(seconds / 86400)
    local hours = math.floor((seconds % 86400) / 3600)

    if days > 0 then
        return days .. "d " .. hours .. "h"
    end

    if hours > 0 then
        return hours .. "h"
    end

    return math.max(1, math.floor(seconds / 60)) .. "m"
end

Vault.FormatReset = FormatReset

function Vault.DescribeRow(row)
    local text = row.label .. ": " .. row.progress

    if row.capped then
        -- "Dungeons: 8 all 3 unlocked" -- two numbers jammed together with no
        -- word between them, and the reader has to guess which is which.
        -- 0.61.0.
        -- A SPACE ON BOTH SIDES. 0.88.0. Every other dash in the addon has
        -- one, and this printed "World: 8 —all 3 rewards unlocked".
        return text .. " |cff73b873" .. CN.DASH .. " all "
            .. CN.Count(row.unlocked, "reward") .. " unlocked|r"
    end

    return text .. " of " .. row.next
        .. " |cff8a8f96(" .. row.unlocked .. " unlocked, "
        .. row.remaining .. " more for the next)|r"
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Urgency rises as the reset approaches AND as the row nears its threshold.
-- One activity away with a day left is the single most actionable thing the
-- addon can surface; three away with six days left is barely worth a mention.
local function Urgency(remaining, resetsIn)
    local value = 0

    if remaining then
        if remaining <= 1 then
            value = value + 3
        elseif remaining <= 2 then
            value = value + 2
        else
            value = value + 1
        end
    end

    if resetsIn then
        local days = resetsIn / 86400

        if days <= 1 then
            value = value + 3
        elseif days <= 2 then
            value = value + 2
        elseif days <= 4 then
            value = value + 1
        end
    end

    return value
end

Vault.Urgency = Urgency

-- How many activities away a row can be and still be worth recommending.
-- Beyond this it is a plan for the week, not a next action.
Vault.maxRemaining = 4

CN.RegisterCandidateProvider("Vault", function()
    local candidates = {}

    if not Vault.IsAvailable() then
        return candidates
    end

    local resetsIn = Blizzard.GetSecondsUntilWeeklyReset()

    -- An unclaimed vault from last week outranks everything: it is free, it
    -- takes thirty seconds, and it expires.
    -- AND HIDING OR DEFERRING IT WORKS. 0.78.0.
    --
    -- Every other provider in the tree guards on both, and the loop directly
    -- below this one does -- while the claim row did not. So right-clicking
    -- "Collect your Great Vault reward" on the heads-up line printed
    -- "Deferred for an hour" and it was back on the next refresh: the addon
    -- telling the player it had done something it had not.
    --
    -- The id is a string now. It was `0`, which `CN.ToID` rejects, so
    -- `/cn unhide` could never name it back either; `Modules/Orders.lua` uses
    -- "claim" for the same shape and the filter falls back to the raw string.
    if Blizzard.HasAvailableWeeklyRewards()
        and not CN.IsIgnored(CN.objectiveTypes.CURRENCY, "vault")
        and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, "vault") then

        table.insert(candidates, CN.NewObjective({
            id               = "vault",
            type             = CN.objectiveTypes.CURRENCY,
            name             = "Collect your Great Vault reward",
            accountWide      = false,
            completionValue  = 8,
            limitedTimeBonus = 3,
            travelCost       = 2,
            reasons          = {
                "a reward is waiting to be claimed",
                "it is replaced when the vault next fills",
            },
        }))
    end

    for _, row in ipairs(Vault.Rows()) do
        if not row.capped
            and row.remaining
            and row.remaining <= Vault.maxRemaining
            and not CN.IsIgnored(CN.objectiveTypes.CURRENCY, row.row)
            and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, row.row) then

            local reasons = {
                row.remaining .. " more to unlock a "
                    .. (row.unlocked > 0 and "further" or "first")
                    .. " Great Vault reward",
                Vault.rowActions[row.row] or "complete another activity",
            }

            if resetsIn then
                table.insert(reasons, "resets in " .. FormatReset(resetsIn))
            end

            table.insert(candidates, CN.NewObjective({
                id               = row.row,
                type             = CN.objectiveTypes.CURRENCY,
                name             = "Great Vault: " .. row.label,
                accountWide      = false,
                completionValue  = 4,
                -- ONE DEADLINE, ONE CURVE. 0.88.0.
                --
                -- `Urgency` adds up to three points from `resetsIn` alone,
                -- and `expiresIn` below hands the SAME number to the
                -- scorer's own urgency term -- two independently tuned
                -- curves charging one deadline, with unexplained cliffs at
                -- the four-, two- and one-day boundaries.
                --
                -- Worse for the player: `/cn urgency` announces "how much a
                -- deadline is worth, at every distance from it" and plots
                -- only the scorer's curve, so `/cn why` under-reported the
                -- reset's contribution by an order of magnitude. This is the
                -- defect `Modules/Opportunities.lua` records fixing in
                -- 0.63.0; the sweep reached that file and not this one.
                --
                -- This term now carries only "how close is the row to its
                -- next threshold", which is not a deadline and is charged
                -- nowhere else.
                limitedTimeBonus = Urgency(row.remaining),

                -- DECLARED, BECAUSE THE SWEEP REFUSES THIS SHAPE OTHERWISE.
                -- 0.89.0. A row may not carry both a deadline and a flat
                -- bonus -- five providers were charging one fact twice. This
                -- one is the exception the rule needs: the term above is how
                -- close the row is to its NEXT THRESHOLD, which is not a
                -- deadline and is charged nowhere else.
                limitedTimeBonusIsProgress = true,
                -- Instanced content has no map coordinate, but it is not
                -- "location unknown" either: the group finder is one click.
                travelCost       = 3,
                expiresIn        = resetsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, { events = { "WEEKLY_REWARDS_UPDATE", "CHALLENGE_MODE_COMPLETED",
                  "ENCOUNTER_END", "QUEST_TURNED_IN" },
                  volatile = true, cooldown = 30 })

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "vault",
    aliases = { "greatvault" },
    order   = 16,
    help    = "Great Vault progress and what unlocks the next reward.",
    handler = function()
        if not Vault.IsAvailable() then
            Print("The Great Vault is not available on this client.")
            return
        end

        local rows = Vault.Rows()

        if #rows == 0 then
            Print("No Great Vault progress recorded yet.")
            Print("|cff8a8f96The client reports vault progress once you have "
                .. "completed at least one qualifying activity this week.|r")
            return
        end

        local summary = Vault.Summary()

        Print("Great Vault: " .. summary.unlocked .. " reward"
            .. CN.Pluralize(summary.unlocked, "") .. " unlocked"
            .. (summary.resetsIn
                and (" |cff8a8f96resets in " .. FormatReset(summary.resetsIn) .. "|r")
                or ""))

        if summary.claimable then
            Print("|cff73b873A reward is waiting to be collected.|r")
        end

        for _, row in ipairs(rows) do
            CN.PrintLine("  " .. Vault.DescribeRow(row))
        end

        if summary.closest then
            Print("|cffffc74fClosest:|r " .. summary.closest.label
                .. " " .. CN.DASH .. " " .. summary.closest.remaining .. " more, "
                .. (Vault.rowActions[summary.closest.row] or "keep going") .. ".")
        else
            Print("|cff73b873Every row is capped. Nothing more to earn this week.|r")
        end

        Print("|cff8a8f96You choose one item from everything unlocked.|r")
    end,
}

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Navigation.lua'] = @'
-- Modules/Navigation.lua
-- Completion Navigator :: native waypoints and the on-screen arrow.
--
-- Until now the addon decided WHERE to go and handed the job of pointing at it
-- to TomTom. That made TomTom effectively required: without it you got a
-- static map pin and no arrow, which is not navigation.
--
-- This file removes that dependency. It is not an attempt to reimplement
-- TomTom -- it is the minimum that makes the addon complete on its own:
--
--   * a waypoint store of our own
--   * an arrow that points at the current target and colours by whether you
--     are facing it
--   * real distance in yards, not map percentage
--   * arrival detection, which is what makes auto-advance work properly
--
-- TomTom stays supported. Someone who already runs it and likes its arrow can
-- keep using it -- /cn nav tomtom -- and everything else still works.
--
------------------------------------------------------------------------------
-- THE MATH, and an admission about it.
--
--   Map coordinates run x east, y SOUTH. North is therefore -y.
--   bearing clockwise from north = atan2(dx, -dy)
--   relative bearing             = bearing - (facing * facingSign)
--   rotation to apply            = -(relative bearing)
--
-- The one thing that cannot be derived from first principles is which way
-- GetPlayerFacing() counts. 0 is north on every build; whether the value grows
-- as you turn left or as you turn right is a client convention.
--
-- 0.19.0 assumed counter-clockwise and shipped a bearing that pointed people
-- away from their target. The harness "verified" it against seven cases -- and
-- every one of those cases computed its expected answer from the same
-- assumption, so the tests agreed with the bug. A test that encodes the
-- premise it is meant to check proves nothing.
--
-- So the sign is not asserted here. It defaults to the convention every
-- established navigation addon uses, and then CORRECTS ITSELF from evidence:
-- if you are lined up with the arrow, moving, and the distance is growing,
-- the sign is wrong, and the addon flips it and says so. The game is the only
-- thing that can settle this, so the game settles it.
--
-- 0.40.0 added a second, better source of that evidence, because the first
-- one only fires when the player happens to be lined up with a target and
-- walking. When you move at all, the direction you moved IS the direction you
-- were facing, and only one of the two conventions agrees with that. See
-- NoteMotion below. Strafing and walking backwards agree with neither, so
-- they are discarded rather than voted on.
--
-- 0.40.0 also fixed an error that was present in every zone: angles were
-- taken from raw map coordinates, which normalize to 0-1 regardless of the
-- shape of the ground, so every bearing was stretched by the zone's aspect
-- ratio. See MapScale.
------------------------------------------------------------------------------

local ADDON_NAME, CN = ...

local Navigation = CN:RegisterModule("Navigation")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- STATE
------------------------------------------------------------

-- The single active target. One arrow, one destination: a list of waypoints is
-- TomTom's job, and duplicating it would be duplicating the wrong half.
local target = nil

local arrow, ticker

Navigation.arrivalYards = 12

function Navigation.GetTarget()
    return target
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Radians clockwise from straight ahead. nil when the bearing cannot be
-- computed, which is different from zero and must not be shown as zero.
-- +1 means GetPlayerFacing() grows clockwise; -1 means counter-clockwise.
-- Persisted once determined, so the correction happens at most once ever.
function Navigation.FacingSign()
    local settings = CN.Settings()

    if settings and settings.facingSign then
        return settings.facingSign
    end

    return 1
end

function Navigation.SetFacingSign(sign)
    local settings = CN.Settings()

    if settings then
        settings.facingSign = (sign < 0) and -1 or 1
    end
end

-- MAP COORDINATES ARE NOT SQUARE, AND ANGLES MEASURED IN THEM ARE WRONG.
--
-- Every map normalizes to 0-1 in both axes regardless of the shape of the
-- ground it covers. A zone 3,000 yards wide and 2,000 yards tall therefore
-- stretches its vertical axis by half again, and an angle computed from raw
-- map deltas is distorted by exactly that ratio: a target genuinely 45
-- degrees off reads as 56 degrees in that zone, and worse in a long one.
--
-- The arrow was doing that in every zone in the game. It is not enough to be
-- noticed as "the arrow is broken" -- it is enough to be noticed as "the
-- arrow is sloppy", and both complaints about the arrow so far have come with
-- "it doesn't point quite right" attached.
--
-- The client will tell us the real width and height in yards, so ask once per
-- map and scale the deltas into yards before taking the angle.
local mapScales = {}

-- Returns yards-per-map-unit on each axis, and a THIRD value saying whether
-- that is a measurement or a shrug.
--
-- THE SENTINEL WAS INDISTINGUISHABLE FROM AN ANSWER.
--
-- `1, 1` means "no distortion", which is the right shrug for the bearing
-- maths -- that only ever uses the RATIO of the two, and a ratio of one is
-- exactly "assume the map is square". But routing asks this for an ABSOLUTE
-- number of yards, and `1` is not a number of yards; it leaves distances in
-- map units, where the whole map is one unit across. `UseMapScale` in
-- Routing.lua validated the answer with `scaleX > 0`, which `1` satisfies, so
-- its 2000-yard fallback could never fire on the one path it was written for:
-- a real map the client would not convert during a loading screen.
--
-- Callers that want a ratio keep ignoring the third value. Callers that want
-- yards must check it.
function Navigation.MapScale(mapID)
    if not mapID then
        return 1, 1, false
    end

    local cached = mapScales[mapID]

    if cached then
        return cached[1], cached[2], true
    end

    -- A tenth of the map, measured across the middle, where a map is least
    -- likely to be doing something strange at its edges.
    local span = 0.1

    local xYards = Navigation.DistanceYards(mapID, 0.45, 0.5, 0.45 + span, 0.5)
    local yYards = Navigation.DistanceYards(mapID, 0.5, 0.45, 0.5, 0.45 + span)

    if not xYards or not yYards or xYards <= 0 or yYards <= 0 then
        -- Do NOT cache a failure. A map the client would not convert during a
        -- loading screen will convert a second later, and caching 1,1 would
        -- keep the distortion for the rest of the session.
        return 1, 1, false
    end

    xYards = xYards / span
    yYards = yYards / span

    mapScales[mapID] = { xYards, yYards }

    return xYards, yYards, true
end

function Navigation.ForgetMapScales()
    mapScales = {}
end

function Navigation.RelativeBearing(playerX, playerY, targetX, targetY, facing, sign, mapID)
    if not (playerX and playerY and targetX and targetY and facing) then
        return nil
    end

    local scaleX, scaleY = Navigation.MapScale(mapID)

    local dx = (targetX - playerX) * scaleX
    local dy = (targetY - playerY) * scaleY

    if dx == 0 and dy == 0 then
        return 0
    end

    -- -dy because map y grows southward.
    local bearing = CN.Atan2(dx, -dy)

    local relative = bearing - (facing * (sign or Navigation.FacingSign()))

    -- Normalize to (-pi, pi] so "how far off am I" is a small number.
    --
    -- THROUGH THE SHIM, WHICH IS WHAT THE SHIM IS FOR.
    --
    -- Core.lua defines `CN.Mod` as the floored modulo -- "if a construct
    -- means two things, the addon uses neither directly; it uses one of
    -- these" -- and then the one place in the addon that wraps an angle did
    -- it with two unbounded `while` loops instead. So the rule was enforced
    -- nowhere and the shim had no call sites at all, which is how a
    -- compatibility guard quietly stops being one.
    --
    -- The loops were also unbounded: a non-finite bearing spins the client.
    -- This is O(1) and it cannot.
    local full = 2 * math.pi

    relative = CN.Mod(relative + math.pi, full) - math.pi

    -- CN.Mod's range is [0, full), so the line above lands in [-pi, pi).
    -- The addon's convention is (-pi, pi] -- exactly antipodal must read as
    -- "behind you", not "behind you, negative".
    if relative == -math.pi then
        relative = math.pi
    end

    return relative
end

-- Distance in yards, using the client's world positions. Map coordinates are
-- normalized per map, so a 0.1 difference is a different real distance in
-- every zone; converting is the only way to get a number worth printing.
--
-- Returns nil when the client cannot convert, rather than a made-up figure.
function Navigation.DistanceYards(mapID, playerX, playerY, targetX, targetY)
    if not (mapID and playerX and playerY and targetX and targetY) then
        return nil
    end

    if not C_Map or not C_Map.GetWorldPosFromMapPos then
        return nil
    end

    -- GetWorldPosFromMapPos takes a Vector2D, NOT a UiMapPoint.
    --
    -- These are two different types and 0.19.0 passed the wrong one, so the
    -- call returned nothing and the arrow reported "distance unknown" for
    -- every target. UiMapPoint carries a nested `position`; Vector2D carries
    -- x and y directly. SetUserWaypoint wants the former, this wants the
    -- latter, and they are easy to confuse because both describe a point.
    if not CreateVector2D then
        return nil
    end

    local function worldPosition(x, y)
        local ok, continentID, position =
            pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

        if not ok or not position then
            return nil, nil
        end

        -- Vector2D exposes GetXY(); some builds also expose x and y directly.
        local wx, wy

        if position.GetXY then
            local gotXY, gx, gy = pcall(position.GetXY, position)

            if gotXY then
                wx, wy = gx, gy
            end
        end

        wx = wx or position.x
        wy = wy or position.y

        if not wx or not wy then
            return nil, nil
        end

        return continentID, { x = wx, y = wy }
    end

    local fromContinent, fromPos = worldPosition(playerX, playerY)

    if not fromPos then
        return nil
    end

    local toContinent, toPos = worldPosition(targetX, targetY)

    if not toPos then
        return nil
    end

    -- Different continents means the straight-line number would be nonsense.
    if fromContinent and toContinent and fromContinent ~= toContinent then
        return nil
    end

    local dx = toPos.x - fromPos.x
    local dy = toPos.y - fromPos.y

    return math.sqrt((dx * dx) + (dy * dy))
end

function Navigation.FormatDistance(yards)
    if not yards then
        return CN.L["distance unknown"]
    end

    if yards >= 1000 then
        return string.format("%.1f km", yards * 0.0009144)
    end

    return string.format("%d yd", math.floor(yards + 0.5))
end

------------------------------------------------------------
-- THE ARROW
------------------------------------------------------------

local function Settings()
    return CN.Settings() or {}
end

function Navigation.IsArrowEnabled()
    local settings = Settings()

    return settings.arrow ~= false
end

local function BuildArrow()
    if arrow or not CreateFrame then
        return arrow
    end

    arrow = CreateFrame("Frame", "CompletionNavigatorArrow", UIParent)

    arrow:SetSize(56, 56)
    arrow:SetFrameStrata("MEDIUM")
    arrow:SetMovable(true)
    arrow:EnableMouse(true)
    arrow:RegisterForDrag("LeftButton")
    arrow:SetClampedToScreen(true)

    -- NOT `settings.arrowPosition = settings.arrowPosition or {}`. 0.78.0.
    --
    -- That wrote a permanent empty table into saved data for a player who
    -- never moved the arrow -- read by nothing, since the restore falls
    -- through to the fallback when there is no `point` -- and it would defeat
    -- any later reset keyed on the entry being present. The two sibling
    -- frames never did it.
    CN.RestoreFramePosition(arrow, Settings().arrowPosition,
        { point = "CENTER", relativePoint = "CENTER", x = 0, y = 160 })

    arrow.texture = arrow:CreateTexture(nil, "ARTWORK")
    arrow.texture:SetAllPoints()
    arrow.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    -- SetTexture fails silently on a missing file, so verify rather than
    -- shipping an invisible arrow.
    if not arrow.texture:GetTexture() then
        arrow.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    arrow.label = CN.Label(arrow, "OVERLAY", "CAPTION")
    arrow.label:SetPoint("TOP", arrow, "BOTTOM", 0, -2)
    arrow.label:SetJustifyH("CENTER")

    arrow.distance = CN.Label(arrow, "OVERLAY", "LEAD")
    arrow.distance:SetPoint("TOP", arrow.label, "BOTTOM", 0, -2)
    arrow.distance:SetJustifyH("CENTER")

    -- OUTLINED, BECAUSE THIS IS DRAWN OVER THE GAME WORLD.
    --
    -- Both of these were bare font objects with the standard one-pixel drop
    -- shadow, which is enough over a dark UI panel and is not enough over
    -- Northrend snow, Uldum sand, Bastion's marble or a spell effect. The
    -- distance is the number a player reads WHILE RUNNING, which is exactly
    -- when the background is moving and unpredictable.
    CN.Outline(arrow.label, 12, "BODY")
    CN.Outline(arrow.distance, 17, "PRIMARY")

    arrow:SetScript("OnDragStart", function(self)
        self:StartMoving()
    end)

    arrow:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        local saved = Settings()

        saved.arrowPosition = CN.SaveFramePosition(self)
            or saved.arrowPosition
    end)

    -- AND A WAY OUT OF IT. 0.77.0.
    --
    -- The arrow eats world clicks in its 56x56 footprint -- it is
    -- mouse-enabled so it can be dragged -- with nothing on screen explaining
    -- why the ground under it does not respond. The tooltip answers that
    -- question; the x answers it better.
    CN.AttachCloseControl(arrow,
        function()
            -- THE SAME SETTING `/cn arrow off` WRITES, so the command and
            -- the control agree afterwards. Hiding it alone would bring it
            -- back on the next refresh, and a control that undoes itself is
            -- worse than no control.
            Settings().arrow = false

            arrow:Hide()

            CN.Print("Arrow off. " .. CN.Aside(CN.Accent("/cn arrow on")
                .. " brings it back"))
        end,
        "Points at what you are navigating to. Drag to move it. The x hides "
        .. "it.",
        "Hide the arrow. /cn arrow on brings it back.")

    arrow:Hide()

    return arrow
end

Navigation.BuildArrow = BuildArrow

-- The arrow's palette.
--
-- ON_COURSE is the blue of the waypoint marker in the addon's own logo,
-- sampled from it rather than guessed: #5DD2FB. Because you are pointed at
-- your target most of the time, this is the colour the arrow actually wears,
-- which is what makes it read as part of the addon rather than as generic
-- navigation furniture.
--
-- The texture is greyscale for exactly this reason: tinting is a multiply, so
-- a pre-coloured blue arrow could never turn amber, and the bearing feedback
-- would be lost to make one screenshot prettier.
-- Derived from the addon's palette rather than restating its numbers. The
-- three that mean something -- on course, turn a bit, wrong way -- are the
-- brand blue, the accent gold and the bad red, which is what they always
-- were; writing them out again is how the two drifted apart in the first
-- place.
-- CN_PALETTE_EXEMPT: UNKNOWN below is deliberately not a palette role -- it
-- is the ABSENCE of a bearing and must not read as any of the three states.
Navigation.colors = {
    ON_COURSE = CN.RGB.BRAND,
    DRIFTING  = CN.RGB.ACCENT,
    AWAY      = CN.RGB.BAD,

    -- Not a palette role: this is the absence of a bearing, and it must not
    -- read as any of the three states.
    UNKNOWN   = { 0.600, 0.640, 0.680 },
}

-- THE PALETTE ITSELF, NOT ONLY A LABEL BESIDE IT.
--
-- Colourblind mode has until now added a word next to the arrow, which
-- satisfies "no information carried by colour alone" and leaves the colours
-- themselves as bad as they were. Gold against red is the single worst pair
-- for the commonest form of colour blindness -- and it is the pair carrying
-- "drifting" against "walking away", which is the distinction the arrow
-- exists to make.
--
-- Blue and orange instead, which separate under every common form, with
-- white for on-course so the three differ in lightness as well as in hue.
-- Somebody who cannot tell the hues apart can still tell these apart.
-- Chosen so that the three differ by at least 0.27 in relative luminance --
-- checked by the suite, not by eye. Lightness is what survives when hue does
-- not.
-- CN_PALETTE_EXEMPT: this is an alternate palette by design, separated by
-- luminance rather than by hue, and the suite checks that separation. Making
-- it use the addon's own roles would delete the feature.
Navigation.colorblindColors = {
    ON_COURSE = { 0.980, 0.980, 0.980 },   -- near-white, luminance 0.98
    DRIFTING  = { 0.400, 0.760, 1.000 },   -- light blue,  luminance 0.70
    AWAY      = { 0.780, 0.340, 0.020 },   -- dark orange, luminance 0.41
    UNKNOWN   = { 0.520, 0.540, 0.560 },
}

function Navigation.Palette()
    local hud = CN:GetModule("Hud")

    if hud and hud.IsColourblind and hud.IsColourblind() then
        return Navigation.colorblindColors
    end

    return Navigation.colors
end

-- Blue when you are walking toward it, gold when you are drifting, red when
-- you are walking away. The single most useful thing an arrow does, and it
-- costs one comparison.
function Navigation.BearingColor(relative)
    local palette = Navigation.Palette()

    if not relative then
        return palette.UNKNOWN[1], palette.UNKNOWN[2], palette.UNKNOWN[3]
    end

    local off = math.abs(relative)

    if off < 0.35 then
        return palette.ON_COURSE[1], palette.ON_COURSE[2], palette.ON_COURSE[3]
    end

    if off < 1.2 then
        return palette.DRIFTING[1], palette.DRIFTING[2], palette.DRIFTING[3]
    end

    return palette.AWAY[1], palette.AWAY[2], palette.AWAY[3]
end

-- Recomputes the arrow. Split out so the harness can drive it without a frame.
-- The player's position expressed on a specific map, or nil.
--
-- Works for any map that can describe where the player is standing -- a zone
-- while you are inside one of its buildings, for instance -- and returns nil
-- when it genuinely cannot, which is the honest answer for another continent.
function Navigation.PlayerPositionOnMap(mapID)
    if not mapID or not C_Map or not C_Map.GetPlayerMapPosition then
        return nil
    end

    local ok, position = pcall(C_Map.GetPlayerMapPosition, mapID, "player")

    if not ok or not position then
        return nil
    end

    local x, y

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            x, y = gx, gy
        end
    end

    x = x or position.x
    y = y or position.y

    if not x or not y then
        return nil
    end

    -- The client answers (0, 0) for a map that cannot place you, which is a
    -- real coordinate on every map and therefore indistinguishable from a
    -- corner. Treated as "cannot say", because a corner is a far less likely
    -- place to be standing than nowhere.
    if x == 0 and y == 0 then
        return nil
    end

    -- TWO VALUES, NOT A TABLE. 0.63.0.
    --
    -- `Compute` calls this on every 10 Hz tick whenever the player's best map
    -- differs from the target's -- which is the ORDINARY case in a city, an
    -- inn, a cave or any micro-dungeon overlay, so much of the time the arrow
    -- is up. 0.61.0 removed the per-tick state table two functions below this
    -- one and left the allocation on the same code path.
    --
    -- Returned as a pair. The two callers both immediately read `.x` and
    -- `.y`, so nothing wanted the table for its own sake.
    return x, y
end

-- ONE STATE TABLE, REUSED. 0.61.0.
--
-- `Compute` runs ten times a second for as long as the arrow is on screen and
-- built a fresh eleven-field table every time: 2.31 KB per second, about
-- 1.4 MB a minute, all of it dead the instant the next tick replaces it.
-- That is a garbage-collection drip running continuously while the player
-- walks, in the one part of the addon they are looking at while walking.
--
-- The three callers all read the table and discard it before the next tick --
-- the ticker, `/cd navdiag`, and the follow-mode check -- so one table can
-- serve all of them. Nothing holds a reference across a tick; if something
-- ever needs to, it must copy, and this comment is where it will find out.
--
-- Every field is written on every return path, including the two early ones,
-- so a reused table can never carry a value from the tick before. That is the
-- whole risk of this change and it is discharged by `Clear` rather than by
-- remembering.
local computed = {}

local function Clear()
    computed.state      = nil
    computed.relative   = nil
    computed.yards      = nil
    computed.facing     = nil
    computed.within     = nil
    computed.mapID      = nil
    computed.playerX    = nil
    computed.playerY    = nil
    computed.zone       = nil
    computed.translated = nil

    return computed
end

function Navigation.Compute()
    if not target then
        return nil
    end

    local mapID, playerX, playerY = CN.GetPlayerPosition()

    if not mapID or not playerX or not playerY then
        local state = Clear()

        state.state = "NO_POSITION"

        return state
    end

    -- THE MAP UNDER YOUR FEET IS NOT THE MAP THE TARGET IS ON.
    --
    -- `GetBestMapForUnit` answers with the most SPECIFIC map containing you:
    -- step into a building, a cave, an inn or a city district and it changes,
    -- even though you have moved thirty yards. The arrow compared that to the
    -- target's map, found them different, and gave up -- announcing "another
    -- zone" while standing next to the destination.
    --
    -- This is the same defect that made available quests invisible in a city
    -- in 0.27.0, in a different file. The fix is the same shape: ask the
    -- client for the player's position expressed on the map that matters,
    -- rather than assuming the two maps are the same one.
    local onTargetMap = false

    if mapID ~= target.mapID then
        local translatedX, translatedY =
            Navigation.PlayerPositionOnMap(target.mapID)

        if translatedX then
            mapID   = target.mapID
            playerX = translatedX
            playerY = translatedY

            onTargetMap = true
        else
            -- Genuinely somewhere the target's map cannot describe --
            -- another continent, or an instance.
            local state = Clear()

            state.state = "WRONG_MAP"
            state.zone  = target.zone or Blizzard.GetMapName(target.mapID)

            return state
        end
    end

    local facing = GetPlayerFacing and GetPlayerFacing() or nil

    local relative = Navigation.RelativeBearing(playerX, playerY,
        target.x, target.y, facing, nil, mapID)

    local yards = Navigation.DistanceYards(mapID, playerX, playerY,
        target.x, target.y)

    local within = yards and yards <= Navigation.arrivalYards

    -- ARRIVAL DOES NOT LATCH.
    --
    -- REPORTED FROM LIVE PLAY, TWICE: "I walked past it and the arrow did not
    -- turn around." `target.arrived` was set once and never cleared, so a
    -- player who walked through the destination and kept going was, as far as
    -- this code was concerned, still arrived -- forever.
    --
    -- Walking back out of the arrival radius is the player un-arriving. Say
    -- so, so that tracking resumes and the arrow turns round.
    if target.arrived and yards and yards > (Navigation.arrivalYards * 2) then
        target.arrived = false

        DebugPrint("Left the destination; tracking it again.")
    end

    local state = Clear()

    state.state      = within and "ARRIVED" or "TRACKING"
    state.relative   = relative
    state.yards      = yards
    state.facing     = facing
    state.within     = within
    state.mapID      = mapID
    state.playerX    = playerX
    state.playerY    = playerY
    state.translated = onTargetMap

    return state
end

------------------------------------------------------------
-- SELF-CORRECTION
------------------------------------------------------------

-- Evidence that the facing convention is backwards.
--
-- If you are lined up with the arrow and moving, the distance must shrink. If
-- it grows instead, the arrow is pointing at the reciprocal. That is not a
-- guess -- it is the definition of the arrow being wrong, observed directly.
--
-- Several consecutive samples are required so that walking backwards, a
-- flight path, or a teleport cannot trigger it.
local calibration = {
    lastDistance = nil,
    growing      = 0,
    corrected    = false,
}

Navigation.calibrationSamples = 4

function Navigation.ResetCalibration()
    calibration.lastDistance = nil
    calibration.growing      = 0
end

-- WHICH WAY DOES GetPlayerFacing COUNT?
--
-- Everything the arrow does rests on one unverified assumption: that the
-- number the client gives for "facing" grows in the same rotational direction
-- as the bearing computed from map coordinates. If it does not, the arrow is
-- not backwards -- it is MIRRORED, wrong by twice your facing, which looks
-- right when you face north and badly wrong when you face east. That is a
-- much better description of what was reported twice than "backwards" was.
--
-- The old evidence for it was indirect: follow the arrow, and if the distance
-- grows, the arrow is wrong. That only fires when the player happens to be
-- lined up and walking, and cannot fire at all when nothing is targeted.
--
-- This is direct evidence instead, and it needs no target and no cooperation:
-- when you MOVE, the direction you moved is the direction you were facing.
-- Compute the bearing of your own movement, compare it against your facing
-- under both conventions, and only one of them can agree. Strafing and
-- walking backwards agree with neither, so they are discarded rather than
-- voted on -- which is what makes this safe to run continuously.
local motion = {
    mapID   = nil,
    x       = nil,
    y       = nil,
    agree   = 0,
    against = 0,
    samples = 0,
    verdict = nil,
}

-- Consecutive agreeing samples before the sign is changed. At ten samples a
-- second this is a fraction of a second of walking, but every one of them has
-- to agree, and one strafe resets the count.
Navigation.motionSamples   = 6

-- Below this the player is standing still; above it, a loading screen, a
-- flight path or a teleport.
Navigation.motionMinYards  = 1.5
Navigation.motionMaxYards  = 60

-- How close a hypothesis has to be to count as agreeing, and how far the
-- other one has to be to count as excluded.
Navigation.motionAgree     = math.rad(25)
Navigation.motionExclude   = math.rad(60)

-- ARITHMETIC, NOT A LOOP.
--
-- `Navigation.RelativeBearing` was rewritten to use `CN.Mod` for exactly this
-- reason, and its comment says so: "the loops were also unbounded: a
-- non-finite bearing spins the client". This copy -- used by `Smooth()` on
-- the arrow's ten-per-second ticker and by `SignFromMotion` -- was left
-- behind. Every current input is bounded by `CN.Atan2` and
-- `GetPlayerFacing`, so it is not reachable today; a hang the file's own rule
-- forbids is not something to leave sitting on the hottest path in the addon
-- waiting for a fifth caller.
--
-- `CN.Mod` is the floored modulo, so its range is [0, full) and the shift
-- lands in [-pi, pi). The loops produced (-pi, pi], so exactly one input
-- changes: a bearing of precisely pi now comes back as -pi. Both mean
-- "directly behind you", every consumer takes `math.abs` of the difference,
-- and the one that does not -- the easing in `Smooth` -- snaps rather than
-- eases at a reversal of that size.
--
-- `Navigation.RelativeBearing` maps -pi back to +pi and so returns (-pi, pi],
-- which is the opposite convention at that one point. Both are correct for
-- their consumers and neither boundary is depended on; recording the
-- difference here rather than claiming they agree, which an earlier draft of
-- this comment did.
local function Normalize(angle)
    if type(angle) ~= "number" then
        return 0
    end

    -- A NaN survives every comparison and every arithmetic operation, so it
    -- has to be caught by the one test it fails: equality with itself.
    --
    -- AND AN INFINITY, which is the case the first version still got wrong:
    -- `CN.Mod(inf + pi, 2pi)` is `inf - inf`, which is NaN -- so the guard
    -- that exists because "a non-finite bearing spins the client" passed one
    -- straight through to `SetRotation`.
    if angle ~= angle or angle == math.huge or angle == -math.huge then
        return 0
    end

    local full = 2 * math.pi

    return CN.Mod(angle + math.pi, full) - math.pi
end

Navigation.NormalizeAngle = Normalize

function Navigation.ResetMotion()
    motion.mapID   = nil
    motion.x       = nil
    motion.y       = nil
    motion.agree   = 0
    motion.against = 0
end

function Navigation.MotionState()
    return {
        samples = motion.samples,
        agree   = motion.agree,
        against = motion.against,
        verdict = motion.verdict,
        sign    = Navigation.FacingSign(),
    }
end

-- Returns the sign the evidence supports, or nil when this sample said
-- nothing. Separated from the sampling so it can be tested as arithmetic.
function Navigation.SignFromMotion(moved, facing)
    if not moved or not facing then
        return nil
    end

    local withPlus  = math.abs(Normalize(moved - facing))
    local withMinus = math.abs(Normalize(moved + facing))

    if withPlus <= Navigation.motionAgree and withMinus >= Navigation.motionExclude then
        return 1
    end

    if withMinus <= Navigation.motionAgree and withPlus >= Navigation.motionExclude then
        return -1
    end

    -- Facing north or south makes both conventions agree, so the sample
    -- cannot distinguish them and must not be counted as evidence for the one
    -- we happen to be using.
    return nil
end

function Navigation.NoteMotion()
    if not GetPlayerFacing then
        return nil
    end

    if UnitOnTaxi and UnitOnTaxi("player") then
        Navigation.ResetMotion()
        return nil
    end

    local mapID, x, y = CN.GetPlayerPosition()

    if not mapID or not x or not y then
        Navigation.ResetMotion()
        return nil
    end

    local previousMap, previousX, previousY = motion.mapID, motion.x, motion.y

    motion.mapID, motion.x, motion.y = mapID, x, y

    if previousMap ~= mapID or not previousX then
        return nil
    end

    local scaleX, scaleY = Navigation.MapScale(mapID)

    local dx = (x - previousX) * scaleX
    local dy = (y - previousY) * scaleY

    local yards = math.sqrt((dx * dx) + (dy * dy))

    if yards < Navigation.motionMinYards then
        -- Standing still is not evidence against anything; leave the tally.
        return nil
    end

    if yards > Navigation.motionMaxYards then
        Navigation.ResetMotion()
        return nil
    end

    local facing = GetPlayerFacing()

    if not facing then
        return nil
    end

    local moved = CN.Atan2(dx, -dy)

    local supported = Navigation.SignFromMotion(moved, facing)

    if not supported then
        return nil
    end

    motion.samples = motion.samples + 1

    if supported == Navigation.FacingSign() then
        motion.agree   = motion.agree + 1
        motion.against = 0

        -- "corrected" is sticky. Once the sign has been changed this session,
        -- every subsequent sample agrees with it by construction, and
        -- overwriting the verdict with "confirmed" would erase the only
        -- record that anything was ever wrong -- which is the single most
        -- useful line in a bug report about the arrow.
        if motion.verdict ~= "corrected" then
            motion.verdict = "confirmed"
        end

        return nil
    end

    motion.against = motion.against + 1
    motion.agree   = 0

    if motion.against < Navigation.motionSamples then
        return nil
    end

    motion.against = 0
    motion.verdict = "corrected"

    Navigation.SetFacingSign(supported)
    Navigation.ResetCalibration()

    Print("The arrow was reading your facing backwards. Corrected, and "
        .. "remembered.")
    DebugPrint("Facing sign is now " .. Navigation.FacingSign()
        .. ", from " .. motion.samples .. " movement samples.")

    return supported
end

function Navigation.NoteObservation(relative, yards)
    -- Only meaningful while genuinely lined up: if you are not following the
    -- arrow, the distance says nothing about whether the arrow is right.
    if not relative or not yards or math.abs(relative) > 0.3 then
        Navigation.ResetCalibration()
        return false
    end

    local previous = calibration.lastDistance

    calibration.lastDistance = yards

    if not previous then
        return false
    end

    local delta = yards - previous

    -- Ignore standing still and ignore jumps far too large to be walking,
    -- which are loading screens rather than movement.
    if math.abs(delta) < 0.5 or math.abs(delta) > 200 then
        return false
    end

    if delta > 0 then
        calibration.growing = calibration.growing + 1
    else
        calibration.growing = 0
    end

    if calibration.growing < Navigation.calibrationSamples then
        return false
    end

    calibration.growing = 0

    if calibration.corrected then
        -- Already flipped once this session and still wrong: flipping back and
        -- forth forever would be worse than leaving it alone.
        return false
    end

    calibration.corrected = true

    Navigation.SetFacingSign(-Navigation.FacingSign())

    Print("The arrow was pointing the wrong way. Corrected, and remembered.")
    DebugPrint("Facing sign is now " .. Navigation.FacingSign() .. ".")

    return true
end

-- Wipe what the arrow is showing.
--
-- Hiding a frame does not clear it. The rotation, the colour and the distance
-- stay exactly as they were, so an arrow hidden while pointing north-east at
-- "10 yd" is still pointing north-east at "10 yd" the moment anything shows
-- it again -- a stale claim about a destination that is no longer being
-- tracked. Costs nothing to reset; costs the player's trust not to.
local function Blank()
    Navigation.ResetSmoothing()
    Navigation.ResetDistanceSmoothing()

    if not arrow then
        return
    end

    if arrow.texture then
        arrow.texture:SetRotation(0)
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
    end

    if arrow.distance then
        arrow.distance:SetText("")
    end

    if arrow.label then
        arrow.label:SetText("")
    end
end

Navigation.Blank = Blank

-- SMOOTHING.
--
-- The arrow recomputes ten times a second and snapped straight to each new
-- bearing, so a player turning on the spot saw it step rather than sweep. The
-- underlying number is right either way -- this is only about whether it
-- reads as an instrument or as a slideshow.
--
-- Snaps rather than sweeps when the change is large: an arrow that eases
-- through 170 degrees is pointing at nothing at all for a quarter of a second,
-- which is worse than a jump. Passing a destination and turning around is
-- exactly that case, and it is the one complaint this addon has actually
-- received about the arrow.
Navigation.smoothingFactor  = 0.35
Navigation.smoothingSnapRad = math.rad(90)

local smoothed = nil

function Navigation.ResetSmoothing()
    smoothed = nil
end

function Navigation.Smooth(bearing)
    if not bearing then
        return bearing
    end

    if not smoothed then
        smoothed = bearing

        return smoothed
    end

    local delta = Normalize(bearing - smoothed)

    if math.abs(delta) >= Navigation.smoothingSnapRad then
        smoothed = bearing

        return smoothed
    end

    smoothed = Normalize(smoothed + (delta * Navigation.smoothingFactor))

    return smoothed
end

-- Distance, eased. Snaps on a large jump for the same reason the rotation
-- does: a teleport, a flight path or a loading screen is a real change and
-- easing through it would show a number that was never true.
Navigation.distanceSmoothing = 0.5
Navigation.distanceSnapYards = 80

local smoothedDistance = nil

function Navigation.ResetDistanceSmoothing()
    smoothedDistance = nil
end

function Navigation.SmoothDistance(yards)
    if not yards then
        smoothedDistance = nil

        return nil
    end

    if not smoothedDistance
        or math.abs(yards - smoothedDistance) >= Navigation.distanceSnapYards then

        smoothedDistance = yards

        return smoothedDistance
    end

    smoothedDistance = smoothedDistance
        + ((yards - smoothedDistance) * Navigation.distanceSmoothing)

    return smoothedDistance
end

local function Refresh()
    if not arrow then
        return
    end

    if not target or not Navigation.IsArrowEnabled() then
        Blank()
        arrow:Hide()

        -- AND THE TICKER STOPS WITH IT. 0.78.0, corrected in 0.79.0 -- see
        -- the restart below, which is the other half this was missing.
        --
        -- `provider.SetWaypoint` starts a ten-per-second ticker and only
        -- `Navigation.Clear` ever stopped it -- so `/cn arrow off`, and the
        -- x this release put ON the arrow, hid the frame and left the ticker
        -- running for the rest of the session: `NoteMotion`, a rotation, a
        -- vertex colour and two `SetText` calls, ten times a second, on a
        -- frame nobody can see.
        --
        -- The x made that trivially easy to hit, which is how it was found.
        if not Navigation.IsArrowEnabled() then
            Navigation.StopTicker()
        end

        return
    end

    local state = Navigation.Compute()

    if not state then
        arrow:Hide()
        return
    end

    arrow:Show()

    -- AND STARTS AGAIN WHEN THERE IS SOMETHING TO DRAW. 0.79.0.
    --
    -- 0.78.0 added the stop and not the start. `StartTicker` had exactly one
    -- caller -- inside `provider.SetWaypoint` -- so `/cn arrow on`, and the
    -- hover x that 0.77.0 added to make toggling easy, left the arrow
    -- reappearing frozen on a stale bearing and a stale distance for the rest
    -- of the session, until the next waypoint happened to be set.
    --
    -- The decision belongs HERE rather than at each toggle: this function
    -- already owns "is there anything to draw", and a rule written at three
    -- call sites is a rule that will be missing from a fourth.
    if not Navigation.IsTicking() then
        Navigation.StartTicker()
    end

    arrow.label:SetText(target.title or CN.L["Destination"])

    if state.state == "WRONG_MAP" then
        arrow.texture:SetRotation(0)
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff8a8f96" .. (state.zone or CN.L["another zone"]) .. "|r")
        return
    end

    if state.state == "NO_POSITION" then
        arrow.texture:SetVertexColor(Navigation.BearingColor(nil))
        arrow.distance:SetText("|cff8a8f96" .. CN.L["no position"] .. "|r")
        return
    end

    if state.relative then
        -- SetRotation turns counter-clockwise; the relative bearing is
        -- clockwise, hence the negation.
        arrow.texture:SetRotation(-Navigation.Smooth(state.relative))
    end

    arrow.texture:SetVertexColor(Navigation.BearingColor(state.relative))

    -- The distance figure jumped the way the rotation used to, because it is
    -- recomputed from a position the client rounds. Same treatment, and a
    -- much lower factor: distance should look steady, not sluggish.
    local distanceText = Navigation.FormatDistance(
        Navigation.SmoothDistance(state.yards))

    -- NO INFORMATION CARRIED BY COLOUR ALONE.
    --
    -- The arrow's whole language is colour -- blue on course, amber drifting,
    -- red walking away -- which is precisely the design that fails a
    -- colourblind player. In that mode the same fact is written next to the
    -- distance, where it survives the colours being indistinguishable.
    local hud = CN:GetModule("Hud")

    if hud and hud.IsColourblind() then
        distanceText = distanceText .. " |cfff2f4f6"
            .. hud.BearingWord(state.relative) .. "|r"
    end

    arrow.distance:SetText(distanceText)

    -- Watch whether following the arrow actually works.
    Navigation.NoteObservation(state.relative, state.yards)

    if state.state == "ARRIVED" then
        Navigation.Arrive()
    end
end

Navigation.Refresh = Refresh

function Navigation.Arrive()
    if not target or target.arrived then
        return
    end

    target.arrived = true

    local reached = tostring(target.title or "destination")

    Print(string.format(CN.L["Arrived: %s"], reached))

    -- The other moment `/cn cues` was written for and never wired to.
    local follow = CN:GetModule("Follow")

    if follow and follow.Cue then
        pcall(follow.Cue, "arrival")
    end

    -- Arrival is exactly the moment auto-advance was designed for; before
    -- this, it could only re-point on a timer or an event.
    if CN.IsAutoWaypointEnabled and CN.IsAutoWaypointEnabled() then
        CN.AutoAdvance("arrival", true)

        -- SAY SO WHEN THE ARROW NOW MEANS SOMETHING ELSE.
        --
        -- Auto-advance re-points at the next thing, and the arrow looks
        -- absolutely identical doing it: same shape, same blue, still ahead
        -- of you. A player who walks through a destination and sees the arrow
        -- still pointing forward reasonably concludes it failed to turn
        -- round, when in fact it is now pointing at something else. That was
        -- reported as a bug twice, and it was a communication failure rather
        -- than a maths one.
        local now = target and tostring(target.title or "destination")

        if now and now ~= reached then
            Print(string.format(CN.L["Now heading to: %s"],
                "|cffffc74f" .. now .. "|r"))
        end
    else
        Navigation.Clear()
    end
end

------------------------------------------------------------
-- TICKER
------------------------------------------------------------

-- Ten times a second. A rotating arrow needs to feel continuous; recomputing
-- world positions every frame does not.
Navigation.tickSeconds = 0.1

function Navigation.StartTicker()
    if ticker or not C_Timer or not C_Timer.NewTicker then
        return
    end

    ticker = C_Timer.NewTicker(Navigation.tickSeconds, function()
        -- Before drawing, and regardless of what is being tracked: the
        -- player's own movement is the only direct evidence of which way the
        -- client counts facing, and it is free to read.
        pcall(Navigation.NoteMotion)

        local ok, err = pcall(Refresh)

        if not ok then
            DebugPrint("Arrow refresh failed: " .. tostring(err))

            local errors = CN:GetModule("Errors")

            if errors then
                errors.Record("arrow refresh", err)
            end
        end
    end)
end

function Navigation.StopTicker()
    if ticker then
        ticker:Cancel()
        ticker = nil
    end
end

-- Published so `/cd navdiag` and the suite can see whether the ten-per-second
-- redraw is running. A ticker over a hidden frame is invisible by definition,
-- which is how it survived from the day the arrow was written.
function Navigation.IsTicking()
    return ticker ~= nil
end

------------------------------------------------------------
-- DIAGNOSIS
------------------------------------------------------------

-- Everything the arrow is thinking, in one command.
--
-- Written because a player reported the arrow misbehaving twice, and both
-- times the only evidence available was a description in prose. I guessed
-- from it twice and was wrong twice. Prose is a bad instrument; this is a
-- better one.
--
-- Reports what is being tracked, where the client says you are, which way it
-- says you are facing, every intermediate value in the bearing, what was
-- actually applied to the texture, and which of the several things that can
-- silently change the destination is switched on.
function Navigation.Diagnose()
    local report = {}

    local function add(label, value)
        table.insert(report, { label = label, value = tostring(value) })
    end

    -- AND WHETHER THE REDRAW IS RUNNING. 0.78.0.
    --
    -- The ticker was started by every waypoint and stopped only by
    -- `Navigation.Clear`, so turning the arrow off left it redrawing a hidden
    -- frame ten times a second for the rest of the session. Invisible by
    -- definition, which is why it survived -- and why the command whose whole
    -- job is "everything the arrow is thinking" should say it.
    add("arrow enabled", CN.YesNo(Navigation.IsArrowEnabled()))
    add("redraw ticker", CN.YesNo(Navigation.IsTicking()))

    if not target then
        add("target", "none" .. CN.DASH .. "nothing is being tracked")

        return report
    end

    add("target", tostring(target.title or "untitled"))
    add("target map", string.format("%s (%s)",
        tostring(target.mapID), tostring(target.zone or "?")))
    add("target coords", string.format("%.1f, %.1f",
        (target.x or 0) * 100, (target.y or 0) * 100))
    add("marked arrived", target.arrived and "yes" or "no")

    local bestMap, px, py = CN.GetPlayerPosition()

    add("your map", tostring(bestMap))
    add("your coords", px and string.format("%.1f, %.1f", px * 100, py * 100)
        or "the client will not say")

    local state = Navigation.Compute() or {}

    add("state", tostring(state.state))

    if state.translated then
        add("translation", "your position was expressed on the target's map")
    end

    add("facing (raw)", state.facing
        and string.format("%.1f deg", math.deg(state.facing)) or "nil")
    local motionState = Navigation.MotionState()

    add("facing sign", tostring(Navigation.FacingSign())
        .. " (flips if the arrow ever pointed backwards)")
    add("facing evidence", motionState.samples == 0
        and "none yet" .. CN.DASH .. "walk a few yards with the arrow up"
        or string.format("%d movement samples, %s",
            motionState.samples, tostring(motionState.verdict)))

    local scaleX, scaleY = Navigation.MapScale(state.mapID or bestMap)

    add("map scale", string.format("%.0f x %.0f yards across", scaleX, scaleY))

    add("relative bearing", state.relative
        and string.format("%.1f deg", math.deg(state.relative))
        or "nil" .. CN.DASH .. "no bearing could be computed")

    if state.relative then
        add("rotation applied", string.format("%.1f deg", math.deg(-state.relative)))

        local off = math.abs(state.relative)

        add("colour", off < 0.35 and "BLUE (on course)"
            or off < 1.2 and "GOLD (drifting)"
            or "RED (walking away)")
    end

    add("distance", Navigation.FormatDistance(state.yards))
    add("arrival radius", Navigation.arrivalYards .. " yd")

    add("provider", tostring(select(2, CN.GetWaypointProvider())))

    -- The two settings that can change what the arrow means without the
    -- player doing anything.
    add("auto-advance", (CN.IsAutoWaypointEnabled and CN.IsAutoWaypointEnabled())
        and "ON" .. CN.DASH .. "arriving re-points the arrow at the next thing"
        or "off")

    local follow = CN:GetModule("Follow")

    add("follow mode", (follow and follow.active) and "ON" or "off")

    return report
end

CN:RegisterCommand{
    name    = "navdiag",
    aliases = { "arrowdiag" },
    order   = 30,
    help    = "Show exactly what the navigation arrow is doing and why.",
    handler = function()
        local report = Navigation.Diagnose()

        Print("Arrow diagnosis:")

        for _, row in ipairs(report) do
            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            CN.PrintLine("  " .. CN.Muted(tostring(row.label)) .. "  "
                .. tostring(row.value))
        end

        -- THE ONE THING THAT MAKES EVERY OTHER LINE HERE UNTRUSTWORTHY.
        --
        -- A migration that threw leaves the saved data in neither the old
        -- shape nor the new one, and everything below reads that data. It
        -- used to be a single line at login and nothing else; this is where
        -- the player was told to look, so this is where it has to appear.
        local failure = (CN.db and CN.db.migrationFailure) or CN.migrationFailure

        -- OUTSIDE THE FAILURE BRANCH, because the failure is cleared the
        -- moment the migration succeeds against the empty table left behind
        -- and the rescued data is not. Reported until somebody deals with it.
        if CN.db and CN.db.rescuedCharacters ~= nil then
            Print(CN.Warn("Some of your saved data was set aside."))
            Print("  " .. CN.Muted("Your character records were the wrong "
                .. "shape, so they were kept rather than replaced. Nothing "
                .. "was destroyed. "
                .. "Run ") .. CN.Accent("/cn rescued")
                .. CN.Muted(" to see what is there."))
        end

        if type(failure) == "table" then
            Print(CN.Bad("Your saved data did not finish upgrading."))
            Print("  " .. CN.Muted("step " .. tostring(failure.version)
                .. ": " .. tostring(failure.error)))
            Print("  " .. CN.Muted("Everything above is read from that data. "
                .. "Copy this line into a bug report."))
        end

        if not target then
            Print("|cff8a8f96Set one with |cffffc74f/cn go|r"
                .. "|cff8a8f96 and run this again.|r")
        end
    end,
}

------------------------------------------------------------
-- WAYPOINT PROVIDER
------------------------------------------------------------

local provider = {}

function provider.IsAvailable()
    -- Native navigation needs nothing but the map API, which is why it is the
    -- default: it is the only provider that cannot be missing.
    return C_Map ~= nil and C_Map.GetBestMapForUnit ~= nil
end

function provider.SetWaypoint(mapID, x, y, title)
    -- THE MAP MAY REFUSE, AND THE ARROW IS NOT THE WHOLE ANSWER.
    --
    -- The native provider draws its own arrow, which works anywhere -- but it
    -- also drops the client's user waypoint, and the client will not place one
    -- on a dungeon, raid, cosmic or continent map. `CanSetUserWaypointOnMap`
    -- says which, and was called nowhere in this addon.
    --
    -- The arrow is still worth having on those maps, so this does not refuse
    -- outright; it simply does not claim a map pin it could not place.
    local allowed = true

    if C_Map and C_Map.CanSetUserWaypointOnMap then
        local asked, answer = pcall(C_Map.CanSetUserWaypointOnMap, mapID)

        if asked and not answer then
            allowed = false
        end
    end

    target = {
        mapID = mapID,
        x     = x,
        y     = y,
        title = title,
        zone  = Blizzard.GetMapName(mapID),
        setAt = time(),
    }

    Navigation.ResetCalibration()
    Navigation.ResetMotion()

    -- SMOOTHING BELONGS TO A DESTINATION, NOT TO THE ARROW.
    --
    -- `Blank` -- the only thing that resets the smoothed bearing and distance
    -- -- ran from `Navigation.Clear` and only when an arrow already existed.
    -- Changing target without clearing first, which is what `/cn go`, the
    -- route's auto-advance and a map-pin click all do, left the previous
    -- destination's smoothed values in place. The snap thresholds hid the
    -- large jumps, so what remained was the confusing case: a new target
    -- within 89 degrees and 79 yards was eased into over several ticks,
    -- showing a bearing and a distance belonging to neither destination.
    Navigation.ResetSmoothing()
    Navigation.ResetDistanceSmoothing()

    BuildArrow()
    Navigation.StartTicker()
    Refresh()

    -- Also drop a map pin, so the destination is visible on the world map and
    -- not only in front of the player.
    if allowed and C_Map.SetUserWaypoint and UiMapPoint
        and UiMapPoint.CreateFromCoordinates then

        local ok = pcall(function()
            C_Map.SetUserWaypoint(UiMapPoint.CreateFromCoordinates(mapID, x, y))
        end)

        if ok then
            -- Remembered so Clear can tell this addon's pin from one the
            -- player placed by hand.
            Navigation.ownsUserWaypoint = true

            if C_SuperTrack and C_SuperTrack.SetSuperTrackedUserWaypoint then
                pcall(C_SuperTrack.SetSuperTrackedUserWaypoint, true)
            end
        end
    end

    if not allowed then
        return true, "the arrow is set; the game does not allow a map pin here"
    end

    return true
end

function provider.ClearAll()
    return Navigation.Clear()
end

function Navigation.Clear()
    local had = target ~= nil or Navigation.ownsUserWaypoint

    target = nil

    if arrow then
        arrow:Hide()
    end

    -- Unconditionally, not only when an arrow was built: the smoothed values
    -- are state about a destination and the destination is gone either way.
    Blank()

    Navigation.StopTicker()

    -- ONLY OUR OWN PIN. `ClearUserWaypoint` removes THE user waypoint, and
    -- there is one. Stopping follow mode used to delete a pin the player had
    -- placed by hand.
    if Navigation.ownsUserWaypoint and C_Map and C_Map.ClearUserWaypoint then
        pcall(C_Map.ClearUserWaypoint)
    end

    Navigation.ownsUserWaypoint = nil

    return had and true or false
end

-- Priority 5: ahead of TomTom's 10. The addon is self-contained now, and a
-- player who prefers TomTom's arrow can say so with /cn nav tomtom.
CN.RegisterWaypointProvider("Native", provider, 5)

Navigation.provider = provider

------------------------------------------------------------
-- PROVIDER PREFERENCE
------------------------------------------------------------

-- Overrides the priority order. Stored rather than inferred, because
-- "whichever addon happens to be loaded" is not a preference.
function Navigation.SetPreference(name)
    local settings = Settings()

    -- Lowercased first: `auto` was the one value that stayed case-sensitive,
    -- so `/cn nav Auto` was refused against a help line that offers `auto`.
    if name == nil or string.lower(name) == "auto" then
        settings.navigation = nil
        return true, "automatic"
    end

    -- THE REGISTRY WAS OPEN AND THIS LIST WAS NOT.
    --
    -- `CN.RegisterWaypointProvider` is a published extension point: another
    -- addon, or a later module of this one, can register a fourth provider
    -- and `CN.GetPreferredWaypointProvider` will honour it. But the only way
    -- to EXPRESS a preference is this command, and it matched against three
    -- names hardcoded here -- so a registered fourth provider could be used
    -- automatically and could never be chosen deliberately. A registry with a
    -- closed selector is three special cases wearing a registry's name.
    --
    -- Matched against what is actually registered now, case-insensitively,
    -- and the registered name is what gets stored so the lookup on the other
    -- side is exact.
    local key = string.lower(name)

    local resolved

    for registered in pairs(CN.waypointProviders or {}) do
        if string.lower(registered) == key then
            resolved = registered
            break
        end
    end

    if not resolved then
        return false, nil
    end

    settings.navigation = resolved

    return true, resolved
end

-- The names `/cn nav <name>` will accept, for the command's own help and its
-- error message. Sorted, so the list does not reorder itself between logins.
function Navigation.PreferenceNames()
    local names = {}

    for registered in pairs(CN.waypointProviders or {}) do
        table.insert(names, registered)
    end

    table.sort(names)

    return names
end

function Navigation.Preference()
    return Settings().navigation
end

-- Consulted by Routing before the priority order.
function CN.GetPreferredWaypointProvider()
    local preferred = Navigation.Preference()

    if not preferred then
        return nil
    end

    local candidate = CN.waypointProviders[preferred]

    if candidate and candidate.IsAvailable and candidate.IsAvailable() then
        return candidate, preferred
    end

    return nil
end

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "arrow",
    args    = "[on or off]",
    order   = 40,
    help    = "Toggle the on-screen navigation arrow.",
    handler = function(args)
        local settings = Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.arrow = true
        elseif args == "off" then
            settings.arrow = false
        elseif args ~= "" then
            Print("Usage: /cn arrow [on or off]")
            return
        else
            settings.arrow = (settings.arrow == false)
        end

        Print("Navigation arrow: " .. CN.YesNo(Navigation.IsArrowEnabled()))

        if Navigation.IsArrowEnabled() then
            BuildArrow()
            Refresh()
        elseif arrow then
            arrow:Hide()
        end

        if not target then
            Print("|cff8a8f96Nothing is being tracked. |cffffc74f/cn go|r "
                .. "points it at something.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "calibrate",
    aliases = { "flip" },
    order   = 43,
    help    = "Flip the navigation arrow if it points the wrong way.",
    handler = function()
        Navigation.SetFacingSign(-Navigation.FacingSign())
        Navigation.ResetCalibration()

        Print("Arrow direction flipped and remembered.")
        Print("|cff8a8f96Whether GetPlayerFacing counts clockwise or "
            .. "counter-clockwise is a client convention, so the addon "
            .. "normally works this out on its own by watching whether "
            .. "following the arrow shortens the distance.|r")

        Navigation.Refresh()
    end,
}

CN:RegisterCommand{
    name    = "nav",
    args    = "[auto, native, tomtom or blizzard]",
    order   = 41,
    help    = "Choose which navigation provider to use.",
    handler = function(args)
        args = CN.Trim(args or "")

        if args ~= "" then
            local ok, resolved = Navigation.SetPreference(args)

            if not ok then
                Print("Not a navigation provider: " .. args)

                -- Named from the registry rather than from a sentence, so a
                -- provider registered by another addon is offered here the
                -- moment it exists.
                Print("|cff8a8f96Choose auto, or one of: "
                    .. table.concat(Navigation.PreferenceNames(), ", ")
                    .. ".|r")

                return
            end

            Print("Navigation provider: |cffffc74f" .. tostring(resolved) .. "|r")
        end

        local preference = Navigation.Preference()

        Print("Preference: " .. (preference or "automatic"))

        local active, name = CN.GetWaypointProvider()

        Print("Currently using: " .. (active and name or "none available"))

        Print("Available:")

        for _, entry in ipairs(CN.waypointOrder) do
            local candidate = CN.waypointProviders[entry.name]

            local available = candidate and candidate.IsAvailable
                and candidate.IsAvailable()

            CN.PrintLine("  " .. entry.name .. " " .. CN.YesNo(available)
                .. " |cff8a8f96priority " .. entry.priority .. "|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "where am i",
    aliases = { "here" },
    order   = 42,
    help    = "Report your position and what is being tracked.",
    handler = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            Print("Your position is not available right now.")
            return
        end

        -- THE MAP ID, WHICH IS THE ONE THING THIS COMMAND WAS ASKED FOR AND
        -- DID NOT SAY.
        --
        -- `/cn setloc <questID> <mapID> <x> <y>` pointed players here to find
        -- a map id, and here printed the zone's NAME -- so the advice was a
        -- loop, and the fallback was `/dump C_Map.GetBestMapForUnit`.
        Print("You are in " .. tostring(Blizzard.GetMapName(mapID))
            .. CN.Muted(" (map " .. tostring(mapID) .. ")")
            .. (x and y and string.format(" at %.1f, %.1f", x * 100, y * 100)
                or ""))

        if not target then
            Print("Nothing is being tracked.")
            return
        end

        local state = Navigation.Compute()

        Print("Tracking: |cffffc74f" .. tostring(target.title) .. "|r in "
            .. tostring(target.zone))

        if state and state.state == "WRONG_MAP" then
            Print("  |cff8a8f96It is in another zone.|r")
        elseif state then
            Print("  " .. Navigation.FormatDistance(state.yards)
                .. (state.relative and string.format(" |cff8a8f96%d degrees off|r",
                    math.floor(math.abs(math.deg(state.relative)) + 0.5)) or ""))
        end
    end,
}

------------------------------------------------------------
-- LIFECYCLE
------------------------------------------------------------

CN:OnLogin(function()
    if Navigation.IsArrowEnabled() then
        BuildArrow()
    end
end)

-- Zone changes can move you onto the target's map, or off it.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    if target then
        Refresh()
    end
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\MapPins.lua'] = @'
-- Modules/MapPins.lua
-- Completion Navigator :: the plan, drawn on the world map.
--
-- Everything else in this addon answers "what next?" one line at a time. That
-- is the right answer to the question, but it hides the thing that actually
-- makes the routing worth having: the SHAPE of the work. The router already
-- groups objectives into hubs, orders the hubs to minimise walking, and
-- improves that order with a 2-opt pass -- and until now a player saw none of
-- it. They saw a list and an arrow, and had no way to know that stops three
-- through six were all the same camp, or that the route doubles back for a
-- reason.
--
-- So: one numbered pin per HUB, in route order, on the map you are looking at.
-- The number is the order. The tooltip is what you do when you arrive, in the
-- order you would do it. Clicking navigates there.
--
-- One pin per hub, not per objective. Twelve overlapping pins on one camp
-- communicate less than a single pin reading "3 -- pick up 2, do 4, hand in
-- 1", and a map that becomes unreadable when you have a lot to do is a map
-- that fails exactly when it matters most.
--
-- Deliberately NOT a MapCanvasDataProvider. The data-provider API is the
-- blessed route, and it is also a moving target that has broken addons across
-- several expansions. A pooled frame parented to the canvas is boring, has no
-- version surface to speak of, and degrades to "no pins" rather than to a Lua
-- error inside Blizzard's map code.

local ADDON_NAME, CN = ...

local MapPins = CN:RegisterModule("MapPins")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

local function Settings()
    return CN.Settings() or {}
end

------------------------------------------------------------
-- ENABLEMENT
------------------------------------------------------------

-- On by default. Pins are additive and read-only -- like tooltip lines, and
-- unlike the waypoint, they take nothing over and interrupt nothing. They
-- also appear only on a map you have deliberately opened.
function MapPins.IsEnabled()
    return Settings().mapPins ~= false
end

function MapPins.SetEnabled(value)
    Settings().mapPins = value and true or false

    if value then
        MapPins.Refresh(true)
    else
        MapPins.Clear()
    end

    return MapPins.IsEnabled()
end

------------------------------------------------------------
-- GEOMETRY
------------------------------------------------------------

-- Normalised map coordinates to a canvas offset.
--
-- The canvas is anchored from its TOPLEFT and y grows DOWNWARD, while map
-- coordinates also grow downward -- so the offset is +x and -y. Getting the
-- sign wrong mirrors every pin vertically, which looks plausible on a
-- symmetrical map and is completely wrong on every other one.
--
-- Pure, and tested as such: this is the one piece of the file that can be
-- wrong in a way no amount of looking at the screen would reveal, because a
-- mirrored pin is still a pin in a believable place.
function MapPins.CanvasOffset(x, y, width, height)
    if not x or not y or not width or not height then
        return nil
    end

    return x * width, -(y * height)
end

MapPins.pinSize      = 26
MapPins.maxPins      = 40
MapPins.crowdedScale = 0.8

-- How big a pin should be. A hub holding six things is worth more of the
-- player's attention than one holding a single stray pet, and size is the
-- cheapest way to say so without adding another colour to read.
function MapPins.PinSize(hubSize, pinCount)
    local size = MapPins.pinSize

    if (hubSize or 1) > 1 then
        size = size + math.min(10, (hubSize - 1) * 2)
    end

    -- A busy zone gets smaller pins rather than fewer of them. Dropping stops
    -- silently would misrepresent the route; shrinking them does not.
    if (pinCount or 0) > 12 then
        size = size * MapPins.crowdedScale
    end

    return math.floor(size + 0.5)
end

------------------------------------------------------------
-- LAYOUT
------------------------------------------------------------

-- Turns ordered hubs into pin descriptors. Pure: no frames, no client, no
-- side effects. Everything that decides what a pin SAYS happens here, so it
-- can be asserted offline.
function MapPins.Layout(hubs)
    local pins = {}

    if type(hubs) ~= "table" then
        return pins
    end

    local total = 0

    for _, hub in ipairs(hubs) do
        if hub.x and hub.y then
            total = total + 1
        end
    end

    for index, hub in ipairs(hubs) do
        if #pins >= MapPins.maxPins then
            break
        end

        -- A hub with no coordinates cannot be drawn. It is not dropped from
        -- the route -- the list still reports it -- it simply has nowhere to
        -- go on a map.
        if hub.x and hub.y then
            local objectives = hub.objectives or {}

            table.insert(pins, {
                order      = index,
                mapID      = hub.mapID,
                x          = hub.x,
                y          = hub.y,
                size       = MapPins.PinSize(#objectives, total),
                hubSize    = #objectives,
                summary    = CN.DescribeHub and CN.DescribeHub(hub) or nil,
                objectives = objectives,
            })
        end
    end

    -- HOW MANY DID NOT FIT. 0.84.0.
    --
    -- The loop above stops at `maxPins` and this function threw the shortfall
    -- away, while thirty lines up the note above `PinSize` states the
    -- opposite rule for the same overflow: "A busy zone gets smaller pins
    -- rather than fewer of them. Dropping stops silently would misrepresent
    -- the route; shrinking them does not." Past forty stops it does drop
    -- them, and said nothing.
    --
    -- `total` is already counted for the sizing; reporting it costs nothing
    -- and lets the caller apply the house rule -- a truncated list that looks
    -- complete is worse than a long one.
    return pins, math.max(0, total - #pins)
end

-- The tooltip body for one pin: what you do when you get there, in the order
-- you would do it. The hub's objectives are already sorted pick up -> do ->
-- hand in by the router, so this only has to not re-sort them.
function MapPins.DescribeLines(pin)
    local lines = {}

    if not pin then
        return lines
    end

    local quests = CN:GetModule("Quests")

    local shown = 0

    for _, objective in ipairs(pin.objectives or {}) do
        if shown >= 8 then
            table.insert(lines, string.format(
                "and %d more", #pin.objectives - shown))
            break
        end

        local verb = "do"

        if objective.phase and quests and quests.PhaseVerb then
            verb = quests.PhaseVerb(objective.phase)
        end

        table.insert(lines, string.format("%s: %s",
            verb, tostring(objective.name or objective.id)))

        shown = shown + 1
    end

    return lines
end

------------------------------------------------------------
-- THE CANVAS
------------------------------------------------------------

-- Resolves the world map's canvas, or nil. Every layer here is optional
-- because every layer is Blizzard's: if any of it moves, pins stop appearing
-- and nothing else in the addon notices.
function MapPins.Canvas()
    local map = _G and _G.WorldMapFrame

    if not map or not map.ScrollContainer then
        return nil
    end

    return map.ScrollContainer.Child
end

-- Which map the player is LOOKING AT, which is not necessarily where they
-- are standing.
function MapPins.DisplayedMapID()
    local map = _G and _G.WorldMapFrame

    if not map or not map.GetMapID then
        return nil
    end

    local ok, mapID = pcall(map.GetMapID, map)

    if ok then
        return mapID
    end

    return nil
end

function MapPins.IsMapShown()
    local map = _G and _G.WorldMapFrame

    if not map or not map.IsShown then
        return false
    end

    local ok, shown = pcall(map.IsShown, map)

    return ok and shown == true
end

------------------------------------------------------------
-- THE ROUTE FOR A DISPLAYED MAP
------------------------------------------------------------

-- Where a route across THIS map should start.
--
-- If you are looking at the zone you are standing in, the route starts at
-- your feet -- that is the whole point of routing. If you are looking at
-- somewhere else, your position is meaningless there: using it would order
-- the stops by their distance from a point on another continent, producing a
-- route that is not merely suboptimal but arbitrary. Start from the middle
-- instead, which orders the stops by their relationship to each other.
function MapPins.RouteStart(displayedMapID)
    local playerMap, x, y = nil, nil, nil

    if CN.GetPlayerPosition then
        local ok, a, b, c = pcall(CN.GetPlayerPosition)

        if ok then
            playerMap, x, y = a, b, c
        end
    end

    if displayedMapID and playerMap == displayedMapID and x and y then
        return x, y, true
    end

    return 0.5, 0.5, false
end

local cache = { mapID = nil, generation = nil, hubs = nil }

function MapPins.InvalidateCache()
    cache.mapID      = nil
    cache.generation = nil
    cache.hubs       = nil
end

-- EVERYTHING THE ROUTE DEPENDS ON, NOT JUST THE CANDIDATES.
--
-- `BuildZoneRoute` applies the objective-type filter when it picks the stops,
-- so the hub set is a function of that filter as well as of the candidate
-- list. `SetTypeEnabled` deliberately does not rebuild providers -- it bumps
-- `CN.typeFilterGeneration` instead -- so the candidate generation did not
-- move and this cache did not notice.
--
-- The result was two views of one route disagreeing on screen: `/cn zone`
-- honoured `/cn show only quests` and the map, reopened a second later, still
-- drew the pet and appearance stops the player had just hidden.
local function RouteGeneration()
    local generation = 0

    if CN.GetCandidateCacheState then
        local ok, state = pcall(CN.GetCandidateCacheState)

        if ok and state then
            generation = state.generation or 0
        end
    end

    -- The ranking generation is deliberately NOT part of this key:
    -- `BuildZoneRoute` bumps it itself, so including it would mean the cache
    -- never matched and the route was rebuilt on every map pan -- which is
    -- the cost this cache exists to avoid.
    return generation .. ":" .. tostring(CN.typeFilterGeneration or 0)
end

-- Building a zone route means collecting and scoring every candidate, so it
-- must not happen on every map pan. It happens when the map you are looking
-- at changes, or when the underlying candidates do.
function MapPins.HubsForMap(mapID, force)
    if not mapID or not CN.BuildZoneRoute then
        return nil
    end

    local generation = RouteGeneration()

    if not force
        and cache.mapID == mapID
        and cache.generation == generation
        and cache.hubs then

        return cache.hubs
    end

    local startX, startY = MapPins.RouteStart(mapID)

    local ok, _, _, hubs = pcall(CN.BuildZoneRoute, mapID, startX, startY)

    if not ok then
        return nil
    end

    cache.mapID      = mapID
    cache.generation = generation
    cache.hubs       = hubs

    return hubs
end

------------------------------------------------------------
-- THE PINS THEMSELVES
------------------------------------------------------------

local pool = {}

-- A SEQUENCE, NOT ONE BRIGHT PIN AND A CROWD OF GREY ONES.
--
-- Stop one wore the brand blue and every other stop wore the same flat grey,
-- so a twelve-stop route read as one pin and eleven identical ones -- and the
-- numbers, which are the smallest and least legible thing on the map, were
-- the only way to tell them apart.
--
-- The route is ordered, and the pins should say so. Same hue throughout,
-- stepped down in value: bright at the front, fading back. That is what the
-- whole 2-opt pass exists to produce and it is now visible without reading a
-- single digit.
MapPins.trailFade = 0.06
MapPins.trailFloor = 0.55

local function PinColor(order)
    local brand = CN.RGB.BRAND

    if (order or 1) <= 1 then
        return brand[1], brand[2], brand[3]
    end

    local step = math.min(MapPins.trailFloor,
        0.10 + ((order - 1) * MapPins.trailFade))

    local keep = 1 - step

    return brand[1] * keep, brand[2] * keep, brand[3] * keep
end

local function ShowPinTooltip(frame)
    if not GameTooltip or not frame.pin then
        return
    end

    GameTooltip:SetOwner(frame, "ANCHOR_RIGHT")

    GameTooltip:AddLine(string.format("Stop %d", frame.pin.order), 1, 1, 1)

    if frame.pin.summary then
        GameTooltip:AddLine(frame.pin.summary, CN.Rgb("BRAND"))
    end

    for _, line in ipairs(MapPins.DescribeLines(frame.pin)) do
        GameTooltip:AddLine(line, CN.Rgb("BODY"))
    end

    GameTooltip:AddLine("Click to navigate here", CN.Rgb("MUTED"))

    GameTooltip:Show()
end

local function HidePinTooltip()
    if GameTooltip then
        GameTooltip:Hide()
    end
end

-- Clicking navigates to the STOP, not to whichever objective happens to be
-- listed first there.
--
-- Those are different things. An objective's own coordinates may be missing
-- -- plenty of collectibles are known to be in a zone and nowhere more
-- precise -- while the stop's are the centre of everything at it and always
-- exist, because that is how the stop was formed. Routing to the member and
-- finding it has no location would answer a click with "no coordinates are
-- known", which from the player's side is the addon refusing to go to a place
-- it just drew a pin on.
local function ClickPin(frame)
    local pin = frame.pin

    if not pin then
        return
    end

    for _, objective in ipairs(pin.objectives or {}) do
        if objective.x and objective.y and CN.NavigateToObjective then
            CN.NavigateToObjective(objective)
            return
        end
    end

    if pin.x and pin.y and pin.mapID and CN.SetWaypointAndSay then
        local first = (pin.objectives or {})[1]

        local label = first and tostring(first.name or first.id)
            or ("Stop " .. tostring(pin.order))

        -- SAY SOMETHING. 0.79.0. This clicked a pin on the world map and
        -- printed nothing, so a refusal and a success looked identical.
        CN.SetWaypointAndSay(pin.mapID, pin.x, pin.y, label,
            "Waypoint set: " .. label)
    end
end

local function AcquirePin(index, canvas)
    if pool[index] then
        return pool[index]
    end

    if not CreateFrame or not canvas then
        return nil
    end

    local frame = CreateFrame("Button", "CompletionNavigatorMapPin" .. index, canvas)

    frame:SetSize(MapPins.pinSize, MapPins.pinSize)

    frame.texture = frame:CreateTexture(nil, "OVERLAY")
    frame.texture:SetAllPoints()
    frame.texture:SetTexture(CN.MEDIA_PATH .. "Arrow")

    if not frame.texture:GetTexture() then
        frame.texture:SetTexture("Interface\\Minimap\\MinimapArrow")
    end

    frame.label = CN.Label(frame, "OVERLAY", "CAPTION")
    frame.label:SetPoint("CENTER")

    -- Over map art, which is the same problem as over the world: a stop
    -- number in ten-point gold with a one-pixel shadow disappears against
    -- half the maps in the game.
    CN.Outline(frame.label, 12, "PRIMARY")

    frame:SetScript("OnEnter", ShowPinTooltip)
    frame:SetScript("OnLeave", HidePinTooltip)
    frame:SetScript("OnClick", ClickPin)

    pool[index] = frame

    return frame
end

MapPins.AcquirePin = AcquirePin

function MapPins.Clear()
    for _, frame in ipairs(pool) do
        frame:Hide()
    end
end

-- Positions the pins. Separated from Refresh so the arithmetic can be driven
-- offline against a stubbed canvas.
function MapPins.Place(pins, canvas)
    if not canvas then
        return 0
    end

    local width  = canvas:GetWidth()
    local height = canvas:GetHeight()

    if not width or not height or width <= 0 or height <= 0 then
        return 0
    end

    local placed = 0

    for index, pin in ipairs(pins) do
        local frame = AcquirePin(index, canvas)

        if frame then
            local offsetX, offsetY = MapPins.CanvasOffset(pin.x, pin.y, width, height)

            if offsetX then
                frame.pin = pin

                frame:SetSize(pin.size, pin.size)
                frame:ClearAllPoints()
                frame:SetPoint("CENTER", canvas, "TOPLEFT", offsetX, offsetY)

                frame.label:SetText(tostring(pin.order))
                frame.texture:SetVertexColor(PinColor(pin.order))

                frame:Show()

                placed = placed + 1
            end
        end
    end

    -- Surplus frames from a busier map are hidden, never destroyed. Pin
    -- frames are cheap to keep and expensive to churn.
    for index = #pins + 1, #pool do
        pool[index]:Hide()
        pool[index].pin = nil
    end

    return placed
end

function MapPins.Refresh(force)
    if not MapPins.IsEnabled() then
        MapPins.Clear()
        return 0
    end

    if not MapPins.IsMapShown() then
        return 0
    end

    local canvas = MapPins.Canvas()

    if not canvas then
        return 0
    end

    local mapID = MapPins.DisplayedMapID()

    if not mapID then
        MapPins.Clear()
        return 0
    end

    local hubs = MapPins.HubsForMap(mapID, force)

    if not hubs then
        MapPins.Clear()
        return 0
    end

    -- AND CARRY THE SHORTFALL OUT. 0.85.0. `Layout` reports how many stops
    -- did not fit; this function discarded it, so the one caller that prints
    -- a number still printed the capped one as the total.
    local pins, dropped = MapPins.Layout(hubs)

    local placed = MapPins.Place(pins, canvas)

    DebugPrint(string.format("Map pins: %d stop(s) on map %s.",
        placed, tostring(mapID)))

    return placed, dropped or 0
end

------------------------------------------------------------
-- HOOKS
------------------------------------------------------------

local hooked = false

-- Hooked, not overwritten. The world map is shared with every other addon
-- the player runs, and replacing a script on it would break them.
function MapPins.Install()
    if hooked then
        return true
    end

    local map = _G and _G.WorldMapFrame

    if not map or not map.HookScript then
        return false
    end

    -- GUARDED, because these are hooks on a frame the player opens
    -- constantly and shares with every other addon they run. An unguarded
    -- throw here is an error box every time the world map opens.
    map:HookScript("OnShow", function()
        CN.Guard("MapPins.Refresh", MapPins.Refresh)
    end)

    map:HookScript("OnHide", function()
        CN.Guard("MapPins.Clear", MapPins.Clear)
    end)

    -- Panning to a different zone is a map change, not a redraw, so the
    -- route must be rebuilt for the map now on screen.
    if map.RegisterCallback and map.OnMapChanged then
        pcall(map.RegisterCallback, map, "WorldMapOnMapChanged", function()
            CN.Guard("MapPins.Refresh", MapPins.Refresh)
        end)
    end

    hooked = true

    return true
end

CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    MapPins.Install()
end)

CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    MapPins.InvalidateCache()
    MapPins.Refresh()
end)

CN:RegisterEvent("QUEST_LOG_UPDATE", function()
    MapPins.InvalidateCache()
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "pins",
    aliases = { "map" },
    args    = "[on, off, or refresh]",
    order   = 18,
    help    = "Show the route as numbered pins on the world map.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            MapPins.SetEnabled(true)
            Print("Map pins are on.")
            return
        end

        if args == "off" then
            MapPins.SetEnabled(false)
            Print("Map pins are off.")
            return
        end

        if args == "refresh" then
            MapPins.InvalidateCache()

            -- THE OTHER BRANCH OF THIS HANDLER. 0.85.0. 0.84.0 fixed the
            -- listing twenty-five lines below to say how many stops it did
            -- not draw, and left the branch above it reporting the capped
            -- count as a fact -- "Redrew 40 stops." for a route of
            -- sixty-three. The sibling nobody swept, in the same function as
            -- the fix.
            local placed, dropped = MapPins.Refresh(true)

            Print("Redrew " .. CN.Count(placed, "stop") .. "."
                .. ((dropped or 0) > 0
                    and CN.Aside(dropped .. " more not drawn; the map caps at "
                        .. MapPins.maxPins) or ""))
            return
        end

        if not MapPins.IsEnabled() then
            Print("Map pins are off. Turn them on with /cn pins on")
            return
        end

        local mapID = MapPins.DisplayedMapID()

        if not mapID then
            Print("Map pins are on. Open the world map to see the route.")
            return
        end

        local hubs = MapPins.HubsForMap(mapID)
        local pins, dropped = MapPins.Layout(hubs or {})

        if #pins == 0 then
            Print("Nothing to route on this map.")
            return
        end

        -- AND SAY WHEN IT STOPPED. 0.84.0. This printed the TRUNCATED count
        -- as the total, so in a busy zone a player read "40 stops on this
        -- map:" as a statement of fact about the whole route.
        Print(CN.Count(#pins, "stop") .. " on this map"
            .. ((dropped or 0) > 0
                and CN.Aside(dropped .. " more not drawn; the map caps at "
                    .. MapPins.maxPins) or "") .. ":")

        for _, pin in ipairs(pins) do
            CN.PrintLine(string.format("  %d. %s (%d)",
                pin.order,
                tostring(pin.summary or "do " .. pin.hubSize),
                pin.hubSize))
        end
    end,
}

return MapPins
'@

$Embedded['Modules\Broker.lua'] = @'
-- Modules/Broker.lua
-- Completion Navigator :: LibDataBroker feed, and rare-spawn alerts.
--
-- Two small things that share a theme: telling you something without you
-- having to ask.
--
-- The broker is the addon's answer to "what next?" displayed permanently in
-- whatever bar you already run -- Titan Panel, ElvUI, ChocolateBar. This is
-- the only place the addon touches an external library, and it does so the
-- same way it touches TomTom and AllTheThings: probed, wrapped, optional. If
-- LibDataBroker is not installed nothing happens and nothing is said, because
-- an addon complaining about a library you never asked for is noise.
--
-- Alerts are OFF by default. Unsolicited sound is worse than a waypoint you
-- did not ask for, and this addon has already decided how it feels about that.

local ADDON_NAME, CN = ...

local Broker = CN:RegisterModule("Broker")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- LIBDATABROKER
------------------------------------------------------------

Broker.available = false

local dataObject

-- `results` may be supplied by a caller that already has them. The
-- recommendation hook does, and re-asking from inside it is re-entering the
-- function that fired the hook -- which recursed until pcall stopped it and
-- cost seventy times the budget for one refresh. A performance budget caught
-- it before it shipped.
local function CurrentText(results)
    if not results then
        local ok, fetched = pcall(CN.Recommend, 1)

        results = ok and fetched or nil
    end

    if not results or not results[1] then
        return "Completion Navigator", CN.L["nothing actionable"]
    end

    local objective = results[1]

    return tostring(objective.name or objective.id), CN.TypeBadge(objective.type)
end

Broker.CurrentText = CurrentText

function Broker.Refresh(results)
    if not dataObject then
        return
    end

    local name, kind = CurrentText(results)

    dataObject.text  = name
    dataObject.value = name
    dataObject.label = kind
end

function Broker.Install()
    if Broker.available or not LibStub then
        return Broker.available
    end

    -- LibStub's silent form: it returns nil rather than throwing when the
    -- library is absent, which is exactly what optional means.
    local ok, ldb = pcall(LibStub, "LibDataBroker-1.1", true)

    if not ok or not ldb then
        return false
    end

    local created, object = pcall(ldb.NewDataObject, ldb, "CompletionNavigator", {
        type  = "data source",
        text  = "Completion Navigator",
        icon  = CN.MEDIA_PATH .. "Logo",

        -- GUARDED, both of them. `Broker.CurrentText` forty lines up already
        -- wraps `CN.Recommend`; the click and tooltip handlers did not -- and
        -- these run inside the host bar addon, so a throw here breaks Titan
        -- Panel's or ElvUI's tooltip rather than this addon's.
        OnClick = function(_, button)
            if button == "RightButton" then
                local asked, results = pcall(CN.Recommend, 1)

                if not asked then
                    results = nil
                end

                if results and results[1] then
                    CN.NavigateToObjective(results[1])
                end

                return
            end

            if CN.UI and CN.UI.Toggle then
                CN.UI.Toggle()
            end
        end,

        OnTooltipShow = function(tooltip)
            if not tooltip or not tooltip.AddLine then
                return
            end

            tooltip:AddLine("Completion Navigator")

            local asked, results = pcall(CN.Recommend, 3)

            if not asked then
                tooltip:AddLine("Something went wrong; /cn errors has it.",
                    CN.Rgb("BAD"))
                return
            end

            if not results or #results == 0 then
                tooltip:AddLine("Nothing actionable yet.", CN.Rgb("MUTED"))

                for index, line in ipairs(CN.ExplainEmptyList()) do
                    if index > 2 then
                        break
                    end

                    tooltip:AddLine(line, CN.Rgb("MUTED"))
                end

                return
            end

            for index, objective in ipairs(results) do
                tooltip:AddLine(
                    (index == 1 and "Next: " or "     ")
                        .. tostring(objective.name or objective.id),
                    index == 1 and 0.365 or 0.7,
                    index == 1 and 0.824 or 0.7,
                    index == 1 and 0.984 or 0.7)
            end

            tooltip:AddLine(" ")
            tooltip:AddLine("Left-click to open, right-click to navigate.", 1, 1, 1)
        end,
    })

    if not created or not object then
        return false
    end

    dataObject      = object
    Broker.available = true

    -- NO EAGER REFRESH HERE. 0.61.0.
    --
    -- `Install` runs from a login hook, and the refresh it used to do called
    -- `CN.Recommend` -- a cold rebuild of every candidate, 15.34 ms of an
    -- 18.35 ms `PLAYER_LOGIN` frame. It bought nothing:
    --
    --   1. It ran before the collection scans in their own login hooks had
    --      populated anything, so it almost always settled on the same
    --      "nothing actionable" the feed was CREATED with two lines above.
    --   2. The `OnLogin` timer at the bottom of this file refreshes ten
    --      seconds later, after those scans, from a real database.
    --   3. The recommendation hook refreshes on every recompute thereafter.
    --
    -- Deleting it moves the cost off the frame the player watches the world
    -- fade in on, and the feed's first real text arrives no later than before.

    DebugPrint("LibDataBroker feed registered.")

    return true
end

------------------------------------------------------------
-- RARE ALERTS
------------------------------------------------------------

-- Which vignettes have already been announced this session. A rare drifting
-- in and out of vignette range must not announce itself repeatedly.
local announced = {}

function Broker.AlertsEnabled()
    local settings = CN.Settings()

    -- Off by default, deliberately. See the file header.
    return settings and settings.rareAlerts == true
end

function Broker.ResetAnnounced()
    announced = {}
end

-- Returns the vignettes worth announcing: up right now, not already announced,
-- not already cleared by this character, and not something you have ignored.
function Broker.PendingAlerts()
    local rares = CN:GetModule("Rares")

    if not rares then
        return {}
    end

    local pending = {}

    for _, vignette in ipairs(rares.GetActive()) do
        local id = vignette.vignetteID

        if id
            and not announced[id]
            and vignette.kind == "RARE"
            and not rares.IsClearedByCharacter(id)
            and not CN.IsIgnored(CN.objectiveTypes.RARE, id) then

            table.insert(pending, vignette)
        end
    end

    return pending
end

function Broker.Announce(vignette)
    announced[vignette.vignetteID] = time()

    Print("|cff5dd2fbRare up:|r " .. tostring(vignette.name or "unknown")
        .. (vignette.x and vignette.y
            and string.format(" |cff8a8f96%.1f, %.1f|r",
                vignette.x * 100, vignette.y * 100)
            or ""))

    if PlaySound then
        -- A quiet, non-alarming stock sound. Raid warnings are for raids.
        pcall(PlaySound, 8959, "Master")
    end

    return true
end

function Broker.CheckAlerts()
    if not Broker.AlertsEnabled() then
        return 0
    end

    local sent = 0

    for _, vignette in ipairs(Broker.PendingAlerts()) do
        Broker.Announce(vignette)

        sent = sent + 1
    end

    return sent
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- THE ALERT PATH IS THROTTLED TOO. 0.80.0.
--
-- `Rares.lua` debounces this exact pair of events and says in its own comment
-- that "the alert path that announces one is a separate event handler that is
-- not throttled by this at all" -- naming this file, which then stayed
-- unthrottled for nineteen releases. `VIGNETTE_MINIMAP_UPDATED` fires several
-- times a second while moving, and each firing ran `CheckAlerts` ->
-- `Rares.GetActive` -> `Rares.GetAll` -> `Blizzard.GetVignettes`, which is
-- two client calls and two table allocations PER VIGNETTE, plus a position
-- read, a sort, and a hidden/cleared test per row.
--
-- Same debounce, same one-second window, as the sweep beside it: leading edge
-- so the first rare in a burst is still announced at once.
for _, event in ipairs({ "VIGNETTE_MINIMAP_UPDATED", "VIGNETTES_UPDATED" }) do
    CN:RegisterEvent(event, function()
        CN.Debounce("Broker.alerts", 1, function()
            local ok, err = pcall(Broker.CheckAlerts)

            if not ok then
                DebugPrint("Rare alert check failed: " .. tostring(err))
            end
        end)
    end)
end

-- A new zone is a new set of rares; nothing carries over.
CN:RegisterEvent("ZONE_CHANGED_NEW_AREA", function()
    Broker.ResetAnnounced()
end)

CN:OnLogin(function()
    Broker.Install()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "alerts",
    args    = "[on or off]",
    order   = 44,
    help    = "Announce rares that appear near you.",
    handler = function(args)
        local settings = CN.Settings()

        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            settings.rareAlerts = true
        elseif args == "off" then
            settings.rareAlerts = false
        elseif args ~= "" then
            Print("Usage: /cn alerts [on or off]")
            return
        else
            settings.rareAlerts = not Broker.AlertsEnabled()
        end

        Print("Rare alerts: " .. CN.YesNo(Broker.AlertsEnabled()))

        if Broker.AlertsEnabled() then
            Print("|cff8a8f96Announced once each, only for rares you have not "
                .. "already cleared, and reset when you change zone.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "broker",
    order   = 45,
    help    = "Show LibDataBroker status.",
    handler = function()
        if Broker.available then
            local name = CurrentText()

            Print("LibDataBroker feed: " .. CN.YesNo(true))
            Print("Currently showing: |cffffc74f" .. tostring(name) .. "|r")
            Print("|cff8a8f96Add it from your display addon: Titan Panel, "
                .. "ElvUI datatexts, ChocolateBar.|r")
            return
        end

        Print("LibDataBroker feed: " .. CN.YesNo(false))
        Print("|cff8a8f96LibDataBroker is not installed, which is fine" .. CN.DASH .. "it is "
            .. "optional. Display addons like Titan Panel and ElvUI ship it, "
            .. "and the feed appears automatically when one of them is present.|r")
    end,
}

------------------------------------------------------------
-- KEEPING IT CURRENT
------------------------------------------------------------

-- REFRESHED WHEN THE ANSWER CHANGES, WHICH IT NEVER WAS.
--
-- `Broker.Refresh` had exactly one caller: `Install`, from a login hook that
-- runs before the collection scans in their own login hooks have populated
-- anything. So the feed was built from an empty database, almost always
-- settled on "nothing actionable", and then never changed again for the whole
-- session -- in a module whose header calls it "the addon's answer to 'what
-- next?' displayed permanently".
--
-- A recommendation hook is the right place: it fires exactly when the list is
-- recomputed, which is the only time this text can be stale.
if CN.RegisterRecommendationHook then
    CN.RegisterRecommendationHook("Broker", function(results)
        if Broker.available then
            pcall(Broker.Refresh, results)
        end
    end)
end

-- And once shortly after login, because a player who opens no window and
-- asks for nothing should still see a real answer rather than the placeholder
-- the feed was created with.
CN:OnLogin(function()
    if C_Timer and C_Timer.After then
        C_Timer.After(10, function()
            if Broker.available then
                pcall(Broker.Refresh)
            end
        end)
    end
end)

-- CN:APPEND -- cn.ps1 inserts generated commands and event handlers above this line.
'@

$Embedded['Modules\Group.lua'] = @'
-- Modules/Group.lua
-- Completion Navigator :: the state the player is actually in.
--
-- Two facts the addon has never read, both of which change what a sensible
-- next action is, and both of which the client reports for free.
--
-- BEING DEAD.
--
-- A dead player's next action is not "collect a battle pet". It is "get back
-- to your body". Until 0.43.0 the addon carried on recommending as though
-- nothing had happened, which is not merely unhelpful -- it is the clearest
-- possible signal that the addon is not paying attention.
--
-- BEING IN A GROUP.
--
-- The addon behaved identically whether you were alone or standing in a
-- dungeon with four other people. Somebody in an instance with a group is not
-- about to go and pick a herb in Durotar, and a recommendation that says so
-- is noise at best and a reason to close the window at worst.
--
-- WHAT THIS DELIBERATELY IS NOT.
--
-- It is not addon-to-addon communication. No messages are sent, no protocol
-- is defined, and nothing depends on anybody else running this addon. That
-- design needs versioned messages and matching builds on both machines, and
-- it becomes a support burden the moment either side is stale. Everything
-- here is read from the client, about this player, on this machine.

local ADDON_NAME, CN = ...

local Group = CN:RegisterModule("Group")

local Print = CN.Print

------------------------------------------------------------
-- STATE
------------------------------------------------------------

function Group.IsDead()
    if UnitIsDeadOrGhost then
        local ok, dead = pcall(UnitIsDeadOrGhost, "player")

        if ok then
            return dead and true or false
        end
    end

    return false
end

function Group.IsGhost()
    if UnitIsGhost then
        local ok, ghost = pcall(UnitIsGhost, "player")

        if ok then
            return ghost and true or false
        end
    end

    return false
end

function Group.Size()
    if GetNumGroupMembers then
        local ok, count = pcall(GetNumGroupMembers)

        if ok and type(count) == "number" then
            return count
        end
    end

    return 0
end

function Group.InGroup()
    return Group.Size() > 1
end

function Group.InRaid()
    if IsInRaid then
        local ok, raid = pcall(IsInRaid)

        if ok then
            return raid and true or false
        end
    end

    return false
end

-- Returns inInstance, kind ("party", "raid", "scenario", "pvp", "none").
function Group.Instance()
    if not IsInInstance then
        return false, "none"
    end

    local ok, inside, kind = pcall(IsInInstance)

    if not ok then
        return false, "none"
    end

    return inside and true or false, kind or "none"
end

-- One word for what the player is doing, which is all the ranking needs.
function Group.Situation()
    if Group.IsDead() then
        return "dead"
    end

    local inside, kind = Group.Instance()

    -- WITH A GROUP. 0.80.0.
    --
    -- The header of this file states the premise: "Somebody in an instance
    -- WITH A GROUP is not about to go and pick a herb in Durotar." This test
    -- never asked about the group, so it returned "instanced" for a player
    -- standing alone in an old raid -- which is the single most common way
    -- mounts, pets, toys and appearances are farmed in this game, and every
    -- one of those types is in `Group.instancedTypes`. The addon buried the
    -- mount you walked in for by 65%, and explained it with "you are in an
    -- instance with a group", to a player with nobody else there. `/cn
    -- situation` said so out loud: "in a instance with 0 people".
    --
    -- The harness never caught it because its fixture sets the instance and
    -- a party of five together, so the two conditions were never separable.
    if inside and Group.InGroup()
        and (kind == "party" or kind == "raid" or kind == "scenario") then

        return "instanced"
    end

    if Group.InGroup() then
        return "grouped"
    end

    return "solo"
end

------------------------------------------------------------
-- WHAT IT CHANGES
------------------------------------------------------------

-- Types that make no sense to walk off and do while four other people are
-- waiting at a boss. NOT hidden -- the player asked to see them at some point
-- and the addon does not un-ask that -- just pushed down.
Group.instancedPenalty = 0.35

-- INSIDE, WHETHER OR NOT ANYBODY IS WITH YOU. 0.81.0.
--
-- Two different facts were being answered by one word. `Situation()` answers
-- a SOCIAL question -- are other people waiting on you -- and 0.80.0 fixed it
-- to require a group, correctly: soloing an old raid for its mount is not
-- "four people waiting at a boss".
--
-- But it left the OTHER fact unasked. Standing inside any instance, alone or
-- not, a herb in Durotar is not something you can go and do; it is something
-- you can do after a loading screen. Nothing in the ranking knew that, so a
-- solo player in Firelands could be handed an outdoor world quest as the best
-- next thing.
--
-- These are answered separately now, because they are separate questions.
Group.outsidePenalty = 0.5

function Group.InsideInstance()
    local inside, kind = Group.Instance()

    return inside
        and (kind == "party" or kind == "raid" or kind == "scenario")
        or false
end

-- Is this objective somewhere the player would have to leave to reach?
--
-- Answers FALSE for everything when the addon does not know where the player
-- is standing, which is the honest reading of a nil map. `GetPlayerPosition`
-- returns nothing during a loading screen -- and `PLAYER_ENTERING_WORLD`
-- invalidates the ranking, so a re-score is scheduled at exactly that moment.
-- Treating "I do not know yet" as "outside" would halve the score of the boss
-- in the room the player had just loaded into and stamp a sentence saying so.
--
-- UNKNOWN IS NOT OUTSIDE. The same reading applies one level down: the
-- instance-identity walk refuses rather than guessing while `C_Map` is still
-- coming up, and a refusal here means no penalty.
function Group.Outside(objective)
    if type(objective) ~= "table" or not objective.mapID then
        return false
    end

    -- NOT MEMOISED, DELIBERATELY -- AND THIS IS THE SECOND ATTEMPT.
    --
    -- The first stamped the answer with `GetTime()`, on the reasoning that
    -- the player cannot move between two candidates in the same frame. True
    -- in the client and false everywhere else: the offline suite drives many
    -- scenarios inside one frame, so the memo answered the FIRST scenario's
    -- question for all of them and the whole branch silently did nothing.
    --
    -- The cost this was avoiding is one `pcall(IsInInstance)`; the position
    -- read underneath already carries its own single-frame memo. That is not
    -- worth a cache whose correctness depends on the clock advancing.
    if not Group.InsideInstance() then
        return false
    end

    local here = select(1, CN.GetPlayerPosition())

    if not here then
        return false
    end

    if objective.mapID == here then
        return false
    end

    -- AT INSTANCE LEVEL, NOT ZONE LEVEL. 0.81.0's first attempt compared
    -- `ZoneMapID`, which walks up to the first ancestor the client calls a
    -- ZONE -- and most modern instance maps parent into the outdoor zone
    -- around them. So the world quest on the other side of the door compared
    -- EQUAL to the boss in front of the player, and nothing outside was
    -- ranked down at all: the exact opposite of what this branch is for.
    -- `Loremaster.lua` records the same trap for the same function.
    local walk = CN.Blizzard and CN.Blizzard.InstanceMapID

    if not walk then
        return false
    end

    local hereInstance = walk(here)

    if not hereInstance then
        return false
    end

    -- A multi-floor dungeon is several maps and one instance, so two floors
    -- of the same instance compare equal and walking downstairs does not
    -- demote the treasure upstairs.
    return walk(objective.mapID) ~= hereInstance
end

Group.instancedTypes = {
    [CN.objectiveTypes.PET]         = true,
    [CN.objectiveTypes.TOY]         = true,
    [CN.objectiveTypes.MOUNT]       = true,
    [CN.objectiveTypes.APPEARANCE]  = true,
    [CN.objectiveTypes.EXPLORATION] = true,
    [CN.objectiveTypes.RARE]        = true,
    [CN.objectiveTypes.TREASURE]    = true,
    [CN.objectiveTypes.VENDOR]      = true,
    [CN.objectiveTypes.PROFESSION]  = true,
    [CN.objectiveTypes.RECIPE]      = true,
}

-- While dead, everything is worth less than getting up. The multiplier is
-- deliberately not zero: the list still answers "what next", it just stops
-- pretending the player can act on it this second.
Group.deadPenalty = 0.2

------------------------------------------------------------
-- WORK THE GROUP SHARES
------------------------------------------------------------

-- THE OTHER HALF OF PARTY AWARENESS, WHICH WAS NEVER BUILT.
--
-- The addon has known since 0.44.0 that you are in a group and has used that
-- to stop offering solo detours mid-dungeon. It has never used it for the
-- thing a group is actually for: four people standing in a zone, and one of
-- the six quests on the list is one all four of them are carrying.
--
-- That one is worth four times the work of a quest only you have, and every
-- player already knows it -- it is why people say "anyone else need Bloodfen?"
-- out loud. The addon had the information and said nothing.
--
-- LOCAL ONLY, WHICH IS THE WHOLE DESIGN. `C_QuestLog.IsUnitOnQuest` answers
-- from your own client about a unit already in your group. Nothing is sent,
-- no protocol is agreed, no other machine has to be running this addon, and
-- it degrades to silence outside a group. The DECLINED backlog item is
-- addon-to-addon route sharing; this is not that.
Group.sharedBonusPerMember = 0.12
Group.sharedBonusCap       = 0.45

-- HELD ACROSS RANKING PASSES, NOT WITHIN ONE.
--
-- The first version keyed this on `CN.rankingGeneration`, which is bumped by
-- `InvalidateRanking` -- the very thing that triggers a re-rank. So the cache
-- was cleared at exactly the moment it would have been used, and every pass
-- asked the client afresh: measured at 8,151 `IsUnitOnQuest` calls and 7.2 ms
-- for one pass over two hundred candidates in a forty-person raid, against a
-- 0.4 ms budget for `Recommend(25)`.
--
-- The answer changes when the ROSTER changes or when somebody accepts or
-- turns in a quest, and both of those already announce themselves. So the
-- cache lives until one of them does.
local sharedCache = {}
local unitCache   = nil

-- How long an answer about somebody else's quest log is worth trusting. See
-- the header inside `SharedWith`.
Group.sharedCacheSeconds = 30

-- The client's fractional clock where it exists, wall clock otherwise. Split
-- out so a test can move it.
function Group.Now()
    return (GetTime and GetTime()) or (time and time()) or 0
end

function Group.ForgetShared()
    sharedCache = {}
    unitCache   = nil
end

-- The unit tokens of the rest of the group, in the order the client lists
-- them. Empty when solo, which is what makes every path below free.
-- Built once per roster rather than once per candidate. This was called
-- before the cache lookup, so a forty-person raid allocated a forty-entry
-- table and forty concatenated strings for every objective on every pass --
-- 8,400 transient strings per ranking, for a list that changes when somebody
-- joins or leaves.
function Group.Units()
    if unitCache then
        return unitCache
    end

    local size = Group.Size()

    if size < 2 then
        unitCache = {}

        return unitCache
    end

    local units = {}

    if Group.InRaid() then
        for index = 1, math.min(size, 40) do
            table.insert(units, "raid" .. index)
        end
    else
        for index = 1, math.min(size - 1, 4) do
            table.insert(units, "party" .. index)
        end
    end

    unitCache = units

    return units
end

-- How many OTHER people in your group are on this quest.
--
-- Nil rather than zero when the question cannot be asked -- solo, or a client
-- without the API -- because "nobody else needs this" and "there is nobody
-- else" are different statements and only one of them should reach the
-- scorer.
function Group.SharedWith(questID)
    questID = CN.ToID(questID)

    if not questID then
        return nil
    end

    if not C_QuestLog or not C_QuestLog.IsUnitOnQuest then
        return nil
    end

    local units = Group.Units()

    if #units == 0 then
        return nil
    end

    -- BOUNDED BY AGE, BECAUSE NO EVENT CAN INVALIDATE THIS.
    --
    -- The answer comes from `C_QuestLog.IsUnitOnQuest(unit, questID)` -- a
    -- question about somebody ELSE'S quest log -- and the client fires no
    -- event when a party member accepts or hands one in. The invalidation
    -- below subscribes to `QUEST_ACCEPTED` and `QUEST_TURNED_IN`, which fire
    -- only for the player, so it never cleared this at all.
    --
    -- Four people in your group finish the quest and stay grouped: your list
    -- kept the shared-work multiplier and `/cn why` kept saying "4 others
    -- here are on this quest" until somebody left the party.
    --
    -- There is no event to wait for, so the honest answer is a short life
    -- rather than a claim of coverage. Thirty seconds is far cheaper than the
    -- per-candidate cost this cache exists to avoid and far fresher than
    -- "until the roster changes".
    local held = sharedCache[questID]

    if held ~= nil and (Group.Now() - held.at) < Group.sharedCacheSeconds then
        return held.value
    end

    local sharing = 0

    for _, unit in ipairs(units) do
        -- Not the player themselves: `raid1` may be you.
        local isSelf = UnitIsUnit and UnitIsUnit(unit, "player")

        if not isSelf then
            local ok, onIt = pcall(C_QuestLog.IsUnitOnQuest, unit, questID)

            if ok and onIt then
                sharing = sharing + 1
            end
        end
    end

    sharedCache[questID] = { value = sharing, at = Group.Now() }

    return sharing
end

CN.RegisterScoreAdjuster("GroupShared", function(objective, score)
    if not objective or objective.type ~= CN.objectiveTypes.QUEST then
        return score
    end

    local sharing = Group.SharedWith(objective.id)

    -- WITHDRAWN FIRST, like every other adjuster reason in this addon. A
    -- party member logging out has to take their sentence with them, and the
    -- objectives it was stamped on outlive the group.
    if not sharing or sharing <= 0 then
        CN.ClearAdjusterReason(objective, "groupShared")

        return score
    end

    local bonus = math.min(Group.sharedBonusCap,
        sharing * Group.sharedBonusPerMember)

    CN.AddAdjusterReason(objective, "groupShared",
        sharing == 1 and "one other person here is on this quest"
        or (sharing .. " others here are on this quest"))

    return score * (1 + bonus)
end)

CN.RegisterScoreAdjuster("Group", function(objective, score)
    local situation = Group.Situation()

    -- WHAT IS NO LONGER TRUE IS WITHDRAWN FIRST.
    --
    -- Both sentences below describe the player's situation at the moment of
    -- scoring, and both used to be one-way: once stamped onto a cached
    -- objective they stayed there through every later pass. Every pass now
    -- starts by taking back the ones that do not apply, so the explanation
    -- and the multiplier always agree.
    if situation ~= "dead" then
        CN.ClearAdjusterReason(objective, "groupDead")
    end

    if situation ~= "instanced" then
        CN.ClearAdjusterReason(objective, "groupInstanced")
    end

    -- THE LOCATION SENTENCE IS WITHDRAWN ON THE BRANCH'S OWN TERMS.
    --
    -- Withdrawing it only on LEAVING the instance was the same one-way
    -- stamping this function's own doctrine forbids sixty lines above: the
    -- branch below can decline for reasons other than the doorway -- the
    -- player's map has not resolved yet, the objective turns out to be in
    -- here -- and in every one of those the sentence outlived its multiplier
    -- for the rest of the run.
    --
    -- Computed first, cleared first, applied last. `Outside` is nil-safe on
    -- a nil objective, which is how this function is called by the reason
    -- sweep.
    local outside = Group.Outside(objective)

    if not outside then
        CN.ClearAdjusterReason(objective, "groupOutside")
    end

    if situation == "dead" then
        -- EXCEPT THE BODY.
        --
        -- The corpse is the one thing that IS actionable while dead;
        -- demoting it with everything else would bury the answer under the
        -- list it is supposed to replace.
        if objective and objective.corpse then
            return score
        end

        -- Unguarded on `objective.reasons`, deliberately. The guard used to
        -- be here and not on the instanced branch below, and most providers
        -- build objectives with no `reasons` field -- so for those the
        -- fivefold penalty was applied with nothing on screen saying why.
        -- `AddAdjusterReason` creates the table itself.
        CN.AddAdjusterReason(objective, "groupDead",
            "you are dead" .. CN.DASH .. "this is for after")

        return score * Group.deadPenalty
    end

    if situation == "instanced"
        and objective
        and Group.instancedTypes[objective.type] then

        CN.AddAdjusterReason(objective, "groupInstanced",
            "outside work, and you are in an instance with a group")

        return score * Group.instancedPenalty
    end

    -- BY WHERE IT IS, NOT BY WHAT IT IS. 0.81.0.
    --
    -- The branch above works from a list of TYPES, which is a proxy for
    -- "outdoors" and a bad one in both directions: it demotes the mount that
    -- drops from the boss you are standing next to, and it says nothing
    -- about the world quest three zones away, because QUEST is not on the
    -- list.
    --
    -- The addon already knows where things are. Inside an instance, anything
    -- with a KNOWN map that is not this instance's map needs a loading screen
    -- first, and that is true of every type equally. Anything with no map --
    -- a collection, a currency, the mount off this raid's last boss -- is not
    -- location-bound and is left exactly where it was, which is the case the
    -- type list got wrong.
    if outside then
        CN.AddAdjusterReason(objective, "groupOutside",
            "outside" .. CN.DASH .. "you would have to leave first")

        return score * Group.outsidePenalty
    end

    return score
end)

------------------------------------------------------------
-- SAYING SO
------------------------------------------------------------

-- The line the recommendation prints above everything else when the situation
-- makes the list beside the point. Nil when there is nothing to say, which is
-- most of the time -- an addon that comments on your circumstances constantly
-- is an addon people turn off.
-- WHERE YOUR BODY IS.
--
-- The addon has recognised death since 0.43.0 and ranked everything else down
-- for it -- which is right, and is only half an answer. A dead player's next
-- action is a corpse run, and the addon knew that, said so in a sentence, and
-- then could not point at the one place that mattered.
--
-- `C_DeathInfo.GetCorpseMapPosition` answers with the map position of your
-- own corpse. Guarded like every other client call: a client that will not
-- say returns nothing and the sentence stays a sentence.
function Group.CorpseTarget()
    if not Group.IsGhost() then
        return nil
    end

    if not C_DeathInfo or not C_DeathInfo.GetCorpseMapPosition then
        return nil
    end

    local mapID = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local ok, position = pcall(C_DeathInfo.GetCorpseMapPosition, mapID)

    if not ok or not position then
        return nil
    end

    local x, y

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            x, y = gx, gy
        end
    end

    x = x or position.x
    y = y or position.y

    if not x or not y or (x == 0 and y == 0) then
        return nil
    end

    return { mapID = mapID, x = x, y = y, title = "Your corpse" }
end

------------------------------------------------------------
-- THE ONE THING WORTH DOING WHILE YOU ARE DEAD
------------------------------------------------------------

-- A dead player's next action is not the recommendation list -- it is their
-- body. The addon has said so in a sentence since 0.43.0 while ranking
-- everything else down, and never once pointed at the place.
--
-- Offered as an ordinary candidate, so the arrow, the map pin, `/cn go` and
-- the heads-up display all pick it up without any of them needing to know
-- what a corpse is. Weighted far above anything else, because while you are a
-- ghost nothing else is actionable at all.
CN.RegisterCandidateProvider("Corpse", function()
    local corpse = Group.CorpseTarget()

    if not corpse then
        return {}
    end

    return {
        CN.NewObjective({
            id              = "body",
            type            = CN.objectiveTypes.CORPSE,
            name            = "Run to your body",
            completionValue = 40,
            travelCost      = 0,
            mapID           = corpse.mapID,
            x               = corpse.x,
            y               = corpse.y,
            corpse          = true,
            reasons         = { "you are a ghost; everything else keeps" },
        }),
    }
end, { volatile = true, events = { "PLAYER_DEAD", "PLAYER_ALIVE",
                                   "PLAYER_UNGHOST" } })

function Group.Notice()
    local situation = Group.Situation()

    if situation == "dead" then
        if Group.IsGhost() then
            local corpse = Group.CorpseTarget()

            if corpse then
                return "You are a ghost. Your body is marked" .. CN.DASH .. "the rest of "
                    .. "this keeps."
            end

            return "You are a ghost. Your body first" .. CN.DASH .. "the rest of this "
                .. "keeps."
        end

        return "You are dead. Release or accept a resurrection first."
    end

    local _, kind = Group.Instance()

    local where = (kind == "raid" and "a raid" or "an instance")

    if situation == "instanced" then
        -- "a instance". 0.80.0. Two words, one article, and it had been in
        -- every `/cn situation` since 0.44.0.
        -- THE OTHER PEOPLE, NOT THE GROUP. 0.89.0.
        --
        -- `GetNumGroupMembers` counts the player, so a full party read "with
        -- 5 people" to somebody standing with four others. `Group.Units`
        -- twelve lines up already takes the player out for exactly this
        -- reason; the sentence did not.
        local others = math.max(0, Group.Size() - 1)

        return "You are in " .. where .. " with "
            .. CN.Count(others, "other person", "other people")
            .. "; outside work is ranked down until you leave."
    end

    -- AND ALONE INSIDE IS STILL INSIDE. 0.81.0.
    --
    -- 0.80.0 stopped calling a solo instance run "instanced", which was
    -- right, and left this function with nothing to say about it -- so
    -- `/cn situation` reported "solo", and `/cn plan` refused with the
    -- generic "not while you are in the middle of that". The doorway is a
    -- fact about the player whether or not anybody came with them.
    if Group.InsideInstance() then
        return "You are in " .. where .. " on your own; what is out in the "
            .. "world is ranked down until you leave, and what is in here "
            .. "with you is not."
    end

    return nil
end

-- The situation changes what is worth doing, so the order has to be rebuilt.
-- Cheap: this bumps the ranking generation rather than rebuilding providers,
-- because no candidate's data changed -- only its weighting.
for _, event in ipairs({
    "PLAYER_DEAD", "PLAYER_ALIVE", "PLAYER_UNGHOST",
    "GROUP_ROSTER_UPDATE", "PLAYER_ENTERING_WORLD",
}) do
    CN:RegisterEvent(event, function()
        Group.ForgetShared()

        CN.InvalidateRanking()
    end)
end

-- AND WHEN YOUR OWN QUEST LOG CHANGES.
--
-- Not theirs: the client fires no event for another unit's quest log, which
-- is why the cache above has a life rather than an invalidation. This still
-- earns its place -- accepting a quest yourself is the moment you start
-- asking whether the group is on it. Held across ranking passes otherwise: the cache exists
-- because a forty-person raid is forty client calls per quest, and clearing
-- it on the event that triggers the re-rank would mean it never hit.
for _, event in ipairs({ "QUEST_ACCEPTED", "QUEST_TURNED_IN" }) do
    CN:RegisterEvent(event, function()
        Group.ForgetShared()
    end)
end

CN:RegisterCommand{
    name    = "situation",
    aliases = { "state" },
    order   = 36,
    help    = "What the addon thinks you are in the middle of.",
    handler = function()
        local situation = Group.Situation()

        -- TRANSLATED WHERE IT IS SHOWN, NOT WHERE IT IS DECIDED.
        --
        -- `Situation()` returns an identifier that four call sites compare
        -- against; translating the return value would break every one of
        -- them. The four words are translated in all ten locale files and
        -- were never looked up, because the only place a player reads them is
        -- here.
        Print("Situation: |cffffc74f" .. CN.L[situation] .. "|r")

        local inside, kind = Group.Instance()

        Print("  group: " .. (Group.InGroup()
            and (Group.Size() .. (Group.InRaid() and " (raid)" or " (party)"))
            or CN.L["solo"]))
        Print("  instance: " .. (inside and kind or "no"))
        Print("  alive: " .. CN.YesNo(not Group.IsDead()))

        local notice = Group.Notice()

        if notice then
            Print("|cffffc74f" .. notice .. "|r")
        else
            Print("|cff8a8f96Nothing about your situation is changing the "
                .. "ranking right now.|r")
        end
    end,
}

return Group

'@

$Embedded['Modules\Inventory.lua'] = @'
-- Modules/Inventory.lua
-- Completion Navigator :: what you are already carrying.
--
-- WHAT WAS MISSING.
--
-- `C_Container` appeared nowhere in this addon. Twenty-nine releases of
-- answering "what should I do next?" without ever looking in the player's
-- bags, which is where a surprising amount of the answer already is:
--
--   * The item that STARTS a quest, sitting in a bag since a boss dropped it.
--   * Forty of the fifty things a quest wants, so the answer is "ten more",
--     not "go and do that quest".
--   * A recipe you already own and have not learned.
--   * A mount, a pet or a toy in item form, uncollected and in a bag.
--
-- Every one of those is a next action the addon could not see, and three of
-- them are the cheapest actions available: the walk is zero yards.
--
-- WHAT IT DOES NOT DO.
--
-- It does not use anything, learn anything, sell anything or move anything. It
-- reads. The standing rule in this addon is that it prompts and never acts,
-- and an addon that starts using items out of your bags is an addon that will
-- eventually use the wrong one.

local ADDON_NAME, CN = ...

local Inventory = CN:RegisterModule("Inventory")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- READING THE BAGS
------------------------------------------------------------

-- Backpack plus four bags, and the reagent bag where the client has one.
-- Numbers rather than a constant because the constants have been renamed
-- twice and the numbers have not changed since 2004.
Inventory.bagIDs = { 0, 1, 2, 3, 4, 5 }

-- Bank containers. Read only while the bank is open -- the client refuses
-- otherwise, and a cached answer about a bank you are not standing at is a
-- claim the addon cannot support.
Inventory.bankIDs = { -1, 6, 7, 8, 9, 10, 11, 12 }

-- AND THE WARBAND BANK, WHICH IS A DIFFERENT CLAIM ABOUT A DIFFERENT THING.
--
-- The tabs above 12 are the account-wide bank. The distinction is not
-- cosmetic and it is the entire reason these are two lists rather than one:
-- an item in your character bank is reachable by ONE character, and an item
-- in the Warband bank is reachable by every character on the account. This
-- addon's whole subject is what is reachable, so merging the two would make
-- the store say something false about half its rows.
Inventory.accountBankIDs = { 13, 14, 15, 16, 17 }

function Inventory.IsAvailable()
    return C_Container ~= nil
        and C_Container.GetContainerNumSlots ~= nil
        and C_Container.GetContainerItemInfo ~= nil
end

-- Whether the client considers this slot a quest item. Guarded separately
-- from the rest: GetContainerItemQuestInfo is a different call with its own
-- availability, and a client that lacks it should report "not a quest item"
-- rather than erroring on every slot in the bag.
-- ASKED ONCE, AND THE WHOLE ANSWER KEPT.
--
-- This asked the client whether a slot is a quest item and threw away the
-- rest of what came back -- and then `QuestStarters` asked the identical
-- question again about every slot, for the `questID` and `isActive` this call
-- had already been handed. Measured at retail scale: one `BAG_UPDATE_DELAYED`
-- produced 288 calls to `GetContainerItemQuestInfo` for 144 distinct slots.
-- Exactly half of them were wasted.
local function QuestInfo(bag, slot)
    if not C_Container or not C_Container.GetContainerItemQuestInfo then
        return nil
    end

    local ok, info = pcall(C_Container.GetContainerItemQuestInfo, bag, slot)

    if not ok or type(info) ~= "table" then
        return nil
    end

    return info
end

-- Every item in a set of containers, as { itemID, count, link, quality, bag,
-- slot, questItem }.
--
-- The shape above used to claim `questID` and `isUsable` as well. Neither was
-- ever set on these rows. A comment that describes a richer row than the code
-- builds is worse than no comment: the next reader writes `row.questID` and
-- gets nil forever, with nothing anywhere to say why.
-- CACHED FOR THE BAGS, WHICH IS WHERE IT IS ASKED FOR REPEATEDLY.
--
-- The candidate provider calls QuestStarters, NearlyDone and
-- UncollectedItems, and every one of them rescanned all five bags -- three
-- full walks of a hundred and eighty slots per rebuild, each slot costing two
-- client calls.
--
-- Bags announce their own changes, so the cache lives until they do. Only the
-- default container set is cached: a bank scan is a deliberate one-off and
-- caching it would risk answering about a bank the player has walked away
-- from.
local bagCache = nil

function Inventory.Forget()
    bagCache = nil
end

function Inventory.Scan(containers)
    if not containers and bagCache then
        return bagCache
    end

    local items = {}

    if not Inventory.IsAvailable() then
        return items
    end

    for _, bag in ipairs(containers or Inventory.bagIDs) do
        local gotSlots, slots = pcall(C_Container.GetContainerNumSlots, bag)

        if gotSlots and type(slots) == "number" and slots > 0 then
            for slot = 1, slots do
                local gotInfo, info =
                    pcall(C_Container.GetContainerItemInfo, bag, slot)

                if gotInfo and type(info) == "table" and info.itemID then
                    local questInfo = QuestInfo(bag, slot)

                    table.insert(items, {
                        itemID   = info.itemID,
                        count    = info.stackCount or 1,
                        link     = info.hyperlink,
                        quality  = info.quality,
                        bag      = bag,
                        slot     = slot,
                        -- `hasNoValue` means the vendor will not buy it. It
                        -- has nothing to do with quest items, and reading it
                        -- as one made `questItem` true for every grey and
                        -- every soulbound token in the bag. The real question
                        -- has its own API, which this same file already asks
                        -- correctly forty lines below.
                        questItem = questInfo
                            and (questInfo.isQuestItem or questInfo.questID)
                            and true or false,

                        -- Kept rather than re-asked. See `QuestInfo` above.
                        startsQuest = questInfo and questInfo.questID or nil,
                        questActive = questInfo and questInfo.isActive or false,
                    })
                end
            end
        end
    end

    if not containers then
        bagCache = items
    end

    return items
end

-- How many of an item the player is carrying, across every bag.
function Inventory.Count(itemID)
    if not itemID then
        return 0
    end

    if C_Item and C_Item.GetItemCount then
        local ok, count = pcall(C_Item.GetItemCount, itemID)

        if ok and count then
            return count
        end
    end

    if GetItemCount then
        local ok, count = pcall(GetItemCount, itemID)

        if ok and count then
            return count
        end
    end

    return 0
end

------------------------------------------------------------
-- WHAT IS ACTIONABLE IN THERE
------------------------------------------------------------

-- Items that start a quest. The client will say so directly, which makes this
-- the single most reliable thing in the file -- and the addon has been
-- ignoring it since the first build.
function Inventory.QuestStarters()
    local starters = {}

    if not Inventory.IsAvailable() then
        return starters
    end

    -- Read from what the scan already asked, rather than asking again. See
    -- `QuestInfo` above.
    for _, item in ipairs(Inventory.Scan()) do
        if item.startsQuest and not item.questActive then
            item.questID = item.startsQuest

            table.insert(starters, item)
        end
    end

    return starters
end

-- WHAT AN ITEM *IS*, WHICH NEVER CHANGES.
--
-- "Does this item teach a mount" is a property of the item, not of the
-- player, and the client answers it from a static table. The scan asked it --
-- along with the pet, toy and recipe forms of the same question -- once per
-- SLOT, so a forty-slot stack of the same reagent asked four times forty. One
-- bag update was measured at 576 of these calls for at most a few dozen
-- distinct items.
--
-- Keyed on the item, and never cleared: an item that teaches a mount teaches
-- that mount for the life of the game. What CAN change is whether the player
-- has collected it, and that is asked separately below and not memoised.
local itemKinds = {}

local function KindOf(itemID)
    local held = itemKinds[itemID]

    if held then
        return held
    end

    held = {
        mount   = Blizzard.GetMountFromItem(itemID),
        species = Blizzard.GetPetSpeciesFromItem(itemID),
    }

    -- A COLD JOURNAL'S "NO" IS NOT AN ANSWER.
    --
    -- Both calls return nil until their journal is populated, which at login
    -- happens AFTER the first `BAG_UPDATE_DELAYED` scan. Remembering that
    -- made every caged pet and every mount item in the player's bags
    -- invisible to the addon for the whole session, recoverable only by a
    -- reload -- where before this memo existed each scan re-asked and it
    -- corrected itself within seconds.
    --
    -- So only a positive answer is remembered. An item that is genuinely
    -- neither costs two client calls per scan, which is what it cost before.
    if held.mount or held.species then
        itemKinds[itemID] = held
    end

    return held
end

-- Collectible items sitting in a bag: a mount, a pet, a toy or a recipe the
-- player owns and has not used. Zero yards from where they are standing.
function Inventory.UncollectedItems()
    local found = {}

    for _, item in ipairs(Inventory.Scan()) do
        -- Collection state comes from the journals, which are the authority.
        -- Asking "is this item a mount" and "do I own that mount" are two
        -- different questions and only the second one keeps the addon from
        -- telling somebody to learn what they already have.
        local kind = KindOf(item.itemID)

        local mountID = kind.mount

        local mount = mountID and Blizzard.GetMountByID(mountID)

        -- `isCollected`, NOT `collected`.
        --
        -- `Blizzard.GetMountByID` returns the field as `isCollected`, and
        -- `Modules/Mounts.lua` reads it correctly. Here it was spelled
        -- `collected`, which is always nil, so `not nil` was always true and
        -- EVERY bag item that teaches a mount was emitted as uncollected --
        -- at completionValue 4 with a travel cost of zero, which is close to
        -- the strongest score shape the addon can produce. A mount you
        -- already learned and kept the item for sat near the top of `/cn next`
        -- telling you to learn it, for ever.
        --
        -- The comment three lines above says this check is what "keeps the
        -- addon from telling somebody to learn what they already have".
        if mount and not mount.isCollected then
            item.kind = CN.objectiveTypes.MOUNT
            item.collectibleID = mountID

            table.insert(found, item)
        else
            local speciesID = kind.species

            local pets = CN:GetModule("Pets")

            if speciesID and pets and pets.Store()[speciesID]
                and not pets.Store()[speciesID].collected then

                item.kind = CN.objectiveTypes.PET
                item.collectibleID = speciesID

                table.insert(found, item)
            elseif PlayerHasToy and C_ToyBox and C_ToyBox.GetToyInfo then
                local isToy = select(2, pcall(C_ToyBox.GetToyInfo, item.itemID))

                local owned = select(2, pcall(PlayerHasToy, item.itemID))

                if isToy and not owned then
                    item.kind = CN.objectiveTypes.TOY
                    item.collectibleID = item.itemID

                    table.insert(found, item)
                end
            end
        end
    end

    return found
end

-- HOW CLOSE AN ACCEPTED QUEST IS, IN THINGS RATHER THAN IN PERCENT.
--
-- This file's own header has promised since 0.44.0 that the addon would say
-- "ten more" rather than "go and do that quest". It did not: the header
-- described an intention and the code collected quest STARTERS and nothing
-- else. Writing down what a thing is going to do and then not doing it is
-- worse than not writing it down, because the next reader believes it.
--
-- The client counts these itself, which is the whole reason this is cheap:
-- an objective that requires more than one of something reports how many are
-- done. Returns the objectives that are counting and unfinished, nearest to
-- completion first -- because "one more" is a completely different suggestion
-- from "nineteen more".
function Inventory.QuestProgress(questID)
    local rows = {}

    for _, objective in ipairs(Blizzard.GetCountingObjectives(questID)) do
        if not objective.finished then
            table.insert(rows, objective)
        end
    end

    table.sort(rows, function(a, b)
        return a.remaining < b.remaining
    end)

    return rows
end

-- The same question across every quest in the log: what is nearly done?
Inventory.nearlyDoneRemaining = 3

function Inventory.NearlyDone()
    local rows = {}

    for _, entry in ipairs(Blizzard.GetQuestLogEntries()) do
        for _, objective in ipairs(Inventory.QuestProgress(entry.questID)) do
            if objective.remaining <= Inventory.nearlyDoneRemaining then
                table.insert(rows, {
                    questID   = entry.questID,
                    title     = entry.title,
                    text      = objective.text,
                    done      = objective.done,
                    required  = objective.required,
                    remaining = objective.remaining,
                })
            end
        end
    end

    table.sort(rows, function(a, b)
        if a.remaining ~= b.remaining then
            return a.remaining < b.remaining
        end

        return (a.questID or 0) < (b.questID or 0)
    end)

    return rows
end

-- RECIPES YOU OWN AND HAVE NOT LEARNED.
--
-- The other promise this header made and did not keep. An unlearned recipe in
-- a bag is a profession skill-up sitting in your inventory, and the addon has
-- been recommending vendors that sell recipes while ignoring the ones you
-- already bought.
--
-- Item class 9 is Recipe. The client will say whether the character already
-- knows it -- an already-known recipe is greyed in the tooltip -- but there
-- is no clean API for that state, so this reports what is CARRIED and leaves
-- the "already known" question to the tooltip, which answers it visually.
function Inventory.Recipes()
    local recipes = {}

    if not C_Item or not C_Item.GetItemInfoInstant then
        return recipes
    end

    for _, item in ipairs(Inventory.Scan()) do
        -- ONE MORE PLACEHOLDER. 0.77.0.
        --
        -- `GetItemInfoInstant` returns `itemID, itemType, itemSubType,
        -- itemEquipLoc, icon, classID, subclassID`, and through `pcall` those
        -- land at positions 2 through 8. This was one short, so the variable
        -- called `classID` was actually receiving the ICON -- a file id in
        -- the six figures -- and `classID == 9` was never true on any client.
        --
        -- So this function has returned an empty list since it was written,
        -- and `/cn bags` has never once reported a carried recipe: the entire
        -- feature the thirty-line header above describes, dead in one
        -- underscore.
        local ok, _, _, _, _, _, classID =
            pcall(C_Item.GetItemInfoInstant, item.itemID)

        if ok and classID == 9 then
            item.kind = CN.objectiveTypes.RECIPE

            table.insert(recipes, item)
        end
    end

    return recipes
end

------------------------------------------------------------
-- THE BANK
------------------------------------------------------------

-- `bankIDs` has been declared since 0.44.0 and read by nothing -- a list of
-- container numbers sitting there looking like a feature.
--
-- The client refuses to describe bank containers unless the bank frame is
-- open, so this is only answerable while the player is standing at one. The
-- honest shape is therefore: scan when it is open, remember what was seen,
-- and report the remembered set with the date it was taken -- never
-- presenting a week-old snapshot as current.
-- PER CHARACTER, WHICH IT WAS NOT.
--
-- This was `CN.Account("bank")` -- one table, account-wide, overwritten
-- wholesale by whichever character last opened a bank. So every alt read the
-- main's bank as its own, `/cn bags` reported items that character cannot
-- reach, and opening the bank on the alt destroyed the main's record. The
-- same defect, in the same shape, that migration 7 removed from
-- `questStatus`.
function Inventory.BankStore()
    local character = CN.character

    -- Nil only before the character table exists, which is before any bank
    -- frame can be open. Returning a throwaway means a scan that lands there
    -- is discarded -- correct, and it must not be mistaken for a real store,
    -- so nothing downstream reports on it.
    if not character then
        return {}
    end

    character.bank = character.bank or {}

    return character.bank
end

-- The Warband bank is genuinely account-wide, so this one genuinely is.
function Inventory.WarbandStore()
    return CN.Account("warbandBank")
end

-- WIPING THE STORE ON EVERY SCAN MADE IT HOLD THE LAST TAB LOOKED AT.
--
-- The client does not describe a bank tab until it has been switched to, so a
-- scan sees the visible tab and reports the rest as empty. Rewriting the
-- whole store from that means the Warband bank ends up holding whichever tab
-- the player clicked last -- and moving one item at the bank rewrites both
-- stores from whatever happens to be described at that moment.
--
-- 0.56.0 fixed that with an IN-MEMORY snapshot per container, which fixed it
-- only inside one session: at the next login the snapshot was empty, so the
-- first `BANKFRAME_OPENED` threw away everything on disk except the tab that
-- happened to be visible -- and stamped `scannedAt = now`, so `/cn bags`
-- reported the truncated record as freshly scanned. You had to click through
-- every tab again after every reload.
--
-- So the per-container shape is what is PERSISTED. `store.containers[bag]` is
-- what was in that container the last time the client described it, with its
-- own timestamp; the flat item counts stay beside it for every reader that
-- wants a total. A container the client is not describing keeps what it had,
-- across a reload, across a week.
local function Fill(store, containers, items, answered)
    store.containers = store.containers or {}
    store.seenAt     = store.seenAt or {}

    local now = time()

    -- Only the containers the client described this time.
    for _, bag in ipairs(containers) do
        if answered[bag] then
            store.containers[bag] = {}
            store.seenAt[bag]     = now
        end
    end

    for _, item in ipairs(items) do
        local bag = store.containers[item.bag]

        if bag then
            bag[item.itemID] = (bag[item.itemID] or 0) + (item.count or 1)
        end
    end

    -- The flat totals, rebuilt from the containers. Item ids and counts only:
    -- the bag and slot of something in a bank is not worth a byte on disk,
    -- because it moves and the player is looking at it.
    for key in pairs(store) do
        if key ~= "containers" and key ~= "seenAt" then
            store[key] = nil
        end
    end

    local seen = 0

    for _, bag in pairs(store.containers) do
        for itemID, count in pairs(bag) do
            store[itemID] = (store[itemID] or 0) + count

            seen = seen + 1
        end
    end

    -- The OLDEST container's timestamp, not this instant.
    --
    -- Stamping `now` claimed the whole record was as fresh as the one tab the
    -- client happened to describe. What `/cn bags` should say is how old the
    -- stalest part of the answer is, which is the honest reading of "seen Nh
    -- ago" over a record assembled from several visits.
    local oldest

    for _, at in pairs(store.seenAt) do
        if not oldest or at < oldest then
            oldest = at
        end
    end

    store.scannedAt = oldest or now

    return seen
end

-- How many kinds of item a bank store holds, ignoring its bookkeeping keys.
-- Counting them was a subtraction of one against a store that now carries
-- three, which is the kind of arithmetic that is wrong the moment anything is
-- added beside it.
function Inventory.Kinds(store)
    local kinds = 0

    for key in pairs(store or {}) do
        if key ~= "containers" and key ~= "seenAt" and key ~= "scannedAt" then
            kinds = kinds + 1
        end
    end

    return kinds
end

-- Which containers the client was willing to describe. A container with no
-- slots is one that has not been opened, not one that is empty, and the
-- difference is the whole reason the snapshot above exists.
local function Answered(containers)
    local answered = {}

    if not Inventory.IsAvailable() then
        return answered
    end

    for _, bag in ipairs(containers) do
        local ok, slots = pcall(C_Container.GetContainerNumSlots, bag)

        if ok and type(slots) == "number" and slots > 0 then
            answered[bag] = true
        end
    end

    return answered
end

-- Returns the character-bank count and the Warband count separately, because
-- the two answer different questions and a caller that adds them up is
-- claiming something the addon cannot support.
function Inventory.ScanBank()
    local mine = Inventory.Scan(Inventory.bankIDs)

    local held = Fill(Inventory.BankStore(), Inventory.bankIDs, mine,
        Answered(Inventory.bankIDs))

    local warband = Inventory.Scan(Inventory.accountBankIDs)

    local heldWarband = Fill(Inventory.WarbandStore(),
        Inventory.accountBankIDs, warband, Answered(Inventory.accountBankIDs))

    return held, heldWarband
end

CN:RegisterEvent("BAG_UPDATE_DELAYED", function()
    Inventory.Forget()
end)

CN:RegisterEvent("BANKFRAME_OPENED", function()
    local mine, warband = Inventory.ScanBank()

    DebugPrint("Bank scanned: " .. mine .. " stacks, "
        .. tostring(warband) .. " in the Warband bank.")
end)

-- THE WARBAND TABS ARE NOT ALL VISIBLE WHEN THE FRAME OPENS.
--
-- The client does not describe a bank tab until it has been switched to, so a
-- single scan at `BANKFRAME_OPENED` sees the tab that happened to be selected
-- and reports the rest as empty -- which is worse than not reading them,
-- because an empty row looks like an answer.
--
-- `BAG_UPDATE_DELAYED` fires when any container the client is describing
-- changes, which includes switching tabs, so re-reading on it WHILE THE FRAME
-- IS OPEN fills the picture in as the player moves around the bank. Only
-- while it is open: asking otherwise returns nothing and would blank a real
-- record with a false one.
--
-- Only events this addon can prove exist. `harness.lua` refuses an invented
-- event name, which is how the two speculative ones in the first draft of
-- this block were caught before they shipped as three handlers that never
-- fired.
CN:RegisterEvent("BAG_UPDATE_DELAYED", function()
    if not Inventory.BankIsOpen() then
        return
    end

    Inventory.ScanBank()
end)

-- Only while the frame the client requires is actually open.
function Inventory.BankIsOpen()
    if BankFrame and BankFrame.IsShown then
        local ok, shown = pcall(BankFrame.IsShown, BankFrame)

        return ok and shown and true or false
    end

    return false
end

function Inventory.Summary()
    local items = Inventory.Scan()

    return {
        items    = #items,
        starters = #Inventory.QuestStarters(),
        uncollected = #Inventory.UncollectedItems(),
    }
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- The cheapest actions the addon can offer: the walk is zero.
CN.RegisterCandidateProvider("Inventory", function()
    local candidates = {}

    if not Inventory.IsAvailable() then
        return candidates
    end

    for _, item in ipairs(Inventory.QuestStarters()) do
        if not CN.IsIgnored(CN.objectiveTypes.QUEST, item.questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, item.questID) then

            table.insert(candidates, CN.NewObjective({
                id               = item.questID,
                type             = CN.objectiveTypes.QUEST,
                name             = "Start: " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID)),
                state            = CN.objectiveStates.AVAILABLE,
                completionValue  = 3,
                unlockValue      = 1,

                -- Zero, and it is the honest number: the item is in your bag.
                travelCost       = 0,
                reasons          = {
                    "a quest starter in your bags" .. CN.DASH .. "right-click it",
                },
            }))
        end
    end

    -- NEARLY-FINISHED OBJECTIVES.
    --
    -- "One more Sunscale Feather" is the cheapest quest advice there is, and
    -- the ranking could not distinguish it from a quest not yet started.
    for _, row in ipairs(Inventory.NearlyDone()) do
        if not CN.IsIgnored(CN.objectiveTypes.QUEST, row.questID)
            and not CN.IsDeferred(CN.objectiveTypes.QUEST, row.questID) then

            -- WHERE IT IS, AND WHAT REACHING IT COSTS. 0.86.0.
            --
            -- This row carried `CN.placelessCost`, which is 0 and means
            -- "there is not a journey" -- true of an item sitting in a bag,
            -- and false of a quest objective out in the world. The sibling
            -- row in `Modules/Quests.lua` charges `CN.unknownLocationCost`
            -- for exactly this case, with a note saying why.
            --
            -- Two things went wrong from it. A zero cost is worth eight to
            -- twenty-four points on a scale where finishing something tops
            -- out around eight, so a quest in a zone left an hour ago
            -- outranked everything in front of the player. And zero also
            -- makes `CN.IsPlaceless` true -- while this provider registers
            -- BEFORE Quests, and the aggregate keeps the first row whole. So
            -- this row won the dedup and replaced the Quests provider's real
            -- coordinates with none: `/cn go`, the arrow, the map pin and
            -- the session plan had nothing to point at.
            -- THROUGH THE MODULE THAT OWNS THE ANSWER. 0.87.0.
            --
            -- 0.86.0 asked the raw client call, which is only the FIRST of
            -- four sources `Quests.GetLocation` layers together: the curated
            -- turn-in location, the player's own `/cn where` override, and
            -- the static database. This row wins the dedup and the dedup
            -- never merges coordinates -- so whatever this did not know was
            -- thrown away, including a location the player had recorded by
            -- hand. The same failure the 0.86.0 note above claims to fix,
            -- moved one source along.
            local questModule = CN:GetModule("Quests")

            local mapID, x, y

            if questModule and questModule.GetLocation then
                mapID, x, y = questModule.GetLocation(row.questID)
            else
                mapID, x, y = Blizzard.GetQuestWaypoint(row.questID)
            end

            local travel, costed

            -- A MAP WITH NO POINT ON IT IS STILL A JOURNEY. 0.87.0.
            --
            -- `GetQuestWaypoint` ends `return zoneMap or playerMap, nil, nil`
            -- -- a map and no point is a normal answer -- and `CN.TravelCost`
            -- prices exactly that shape: the routing constant for this map,
            -- the fallback for another one. Guarding on the point skipped
            -- that and fell through to the "no location at all" cost, so a
            -- quest on another continent was charged 8 where the router says
            -- 40. Thirty-two points, on a scale where finishing something is
            -- worth four -- which is the symptom the note above says it
            -- removed.
            if mapID then
                travel, costed = CN.TravelCost(mapID, x, y)
            end

            table.insert(candidates, CN.NewObjective({
                id               = row.questID,
                type             = CN.objectiveTypes.QUEST,
                name             = tostring(row.title or ("Quest " .. row.questID))
                    .. ": " .. row.remaining .. " more",
                state            = CN.objectiveStates.AVAILABLE,
                mapID            = mapID,
                x                = x,
                y                = y,

                -- Worth more the closer it is, which is the entire point.
                completionValue  = 2 + (Inventory.nearlyDoneRemaining - row.remaining),
                travelCost       = travel or CN.unknownLocationCost,
                travelCosted     = costed or nil,
                reasons          = {
                    string.format("%s" .. CN.DASH .. "%d of %d done",
                        tostring(row.text or "objective"), row.done, row.required),
                },
            }))
        end
    end

    for _, item in ipairs(Inventory.UncollectedItems()) do
        if not CN.IsIgnored(item.kind, item.collectibleID)
            and not CN.IsDeferred(item.kind, item.collectibleID) then

            table.insert(candidates, CN.NewObjective({
                id               = item.collectibleID,
                type             = item.kind,
                name             = Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID),
                completionValue  = 4,
                travelCost       = 0,
                reasons          = {
                    "already in your bags, uncollected",
                },
            }))
        end
    end

    return candidates
end, {
    -- THE QUEST EVENTS, because this provider reads the quest log.
    --
    -- `Inventory.NearlyDone` walks `GetQuestLogEntries` and emits a row per
    -- nearly-finished objective -- "Test Quest Alpha: 1 more" -- and the
    -- declaration named only bag events. `InvalidateCandidates` SKIPS a
    -- provider that has an events table and was not named, so handing a quest
    -- in did not touch these rows at all: the quest stayed on the list and in
    -- the route until a bag update or a loading screen happened along.
    --
    -- Reported from play, and the reason the lint below this file exists: a
    -- provider must declare the events of every system it reads, not of the
    -- system it is named after.
    events   = {
        "BAG_UPDATE_DELAYED", "PLAYER_ENTERING_WORLD",
        "QUEST_TURNED_IN", "QUEST_REMOVED", "QUEST_ACCEPTED",
        "QUEST_LOG_UPDATE",

        -- AND WHERE THE PLAYER IS STANDING. 0.86.0. The nearly-done quest
        -- row now costs a real journey, which reads the player's position --
        -- so this provider reads that system too, and the lint below this
        -- file is right to require it to say so.
        "ZONE_CHANGED_NEW_AREA",
    },
    cooldown = 5,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "bags",
    aliases = { "inventory" },
    order   = 28,
    help    = "What is in your bags that you could act on right now.",
    handler = function()
        if not Inventory.IsAvailable() then
            Print("This client does not expose container contents.")
            return
        end

        local summary = Inventory.Summary()

        Print(summary.items .. " items carried.")

        local starters = Inventory.QuestStarters()

        if #starters > 0 then
            Print(#starters .. " of them start a quest:")

            for _, item in ipairs(starters) do
                CN.PrintLine("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID))
                    .. " |cff8a8f96bag " .. item.bag .. ", slot " .. item.slot .. "|r")
            end
        end

        local uncollected = Inventory.UncollectedItems()

        if #uncollected > 0 then
            Print(#uncollected .. " are collectibles you have not learned:")

            for _, item in ipairs(uncollected) do
                CN.PrintLine("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID))
                    .. " |cff8a8f96" .. tostring(item.kind) .. "|r")
            end
        end

        local recipes = Inventory.Recipes()

        if #recipes > 0 then
            Print(CN.Count(#recipes, "recipe") .. " carried:")

            for _, item in ipairs(recipes) do
                CN.PrintLine("  " .. (Blizzard.GetItemName(item.itemID)
                    or ("item " .. item.itemID)))
            end
        end

        local nearly = Inventory.NearlyDone()

        if #nearly > 0 then
            Print("Nearly finished:")

            for index, row in ipairs(nearly) do
                if index > 8 then
                    -- Translated, like the identical phrase nine lines below.
                    -- Hardcoded English two lines from a CN.L lookup of the
                    -- same words is how a locale file ends up complete and
                    -- the addon still English.
                    CN.PrintLine("  |cff8a8f96"
                        .. string.format(CN.L["%d more"], #nearly - 8) .. "|r")
                    break
                end

                CN.PrintLine(string.format("  |cffffc74f" .. CN.L["%d more"]
                    .. "|r %s |cff8a8f96(%d/%d)|r",
                    row.remaining, tostring(row.text or row.title),
                    row.done, row.required))
            end
        end

        -- TWO BANKS, REPORTED AS TWO, because they answer different
        -- questions. What is in this character's bank is reachable by this
        -- character; what is in the Warband bank is reachable by all of them,
        -- and that difference is the whole reason to mention either.
        -- THROUGH `CN.Ago`. 0.77.0.
        --
        -- This was raw hours, rendered as "seen 336h ago" for a bank read a
        -- fortnight before. `CN.Ago` exists for exactly this, its own header
        -- names "97h 12m" as the wrong shape for a stored reading, and the
        -- Scans tab has used it correctly all along.
        local function Age(store)
            return CN.Ago(store and store.scannedAt) or "never"
        end

        local bank = Inventory.BankStore()

        if bank.scannedAt then
            CN.PrintLine(CN.Muted("Your bank: " .. Inventory.Kinds(bank)
                .. " kinds of item, seen " .. Age(bank) .. " " .. CN.DASH
                .. " the client only describes it while you are standing at "
                .. "one."))
        end

        local warband = Inventory.WarbandStore()

        if warband.scannedAt then
            CN.PrintLine(CN.Muted("Warband bank: "
                .. Inventory.Kinds(warband)
                .. " kinds of item, seen " .. Age(warband) .. " "
                .. CN.DASH .. " reachable from every character."))
        end

        if #starters == 0 and #uncollected == 0 and #recipes == 0
            and #nearly == 0 then

            Print("|cff8a8f96Nothing in there needs doing.|r")
        end

        Print("|cff8a8f96Nothing is used, learned or moved on your behalf.|r")
    end,
}

return Inventory
'@

$Embedded['Modules\Waiting.lua'] = @'
-- Modules/Waiting.lua
-- Completion Navigator :: things with a clock on them that the addon could
-- not see.
--
-- Four systems, one file, because each is thirty lines and none of them
-- deserves a module. What they share is the only thing that matters to the
-- ranking: a deadline, and something lost when it passes.
--
--   MAIL          -- expires and is destroyed. Thirty days, and the client
--                    tells you how many are left.
--   KEYSTONE      -- the one in your bag is gone at the weekly reset.
--   KNOWLEDGE     -- profession knowledge is weekly, capped, and permanently
--                    missable: the week you skip does not come back.
--   HEIRLOOMS     -- no deadline, but a collection with its own journal that
--                    nothing in this addon had ever read.
--
-- ON MAIL, SPECIFICALLY.
--
-- This reads the mailbox the client has already told the addon about. It does
-- not open mail, take attachments, or send anything. An addon that empties
-- your mailbox unprompted is one bad edge case away from destroying something
-- irreplaceable, and the standing rule here is that the addon prompts and
-- never acts.

local ADDON_NAME, CN = ...

local Waiting = CN:RegisterModule("Waiting")

local Print      = CN.Print
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- MAIL
------------------------------------------------------------

-- Below this, it is worth interrupting whatever the player is doing. Three
-- days: enough warning to be actionable, short enough that it is not shouting
-- about mail that arrived this morning.
Waiting.mailWarningDays = 3

function Waiting.Mail()
    local items = {}

    if not GetInboxNumItems or not GetInboxHeaderInfo then
        return items, false
    end

    local ok, count = pcall(GetInboxNumItems)

    if not ok or not count or count == 0 then
        return items, true
    end

    for index = 1, count do
        local gotInfo, _, _, sender, subject, money, _, daysLeft, itemCount =
            pcall(GetInboxHeaderInfo, index)

        if gotInfo and daysLeft then
            table.insert(items, {
                sender    = sender,
                subject   = subject,
                money     = money or 0,
                items     = itemCount or 0,
                daysLeft  = daysLeft,
                expiring  = daysLeft <= Waiting.mailWarningDays,
            })
        end
    end

    table.sort(items, function(a, b)
        return (a.daysLeft or 0) < (b.daysLeft or 0)
    end)

    return items, true
end

function Waiting.ExpiringMail()
    local expiring = {}

    for _, mail in ipairs((Waiting.Mail())) do
        if mail.expiring and (mail.items > 0 or mail.money > 0) then
            table.insert(expiring, mail)
        end
    end

    return expiring
end

------------------------------------------------------------
-- KEYSTONE
------------------------------------------------------------

function Waiting.Keystone()
    if not C_MythicPlus then
        return nil
    end

    local level, mapID

    if C_MythicPlus.GetOwnedKeystoneLevel then
        local ok, owned = pcall(C_MythicPlus.GetOwnedKeystoneLevel)

        if ok then
            level = owned
        end
    end

    if not level or level == 0 then
        return nil
    end

    if C_MythicPlus.GetOwnedKeystoneChallengeMapID then
        local ok, owned = pcall(C_MythicPlus.GetOwnedKeystoneChallengeMapID)

        if ok then
            mapID = owned
        end
    end

    local name

    if mapID and C_ChallengeMode and C_ChallengeMode.GetMapUIInfo then
        local ok, mapName = pcall(C_ChallengeMode.GetMapUIInfo, mapID)

        if ok then
            name = mapName
        end
    end

    return {
        level = level,
        mapID = mapID,
        name  = name,
        -- A keystone is replaced at the reset whether or not it is used, so
        -- the reset IS its expiry.
        expiresIn = Blizzard.GetSecondsUntilWeeklyReset(),
    }
end

------------------------------------------------------------
-- PROFESSION KNOWLEDGE
------------------------------------------------------------

-- Weekly knowledge is the most permanently missable thing in modern
-- professions: the cap resets, and a week not collected is gone. The client
-- exposes it as a currency, which is why this reads currencies rather than
-- the profession API -- fewer moving parts, and it works for every expansion
-- that has used the pattern.
--
-- THE ENGLISH WORD WAS THE GATE, AND IT SHOULD NEVER HAVE BEEN. FIXED 0.61.0.
--
-- `knowledgePattern = "[Kk]nowledge"` was matched against the currency's
-- LOCALIZED name. On a German client the currency is "Wissen", on French
-- "Connaissance", on Spanish "Conocimiento" -- so this section, and every
-- candidate it produces, returned exactly zero rows on every non-English
-- client in the world. That is roughly half the player base being silently
-- denied the feature this file's own header calls "the most permanently
-- missable thing in modern professions".
--
-- It is also the second locale bug of this shape the project has found, and
-- the lesson is the same: a localized string is a thing to DISPLAY, never a
-- thing to BRANCH ON.
--
-- What replaces it is a fact the client vouches for in every locale: the
-- currency has a weekly cap and there is room left under it. That is already
-- what the loop below tests, and it was the honest gate all along. A weekly
-- cap on a currency is the game saying "this is gone on Tuesday", which is
-- precisely the question `/cn clock` asks.
--
-- AND THE DEMOTED PATTERN IS GONE TOO. 0.63.0.
--
-- 0.61.0 kept it as an ordering hint, which is the same bug with a smaller
-- blast radius: an English player saw knowledge sorted first and a German
-- player did not. A hint that works in one language is not a hint. See the
-- note at the ordering below for what replaced it.

-- Locale-free reinforcement: the profession knowledge currencies the addon
-- knows by id. An id is the same in every locale. This is a HINT for
-- ordering, not a gate -- a currency missing from this list is still
-- reported, because the weekly cap is what makes it missable and a hard-coded
-- list of ids goes stale on every content patch.
Waiting.knowledgeCurrencies = {
    -- The War Within profession knowledge.
    [2915] = true, [2916] = true, [2917] = true, [2918] = true,
    [2919] = true, [2920] = true, [2921] = true, [2922] = true,
    [2923] = true, [2924] = true, [2925] = true,
}

function Waiting.Knowledge()
    local rows = {}

    local currencies = CN:GetModule("Currencies")

    -- `CharacterStore`, not `Store`. There has never been a Currencies.Store,
    -- so this guard was false on every client and the whole KNOWLEDGE section
    -- of `/cn clock` -- plus its candidates -- has never once produced a row,
    -- in a file whose header calls weekly profession knowledge "the most
    -- permanently missable thing in modern professions".
    --
    -- Nothing caught it because an empty knowledge list and a knowledge list
    -- that cannot be built look identical from outside, and the suite only
    -- asserted that `/cn clock` did not error.
    if not currencies or not currencies.CharacterStore then
        return rows
    end

    for currencyID, record in pairs(currencies.CharacterStore() or {}) do
        -- THE SAME STALENESS RULE THE CURRENCY MODULE APPLIES. 0.64.0.
        --
        -- `Currencies.IsCurrent` exists so a row the client has stopped
        -- listing -- a currency retired at a patch, or any row still carrying
        -- migration 13's "unconfirmed" serial -- is not reported as though it
        -- were live. `Capped` and `WeeklyUnfilled` both apply it; this
        -- re-implemented the filter without it.
        --
        -- So `/cn clock` said "still 1,500 to earn this week" about a
        -- currency `/cn currencies` had correctly dropped, on the same login.
        if currencies.IsCurrent(record)
            and record.maxWeeklyQuantity and record.maxWeeklyQuantity > 0
            and (record.weeklyRemaining or 0) > 0 then

            local info = Blizzard.GetCurrency(currencyID)
            local name = info and info.name

            -- No name is not a reason to drop a capped currency: the row is
            -- still true, and the id can carry it.
            -- THE HINT IS STILL A GATE, JUST A SMALLER ONE. 0.63.0.
            --
            -- 0.61.0 demoted the English word from deciding WHETHER a row
            -- appears to deciding where it SORTS -- which is better and still
            -- wrong for the same reason. A German player whose knowledge
            -- currency is not in the hard-coded id list (any new expansion's
            -- will not be) sees "Wissen" sorted among the ordinary weeklies
            -- while an English player sees it first.
            --
            -- The id list is locale-free and stays. The English match is gone
            -- rather than demoted again: a hint that works in one language is
            -- not a hint, it is a bug with a smaller blast radius. What
            -- replaces it for currencies the list does not know is the fact
            -- the client vouches for -- a weekly cap that is nearly full is
            -- more urgent than one barely touched -- which is true in every
            -- language and is what a player is actually deciding on.
            local knowledge = Waiting.knowledgeCurrencies[currencyID] == true

            table.insert(rows, {
                currencyID = currencyID,
                name       = name or ("Currency " .. tostring(currencyID)),
                knowledge  = knowledge,
                remaining  = record.weeklyRemaining,
                cap        = record.maxWeeklyQuantity,
            })
        end
    end

    -- Knowledge first where it is identifiable, then by id so the order is
    -- stable across sessions and locales.
    table.sort(rows, function(a, b)
        if a.knowledge ~= b.knowledge then
            return a.knowledge
        end

        -- Then by how much of the week's cap is still unclaimed, which is a
        -- fact in every locale. See the note above.
        local left  = (a.cap or 0) > 0 and (a.remaining / a.cap) or 0
        local right = (b.cap or 0) > 0 and (b.remaining / b.cap) or 0

        if left ~= right then
            return left > right
        end

        return a.currencyID < b.currencyID
    end)

    return rows
end

------------------------------------------------------------
-- HEIRLOOMS
------------------------------------------------------------

function Waiting.Heirlooms()
    if not C_Heirloom or not C_Heirloom.GetNumHeirlooms then
        return nil
    end

    local ok, total = pcall(C_Heirloom.GetNumHeirlooms)

    if not ok or not total then
        return nil
    end

    local collected = 0

    for index = 1, total do
        local gotID, itemID = pcall(C_Heirloom.GetHeirloomItemIDFromIndex, index)

        if gotID and itemID then
            local gotOwned, owned = pcall(C_Heirloom.PlayerHasHeirloom, itemID)

            if gotOwned and owned then
                collected = collected + 1
            end
        end
    end

    return { total = total, collected = collected }
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN.RegisterCandidateProvider("Waiting", function()
    local candidates = {}

    -- MAIL. Ranked by what is actually at stake: mail with something in it,
    -- about to be destroyed.
    local expiring = Waiting.ExpiringMail()

    -- AND HIDING OR DEFERRING IT WORKS. 0.82.0.
    --
    -- The two loops below this one both guard on `IsIgnored` and
    -- `IsDeferred`, and this singleton row did not -- the exact defect
    -- `Modules/Orders.lua` and `Modules/Vault.lua` each record for their own
    -- singleton rows, in the two passes that missed this one.
    --
    -- Hiding is enforced INSIDE providers; there is no aggregate filter above
    -- them. So the row scored highest in the file, sat at the top of
    -- `/cn next`, printed "Ignored: 3 mail expiring" when the player hid it,
    -- wrote the entry, and came straight back on the next rebuild -- listed
    -- in `/cn hidden` and first in the list at the same time.
    if #expiring > 0
        and not CN.IsIgnored(CN.objectiveTypes.CURRENCY, "mail")
        and not CN.IsDeferred(CN.objectiveTypes.CURRENCY, "mail") then

        local soonest = expiring[1]

        table.insert(candidates, CN.NewObjective({
            id               = "mail",
            type             = CN.objectiveTypes.CURRENCY,
            name             = #expiring .. " mail expiring",
            completionValue  = 6,
            -- ONE DEADLINE, ONE CURVE. 0.89.0.
            --
            -- This was 3, and `expiresIn` below hands the SAME fact -- mail
            -- is destroyed on a timer -- to the scorer's urgency term. The
            -- flat bonus is worth 3.0 per point and the curve up to 4.0, so
            -- one deadline was charged nine points plus the ramp, through two
            -- shapes tuned independently, only one of which `/cn urgency`
            -- plots. "3 mail expiring" outranked a world quest with nine
            -- minutes left.
            --
            -- `Opportunities` states the settled convention: the flat term is
            -- what you charge only when there is NO deadline to charge.
            -- Fixed in `Opportunities` in 0.63.0 and in `Vault` and
            -- `Instances` in 0.88.0; the sweep reached three files and left
            -- this one, which has the largest flat bonus of the four.
            limitedTimeBonus = 0,
            travelCost       = 3,
            expiresIn        = math.max(0, (soonest.daysLeft or 0) * 86400),
            reasons          = {
                string.format("%s with attachments, the first in %.1f days",
                    CN.Count(#expiring, "message"), soonest.daysLeft or 0),
                "expired mail is destroyed, not returned",
            },
        }))
    end

    -- KEYSTONE. Not gearing: a thing in your bag that is replaced on Tuesday
    -- whether you use it or not.
    local keystone = Waiting.Keystone()

    if keystone and not CN.IsIgnored(CN.objectiveTypes.INSTANCE, "keystone")
        and not CN.IsDeferred(CN.objectiveTypes.INSTANCE, "keystone") then

        table.insert(candidates, CN.NewObjective({
            id               = "keystone",
            type             = CN.objectiveTypes.INSTANCE,
            name             = "Keystone: " .. (keystone.name or "unknown")
                .. " +" .. keystone.level,
            completionValue  = 4,
            -- ONE DEADLINE, ONE CURVE. 0.89.0. See the mail row above.
            limitedTimeBonus = 0,
            travelCost       = 3,
            expiresIn        = keystone.expiresIn,
            reasons          = {
                "your keystone is replaced at the weekly reset whether you "
                    .. "use it or not",
            },
        }))
    end

    -- KNOWLEDGE. The most permanently missable thing in the game that the
    -- addon can see.
    for _, row in ipairs(Waiting.Knowledge()) do
        if not CN.IsIgnored(CN.objectiveTypes.PROFESSION, row.currencyID)
            and not CN.IsDeferred(CN.objectiveTypes.PROFESSION, row.currencyID) then

            table.insert(candidates, CN.NewObjective({
                id               = row.currencyID,
                type             = CN.objectiveTypes.PROFESSION,
                name             = row.name .. ": " .. row.remaining .. " left this week",
                completionValue  = 5,
                -- ONE DEADLINE, ONE CURVE. 0.89.0. See the mail row above.
                limitedTimeBonus = 0,
                travelCost       = CN.placelessCost,
                expiresIn        = Blizzard.GetSecondsUntilWeeklyReset(),
                reasons          = {
                    row.remaining .. " of " .. row.cap .. " still collectable this week",
                    "a week not collected does not come back",
                },
            }))
        end
    end

    return candidates
end, {
    events   = { "MAIL_INBOX_UPDATE", "BAG_UPDATE_DELAYED", "CURRENCY_DISPLAY_UPDATE" },
    volatile = true,
    cooldown = 30,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "clock",
    aliases = { "expiring" },
    order   = 29,
    -- WHAT IT PRINTS, NOT WHAT ANOTHER COMMAND PRINTS. 0.89.0. This named
    -- the vault (`/cn vault`) and lockouts (`/cn instances`) -- both separate
    -- commands in the same essentials list -- and left out mail and heirlooms,
    -- which are the two largest things it does show.
    help    = "Mail about to expire, your keystone, weekly caps, heirlooms.",
    handler = function()
        local said = false

        local mail, readable = Waiting.Mail()

        if not readable then
            Print("|cff8a8f96Mail cannot be read in this client.|r")
        elseif #mail == 0 then
            Print("|cff8a8f96No mail, or the mailbox has not been opened this "
                .. "session" .. CN.DASH .. "the client only hands the addon the inbox once "
                .. "you have looked at it.|r")
        else
            local rows = {}

            for _, entry in ipairs(mail) do
                table.insert(rows, {
                    text  = tostring(entry.subject or "(no subject)"),
                    value = string.format("%.1f days", entry.daysLeft or 0),
                    state = entry.expiring and "BAD" or "MUTED",
                    note  = "from " .. tostring(entry.sender or "?"),
                })
            end

            CN.PrintRows(CN.Count(#mail, "message") .. " in your mailbox:",
                rows, { limit = 5, more = "open your mailbox for the rest" })

            said = true
        end

        local keystone = Waiting.Keystone()

        if keystone then
            Print("Keystone: " .. (keystone.name or "unknown")
                .. " |cffffc74f+" .. keystone.level .. "|r")

            said = true
        end

        local knowledge = Waiting.Knowledge()

        if #knowledge > 0 then
            local rows = {}

            for _, row in ipairs(knowledge) do
                table.insert(rows, {
                    text  = row.name,
                    value = row.remaining .. " of " .. row.cap,
                    state = "ACCENT",
                    note  = "still collectable this week",
                })
            end

            CN.PrintRows(nil, rows)

            said = true
        end

        local heirlooms = Waiting.Heirlooms()

        if heirlooms then
            Print("Heirlooms: " .. heirlooms.collected .. " of " .. heirlooms.total)

            said = true
        end

        if not said then
            Print(CN.L["Nothing is on a clock right now."])
        end
    end,
}

return Waiting
'@

$Embedded['Modules\Sets.lua'] = @'
-- Modules/Sets.lua
-- Completion Navigator :: appearance SETS, the guild, and what you could
-- queue for.
--
-- Three readers, one file, for the same reason Waiting holds four: each is a
-- thin wrapper over a client API the addon had never opened, and none of them
-- carries enough behaviour to justify a module of its own.
--
-- SETS.
--
-- The addon has tracked individual appearances since 0.13.0 and has never
-- known that the game groups them. That matters because collecting is
-- overwhelmingly done by SET -- nobody wants "one more shoulder", they want
-- the tier set finished -- and "3 of 5 pieces" is a genuine denominator the
-- client supplies, which this addon is otherwise very short of.
--
-- GUILD.
--
-- Guild achievements and guild reputation are a whole progression track that
-- was structurally invisible. Modest scope deliberately: what the guild is,
-- and whether the character is close to anything in it.
--
-- QUEUES.
--
-- "You could run this right now" is a different and more useful sentence than
-- "this dungeon exists". The client knows what the character is eligible for;
-- the addon never asked.

local ADDON_NAME, CN = ...

local Sets = CN:RegisterModule("Sets")

local Print = CN.Print

------------------------------------------------------------
-- APPEARANCE SETS
------------------------------------------------------------

function Sets.IsAvailable()
    return C_TransmogSets ~= nil and C_TransmogSets.GetAllSets ~= nil
end

-- Every set the client will describe, with how much of it is collected.
--
-- Bounded: there are several thousand sets across the game's history and each
-- one costs a call to enumerate its pieces. The cap is a real limit on what
-- this answers, so it is stated rather than hidden -- the command says how
-- many were examined.
Sets.scanCap = 400

-- CACHED, BECAUSE THIS IS THE MOST EXPENSIVE THING IN THE ADDON WITHOUT IT.
--
-- Measured at realistic scale -- three thousand sets, which is roughly what
-- the game holds -- the uncached scan cost 4.4 milliseconds per candidate
-- rebuild: more than every other provider in the addon added together, and
-- nearly half of a 16ms frame.
--
-- It was invisible in the first measurement because the fixture had three
-- sets in it. That is the same trap as the map that was always square and the
-- flying speed that was always rejected: a fixture small enough to read is a
-- fixture too small to measure.
--
-- Collections change rarely and announce themselves, so the cache is held
-- until the client says a transmog was collected.
local cache = nil

function Sets.Forget()
    cache = nil
end

function Sets.All(limit)
    limit = limit or Sets.scanCap

    if cache and cache.limit == limit then
        return cache.rows, cache.readable, cache.examined
    end

    local rows = {}

    if not Sets.IsAvailable() then
        return rows, false
    end

    local ok, all = pcall(C_TransmogSets.GetAllSets)

    if not ok or type(all) ~= "table" then
        return rows, false
    end

    local examined = 0

    for _, set in ipairs(all) do
        if examined >= limit then
            break
        end

        if set.setID and set.collected ~= nil then
            examined = examined + 1

            local total, collected = 0, 0

            if C_TransmogSets.GetSetPrimaryAppearances then
                local gotPieces, pieces =
                    pcall(C_TransmogSets.GetSetPrimaryAppearances, set.setID)

                if gotPieces and type(pieces) == "table" then
                    for _, piece in ipairs(pieces) do
                        total = total + 1

                        if piece.collected then
                            collected = collected + 1
                        end
                    end
                end
            end

            table.insert(rows, {
                setID     = set.setID,
                name      = set.name,
                label     = set.label,
                collected = collected,
                total     = total,
                complete  = set.collected and true or false,
            })
        end
    end

    cache = {
        rows     = rows,
        readable = true,
        examined = examined,
        limit    = limit,
    }

    return rows, true, examined
end

-- The sets closest to finished, which is the only ordering anybody wants.
-- A set with nothing collected is not "nearly done"; it is a decision.
function Sets.NearlyComplete(maxMissing)
    maxMissing = maxMissing or 2

    local rows = {}

    for _, set in ipairs((Sets.All())) do
        local missing = set.total - set.collected

        if set.total > 0 and missing > 0 and missing <= maxMissing then
            set.missing = missing

            table.insert(rows, set)
        end
    end

    table.sort(rows, function(a, b)
        if a.missing ~= b.missing then
            return a.missing < b.missing
        end

        return (a.setID or 0) < (b.setID or 0)
    end)

    return rows
end

------------------------------------------------------------
-- THE GUILD
------------------------------------------------------------

function Sets.Guild()
    if not IsInGuild then
        return nil
    end

    local ok, inGuild = pcall(IsInGuild)

    if not ok or not inGuild then
        return nil
    end

    local name, rank, rankIndex

    if GetGuildInfo then
        local gotInfo, guildName, guildRank, guildRankIndex =
            pcall(GetGuildInfo, "player")

        if gotInfo then
            name, rank, rankIndex = guildName, guildRank, guildRankIndex
        end
    end

    return {
        name      = name,
        rank      = rank,
        rankIndex = rankIndex,
    }
end

------------------------------------------------------------
-- WHAT YOU COULD QUEUE FOR
------------------------------------------------------------

-- Deliberately read-only, and deliberately not a queueing button. An addon
-- that puts you in a group finder queue is an addon that will one day do it
-- while you are in a raid.
function Sets.Queues()
    local rows = {}

    if not C_LFGList or not C_LFGList.GetAvailableActivities then
        return rows, false
    end

    local ok, activities = pcall(C_LFGList.GetAvailableActivities)

    if not ok or type(activities) ~= "table" then
        return rows, false
    end

    for _, activityID in ipairs(activities) do
        local gotInfo, info = pcall(C_LFGList.GetActivityInfoTable, activityID)

        if gotInfo and type(info) == "table" and info.fullName then
            table.insert(rows, {
                activityID = activityID,
                name       = info.fullName,
                maxPlayers = info.maxNumPlayers,
            })
        end
    end

    return rows, true
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

CN:RegisterEvent("TRANSMOG_COLLECTION_UPDATED", function()
    Sets.Forget()
end)

CN.RegisterCandidateProvider("Sets", function()
    local candidates = {}

    for _, set in ipairs(Sets.NearlyComplete()) do
        -- TWO ID SPACES, ONE NAMESPACE. FIXED IN 0.61.0.
        --
        -- This provider emitted `id = set.setID` under type APPEARANCE, and
        -- Appearances.lua emits `id = row.categoryID` under the SAME type.
        -- Both are plain integers from unrelated Blizzard tables, and both
        -- start low: transmog set 5 and appearance category 5 are different
        -- things wearing the same (type, id).
        --
        -- The aggregate cache dedups on exactly that pair, so whichever
        -- provider ran second had its row silently DROPPED -- no error, no
        -- warning, just a set that never appeared in the list no matter how
        -- close to complete it was. Worse in the other direction: ignoring
        -- one ignored the other, because `CN.IsIgnored` keys on the same
        -- pair, so a player hiding an appearance slot could not work out why
        -- an unrelated set had vanished with it.
        --
        -- A prefixed string key is unambiguous forever and costs one
        -- concatenation per row, at a cooldown of sixty seconds.
        local key = "set:" .. tostring(set.setID)

        if not CN.IsIgnored(CN.objectiveTypes.APPEARANCE, key)
            and not CN.IsDeferred(CN.objectiveTypes.APPEARANCE, key) then

            table.insert(candidates, CN.NewObjective({
                id               = key,

                -- The raw id, for anything that needs to ask the client
                -- about the set rather than about this row.
                setID            = set.setID,
                type             = CN.objectiveTypes.APPEARANCE,
                name             = tostring(set.name or ("Set " .. set.setID))
                    .. ": " .. CN.Count(set.missing, "piece") .. " left",

                -- A REAL denominator, which this addon is normally short of.
                completionValue  = 3 + (3 - math.min(3, set.missing)),
                travelCost       = CN.placelessCost,
                reasons          = {
                    set.collected .. " of " .. set.total .. " pieces collected",
                },
            }))
        end
    end

    return candidates
end, {
    events   = { "TRANSMOG_COLLECTION_UPDATED" },
    cooldown = 60,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "sets",
    aliases = { "guild", "queues" },
    order   = 31,
    help    = "Appearance sets nearly finished, your guild, and what you "
        .. "could queue for.",
    handler = function()
        local rows, readable, examined = Sets.All()

        if not readable then
            Print("|cff8a8f96This client does not expose appearance sets.|r")
        else
            local nearly = Sets.NearlyComplete()

            -- `CN.Count` EXISTS FOR THIS. 0.82.0. Two headline lines in
            -- this command said "1 sets" and "1 activities", in a file that
            -- already uses the helper twenty lines up.
            Print(CN.Count(#rows, "set") .. " read"
                .. (examined and examined >= Sets.scanCap
                    and (" |cff8a8f96(capped at " .. Sets.scanCap
                        .. "; there are more)|r") or "") .. ".")

            if #nearly == 0 then
                Print("|cff8a8f96None of them is within two pieces.|r")
            else
                Print("Nearly finished:")

                for index, set in ipairs(nearly) do
                    if index > 10 then
                        CN.PrintLine("  |cff8a8f96... and " .. (#nearly - 10) .. " more|r")
                        break
                    end

                    CN.PrintLine(string.format("  |cffffc74f%d left|r %s |cff8a8f96(%d/%d)|r",
                        set.missing, tostring(set.name or set.setID),
                        set.collected, set.total))
                end
            end
        end

        local guild = Sets.Guild()

        if guild then
            Print("Guild: |cffffc74f" .. tostring(guild.name or "?") .. "|r"
                .. (guild.rank and (" |cff8a8f96" .. guild.rank .. "|r") or ""))
        end

        local queues, queueReadable = Sets.Queues()

        if queueReadable and #queues > 0 then
            Print(CN.Count(#queues, "activity", "activities")
                .. " you are eligible to queue for.")
            Print("|cff8a8f96The addon reads that list. It does not queue you "
                .. "for anything.|r")
        end
    end,
}

return Sets
'@

$Embedded['Modules\Travel.lua'] = @'
-- Modules/Travel.lua
-- Completion Navigator :: how long it actually takes to get there.
--
-- WHAT WAS WRONG.
--
-- Every travel figure in this addon was a straight line. Within a zone that is
-- very nearly right -- you run in roughly the direction you are going. Between
-- zones it is not even approximately right, and the addon papered over that
-- with a flat penalty: anything outside your current zone cost the same
-- whether it was over the next ridge or on the far side of the continent.
--
-- That flat number is why `/cn plan 30` could put something in your half hour
-- that is a flight and a ride away, and why `/cn zones` ranked a zone with a
-- flight master in it the same as one without.
--
-- WHAT THIS DOES.
--
-- Costs a journey the way you would actually make it: run to the nearest
-- flight point you know, fly, run from the arrival point to the target -- and
-- compares that against simply running the whole way, taking whichever is
-- quicker. Flight points you have not discovered do not exist as far as this
-- is concerned, because they do not exist for you either.
--
-- WHAT IT REFUSES TO DO.
--
-- Guess. Flight speed is MEASURED, from your own flights, exactly the way
-- running speed already is -- the client will not tell us and the number
-- differs between expansions. Until it has been measured, estimates are
-- returned with confidence false and every caller says so out loud rather
-- than printing a number that looks like a fact.
--
-- Two continents with no flight between them return nil, not a large number.
-- "I do not know" is an answer; a fabricated four hours is not.

local ADDON_NAME, CN = ...

local Travel = CN:RegisterModule("Travel")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- POINTS IN THE WORLD
------------------------------------------------------------

-- Map coordinates are normalized per map, so two points on different maps
-- cannot be compared at all in map space. World coordinates can: they are
-- yards, they are continuous across a continent, and the client will convert
-- into them. This is what makes a cross-zone distance possible where the old
-- code simply gave up and charged a flat penalty.
-- MEMOISED, and safely so: a map coordinate's world position is a property of
-- the world, not of the player, so it cannot go stale. The conversion is a
-- client call with a table allocation on either side of it, and costing a
-- journey needs four of them -- which the quest provider then does once per
-- candidate.
--
-- Bounded rather than unbounded: a long session touches a lot of points, and a
-- cache with no ceiling is a memory leak with good intentions.
local worldPoints = {}
local worldPointCount = 0

Travel.worldPointCap = 2048

function Travel.ForgetWorldPoints()
    worldPoints = {}
    worldPointCount = 0
end

function Travel.WorldPoint(mapID, x, y)
    if not (mapID and x and y) then
        return nil
    end

    -- Rounded to about a yard on any map. Finer than that is precision the
    -- callers do not use and cache entries nothing will ever hit again.
    local key = mapID .. ":" .. math.floor(x * 10000) .. ":" .. math.floor(y * 10000)

    local cached = worldPoints[key]

    if cached ~= nil then
        if cached == false then
            return nil
        end

        return cached
    end

    if not C_Map or not C_Map.GetWorldPosFromMapPos or not CreateVector2D then
        return nil
    end

    local ok, continentID, position =
        pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

    if not ok or not position then
        -- NOT cached as a miss: during a loading screen the client refuses
        -- every conversion, and remembering that would poison the cache for
        -- the rest of the session.
        return nil
    end

    local wx, wy

    if position.GetXY then
        local gotXY, gx, gy = pcall(position.GetXY, position)

        if gotXY then
            wx, wy = gx, gy
        end
    end

    wx = wx or position.x
    wy = wy or position.y

    if not wx or not wy then
        return nil
    end

    local point = { continent = continentID, x = wx, y = wy }

    if worldPointCount >= Travel.worldPointCap then
        Travel.ForgetWorldPoints()
    end

    worldPoints[key] = point
    worldPointCount  = worldPointCount + 1

    return point
end

-- Yards between two world points, or nil when they are not on the same
-- continent -- in which case the straight-line number would be meaningless
-- rather than merely imprecise.
function Travel.YardsBetweenPoints(from, to)
    if not from or not to then
        return nil
    end

    if from.continent and to.continent and from.continent ~= to.continent then
        return nil
    end

    local dx = to.x - from.x
    local dy = to.y - from.y

    return math.sqrt((dx * dx) + (dy * dy))
end

-- The headline: distance between two points that may be on different maps.
function Travel.YardsBetween(fromMapID, fromX, fromY, toMapID, toX, toY)
    return Travel.YardsBetweenPoints(
        Travel.WorldPoint(fromMapID, fromX, fromY),
        Travel.WorldPoint(toMapID, toX, toY))
end

------------------------------------------------------------
-- FLIGHT POINTS
------------------------------------------------------------

-- The continent a map belongs to. Taxi nodes are listed per continent, and a
-- zone map will not answer for them.
function Travel.ContinentFor(mapID)
    local guard = 0

    while mapID and guard < 12 do
        local info = Blizzard.GetMapInfo(mapID)

        if not info then
            return nil
        end

        -- Enum.UIMapType.Continent == 2.
        if info.mapType == 2 then
            return mapID
        end

        mapID = info.parentMapID

        guard = guard + 1
    end

    return nil
end

-- Cached per continent. The set of flight points you know changes only when
-- you discover one, which is rare and which the client announces.
local nodeCache = {}

-- CLAMPED BEFORE PACKING.
--
-- The packing is exact for coordinates in [0, 1), which is where the client's
-- own APIs stay -- but a third-party data provider is not the client, and at
-- exactly 1.0 the coordinate term is a full 1,000,000 and collides with the
-- next map's origin. A negative coordinate floors downward and collides with
-- the previous map's far corner.
--
-- FILE SCOPE, because it was declared inside `CostFor` ABOVE the cache
-- lookup -- so every call allocated a closure, including the overwhelming
-- majority that were about to return a cached answer.
local function Packed(value)
    local scaled = math.floor((value or 0) * 1000)

    if scaled < 0 then
        return 0
    end

    if scaled > 999 then
        return 999
    end

    return scaled
end

-- Scratch buffers for the journey search below, reused across calls. See the
-- comment at their first use.
local scratchOrigin, scratchArrival, scratchOrder = {}, {}, {}

local scratchSort

local function OrderByOrigin(a, b)
    if scratchSort[a] == scratchSort[b] then
        return a < b
    end

    return scratchSort[a] < scratchSort[b]
end

-- The flight network, and the shortest way through it. See THE NETWORK below.
local neighbourCache = {}
local pathCache      = {}

function Travel.ForgetNodes()
    nodeCache      = {}
    neighbourCache = {}
    pathCache      = {}

    -- Every costed journey was costed through this network, so it goes too.
    if Travel.ForgetCosts then
        Travel.ForgetCosts()
    end
end

-- Only nodes you can actually use. An undiscovered flight master is not a
-- shortcut, and costing a journey through one would produce a plan you cannot
-- follow -- which is worse than a pessimistic plan you can.
local function IsUsable(node)
    if not node then
        return false
    end

    if not Enum or not Enum.FlightPathState then
        -- Unknown enum: trust the client's list rather than dropping
        -- everything, and let the distance maths decide.
        return true
    end

    return node.state == Enum.FlightPathState.Current
        or node.state == Enum.FlightPathState.Reachable
end

function Travel.KnownNodes(mapID)
    local continent = Travel.ContinentFor(mapID)

    if not continent then
        return {}, nil
    end

    if nodeCache[continent] then
        return nodeCache[continent], continent
    end

    if not C_TaxiMap or not C_TaxiMap.GetAllTaxiNodes then
        return {}, continent
    end

    local ok, nodes = pcall(C_TaxiMap.GetAllTaxiNodes, continent)

    if not ok or type(nodes) ~= "table" then
        return {}, continent
    end

    local usable = {}

    for _, node in ipairs(nodes) do
        if IsUsable(node) and node.position then
            local nx, ny

            if node.position.GetXY then
                local gotXY, gx, gy = pcall(node.position.GetXY, node.position)

                if gotXY then
                    nx, ny = gx, gy
                end
            end

            nx = nx or node.position.x
            ny = ny or node.position.y

            local point = nx and Travel.WorldPoint(continent, nx, ny)

            if point then
                table.insert(usable, {
                    name  = node.name,
                    id    = node.nodeID,
                    point = point,
                })
            end
        end
    end

    -- AN EMPTY LIST IS NOT AN ANSWER, SO IT IS NOT REMEMBERED.
    --
    -- `C_TaxiMap.GetAllTaxiNodes` answers usefully only while the client has
    -- the taxi map's data to hand, and every node here needs
    -- `Travel.WorldPoint`, which refuses during a loading screen. The one
    -- event that clears this cache -- PLAYER_ENTERING_WORLD -- is a loading
    -- screen, so the very next query was the one most likely to get nothing.
    --
    -- Caching that nothing meant every flight-based estimate on the continent
    -- degraded to "run there" for the rest of the session. `Travel.WorldPoint`
    -- and `Navigation.MapScale` both already refuse to remember a miss, with
    -- comments saying why; this derived list did it anyway.
    if #usable > 0 then
        nodeCache[continent] = usable
    end

    return usable, continent
end

------------------------------------------------------------
-- THE NETWORK
------------------------------------------------------------

-- A FLIGHT IS NOT A STRAIGHT LINE, AND SOME JOURNEYS NEED TWO HOPS.
--
-- Until now the flight leg of a route was the straight-line distance between
-- the two flight points, which is the one distance a taxi never travels. The
-- network is a graph: the bird hops from master to master, and a pair at
-- opposite ends of a continent is reached by going through the ones in
-- between. Measuring the hypotenuse understated every long flight -- always
-- in the same direction, so the addon systematically recommended distant
-- objectives over near ones.
--
-- It also let the addon cost a pairing that does not connect at all. An
-- island node with no route to the mainland was quoted as a short flight
-- because the two points happen to be close together on the map.
--
-- The client does not publish the edge list -- `GetAllTaxiNodes` gives
-- positions and reachability, not who connects to whom -- so the edges are
-- inferred: a flight master connects to the ones near it, plus its nearest
-- few regardless of distance so that a sparse region is not cut off from the
-- rest of the continent. That is a model, and it is marked as one: a
-- multi-hop estimate is never reported as confident.
--
-- What it is not is a guess in the direction of optimism. Every path length
-- this produces is at least the straight line it replaces, so the estimate
-- moved from "certainly too short" to "approximately right".
Travel.hopYards = 4000

-- Plus the nearest few whatever the distance, so that a lone outpost still
-- joins the graph rather than becoming unreachable and silently dropping out
-- of every route.
Travel.minimumNeighbours = 4

-- No real continent has a flight chain anywhere near this long. It exists so
-- that a malformed graph cannot spin a loop.
Travel.maximumHops = 32

local function Neighbours(continent, nodes)
    if neighbourCache[continent] then
        return neighbourCache[continent]
    end

    -- BUILT WITHOUT SORTING EVERYTHING FIRST.
    --
    -- The original built, for every node, a table of ALL n-1 edges -- one
    -- freshly allocated row each -- sorted the whole thing, and then threw
    -- away everything past the threshold. On a sixty-node continent that is
    -- three and a half thousand allocations and sixty sorts to keep a few
    -- hundred edges, and it ran again after every loading screen. Measured at
    -- 4.9 ms, which was most of the cold graph cost.
    --
    -- What is actually needed is two things: every edge within `hopYards`,
    -- and the nearest `minimumNeighbours` whatever the distance. The first is
    -- one pass with no sort at all. The second is a fixed four-slot insertion,
    -- which is a sort of four elements rather than of fifty-nine.
    --
    -- `Spans` is gone with it: since the flight leg became a path rather than
    -- a straight line it was read exactly once per continent, here, and then
    -- retained for the session -- sixty tables and three and a half thousand
    -- numbers kept for nothing.
    local count = #nodes
    local out   = {}

    -- The shortest edge leaving each node, which is the cheapest any flight
    -- from it can possibly be. Used to tighten the search's pruning bound.
    local minOutgoing = {}

    local keep = Travel.minimumNeighbours

    for i = 1, count do
        local list = {}
        local held = {}

        -- The `keep` nearest, as a small insertion-sorted array.
        local nearIndex, nearYards = {}, {}
        local nearCount = 0

        local shortest

        for j = 1, count do
            if i ~= j then
                local yards = Travel.YardsBetweenPoints(
                    nodes[i].point, nodes[j].point)

                if yards then
                    if not shortest or yards < shortest then
                        shortest = yards
                    end

                    if yards <= Travel.hopYards then
                        held[j] = true

                        table.insert(list, { index = j, yards = yards })
                    else
                        -- Not close enough to connect on distance, so it is a
                        -- candidate for the nearest-few rule instead.
                        local slot = nearCount + 1

                        while slot > 1 and nearYards[slot - 1] > yards do
                            nearYards[slot] = nearYards[slot - 1]
                            nearIndex[slot] = nearIndex[slot - 1]
                            slot = slot - 1
                        end

                        if slot <= keep then
                            nearYards[slot] = yards
                            nearIndex[slot] = j

                            if nearCount < keep then
                                nearCount = nearCount + 1
                            end
                        end
                    end
                end
            end
        end

        -- Top up to `keep` edges from the nearest-few list, in order, without
        -- duplicating anything the distance rule already took.
        local taken = #list

        for slot = 1, nearCount do
            if taken >= keep then
                break
            end

            local j = nearIndex[slot]

            if j and not held[j] then
                held[j] = true
                taken   = taken + 1

                table.insert(list, { index = j, yards = nearYards[slot] })
            end
        end

        minOutgoing[i] = shortest
        out[i]         = list
        out[i].held    = held
    end

    -- AND THE GRAPH IS UNDIRECTED, BECAUSE FLIGHT PATHS ARE.
    --
    -- Built one node at a time, `minimumNeighbours` is a rule about who each
    -- node reaches OUT to, and that is not the same as who reaches it. A lone
    -- outpost picks its four nearest and every one of them is close enough to
    -- fill its own four from the crowd nearby -- so the outpost had a way out
    -- and no way in, and Dijkstra from anywhere on the mainland simply never
    -- reached it. It vanished from every route, silently, which is the exact
    -- failure `minimumNeighbours` was written to prevent.
    -- A membership set rather than a linear scan of the target's list: the
    -- scan made this O(V*E), which on a dense graph is cubic in nodes.
    for i = 1, count do
        for _, edge in ipairs(out[i]) do
            local back = out[edge.index]

            if not back.held[i] then
                back.held[i] = true

                table.insert(back, { index = i, yards = edge.yards })
            end
        end
    end

    out.minOutgoing = minOutgoing

    neighbourCache[continent] = out

    return out
end

-- Dijkstra from one flight point to every other, cached per origin.
--
-- Per origin rather than all-pairs: the search below prunes most origins
-- before it ever asks, and paying for a full Floyd-Warshall on sixty nodes at
-- the first estimate of a session would be a visible hitch for answers that
-- are mostly never needed. What is computed is kept, and thrown away with the
-- node list it was derived from.
local function ShortestFrom(continent, nodes, source)
    local cache = pathCache[continent]

    if not cache then
        cache = {}
        pathCache[continent] = cache
    end

    if cache[source] then
        return cache[source]
    end

    local neighbours = Neighbours(continent, nodes)
    local count      = #nodes
    local dist, prev, settled = {}, {}, {}

    dist[source] = 0

    for _ = 1, count do
        local pick, pickDist

        for index = 1, count do
            if not settled[index] and dist[index]
                and (not pickDist or dist[index] < pickDist) then

                pick, pickDist = index, dist[index]
            end
        end

        if not pick then
            -- Everything reachable has been settled. What is left is a
            -- separate component, and stays unreachable -- which is the
            -- honest answer for it.
            break
        end

        settled[pick] = true

        for _, edge in ipairs(neighbours[pick] or {}) do
            local through = pickDist + edge.yards

            if not dist[edge.index] or through < dist[edge.index] then
                dist[edge.index] = through
                prev[edge.index] = pick
            end
        end
    end

    local result = { dist = dist, prev = prev }

    cache[source] = result

    return result
end

-- The hops themselves, so `/cn travel` can print the chain rather than a
-- single number the player cannot check.
function Travel.LegsBetween(nodes, path, source, target)
    if not path or not path.dist or not path.dist[target] then
        return nil
    end

    local chain, at, guard = {}, target, 0

    while at and guard <= Travel.maximumHops do
        table.insert(chain, 1, at)

        if at == source then
            break
        end

        at    = path.prev[at]
        guard = guard + 1
    end

    if chain[1] ~= source then
        return nil
    end

    local legs = {}

    for step = 1, #chain - 1 do
        local a, b = chain[step], chain[step + 1]

        table.insert(legs, {
            from  = nodes[a] and nodes[a].name,
            to    = nodes[b] and nodes[b].name,
            yards = (path.dist[b] or 0) - (path.dist[a] or 0),
        })
    end

    return legs
end

-- Nearest known flight point to a world point, and how far it is.
function Travel.NearestNode(point, nodes)
    if not point then
        return nil, nil
    end

    local best, bestYards

    for _, node in ipairs(nodes or {}) do
        local yards = Travel.YardsBetweenPoints(point, node.point)

        if yards and (not bestYards or yards < bestYards) then
            best, bestYards = node, yards
        end
    end

    return best, bestYards
end

------------------------------------------------------------
-- HOW FAST YOU FLY
------------------------------------------------------------

-- MEASURED, not assumed. Flight-path speed differs by expansion and by
-- whether the route is a modern one, the client does not expose it, and
-- Session already discards taxi movement when learning running speed -- so
-- nothing in the addon knew this number at all.
--
-- Seeded with a figure that is in the right area so the feature does
-- something on day one, and flagged as unmeasured until the player has
-- actually flown, exactly as running speed is.
Travel.seededFlightSpeed = 25

-- The part of a flight that is not flying: talking to the flight master,
-- taking off, and landing. A constant rather than a measurement because it is
-- dominated by a fixed animation, and because the alternative -- timing the
-- gossip window -- would be measuring the player's reading speed.
Travel.flightOverheadSeconds = 20

-- Casting a teleport and loading the destination. A constant for the same
-- reason as the others: it is an animation and a loading screen, not
-- something worth instrumenting.
Travel.castSeconds = 15

Travel.speedSampleCap = 20

local function Samples()
    local account = CN.Account("flight")

    account.samples = account.samples or {}

    return account.samples
end

local flight = {
    point = nil,
    at    = nil,
    yards = 0,
    seconds = 0,
}

local function Median(values)
    if not values or #values == 0 then
        return nil
    end

    local sorted = {}

    for _, value in ipairs(values) do
        table.insert(sorted, value)
    end

    table.sort(sorted)

    local middle = math.floor(#sorted / 2)

    if #sorted % 2 == 1 then
        return sorted[middle + 1]
    end

    return (sorted[middle] + sorted[middle + 1]) / 2
end

-- Returns yards per second and whether it was measured.
function Travel.FlightSpeed()
    local measured = Median(Samples())

    if measured and measured > 0 then
        return measured, true
    end

    return Travel.seededFlightSpeed, false
end

function Travel.FlightSampleCount()
    return #Samples()
end

-- Called on a timer while the player is on a taxi. Accumulates distance and
-- time for the whole flight and records ONE sample when it ends, rather than
-- one per tick: a flight is a single observation of a constant speed, and
-- treating each tick as independent would let a long flight drown out every
-- other measurement.
function Travel.ObserveFlight()
    local onTaxi = UnitOnTaxi and UnitOnTaxi("player")

    local now = (GetTime and GetTime()) or 0

    if not onTaxi then
        if flight.at and flight.seconds > 10 and flight.yards > 100 then
            local speed = flight.yards / flight.seconds

            -- Sanity bounds. A loading screen or a zone change mid-flight can
            -- produce a figure no aircraft in this game achieves, and one bad
            -- sample in a median of twenty is survivable but pointless.
            if speed > 5 and speed < 200 then
                local samples = Samples()

                table.insert(samples, speed)

                while #samples > Travel.speedSampleCap do
                    table.remove(samples, 1)
                end

                DebugPrint(string.format(
                    "Flight speed sampled: %.1f yards/second over %.0f yards.",
                    speed, flight.yards))
            end
        end

        flight.point, flight.at = nil, nil
        flight.yards, flight.seconds = 0, 0

        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    if point and flight.point and flight.at then
        local yards = Travel.YardsBetweenPoints(flight.point, point)

        local elapsed = now - flight.at

        -- Crossing a continent boundary mid-flight yields nil, which is not a
        -- reason to throw the flight away -- just this interval.
        if yards and elapsed > 0 and elapsed < 10 then
            flight.yards   = flight.yards + yards
            flight.seconds = flight.seconds + elapsed
        end
    end

    flight.point, flight.at = point, now

    return true
end

------------------------------------------------------------
-- WHICH FLIGHTS ACTUALLY CONNECT
------------------------------------------------------------

-- THE ASSUMPTION THIS REPLACES.
--
-- The costing has assumed since 0.42.0 that any flight point on a continent
-- can reach any other. Mostly true, and wrong often enough to matter: routes
-- go through hubs, some connect only one way, and a few zones are served by a
-- single node that reaches almost nothing.
--
-- There is no API that answers "does A connect to B". There is, however, the
-- player, who takes flights -- and a flight taken is proof that its two ends
-- connect. So: watch, remember, and prefer a pair that is known to work over
-- one that is merely plausible.
--
-- Nothing is ever ruled OUT by this. A pair never observed is not a pair that
-- does not connect; it is a pair nobody has flown yet, and treating those as
-- impossible would make the model worse than the assumption it replaces.
local function Routes()
    return CN.Account("flightRoutes")
end

Travel.Routes = Routes

-- NUMERIC, NOT A STRING.
--
-- `IsKnownRoute` is asked once per surviving pair inside the search, which on
-- a real continent is a thousand times per estimate -- so this built a
-- thousand strings, each of them two coercions and a concatenation, to look
-- up a table with a few dozen rows in it.
--
-- Node ids are integers well under the multiplier, so packing them into one
-- number is exact and costs nothing. The stored keys change shape, so
-- migration 8 rewrites them; `Travel.UnpackRouteKey` reads one back.
Travel.routeKeyStride = 1000000

local function RouteKey(fromID, toID)
    if not fromID or not toID then
        return nil
    end

    -- Undirected: a flight path that carries you one way is evidence the two
    -- points are on the same network, which is what the costing needs.
    if fromID > toID then
        fromID, toID = toID, fromID
    end

    return (fromID * Travel.routeKeyStride) + toID
end

Travel.RouteKey = RouteKey

-- The two node ids back out of a packed key, for anything that has to read
-- the store rather than write it -- `/cn dbsize`, a future export, and the
-- migration's own verification. Returns nil for anything that is not one of
-- our keys rather than inventing a pair out of arithmetic.
function Travel.UnpackRouteKey(key)
    if type(key) ~= "number" or key < 0 or key ~= math.floor(key) then
        return nil
    end

    local stride = Travel.routeKeyStride

    local fromID = math.floor(key / stride)
    local toID   = key - (fromID * stride)

    if fromID <= 0 or toID <= 0 then
        return nil
    end

    return fromID, toID
end

function Travel.NoteRoute(fromID, toID)
    local key = RouteKey(fromID, toID)

    if not key then
        return false
    end

    local routes = Routes()

    routes[key] = (routes[key] or 0) + 1

    return true
end

function Travel.IsKnownRoute(fromID, toID)
    local key = RouteKey(fromID, toID)

    return key ~= nil and (Routes()[key] or 0) > 0
end

-- How much a known pair is preferred. A multiplier on the estimate rather
-- than a hard filter, because an unobserved pair is unproven, not impossible
-- -- and a small preference is enough to break a tie between two routes of
-- similar length.
Travel.knownRouteBonus = 0.9

-- The flight the player is currently on, so its endpoints can be recorded
-- when it ends. Which node they left from is known at the moment they board:
-- it is the nearest one to where they were standing.
local boarding = nil

function Travel.NoteBoarding()
    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    local node = point and Travel.NearestNode(point, Travel.KnownNodes(mapID))

    boarding = node and node.id or nil

    return boarding
end

function Travel.NoteLanding()
    if not boarding then
        return false
    end

    local mapID, x, y = CN.GetPlayerPosition()

    local point = mapID and Travel.WorldPoint(mapID, x, y)

    local node = point and Travel.NearestNode(point, Travel.KnownNodes(mapID))

    local landed = node and node.id

    local recorded = false

    if landed and landed ~= boarding then
        recorded = Travel.NoteRoute(boarding, landed)

        DebugPrint("Flight recorded: " .. boarding .. " to " .. landed .. ".")
    end

    boarding = nil

    return recorded
end

------------------------------------------------------------
-- FLYING YOURSELF
------------------------------------------------------------

-- Seconds spent mounting up and gaining height before any distance is
-- covered. A constant, like the flight master's overhead, and for the same
-- reason: it is an animation, not a measurement.
Travel.takeoffSeconds = 6

-- Whether the player can fly to the destination.
--
-- Two separate questions, and both have to be yes: does this character fly at
-- all, and does the game allow it where they are going. `IsFlyableArea`
-- answers for where the player IS, which is the honest approximation
-- available -- the client will not answer for a zone the player is not in, so
-- a cross-zone claim is checked at the near end and re-checked when they get
-- there.
-- Which zones the player has actually been able to fly in.
--
-- `IsFlyableArea` answers for where the player IS STANDING, and there is no
-- API that answers for anywhere else -- so a cross-zone claim was being made
-- from the near end and could be wrong at the far end. Remembering the answer
-- per zone, as it is observed, turns that guess into evidence: a zone the
-- player has flown in is flyable, and one they have been in and could not fly
-- in is not.
local function FlightMemory()
    return CN.Account("flyableZones")
end

Travel.FlightMemory = FlightMemory

-- A "NO" HAS A SHELF LIFE. A "YES" DOES NOT.
--
-- Whether a zone allows flying is not a stable fact in the direction that
-- matters: flight is disabled before the campaign or Pathfinder unlock and
-- enabled after, and disabled inside some quest phases. The store was
-- permanent and account-wide, and `CanFly` treats a remembered `false` as
-- authoritative -- so a player who quested through a zone before unlocking
-- flight had every route TO that zone costed at ground speed, a factor of
-- roughly three and a half, for ever. It corrected only by physically flying
-- back into the zone, which is the one thing the wrong estimate discourages.
--
-- A remembered `true` cannot go stale the same way: a zone that allowed
-- flying does not stop.
Travel.flyableDenialDays = 1

function Travel.NoteFlyable(mapID)
    if not mapID or not IsFlyableArea then
        return nil
    end

    local ok, flyable = pcall(IsFlyableArea)

    if not ok then
        return nil
    end

    if flyable then
        FlightMemory()[mapID] = true

        return true
    end

    -- A STORED "YES" IS NOT OVERWRITTEN BY A "NO".
    --
    -- The header above says a remembered `true` cannot go stale, and then
    -- this branch overwrote one unconditionally. `NoteWhereWeAre` calls this
    -- on every zone change and every loading screen, and `IsFlyableArea`
    -- answers for the SPOT the player is standing on -- a cave, a quest
    -- vehicle, an indoor phase -- while `CN.GetPlayerPosition` still reports
    -- the parent map. So walking into a cave in a zone you have flown around
    -- turned a permanent permission into a day-long refusal, and every route
    -- to that zone was costed at ground speed until it expired.
    --
    -- Flight being unavailable where you are standing is not evidence that
    -- it is unavailable in the zone. Flight being available IS evidence that
    -- it is available, which is why the two are not symmetrical.
    if FlightMemory()[mapID] == true then
        return false
    end

    -- Stamped, so the refusal can expire. A bare `false` cannot.
    FlightMemory()[mapID] = { flyable = false, at = time() }

    return false
end

-- What the store says about a map: true, false, or nil for "no longer worth
-- believing". Old entries are bare booleans; a bare `false` from before this
-- version has no stamp and is treated as expired, which is the safe
-- direction -- it costs one `IsFlyableArea` call the next time the player
-- stands there.
function Travel.RememberedFlyable(mapID)
    local held = mapID and FlightMemory()[mapID]

    if held == true then
        return true
    end

    if type(held) == "table" then
        if held.flyable then
            return true
        end

        if (time() - (held.at or 0)) > (Travel.flyableDenialDays * 86400) then
            return nil
        end

        return false
    end

    if held == false then
        return nil
    end

    return nil
end

function Travel.CanFly(mapID)
    if not Travel.HasFlying() then
        return false
    end

    -- What is REMEMBERED about the destination beats what is true where the
    -- player happens to be standing -- as long as it is still worth
    -- believing. See `Travel.RememberedFlyable`.
    local remembered = Travel.RememberedFlyable(mapID)

    if remembered == false then
        return false
    end

    if remembered ~= true and IsFlyableArea and not IsFlyableArea() then
        -- Nothing remembered, and flight is disabled here. The conservative
        -- answer is the one the player can definitely follow.
        return false
    end

    -- Same continent only; crossing one is handled above.
    local continent = Travel.ContinentFor(mapID)

    return continent ~= nil
end

-- Has this character ever actually flown? Measured, not assumed: the client
-- exposes no reliable "can you fly here" for an arbitrary map, and skyriding
-- availability changes with expansion, level and campaign progress. A
-- character with flying samples has flown; one without has not, and the
-- addon does not offer them a route they may not be able to take.
function Travel.HasFlying()
    local session = CN:GetModule("Session")

    if not session or not session.SpeedSampleCount then
        return false
    end

    return session.SpeedSampleCount("flying") >= (session.minSamples or 3)
end

-- Yards per second flying yourself, from the player's own measurements.
function Travel.SelfFlightSpeed()
    local session = CN:GetModule("Session")

    if not session or not session.Speed then
        return Travel.seededFlightSpeed, false
    end

    return session.Speed("flying")
end

------------------------------------------------------------
-- HEARTHSTONES, PORTALS AND TELEPORTS
------------------------------------------------------------

-- WHAT THIS IS AND IS NOT.
--
-- It is a list of ways off this continent that the player DEMONSTRABLY has:
-- an item in their bags, or a spell they know. Each one is reported with the
-- cooldown the client gives, so "your hearthstone is ready" and "your
-- hearthstone is on a 40 minute cooldown" are different answers.
--
-- It is NOT a routing model. The addon does not know where a hearthstone is
-- bound in map terms -- `GetBindLocation` returns a name, and names do not
-- convert to map ids -- so no duration is claimed and none is folded into any
-- score. Naming the option is useful; costing it would be fiction.
-- WHERE A TELEPORT ACTUALLY GOES.
--
-- The client will not convert a hearthstone's bind location into a map, and
-- it will not tell you where a mage portal leads either. Both are knowable
-- facts about the game rather than about the player, so they are curated
-- here -- which is the same argument that put quest locations in Data.
--
-- `mapID` is the ZONE the teleport lands in. Where it is nil, the option is
-- still listed and simply cannot be costed; naming a shortcut you have is
-- useful even when the addon cannot price it.
-- WHERE EACH ONE PUTS YOU DOWN.
--
-- A cross-continent journey can only be costed through a teleport whose
-- destination is known, and eight of these fourteen carried no destination at
-- all -- including the hearthstone, which is the one every player has. So a
-- non-mage asking about another continent got a list of what they own and no
-- duration whatsoever, which is the state this whole branch was built to
-- replace.
--
-- Three of them genuinely cannot be pinned, and are marked rather than given
-- a plausible-looking false landing:
--
--   * The hearthstone and Astral Recall go wherever the player set them. The
--     client reports that as a zone NAME, and this addon has no name-to-map
--     index -- building one means walking the whole map tree, which is a
--     client call per zone for a fact that is worth less than its cost.
--
--     LEARNED INSTEAD, from 0.59.0. The addon watches for the hearth being
--     cast and records where the player lands. That is one observation of
--     one fact the player performs anyway, it cannot be wrong the way a
--     curated table of localized inn names can, and it costs nothing until
--     it happens. Until it does, the option is listed and not costed --
--     exactly as before.
--   * The Flight Master's Whistle lands at the nearest flight point in the
--     zone you are already standing in. It is not a cross-continent option at
--     all.
--
-- The other eleven are fixed locations and are simply written down. Five of
-- them had no destination for no better reason than that nobody had filled
-- it in, which is why a non-mage got no cross-continent number at all.
Travel.teleports = {
    { kind = "item",  id = 6948,   label = "Hearthstone", bindPoint = true },

    { kind = "item",  id = 110560, label = "Garrison Hearthstone",
      -- Two garrisons, one per faction, and the client will not say which
      -- without reading the player's own garrison data. Draenor is the
      -- continent either way, which is what a cross-continent estimate needs.
      mapID = 590 },

    { kind = "item",  id = 140192, label = "Dalaran Hearthstone", mapID = 627 },

    -- Not a destination: it lands you at the nearest flight point in the zone
    -- you are already in.
    { kind = "item",  id = 141605, label = "Flight Master's Whistle",
      local_ = true },

    { kind = "spell", id = 556,    label = "Astral Recall", bindPoint = true },
    { kind = "spell", id = 3565,   label = "Teleport: Darnassus",     mapID = 89 },
    { kind = "spell", id = 3562,   label = "Teleport: Ironforge",     mapID = 87 },
    { kind = "spell", id = 3561,   label = "Teleport: Stormwind",     mapID = 84 },
    { kind = "spell", id = 3567,   label = "Teleport: Orgrimmar",     mapID = 85 },
    { kind = "spell", id = 3563,   label = "Teleport: Undercity",     mapID = 90 },
    { kind = "spell", id = 3566,   label = "Teleport: Thunder Bluff", mapID = 88 },
    { kind = "spell", id = 18960,  label = "Teleport: Moonglade",     mapID = 80 },
    { kind = "spell", id = 50977,  label = "Death Gate",              mapID = 118 },
    { kind = "spell", id = 126892, label = "Zen Pilgrimage",          mapID = 809 },
}


local function ItemCooldown(itemID)
    local count = 0

    if C_Item and C_Item.GetItemCount then
        count = C_Item.GetItemCount(itemID) or 0
    elseif GetItemCount then
        count = GetItemCount(itemID) or 0
    end

    if count <= 0 then
        return nil
    end

    local start, duration

    if C_Item and C_Item.GetItemCooldown then
        start, duration = C_Item.GetItemCooldown(itemID)
    elseif GetItemCooldown then
        start, duration = GetItemCooldown(itemID)
    end

    if not start or not duration or duration == 0 then
        return 0
    end

    local remaining = (start + duration) - ((GetTime and GetTime()) or 0)

    return math.max(0, remaining)
end

local function SpellCooldown(spellID)
    local known = false

    if IsSpellKnown then
        local ok, result = pcall(IsSpellKnown, spellID)

        known = ok and result
    end

    if not known and IsPlayerSpell then
        local ok, result = pcall(IsPlayerSpell, spellID)

        known = ok and result
    end

    if not known then
        return nil
    end

    local start, duration

    if C_Spell and C_Spell.GetSpellCooldown then
        local info = C_Spell.GetSpellCooldown(spellID)

        if type(info) == "table" then
            start, duration = info.startTime, info.duration
        end
    elseif GetSpellCooldown then
        start, duration = GetSpellCooldown(spellID)
    end

    if not start or not duration or duration == 0 then
        return 0
    end

    local remaining = (start + duration) - ((GetTime and GetTime()) or 0)

    return math.max(0, remaining)
end

-- Every teleport this character has, with seconds of cooldown remaining.
-- Ready ones first, because that is the order they are useful in.
-- WHERE THE PLAYER'S HEARTHSTONE ACTUALLY GOES, LEARNED BY WATCHING.
--
-- `GetBindLocation()` is a localized inn name. Turning that into a map means
-- either walking the whole map tree looking for a match -- a client call per
-- zone, for a name that may not be a zone name at all -- or a curated table
-- of inn names in ten languages, which is wrong the moment Blizzard renames
-- one.
--
-- Watching is exact and free: the player hearths, the addon notes the map
-- they arrived on, and files it under the bind name the client reports. If
-- they rebind, the name changes and the old entry simply stops being asked
-- for. Persisted because it is an observation the client will not repeat --
-- the standing rule -- and keyed on the name so a wrong one cannot outlive
-- the binding it describes.
local function BindPoints()
    local account = CN.Account()

    account.bindPoints = account.bindPoints or {}

    return account.bindPoints
end

function Travel.BindName()
    if not GetBindLocation then
        return nil
    end

    local ok, name = pcall(GetBindLocation)

    if not ok or type(name) ~= "string" or name == "" then
        return nil
    end

    return name
end

function Travel.BindMap()
    local name = Travel.BindName()

    return name and BindPoints()[name] or nil
end

-- Called once, after a hearth lands. Returns the map it recorded, or nil.
-- A CEILING, like the two stores beside it.
--
-- `questPins` is capped at 600 and `questHarvest` at 2000, both by explicit
-- migration, both with headers saying an uncapped store is the defect. This
-- one is keyed on a localized bind name and written on every hearth, so a
-- player who rebinds often accumulates names that will never be asked for
-- again. Small per entry and unbounded in principle, which is the same thing
-- the neighbours were.
Travel.bindPointCap = 32

function Travel.NoteHearthArrival()
    local name = Travel.BindName()

    if not name then
        return nil
    end

    local mapID = CN.GetPlayerPosition()

    if not mapID then
        return nil
    end

    local held = BindPoints()[name]

    -- Past the cap the whole store goes, which costs one hearth to relearn
    -- the binding actually in use -- cheaper than keeping an order nobody
    -- reads in order to evict by it.
    if held == nil and CN.CountKeys(BindPoints()) >= Travel.bindPointCap then
        CN.Account().bindPoints = {}

        CN.DebugPrint("Bind point store was full; cleared it.")
    end

    BindPoints()[name] = mapID

    if held ~= mapID then
        -- A journey that could not be costed a moment ago can be now.
        CN.InvalidateRanking()

        CN.DebugPrint("Hearthstone bind \"" .. name .. "\" lands on map "
            .. tostring(mapID) .. ".")
    end

    return mapID
end

-- How many bind points have been observed, for `/cn travel` and the tests.
function Travel.BindPointCount()
    return CN.CountKeys(BindPoints())
end

function Travel.ReadyTeleports()
    local available = {}

    for _, entry in ipairs(Travel.teleports) do
        local remaining

        if entry.kind == "item" then
            remaining = ItemCooldown(entry.id)
        else
            remaining = SpellCooldown(entry.id)
        end

        if remaining then
            table.insert(available, {
                label     = entry.label,
                kind      = entry.kind,
                id        = entry.id,
                mapID     = entry.mapID,
                remaining = remaining,
                ready     = remaining <= 0,
                -- Where a hearthstone actually goes. A name, because that is
                -- all the client offers; deliberately not turned into a map.
                bound     = entry.bindPoint and Travel.BindName() or nil,

                -- Where that bind point has been observed to land, if the
                -- player has hearthed once with the addon loaded. See
                -- `Travel.NoteHearthArrival`.
                learnedMap = entry.bindPoint
                    and Travel.BindMap() or nil,
            })
        end
    end

    table.sort(available, function(a, b)
        if a.ready ~= b.ready then
            return a.ready
        end

        return a.remaining < b.remaining
    end)

    return available
end

------------------------------------------------------------
-- THE ESTIMATE
------------------------------------------------------------

-- Returns seconds, confident, detail.
--
-- detail = { mode = "run"|"fly", yards, runToNode, flightYards, runFromNode,
--            node, arrival }
function Travel.EstimateSeconds(fromMapID, fromX, fromY, toMapID, toX, toY)
    local from = Travel.WorldPoint(fromMapID, fromX, fromY)
    local to   = Travel.WorldPoint(toMapID, toX, toY)

    if not from or not to then
        return nil, false, nil
    end

    if from.continent and to.continent and from.continent ~= to.continent then
        -- ANOTHER CONTINENT.
        --
        -- Still no duration: portal networks and boat schedules are not
        -- modelled and a fabricated number would be worse than an admission.
        -- But "I cannot cost this" and "there is no way to do it" are
        -- different statements, and until 0.43.0 the addon made the first and
        -- the player heard the second. So: say what is actually available.
        local teleports = Travel.ReadyTeleports()

        -- COSTED THROUGH A TELEPORT, WHERE ONE LANDS SOMEWHERE USEFUL.
        --
        -- Until 0.44.0 a cross-continent journey returned nothing at all,
        -- which is honest and unhelpful: the real answer is usually "hearth,
        -- then fly for ten seconds". Where a teleport has a known destination
        -- ON THE TARGET'S CONTINENT, the journey becomes castable: the
        -- teleport, plus the ordinary journey from where it drops you.
        --
        -- A teleport on cooldown is still offered, with the wait added --
        -- because "twenty minutes, then four" is a real answer and often the
        -- right one.
        local best

        for _, teleport in ipairs(teleports) do
            -- The curated destination, or the one the player's own hearth
            -- taught the addon.
            local destination = teleport.mapID or teleport.learnedMap

            local landing = destination and Travel.WorldPoint(destination, 0.5, 0.5)

            if landing and landing.continent == to.continent then
                local onward, _, onwardDetail = Travel.EstimateSeconds(
                    destination, 0.5, 0.5, toMapID, toX, toY)

                if onward then
                    local seconds = onward + Travel.castSeconds
                        + (teleport.ready and 0 or teleport.remaining)

                    if not best or seconds < best.seconds then
                        best = {
                            seconds   = seconds,
                            mode      = "teleport",
                            via       = teleport.label,
                            waited    = teleport.ready and 0 or teleport.remaining,
                            onward    = onward,
                            onwardMode = onwardDetail and onwardDetail.mode,
                        }
                    end
                end
            end
        end

        if best then
            -- Never confident: the onward leg is measured from the middle of
            -- the landing zone, because the addon does not know precisely
            -- where a teleport puts you down.
            best.teleports = teleports

            return best.seconds, false, best
        end

        return nil, false, {
            mode      = "elsewhere",
            teleports = teleports,
        }
    end

    local session = CN:GetModule("Session")

    -- THE SPEED OF RUNNING, NOT THE SPEED YOU HAPPEN TO BE MOVING.
    --
    -- `Speed()` with no argument answers for the bucket the player is in
    -- RIGHT NOW -- so asking it while airborne returned the skyriding median
    -- and used it to divide the "run the whole way" option and both walking
    -- legs of every flight-path route. A twenty-one thousand yard journey was
    -- quoted at six minutes, labelled `run`, and marked confident. The true
    -- figure on foot is fifty.
    --
    -- It also made the self-flown option unreachable while flying: dividing
    -- the same distance by the same number and then adding six seconds of
    -- takeoff can never win, so the mode this addon built a whole travel
    -- model around never appeared in the situation it was written for.
    --
    -- The ground speed is asked for by name. Which bucket the player is
    -- standing in is not a fact about how long it takes to walk somewhere.
    local runSpeed, runMeasured = 7, false

    if session and session.Speed then
        runSpeed, runMeasured = session.Speed(false)
    end

    runSpeed = math.max(0.5, runSpeed)

    local direct = Travel.YardsBetweenPoints(from, to)

    if not direct then
        return nil, false, nil
    end

    local best = {
        seconds = direct / runSpeed,
        mode    = "run",
        yards   = direct,
    }

    -- What the comparison uses, which is the duration for everything except a
    -- flight pair the player has flown before -- see the tie-break below.
    local bestRanking = best.seconds

    local confident = runMeasured

    -- SELF-FLYING (0.43.0).
    --
    -- In current content, flying yourself point to point usually beats both
    -- running and the flight network: no walk to a flight master, no
    -- overhead, and a straight line. Leaving it out meant the addon sent
    -- people to a flight master for journeys they would simply fly.
    --
    -- Only offered where the player can actually fly: a zone with flying
    -- disabled, or a character who has never flown, gets the ground answer.
    if Travel.CanFly(toMapID) then
        local flySpeed, flyMeasured = Travel.SelfFlightSpeed()

        local seconds = (direct / flySpeed) + Travel.takeoffSeconds

        if seconds < bestRanking then
            bestRanking = seconds

            best = {
                seconds = seconds,
                mode    = "self",
                yards   = direct,
            }

            confident = flyMeasured
        end
    end

    local nodes, continent = Travel.KnownNodes(toMapID)

    nodes = nodes or {}

    if #nodes >= 2 then
        -- THE BEST PAIR, NOT THE NEAREST AT EACH END.
        --
        -- Nearest-to-you and nearest-to-target are two independently sensible
        -- choices that together are often not the best route: a flight point
        -- slightly further from you can sit much closer to where you are
        -- going. The node count per continent is small enough to simply try
        -- every pairing, and that is still true -- what was not true was
        -- doing three distance computations inside each pairing.
        --
        -- REWRITTEN IN 0.46.0 with the same answers and a twentieth of the
        -- work. The two ends are each measured once per node instead of once
        -- per pair, the flight leg comes from a table computed once per
        -- continent, and the inner loop is arithmetic on numbers already in
        -- hand.
        local flightSpeed, flightMeasured = Travel.FlightSpeed()

        -- SCRATCH, NOT FRESH.
        --
        -- Three arrays of one entry per flight node -- fifty-nine on a real
        -- continent -- allocated on every call, and this is called once per
        -- located candidate per rebuild and on every costing cache miss.
        -- Measured at 8.3 KB per call. The cross-continent branch returns
        -- well above here, so the recursive teleport call cannot re-enter
        -- this block and reusing the buffers is safe.
        local originSeconds, arrivalSeconds = scratchOrigin, scratchArrival

        for index = #originSeconds, 1, -1 do
            originSeconds[index] = nil
        end

        for index = #arrivalSeconds, 1, -1 do
            arrivalSeconds[index] = nil
        end

        -- The cheapest either end can possibly be. Used to abandon an origin
        -- whose walk alone already costs more than the best route found so
        -- far.
        local cheapestArrival

        -- AND THE MOST THE REST OF THE SUM CAN BE DISCOUNTED.
        --
        -- 0.46.0 wrote this bound and called it exact "because every remaining
        -- term of the sum is positive". Every term is -- but the sum is then
        -- MULTIPLIED by knownRouteBonus when the pair is a route the player
        -- has actually flown, and a discount is not a term. A bound that
        -- ignores it prunes origins whose true cost is up to a tenth below
        -- what the bound predicted, and the addon silently reports the
        -- second-best route.
        --
        -- The test that was supposed to catch this brute-forced the answer
        -- honestly and still missed it: no routes had been noted at that point
        -- in the run, so the discount branch was never live while the
        -- comparison ran. It would have bitten only players who had flown
        -- somewhere -- which is all of them, and none of the fixtures.
        local bestPossibleDiscount = math.min(1, Travel.knownRouteBonus or 1)

        for index, node in ipairs(nodes) do
            local originYards = Travel.YardsBetweenPoints(from, node.point)
            local arrivalYards = Travel.YardsBetweenPoints(to, node.point)

            originSeconds[index]  = originYards and (originYards / runSpeed)
            arrivalSeconds[index] = arrivalYards and (arrivalYards / runSpeed)

            if arrivalSeconds[index]
                and (not cheapestArrival or arrivalSeconds[index] < cheapestArrival) then

                cheapestArrival = arrivalSeconds[index]
            end
        end

        -- ORIGINS IN THE ORDER THAT MAKES THE BOUND BITE.
        --
        -- The loop used to walk the node list in whatever order the client
        -- returned it, so `bestRanking` might not improve until late and the
        -- bound could not reject anything before it did. Walked nearest-first,
        -- the best route is usually found in the first few origins and every
        -- one after it fails the bound -- and because the bound rises
        -- monotonically with `walkOut`, the first failure means every
        -- remaining origin fails too. A filter becomes an early exit.
        local order = scratchOrder

        for index = #order, 1, -1 do
            order[index] = nil
        end

        for index = 1, #nodes do
            if originSeconds[index] then
                order[#order + 1] = index
            end
        end

        -- The comparator reads the scratch array through an upvalue rather
        -- than being rebuilt as a closure on every call.
        scratchSort = originSeconds

        table.sort(order, OrderByOrigin)

        -- The cheapest any flight out of a given node can be. Built with the
        -- graph, and it tightens the bound in exactly the place the bound was
        -- weakest: since 0.53.0 the flight leg is a path rather than a
        -- straight line, so assuming the flight is free -- which is what the
        -- bound did -- became a much larger lie.
        local minOutgoing = Neighbours(continent, nodes).minOutgoing or {}

        -- THE SMALLEST FLIGHT LEG ANYWHERE ON THIS CONTINENT.
        --
        -- The per-origin floor below uses `minOutgoing[i]`, which varies by
        -- origin -- so it is NOT monotone in `walkOut`, and the `break` that
        -- claimed "every remaining origin has a floor at least this high" was
        -- unsound as written. (Five and a half thousand randomised continents
        -- failed to produce a case where it changed the answer, which is why
        -- it survived; the triangle inequality and the 25:7 speed ratio make
        -- it very nearly true. Very nearly true is not an argument.)
        --
        -- So: a floor that IS monotone -- the same expression with the
        -- continent-wide minimum substituted -- keeps a sound early exit, and
        -- the per-origin floor becomes a filter, which is exact.
        local globalOutgoing

        for _, value in pairs(minOutgoing) do
            if not globalOutgoing or value < globalOutgoing then
                globalOutgoing = value
            end
        end

        globalOutgoing = globalOutgoing or 0

        for _, i in ipairs(order) do
            local walkOut = originSeconds[i]

            -- MONOTONE IN `walkOut`, so `order` being sorted by it means
            -- every remaining origin's floor really is at least this high.
            local soundFloor = walkOut + Travel.flightOverheadSeconds
                + (globalOutgoing / flightSpeed)
                + (cheapestArrival or 0)

            if not cheapestArrival
                or (bestPossibleDiscount * soundFloor) >= bestRanking then

                break
            end

            -- Nothing beyond this point can be free, no flight out of HERE is
            -- shorter than the shortest edge leaving it, and nothing can be
            -- discounted further than a known route discounts it -- so an
            -- origin whose best conceivable total already loses cannot win.
            -- A filter, not a break: this one is about one origin.
            local floor = walkOut + Travel.flightOverheadSeconds
                + ((minOutgoing[i] or 0) / flightSpeed)
                + (cheapestArrival or 0)

            if (bestPossibleDiscount * floor) < bestRanking then
                local origin = nodes[i]

                -- THE WAY THE BIRD ACTUALLY GOES.
                --
                -- `spans` is still what the graph is built from, but the
                -- flight leg is now the shortest path through that graph
                -- rather than the straight line across it. A pair with no
                -- path between them has no entry and is not offered.
                local path = ShortestFrom(continent, nodes, i)

                for j = 1, #nodes do
                    local flightYards = (i ~= j) and path.dist[j] or nil
                    local walkIn      = arrivalSeconds[j]

                    -- The same argument, one level down: an arrival whose two
                    -- walks alone already lose cannot be rescued by a flight,
                    -- which is never negative. There was no bound on the
                    -- inner loop at all.
                    if walkIn
                        and (bestPossibleDiscount
                            * (walkOut + Travel.flightOverheadSeconds + walkIn))
                            >= bestRanking then

                        flightYards = nil
                    end

                    if flightYards and walkIn then
                        local seconds = walkOut
                            + Travel.flightOverheadSeconds
                            + (flightYards / flightSpeed)
                            + walkIn

                        -- A pair the player has actually flown beats an
                        -- equivalent pair nobody has: same distance, one
                        -- of them proven to connect.
                        --
                        -- A TIE-BREAK, NOT A DISCOUNT. This used to multiply
                        -- `seconds` itself, so the duration reported to the
                        -- player was ten percent below the model's own
                        -- arithmetic -- `/cn travel` printed legs that summed
                        -- to fifty seconds more than its own headline -- and
                        -- that shortened number flowed into scoring and into
                        -- `/cn plan`'s budget. Every player has flown
                        -- somewhere, so this was the common case, not an
                        -- edge one.
                        --
                        -- The preference belongs in the comparison. The
                        -- seconds are the seconds.
                        local ranking = seconds

                        if Travel.IsKnownRoute(origin.id, nodes[j].id) then
                            ranking = ranking * Travel.knownRouteBonus
                        end

                        if ranking < bestRanking then
                            bestRanking = ranking

                            best = {
                                seconds     = seconds,
                                mode        = "fly",
                                yards       = direct,
                                runToNode   = walkOut * runSpeed,
                                flightYards = flightYards,
                                runFromNode = walkIn * runSpeed,
                                node        = origin.name,
                                arrival     = nodes[j].name,

                                -- The ids as well as the names, added in
                                -- 0.46.0: a name is what a player reads, and
                                -- an id is what anything downstream needs to
                                -- ask a further question about the route.
                                nodeID      = origin.id,
                                arrivalID   = nodes[j].id,

                                -- The chain itself. One entry means the
                                -- ordinary direct hop; more means the route
                                -- goes through flight masters in between,
                                -- and the player is told which.
                                legs        = Travel.LegsBetween(
                                                  nodes, path, i, j),
                            }

                            best.hops = best.legs and #best.legs or 1

                            -- A flight estimate is only as good as the
                            -- flight speed behind it -- and a multi-hop
                            -- route rests on an inferred edge list as well,
                            -- which is a model and not a measurement.
                            confident = runMeasured and flightMeasured
                                and best.hops <= 1
                        end
                    end
                end
            end
        end
    end

    return best.seconds, confident, best
end

-- The same answer on the scale the scorer uses, where roughly ten is "across
-- a zone". Kept as a separate function so the scoring scale and the human
-- number never drift apart: one is derived from the other.
Travel.secondsPerCostPoint = 30

-- Published, because Session has to remove from a measured duration exactly
-- what the planner will add back to it. One constant, one conversion.
CN.secondsPerCostPoint = Travel.secondsPerCostPoint
Travel.maximumCost         = 40

-- MEMOISED, BECAUSE EVERY LOCATED CANDIDATE PAYS THIS.
--
-- One estimate costs about two tenths of a millisecond against a real flight
-- network, and a rebuild asks for one per located objective -- a full quest
-- log plus rares, treasures and located vendor recipes is forty to eighty of
-- them. That is most of the rebuild, and it was recomputed from scratch every
-- time even though a rebuild answers the same question about the same
-- destinations from the same place.
--
-- Keyed on the destination rounded to about a yard, and on where the player
-- is standing rounded rather more coarsely -- the answer does not change
-- meaningfully for a few paces, and re-keying on every step would defeat the
-- cache in exactly the situation it is for.
--
-- Numeric key, not a string: `Travel.WorldPoint`'s string key is built two
-- concatenations and two coercions at a time, and this runs far more often.
Travel.costCacheCap = 512

-- How far the player has to move before the cached costs stop being about
-- where they are. Twenty yards is under two seconds of running and well
-- inside the noise of a model whose smallest unit is thirty seconds.
Travel.costCacheYards = 20

local costCache, costCacheCount = {}, 0

-- Whether the model was confident about each cached cost. Kept beside the
-- cache rather than inside it so nothing that reads a cost by key has to know
-- about a second shape. 0.71.0.
local confidentCache = {}
local costCacheMap, costCacheX, costCacheY

function Travel.ForgetCosts()
    costCache, costCacheCount = {}, 0
    confidentCache = {}
    costCacheMap, costCacheX, costCacheY = nil, nil, nil
end

function Travel.CostCacheSize()
    return costCacheCount
end

function Travel.CostFor(mapID, x, y)
    local playerMap, playerX, playerY = CN.GetPlayerPosition()

    if not playerMap or not mapID or not x or not y then
        return nil
    end

    -- THE PLAYER'S OWN POSITION HAS TO BE KNOWN, TOO.
    --
    -- The guard checked the DESTINATION's coordinates and not the player's,
    -- and `CN.GetPlayerPosition` routinely answers `mapID, nil, nil` for a
    -- moment after a loading screen. So the cache was stamped with a nil
    -- origin, every estimate failed, and the failures were remembered.
    if not playerX or not playerY then
        return nil
    end

    -- Has the player moved far enough for the answers to be about somewhere
    -- else? A different map always counts; on the same map, compare in yards.
    local moved = costCacheMap ~= playerMap

    if not moved and not costCacheX then
        -- No origin was recorded, so nothing in the cache is about anywhere
        -- in particular. Fail open: a cache whose premise is unknown is a
        -- cache that has to be rebuilt.
        moved = true
    elseif not moved then
        local yards = Travel.YardsBetween(playerMap, costCacheX, costCacheY,
            playerMap, playerX, playerY)

        moved = (yards == nil) or (yards > Travel.costCacheYards)
    end

    if moved then
        costCache, costCacheCount = {}, 0
        confidentCache = {}
        costCacheMap = playerMap
        costCacheX, costCacheY = playerX, playerY
    end

    local key = (mapID * 1000000) + (Packed(x) * 1000) + Packed(y)

    -- `~= nil` rather than a truth test, and no `false` branch: 0.54.0 stored
    -- `false` for a refusal and the paragraph below explains why it stopped.
    -- The branch that read it back outlived the branch that wrote it, so it
    -- was unreachable code standing exactly where a reader would look to find
    -- out whether misses are cached. They are not.
    local held = costCache[key]

    if held ~= nil then
        return held, confidentCache[key]
    end

    -- THE MODEL'S OWN CONFIDENCE, CARRIED RATHER THAN DROPPED. 0.71.0.
    --
    -- `EstimateSeconds` returns whether it is confident in the figure -- a
    -- multi-hop route through a flight network it is partly guessing at is
    -- not the same claim as a walk across a zone -- and this threw that away.
    -- So the addon ended up with two different rules for "is this journey a
    -- measurement": the window's tooltips required confidence, and `/cn list`
    -- and the deadline guard required only that a number came back. The same
    -- rare could show a distance in one and not the other.
    local seconds, confident = Travel.EstimateSeconds(
        playerMap, playerX, playerY, mapID, x, y)

    if costCacheCount >= Travel.costCacheCap then
        costCache, costCacheCount = {}, 0
        confidentCache = {}
    end

    if not seconds then
        -- NOT REMEMBERED.
        --
        -- 0.54.0 cached the refusal, reasoning that re-deriving the same nil
        -- is the most expensive way to learn nothing. That was wrong for the
        -- same reason `Travel.WorldPoint` fourteen hundred lines above
        -- refuses to cache ITS miss, in a comment that says so plainly: a
        -- failure here is almost never a property of the destination, it is a
        -- property of the moment. The client refuses every coordinate
        -- conversion for a window after a loading screen, and remembering
        -- that made the whole ranking travel-blind for the rest of the
        -- session -- at exactly the moment a player is most likely to be
        -- looking at it.
        --
        -- Re-deriving a nil costs one failed estimate. Remembering it cost
        -- the feature.
        return nil
    end

    local cost = math.min(Travel.maximumCost,
        seconds / Travel.secondsPerCostPoint)

    costCache[key]  = cost
    costCacheCount  = costCacheCount + 1

    -- CACHED AS A PAIR, so the second reader of a cached cost gets the same
    -- answer about it as the first.
    confidentCache[key] = confident and true or false

    return cost, confident and true or false
end

-- Published so providers do not each have to decide what to do when the
-- estimate is unavailable.
--
-- IT MUST NOT BE CHEAPER THAN A JOURNEY WE CAN ACTUALLY COST.
--
-- This was 25 while a costed journey saturates at `maximumCost = 40`, so
-- "I cannot work out how to get there" scored fifteen points BELOW the far
-- side of the zone the player is standing in -- and fifteen is nearly twice
-- the entire range of what finishing something is worth. Another continent,
-- unreachable and unmodelled, outranked a quest two minutes away.
--
-- An uncostable journey is the one we know least about; it has to be the
-- pessimistic answer, not the optimistic one.
CN.fallbackZoneCost = 40

function CN.TravelCost(mapID, x, y)
    local travel = CN:GetModule("Travel")

    -- THE MODEL'S OWN CONFIDENCE, NOT "IT RETURNED A NUMBER". 0.71.0.
    --
    -- This reported `true` for anything `CostFor` answered at all, and
    -- `CostFor` answers for a multi-hop route through a flight network it is
    -- partly guessing at as readily as for a walk across a zone. The window's
    -- tooltips already asked `EstimateSeconds` for its confidence flag and
    -- printed nothing without it -- so the addon carried two different rules
    -- for "is this journey a measurement", and the same rare could show a
    -- distance in the tooltip and none in `/cn list`, or the reverse.
    local cost, confident

    if travel then
        cost, confident = travel.CostFor(mapID, x, y)
    end

    if cost then
        return cost, confident and true or false
    end

    local playerMap = CN.GetPlayerPosition()

    if mapID and playerMap and mapID == playerMap then
        return CN.unknownLocationCost, false
    end

    if not mapID then
        return CN.unknownLocationCost, false
    end

    return CN.fallbackZoneCost, false
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

-- Short "how long until it is usable" text. Minutes and seconds, because a
-- cooldown the player is waiting on is measured in the units they are
-- counting in.
function Travel.FormatReset(seconds)
    if not seconds or seconds <= 0 then
        return "ready"
    end

    if seconds < 60 then
        return math.floor(seconds) .. "s"
    end

    if seconds < 3600 then
        return math.floor(seconds / 60) .. "m"
    end

    return string.format("%.1fh", seconds / 3600)
end

function Travel.Describe(detail, seconds, confident)
    if not seconds then
        return CN.WithConfidence(nil, CN.confidence.UNKNOWN) .. " travel time"
    end

    local session = CN:GetModule("Session")

    local text = session and session.FormatDuration
        and session.FormatDuration(seconds)
        or (math.floor(seconds / 60) .. "m")

    if detail and detail.mode == "self" then
        text = text .. " |cff8a8f96flying yourself|r"
    end

    if detail and detail.mode == "teleport" then
        text = text .. " |cff8a8f96via " .. tostring(detail.via)

        if (detail.waited or 0) > 0 then
            text = text .. ", after a " .. Travel.FormatReset(detail.waited)
                .. " cooldown"
        end

        text = text .. "|r"
    end

    if detail and detail.mode == "fly" and detail.node then
        text = text .. " |cff8a8f96via " .. tostring(detail.node)
        if detail.arrival then
            text = text .. " to " .. tostring(detail.arrival)
        end
        text = text .. "|r"
    end

    -- One convention, defined in Core, used by everything that prints a
    -- number it is not certain of.
    return CN.WithConfidence(text, CN.ConfidenceFor(confident))
end

------------------------------------------------------------
-- EVENTS
------------------------------------------------------------

-- Discovering a flight point changes every cross-zone answer this module
-- gives, so the cache goes when it happens.
--
-- `NEW_TAXI_NODE` was in this list and is not an event. The client refuses to
-- register an unknown name -- it throws -- so every login since this line was
-- written produced a Lua error, and the two events either side of it were
-- registered anyway only because they come before and after in the loop. It
-- was invented, plausibly, and nothing ever checked.
--
-- There is no discovery event. TAXIMAP_OPENED is the honest substitute: you
-- discover a flight point by talking to the flight master, which opens the
-- map.
-- ONLY TAXIMAP_OPENED THROWS THE NETWORK AWAY.
--
-- `PLAYER_ENTERING_WORLD` was in this list, and it fires on every zone
-- transition through a loading screen, every instance, every portal, every
-- hearth and every reload -- so the first rebuild after any of those paid for
-- the whole flight graph again. Measured at about ten milliseconds, on top of
-- a provider rebuild, at precisely the moment the client is busiest.
--
-- And it bought nothing: flight points cannot appear during a loading screen.
-- The only thing that adds one is talking to a flight master, which opens the
-- taxi map. `Travel.KnownNodes` already refuses to remember an empty list, so
-- the "client was not ready yet" case that the event was covering is handled
-- where it belongs.
-- WATCHING FOR THE HEARTH.
--
-- `UNIT_SPELLCAST_SUCCEEDED` fires the moment the cast completes and before
-- the loading screen, so the arrival is the next `PLAYER_ENTERING_WORLD`.
-- Two spell ids: the hearthstone's own, and Astral Recall, which goes to the
-- same bind point.
--
-- Deliberately narrow. A flag, one event deep, cleared whether or not the
-- arrival produced a map -- a pending flag that can survive an unrelated
-- loading screen would file the wrong zone under the player's bind name and
-- then cost journeys against it.
Travel.hearthSpells = {
    [8690] = true,   -- Hearthstone
    [556]  = true,   -- Astral Recall
}

local hearthPending  = false
local hearthAttempts = 0

-- Three loading screens, or three seconds of retries after one. Past that the
-- client is not going to place the player and the observation is dropped
-- rather than filed against whatever map eventually answers.
Travel.hearthRetries = 3

CN:RegisterEvent("UNIT_SPELLCAST_SUCCEEDED", function(_, unit, _, spellID)
    if unit == "player" and Travel.hearthSpells[spellID] then
        hearthPending = true
    end
end)

-- NARROWED TO THE PLAYER. 0.86.0.
--
-- `CN:RegisterEvent` goes through the client's plain `RegisterEvent`, and a
-- UNIT event registered that way fires for every unit token the client is
-- tracking -- party, raid, boss, arena, target, focus, mouseover, nameplates.
-- The handler above filters correctly, and the filtering happens after the
-- dispatcher has already built a closure and a pcall for each firing: in a
-- raid or a busy hub, a hundred of those a second, for a flag that can flip
-- once per hearthstone.
--
-- This is the only unit event in the addon, which is why the rule the rest of
-- the tree applies to chatty events had never been applied here. The offline
-- suite fires it twice, once per unit, so it modelled the shape and not the
-- volume.
--
-- `RegisterUnitEvent` replaces the broad registration on the same frame and
-- the same event, so nothing above needs to change.
if CN.eventFrame and CN.eventFrame.RegisterUnitEvent then
    pcall(CN.eventFrame.RegisterUnitEvent, CN.eventFrame,
        "UNIT_SPELLCAST_SUCCEEDED", "player")
end

CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    if not hearthPending then
        return
    end

    -- THE FLAG IS NOT CLEARED UNTIL THE OBSERVATION SUCCEEDS.
    --
    -- `CN.GetPlayerPosition()` returns nil whenever the client will not place
    -- the player, which this addon documents in three places as routine for a
    -- moment after a loading screen -- and `PLAYER_ENTERING_WORLD` IS that
    -- moment. Clearing first meant the one observation was thrown away
    -- exactly when it was most likely to fail, and nothing re-armed until the
    -- next hearth: the bind point stayed unknown and every cross-continent
    -- journey stayed uncosted.
    if Travel.NoteHearthArrival() then
        hearthPending = false

        return
    end

    -- One retry a frame later, by which time the map has resolved. Bounded,
    -- so a hearth into a zone the client will never place does not leave a
    -- flag armed for the rest of the session waiting to record the wrong map.
    hearthAttempts = (hearthAttempts or 0) + 1

    if hearthAttempts >= Travel.hearthRetries then
        hearthPending  = false
        hearthAttempts = 0

        return
    end

    if C_Timer and C_Timer.After then
        C_Timer.After(1, function()
            if not hearthPending then
                return
            end

            if Travel.NoteHearthArrival() then
                hearthPending  = false
                hearthAttempts = 0
            end
        end)
    end
end)

-- Rebinding invalidates nothing -- the store is keyed on the bind NAME, so a
-- new binding is simply a name that has not been observed yet. What it does
-- change is whether a journey can be costed, so the ranking is told.
CN:RegisterEvent("HEARTHSTONE_BOUND", function()
    CN.InvalidateRanking()
end)

CN:RegisterEvent("TAXIMAP_OPENED", function()
    Travel.ForgetNodes()

    CN.InvalidateCandidates()
end)

-- A loading screen still moves the player, though, so the costed journeys
-- are about somewhere else now. Those are cheap to rebuild and the network
-- they were derived from is not.
CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    Travel.ForgetCosts()

    CN.InvalidateCandidates()
end)

-- WHERE THE FLYABILITY MEMORY IS ACTUALLY WRITTEN.
--
-- `Travel.NoteFlyable` was written in 0.43.0 with a block comment explaining
-- that remembering the answer per zone "turns that guess into evidence", and
-- then nothing ever called it. The store stayed empty for four releases, so
-- `Travel.CanFly` always fell through to `IsFlyableArea()` -- which answers
-- for where the player is STANDING -- and that is precisely the guess the
-- comment claims was replaced. Every self-flown route estimate to another
-- zone rested on it.
--
-- The test suite could not see it because the harness wrote the store
-- directly, bypassing the producer: populated in test, permanently empty in
-- game.
--
-- Observed on arrival, which is the only moment the client will answer
-- honestly about a zone.
local function NoteWhereWeAre()
    local mapID = CN.GetPlayerPosition()

    if mapID then
        pcall(Travel.NoteFlyable, mapID)
    end
end

for _, event in ipairs({ "ZONE_CHANGED_NEW_AREA", "PLAYER_ENTERING_WORLD" }) do
    CN:RegisterEvent(event, NoteWhereWeAre)
end

-- And whenever the player is demonstrably flying, which is evidence that
-- outranks anything the client says about the area: you cannot be flying
-- somewhere flight is disabled.
CN:RegisterEvent("PLAYER_CONTROL_GAINED", function()
    if IsFlying and select(1, pcall(IsFlying)) then
        local flying = select(2, pcall(IsFlying))

        if flying then
            local mapID = CN.GetPlayerPosition()

            if mapID then
                -- A plain `true`: observing yourself flying there is the
                -- strongest evidence there is, and a yes does not expire.
                FlightMemory()[mapID] = true
            end
        end
    end
end)

-- Sampling the flight only while there is a flight to sample.
local ticker

Travel.tickSeconds = 1

CN:RegisterEvent("PLAYER_CONTROL_LOST", function()
    -- Losing control is the moment a flight starts. Record where from.
    pcall(Travel.NoteBoarding)

    if ticker or not C_Timer or not C_Timer.NewTicker then
        return
    end

    ticker = C_Timer.NewTicker(Travel.tickSeconds, function()
        local flying = Travel.ObserveFlight()

        if not flying and ticker then
            -- The flight has ended: record which two points it joined.
            pcall(Travel.NoteLanding)

            ticker:Cancel()
            ticker = nil
        end
    end)
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "travel",
    order   = 26,
    help    = "How long it takes to reach the top recommendation, and how.",
    handler = function()
        local nodes, continent = Travel.KnownNodes(CN.GetPlayerPosition())

        local speed, measured = Travel.FlightSpeed()

        Print(string.format("Flight points known on this continent: %d", #nodes))
        Print(string.format("Flight speed: %.1f yards/second %s",
            speed, measured
                and ("|cff8a8f96from " .. Travel.FlightSampleCount()
                    .. " of your own flights|r")
                or (CN.WithConfidence("", CN.confidence.ESTIMATED)
                    .. " |cff8a8f96-- take a flight path and it will be "
                    .. "measured|r")))

        if not continent then
            Print("|cff8a8f96The client will not say which continent this is.|r")
        end

        Print("Bind points learned: " .. Travel.BindPointCount()
            .. CN.Aside("recorded by watching where your hearth lands"))

        local results = CN.Recommend(1)

        local target = results and results[1]

        if not target or not target.mapID or not target.x then
            Print("|cff8a8f96Nothing with a location is being recommended, so "
                .. "there is nothing to cost.|r")
            return
        end

        local playerMap, playerX, playerY = CN.GetPlayerPosition()

        local seconds, confident, detail = Travel.EstimateSeconds(
            playerMap, playerX, playerY, target.mapID, target.x, target.y)

        Print("To " .. tostring(target.name) .. ": "
            .. Travel.Describe(detail, seconds, confident))

        if detail and detail.mode == "fly" then
            local session = CN:GetModule("Session")

            -- ON FOOT MEANS ON FOOT. 0.77.0.
            --
            -- `Session.Speed()` with no argument answers for the bucket the
            -- player is in RIGHT NOW -- and a player reading `/cn travel` is
            -- normally mounted or skyriding, so the "running the whole way"
            -- figure was quoted at roughly three and a half times the true
            -- speed. A fifty-minute walk read as fourteen minutes, which
            -- makes the flight this line exists to justify look like a bad
            -- idea.
            --
            -- The sixteen-line header on `EstimateSeconds` documents this
            -- exact defect being fixed there; this was the last no-argument
            -- caller left in the tree.
            local runSpeed, runMeasured = 7, false

            if session and session.Speed then
                runSpeed, runMeasured = session.Speed(false)
                runSpeed = runSpeed or 7
            end

            Print(string.format(
                "  |cff8a8f96%.0f yd to %s, %.0f yd in the air, %.0f yd at the "
                .. "far end" .. CN.DASH .. "against %.0f yd on foot|r",
                detail.runToNode, tostring(detail.node), detail.flightYards,
                detail.runFromNode, detail.yards))

            -- THE CHAIN, NOT JUST ITS ENDS.
            --
            -- A two-hop route printed as a single "in the air" figure looks
            -- like a straight line the player can check against the map and
            -- find wrong. Printed as its legs it is checkable, which is the
            -- point of the whole breakdown.
            local legs = detail.legs or {}

            if #legs > 1 then
                Print(string.format("  |cff8a8f96%d legs:|r", #legs))

                for index, leg in ipairs(legs) do
                    CN.PrintLine(string.format("    |cff8a8f96%d. %s to %s, %.0f yd|r",
                        index, tostring(leg.from), tostring(leg.to),
                        leg.yards or 0))
                end
            end

            local onFoot = session and session.FormatDuration
                and session.FormatDuration(
                    detail.yards / math.max(0.5, runSpeed))

            -- And marked, like every other duration in this file: a figure
            -- from a measured run speed and one from the default are not the
            -- same claim.
            -- THROUGH `CN.ConfidenceFor`, NOT A RAW BOOLEAN. 0.78.0.
            --
            -- `CN.WithConfidence` compares its second argument against the
            -- `CN.confidence` STRINGS. A boolean matches neither, so it fell
            -- through and returned the text unmarked -- the measured form,
            -- always. The comment two lines up described behaviour the code
            -- did not have, and both siblings in this file and in `Session`
            -- already did it correctly.
            Print(string.format("  |cff8a8f96running the whole way: %s|r",
                onFoot
                    and CN.WithConfidence(onFoot,
                        CN.ConfidenceFor(runMeasured))
                    or CN.L["unknown"]))
        elseif detail and detail.mode == "self" then
            local flySpeed, flyMeasured = Travel.SelfFlightSpeed()

            Print(string.format(
                "  |cff8a8f96%.0f yd direct at %.0f yd/s%s|r",
                detail.yards, flySpeed,
                flyMeasured and ""
                    or (" " .. CN.WithConfidence("",
                        CN.confidence.ESTIMATED))))
        elseif detail and detail.mode == "elsewhere" then
            Print("|cff8a8f96That is on another continent. Portals and boats "
                .. "are not modelled, so no time is claimed" .. CN.DASH .. "but here is "
                .. "what you have:|r")

            local teleports = detail.teleports or {}

            if #teleports == 0 then
                Print("  |cff8a8f96no hearthstone or teleport available|r")
            end

            -- AND SAYS SO WHEN IT STOPS. 0.78.0. A cap nobody can see reads
            -- as "that was everything"; see the same fix in
            -- `Modules/Currencies.lua`.
            if #teleports > 5 then
                Print("  |cff8a8f96showing 5 of " .. #teleports .. "|r")
            end

            for index, teleport in ipairs(teleports) do
                if index > 5 then
                    break
                end

                local line = "  " .. teleport.label

                if teleport.bound then
                    line = line .. CN.Muted(" to " .. teleport.bound)

                    -- SAY WHETHER THE ADDON CAN PRICE IT.
                    --
                    -- A bind point is a name until the player hearths once
                    -- with the addon loaded; after that it is a map and the
                    -- journey costs like any other. Both states are honest;
                    -- only one of them was visible.
                    if not teleport.learnedMap then
                        line = line .. CN.Muted(" (not costed yet"
                            .. CN.DASH .. "hearth once and it will be)")
                    end
                end

                if teleport.ready then
                    line = line .. " |cff73b873ready|r"
                else
                    line = line .. " |cffe2564c"
                        .. Travel.FormatReset(teleport.remaining) .. "|r"
                end

                CN.PrintLine(line)
            end
        end
    end,
}

return Travel
'@

$Embedded['Modules\Instances.lua'] = @'
-- Modules/Instances.lua
-- Completion Navigator :: dungeons and raids, which the addon could not see.
--
-- WHAT WAS MISSING.
--
-- Until now this addon knew everything about the open world and nothing about
-- the inside of a dungeon. A mount that drops from a raid boss was a line of
-- free text out of the mount journal: no boss, no instance, no difficulty, no
-- idea whether you had already killed the thing this week. `/cn chase` on such
-- a mount produced a goal with no path to it, which is the one thing this
-- addon is supposed to never do.
--
-- Worse, lockouts are the strongest deadline in the game -- stronger than a
-- daily, because a missed raid week is gone for a week rather than a day --
-- and the ranking could not see them at all, so a world quest expiring in an
-- hour outranked a raid you were six bosses into with two days left on it.
--
-- WHAT THIS DOES NOT DO.
--
-- It does not queue for anything, invite anyone, or set foot in an instance.
-- It reads three things and reports them: what you are locked to, which
-- bosses in that lockout are still alive, and where a given drop comes from.
--
-- AND WHAT IT REFUSES TO STORE.
--
-- Nothing. A lockout expires, the client always knows it, and a stale copy is
-- worse than none: "6 of 8 down in there" is actively wrong advice the moment
-- the reset it never heard about happens. The same goes for loot tables,
-- which change with patches. Everything here is read live and cached in
-- memory for the session at most.

local ADDON_NAME, CN = ...

local Instances = CN:RegisterModule("Instances")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- LOCKOUTS
------------------------------------------------------------

-- An unfinished lockout is the cheapest progress in the game: the bosses you
-- already killed stay dead, so the remaining ones cost a fraction of a fresh
-- clear. A finished one is worth nothing until it resets. That difference is
-- the entire reason this module scores anything.
function Instances.Lockouts()
    local raw = Blizzard.GetSavedInstances()

    local lockouts = {}

    for _, saved in ipairs(raw) do
        -- An expired lockout is still listed for a while. Anything with no
        -- time left on it is not a lockout, it is a memory.
        if not saved.reset or saved.reset > 0 then
            local encounters = saved.encounters or 0
            local defeated   = saved.defeated or 0

            table.insert(lockouts, {
                name         = saved.name,

                -- Two ids, deliberately both carried and deliberately named
                -- differently: `id` is the lockout save, `instanceID` is the
                -- Encounter Journal's. Handing the first to the journal is
                -- the defect this pair exists to make impossible.
                id           = saved.id,
                instanceID   = saved.instanceID,
                difficulty   = saved.difficulty,
                difficultyID = saved.difficultyID,
                raid         = saved.raid,
                defeated     = defeated,
                encounters   = encounters,
                remaining    = math.max(0, encounters - defeated),
                resetsIn     = saved.reset,
                extended     = saved.extended,
                complete     = encounters > 0 and defeated >= encounters,
            })
        end
    end

    table.sort(lockouts, function(a, b)
        -- Most nearly finished first: that is the order they are worth doing.
        if a.complete ~= b.complete then
            return b.complete
        end

        if a.remaining ~= b.remaining then
            return a.remaining < b.remaining
        end

        return (a.resetsIn or math.huge) < (b.resetsIn or math.huge)
    end)

    return lockouts
end

function Instances.Summary()
    local lockouts = Instances.Lockouts()

    local summary = {
        total      = #lockouts,
        unfinished = 0,
        soonest    = nil,
        bosses     = 0,
    }

    for _, lockout in ipairs(lockouts) do
        if not lockout.complete then
            summary.unfinished = summary.unfinished + 1
            summary.bosses     = summary.bosses + lockout.remaining

            if not summary.soonest
                or (lockout.resetsIn or math.huge) < (summary.soonest.resetsIn or math.huge) then
                summary.soonest = lockout
            end
        end
    end

    return summary
end

-- WHICH bosses are still alive in a lockout the player is part-way through.
--
-- The client reports a count, not a list, so the names come from the
-- Adventure Guide and the state comes from the count. Where the two cannot be
-- reconciled -- a boss killed out of order, which is normal -- this says how
-- many are left rather than inventing which ones. An invented name is worse
-- than a number.
function Instances.RemainingBosses(lockout)
    if not lockout or lockout.remaining <= 0 then
        return {}, nil
    end

    if not lockout.id then
        return {}, "the client did not name this instance"
    end

    -- The JOURNAL's id, not the lockout id. See GetSavedInstances.
    if not lockout.instanceID then
        return {}, "the client did not give an Adventure Guide id for this "
            .. "instance"
    end

    local encounters = Blizzard.GetInstanceEncounters(lockout.instanceID)

    if #encounters == 0 then
        return {}, "the Adventure Guide has no boss list for this instance"
    end

    -- Only when nothing has been killed can each boss be named with
    -- confidence. Past that, the client tells us how many, not which.
    if lockout.defeated == 0 then
        return encounters, nil
    end

    return {}, lockout.remaining .. " of " .. lockout.encounters
        .. " still up (the client does not say which)"
end

------------------------------------------------------------
-- WHERE DOES IT DROP
------------------------------------------------------------

-- Answers for a name rather than an ID, because that is what the collection
-- journals hand us, and because the Adventure Guide's own search works that
-- way. Cached for the session: the answer does not change until a patch does,
-- and the search is not free.
local dropCache = {}

function Instances.ForgetDrops()
    dropCache = {}
end

-- How long a "nothing found" is trusted before the journal is asked again.
-- Short, because a zero is usually "the async search has not landed yet";
-- non-zero, because most items are not boss drops and a mouseover storm must
-- not re-run the whole search for each of them.
Instances.dropMissSeconds = 60

function Instances.WhereDoesItDrop(name)
    if type(name) ~= "string" or name == "" then
        return {}
    end

    local cached = dropCache[name]

    if cached then
        if cached.results then
            return cached.results
        end

        if (time() - (cached.at or 0)) < Instances.dropMissSeconds then
            return {}
        end
    end

    local results = Blizzard.SearchEncounterJournal(name, 6)

    -- A ZERO IS "NOT YET", NOT "NOTHING" -- BUT IT IS NOT FREE EITHER. 0.80.0.
    --
    -- The journal's search is asynchronous, so the first query for a name
    -- reliably returns nothing. Caching that made the emptiness permanent for
    -- the session: every later ask returned the memoised zero and the search
    -- that had by then completed was never read. So misses were not recorded
    -- at all, justified in this comment by "the cost of asking again is one
    -- search the player triggered themselves".
    --
    -- That stopped being true when the tooltip became a caller. A tooltip is
    -- not triggered by the player asking a question; it fires on every
    -- tooltip built, and MOST COLLECTIBLES ARE NOT BOSS DROPS -- so the
    -- common case was the uncached one. Sweeping a bag, a loot window or an
    -- auction-house page of mounts ran a full `EJ_SetSearch` cycle, with a
    -- save and restore of the Adventure Guide's own selection, dozens of
    -- times a second.
    --
    -- Both facts are now true at once: an answer is kept, and a miss is kept
    -- just long enough to absorb the storm.
    -- A REFUSAL IS NOT AN ANSWER, AND THE FIRST ZERO IS NOT ONE EITHER.
    -- 0.81.0.
    --
    -- 0.80.0 began recording misses to stop a mouseover storm re-running the
    -- search, which was right, and recorded THREE different things as one:
    --
    --   * the Adventure Guide is not on this client, or is OPEN -- in which
    --     case the search never ran. `WithJournal` refuses outright while the
    --     player has it open, and the tooltip and `/cn chase` both call in
    --     with no such guard.
    --   * `EJ_SetSearch` has not finished. The client's search is
    --     asynchronous and the FIRST query for a name reliably returns
    --     nothing -- which is the defect the comment above was written for.
    --   * the name genuinely drops from nothing.
    --
    -- So `/cn drops <name>` typed twice in a row answered "nothing in the
    -- Adventure Guide matches" for a full minute, and a raid mount's chase
    -- silently lost its "kill this boss" step.
    --
    -- Only the third is remembered. A refusal is not written at all; a first
    -- zero is recorded as HAVING BEEN ASKED, which the read path above treats
    -- as no answer, so the next call searches again and it is the second zero
    -- that becomes a miss.
    if #results > 0 then
        dropCache[name] = { results = results }
    elseif not Blizzard.HasEncounterJournal()
        or Blizzard.IsEncounterJournalOpen() then
        dropCache[name] = nil
    elseif cached and cached.asked then
        dropCache[name] = { at = time() }
    else
        dropCache[name] = { asked = true }
    end

    return results
end

-- ENTERING A NEW WORLD IS A NEW JOURNAL CONTEXT. 0.80.0.
--
-- `Instances.ForgetDrops` was written with the cache and then never called
-- from anywhere -- the dead-writer shape this project keeps finding, here as
-- a dead resetter, while every sibling (`Sets.Forget`, `Group.ForgetShared`,
-- `CN.ClearShortlist`) is wired to the event that invalidates it.
--
-- The search reads and restores the Adventure Guide's current instance and
-- difficulty, so a zone or instance change is the moment its answers -- and
-- especially its cached misses -- are worth asking again.
CN:RegisterEvent("PLAYER_ENTERING_WORLD", function()
    Instances.ForgetDrops()
end)

-- The one-line version, for a tooltip or a chase step.
function Instances.DescribeSource(name)
    local results = Instances.WhereDoesItDrop(name)

    if #results == 0 then
        return nil
    end

    local first = results[1]

    local text = tostring(first.encounter or "a boss")

    if first.instance then
        text = text .. " in " .. first.instance
    end

    -- THE DIFFICULTY THIS REPORTED WAS NOT THE DROP'S.
    --
    -- It came from `EJ_GetDifficulty()`, which answers with the difficulty
    -- the Encounter Journal happens to be SET to -- a window the player may
    -- have opened once and left on Normal. So a Mythic-only mount was
    -- confidently labelled "Normal", and the sentence below explaining why
    -- that distinction matters made the wrong label worse: it told the reader
    -- to trust it.
    --
    -- A mount that only drops on Mythic is indeed a different plan from one
    -- that drops on Normal -- which is exactly why a guess is not good enough
    -- here. The client offers no per-item difficulty, so the label is now
    -- shown only when the journal's setting is genuinely what was queried,
    -- and is named as such rather than presented as a property of the drop.
    if first.difficulty then
        -- The convention's own word, not a fifth phrasing of it. This is an
        -- answer about one difficulty presented as an answer about the drop,
        -- which is exactly what "estimated" is for.
        text = CN.WithConfidence(text, CN.confidence.ESTIMATED)
            .. " " .. CN.Muted("(searched on " .. first.difficulty .. ")")
    end

    if #results > 1 then
        text = text .. " (and " .. (#results - 1) .. " other "
            .. (#results == 2 and "encounter" or "encounters") .. ")"
    end

    return text, first
end

-- Is the player locked to the instance a drop comes from? This is the
-- difference between "go and kill it" and "not until Tuesday".
-- ONE NAME, SEVERAL LOCKOUTS. FIXED IN 0.61.0.
--
-- The client returns one saved-instance row PER DIFFICULTY, and they all
-- carry the same name. This returned the first one it walked past, so a
-- player who had cleared Heroic and never set foot in Normal was told they
-- were locked out of the drop -- and a player who had cleared Mythic but not
-- Normal was told they could still go. Wrong in both directions, and the
-- direction depended on the order the client happened to hand back its rows.
--
-- The caller knows the difficulty only sometimes, so:
--
--   * given a difficulty, match it exactly;
--   * otherwise prefer a lockout that is NOT complete, because an open
--     difficulty means the answer to "can I go and kill it" is yes;
--   * otherwise the first, which is now known to be one of several closed
--     ones and says the same thing whichever it is.
--
-- Returns lockout, count -- where count is how many share the name, so a
-- caller can say "on this difficulty" rather than implying there is only one.
function Instances.LockoutFor(instanceName, difficulty)
    if not instanceName then
        return nil, 0
    end

    local matches, first, open, exact = 0, nil, nil, nil

    for _, lockout in ipairs(Instances.Lockouts()) do
        if lockout.name == instanceName then
            matches = matches + 1

            first = first or lockout

            if difficulty and lockout.difficulty == difficulty then
                exact = exact or lockout
            end

            if not lockout.complete then
                open = open or lockout
            end
        end
    end

    if matches == 0 then
        return nil, 0
    end

    return exact or open or first, matches
end

------------------------------------------------------------
-- FORMATTING
------------------------------------------------------------

-- ALWAYS A STRING. FIXED IN 0.61.0.
--
-- `Vault.FormatReset` returns nil for a nil input -- deliberately, so the
-- Vault can decide whether to print a row at all -- and this delegated to it
-- and returned that nil straight through, past its own "unknown" fallback.
-- Both call sites below CONCATENATE the answer, so any lockout the client
-- had not yet given a reset time for threw
-- "attempt to concatenate a nil value" out of `/cn drops` and out of the
-- instance list, which is exactly the moment right after a loading screen
-- when a player is most likely to be looking at either.
--
-- The nil check goes AFTER the delegation, not instead of it.
function Instances.FormatReset(seconds)
    local vault = CN:GetModule("Vault")

    if vault and vault.FormatReset then
        local text = vault.FormatReset(seconds)

        if text then
            return text
        end
    end

    if not seconds then
        return "unknown"
    end

    return math.max(1, math.floor(seconds / 3600)) .. "h"
end

function Instances.Describe(lockout)
    local text = lockout.name

    if lockout.difficulty then
        text = text .. " |cff8a8f96(" .. lockout.difficulty .. ")|r"
    end

    if lockout.encounters > 0 then
        text = text .. ": " .. lockout.defeated .. " of " .. lockout.encounters
    end

    if lockout.complete then
        return text .. " |cff73b873cleared|r"
    end

    return text .. " |cffffc74f" .. lockout.remaining .. " left|r"
        .. " |cff8a8f96resets in " .. Instances.FormatReset(lockout.resetsIn) .. "|r"
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- How near the reset the lockout has to be, and how few bosses have to be
-- left, before an unfinished lockout is a next action rather than a plan for
-- the week. Same shape as the Vault's rule, and for the same reason.
Instances.maxRemaining = 6

local function Urgency(remaining, resetsIn, defeated)
    local value = 0

    -- Already started is the whole point: those kills are spent effort that
    -- expires. Nothing started is just "a dungeon exists".
    if defeated and defeated > 0 then
        value = value + 2
    end

    if remaining then
        if remaining <= 1 then
            value = value + 3
        elseif remaining <= 3 then
            value = value + 2
        else
            value = value + 1
        end
    end

    if resetsIn then
        local days = resetsIn / 86400

        if days <= 1 then
            value = value + 3
        elseif days <= 2 then
            value = value + 2
        elseif days <= 4 then
            value = value + 1
        end
    end

    return value
end

Instances.Urgency = Urgency

CN.RegisterCandidateProvider("Instances", function()
    local candidates = {}

    for _, lockout in ipairs(Instances.Lockouts()) do
        -- THE LOCKOUT'S OWN ID, NOT ITS LOCALIZED NAME.
        --
        -- The objective's `id` was `lockout.name` -- the display string. Two
        -- lockouts of the same instance at different difficulties are the
        -- ordinary case in retail, and both produced the key INSTANCE:<name>,
        -- so the aggregate deduplicated them and ONE OF THE TWO SILENTLY
        -- VANISHED from every list -- with the loser's reasons ("3 of 8
        -- already defeated") merged onto the wrong difficulty.
        --
        -- It also meant the ignore store was keyed on a translated string:
        -- ignoring Heroic ignored Normal too, and every ignore was lost the
        -- day the player changed client language.
        local key = lockout.id
            or (tostring(lockout.instanceID or lockout.name) .. ":"
                .. tostring(lockout.difficultyID or 0))

        -- A cleared lockout is not an objective, and a lockout nobody has
        -- started is a decision about the evening rather than a next action.
        if not lockout.complete
            and lockout.defeated > 0
            and lockout.remaining > 0
            and lockout.remaining <= Instances.maxRemaining
            and not CN.IsIgnored(CN.objectiveTypes.INSTANCE, key)
            and not CN.IsDeferred(CN.objectiveTypes.INSTANCE, key) then

            local reasons = {
                lockout.defeated .. " of " .. lockout.encounters
                    .. " already defeated" .. CN.DASH .. "those kills expire at the reset",
                lockout.remaining .. " "
                    .. CN.Pluralize(lockout.remaining, "boss", "bosses") .. " left",
            }

            if lockout.resetsIn then
                table.insert(reasons, "resets in " .. Instances.FormatReset(lockout.resetsIn))
            end

            if lockout.extended then
                table.insert(reasons, "you extended this lockout deliberately")
            end

            table.insert(candidates, CN.NewObjective({
                id               = key,
                type             = CN.objectiveTypes.INSTANCE,
                name             = lockout.name
                    .. (lockout.difficulty and (" (" .. lockout.difficulty .. ")") or ""),
                accountWide      = false,
                completionValue  = lockout.raid and 6 or 4,
                -- ONE DEADLINE, ONE CURVE. 0.88.0. See the note on the
                -- vault row: `expiresIn` below hands the same reset to the
                -- scorer's own urgency term, and `/cn urgency` plots only
                -- that one. The sibling this file shares the defect with.
                limitedTimeBonus = Urgency(lockout.remaining, nil,
                    lockout.defeated),

                -- DECLARED. 0.89.0. See the sibling in `Modules/Vault.lua`:
                -- this term is how close the lockout is to being cleared,
                -- not when it resets, and the reset is charged once through
                -- `expiresIn` below.
                limitedTimeBonusIsProgress = true,
                -- No map coordinate, but not "location unknown" either: the
                -- group finder is one click. Same figure the Vault uses.
                travelCost       = 3,
                expiresIn        = lockout.resetsIn,
                reasons          = reasons,
            }))
        end
    end

    return candidates
end, {
    -- A lockout changes when a boss dies or when the reset happens, and
    -- nothing else. UPDATE_INSTANCE_INFO is the client saying so.
    events   = { "UPDATE_INSTANCE_INFO", "BOSS_KILL", "ENCOUNTER_END" },
    volatile = true,
    cooldown = 30,
})

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "instances",
    aliases = { "lockouts", "saved" },
    order   = 24,
    help    = "What you are saved to, and how much of it is left.",
    handler = function()
        local lockouts = Instances.Lockouts()

        if #lockouts == 0 then
            Print("You are not saved to anything.")
            Print("|cff8a8f96Lockouts appear here as soon as you kill a boss "
                .. "in a dungeon or raid that saves you.|r")
            return
        end

        Print("Saved to " .. #lockouts
            .. CN.Pluralize(#lockouts, " instance:", " instances:"))

        for _, lockout in ipairs(lockouts) do
            CN.PrintLine("  " .. Instances.Describe(lockout))

            local bosses, note = Instances.RemainingBosses(lockout)

            for _, boss in ipairs(bosses) do
                CN.PrintLine("      |cff8a8f96" .. boss.name .. "|r")
            end

            if note then
                CN.PrintLine("      |cff8a8f96" .. note .. "|r")
            end
        end

        local summary = Instances.Summary()

        if summary.unfinished > 0 then
            Print(summary.bosses .. " "
                .. CN.Pluralize(summary.bosses, "boss", "bosses")
                .. " still available across "
                .. summary.unfinished
                .. CN.Pluralize(summary.unfinished, " lockout.", " lockouts."))
        else
            Print("|cff8a8f96Everything you are saved to is cleared.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "drops",
    args    = "<name>",
    order   = 25,
    help    = "Which boss drops something, and whether you are locked to it.",
    handler = function(args)
        args = CN.Trim(args or "")

        if args == "" then
            Print("Usage: /cn drops <name of a mount, pet or item>")
            return
        end

        if not Blizzard.HasEncounterJournal() then
            Print("The Adventure Guide is not available in this client.")
            return
        end

        if Blizzard.IsEncounterJournalOpen() then
            -- Reading the journal moves its selection, which is what the
            -- player is looking at. Refuse rather than reach into it.
            Print("Close the Adventure Guide first" .. CN.DASH .. "reading it would change "
                .. "what you are looking at.")
            return
        end

        local results = Instances.WhereDoesItDrop(args)

        if #results == 0 then
            Print("Nothing in the Adventure Guide matches \"" .. args .. "\".")
            Print("|cff8a8f96Not everything drops from a boss; try the exact "
                .. "name the journal uses.|r")
            return
        end

        Print("\"" .. args .. "\" " .. CN.DASH .. " " .. #results
            .. CN.Pluralize(#results, " encounter:", " encounters:"))

        for _, result in ipairs(results) do
            local line = "  " .. tostring(result.encounter or "?")

            if result.instance then
                line = line .. " |cff8a8f96in " .. result.instance .. "|r"
            end

            -- `x and f()` TRUNCATES TO ONE VALUE.
            --
            -- Written as `local a, b = cond and f()`, Lua adjusts the `and`
            -- expression to a single result, so `sharing` was always nil and
            -- the "on Heroic" clause below could never appear. Caught by
            -- luacheck as "variable is never set", which is exactly what it
            -- was -- and would have been invisible in play, because a missing
            -- clause looks like a lockout that is simply not shared.
            local lockout, sharing

            if result.instance then
                lockout, sharing = Instances.LockoutFor(result.instance)
            end

            if lockout then
                if lockout.complete then
                    -- "locked until 2d 3h" reads as a date and is a
                    -- DURATION. `FormatReset` returns "2d 3h"; the only
                    -- preposition that fits it is "for", and "resets in" is
                    -- the phrasing every other lockout line in the addon
                    -- already uses. 0.61.0.
                    line = line .. " |cffe2564clocked, resets in "
                        .. Instances.FormatReset(lockout.resetsIn)
                        .. ((sharing or 1) > 1
                            and (" on " .. tostring(lockout.difficulty
                                or "this difficulty"))
                            or "")
                        .. "|r"
                else
                    line = line .. " |cffffc74f" .. lockout.remaining
                        .. " left on your lockout|r"
                end
            end

            CN.PrintLine(line)
        end
    end,
}

return Instances
'@

$Embedded['Modules\Preference.lua'] = @'
-- Modules/Preference.lua
-- Completion Navigator :: learning what you actually do.
--
-- THE PROBLEM.
--
-- The ranking has always been the addon's opinion. It is a good opinion --
-- deadlines first, batching second, travel cost third -- but it is the same
-- opinion for everybody, and people do not play the same way. Somebody who
-- has never once gone out of their way for a battle pet gets pets in their
-- list forever, and the addon never notices.
--
-- Hiding the type is the blunt fix and it already exists. This is the fine
-- one: notice what you take up, notice what you scroll past, and lean.
--
-- WHAT IS MEASURED.
--
--   shown   -- the objective was actually put in front of you, via the
--              recommendation hook, which fires on the handful that were
--              displayed rather than the two hundred that were considered.
--   acted   -- it was completed, or its type was, within the window below.
--
-- A ratio of those two, per objective TYPE, on this character.
--
-- WHY TYPE AND NOT THE OBJECTIVE ITSELF.
--
-- Because an individual objective is shown a handful of times before it is
-- either done or gone, which is far too little to learn anything from. A type
-- accumulates hundreds of observations in a week of play. Learning per
-- objective would be learning noise, and dressing it up as personalisation.
--
-- THE GUARDRAILS, WHICH MATTER MORE THAN THE LEARNING.
--
--   * Nothing happens below `minimumObservations`. Until then the multiplier
--     is exactly 1 and the addon behaves as it always did.
--   * The adjustment is CLAMPED, hard. A type you ignore is quieter, never
--     silent -- silencing a type is a decision for you to make in /cn show,
--     not one for a counter to make on your behalf.
--   * It is EXPLAINED. Every adjusted line carries a reason saying so. A
--     ranking that changed for reasons the player cannot see is a ranking
--     they cannot trust.
--   * It DECAYS. Somebody who spent a month on transmog and has now moved on
--     should not be arguing with a month-old opinion forever.
--   * `/cn learned` shows the whole table, and `/cn learned reset` throws it
--     away. Nothing here is permanent and nothing here is hidden.

local ADDON_NAME, CN = ...

local Preference = CN:RegisterModule("Preference")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- TUNING
------------------------------------------------------------

-- How many times a type has to have been shown before its ratio is allowed
-- to move anything at all. Deliberately high: the cost of learning too early
-- is a ranking that lurches around in the player's first evening, which reads
-- as the addon being unreliable rather than adaptive.
Preference.minimumObservations = 25

-- The window in which finishing something counts as having acted on it.
--
-- Twenty minutes suits a quest. It does not suit a raid lockout, which takes
-- an evening, or a reputation, which takes a week -- and crediting those at
-- twenty minutes meant the addon concluded the player ignores exactly the
-- things that take longest to do.
--
-- Per type, therefore, with the old figure as the default. These are not
-- measured -- they are how long the ACTIVITY takes, which the addon cannot
-- observe before the fact -- so they are stated plainly as judgements rather
-- than dressed up as data.
Preference.actionWindowSeconds = 1200

-- ONLY THE TYPES THAT CAN BE CREDITED. 0.86.0.
--
-- `WindowFor` is reached only after `Preference.IsCreditable` has passed, and
-- from `NoteCompleted`, whose only caller is the completion-event loop at the
-- bottom of this file. `Preference.creditableTypes` is QUEST, ACHIEVEMENT,
-- PET, MOUNT and TOY -- so INSTANCE, REPUTATION, RENOWN, PROFESSION and
-- APPEARANCE could never reach this table. Five of the six entries added in
-- 0.46.0 became unreachable when 0.55.0 added the creditability gate, and the
-- header above still explains at length why a raid needs a longer window than
-- an appearance.
--
-- Nothing on screen changed; what changed is that the next reader will not
-- retune a number and watch nothing happen. They go back in the same change
-- that starts crediting one of those types, and not before.
Preference.actionWindows = {
    [CN.objectiveTypes.ACHIEVEMENT] = 3600,
}

function Preference.WindowFor(objectiveType)
    return Preference.actionWindows[objectiveType]
        or Preference.actionWindowSeconds
end

-- The full range of the multiplier. A type you always act on gets a modest
-- push; one you never touch gets a modest shove. Both are small on purpose --
-- this is a thumb on the scale, not a second scoring system.
Preference.minMultiplier = 0.80
Preference.maxMultiplier = 1.25

-- Above this ratio the type is "one you act on", below it "one you skip".
-- Not 0.5: most recommendations are not acted on immediately by anybody,
-- because the list is longer than the evening.
Preference.actedThreshold = 0.25

-- Counters are halved when either passes this, so the table reflects how you
-- play now rather than how you played in June.
Preference.decayAt = 400

------------------------------------------------------------
-- THE STORE
------------------------------------------------------------

-- Per character, because how you play a levelling alt is not how you play the
-- character you raid on. Two integers per type: about as cheap as a store in
-- this addon gets, and nothing here cannot be thrown away.
local function Store()
    local character = CN.character

    if not character then
        return nil
    end

    character.preference = character.preference or {}

    return character.preference
end

Preference.Store = Store

local function Row(objectiveType)
    local store = Store()

    if not store or not objectiveType then
        return nil
    end

    store[objectiveType] = store[objectiveType] or { shown = 0, acted = 0 }

    return store[objectiveType]
end

function Preference.IsEnabled()
    local settings = CN.Settings()

    -- On by default, but a real setting: someone who wants the addon's
    -- opinion and only the addon's opinion is entitled to have it.
    return not settings or settings.learnPreferences ~= false
end

function Preference.SetEnabled(enabled)
    local settings = CN.Settings()

    if settings then
        -- Store false to turn it OFF and nil to turn it back on: the default
        -- is on, so "nil" and "off" must not be the same stored value.
        --
        -- Written as an if rather than as `x and false or nil`, which is how
        -- it was written first: in Lua that expression can never produce
        -- false, because `and false` is falsy and falls straight through to
        -- the `or`. It read correctly and did nothing.
        if enabled then
            settings.learnPreferences = nil
        else
            settings.learnPreferences = false
        end
    end

    -- The observation generation is what the multiplier cache is keyed on
    -- now, and switching the whole feature off changes every multiplier.
    Preference.observationGeneration = Preference.observationGeneration + 1

    CN.InvalidateRanking()
end

------------------------------------------------------------
-- MEMOISATION
------------------------------------------------------------

-- MEMOISED, because this runs on every candidate in the list.
--
-- Ranking scores a few thousand objectives, and without this each one of them
-- resolved the settings proxy, found the character table and did the
-- arithmetic again for an answer that changes a few times an hour. Measured,
-- the uncached version doubled the cost of Recommend(25).
--
-- The key is both generations: the ranking one, bumped when something the
-- player did changes the order, and the observation one, bumped whenever a
-- counter moves. Between them nothing can go stale.
local multiplierCache   = {}

Preference.observationGeneration = 0

local function Observed()
    Preference.observationGeneration = Preference.observationGeneration + 1
end

-- Published, because the multiplier cache is keyed on this generation and
-- anything that writes the preference store from outside this file -- the
-- test suite, a future import -- has to be able to say so. Before 0.54.0 the
-- key also carried `CN.rankingGeneration`, so a bare `InvalidateRanking()`
-- happened to clear the cache; that was never the contract, it was a side
-- effect of a key that threw the cache away every two seconds.
Preference.NoteStoreChanged = Observed

-- TWO NUMBERS COMPARED, NOT A STRING BUILT TO COMPARE.
--
-- `Multiplier` is asked twice per objective in the ordinary case, and this
-- built a fresh string on every call purely so it could be compared against
-- the previous one. Measured over a hundred and fifty calls: 81% of the
-- function's entire cost was the string, against 6% for the comparison it
-- existed to perform.
--
-- AND `rankingGeneration` DOES NOT BELONG IN THE KEY. The multiplier is a
-- function of the preference store and the learn setting; the store is what
-- `observationGeneration` tracks. `rankingGeneration` is bumped by every
-- `BuildZoneRoute`, so opening the Zone tab threw away a cache of at most
-- twenty entries that could otherwise have stood for minutes.
local multiplierObservation = -1

------------------------------------------------------------
-- OBSERVING
------------------------------------------------------------

-- What was shown, and when. In memory only: this is a question about the last
-- twenty minutes, and twenty minutes does not survive a logout in any useful
-- form.
local shownAt = {}

-- Which sub-bucket each sighting was filed under, so the completion side can
-- credit the same bucket the showing side incremented.
local shownRefinement = {}

-- BOUNDED, THE SAME WAY SESSION'S OFFER MEMORY IS.
--
-- `shownAt` gained an entry per distinct objective ever put in front of the
-- player and lost one only on a successful action or on the expired branch,
-- so anything shown and never acted on stayed forever. `shownRefinement` was
-- worse: the success path cleared `shownAt[key]` and left the refinement
-- entry behind unconditionally -- and that is the table the fallback match
-- loop runs a `string.sub` over on every NEW_PET_ADDED, NEW_MOUNT_ADDED and
-- NEW_TOY_ADDED.
--
-- Session next door carries the identical structure with an expiry and a cap
-- and a comment calling the unbounded version "a slow leak I shipped in
-- 0.28.0". The same shape was reintroduced here. Same two bounds, same
-- hysteresis, same reason.
local shownCount = 0

Preference.sightingCap     = 400
Preference.sightingSeconds = 1800
Preference.sightingSlack   = 0.25

-- Removing a sighting means removing it from both tables. Every path that
-- used to touch only one of them is why this is a function.
local function Forget(key)
    if shownAt[key] ~= nil then
        shownCount = shownCount - 1
    end

    shownAt[key]         = nil
    shownRefinement[key] = nil
end

Preference.Forget = Forget

local function Now()
    return (GetTime and GetTime()) or (time and time()) or 0
end

Preference.Now = Now

-- Overshoot by a quarter, then sweep back to the cap -- pruning on every
-- insert would walk four hundred entries per recommendation, which is the
-- trade Session already refused to make.
function Preference.Prune(force)
    local trigger = Preference.sightingCap * (1 + Preference.sightingSlack)

    if not force and shownCount <= trigger then
        return 0
    end

    local now     = Now()
    local removed = 0

    for key, at in pairs(shownAt) do
        if (now - at) > Preference.sightingSeconds then
            Forget(key)
            removed = removed + 1
        end
    end

    if shownCount > Preference.sightingCap then
        local ordered = {}

        for key, at in pairs(shownAt) do
            table.insert(ordered, { key = key, at = at })
        end

        table.sort(ordered, function(a, b)
            if a.at == b.at then
                return a.key < b.key
            end

            return a.at < b.at
        end)

        for index = 1, shownCount - Preference.sightingCap do
            if ordered[index] then
                Forget(ordered[index].key)
                removed = removed + 1
            end
        end
    end

    -- A refinement entry with no sighting behind it is unreachable, and this
    -- is the table the fallback loop walks.
    for key in pairs(shownRefinement) do
        if shownAt[key] == nil then
            shownRefinement[key] = nil
        end
    end

    return removed
end

function Preference.SightingCount()
    return shownCount
end

-- Hung on the recommendation hook rather than a decorator, deliberately.
-- Duration learning made exactly this mistake in 0.28.0 and timed all two
-- hundred candidates on every rebuild, including the hundred and seventy
-- nobody ever saw.
CN.RegisterRecommendationHook("Preference", function(results)
    if not Preference.IsEnabled() then
        return
    end

    local now = Now()

    local store = Store()

    if not store then
        return
    end

    for _, objective in ipairs(results or {}) do
        local objectiveType = objective and objective.type

        -- Don't count sightings the addon can never pair with a completion.
        -- A row that can only ever read "0 of 300" is not data; it is a
        -- persisted misunderstanding, and it was being spent on every one of
        -- the thirteen uncreditable types. See `Preference.creditableTypes`.
        if objectiveType and not Preference.IsCreditable(objectiveType) then
            objectiveType = nil
        end

        if objectiveType then
            local row = store[objectiveType]

            if not row then
                row = { shown = 0, acted = 0 }

                store[objectiveType] = row
            end

            if row then
                -- ONE OBSERVATION PER APPEARANCE, NOT PER REDRAW.
                --
                -- The window redraws on a great many events, and the same
                -- three lines are "shown" on every one of them. Counting
                -- those would mean an open window taught the addon that you
                -- ignore everything, at a rate of several observations a
                -- second, purely for leaving it open.
                -- Built once and kept on the objective. This runs on
                -- every redraw of an open window, and the concatenation was
                -- the most expensive thing in it -- for a string that cannot
                -- change while the objective exists.
                local key = objective.preferenceKey

                if not key then
                    key = objectiveType .. ":" .. tostring(objective.id)

                    objective.preferenceKey = key
                end

                local last = shownAt[key]

                -- FINER THAN A TYPE, WHERE THE TYPE IS TOO COARSE.
                --
                -- "Quests" is one bucket containing two quite different
                -- habits: people who follow the story, and people who clear
                -- everything. Somebody who always does the campaign and never
                -- touches side quests looks, at type resolution, like
                -- somebody with no opinion at all -- the rate averages to the
                -- middle and nothing moves.
                --
                -- Only quests get this. Every other type is one habit, and
                -- six buckets that each learn nothing beat none at all.
                local refined = Preference.Refine(objective)

                -- Keyed on `key`, which is what `shownAt` is keyed on and
                -- what the completion side matches against. It used to
                -- rebuild the string from the type and id, which is the same
                -- thing only while `objective.preferenceKey` has not been set
                -- to something else -- and a refinement filed under a key
                -- nothing looks up is a refinement that never credits.
                shownRefinement[key] = refined

                if refined ~= objectiveType then
                    local refinedRow = store[refined]

                    if not refinedRow then
                        refinedRow = { shown = 0, acted = 0 }

                        store[refined] = refinedRow
                    end

                    -- The SAME window as the counter twelve lines below, and
                    -- for the same reason. This one kept the flat default
                    -- that 0.46.0 replaced with per-type windows, so the
                    -- moment a quest window is added to Preference.
                    -- actionWindows the two counters silently disagree and
                    -- the refined buckets over-count what was shown.
                    if not last
                        or (now - last) > Preference.WindowFor(objectiveType) then

                        refinedRow.shown = refinedRow.shown + 1
                    end
                end

                if not last
                    or (now - last) > Preference.WindowFor(objectiveType) then

                    row.shown = row.shown + 1

                    Observed()

                    -- Only when a counter actually moved. Decaying on every
                    -- call meant walking the whole table on every redraw of
                    -- the window to discover, almost always, that nothing had
                    -- reached the threshold -- the same shape of waste the
                    -- 0.28.0 duration bug was.
                    Preference.Decay()
                end

                if shownAt[key] == nil then
                    shownCount = shownCount + 1
                end

                shownAt[key] = now

                Preference.Prune()
            end
        end
    end
end)

-- Types whose completion event carries the same id the recommendation did.
-- For these an inexact match is not evidence of anything.
Preference.exactIdEvents = {
    [CN.objectiveTypes.QUEST]       = true,
    [CN.objectiveTypes.ACHIEVEMENT] = true,
}

------------------------------------------------------------
-- WHAT THE ADDON CAN ACTUALLY WATCH YOU DO
------------------------------------------------------------

-- THE HALF OF THE SUBJECT MATTER THAT WAS BEING PUNISHED FOR THE ADDON'S OWN
-- DEAFNESS.
--
-- `shown` was counted for every type a provider emits. `acted` was counted
-- only for the five types the client announces a completion for -- quests,
-- achievements, pets, mounts and toys. For the other thirteen the ratio was
-- structurally, permanently zero: not "you ignore these", but "nobody is
-- listening". Past `minimumObservations` sightings, every one of them settled
-- on the 0.80 floor and stayed there for the life of the character.
--
-- Two things were wrong with that, and the second is worse than the first.
--
--   * A uniform, invisible, unearned demotion of reputations, renown,
--     appearances, recipes, professions, rares, treasures, exploration,
--     titles, currencies, vendors, collectibles and lockouts -- against
--     quests and achievements, which could be credited. The addon's own
--     ranking quietly decided that half of what it recommends is not worth
--     doing, on no evidence at all.
--
--   * `/cn learned` then printed "you rarely act on these" beside them. That
--     is a statement about the player, and it is false. The addon has never
--     been able to see whether you collected that appearance. Saying
--     otherwise on the strength of a counter that cannot move is the one
--     thing this addon promises never to do.
--
-- So: a type earns an opinion only if there is a path by which it could be
-- credited. Everything else returns a flat 1 and says nothing. When a future
-- release learns to observe a type -- a currency threshold crossed, a rare's
-- loot received -- it is added here in the same commit that starts crediting
-- it, and not before.
Preference.creditableTypes = {
    [CN.objectiveTypes.QUEST]       = true,
    [CN.objectiveTypes.ACHIEVEMENT] = true,
    [CN.objectiveTypes.PET]         = true,
    [CN.objectiveTypes.MOUNT]       = true,
    [CN.objectiveTypes.TOY]         = true,

    -- The refinements of QUEST, which are credited through the same event.
    QUEST_CAMPAIGN = true,
    QUEST_SIDE     = true,
}

-- Whether a preference multiplier may be computed for this type at all.
function Preference.IsCreditable(objectiveType)
    if not objectiveType then
        return false
    end

    return Preference.creditableTypes[objectiveType] == true
end

-- Called when something is genuinely finished. Credited only if the addon had
-- recommended it recently -- otherwise every quest anybody turns in would
-- count as the addon's advice being taken, which would teach it that its
-- opinion is always right.
-- The sub-bucket an objective belongs in, or its plain type when it has none.
--
-- MEMOISED ON THE OBJECTIVE, like `preferenceKey` twenty lines below and for
-- exactly the same reason. This is one protected client call --
-- `C_CampaignInfo.GetCampaignID` -- and the adjuster's first statement, so
-- it ran once per quest candidate per scoring pass: measured at 130 calls
-- for `Recommend(5)` over 148 candidates, and 130 again on the next re-rank
-- with nothing changed, while `BuildZoneRoute` bumps the ranking generation
-- from the Zone tab's two-second refresh, follow mode's ticker and every map
-- open.
--
-- Whether a quest is part of a campaign is a fact about the quest and does
-- not change while the client is running, so the answer is kept for the
-- session -- on the objective, so it dies with the candidate.
function Preference.Refine(objective)
    if not objective or objective.type ~= CN.objectiveTypes.QUEST then
        return objective and objective.type
    end

    local held = objective.preferenceBucket

    if held then
        return held
    end

    -- The game's own campaign data, which is what Loremaster already uses to
    -- keep "the story" and "everything else" apart.
    local bucket = "QUEST_SIDE"

    if CN.Blizzard and CN.Blizzard.IsQuestCampaign
        and CN.Blizzard.IsQuestCampaign(objective.id) then

        bucket = "QUEST_CAMPAIGN"
    end

    objective.preferenceBucket = bucket

    return bucket
end

-- Which sub-bucket a recorded sighting belonged to.
--
-- The showing side files an objective under both its plain type and its
-- refinement; the completion side sees only a type and an id, and the id is
-- not always the one that was recommended. So the refinement is remembered
-- when the sighting is recorded, keyed the same way.
function Preference.RefinedKeyFor(key, objectiveType)
    local remembered = shownRefinement[key]

    if remembered then
        return remembered
    end

    return objectiveType
end

function Preference.NoteCompleted(objectiveType, objectiveID)
    if not Preference.IsEnabled() or not objectiveType then
        return false
    end

    local now = Now()

    local key = objectiveType .. ":" .. tostring(objectiveID)

    local last = shownAt[key]

    -- THE ID THE EVENT CARRIES IS NOT ALWAYS THE ID THAT WAS RECOMMENDED.
    --
    -- NEW_PET_ADDED reports the unique pet you now own; the recommendation was
    -- about the species. NEW_MOUNT_ADDED and the transmog events have the same
    -- shape of mismatch. For those, fall back to "was anything of this type
    -- recommended in the window", since what is being learned is per type
    -- anyway.
    --
    -- NOT for quests and achievements. Those events carry exactly the id that
    -- was recommended, so a fallback there would credit the addon for every
    -- quest anybody turns in merely because it had mentioned some other quest
    -- in the last twenty minutes -- and on a levelling character it has always
    -- mentioned some other quest in the last twenty minutes. That is not
    -- learning, it is a counter that only goes up.
    if not last and not Preference.exactIdEvents[objectiveType] then
        local fallbackKey

        for candidateKey, when in pairs(shownAt) do
            if (now - when) <= Preference.WindowFor(objectiveType)
                and string.sub(candidateKey, 1, #objectiveType + 1)
                    == (objectiveType .. ":") then

                -- The most recently shown one, so a stale sighting from
                -- nineteen minutes ago does not get the credit.
                if not fallbackKey or when > shownAt[fallbackKey] then
                    fallbackKey = candidateKey
                end
            end
        end

        if not fallbackKey then
            return false
        end

        key  = fallbackKey
        last = shownAt[fallbackKey]
    end

    -- Still nothing: this was never recommended, so it teaches us nothing.
    -- Reaching the arithmetic below with a nil here threw inside a
    -- QUEST_TURNED_IN handler -- a learning feature breaking quest turn-ins
    -- would be a spectacularly bad trade.
    if not last then
        return false
    end

    if (now - last) > Preference.WindowFor(objectiveType) then
        Forget(key)

        return false
    end

    local row = Row(objectiveType)

    if not row then
        return false
    end

    row.acted = row.acted + 1

    -- AND THE REFINED BUCKET, WHICH WAS NEVER CREDITED AT ALL.
    --
    -- The showing side increments both the plain type and the campaign/side
    -- sub-bucket; this side incremented only the plain type. So the refined
    -- rows accumulated sightings and no actions, drifted to the floor
    -- multiplier, and the score adjuster PREFERS the refined row whenever its
    -- multiplier is not 1 -- meaning the plain row that held the true answer
    -- was correct and unreachable.
    --
    -- Measured: a player who turned in all 120 quests they were shown was
    -- told, after an hour or two, that they "rarely act on these", and every
    -- quest was multiplied by 0.80 permanently.
    --
    -- The id is not always available here (some events carry a different one
    -- than was recommended), so the bucket is recovered from the key that was
    -- actually matched.
    local refined = Preference.RefinedKeyFor(key, objectiveType)

    if refined and refined ~= objectiveType then
        local store = Store()

        local refinedRow = store and store[refined]

        if refinedRow then
            refinedRow.acted = (refinedRow.acted or 0) + 1
        end
    end

    Observed()

    -- BOTH TABLES. Clearing only `shownAt` here is what left an entry in
    -- `shownRefinement` for every objective the player ever acted on.
    Forget(key)

    CN.InvalidateRanking()

    DebugPrint("Acted on a " .. objectiveType .. " that was recommended.")

    return true
end

-- Halve everything once the counts get large, so the table tracks how you
-- play now. Halving keeps the RATIO and forgets the certainty, which is
-- exactly the right thing to forget.
function Preference.Decay()
    local store = Store()

    if not store then
        return false
    end

    local decayed = false

    for _, row in pairs(store) do
        if row.shown >= Preference.decayAt then
            row.shown = math.floor(row.shown / 2)
            row.acted = math.floor(row.acted / 2)

            Observed()

            decayed = true
        end
    end

    return decayed
end

------------------------------------------------------------
-- THE ADJUSTMENT
------------------------------------------------------------

-- Returns the multiplier and, when it is not 1, a sentence saying why.
function Preference.Multiplier(objectiveType)
    if not objectiveType then
        return 1, nil
    end

    if multiplierObservation ~= Preference.observationGeneration then
        multiplierCache        = {}
        multiplierObservation  = Preference.observationGeneration
    end

    local cached = multiplierCache[objectiveType]

    if cached then
        return cached[1], cached[2]
    end

    local multiplier, reason = Preference.Compute(objectiveType)

    multiplierCache[objectiveType] = { multiplier, reason }

    return multiplier, reason
end

function Preference.Compute(objectiveType)
    if not Preference.IsEnabled() then
        return 1, nil
    end

    -- No completion path, no opinion. See `Preference.creditableTypes`.
    if not Preference.IsCreditable(objectiveType) then
        return 1, nil
    end

    local store = Store()

    local row = store and store[objectiveType]

    if not row or row.shown < Preference.minimumObservations then
        return 1, nil
    end

    local ratio = row.acted / row.shown

    if ratio >= Preference.actedThreshold then
        -- Scale across the range above the threshold rather than jumping to
        -- the cap the moment it is crossed.
        local above = math.min(1, (ratio - Preference.actedThreshold)
            / (1 - Preference.actedThreshold))

        local multiplier = 1 + (Preference.maxMultiplier - 1) * above

        return multiplier, "you usually act on these"
    end

    local below = 1 - (ratio / Preference.actedThreshold)

    local multiplier = 1 - (1 - Preference.minMultiplier) * below

    return multiplier, "you rarely act on these"
end

-- Applied in scoring, after the profile's own type weighting, so a focus you
-- chose deliberately always outranks a habit the addon inferred.
CN.RegisterScoreAdjuster("Preference", function(objective, score)
    -- THE GATE BEFORE THE WORK.
    --
    -- `Refine` was called first and `IsEnabled` afterwards, so a player who
    -- had turned learning OFF paid the whole cost of it on every pass and
    -- got nothing. Withdraw first, because a sentence stamped while learning
    -- was on must not outlive it.
    if not Preference.IsEnabled() then
        CN.ClearAdjusterReason(objective, "preference")

        return score
    end

    -- The finer bucket first, and only if it has earned an opinion of its
    -- own. Falling back to the type means a player whose quest habits are
    -- undifferentiated is treated exactly as before.
    local refined = Preference.Refine(objective)

    local multiplier, reason = 1, nil

    if refined and refined ~= (objective and objective.type) then
        multiplier, reason = Preference.Multiplier(refined)
    end

    if multiplier == 1 then
        multiplier, reason = Preference.Multiplier(objective and objective.type)
    end

    -- WHAT IS NO LONGER TRUE IS WITHDRAWN FIRST, which this adjuster never
    -- did and the Group adjuster has since 0.51.0.
    --
    -- The sentence is stamped onto objectives that live in the per-provider
    -- cache, and the cache outlives the opinion. So `/cn learned reset` said
    -- "Forgotten. The ranking is back to its defaults." while `/cn why` went
    -- on printing "you rarely act on these" until some unrelated rebuild
    -- happened to produce a different list. `/cn learned off` did the same,
    -- and so does anything that stops being creditable.
    if multiplier == 1 then
        CN.ClearAdjusterReason(objective, "preference")

        return score
    end

    -- SAY SO. A list that quietly reordered itself is a list nobody can
    -- argue with, and this addon's whole contract is that every line has a
    -- stated reason.
    if reason then
        CN.AddAdjusterReason(objective, "preference", reason)
    end

    return score * multiplier
end)

------------------------------------------------------------
-- WHAT COUNTS AS HAVING ACTED
------------------------------------------------------------

-- Only completions the game announces. Nothing here infers that you did
-- something because you walked near it.
local completionEvents = {
    { event = "QUEST_TURNED_IN",   type = CN.objectiveTypes.QUEST },
    { event = "ACHIEVEMENT_EARNED", type = CN.objectiveTypes.ACHIEVEMENT },
    { event = "NEW_PET_ADDED",     type = CN.objectiveTypes.PET },
    { event = "NEW_MOUNT_ADDED",   type = CN.objectiveTypes.MOUNT },
    { event = "NEW_TOY_ADDED",     type = CN.objectiveTypes.TOY },
}

for _, entry in ipairs(completionEvents) do
    CN:RegisterEvent(entry.event, function(_, id)
        Preference.NoteCompleted(entry.type, id)
    end)
end

Preference.completionEvents = completionEvents

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "learned",
    args    = "[reset or off or on]",
    order   = 34,
    help    = "What the addon has worked out about how you play.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "reset" then
            local character = CN.character

            if character then
                character.preference = nil
            end

            Preference.observationGeneration =
                Preference.observationGeneration + 1

            CN.InvalidateRanking()

            Print("Forgotten. The ranking is back to its defaults.")
            return
        end

        if args == "off" or args == "on" then
            Preference.SetEnabled(args == "on")

            Print("Learning from what you do: "
                .. CN.YesNo(Preference.IsEnabled()))
            return
        end

        local store = Store()

        if not store or next(store) == nil then
            Print("Nothing learned yet.")
            Print("|cff8a8f96The addon watches which kinds of thing you "
                .. "actually go and do, and needs "
                .. Preference.minimumObservations
                .. " sightings of a kind before it acts on anything.|r")
            return
        end

        if not Preference.IsEnabled() then
            Print("|cff8a8f96Learning is switched off; the figures below are "
                .. "not affecting your ranking. |cffffc74f/cn learned on|r "
                .. "re-enables it.|r")
        end

        local filters = CN:GetModule("Filters")

        local rows = {}

        for objectiveType, row in pairs(store) do
            table.insert(rows, { type = objectiveType, row = row })
        end

        table.sort(rows, function(a, b)
            return (a.row.shown or 0) > (b.row.shown or 0)
        end)

        Print("What this character actually does:")

        for _, entry in ipairs(rows) do
            local labels = {
                QUEST_CAMPAIGN = "Story quests",
                QUEST_SIDE     = "Side quests",
            }

            local label = labels[entry.type]
                or (filters and filters.TypeLabel(entry.type))
                or entry.type

            local multiplier, reason = Preference.Multiplier(entry.type)

            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            local line = "  " .. CN.Body(label) .. "  "
                .. entry.row.acted .. " of " .. entry.row.shown
                .. " acted on"

            if not Preference.IsCreditable(entry.type) then
                -- Only reachable from a database written before 0.55.0 and
                -- not yet migrated. Say what it is rather than implying the
                -- counter is on its way somewhere.
                line = line .. " |cff8a8f96(not watched" .. CN.DASH .. "the addon cannot "
                    .. "see when you finish one of these)|r"
            elseif multiplier == 1 then
                local short = Preference.minimumObservations - entry.row.shown

                line = line .. " |cff8a8f96(no effect"
                    .. (short > 0 and (" " .. CN.DASH .. " " .. short .. " more sightings needed")
                        or "")
                    .. ")|r"
            else
                line = line .. string.format(" |cffffc74fx%.2f|r |cff8a8f96%s|r",
                    multiplier, reason or "")
            end

            CN.PrintLine(line)
        end

        Print("|cff8a8f96" .. "/cn learned reset" .. " forgets all of it. "
            .. "Hiding a type outright is |cffffc74f/cn show|r.|r")
    end,
}

return Preference
'@

$Embedded['Modules\Capture.lua'] = @'
-- Modules/Capture.lua
-- Completion Navigator :: recording what the client actually returns.
--
-- THE PROBLEM THIS EXISTS TO END.
--
-- Nine defects in this addon's history came from the same place: the offline
-- test harness modelled the world more simply than the world is, the tests
-- agreed with the model, and the bug shipped. A map point modelled as a flat
-- table when the client wants a vector. A quest list containing no quest
-- starts. An achievement criterion with no counter. Every map modelled as a
-- perfect square, for eight releases, which hid an angle error in every zone
-- in the game.
--
-- `/cn selftest` catches these in play, which is a great deal better than a
-- player catching them, but it is still after the fact. It cannot stop the
-- NEXT optimistic stub from being written, because the author of a stub does
-- not know which part of reality he is simplifying -- that is what makes it a
-- simplification rather than a decision.
--
-- The only thing that ends it is testing against real data. So: record what
-- the client actually returned, on a real character, and let the offline
-- suite check its own stubs against that recording. A stub that is missing a
-- field reality had becomes a test failure instead of a future bug report.
--
-- WHAT IS RECORDED.
--
-- Shapes and small samples, never the player's collections wholesale. The
-- suite needs to know that GetSavedInstanceInfo returns thirteen values in a
-- particular order and that map spans are not square; it does not need
-- eighteen hundred pets.
--
-- WHAT IS NOT RECORDED.
--
-- Character names, realm, guild, anything that identifies the player, and
-- nothing at all unless the command is run deliberately. The file is written
-- into your own SavedVariables and goes nowhere on its own -- this addon has
-- no network access of any kind and never will.

local ADDON_NAME, CN = ...

local Capture = CN:RegisterModule("Capture")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint
local Blizzard   = CN.Blizzard

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

CN.captures = CN.captures or {}

-- definition = {
--     name = "GetSavedInstanceInfo",
--     run  = function() return <plain data>, note end,
-- }
-- THE NAME IS THE KEY THE RESULT IS FILED UNDER, AND IT WAS NOT CHECKED.
--
-- `Capture.Run` writes `records[definition.name]`. A definition registered
-- without a name made that `records[nil] = value`, which throws -- inside the
-- capture run, taking every later capture with it. A definition registered
-- with a name another one already uses silently overwrote it, so a capture
-- ran, cost its time, and produced nothing anybody could find.
function CN.RegisterCapture(definition)
    if type(definition) ~= "table" or type(definition.run) ~= "function" then
        return false, "a capture needs a run function"
    end

    if type(definition.name) ~= "string" or definition.name == "" then
        return false, "a capture needs a name" .. CN.DASH .. "it is the key its result is "
            .. "filed under"
    end

    for _, existing in ipairs(CN.captures) do
        if existing.name == definition.name then
            return false, "a capture named " .. definition.name
                .. " is already registered"
        end
    end

    table.insert(CN.captures, definition)

    return true
end

------------------------------------------------------------
-- SHAPE, NOT CONTENT
------------------------------------------------------------

-- Reduces a value to what a test needs to know about it: its type, and for a
-- table, the shape of its keys. Numbers survive because a range matters --
-- a map span of 4,000 by 2,700 is the whole point of one of these captures --
-- but a list of three thousand achievement IDs collapses to "3000 numbers".
--
-- Bounded by depth and by width, because this is written to disk and read
-- back on every login until it is cleared.
function Capture.Shape(value, depth, width)
    depth = depth or 3
    width = width or 12

    local kind = type(value)

    if kind ~= "table" then
        if kind == "string" and #value > 64 then
            return { type = "string", length = #value }
        end

        return { type = kind, value = (kind == "function" and "function" or value) }
    end

    if depth <= 0 then
        return { type = "table", truncated = true }
    end

    local shape = { type = "table", fields = {}, count = 0, array = 0 }

    -- Methods matter as much as fields: the 0.19.0 bug was a Vector2D whose
    -- GetXY the stub did not have.
    -- THE BUDGET WAS SPENT ON ROWS IT DID NOT RECORD. FIXED IN 0.61.0.
    --
    -- `shape.count` counted EVERY key, array entries included, and the
    -- `count <= width` gate then decided whether to describe a named field.
    -- So a client table with sixty array entries and eight named fields --
    -- which is the ordinary shape of a POI list, a criteria list, a bag --
    -- had its entire field budget consumed before a single named field was
    -- looked at, and the capture recorded none of them.
    --
    -- Worse, it depended on `pairs` ORDER: array entries and named fields
    -- come back interleaved in an order Lua does not promise, so the same
    -- table captured twice produced different field sets. This is the tool
    -- the project uses to write stubs that match the client, and it was
    -- handing back a different answer each run for the tables most worth
    -- capturing.
    --
    -- The budget now counts what it is a budget FOR. `count` still reports
    -- the true size, and `dropped` says what the width cost, so a capture
    -- that hit the limit says so instead of looking complete.
    local described = 0

    for key, entry in pairs(value) do
        shape.count = shape.count + 1

        if type(key) == "number" then
            shape.array = shape.array + 1
        elseif type(key) == "string" then
            if described < width then
                described = described + 1

                shape.fields[key] = Capture.Shape(entry, depth - 1, width)
            else
                shape.dropped = (shape.dropped or 0) + 1
            end
        end
    end

    if getmetatable(value) then
        shape.metatable = true
    end

    return shape
end

------------------------------------------------------------
-- WHAT GETS CAPTURED
------------------------------------------------------------

CN.RegisterCapture{
    name = "position",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        return { mapID = mapID, x = x, y = y }
    end,
}

-- THE ONE THAT WOULD HAVE CAUGHT 0.40.0's ANGLE BUG EIGHT RELEASES EARLIER.
CN.RegisterCapture{
    name = "mapSpanYards",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        local nav = CN:GetModule("Navigation")

        if not mapID or not nav then
            return nil, "no map"
        end

        -- THE THIRD RETURN, WHICH SAYS WHETHER THE FIRST TWO ARE REAL.
        -- 0.82.0.
        --
        -- `Navigation.MapScale` answers `1, 1, false` on both of its refusal
        -- paths, and its own header says so: "callers that want a ratio keep
        -- ignoring the third value. Callers that want yards MUST check it."
        -- `Routing.lua` checks it, under a comment about `1 > 0` passing
        -- validation being "a disaster". This capture wants yards and did
        -- not check.
        --
        -- The refusal path is exactly a loading screen -- which is when the
        -- map API declines and when a player is most likely to be running
        -- `/cn capture` after something went wrong. So the file the player
        -- pastes into a bug report recorded "this map is one yard square",
        -- as a successful observation, and the offline suite then validated
        -- its stubs against it. This capture exists to catch a map-geometry
        -- defect; it was capable of manufacturing one.
        local scaleX, scaleY, measured = nav.MapScale(mapID)

        if not measured then
            return nil, "the client would not convert this map"
        end

        return {
            mapID  = mapID,
            xYards = scaleX,
            yYards = scaleY,
            square = math.abs(scaleX - scaleY) < 1,
        }
    end,
}

CN.RegisterCapture{
    name = "worldPosition",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID or not C_Map or not C_Map.GetWorldPosFromMapPos then
            return nil, "no map"
        end

        local ok, continentID, position =
            pcall(C_Map.GetWorldPosFromMapPos, mapID, CreateVector2D(x, y))

        if not ok or not position then
            return nil, "the client would not convert"
        end

        return {
            continentID = continentID,
            shape       = Capture.Shape(position),
            hasGetXY    = position.GetXY ~= nil,
        }
    end,
}

CN.RegisterCapture{
    name = "mapInfo",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        return Capture.Shape(Blizzard.GetMapInfo(mapID))
    end,
}

CN.RegisterCapture{
    name = "questPOI",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return nil, "no map"
        end

        local pois = Blizzard.GetQuestPOIsOnMap(mapID)

        if #pois == 0 then
            return nil, "no quest pins here"
        end

        local starts = 0

        for _, poi in ipairs(pois) do
            if poi.isQuestStart then
                starts = starts + 1
            end
        end

        return {
            count       = #pois,
            questStarts = starts,
            shape       = Capture.Shape(pois[1]),
        }
    end,
}

CN.RegisterCapture{
    name = "achievementCriteria",
    run  = function()
        local achievements = CN:GetModule("Achievements")

        if not achievements then
            return nil, "achievements module not loaded"
        end

        for achievementID in pairs(achievements.Store()) do
            local criteria = Blizzard.GetAchievementCriteriaList(achievementID, 4)

            if criteria and criteria[1] then
                return {
                    shape    = Capture.Shape(criteria[1]),
                    counted  = criteria[1].required ~= nil,
                }
            end
        end

        return nil, "nothing scanned yet"
    end,
}

CN.RegisterCapture{
    name = "savedInstances",
    run  = function()
        local saved = Blizzard.GetSavedInstances()

        if #saved == 0 then
            return nil, "not saved to anything"
        end

        return { count = #saved, shape = Capture.Shape(saved[1]) }
    end,
}

CN.RegisterCapture{
    name = "encounterJournal",
    run  = function()
        if not Blizzard.HasEncounterJournal() then
            return nil, "no Adventure Guide in this client"
        end

        if Blizzard.IsEncounterJournalOpen() then
            return nil, "the Adventure Guide is open"
        end

        return { available = true }
    end,
}

CN.RegisterCapture{
    name = "completedQuests",
    run  = function()
        local progress = CN:GetModule("Progress")

        local total = progress and progress.LifetimeCompleted()

        if not total then
            return nil, "the client will not report a lifetime total"
        end

        -- The COUNT is the interesting number: a stub that returns eight
        -- entries where the client returns twelve thousand is a stub that
        -- makes an expensive call look free.
        return { count = total }
    end,
}

CN.RegisterCapture{
    name = "weeklyReset",
    run  = function()
        local seconds = Blizzard.GetSecondsUntilWeeklyReset()

        if not seconds then
            return nil, "the client will not say"
        end

        return { seconds = seconds }
    end,
}

-- WHICH OF THE EVENTS THIS ADDON REGISTERS ARE REAL.
--
-- Added in 0.46.0, after `NEW_TAXI_NODE` -- a name that does not exist and
-- never has -- threw a Lua error at every login. The test suite could not see
-- it because the stub frame accepted any string, and the fix for that is a
-- list of real event names maintained by hand in the harness. A list
-- maintained by hand is precisely the kind of thing this project keeps being
-- caught by, so it needs checking against a client rather than against
-- memory.
--
-- This asks the live client to register every event the addon uses, on a
-- throwaway frame with no handler attached, and records the ones it refused.
-- The harness fails on any refusal.
CN.RegisterCapture{
    name = "events",
    run  = function()
        if not CreateFrame then
            return nil, "no frame factory"
        end

        local ok, probe = pcall(CreateFrame, "Frame")

        if not ok or not probe then
            return nil, "the client would not make a frame"
        end

        local refused, accepted = {}, 0

        for event in pairs(CN.eventTable or {}) do
            local registered = pcall(probe.RegisterEvent, probe, event)

            if registered then
                accepted = accepted + 1

                pcall(probe.UnregisterEvent, probe, event)
            else
                table.insert(refused, event)
            end
        end

        table.sort(refused)

        return { accepted = accepted, refused = refused }
    end,
}

-- WHICH OF THE CLIENT FUNCTIONS THIS ADDON CALLS STILL EXIST.
--
-- The sibling of the `events` capture, and the more insidious half. An
-- unknown EVENT name throws, so it announces itself. An unknown FUNCTION name
-- announces nothing: every call site in this addon is guarded with
-- `if C_Thing and C_Thing.Method`, which is correct, and which makes a
-- misspelled or renamed name indistinguishable from a client that does not
-- support the feature. The guard is false, the branch never runs, and the
-- feature is quietly dead for as long as nobody notices.
--
-- Data/ApiSurface.lua is generated from the source at build time -- a
-- hand-written list of what the code calls is a second copy of the code, and
-- would drift within a release.
CN.RegisterCapture{
    name = "apiSurface",
    run  = function()
        if type(CN.apiSurface) ~= "table" or #CN.apiSurface == 0 then
            return nil, "no generated surface in this build"
        end

        local missing, present = {}, 0

        for _, path in ipairs(CN.apiSurface) do
            local namespace, method = string.match(path, "^([^.]+)%.(.+)$")

            local value

            if namespace then
                local container = _G and _G[namespace]

                value = type(container) == "table" and container[method] or nil
            else
                value = _G and _G[path]
            end

            if value ~= nil then
                present = present + 1
            else
                table.insert(missing, path)
            end
        end

        return { examined = #CN.apiSurface, present = present, missing = missing }
    end,
}

------------------------------------------------------------
-- RUNNING IT
------------------------------------------------------------

function Capture.Run()
    local records = {}

    local captured, skipped = 0, 0

    for _, definition in ipairs(CN.captures) do
        local ok, value, note = pcall(definition.run)

        if not ok then
            records[definition.name] = { skipped = "errored: " .. tostring(value) }
            skipped = skipped + 1
        elseif value == nil then
            records[definition.name] = { skipped = note or "nothing to record" }
            skipped = skipped + 1
        else
            records[definition.name] = value
            captured = captured + 1
        end
    end

    records.build   = CN.version
    records.locale  = CN.ClientLocale and CN.ClientLocale() or nil
    records.recorded = time()

    -- WHICH CLIENT THIS IS EVIDENCE ABOUT.
    --
    -- Added in 0.46.0, because a recording with no interface number cannot be
    -- checked for staleness, and stale evidence is worse than none: it makes
    -- the audit report success about a game that has since been patched. The
    -- .toc's Interface line is the addon's claim about which client it
    -- supports; this is the client that was actually running.
    if GetBuildInfo then
        local ok, _, _, _, interface = pcall(GetBuildInfo)

        if ok then
            records.interface = tonumber(interface)
        end
    end

    -- Written under the account table so it survives to the next logout and
    -- lands in SavedVariables, which is the only way it can reach the
    -- repository. Explicitly NOT merged into anything the addon reads: this
    -- is evidence, not data.
    local account = CN.Account()

    account.capture = records

    return records, captured, skipped
end

function Capture.Clear()
    local account = CN.Account()

    local had = account.capture ~= nil

    account.capture = nil

    return had
end

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "capture",
    args    = "[clear]",
    order   = 35,
    help    = "Record what your client returns, so the tests can check "
        .. "themselves against reality.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "clear" then
            Print(Capture.Clear()
                and "Capture cleared. It will be gone from your saved data "
                    .. "at the next logout."
                or "There was nothing recorded.")
            return
        end

        local records, captured, skipped = Capture.Run()

        Print("Recorded " .. captured .. " of " .. (captured + skipped)
            .. " observations.")

        for name, value in pairs(records) do
            if type(value) == "table" and value.skipped then
                CN.PrintLine("  |cff8a8f96" .. name .. " " .. CN.DASH .. " " .. value.skipped .. "|r")
            end
        end

        Print("|cff8a8f96Nothing identifying you is recorded, and nothing "
            .. "leaves your machine" .. CN.DASH .. "this addon has no network access. "
            .. "It is written to your SavedVariables at logout.|r")
        Print("To send it: log out, then find "
            .. "|cffffc74fWTF\\Account\\<account>\\SavedVariables\\"
            .. "CompletionNavigatorDB.lua|r.")
        Print("|cffffc74f/cn capture clear|r removes it again.")
    end,
}

return Capture
'@

$Embedded['Modules\SelfTest.lua'] = @'
-- Modules/SelfTest.lua
-- Completion Navigator :: assertions that run where reality is.
--
-- WHY THIS EXISTS.
--
-- Seven times in this project's history, the offline test harness has modelled
-- the world more simply than the world, and hidden a real defect by doing it:
--
--   * a map point modelled as a flat table when the client wants a vector
--   * a quest list that contained no quest starts
--   * an achievement criterion with no counter
--   * a completed-quest list that cost nothing to read
--   * a player who could not move
--   * an arrow whose direction nothing could read
--   * a map that would place the player anywhere it was asked about
--
-- Every one was found by somebody playing the game. None was found by the
-- suite. And no amount of improving the harness fixes that, because the
-- harness is the thing that is wrong: you cannot write a stub for the part of
-- reality you did not know you were simplifying.
--
-- So these assertions do not run against a stub. They run against the live
-- client, on the player's own character, and report what they actually got.
-- When something is wrong, the answer is one command rather than a
-- conversation.
--
-- RULES FOR A CHECK IN HERE.
--
--   * It must be read-only. A diagnostic that changes the game is a liability.
--   * It must be fast. This runs on demand, but nobody waits.
--   * It must report the VALUE it saw, not just pass or fail. "Failed" starts
--     a conversation; "expected a number, got nil" ends one.
--   * A client that cannot answer is a SKIP, not a failure. Being in a raid
--     with the map API restricted is not a bug in this addon.

local ADDON_NAME, CN = ...

local SelfTest = CN:RegisterModule("SelfTest")

local Print = CN.Print

local Blizzard = CN.Blizzard

------------------------------------------------------------
-- REGISTRY
------------------------------------------------------------

SelfTest.results = { PASS = "PASS", FAIL = "FAIL", SKIP = "SKIP" }

-- The registry itself is in Core.lua, so that a module registering a check
-- does not have to load after this file:
--
--     CN.RegisterSelfTest{ name = ..., area = ..., run = function() end }
--
-- definition.run returns status, detail.

function SelfTest.Run()
    local rows = { passed = 0, failed = 0, skipped = 0, checks = {} }

    local ordered = {}

    for _, definition in ipairs(CN.selfTests) do
        table.insert(ordered, definition)
    end

    table.sort(ordered, function(a, b)
        if (a.area or "") ~= (b.area or "") then
            return (a.area or "") < (b.area or "")
        end

        return (a.order or 0) < (b.order or 0)
    end)

    for _, definition in ipairs(ordered) do
        -- A check that throws is a failed check, not a broken command. The
        -- whole point is to survive a client that surprises us.
        local ok, status, detail = pcall(definition.run)

        if not ok then
            -- `status` is the error message here, so read it BEFORE
            -- overwriting it. Getting that order wrong produced a check that
            -- reported "the check itself errored: FAIL", which is the least
            -- useful sentence this module could possibly print.
            detail = "the check itself errored: " .. tostring(status)
            status = SelfTest.results.FAIL
        end

        status = status or SelfTest.results.SKIP

        if status == SelfTest.results.PASS then
            rows.passed = rows.passed + 1
        elseif status == SelfTest.results.FAIL then
            rows.failed = rows.failed + 1
        else
            rows.skipped = rows.skipped + 1
        end

        table.insert(rows.checks, {
            name   = definition.name,
            area   = definition.area or "general",
            status = status,
            detail = detail,
        })
    end

    return rows
end

------------------------------------------------------------
-- THE CHECKS
------------------------------------------------------------

local PASS = SelfTest.results.PASS
local FAIL = SelfTest.results.FAIL
local SKIP = SelfTest.results.SKIP

-- 1. Can the client say where we are at all? Everything else depends on it.
-- WHAT THE GAME PATCHED OUT FROM UNDER US.
--
-- Added in 0.47.0. Every expansion renames or removes client functions, and
-- this addon names nearly two hundred of them. Each call site guards on the
-- name existing -- which is right, and which is also why a removed function
-- produces silence rather than an error: the guard goes false and the feature
-- is dead with nothing to say so.
--
-- Data/ApiSurface.lua is generated from the source at build time, so this
-- cannot fall out of step with what the addon actually calls. Reported here
-- because the player is the one holding a client the author has not seen.
-- NAMES THE ADDON PROBES FOR AND DOES NOT REQUIRE. 0.86.0.
--
-- `Data/ApiSurface.lua` is generated from every client name the source
-- mentions, which is right for its purpose and cannot tell a name the addon
-- NEEDS from one it asks about and takes the other branch when it is absent.
--
-- `InterfaceOptions_AddCategory` is the pre-10.0 options API -- `Modules/
-- Hud.lua` says so in a comment right above the guard that probes for it --
-- and it is gone from every Retail client, which this addon's `.toc` targets.
-- The other four are the pre-`C_Item`/`C_Spell` globals, each reached only as
-- an `elseif` after the modern call.
--
-- So the FIRST check in `/cn selftest` reported FAIL on 100% of Retail
-- clients, permanently, under a footer reading "A failure above is a real
-- defect. Copy this output into a bug report." The diagnostic written to end
-- support conversations started one -- and, being always red, buried the real
-- API loss it exists to catch.
--
-- The offline suite could not see it: it asserts that FAIL is the correct
-- answer whenever a name is absent, which it is -- for a name the addon
-- requires.
SelfTest.optionalApi = {
    ["InterfaceOptions_AddCategory"] = true,
    ["GetItemCooldown"]              = true,
    ["GetItemCount"]                 = true,
    ["GetItemInfo"]                  = true,
    ["GetSpellCooldown"]             = true,
}

CN.RegisterSelfTest{
    area  = "client",
    order = 0,
    name  = "every client function this addon calls still exists",
    run   = function()
        if type(CN.apiSurface) ~= "table" or #CN.apiSurface == 0 then
            return SKIP, "this build carries no generated API list"
        end

        local missing = {}

        local checked = 0

        for _, path in ipairs(CN.apiSurface) do
            if not SelfTest.optionalApi[path] then
                checked = checked + 1

                local namespace, method = string.match(path, "^([^.]+)%.(.+)$")

                local value

                if namespace then
                    local container = _G and _G[namespace]

                    value = type(container) == "table"
                        and container[method] or nil
                else
                    value = _G and _G[path]
                end

                if value == nil then
                    table.insert(missing, path)
                end
            end
        end

        if #missing == 0 then
            return PASS, checked .. " client functions, all present"
        end

        -- Named, and bounded: a patch that removes a whole namespace would
        -- otherwise print forty lines into the chat frame.
        local named = {}

        for index = 1, math.min(6, #missing) do
            table.insert(named, missing[index])
        end

        return FAIL, #missing .. " of " .. checked
            .. " are gone from this client: " .. table.concat(named, ", ")
            .. (#missing > 6 and (" and " .. (#missing - 6) .. " more") or "")
    end,
}

CN.RegisterSelfTest{
    area = "position",
    name = "the client reports your position",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map" .. CN.DASH .. "are you in an instance or a loading screen?"
        end

        if not x or not y then
            return FAIL, "map " .. mapID .. " but no coordinates"
        end

        return PASS, string.format("map %d at %.1f, %.1f", mapID, x * 100, y * 100)
    end,
}

-- 2. THE 0.19.0 BUG. GetWorldPosFromMapPos wants a Vector2D, not a UiMapPoint.
--    Passing the wrong one returns nothing and every distance reads "unknown".
--    The stub modelled both as the same shape, so the suite agreed with it.
CN.RegisterSelfTest{
    area = "position",
    name = "map coordinates convert to world positions",
    run  = function()
        local mapID, x, y = CN.GetPlayerPosition()

        if not mapID or not x then
            return SKIP, "no position to convert"
        end

        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        -- Distance from where we are to slightly north of it. Any real
        -- number proves the conversion works.
        local yards = nav.DistanceYards(mapID, x, y, x, math.max(0, y - 0.01))

        if not yards then
            return FAIL, "the client would not convert" .. CN.DASH .. "every distance in "
                .. "the addon will read 'unknown'"
        end

        return PASS, string.format("%.0f yards per 1%% of this map", yards)
    end,
}

-- 3. THE 0.34.0 BUG. Standing in a building changes which map you are "on",
--    and the arrow gave up when that map differed from the destination's.
CN.RegisterSelfTest{
    area = "position",
    name = "your position is expressible on the surrounding zone",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map"
        end

        local info = Blizzard.GetMapInfo(mapID)

        local parentID = info and info.parentMapID

        if not parentID or parentID == 0 then
            return SKIP, "this map has no parent" .. CN.DASH .. "you are not indoors"
        end

        local nav = CN:GetModule("Navigation")

        local translatedX, translatedY

        if nav then
            translatedX, translatedY = nav.PlayerPositionOnMap(parentID)
        end

        if not translatedX then
            return SKIP, "the parent map cannot place you, which is normal "
                .. "for a continent"
        end

        return PASS, string.format("also %.1f, %.1f on map %d",
            translatedX * 100, translatedY * 100, parentID)
    end,
}

-- 4. THE BEARING MATHS, against cases whose answers are known independently
--    of the code being checked.
--
--    NOT written the obvious way. The obvious way is to project a point in
--    front of the player using the addon's own facing convention and then ask
--    the addon which way that point is -- which is a tautology: it derives the
--    expected answer from the thing under test, so it passes whether the
--    convention is right or wrong. That is precisely the failure this module
--    exists to stop, and it was in this file before it shipped.
--
--    Instead: fix the facing at zero, put a target somewhere whose bearing is
--    known from the definition of the map (north is up, east is right), and
--    require the stated answer.
CN.RegisterSelfTest{
    area = "navigation",
    name = "the bearing maths gives known answers",
    run  = function()
        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        local cases = {
            { name = "north",  x = 0.5, y = 0.4, expected =   0 },
            { name = "east",   x = 0.6, y = 0.5, expected =  90 },
            { name = "south",  x = 0.5, y = 0.6, expected = 180 },
            { name = "west",   x = 0.4, y = 0.5, expected = -90 },
        }

        for _, case in ipairs(cases) do
            -- No mapID: unscaled, so the four cardinals stay cardinal.
            local relative = nav.RelativeBearing(0.5, 0.5, case.x, case.y, 0, 1)

            if not relative then
                return FAIL, "no bearing could be computed at all"
            end

            local degrees = math.deg(relative)

            -- Signed difference, wrapped, so that east reading as west is a
            -- failure rather than the same distance from zero.
            local off = math.abs(math.deg(
                nav.NormalizeAngle(math.rad(degrees - case.expected))))

            if off > 1 then
                return FAIL, string.format(
                    "a target due %s read as %.0f degrees, not %d",
                    case.name, degrees, case.expected)
            end
        end

        return PASS, "north, east, south and west all read correctly"
    end,
}

-- 5. WHICH WAY THE CLIENT COUNTS FACING, from the player's own movement.
--
--    This is the one that would have ended two bug reports. It cannot be
--    answered by arithmetic, because it is a fact about the client, so it is
--    answered by evidence: when you walk, the direction you moved is the
--    direction you were facing, and only one of the two conventions agrees
--    with that.
--
--    No evidence yet is a SKIP with an instruction, not a pass. An
--    unverified assumption reported as PASS is worse than no check.
CN.RegisterSelfTest{
    area = "navigation",
    name = "your facing is being read the right way round",
    run  = function()
        local nav = CN:GetModule("Navigation")

        if not nav then
            return SKIP, "navigation module not loaded"
        end

        local state = nav.MotionState()

        if state.samples == 0 then
            return SKIP, "no movement seen yet" .. CN.DASH .. "point the arrow at "
                .. "something with /cn go, walk forward a few seconds, and "
                .. "run this again"
        end

        if state.verdict == "corrected" then
            return PASS, "was backwards; corrected from your movement and "
                .. "remembered (sign " .. tostring(state.sign) .. ")"
        end

        -- THERE WAS NO FAIL BRANCH HERE, IN A CHECK WHOSE OWN HEADER SAYS
        -- "AN UNVERIFIED ASSUMPTION REPORTED AS PASS IS WORSE THAN NO CHECK".
        -- 0.61.0.
        --
        -- `motion.verdict` is set to "confirmed" only by a sample that AGREES
        -- with the sign in use. A sample that DISAGREES increments `against`
        -- and leaves the verdict alone, and the sign is not flipped until
        -- `against` reaches the threshold. So the whole window between the
        -- first disagreeing sample and the correction has samples > 0 and no
        -- verdict -- and this function reported that state as
        -- "confirmed against 1 movement samples".
        --
        -- That is the exact state in which the arrow IS pointing backwards
        -- and the addon has already seen the evidence. Reporting it as a pass
        -- told a player chasing precisely this bug that there was nothing
        -- wrong, in the diagnostic written to find it.
        if state.verdict ~= "confirmed" then
            if (state.against or 0) > 0 then
                return FAIL, string.format(
                    "%d of %d samples say the arrow is backwards and the sign "
                    .. "has not been flipped yet" .. CN.DASH .. "keep walking "
                    .. "forward for a few more seconds and run this again",
                    state.against, state.samples)
            end

            return SKIP, string.format(
                "%d samples, none of them conclusive" .. CN.DASH .. "walk "
                .. "forward while facing east or west, then run this again",
                state.samples)
        end

        return PASS, string.format(
            "confirmed against %d movement samples (sign %s)",
            state.samples, tostring(state.sign))
    end,
}

-- 6. MAP ASPECT RATIO. Angles taken from raw map coordinates are distorted by
--    however far from square the zone is, which was wrong in every zone in
--    the game until 0.40.0.
CN.RegisterSelfTest{
    area = "navigation",
    name = "angles are corrected for the shape of the zone",
    run  = function()
        local nav = CN:GetModule("Navigation")

        local mapID = CN.GetPlayerPosition()

        if not nav or not mapID then
            return SKIP, "no map"
        end

        local scaleX, scaleY = nav.MapScale(mapID)

        if scaleX == 1 and scaleY == 1 then
            return SKIP, "the client would not size this map"
        end

        local ratio = scaleX / scaleY

        return PASS, string.format(
            "%.0f x %.0f yards, ratio %.2f" .. CN.DASH .. "angles adjusted by it",
            scaleX, scaleY, ratio)
    end,
}

-- 7. THE 0.23.0 BUG. Every quest source read the quest log, so quests
--    offered in front of the player were structurally invisible.
CN.RegisterSelfTest{
    area = "quests",
    name = "the map reports quests you have NOT accepted",
    run  = function()
        local mapID = CN.GetPlayerPosition()

        if not mapID then
            return SKIP, "no map"
        end

        local pois = Blizzard.GetQuestPOIsOnMap(mapID)

        if #pois == 0 then
            return SKIP, "no quest pins on this map at all"
        end

        local starts = 0

        for _, poi in ipairs(pois) do
            if poi.isQuestStart then
                starts = starts + 1
            end
        end

        -- IT COUNTED, AND THEN PASSED REGARDLESS. 0.61.0.
        --
        -- This is the regression test for the 0.23.0 bug -- quests offered in
        -- front of the player being structurally invisible because every
        -- source read the quest log. The whole question is whether ANY pin
        -- comes back flagged as a quest start. Zero of them is the bug,
        -- exactly, and this returned PASS for it.
        --
        -- Zero starts is not automatically a failure: a map where the player
        -- has already accepted everything legitimately has none. So the
        -- distinction is made against the quest log rather than assumed.
        if starts == 0 then
            local unaccepted = 0

            for _, poi in ipairs(pois) do
                if poi.questID and not Blizzard.IsQuestInLog(poi.questID) then
                    unaccepted = unaccepted + 1
                end
            end

            if unaccepted > 0 then
                return FAIL, string.format(
                    "%d pins, %d for quests not in your log, and NONE flagged "
                    .. "as a quest start" .. CN.DASH .. "the 0.23.0 blind spot "
                    .. "is back",
                    #pois, unaccepted)
            end

            return SKIP, string.format(
                "%d pins, all for quests already in your log" .. CN.DASH
                .. "nothing here can answer the question",
                #pois)
        end

        return PASS, string.format("%d pins, %d of them quest starts",
            #pois, starts)
    end,
}

-- 8. THE 0.32.0 BUG. This returns a table of every quest ever completed, not
--    a count, and reading it on every refresh was expensive.
CN.RegisterSelfTest{
    area = "quests",
    name = "your completed-quest history is readable",
    run  = function()
        local progress = CN:GetModule("Progress")

        if not progress then
            return SKIP, "progress module not loaded"
        end

        local total = progress.LifetimeCompleted()

        if not total then
            return SKIP, "the client will not report a lifetime total"
        end

        return PASS, CN.Comma(total) .. " quests completed on this character"
    end,
}

-- 9. THE 0.26.0 BUG. A criterion can carry its own counter, and a stub that
--    returned only three values hid that.
CN.RegisterSelfTest{
    area = "achievements",
    name = "achievement criteria report their counters",
    run  = function()
        local achievements = CN:GetModule("Achievements")

        if not achievements then
            return SKIP, "achievements module not loaded"
        end

        -- ORDERED, NOT HASH ORDER. 0.86.0.
        --
        -- The sample is the first thirty criteria this loop reaches, and the
        -- verdict below turns FAIL if none of them carries a counter. Which
        -- five-or-so achievements those are was `pairs` order -- so the same
        -- account, unchanged, could report PASS one session and FAIL the
        -- next, and the FAIL tells the player the addon is dropping the
        -- client's quantity fields and to file a bug report.
        --
        -- A diagnostic that is not reproducible is worse than none. This
        -- project already has a stable tie-break over mixed id types, added
        -- for exactly this reason and used by the sorts and the zone lookup.
        local ids = {}

        for achievementID in pairs(achievements.Store()) do
            ids[#ids + 1] = achievementID
        end

        table.sort(ids, CN.IdBefore)

        local sampled, counted = 0, 0

        for _, achievementID in ipairs(ids) do
            local criteria = Blizzard.GetAchievementCriteriaList(achievementID, 6)

            for _, criterion in ipairs(criteria) do
                sampled = sampled + 1

                if criterion.required and criterion.required > 1 then
                    counted = counted + 1
                end
            end

            if sampled >= 30 then
                break
            end
        end

        if sampled == 0 then
            return SKIP, "nothing scanned yet" .. CN.DASH .. "run /cn setup"
        end

        -- SAME SHAPE AS THE ONE ABOVE, SAME FIX. 0.61.0.
        --
        -- This is the regression test for the 0.26.0 bug: a stub that
        -- returned only three values, hiding the criterion counters. If not
        -- one of thirty sampled criteria carries a counter, the fifth and
        -- sixth return values are being dropped again -- which is the bug --
        -- and this reported "30 criteria read, 0 carry a counter" as a PASS.
        --
        -- Thirty criteria with no counter among them does happen on a fresh
        -- account with only simple achievements scanned, so it is reported as
        -- inconclusive rather than as a failure unless the sample is large
        -- enough to mean something.
        if counted == 0 then
            if sampled >= 30 then
                return FAIL, string.format(
                    "%d criteria read and not one carries a counter" .. CN.DASH
                    .. "the client's quantity and required fields are being "
                    .. "dropped",
                    sampled)
            end

            return SKIP, string.format(
                "only %d criteria available, none with a counter" .. CN.DASH
                .. "too few to tell", sampled)
        end

        return PASS, string.format("%d criteria read, %d carry a counter",
            sampled, counted)
    end,
}

-- 10. Names the addon deliberately stopped storing must come back live. If
--    they do not, everything in the interface reads "Pet 12345".
CN.RegisterSelfTest{
    area = "names",
    name = "names resolve from the client rather than from disk",
    run  = function()
        local checked, resolved = 0, 0

        local pets = CN:GetModule("Pets")

        if pets then
            for speciesID in pairs(pets.Store()) do
                checked = checked + 1

                if Blizzard.GetPetName(speciesID) then
                    resolved = resolved + 1
                end

                if checked >= 10 then
                    break
                end
            end
        end

        if checked == 0 then
            return SKIP, "no pets scanned yet"
        end

        if resolved == 0 then
            return FAIL, "the pet journal named none of "
                .. checked .. CN.DASH .. "the interface will show numbers"
        end

        return PASS, resolved .. " of " .. checked .. " named by the client"
    end,
}

-- 11. The database is at the version this build expects. A migration that
--    silently failed leaves a shape nothing else understands.
CN.RegisterSelfTest{
    area = "database",
    name = "the database is at the expected version",
    run  = function()
        if not CN.db then
            return FAIL, "no database loaded at all"
        end

        local version = CN.db.version

        -- The specific reason, when there is one. "Version 7, expected 10" is
        -- true and useless; "migration 7 threw X" is the actual fault.
        -- Data that was set aside rather than destroyed is still an
        -- unresolved fault, and it outlives the failure record that produced
        -- it -- so it is reported on its own rather than under it.
        if CN.db.rescuedCharacters ~= nil then
            return FAIL, "some saved data was set aside as unreadable" .. " " .. CN.DASH .. " "
                .. "/cn rescued"
        end

        local failure = CN.db.migrationFailure or CN.migrationFailure

        if type(failure) == "table" and failure.version then
            return FAIL, "migration " .. tostring(failure.version)
                .. " failed: " .. tostring(failure.error)
        end

        if version ~= CN.dbVersion then
            return FAIL, "database is version " .. tostring(version)
                .. ", this build expects " .. tostring(CN.dbVersion)
        end

        return PASS, "version " .. tostring(version)
    end,
}

-- 12. Size, because it is rewritten on every logout and nobody notices it
--     growing until logging out becomes slow.
CN.RegisterSelfTest{
    area = "database",
    name = "saved data is a reasonable size",
    run  = function()
        if not CN.MeasureDatabase or not CN.db then
            return SKIP, "cannot measure"
        end

        local bytes = CN.MeasureDatabase(CN.db)

        local kb = bytes / 1024

        if kb > 4096 then
            return FAIL, string.format(
                "%.0f KB" .. CN.DASH .. "unusually large; run /cn dbsize to see where", kb)
        end

        return PASS, string.format("%.0f KB", kb)
    end,
}

-- 13. The recommendation engine produces something. An addon whose entire
--     purpose is answering a question should be asked it.
CN.RegisterSelfTest{
    area = "engine",
    name = "the engine can answer 'what next'",
    run  = function()
        -- QUIETLY. A diagnostic must not teach the addon anything about how
        -- the player plays: `/cn selftest` runs on demand and its result is
        -- a pass or a fail, not a recommendation anybody acted on. 0.69.0.
        local results = CN.Recommend(1, true)

        if not results or #results == 0 then
            return SKIP, "nothing actionable right now" .. CN.DASH .. "try /cn setup, or "
                .. "check /cn show in case everything is filtered out"
        end

        local first = results[1]

        return PASS, tostring(first.name or first.id)
            .. " (" .. tostring(first.type) .. ")"
    end,
}

-- 14. LOCKOUTS. The client reports these directly, and a lockout the addon
--     cannot read is a deadline it cannot rank.
CN.RegisterSelfTest{
    area = "instances",
    name = "your dungeon and raid lockouts are readable",
    run  = function()
        local instances = CN:GetModule("Instances")

        if not instances then
            return SKIP, "instances module not loaded"
        end

        local lockouts = instances.Lockouts()

        if #lockouts == 0 then
            return SKIP, "you are not saved to anything right now"
        end

        local summary = instances.Summary()

        return PASS, string.format("%d saved, %d unfinished, %d bosses left",
            summary.total, summary.unfinished, summary.bosses)
    end,
}

-- 15. THE ADVENTURE GUIDE, which is how a drop gets a boss's name attached to
--     it. Open, it must refuse -- reading it moves what the player is looking
--     at, and that refusal is the behaviour worth checking.
CN.RegisterSelfTest{
    area = "instances",
    name = "the Adventure Guide can be read without disturbing you",
    run  = function()
        if not Blizzard.HasEncounterJournal() then
            return SKIP, "this client has no Adventure Guide"
        end

        if Blizzard.IsEncounterJournalOpen() then
            return SKIP, "the Adventure Guide is open, so nothing was read" .. " " .. CN.DASH .. " "
                .. "which is the intended behaviour, not a fault"
        end

        local encounters = Blizzard.GetInstanceEncounters(1273)

        if #encounters == 0 then
            return SKIP, "the journal returned no bosses for the sample "
                .. "instance; loot lookups may be unavailable"
        end

        return PASS, #encounters .. " bosses read, and the journal's own "
            .. "selection restored"
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "selftest",
    aliases = { "diagnose", "check" },
    order   = 32,
    help    = "Check the addon against the live game and report what it finds.",
    handler = function()
        local rows = SelfTest.Run()

        Print("Self-test: " .. #rows.checks .. " checks against the live client.")

        local area

        for _, check in ipairs(rows.checks) do
            if check.area ~= area then
                area = check.area

                CN.PrintLine("|cffffc74f" .. area .. "|r")
            end

            local colour = "|cff73b873"

            if check.status == FAIL then
                colour = "|cffe2564c"
            elseif check.status == SKIP then
                colour = "|cff8a8f96"
            end

            -- NO COLUMN PADDING. 0.77.0. See the note in `Routing.lua`.
            CN.PrintLine("  " .. colour .. check.status .. "|r  "
                .. check.name)

            if check.detail then
                CN.PrintLine("        |cff8a8f96" .. check.detail .. "|r")
            end
        end

        Print(string.format("%d passed, %d failed, %d skipped.",
            rows.passed, rows.failed, rows.skipped))

        if rows.failed > 0 then
            Print("|cffffc74fA failure above is a real defect. Copy this "
                .. "output into a bug report" .. CN.DASH .. "it says more than any "
                .. "description could.|r")
        end
    end,
}

return SelfTest
'@

$Embedded['Modules\Orders.lua'] = @'
-- Modules/Orders.lua
-- Completion Navigator :: crafting orders, and a standing question about
-- Delves.
--
-- CRAFTING ORDERS.
--
-- The addon has tracked recipes since 0.14.0 and never noticed that other
-- people can pay you to use them, or that an order you placed yourself
-- finishes and then sits there. Both are time-limited -- an order expires --
-- and both are knowable from the client.
--
-- What it does NOT do is browse the order board. That requires standing at a
-- crafting table with the frame open, and an addon that pokes at that UI to
-- read it is an addon that fights the player for control of their own window.
-- This reports what the client will answer without being asked to open
-- anything: your own orders, and whether any of them are ready to collect.
--
-- DELVES.
--
-- Assessed twice and deliberately not built, for a reason that is written
-- down rather than remembered: `C_DelvesUI` exposes interface plumbing --
-- minimum level, which button to show -- and not progress. Delve credit
-- toward the Great Vault already flows through the World row, so a Delves
-- module would duplicate working behaviour with guesswork.
--
-- The decision has a trigger rather than a date: if a build ever exposes a
-- progress API, the probe below starts answering and the self-test says so.
-- That is the difference between a decision and a thing everyone forgot.

local ADDON_NAME, CN = ...

local Orders = CN:RegisterModule("Orders")

local Print      = CN.Print
local DebugPrint = CN.DebugPrint

------------------------------------------------------------
-- CRAFTING ORDERS
------------------------------------------------------------

function Orders.IsAvailable()
    return C_CraftingOrders ~= nil
end

-- Orders this character placed, as the client last reported them. The list is
-- populated by the game when the order frame is opened, so this can be empty
-- and empty is not an error -- it means "nothing known yet", and the command
-- says so rather than claiming you have no orders.
function Orders.Mine()
    if not Orders.IsAvailable() or not C_CraftingOrders.GetMyOrders then
        return nil
    end

    local ok, orders = pcall(C_CraftingOrders.GetMyOrders)

    if not ok or type(orders) ~= "table" then
        return nil
    end

    local rows = {}

    for _, order in ipairs(orders) do
        if type(order) == "table" then
            table.insert(rows, {
                orderID    = order.orderID,
                itemID     = order.itemID,
                itemName   = order.itemName,
                expiresIn  = order.expirationTime
                    and math.max(0, order.expirationTime - time()) or nil,
                state      = order.orderState,
                crafter    = order.crafterName,
            })
        end
    end

    return rows
end

-- Whether the client says something is waiting to be collected.
function Orders.HasClaimable()
    if not Orders.IsAvailable() then
        return false
    end

    if C_CraftingOrders.GetClaimedOrder then
        local ok, claimed = pcall(C_CraftingOrders.GetClaimedOrder)

        if ok and claimed then
            return true
        end
    end

    return false
end

------------------------------------------------------------
-- CANDIDATES
------------------------------------------------------------

-- Deliberately narrow. An order that is finished, or one about to expire, is
-- a real next action with a real deadline. "Someone somewhere might want a
-- flask" is not, and the addon does not have the data to say it anyway.
Orders.expiryHorizonSeconds = 86400

CN.RegisterCandidateProvider("Orders", function()
    local candidates = {}

    local mine = Orders.Mine()

    if not mine then
        return candidates
    end

    for _, order in ipairs(mine) do
        -- THE THIRD ID SPACE THIS TYPE CARRIES. 0.83.0.
        --
        -- `Modules/Filters.lua` names all three: a merchant itemID from
        -- Vendors, a trade-skill recipe id from Professions, and a crafting
        -- orderID from here. 0.82.0 converted the Vendors rows to the recipe
        -- space because the RECIPE eligibility checker indexes
        -- `character.recipes` -- written from `C_TradeSkillUI.GetAllRecipeIDs`
        -- -- and left this provider exactly as it was.
        --
        -- Same consequence: an orderID that happened to collide with a recipe
        -- this character knows was answered "already known by this
        -- character", named after an unrelated recipe, and the waypoint was
        -- silently retired from an order about to expire -- which is the one
        -- deadline this provider exists for.
        --
        -- Prefixed rather than renumbered, because an order id IS the right
        -- identity for this row; it just must not be mistaken for a recipe.
        -- A string can never collide with one, and the row's own number is
        -- kept beside it.
        local rowID = "order:" .. tostring(order.orderID)

        if order.expiresIn and order.expiresIn <= Orders.expiryHorizonSeconds
            and not CN.IsIgnored(CN.objectiveTypes.RECIPE, rowID)
            and not CN.IsDeferred(CN.objectiveTypes.RECIPE, rowID) then

            local session = CN:GetModule("Session")

            table.insert(candidates, CN.NewObjective({
                id               = rowID,
                orderID          = order.orderID,
                type             = CN.objectiveTypes.RECIPE,
                name             = "Crafting order: "
                    .. tostring(order.itemName or order.itemID or "?"),
                completionValue  = 3,

                -- ONE DEADLINE, ONE CURVE. 0.89.0. `expiresIn` on the next
                -- line is the same expiry, and the reason text below quotes
                -- it a third time. The claim row further down keeps its flat
                -- bonus, correctly: nothing there expires.
                limitedTimeBonus = 0,
                travelCost       = CN.placelessCost,
                expiresIn        = order.expiresIn,
                reasons          = {
                    "a crafting order you placed expires in "
                        .. ((session and session.FormatDuration
                            and session.FormatDuration(order.expiresIn))
                            or "less than a day"),
                },
            }))
        end
    end

    -- AND HIDING OR DEFERRING IT WORKS. 0.78.0. See the same fix in
    -- `Modules/Vault.lua`: the loop above this one guards on both and the
    -- claim row did not, so deferring it said one thing and did another.
    if Orders.HasClaimable()
        and not CN.IsIgnored(CN.objectiveTypes.RECIPE, "claim")
        and not CN.IsDeferred(CN.objectiveTypes.RECIPE, "claim") then

        table.insert(candidates, CN.NewObjective({
            id               = "claim",
            type             = CN.objectiveTypes.RECIPE,
            name             = "Collect your finished crafting order",
            completionValue  = 5,
            limitedTimeBonus = 2,
            travelCost       = CN.placelessCost,
            reasons          = { "it is done and waiting at a crafting table" },
        }))
    end

    return candidates
end, {
    events   = { "CRAFTINGORDERS_UPDATE_ORDER_COUNT", "CRAFTINGORDERS_CLAIM_ORDER_RESPONSE" },

    -- VOLATILE, BECAUSE THIS CARRIES A DEADLINE.
    --
    -- `expiresIn` is computed at build time and feeds the urgency curve --
    -- the heaviest term in the table -- and is printed verbatim in the
    -- reason. Without this the row rebuilt only when the player touched the
    -- crafting-order system, so six hours later it still said "expires in 6
    -- hours" and still scored as though six hours remained.
    --
    -- Exactly the defect 0.59.0 fixed for calendar events, in the one
    -- deadline-carrying provider that was not volatile. The thirty-second
    -- cooldown already bounds what this costs.
    volatile = true,
    cooldown = 30,
})

------------------------------------------------------------
-- THE DELVES PROBE
------------------------------------------------------------

-- Names the exact API that would change the decision, so that "we looked and
-- there was nothing" does not decay into "nobody ever checked".
Orders.delveProgressAPIs = {
    "GetDelvesProgress",
    "GetDelveProgressInfo",
    "GetSeasonProgress",
}

-- Returns available, detail.
function Orders.DelveProgressAvailable()
    if not C_DelvesUI then
        return false, "C_DelvesUI is not present in this client"
    end

    for _, name in ipairs(Orders.delveProgressAPIs) do
        if type(C_DelvesUI[name]) == "function" then
            return true, "C_DelvesUI." .. name .. " exists" .. CN.DASH .. "Delve progress "
                .. "is now readable, and this addon should be tracking it"
        end
    end

    return false, "C_DelvesUI exists but exposes no progress function; Delve "
        .. "credit still reaches the addon through the Great Vault's World row"
end

CN.RegisterSelfTest{
    area = "instances",
    name = "Delve progress is still unavailable",
    run  = function()
        local available, detail = Orders.DelveProgressAvailable()

        if available then
            -- A PASS would be wrong here. This check exists to notice a
            -- decision going stale, and the answer that needs acting on is
            -- the one that must stand out.
            return "FAIL", detail
        end

        return "SKIP", detail
    end,
}

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

CN:RegisterCommand{
    name    = "orders",
    order   = 27,
    help    = "Crafting orders you have placed, and anything ready to collect.",
    handler = function()
        if not Orders.IsAvailable() then
            Print("This client has no crafting order system.")
            return
        end

        local mine = Orders.Mine()

        if not mine then
            Print("Nothing known yet.")
            Print("|cff8a8f96The game only hands the addon your order list "
                .. "once you have opened the order frame this session. It is "
                .. "not asked to open on your behalf.|r")
            return
        end

        if #mine == 0 then
            Print("No orders outstanding.")
        else
            Print(#mine .. " order" .. CN.Pluralize(#mine, "") .. ":")

            local session = CN:GetModule("Session")

            for _, order in ipairs(mine) do
                local line = "  " .. tostring(order.itemName or order.itemID)

                if order.crafter then
                    line = line .. " |cff8a8f96claimed by "
                        .. order.crafter .. "|r"
                end

                if order.expiresIn then
                    line = line .. " |cffffc74fexpires in "
                        .. ((session and session.FormatDuration
                            and session.FormatDuration(order.expiresIn))
                            or "soon") .. "|r"
                end

                CN.PrintLine(line)
            end
        end

        if Orders.HasClaimable() then
            Print("|cff73b873Something is finished and waiting to be "
                .. "collected.|r")
        end
    end,
}

return Orders
'@

$Embedded['Modules\Contribute.lua'] = @'
-- Modules/Contribute.lua
-- Completion Navigator :: sharing what you learned, without a server.
--
-- THE PROBLEM.
--
-- The addon learns quest orderings from play, and that knowledge dies on the
-- machine that learned it. One player's evening becomes better advice for
-- that player and for nobody else. The obvious fix is a central database that
-- collects everyone's observations -- and the obvious fix is wrong here, for
-- reasons worth writing down rather than re-deriving:
--
--   * A World of Warcraft addon has NO network access. None. So "upload"
--     necessarily means a second product -- a desktop application, an
--     installer, an update channel -- and that is a larger undertaking than
--     this addon.
--   * Character name, realm and play times are personal data. Collecting them
--     makes the publisher a data controller, with a privacy policy, deletion
--     requests and breach obligations attached.
--   * The project page promises, twice, that nothing leaves your machine.
--
-- So: a one-way, opt-in, de-identified export the player chooses to attach to
-- a bug report. No server, no account, no personal data, and the promise on
-- the store page stays true, because nothing leaves the machine unless the
-- player themselves moves it.
--
-- WHAT IS IN AN EXPORT.
--
-- Quest IDs and orderings. That is all. No names, no realm, no character, no
-- timestamps, no coordinates, no play history. The receiving end can verify
-- what it is by reading it, which is a property worth more than any assurance
-- in a privacy policy.

local ADDON_NAME, CN = ...

local Contribute = CN:RegisterModule("Contribute")

local Print = CN.Print

------------------------------------------------------------
-- THE FORMAT
------------------------------------------------------------

-- Version first, so a future format change is detectable rather than
-- misparsed. Deliberately plain text: a player can read it before deciding to
-- send it, and anybody who has ever been asked to paste an opaque blob into a
-- form knows why that matters.
--
--   CN1 <questID>:<prerequisiteID>,<prerequisiteID> ...
Contribute.formatVersion = "CN1"

function Contribute.Build()
    local harvest = CN:GetModule("Harvest")

    if not harvest or not harvest.AllConfident then
        return nil, "the harvest module is not loaded"
    end

    local edges = harvest.AllConfident()

    local ids = {}

    for questID in pairs(edges) do
        table.insert(ids, questID)
    end

    table.sort(ids)

    if #ids == 0 then
        return nil, "nothing is confident yet" .. CN.DASH .. "a chain has to hold on "
            .. (harvest.confidenceThreshold or 3)
            .. " characters before it is worth sending"
    end

    local parts = { Contribute.formatVersion }

    for _, questID in ipairs(ids) do
        local prerequisites = edges[questID]

        table.sort(prerequisites)

        table.insert(parts, questID .. ":" .. table.concat(prerequisites, ","))
    end

    return table.concat(parts, " "), nil, #ids
end

-- Reads an export back. Returns a table of questID -> { prerequisiteIDs }.
--
-- Strict: anything malformed is rejected outright rather than partially
-- accepted. A half-parsed contribution is worse than a refused one, because
-- it silently teaches the addon a chain nobody wrote.
function Contribute.Parse(text)
    if type(text) ~= "string" then
        return nil, "not text"
    end

    text = CN.Trim(text)

    local version, body = text:match("^(%u%u%d)%s+(.+)$")

    if version ~= Contribute.formatVersion then
        return nil, "not a Completion Navigator export "
            .. "(expected " .. Contribute.formatVersion .. ")"
    end

    local edges = {}

    local count = 0

    for entry in body:gmatch("%S+") do
        local questID, list = entry:match("^(%d+):([%d,]+)$")

        if not questID then
            return nil, "malformed entry: " .. entry
        end

        local prerequisites = {}

        for id in list:gmatch("%d+") do
            table.insert(prerequisites, tonumber(id))
        end

        if #prerequisites == 0 then
            return nil, "entry with no prerequisites: " .. entry
        end

        edges[tonumber(questID)] = prerequisites

        count = count + 1
    end

    if count == 0 then
        return nil, "no entries"
    end

    return edges, nil, count
end

------------------------------------------------------------
-- IMPORTING
------------------------------------------------------------

-- Imported chains land in their OWN store and are published as
-- observedRequires, never as requires.
--
-- The distinction is the whole safety model: curated data is something a
-- human checked, an observation is something the addon watched, and a
-- contribution is something a stranger's addon watched. The third must never
-- be able to present itself as the first, and /cn why has to be able to tell
-- the player which it is looking at.
function Contribute.Import(text)
    local edges, err, count = Contribute.Parse(text)

    if not edges then
        return false, err
    end

    local store = CN.Account("contributed")

    local added = 0

    for questID, prerequisites in pairs(edges) do
        if not store[questID] then
            added = added + 1
        end

        store[questID] = prerequisites

        -- TAGGED WITH WHERE IT CAME FROM.
        --
        -- The command promises that `/cn why` "will say the chain came from a
        -- contribution rather than from curated data", and it did not: an
        -- imported edge was indistinguishable from a locally observed one, so
        -- the eligibility checker formatted it as "seen first on N
        -- characters" -- with N read from the harvest store, which has no
        -- record of an imported quest and therefore answered zero. The player
        -- was told the addon had watched the ordering hold on ZERO
        -- characters, which is both a false provenance claim and nonsense as
        -- evidence.
        CN.AddDependency(CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID), {
            observedRequires = prerequisites,
            origin           = "contributed",
        })
    end

    CN.InvalidateCandidates()

    return true, nil, count, added
end

-- AND THE EDGES GO WITH IT. 0.82.0.
--
-- This cleared the account store and left the DEPENDENCY GRAPH, which is
-- where an imported chain actually does its work: `Import` publishes each one
-- through `CN.AddDependency`, that function only ever merges, and nothing in
-- the addon removes an edge. So `/cn contribute forget` printed "Forgot 47
-- imported chains" and every quest they named stayed LOCKED, still explained
-- as "from an imported chain, not from your own play", until the player
-- reloaded. It did not invalidate the candidate cache either, which `Import`
-- does -- so the list stayed as the import had left it.
--
-- Only edges this module published are withdrawn. A quest the player's own
-- harvest also observed keeps its own edge, which is why both writers now
-- state their provenance.
function Contribute.Forget()
    local store = CN.Account("contributed")

    local count = CN.CountKeys(store)

    for questID in pairs(store) do
        store[questID] = nil

        local dependency = CN.GetDependency(
            CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID))

        if dependency and dependency.origin == "contributed" then
            dependency.observedRequires = nil
            dependency.origin           = nil
        end
    end

    -- AND THE PLAYER'S OWN EDGES COME BACK. 0.83.0.
    --
    -- 0.82.0's guard -- withdraw only edges stamped "contributed" -- is
    -- correct at login, where load order makes the harvest publisher run
    -- last and win. It is wrong for an import made DURING a session:
    -- `CN.AddDependency` merges field by field, so the import overwrites
    -- both the requirements and the origin of a quest the player had also
    -- harvested, and `Harvest.PublishConfident` is called from its login
    -- hook and nowhere else -- so nothing puts it back until a reload.
    --
    -- Two things went wrong from that. Between the import and the reload,
    -- `/cn why` reported the player's own three-character observation as
    -- "not from your own play". And after this function ran, the harvested
    -- edge was gone entirely: a quest the addon had correctly held LOCKED
    -- became AVAILABLE, offered by `/cn next` and routed to a quest giver
    -- who would not talk to the player.
    --
    -- Republishing costs one walk of the harvest store and is the only
    -- thing that can restore an edge this function cannot tell apart.
    local harvest = CN:GetModule("Harvest")

    if harvest and harvest.PublishConfident then
        pcall(harvest.PublishConfident)
    end

    CN.InvalidateCandidates()

    return count
end

CN:OnLogin(function()
    -- Re-publish on login, because the dependency graph is rebuilt from
    -- scratch each session and imported edges would otherwise silently stop
    -- applying the next time the player logged in.
    local store = CN.Account("contributed")

    for questID, prerequisites in pairs(store) do
        CN.AddDependency(CN.ObjectiveKey(CN.objectiveTypes.QUEST, questID), {
            observedRequires = prerequisites,
            origin           = "contributed",
        })
    end
end)

------------------------------------------------------------
-- COMMAND
------------------------------------------------------------

-- WHERE A CLAIM CAME FROM, ROW BY ROW. 0.67.0.
--
-- Backlog item 13. The addon draws prerequisite chains from four sources, in
-- a deliberate order of authority -- curated data, this character's own
-- harvest, rows other players contributed, rows imported by hand -- and
-- `/cn why` says which one a particular answer came from. What nothing could
-- do was ask the opposite question: *which* of the things I am being told
-- have never been checked by anybody?
--
-- That matters because the two weakest sources grow on their own. A harvest
-- row is promoted the moment three characters agree, and a contributed row
-- arrives believed. Neither has ever been read by a person, and without a
-- list of them nobody can start.
function Contribute.Provenance()
    local rows = {}

    local harvestModule = CN:GetModule("Harvest")

    local threshold = (harvestModule and harvestModule.confidenceThreshold) or 3

    local harvest = CN.Account("questHarvest")

    for questID, record in pairs(harvest or {}) do
        local observed = record.observedRequires

        if type(observed) == "table" and #observed > 0 then
            table.insert(rows, {
                questID = questID,
                origin  = "harvested",
                count   = #observed,
                detail  = "seen on " .. tostring(threshold)
                    .. "+ of your own characters",
            })
        end
    end

    for questID, record in pairs((CN.Static and CN.Static.community) or {}) do
        if type(record) == "table" and type(record.requires) == "table" then
            table.insert(rows, {
                questID = questID,
                origin  = "community",
                count   = #record.requires,
                detail  = record.sources
                    and (CN.Count(record.sources, "independent contribution"))
                    or "shipped without a source count",
            })
        end
    end

    for questID, requires in pairs(CN.Account("contributed") or {}) do
        if type(requires) == "table" and #requires > 0 then
            table.insert(rows, {
                questID = questID,
                origin  = "imported",
                count   = #requires,
                detail  = "imported on this account by hand",
            })
        end
    end

    table.sort(rows, function(a, b)
        if a.origin ~= b.origin then
            return a.origin < b.origin
        end

        return a.questID < b.questID
    end)

    return rows
end

CN:RegisterCommand{
    name    = "provenance",
    args    = "[origin]",
    order   = 37.5,
    help    = "Which chain claims have never been checked by a person.",
    handler = function(args)
        local wanted = string.lower(CN.Trim(args or ""))

        local rows = Contribute.Provenance()

        local curated = 0

        for _ in pairs((CN.Static and CN.Static.quests) or {}) do
            curated = curated + 1
        end

        Print("Curated rows, each one checked by hand: " .. curated)

        Print("Rows believed on evidence rather than on a reading: "
            .. #rows .. " |cff8a8f96("
            .. ((CN.Static and CN.Static.CommunityCount
                and CN.Static.CommunityCount()) or 0)
            .. " of them shipped with the addon)|r")

        if #rows == 0 then
            Print("|cff8a8f96Nothing unchecked. Play with |cffffc74f/cn "
                .. "harvestnow|r on and this fills from your own play.|r")
            return
        end

        local shown = 0

        for _, row in ipairs(rows) do
            if wanted == "" or wanted == row.origin then
                shown = shown + 1

                if shown <= 20 then
                    local quests = CN:GetModule("Quests")

                    local name = quests and quests.GetName(row.questID)

                    CN.PrintLine("  " .. row.origin .. " |cffffc74f"
                        .. tostring(name or ("Quest " .. row.questID))
                        .. "|r |cff8a8f96(" .. row.questID .. ") "
                        .. CN.Count(row.count, "prerequisite") .. CN.DASH
                        .. row.detail .. "|r")
                end
            end
        end

        if shown > 20 then
            Print("|cff8a8f96... and " .. (shown - 20) .. " more. "
                .. "|cffffc74f/cn provenance harvested|r, |cffffc74f"
                .. "community|r or |cffffc74fimported|r narrows it.|r")
        elseif shown == 0 then
            Print("|cff8a8f96Nothing with that origin. Try harvested, "
                .. "community or imported.|r")
        end

        Print("|cff8a8f96None of these is presented to you as fact"
            .. CN.DASH .. "|cffffc74f/cn why|r names the source on every "
            .. "answer that uses one. This list is where checking them "
            .. "starts.|r")
    end,
}

CN:RegisterCommand{
    name    = "contribute",
    args    = "[import <text>, or forget]",
    order   = 37,
    help    = "Share the quest chains you have learned, or take somebody "
        .. "else's.",
    handler = function(args)
        args = CN.Trim(args or "")

        local verb, rest = args:match("^(%S+)%s*(.*)$")

        verb = verb and string.lower(verb) or ""

        if verb == "forget" then
            Print("Forgot " .. CN.Count(Contribute.Forget(), "imported chain")
                .. ".")
            return
        end

        if verb == "import" then
            local ok, err, count, added = Contribute.Import(rest)

            if not ok then
                Print("|cffe2564cNot imported:|r " .. tostring(err))
                return
            end

            Print("Imported " .. CN.Count(count, "chain")
                .. ", " .. added .. " new.")
            Print("|cff8a8f96They are recorded as observations, not as facts: "
                .. "|cffffc74f/cn why|r will say the chain came from a "
                .. "contribution rather than from curated data.|r")
            return
        end

        local export, err, count = Contribute.Build()

        if not export then
            Print("Nothing to contribute yet.")
            Print("|cff8a8f96" .. tostring(err) .. "|r")
            return
        end

        Print(CN.Count(count, "chain")
            .. " ready to share. This text and nothing else:")
        Print("|cffffc74f" .. export .. "|r")
        Print("|cff8a8f96It contains quest IDs and orderings. No character "
            .. "name, no realm, no timestamps, no coordinates" .. CN.DASH .. "read it "
            .. "before you send it, which is rather the point of a format you "
            .. "can read.|r")
        Print("Paste it into an issue on the tracker and it ships to everyone "
            .. "in a later release.")
    end,
}

return Contribute
'@

$Embedded['Modules\Welcome.lua'] = @'
-- Modules/Welcome.lua
-- Completion Navigator :: the first sixty seconds.
--
-- An addon is judged before it is understood. This one opened with a slash
-- command and a list of things the player had not asked about, which is a
-- perfectly honest way to present a tool and a poor way to introduce one.
--
-- WHAT THIS IS.
--
-- One question, asked once: what are you playing for right now? The answer
-- sets the focus mode, which the addon already supports and which almost
-- nobody discovers, because `/cn mode collecting` is a sentence you have to
-- already know to type.
--
-- WHAT IT IS NOT.
--
--   * It is not a wizard. One screen, four buttons, and a way out.
--   * It does not run again. Ever. An addon that re-introduces itself is an
--     addon that has not noticed you already met.
--   * It does not block anything. Close it and every command still works
--     exactly as before -- nothing here is a gate.
--   * It changes only the focus, which `/cn mode off` reverses completely.
--     A first-run screen that quietly reconfigures things is a first-run
--     screen people learn to distrust.

local ADDON_NAME, CN = ...

local Welcome = CN:RegisterModule("Welcome")

local Print = CN.Print

------------------------------------------------------------
-- STATE
------------------------------------------------------------

local function Account()
    return CN.Account()
end

function Welcome.HasSeen()
    local account = Account()

    return account and account.welcomed and true or false
end

function Welcome.MarkSeen()
    local account = Account()

    if account then
        account.welcomed = true
    end
end

------------------------------------------------------------
-- THE CHOICES
------------------------------------------------------------

-- Four, because five is a menu and three leaves out collecting or levelling,
-- which are the two most common answers. Each maps onto a focus that already
-- exists rather than inventing new behaviour for the occasion.
-- ONE SOURCE FOR WHAT A FOCUS IS CALLED AND WHAT IT DOES.
--
-- These carried their own `label` and `note`, and all four had drifted from
-- `CN.modes` -- which is what the Settings tab, `/cn mode` and `/cn status`
-- all read. Three of the four were merely different words for the same thing.
-- The fourth was wrong: the first-run screen described Levelling as "Quests
-- first, collections quiet", and `leveling.show` is `{ QUEST, EXPLORATION }`,
-- which HIDES seventeen of the nineteen types. "Quiet" and "gone" are not the
-- same promise, and this is the screen where the promise is made.
--
-- Names and descriptions come from `CN.modes` now. A mode renamed there is
-- renamed here, and cannot say two things at once.
Welcome.choices = {
    { mode = "leveling" },
    { mode = "collecting" },
    { mode = "reputation" },
    { mode = "everything" },
}

-- What the button says, and what the line under it says.
function Welcome.Describe(mode)
    local definition = CN.modes and CN.modes[mode]

    if not definition then
        return tostring(mode), nil
    end

    return definition.label or tostring(mode), definition.note
end

function Welcome.Choose(mode)
    Welcome.MarkSeen()

    -- "A BIT OF EVERYTHING" SET NOTHING, AND SAID IT HAD.
    --
    -- This short-circuited before `ApplyMode`, so the click handler printed
    -- "Focus set to everything" while `/cn mode` reported no focus and `/cn
    -- mode off` answered "No focus was set, so nothing changed." Worse: with
    -- a focus already active -- from an earlier `/cn mode collecting`, say --
    -- picking "a bit of everything" left thirteen types hidden and told the
    -- player the focus was now everything.
    --
    -- `CN.modes.everything` exists and does exactly the right thing.
    if not mode then
        mode = "everything"
    end

    local filters = CN:GetModule("Filters")

    if filters and filters.ApplyMode then
        filters.ApplyMode(mode)
    end

    CN.InvalidateCandidates()

    return true, mode
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

local frame

function Welcome.Build()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorWelcome", UIParent,
        BackdropTemplateMixin and "BackdropTemplate" or nil)

    frame:SetSize(432, 300)
    frame:SetPoint("CENTER")
    frame:SetFrameStrata("DIALOG")
    frame:EnableMouse(true)
    frame:SetMovable(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetScript("OnDragStart", frame.StartMoving)
    frame:SetScript("OnDragStop", frame.StopMovingOrSizing)

    -- ESCAPE CLOSES IT, LIKE EVERY OTHER PANEL IN THE GAME.
    --
    -- Three frames this addon creates were on this list and one was not: the
    -- welcome screen -- the only frame most players ever see, shown once, on
    -- first login, over a character they have just logged into. Escape did
    -- nothing, and the close button is a small X in a corner of a dialog that
    -- appears without being asked for.
    if UISpecialFrames then
        table.insert(UISpecialFrames, "CompletionNavigatorWelcome")
    end

    if frame.SetBackdrop then
        frame:SetBackdrop({
            bgFile   = "Interface\\DialogFrame\\UI-DialogBox-Background",
            edgeFile = "Interface\\DialogFrame\\UI-DialogBox-Border",
            tile = true, tileSize = 32, edgeSize = 32,
            insets = { left = 8, right = 8, top = 8, bottom = 8 },
        })
    end

    local title = CN.Label(frame, "OVERLAY", "TITLE")
    title:SetPoint("TOP", 0, -18)
    title:SetText("Completion Navigator")

    local body = CN.Label(frame, "OVERLAY", "BODY")
    body:SetPoint("TOPLEFT", 24, -48)
    body:SetPoint("TOPRIGHT", -24, -48)
    body:SetJustifyH("LEFT")
    body:SetText("What are you playing for at the moment? This only sets a "
        .. "starting focus " .. CN.DASH .. " everything is still tracked, and "
        .. CN.Accent("/cn mode off") .. " puts it back.")

    -- THE ONE THING THAT ACTUALLY MATTERS, AS A BUTTON.
    --
    -- This screen arrives at the single moment a new player is engaged and
    -- looking at the addon's own interface, and it offered four flavour
    -- presets and no way to do the required step. `/cn setup` was mentioned
    -- in CHAT, after the click. Somebody who pressed "Not now" was told
    -- "Right. /cn whenever you want it." and never heard about it again that
    -- session.
    --
    -- Offered, not run, which is the standing rule -- but offered where the
    -- player is, rather than in a line that scrolls away under login chatter.
    local scan = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")

    scan:SetSize(384, 26)
    scan:SetPoint("TOPLEFT", 24, -96)
    scan:SetText("Read my collections now (a few seconds)")
    -- The client built this label, so `CN.Label` never saw it and the
    -- text-size setting did not reach it. 0.69.0.
    CN.AdoptLabel(scan:GetFontString(), "CAPTION")

    scan:SetScript("OnClick", function()
        local setup = CN:GetModule("Setup")

        if setup then
            scan:SetEnabled(false)
            scan:SetText("Reading" .. CN.DOT .. CN.DOT .. CN.DOT)

            setup.Run(function()
                -- A STATUS MESSAGE IS NOT A BUTTON.
                --
                -- This left a permanently disabled, greyed 384-pixel control
                -- reading "Read. /cn asks what is next." -- a sentence shaped
                -- like something you press.
                if scan and scan.Hide then
                    scan:Hide()
                end

                if frame and frame.scanNote then
                    frame.scanNote:SetText(CN.Good("Read.") .. " "
                        .. CN.Muted("Close this and try ")
                        .. CN.Accent("/cn") .. CN.Muted("."))
                end

                -- The scan is the thing this screen was open for. Once it has
                -- run there is nothing left to do here.
                if frame and frame.Hide then
                    frame:Hide()
                end
            end)
        end
    end)

    frame.scan = scan

    -- Where the scan reports, so the button does not have to become a label.
    frame.scanNote = CN.Label(frame, "OVERLAY", "SMALL")
    frame.scanNote:SetPoint("TOPLEFT", scan, "BOTTOMLEFT", 0, -2)
    frame.scanNote:SetPoint("RIGHT", scan, "RIGHT")
    frame.scanNote:SetJustifyH("LEFT")
    frame.scanNote:SetText("")

    local previous

    for index, choice in ipairs(Welcome.choices) do
        local button = CreateFrame("Button", nil, frame,
            "UIPanelButtonTemplate")

        local label = Welcome.Describe(choice.mode)

        button:SetSize(180, 24)
        button:SetText(label)
        -- The client built this label, so `CN.Label` never saw it and the
        -- text-size setting did not reach it. 0.69.0.
        CN.AdoptLabel(button:GetFontString(), "CAPTION")

        if index == 1 then
            button:SetPoint("TOPLEFT", 24, -140)
        elseif index == 2 then
            button:SetPoint("TOPLEFT", previous, "TOPRIGHT", 12, 0)
        elseif index == 3 then
            button:SetPoint("TOPLEFT", 24, -172)
        else
            button:SetPoint("TOPLEFT", previous, "TOPRIGHT", 12, 0)
        end

        button:SetScript("OnClick", function()
            local _, mode = Welcome.Choose(choice.mode)

            local lines = {
                CN.Accent("/cn") .. CN.Muted(" asks what is next. ")
                    .. CN.Accent("/cn ui") .. CN.Muted(" opens the window."),
            }

            local setup = CN:GetModule("Setup")

            if setup and setup.HasRun and not setup.HasRun() then
                table.insert(lines, CN.Muted("It has not read your "
                    .. "collections yet. ") .. CN.Accent("/cn setup")
                    .. CN.Muted(" does that once."))
            end

            -- THE LABEL THE PLAYER CLICKED, NOT THE TABLE KEY.
            --
            -- This printed `mode`, which is the internal key -- so clicking
            -- the button marked "Reputation" answered "Focus: reputation",
            -- and clicking "Levelling" answered "Focus: leveling", in
            -- American spelling, in an addon that writes colour and
            -- levelling everywhere else. `/cn mode` has always done this
            -- correctly.
            local chosenLabel, chosenNote = Welcome.Describe(mode)

            if chosenNote then
                table.insert(lines, 1, CN.Muted(chosenNote))
            end

            CN.PrintBlock("Focus: " .. CN.Accent(chosenLabel)
                .. CN.Aside(CN.Accent("/cn mode off") .. " undoes it"), lines)

            -- ANSWERING THE QUESTION MUST NOT DESTROY THE CALL TO ACTION.
            --
            -- This screen's primary action is the scan button at the top, and
            -- every focus button closed the frame -- so a player who answered
            -- the question it asked lost the button that does the one setup
            -- step the addon needs, and the only recovery was a chat line
            -- that scrolls away under login chatter.
            --
            -- The choice is marked instead, and the frame stays open until
            -- the scan runs, "Not now" is pressed, or Escape is.
            for _, other in ipairs(frame.choiceButtons or {}) do
                other:SetText(Welcome.Describe(other.cnMode))
            end

            button:SetText(CN.Good("|cff73b873>|r ") .. label)
        end)

        button.cnMode = choice.mode

        frame.choiceButtons = frame.choiceButtons or {}

        table.insert(frame.choiceButtons, button)

        previous = button
    end

    local note = CN.Label(frame, "OVERLAY", "LABEL")
    note:SetPoint("BOTTOMLEFT", 24, 46)
    note:SetPoint("BOTTOMRIGHT", -24, 46)
    note:SetJustifyH("LEFT")
    -- SAY WHAT IS ACTUALLY TRUE OF ALL THREE VERBS.
    --
    -- "Nothing is scanned, sent or changed until you ask" is exactly right
    -- about scanning and sending, and a player will read it as covering the
    -- third: preference learning is on by default and does quietly reweight
    -- the ranking from what they go and do. Nothing leaves the machine, so
    -- this is not a privacy defect -- it is a promise that needs one more
    -- clause to stay true.
    note:SetText("Nothing is scanned or sent until you ask. It does notice "
        .. "which kinds of thing you go and do" .. CN.DASH .. "/cn learned shows what, and "
        .. "undoes it. This appears once.")

    local dismiss = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
    dismiss:SetSize(120, 22)
    dismiss:SetPoint("BOTTOM", 0, 16)
    dismiss:SetText("Not now")
    -- The client built this label, so `CN.Label` never saw it and the
    -- text-size setting did not reach it. 0.69.0.
    CN.AdoptLabel(dismiss:GetFontString(), "CAPTION")
    dismiss:SetScript("OnClick", function()
        Welcome.MarkSeen()

        Print("Right. |cffffc74f/cn|r whenever you want it.")

        frame:Hide()
    end)

    frame:Hide()

    return frame
end

function Welcome.Show()
    local built = Welcome.Build()

    if built then
        built:Show()

        -- SHOWN COUNTS AS SEEN.
        --
        -- This marked the window seen only on the button handlers, so a
        -- player who read it and closed it -- or ignored it -- got it again
        -- on every login, against this file's own promise that "it does not
        -- run again. Ever." Answering the question is a choice; being asked
        -- twice is not.
        Welcome.MarkSeen()

        return true
    end

    -- No frame available -- a headless test, or a client that refuses to
    -- create one. Say the same thing in chat rather than silently doing
    -- nothing.
    Print("Installed. |cffffc74f/cn mode leveling|r, "
        .. "|cffffc74fcollecting|r, |cffffc74freputation|r or just "
        .. "|cffffc74f/cn|r to begin.")

    Welcome.MarkSeen()

    return false
end

CN:OnLogin(function()
    if Welcome.HasSeen() then
        return
    end

    -- After the login chatter, and after the setup reminder has had its turn.
    -- Two things talking at once on a first login is worse than either alone.
    --
    -- FOURTEEN SECONDS, NOT EIGHT. The setup reminder is also scheduled at
    -- eight, and because this module loads first its timer fired FIRST -- the
    -- exact opposite of what the sentence above promised, and the player got
    -- the modal with two lines of setup reminder appearing underneath it.
    -- A comment describing an ordering that the code leaves to load order is
    -- not an ordering.
    if C_Timer and C_Timer.After then
        C_Timer.After(14, function()
            if not Welcome.HasSeen() then
                Welcome.Show()
            end
        end)
    end
end)

CN:RegisterCommand{
    name    = "welcome",
    order   = 38,
    help    = "Show the first-run question again.",
    handler = function()
        Welcome.Show()
    end,
}

return Welcome
'@

$Embedded['Modules\Hud.lua'] = @'
-- Modules/Hud.lua
-- Completion Navigator :: a small always-on frame, and the settings that make
-- the whole addon legible.
--
-- THE HUD.
--
-- Off by default, like everything in this addon that puts pixels on the
-- screen uninvited. It shows one line -- what to do next -- and nothing else,
-- because a heads-up display that needs reading is not a heads-up display.
--
-- Distinct from Follow's frame, which appears only while a route is being
-- walked and shows the current stop. This is for the player who is not
-- following anything and wants the answer visible while they get on with
-- something else.
--
-- ACCESSIBILITY.
--
-- Two settings that cost almost nothing and matter a great deal to the people
-- who need them:
--
--   * A scale, because the default font is small and not everybody's monitor
--     is two feet away.
--   * A colourblind mode for the navigation arrow. The arrow's whole language
--     is colour -- blue on course, amber drifting, red walking away -- which
--     is exactly the design that fails eight percent of men. In this mode the
--     arrow carries a short text label as well, so the information survives
--     the colour being indistinguishable.
--
-- The rule behind both: no information carried by colour alone.

local ADDON_NAME, CN = ...

local Hud = CN:RegisterModule("Hud")

local Print = CN.Print

------------------------------------------------------------
-- SETTINGS
------------------------------------------------------------

-- Named `Preferences`, not `Settings`.
--
-- `Settings` is also the name of the client's global options API since 10.0,
-- and this file's options-panel registration reads `Settings.RegisterCanvas-
-- LayoutCategory` -- which resolved to this local FUNCTION and threw
-- "attempt to index a function value" on every login on every retail client.
-- The error was caught and printed, and because it aborted the function the
-- pre-10.0 fallback below never ran either: the addon has never appeared in
-- the game's own options list, which is the entire purpose of that block.
--
-- The harness never defined SettingsPanel, so the `and` chain short-circuited
-- before the bad index and the suite saw nothing. Same shape as the invented
-- event name: a stub more forgiving than the client.
local function Preferences()
    return CN.Settings() or {}
end

function Hud.IsEnabled()
    return Preferences().hud == true
end

function Hud.Scale()
    local scale = tonumber(Preferences().uiScale)

    if not scale or scale < 0.7 or scale > 2.0 then
        return 1
    end

    return scale
end

function Hud.IsColourblind()
    return Preferences().colourblind == true
end

------------------------------------------------------------
-- THE FRAME
------------------------------------------------------------

local frame, ticker

-- Sixteen for the button plus two of margin. See where the label is anchored.
-- `Hud.closeWidth` REMOVED. 0.78.0: it restated the width the control itself
-- sizes from, in another file. `CN.CLOSE_WIDTH` is the one number.

local function Build()
    if frame or not CreateFrame then
        return frame
    end

    frame = CreateFrame("Frame", "CompletionNavigatorHud", UIParent)

    frame:SetSize(260, 34)

    -- MEDIUM, LIKE EVERY OTHER FRAME THIS ADDON PUTS OVER THE WORLD.
    --
    -- This was BACKGROUND, the lowest strata above the world itself -- and it
    -- is the only frame in the addon that was: the arrow and the follow
    -- frame, which sit over the world in exactly the same way, are both
    -- MEDIUM. At BACKGROUND anything else on screen takes the mouse first,
    -- so the line could not be dragged and its two click actions did nothing,
    -- while its own tooltip promised all three.
    --
    -- Reported from play: "the heads up box should be able to be dragged
    -- around to a different location".
    frame:SetFrameStrata("MEDIUM")
    frame:SetMovable(true)
    frame:EnableMouse(true)
    frame:RegisterForDrag("LeftButton")
    frame:SetClampedToScreen(true)

    CN.RestoreFramePosition(frame, Preferences().hudPosition,
        { point = "TOP", relativePoint = "TOP", x = 0, y = -220 })

    -- A PANEL, AND THE ADDON'S OWN MARK ON IT.
    --
    -- The heads-up line and the follow frame were both bare frames with text
    -- hung on them -- no background, no edge, no padding -- while the main
    -- window used a Blizzard template and the welcome screen used parchment.
    -- Three idioms in one addon, and two of them read as text that had come
    -- loose from something.
    --
    -- `UI.PaintPanel` already draws a flat fill and a one-pixel border owing
    -- nothing to any template, which is why it survives Blizzard retiring
    -- one. Low alpha, because this sits over the world and a black box is
    -- worse than no box.
    if CN.UI and CN.UI.PaintPanel then
        CN.UI.PaintPanel(frame, 0.04, 0.05, 0.07, 0.55)
    end

    -- Two pixels of brand blue down the left edge. The cheapest mark in the
    -- addon: it appears here, on the follow frame and under the selected tab,
    -- and it is what makes the three read as one product.
    local rule = frame:CreateTexture(nil, "ARTWORK")
    rule:SetPoint("TOPLEFT")
    rule:SetPoint("BOTTOMLEFT")
    rule:SetWidth(2)
    rule:SetColorTexture(CN.Rgb("BRAND"))
    rule:SetAlpha(0.9)

    local inset = CN.SPACE.S

-- The width the close control reserves along the top-right edge. Declared
-- before the label, which has to keep clear of it.

    -- ROOM FOR THE CLOSE BUTTON.
    --
    -- The X is 16 wide at the top-right corner, and alpha 0 does not disable
    -- mouse input -- so the last stretch of a long objective name sat under a
    -- button that turns the line off rather than navigating to it. The label
    -- stops short of it instead.
    frame.label = CN.Label(frame, "OVERLAY", "HEAD")
    frame.label:SetPoint("TOPLEFT", inset, -inset)
    frame.label:SetPoint("TOPRIGHT", -(inset + CN.CLOSE_WIDTH), -inset)
    frame.label:SetJustifyH("LEFT")

    frame.detail = CN.Label(frame, "OVERLAY", "SMALL")
    frame.detail:SetPoint("TOPLEFT", frame.label, "BOTTOMLEFT", 0, -CN.SPACE.XS)
    frame.detail:SetPoint("TOPRIGHT", frame.label, "BOTTOMRIGHT", 0, -CN.SPACE.XS)
    frame.detail:SetJustifyH("LEFT")

    CN.Outline(frame.label, 13, "PRIMARY")
    CN.Outline(frame.detail, 11, "MUTED")

    frame:SetScript("OnDragStart", frame.StartMoving)
    frame:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()

        Preferences().hudPosition = CN.SaveFramePosition(self)
            or Preferences().hudPosition
    end)

    -- IT NAMES THE NEXT THING AND COULD NOT BE CLICKED.
    --
    -- The frame was mouse-enabled for dragging and showed the current
    -- recommendation -- so the player read "Kill Ten Rats" on their own
    -- screen and then typed `/cn go`. The two actions the Next tab offers for
    -- the same objective are a left and a right click away, and neither
    -- fights the drag: `OnMouseUp` fires on a click, not on a drag.
    frame:RegisterForDrag("LeftButton")

    frame:SetScript("OnMouseUp", function(clicked, button)
        -- THE ONE IT IS SHOWING, NOT THE ONE SOMETHING ELSE SELECTED.
        --
        -- This read `CN.currentRecommendation`, which only the Next tab,
        -- `/cn next`, the minimap right-click and auto-advance ever write.
        -- A player who turned the heads-up line on and never opened the
        -- window had it nil for the whole session: the line named an
        -- objective, its tooltip promised two clicks, and both did nothing
        -- with no message. And when they diverged -- row 7 selected on the
        -- Next tab -- the line showed #1 and clicking it navigated to 7.
        local objective = clicked.objective or CN.currentRecommendation

        if not objective then
            return
        end

        if button == "RightButton" then
            CN.SetDeferred(objective.type, objective.id, 3600)

            CN.Print("Deferred for an hour: "
                .. tostring(objective.name or objective.id)
                .. CN.Aside(CN.Accent("/cn unhide " .. tostring(objective.id))
                    .. " brings it back now"))

            CN.InvalidateCandidates()

            Hud.Refresh()

            return
        end

        CN.NavigateToObjective(objective)
    end)

    -- A WAY OUT, ON THE THING ITSELF.
    --
    -- Turning this off meant knowing that `/cn hud` exists, or finding the
    -- checkbox on the Settings tab of a window you have to open first. A
    -- frame that appears over the world and cannot be dismissed from itself
    -- is a frame people uninstall the addon to be rid of.
    --
    -- Reported from play: it "should also be able to be closed or turned off
    -- by clicking an x or other appropriate icon or button in or on the heads
    -- up box itself".
    -- THROUGH THE ONE HELPER. 0.77.0.
    --
    -- This was the first of these and it was the only one: the follow list
    -- and the arrow are also drawn over the world, also mouse-enabled, also
    -- draggable, and offered no way out at all. Hoisted into
    -- `CN.AttachCloseControl` so all three read from one definition rather
    -- than two of them going without.
    CN.AttachCloseControl(frame,
        function()
            -- TURNED OFF, NOT HIDDEN.
            --
            -- Hiding it would bring it back on the next refresh, and a
            -- control that undoes itself is worse than no control. This is
            -- the same setting the Settings checkbox and `/cn hud` write, so
            -- all three agree afterwards.
            Hud.SetEnabled(false)

            CN.Print("Heads-up line off. " .. CN.Aside(CN.Accent("/cn hud")
                .. " brings it back"))
        end,
        "Click to navigate to this. Right-click to put it off for an hour. "
        .. "Drag to move this line. The x turns it off.",
        "Turn the heads-up line off. /cn hud brings it back.")

    frame:SetScale(Hud.Scale())

    frame:Hide()

    return frame
end

Hud.Build = Build

function Hud.Refresh()
    if not frame or not Hud.IsEnabled() then
        return false
    end

    local results = CN.Recommend(1)

    local objective = results and results[1]

    if not objective then
        frame.objective = nil

        -- THROUGH THE LOCALE TABLE, LIKE THE OTHER CALL SITE. 0.64.0.
        --
        -- `Modules/Broker.lua` prints `CN.L["nothing actionable"]` for the
        -- same state. The key is canonical and translated in all ten shipped
        -- locale files, and the build lint only requires that a key be used
        -- ONCE -- so a second, hardcoded copy of the same sentence passed
        -- every check. A German player read "nichts zu tun" in the broker
        -- feed and "nothing actionable" an inch away on the heads-up line.
        frame.label:SetText(CN.Muted(CN.L["nothing actionable"]))
        frame.detail:SetText("")

        return true
    end

    -- What the line is showing IS what clicking it acts on. See OnMouseUp.
    frame.objective = objective

    frame.label:SetText(tostring(objective.name or objective.id))

    local detail = CN.FirstReason(objective)

    -- WHILE A ROUTE IS BEING WALKED, SAY HOW FAR THROUGH IT YOU ARE.
    --
    -- The reason line is the right thing to show when nothing else is
    -- happening. It is the wrong thing when the player is nine stops into a
    -- twelve-stop route, which is exactly when a glanceable frame earns its
    -- place on the screen.
    local follow = CN:GetModule("Follow")

    if follow and follow.active and (follow.startedWith or 0) > 0 then
        -- ONE PHRASING PER QUANTITY.
        --
        -- This said "stop 4 of 12" -- counted over hubs in the route -- while
        -- the follow frame two inches away said "Stop: 3 of 5 left", counted
        -- over objectives at the current hub. Two frames on screen at once,
        -- describing the same activity in near-identical words with unrelated
        -- numbers. The follow frame now says "3 left here"; this one keeps
        -- the route-level count, which is the one a glanceable line wants.
        -- TRANSLATED. 0.78.0: this sat two lines under a `CN.L` lookup and
        -- was assembled from an English literal, which is the same defect as
        -- the route-complete line one frame away.
        detail = string.format(CN.L["stop %d of %d"],
            math.min((follow.completed or 0) + 1, follow.startedWith),
            follow.startedWith)
    end

    frame.detail:SetText(detail and ("|cff8a8f96" .. detail .. "|r") or "")

    return true
end

function Hud.SetEnabled(enabled)
    Preferences().hud = enabled and true or nil

    if enabled then
        Build()

        if frame then
            frame:SetScale(Hud.Scale())
            frame:Show()
        end

        -- Slow on purpose. The answer to "what next" changes when the player
        -- does something, not several times a second, and a HUD that
        -- recomputes constantly is a HUD that costs frames for nothing.
        if C_Timer and C_Timer.NewTicker and not ticker then
            ticker = C_Timer.NewTicker(5, function()
                pcall(Hud.Refresh)
            end)
        end

        Hud.Refresh()
    else
        if frame then
            frame:Hide()
        end

        if ticker then
            ticker:Cancel()
            ticker = nil
        end
    end

    return Hud.IsEnabled()
end

CN:OnLogin(function()
    if Hud.IsEnabled() then
        Hud.SetEnabled(true)
    end

    -- THE TEXT SIZE SILENTLY REVERTED ON EVERY RELOAD.
    --
    -- `ApplyScale` is what scales the window, the arrow, the follow frame and
    -- the welcome frame, and it was called from exactly one place: the
    -- command that sets the number. So a player who set Size 1.50 saw it
    -- apply, reloaded, and got everything except the heads-up line back at
    -- 1.0 -- with the button still reading "Size 1.50".
    --
    -- This is the accessibility control the settings rebuild existed for,
    -- because "the players who most need a larger interface are the least
    -- likely to find /cn scale 1.4 in a hundred-line help listing".
    Hud.ApplyScale()
end)

------------------------------------------------------------
-- ACCESSIBILITY APPLIED
------------------------------------------------------------

-- Everything the addon draws, at the player's scale.
-- SETTERS, so the window can offer these two.
--
-- Both accessibility controls were reachable only by typing a slash command,
-- which is the sharpest form of the problem: the players who most need a
-- larger interface or a hue-independent arrow are the least likely to find
-- `/cn scale 1.4`.
function Hud.SetScale(scale)
    scale = tonumber(scale)

    if not scale or scale < 0.7 or scale > 2.0 then
        return false
    end

    Preferences().uiScale = scale

    Hud.ApplyScale()

    return true
end

function Hud.SetColourblind(enabled)
    Preferences().colourblind = enabled or nil

    local navigation = CN:GetModule("Navigation")

    if navigation and navigation.Refresh then
        navigation.Refresh()
    end

    return Hud.IsColourblind()
end

function Hud.ApplyScale()
    local scale = Hud.Scale()

    for _, name in ipairs({
        "CompletionNavigatorFrame",
        "CompletionNavigatorHud",
        "CompletionNavigatorArrow",
        "CompletionNavigatorFollow",
        "CompletionNavigatorWelcome",
    }) do
        local target = _G and _G[name]

        if target and target.SetScale then
            -- A FRAME TALLER THAN THE SCREEN CANNOT BE CLAMPED ONTO IT.
            -- 0.85.0.
            --
            -- The window sets `SetClampedToScreen(true)`, which pins one edge
            -- and lets the opposite one overhang -- it cannot help with a
            -- frame that is simply bigger than the screen. UIParent is 768
            -- units tall, and 0.84.0 grew the window from 480 to 560: at the
            -- Size button's top step, 560 x 1.5 is 840. Forty-eight pixels of
            -- window off one end, applied at BUILD time rather than only when
            -- the button is pressed.
            --
            -- Which end depends on how the clamp resolves, and both are bad:
            -- the footer and the answer line, or the title bar, the close
            -- button and the filter box -- in which case the window can no
            -- longer be dragged or closed with the mouse. And the placement
            -- persists, because the position is saved.
            --
            -- 480 x 1.5 was 720 and fitted, which is why this has never come
            -- up before. The size the player asked for is honoured as far as
            -- the screen allows and no further.
            local applied = scale

            local room = (UIParent and UIParent.GetHeight
                and UIParent:GetHeight()) or 768

            local height = (target.GetHeight and target:GetHeight()) or 0

            if height > 0 and room > 0 and (height * applied) > room then
                applied = room / height
            end

            pcall(target.SetScale, target, applied)
        end
    end

    return scale
end

-- The word for a bearing, for players who cannot rely on the colour. Kept
-- very short: it sits under an arrow, not in a paragraph.
function Hud.BearingWord(relative)
    if not relative then
        return "?"
    end

    local off = math.abs(relative)

    -- THROUGH CN.L, LIKE EVERY OTHER STRING A PLAYER READS.
    --
    -- These four are translated into all ten shipped locales and were
    -- returned as English literals, so the one accessibility feature that
    -- exists for players who cannot use the arrow's colours spoke only
    -- English to nine of them.
    if off < 0.35 then
        return CN.L["ahead"]
    end

    if off < 1.2 then
        return CN.L["veer"]
    end

    if off < 2.4 then
        return CN.L["turn"]
    end

    return CN.L["back"]
end

------------------------------------------------------------
-- THE GAME'S OWN OPTIONS LIST
------------------------------------------------------------

-- The addon has had a settings tab since 0.15.0 and it lives inside a window
-- you have to know how to open. Somebody who installs an addon and goes
-- looking for its options goes to the game's options list, finds nothing, and
-- reasonably concludes it has none.
--
-- Registered defensively: the API was replaced wholesale in 10.0 and the old
-- one still exists on older clients, so both paths are here and neither is
-- assumed.
local registered = false

function Hud.RegisterOptionsPanel()
    if registered or not CreateFrame then
        return registered
    end

    local panel = CreateFrame("Frame")

    panel.name = "Completion Navigator"

    local title = CN.Label(panel, "ARTWORK", "TITLE")
    title:SetPoint("TOPLEFT", 16, -16)
    title:SetText("Completion Navigator")

    -- WHAT THIS PANEL SAYS IS WHAT A NEW PLAYER NEEDS FIRST.
    --
    -- It used to list six commands, three of which are display preferences,
    -- and point at bare `/cn`, which printed the addon's internal module
    -- list. It did not mention `/cn setup` -- the one step the addon's own
    -- first-run flow calls required -- so somebody who installed the addon
    -- and went straight to Options learned about text size and never learned
    -- that anything needed reading.
    --
    -- Three sentences and two buttons. The settings themselves live one click
    -- away, in the window, where there is room to group them.
    local body = CN.Label(panel, "ARTWORK", "BODY")
    body:SetPoint("TOPLEFT", 16, -48)
    body:SetPoint("TOPRIGHT", -16, -48)
    body:SetJustifyH("LEFT")
    body:SetText("Answers \"what should I do next?\" " .. CN.DASH .. " ranks what is worth "
        .. "doing now, costs the journey the way you would really make it, "
        .. "and shows its working when you ask why.\n\n"
        .. "1.  Scan once, so it knows what you have.\n"
        .. "2.  Type /cn to ask what is next.\n"
        .. "3.  Open the window for everything else. Its Settings tab has "
        .. "text size, the colourblind arrow labels, sound, and what the "
        .. "addon draws on screen.")

    local scan = CreateFrame("Button", nil, panel, "UIPanelButtonTemplate")
    scan:SetSize(190, 24)
    scan:SetPoint("TOPLEFT", 16, -190)
    scan:SetText("Scan my collections")
    -- The client built this label, so `CN.Label` never saw it and the
    -- text-size setting did not reach it. 0.69.0.
    CN.AdoptLabel(scan:GetFontString(), "CAPTION")
    scan:SetScript("OnClick", function()
        local setup = CN:GetModule("Setup")

        if setup then
            setup.Run()
        end
    end)

    local open = CreateFrame("Button", nil, panel, "UIPanelButtonTemplate")
    open:SetSize(160, 24)
    open:SetPoint("LEFT", scan, "RIGHT", 8, 0)
    open:SetText("Open the window")
    -- The client built this label, so `CN.Label` never saw it and the
    -- text-size setting did not reach it. 0.69.0.
    CN.AdoptLabel(open:GetFontString(), "CAPTION")
    open:SetScript("OnClick", function()
        if CompletionNavigator_ToggleUI then
            CompletionNavigator_ToggleUI()
        end
    end)

    local version = CN.Label(panel, "ARTWORK", "LABEL")
    version:SetPoint("TOPLEFT", scan, "BOTTOMLEFT", 0, -12)
    version:SetText("v" .. tostring(CN.version)
        .. "  " .. CN.DOT .. "  Dam Beaver Studios, LLC")

    -- Modern path first.
    if SettingsPanel and Settings and Settings.RegisterCanvasLayoutCategory
        and Settings.RegisterAddOnCategory then

        local ok, category = pcall(Settings.RegisterCanvasLayoutCategory,
            panel, panel.name)

        if ok and category then
            category.ID = panel.name

            pcall(Settings.RegisterAddOnCategory, category)

            registered = true
        end
    end

    -- The pre-10.0 API, still present on Classic clients.
    if not registered and InterfaceOptions_AddCategory then
        local ok = pcall(InterfaceOptions_AddCategory, panel)

        registered = ok and true or false
    end

    return registered
end

CN:OnLogin(function()
    Hud.RegisterOptionsPanel()
end)

------------------------------------------------------------
-- COMMANDS
------------------------------------------------------------

CN:RegisterCommand{
    name    = "hud",
    args    = "[on or off]",
    order   = 39,
    help    = "A small always-on line showing what to do next.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Hud.SetEnabled(true)
        elseif args == "off" then
            Hud.SetEnabled(false)
        else
            Hud.SetEnabled(not Hud.IsEnabled())
        end

        Print("Heads-up line: " .. CN.YesNo(Hud.IsEnabled()))

        if Hud.IsEnabled() then
            Print("|cff8a8f96Drag it where you want it.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "scale",
    args    = "<0.7 to 2.0>",
    order   = 40,
    help    = "Size of everything this addon draws.",
    handler = function(args)
        local scale = tonumber(CN.Trim(args or ""))

        if not scale then
            Print(string.format("Size: %.2f", Hud.Scale()))
            Print("|cff8a8f96Usage: /cn scale 1.25|r")
            return
        end

        if scale < 0.7 or scale > 2.0 then
            Print("Scale must be between 0.7 and 2.0.")
            return
        end

        Hud.SetScale(scale)

        Print("Scale set to " .. scale .. ".")
    end,
}

CN:RegisterCommand{
    name    = "textsize",
    aliases = { "text" },

    -- WHAT THE SETTER ACTUALLY ACCEPTS. 0.88.0. Three constants described
    -- one ceiling and disagreed: this said 150, the rejection message below
    -- says 200, and `CN.SetTextScale` accepts up to 200. So `/cn help` told
    -- the players who most need larger text that 150 was the limit -- on the
    -- accessibility control the surrounding notes say was rebuilt precisely
    -- because those players are least likely to go hunting for a command.
    args    = "<100 to 200>",
    order   = 40.5,
    help    = "Size of the text in the window, without resizing it.",
    handler = function(args)
        local typed = CN.Trim(args or "")

        if typed == "" then
            Print(string.format("Text size: %d%%",
                math.floor(CN.TextScale() * 100 + 0.5)))
            Print("|cff8a8f96Usage: /cn textsize 130. `/cn scale` resizes the "
                .. "whole window instead.|r")
            return
        end

        local asked = tonumber(typed)

        if not asked then
            Print("Usage: /cn textsize 130")
            return
        end

        -- A PERCENTAGE OR A MULTIPLIER, WHICHEVER THEY TYPED. Both readings
        -- are obvious and only one of them can be meant: nobody wants their
        -- text at 130 times its size, and nobody wants it at 1.3 percent.
        if asked > 3 then
            asked = asked / 100
        end

        if not CN.SetTextScale(asked) then
            Print("Text size must be between 100% and 200%.")
            return
        end

        Print(string.format("Text size: %d%%",
            math.floor(CN.TextScale() * 100 + 0.5)))

        Print("|cff8a8f96Applied to text already on screen. `/cn scale` "
            .. "resizes the whole window instead.|r")
    end,
}

CN:RegisterCommand{
    name    = "colourblind",
    aliases = { "colorblind" },
    args    = "[on or off]",
    order   = 41,
    help    = "Label the arrow in words as well as colour.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Hud.SetColourblind(true)
        elseif args == "off" then
            Hud.SetColourblind(false)
        else
            Hud.SetColourblind(not Hud.IsColourblind())
        end

        Print("Arrow labelled in words: " .. CN.YesNo(Hud.IsColourblind()))
    end,
}

CN:RegisterCommand{
    name    = "keepfilter",
    args    = "[on or off]",
    order   = 44,
    help    = "Whether the window's filter box follows you between tabs.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        local settings = Preferences()

        if args == "on" then
            settings.keepFilter = true
        elseif args == "off" then
            settings.keepFilter = nil
        else
            settings.keepFilter = (not settings.keepFilter) or nil
        end

        Print("Filter follows you between tabs: "
            .. CN.YesNo(settings.keepFilter))

        if not settings.keepFilter then
            -- Turning it off forgets what it was holding. Leaving the term
            -- behind means turning the setting back on later silently applies
            -- a filter the player typed in another session.
            -- `CN.UI`, NOT `CN:GetModule("UI")`.
            --
            -- UI.lua publishes itself as `CN.UI` (UI.lua:24) and never calls
            -- `RegisterModule`, so the lookup returned nil, the branch never
            -- ran, and this command printed "a filter that persists invisibly
            -- is how a list looks empty when it is not" while leaving exactly
            -- that filter in memory. The checkbox path did it correctly, so
            -- the setting worked from the window and not from the command.
            if CN.UI then
                CN.UI.persistedFilter = nil
            end

            Print("|cff8a8f96Off is the safer default: a filter that persists "
                .. "invisibly is how a list looks empty when it is not.|r")
        end
    end,
}

CN:RegisterCommand{
    name    = "cues",
    args    = "[on or off]",
    order   = 42,
    help    = "Sound when you arrive, clear a stop, or finish a route.",
    handler = function(args)
        args = string.lower(CN.Trim(args or ""))

        if args == "on" then
            Preferences().cues = true
        elseif args == "off" then
            Preferences().cues = nil
        else
            Preferences().cues = (not Preferences().cues) or nil
        end

        Print("Sound when you clear a stop: " .. CN.YesNo(Preferences().cues))
    end,
}

return Hud
'@

$Embedded['Modules\Errors.lua'] = @'
-- Modules/Errors.lua
-- Completion Navigator :: what went wrong, kept where the player can find it.
--
-- WHY.
--
-- Every bug report this project has received has been prose. "The arrow does
-- not turn around." I guessed from that description twice and was wrong twice,
-- and the fix both times was to build an instrument -- /cn navdiag, then
-- /cn selftest -- so that the next report could carry evidence instead of
-- adjectives.
--
-- This is the same move applied to errors themselves. The addon already wraps
-- its risky work in pcall, which is why a failure inside a candidate provider
-- does not break the player's session. The cost of that is that the failure is
-- invisible: it happened, something was quietly missing from a list, and
-- nobody will ever know.
--
-- So: keep them. A short ring buffer, in memory, that /cn errors prints.
--
-- WHAT THIS IS NOT.
--
-- It is not telemetry. Nothing is sent anywhere -- an addon cannot send
-- anything anywhere -- and nothing is written to disk, because an error from
-- three weeks ago is noise and a growing error log is a leak.

local ADDON_NAME, CN = ...

local Errors = CN:RegisterModule("Errors")

local Print = CN.Print

-- Twenty is enough to see a pattern and short enough that the memory cost is
-- irrelevant. When it fills, the oldest goes: the recent ones are the ones
-- somebody is trying to explain.
Errors.capacity = 20

local ring = {}

local seen = {}

-- ONE-TIME NOTICES: THINGS THE ADDON OWES THE PLAYER AN EXPLANATION FOR.
-- 0.74.0.
--
-- Distinct from an error, which is a defect caught as it happened. A notice
-- is a statement about something already done and not undoable -- so far,
-- exactly one: the friendship ranks that version 0.72.0's migration deleted
-- from every character that was not logged in at the time.
--
-- Shown once, at login, then kept where `/cn errors` can find it, because a
-- player who logs in during a raid will not read the chat frame and should
-- still be able to go and look.
function Errors.Notices()
    return CN.Account("notices")
end

function Errors.ShowNotices()
    local notices = Errors.Notices()

    local unseen = {}

    for _, notice in ipairs(notices) do
        if type(notice) == "table" and not notice.seen and notice.text then
            table.insert(unseen, notice)
        end
    end

    if #unseen == 0 then
        return 0
    end

    local lines = {}

    for _, notice in ipairs(unseen) do
        notice.seen = true

        table.insert(lines, tostring(notice.text))
    end

    CN.PrintBlock("Something you should know:", lines)

    return #unseen
end

-- DELAYED, so it lands after the login chatter rather than inside it.
-- 0.75.0.
--
-- `OnLogin` handlers run synchronously inside `PLAYER_LOGIN`, immediately
-- after the version banner and every other addon's. This is a one-time
-- explanation of data the addon destroyed and cannot restore, and 0.74.0
-- printed it at the single worst moment and then marked it seen on the way
-- past -- so the one chance to read it was the one moment nobody reads.
--
-- `Setup.RemindIfNeeded` solves exactly this and says so; this is that.
Errors.noticeDelaySeconds = 12

CN:OnLogin(function()
    if C_Timer and C_Timer.After then
        C_Timer.After(Errors.noticeDelaySeconds, function()
            CN.Guard("Errors.ShowNotices", Errors.ShowNotices)
        end)
    else
        CN.Guard("Errors.ShowNotices", Errors.ShowNotices)
    end
end)

-- The whole ring, oldest first. Read by the offline suite, which asserts the
-- eviction bound this buffer exists to keep, and by nothing in the addon --
-- `/cn errors` walks the upvalue directly.
function Errors.All()
    return ring
end

function Errors.Record(context, message)
    if not message then
        return false
    end

    message = tostring(message)

    -- REPEATS ARE COUNTED, NOT LISTED.
    --
    -- A failure inside a ticker fires ten times a second. Twenty identical
    -- lines is not twenty pieces of evidence, and it pushes out the one
    -- different error that would have explained the whole thing.
    local key = tostring(context) .. "|" .. message

    if seen[key] then
        seen[key].count = seen[key].count + 1
        seen[key].last  = time()

        return true
    end

    local entry = {
        context = tostring(context or "?"),
        message = message,
        first   = time(),
        last    = time(),
        count   = 1,
    }

    seen[key] = entry

    table.insert(ring, entry)

    while #ring > Errors.capacity do
        local dropped = table.remove(ring, 1)

        seen[tostring(dropped.context) .. "|" .. dropped.message] = nil
    end

    return true
end

function Errors.Count()
    return #ring
end

function Errors.Clear()
    local count = #ring

    ring = {}
    seen = {}

    return count
end

-- Wraps a call so a failure is recorded rather than swallowed. Returns the
-- same thing pcall does, so it is a drop-in replacement at every site that
-- currently discards the error.
local function Pack(...)
    return select("#", ...), { ... }
end

function Errors.Guard(context, fn, ...)
    -- COUNTED, NOT MEASURED WITH `#`.
    --
    -- This was `local results = { pcall(fn, ...) }` followed by
    -- `CN.Unpack(results)`, which truncates at the first nil: a wrapped
    -- function returning `value, nil` came back as one value, so a "drop-in
    -- replacement" silently changed the arity of whatever it wrapped. `#` on
    -- a table with holes is undefined in both interpreters -- 5.1 and 5.4
    -- happen to agree on the cases here, which is precisely the kind of
    -- agreement this project has learned not to rest on.
    --
    -- `table.pack` does not exist in 5.1, so the count is taken with
    -- `select("#", ...)` inside a varargs helper, which does.
    local count, results = Pack(pcall(fn, ...))

    if not results[1] then
        Errors.Record(context, results[2])
    end

    -- CN.Unpack, not a second copy of it. Core.lua states the rule -- "if a
    -- construct means two things, the addon uses neither directly; it uses
    -- one of these" -- and this file quietly kept its own identical shim
    -- outside the one file that gets audited for exactly this class of
    -- mistake. Equivalent today; the point is that there is one place to fix
    -- it when it is not.
    return CN.Unpack(results, 1, count)
end

CN.Guard = Errors.Guard

------------------------------------------------------------
-- THE PREVIOUS SESSION
------------------------------------------------------------

-- ONE SUMMARY LINE PER ERROR, KEPT ACROSS A LOGOUT.
--
-- The ring buffer is in memory, deliberately: a growing error log is a leak,
-- and an error from three weeks ago is noise. But the case that matters most
-- -- something went wrong, and the player relogged before thinking to look --
-- was exactly the case where the evidence was gone.
--
-- So the counts survive, and nothing else: context, message, and how many
-- times. Cleared whenever the player reads them, and capped at the same size
-- as the live ring.
local function Stored()
    return CN.Account("lastErrors")
end

function Errors.Persist()
    -- A CLEAN SESSION MUST NOT ERASE THE RECORD OF A BAD ONE.
    --
    -- This ran unconditionally on logout, including when nothing had gone
    -- wrong -- so the sequence the feature exists for destroyed its own
    -- evidence: something breaks, the player reloads before thinking to look,
    -- and the reload's empty ring overwrites the record. `/cn errors` then
    -- says nothing has gone wrong, which is true of the last four seconds and
    -- false of the thing the player wanted to report.
    --
    -- Players reload several times an hour. An empty ring is not news, so it
    -- is not written.
    if #ring == 0 then
        return 0
    end

    local stored = Stored()

    for key in pairs(stored) do
        stored[key] = nil
    end

    for index, entry in ipairs(ring) do
        stored[index] = {
            context = entry.context,
            message = entry.message,
            count   = entry.count,
        }
    end

    return #ring
end

function Errors.Previous()
    local rows = {}

    for _, entry in ipairs(Stored()) do
        table.insert(rows, entry)
    end

    return rows
end

function Errors.ForgetPrevious()
    local stored = Stored()

    local count = #stored

    for key in pairs(stored) do
        stored[key] = nil
    end

    return count
end

CN:RegisterEvent("PLAYER_LOGOUT", function()
    Errors.Persist()
end)

CN:RegisterCommand{
    name    = "errors",
    aliases = { "log" },
    args    = "[clear]",
    order   = 43,
    help    = "Anything that went wrong inside the addon this session.",
    handler = function(args)
        if string.lower(CN.Trim(args or "")) == "clear" then
            -- AND THE NOTICES THE PLAYER HAS ALREADY READ. 0.75.0.
            --
            -- `Errors.Clear` empties the in-memory ring. A notice lives in a
            -- persisted account store and 0.74.0 gave it no removal path at
            -- all, so a player who had read and understood it saw it in red
            -- at the top of this command for the life of the account.
            --
            -- Only the ones already shown at login: an unread notice is not
            -- something a command about ERRORS should be able to discard by
            -- accident.
            local notices = Errors.Notices()

            local dropped = 0

            for index = #notices, 1, -1 do
                local notice = notices[index]

                if type(notice) == "table" and notice.seen then
                    table.remove(notices, index)
                    dropped = dropped + 1
                end
            end

            local cleared = Errors.Clear()

            Print("Cleared " .. cleared
                .. CN.Pluralize(cleared, " recorded error.", " recorded errors."))

            if dropped > 0 then
                Print("Cleared " .. dropped .. CN.Pluralize(dropped,
                    " notice.", " notices."))
            elseif #Errors.Notices() > 0 then
                -- SAYS WHY, rather than nothing. An unread notice is not
                -- something a command about errors discards by accident, and
                -- silence here reads as a command that did not work.
                Print("|cff8a8f96" .. #Errors.Notices()
                    .. CN.Pluralize(#Errors.Notices(), " notice is",
                        " notices are")
                    .. " still waiting to be read; run |r"
                    .. CN.Accent("/cn errors")
                    .. "|cff8a8f96 first.|r")
            end

            return
        end

        -- EVENT NAMES THE CLIENT REFUSED.
        --
        -- `CN.RegisterWithClient` has recorded these since 0.49.0, with a
        -- comment saying they are kept "so /cn errors can name it". Nothing
        -- read the table. The secondary path -- recording into this module's
        -- ring -- cannot fire for the sixty-odd files that load before this
        -- one, which includes Travel, the very file whose invented
        -- `NEW_TAXI_NODE` the whole mechanism was written for. A bad event
        -- name today would reproduce the original symptom exactly: silent,
        -- and findable only by reading the source.
        --
        -- Printed first and unconditionally, because a handler that never
        -- runs is the failure most likely to be mistaken for "there is just
        -- nothing to do".
        -- A CACHE THAT SOMEBODY WROTE INTO IS WORTH SAYING OUT LOUD. 0.68.0.
        --
        -- `CN.Memo` notices when a reader has modified what it handed out,
        -- rebuilds rather than serving the damage, and records it -- and the
        -- counter it keeps was written and read by nothing, which is the
        -- state five migrations in this addon exist to clean up. It belongs
        -- here: this is the command whose job is "what went wrong that you
        -- did not see".
        -- ANYTHING THE ADDON DID TO THE PLAYER'S DATA THAT IT CANNOT UNDO.
        -- 0.74.0. Printed here whether or not it has been seen, because this
        -- is the command whose job is "what went wrong that you did not see".
        local notices = Errors.Notices()

        local shown = 0

        for _, notice in ipairs(notices) do
            if type(notice) == "table" and notice.text then
                CN.PrintLine(CN.Bad(tostring(notice.text)))

                -- PRINTING IT IS SHOWING IT. 0.76.0.
                --
                -- `seen` was set only by the login pass, which 0.75.0
                -- deferred twelve seconds -- and `clear` removes only seen
                -- notices. So a player who read the notice HERE and followed
                -- the addon's own instruction got "Cleared 0 recorded
                -- errors", the notice stayed, and the login timer printed the
                -- same block again seconds later.
                notice.seen = true

                shown = shown + 1
            end
        end

        if shown > 0 then
            CN.PrintLine("  " .. CN.Muted("Read it? ")
                .. CN.Accent("/cn errors clear")
                .. CN.Muted(CN.Pluralize(shown, " removes it.",
                    " removes them.")))
        end

        if (CN.memoMutations or 0) > 0 then
            CN.PrintLine(CN.Bad(CN.Count(CN.memoMutations,
                "cached list was", "cached lists were")
                .. " modified after being handed out, and rebuilt."))
            CN.PrintLine("  " .. CN.Muted("Harmless to you; it means a list "
                .. "grew every time it was read until this caught it."))
        end

        local rejected = 0

        for event, why in pairs(CN.rejectedEvents or {}) do
            if rejected == 0 then
                CN.PrintLine("|cffe2564cThe client refused to register these "
                    .. "events, so nothing listening for them ever runs:|r")
            end

            rejected = rejected + 1

            CN.PrintLine(CN.Bad(tostring(event)))
            CN.PrintLine("  " .. CN.Muted(tostring(why)))
        end

        if #ring == 0 then
            local previous = Errors.Previous()

            if #previous > 0 then
                Print("Nothing this session. From the previous one:")

                for _, entry in ipairs(previous) do
                    CN.PrintLine(CN.Bad(tostring(entry.context))
                        .. ((entry.count or 1) > 1
                            and (" |cffffc74fx" .. entry.count .. "|r") or ""))
                    CN.PrintLine("  " .. CN.Muted(tostring(entry.message)))
                end

                Errors.ForgetPrevious()

                Print("|cff8a8f96Shown once, then forgotten.|r")
                return
            end

            -- A NOTICE COUNTS TOWARDS "SOMETHING WAS SAID". 0.75.0.
            --
            -- 0.74.0 printed the notice in red at the top of this handler
            -- and then, if the ring happened to be empty, followed it
            -- immediately with "Nothing has gone wrong this session." Two
            -- contradictory statements, adjacent, in the command whose whole
            -- job is to be trustworthy about failures. The `rejected` branch
            -- one line up already knew to say "nothing ELSE".
            if rejected > 0 or shown > 0 then
                Print("Nothing else has gone wrong this session.")
                return
            end

            Print("Nothing has gone wrong this session.")
            Print("|cff8a8f96Errors inside the addon are caught so they "
                .. "cannot break your session" .. CN.DASH .. "which is also why they would "
                .. "otherwise be invisible. They are recorded here instead.|r")
            return
        end

        Print(#ring .. CN.Pluralize(#ring, " error", " errors")
            .. " recorded this session:")

        for _, entry in ipairs(ring) do
            CN.PrintLine(CN.Bad(entry.context)
                .. (entry.count > 1 and (" |cffffc74fx" .. entry.count .. "|r") or ""))
            CN.PrintLine("  " .. CN.Muted(entry.message))
        end

        Print("|cff8a8f96Paste this into a bug report along with "
            .. "|cffffc74f/cn selftest|r output.|r")
    end,
}

return Errors
'@

