$Embedded['.github\workflows\release.yml'] = @'
name: Package and release

# Fires when you push a version tag, e.g.  git tag v0.8.0 && git push --tags
on:
  push:
    tags:
      - 'v*'

permissions:
  contents: write

jobs:
  release:
    runs-on: ubuntu-latest

    # Without this, a hung step runs until GitHub's six-hour default kills it.
    # A release that has hung for hours looks identical to one still working,
    # which is exactly how a stuck run went unnoticed: it sat "in progress"
    # indefinitely while nobody could tell it was dead.
    # A BACKSTOP, NOT THE LIMIT. 0.67.1.
    #
    # This was 20 while the steps inside it carried caps adding to 53, which
    # inverts what the two are for. Each step's cap is sized to the work that
    # step does and is what notices a hang; the job cap exists only to stop a
    # runner being held for six hours if something escapes all of them. A
    # backstop smaller than what it backs is not a backstop -- it is the real
    # limit, and it kills whichever step happens to be running when it
    # expires, marking nothing as failed.
    #
    # Above the sum of every step cap, and the release rehearsal checks that.
    timeout-minutes: 75

    steps:
      - name: Check out
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          # Without this the tag object may not be present in the checkout,
          # and the packager decides the release type from
          # `git tag --points-at HEAD`. No tag means it uploads as ALPHA.
          fetch-tags: true

      # Belt and braces: force-fetch tags even if the checkout missed them.
      - name: Fetch tags
        run: git fetch --force --tags --prune --prune-tags

      # If no tag points at HEAD the packager silently publishes an alpha,
      # which then hides behind "Show alpha files" on CurseForge. Fail
      # instead, and print what git actually sees.
      - name: Verify a tag points at HEAD
        run: |
          echo "GITHUB_REF      = $GITHUB_REF"
          echo "GITHUB_REF_NAME = $GITHUB_REF_NAME"
          echo "HEAD            = $(git rev-parse HEAD)"
          echo "tags at HEAD    = $(git tag --points-at HEAD | tr '\n' ' ')"

          if [ -z "$(git tag --points-at HEAD)" ]; then
            echo "::error::No tag points at HEAD, so the packager would upload this as an ALPHA."
            echo "The release type is derived entirely from the tag; there is no flag to override it."
            exit 1
          fi

          # A tag containing alpha or beta is an intentional pre-release, but
          # say so out loud rather than surprising anyone.
          for t in $(git tag --points-at HEAD); do
            case "${t,,}" in
              *alpha*) echo "::warning::Tag $t contains 'alpha'; this will publish as an alpha file." ;;
              *beta*)  echo "::warning::Tag $t contains 'beta'; this will publish as a beta file." ;;
              *)       echo "Tag $t will publish as a RELEASE file." ;;
            esac
          done

      # The Lua toolchain does NOT come from apt, deliberately.
      #
      # ubuntu-latest runs unattended-upgrades shortly after boot, which holds
      # the dpkg lock. apt-get waits for that lock FOREVER by default, so this
      # step wedged for thirty-eight minutes on one release while reporting
      # "in progress". Bounding the wait only converted the hang into a
      # failure: the lock was still held, so apt still could not run.
      #
      # These actions download and build the toolchain into .lua/ in the
      # workspace. No package manager, no shared lock, nothing to contend with.
      - name: Install Lua
        timeout-minutes: 6
        uses: leafo/gh-actions-lua@v13
        with:
          luaVersion: "5.4"

      - name: Install LuaRocks
        timeout-minutes: 6
        uses: leafo/gh-actions-luarocks@v6

      # luacheck is the only tool the blocking steps need; luacov is optional
      # and the coverage step tolerates its absence.
      #
      # The shims matter. Every downstream step, coverage.sh, and the local
      # test suite all invoke `lua5.4` and `luac5.4` by name, and the test
      # suite asserts CI runs those exact commands. The actions above install
      # plain `lua` and `luac`, so alias them rather than editing the command
      # in six places and breaking that parity check.
      - name: Install Lua tooling
        timeout-minutes: 6
        run: |
          luarocks install luacheck
          luarocks install luacov || echo "luacov unavailable; coverage will skip"

          # NO LUA 5.1 HERE, DELIBERATELY. 0.61.1.
          #
          # The game runs Lua 5.1 and this workspace's toolchain is 5.4, so
          # installing 5.1 is tempting -- and 0.61.1 tried it with apt before
          # the toolkit's own lint stopped it. That lint exists because the
          # runner's unattended upgrades hold the dpkg lock and a release that
          # waits on it dies on a timeout for no reason anybody can act on.
          #
          # So the two steps that want 5.1 -- the harness and the performance
          # budgets -- both CHECK for it and say plainly when it is missing.
          # They run on 5.1 wherever it exists, including the local release
          # rehearsal, and neither can exit 127 for the want of it.

          mkdir -p "$HOME/bin"
          ln -sf "$(command -v lua)"  "$HOME/bin/lua5.4"
          ln -sf "$(command -v luac)" "$HOME/bin/luac5.4"
          echo "$HOME/bin" >> "$GITHUB_PATH"

          lua -v
          luac -v || true
          luacheck --version

      # Only OUR Lua. The toolchain is built into .lua/ in this same workspace,
      # which drags several thousand third-party files into any naive `find` --
      # including LuaRocks' own test fixtures, some of which are deliberately
      # malformed. Excluding every dotted directory covers .git, .github, .lua,
      # .lua-build and .luarocks in one rule, and covers whatever the next
      # tool decides to name its install directory.
      - name: Syntax check every Lua file
        run: |
          status=0
          count=0
          while IFS= read -r file; do
            count=$((count + 1))
            if ! luac5.4 -p "$file"; then
              echo "SYNTAX ERROR: $file"
              status=1
            fi
          done < <(find . -type f -name '*.lua' -not -path './.*' \
                     -not -path './fixtures/*')
          echo "checked $count file(s)"

          # A find that silently matches nothing would pass this step while
          # checking nothing at all.
          if [ "$count" -lt 10 ]; then
            echo "::error::Only $count Lua files were found; the search is wrong."
            status=1
          fi

          exit $status

      # fixtures/captured.lua is EVIDENCE, not source: a recording of what a
      # live client returned, written by `cn.ps1 fixtures` and read only by
      # the test harness. It is a .lua file sitting in the repository, so this
      # step reported it as missing from the .toc and failed the build --
      # blocking the packager, so three tagged releases were pushed, reported
      # as pushed, and never reached CurseForge.
      #
      # 0.47.0 taught the PowerShell file scanner to ignore fixtures/ and did
      # not touch this, which does the same job on the runner. A fix applied
      # to the instance somebody noticed rather than to the class.
      - name: Verify the .toc lists every Lua file
        run: |
          status=0
          toc=CompletionNavigator.toc
          while IFS= read -r file; do
            rel="${file#./}"
            win="${rel//\//\\}"
            if ! grep -qxF "$win" "$toc" && ! grep -qxF "$rel" "$toc"; then
              echo "NOT IN TOC: $rel"
              status=1
            fi
          done < <(find . -type f -name '*.lua' -not -path './.*' \
                     -not -name 'harness.lua' -not -name 'bench.lua' \
                     -not -path './fixtures/*')
          exit $status

      # Static analysis. Catches globals-by-typo, shadowing and dead locals --
      # the class of bug a stubbed test harness hides, because the harness
      # defines the very globals a typo would otherwise expose.
      - name: Lint
        timeout-minutes: 5
        run: luacheck . --no-color

      # The offline harness loads every file in .toc order against a stubbed
      # client, fires the lifecycle events, runs every slash command, exercises
      # every UI tab and asserts the SavedVariables shapes.
      #
      # This used to run only on the author's machine, which meant a release
      # could ship with it failing and nothing would say so.
      # THE SUITE RUNS TWICE, ON TWO LANGUAGES.
      #
      # World of Warcraft runs Lua 5.1. This suite normally runs 5.4. They are
      # not the same language, and the difference hid the worst defect this
      # project has shipped: `math.atan(y, x)` is the two-argument arctangent
      # in 5.3+, and in 5.1 it silently discards the second argument. Every
      # bearing the addon computed in game for twenty-four releases was wrong,
      # and the suite agreed it was right because the suite ran on 5.4.
      #
      # 5.1 first, because it is the one that matters.
      - name: Run the offline harness on Lua 5.1 (the game's version)
        timeout-minutes: 5
        run: |
          if command -v lua5.1 >/dev/null 2>&1; then
            lua5.1 harness.lua .
          else
            echo "::warning::lua5.1 is not on this runner; the game's own"
            echo "language went unverified for this build."
          fi

      - name: Run the offline harness
        timeout-minutes: 5
        run: |
          if [ -f harness.lua ]; then
            lua5.4 harness.lua .
          else
            echo "::error::harness.lua is missing from the repository."
            echo "The test suite cannot run, so this release is not verified."
            exit 1
          fi

      # Performance budgets. Two regressions have shipped in this project's
      # history and BOTH were visible in the benchmark output at the time --
      # printing a number somebody has to remember is not a check. The
      # ceilings live in bench.lua and carry real headroom, because a budget
      # that fails on runner noise gets deleted within a fortnight.
      #
      # AND THE GATE RUNS ON THE VERSION THE GAME RUNS. 0.61.0.
      #
      # Every budget in this file was measured and enforced under lua5.4,
      # which is roughly twice as fast as the 5.1 the WoW client actually
      # interprets. So a path sitting at 60% of its ceiling here was at 120%
      # of it in the game, and the gate said "ok". The whole point of a budget
      # is that it corresponds to a frame the player experiences.
      #
      # 5.1 is the gate. 5.4 still runs, reporting only, because the two
      # numbers side by side are how a real regression is told apart from an
      # interpreter difference.
      - name: Performance budgets
        timeout-minutes: 6
        run: |
          if [ ! -f bench.lua ]; then
            echo "bench.lua is missing; skipping budgets."
            exit 0
          fi

          echo "--- lua5.4 (reference, not the gate) ---"
          lua5.4 bench.lua . --budget || true

          # GUARDED, LIKE THE 5.1 HARNESS STEP NEXT DOOR. 0.61.1.
          #
          # 0.61.0 called `lua5.1` here unguarded. The runner did not have it,
          # the step exited 127 -- "command not found" -- and the release died
          # between the harness and packaging. The harness step ten lines above
          # had ALWAYS guarded this exact binary; this step was written without
          # looking at it.
          #
          # That is the same shape of defect this project keeps finding: two
          # places that need the same precondition, one of which nobody
          # checked against the other.
          if command -v lua5.1 >/dev/null 2>&1; then
            echo "--- lua5.1 (the version the game runs; this is the gate) ---"
            lua5.1 bench.lua . --budget
          else
            echo "::warning::lua5.1 is not on this runner, so the budgets were"
            echo "gated on 5.4 -- which is about twice as fast as the game."
          fi

      # Mutation testing: does the suite actually notice when the code is
      # wrong? A green suite proves the code runs. This proves the assertions
      # would complain. It found three holes on the day it was written.
      #
      # NOT blocking, deliberately, and by the same rule as coverage: a
      # surviving mutation means the SUITE is weak, not that the code is
      # broken. Blocking a release on it would be blocking users from a fix
      # because a test could be better.
      # FIFTEEN, NOT EIGHT. 0.67.1.
      #
      # The suite is 314 mutations and each one runs the whole harness. On the
      # author's machine that is 341 seconds -- 71% of an eight-minute budget
      # -- and a GitHub runner has two cores and is slower, so this step was
      # being killed there and the mutation testing simply stopped happening.
      # It is continue-on-error, so nothing failed and nothing said so: the
      # release went green with its strongest suite silently not run.
      #
      # `cisim.sh` now enforces `timeout-minutes` locally and warns when a
      # step passes using more than two thirds of its budget, which is how
      # this was found.
      - name: Mutation testing
        continue-on-error: true
        timeout-minutes: 15
        run: |
          if [ -f mutate.sh ]; then
            bash mutate.sh .
          else
            echo "mutate.sh is missing; skipping mutation testing."
          fi

      # Coverage, with a floor. A test suite whose reach nobody measures
      # drifts: it keeps passing while covering less and less of the addon.
      #
      # continue-on-error is deliberate and important. This step once blocked a
      # release outright: coverage.sh hardcoded a luacov path from the author's
      # machine, died silently on the runner, and the packager never ran -- so a
      # tagged, pushed, validated release simply never reached CurseForge and
      # the Actions log showed nothing useful.
      #
      # Lint and the harness SHOULD block a release; they catch broken code.
      # A missing developer tool should not. Users do not care whether the
      # author's coverage report generated.
      - name: Coverage
        continue-on-error: true
        timeout-minutes: 6
        run: bash coverage.sh . 85

      # The packager SKIPS the CurseForge upload silently when CF_API_KEY is
      # missing -- the build still goes green and no file appears. Fail here
      # instead, so a missing or misnamed secret is obvious.
      - name: Verify the CurseForge token is available
        env:
          CF_API_KEY: ${{ secrets.CF_API_KEY }}
        run: |
          if [ -z "$CF_API_KEY" ]; then
            echo "::error::CF_API_KEY is empty or not visible to this workflow."
            echo ""
            echo "Check all three:"
            echo "  1. The secret is named exactly CF_API_KEY (case sensitive)."
            echo "  2. It is a REPOSITORY secret, or an organization secret with"
            echo "     this repository granted access."
            echo "  3. It is under Secrets, not Variables."
            exit 1
          fi
          echo "CF_API_KEY is present (${#CF_API_KEY} characters)."

      # BigWigs' packager is the standard tool; it reads .pkgmeta, builds the
      # zip, and uploads to CurseForge, WoWInterface and Wago as configured.
      # RELEASE NOTES, FROM THE CHANGELOG.
      #
      # The packager will use a changelog if it can find one, and until now it
      # was finding the whole file -- every version since 0.1.0 -- which makes
      # a release page nobody scrolls. This extracts the section for the tag
      # being built, so the notes are about this release and nothing else.
      #
      # Not blocking: badly formatted release notes are a cosmetic problem and
      # the packager has its own fallback.
      - name: Release notes for this version
        continue-on-error: true
        run: |
          VERSION="${GITHUB_REF_NAME#v}"

          if [ ! -f CHANGELOG.md ]; then
            echo "No CHANGELOG.md; the packager will fall back to its default."
            exit 0
          fi

          awk -v version="## [$VERSION]" '
            index($0, version) == 1 { found = 1; next }
            found && /^## \[/ { exit }
            found { print }
          ' CHANGELOG.md > RELEASE_NOTES.md

          if [ ! -s RELEASE_NOTES.md ]; then
            echo "::warning::No changelog section for $VERSION; notes left empty."
            rm -f RELEASE_NOTES.md
          else
            echo "Release notes: $(wc -l < RELEASE_NOTES.md) lines."
          fi

      # Reached regardless of the optional steps above.
      #
      # WAGO_API_TOKEN is passed through but not required: the packager skips
      # a destination it has no credentials for, and Wago is a second channel
      # rather than the primary one. X-Wago-ID in the .toc has to be filled in
      # before anything reaches it.
      - name: Package and upload
        uses: BigWigsMods/packager@master
        env:
          CF_API_KEY: ${{ secrets.CF_API_KEY }}
          WAGO_API_TOKEN: ${{ secrets.WAGO_API_TOKEN }}
          GITHUB_OAUTH: ${{ secrets.GITHUB_TOKEN }}
'@

$Embedded['.github\ISSUE_TEMPLATE\bug_report.md'] = @'
---
name: Something is wrong
about: The addon did something it should not, or failed to do something it should
title: ""
labels: bug
---

<!--
Two of this addon's hardest bugs were reported as prose, and prose is a bad
instrument: "the arrow does not turn around" was diagnosed wrongly twice
before the addon grew commands that could answer the question directly.

The three blocks below take about thirty seconds and usually contain the
answer. Please paste the output rather than describing it.
-->

## What happened

<!-- What you did, what you expected, and what you got instead. -->

## `/cn selftest`

<!-- Fifteen checks against your own client. Paste the whole output. -->

```
```

## `/cn errors`

<!-- Anything that went wrong inside the addon this session. Often empty. -->

```
```

## If it is about the arrow or a distance, also `/cn navdiag`

```
```

## Version

<!-- The version shown on the addon list, and your game version. -->

- Addon:
- Game:
'@

$Embedded['.github\ISSUE_TEMPLATE\feature_request.md'] = @'
---
name: Something is missing
about: A thing the addon should be able to answer and cannot
title: ""
labels: enhancement
---

## What question should it be able to answer?

<!--
This addon answers "what should I do next?". Requests phrased as a question
it should be able to answer are much easier to build well than requests
phrased as a feature.
-->

## What do you do today instead?

<!-- Another addon, a website, a spreadsheet, or working it out by hand. -->

## Anything it should NOT do

<!--
Useful and rarely asked. For example: this addon never invents a completion
percentage where the game does not supply a trustworthy total, and never
takes over your waypoint without being asked.
-->
'@

$Embedded['.github\ISSUE_TEMPLATE\data_contribution.md'] = @'
---
name: Quest chain contribution
about: Share what your own play taught the addon
title: "Chains: "
labels: data
---

<!--
In game: /cn contribute

That prints a single line of text containing quest IDs and orderings. No
character name, no realm, no timestamps, no coordinates -- you can read the
whole thing before you send it, which is the point of a format you can read.

Nothing is uploaded by the addon. It cannot upload anything; World of Warcraft
addons have no network access. Pasting it here is the entire transport.
-->

```
```

## Anything unusual about these chains?

<!-- Faction-specific, class-specific, or an ordering you think is wrong. -->
'@

$Embedded['mutate.sh'] = @'
#!/usr/bin/env bash
# mutate.sh -- does the test suite actually test anything?
#
# WHY THIS EXISTS.
#
# A passing suite proves the code runs. It does not prove the assertions
# would notice if the code were wrong, and this project has repeatedly found
# tests that would not: an assertion comparing a value against the setting
# that produced it, a fixture that failed a different check first, a
# comparison so loose that east reading as west still passed.
#
# Every one of those was found by hand, by breaking the code on purpose and
# seeing whether anything complained. That is a mechanical task and it was
# being done from memory, which means it was being done inconsistently.
#
# Each mutation below is a deliberate, plausible bug. A mutation that SURVIVES
# is a hole in the suite, and the correct response is to write the missing
# assertion -- never to delete the mutation.
#
# Usage:  ./mutate.sh [tree]
set -u

TREE="${1:-build/CompletionNavigator}"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

PASSED=0
SURVIVED=0

# A BACKTICK IN AN ANCHOR IS A COMMAND, NOT A CHARACTER. 0.77.0.
#
# The anchors are double-quoted, so the shell runs anything between backticks
# and substitutes its output -- and this file's own prose style puts Lua names
# in backticks everywhere. A 0.77.0 anchor copied a comment line verbatim,
# the shell tried to run `EffectiveWeights`, and the mutation silently became
# inapplicable rather than failing: it was reported as stale, which reads like
# a re-anchoring chore rather than a bug in this script.
#
# Refuse the whole run rather than quietly testing one thing fewer.
mutate() {
    local file="$1" from="$2" to="$3" label="$4"

    case "$from$to" in
        *'`'*)
            echo "ANCHOR CONTAINS A BACKTICK, which the shell would run: $label"
            exit 2
            ;;
    esac

    rm -rf "$WORK/tree"
    cp -r "$TREE" "$WORK/tree"

    python3 - "$WORK/tree/$file" "$from" "$to" <<'PY'
import sys
path, old, new = sys.argv[1], sys.argv[2], sys.argv[3]
text = open(path, encoding="utf-8").read()
if text.count(old) != 1:
    print("MUTATION NOT APPLICABLE: %s (%d matches)" % (old[:60], text.count(old)))
    sys.exit(3)
open(path, "w", encoding="utf-8").write(text.replace(old, new))
PY

    local applied=$?

    if [ "$applied" = "3" ]; then
        printf '  \033[33mstale\033[0m     %s\n' "$label"
        SURVIVED=$((SURVIVED + 1))
        return
    fi

    if lua5.4 harness.lua "$WORK/tree" >/dev/null 2>&1; then
        printf '  \033[31mSURVIVED\033[0m  %s\n' "$label"
        SURVIVED=$((SURVIVED + 1))
    else
        printf '  \033[32mkilled\033[0m    %s\n' "$label"
        PASSED=$((PASSED + 1))
    fi
}

echo "Mutation testing $TREE"
echo

mutate "Modules/Travel.lua" \
    "                        if ranking < bestRanking then" \
    "                        if true then" \
    "travel always flies, even when running is quicker"

mutate "Modules/Travel.lua" \
    '        return nil, false, {
            mode      = "elsewhere",' \
    '        return 3600, false, {
            mode      = "elsewhere",' \
    "travel invents a cross-continent duration"

mutate "Modules/Instances.lua" \
    "            and lockout.defeated > 0" \
    "            and lockout.defeated >= 0" \
    "a lockout nothing has been killed in is recommended"

mutate "Modules/Preference.lua" \
    "    if not row or row.shown < Preference.minimumObservations then" \
    "    if not row then" \
    "learning acts before it has evidence"

# RE-ANCHORED IN 0.89.0: the boundary case is refused now, so the comparison
# is `<=` rather than `<`.
mutate "Modules/Chase.lua" \
    "    if timed == 0 or (timed / outstanding) <= Chase.estimateCoverage then" \
    "    if false then" \
    "chase estimates a time from nothing"

mutate "Scoring.lua" \
    "    if secondsLeft < CN.urgencyHorizonSeconds then" \
    "    if false then" \
    "the short urgency ramp is removed"

mutate "Modules/Navigation.lua" \
    "    if math.abs(delta) >= Navigation.smoothingSnapRad then" \
    "    if false then" \
    "the arrow eases through a reversal instead of snapping"

mutate "Modules/Group.lua" \
    '        return score * Group.deadPenalty' \
    "        return score" \
    "recommendations ignore the player being dead"

mutate "Modules/Contribute.lua" \
    '    if version ~= Contribute.formatVersion then' \
    "    if false then" \
    "an import accepts text of any format"

mutate "Core.lua" \
    "    if level == CN.confidence.ESTIMATED then" \
    "    if false then" \
    "estimated numbers are printed as though measured"

mutate "Modules/Inventory.lua" \
    "        if item.startsQuest and not item.questActive then" \
    "        if item.startsQuest then" \
    "quest starters already accepted are offered again"

mutate "Modules/Waiting.lua" \
    "        if mail.expiring and (mail.items > 0 or mail.money > 0) then" \
    "        if mail.expiring then" \
    "empty expiring mail is treated as something to save"

mutate "Modules/Travel.lua" \
    "    if remembered == false then
        return false
    end" \
    "    if false then
        return false
    end" \
    "flying is offered in a zone known not to allow it"

# NOT `value % divisor`: Lua's own operator is already floored, so that
# mutation is behaviourally identical and survived for the honest reason that
# it was not a defect. math.fmod truncates toward zero, which is the actual
# hazard this helper exists to avoid.
mutate "Core.lua" \
    "    return value - (math.floor(value / divisor) * divisor)" \
    "    return math.fmod(value, divisor)" \
    "modulo truncates toward zero instead of flooring"

mutate "Scoring.lua" \
    "        if math.abs(term.value) > 0.001 or term.keepAtZero then" \
    "        if true then" \
