$Embedded['.gitattributes'] = @'
# Shell and YAML must be LF in the repository. A CRLF workflow file reaches
# the Linux runner with trailing carriage returns and every `run:` step dies
# with "$'\r': command not found".
*.yml   text eol=lf
*.yaml  text eol=lf
*.sh    text eol=lf
.pkgmeta text eol=lf

# Lua and docs are edited on Windows; leave them to git's normalization.
*.lua   text
*.toc   text
*.xml   text
*.md    text
*.ps1   text

*.png   binary
*.jpg   binary
*.zip   binary
'@

$Embedded['.luacheckrc'] = @'
-- .luacheckrc
-- Completion Navigator :: static analysis configuration.
--
-- luacheck knows nothing about the WoW client, so every API call reads as an
-- undefined global and the real signal drowns in 500 lines of noise. Declaring
-- the client surface here means a warning is worth reading: an undeclared
-- global is now either a typo or a genuine leak.
--
-- Run:  luacheck .

std = "lua51"

max_line_length = false

-- Every file is loaded by the client as
--   local ADDON_NAME, CN = ...
self = false

read_globals = {
    -- Namespaced client API.
    "C_Calendar", "C_CurrencyInfo", "C_DateAndTime",
    "C_CampaignInfo", "C_CreatureInfo", "C_GossipInfo", "C_Item",
    "C_MajorFactions", "C_Map",
    "C_MerchantFrame",
    "C_MountJournal", "C_PetJournal", "C_QuestLog", "C_Reputation",
    "C_SuperTrack", "C_TaskQuest", "C_Timer", "C_ToyBox", "C_TradeSkillUI",
    "C_TransmogCollection", "C_VignetteInfo", "C_WeeklyRewards",

    -- Flat client API.
    "CreateFrame", "CreateFont", "GetAchievementCriteriaInfo", "GetAchievementInfo",
    "IsMounted", "UnitOnTaxi",
    "GetAchievementNumCriteria", "GetCategoryList", "GetCategoryNumAchievements",
    "GetCursorPosition", "GetItemInfo", "GetMerchantItemInfo",
    "GetMerchantItemLink", "GetMerchantNumItems", "GetNumCompletedAchievements",
    "GetNumTitles", "GetProfessionInfo", "GetProfessions", "GetQuestResetTime",
    "GetRealmName", "GetSpecialization", "GetSpecializationInfo", "GetSpecializationInfoByID", "GetTitleName",
    "GetZoneText", "IsTitleKnown", "PlayerHasToy", "UnitClass", "UnitExists",
    "UnitFactionGroup", "UnitGUID", "UnitLevel", "UnitName", "UnitRace",
    "PlaySound", "GetTime",

    -- 0.56.0. `UnitIsUnit` tells the shared-quest count that the raid unit it
    -- is asking about is the player themselves; `BankFrame` is the frame the
    -- client requires to be open before it will describe a bank container.
    "UnitIsUnit", "BankFrame",
    "GetPlayerFacing", "InCombatLockdown", "IsInInstance",
    "GetLocale",

    -- Saved instances and the Adventure Guide (Encounter Journal). The EJ
    -- functions are globals rather than a namespaced table, which is why
    -- there are so many of them.
    "GetNumSavedInstances", "GetSavedInstanceInfo", "C_TaxiMap",

    -- Memory reporting, sound and flash, group and death state, self-flying,
    -- crafting orders and the settings panel. All optional, all guarded at
    -- the call site, all real APIs the client provides.
    "UpdateAddOnMemoryUsage", "GetAddOnMemoryUsage",
    "SOUNDKIT", "PlaySound", "UIFrameFlash",
    "UnitIsDeadOrGhost", "UnitIsGhost", "GetNumGroupMembers", "C_DeathInfo",
    "IsInRaid", "IsInInstance", "IsFlying", "IsFlyableArea",
    "C_CraftingOrders", "C_DelvesUI", "C_Spell",

    -- Bags, mail, keystones, heirlooms and challenge modes: five systems the
    -- addon began reading in 0.44.0.
    "C_Container", "GetInboxNumItems", "GetInboxHeaderInfo",
    "C_MythicPlus", "C_ChallengeMode", "C_Heirloom",
    "C_ToyBox", "PlayerHasToy",
    "C_TransmogSets", "C_LFGList", "IsInGuild", "GetGuildInfo", "GetBuildInfo",
    "IsSpellKnown", "IsPlayerSpell", "GetSpellCooldown", "GetItemCooldown",
    "GetItemCount", "GetBindLocation", "EJ_GetDifficulty", "GetDifficultyInfo",
    "SettingsPanel", "Settings", "InterfaceOptions_AddCategory",
    "BackdropTemplateMixin",
    "EncounterJournal", "EJ_SelectInstance", "EJ_GetCurrentInstance",
    "EJ_GetInstanceInfo", "EJ_GetEncounterInfoByIndex", "EJ_GetEncounterInfo",
    "EJ_SetSearch", "EJ_ClearSearch", "EJ_GetNumSearchResults",
    "EJ_GetSearchResult",
    "GetQuestID", "GetTitleText", "GetCategoryInfo",

    -- Globals the client defines that are not functions.
    "Enum", "GameTooltip", "GameFontNormal", "Minimap", "UIParent",
    "UIFrameFadeIn", "UIFrameFadeOut",
    "UISpecialFrames",
    "UiMapPoint", "CreateVector2D", "DEFAULT_CHAT_FRAME", "TooltipDataProcessor",
    "TooltipUtil", "LE_PET_JOURNAL_FILTER_COLLECTED",
    "LE_PET_JOURNAL_FILTER_NOT_COLLECTED",

    -- Lua functions the client exposes globally.
    "date", "time", "strsplit", "debugprofilestop", "wipe",

    -- Optional third-party addons. Probed, never required. The three addon
    -- tables themselves are reached through _G and so are not listed: an
    -- entry here for a name the source never mentions weakens the guarantee
    -- in this file's own header, that an undeclared global is a typo or a
    -- leak. Eleven such entries were pruned in 0.47.0.
    "LibStub",
}

globals = {
    -- SavedVariables, declared in the .toc.
    "CompletionNavigatorDB",

    -- Named frames the client publishes as globals.
    "CompletionNavigatorFrame", "CompletionNavigatorMinimapButton",

    -- Binding labels, read by the client's key binding UI.
    "BINDING_HEADER_COMPLETIONNAVIGATOR",
    "BINDING_NAME_COMPLETIONNAVIGATOR_TOGGLE",
    "BINDING_NAME_COMPLETIONNAVIGATOR_FOLLOW",
    "BINDING_NAME_COMPLETIONNAVIGATOR_PLAN",
    "BINDING_NAME_COMPLETIONNAVIGATOR_HUD",
    "BINDING_NAME_COMPLETIONNAVIGATOR_NEXT",
    "BINDING_NAME_COMPLETIONNAVIGATOR_GO",

    -- Binding handlers, called by name from Bindings.xml.
    "CompletionNavigator_ToggleUI",
    "CompletionNavigator_ToggleFollow",
    "CompletionNavigator_Plan",
    "CompletionNavigator_ToggleHud",
    "CompletionNavigator_NextObjective",
    "CompletionNavigator_Navigate",

    -- Exploration category constant, set by Data files.
    "CN_EXPLORATION_CATEGORY",

    -- Slash command registration. The client reads SLASH_<NAME><n> globals and
    -- dispatches through SlashCmdList; there is no other way to register one.
    "SLASH_COMPLETIONNAVIGATOR1",
    "SLASH_COMPLETIONNAVIGATOR2",
    "SlashCmdList",
}

-- Every file opens with `local ADDON_NAME, CN = ...`. Most only need CN, and
-- dropping the name would make the idiom inconsistent across 38 files for no
-- gain. Suppressed by name rather than by disabling the whole unused-variable
-- check, which does catch real things.
-- Event handlers receive (event, ...) and most do not need the event name.
-- Silencing unused arguments wholesale is right for an event-driven addon;
-- unused *variables* are still reported, and those do catch real things.
unused_args = false

ignore = {
    -- Every file opens with `local ADDON_NAME, CN = ...`. Most only need CN,
    -- and dropping the name would make the idiom inconsistent across 39 files
    -- for no gain.
    "211/ADDON_NAME",

    -- Same idiom: the logging locals are bound at the top of every module so
    -- that adding a Print call later needs no edit to the header.
    "211/DebugPrint",
    "211/Print",
}

-- The provider files exist to absorb the client's positional return lists.
-- Naming every slot is what makes the call sites readable; most are unused by
-- design, and replacing them with select() would make the files worse.
--
-- All three, since the split in 0.45.0 -- the exception belonged to the ROLE,
-- not to the filename, and naming only the original file would have meant the
-- warnings reappeared the moment the role moved.
for _, provider in ipairs({
    "Providers/Blizzard.lua",
    "Providers/BlizzardCollections.lua",
    "Providers/BlizzardWorld.lua",
}) do
    files[provider] = { ignore = { "211" } }
end

-- Test tooling. The harness exists to define the globals the addon reads, so
-- "setting an undefined global" is its entire job; linting it under the addon's
-- rules would report several hundred deliberate ones.
files["harness.lua"] = { ignore = { "1" }, unused = false }
files["bench.lua"]   = { ignore = { "1" }, unused = false }

-- CI builds the Lua toolchain into the workspace, so the repository root now
-- contains thousands of third-party .lua files belonging to LuaRocks and its
-- dependencies. They are not ours and must not be analysed.
exclude_files = {
    "_backups/",

    -- Recordings of a live client, read only by the harness. Evidence, not
    -- source: a malformed one is a broken recording to re-capture, not a
    -- syntax error in the addon -- and it failed the build as though it were.
    --
    -- The FOURTH place that decides what counts as addon source. The other
    -- three -- the toolkit's file scanner, the CI search, and .pkgmeta --
    -- were taught about fixtures/ and this was missed, so the build moved
    -- from failing at the .toc step to failing at Lint.
    "fixtures/",
    ".lua/**",
    ".lua-build/**",
    ".luarocks/**",
    ".install/**",
}
'@

$Embedded['harness.lua'] = @'
-- Offline load harness: stubs enough of the WoW client to execute every
-- Completion Navigator file in .toc order, fire the lifecycle events, and
-- run every registered slash command.

local ROOT = arg[1] or "."

------------------------------------------------------------
-- UNIVERSAL STUB
------------------------------------------------------------

local U = {}
setmetatable(U, {
    __index = function() return U end,
    __call  = function() return U end,
})

-- EVENTS THE CLIENT ACTUALLY HAS.
--
-- The frame stub above refuses anything not on this list, because the real
-- client refuses too -- it throws rather than ignoring, so one invented name
-- is a Lua error at every login for every player. `NEW_TAXI_NODE` was such a
-- name and shipped in 0.46.0.
--
-- HONESTY ABOUT WHAT THIS LIST IS. It is written from knowledge, not read
-- from a client, so it is exactly the kind of artefact this project keeps
-- getting caught by: a model of the world maintained by hand. It is checked
-- against reality by the `events` capture -- /cn capture asks the live client
-- to register every event the addon uses and records which ones it refused --
-- and the stub audit fails on any refusal. Until a recording is present, this
-- list catches typos and inventions but cannot catch an event that was real
-- and has since been removed.
CN_KNOWN_EVENTS = {}

for _, name in ipairs({
    "ACHIEVEMENT_EARNED", "ADDON_LOADED", "BAG_UPDATE_DELAYED",
    "BANKFRAME_OPENED", "BOSS_KILL", "CHALLENGE_MODE_COMPLETED",
    "CRAFTINGORDERS_CLAIM_ORDER_RESPONSE", "CRAFTINGORDERS_UPDATE_ORDER_COUNT", "CRITERIA_UPDATE",
    "CURRENCY_DISPLAY_UPDATE", "ENCOUNTER_END", "GOSSIP_SHOW",
    "KNOWN_TITLES_UPDATE", "MAIL_INBOX_UPDATE", "MAJOR_FACTION_RENOWN_LEVEL_CHANGED",
    "MAJOR_FACTION_UNLOCKED", "MERCHANT_SHOW", "MERCHANT_UPDATE",
    "NEW_MOUNT_ADDED", "NEW_PET_ADDED", "NEW_TOY_ADDED",
    "PET_JOURNAL_LIST_UPDATE", "PLAYER_CONTROL_GAINED", "PLAYER_CONTROL_LOST",
    "PLAYER_ENTERING_WORLD", "PLAYER_LEVEL_UP", "PLAYER_LOGIN",
    "PLAYER_LOGOUT", "PLAYER_REGEN_DISABLED", "PLAYER_REGEN_ENABLED",
    "PLAYER_SPECIALIZATION_CHANGED", "QUEST_ACCEPTED", "QUEST_DATA_LOAD_RESULT",
    "QUEST_DETAIL", "QUEST_LOG_UPDATE", "QUEST_REMOVED",
    "QUEST_TURNED_IN", "SKILL_LINES_CHANGED", "TAXIMAP_CLOSED",
    "TAXIMAP_OPENED", "TRADE_SKILL_LIST_UPDATE", "TRADE_SKILL_SHOW",
    "TRANSMOG_COLLECTION_UPDATED", "UPDATE_FACTION", "UPDATE_INSTANCE_INFO",
    "VIGNETTES_UPDATED", "VIGNETTE_MINIMAP_UPDATED", "WEEKLY_REWARDS_UPDATE",
    "ZONE_CHANGED", "ZONE_CHANGED_NEW_AREA", "GROUP_ROSTER_UPDATE",
    "PLAYER_ALIVE", "PLAYER_DEAD", "PLAYER_UNGHOST",
    -- 0.59.0: watching for the hearth being cast, so the addon can learn
    -- where the player's bind point actually is rather than guessing at a
    -- localized inn name. Real events, both of them, and both checked
    -- against the client's own list before being added -- which is what
    -- adding a name to this table is supposed to mean.
    "UNIT_SPELLCAST_SUCCEEDED", "HEARTHSTONE_BOUND",
}) do
    CN_KNOWN_EVENTS[name] = true
end

local function Frame()
    local f = {}
    local events, scripts = {}, {}

    f.events  = events
    f.scripts = scripts

    -- THE CLIENT REFUSES AN EVENT IT DOES NOT HAVE. SO DOES THIS.
    --
    -- This stub accepted any string, which is how `NEW_TAXI_NODE` -- a name
    -- that does not exist and never has -- shipped in 0.46.0 and threw a Lua
    -- error at every login. Eighty files of tests, a mutation suite and two
    -- interpreters, and not one of them could see it, because the fake frame
    -- was more forgiving than the real one.
    --
    -- Tenth entry in the list of defects caused by a stub simpler than the
    -- thing it stands for. The list is in CN_KNOWN_EVENTS below, and adding
    -- an event to it is the deliberate act that asks "is this real?".
    function f:RegisterEvent(e)
        assert(CN_KNOWN_EVENTS[e],
            "the client has no event called " .. tostring(e)
            .. " -- if it is real, add it to CN_KNOWN_EVENTS in harness.lua")

        events[e] = true

        -- A broad registration replaces a narrow one, as in the client.
        rawset(f, "unitEvents", rawget(f, "unitEvents") or {})

        f.unitEvents[e] = nil
    end

    -- A UNIT EVENT REGISTERED BROADLY FIRES FOR EVERY UNIT TOKEN. 0.86.0.
    --
    -- This fell through to the universal stub, so "is this event narrowed to
    -- the player, or is it firing for all forty raid members" was a question
    -- no test could ask -- and the addon's one unit event was registered
    -- broadly. Nineteenth entry in this file's list of defects hidden by a
    -- stub simpler than the client.
    function f:RegisterUnitEvent(e, ...)
        assert(CN_KNOWN_EVENTS[e],
            "the client has no event called " .. tostring(e))

        events[e] = true

        rawset(f, "unitEvents", rawget(f, "unitEvents") or {})

        f.unitEvents[e] = { ... }
    end

    function f:GetUnitEventUnits(e)
        local held = rawget(f, "unitEvents")

        return held and held[e]
    end
    function f:UnregisterEvent(e) events[e] = nil end
    function f:SetScript(k, fn) scripts[k] = fn end
    function f:GetScript(k) return scripts[k] end
    function f:IsShown() return rawget(f, "shown") == true end
    function f:Show() f.shown = true end
    function f:Hide() f.shown = false end

    -- `SetShown` fell through to the universal stub, so every frame the addon
    -- shows or hides through it -- the selected-tab rule, the row selection
    -- texture, the progress bar -- was invisible to every test.
    -- STRATA AND MOVABILITY, RECORDED.
    --
    -- Both fell through to the universal stub, which accepts anything and
    -- remembers nothing -- so "is this frame where the player can click it"
    -- was a question no test could ask. The heads-up line sat at the lowest
    -- strata in the addon for eleven releases and a player had to report it.
    -- Sixteenth entry in the list.
    function f:SetFrameStrata(value) f.strata = value end
    function f:GetFrameStrata() return rawget(f, "strata") or "MEDIUM" end

    function f:SetMovable(value) f.movable = value and true or false end
    function f:IsMovable() return rawget(f, "movable") == true end

    function f:SetShown(value)
        if value then
            f:Show()
        else
            f:Hide()
        end
    end
    -- AN EDIT BOX THAT LOSES FOCUS LOUDLY, LIKE THE CLIENT'S.
    --
    -- `SetText`/`GetText` and `ClearFocus` all fell through to the universal
    -- stub, which accepts anything and remembers nothing -- so the window's
    -- filter box could not be read by any test, and `ClearFocus` fired no
    -- `OnEditFocusLost`. In the client it does, and 0.58.0 shipped a defect
    -- that lived entirely inside that handler: clearing the box on a tab with
    -- no list destroyed the filter the player had asked to keep.
    --
    -- Eleventh entry in the list of defects a stub simpler than the real
    -- thing made invisible.
    function f:SetText(value) f.text = value end
    function f:GetText() return f.text or "" end

    function f:SetFocus() f.focused = true end

    function f:ClearFocus()
        if f.focused then
            f.focused = false

            local handler = scripts.OnEditFocusLost

            if handler then
                handler(f)
            end
        end
    end

    function f:Enable() f.enabled = true end
    function f:Disable() f.enabled = false end
    function f:IsEnabled() return rawget(f, "enabled") ~= false end

    -- THE TEMPLATE IS RECORDED, AND SO IS THE FONT OBJECT SET AFTERWARDS.
    --
    -- Both fell through to the universal stub, which accepts anything and
    -- remembers nothing -- so "what size is this text" was a question no test
    -- could ask, and the window's entire typography was invisible to the
    -- suite. Seventeenth entry in the list of defects a stub simpler than the
    -- client made unobservable. 0.66.0.
    -- A TEMPLATED BUTTON ARRIVES WITH ITS OWN LABEL, AND THIS HAD NONE.
    --
    -- `GetFontString` fell through to the universal stub, which answers any
    -- call with another stub -- truthy, and truthy again when asked for its
    -- font. So "does this button's caption wear the player's text size" was
    -- a question that answered yes whatever the addon did, and the mutation
    -- for it survived. Eighteenth entry in the list. 0.68.0.
    function f:SetFontString(value) f.fontString = value end

    function f:GetFontString()
        if not rawget(f, "fontString") then
            f.fontString = f:CreateFontString(nil, "ARTWORK", "GameFontNormal")
        end

        return rawget(f, "fontString")
    end

    function f:CreateFontString(_, layer, template)
        local fs = Frame()

        fs.layer    = layer
        fs.template = template

        function fs:SetFontObject(object) fs.fontObject = object end
        function fs:GetFontObject() return rawget(fs, "fontObject") end

        -- AND THE EXPLICIT FACE/SIZE/FLAGS PATH, which is what `CN.Outline`
        -- uses -- a font object cannot carry an outline. It fell through to
        -- the universal stub, so the four widgets drawn over the world were
        -- the only text in the addon no test could measure. 0.67.0.
        function fs:SetFont(file, points, flags)
            fs.fontFile, fs.fontSize, fs.fontFlags = file, points, flags
        end

        function fs:GetFont()
            local object = rawget(fs, "fontObject")

            if rawget(fs, "fontSize") then
                return rawget(fs, "fontFile"), rawget(fs, "fontSize"),
                    rawget(fs, "fontFlags")
            end

            if object and object.GetFont then
                return object:GetFont()
            end

            local fontTemplate = rawget(fs, "template")

            if fontTemplate and _G[fontTemplate] and _G[fontTemplate].GetFont then
                return _G[fontTemplate]:GetFont()
            end

            return nil
        end

        -- Record what was actually displayed. The universal stub swallowed
        -- SetText, so no test could ever assert what the arrow said.
        function fs:SetText(value) fs.text = value end
        function fs:GetText() return fs.text end

        -- A NUMBER, because the client returns one and the universal stub
        -- returns a frame -- which is truthy, so `24 + width` threw where the
        -- real call would have worked. Thirteenth entry in the list. Roughly
        -- six pixels per character is close enough for a hit rect and is not
        -- claimed to be more than that.
        function fs:GetStringWidth()
            return #tostring(fs.text or "") * 6
        end

        function fs:GetStringHeight() return 12 end

        return fs
    end

    function f:CreateTexture()
        local t = Frame()

        -- RECORD ROTATION AND COLOUR.
        --
        -- These fell through to the universal stub, which accepts anything
        -- and remembers nothing. That is why the on-screen arrow -- the most
        -- visible thing this addon draws -- had no test that could see which
        -- way it pointed, and why a player had to report the same defect
        -- twice.
        function t:SetRotation(value) t.rotation = value end
        function t:GetRotation() return t.rotation end

        function t:SetVertexColor(r, g, b)
            t.colour = { r = r, g = g, b = b }
        end

        function t:GetVertexColor()
            local c = t.colour or {}
            return c.r, c.g, c.b
        end

        function t:SetTexture(path) t.texturePath = path end
        function t:GetTexture() return t.texturePath end

        return t
    end

    -- Numeric getters must return numbers, or arithmetic in the addon
    -- silently becomes "attempt to perform arithmetic on a table value".
    --
    -- AND A WIDTH THAT WAS SET MUST BE THE WIDTH THAT COMES BACK.
    --
    -- These were flat constants and `SetWidth` fell through to the universal
    -- stub, so nothing the addon sized could be asserted about -- which is
    -- how a progress bar drawn at a fixed width would have passed. A stub
    -- that forgets what it was told is a stub that agrees with any code.
    function f:SetWidth(value)
        if type(value) == "number" then
            f.width = value
        end
    end

    function f:SetHeight(value)
        if type(value) == "number" then
            f.height = value
        end
    end

    function f:SetSize(w, h)
        f:SetWidth(w)
        f:SetHeight(h)
    end

    -- `rawget`, NOT `f.width`. Every frame here has a catch-all `__index`
    -- that answers with the universal stub, so an unset field reads back as a
    -- TABLE rather than as nil -- and `f.width or 400` therefore returned a
    -- table, which the addon then did arithmetic on.
    function f:GetWidth() return rawget(f, "width") or 400 end
    function f:GetHeight() return rawget(f, "height") or 300 end

    -- SCALE IS STATE, AND THE ONE PIECE OF IT THAT CAN PUT A WINDOW OFF THE
    -- SCREEN. 0.85.0. This fell through to the universal stub, so "does the
    -- window still fit at the largest size the addon offers" was
    -- unanswerable by any test -- and the answer had just become no.
    function f:SetScale(value)
        if type(value) == "number" then
            rawset(f, "scale", value)
        end
    end

    function f:GetScale() return rawget(f, "scale") or 1 end
    function f:GetTextWidth() return 60 end
    function f:GetTextHeight() return 12 end
    function f:GetEffectiveScale() return 1 end
    function f:GetCenter() return 500, 400 end
    -- WHERE A REGION WAS ACTUALLY ANCHORED.
    --
    -- `SetPoint` fell through to the universal stub, so every layout question
    -- -- does this control overlap that one, does the label leave room for
    -- the button -- was unanswerable by any test. The addon has shipped three
    -- overlapping-control defects that a player had to report. Seventeenth
    -- entry in the list.
    --
    -- Recorded per anchor point, last write wins, which is how the client
    -- behaves for the same point.
    function f:SetPoint(point, ...)
        f.points = rawget(f, "points") or {}

        local relativeTo, relativePoint, x, y = ...

        -- `SetPoint("LEFT", 4, 0)` is the two-number form; the four-argument
        -- form names a frame first.
        if type(relativeTo) == "number" then
            relativeTo, relativePoint, x, y = nil, nil, relativeTo, relativePoint
        end

        local key = point or "?"

        local order = rawget(f, "pointOrder") or {}

        if rawget(f, "points")[key] == nil then
            table.insert(order, key)
        end

        rawset(f, "pointOrder", order)

        f.points[key] = {
            point         = point,
            relativeTo    = relativeTo,
            relativePoint = relativePoint,
            x             = x,
            y             = y,
        }
    end

    function f:ClearAllPoints()
        f.points = {}
        f.pointOrder = {}
    end

    -- RECORDED, BECAUSE A BUTTON THAT IS NOT REGISTERED FOR DRAG IS A DEAD
    -- ZONE. 0.77.0.
    --
    -- This fell through to the universal stub, so "does the corner with the x
    -- in it still drag the frame" was unanswerable by any test -- and the
    -- drag scripts alone do not answer it: a frame that never registers for
    -- the button never fires them.
    function f:RegisterForDrag(...)
        rawset(f, "dragButtons", { ... })
    end

    function f:GetRegisteredDragButtons()
        return rawget(f, "dragButtons")
    end

    function f:GetPointBy(point)
        local held = rawget(f, "points")

        return held and held[point]
    end

    -- THE FIRST POINT SET, WHATEVER IT IS CALLED. 0.77.0.
    --
    -- This looked only at TOPLEFT, CENTER and LEFT, and answered
    -- `"CENTER", nil, "CENTER", 0, 0` for anything else -- so a frame
    -- anchored BOTTOMLEFT to TOPRIGHT, which is exactly the shape that
    -- breaks a save that discards the relative point, could not be
    -- represented at all. A stub less capable than the client is a stub that
    -- hides the defect it should catch.
    function f:GetPoint(index)
        local held  = rawget(f, "points")
        local order = rawget(f, "pointOrder") or {}

        local key = order[index or 1]

        local anchor = held and key and held[key]

        if not anchor and held then
            anchor = held.TOPLEFT or held.CENTER or held.LEFT
        end

        if anchor then
            return anchor.point, anchor.relativeTo, anchor.relativePoint,
                anchor.x or 0, anchor.y or 0
        end

        return "CENTER", nil, "CENTER", 0, 0
    end

    setmetatable(f, { __index = function() return U end })

    return f
end

