      pieces = { true, false, false, false, false, false } },
}

C_TransmogSets = {
    GetAllSets = function()
        local sets = {}

        for _, set in ipairs(CN_TEST_SETS) do
            table.insert(sets, {
                setID     = set.setID,
                name      = set.name,
                collected = set.collected,
            })
        end

        return sets
    end,

    GetSetPrimaryAppearances = function(setID)
        for _, set in ipairs(CN_TEST_SETS) do
