local achievementData
achievementData = {
    [10] = { name = "Almost There",  points = 10, completed = false, criteria = 5, done = 4 },
    [11] = { name = "Long Way Off",  points = 10, completed = false, criteria = 50, done = 2 },
    [12] = { name = "Done Already",  points = 20, completed = true,  criteria = 3, done = 3 },
    [13] = { name = "One Criterion", points = 5,  completed = false, criteria = 2, done = 1 },
}

local categoryAchievements = { [92] = { 10, 11 }, [96] = { 12, 13 }, [97] = { 20, 21 } }

-- A test about what a SCAN keeps and drops needs to be able to put something
-- in the game's category listing and take it out again.
function CN_TEST_AddToCategory(categoryID, achievementID)
    categoryAchievements[categoryID] = categoryAchievements[categoryID] or {}

    for _, held in ipairs(categoryAchievements[categoryID]) do
        if held == achievementID then
            return
        end
    end

    table.insert(categoryAchievements[categoryID], achievementID)
end

function CN_TEST_RemoveFromCategory(categoryID, achievementID)
    local list = categoryAchievements[categoryID]

    if not list then
        return
    end

    for index = #list, 1, -1 do
        if list[index] == achievementID then
            table.remove(list, index)
        end
    end
end

achievementDataExtra = {
    [20] = { name = "Explore Eversong Woods", points = 10, completed = false, criteria = 12, done = 9 },
    [21] = { name = "Explore Durotar",        points = 10, completed = true,  criteria = 8,  done = 8 },
}

for id, data in pairs(achievementDataExtra) do achievementData[id] = data end

function GetCategoryList() return { 92, 96, 97 } end

-- The achievement category tree. 96 is Blizzard's "Quests" root; the others
-- hang off it the way expansion and continent categories really do, so the
-- tree walk has an actual tree to walk rather than a flat list that would
-- pass without exercising anything.
local achievementCategories = {
    [96] = { name = "Quests",          parent = -1 },
    [92] = { name = "Khaz Algar",      parent = 96 },
    [97] = { name = "Dragon Isles",    parent = 96 },
    [11] = { name = "Not A Quest Cat", parent = -1 },
}

-- A test needs to be able to name a category after the continent the fixture
-- player is standing on -- that comparison is the 0.73.0 tie-break between
-- two zones with one name.
function CN_TEST_SetCategoryName(categoryID, name)
    if not name then
        achievementCategories[categoryID] = nil

        return
    end

    achievementCategories[categoryID] =
        achievementCategories[categoryID] or { parent = 96 }

    achievementCategories[categoryID].name = name
end

function GetCategoryInfo(categoryID)
    local entry = achievementCategories[categoryID]

    if not entry then
        return nil
    end

    return entry.name, entry.parent, 0
end

function GetCategoryNumAchievements(categoryID)
    local list = categoryAchievements[categoryID] or {}
    local done = 0
    for _, id in ipairs(list) do
        if achievementData[id].completed then done = done + 1 end
    end
    return #list, done
end

function GetAchievementInfo(a, b)
    local id
    if b then
        local list = categoryAchievements[a] or {}
        id = list[b]
    else
        id = a
    end
    local data = achievementData[id]
    if not data then return nil end
    return id, data.name, data.points, data.completed, 1, 1, 2026, "desc", 0, 1
end

-- An id the fixture's client actually knows, for tests that need to tell
-- "the client answered" from "the client did not". 0.71.0.
function CN_TEST_KnownAchievementID()
    return (next(achievementData))
end

function GetAchievementNumCriteria(id)
    return achievementData[id] and achievementData[id].criteria or 0
end

-- A META ACHIEVEMENT, WHICH IS THE SHAPE THE CAP WAS WRONG FOR.
--
-- The fixture's achievements all have a handful of criteria, so a reader
-- that capped its own loop at 25 and then counted the rows looked correct
-- for every one of them. Every meta achievement in the game is past that cap
-- and none was representable here.
local wideAchievementID = 990000

-- AN ACHIEVEMENT THE CLIENT KNOWS BY NAME.
--
-- Since 0.64.0 the addon reads achievement names live rather than from its own
-- store, so a test that invents a store row without telling the client about
-- it is testing a row the addon can no longer name.
function CN_TEST_MakeAchievement(achievementID, name, criteria, done)
    achievementData[achievementID] = {
        name      = name,
        points    = 10,
        completed = false,
        criteria  = criteria or 0,
        done      = done or 0,
    }

    return achievementID
end

function CN_TEST_MakeWideAchievement(criteria, done)
    wideAchievementID = wideAchievementID + 1

    achievementData[wideAchievementID] = {
        name      = "Glory of Something Large",
        points    = 10,
        completed = false,
        criteria  = criteria,
        done      = done,
    }

    return wideAchievementID
end

-- The real signature carries a quantity and a requirement after the
-- completion flag, and some criteria are counters rather than checkboxes.
-- Returning only three values modelled a world where every criterion is a
-- checkbox, which is the kind of simplification that has hidden real bugs in
-- this addon twice.
function GetAchievementCriteriaInfo(id, index)
    local data = achievementData[id]
    if not data then return nil end

    local completed = index <= data.done

    -- Make the second criterion a counter, so anything reading quantity has
    -- a case where it actually matters.
    if index == 2 then
        return "collect widgets", 1, completed, completed and 25 or 7, 25
    end

    return "criterion " .. index, 1, completed, completed and 1 or 0, 1
end

function GetNumCompletedAchievements() return 4, 1 end

