local toc = assert(io.open(ROOT .. "/CompletionNavigator.toc", "r"))
local files = {}

for line in toc:lines() do
    line = line:gsub("%s+$", "")
    if line ~= "" and not line:match("^#") and line:match("%.lua$") then
        table.insert(files, (line:gsub("\\", "/")))
    end
end

toc:close()

io.stdout:setvbuf("line")

-- SOME RULES ARE ABOUT WHAT THE SOURCE MUST NOT SAY.
--
-- "Nothing expensive on the login frame" is not observable from behaviour --
-- an eager refresh and a deferred one produce the same text -- so it is
-- asserted against the file. Used sparingly and only where the rule really is
-- structural.
-- The .toc order, published so a source lint can walk every file rather than
-- a hand-kept list that the next new module is not added to.
CN_TEST_ADDON_FILES = files

function CN_TEST_ReadAddonFile(relative)
    local handle = io.open(ROOT .. "/" .. relative, "r")

    if not handle then
        return nil
    end

    local text = handle:read("*a")

    handle:close()

    return text
end

local ADDON_NAME = "CompletionNavigator"
local CN = {}

print("Loading " .. #files .. " files:")

for _, relative in ipairs(files) do
    local path  = ROOT .. "/" .. relative
    local chunk, err = loadfile(path)

    if not chunk then
        print("LOAD ERROR " .. relative .. ": " .. tostring(err))
        os.exit(1)
    end

    local ok, runErr = pcall(chunk, ADDON_NAME, CN)

    if not ok then
        print("RUNTIME ERROR " .. relative .. ": " .. tostring(runErr))
        os.exit(1)
    end

    print("  ok  " .. relative)
end

