end)()

;(function()
    ------------------------------------------------------------
    -- THIRTY THOUSAND CLIENT CALLS FOR A NUMBER THAT MOVES BY ONE.
    --
    -- The Remaining tab's quest row walked every discovered quest, calling
    -- the client on each, on every invalidated refresh -- 13.65 ms at retail
    -- scale for a figure that changes by exactly one when a quest is handed
    -- in. Counted once and maintained since 0.61.0.
    ------------------------------------------------------------
    local breakdown = CN:GetModule("Breakdown")
    local quests    = CN:GetModule("Quests")

    breakdown.ForgetQuestCounts()

    local discovered = CN.Account("discoveredQuests")

    for id = 970001, 970200 do
        discovered[id] = true
    end

    -- Count the client calls the way the provider makes them.
    local real = quests.IsCompletedByCharacter
    local asked = 0

    quests.IsCompletedByCharacter = function(questID)
        asked = asked + 1

        return real(questID)
    end

    local first = breakdown.CompletedQuestCount()

    local walked = asked

    assert(walked >= 200,
        "the first count must actually walk the set, walked " .. walked)

    asked = 0

    for _ = 1, 20 do
        assert(breakdown.CompletedQuestCount() == first,
            "and every repeat gives the same answer")
    end

    assert(asked == 0,
        "twenty refreshes must not ask the client again, asked " .. asked)

    -- A turn-in credits the count without rewalking.
    --
    -- The count is read AFTER the event, and `asked` is zeroed in between:
    -- other handlers on QUEST_TURNED_IN legitimately ask the client about
    -- the one quest that was handed in, and this is a claim about the walk,
    -- not about the whole event.
    CN_TEST_COMPLETED[970001] = true

    CN.Dispatch("QUEST_TURNED_IN", 970001)

    asked = 0

    assert(breakdown.CompletedQuestCount() == first + 1,
        "a turn-in moves the count by one: "
        .. breakdown.CompletedQuestCount() .. " from " .. first)

    assert(asked <= 1,
        "and without walking the set again, asked " .. asked)

    -- A REPEATABLE TURN-IN IS NOT A COMPLETION.
    --
    -- Most turn-ins in a modern evening are repeatable -- a token hand-in, an
    -- assault, a holiday daily -- and `IsQuestFlaggedCompleted` stays false
    -- for them. A "+1 per turn-in" count adds one every time, so twenty
    -- hand-ins is twenty phantom completions and the tab can report more
    -- quests completed than discovered.
    local credited = breakdown.CompletedQuestCount()

    for _ = 1, 20 do
        CN.Dispatch("QUEST_TURNED_IN", 970002)
    end

    assert(breakdown.CompletedQuestCount() == credited,
        "a repeatable turn-in the client does not flag as completed must "
        .. "not be counted, twenty times or once: "
        .. breakdown.CompletedQuestCount() .. " from " .. credited)

    -- And handing the SAME completed quest in again cannot credit it twice.
    for _ = 1, 5 do
        CN.Dispatch("QUEST_TURNED_IN", 970001)
    end

    assert(breakdown.CompletedQuestCount() == credited,
        "and a quest already counted is not counted again: "
        .. breakdown.CompletedQuestCount() .. " from " .. credited)

    CN_TEST_COMPLETED[970001] = nil

    -- A quest the addon has never seen is not in the denominator, so it must
    -- not be credited to it. Asserted against the credit function directly:
    -- dispatching the event would ALSO discover the quest -- `RecordDiscovered`
    -- is on the same event -- which grows the set and correctly triggers a
    -- recount, so the event is the wrong seam for this particular claim.
    local heldCount = breakdown.CompletedQuestCount()

    breakdown.NoteQuestCompleted(979999)

    asked = 0

    assert(breakdown.CompletedQuestCount() == heldCount,
        "an undiscovered quest is not credited to a set it is not in: "
        .. breakdown.CompletedQuestCount() .. " from " .. heldCount)

    -- Pressing Refresh asks to be told the truth rather than the remembered
    -- answer, and the quest figure is the one number in this file that does
    -- not live in the report cache.
    asked = 0

    breakdown.Report(nil, true)

    assert(asked >= 200,
        "a forced recount must recount the quests, asked " .. asked)

    quests.IsCompletedByCharacter = real

    for id = 970001, 970200 do
        discovered[id] = nil
    end

    breakdown.ForgetQuestCounts()

    print("  the Remaining tab counts thirty thousand quests once, then "
        .. "maintains it")
end)()

;(function()
    ------------------------------------------------------------
    -- A RECOMMENDED RECIPE IS CALLED SOMETHING.
    --
    -- The recipe provider was changed to iterate the vendor item index rather
    -- than every known recipe name. `CN.CollectBounded` hands the build
    -- callback `source[id]` as its second argument -- which under the new
    -- source is the ARRAY OF NPC IDS, not the name. Assigning that to `name`
    -- did not throw, because every reader wraps a name in `tostring`. It put
    -- `table: 0x...` on the recommended row, in the heads-up line, on the map
    -- pin and in the data-broker feed.
    --
    -- Nothing in the suite asserted what a recipe row is CALLED, which is how
    -- a defect that renders a pointer to the player passed every test.
    ------------------------------------------------------------
    local provider = CN.candidateProviders["Vendors"]

    assert(provider, "the recipe provider must be registered")

    -- THE FIXTURE NEVER PRODUCED A ROW FROM THIS PROVIDER.
    --
    -- Which is why the defect above was invisible: a provider whose output is
    -- always empty asserts nothing. Its two conditions are a located seller
    -- who sells the item, and a recipe name for it that this character does
    -- not know. Both are set up here, explicitly.
    local merchantModule   = CN:GetModule("Vendors")
    local professionModule = CN:GetModule("Professions")

    local vendorStore = CN.Account("vendors")

    vendorStore[912345] = {
        name  = "Trader Halkaz",
        mapID = 94,
        x     = 0.31,
        y     = 0.62,
        zone  = "Eversong Woods",
        items = { [880001] = 25000 },
    }

    -- The RECIPE id is not the ITEM id. The vendor sells item 880001, whose
    -- name teaches recipe 770001. The provider must join those by name.
    CN.Account("recipeNames")[770001] = "Flask of Assertion"

    professionModule.nameRevision = (professionModule.nameRevision or 0) + 1

    merchantModule.ForgetItemIndex()

    local rows = provider.fn() or {}

    local checked = 0

    for _, objective in ipairs(rows) do
        assert(type(objective.name) == "string" and objective.name ~= "",
            "a recipe row must be named, got a "
            .. type(objective.name) .. ": " .. tostring(objective.name))

        assert(not tostring(objective.name):find("table: ", 1, true),
            "and the name must not be a table address: "
            .. tostring(objective.name))

        -- AND IT IS THE RECIPE'S NAME, REACHED BY NAME. 0.81.0. The store
        -- this comes from is keyed by trade-skill recipe id; the id the row
        -- is built from is a merchant item id. If those are joined by number
        -- again, this fixture produces no rows at all and the count below
        -- fails.
        assert(objective.name == "Flask of Assertion",
            "the row carries the recipe's name, not the item's: "
            .. tostring(objective.name))

        -- AND ITS IDENTITY IS THE RECIPE ID. 0.82.0.
        --
        -- The RECIPE eligibility checker indexes `character.recipes`, which
        -- is keyed by trade-skill recipe id. A row identified by the
        -- merchant's item id asked that table an item-id question, and on a
        -- collision answered "already known" -- retiring the waypoint from a
        -- recipe the player had not bought.
        assert(objective.id == 770001,
            "the row is identified by the recipe it teaches: "
            .. tostring(objective.id))

        assert(objective.itemID == 880001,
            "and keeps the merchant item beside it, which is what you buy: "
            .. tostring(objective.itemID))

        checked = checked + 1
    end

    assert(checked > 0,
        "the fixture must produce at least one recipe candidate to check")

    vendorStore[912345] = nil
    CN.Account("recipeNames")[770001] = nil

    merchantModule.ForgetItemIndex()

    print("  a recommended recipe is named after the recipe")
end)()

;(function()
    ------------------------------------------------------------
    -- A SCAN IS THE LOUDEST THING THAT CHANGES A COLLECTION COUNT.
    --
    -- The Collections, Scans and Warband tabs memoize their `Summary()` calls
    -- against `CN.collectionGeneration`, which was bumped by the CLIENT
    -- events that announce a collection changing -- and not by the addon's
    -- own scans, which are what actually populate the stores those summaries
    -- read.
    --
    -- So on the onboarding screen: press "Scan everything", the stores fill,
    -- the "last read" stamp beside each row updates to "just now" because it
    -- is not memoized -- and the count beside it still says "not scanned".
    -- The tab contradicts itself until a zone change happens along.
    ------------------------------------------------------------
    local scanGeneration = CN.collectionGeneration or 0

    CN.MarkScanned("pets")

    assert((CN.collectionGeneration or 0) > scanGeneration,
        "a scan must move the generation the tabs are memoized against: "
        .. tostring(CN.collectionGeneration) .. " from " .. scanGeneration)

    -- And through the memo itself, which is the thing that was wrong.
    local rebuilds = 0

    local function Count()
        return CN.Memo("harness:scan-memo", CN.collectionGeneration, function()
            rebuilds = rebuilds + 1

            return rebuilds
        end)
    end

    Count()
    Count()

    assert(rebuilds == 1, "the memo holds while nothing has changed")

    CN.MarkScanned("mounts")

    Count()

    assert(rebuilds == 2,
        "and a scan releases it, so the tab shows what the scan found")

    print("  scanning something changes what the tabs say about it")
end)()

print("\nWhat 0.60.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- HANDING A QUEST IN TAKES IT OFF THE LIST.
    --
    -- Reported from play: "the completion of a quest does not appear to
    -- remove it from the journey or queue."
    --
    -- The Inventory provider emits a row per nearly-finished quest objective
    -- -- "Test Quest Alpha: 1 more" -- read from the quest log, and declared
    -- only bag events. `InvalidateCandidates` SKIPS a provider that has an
    -- events table and was not named, so a turn-in did not touch those rows
    -- at all: they survived until a bag update or a loading screen.
    --
    -- Invisible to this suite for a different reason:
    -- `IsQuestFlaggedCompleted` was a pure function of the quest id, so the
    -- single most ordinary thing that happens in this game could not be
    -- written down. `CN_TEST_TurnInQuest` is that missing verb.
    ------------------------------------------------------------
    local questID = 9001

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    local function Offered()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.type == CN.objectiveTypes.QUEST
                and objective.id == questID then

                return objective
            end
        end
    end

    assert(Offered(), "the fixture must offer quest " .. questID .. " first")

    -- Rebuilt a moment ago, so every provider's cooldown is at its coldest --
    -- which is the case that used to hide this.
    assert(CN_TEST_TurnInQuest(questID), "it must have been in the log")

    CN.Dispatch("QUEST_TURNED_IN", questID)

    local lingering = Offered()

    assert(not lingering,
        "a quest you have handed in must leave the list at once, not when "
        .. "some unrelated event happens along; it is still offered as \""
        .. tostring(lingering and lingering.name) .. "\"")

    -- AND IT LEAVES THE ROUTE WITH IT, which is where the player saw it.
    local mapID, x, y = CN.GetPlayerPosition()

    CN.ForgetRoutes()

    for _, objective in ipairs(CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5) or {}) do
        assert(objective.id ~= questID,
            "and it must not still be a stop on the route")
    end

    -- The fixture goes back the way it was found.
    CN_TEST_RestoreQuestLog()

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    assert(Offered(),
        "and the fixture is restored, or every test after this one is "
        .. "running against a world this one changed")

    print("  a quest handed in leaves the list and the route at once")
end)()

;(function()
    ------------------------------------------------------------
    -- A PROVIDER DECLARES THE EVENTS OF EVERY SYSTEM IT READS.
    --
    -- The defect above is a class, not an instance: a provider's `events`
    -- table is the ONLY thing that decides whether it is invalidated, and a
    -- provider that reads the quest log while declaring bag events is a
    -- provider whose rows go stale silently and stay stale.
    --
    -- Checked structurally, so the next one fails the build rather than
    -- reaching a player.
    ------------------------------------------------------------
    local systems = {
        {
            name    = "the quest log",
            readers = {
                "GetQuestLogEntries", "IsQuestInLog", "QuestProgress",
                "GetQuestObjectives",
            },
            events  = {
                "QUEST_TURNED_IN", "QUEST_REMOVED", "QUEST_ACCEPTED",
                "QUEST_LOG_UPDATE",
            },
        },
        {
            name    = "your bags",
            readers = { "Inventory.Bags", "GetContainerItemInfo" },
            events  = { "BAG_UPDATE_DELAYED" },
        },
        {
            -- A provider that scores by where the player is standing, or
            -- costs a journey from it, is answering a question whose answer
            -- changes every time they cross a zone line.
            name    = "where you are standing",
            -- `CN.TravelCost` is the one that matters: it prices a journey
            -- FROM the player, so its answer changes with every zone line.
            -- A bare `GetPlayerPosition` may only be asking which map to look
            -- something up on, which a zone change does not invalidate --
            -- Group asks it to find the player's own corpse.
            readers = { "CN.TravelCost" },
            events  = { "ZONE_CHANGED_NEW_AREA" },
        },
        {
            -- `CN.Explain` asks whether a mount, pet, toy, achievement or
            -- quest is already done. Every one of those has an event.
            name    = "what you have collected",
            -- The DYNAMIC call sites: `CN.Explain(goal.type, ...)` can be
            -- asking about any of them. `CN.Explain(CN.objectiveTypes.QUEST,
            -- ...)` is asking about a quest and the quest events cover it,
            -- which is why the literal form is not listed here.
            readers = {
                "CN.Explain(goal.type", "CN.Explain(objectiveType",
                "CN.Explain(record.type", "CN.Explain(entry.type",
            },
            events  = {
                "NEW_MOUNT_ADDED", "NEW_PET_ADDED", "NEW_TOY_ADDED",
                "ACHIEVEMENT_EARNED",
            },
        },
    }

    local manifest = assert(io.open(ROOT .. "/CompletionNavigator.toc", "r"))

    local offenders, checked = {}, 0

    for entry in manifest:read("*a"):gmatch("[^\r\n]+") do
        if entry:match("%.lua$") and not entry:match("^#") then
            local path = ROOT .. "/" .. (entry:gsub("\\", "/"))

            local file = io.open(path, "r")

            if file then
                local text = file:read("*a")

                file:close()

                -- CODE, NOT PROSE. 0.69.0.
                --
                -- This searched the whole file for a reader's name, comments
                -- included -- so a comment EXPLAINING why something no longer
                -- calls `CN.TravelCost` reported the file as calling it. The
                -- same trap the CI preflight documents having closed: "the
                -- check passed on prose and said nothing", in the other
                -- direction. A lint that reads comments is a lint that can be
                -- talked out of, and talked into.
                local code = {}

                for line in (text .. "\n"):gmatch("([^\n]*)\n") do
                    if not line:match("^%s*%-%-") then
                        table.insert(code, (line:gsub("%s%-%-[^\"]*$", "")))
                    end
                end

                text = table.concat(code, "\n")

                -- One provider per file in this addon, so the file is the
                -- unit. `events = { ... }` on the registration is what
                -- `InvalidateCandidates` reads.
                if text:find("RegisterCandidateProvider", 1, true) then
                    local declared = text:match("events%s*=%s*{(.-)}")

                    if declared then
                        checked = checked + 1

                        for _, system in ipairs(systems) do
                            local reads = false

                            for _, reader in ipairs(system.readers) do
                                if text:find(reader, 1, true) then
                                    reads = true
                                    break
                                end
                            end

                            if reads then
                                local covered = false

                                for _, event in ipairs(system.events) do
                                    if declared:find(event, 1, true) then
                                        covered = true
                                        break
                                    end
                                end

                                if not covered then
                                    table.insert(offenders,
                                        path:gsub("^.*/", "") .. " reads "
                                        .. system.name
                                        .. " and declares none of its events")
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    manifest:close()

    for _, offender in ipairs(offenders) do
        print("  UNDECLARED: " .. offender)
    end

    assert(#offenders == 0,
        #offenders .. " provider(s) read a system whose events they do not "
        .. "declare. A provider that is not named is not invalidated, so its "
        .. "rows go stale and stay stale.")

    assert(checked >= 8,
        "the scan must have found the providers, saw " .. checked)

    print("  " .. checked .. " providers, each declaring the events of what "
        .. "it reads")
end)()

;(function()
    ------------------------------------------------------------
    -- THE HEADS-UP LINE CAN BE MOVED AND CAN BE CLOSED.
    --
    -- Reported from play: it "should be able to be dragged around to a
    -- different location", and "should also be able to be closed or turned
    -- off by clicking an x ... in or on the heads up box itself".
    --
    -- It was the only frame in the addon at BACKGROUND strata -- the arrow
    -- and the follow frame, which sit over the world in exactly the same way,
    -- are both MEDIUM -- so anything else on screen took the mouse first and
    -- all three of the actions its own tooltip promised did nothing.
    ------------------------------------------------------------
    local hud = CN:GetModule("Hud")

    local hudProbeFrame = hud.Build()

    assert(hudProbeFrame, "the heads-up hudProbeFrame must build")

    assert(hudProbeFrame:GetFrameStrata() == "MEDIUM",
        "a hudProbeFrame meant to be clicked and dragged cannot sit below everything "
        .. "else on screen; it is at " .. tostring(hudProbeFrame:GetFrameStrata()))

    assert(hudProbeFrame:IsMovable(), "and it must be movable")

    assert(hudProbeFrame:GetScript("OnDragStart") and hudProbeFrame:GetScript("OnDragStop"),
        "with both halves of the drag wired")

    -- THE WAY OUT.
    assert(hudProbeFrame.close, "there must be a close control on the line itself")

    local held = hud.IsEnabled()

    hud.SetEnabled(true)

    hudProbeFrame.close:GetScript("OnClick")(hudProbeFrame.close)

    assert(not hud.IsEnabled(),
        "the x turns the line off -- not merely hides it, which the next "
        .. "refresh would undo")

    hud.SetEnabled(held)

    print("  the heads-up line moves, and closes from itself")
end)()

;(function()
    ------------------------------------------------------------
    -- A TOOLTIP DOES NOT SILENTLY DELETE A HOVER HANDLER.
    --
    -- `SetScript` replaces, so a frame that did something on hover lost it
    -- the moment somebody attached a tooltip -- a trap invisible at the call
    -- site and dependent on the order two unrelated lines are written in.
    ------------------------------------------------------------
    local probe = CreateFrame("Frame", nil, UIParent)

    local entered, left = 0, 0

    probe:SetScript("OnEnter", function() entered = entered + 1 end)
    probe:SetScript("OnLeave", function() left = left + 1 end)

    CN.UI.AttachTooltip(probe, "something")

    probe:GetScript("OnEnter")(probe)
    probe:GetScript("OnLeave")(probe)

    assert(entered == 1,
        "the handler that was already there must still run, ran " .. entered)

    assert(left == 1, "and so must its partner, ran " .. left)

    print("  attaching a tooltip keeps the hover handler already there")
end)()

;(function()
    ------------------------------------------------------------
    -- "INVALIDATE EVERYTHING" HAS TO INVALIDATE EVERYTHING.
    --
    -- `CN.baseInvalidationEvents` says in its own comment that these events
    -- "must invalidate EVERYTHING regardless of who declared what". It was
    -- only used to make sure they were SUBSCRIBED; the ordinary per-provider
    -- filter was then applied to them like any other event -- and no provider
    -- declares `PLAYER_LEVEL_UP`, so levelling up invalidated zero of the
    -- twenty-three.
    ------------------------------------------------------------
    assert(CN.IsUniversalInvalidation(nil),
        "no reason at all is a deliberate act")

    for _, event in ipairs(CN.baseInvalidationEvents) do
        assert(CN.IsUniversalInvalidation(event),
            event .. " is on the list that says it reaches everything")
    end

    assert(not CN.IsUniversalInvalidation("QUEST_TURNED_IN"),
        "and an ordinary event still only reaches who asked for it")

    -- Through the dispatch, which is the path the game takes.
    local counted = 0

    for _ in pairs(CN.candidateProviders) do
        counted = counted + 1
    end

    assert(counted > 15, "the fixture must have the real provider set, saw "
        .. counted)

    CN.CollectCandidates(true)

    CN.Dispatch("PLAYER_LEVEL_UP")

    local dirty = 0

    for name in pairs(CN.candidateProviders) do
        if CN.IsProviderDirty and CN.IsProviderDirty(name) then
            dirty = dirty + 1
        end
    end

    assert(dirty == counted,
        "levelling up changes what is available to everything; it marked "
        .. dirty .. " of " .. counted .. " providers")

    print("  " .. counted .. " providers, and a level-up reaches all of them")
end)()

;(function()
    ------------------------------------------------------------
    -- BUMPING THE DECORATOR GENERATION IS HALF OF IT.
    --
    -- `CN.decoratorGeneration` is read in exactly one place: inside the
    -- branch that runs when a provider is ALREADY being rebuilt. So bumping
    -- it cannot make a clean provider re-decorate -- it defeats the
    -- identical-list shortcut, not the not-stale-at-all one.
    --
    -- Harvest and Goals both discovered this separately and both call
    -- `InvalidateCandidates` alongside the bump. Warband, Session and the
    -- decorator registry did not, so three of five callers were moving a
    -- counter nothing would read.
    ------------------------------------------------------------
    CN.CollectCandidates(true)

    local decoratorBefore = CN.decoratorGeneration

    local moved = CN.NoteDecoratorsChanged()

    assert(moved ~= decoratorBefore, "the counter moves")

    local clean = 0

    for name in pairs(CN.candidateProviders) do
        if CN.IsProviderDirty and not CN.IsProviderDirty(name) then
            clean = clean + 1
        end
    end

    assert(clean == 0,
        "and every provider is stale, because a counter nothing reads is not "
        .. "a way of telling anybody anything; " .. clean .. " stayed clean")

    -- REGISTERING A DECORATOR LATE MUST REACH THE ROWS ALREADY BUILT.
    --
    -- The registry's own header names this as the case it exists for.
    CN.CollectCandidates(true)

    CN.RegisterCandidateDecorator("LateProbe", function(objective)
        objective.lateProbe = true

        return objective
    end)

    local reached, total = 0, 0

    for _, objective in ipairs(CN.CollectCandidates()) do
        total = total + 1

        if objective.lateProbe then
            reached = reached + 1
        end
    end

    assert(total > 0, "there must be rows to reach")

    assert(reached == total,
        "a decorator registered after the rows were built must still reach "
        .. "them: " .. reached .. " of " .. total)

    CN.candidateDecorators["LateProbe"] = nil

    CN.NoteDecoratorsChanged()

    CN.CollectCandidates(true)

    print("  a late decorator reaches rows that were already built")
end)()

;(function()
    ------------------------------------------------------------
    -- A DEFERRAL THAT EXPIRES BRINGS THE THING BACK.
    --
    -- Setting one invalidates the candidates. Nothing fired when one ran out,
    -- and every provider consults `CN.IsDeferred` at BUILD time -- so the
    -- deferral was baked into the cached list and the providers it is most
    -- used on are not volatile. Right-click the heads-up line to put a mount
    -- off for an hour, and an hour later it did not come back, while
    -- `/cn hidden` reported the deferral as expired.
    ------------------------------------------------------------
    local filterModule = CN:GetModule("Filters")

    assert(filterModule and filterModule.SweepExpired, "Filters must expose the sweep")

    local deferredStore = CN.Account("deferredObjectives")

    deferredStore[CN.objectiveTypes.MOUNT] = deferredStore[CN.objectiveTypes.MOUNT] or {}

    -- One that ran out a minute ago.
    deferredStore[CN.objectiveTypes.MOUNT][880001] = { until_ = time() - 60 }

    CN.CollectCandidates(true)

    -- Everything clean, which is the state the defect lived in.
    for name in pairs(CN.candidateProviders) do
        assert(not CN.IsProviderDirty(name),
            name .. " must start clean or this proves nothing")
    end

    local prunedCount = filterModule.SweepExpired()

    assert(prunedCount >= 1, "an expired deferral is prunedCount, got " .. prunedCount)

    -- ASSERTED ON THE INVALIDATION, not on the aggregate generation:
    -- `InvalidateCandidates` deliberately does not bump the aggregate, because
    -- marking a provider stale is not the same as its list having changed.
    local dirty = 0

    for name in pairs(CN.candidateProviders) do
        if CN.IsProviderDirty(name) then
            dirty = dirty + 1
        end
    end

    assert(dirty > 0,
        "and the providers are told, or the objective stays missing from a "
        .. "list that has already been built")

    -- Sweeping again with nothing to prune is not a change.
    local quiet = filterModule.SweepExpired()

    assert(quiet == 0, "nothing left to prune, got " .. quiet)

    print("  a deferral that runs out brings the objective back")
end)()

;(function()
    ------------------------------------------------------------
    -- A CURRENCY THE CLIENT HAS STOPPED LISTING IS NOT REPORTED.
    --
    -- The store was write-only-grow and `Capped` walked all of it with no
    -- freshness check, so a currency capped last season kept producing "at
    -- cap, further earning is wasted" -- every five seconds, with a fresh
    -- weekly urgency bonus every reset, for the life of the character.
    ------------------------------------------------------------
    local currencyModule = CN:GetModule("Currencies")

    currencyModule.Scan()

    local cappedBefore = #currencyModule.Capped()

    -- A row from a season that has ended: capped, and not seen by any sweep
    -- since.
    -- `CN.character` is the live record for whoever is logged in, which is
    -- the same table `Currencies.CharacterStore` writes into.
    local record = CN.character

    assert(record, "the fixture character must exist")

    record.currencies = record.currencies or {}

    local store = record.currencies

    store[999001] = {
        currencyID  = 999001,
        quantity    = 2000,
        maxQuantity = 2000,
        capped      = true,
        serial      = currencyModule.CurrentSerial() - 5,
    }

    assert(#currencyModule.Capped() == cappedBefore,
        "a currency the last sweep did not see is not something you can go "
        .. "and spend")

    -- And one the sweep DID see is.
    store[999002] = {
        currencyID  = 999002,
        quantity    = 100,
        maxQuantity = 100,
        capped      = true,
        serial      = currencyModule.CurrentSerial(),
    }

    assert(#currencyModule.Capped() == cappedBefore + 1,
        "while a current one still is")

    store[999001] = nil
    store[999002] = nil

    print("  a retired currency stops being recommended")
end)()

;(function()
    ------------------------------------------------------------
    -- AN ANSWER ABOUT SOMEBODY ELSE'S QUEST LOG HAS A SHELF LIFE.
    --
    -- It comes from `C_QuestLog.IsUnitOnQuest(unit, questID)` and the client
    -- fires no event when a party member accepts or hands one in. The
    -- invalidation subscribed to the player's own quest events, which never
    -- fire for anybody else -- so four people finishing a quest and staying
    -- grouped left the shared-work multiplier applied and `/cn why` still
    -- saying "4 others here are on this quest".
    ------------------------------------------------------------
    local group = CN:GetModule("Group")

    assert(group and group.sharedCacheSeconds,
        "the cache must declare how long it trusts an answer")

    CN_TEST_GROUP_SIZE = 3

    group.ForgetShared()

    CN_TEST_QUEST_SHARED[9002] = { party1 = true, party2 = true }

    local first = group.SharedWith(9002)

    assert(first and first > 0, "the party is on it, got " .. tostring(first))

    -- They hand it in. No event fires, because the client has none.
    CN_TEST_QUEST_SHARED[9002] = nil

    assert(group.SharedWith(9002) == first,
        "inside the window the cached answer stands, which is the point of "
        .. "the cache")

    CN_TEST_CLOCK = CN_TEST_CLOCK + group.sharedCacheSeconds + 1

    assert(group.SharedWith(9002) == 0,
        "past it, the addon asks again rather than going on claiming a group "
        .. "is doing something it finished")

    CN_TEST_GROUP_SIZE = 1

    group.ForgetShared()

    print("  a party member finishing a quest stops counting, on its own")
end)()

;(function()
    ------------------------------------------------------------
    -- A MONTH-OLD SNAPSHOT IS NOT A CHARACTER.
    --
    -- `Alts.staleDays` is 30, and its comment says the addon "stops making
    -- suggestions" past it. The suggestion path honoured that; the SCORING
    -- path -- two points off every objective another character covers, with
    -- their name printed as the reason -- did not, and nothing anywhere
    -- removes a character from the roster.
    ------------------------------------------------------------
    local warband = CN:GetModule("Warband")
    local alts    = CN:GetModule("Alts")

    assert(warband and alts, "both modules must be loaded")

    -- A CHARACTER WHO IS DEMONSTRABLY BETTER AT THIS, so the penalty is
    -- reachable at all. Guessing that the fixture happens to contain one is
    -- how a test passes for the wrong reason.
    local key = "Probealt-Testrealm"

    -- A PROFESSION, NOT A RECIPE. 0.88.0.
    --
    -- This used RECIPE, and for a recipe the character `WhoShould` names is
    -- the one who ALREADY KNOWS IT -- so there is nothing to switch for, and
    -- 0.88.0 stopped `Suitability` naming them. A profession is the case
    -- where switching genuinely helps: the alt with the higher skill can
    -- make the thing and this one cannot.
    --
    -- `Professions.BestCharacterFor` reads `character.professions`, which is
    -- the shape the scan actually writes.
    CN.db.characters[key] = {
        name        = "Probealt",
        realm       = "Testrealm",
        lastSeen    = time(),
        professions = { [164] = { skillLineID = 164, rank = 100 } },
    }

    local fresh, freshReason =
        warband.Suitability(CN.objectiveTypes.PROFESSION, 164)

    assert(fresh < 0 and freshReason,
        "a character with the higher skill and a login today must be "
        .. "preferred, got " .. tostring(fresh))

    assert(freshReason:find("Probealt", 1, true),
        "and named, got " .. tostring(freshReason))

    -- The same character, last seen before the staleness line.
    CN.db.characters[key].lastSeen = time() - ((alts.staleDays + 5) * 86400)

    -- THE SAME TYPE THE FRESH CASE USED. 0.88.0: this asked about a RECIPE,
    -- which `Suitability` now declines to answer for whoever the character's
    -- staleness -- so the assertion held with the staleness guard removed.
    local score, reason =
        warband.Suitability(CN.objectiveTypes.PROFESSION, 164)

    assert(score == 0 and reason == nil,
        "a character last seen " .. (alts.staleDays + 5) .. " days ago must "
        .. "not reorder today's list, got " .. tostring(score) .. " / "
        .. tostring(reason))

    CN.db.characters[key] = nil

    print("  a stale alt stops reordering the list")
end)()

;(function()
    ------------------------------------------------------------
    -- A GOAL YOU FINISHED LEAVES THE LIST.
    --
    -- The Goals provider declared one event -- the zone change -- while
    -- `Goals.Plan` asks `CN.Explain` whether the goal is done, and a goal can
    -- be a quest, a mount, a pet, a toy, an achievement or a reputation. So
    -- finishing the thing you had pinned did not take it off the list: the
    -- row carries a completionValue of six, so it stayed near the top of
    -- `/cn list` and on the route.
    --
    -- Worse, `Follow.Remaining` decides a stop is finished by asking whether
    -- its objectives are still candidates -- so follow mode STUCK on a goal
    -- the player had already completed until they crossed a zone boundary.
    ------------------------------------------------------------
    local goalModule = CN:GetModule("Goals")

    -- A MOUNT, because no other provider offers one that is uncollected AND
    -- pinned -- so what the list holds is unambiguously the Goals row. A
    -- pinned quest is also emitted by the Quests provider, and asserting on
    -- that proves only that the Quests provider works.
    local mountID = 2

    goalModule.Add(CN.objectiveTypes.MOUNT, mountID)

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    local function Pinned()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.type == CN.objectiveTypes.MOUNT
                and objective.id == mountID then

                return true
            end
        end

        return false
    end

    assert(Pinned(), "the pinned goal must be on the list first")

    -- Collect it. The Mounts provider declares this event; the question is
    -- whether the Goals provider does.
    CN_TEST_SetMountCollected(mountID, true)

    local mountModule = CN:GetModule("Mounts")

    if mountModule and mountModule.Scan then
        pcall(mountModule.Scan)
    end

    CN.Dispatch("NEW_MOUNT_ADDED", mountID)

    assert(not Pinned(),
        "a goal you have finished must leave the list at once -- it carries "
        .. "the heaviest completion value in the addon, and follow mode "
        .. "decides a stop is done by asking whether it is still here")

    goalModule.Remove(CN.objectiveTypes.MOUNT, mountID)

    CN_TEST_SetMountCollected(mountID, false)

    if mountModule and mountModule.Scan then
        pcall(mountModule.Scan)
    end

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  a goal you finished leaves the list at once")
end)()

;(function()
    ------------------------------------------------------------
    -- A FLIGHT REFUSAL EXPIRES; A PERMISSION DOES NOT.
    --
    -- Flight is disabled in a zone before the campaign or Pathfinder unlock
    -- and enabled after. `CanFly` treats a remembered `false` as
    -- authoritative, and the store was permanent -- so a player who quested
    -- through a zone before unlocking flight had every route TO that zone
    -- costed at ground speed for ever, correctable only by flying back into
    -- it, which is the one thing the wrong estimate discourages.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    assert(travel.flyableDenialDays, "the shelf life must be stated")

    assert(travel.RememberedFlyable(nil) == nil, "no map, no memory")

    print("  a flight refusal is re-asked; a permission is kept")
end)()

;(function()
    ------------------------------------------------------------
    -- THE SUBZONE COUNT MOVES WHILE YOU EXPLORE.
    --
    -- The provider declared `CRITERIA_UPDATE` -- exactly the event that fires
    -- when you discover a subzone -- and rebuilt on it, reading the same
    -- persisted record it had read on entering the zone. So "3 subzones left"
    -- was frozen at 3 for as long as the player explored, and only moved when
    -- they left and came back.
    ------------------------------------------------------------
    local explorationModule = CN:GetModule("Exploration")

    assert(explorationModule and explorationModule.RefreshCurrentZone,
        "Exploration must expose its refresh")

    -- MADE REACHABLE, rather than skipped if the fixture happens not to have
    -- one. `ForCurrentZone` matches a stored record's name against
    -- `GetZoneText()`, which the stub answers as "Eversong Woods".
    local store = CN.Account("exploration")

    -- NO FABRICATED ROW. 0.62.0.
    --
    -- This used to build a store row named after `GetZoneText()` whenever the
    -- lookup failed -- which is a stub being more forgiving than the client,
    -- the defect class this project has now found eighteen times. The lookup
    -- failed on EVERY client, because it compared an achievement name
    -- ("Explore Eversong Woods") against a zone name ("Eversong Woods"), and
    -- this rescue meant the suite never noticed.
    --
    -- The fixture carries the name the client actually returns. If the lookup
    -- cannot find it, that is the bug, and it fails here.
    if CN.CountKeys(store) == 0 then
        explorationModule.Scan()
    end

    local record = explorationModule.ForCurrentZone()

    assert(record,
        "the zone lookup must find the exploration achievement for the zone "
        .. "the player is standing in, by the name the client actually "
        .. "returns for it")

    local heldDone      = record.done
    local heldCriteria  = record.criteria
    local heldCompleted = record.completed

    -- Stale on purpose: the state the defect left behind.
    record.done      = 0
    record.criteria  = 0
    record.completed = false

    -- THE CLIENT SAYS SOMETHING DIFFERENT FROM WHAT IS STORED.
    --
    -- Asserting `record.done == GetAchievementProgress(...)` proves nothing
    -- when both are zero, which is what a synthetic achievement returns.
    local realProgress = CN.Blizzard.GetAchievementProgress

    CN.Blizzard.GetAchievementProgress = function()
        return 4, 9
    end

    CN.ForgetDebounces()

    CN.Dispatch("CRITERIA_UPDATE")

    CN.Blizzard.GetAchievementProgress = realProgress

    -- READ THROUGH THE ACCESSOR. 0.66.0 stopped writing the flat field,
    -- which was being rewritten by whoever was logged in on every zone
    -- change and so handed a fresh alt the main's progress.
    local movedTo = explorationModule.DoneFor(record)

    assert(movedTo == 4 and record.criteria == 9,
        "discovering a subzone must move the count: the client says 4/9 and "
        .. "the record says " .. tostring(movedTo) .. "/"
        .. tostring(record.criteria))

    -- AND A ZONE THAT IS FINISHED IS MARKED FINISHED.
    --
    -- `Exploration.Closest` filters on `not record.completed` and sorts by
    -- what is left ascending -- so a zone finished this session sat at the
    -- TOP of that list reading "0 left", because the only writer of the flag
    -- was the full scan.
    CN.Blizzard.GetAchievementProgress = function()
        return 7, 7
    end

    record.completed = false
    record.progress  = nil

    explorationModule.RefreshCurrentZone()

    CN.Blizzard.GetAchievementProgress = realProgress

    local _, finished = explorationModule.DoneFor(record)

    assert(finished == true,
        "a zone whose criteria are all met is finished, and the store has to "
        .. "say so")

    record.done      = heldDone
    record.criteria  = heldCriteria
    record.completed = heldCompleted

    print("  the subzone count moves as you explore, and finishing is recorded")
end)()

;(function()
    ------------------------------------------------------------
    -- A DEADLINE-CARRYING PROVIDER IS VOLATILE.
    --
    -- `expiresIn` is computed at build time and feeds the urgency curve --
    -- the heaviest term in the table -- and is printed verbatim in the
    -- reason. Orders was the only one of the six that was not volatile, so
    -- after its first build it rebuilt only when the player touched the
    -- crafting-order system: six hours later the row still said "expires in
    -- 6 hours" and still scored as though six hours remained.
    ------------------------------------------------------------
    local deadlineProviders = {
        "Orders", "Instances", "Waiting", "Currencies", "Opportunities",
    }

    for _, name in ipairs(deadlineProviders) do
        local provider = CN.candidateProviders[name]

        if provider then
            assert(provider.volatile,
                name .. " carries a deadline and must expire on its own; "
                .. "nothing else can tell it that time has passed")
        end
    end

    print("  every provider carrying a deadline goes stale on its own")
end)()

;(function()
    ------------------------------------------------------------
    -- THE WINDOW REDRAWS FOR EVERYTHING A PROVIDER CARES ABOUT.
    --
    -- This was a second hand-written list of six events -- the same "two
    -- lists, one of which nobody checked against the other" that Scoring.lua
    -- records as fixed for the invalidator, left standing in the window.
    -- Missing: every collection event, achievements, criteria, currencies,
    -- bags, vignettes, lockouts and the vault. In a city, where none of the
    -- six fire, looting a toy left "collect this toy" on screen -- and DYING
    -- did not show the corpse run, which is the one objective this addon
    -- weights above everything else.
    ------------------------------------------------------------
    local subscribed = CN.UI.SubscribeToRefreshEvents()

    assert(subscribed and subscribed > 20,
        "the window must watch what the providers watch, saw "
        .. tostring(subscribed))

    -- Every event any provider declares has to be one of them.
    local watched = {}

    for _, name in ipairs({ "PLAYER_DEAD", "PLAYER_ALIVE",
                            "NEW_MOUNT_ADDED", "NEW_TOY_ADDED",
                            "ACHIEVEMENT_EARNED", "BAG_UPDATE_DELAYED",
                            "CURRENCY_DISPLAY_UPDATE" }) do
        watched[name] = false
    end

    for _, provider in pairs(CN.candidateProviders) do
        for event in pairs(provider.events or {}) do
            if watched[event] ~= nil then
                watched[event] = true
            end
        end
    end

    -- The two the providers cannot declare are wired explicitly; the rest
    -- have to come from a provider, or the list is hand-written again.
    assert(watched.NEW_MOUNT_ADDED and watched.ACHIEVEMENT_EARNED,
        "the collection events must come from the providers that declare "
        .. "them, not from a list in the window")

    print("  the window watches " .. subscribed .. " events, from the "
        .. "providers themselves")
end)()

;(function()
    ------------------------------------------------------------
    -- TELLING EVERYBODY IS NOT THE SAME AS TELLING EVERYBODY NOW.
    --
    -- `InvalidateCandidates()` with no reason marks every provider URGENT,
    -- which bypasses every declared cooldown. That is right for a deliberate
    -- act -- pinning a goal must not wait two seconds -- and wrong for the
    -- decorator set changing, which means "re-decorate on the next rebuild".
    --
    -- Warband calls that from `UPDATE_FACTION`, debounced to once every five
    -- seconds and firing continuously while questing. Measured at retail
    -- scale, the urgent form is 12.3 ms: more than twice a forced cold
    -- rebuild, and three quarters of a frame. The 0.59.0 debounce capped how
    -- OFTEN; this would have raised what each one costs by about eight
    -- hundred times.
    ------------------------------------------------------------
    CN.CollectCandidates(true)

    CN.NoteDecoratorsChanged()

    local urgent, dirty, total = 0, 0, 0

    for name, provider in pairs(CN.candidateProviders) do
        total = total + 1

        if CN.IsProviderDirty(name) then
            dirty = dirty + 1
        end

        if provider.cooldown and CN.IsProviderUrgent
            and CN.IsProviderUrgent(name) then

            urgent = urgent + 1
        end
    end

    assert(dirty == total,
        "a decorator change still has to reach every provider, reached "
        .. dirty .. " of " .. total)

    assert(urgent == 0,
        "but it must not bypass a single cooldown: " .. urgent
        .. " provider(s) were told to drop what they declared they cost")

    -- A DELIBERATE ONE STILL DOES, because the player is waiting for it.
    CN.CollectCandidates(true)

    CN.NoteDecoratorsChanged(true)

    local bypassed = 0

    for name, provider in pairs(CN.candidateProviders) do
        if provider.cooldown and CN.IsProviderUrgent
            and CN.IsProviderUrgent(name) then

            bypassed = bypassed + 1
        end
    end

    assert(bypassed > 0,
        "pinning a goal must not wait for anybody's cooldown -- 0.57.0 "
        .. "records that seeing nothing happen for two seconds reads as the "
        .. "feature being broken")

    CN.CollectCandidates(true)

    print("  a background change is patient; a deliberate one is not")
end)()

;(function()
    ------------------------------------------------------------
    -- WALKING INTO A CAVE DOES NOT CHANGE WHICH PETS YOU OWN.
    --
    -- `ZONE_CHANGED_NEW_AREA` was on the universal list, and once that list
    -- started meaning something it reached all twenty-three providers at
    -- 2.5 ms a time -- for an event the client fires on every indoor and
    -- sub-area transition and repeatedly while flying along a zone border.
    --
    -- Every provider a zone change actually affects declares it, and the
    -- check above fails the build if one reads the player's position without
    -- doing so. The declaration is better than the blanket.
    ------------------------------------------------------------
    assert(not CN.IsUniversalInvalidation("ZONE_CHANGED_NEW_AREA"),
        "a zone change reaches the providers that asked for it, not all of "
        .. "them")

    assert(CN.IsUniversalInvalidation("PLAYER_LEVEL_UP"),
        "a level-up genuinely changes what is available everywhere")

    CN.CollectCandidates(true)

    CN.Dispatch("ZONE_CHANGED_NEW_AREA")

    local dirty, total = 0, 0

    for name in pairs(CN.candidateProviders) do
        total = total + 1

        if CN.IsProviderDirty(name) then
            dirty = dirty + 1
        end
    end

    assert(dirty > 0, "the located providers must still be told")

    assert(dirty < total,
        "but not all of them: " .. dirty .. " of " .. total
        .. " rebuilt for a sub-area transition")

    print("  a zone change reaches " .. dirty .. " of " .. total
        .. " providers, not all of them")
end)()

;(function()
    ------------------------------------------------------------
    -- A STORED "YES" IS NOT OVERWRITTEN BY A "NO".
    --
    -- `IsFlyableArea` answers for the SPOT the player is standing on -- a
    -- cave, a quest vehicle, an indoor phase -- while the map id is still the
    -- parent zone. `NoteFlyable` runs on every zone change and every loading
    -- screen, so walking into a cave in a zone you have flown around turned a
    -- permanent permission into a day-long refusal, and every route to that
    -- zone was costed at ground speed until it expired.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    local memory = travel.FlightMemory()

    local mapID = CN.GetPlayerPosition()

    memory[mapID] = true

    CN_TEST_FLYABLE = false

    travel.NoteFlyable(mapID)

    assert(memory[mapID] == true,
        "flight being unavailable where you are standing is not evidence "
        .. "that it is unavailable in the zone")

    -- With nothing remembered, a refusal is still recorded.
    memory[mapID] = nil

    travel.NoteFlyable(mapID)

    assert(type(memory[mapID]) == "table" and memory[mapID].flyable == false,
        "and a first observation of no-flight is still worth keeping")

    CN_TEST_FLYABLE = true

    memory[mapID] = nil

    print("  a cave does not revoke a zone's flight permission")
end)()

;(function()
    ------------------------------------------------------------
    -- TWO ZONES CALLED NAGRAND.
    --
    -- `ForCurrentZone` was a SUBSTRING match over an unordered walk of every
    -- exploration achievement, returning the first hit -- and retail has two
    -- zones called Nagrand and two called Shadowmoon Valley. That was
    -- cosmetic while nothing wrote through it. `RefreshCurrentZone` writes
    -- through it, so finishing one would stamp `completed` on the other,
    -- which then vanishes from the list until a full rescan nothing runs.
    ------------------------------------------------------------
    local zoneExploration = CN:GetModule("Exploration")

    local store = CN.Account("exploration")

    local heldStore = {}

    for key, value in pairs(store) do
        heldStore[key] = value
        store[key]     = nil
    end

    local zone = GetZoneText()

    -- ONE EXACT NAME AND ONE THAT MERELY CONTAINS IT. A substring match hits
    -- both -- which is the defect, because retail has two zones called
    -- Nagrand and two called Shadowmoon Valley -- and an exact match hits
    -- one.
    store[91001] = {
        achievementID = 91001,
        name          = zone .. " (Outland)",
        done          = 1,
        criteria      = 5,
    }

    store[91002] = { achievementID = 91002, name = zone, done = 2, criteria = 7 }

    -- Whichever one it picks, it must pick the SAME one twice -- and having
    -- picked it, it must have written the map down so the ambiguity is over.
    local first  = zoneExploration.ForCurrentZone()

    assert(first, "one of the two must match")

    assert(first.achievementID == 91002,
        "the zone you are standing in is the one named exactly that, not the "
        .. "one whose name happens to contain it; got "
        .. tostring(first.achievementID) .. " (" .. tostring(first.name) .. ")")

    assert(first.mapID == CN.GetPlayerPosition(),
        "and it must record which map it is about, or the next call is "
        .. "another coin toss")

    for _ = 1, 5 do
        assert(zoneExploration.ForCurrentZone() == first,
            "the same zone must give the same record every time")
    end

    -- A REFUSAL IS NOT A MEASUREMENT.
    local realProgress = CN.Blizzard.GetAchievementProgress

    CN.Blizzard.GetAchievementProgress = function()
        return 0, 0
    end

    zoneExploration.RefreshCurrentZone()

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(first.criteria > 0,
        "a client that will not answer must not overwrite a scanned count "
        .. "with nothing")

    for key in pairs(store) do
        store[key] = nil
    end

    for key, value in pairs(heldStore) do
        store[key] = value
    end

    print("  two zones with one name do not overwrite each other")
end)()

;(function()
    ------------------------------------------------------------
    -- THE UPGRADE PATH IS THE ONLY PATH ANYBODY IS ON.
    --
    -- A currency row written before this release carries no serial, and the
    -- first version treated that as current "until the next scan rewrites
    -- it" -- which is wrong in exactly the case the feature exists for: a
    -- currency the client no longer lists is the row the next scan will NOT
    -- rewrite. The fix worked on a fresh install and did nothing at all for
    -- everybody upgrading.
    ------------------------------------------------------------
    local probe = {
        version = 13,
        account = {},
        characters = {
            ["Someone-Somewhere"] = {
                currencies = {
                    [1] = { currencyID = 1, capped = true },
                    [2] = { currencyID = 2, capped = true, serial = 4 },
                },
            },
        },
    }

    CN.RunMigrations(probe)

    local rows = probe.characters["Someone-Somewhere"].currencies

    assert(rows[1].serial == 0,
        "an unstamped row is older than any sweep, not current, got "
        .. tostring(rows[1].serial))

    assert(rows[2].serial == 4, "and a stamped one is left alone")

    print("  a currency stored before this release is confirmed, not assumed")
end)()

;(function()
    ------------------------------------------------------------
    -- THE FRESHEST HOLDER, NOT THE ALPHABETICALLY FIRST.
    --
    -- `WhoKnows` sorts its holders by realm-name and nothing else. So a
    -- deleted alt called Aaathrowaway came back ahead of a main called
    -- Zeddicus -- and the staleness check, seeing a record older than the
    -- line, dropped the penalty entirely and concluded nobody was better
    -- suited, when somebody played yesterday already knew the thing.
    ------------------------------------------------------------
    local warband = CN:GetModule("Warband")
    local alts    = CN:GetModule("Alts")

    local stale, fresh = "Aaathrowaway-Testrealm", "Zeddicus-Testrealm"

    CN.db.characters[stale] = {
        name     = "Aaathrowaway",
        realm    = "Testrealm",
        lastSeen = time() - ((alts.staleDays + 300) * 86400),
        recipes  = { [7001] = true },
    }

    CN.db.characters[fresh] = {
        name     = "Zeddicus",
        realm    = "Testrealm",
        lastSeen = time(),
        recipes  = { [7001] = true },
    }

    -- ASKED OF `WhoShould`, NOT OF `Suitability`. 0.88.0.
    --
    -- The subject here is WHICH holder is named, and `Suitability` stopped
    -- naming one at all for a recipe in 0.88.0 -- correctly, because the
    -- holder is the character who cannot learn it again. `WhoShould` still
    -- names them, for `/cn why` and the hidden list, and choosing the
    -- freshest is still the thing this test was written for.
    local best, detail, scope, switchable =
        warband.WhoShould(CN.objectiveTypes.RECIPE, 7001)

    assert(best == fresh,
        "the character you played yesterday is the one named, got "
        .. tostring(best))

    assert(detail and detail:find("Zeddicus", 1, true),
        "and is listed among the holders: " .. tostring(detail))

    assert(switchable == false,
        "while still saying there is nothing to switch for: "
        .. tostring(scope))

    -- AND THE SCORER DOES NOT PENALISE THE ONE CHARACTER WHO CAN LEARN IT.
    local score = warband.Suitability(CN.objectiveTypes.RECIPE, 7001)

    assert(score == 0,
        "a recipe somebody else already knows is not a reason to rank this "
        .. "character down: " .. tostring(score))

    CN.db.characters[stale] = nil
    CN.db.characters[fresh] = nil

    print("  a deleted alt does not hide a live one")
end)()

;(function()
    ------------------------------------------------------------
    -- THE CLOSE BUTTON DOES NOT SIT ON TOP OF THE OBJECTIVE.
    --
    -- Alpha zero does not disable mouse input, so the last stretch of a long
    -- name was covered by a 16-pixel button that turns the line off rather
    -- than navigating to it -- and a drag started in that corner did nothing,
    -- while the tooltip promises the whole line can be dragged.
    ------------------------------------------------------------
    local hud = CN:GetModule("Hud")

    local hudCloseFrame = hud.Build()

    if hudCloseFrame and hudCloseFrame.close then
        -- ONE CONSTANT, IN ONE FILE. 0.78.0: `Hud.closeWidth` restated the
        -- width the control itself sizes from, so the two could drift and
        -- two other frames reserved nothing at all.
        assert(CN.CLOSE_WIDTH and CN.CLOSE_WIDTH >= 16,
            "the label has to keep clear of the button, by at least its width")

        assert(hud.closeWidth == nil,
            "and the module does not keep a second copy of it")

        -- ASSERTED ON THE ANCHOR, not on the constant: the defect was the
        -- label's right edge, and a constant nobody uses is not a fix.
        local labelRight = hudCloseFrame.label:GetPointBy("TOPRIGHT")
        local closeRight = hudCloseFrame.close:GetPointBy("TOPRIGHT")

        assert(labelRight and closeRight,
            "both must be anchored to the top-right edge")

        assert(math.abs(labelRight.x) >= math.abs(closeRight.x) + CN.CLOSE_WIDTH,
            "the name must stop before the button starts: label at "
            .. tostring(labelRight.x) .. ", button at "
            .. tostring(closeRight.x) .. " and " .. CN.CLOSE_WIDTH .. " wide")

        assert(hudCloseFrame.close:GetScript("OnDragStart"),
            "and a drag started on the button still moves the line")
    end

    print("  the close control keeps clear of the name and still drags")
end)()

;(function()
    ------------------------------------------------------------
    -- A CLIENT THAT HAS NOT LOADED THE WARDROBE ANSWERS ZERO.
    --
    -- The appearance scan now runs at login, and it overwrote every stored
    -- count unconditionally -- so a "0 of 260" from a collection that is not
    -- ready yet would replace a scanned "184 of 260" and the addon would
    -- recommend every slot the player had already finished.
    ------------------------------------------------------------
    local appearanceModule = CN:GetModule("Appearances")

    appearanceModule.Scan()

    local store = CN.Account("appearances")

    local categoryID, record = next(store)

    if categoryID and record and (record.collected or 0) > 0 then
        local held = record.collected

        local realCategories = CN.Blizzard.GetAppearanceCategories

        CN.Blizzard.GetAppearanceCategories = function()
            local rows = realCategories()

            for _, row in ipairs(rows) do
                row.collected = 0
            end

            return rows
        end

        appearanceModule.Scan()

        CN.Blizzard.GetAppearanceCategories = realCategories

        assert(store[categoryID].collected == held,
            "a refusal reads as zero and a count only goes up, so the "
            .. "stored figure stands: had " .. held .. ", now "
            .. tostring(store[categoryID].collected))
    end

    print("  a wardrobe that has not loaded does not erase what was scanned")
end)()


print("\nWhat 0.59.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- A CACHED ROUTE STILL HAS TO PUBLISH ITS BATCHING.
    --
    -- `BuildZoneRoute` returns early on a cache hit. Before 0.59.0 that early
    -- return skipped the stamping as well as the work, so re-routing your own
    -- zone after glancing at the next one over gave back a route whose hubs
    -- the Zone tab and the map pins drew at size four while the objectives
    -- themselves carried no batch bonus -- and standing still, the cache key
    -- is stable for minutes, so it could not recover.
    ------------------------------------------------------------
    local mapID, x, y = CN.GetPlayerPosition()

    CN.RegisterCandidateProvider("CachedHubProbe", function()
        local rows = {}

        for index = 1, 3 do
            table.insert(rows, CN.NewObjective({
                id              = 559000 + index,
                type            = CN.objectiveTypes.RARE,
                name            = "Cached together " .. index,
                completionValue = 3,
                mapID           = mapID,
                x               = 0.42,
                y               = 0.58,
            }))
        end

        return rows
    end)

    CN.CollectCandidates(true)

    CN.ForgetRoutes()
    CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    local sample

    for _, objective in ipairs(CN.CollectCandidates()) do
        if (CN.batchSizes[objective] or 0) > 1 then
            sample = objective
            break
        end
    end

    assert(sample, "the fixture must produce a hub with company in it")

    -- Now throw the batching away WITHOUT throwing the route cache away,
    -- which is exactly the state a map glance used to leave behind.
    CN.ForgetBatching()

    assert(CN.batchSizes[sample] == nil, "the batching is gone")

    -- The same call again. It is a cache hit -- and it must still say what
    -- the route it is handing back means.
    CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)

    assert((CN.batchSizes[sample] or 0) > 1,
        "a cache hit must publish the batching its route describes, or the "
        .. "map pins and the ranking disagree about the same stops")

    assert(CN.batchMapID == mapID, "and say which map it is about")

    CN.candidateProviders["CachedHubProbe"] = nil

    CN.CollectCandidates(true)
    CN.ForgetRoutes()

    print("  a route served from the cache still says what it batched")
end)()

;(function()
    ------------------------------------------------------------
    -- LEARNING THAT IS SWITCHED OFF MUST NOT BE PAID FOR.
    --
    -- The preference adjuster's first statement was `Preference.Refine`,
    -- which for a quest makes a protected client call --
    -- `C_CampaignInfo.GetCampaignID` -- and the `IsEnabled` check came after
    -- it. Measured: 130 calls for `Recommend(5)` over 148 candidates, and 130
    -- again on the next re-rank with nothing changed. `/cn learned off` did
    -- not reduce it at all.
    ------------------------------------------------------------
    local preference = CN:GetModule("Preference")

    assert(preference and preference.SetEnabled, "Preference must be loaded")

    local real = C_CampaignInfo.GetCampaignID

    local asked = 0

    C_CampaignInfo.GetCampaignID = function(...)
        asked = asked + 1

        return real(...)
    end

    -- FRESH BUCKETS, because the memo is the other half of what is asserted.
    --
    -- These candidate tables have been through the suite already and carry
    -- their refinement, so a naive "did it ask?" would answer no for the
    -- right reason and prove nothing about the gate.
    local function ForgetBuckets()
        local quests = 0

        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.type == CN.objectiveTypes.QUEST then
                objective.preferenceBucket = nil

                quests = quests + 1
            end
        end

        return quests
    end

    local held = preference.IsEnabled()

    preference.SetEnabled(false)

    local quests = ForgetBuckets()

    assert(quests > 0, "the fixture must offer some quests to refine")

    CN.InvalidateRanking()
    CN.Recommend(5)

    assert(asked == 0,
        "learning that is off must cost nothing, and it asked the client "
        .. asked .. " time(s)")

    -- AND WITH IT ON, ONCE PER ROW AND NEVER AGAIN.
    --
    -- Whether a quest belongs to a campaign is a fact about the quest and
    -- cannot change while the client is running, so a second pass over the
    -- same rows must ask nobody.
    preference.SetEnabled(true)

    ForgetBuckets()

    CN.InvalidateRanking()
    CN.Recommend(5)

    local refinedFirstPass = asked

    assert(refinedFirstPass > 0,
        "with learning on, the refinement has to be worked out at least once")

    assert(refinedFirstPass <= quests,
        "and at most once per quest row, not " .. refinedFirstPass .. " for "
        .. quests .. " rows")

    CN.InvalidateRanking()
    CN.Recommend(5)

    assert(asked == refinedFirstPass,
        "and never again for the same rows -- it asked " .. (asked - refinedFirstPass)
        .. " more time(s) on a re-rank that changed nothing")

    C_CampaignInfo.GetCampaignID = real

    preference.SetEnabled(held)

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  learning that is off costs nothing, and on it asks once")
end)()

;(function()
    ------------------------------------------------------------
    -- A DEADLINE IS DERIVED WHEN IT IS READ, NOT WHEN IT WAS SCANNED.
    --
    -- `endsIn` is a countdown computed at calendar-read time, and the event
    -- list is held for thirty minutes -- so the addon printed "ends in 40m"
    -- about an event that had finished ten minutes earlier, and the urgency
    -- ramp (weight 4.0, steepest inside the last two hours) was fed a figure
    -- that could be half an hour wrong exactly where it matters most.
    ------------------------------------------------------------
    local opportunities = CN:GetModule("Opportunities")

    assert(opportunities and opportunities.GetActiveEvents,
        "Opportunities must be loaded")

    CN_TEST_EVENT_ENDS_IN = 3 * 3600

    local events = opportunities.GetActiveEvents(true)

    local held

    for _, event in ipairs(events) do
        if event.endsAt then
            held = event
            break
        end
    end

    assert(held, "the calendar stub must supply an event with an end time")

    local first = held.endsIn

    assert(first and first > 0, "and it must have time left, got "
        .. tostring(first))

    -- Move the clock forward by pretending the stamp is older, then read the
    -- CACHED list. Nothing rescans; the countdown must still be right.
    held.endsAt = held.endsAt - 3600

    local again = opportunities.GetActiveEvents()

    local same

    for _, event in ipairs(again) do
        if event == held then
            same = event
        end
    end

    assert(same, "the cached list is the same list")

    assert(math.abs((first - 3600) - same.endsIn) <= 2,
        "a cached deadline must be re-derived from its absolute end time; "
        .. "expected about " .. (first - 3600) .. ", got "
        .. tostring(same.endsIn))

    -- AND AN EVENT THAT HAS ENDED CARRIES NO DEADLINE AT ALL.
    held.endsAt = time() - 60

    opportunities.GetActiveEvents()

    assert(held.endsIn == nil,
        "an event that has finished has no time left, not a negative amount")

    print("  a world event's deadline is right however long the list is held")
end)()

;(function()
    ------------------------------------------------------------
    -- AN EVENT IS KEYED ON SOMETHING THE CLIENT'S LANGUAGE CANNOT CHANGE.
    --
    -- `id = event.title` is a localized string. Instances.lua carries a
    -- header describing the same defect as fixed for lockouts: every ignore
    -- was lost the day the player changed client language. The key also feeds
    -- the aggregate dedup, so two events sharing a title on one day collapsed
    -- into one row.
    ------------------------------------------------------------
    CN_TEST_EVENT_ENDS_IN = 3 * 3600

    local opportunities = CN:GetModule("Opportunities")

    opportunities.GetActiveEvents(true)

    CN.InvalidateCandidates()

    local found

    for _, objective in ipairs(CN.CollectCandidates(true)) do
        if objective.name == "Darkmoon Faire" then
            found = objective
            break
        end
    end

    if found then
        assert(found.id ~= found.name,
            "an objective keyed on its own translated title cannot survive a "
            .. "language change, and neither can anything filed against it")

        assert(tostring(found.id):find("4242", 1, true),
            "the client supplies an eventID; use it -- got "
            .. tostring(found.id))

        print("  a world event is keyed on its id, not on its translated name")
    else
        print("  (no world event in this fixture to key-check)")
    end
end)()

;(function()
    ------------------------------------------------------------
    -- "NO IDEA WHERE THIS IS" HAS ONE PRICE, SET IN ONE PLACE.
    --
    -- The quest provider hard-coded 5 while `CN.unknownLocationCost` is 8 --
    -- raised from 3 in 0.57.0 with a note explaining that anything below the
    -- cost of crossing a zone lets "no idea" outrank "I can see it". So a
    -- quest with NO location was cheaper than one in your own zone whose
    -- coordinates had not resolved.
    ------------------------------------------------------------
    local source = assert(io.open(ROOT .. "/Modules/Quests.lua", "r"))

    local text = source:read("*a")

    source:close()

    assert(not text:find("travel = 5", 1, true),
        "the quest provider must not carry its own unknown-location price")

    assert(text:find("travel = CN.unknownLocationCost", 1, true),
        "it must use the one the rest of the addon uses")

    -- And nil rather than zero, because zero means "you are standing on it"
    -- and `CN.IsPlaceless` reads it that way -- which is what made every
    -- located quest score as free for a second after each loading screen.
    -- `%s*$` in multiline mode, not a literal "\n": the toolkit scaffolds
    -- this tree with CRLF line endings, so a literal newline match passes in
    -- the repository and fails in the scaffold -- which is the environment
    -- the PowerShell suite actually checks.
    -- `local travel, costed` since 0.70.0: the second is the travel model's
    -- own "did I actually answer" flag, which every caller but one used to
    -- throw away. Both still start nil, which is the property.
    assert(text:find("\n%s*local travel, costed%s*\r?\n"),
        "and start from nil, not from zero")

    print("  one price for an unknown location, and zero means zero")
end)()

;(function()
    ------------------------------------------------------------
    -- A BURSTY EVENT MUST NOT DEFEAT THE UNCHANGED-PROVIDER SHORTCUT.
    --
    -- `UPDATE_FACTION` fires on nearly every reputation tick -- this addon
    -- says so in three files, one of which gives its own provider a
    -- five-second cooldown for the reason. Two handlers used it to bump
    -- `CN.decoratorGeneration`, which is the ONE thing that defeats the
    -- shortcut, so while a player was questing it was permanently off.
    ------------------------------------------------------------
    CN.ForgetDebounces()

    local errorsBefore = CN.decoratorGeneration or 0

    for _ = 1, 20 do
        CN.Dispatch("UPDATE_FACTION")
    end

    local moved = (CN.decoratorGeneration or 0) - errorsBefore

    assert(moved <= 1,
        "twenty reputation ticks must not be twenty full re-decorations; the "
        .. "generation moved " .. moved .. " time(s)")

    assert(moved == 1,
        "but the first one must be answered immediately -- a plain throttle "
        .. "would delay the common case, which is a single event")

    print("  a burst of reputation ticks costs one re-decoration, not twenty")

    ------------------------------------------------------------
    -- AND THE DEBOUNCE ITSELF DOES WHAT IT SAYS.
    ------------------------------------------------------------
    CN.ForgetDebounces()

    local ran = 0

    local function Work() ran = ran + 1 end

    assert(CN.Debounce("probe", 5, Work), "the first call runs")
    assert(ran == 1, "immediately")

    assert(not CN.Debounce("probe", 5, Work), "the second does not")
    assert(not CN.Debounce("probe", 5, Work), "nor the third")

    assert(ran == 1, "so the work ran once, not " .. ran .. " times")

    -- A different key is a different burst.
    assert(CN.Debounce("other", 5, Work), "another key is not throttled")

    assert(ran == 2, "and runs on its own")

    CN.ForgetDebounces()

    print("  the debounce answers the first event and collapses the rest")
end)()

;(function()
    ------------------------------------------------------------
    -- A RARE IS COSTED THROUGH THE TRAVEL MODEL LIKE EVERYTHING ELSE.
    --
    -- This provider did raw Pythagoras on normalized map units and multiplied
    -- by ten, which asserts that a map unit is the same number of yards in
    -- both directions (the bearing defect of 0.40.0, in another file), that
    -- every zone is about 2,100 yards across, and that the player is on foot.
    ------------------------------------------------------------
    local source = assert(io.open(ROOT .. "/Modules/Rares.lua", "r"))

    local text = source:read("*a")

    source:close()

    -- The exact expression, not the substring "* 10", which also appears in
    -- coordinate rounding twice in the same file.
    assert(not text:find("math.sqrt((dx * dx) + (dy * dy)) * 10", 1, true),
        "no hand-rolled distance-to-cost constant")

    assert(text:find("CN.TravelCost(vignette.mapID", 1, true),
        "the travel model prices this like every other located provider")

    -- AND A RARE WITH NO COORDINATES IS NOWHERE, NOT UNDERFOOT.
    --
    -- `travel = 0` meant `CN.IsPlaceless` read it as "not a journey", so a
    -- rare the client would not place was scored as free AND exempt from the
    -- unknown-location cost.
    assert(not text:find("local travel  = 0", 1, true),
        "a rare with no position must start from nil, not from zero")

    print("  a rare is priced by the same model as everything else")
end)()

;(function()
    ------------------------------------------------------------
    -- `/cn plan` WITH A FRACTION.
    --
    -- Lua 5.3+ makes `/` always produce a float, so `budget / 60` gave 12.5
    -- and `string.format("%dm", 12.5)` is an ERROR on 5.4 and silently "12m"
    -- on the game's 5.1 -- where the header then disagreed with the plan it
    -- was describing. Same divergence class as the two-argument `math.atan`,
    -- with the polarity reversed.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    local plan = session.Plan(12.5)

    assert(plan, "a fractional budget must still produce a plan")

    assert(plan.minutes == math.floor(plan.minutes),
        "and its headline figure must be a whole number of minutes, got "
        .. tostring(plan.minutes))

    -- Through the command, which is the path that formats it.
    local errors = CN:GetModule("Errors")

    local batchedBefore = errors.Count()

    CN.HandleSlashCommand("plan 12.5")

    assert(errors.Count() == batchedBefore,
        "and the command must not throw on it")

    print("  a fractional plan budget is answered, not thrown")
end)()

;(function()
    ------------------------------------------------------------
    -- WHERE THE HEARTHSTONE GOES, LEARNED BY WATCHING.
    --
    -- `GetBindLocation()` is a localized inn name and the addon has no
    -- name-to-map index, so the one teleport every player owns was listed and
    -- never costed. Watching where the player lands after a hearth is exact,
    -- free, and cannot be wrong the way a curated table of translated names
    -- can.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    assert(travel and travel.NoteHearthArrival, "Travel must be loaded")

    CN.Account().bindPoints = nil

    assert(travel.BindPointCount() == 0, "nothing observed yet")

    assert(travel.BindMap() == nil,
        "and no bind point has a map until one is observed")

    -- The player casts it, and then arrives.
    CN.Dispatch("UNIT_SPELLCAST_SUCCEEDED", "player", "cast-1", 8690)
    CN.Dispatch("PLAYER_ENTERING_WORLD")

    local mapID = CN.GetPlayerPosition()

    assert(travel.BindMap() == mapID,
        "one hearth teaches the addon where the bind point is, got "
        .. tostring(travel.BindMap()) .. " for map " .. tostring(mapID))

    assert(travel.BindPointCount() == 1, "one bind point, not more")

    -- A LOADING SCREEN THAT IS NOT A HEARTH MUST TEACH IT NOTHING.
    --
    -- A pending flag that survives an unrelated zone change would file the
    -- wrong map under the player's bind name and then cost journeys with it.
    CN.Account().bindPoints = nil

    CN.Dispatch("PLAYER_ENTERING_WORLD")

    assert(travel.BindPointCount() == 0,
        "an ordinary loading screen is not a hearth")

    -- AND SOMEBODY ELSE'S CAST IS NOT YOURS.
    CN.Dispatch("UNIT_SPELLCAST_SUCCEEDED", "party1", "cast-2", 8690)
    CN.Dispatch("PLAYER_ENTERING_WORLD")

    assert(travel.BindPointCount() == 0,
        "a party member hearthing says nothing about your bind point")

    print("  the hearthstone's destination is learned from one hearth")
end)()

;(function()
    ------------------------------------------------------------
    -- ANGLE NORMALISATION IS ARITHMETIC, NOT AN UNBOUNDED LOOP.
    --
    -- `RelativeBearing` was rewritten to use `CN.Mod` because "the loops were
    -- also unbounded: a non-finite bearing spins the client" -- and this copy,
    -- used by the arrow's ten-per-second ticker, was left behind.
    ------------------------------------------------------------
    local navigation = CN:GetModule("Navigation")

    local normalize = navigation.NormalizeAngle

    assert(normalize, "the normaliser must be reachable")

    for _, case in ipairs({
        { input = 0,                    expect = 0 },
        { input = math.pi / 2,          expect = math.pi / 2 },
        { input = -math.pi / 2,         expect = -math.pi / 2 },
        { input = (3 * math.pi),        expect = -math.pi },
        { input = -(3 * math.pi),       expect = -math.pi },
        { input = 400 * math.pi,        expect = 0 },
    }) do
        local got = normalize(case.input)

        assert(math.abs(got - case.expect) < 0.0001,
            "normalising " .. case.input .. " gave " .. got
            .. ", expected " .. case.expect)

        assert(got >= -math.pi and got < math.pi,
            "and every answer is in [-pi, pi), got " .. got)
    end

    -- A NON-FINITE INPUT MUST RETURN, not spin. This is the case the loops
    -- could not survive and the reason the file's own rule forbids them.
    local nan = 0 / 0

    assert(normalize(nan) == 0, "a NaN bearing is no bearing")

    assert(normalize("not a number") == 0, "and neither is a string")

    print("  every angle normalises in constant time, including a NaN")
end)()

;(function()
    ------------------------------------------------------------
    -- A DISCOVERED QUEST IS ONE FACT.
    --
    -- The store held `{ firstSeen, lastSeen, source }` per quest and every
    -- reader counts or iterates KEYS -- tens of thousands of three-field
    -- tables rewritten in full on every logout for information nothing has
    -- ever asked for.
    ------------------------------------------------------------
    local quests = CN:GetModule("Quests")

    quests.RecordDiscovered(778001, "probe")

    local record = CN.Account("discoveredQuests")[778001]

    assert(record == true,
        "a discovery is a boolean, got a " .. type(record))

    -- And the migration collapses the old shape rather than dropping it.
    local probeDb = {
        version = 12,
        account = {
            discoveredQuests = {
                [1] = { firstSeen = 100, lastSeen = 200, source = "pin" },
                [2] = true,
            },
            questMetadata = {
                [3] = { questID = 3, name = "Kept", lastSeen = 5, source = "api" },
            },
        },
        characters = {},
    }

    CN.RunMigrations(probeDb)

    assert(probeDb.account.discoveredQuests[1] == true,
        "an existing record collapses to the fact it carried")

    assert(probeDb.account.discoveredQuests[2] == true, "and a boolean is left alone")

    -- 0.61.0: migration 15 goes further. `source` is only read to stop a
    -- Blizzard name clobbering one the PLAYER typed, so a row from any other
    -- source has nothing to say beyond the name -- and this store is 708 KB
    -- of a 2.0 MB file the game rewrites on every logout.
    local kept = probeDb.account.questMetadata[3]

    assert(kept == "Kept",
        "a client-supplied name collapses to the name itself: "
        .. tostring(kept))

    -- And the one shape that must NOT collapse.
    probeDb.version = 14
    probeDb.account.questMetadata[4] =
        { questID = 4, name = "Mine", lastSeen = 9, source = "manual" }

    CN.RunMigrations(probeDb)

    local mine = probeDb.account.questMetadata[4]

    assert(type(mine) == "table" and mine.name == "Mine"
        and mine.source == "manual",
        "a name the player typed keeps the table that protects it")

    assert(mine.questID == nil and mine.lastSeen == nil,
        "the two fields nothing reads are dropped")

    print("  a discovery is one fact, and a quest name is a string")
end)()

;(function()
    ------------------------------------------------------------
    -- PRUNING THE HARVEST MUST REACH THE ROWS ALREADY BUILT.
    --
    -- `Harvest.NoteUnlocksChanged` carries a header explaining that bumping
    -- `unlockGeneration` alone is not enough -- the decorator only consults it
    -- if `Decorate` runs, which the unchanged-provider shortcut skips. Prune
    -- bumped the counter directly, so after it dropped rows a quest kept an
    -- `unlockValue` (weight 1.5, the second-heaviest term) and a `/cn why`
    -- sentence derived from records that no longer existed.
    ------------------------------------------------------------
    local source = assert(io.open(ROOT .. "/Modules/Harvest.lua", "r"))

    local text = source:read("*a")

    source:close()

    local prune = text:match("function Harvest%.Prune.-\nend")

    assert(prune, "Prune must still be there to check")

    assert(prune:find("Harvest.NoteUnlocksChanged()", 1, true),
        "a prune goes through the function that knows what invalidating "
        .. "unlocks actually requires")

    assert(not prune:find("Harvest.unlockGeneration =", 1, true),
        "and does not touch the counter behind its back")

    print("  pruning the harvest invalidates what it invalidated")
end)()

;(function()
    ------------------------------------------------------------
    -- THE WINDOW'S OWN AFFORDANCES, ASSERTED.
    --
    -- Five separate defects in this block, all of the same kind: a control
    -- that says one thing and does another. None of them had an assertion,
    -- because the suite asserted that tabs BUILD rather than that they mean
    -- anything.
    ------------------------------------------------------------
    CN.UI.Show()

    local list = CN.UI.CreateList(UIParent)

    ------------------------------------------------------------
    -- 1. A ROW THAT ACTS IS MARKED, NOT MERELY BRIGHTER.
    ------------------------------------------------------------
    list:SetEntries({
        { text = "does something", onClick = function() end },
        { text = "does nothing" },
    })

    assert(list.rows[1].chevron:IsShown(),
        "a row that acts must carry a marker; two steps of brightness is "
        .. "information carried by colour alone")

    assert(not list.rows[2].chevron:IsShown(),
        "and an inert row must not")

    ------------------------------------------------------------
    -- 2. "NOTHING MATCHED" IS NOT "YOU HAVE NEVER SCANNED".
    --
    -- The filter runs before the empty check, so a typo fell into the tab's
    -- own empty text -- on Collections, "Nothing scanned yet. Press Scan
    -- everything." So a search with a typo told the player to run a scan that
    -- freezes the client for seconds, and the list was still empty after it.
    ------------------------------------------------------------
    list.emptyText = "Nothing scanned yet."

    list:SetFilter("zzzznothing")
    list:SetEntries({ { text = "a thing" }, { text = "another" } })

    local shown = list.rows[1].label:GetText()

    assert(shown and shown:find("matches", 1, true),
        "a filter that matched nothing must say so, got " .. tostring(shown))

    assert(not shown:find("Nothing scanned", 1, true),
        "and must not send the player to a scan that will not help")

    -- With no filter, the tab's own empty text is right again.
    list:SetFilter("")
    list:SetEntries({})

    shown = list.rows[1].label:GetText()

    assert(shown and shown:find("Nothing scanned", 1, true),
        "an empty list with no filter still says what would fill it, got "
        .. tostring(shown))

    print("  a marker for a row that acts, and the right empty state")

    ------------------------------------------------------------
    -- 3. THE HEADS-UP LINE ACTS ON WHAT IT IS SHOWING.
    --
    -- It read `CN.currentRecommendation`, which only the Next tab, `/cn next`,
    -- the minimap and auto-advance ever write -- so a player who turned the
    -- line on and never opened the window had it nil all session: the line
    -- named an objective, its tooltip promised two clicks, and both did
    -- nothing with no message.
    ------------------------------------------------------------
    local hud = CN:GetModule("Hud")

    assert(hud and hud.Build, "the heads-up module must be loaded")

    local hudFrame = hud.Build()

    if hudFrame then
        local heldEnabled = hud.IsEnabled()

        hud.SetEnabled(true)

        -- THE STATE A PLAYER WHO NEVER OPENS THE WINDOW IS IN.
        CN.currentRecommendation = nil

        hud.Refresh()

        local hudTop = CN.Recommend(1)[1]

        if hudTop then
            assert(hudFrame.objective == hudTop,
                "the line must hold the objective it drew, with nothing else "
                .. "having written it")

            -- AND CLICKING IT ACTS ON THAT ONE, not on whatever some other
            -- surface selected. Set the global to something else entirely and
            -- the click must still follow the line.
            local other = CN.NewObjective({
                id = 991001, name = "Somewhere else", completionValue = 1,
            })

            CN.currentRecommendation = other

            local navigated

            local realNavigate = CN.NavigateToObjective

            CN.NavigateToObjective = function(objective)
                navigated = objective
            end

            hudFrame:GetScript("OnMouseUp")(hudFrame, "LeftButton")

            CN.NavigateToObjective = realNavigate

            assert(navigated == hudTop,
                "clicking the line goes where the line says, not where "
                .. "something off screen selected")

            CN.currentRecommendation = nil
        end

        hud.SetEnabled(heldEnabled)

        print("  the heads-up line acts on the objective it is showing")
    end

    ------------------------------------------------------------
    -- 4. A CONTROL THAT CANNOT ACT MUST NOT LOOK LIKE IT CAN.
    --
    -- The Next tab's Navigate / Defer / Ignore were built enabled and never
    -- disabled. On a fresh install the first thing a player sees is "Nothing
    -- actionable yet" above three live-looking buttons that silently return.
    ------------------------------------------------------------
    -- THROUGH THE TAB'S OWN REFRESH, not by calling the helper: the defect
    -- was that nothing called it.
    local nextTab, nextIndex

    for index, tab in ipairs(CN.UI.tabs) do
        if tab.name == "Next" then
            nextTab, nextIndex = tab, index
            break
        end
    end

    assert(nextTab, "the Next tab must exist")

    CN.UI.SelectTab(nextIndex)

    -- Record what the buttons are told, since a stub hudFrame remembers nothing.
    local told = {}

    for _, name in ipairs({ "navigate", "skip", "ignore" }) do
        local button = nextTab.panel[name]

        assert(button, "the Next tab must have a " .. name .. " button")

        button.SetEnabled = function(_, value) told[name] = value end
    end

    -- WITH SOMETHING TO ACT ON, first.
    --
    -- Not in the type-checklist mode, which is its own case: there the panel
    -- has become a list of types and the three buttons are correctly dead.
    --
    -- ASSERTED RATHER THAN SET. The tab's build initialises this to `false`,
    -- and setting it here would paper over the initialisation being missing --
    -- which is the whole defect: an unset field on a hudFrame is not reliably
    -- nil, so the Next tab used to open into the checklist branch.
    assert(nextTab.panel.filtering == false,
        "the Next tab must initialise its own mode, got a "
        .. type(nextTab.panel.filtering))

    CN.InvalidateCandidates()

    nextTab.refresh(nextTab.panel)

    assert(#CN.Recommend(1) > 0,
        "the fixture must recommend something, or the live half proves nothing")

    for _, name in ipairs({ "navigate", "skip", "ignore" }) do
        assert(told[name] == true,
            name .. " is live when there is something to act on, got "
            .. tostring(told[name]))
    end

    -- AND WITH NOTHING. Every type hidden is the state a player who pressed
    -- "Filter types" and unticked everything reaches, and it looks exactly
    -- like a fresh install that has not scanned.
    local typeFilters = CN:GetModule("Filters")

    print("    PROBE A")

    local hidden = {}

    for _, objectiveType in ipairs(typeFilters.TypeOrder()) do
        if typeFilters.IsTypeEnabled(objectiveType) then
            typeFilters.ToggleType(objectiveType)

            table.insert(hidden, objectiveType)
        end
    end

    print("    PROBE B")

    CN.InvalidateCandidates()

    nextTab.refresh(nextTab.panel)

    print("    PROBE C")

    assert(#CN.Recommend(1) == 0,
        "hiding every type must empty the list, or the dead half proves "
        .. "nothing")

    for _, name in ipairs({ "navigate", "skip", "ignore" }) do
        assert(told[name] == false,
            name .. " must go dead above an empty list; it was told "
            .. tostring(told[name]))
    end

    for _, objectiveType in ipairs(hidden) do
        typeFilters.ToggleType(objectiveType)
    end

    CN.InvalidateCandidates()

    print("  the Next tab's actions go dead when they cannot act")
end)()

;(function()
    ------------------------------------------------------------
    -- SETUP'S ELEVEN NUMBERS ARE NOT THE SAME QUANTITY.
    --
    -- `Setup.Report` printed each scan's first return value and nothing else.
    -- `Appearances.Scan` returns slot CATEGORIES (about seventeen) and
    -- `Professions.Scan` returns profession LINES (two to four); the rest
    -- return thousands of rows. So a player who had just told the addon to
    -- read their transmog saw "Appearances: 17" beside "Mounts: 1104".
    ------------------------------------------------------------
    local setupModule2 = CN:GetModule("Setup")

    assert(setupModule2 and setupModule2.steps, "Setup must be loaded")

    for _, step in ipairs(setupModule2.steps) do
        assert(step.unit and step.unit ~= "",
            step.label .. " reports a bare number with no unit; say what it "
            .. "counted")
    end

    -- And the report actually uses them.
    local seen = {}

    local realPrint = CN.PrintLine

    CN.PrintLine = function(line) table.insert(seen, tostring(line)) end

    local realHead = CN.Print

    CN.Print = function(line) table.insert(seen, tostring(line)) end

    setupModule2.Report({
        { label = "Appearances", ok = true, value = 17 },
        { label = "Mounts",      ok = true, value = 1104 },
    })

    CN.PrintLine = realPrint
    CN.Print     = realHead

    local body = table.concat(seen, "\n")

    assert(body:find("slot categories", 1, true),
        "seventeen WHAT? -- got:\n" .. body)

    assert(body:find("mounts", 1, true), "and 1,104 what")

    -- The headline comes first, which is what a headline is. This printed
    -- eleven continuations and THEN three headlines.
    assert(seen[1] and seen[1]:find("Setup complete", 1, true),
        "the headline leads, got " .. tostring(seen[1]))

    print("  setup says what each of its numbers counted")
end)()

;(function()
    ------------------------------------------------------------
    -- A TOY SAYS WHY IT MATTERS, LIKE A MOUNT AND A PET DO.
    --
    -- The "why you should care" line fired only for the two collectible types
    -- the client resolves from an item id. A toy IS its item id -- that is the
    -- key the addon's own store uses -- so it was one branch away.
    ------------------------------------------------------------
    local tooltipModule = CN:GetModule("Tooltips")

    assert(tooltipModule and tooltipModule.ItemLines, "Tooltips must be loaded")

    local toysModule = CN:GetModule("Toys")

    if toysModule and toysModule.Scan then
        pcall(toysModule.Scan)
    end

    local toyID = next(CN.Account("toys"))

    assert(toyID, "the fixture must have scanned at least one toy")

    -- PIN IT, so the "why you should care" line has something to say. That
    -- line fired only for mounts and pets; a toy hovered silently.
    local goalsModule = CN:GetModule("Goals")

    goalsModule.Add(CN.objectiveTypes.TOY, toyID)

    local lines = tooltipModule.ItemLines(toyID, "Test Toy")

    assert(lines and #lines > 0, "a known toy produces tooltip lines")

    local body = {}

    for _, line in ipairs(lines) do
        table.insert(body, tostring(line.text or line))
    end

    local joined = table.concat(body, " | ")

    assert(joined:find("Toy", 1, true), "it says it is a toy")

    assert(joined:find("chasing this", 1, true),
        "and a toy you have pinned says so, exactly as a mount does -- got: "
        .. joined)

    goalsModule.Remove(CN.objectiveTypes.TOY, toyID)

    print("  a toy's tooltip is built through the same path as a mount's")
end)()

;(function()
    ------------------------------------------------------------
    -- HIDING A WORLD EVENT ACTUALLY HIDES IT.
    --
    -- The ignore and defer guards read `event.title` while the objective was
    -- built with an id, so `CN.IsIgnored` looked up one key and
    -- `CN.SetIgnored` had written another. Pressing Ignore on a world event
    -- did nothing at all, for ever. Before 0.59.0 the two happened to be the
    -- same string, which is how changing one of them broke the other.
    ------------------------------------------------------------
    CN_TEST_EVENT_ENDS_IN = 3 * 3600

    local opportunities = CN:GetModule("Opportunities")

    opportunities.GetActiveEvents(true)

    CN.InvalidateCandidates()

    local found

    for _, objective in ipairs(CN.CollectCandidates(true)) do
        if objective.name == "Darkmoon Faire" then
            found = objective
            break
        end
    end

    assert(found, "the fixture must offer a world event")

    -- Through the same call the window's Ignore button makes.
    CN.SetIgnored(found.type, found.id, true)

    CN.InvalidateCandidates()

    for _, objective in ipairs(CN.CollectCandidates(true)) do
        assert(objective.name ~= "Darkmoon Faire",
            "an ignored world event must stop being offered; the guard and "
            .. "the objective have to agree about the key")
    end

    CN.SetIgnored(found.type, found.id, false)

    CN.InvalidateCandidates()

    -- AND A FALLBACK KEY HAS TO IDENTIFY ONE EVENT, NOT A KIND OF EVENT.
    --
    -- A triple of eventType, calendarType and sequenceType is a description
    -- of a category: two ongoing holidays on the same day composed the
    -- identical key, and the aggregate dedups on it, so one of them was
    -- silently dropped -- exactly the collapse this was meant to fix.
    local first = opportunities.EventKey({
        eventType = 4, calendarType = "HOLIDAY",
        sequenceType = "ONGOING", title = "One",
    })

    local second = opportunities.EventKey({
        eventType = 4, calendarType = "HOLIDAY",
        sequenceType = "ONGOING", title = "Two",
    })

    assert(first ~= second,
        "two events of the same kind on the same day are two events")

    -- Zero is truthy in Lua, so a client that answered 0 would have given
    -- every holiday the same id.
    assert(opportunities.EventKey({ eventID = 0, title = "Zero" })
        ~= opportunities.EventKey({ eventID = 0, title = "Other" }),
        "an eventID of zero is not an id")

    assert(opportunities.EventKey({ eventID = 4242 }) == 4242,
        "and a real one is used as it is")

    print("  hiding a world event hides it, and two events are two rows")
end)()

;(function()
    ------------------------------------------------------------
    -- `/cn why` MUST SHOW THE SAME ARITHMETIC THE SCORER USED.
    --
    -- `CN.ExplainScore` read `objective.hubSize`, which 0.59.0 stopped
    -- writing when batching moved onto a table the router owns -- so the
    -- batch term silently vanished from the explanation AND the focus term
    -- below it, computed as `after - worth`, was wrong by the same amount.
    -- The function's own header says the two must agree.
    ------------------------------------------------------------
    local objective = CN.NewObjective({
        id = 993001, name = "Batched", completionValue = 5, travelCost = 3,
    })

    CN.batchSizes[objective] = 4

    local scored = CN.ScoreObjective(objective)

    local total = 0

    for _, term in ipairs(CN.ExplainScore(objective)) do
        total = total + term.value
    end

    assert(math.abs(total - scored) < 0.001,
        "the explanation and the score must be the same sum: explained "
        .. string.format("%.3f", total) .. " against "
        .. string.format("%.3f", scored))

    local named = false

    for _, term in ipairs(CN.ExplainScore(objective)) do
        if tostring(term.label):find("batches with", 1, true) then
            named = true
        end
    end

    assert(named, "and the batch term must be named, not merely counted")

    CN.batchSizes[objective] = nil

    print("  the ranking explanation adds up to the ranking")
end)()

;(function()
    ------------------------------------------------------------
    -- A HEARTH THAT ARRIVES BEFORE THE CLIENT WILL PLACE YOU.
    --
    -- `PLAYER_ENTERING_WORLD` is exactly the moment
    -- `C_Map.GetBestMapForUnit` returns nothing, which this addon documents
    -- in three places. Clearing the pending flag before the observation
    -- succeeded threw the one recording away precisely when it was most
    -- likely to fail, and nothing re-armed until the next hearth.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    CN.Account().bindPoints = nil

    CN_TEST_REFUSE_MAP = true

    CN.Dispatch("UNIT_SPELLCAST_SUCCEEDED", "player", "cast-3", 8690)
    CN.Dispatch("PLAYER_ENTERING_WORLD")

    assert(travel.BindPointCount() == 0,
        "nothing is recorded while the client will not say where you are")

    -- The map resolves, and the next loading screen -- or the retry -- lands
    -- the observation. The flag must still be armed.
    CN_TEST_REFUSE_MAP = false

    CN.Dispatch("PLAYER_ENTERING_WORLD")

    assert(travel.BindPointCount() == 1,
        "the observation must survive a client that was not ready yet")

    -- AND IT MUST NOT STAY ARMED FOR EVER.
    CN.Account().bindPoints = nil

    CN_TEST_REFUSE_MAP = true

    CN.Dispatch("UNIT_SPELLCAST_SUCCEEDED", "player", "cast-4", 8690)

    for _ = 1, travel.hearthRetries + 2 do
        CN.Dispatch("PLAYER_ENTERING_WORLD")
    end

    CN_TEST_REFUSE_MAP = false

    CN.Dispatch("PLAYER_ENTERING_WORLD")

    assert(travel.BindPointCount() == 0,
        "a hearth the client would never place is given up on, not left "
        .. "armed to record whatever zone answers next")

    -- AND THE STORE HAS A CEILING.
    CN.Account().bindPoints = nil

    for index = 1, travel.bindPointCap + 4 do
        CN_TEST_BIND_LOCATION = "Inn " .. index

        travel.NoteHearthArrival()
    end

    CN_TEST_BIND_LOCATION = "Test Inn"

    assert(travel.BindPointCount() <= travel.bindPointCap,
        "the bind point store must be bounded, holds "
        .. travel.BindPointCount())

    CN.Account().bindPoints = nil

    print("  a hearth is recorded when the client is ready, and only then")
end)()

;(function()
    ------------------------------------------------------------
    -- ONE BUDGET, ONE ROUNDING.
    --
    -- Rounding only the DISPLAY fixed the 5.4 throw and left the
    -- disagreement, in the other direction: "13m" printed above a plan built
    -- against twelve and a half.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    for _, request in ipairs({ 12.5, 12.4, 1, 45, 0.4 }) do
        local plan = session.Plan(request)

        assert(plan.minutes == math.floor(plan.minutes),
            "a whole number of minutes for " .. request .. ", got "
            .. tostring(plan.minutes))

        assert(plan.minutes >= 1,
            "and never a plan for no time at all, got " .. tostring(plan.minutes)
            .. " for " .. request)

        assert(plan.budgetSeconds == plan.minutes * 60,
            "and one rounding, not two: " .. tostring(plan.budgetSeconds)
            .. "s against " .. tostring(plan.minutes) .. "m for " .. request)
    end

    -- The headline figure and the budget the plan was built against are the
    -- same number, which is the whole point.
    local plan = session.Plan(12.5)

    assert(plan.minutes == 13,
        "12.5 rounds to 13, got " .. tostring(plan.minutes))

    assert(plan.budgetSeconds == plan.minutes * 60,
        "and the plan is BUILT against the number it prints: "
        .. tostring(plan.budgetSeconds) .. "s against "
        .. tostring(plan.minutes) .. "m")

    print("  a plan's headline and its budget are the same number")
end)()

;(function()
    ------------------------------------------------------------
    -- A NON-FINITE BEARING IS NOT A BEARING.
    --
    -- The first version of the arithmetic normaliser caught a NaN and passed
    -- an INFINITY straight through: `CN.Mod(inf + pi, 2pi)` is `inf - inf`,
    -- which is NaN -- so the guard that exists because "a non-finite bearing
    -- spins the client" produced one.
    ------------------------------------------------------------
    local normalize = (CN:GetModule("Navigation")).NormalizeAngle

    for _, value in ipairs({ math.huge, -math.huge, 0 / 0 }) do
        local got = normalize(value)

        assert(got == 0, "a non-finite bearing normalises to zero, got "
            .. tostring(got))

        assert(got == got, "and never to a NaN")
    end

    print("  an infinite bearing is answered, not propagated")
end)()


print("\nWhat 0.58.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- ROWS THAT BELONG TO EACH OTHER SURVIVE A SORT AND A FILTER.
    --
    -- The three-mode sort treated every row as a peer, so "A to Z" on the
    -- Goals tab interleaved every chain step of every goal into one
    -- alphabetical column with the headings scattered through it. Filtering
    -- was the same defect in the other direction: a match on a chain step
    -- showed the step and dropped the goal it belonged to.
    ------------------------------------------------------------
    local list = CN.UI.CreateList(UIParent)

    assert(list and list.SetEntries, "the list widget must build")

    local entries = {
        { text = "Zebra goal",  group = "g:1" },
        { text = "  step one",  group = "g:1" },
        { text = "  step two",  group = "g:1" },
        { text = "Apple goal",  group = "g:2" },
        { text = "  a step",    group = "g:2" },
    }

    -- As ranked: untouched, which is the default and the product.
    local asRanked = list:ApplySort(entries)

    assert(asRanked[1].text == "Zebra goal" and asRanked[4].text == "Apple goal",
        "the default order must be the order the tab produced")

    -- A to Z: the BLOCKS move, the steps inside one do not.
    list:CycleSort()

    assert(list:SortMode() == "name", "the second mode is A to Z")

    local sorted = list:ApplySort(entries)

    assert(sorted[1].text == "Apple goal",
        "sorting must move whole goals, got " .. sorted[1].text)

    assert(sorted[2].text == "  a step",
        "and its own steps must follow it, got " .. sorted[2].text)

    assert(sorted[3].text == "Zebra goal",
        "before the next goal begins, got " .. sorted[3].text)

    assert(sorted[4].text == "  step one" and sorted[5].text == "  step two",
        "and a chain's steps keep the order you do them in")

    -- AND FILTERING KEEPS THE PARENT.
    list:SetFilter("step two")

    local kept = list:Filter(entries)

    assert(#kept == 3, "matching one step must keep its whole goal, got " .. #kept)

    assert(kept[1].text == "Zebra goal",
        "and the goal must be the first row of it, got " .. kept[1].text)

    local missed = list:Filter({ { text = "nothing like it" } })

    assert(#missed == 0, "a filter that matches nothing still matches nothing")

    list:SetFilter("")

    print("  a goal and its chain sort and filter as one thing")

    ------------------------------------------------------------
    -- A SECTION IS NOT A GROUP, AND THE DIFFERENCE IS THE POINT.
    --
    -- The Journey tab draws "Closest to finished" and then twelve
    -- achievements. Those twelve are peers -- alphabetising them is exactly
    -- what somebody asks for -- so freezing them the way a goal's chain is
    -- frozen would take the sort away where it is most useful. What must not
    -- move is the heading.
    ------------------------------------------------------------
    local sectioned = {
        { text = "loose row" },
        { text = "Closest to finished", section = "c", sectionHeader = true },
        { text = "  Zebra",             section = "c" },
        { text = "  Apple",             section = "c" },
    }

    local out = list:ApplySort(sectioned)

    assert(out[1].text == "loose row",
        "a row outside every section keeps its own run, got " .. out[1].text)

    assert(out[2].text == "Closest to finished",
        "the heading stays at the top of its section, got " .. out[2].text)

    assert(out[3].text == "  Apple" and out[4].text == "  Zebra",
        "and the rows under it DO sort, among themselves")

    print("  a section's heading is pinned and its rows still sort")

    ------------------------------------------------------------
    -- AND THE SORT MUST NOT TWITCH.
    --
    -- `table.sort` is not stable, and two blocks whose first rows read the
    -- same would swap places on every refresh -- on a tab that redraws every
    -- two seconds, that is a list that will not sit still.
    ------------------------------------------------------------
    -- ENOUGH OF THEM THAT AN UNSTABLE SORT ACTUALLY REORDERS.
    --
    -- Two equal elements is not a test: `table.sort` leaves a pair of them
    -- alone whatever the comparator says, so this passed with the tie-break
    -- removed. Lua's quicksort reorders equal keys once there are enough to
    -- partition, and twenty is comfortably enough.
    local twins = {}

    for index = 1, 20 do
        table.insert(twins, { text = "same", group = "g" .. index })
        table.insert(twins, { text = "  child " .. index, group = "g" .. index })
    end

    local once  = list:ApplySort(twins)
    local twice = list:ApplySort(twins)

    for index = 1, #once do
        assert(once[index].text == twice[index].text,
            "sorting the same list twice must give the same order")
    end

    -- The tie-break is the ONLY thing that can produce this: every parent
    -- reads "same", so without it the children come back in whatever order
    -- the partition happened to leave.
    for index = 1, 20 do
        assert(once[(index * 2) - 1].text == "same",
            "every odd row is a parent")

        assert(once[index * 2].text == "  child " .. index,
            "and the tie must break on the order the tab produced -- row "
            .. (index * 2) .. " is " .. once[index * 2].text)
    end

    print("  two rows that read the same do not swap on every refresh")
end)()

;(function()
    ------------------------------------------------------------
    -- SORTING MUST SORT ON THE WORDS, NOT ON THE COLOUR IN FRONT OF THEM.
    --
    -- `entry.text` is the RENDERED string, and `|` plus eight hex digits sort
    -- against real letters. So "A to Z" on the Goals tab put every finished
    -- goal (muted, `8a...`) above every unfinished one (accented, `ff...`)
    -- whatever they were called, and on the Zone tab -- where every row
    -- begins with its route number -- clicking the header did nothing at all.
    ------------------------------------------------------------
    local list = CN.UI.CreateList(UIParent)

    local coloured = {
        { text = CN.Muted("Zebra") },
        { text = CN.Accent("Aardvark") },
        { text = "|cff8a8f96 3.|r Mole" },
    }

    list:CycleSort()

    assert(list:SortMode() == "name", "the second mode is A to Z")

    local sorted = list:ApplySort(coloured)

    assert(sorted[1].text:find("Aardvark", 1, true),
        "A must come first whatever colour it is wearing, got "
        .. sorted[1].text)

    assert(sorted[2].text:find("Mole", 1, true),
        "and a leading route number must not sort ahead of the name, got "
        .. sorted[2].text)

    assert(sorted[3].text:find("Zebra", 1, true),
        "got " .. sorted[3].text)

    -- AND THE FILTER SEARCHES THE SAME STRIPPED TEXT.
    --
    -- It shared the key, so typing "cff" matched every row in the addon.
    list:SetFilter("cff")

    assert(#list:Filter(coloured) == 0,
        "a colour code is not something a player is searching for")

    list:SetFilter("aardvark")

    assert(#list:Filter(coloured) == 1,
        "but the name inside it is")

    list:SetFilter("")

    print("  sorting and filtering read the words, not the markup")
end)()

;(function()
    ------------------------------------------------------------
    -- LEAVING A FILTERED TAB MUST CLEAR THE LIST, NOT ONLY THE BOX.
    --
    -- `UI.SetFilter` resolves through `UI.tabs[UI.selectedTab]`, and
    -- `SelectTab` advanced that index BEFORE emptying the box -- so nothing
    -- in the addon could reach the list being left. Emptying the widget
    -- cleared the widget; the list behind it stayed filtered, which is the
    -- exact state the `keepFilter` help text warns about.
    ------------------------------------------------------------
    CN.UI.Show()

    local uiSettings = CN.Settings()

    local heldKeep = uiSettings.keepFilter

    uiSettings.keepFilter = false

    -- Find two tabs that both have a list.
    local first, second

    for index, tab in ipairs(CN.UI.tabs) do
        CN.UI.SelectTab(index)

        if tab.panel and CN.UI.listPanels[tab.panel] then
            if not first then
                first = index
            elseif not second then
                second = index
                break
            end
        end
    end

    assert(first and second, "two tabs with lists are needed for this")

    CN.UI.SelectTab(first)

    local leftList = CN.UI.listPanels[CN.UI.tabs[first].panel]

    leftList:SetFilter("something nothing matches")

    assert(leftList:GetFilter(), "the filter must have taken")

    CN.UI.SelectTab(second)

    assert(leftList:GetFilter() == nil,
        "leaving a tab must clear ITS list, not just the box")

    uiSettings.keepFilter = heldKeep

    print("  the filter on the tab you leave is actually cleared")

    ------------------------------------------------------------
    -- AND GOING SOMEWHERE WITHOUT A LIST MUST NOT DESTROY WHAT IS KEPT.
    --
    -- `ClearFocus` fires `OnEditFocusLost`, which with `keepFilter` on writes
    -- the now-empty box over `UI.persistedFilter`. So typing a filter and
    -- then clicking the one tab with no list threw the remembered term away.
    ------------------------------------------------------------
    uiSettings.keepFilter = true

    CN.UI.persistedFilter = "mount"

    local listless

    for index, tab in ipairs(CN.UI.tabs) do
        CN.UI.SelectTab(index)

        if tab.panel and not CN.UI.listPanels[tab.panel] then
            listless = index
            break
        end
    end

    assert(listless, "one tab has no list; that is the case being tested")

    -- FOCUSED FIRST, because the defect lives inside `OnEditFocusLost` and a
    -- box that never had focus never loses it. This is the state a player is
    -- in the moment they finish typing a filter: a Button click does not take
    -- focus off a WoW EditBox, so they are still in the box when they reach
    -- for a tab.
    CN.UI.Frame().search:SetFocus()
    CN.UI.Frame().search:SetText("mount")

    CN.UI.SelectTab(listless)

    assert(CN.UI.persistedFilter == "mount",
        "a tab with no list must not eat the filter the player asked to "
        .. "keep, got " .. tostring(CN.UI.persistedFilter))

    uiSettings.keepFilter = heldKeep
    CN.UI.persistedFilter = nil

    print("  and a listless tab does not eat the filter you asked to keep")
end)()

;(function()
    ------------------------------------------------------------
    -- A SCAN THAT THROWS MUST NOT WEDGE THE BUTTON THAT RAN IT.
    --
    -- The Collections buttons disable themselves, run the scan, and re-enable
    -- afterwards. The work ran unprotected, so a scan that threw left the
    -- button disabled and reading "Working..." until the player reloaded --
    -- no retry, and nothing on screen saying why.
    ------------------------------------------------------------
    local source = assert(io.open(ROOT .. "/UI.lua", "r"))

    local text = source:read("*a")

    source:close()

    local body = text:match("local function RunScans%(button, label, work%).-\n        end")

    assert(body, "RunScans must still be there to check")

    assert(body:find("pcall(work)", 1, true),
        "the scan must run protected, or a failure disables its own button "
        .. "for the rest of the session")

    assert(body:find("button:SetEnabled(true)", 1, true),
        "and the button comes back either way")

    print("  a scan that throws gives its button back")
end)()

;(function()
    ------------------------------------------------------------
    -- A COST OF ZERO IS AN ANSWER, NOT A MISS.
    --
    -- `Travel.CostFor` reads its cache with `if held ~= nil`. A truth test
    -- reads identically and is wrong for exactly one value: zero, which is
    -- what standing on top of the destination costs -- and standing on top of
    -- the destination is the single most common case in the game, because it
    -- is where the addon has just navigated you.
    --
    -- Asserted by counting how many times the estimate is DERIVED, because
    -- the returned number is the same either way. That is the whole point:
    -- the defect is invisible in the answer.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    assert(travel and travel.CostFor, "Travel must be loaded")

    travel.ForgetCosts()

    local mapID, x, y = CN.GetPlayerPosition()

    assert(mapID and x and y, "the fixture player must have a position")

    local real = travel.EstimateSeconds

    local derived = 0

    travel.EstimateSeconds = function(...)
        derived = derived + 1

        -- Zero seconds away: the destination is where the player is.
        return 0
    end

    local first = travel.CostFor(mapID, x, y)

    assert(first == 0, "standing on it must cost nothing, got " .. tostring(first))

    assert(derived == 1, "the first read derives it, got " .. derived)

    local second = travel.CostFor(mapID, x, y)

    assert(second == 0, "and it still costs nothing, got " .. tostring(second))

    assert(derived == 1,
        "but a cost of zero must be SERVED from the cache, not re-derived -- "
        .. "it was derived " .. derived .. " times")

    travel.EstimateSeconds = real

    travel.ForgetCosts()

    print("  a travel cost of zero is cached like any other number")
end)()

;(function()
    ------------------------------------------------------------
    -- HOW OLD A STORED NUMBER IS, IN WORDS.
    --
    -- `Session.FormatDuration` renders four days as "97h 12m", which is the
    -- right shape for "this will take 40m" and the wrong one for "this was
    -- read four days ago". Everything the addon keeps between sessions is
    -- measured in days.
    ------------------------------------------------------------
    local now = 1000000

    assert(CN.Ago(nil) == nil, "no stamp is not an age")
    assert(CN.Ago(0) == nil, "and neither is a zero stamp")

    assert(CN.Ago(now - 5, now) == "just now", "under a minute is just now")
    assert(CN.Ago(now - 600, now) == "10m ago", "got " .. tostring(CN.Ago(now - 600, now)))
    assert(CN.Ago(now - 7200, now) == "2h ago", "got " .. tostring(CN.Ago(now - 7200, now)))
    assert(CN.Ago(now - 86400, now) == "1 day ago",
        "one day is singular, got " .. tostring(CN.Ago(now - 86400, now)))
    assert(CN.Ago(now - (4 * 86400), now) == "4 days ago",
        "got " .. tostring(CN.Ago(now - (4 * 86400), now)))

    -- A CLOCK THAT MOVED BACKWARDS MUST NOT PRINT A NEGATIVE AGE.
    --
    -- A client restart across a timezone change is enough to produce one, and
    -- "-3h ago" is the kind of thing a player screenshots.
    assert(CN.Ago(now + 500, now) == "just now",
        "a stamp in the future reads as now, got "
        .. tostring(CN.Ago(now + 500, now)))

    print("  a stored number can say how old it is without lying")
end)()

;(function()
    ------------------------------------------------------------
    -- EVERY SCAN THE SCANS TAB OFFERS MUST BE A COMMAND THAT EXISTS.
    --
    -- The tab is a list of sources and each row runs a slash command on
    -- click. A row pointing at a command that was renamed is a button that
    -- does nothing, and nothing else in the build would catch it.
    ------------------------------------------------------------
    local sources = CN.UI.Sources()

    assert(#sources > 4, "the source list must not be empty, got " .. #sources)

    local live, stored = 0, 0

    for _, source in ipairs(sources) do
        assert(source.label and source.label ~= "", "every source is named")
        assert(source.detail and source.detail ~= "",
            source.label .. " must say where its number comes from")

        if source.kind == "live" then
            live = live + 1

            assert(source.command == nil,
                "a live source is read from the client, so it has no scan")

            assert(source.at == nil,
                "and it has no age, because it was read just now")
        else
            stored = stored + 1

            assert(CN.commands[source.command],
                source.label .. " points at /cn " .. tostring(source.command)
                .. ", which is not a command")
        end
    end

    assert(live > 0 and stored > 0,
        "both kinds must be present, got " .. live .. " live and "
        .. stored .. " stored")

    print("  " .. #sources .. " sources, and every scan they offer exists")

    ------------------------------------------------------------
    -- AND EACH ONE MUST CLEAR ITS OWN STALENESS.
    --
    -- Existing is not enough. A row's age is `steps[<module>]`, and the row
    -- runs a command -- so the command has to be one that stamps THAT key.
    -- `/cn discoveractive` reads the quest log and stamps nothing, and while
    -- it was wired here the "Quests known" row did real work on every click
    -- and stayed marked stale for ever, while "refresh what is stale" could
    -- never reach zero.
    --
    -- Asserted by clearing the stamp, running the row's command, and looking
    -- at the stamp -- which is the loop a player is actually in.
    local stamps = (CN:GetModule("Setup")).Steps()

    for _, source in ipairs(sources) do
        if source.command then
            -- Sources carry the age, not the key it came from, so recover it
            -- the same way `UI.Sources` stored it: the row is stale iff its
            -- stamp is old, and after the scan it must not be.
            for key in pairs(stamps) do
                stamps[key] = nil
            end

            CN.HandleSlashCommand(source.command)

            local fresh = false

            for _, at in pairs(stamps) do
                if at and at > 0 then
                    fresh = true
                    break
                end
            end

            assert(fresh,
                source.label .. " runs /cn " .. source.command
                .. ", which stamps nothing -- so the row can never stop "
                .. "being stale and clicking it does the same thing for ever")
        end
    end

    print("  and every one of them clears its own staleness when it runs")

    ------------------------------------------------------------
    -- AND "REFRESH WHAT IS STALE" MUST NOT RUN WHAT IS FRESH.
    ------------------------------------------------------------
    local setupModule = CN:GetModule("Setup")

    assert(setupModule and setupModule.Steps,
        "Setup must expose its per-step stamps")

    local steps = setupModule.Steps()

    -- Everything read one second ago.
    for _, source in ipairs(sources) do
        if source.command then
            steps[string.lower(tostring(source.label))] = time()
        end
    end

    -- The stamps are keyed on the MODULE, which is what Sources reads, so
    -- stamp those too rather than assuming the label matches.
    for _, key in ipairs({ "quests", "reputations", "mounts", "pets", "toys",
                           "titles", "appearances", "achievements",
                           "currencies", "professions" }) do
        steps[key] = time()
    end

    assert(CN.UI.RefreshStaleSources() == 0,
        "nothing read a second ago is stale")

    -- And now everything is a week old.
    for key in pairs(steps) do
        steps[key] = time() - (7 * 86400)
    end

    assert(CN.UI.RefreshStaleSources() > 0,
        "a source read a week ago must be refreshed")

    print("  refreshing what is stale skips what is not")
end)()

;(function()
    ------------------------------------------------------------
    -- A CONTROL THAT CANNOT ACT MUST NOT LOOK LIKE IT CAN.
    --
    -- The filter box is one per window and applies to `panel.list`. Two tabs
    -- draw controls rather than a list, so every keystroke typed into the box
    -- on those tabs did nothing -- while the box stayed white, focusable and
    -- captioned "filter".
    ------------------------------------------------------------
    CN.UI.Show()

    local withList, withoutList

    for index, tab in ipairs(CN.UI.tabs) do
        CN.UI.SelectTab(index)

        local usable = CN.UI.UpdateFilterAvailability(tab)

        if usable then
            withList = withList or tab.name
        else
            withoutList = withoutList or tab.name
        end
    end

    assert(withList, "at least one tab must have a filterable list")

    assert(withoutList,
        "and the Settings tab has no list, so the box must go dead on it")

    print("  the filter box goes dead on the tabs it cannot reach ("
        .. withoutList .. ")")
end)()

