print("\nWhat 0.57.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- PINNING A GOAL MUST REACH THE ROWS THAT ARE ALREADY BUILT.
    --
    -- A goal changes the WEIGHT of rows that are otherwise unchanged, and
    -- `userPreference` is deliberately not one of the fields the identity
    -- comparison looks at. So a provider whose rows had not changed took the
    -- unchanged-provider shortcut, the goals decorator never ran, and
    -- `/cn goal` did nothing to a quest already in your log while `/cn ungoal`
    -- left the weighting and the sentence behind -- until the owning provider
    -- happened to rebuild, which is not what is happening while somebody
    -- stands at a vendor managing their goal list.
    ------------------------------------------------------------
    local pinned = CN:GetModule("Goals")

    CN.RegisterCandidateProvider("MutationSteadyRow", function()
        return {
            { type = CN.objectiveTypes.TOY, id = 57000, name = "Steady",
              completionValue = 3 },
        }
    end)

    local function Row()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 57000 then
                return objective
            end
        end
    end

    CN.CollectCandidates(true)

    assert(Row(), "the fixture row must be in the list")

    -- ASSERTED THROUGH WHAT A PLAYER SEES, not through a flag kept for the
    -- test's benefit. `objective.isGoal` was written three times in
    -- Goals.lua and read only here; it is gone, and the row's own sentences
    -- are the thing the window, the tooltip and `/cn why` all read.
    local function SaysGoal()
        for _, reason in ipairs(CN.Reasons(Row()) or {}) do
            if reason:find("one of your goals", 1, true) then
                return true
            end
        end

        return false
    end

    assert(not SaysGoal(), "and must not start out as a goal")

    local generation = CN.decoratorGeneration

    pinned.Add(CN.objectiveTypes.TOY, 57000)

    -- THE MECHANISM, asserted directly.
    --
    -- Invalidating the candidates is not enough on its own: a provider whose
    -- rows have not changed takes the unchanged-provider shortcut and its
    -- rows are never re-decorated. `CN.decoratorGeneration` is the only thing
    -- that defeats that shortcut, so pinning has to move it.
    assert(CN.decoratorGeneration ~= generation,
        "pinning must defeat the unchanged-provider shortcut, or it cannot "
        .. "reach a row the provider has not rebuilt")

    CN.CollectCandidates()

    assert(SaysGoal(),
        "pinning must reach a row the provider has not rebuilt")

    assert((Row().userPreference or 0) >= pinned.goalPreference,
        "and carry the weighting, got " .. tostring(Row().userPreference))

    local saidGoal = false

    for _, reason in ipairs(CN.Reasons(Row())) do
        if reason:find("one of your goals", 1, true) then saidGoal = true end
    end

    assert(saidGoal, "and say so")

    -- AND UNPINNING MUST REACH IT TOO.
    generation = CN.decoratorGeneration

    pinned.Remove(CN.objectiveTypes.TOY, 57000)

    assert(CN.decoratorGeneration ~= generation,
        "and so must unpinning")

    CN.CollectCandidates()

    assert(not SaysGoal(),
        "unpinning must reach the same row, not wait for a rebuild")

    assert((Row().userPreference or 0) == 0,
        "and give the weighting back, got " .. tostring(Row().userPreference))

    for _, reason in ipairs(CN.Reasons(Row())) do
        assert(not reason:find("one of your goals", 1, true),
            "and stop saying it is one")
    end

    CN.candidateProviders["MutationSteadyRow"] = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  pinning and unpinning reach rows that are already built")
end)()

;(function()
    ------------------------------------------------------------
    -- ROUTING A ZONE THAT CHANGED NOTHING MUST NOT RE-RANK EVERYTHING.
    --
    -- `BuildZoneRoute` ended with an unconditional `InvalidateRanking()`. It
    -- runs from the Zone tab's two-second refresh, from every map open, and
    -- from follow mode's three-second ticker -- so the ranked cache had a hit
    -- rate of ZERO for as long as any of those was open. Measured: thirty
    -- Zone-tab ticks produced thirty full re-ranks, four and a half thousand
    -- scorings, and zero hub changes.
    ------------------------------------------------------------
    local mapID, x, y = CN.GetPlayerPosition()

    CN.CollectCandidates(true)
    CN.Recommend(1)

    -- The first build stamps hubs onto candidates that had none, so it
    -- legitimately re-ranks.
    CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)
    CN.Recommend(1)

    local held = CN.rankingGeneration

    -- 0.58.0 added a route cache, and a cached call returns before it reaches
    -- the hub comparison at all -- so a loop of identical calls proves only
    -- that the cache works. Forget the cache each time: the route is genuinely
    -- recomputed, lands on the same hubs, and must STILL not re-rank.
    for _ = 1, 5 do
        CN.ForgetRoutes()
        CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)
    end

    assert(CN.rankingGeneration == held,
        "routing the same zone again changes no hub, so it must leave the "
        .. "ranked list alone -- it moved " .. (CN.rankingGeneration - held)
        .. " time(s) for nothing")

    -- AND ROUTING SOMEWHERE ELSE MUST NOT TOUCH THIS ZONE AT ALL.
    --
    -- This used to assert the opposite -- that routing another zone cleared
    -- this one's hubs and therefore re-ranked. That behaviour was the defect:
    -- `MapPins.Refresh` routes whatever map is being LOOKED at, including on
    -- `WorldMapOnMapChanged`, so panning the world map one zone over stripped
    -- the batch bonus off the zone the player was standing in -- worth up to
    -- three points, comparable to the whole range of completionValue.
    local batchedBefore = CN.batchSizes
    local batchMapBefore = CN.batchMapID

    CN.BuildZoneRoute(2112, 0.5, 0.5)

    assert(CN.rankingGeneration == held,
        "previewing another zone is not a change to this one")

    assert(CN.batchSizes == batchedBefore and CN.batchMapID == batchMapBefore,
        "and it must leave this zone's batching exactly where it was")

    print("  routing the same zone twice does not re-rank the addon twice")
    print("  and previewing another zone does not strip this one's batching")
end)()

;(function()
    ------------------------------------------------------------
    -- "I DO NOT KNOW WHERE IT IS" WAS CHEAPER THAN "I CAN SEE IT".
    --
    -- `CN.unknownLocationCost` was 3 and the far side of the player's own
    -- zone costs about 3.3, so an objective with no coordinates outranked one
    -- twenty yards away -- and twenty of the top thirty recommendations were
    -- things with no location at all.
    --
    -- Two states, not one: a currency is not ANYWHERE, and costs nothing to
    -- reach because there is no journey; a quest whose coordinates have not
    -- resolved is somewhere the addon cannot name, and is charged the
    -- pessimistic answer, exactly as `Travel.CostFor` charges one.
    ------------------------------------------------------------
    assert(CN.unknownLocationCost > 3.3,
        "an unknown journey must cost more than crossing your own zone, "
        .. "got " .. tostring(CN.unknownLocationCost))

    assert(CN.unknownLocationCost < 40,
        "and less than another continent")

    local currency = { type = CN.objectiveTypes.CURRENCY, id = 57100,
        name = "Placeless", completionValue = 3 }

    local lost = { type = CN.objectiveTypes.QUEST, id = 57101,
        name = "Unlocated", completionValue = 3 }

    assert(CN.IsPlaceless(currency),
        "a currency is not anywhere")

    assert(not CN.IsPlaceless(lost),
        "a quest is somewhere, even when the addon cannot say where")

    local near = { type = CN.objectiveTypes.QUEST, id = 57102,
        name = "Nearby", completionValue = 3,
        mapID = 94, x = 0.5, y = 0.5, travelCost = 0.2 }

    assert(CN.ScoreObjective(near) > CN.ScoreObjective(lost),
        "something you can see beats something the addon cannot place")

    assert(CN.ScoreObjective(currency) > CN.ScoreObjective(lost),
        "and a thing with no journey beats one with an unknown journey")

    -- And a located objective is never treated as placeless whatever its
    -- type says.
    local locatedCurrency = { type = CN.objectiveTypes.CURRENCY, id = 57103,
        mapID = 94, x = 0.5, y = 0.5 }

    assert(not CN.IsPlaceless(locatedCurrency),
        "coordinates win over the type table")

    print("  not knowing where something is costs more than knowing")
end)()

;(function()
    ------------------------------------------------------------
    -- THE BANK RECORD SURVIVES A RELOAD.
    --
    -- 0.56.0 held the per-container picture in memory only, so at the next
    -- login the first `BANKFRAME_OPENED` threw away everything on disk except
    -- the one tab the client happened to be describing -- and stamped it as
    -- freshly scanned. You had to click through every tab again after every
    -- reload.
    ------------------------------------------------------------
    local inventory = CN:GetModule("Inventory")

    local first  = inventory.accountBankIDs[1]
    local second = inventory.accountBankIDs[2]

    local store = inventory.WarbandStore()

    for key in pairs(store) do
        store[key] = nil
    end

    CN_TEST_BAGS[first]  = { { itemID = 57200, stackCount = 2 } }
    CN_TEST_BAGS[second] = { { itemID = 57201, stackCount = 6 } }

    inventory.ScanBank()

    assert(store[57200] == 2 and store[57201] == 6,
        "both described tabs are recorded")

    assert(type(store.containers) == "table",
        "and the record says WHICH container each came from, which is what "
        .. "makes a reload survivable")

    -- A reload: the in-memory picture is gone, the persisted one is not, and
    -- the client is describing one tab.
    CN_TEST_BAGS[second] = nil

    inventory.ScanBank()

    assert(store[57201] == 6,
        "a tab the client is not describing keeps what it had ACROSS a "
        .. "reload, not just within a session")

    assert(store[57200] == 2, "and the visible tab is still right")

    CN_TEST_BAGS[first] = nil

    for key in pairs(store) do
        store[key] = nil
    end

    print("  a bank tab you have not opened this session is not forgotten")
end)()

;(function()
    ------------------------------------------------------------
    -- DATA SET ASIDE STAYS REPORTED UNTIL SOMEBODY DEALS WITH IT.
    --
    -- The migration refuses to destroy a corrupt character table and moves it
    -- aside. The NEXT login then saw a nil, took the "create it" branch,
    -- succeeded, and cleared the failure record -- so one login after the
    -- refusal `/cn navdiag` reported a clean bill of health over an empty
    -- character list, and the rescued data sat in SavedVariables for ever
    -- with nothing that mentioned it.
    ------------------------------------------------------------
    -- THROUGH THE RESCUE ITSELF, not by writing the key by hand.
    local raw = {
        version          = 9,
        migrationFailure = { version = 9, error = "unreadable" },
        characters       = "a corrupt string",
    }

    assert(CN.RescueUnreadable(raw), "an unreadable value is set aside")

    assert(raw.rescuedCharacters == "a corrupt string",
        "and kept, rather than replaced")

    assert(raw.characters == nil,
        "and taken out of the way of the defaults merge, which would replace "
        .. "it with an empty table and erase the evidence")

    assert(not CN.RescueUnreadable({ version = 9, characters = {} }),
        "and a table the addon CAN read is not rescued from anything")

    local held = CN.db.rescuedCharacters

    CN.db.rescuedCharacters = "a corrupt string"

    local rescuedBefore = #output

    CN.HandleSlashCommand("rescued")

    local mentioned = false

    for index = rescuedBefore + 1, #output do
        if output[index]:find("set aside", 1, true) then mentioned = true end
    end

    assert(mentioned, "the command must say what is there")

    -- The self-test reports it too, because that is what a bug report pastes.
    local selfTest = CN:GetModule("SelfTest")

    local failed = false

    for _, check in ipairs(selfTest.Run().checks) do
        if check.status == "FAIL" and tostring(check.detail):find("set aside",
            1, true) then

            failed = true
        end
    end

    assert(failed,
        "and an unresolved rescue is a failed check, not a clean bill of "
        .. "health")

    CN.HandleSlashCommand("rescued discard")

    assert(CN.db.rescuedCharacters == nil,
        "and there must be a way to be done with it")

    CN.db.rescuedCharacters = held

    print("  data the addon would not destroy is reported until you decide")
end)()

;(function()
    ------------------------------------------------------------
    -- THE REMAINING COUNTS ARE CACHED, AND THE CACHE NOTICES.
    --
    -- The report walks three thousand achievement rows and eighteen hundred
    -- pets to produce numbers that are identical until the player collects
    -- something -- and the Remaining tab asked for it every two seconds.
    -- 0.63 ms of that, twice a second, for an answer that had not changed.
    ------------------------------------------------------------
    local breakdown = CN:GetModule("Breakdown")

    local first = breakdown.Report()

    assert(breakdown.Report() == first,
        "asking twice for an answer nothing has changed returns the same "
        .. "table rather than rebuilding it")

    -- And collecting something is a change.
    breakdown.NoteChanged()

    assert(breakdown.Report() ~= first,
        "but a collection changing must be noticed, or the tab reports "
        .. "yesterday's numbers for the rest of the session")

    -- Through the event, which is the path the game takes.
    local held = breakdown.Report()

    local eventFrame = CN.eventFrame

    eventFrame.scripts.OnEvent(eventFrame, "NEW_PET_ADDED", 1)

    assert(breakdown.Report() ~= held,
        "and the client announcing a new pet is one of those changes")

    print("  the remaining counts are counted once per thing that changes them")
end)()

;(function()
    ------------------------------------------------------------
    -- THE SCAN ASKS THE CLIENT ONE QUESTION ONCE.
    --
    -- One bag update was measured at 1,022 client calls, 144 of them exact
    -- duplicates: the scan asked whether each slot starts a quest and threw
    -- away the answer, and `QuestStarters` then asked the identical question
    -- again about every slot. The four journal lookups were keyed on an
    -- itemID, which is immutable, and re-asked per slot -- so a forty-slot
    -- stack of one reagent asked forty times.
    ------------------------------------------------------------
    local inventory = CN:GetModule("Inventory")

    local asked = 0

    local realQuestInfo = C_Container.GetContainerItemQuestInfo

    C_Container.GetContainerItemQuestInfo = function(bag, slot)
        asked = asked + 1

        return realQuestInfo(bag, slot)
    end

    inventory.Forget()

    local items = inventory.Scan()

    local afterScan = asked

    inventory.QuestStarters()

    C_Container.GetContainerItemQuestInfo = realQuestInfo

    assert(afterScan > 0, "the scan must ask at all")

    assert(asked == afterScan,
        "and asking again for the same slots is waste: " .. afterScan
        .. " became " .. asked)

    assert(#items > 0, "the fixture must have something in its bags")

    -- AND WHAT AN ITEM *IS* IS ASKED ONCE PER ITEM, NOT ONCE PER SLOT.
    --
    -- "Does this item teach a mount" is a property of the item and the client
    -- answers it from a static table, so a forty-slot stack of one reagent
    -- was asking forty times. One bag update was measured at 576 of these.
    local lookups = 0

    local realMount = C_MountJournal.GetMountFromItem

    C_MountJournal.GetMountFromItem = function(itemID)
        lookups = lookups + 1

        return realMount(itemID)
    end

    -- An item that IS a mount is remembered; an item that is neither a mount
    -- nor a pet is not, because a cold journal answers "neither" to
    -- everything and remembering that hides every collectible in the bags
    -- for the session.
    CN_TEST_BAGS[0] = CN_TEST_BAGS[0] or {}

    table.insert(CN_TEST_BAGS[0], { itemID = 800, stackCount = 1 })

    inventory.Forget()

    inventory.UncollectedItems()

    local firstQuestPass = lookups

    inventory.UncollectedItems()
    inventory.UncollectedItems()

    C_MountJournal.GetMountFromItem = realMount

    assert(lookups < firstQuestPass * 3,
        "asking what the same items are three times must not ask the client "
        .. "three times: " .. firstQuestPass .. " became " .. lookups)

    -- AND A COLD JOURNAL'S "NO" IS NOT REMEMBERED.
    --
    -- Both journals answer nil until they are populated, which at login is
    -- after the first bag scan. Remembering that made every caged pet and
    -- mount item invisible for the session, recoverable only by a reload.
    local coldAsked = 0

    local realCold = C_MountJournal.GetMountFromItem

    C_MountJournal.GetMountFromItem = function(itemID)
        coldAsked = coldAsked + 1

        return nil
    end

    inventory.Forget()
    inventory.UncollectedItems()

    local firstCold = coldAsked

    inventory.Forget()
    inventory.UncollectedItems()

    C_MountJournal.GetMountFromItem = realCold

    assert(coldAsked > firstCold,
        "an item the client said nothing about must be asked again, or a "
        .. "cold journal hides everything in your bags until you reload")

    table.remove(CN_TEST_BAGS[0])

    inventory.Forget()

    print("  a bag scan asks each slot about itself once")
end)()

;(function()
    ------------------------------------------------------------
    -- THE 2-OPT PASS STILL PRODUCES A ROUTE, AND A SHORTER ONE.
    --
    -- Rewritten in 0.57.0 with flat coordinate arrays and don't-look bits.
    -- Both are supposed to be exact -- the same answer, reached with less
    -- work -- so the property to assert is the one that matters: the route
    -- holds the same stops and is no longer than it was.
    ------------------------------------------------------------
    local savedSpan = CN_TEST_MAP_SPAN

    CN_TEST_SetMapSpan({ 3000, 2000 })

    CN.UseRouteMapScale(94)

    local worse, better = 0, 0

    for seed = 1, 40 do
        local stops = {}

        for index = 1, 24 do
            table.insert(stops, {
                name = "S" .. index,
                mapID = 94,
                x = 0.05 + (((index * seed * 7) % 37) * 0.024),
                y = 0.05 + (((index * seed * 11) % 41) * 0.022),
            })
        end

        local length = CN.RouteLength(stops, 0.5, 0.5)

        local held = {}

        for _, stop in ipairs(stops) do
            held[stop] = (held[stop] or 0) + 1
        end

        local improved = CN.ImproveRoute(stops, 0.5, 0.5)

        assert(#improved == 24, "every stop survives, got " .. #improved)

        for _, stop in ipairs(improved) do
            held[stop] = (held[stop] or 0) - 1
        end

        for stop, stopCount in pairs(held) do
            assert(stopCount == 0,
                "and no stop is duplicated or lost: " .. tostring(stop.name))
        end

        local after = CN.RouteLength(improved, 0.5, 0.5)

        if after > length + 1e-6 then
            worse = worse + 1
        elseif after < length - 1e-6 then
            better = better + 1
        end
    end

    assert(worse == 0, worse .. " of 40 routes got LONGER")

    assert(better > 20,
        "and it must actually shorten most of them, got " .. better)

    CN_TEST_SetMapSpan(savedSpan)

    CN.UseRouteMapScale(nil)

    print("  " .. better .. " of 40 routes shortened, none lengthened, none lost")
end)()

;(function()
    ------------------------------------------------------------
    -- THE PLAYER'S POSITION IS ASKED FOR ONCE PER FRAME.
    --
    -- One cold rebuild was measured at 23 calls, 13 of them from a single
    -- loop in the travel costing -- and `GetPlayerMapPosition` allocates a
    -- vector in the client on every one. The MAP is still asked for every
    -- time, because walking into a building changes it without the player
    -- moving, and memoising that would stop the arrow in a doorway.
    ------------------------------------------------------------
    local positions, maps = 0, 0

    local realPosition = C_Map.GetPlayerMapPosition
    local realMap      = C_Map.GetBestMapForUnit

    C_Map.GetPlayerMapPosition = function(...)
        positions = positions + 1

        return realPosition(...)
    end

    C_Map.GetBestMapForUnit = function(...)
        maps = maps + 1

        return realMap(...)
    end

    for _ = 1, 20 do
        CN.GetPlayerPosition()
    end

    C_Map.GetPlayerMapPosition = realPosition
    C_Map.GetBestMapForUnit    = realMap

    assert(positions <= 1,
        "twenty asks inside one frame must convert once, got " .. positions)

    assert(maps == 20,
        "and the map must still be asked every time, or the arrow stops in "
        .. "a doorway; got " .. maps)

    -- A new frame is a new answer.
    CN_TEST_CLOCK = CN_TEST_CLOCK + 0.05

    positions = 0

    C_Map.GetPlayerMapPosition = function(...)
        positions = positions + 1

        return realPosition(...)
    end

    CN.GetPlayerPosition()

    C_Map.GetPlayerMapPosition = realPosition

    assert(positions == 1, "and the next frame asks again")

    print("  the client is asked where you are once a frame, not once a call")
end)()

print("\nWhat 0.56.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- A SATURATED JOURNEY ESTIMATE POISONED EVERY LEARNED DURATION.
    --
    -- `Travel.maximumCost` is 40 and `CN.secondsPerCostPoint` is 30, so a
    -- journey estimate tops out at exactly 1200 seconds -- which is also the
    -- span 0.55.0 rejected as implausible. The window in which a saturated
    -- sample could produce anything but the 0.05-second floor was
    -- arithmetically EMPTY, so every cross-continent completion stored 0.05,
    -- the median collapsed to 0.05, and `/cn plan` reported a zone as four
    -- minutes of work. Confidently, because 0.05 is not nil.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")
    local travel  = CN:GetModule("Travel")

    local durations = session.Durations()

    durations[CN.objectiveTypes.RARE] = nil

    local savedClock = CN_TEST_CLOCK

    -- A cost at the ceiling: the model saying "far away, I stopped counting".
    session.NoteOffered({
        type = CN.objectiveTypes.RARE, id = 56001,
        mapID = 2248, x = 0.5, y = 0.5,
        travelCost = travel.maximumCost,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 300

    assert(session.NoteCompleted(CN.objectiveTypes.RARE, 56001) == nil,
        "a journey estimate that hit its own ceiling cannot be subtracted, "
        .. "so the sample teaches nothing and must be dropped rather than "
        .. "flattened to the floor")

    assert(durations[CN.objectiveTypes.RARE] == nil,
        "and must not reach the store")

    -- AND ESPECIALLY NOT WHEN THE SPAN IS SHORT, which is the case the two
    -- rules disagree about: a short span would otherwise be floored and kept,
    -- so this is where "the estimate is unusable" has to win on its own.
    session.NoteOffered({
        type = CN.objectiveTypes.RARE, id = 56005,
        mapID = 2248, x = 0.5, y = 0.5,
        travelCost = travel.maximumCost,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 5

    assert(session.NoteCompleted(CN.objectiveTypes.RARE, 56005) == nil,
        "five seconds against a ceilinged estimate is still a sample with no "
        .. "separable journey in it")

    -- A REAL COST STILL WORKS, and still subtracts.
    -- `travelCosted`, because since 0.70.0 a cost is only subtractable when
    -- the travel model actually produced it -- a routing constant is not a
    -- journey, and subtracting one biases the learned work time down.
    session.NoteOffered({
        type = CN.objectiveTypes.RARE, id = 56002, travelCost = 2,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 300

    local real = session.NoteCompleted(CN.objectiveTypes.RARE, 56002)

    assert(real and math.abs(real - (300 - 60)) < 0.01,
        "a real journey is taken out of the span, got " .. tostring(real))

    -- AND THE FLOOR IS GATED ON THE SPAN, NOT ON THE ESTIMATE.
    --
    -- Under a minute on the list is instant however far the model thought you
    -- had to go. Over a minute with an estimate that swallowed the span means
    -- the estimate is stale -- `NoteOffered` stamps it once, from wherever
    -- the addon thought you were -- and the split is unknowable.
    durations[CN.objectiveTypes.RARE] = nil

    session.NoteOffered({
        type = CN.objectiveTypes.RARE, id = 56003, travelCost = 20,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 10

    assert(session.NoteCompleted(CN.objectiveTypes.RARE, 56003)
        == session.minimumWorkSeconds,
        "ten seconds on the list is instant whatever the model expected")

    session.NoteOffered({
        type = CN.objectiveTypes.RARE, id = 56004, travelCost = 20,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 500

    assert(session.NoteCompleted(CN.objectiveTypes.RARE, 56004) == nil,
        "but eight minutes on the list against a ten-minute estimate is a "
        .. "stale estimate, not an instant objective")

    CN_TEST_CLOCK = savedClock

    durations[CN.objectiveTypes.RARE] = nil

    print("  a learned duration comes from a journey the model stands behind")
end)()

;(function()
    ------------------------------------------------------------
    -- THE AGGREGATE'S REASON UNION BECAME PERMANENT.
    --
    -- The dedup merges the losing provider's sentences onto the WINNER'S LIVE
    -- TABLE. That was harmless only by accident: the identity comparison
    -- always failed, so the winner's table was rebuilt every pass and the
    -- union reset with it. Repairing that comparison in 0.55.0 made the union
    -- accumulate -- so a quest two providers know about collected every state
    -- it had ever been in, and `/cn why` printed "available to pick up",
    -- "quest is ACTIVE" and "ready to turn in" at once, about one quest.
    ------------------------------------------------------------
    local phase = "PICKUP"

    CN.RegisterCandidateProvider("MutationWinner", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56100, name = "Contested",
              completionValue = 9, reasons = { "the winner says so" } },
        }
    end)

    CN.RegisterCandidateProvider("MutationLoser", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56100, name = "Contested",
              completionValue = 1, reasons = { "quest is " .. phase } },
        }
    end)

    local function Reasons()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 56100 then
                return CN.Reasons(objective)
            end
        end

        return {}
    end

    CN.CollectCandidates(true)

    local first = #Reasons()

    for _, next in ipairs({ "ACTIVE", "TURNIN", "PICKUP", "ACTIVE" }) do
        phase = next

        CN.InvalidateProvider("MutationLoser", true)
        CN.CollectCandidates()
    end

    local held = Reasons()

    assert(#held == first,
        "a merged reason is withdrawn before the next merge, " .. first
        .. " became " .. #held .. ": " .. table.concat(held, " | "))

    -- And the CURRENT one is the one that survives, not the first one.
    local saidActive = false

    for _, reason in ipairs(held) do
        if reason == "quest is ACTIVE" then
            saidActive = true
        end
    end

    assert(saidActive,
        "and it is the current sentence that is merged, not a stale one: "
        .. table.concat(held, " | "))

    CN.candidateProviders["MutationWinner"] = nil
    CN.candidateProviders["MutationLoser"]  = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  a quest two providers know about does not collect contradictions")
end)()

;(function()
    ------------------------------------------------------------
    -- DECORATING A REUSED TABLE TWICE MUST PRODUCE WHAT DECORATING IT ONCE
    -- PRODUCES.
    --
    -- `MarkProviderReasons` recorded the count blindly, so a provider that
    -- hands back the same table it handed back last time -- several do -- had
    -- the previous pass's decorator output absorbed into "what the provider
    -- said". The boundary crept up one sentence per rebuild and `/cn why`
    -- repeated the line once per rebuild.
    ------------------------------------------------------------
    -- The same OBJECTIVE table every time, in a list that grows -- which is
    -- what a caching provider that discovers a new row looks like. The
    -- growing list is what makes the identity comparison fail and the shared
    -- object get decorated a second time; a provider whose list never changes
    -- short-circuits and never reaches this at all.
    local cached = { type = CN.objectiveTypes.TOY, id = 56200, name = "Cached",
        completionValue = 4, reasons = { "the provider says so" } }

    local extra = 0

    CN.RegisterCandidateProvider("MutationCachedTable", function()
        local list = { cached }

        for index = 1, extra do
            table.insert(list, {
                type = CN.objectiveTypes.TOY, id = 56210 + index,
                name = "Extra " .. index, completionValue = 1,
            })
        end

        return list
    end)

    CN.RegisterCandidateDecorator("MutationStamps", function(objective)
        if objective.id ~= 56200 then
            return
        end

        -- Through the contract, which is what a decorator must use: its
        -- output lives in its own table, so running twice assigns the same
        -- key twice rather than appending twice.
        CN.AddDecoratorReason(objective, "mutation", "the decorator says so")
    end)

    CN.CollectCandidates(true)

    local afterOne = #CN.Reasons(cached)

    assert(afterOne == 2,
        "one provider sentence and one decorator sentence, got " .. afterOne)

    assert(#(cached.reasons or {}) == 1,
        "and the provider's own list still holds exactly what the provider "
        .. "put in it, got " .. #(cached.reasons or {}))

    for _ = 1, 5 do
        extra = extra + 1

        CN.InvalidateProvider("MutationCachedTable", true)
        CN.CollectCandidates()
    end

    assert(#CN.Reasons(cached) == afterOne,
        "decorating a reused object six times must not stamp six sentences, "
        .. afterOne .. " became " .. #CN.Reasons(cached) .. ": "
        .. table.concat(CN.Reasons(cached), " | "))

    CN.candidateDecorators["MutationStamps"] = nil
    CN.candidateProviders["MutationCachedTable"] = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  a caching provider's rows do not accumulate decorator sentences")
end)()

;(function()
    ------------------------------------------------------------
    -- AN UNLOCK COUNT FROZEN FOR THE SESSION.
    --
    -- Repairing the identity comparison means a provider's tables are REUSED
    -- across rebuilds, and the decorator's "already set, leave it" guard then
    -- made the first answer permanent -- on the second-heaviest term in the
    -- scorer, with `/cn why` stating a count the addon knew was wrong.
    ------------------------------------------------------------
    local unlockHarvest = CN:GetModule("Harvest")

    local store = unlockHarvest.Store()

    for questID in pairs(store) do
        store[questID] = nil
    end

    store[56300] = { questID = 56300, lastSeen = 1 }
    store[56301] = { questID = 56301, lastSeen = 1, observedRequires = { 56300 } }

    unlockHarvest.NoteUnlocksChanged()

    local objective = { type = CN.objectiveTypes.QUEST, id = 56300 }

    CN.candidateDecorators["Unlocks"](objective)

    local unlockBefore = objective.unlockValue

    assert(unlockBefore and unlockBefore > 0, "one observed follower is an unlock value")

    -- Four more quests are harvested behind it.
    for questID = 56302, 56305 do
        store[questID] = {
            questID = questID, lastSeen = 1, observedRequires = { 56300 },
        }
    end

    unlockHarvest.NoteUnlocksChanged()

    CN.candidateDecorators["Unlocks"](objective)

    assert(objective.unlockValue > unlockBefore,
        "and the same objective must pick up the new ones, "
        .. tostring(unlockBefore) .. " stayed " .. tostring(objective.unlockValue))

    -- The sentence is REPLACED, not appended to.
    local unlockSaid = 0

    for _, reason in ipairs(CN.Reasons(objective)) do
        if reason:find("come after this one", 1, true)
            or reason:find("comes after this one", 1, true) then

            unlockSaid = unlockSaid + 1
        end
    end

    assert(unlockSaid == 1,
        "and it says so once, not once per rebuild, got " .. unlockSaid)

    for questID in pairs(store) do
        store[questID] = nil
    end

    unlockHarvest.NoteUnlocksChanged()

    print("  what a quest unlocks keeps up with what has been harvested")
end)()

;(function()
    ------------------------------------------------------------
    -- WORK THE GROUP SHARES.
    --
    -- The addon has known you are in a group since 0.44.0 and used it only to
    -- push solo detours down. Four people in a zone, one quest all four are
    -- carrying: that one is worth four times the work, every player already
    -- knows it, and the addon had the information and said nothing.
    ------------------------------------------------------------
    local group = CN:GetModule("Group")

    local savedSize     = CN_TEST_GROUP_SIZE
    local savedInstance = CN_TEST_INSTANCE

    CN_TEST_GROUP_SIZE = 1
    CN_TEST_INSTANCE   = nil

    group.ForgetShared()

    assert(group.SharedWith(56400) == nil,
        "solo, the question cannot be asked -- and nil is not zero")

    CN_TEST_GROUP_SIZE = 4

    CN_TEST_QUEST_SHARED[56400] = { party1 = true, party2 = true }
    CN_TEST_QUEST_SHARED[56401] = {}

    group.ForgetShared()

    assert(group.SharedWith(56400) == 2,
        "two of the three others are on it, got "
        .. tostring(group.SharedWith(56400)))

    assert(group.SharedWith(56401) == 0,
        "and nobody is on the other one")

    -- Through the scorer, which is the path that matters.
    local shared = { type = CN.objectiveTypes.QUEST, id = 56400 }
    local alone  = { type = CN.objectiveTypes.QUEST, id = 56401 }

    local adjuster = CN.scoreAdjusters["GroupShared"]

    assert(adjuster, "the adjuster must be registered")

    assert(adjuster(shared, 10) > 10,
        "work the group shares ranks higher")

    assert(adjuster(alone, 10) == 10,
        "work only you have is left exactly alone")

    assert(shared.adjusterReasons and shared.adjusterReasons.groupShared,
        "and the line says why, because every line in this addon does")

    -- THE GROUP LEAVING TAKES THE SENTENCE WITH IT.
    CN_TEST_GROUP_SIZE = 1

    group.ForgetShared()

    adjuster(shared, 10)

    assert(not (shared.adjusterReasons and shared.adjusterReasons.groupShared),
        "and a sentence about a group you are no longer in is withdrawn")

    -- A raid must not credit the player with their own quest.
    CN_TEST_GROUP_SIZE = 2
    CN_TEST_INSTANCE   = "raid"

    CN_TEST_QUEST_SHARED[56402] = { raid1 = true, raid2 = true }

    group.ForgetShared()

    assert(group.SharedWith(56402) == 1,
        "the client lists you among the raid units; you are not somebody "
        .. "else on your own quest, got " .. tostring(group.SharedWith(56402)))

    -- AND THE CLIENT IS ASKED ONCE, NOT ONCE PER CANDIDATE PER PASS.
    --
    -- The first version keyed the cache on `CN.rankingGeneration`, which is
    -- bumped by the very thing that triggers a re-rank -- so it was cleared
    -- at exactly the moment it would have been used. Measured at 8,151 client
    -- calls and 7.2 ms for one pass over two hundred candidates in a
    -- forty-person raid, against a 0.4 ms budget for `Recommend(25)`.
    CN_TEST_GROUP_SIZE = 5
    CN_TEST_INSTANCE   = nil

    CN_TEST_QUEST_SHARED[56403] = { party1 = true }

    group.ForgetShared()

    local asked = 0

    local realIsOnQuest = C_QuestLog.IsUnitOnQuest

    C_QuestLog.IsUnitOnQuest = function(unit, questID)
        asked = asked + 1

        return realIsOnQuest(unit, questID)
    end

    for _ = 1, 50 do
        CN.InvalidateRanking()

        group.SharedWith(56403)
    end

    C_QuestLog.IsUnitOnQuest = realIsOnQuest

    assert(asked <= 4,
        "fifty passes over one quest must ask the client once per group "
        .. "member, not once per pass -- asked " .. asked .. " times")

    -- And the roster changing does clear it.
    group.ForgetShared()

    CN_TEST_QUEST_SHARED = {}
    CN_TEST_GROUP_SIZE   = savedSize
    CN_TEST_INSTANCE     = savedInstance

    group.ForgetShared()

    print("  a quest the group shares outranks one only you are on")
end)()

;(function()
    ------------------------------------------------------------
    -- TWO BANKS, WHICH ARE TWO DIFFERENT CLAIMS.
    --
    -- The bank store was `CN.Account("bank")` -- account-wide, written
    -- wholesale by whichever character last opened one -- so every alt read
    -- the main's bank as its own and opening the bank on the alt destroyed
    -- the main's record. And the Warband tabs, which genuinely ARE
    -- account-wide, were not read at all.
    ------------------------------------------------------------
    local inventory = CN:GetModule("Inventory")

    assert(inventory.accountBankIDs and #inventory.accountBankIDs > 0,
        "the Warband tabs must be a list of their own")

    for _, bag in ipairs(inventory.bankIDs) do
        for _, warbandBag in ipairs(inventory.accountBankIDs) do
            assert(bag ~= warbandBag,
                "a container cannot be in both banks -- " .. bag)
        end
    end

    local mineBag    = inventory.bankIDs[2]
    local warbandBag = inventory.accountBankIDs[1]

    CN_TEST_BAGS[mineBag]    = { { itemID = 56500, stackCount = 3 } }
    CN_TEST_BAGS[warbandBag] = { { itemID = 56501, stackCount = 7 } }

    local mine, warband = inventory.ScanBank()

    assert(mine == 1 and warband == 1,
        "each bank is counted separately, got " .. tostring(mine) .. " and "
        .. tostring(warband))

    assert(inventory.BankStore()[56500] == 3,
        "your own bank holds what is in your own bank")

    assert(inventory.BankStore()[56501] == nil,
        "and not what is in the Warband bank -- one is reachable by this "
        .. "character and one by all of them, which is the whole point")

    assert(inventory.WarbandStore()[56501] == 7,
        "and the Warband bank holds the Warband bank")

    -- PER CHARACTER, which is what the account-wide store got wrong.
    assert(CN.character and CN.character.bank,
        "your own bank is a fact about your own character")

    assert(CN.db and CN.db.account and CN.db.account.bank == nil,
        "and must not be sitting in the account-wide table for every alt to "
        .. "read as its own")

    CN_TEST_BAGS[mineBag]    = nil
    CN_TEST_BAGS[warbandBag] = nil

    print("  your bank and the Warband bank are two answers, not one")
end)()

;(function()
    ------------------------------------------------------------
    -- A LIST WITH NOTHING IN IT DREW NOTHING AT ALL.
    --
    -- `SetEntries({})` hid every row and returned, so a tab with nothing to
    -- show was a one-line header above three hundred and eighty pixels of
    -- void -- which reads as broken rather than as empty.
    ------------------------------------------------------------
    local UI = CN.UI

    local panel = CreateFrame("Frame", nil, UIParent)

    local list = UI.CreateList(panel)

    list.emptyText = "Nothing pinned yet."

    list:SetEntries({})

    local row = list.rows and list.rows[1]

    assert(row and row:IsShown(),
        "an empty list must still draw one row saying so")

    local text = row.label and row.label:GetText() or ""

    assert(text:find("Nothing pinned yet.", 1, true),
        "and it must be the tab's own sentence, got " .. tostring(text))

    -- And every tab that has a list says what would fill it.
    local without = {}

    for _, tab in ipairs(UI.tabs) do
        if tab.panel and tab.panel.list and not tab.panel.list.emptyText then
            table.insert(without, tab.name)
        end
    end

    assert(#without == 0,
        "every list must say what would fill it: " ..
        table.concat(without, ", ") .. " does not")

    print("  an empty tab says what would fill it")
end)()

;(function()
    ------------------------------------------------------------
    -- THE HELP SEARCH DID NOT READ ALIASES, WHICH IS WHAT IT WAS FOR.
    --
    -- Commands.lua's own header says the search exists so that "somebody who
    -- half-remembers 'the one about lockouts' should not have to read a
    -- hundred and twenty lines to find /cn instances" -- and `lockouts` is
    -- one of that command's aliases, which the search did not read. The
    -- worked example in the comment was the query that returned nothing.
    ------------------------------------------------------------
    local aliasBefore = #output

    CN.HandleSlashCommand("help lockouts")

    local found = false

    for index = aliasBefore + 1, #output do
        if output[index]:find("/cn instances", 1, true) then
            found = true
        end
    end

    assert(found,
        "searching an alias must find the command it is an alias for")

    -- And the failure path still names a way forward.
    local missAt = #output

    CN.HandleSlashCommand("help zzzznothing")

    local advised = false

    for index = missAt + 1, #output do
        if output[index]:find("/cn help all", 1, true) then
            advised = true
        end
    end

    assert(advised, "and a search that finds nothing points somewhere")

    print("  half-remembering an alias is enough to find the command")
end)()

;(function()
    ------------------------------------------------------------
    -- THE ADDON'S OWN VOCABULARY WAS REACHING PLAYERS.
    ------------------------------------------------------------
    assert(CN.StateLabel,
        "an objective state must have a name a person can read")

    for _, state in pairs(CN.objectiveStates) do
        local label = CN.StateLabel(state)

        assert(label and label ~= state,
            state .. " is printed to players and has no readable label")

        assert(not label:find("_", 1, true),
            "and a label with an underscore in it is the enum wearing a hat: "
            .. label)
    end

    -- `/cn queststatus` prints it, so assert through that.
    local stateBefore = #output

    CN.HandleSlashCommand("queststatus 9001")

    for index = stateBefore + 1, #output do
        assert(not output[index]:find("REQUIRES_OTHER_CHARACTER", 1, true)
            and not output[index]:find("TEMPORARILY_UNAVAILABLE", 1, true),
            "the enum must not reach the player: " .. output[index])
    end

    -- And a filter is refused stateBefore an eligibility answer is invented.
    local state, reason = CN.Explain(CN.objectiveTypes.CURRENCY, 1)

    assert(state == CN.objectiveStates.UNKNOWN, "no checker, no answer")

    assert(reason and not reason:find("eligibility checker", 1, true),
        "and the registry's name is not an explanation: " .. tostring(reason))

    print("  states and registries are described, not named")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn keepfilter off DID NOT CLEAR THE FILTER IT WAS TURNING OFF.
    --
    -- UI.lua publishes itself as `CN.UI` and never calls `RegisterModule`, so
    -- `CN:GetModule("UI")` returned nil, the branch never ran, and the
    -- command printed "a filter that persists invisibly is how a list looks
    -- empty when it is not" while leaving exactly that filter in memory.
    ------------------------------------------------------------
    local filterSettings = CN.Settings()

    filterSettings.keepFilter    = true
    CN.UI.persistedFilter  = "mount"

    CN.HandleSlashCommand("keepfilter off")

    assert(filterSettings.keepFilter ~= true,
        "the setting must actually go off")

    assert(CN.UI.persistedFilter == nil,
        "and the term it was holding must go with it, got "
        .. tostring(CN.UI.persistedFilter))

    print("  turning off a persisting filter forgets what it was holding")
end)()

;(function()
    ------------------------------------------------------------
    -- THE HARVEST SORTED ITS WHOLE STORE ON EVERY CAPTURE AT THE CEILING.
    --
    -- "Count before allocating" fixed the case below the cap and did nothing
    -- at it: `held == cap + 1` on every capture, so each one built a 2001-row
    -- array and sorted it to drop one row -- inside a loop over the whole
    -- quest log at login. Hysteresis, the same way the offer memory has had
    -- it since 0.28.0.
    ------------------------------------------------------------
    local slackHarvest = CN:GetModule("Harvest")

    assert(slackHarvest.pruneSlack and slackHarvest.pruneSlack > 0,
        "the prune must be allowed to overshoot")

    local store = slackHarvest.Store()

    for questID in pairs(store) do
        store[questID] = nil
    end

    local savedCap   = slackHarvest.cap
    local savedSlack = slackHarvest.pruneSlack

    slackHarvest.cap        = 10
    slackHarvest.pruneSlack = 4

    for questID = 1, slackHarvest.cap + 2 do
        store[questID] = { questID = questID, lastSeen = questID }
    end

    assert(slackHarvest.Prune() == 0,
        "two rows over the cap is inside the slack and must not sort")

    for questID = 100, 103 do
        store[questID] = { questID = questID, lastSeen = questID }
    end

    assert(slackHarvest.Prune() > 0,
        "and past the slack it prunes back to the cap")

    assert(CN.CountKeys(store) == slackHarvest.cap,
        "all the way back to the cap, not just under the slack, got "
        .. CN.CountKeys(store))

    for questID in pairs(store) do
        store[questID] = nil
    end

    slackHarvest.cap        = savedCap
    slackHarvest.pruneSlack = savedSlack

    slackHarvest.NoteUnlocksChanged()

    print("  the slackHarvest sorts once per two hundred captures, not once each")
end)()

;(function()
    ------------------------------------------------------------
    -- A REPLACEMENT PROVIDER KEEPS ITS PLACE IN THE QUEUE.
    --
    -- Removing the row and minting a fresh sequence moved the provider to the
    -- back of its priority band -- the exact symptom the tiebreak was added
    -- to prevent, on the path 0.55.0 opened up.
    ------------------------------------------------------------
    local function Provider()
        return {
            GetQuestData = function() return {} end,
            IsAvailable  = function() return true end,
            priority     = 500,
        }
    end

    for _, name in ipairs({ "MutationA", "MutationB", "MutationC" }) do
        CN.RegisterQuestDataProvider(name, Provider())
    end

    local function PositionOf(name)
        for index, entry in ipairs(CN.questDataOrder) do
            if entry.name == name then
                return index
            end
        end
    end

    local was = PositionOf("MutationB")

    CN.RegisterQuestDataProvider("MutationB", Provider())

    assert(PositionOf("MutationB") == was,
        "re-registering must not hand over which addon answers first, "
        .. tostring(was) .. " became " .. tostring(PositionOf("MutationB")))

    for _, name in ipairs({ "MutationA", "MutationB", "MutationC" }) do
        CN.questDataProviders[name] = nil

        for index = #CN.questDataOrder, 1, -1 do
            if CN.questDataOrder[index].name == name then
                table.remove(CN.questDataOrder, index)
            end
        end
    end

    print("  a provider that re-registers keeps its priority position")
end)()

;(function()
    ------------------------------------------------------------
    -- A DECORATOR THAT ADDS TO ITSELF IS A DECORATOR THAT COMPOUNDS.
    --
    -- `Goals.Decorate` read `userPreference` and added eight to it. That was
    -- harmless only while every rebuild produced fresh tables; since 0.55.0
    -- reuses them, a pinned goal's preference climbed by eight per rebuild
    -- without bound -- 8, 16, 24, 32 -- until it outweighed everything else
    -- on the list by thirty to one and nothing could displace it, including
    -- something about to despawn. `/cn breakdown` showed the inflated figure
    -- as though it were deliberate, and only a reload cleared it.
    ------------------------------------------------------------
    local pinnedGoals = CN:GetModule("Goals")

    pinnedGoals.Add(CN.objectiveTypes.TOY, 56600)

    local objective = { type = CN.objectiveTypes.TOY, id = 56600,
        name = "Pinned", completionValue = 3, userPreference = 1 }

    for _ = 1, 6 do
        pinnedGoals.Decorate(objective)
    end

    assert(objective.userPreference == 1 + pinnedGoals.goalPreference,
        "six passes must weigh the same as one, got "
        .. tostring(objective.userPreference))

    local saidPinned = 0

    for _, reason in ipairs(CN.Reasons(objective)) do
        if reason == "this is one of your goals" then
            saidPinned = saidPinned + 1
        end
    end

    assert(saidPinned == 1, "and say so once, got " .. saidPinned)

    -- AND UNPINNING TAKES IT BACK.
    pinnedGoals.Remove(CN.objectiveTypes.TOY, 56600)

    pinnedGoals.Decorate(objective)

    assert(objective.userPreference == 1,
        "unpinning must give back the provider's own preference, got "
        .. tostring(objective.userPreference))

    for _, reason in ipairs(CN.Reasons(objective)) do
        assert(reason ~= "this is one of your goals",
            "and stop saying it is one")
    end

    print("  a pinned goal is worth the same on the sixth pass as the first")
end)()

;(function()
    ------------------------------------------------------------
    -- FOUR WRITERS, FOUR TABLES, ONE READ.
    --
    -- Every reason used to be appended to one array on the objective, and
    -- each of four writers with four different lifetimes had to know where
    -- its own entries began and ended in order to take them back. Three
    -- consecutive releases shipped a different symptom of that one cause.
    --
    -- Nothing writes into anything it does not own now, so there is no
    -- boundary to go stale, and running any writer twice is idempotent by
    -- construction rather than by bookkeeping.
    ------------------------------------------------------------
    local objective = { type = CN.objectiveTypes.QUEST, id = 56700,
        name = "Explained", reasons = { "the provider says so" } }

    CN.AddDecoratorReason(objective, "test", "a decorator says so")
    CN.AddAdjusterReason(objective, "test", "an adjuster says so")

    assert(#CN.Reasons(objective) == 3,
        "three sentences, got " .. #CN.Reasons(objective))

    assert(#objective.reasons == 1,
        "and the provider's own list is untouched by either of them, got "
        .. #objective.reasons)

    -- Every writer, run again, changes nothing.
    for _ = 1, 5 do
        CN.AddDecoratorReason(objective, "test", "a decorator says so")
        CN.AddAdjusterReason(objective, "test", "an adjuster says so")
    end

    assert(#CN.Reasons(objective) == 3,
        "six passes read the same as one, got " .. #CN.Reasons(objective)
        .. ": " .. table.concat(CN.Reasons(objective), " | "))

    -- WITHDRAWN, AND THEN SAYABLE AGAIN. The old shape could delete a
    -- sentence while leaving the key that says "I already said this", so it
    -- could never come back.
    CN.ClearAdjusterReason(objective, "test")

    assert(#CN.Reasons(objective) == 2, "withdrawing takes one away")

    CN.AddAdjusterReason(objective, "test", "an adjuster says so")

    assert(#CN.Reasons(objective) == 3,
        "and it can be said again afterwards, got "
        .. #CN.Reasons(objective))

    -- AND A SENTENCE THAT CARRIES A NUMBER UPDATES RATHER THAN FREEZING.
    CN.AddAdjusterReason(objective, "count", "3 others here are on this quest")
    CN.AddAdjusterReason(objective, "count", "1 other here is on this quest")

    local froze, held = false, 0

    for _, reason in ipairs(CN.Reasons(objective)) do
        if reason:find("others here", 1, true) then froze = true end
        if reason:find("here is on this quest", 1, true) then held = held + 1 end
    end

    assert(not froze,
        "a sentence with a number in it must not freeze at the first number")

    assert(held == 1, "and must not be said twice, got " .. held)

    -- The composed order is stable, which is what stops a list re-ordering
    -- itself under the player between two identical refreshes.
    local first  = table.concat(CN.Reasons(objective), " | ")
    local second = table.concat(CN.Reasons(objective), " | ")

    assert(first == second, "the same objective reads the same way twice")

    print("  four writers, four tables, and one composed answer")
end)()

;(function()
    ------------------------------------------------------------
    -- THE MERGE RATCHETED THE WINNER'S VALUE AND COULD NOT LET GO.
    --
    -- The dedup raises the winner's `completionValue` to the loser's, into
    -- the winner's LIVE CACHED TABLE, with no way back. Unpin a goal and the
    -- quest kept the pinned-era value for the rest of the session; the losing
    -- provider could stop emitting the row entirely and the number stayed.
    ------------------------------------------------------------
    local loserValue = 9

    CN.RegisterCandidateProvider("MutationHigh", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56800, name = "Contested",
              completionValue = 2 },
        }
    end)

    CN.RegisterCandidateProvider("MutationLow", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56800, name = "Contested",
              completionValue = loserValue },
        }
    end)

    -- Through `CN.CompletionValue`, which is what the scorer reads: the
    -- merge records another provider's higher figure beside the row rather
    -- than writing it into the row, so the provider's own value stays its
    -- own and the contribution can go away again.
    local function ValueOf()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 56800 then
                return CN.CompletionValue(objective)
            end
        end
    end

    CN.CollectCandidates(true)

    assert(ValueOf() == 9,
        "the higher of the two wins, got " .. tostring(ValueOf()))

    -- The other provider changes its mind.
    loserValue = 1

    CN.InvalidateProvider("MutationLow", true)
    CN.CollectCandidates()

    assert(ValueOf() == 2,
        "and when it changes its mind the winner goes back to its own value, "
        .. "got " .. tostring(ValueOf()))

    -- AND THE PROVIDER'S OWN ROW WAS NEVER WRITTEN INTO, which is what lets
    -- that provider keep taking the unchanged-provider shortcut. One shipped
    -- provider was measured rebuilding on 31 of 31 passes while the player
    -- stood still, for a value it had not changed.
    for _, objective in ipairs(CN.CollectCandidates()) do
        if objective.id == 56800 then
            assert(objective.completionValue == 2,
                "the merge must not write into the provider's own row, got "
                .. tostring(objective.completionValue))
        end
    end

    CN.candidateProviders["MutationHigh"] = nil
    CN.candidateProviders["MutationLow"]  = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  a value another provider contributed is given back when it goes")
end)()

;(function()
    ------------------------------------------------------------
    -- SAYING THE UNLOCK COUNT CHANGED MUST MAKE SOMETHING REDECORATE.
    --
    -- `NoteUnlocksChanged` bumped a counter, and the decorator only consults
    -- the counter if `Decorate` runs -- which the unchanged-provider shortcut
    -- skips, which is the normal case. So the guard was correct and
    -- unreachable, and the count stayed frozen exactly as before.
    ------------------------------------------------------------
    local unlockHarvest = CN:GetModule("Harvest")

    local store = unlockHarvest.Store()

    for questID in pairs(store) do
        store[questID] = nil
    end

    store[56900] = { questID = 56900, lastSeen = 1 }
    store[56901] = { questID = 56901, lastSeen = 1, observedRequires = { 56900 } }

    CN.RegisterCandidateProvider("MutationUnlocked", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56900, name = "Hub",
              completionValue = 5 },
        }
    end)

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates(true)

    local function UnlockOf()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 56900 then
                return objective.unlockValue
            end
        end
    end

    local was = UnlockOf()

    assert(was and was > 0, "one observed follower is an unlock value")

    for questID = 56902, 56905 do
        store[questID] = {
            questID = questID, lastSeen = 1, observedRequires = { 56900 },
        }
    end

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates()

    assert(UnlockOf() and UnlockOf() > was,
        "and harvesting four more behind it must reach the ranked list, "
        .. tostring(was) .. " stayed " .. tostring(UnlockOf()))

    CN.candidateProviders["MutationUnlocked"] = nil

    for questID in pairs(store) do
        store[questID] = nil
    end

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates(true)

    print("  a harvested unlock reaches the ranking, not just the index")
end)()

;(function()
    ------------------------------------------------------------
    -- THE BANK STORE HELD WHICHEVER TAB WAS LOOKED AT LAST.
    --
    -- The client does not describe a bank tab until it has been switched to,
    -- and the scan rewrote the whole store from what it could see -- so the
    -- Warband bank ended up holding one tab, and moving a single item
    -- rewrote both stores from whatever happened to be described.
    ------------------------------------------------------------
    local inventory = CN:GetModule("Inventory")

    local first  = inventory.accountBankIDs[1]
    local second = inventory.accountBankIDs[2]

    CN_TEST_BAGS[first]  = { { itemID = 57000, stackCount = 2 } }
    CN_TEST_BAGS[second] = nil

    inventory.ScanBank()

    assert(inventory.WarbandStore()[57000] == 2,
        "the tab that was described is recorded")

    -- The player switches tabs. The first is no longer described; the second
    -- now is.
    CN_TEST_BAGS[first]  = nil
    CN_TEST_BAGS[second] = { { itemID = 57001, stackCount = 5 } }

    inventory.ScanBank()

    assert(inventory.WarbandStore()[57001] == 5,
        "the new tab is recorded")

    assert(inventory.WarbandStore()[57000] == 2,
        "and a tab the client has stopped describing is not the same thing "
        .. "as a tab that is empty")

    CN_TEST_BAGS[first]  = nil
    CN_TEST_BAGS[second] = nil

    print("  a bank tab the client stops describing is not emptied")
end)()

;(function()
    ------------------------------------------------------------
    -- THE JOURNEY IS RE-STAMPED AS IT SHORTENS.
    --
    -- `NoteOffered` returned early the moment the key existed, so the travel
    -- estimate was frozen at whatever it was the FIRST time the objective
    -- appeared -- from wherever the addon thought you were then. Fly to that
    -- zone, quest for eight minutes, hand it in, and the sample was compared
    -- against a cost from the continent you left, and rejected.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    local durations = session.Durations()

    durations[CN.objectiveTypes.TREASURE] = nil

    local savedClock = CN_TEST_CLOCK

    -- Offered from a long way off.
    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 57100, travelCost = 20,
        travelCosted = true,
    })

    -- The player flies there. It is offered again, from next door.
    CN_TEST_CLOCK = CN_TEST_CLOCK + 400

    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 57100, travelCost = 1,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 200

    local elapsed = session.NoteCompleted(CN.objectiveTypes.TREASURE, 57100)

    assert(elapsed,
        "an objective reached and finished must produce a sample, not be "
        .. "compared against a journey from the continent you left")

    assert(math.abs(elapsed - (600 - 30)) < 0.01,
        "and the journey taken out is the closest the model got, got "
        .. tostring(elapsed))

    -- And the clock is NOT re-stamped: that is the measurement.
    durations[CN.objectiveTypes.TREASURE] = nil

    CN_TEST_CLOCK = savedClock

    print("  the journey is re-costed as you close on it; the clock is not")
end)()

print("\nWhat 0.55.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- THE FLOOR AND THE DISCARD CANCELLED EACH OTHER OUT.
    --
    -- `NoteCompleted` clamped a short sample up to `minimumWorkSeconds` and
    -- the very next line threw away anything at or below the same number. So
    -- every fast objective -- a quest handed in on arrival, a treasure picked
    -- up on the way past -- was measured, floored, and discarded, which is
    -- the exact bias the floor was written to remove. Every learned duration
    -- read long, and read long confidently.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    assert(session and session.NoteCompleted, "Session must expose NoteCompleted")

    local durations = session.Durations()

    durations[CN.objectiveTypes.TREASURE] = nil

    local savedClock = CN_TEST_CLOCK

    -- Offered now, finished in the same instant, with a travel estimate that
    -- swallows the whole span. This is the shape the floor exists for.
    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 55001, travelCost = 3,
        travelCosted = true,
    })

    local elapsed = session.NoteCompleted(CN.objectiveTypes.TREASURE, 55001)

    assert(elapsed ~= nil,
        "a sample floored to the minimum must be KEPT -- it was floored and "
        .. "then discarded by the test on the next line")

    assert(elapsed == session.minimumWorkSeconds,
        "and it must be the floor itself, got " .. tostring(elapsed))

    assert(#durations[CN.objectiveTypes.TREASURE] == 1,
        "and it must reach the store")

    -- The implausible sample is still rejected, and rejected on the RAW span.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({ type = CN.objectiveTypes.TREASURE, id = 55002 })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 4000

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55002) == nil,
        "over twenty minutes is not a measurement of doing the thing")

    -- A FORTY-MINUTE SPAN WITH A TWENTY-FIVE MINUTE JOURNEY IS STILL FORTY
    -- MINUTES OF NOT DOING IT. Judging plausibility on the travel-adjusted
    -- figure would let this through as a confident fifteen-minute sample.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 55003, travelCost = 50,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 2400

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55003) == nil,
        "an implausible span is implausible however far away it was")

    -- And a clock that went backwards is not a negative duration.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({ type = CN.objectiveTypes.TREASURE, id = 55004 })

    CN_TEST_CLOCK = CN_TEST_CLOCK - 60

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55004) == nil,
        "a clock that went backwards is not a measurement")

    CN_TEST_CLOCK = savedClock

    durations[CN.objectiveTypes.TREASURE] = nil

    print("  a fast objective is floored and KEPT, and a stale one is not")
end)()

;(function()
    ------------------------------------------------------------
    -- HALF THE SUBJECT MATTER WAS BEING DEMOTED FOR THE ADDON'S DEAFNESS.
    --
    -- `shown` was counted for every type; `acted` only for the five the
    -- client announces a completion for. The other thirteen crossed the
    -- observation threshold with a numerator nailed to zero, settled on the
    -- 0.80 floor permanently, and `/cn learned` said "you rarely act on
    -- these" -- a statement about the player that the addon had no way to
    -- make.
    ------------------------------------------------------------
    local preference = CN:GetModule("Preference")

    assert(preference and preference.IsCreditable,
        "Preference must publish what it can credit")

    assert(preference.IsCreditable(CN.objectiveTypes.QUEST),
        "quests are announced by the client and must stay creditable")

    for _, objectiveType in ipairs({
        CN.objectiveTypes.REPUTATION, CN.objectiveTypes.APPEARANCE,
        CN.objectiveTypes.RARE, CN.objectiveTypes.TREASURE,
        CN.objectiveTypes.CURRENCY, CN.objectiveTypes.EXPLORATION,
        CN.objectiveTypes.RENOWN, CN.objectiveTypes.TITLE,
        CN.objectiveTypes.RECIPE, CN.objectiveTypes.PROFESSION,
        CN.objectiveTypes.VENDOR, CN.objectiveTypes.COLLECTIBLE,
        CN.objectiveTypes.INSTANCE,
    }) do
        assert(not preference.IsCreditable(objectiveType),
            objectiveType .. " has no completion event, so it must not be "
            .. "credited or punished")
    end

    -- EVERY TYPE WITH A COMPLETION EVENT MUST BE CREDITABLE, which is the
    -- half of the contract that rots: add an event, forget the set, and the
    -- type is punished for being watched.
    for _, entry in ipairs(preference.completionEvents) do
        assert(preference.IsCreditable(entry.type),
            entry.type .. " is announced by " .. entry.event
            .. " but is not in creditableTypes")
    end

    -- And the multiplier itself, through the path scoring takes: an
    -- uncreditable type sat at three hundred sightings and no completions
    -- must still be 1.00.
    local store = preference.Store()

    store[CN.objectiveTypes.APPEARANCE] = { shown = 300, acted = 0 }

    preference.NoteStoreChanged()

    local multiplier, reason = preference.Multiplier(CN.objectiveTypes.APPEARANCE)

    assert(multiplier == 1,
        "an uncreditable type must not be demoted, got " .. tostring(multiplier))

    assert(reason == nil,
        "and must not claim the player rarely acts on them, got "
        .. tostring(reason))

    store[CN.objectiveTypes.APPEARANCE] = nil

    preference.NoteStoreChanged()

    -- AND THE SENTENCE IS WITHDRAWN WHEN IT STOPS BEING TRUE.
    --
    -- The reason is stamped onto objectives that live in the per-provider
    -- cache, and the cache outlives the opinion. `/cn learned reset` says
    -- "Forgotten. The ranking is back to its defaults." -- and `/cn why` went
    -- on printing the old verdict until some unrelated rebuild happened.
    store[CN.objectiveTypes.TOY] = { shown = 300, acted = 0 }

    preference.NoteStoreChanged()

    local toy = { type = CN.objectiveTypes.TOY, id = 55200, name = "Judged" }

    CN.scoreAdjusters["Preference"](toy, 10)

    assert(toy.adjusterReasons and toy.adjusterReasons.preference,
        "a demoted type must say why")

    local stamped = #CN.Reasons(toy)

    assert(stamped > 0, "and the sentence must reach what the player reads")

    -- Now the evidence goes away, exactly as `/cn learned reset` makes it.
    store[CN.objectiveTypes.TOY] = nil

    preference.NoteStoreChanged()

    CN.scoreAdjusters["Preference"](toy, 10)

    assert(not (toy.adjusterReasons and toy.adjusterReasons.preference),
        "and it must be WITHDRAWN when it stops being true, not left on a "
        .. "cached objective for the rest of the session")

    assert(#CN.Reasons(toy) == stamped - 1,
        "and taken back out of what the player reads")

    print("  only what the client announces earns an opinion; the other "
        .. "thirteen are left alone")
end)()

;(function()
    ------------------------------------------------------------
    -- CLUSTERING ON THE FALLBACK PATH MADE THE WHOLE ZONE ONE STOP.
    --
    -- The 0.54.0 grid compares a squared distance against the hub radius in
    -- yards squared -- 4,900. With the old scale fallback of 1, the largest
    -- possible squared distance across the entire map is 2. So when the
    -- client would not give a scale, every objective in the zone joined the
    -- first hub: one stop, containing everything, with a batch bonus to
    -- match. Before 0.54.0 this path went through ObjectiveDistanceYards,
    -- which has always had a 2000-yard fallback -- so this was a regression
    -- introduced by making the clustering fast.
    ------------------------------------------------------------
    local saved = CN_TEST_MAP_SPAN

    -- The client refusing to answer is what the fallback is for.
    CN_TEST_SetMapSpan(nil)

    CN.UseRouteMapScale(nil)

    local far = {}

    for index = 1, 6 do
        table.insert(far, {
            name  = "Far " .. index,
            mapID = nil,
            x     = 0.05 + (index * 0.15),
            y     = 0.5,
        })
    end

    local hubs = CN.ClusterByProximity(far)

    assert(#hubs == 6,
        "six things spread across a zone are six stops even when the client "
        .. "will not say how big the zone is, got " .. #hubs)

    -- And two things genuinely on top of each other are still one stop.
    local together = CN.ClusterByProximity({
        { name = "A", x = 0.500, y = 0.500 },
        { name = "B", x = 0.505, y = 0.500 },
    })

    assert(#together == 1,
        "two things ten yards apart are one stop, got " .. #together)

    CN_TEST_SetMapSpan(saved)

    CN.UseRouteMapScale(nil)

    -- AND THE SENTINEL MUST NOT PASS FOR AN ANSWER.
    --
    -- `Navigation.MapScale` returns `1, 1` when the client will not convert,
    -- which is the right shrug for a bearing (it only uses the ratio) and a
    -- disaster for routing (it wants absolute yards). `UseMapScale` validated
    -- with `scaleX > 0`, which `1` satisfies -- so the fallback above could
    -- never fire for a REAL map during a loading screen, which is the only
    -- situation it exists for. Asserted through a real mapID.
    CN_TEST_REFUSE_WORLD_POS = true

    local navigation = CN:GetModule("Navigation")

    navigation.ForgetMapScales()

    local shrugX, shrugY, measured = navigation.MapScale(94)

    assert(shrugX == 1 and shrugY == 1,
        "the bearing maths still wants 1,1 when the client will not convert")

    assert(measured == false,
        "and it must SAY that is a shrug rather than a measurement")

    local routedX = select(1, CN.UseRouteMapScale(94))

    assert(routedX == CN.fallbackZoneYards,
        "routing must reject the shrug and use the yard fallback, got "
        .. tostring(routedX))

    local realFar = {}

    for index = 1, 6 do
        table.insert(realFar, {
            name = "RealFar " .. index, mapID = 94,
            x = 0.05 + (index * 0.15), y = 0.5,
        })
    end

    assert(#CN.ClusterByProximity(realFar) == 6,
        "and a real zone the client will not measure is still six stops, got "
        .. #CN.ClusterByProximity(realFar))

    CN_TEST_REFUSE_WORLD_POS = false

    CN_TEST_SetMapSpan(saved)

    CN.UseRouteMapScale(nil)

    print("  the hub radius means yards on the fallback path too")
end)()

;(function()
    ------------------------------------------------------------
    -- EXPLAINING A SCORE MUST NOT CHANGE IT.
    --
    -- `ExplainScore` re-invokes every adjuster, because an adjuster's
    -- contribution is recorded nowhere else. That is safe only while every
    -- adjuster is idempotent and never accumulates. Asserted rather than
    -- assumed: explain the same objective twice and the reason list must not
    -- grow.
    ------------------------------------------------------------
    local objective = {
        type = CN.objectiveTypes.QUEST, id = 55010, name = "Explained",
        completionValue = 5, travelCost = 0.2,
    }

    CN.ExplainScore(objective)

    local first = #(objective.reasons or {})

    CN.ExplainScore(objective)
    CN.ExplainScore(objective)

    assert(#(objective.reasons or {}) == first,
        "explaining a score three times must not stamp three reasons, "
        .. first .. " became " .. #(objective.reasons or {}))

    -- And an adjuster that throws must not take the explanation with it.
    CN.RegisterScoreAdjuster("MutationExplodes", function()
        error("adjuster failure")
    end)

    local ok = pcall(CN.ExplainScore, objective)

    CN.scoreAdjusters["MutationExplodes"] = nil

    assert(ok, "/cn why must survive an adjuster that throws")

    print("  explaining is idempotent, and survives an adjuster that throws")
end)()

;(function()
    ------------------------------------------------------------
    -- A REGISTRY THAT ACCEPTS HALF A CONTRACT.
    ------------------------------------------------------------
    local accepted = CN.RegisterQuestDataProvider("MutationHalf", {
        GetQuestData = function() return {} end,
    })

    assert(not accepted,
        "a quest data provider with no IsAvailable must be refused -- every "
        .. "read calls it")

    assert(CN.questDataProviders["MutationHalf"] == nil,
        "and must not be stored")

    -- Registering twice must replace, not duplicate the priority row.
    local function Whole()
        return {
            GetQuestData = function() return {} end,
            IsAvailable  = function() return true end,
            priority     = 5,
        }
    end

    CN.RegisterQuestDataProvider("MutationTwice", Whole())
    CN.RegisterQuestDataProvider("MutationTwice", Whole())

    local rows = 0

    for _, entry in ipairs(CN.questDataOrder) do
        if entry.name == "MutationTwice" then
            rows = rows + 1
        end
    end

    assert(rows == 1,
        "registering twice is a replacement, not a second row, got " .. rows)

    -- A capture with no name would be filed under nil, which throws inside
    -- the capture run and takes every later capture with it.
    assert(not CN.RegisterCapture{ run = function() return {} end },
        "a capture with no name must be refused")

    for index = #CN.questDataOrder, 1, -1 do
        if CN.questDataOrder[index].name == "MutationTwice" then
            table.remove(CN.questDataOrder, index)
        end
    end

    CN.questDataProviders["MutationTwice"] = nil

    -- A packed route key must read back as the pair that went in, and
    -- anything that is not one of our keys must read back as nothing rather
    -- than as an invented pair.
    local travel = CN:GetModule("Travel")

    local packed = travel.RouteKey(1450, 88)

    local fromID, toID = travel.UnpackRouteKey(packed)

    assert(fromID == 88 and toID == 1450,
        "a packed key must unpack to the pair it holds, got "
        .. tostring(fromID) .. ", " .. tostring(toID))

    assert(travel.UnpackRouteKey("88:1450") == nil,
        "and a string is not one of our keys")

    assert(travel.UnpackRouteKey(0) == nil,
        "and neither is zero")

    print("  a registry checks the whole contract, and twice is once")
end)()

;(function()
    ------------------------------------------------------------
    -- THE REMEMBERED TAB WAS AN ARRAY INDEX.
    --
    -- `UI.tabs` is sorted by order then name and rebuilt whenever a tab
    -- registers. Index 7 is "Collections" only until the tab list changes --
    -- so adding a tab silently reopens the window on somebody else's panel.
    ------------------------------------------------------------
    local tabSettings = CN.Settings()

    local UI = CN.UI or CN:GetModule("UI")

    local target = UI.tabs[#UI.tabs]

    assert(target and target.name, "there must be tabs to remember")

    -- THROUGH THE PATH A CLICK TAKES, not by writing the setting by hand:
    -- the defect is that `SelectTab` recorded only the index, so a test that
    -- writes the name itself passes with the fix removed.
    UI.SelectTab(#UI.tabs)

    assert(tabSettings.selectedTabName == target.name,
        "selecting a tab must record its NAME, got "
        .. tostring(tabSettings.selectedTabName))

    -- Now the tab list changes shape underneath it, which is what actually
    -- happens when a release adds a tab.
    tabSettings.selectedTab = 1

    assert(UI.RememberedTabIndex() == #UI.tabs,
        "the NAME decides, not the stale index")

    -- A database written before 0.55.0 has only the index, and must still
    -- open somewhere sensible.
    tabSettings.selectedTabName = nil
    tabSettings.selectedTab     = 2

    assert(UI.RememberedTabIndex() == 2,
        "an older database still opens on its remembered index")

    -- AND REBUILDING THE STRIP MUST NOT MOVE THE PLAYER.
    --
    -- `RebuildTabs` runs whenever a tab registers, which can happen after the
    -- window exists. Re-selecting unconditionally yanks the player off the tab
    -- they are reading and throws away what they had typed in the search box.
    -- What it must do is follow them across the re-sort, by name.
    UI.SelectTab(1)

    tabSettings.selectedTab     = #UI.tabs
    tabSettings.selectedTabName = target.name

    local standingOn = UI.tabs[1].name

    -- The list re-sorts underneath them, which is exactly what registering a
    -- tab does.
    local moved = table.remove(UI.tabs, 1)

    table.insert(UI.tabs, moved)

    UI.RebuildTabs()

    assert(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name
        == standingOn,
        "a rebuild must leave the player on the tab they were reading, got "
        .. tostring(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name))

    table.insert(UI.tabs, 1, table.remove(UI.tabs))

    -- With nothing selected -- the first time the window is built -- the
    -- remembered NAME decides.
    UI.selectedTab     = nil
    UI.selectedTabName = nil

    UI.RebuildTabs()

    assert(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name
        == target.name,
        "a first build must open on the remembered name, got "
        .. tostring(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name))

    -- A tab that no longer exists is not an error.
    tabSettings.selectedTabName = "AGoneTab"
    tabSettings.selectedTab     = nil

    assert(UI.RememberedTabIndex() == nil,
        "a removed tab falls back to the default rather than throwing")

    tabSettings.selectedTabName = nil
    tabSettings.selectedTab     = nil

    print("  the window reopens on the tab you left, by name")
end)()

;(function()
    ------------------------------------------------------------
    -- A SCORING TERM WITH ONE PRODUCER OUT OF TWENTY-TWO.
    --
    -- `unlockValue` carries the second-heaviest weight in the scorer and was
    -- set by exactly one provider. It now reads the inverted prerequisite
    -- graph the addon already harvests -- and only that, so a quest nothing
    -- has been observed behind still scores zero.
    ------------------------------------------------------------
    local unlockHarvest = CN:GetModule("Harvest")

    assert(unlockHarvest and unlockHarvest.UnlockCount, "Harvest must publish UnlockCount")

    local store = unlockHarvest.Store()

    store[55100] = { questID = 55100, lastSeen = 1 }
    store[55101] = { questID = 55101, lastSeen = 1, observedRequires = { 55100 } }
    store[55102] = { questID = 55102, lastSeen = 1, observedRequires = { 55100 } }

    -- Named twice by one record is one unlock, not two.
    store[55103] = {
        questID = 55103, lastSeen = 1,
        requires = { 55100 }, observedRequires = { 55100 },
    }

    unlockHarvest.NoteUnlocksChanged()

    assert(unlockHarvest.UnlockCount(55100) == 3,
        "three quests were observed behind it, got "
        .. unlockHarvest.UnlockCount(55100))

    assert(unlockHarvest.UnlockCount(55101) == 0,
        "and nothing was observed behind a leaf")

    -- Through the decorator, which is the path scoring actually takes.
    local objective = { type = CN.objectiveTypes.QUEST, id = 55100 }

    CN.candidateDecorators["Unlocks"](objective)

    assert(objective.unlockValue
        and objective.unlockValue > 0 and objective.unlockValue <= 1,
        "the decorator must stamp a 0..1 unlock value, got "
        .. tostring(objective.unlockValue))

    local leaf = { type = CN.objectiveTypes.QUEST, id = 55101 }

    CN.candidateDecorators["Unlocks"](leaf)

    assert(leaf.unlockValue == nil,
        "and must invent nothing for a quest with no observed followers")

    -- A provider with its own opinion keeps it.
    local owned = { type = CN.objectiveTypes.QUEST, id = 55100, unlockValue = 0.25 }

    CN.candidateDecorators["Unlocks"](owned)

    assert(owned.unlockValue == 0.25,
        "the decorator fills a gap; it does not overrule a provider")

    for id = 55100, 55103 do
        store[id] = nil
    end

    unlockHarvest.NoteUnlocksChanged()

    print("  what a quest unlocks is measured from this account's own play")
end)()

;(function()
    ------------------------------------------------------------
    -- EVICTION BY QUEST ID DELETED EXACTLY WHAT A LEVELLING ALT NEEDS.
    --
    -- The pruneHarvest store dropped its lowest ids on the reasoning that a low id
    -- is old content. That describes a max-level character; it describes the
    -- opposite of an alt levelling through classic zones, whose entire log is
    -- low ids.
    ------------------------------------------------------------
    local pruneHarvest = CN:GetModule("Harvest")

    local store = pruneHarvest.Store()

    local savedCap = pruneHarvest.cap

    for questID in pairs(store) do
        store[questID] = nil
    end

    local savedSlack = pruneHarvest.pruneSlack

    pruneHarvest.cap        = 3
    pruneHarvest.pruneSlack = 1

    -- A low id seen just now, and high ids not seen in a long time.
    store[100]   = { questID = 100,   lastSeen = 9000 }
    store[90001] = { questID = 90001, lastSeen = 10 }
    store[90002] = { questID = 90002, lastSeen = 20 }
    store[90003] = { questID = 90003, lastSeen = 30 }
    store[90004] = { questID = 90004, lastSeen = 40 }

    pruneHarvest.Prune()

    assert(store[100] ~= nil,
        "the quest the player is standing next to must survive eviction")

    assert(store[90001] == nil and store[90002] == nil,
        "and the least recently seen must be the ones that go")

    for questID in pairs(store) do
        store[questID] = nil
    end

    pruneHarvest.cap        = savedCap
    pruneHarvest.pruneSlack = savedSlack

    pruneHarvest.NoteUnlocksChanged()

    print("  the pruneHarvest evicts what has not been seen, not what is oldest")
end)()

;(function()
    ------------------------------------------------------------
    -- A REGISTRY WITH A CLOSED SELECTOR IS NOT A REGISTRY.
    --
    -- `RegisterWaypointProvider` is published, but the only way to CHOOSE a
    -- provider matched three names hardcoded in `SetPreference`. A fourth
    -- provider could be used automatically and never chosen deliberately.
    ------------------------------------------------------------
    local navigation = CN:GetModule("Navigation")

    CN.RegisterWaypointProvider("MutationPin", {
        priority    = 500,
        IsAvailable = function() return true end,
        SetWaypoint = function() return true end,
    })

    local ok, resolved = navigation.SetPreference("mutationpin")

    assert(ok and resolved == "MutationPin",
        "a registered provider must be selectable by name, case-insensitively")

    assert(navigation.Preference() == "MutationPin",
        "and stored under the name the registry uses")

    local offeredHere = false

    for _, name in ipairs(navigation.PreferenceNames()) do
        if name == "MutationPin" then
            offeredHere = true
        end
    end

    assert(offeredHere, "and named in what the command offers")

    assert(not (navigation.SetPreference("nothingatall")),
        "something nobody registered is still refused")

    navigation.SetPreference("auto")

    CN.waypointProviders["MutationPin"] = nil

    for index = #CN.waypointOrder, 1, -1 do
        if CN.waypointOrder[index].name == "MutationPin" then
            table.remove(CN.waypointOrder, index)
        end
    end

    print("  any registered waypoint provider can be chosen, not three names")
end)()

;(function()
    ------------------------------------------------------------
    -- ADDON_LOADED WAS REGISTRABLE AND UNDISPATCHABLE.
    --
    -- It is in the registered-events list and `RegisterEvent` accepts a
    -- handler for it, but the handler returned before `Dispatch`. Anything
    -- registered that way was accepted and silently never called.
    ------------------------------------------------------------
    local loadedFired = 0

    CN:RegisterEvent("ADDON_LOADED", function()
        loadedFired = loadedFired + 1
    end)

    local eventFrame = CN.eventFrame

    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "CompletionNavigator")

    assert(loadedFired == 1,
        "a handler registered for ADDON_LOADED must be called, loadedFired "
        .. loadedFired .. " time(s)")

    -- AND FOR SOMEBODY ELSE'S ADDON, WHICH IS THE ONLY REASON TO WANT IT.
    -- 0.68.0.
    --
    -- This used to assert the opposite. The client loads `Blizzard_TokenUI`,
    -- `Blizzard_Collections` and the rest on demand, and there is no other
    -- announcement that one of those frames now exists -- so a handler that
    -- fires only on OUR load fires at the one moment the frame it is waiting
    -- for is guaranteed absent. 0.67.0 registered exactly such a handler for
    -- the currency panel and it was inert.
    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "Blizzard_TokenUI")

    assert(loadedFired == 2,
        "another addon loading reaches the handler too, loadedFired "
        .. loadedFired .. " time(s)")

    -- The database initialization stays ours alone: running it on somebody
    -- else's load is the opposite mistake.
    local initialised = 0

    local realInit = CN.InitializeDatabase

    CN.InitializeDatabase = function(...)
        initialised = initialised + 1

        return realInit(...)
    end

    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "SomeOtherAddon")

    CN.InitializeDatabase = realInit

    assert(initialised == 0,
        "another addon loading must not re-initialize this addon's database")

    print("  ADDON_LOADED reaches the handlers the registry accepted")
end)()

;(function()
    ------------------------------------------------------------
    -- A MIGRATION THAT FAILED PART-WAY SAID SO ONCE AND CARRIED ON.
    ------------------------------------------------------------
    local saved = CN.migrations[3]

    CN.migrations[3] = function()
        error("deliberate migration failure")
    end

    local migrationDb = { version = 3, account = {}, characters = {} }

    CN.RunMigrations(migrationDb)

    assert(migrationDb.version == 3,
        "a failed migration must not advance the version, got "
        .. tostring(migrationDb.version))

    assert(type(migrationDb.migrationFailure) == "table"
        and migrationDb.migrationFailure.version == 3,
        "and must record WHICH migration failed")

    CN.migrations[3] = saved

    CN.migrationFailure = nil

    -- AND MIGRATION 9 ITSELF, which drops the preference rows the addon could
    -- never have credited.
    local ninth = {
        version = 9,
        account = {},
        characters = {
            ["Main-Realm"] = {
                preference = {
                    QUEST      = { shown = 40, acted = 12 },
                    APPEARANCE = { shown = 300, acted = 0 },
                    RARE       = { shown = 120, acted = 0 },
                },
            },

            -- A row that is not a table at all must not throw.
            ["Broken-Realm"] = true,
        },
    }

    CN.RunMigrations(ninth)

    local kept = ninth.characters["Main-Realm"].preference

    assert(kept.QUEST, "a type the client announces keeps its record")

    assert(not kept.APPEARANCE and not kept.RARE,
        "and rows that could only ever read 0 of N are dropped")

    assert(ninth.version == CN.dbVersion,
        "and the ladder runs to the top, got " .. tostring(ninth.version))

    -- A CORRUPT CHARACTERS TABLE IS A FAULT, NOT A THING TO PAPER OVER.
    --
    -- 0.55.0 replaced it with an empty table, which destroys every character
    -- profile, advances the version, and reports a clean bill of health. The
    -- migration refuses now, and refusing is recorded -- which is recoverable,
    -- because the data is still there.
    local corrupt = { version = 9, account = {}, characters = "not a table" }

    CN.RunMigrations(corrupt)

    assert(corrupt.characters == "not a table",
        "a migration must not silently destroy what it cannot read")

    assert(corrupt.version == 9,
        "and must not claim to have upgraded it, got "
        .. tostring(corrupt.version))

    assert(type(corrupt.migrationFailure) == "table",
        "and must record the refusal where /cn navdiag can find it")

    CN.migrationFailure = nil

    print("  a failed migration is recorded, not just printed once")
end)()

