;(function()
    ------------------------------------------------------------
    -- A COLD SCAN TRIES AGAIN INSTEAD OF LEAVING AN EMPTY TAB FOREVER.
    ------------------------------------------------------------
    local lore = CN:GetModule("Loremaster")

    lore.coldAttempts = 0

    local realProgress = CN.Blizzard.GetAchievementProgress

    CN.Blizzard.GetAchievementProgress = function() return 0, 0 end

    local scheduled = CN_TEST_PendingTimers and CN_TEST_PendingTimers() or 0

    lore.Scan()

    CN.Blizzard.GetAchievementProgress = realProgress

    -- 0.73.0 correctly stopped such a scan recording itself, and left the
    -- player with nothing: the store is no longer EMPTY, so the "no data yet,
    -- running a scan" branch never fires again, and `Closest` filters on
    -- `criteria > 0`, so the tab is blank -- silently, until the next login.
    assert(lore.coldAttempts == 1,
        "a scan that measured nothing counts an attempt")

    assert((CN_TEST_PendingTimers and CN_TEST_PendingTimers() or 0) > scheduled,
        "and schedules another, because the condition is known transient")

    -- AND THE RETRY CHAIN IS NOT ASKED FOREVER.
    lore.coldAttempts = lore.maximumColdAttempts

    local ceiling = CN_TEST_PendingTimers()

    CN.Blizzard.GetAchievementProgress = function() return 0, 0 end

    lore.Scan(true)

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(CN_TEST_PendingTimers() == ceiling,
        "a retry chain that has run its course stops")

    -- BUT A SCAN THE PLAYER ASKED FOR IS A FRESH START. 0.75.0.
    --
    -- 0.74.0 reset the counter only on a scan that measured something, so
    -- three cold scans anywhere in a session -- `/cn setup` at login plus two
    -- presses of "Rescan zones", which is what the addon's own messages tell
    -- the player to do -- left it spent, and every later cold scan scheduled
    -- nothing. The retry died silently at the moment the player started
    -- trying harder.
    lore.coldAttempts = lore.maximumColdAttempts

    local beforeAsking = CN_TEST_PendingTimers()

    CN.Blizzard.GetAchievementProgress = function() return 0, 0 end

    lore.Scan()

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(CN_TEST_PendingTimers() > beforeAsking,
        "a scan the player asked for still gets its retry, however many the "
        .. "session has already spent")

    -- A SUCCESSFUL SCAN CLEARS THE COUNT, so a cold login does not spend
    -- the whole session's retries and leave a later one with none.
    lore.coldAttempts = lore.maximumColdAttempts

    lore.Scan()

    assert(lore.coldAttempts == 0,
        "a scan that worked clears the count: " .. lore.coldAttempts)

    local afterGood = CN_TEST_PendingTimers()

    CN.Blizzard.GetAchievementProgress = function() return 0, 0 end

    lore.Scan()

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(CN_TEST_PendingTimers() > afterGood,
        "so a cold scan later in the session still gets its retry")

    lore.coldAttempts = 0
    lore.Scan()

    -- AND WHEN IT SUCCEEDS IT SAYS WHAT IT READ, not what it walked past.
    --
    -- The same mistake fixed at `/cn scanlore` in 0.72.0 and at the Rescan
    -- button in 0.74.0, in a third place one release later: a retry against a
    -- half-warm client that read 40 of 412 announced "412".
    lore.coldAttempts = 0

    CN.Blizzard.GetAchievementProgress = function() return 0, 0 end

    lore.Scan()

    CN.Blizzard.GetAchievementProgress = realProgress

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(chatFrame, message)
        table.insert(spoken, tostring(message))

        return realAdd(chatFrame, message)
    end

    -- ONE ROW THE CLIENT STILL WILL NOT ANSWER FOR, so reached and measured
    -- differ. Without that the two numbers are equal and the assertion below
    -- cannot fail.
    local quietRow = next(lore.Records())

    CN.Blizzard.GetAchievementProgress = function(id, ...)
        if id == quietRow then
            return 0, 0
        end

        return realProgress(id, ...)
    end

    CN_TEST_DrainDeferred()

    CN.Blizzard.GetAchievementProgress = realProgress
    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local announced

    for _, line in ipairs(spoken) do
        if string.find(line, "Zone progress read", 1, true) then
            announced = line
        end
    end

    assert(announced, "the successful retry announces itself")

    local reached = CN.CountKeys(lore.Records())

    assert(string.find(announced, tostring(reached - 1) .. " of ", 1, true)
        and not string.find(announced,
            "read: " .. tostring(reached) .. " of", 1, true),
        "and it leads with what it READ, not with what it walked past: "
        .. announced)

    print("  a scan the game was not ready for tries again, a bounded number "
        .. "of times")
end)()

