'@

$Embedded['bench.lua'] = @'
-- Benchmark: loads the addon through the harness stubs, then inflates the
-- collection stores to retail scale and times the recommendation path.
--
-- Run:  lua5.4 bench.lua build/CompletionNavigator

local ROOT = arg[1] or "build/CompletionNavigator"

-- Read BEFORE `arg` is rewritten for the harness below, which replaces the
-- whole table and would otherwise take the flag with it. The budget block at
-- the end of this file therefore saw no arguments and silently did nothing --
-- a check that cannot fail because it never runs.
local ENFORCE_BUDGETS = false

-- Kept, because `arg` is replaced wholesale below for the harness.
BENCH_ARGS = {}

for _, argument in ipairs(arg) do
    table.insert(BENCH_ARGS, argument)
end

for _, argument in ipairs(arg) do
    if argument == "--budget" then
        ENFORCE_BUDGETS = true
    end
end

-- Silence the harness's own output while it loads and self-tests.
local realPrint = print
_G.print = function() end

CN_BENCH = true
arg = { ROOT }
dofile("harness.lua")

_G.print = realPrint

local CN = _G.CompletionNavigator
local db = _G.CompletionNavigatorDB

------------------------------------------------------------
-- RETAIL-SCALE DATA
------------------------------------------------------------

-- Approximate live retail counts.
local N_PETS         = 1800
local N_MOUNTS       = 900
local N_TOYS         = 600
local N_ACHIEVEMENTS = 3000
local N_FACTIONS     = 500
local N_RECIPES      = 2500
local N_VENDOR_ITEMS = 400

local pets = CN.Account('pets')
for i = 1, N_PETS do
    -- No name: the client's journal has it. Keeping the fixture in step with
    -- what the addon actually writes is the whole point of measuring.
    pets[10000 + i] = {
        speciesID = 10000 + i,
        collected = (i % 3 == 0),
        obtainable = true,
        isWild = (i % 5 == 0),
        count = 0, limit = 3,
    }
end

local achievements = CN.Account('achievements')
for i = 1, N_ACHIEVEMENTS do
    local criteria = 1 + (i % 12)
    achievements[20000 + i] = {
        achievementID = 20000 + i,
        criteria = criteria,
        done = math.max(0, criteria - (i % 4)),
        points = 10,
    }
end

local reputations = CN.Account('reputations')
for i = 1, N_FACTIONS do
    reputations[30000 + i] = {
        factionID = 30000 + i,
        name = "Faction " .. i,
        standing = 4,
        accountWide = (i % 2 == 0),
    }
end

local recipeNames = CN.Account('recipeNames')
for i = 1, N_RECIPES do
    recipeNames[40000 + i] = "Recipe " .. i
end

local vendorStore = CN.Account('vendors')
for v = 1, 20 do
    local items = {}
    for i = 1, N_VENDOR_ITEMS do
        -- A NUMBER, matching what the addon actually writes: the price, not
        -- a table holding it. Keeping the fixture in step with the real shape
        -- is the whole point of measuring.
        items[40000 + ((v * 100 + i) % N_RECIPES)] = 1
    end
    vendorStore[60000 + v] = {
        npcID = 60000 + v, name = "Vendor " .. v, items = items,
        itemCount = N_VENDOR_ITEMS, mapID = 94, x = 0.5, y = 0.5, zone = "Bench Zone",
    }
end

------------------------------------------------------------
-- TIMING
------------------------------------------------------------

-- MEASUREMENTS, KEPT.
--
-- The benchmark printed numbers and threw them away, so a regression was only
-- caught by somebody reading the output and remembering what it used to say.
-- Nobody remembers. Recording them means CI can fail on one.
CN_BENCH_RESULTS = {}

local function bench(label, iterations, fn)
    -- Warm up, so the first-call cost of building any lazy index is not
    -- charged to the measurement.
    fn()

    local started = os.clock()
    for _ = 1, iterations do fn() end
    local elapsed = (os.clock() - started) * 1000

    local perCall = elapsed / iterations

    print(string.format("  %-38s %8.3f ms/call  (%d iterations)",
        label, perCall, iterations))

    CN_BENCH_RESULTS[label] = perCall

    return perCall
end

print("\nData scale:")
local function count(t) local n = 0 for _ in pairs(t) do n = n + 1 end return n end
print("  pets         = " .. count(CN.Account('pets')))
print("  achievements = " .. count(CN.Account('achievements')))
print("  reputations  = " .. count(CN.Account('reputations')))
print("  recipes      = " .. count(CN.Account('recipeNames')))
print("  vendors      = " .. count(CN.Account('vendors')))

print("\nCold rebuild (cache forced, what an invalidating event costs):")
bench("CollectCandidates(force)", 20, function()
    CN.CollectCandidates(true)
end)

print("\nWarm path (what a tooltip hover or UI refresh costs):")
bench("CollectCandidates()", 2000, function()
    CN.CollectCandidates()
end)
bench("Recommend(1)", 200, function()
    CN.Recommend(1)
end)
bench("Recommend(25)", 200, function()
    CN.Recommend(25)
end)

-- AND THE BRANCH THAT ACTUALLY RUNS WHILE PLAYING.
--
-- The two above measure the cache hit, which is 0.008 ms and cannot fail any
-- budget worth writing. The ranked list is invalidated by anything that
-- changes the ORDER without changing a candidate -- entering combat, a
-- faction standing moving, a goal being pinned -- and until 0.57.0 it was
-- invalidated by every zone route build, which the Zone tab does every two
-- seconds. The cold branch is the one that costs 1.4 ms, and no budget in
-- this file was measuring it.
print("\nCold path (what a re-rank costs when the order has changed):")
bench("Recommend(1) after a re-rank", 100, function()
    CN.InvalidateRanking()
    CN.Recommend(1)
end)
bench("Recommend(25) after a re-rank", 100, function()
    CN.InvalidateRanking()
    CN.Recommend(25)
end)

print("\nCandidates produced: " .. #CN.CollectCandidates(true))

-- THE PER-PROVIDER FIGURES WERE AVERAGED OVER THE WHOLE RUN. 0.61.0.
--
-- `CN.providerTimings` accumulates for the life of the session and nothing
-- reset it, so by the time this block ran every provider had been called by
-- each of the benchmarks above -- most of them on a warm cache, at a fraction
-- of a millisecond. Dividing the total by that call count buried the cold
-- cost this table exists to expose: the Pets provider read 0.56 ms here and
-- 4.53 ms when measured alone, understating by eight times.
--
-- Reset, then ONE cold collection, then read. What the table then holds is
-- what one provider costs when it actually has to do its work, which is the
-- only figure worth putting a budget on.
for name in pairs(CN.providerTimings) do
    CN.providerTimings[name] = nil
end

CN.InvalidateCandidates("bench:per-provider")
CN.CollectCandidates(true)

print("\nPer-provider, slowest first (one cold rebuild, not an average):")
local rows = {}
for name, timing in pairs(CN.providerTimings) do
    if (timing.calls or 0) > 0 then
        table.insert(rows, { name = name, avg = timing.total / timing.calls })
    end
end
table.sort(rows, function(a, b) return a.avg > b.avg end)
for _, row in ipairs(rows) do
    print(string.format("  %-16s %8.3f ms", row.name, row.avg))
end

print("\nSingle-event invalidation (what actually happens while playing):")

local function fireEvent(event)
    for _, handler in ipairs(CN.eventTable[event] or {}) do
        handler(event)
    end
end

for _, event in ipairs({
    "QUEST_LOG_UPDATE",
    "NEW_PET_ADDED",
    "CRITERIA_UPDATE",
    "UPDATE_FACTION",
    "NEW_MOUNT_ADDED",
}) do
    CN.CollectCandidates()
    bench(event, 20, function()
        fireEvent(event)
        CN.Recommend(1)
    end)
end

print("\nFilter cost (ignored/deferred lists are empty here, the common case):")
bench("IsIgnored + IsDeferred x 10000", 20, function()
    for i = 1, 10000 do
        CN.IsIgnored("PET", i)
        CN.IsDeferred("PET", i)
    end
end)

------------------------------------------------------------
-- UI REFRESH
------------------------------------------------------------
--
-- The path that runs while the window is open, which had never been measured.

print("\nUI refresh (what an open window costs):")

do
    local goals = CN:GetModule("Goals")
    local chase = CN:GetModule("Chase")

    if goals and chase then
        goals.Clear()

        for index = 1, 8 do
            goals.Add(CN.objectiveTypes.ACHIEVEMENT, 10 + (index % 4))
        end

        bench("Chase.All() with 8 goals", 50, function()
            chase.All()
        end)

        goals.Clear()
    end

    local alts = CN:GetModule("Alts")

    if alts then
        bench("Alts.Verdict()", 50, function()
            alts.Verdict()
        end)
    end

    local progress = CN:GetModule("Progress")

    if progress then
        bench("Progress.Summary() (12k completed quests)", 50, function()
            progress.Summary()
        end)

        -- QUEST_LOG_UPDATE fires many times a second during normal play. If
        -- it invalidates the cache, the cache does nothing and this number
        -- goes straight back to the uncached one.
        bench("Summary under a chatty QUEST_LOG_UPDATE", 50, function()
            for _, handler in ipairs(CN.eventTable["QUEST_LOG_UPDATE"] or {}) do
                handler("QUEST_LOG_UPDATE")
            end

            progress.Summary()
        end)
    end
end

------------------------------------------------------------
-- SAVEDVARIABLES SIZE
------------------------------------------------------------
--
-- The client rewrites this entire file on every logout. Nobody had ever
-- measured how big this addon makes it.

print("\nSavedVariables (rewritten in full on every logout):")

local function measure(value, seen)
    seen = seen or {}

    if type(value) == "table" then
        if seen[value] then return 0 end
        seen[value] = true

        local bytes = 8

        for k, v in pairs(value) do
            bytes = bytes + measure(k, seen) + measure(v, seen) + 4
        end

        return bytes
    end

    if type(value) == "string" then return #value + 2 end
    if type(value) == "number" then return 8 end

    return 4
end

local total = measure(CompletionNavigatorDB)

local sections = {}

for section, contents in pairs(CompletionNavigatorDB.account or {}) do
    local bytes = measure(contents)

    if bytes > 200 then
        table.insert(sections, {
            name  = section,
            bytes = bytes,
            count = CN.CountKeys(contents),
        })
    end
end

table.sort(sections, function(a, b) return a.bytes > b.bytes end)

print(string.format("  TOTAL %s", string.format("%.1f KB", total / 1024)))

for _, row in ipairs(sections) do
    print(string.format("  %-22s %8.1f KB  (%d rows)",
        row.name, row.bytes / 1024, row.count))
end

------------------------------------------------------------
-- TOOLTIPS
------------------------------------------------------------
--
-- The hottest path in the addon: every mouseover in the game, in bags, in the
-- auction house, on a vendor's entire inventory. Never measured until now.

print("\nTooltip cost (runs on every mouseover):")

do
    local tooltips = CN:GetModule("Tooltips")

    if tooltips then
        -- An ordinary item: not a toy, not a mount, not a recipe. The common
        -- case, and the one that falls through every check.
        bench("ItemLines on an ordinary item", 200, function()
            tooltips.ItemLines(123456, "Some Ordinary Item")
        end)

        bench("ItemLines with no name supplied", 200, function()
            tooltips.ItemLines(123457)
        end)
    end
end

------------------------------------------------------------
-- BENCH: A REAL FLIGHT NETWORK
------------------------------------------------------------

-- The harness fixture clusters its sixty flight points into a far corner so
-- that the suite's travel assertions keep their answers -- a spread network
-- starts winning journeys the tests assert are quicker on foot, and weakening
-- an assertion to suit a benchmark is how a suite stops checking.
--
-- That was fine while the flight leg was a straight line. It stopped being
-- fine when the pair search gained a pruning bound, because a corner cluster
-- is exactly the geometry that bound rejects unexamined: ONE origin of
-- fifty-nine survived with the cluster, against seventeen of sixty on a real
-- continent. So the benchmark was measuring a square the prune never walks,
-- and it reported both travel budgets at a fifth of their ceiling while a
-- realistic network was over both of them.
--
-- The assertions have run by this point. Spread the same nodes over the map
-- and throw the derived caches away, and every number below is about a
-- continent instead of a corner.
do
    local nodes = CN_TEST_TAXI_NODES and CN_TEST_TAXI_NODES[1941]

    if nodes then
        for index = 4, #nodes do
            nodes[index].position = {
                x = 0.05 + (((index * 7) % 23) * 0.040),
                y = 0.05 + (((index * 11) % 19) * 0.048),
            }
        end
    end

    local travel = CN:GetModule("Travel")

    if travel and travel.ForgetNodes then
        travel.ForgetNodes()
        travel.ForgetWorldPoints()
    end

    CN.InvalidateCandidates()
end

print("\nThe paths a player triggers without meaning to:")

do
    local mapID, x, y = CN.GetPlayerPosition()

    -- FORCED, because 0.57.0's route cache would otherwise make this measure
    -- a table lookup. A budget that measures the cached branch of the path it
    -- is guarding is a budget that guards nothing -- which is the reasoning
    -- this file already applies to `UI.Refresh`, and which four of these
    -- budgets were failing in 0.56.0.
    bench("BuildZoneRoute()", 50, function()
        CN.ForgetRoutes()
        CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)
    end)

    -- AND THE SAME CALL WITH THE ROUTE ALREADY BUILT, which is what the Zone
    -- tab's two-second refresh and follow mode's ticker actually do.
    bench("BuildZoneRoute() unchanged", 500, function()
        CN.BuildZoneRoute(mapID, x or 0.5, y or 0.5)
    end)

    -- THE ROUTE OPTIMISER, ON ITS OWN, AT THE SIZE A BUSY ZONE PRODUCES.
    --
    -- `BuildZoneRoute` above is measured against whatever the fixture happens
    -- to place in the player's zone, which is a handful of stops. The 2-opt
    -- pass is quadratic in stops and was, until 0.54.0, quadratic in
    -- ALLOCATIONS too -- so at thirty to fifty stops, which is an ordinary
    -- evening with a full quest log plus rares and treasures, one call cost
    -- thirty-three milliseconds and produced megabytes of garbage. It runs
    -- every two seconds while the Zone tab is open.
    --
    -- Measured directly, at a size the fixture cannot reach on its own.
    -- NINETY, NOT FORTY.
    --
    -- Forty was chosen before the clustering was measured against a real
    -- zone. A hundred and sixty located objectives -- a full quest log plus
    -- rares and treasures, which is an ordinary evening -- cluster to about
    -- ninety hubs, and this is quadratic in hubs: measured at 3.70 ms, past
    -- its own 3.0 ms budget, and 72% of the whole route build. A budget the
    -- benchmark cannot reach is a budget that guards nothing, which is the
    -- reasoning this file already applies to `UI.Refresh`.
    local stops = {}

    for index = 1, 90 do
        table.insert(stops, {
            name  = "Stop " .. index,
            mapID = 94,
            x     = 0.05 + (((index * 13) % 29) * 0.031),
            y     = 0.05 + (((index * 17) % 31) * 0.029),
        })
    end

    CN.UseRouteMapScale(94)

    bench("ImproveRoute() over 90 stops", 50, function()
        local copy = {}

        for index = 1, #stops do
            copy[index] = stops[index]
        end

        CN.ImproveRoute(copy, 0.5, 0.5)
    end)

    -- And the clustering that produces those stops, which was quadratic in
    -- objectives with a module lookup and a square root inside the inner
    -- loop.
    local located = {}

    for index = 1, 110 do
        table.insert(located, {
            name  = "Objective " .. index,
            mapID = 94,
            x     = 0.03 + (((index * 19) % 37) * 0.026),
            y     = 0.03 + (((index * 23) % 41) * 0.023),
        })
    end

    bench("ClusterByProximity() over 110 objectives", 50, function()
        CN.ClusterByProximity(located)
    end)

    -- NOT UI.Refresh: it returns immediately unless the window is genuinely
    -- shown, and the harness's frames are not. Measuring it produced a
    -- confident 0.000 ms for a function that never ran -- a budget that
    -- cannot fail is a budget that guards nothing.
    --
    -- Chase.All() below is the real cost of an open window, and it does run.
end

print("\nCosting a journey (every objective with a location pays this):")

do
    local travel = CN:GetModule("Travel")

    if travel and travel.EstimateSeconds then
        local nodes = travel.KnownNodes(94) or {}

        print("  flight points known on this continent: " .. #nodes)

        -- THE NUMBER THAT MATTERS IS THE SQUARE OF THAT ONE.
        --
        -- The pair search is deliberately exhaustive -- nearest-to-you and
        -- nearest-to-target are often not the best route together -- and that
        -- is the right call. It was measured against three nodes.
        bench("EstimateSeconds() across a zone", 200, function()
            travel.EstimateSeconds(94, 0.10, 0.10, 94, 0.90, 0.90)
        end)

        bench("CostFor() as the scorer calls it", 200, function()
            travel.CostFor(94, 0.90, 0.90)
        end)
    end
end

------------------------------------------------------------
-- BUDGETS
------------------------------------------------------------

-- WHY THESE ARE ASSERTIONS AND NOT A REPORT.
--
-- Two performance regressions have shipped in this project's history, and
-- both were visible in this file's output at the time. Printing a number that
-- somebody has to compare against a number they remember is not a check; it
-- is a document nobody reads.
--
-- The figures are ceilings with real headroom -- roughly three times the
-- measured cost -- because a budget that fails on noise gets disabled within
-- a fortnight, and a disabled budget catches nothing at all.
--
-- Run with: lua5.4 bench.lua <tree> --budget
local BUDGETS = {
    ["CollectCandidates(force)"]  = 20.0,
    ["CollectCandidates()"]       = 0.05,
    ["Recommend(1)"]              = 0.10,
    ["Recommend(25)"]             = 0.40,

    -- The branch that runs when the order has actually changed. Generous
    -- against the 1.4 ms it was measured at before 0.57.0's sort fix, and
    -- tight enough that a regression in the scoring pass shows up here rather
    -- than in a player's frame rate.
    ["Recommend(1) after a re-rank"]  = 2.5,
    ["Recommend(25) after a re-rank"] = 2.5,
    ["ItemLines on an ordinary item"] = 0.05,

    -- Added in 0.44.0. The two paths a player triggers most often without
    -- meaning to: opening the window, and the router recomputing because they
    -- walked into a new zone.
    ["BuildZoneRoute()"]          = 8.0,
    ["BuildZoneRoute() unchanged"] = 0.05,
    ["Chase.All() with 8 goals"]  = 5.0,

    -- Added in 0.46.0, and the reason the rebuild ceiling above is now
    -- meaningful. Every objective with a location pays this, so it multiplies
    -- by the candidate count -- which is how 1.5 ms per call became eleven
    -- milliseconds of rebuild without anything looking slow.
    ["EstimateSeconds() across a zone"] = 0.25,
    ["CostFor() as the scorer calls it"] = 0.25,

    -- Added in 0.54.0, and both of them were over a hundred times their
    -- eventual measured cost before that release. The fixture could not
    -- reach the size at which either mattered, so neither had a budget and
    -- neither was measured -- which is how a thirty-three millisecond stutter
    -- lived in the file a player watches while walking.
    -- 2-opt is quadratic in stops and every comparison needs four real
    -- distances, so ninety stops is genuinely expensive. 0.57.0 got it under
    -- six by skipping work with don't-look bits, and those turned out not to
    -- be exact -- 41 of 60 ninety-stop routes came out LONGER. Correct and
    -- slower is the right trade; the cost is paid once per route now rather
    -- than on every two-second refresh (see `routeCache`).
    ["ImproveRoute() over 90 stops"] = 8.0,
    ["ClusterByProximity() over 110 objectives"] = 3.0,
}

if ENFORCE_BUDGETS then
    print("\nBudgets:")

    local failed = 0

    for label, ceiling in pairs(BUDGETS) do
        local measured = CN_BENCH_RESULTS[label]

        if not measured then
            print(string.format("  MISSING  %-38s (never measured)", label))

            failed = failed + 1
        elseif measured <= 0 then
            -- A ZERO IS NOT A PASS.
            --
            -- "UI refresh: 0.000 ms" meant the window was not open and the
            -- function returned immediately -- a budget that can never fail
            -- because the thing it guards never ran. That is the same shape
            -- as a vacuous test, and it gets the same treatment: reported,
            -- not counted as a success.
            print(string.format("  NOT RUN  %-38s (measured 0 -- the path did "
                .. "not execute)", label))

            failed = failed + 1
        elseif measured > ceiling then
            print(string.format("  OVER     %-38s %.3f ms > %.3f ms",
                label, measured, ceiling))

            failed = failed + 1
        else
            print(string.format("  ok       %-38s %.3f ms of %.3f ms",
                label, measured, ceiling))
        end
    end

    if failed > 0 then
        print("\n" .. failed .. " budget(s) exceeded.")

        os.exit(1)
    end

    print("\nEvery measured path is inside its budget.")
end

------------------------------------------------------------
-- HISTORY
------------------------------------------------------------

-- BUDGETS CATCH A CLIFF. THEY DO NOT CATCH A SLOPE.
--
-- A ceiling with threefold headroom is the right shape for a gate: it fails
-- on a regression and not on runner noise. It is exactly the wrong shape for
-- noticing that the cold rebuild has crept from 3.9ms to 6.2ms across eight
-- releases, each step small enough to be invisible and the total large enough
-- to matter -- which is what actually happened between 0.36.0 and 0.44.0.
--
-- So: append every run to a file, one line per measurement, with the version.
-- No analysis and no thresholds; a file somebody can look at, sorted by the
-- thing that changed. `--history` writes it; nothing reads it automatically,
-- because a trend needs a person.
local writingHistory = false

for _, argument in ipairs(BENCH_ARGS) do
    if argument == "--history" then
        writingHistory = true
    end
end

if writingHistory then
    local path = "bench-history.tsv"

    local existing = io.open(path, "r")

    local needsHeader = existing == nil

    if existing then
        existing:close()
    end

    local handle = io.open(path, "a")

    if handle then
        if needsHeader then
            handle:write("version\tmeasurement\tms\n")
        end

        local labels = {}

        for label in pairs(CN_BENCH_RESULTS) do
            table.insert(labels, label)
        end

        table.sort(labels)

        for _, label in ipairs(labels) do
            handle:write(string.format("%s\t%s\t%.4f\n",
                CN.version, label, CN_BENCH_RESULTS[label]))
        end

        handle:close()

        print("\nAppended " .. #labels .. " measurements to " .. path .. ".")
    end
end
'@

$Embedded['coverage.sh'] = @'
#!/bin/bash
# Coverage over the offline harness.
#
# IMPORTANT: this script must NEVER block a release.
#
# It once did. It hardcoded the luacov path from the author's machine
# (/usr/local/share/lua/5.1), so on any host where luarocks installed luacov
# somewhere else the script died under `set -e` with no output at all -- and
# because it ran in CI ahead of the packager, the whole release silently
# stopped. A quality signal for the author is not a reason to deny users a
# build.
#
# So: locate luacov rather than assume it, and when it genuinely cannot run,
# say so clearly and exit 0.

ROOT=${1:-build/CompletionNavigator}
FLOOR=${2:-80}

note() { echo "coverage: $*"; }

if [ ! -f "$ROOT/CompletionNavigator.toc" ]; then
  note "no addon tree at '$ROOT'; skipping."
  exit 0
fi

if [ ! -f harness.lua ]; then
  note "harness.lua not found; skipping."
  exit 0
fi

# Find luacov wherever this machine put it. luacov is pure Lua, so any
# version's install directory works under any Lua interpreter.
LUACOV_PATH=""

# Ask luarocks first. It knows where it installed things, which a hardcoded
# list of directories does not -- and a workspace-local rocks tree (which is
# what CI now uses, having abandoned apt) appears in none of the usual places.
if command -v luarocks >/dev/null 2>&1; then
  ROCKS_PATH=$(luarocks path --lr-path 2>/dev/null)
  [ -n "$ROCKS_PATH" ] && LUACOV_PATH="${ROCKS_PATH};${LUACOV_PATH}"
fi

for base in /usr/local/share/lua /usr/share/lua "$HOME/.luarocks/share/lua"; do
  [ -d "$base" ] || continue

  for versioned in "$base"/*; do
    if [ -f "$versioned/luacov.lua" ] || [ -d "$versioned/luacov" ]; then
      LUACOV_PATH="$versioned/?.lua;$versioned/?/init.lua;$LUACOV_PATH"
    fi
  done
done

if [ -z "$LUACOV_PATH" ]; then
  note "luacov is not installed; skipping coverage."
  note "install it with:  luarocks install luacov"
  exit 0
fi

export LUA_PATH="${LUACOV_PATH};;"

# Confirm it actually loads before relying on it.
if ! lua5.4 -e 'require("luacov.runner")' >/dev/null 2>&1; then
  note "luacov was found but will not load; skipping coverage."
  exit 0
fi

cat > .luacov <<CONFIG
statsfile = "luacov.stats.out"
reportfile = "luacov.report.out"
include = { "${ROOT}/.*" }
exclude = { "harness", "bench", "luacov", "^%./%.", "/%.lua/", "%.luarocks" }
CONFIG

rm -f luacov.stats.out luacov.report.out

lua5.4 -lluacov harness.lua "$ROOT" > /dev/null 2>&1

lua5.4 -e 'require("luacov.reporter").report()' > /dev/null 2>&1

if [ ! -f luacov.report.out ]; then
  note "no report was produced; skipping."
  exit 0
fi

TOTAL=$(grep -E "^Total" luacov.report.out | awk '{print $NF}' | tr -d '%')

if [ -z "$TOTAL" ]; then
  note "report contained no total; skipping."
  exit 0
fi

# The report lists every file twice: once with per-line detail, once in the
# summary table. Only the summary rows have four columns.
echo "Coverage by file, weakest first:"
awk 'NF==4 && $1 ~ /\.lua$/ { gsub(/%/,"",$4); printf "  %6.2f%%  %s\n", $4, $1 }' \
  luacov.report.out | sort -n | head -8

echo ""
echo "Total: ${TOTAL}%"

# Compared as integers: bash cannot do floating point, and a floor is a floor.
if [ "${TOTAL%.*}" -lt "$FLOOR" ]; then
  echo "FAIL: coverage ${TOTAL}% is below the ${FLOOR}% floor"
  exit 1
fi

echo "Above the ${FLOOR}% floor."
'@

$Embedded['pstest.sh'] = @'
#!/bin/bash
# End-to-end test of cn.ps1 against a real PowerShell host and a real git
# remote. This is what was missing when a broken release path shipped.
set -e
PWSH=/opt/pwsh/pwsh
SRC=/home/claude/cn/out/cn.ps1
WORK=$(mktemp -d)
REMOTE=$(mktemp -d)/remote.git
VERSION=$(grep -oP 'ToolkitVersion = .\K[0-9.]+' "$SRC" | head -1)

echo "Toolkit version: $VERSION"

$PWSH -NoProfile -Command "
\$e=\$null;\$t=\$null
[System.Management.Automation.Language.Parser]::ParseFile('$SRC',[ref]\$t,[ref]\$e)|Out-Null
if(\$e){\$e|%{Write-Host (\"line {0}: {1}\" -f \$_.Extent.StartLineNumber,\$_.Message)};exit 1}
Write-Host '  parse ok'"

cp "$SRC" "$WORK/cn.ps1"
cd "$WORK"

echo "  init"
$PWSH -NoProfile -File ./cn.ps1 init > init.log 2>&1
FILES=$(grep -cE "wrote  .*\.lua$" init.log)
echo "    $FILES lua files scaffolded"
# Count the ORDER list specifically, not every quoted .lua string in gen.py.
# Grepping the whole file counted names that appear elsewhere in it and made
# this check fail for a reason that had nothing to do with the scaffold.
EXPECTED=$(python3 -c "
import re
text = open('/home/claude/cn/gen.py').read()
block = re.search(r'^ORDER = \[(.*?)^\]', text, re.S | re.M).group(1)
print(len(re.findall(r'\"[^\"]+\.lua\"', block)))
")
[ "$FILES" -eq "$EXPECTED" ] || { echo "FAIL: expected $EXPECTED lua files, scaffolded $FILES"; exit 1; }

# The .toc must list only what the CLIENT loads. harness.lua stubs the whole
# client API; listing it would replace live functions with fakes in game.
grep -q 'harness.lua' CompletionNavigator.toc && { echo "FAIL: harness.lua is in the .toc"; exit 1; }
grep -q 'bench.lua'   CompletionNavigator.toc && { echo "FAIL: bench.lua is in the .toc"; exit 1; }
[ -f harness.lua ] || { echo "FAIL: harness.lua was not scaffolded"; exit 1; }
echo "    test tooling present and excluded from the .toc"
[ -f Media/Logo.tga ] || { echo "FAIL: Media/Logo.tga not scaffolded"; exit 1; }

echo "  check"
$PWSH -NoProfile -File ./cn.ps1 check > check.log 2>&1
grep -q "All checks passed" check.log || { echo "FAIL: fresh scaffold does not pass check"; cat check.log; exit 1; }

echo "  the release workflow's own steps, run here"
# FOUR RELEASES WERE TAGGED, PUSHED, AND NEVER PUBLISHED.
#
# Each died at a different workflow step, and each was reproducible in seconds
# on this machine. Everything below ran EQUIVALENTS -- luacheck against the
# build tree, the harness against the build tree -- while the runner runs
# `luacheck .` and `lua5.4 harness.lua .` against a scaffolded tree from the
# repository root. That difference is where all four failures lived.
#
# cisim.sh extracts each `run:` block from the workflow and executes it. It is
# run here so that no release can be cut without the workflow having been
# executed at least once against the tree being released.
if [ -x /home/claude/cn/cisim.sh ]; then
  /home/claude/cn/cisim.sh "$SRC" > cisim.log 2>&1 \
    || { echo "FAIL: a workflow step fails; this release would not publish"; tail -30 cisim.log; exit 1; }
  echo "    $(grep -c 'ok    ' cisim.log) workflow steps executed against a scaffolded tree"
fi

echo "  a captured fixture is loadable Lua"
# EVERY RECORDING THIS COMMAND EVER WROTE WAS MALFORMED.
#
# Get-CNLuaBlock returns the INTERIOR of a block -- correct for its other two
# callers -- and the fixtures writer emitted `return ` followed by that, so
# every captured.lua began `return` then a bare `["worldPosition"] = {`. It
# never loaded. The harness treated an unparseable file exactly like a missing
# one, printed "no recording present", and passed; `check` reported a
# recording was backing the audit because it only regex-scanned the text. The
# strongest test in this project had never once run.
cat > svcapture.sv <<'SAVEDVARS'
CompletionNavigatorDB = {
	["account"] = {
		["capture"] = {
			["build"] = "9.9.9",
			["interface"] = 120100,
			["worldPosition"] = {
				["continentID"] = 2444,
				["hasGetXY"] = true,
			},
			["events"] = {
				["accepted"] = 40,
				["refused"] = {},
			},
		},
	},
}
SAVEDVARS

$PWSH -NoProfile -File ./cn.ps1 fixtures svcapture.sv > fixwrite.log 2>&1
grep -q "wrote  fixtures" fixwrite.log \
  || { echo "FAIL: fixtures did not write a recording"; cat fixwrite.log; exit 1; }

lua5.4 -e 'local f, e = loadfile("fixtures/captured.lua"); if not f then error(e) end; local t = f(); assert(type(t) == "table", "a recording must be a table"); assert(t.interface == 120100, "and must carry what was captured")' \
  || { echo "FAIL: the recording cn.ps1 fixtures wrote is not loadable Lua"; head -12 fixtures/captured.lua; exit 1; }

$PWSH -NoProfile -File ./cn.ps1 check > fixcheck2.log 2>&1
grep -q "All checks passed" fixcheck2.log \
  || { echo "FAIL: check rejects a recording this toolkit just wrote"; cat fixcheck2.log; exit 1; }

rm -rf fixtures svcapture.sv
echo "    written, loadable, and accepted by check"

echo "  a string with no translation anywhere blocks the release"
# THE NOTE THAT PRINTED FOR FOUR RELEASES AND WAS SCROLLED PAST.
#
# "1 of 46 strings have no translation in any locale" appeared in every check
# from 0.45.0 onward. It was true -- "Stop %d of %d cleared" was added to the
# canonical key list and never handed to a translator -- and being a note, it
# was ignored every single time, including by the person who wrote the string.
cp Locales/enUS.lua Locales/enUS.bak
python3 - <<'EOF'
# ANCHORED ON A KEY THAT IS ASSERTED TO EXIST.
#
# This anchored on "cleared", which 0.52.0 removed from the canonical list --
# so the insertion silently did nothing and the test failed reporting that the
# lint was broken. A probe that can no-op is a probe that can pass for the
# wrong reason; this one refuses rather than pretending.
p = 'Locales/enUS.lua'
s = open(p, encoding='utf-8').read()
anchor = '    "ahead",'
assert anchor in s, "the probe anchor is gone from Locales/enUS.lua"
s = s.replace(anchor, anchor + '\n    "untranslated probe",', 1)
open(p, 'w', encoding='utf-8').write(s)
EOF
$PWSH -NoProfile -File ./cn.ps1 check 2>&1 | grep -q 'no translation in ANY locale' \
  || { echo "FAIL: an untranslated string must block the release"; exit 1; }
$PWSH -NoProfile -File ./cn.ps1 check 2>&1 | grep -q '"untranslated probe"' \
  || { echo "FAIL: and it must say WHICH string"; exit 1; }

# A duplicate in the canonical list makes every count reported against it wrong.
cp Locales/enUS.bak Locales/enUS.lua
python3 - <<'EOF'
p = 'Locales/enUS.lua'
s = open(p, encoding='utf-8').read()
anchor = '    "ahead",'
assert anchor in s, "the probe anchor is gone from Locales/enUS.lua"
s = s.replace(anchor, anchor + '\n    "ahead",', 1)
open(p, 'w', encoding='utf-8').write(s)
EOF
$PWSH -NoProfile -File ./cn.ps1 check 2>&1 | grep -q 'more than once' \
  || { echo "FAIL: a duplicated canonical key must block the release"; exit 1; }

mv Locales/enUS.bak Locales/enUS.lua
$PWSH -NoProfile -File ./cn.ps1 check > localecheck.log 2>&1
grep -q "All checks passed" localecheck.log \
  || { echo "FAIL: the shipped locales do not pass their own lint"; cat localecheck.log; exit 1; }
echo "    named, blocking, and the shipped locales are complete"

echo "  four lists of what counts as addon source, agreeing"
# THE FAILURE THAT COST THREE RELEASES.
#
# `cn.ps1 fixtures` writes fixtures/captured.lua -- a recording of a live
# client, read only by the harness. Three separate things decide which .lua
# files are addon source: Get-CNLuaFiles in this toolkit, the find expression
# in the CI workflow, and .pkgmeta's ignore list. 0.47.0 taught the first one
# about fixtures/ and left the other two alone, so every build from that point
# failed at "Verify the .toc lists every Lua file" -- before the packager --
# while `release` printed that it had uploaded to CurseForge.
mkdir -p fixtures
printf 'return { interface = 120100 }\n' > fixtures/captured.lua

$PWSH -NoProfile -File ./cn.ps1 check > fixcheck.log 2>&1
grep -q "All checks passed" fixcheck.log \
  || { echo "FAIL: a captured fixture must not fail check"; cat fixcheck.log; exit 1; }

# THE WORKFLOW'S OWN RULE, NOT A COPY OF IT.
#
# The behavioural check below runs a find expression written out here, which
# is a second copy of the very list this test exists to keep in agreement --
# it would pass while the workflow on the runner still rejected the tree. So
# assert against the workflow file itself first.
fixtureExclusions=$(grep -c "not -path './fixtures/\*'" .github/workflows/release.yml || true)
[ "$fixtureExclusions" -ge 2 ] \
  || { echo "FAIL: the CI workflow does not exclude fixtures/ from both Lua searches (found $fixtureExclusions)"; exit 1; }

# The CI step, run exactly as the workflow runs it -- against an LF copy of
# the .toc, because .gitattributes normalizes it on the way into the
# repository and the runner checks out LF. The scaffold on this disk is CRLF,
# and comparing against that reports every file in the addon as missing.
status=0
toc=$(mktemp)
tr -d '\r' < CompletionNavigator.toc > "$toc"
while IFS= read -r file; do
  rel="${file#./}"
  win="${rel//\//\\}"
  if ! grep -qxF "$win" "$toc" && ! grep -qxF "$rel" "$toc"; then
    echo "  NOT IN TOC: $rel"
    status=1
  fi
done < <(find . -type f -name '*.lua' -not -path './.*' \
           -not -name 'harness.lua' -not -name 'bench.lua' \
           -not -path './fixtures/*')
rm -f "$toc"
[ "$status" -eq 0 ] \
  || { echo "FAIL: CI would reject the tree over a file the toolkit ignores"; exit 1; }

# And luacheck -- the FOURTH list, and the one that was missed. A malformed
# recording is a recording to re-capture, not a syntax error in the addon,
# and it failed the Lint step as though it were.
printf 'return\n["capture"] = {}\n' > fixtures/broken.lua
if command -v luacheck >/dev/null 2>&1; then
  luacheck . --no-color >lintfix.log 2>&1 \
    || { echo "FAIL: luacheck rejects the tree over a file under fixtures/"; tail -4 lintfix.log; exit 1; }
fi
rm -f fixtures/broken.lua

# And the packager must not ship the recording to players.
tr -d '\r' < .pkgmeta | grep -q '^  - fixtures$' \
  || { echo "FAIL: .pkgmeta does not ignore fixtures/"; exit 1; }

rm -rf fixtures
echo "    toolkit, CI, luacheck and .pkgmeta all ignore a captured fixture"

echo "  release guard: the project page must be reviewed"
# A release with no user-visible change legitimately needs no new copy -- but
# that has to be a decision somebody made. It was not; it was an omission, and
# the author had to ask why the description had not been updated.
cp _curseforge/REVIEWED.txt _curseforge/REVIEWED.bak
printf '0.0.1\n' > _curseforge/REVIEWED.txt
$PWSH -NoProfile -File ./cn.ps1 check 2>&1 | grep -q "last reviewed for 0.0.1" \
  || { echo "FAIL: a stale project-page review must block the release"; exit 1; }
mv _curseforge/REVIEWED.bak _curseforge/REVIEWED.txt
$PWSH -NoProfile -File ./cn.ps1 check > check2.log 2>&1
grep -q "All checks passed" check2.log \
  || { echo "FAIL: check does not pass once the page is reviewed"; cat check2.log; exit 1; }

echo "  release guard: wrong version"
$PWSH -NoProfile -File ./cn.ps1 release 9.9.9 2>&1 | grep -q "carries version $VERSION" \
  || { echo "FAIL: wrong-version guard"; exit 1; }
grep -q "## Version: $VERSION" CompletionNavigator.toc || { echo "FAIL: guard modified the tree"; exit 1; }

echo "  check guard: a tree left behind by a refused init"
# THE FAILURE THAT COST A RELEASE CYCLE.
#
# A new cn.ps1 arrives, `init` refuses because Core.lua already exists, and
# the tree stays a release behind while every other line of `check` reports
# happily on the OLD source. There was a branch for the opposite case -- a
# cn.ps1 older than the tree -- and none at all for this one.
cp Core.lua Core.bak
sed -i 's/^CN.version     = "'"$VERSION"'"/CN.version     = "0.0.1"/' Core.lua
sed -i 's/^## Version: '"$VERSION"'/## Version: 0.0.1/' CompletionNavigator.toc
$PWSH -NoProfile -File ./cn.ps1 check 2>&1 | grep -q "but the tree on disk is 0.0.1" \
  || { echo "FAIL: a tree behind the toolkit must be reported"; exit 1; }
mv Core.bak Core.lua
sed -i 's/^## Version: 0.0.1/## Version: '"$VERSION"'/' CompletionNavigator.toc
$PWSH -NoProfile -File ./cn.ps1 check > check3.log 2>&1
grep -q "All checks passed" check3.log \
  || { echo "FAIL: check does not pass once the tree is current"; cat check3.log; exit 1; }

git init -q -b main . && git config user.email t@e.com && git config user.name T
git add -A >/dev/null 2>&1 && git commit -qm init
git init -q --bare "$REMOTE" && git remote add origin "$REMOTE" && git push -q -u origin main

echo "  release: happy path"
$PWSH -NoProfile -File ./cn.ps1 release "$VERSION" > release.log 2>&1
grep -q "Pushed v$VERSION" release.log || { echo "FAIL: release did not push"; cat release.log; exit 1; }
grep -q "RemoteException" release.log && { echo "FAIL: git output rendered as exception type"; exit 1; }

echo "  release guard: duplicate tag"
$PWSH -NoProfile -File ./cn.ps1 release "$VERSION" 2>&1 | grep -q "already exists" \
  || { echo "FAIL: duplicate-tag guard"; exit 1; }

echo "  doctor"
$PWSH -NoProfile -File ./cn.ps1 doctor > doctor.log 2>&1
grep -q "v$VERSION is on the remote" doctor.log || { echo "FAIL: doctor"; cat doctor.log; exit 1; }

echo "  harvest: SavedVariables -> Data\\Quests.lua"
cat > sv.lua <<'SAVEDVARS'

CompletionNavigatorDB = {
	["account"] = {
		["questHarvest"] = {
			[8237] = {
				["name"] = "Already Curated",
				["mapID"] = 94,
				["x"] = 0.42,
				["y"] = 0.55,
			},
			[71234] = {
				["name"] = "A Quest With \"Quotes\" In It",
				["zone"] = "Valdrakken",
				["mapID"] = 2112,
				["x"] = 0.611,
				["y"] = 0.482,
				["observedRequires"] = {
					71230, 71231,
				},
				["maybeRequires"] = {
					1, 2,
				},
			},
			[99001] = {
				["name"] = "No Coordinates Known",
			},
		},
		["questMetadata"] = {
			[555] = { ["name"] = "Must Not Be Imported" },
		},
	},
}
SAVEDVARS

$PWSH -NoProfile -File ./cn.ps1 harvest ./sv.lua > harvest.log 2>&1
grep -q "new rows to add            1" harvest.log \
  || { echo "FAIL: harvest should add exactly one located, uncurated quest"; cat harvest.log; exit 1; }

grep -q '71234' Data/Quests.lua || { echo "FAIL: harvested quest not written"; exit 1; }
grep -q '555'   Data/Quests.lua && { echo "FAIL: questMetadata leaked into the static database"; exit 1; }
grep -q '99001' Data/Quests.lua && { echo "FAIL: unlocated quest added without -Force"; exit 1; }

# THE CHAIN MUST COME WITH IT.
#
# Prerequisites are the whole reason the harvest exists, and until 0.42.0 the
# toolkit's parser could not see an array field at all -- so the addon wrote
# them, the toolkit silently dropped them, and both halves looked like they
# worked.
grep -q 'requires  = { 71230, 71231 }' Data/Quests.lua \
  || { echo "FAIL: harvested prerequisites were not written"; exit 1; }

# And a guess must NOT: maybeRequires is what the addon calls an ordering it
# has seen too few times to believe.
grep -q 'requires  = { 1, 2 }' Data/Quests.lua \
  && { echo "FAIL: unconfident prerequisites were shipped as fact"; exit 1; }

# Escaped quotes must survive the round trip, and the file must still be Lua.
grep -q 'A Quest With .* In It' Data/Quests.lua || { echo "FAIL: quoted name mangled"; exit 1; }
luac5.4 -p Data/Quests.lua || { echo "FAIL: harvest produced invalid Lua"; exit 1; }

# FOLDING INTO A ROW THAT ALREADY EXISTS.
#
# A row is usually added for its location long before enough characters have
# walked the chain for its prerequisites to be believed. Skipping the whole row
# meant that evidence, when it finally arrived, had nowhere to go.
mkdir -p fixtures-tmp
cat > fixtures-tmp/sv2.lua <<'SAVEDVARS2'

CompletionNavigatorDB = {
	["account"] = {
		["questHarvest"] = {
			[8237] = {
				["name"] = "Already Curated",
				["mapID"] = 94,
				["x"] = 0.42,
				["y"] = 0.55,
				["observedRequires"] = {
					8230,
				},
			},
		},
	},
}
SAVEDVARS2

$PWSH -NoProfile -File ./cn.ps1 harvest ./fixtures-tmp/sv2.lua > harvestfold.log 2>&1
grep -q "chains folded into existing rows 1" harvestfold.log \
  || { echo "FAIL: a chain was not folded into the existing row"; cat harvestfold.log; exit 1; }
grep -q 'requires  = { 8230 }' Data/Quests.lua \
  || { echo "FAIL: the folded chain is not in the file"; exit 1; }
luac5.4 -p Data/Quests.lua || { echo "FAIL: folding produced invalid Lua"; exit 1; }

# And folding must be idempotent: a second run must not duplicate it.
$PWSH -NoProfile -File ./cn.ps1 harvest ./fixtures-tmp/sv2.lua > harvestfold2.log 2>&1
FOLDED=$(grep -c 'requires  = { 8230 }' Data/Quests.lua)
[ "$FOLDED" = "1" ] \
  || { echo "FAIL: folding is not idempotent ($FOLDED copies)"; exit 1; }

# The fixture must not linger where `check` will find it: a stray .lua file in
# the tree is exactly the thing check is supposed to complain about, and a test
# that leaves rubbish behind makes a later test fail for a reason that has
# nothing to do with what it is testing.
rm -rf fixtures-tmp

# A CONTRIBUTION FOLDS INTO THE COMMUNITY FILE, AND ONLY INTO THAT ONE.
#
# Community rows are believed because several installs agreed, not because a
# human checked them. Letting them into Data\Quests.lua would destroy that
# distinction permanently and silently.
$PWSH -NoProfile -File ./cn.ps1 contribution "CN1 100:98,99 200:150" > contrib.log 2>&1
grep -q "new rows to add            2" contrib.log \
  || { echo "FAIL: the contribution was not folded"; cat contrib.log; exit 1; }
grep -q "requires = { 98, 99 }" Data/Community.lua \
  || { echo "FAIL: the chain is not in the community file"; exit 1; }
grep -q "100" Data/Quests.lua \
  && { echo "FAIL: a contribution leaked into the curated database"; exit 1; }
luac5.4 -p Data/Community.lua || { echo "FAIL: contribution produced invalid Lua"; exit 1; }

# Malformed input must change nothing at all, rather than importing the half
# it could parse.
BEFORE=$(md5sum Data/Community.lua | cut -d" " -f1)
$PWSH -NoProfile -File ./cn.ps1 contribution "CN1 100:98 rubbish" > contrib2.log 2>&1
grep -q "malformed" contrib2.log \
  || { echo "FAIL: malformed contribution was not refused"; cat contrib2.log; exit 1; }
AFTER=$(md5sum Data/Community.lua | cut -d" " -f1)
[ "$BEFORE" = "$AFTER" ] \
  || { echo "FAIL: a refused contribution still changed the file"; exit 1; }

# Running it again must add nothing.
$PWSH -NoProfile -File ./cn.ps1 harvest ./sv.lua > harvest2.log 2>&1
grep -q "Nothing to add" harvest2.log || { echo "FAIL: harvest is not idempotent"; cat harvest2.log; exit 1; }

# -Force reaches the unlocated ones.
$PWSH -NoProfile -File ./cn.ps1 harvest ./sv.lua -Force > harvest3.log 2>&1
grep -q '99001' Data/Quests.lua || { echo "FAIL: -Force did not include unlocated quests"; exit 1; }
luac5.4 -p Data/Quests.lua || { echo "FAIL: -Force harvest produced invalid Lua"; exit 1; }

# Leave the tree clean for the release steps below.
git checkout -- Data/Quests.lua 2>/dev/null || true
rm -f sv.lua harvest*.log

echo "  harness runs exactly as CI runs it"
# CI invokes `lua5.4 harness.lua .` from the repository root. Everything else
# here runs it from the development tree with a path argument, so this is the
# one check that matches what the runner actually does.
(cd "$WORK" && lua5.4 harness.lua . > ciharness.log 2>&1) || {
  echo "FAIL: the harness does not pass the way CI runs it"
  tail -20 "$WORK/ciharness.log"; exit 1; }
grep -q "ALL HARNESS CHECKS PASSED" "$WORK/ciharness.log" || {
  echo "FAIL: harness did not report success"; tail -20 "$WORK/ciharness.log"; exit 1; }
echo "    passed from the repository root"

# AND ON THE LANGUAGE THE GAME ACTUALLY RUNS.
#
# WoW runs Lua 5.1; this suite normally runs 5.4. They are not the same
# language, and the difference concealed the worst defect this project has
# shipped -- two-argument math.atan, silently wrong in game for twenty-four
# releases while the suite agreed the code was correct.
if command -v lua5.1 >/dev/null 2>&1; then
  (cd "$WORK" && lua5.1 harness.lua . > ciharness51.log 2>&1) || {
    echo "FAIL: the harness does not pass on Lua 5.1, which is what the game runs"
    tail -20 "$WORK/ciharness51.log"; exit 1; }
  grep -q "ALL HARNESS CHECKS PASSED" "$WORK/ciharness51.log" || {
    echo "FAIL: the 5.1 harness did not report success"; exit 1; }
  echo "    passed on Lua 5.1, the game's own version"
else
  echo "    lua5.1 not installed; the game's own language went unverified"
fi

echo "  luacheck runs exactly as CI runs it"
if command -v luacheck >/dev/null 2>&1; then
  (cd "$WORK" && luacheck . --no-color > cilint.log 2>&1) || {
    echo "FAIL: luacheck does not pass the way CI runs it"
    tail -20 "$WORK/cilint.log"; exit 1; }
  echo "    $(grep -oE 'Total: [0-9]+ warnings / [0-9]+ errors' "$WORK/cilint.log")"
fi

echo "  the project page ships with the code"
[ -f "$WORK/_curseforge/DESCRIPTION.md" ] || {
  echo "FAIL: the CurseForge description was not scaffolded"; exit 1; }
[ -f "$WORK/_curseforge/SUMMARY.txt" ] || {
  echo "FAIL: the CurseForge summary was not scaffolded"; exit 1; }

# The packaged addon must NOT contain it. It belongs in the repository, not
# in a player's AddOns folder.
grep -q "_curseforge" "$WORK/.pkgmeta" || {
  echo "FAIL: .pkgmeta does not exclude _curseforge from the package"; exit 1; }

# House rules, enforced rather than merely written down. Public-facing copy
# for this project carries a heightened bar: no superlatives, no claims of
# being the best or only anything, no promises about outcomes.
#
# Two hard limits sit alongside them. The summary has a length CurseForge
# will reject beyond, and the description is pasted verbatim -- so an HTML
# comment in it is a private note published by accident, invisible when
# rendered and plainly readable to anyone who opens the file.
python3 - "$WORK/_curseforge/DESCRIPTION.md" "$WORK/_curseforge/SUMMARY.txt" <<'COPYLINT'
import re, sys

banned = [
    r"\bthe best\b", r"\bbest[- ]in[- ]class\b", r"\bworld[- ]class\b",
    r"\bultimate\b", r"\bunmatched\b", r"\bunrivall?ed\b",
    r"\bsuperior to\b", r"\bbetter than\b", r"\bthe only addon\b",
    r"\bguarantee[ds]?\b", r"\bwill ensure\b", r"\bnever miss\b",
    r"\bperfect\b", r"\bflawless\b", r"\brevolutionary\b",
    r"\bgame[- ]changing\b", r"\bmust[- ]have\b",
]

problems = []

for path in sys.argv[1:]:
    text = open(path, encoding="utf-8").read()

    # The comment block states the rules; it is allowed to name them.
    body = re.sub(r"<!--.*?-->", "", text, flags=re.S)

    for pattern in banned:
        for match in re.finditer(pattern, body, re.I):
            line = body.count("\n", 0, match.start()) + 1
            problems.append("%s:%d: %s" % (path.split("/")[-1], line, match.group(0)))

description, summary = sys.argv[1], sys.argv[2]

# CurseForge rejects a summary over 256 characters outright.
summary_text = open(summary, encoding="utf-8").read().strip()

if len(summary_text) > 256:
    problems.append("SUMMARY.txt is %d characters; the limit is 256"
                    % len(summary_text))

if "\n" in summary_text:
    problems.append("SUMMARY.txt must be a single line")

# The description is pasted verbatim into a public page. Nothing internal
# belongs in it, including inside a comment nobody expected to be read.
body = open(description, encoding="utf-8").read()

if re.search(r"<!--", body):
    problems.append("DESCRIPTION.md contains an HTML comment; internal notes "
                    "belong in RULES.md, which is not published")

if not body.lstrip().startswith("# Completion Navigator"):
    problems.append("DESCRIPTION.md must open with the title heading")

if problems:
    print("FAIL: public-facing copy breaks the house rules")
    for problem in problems:
        print("  " + problem)
    sys.exit(1)

print("    copy passes the house rules (%d/256 chars)" % len(summary_text))
COPYLINT

echo "  CI ignores the toolchain it installs into the workspace"
# CI builds Lua and LuaRocks into .lua/ in the repository root. Two distinct
# problems follow, and a release failed on both at once:
#
#   1. The install directory is itself named `.lua`, so `-name '*.lua'` matched
#      a DIRECTORY and luac was handed it. "cannot read ./.lua: Is a directory".
#   2. Under it sit thousands of third-party files, some deliberately malformed
#      because they are another project's test fixtures.
#
# Poison the tree the same way the runner does -- a directory named .lua, and a
# broken file inside it -- and prove the checks skip both.
mkdir -p "$WORK/.lua/share/lua/5.4"
printf 'this is not ) valid lua ((\n' > "$WORK/.lua/share/lua/5.4/fixture.lua"

(cd "$WORK" && \
  find . -type f -name '*.lua' -not -path './.*' -exec luac5.4 -p {} + > poison.log 2>&1) || {
  echo "FAIL: the syntax check walks into the installed toolchain"
  tail -10 "$WORK/poison.log"; exit 1; }

if command -v luacheck >/dev/null 2>&1; then
  (cd "$WORK" && luacheck . --no-color > poisonlint.log 2>&1) || {
    echo "FAIL: luacheck analyses the installed toolchain"
    tail -10 "$WORK/poisonlint.log"; exit 1; }
fi

rm -rf "$WORK/.lua" "$WORK/poison.log" "$WORK/poisonlint.log"
echo "    third-party .lua files under dotted directories are skipped"

echo "  CI: no Lua search may walk the workspace toolchain"
python3 - "$WORK/.github/workflows/release.yml" <<'FINDLINT'
import re, sys

text = open(sys.argv[1], encoding="utf-8").read()

searches = [line.strip() for line in text.splitlines()
            if re.search(r"find .*-name '\*\.lua'", line)]

if not searches:
    print("FAIL: no Lua file search found; this lint is checking nothing.")
    sys.exit(1)

bad = [line for line in searches
       if "-not -path './.*'" not in line or "-type f" not in line]

if bad:
    print("FAIL: a Lua file search is not scoped to our own files")
    for line in bad:
        print("  " + line)
    print("  Needs -type f (the install directory is NAMED .lua) and")
    print("  -not -path './.*' (the toolchain lives inside it).")
    sys.exit(1)

print("    every Lua search is scoped to our own files")
FINDLINT

echo "  coverage: harness exercises the addon"
if command -v luacov >/dev/null 2>&1; then
  # Run against the scaffolded tree, which is what actually ships.
  # init writes files without the execute bit; invoke through the shell.
  (cd "$WORK" && bash coverage.sh . 82 > coverage.log 2>&1) || {
    echo "FAIL: coverage below floor"; tail -15 "$WORK/coverage.log"; exit 1; }
  echo "    $(grep '^Total:' "$WORK/coverage.log")"
else
  echo "    luacov not installed; skipped"
fi

echo "  luacheck: static analysis of the scaffolded tree"
if command -v luacheck >/dev/null 2>&1; then
  cp /home/claude/cn/build/CompletionNavigator/.luacheckrc "$WORK/.luacheckrc"
  (cd "$WORK" && luacheck . --no-color > luacheck.log 2>&1) || {
    echo "FAIL: luacheck reported problems"; tail -30 "$WORK/luacheck.log"; exit 1; }
  echo "    $(grep -oE 'Total: [0-9]+ warnings / [0-9]+ errors' "$WORK/luacheck.log")"
else
  echo "    luacheck not installed; skipped"
fi

echo "  coverage degrades instead of blocking"
# A developer tool being absent must never stop a release. This exact failure
# shipped: coverage.sh hardcoded a luacov path, died on the CI runner, and the
# packager never ran -- so a tagged release never reached CurseForge.
#
# Every way coverage.sh can find luacov must be blinded, or this passes while
# proving nothing: once it learned to ask luarocks, blanking the hardcoded
# directories alone left it finding luacov anyway.
(cd "$WORK" && sed 's#/usr/local/share/lua#/nonexistent/share/lua#g; s#/usr/share/lua#/nonexistent2/share/lua#g; s#$HOME/.luarocks/share/lua#/nonexistent3#g; s#command -v luarocks#command -v definitely-not-luarocks#g' coverage.sh > coverage_nolua.sh \
  && bash coverage_nolua.sh . 80 > nolua.log 2>&1)
NOLUA=$?
if [ "$NOLUA" -ne 0 ]; then
  echo "FAIL: coverage.sh exits non-zero when luacov is missing; that blocks releases"
  cat "$WORK/nolua.log"
  exit 1
fi
grep -q "skipping" "$WORK/nolua.log" || {
  echo "FAIL: coverage.sh must say why it skipped"; cat "$WORK/nolua.log"; exit 1; }
echo "    $(head -1 "$WORK/nolua.log")"

echo "  CI: the job cannot hang indefinitely"
python3 - "$WORK/.github/workflows/release.yml" <<'TIMEOUT'
import re, sys

text = open(sys.argv[1], encoding="utf-8").read()

if not re.search(r"^\s*timeout-minutes:\s*\d+", text, re.M):
    print("FAIL: the workflow has no timeout-minutes anywhere.")
    print("  A hung step runs for six hours and looks identical to a working one.")
    sys.exit(1)

# The job itself must be bounded, not only individual steps.
job_timeout = re.search(r"runs-on:.*?\n(?:.*?\n)*?\s*timeout-minutes:\s*(\d+)", text)

if not job_timeout:
    print("FAIL: the job has no timeout-minutes; only steps are bounded.")
    sys.exit(1)

minutes = int(job_timeout.group(1))

# THE PER-STEP CAPS ARE THE HANG DETECTOR; THE JOB CAP IS THE BACKSTOP.
#
# The ceiling here used to be 60, on the reasoning that a generous job cap
# cannot notice a hang. That reasoning belongs to the STEP caps -- every step
# in this workflow carries one, and each is sized to the work it does. The job
# cap only has to be larger than all of them together, or it becomes the real
# limit and kills whichever step happens to be running. 0.67.1.
if minutes > 120:
    print("FAIL: job timeout of %d minutes is too generous to be a backstop" % minutes)
    sys.exit(1)

# AND THE JOB CAP MUST EXCEED THE STEPS IT CONTAINS. 0.67.1.
#
# 0.67.0 shipped with a job capped at 20 minutes containing step caps that add
# to 57. When the job cap is the smaller number the per-step ones are
# decoration: whichever step happens to be running when the job clock runs out
# is killed, no step is marked failed, and the run reports a failure with
# nothing to point at -- which is exactly what `cn.ps1 ci` could not explain.
#
# Only the steps AFTER the job's own line are summed; the job's cap is the
# first `timeout-minutes` in the file.
after = text[job_timeout.end():]

step_caps = [int(m) for m in re.findall(r"^\s*timeout-minutes:\s*(\d+)", after, re.M)]

total = sum(step_caps)

if step_caps and minutes <= total:
    print("FAIL: the job is capped at %d minutes and the steps inside it are"
          % minutes)
    print("  capped at %d in total (%s)." % (total, ", ".join(str(c) for c in step_caps)))
    print("  The job cap is then the real limit, and it kills whichever step")
    print("  happens to be running -- marking nothing as failed.")
    sys.exit(1)

print("    job bounded at %d minutes, over %d minutes of step caps"
      % (minutes, total))
TIMEOUT

echo "  CI: the toolchain does not come from the runner's package manager"
python3 - "$WORK/.github/workflows/release.yml" <<'APTLOCK'
import re, sys

text = open(sys.argv[1], encoding="utf-8").read()

# A fresh runner holds the dpkg lock via unattended-upgrades. apt-get has no
# default timeout on that lock: it waits silently, forever. One release wedged
# there for thirty-eight minutes. Bounding the wait did not help -- the lock
# was still held, so the install failed instead of hanging.
#
# The toolchain now comes from setup actions that build into the workspace,
# contending with nothing. Any apt-get reintroduced here must at minimum bound
# the lock wait, and must not be how Lua itself arrives.
calls = [line.strip() for line in text.splitlines()
         if re.search(r"\bapt-get\b", line)
         and not line.strip().startswith("#")]

unbounded = [c for c in calls if "DPkg::Lock::Timeout" not in c]

if unbounded:
    print("FAIL: apt-get invocation with no dpkg lock timeout")
    for call in unbounded:
        print("  " + call)
    print("  Add -o DPkg::Lock::Timeout=<seconds>; without it apt waits forever.")
    sys.exit(1)

if re.search(r"apt-get[^\n]*\b(lua5\.\d|lua-check|luarocks)\b", text):
    print("FAIL: the Lua toolchain is being installed with apt-get.")
    print("  That is the dpkg-lock hang. Use the setup actions instead.")
    sys.exit(1)

if not re.search(r"uses:\s*leafo/gh-actions-lua", text):
    print("FAIL: no Lua setup action; something replaced it.")
    sys.exit(1)

print("    Lua from a setup action, %d bounded apt-get call(s)" % len(calls))
APTLOCK

echo "  CI: only real failures may block the packager"
# Any blocking CI step must be one that indicates broken code. Optional
# tooling steps must carry continue-on-error.
python3 - "$WORK/.github/workflows/release.yml" <<'CILINT'
import re, sys

text = open(sys.argv[1], encoding="utf-8").read()

# Steps that are allowed to block a release, because they mean the addon is
# actually broken.
blocking_allowed = {
    "Check out", "Fetch tags", "Verify a tag points at HEAD", "Install Lua",
    "Install LuaRocks", "Install Lua tooling",
    "Syntax check every Lua file", "Verify the .toc lists every Lua file",
    "Lint", "Run the offline harness",
    "Run the offline harness on Lua 5.1 (the game's version)",
    # Budgets block, and should: a performance regression is a defect, two
    # have shipped in this project, and both were visible in output nobody
    # was comparing against anything.
    "Performance budgets",
    "Verify the CurseForge token is available", "Package and upload",
}

steps = re.findall(r"- name: (.+?)\n(.*?)(?=\n      - name: |\Z)", text, re.S)

problems = []

for name, body in steps:
    name = name.strip()
    optional = "continue-on-error: true" in body

    if name not in blocking_allowed and not optional:
        problems.append("step '%s' can block a release but is not in the "
                        "allow-list; add continue-on-error or justify it" % name)

if problems:
    print("FAIL: CI would block a release on a non-essential step")
    for problem in problems:
        print("  " + problem)
    sys.exit(1)

print("    %d steps checked" % len(steps))
CILINT

echo "  lint: no unguarded native invocations"
# Structural guarantee, not a behavioural one. Every native command must go
# through Invoke-CNNative; a stray `2>&1` or a bare `git` call reintroduces
# exactly the Windows PowerShell 5.1 failure this exists to prevent.
python3 - /home/claude/cn/ps/cn.head.ps1 /home/claude/cn/ps/cn.body.ps1 <<'LINT'
import re, sys

problems  = []
redirects = []
bare_git  = []

lines = []

for path in sys.argv[1:]:
    with open(path, encoding="utf-8") as fh:
        for number, line in enumerate(fh, 1):
            lines.append(("%s:%d" % (path.split("/")[-1], number), line))

for number, line in lines:
    stripped = line.strip()

    # Comments are documentation, not invocations.
    if stripped.startswith("#") or stripped.startswith("<#"):
        continue

    if "2>&1" in line:
        redirects.append((number, stripped))

    # A native git call that is not routed through the wrapper.
    if re.match(r"^(\$\w+\s*=\s*)?(&\s*)?git\s+\S", stripped):
        bare_git.append((number, stripped))

# Exactly one redirect is allowed: the one inside Invoke-CNNative.
if len(redirects) != 1 or "$Executable @Arguments" not in redirects[0][1]:
    problems.append("2>&1 must appear exactly once, inside Invoke-CNNative:")
    problems += ["    %s: %s" % r for r in redirects]

if bare_git:
    problems.append("git must be called through Invoke-CNGit:")
    problems += ["    %s: %s" % r for r in bare_git]

if problems:
    print("FAIL: unguarded native invocation")
    for problem in problems:
        print("  " + problem)
    sys.exit(1)
LINT

echo "  strict native error handling (approximates Windows PowerShell 5.1)"
# On Windows PowerShell 5.1, stderr from a native command under 2>&1 becomes a
# terminating error when $ErrorActionPreference is Stop. PowerShell 7 only does
# this with $PSNativeCommandUseErrorActionPreference, so turn it on: without
# it, this suite passes a script that dies on the user's machine. It already
# did exactly that once.
cd "$WORK"
$PWSH -NoProfile -Command "
\$PSNativeCommandUseErrorActionPreference = \$true
\$ErrorActionPreference = 'Stop'
& '$WORK/cn.ps1' doctor
if (\$LASTEXITCODE -ne 0) { exit 1 }
" > strict.log 2>&1 || { echo "FAIL: doctor dies under strict native error handling"; cat strict.log; exit 1; }

grep -q "is on the remote" strict.log || { echo "FAIL: strict-mode doctor output wrong"; cat strict.log; exit 1; }

# And the part that actually broke: a push, under strict handling.
git tag -d "v$VERSION" >/dev/null 2>&1
git push --delete origin "v$VERSION" >/dev/null 2>&1
echo "probe" > probe.txt && git add probe.txt && git commit -qm probe

$PWSH -NoProfile -Command "
\$PSNativeCommandUseErrorActionPreference = \$true
\$ErrorActionPreference = 'Stop'
& '$WORK/cn.ps1' release '$VERSION'
" > strictrelease.log 2>&1 || true

grep -q "Pushed v$VERSION" strictrelease.log \
  || { echo "FAIL: release does not survive strict native error handling"; cat strictrelease.log; exit 1; }

echo "ALL POWERSHELL CHECKS PASSED"
rm -rf "$WORK" "$(dirname "$REMOTE")"
'@

$Embedded['cisim.sh'] = @'
#!/bin/bash
# cisim.sh -- run the release workflow's own steps, locally, before tagging.
#
# WHY THIS EXISTS.
#
# Four consecutive releases were tagged, pushed, reported as published, and
# never reached CurseForge. Each died at a different step of the GitHub
# workflow -- the .toc audit, then Lint, then the offline harness -- and each
# was discovered only by pushing a tag, waiting, and reading a web page. Every
# one of them was reproducible in seconds on this machine, and nothing here
# ran them.
#
# The local suite ran *equivalents* of those steps: `luacheck build/...`,
# `lua5.4 harness.lua build/...`. The workflow runs `luacheck .` and
# `lua5.4 harness.lua .` against a SCAFFOLDED TREE, from the repository root,
# with whatever else happens to be in the working directory. Those are not the
# same command in the same place, and the difference is exactly where all four
# failures lived.
#
# So this does not re-implement the workflow. It EXTRACTS each `run:` block
# from .github/workflows/release.yml and executes it, in a scaffolded tree, in
# order, stopping at the first non-zero exit -- the same way the runner does.
#
# Usage:  ./cisim.sh [path-to-cn.ps1]
set -u

SRC=${1:-/home/claude/cn/out/cn.ps1}
PWSH=/opt/pwsh/pwsh

WORK=$(mktemp -d)

cleanup() { rm -rf "$WORK"; }
trap cleanup EXIT

echo "CI simulation :: $(basename "$SRC")"

cp "$SRC" "$WORK/cn.ps1"
cd "$WORK" || exit 1

$PWSH -NoProfile -File ./cn.ps1 init > init.log 2>&1 || {
    echo "  FAIL  scaffold failed"; cat init.log; exit 1; }

# The runner checks the repository out with LF endings -- .gitattributes
# normalizes on the way in. The scaffold writes CRLF, and comparing CRLF text
# with grep -qxF reports every file in the addon as missing from the .toc.
# Simulating the workflow without simulating the checkout tests nothing.
find . -type f \( -name '*.lua' -o -name '*.toc' -o -name '*.xml' \
    -o -name '*.md' -o -name '*.sh' -o -name '.pkgmeta' -o -name '*.yml' \) \
    -exec sed -i 's/\r$//' {} \; 2>/dev/null

# THE RECORDING GOES IN TOO.
#
# The repository has one, and the step that finally exposed the broken
# fixtures writer was the offline harness reading it. A simulation of a
# repository that omits the file the repository actually contains is a
# simulation of a different repository.
if [ -f /home/claude/cn/build/fixtures/captured.lua ]; then
    mkdir -p fixtures
    cp /home/claude/cn/build/fixtures/captured.lua fixtures/captured.lua
fi

# A git repository, because a step asks git what tag points at HEAD.
git init -q -b main . 2>/dev/null
git config user.email ci@example.com
git config user.name CI
git add -A >/dev/null 2>&1
git commit -qm "ci simulation" >/dev/null 2>&1
git tag v0.0.0-cisim 2>/dev/null

export GITHUB_REF="refs/tags/v0.0.0-cisim"
export GITHUB_REF_NAME="v0.0.0-cisim"
export CF_API_KEY="cisim-placeholder"

# Extract every `run:` block from the workflow, with the step name that owns
# it, and execute them in order.
python3 - <<'EXTRACT'
import re, os

text = open('.github/workflows/release.yml', encoding='utf-8').read()

lines = text.split('\n')

steps = []
name = None
limit = None
soft = False
i = 0

while i < len(lines):
    line = lines[i]

    match = re.match(r'^\s*-\s+name:\s*(.+?)\s*$', line)

    if match:
        name = match.group(1)
        limit = None
        soft = False
        i += 1
        continue

    # THE RUNNER'S OWN LIMITS, CARRIED THROUGH. 0.67.1.
    #
    # This script existed to stop a step passing here and failing there, and
    # it read only the commands -- so the two constraints the runner enforces
    # around them were invisible to it. A step with `timeout-minutes: 8` that
    # takes nine here was reported as passing, and a step marked
    # `continue-on-error` was treated as fatal, which is the opposite of what
    # the runner does with it.
    cap = re.match(r'^\s*timeout-minutes:\s*(\d+)\s*$', line)

    if cap:
        limit = int(cap.group(1))
        i += 1
        continue

    soften = re.match(r'^\s*continue-on-error:\s*(true|false)\s*$', line)

    if soften:
        soft = soften.group(1) == 'true'
        i += 1
        continue

    # `run: |` opens a block; `run: something` is a one-liner.
    block = re.match(r'^(\s*)run:\s*\|\s*$', line)

    if block:
        indent = len(block.group(1))
        body = []
        i += 1

        while i < len(lines):
            nxt = lines[i]

            if nxt.strip() == '':
                body.append('')
                i += 1
                continue

            if len(nxt) - len(nxt.lstrip()) <= indent:
                break

            body.append(nxt)
            i += 1

        # Strip the common indent.
        trim = min((len(b) - len(b.lstrip()) for b in body if b.strip()),
                   default=0)

        steps.append((name, '\n'.join(b[trim:] for b in body), limit, soft))
        continue

    inline = re.match(r'^\s*run:\s*(\S.*?)\s*$', line)

    if inline:
        steps.append((name, inline.group(1), limit, soft))

    i += 1

with open('.cisim-steps', 'w', encoding='utf-8') as fh:
    for index, (label, body, limit, soft) in enumerate(steps):
        fh.write('=== %d\t%s\t%s\t%s\n' % (index, label or '(unnamed)',
                                              limit if limit else '0',
                                              '1' if soft else '0'))
        fh.write(body)
        fh.write('\n=== end\n')

print('  %d run-steps extracted' % len(steps))
EXTRACT

[ -f .cisim-steps ] || { echo "  FAIL  could not read the workflow"; exit 1; }

# Steps that cannot be simulated here, with the reason stated rather than
# silently skipped. A skip nobody can see is how a step stops being checked.
SKIP_PATTERN='^(Fetch tags|Verify a tag points at HEAD)$'

status=0
ran=0
skipped=0

# ------------------------------------------------------------
# PREFLIGHT: A COMMAND NOTHING INSTALLS IS AN EXIT 127 WAITING FOR A TAG.
#
# 0.61.0 died on the runner with "Process completed with exit code 127" --
# command not found. The Performance budgets step called `lua5.1` directly,
# the runner does not have it, and nothing here noticed because THIS MACHINE
# does. That is precisely the failure mode this whole script exists to
# prevent: a step that passes locally and cannot pass there.
#
# So the steps are read for bare invocations of the interpreters and tools
# this workflow depends on, and each one must either be installed by the
# workflow's own "Install Lua tooling" step or be guarded by `command -v`.
# Whether it happens to exist locally is not evidence about the runner.
# ------------------------------------------------------------
# ONLY LINES THAT ACTUALLY INSTALL SOMETHING.
#
# The first version of this grepped the whole Install step for the tool's
# name, and the step's own comment and its "could not be installed" warning
# both contain it -- so the check passed on prose and the preflight said
# nothing. Comments and echoes are stripped, and what remains must be an
# install or a symlink.
# THE END MARKER MATCHES THE START PATTERN, SO IT IS TESTED FIRST.
#
# Steps are delimited `=== <n>\t<label>` ... `=== end`, and `/^=== /` matches
# BOTH. With the start rule first, every `=== end` reset the body before the
# end rule could read it, so the body was always empty and the preflight
# checked nothing while reporting success -- a check that cannot fail, which
# is worse than no check.
install_body=$(awk '
    /^=== end/{ collecting = 0; next }
    /^=== /{ collecting = ($0 ~ /Install Lua tooling/) ? 1 : 0; next }
    !collecting { next }
    /^ *#/ { next }
    /echo / { next }
    /(apt-get +install|luarocks +install|ln +-sf|apk +add|brew +install)/ { print }
' .cisim-steps)

preflight=0

for tool in lua5.1 lua5.2 lua5.3 lua5.4 luac5.1 luac5.4 luacheck luacov busted; do
    # Every step that invokes the tool as a command.
    if ! grep -qE "(^|[^-[:alnum:]_./])${tool}[[:space:]]" .cisim-steps 2>/dev/null; then
        continue
    fi

    # Installed by the workflow itself?
    if printf '%s' "$install_body" | grep -q "$tool"; then
        continue
    fi

    # Every invocation guarded by a presence check in its own step?
    # `&&` TRAILS THE LINE. mawk continues a condition after a trailing
    # operator and refuses one that begins with it, which is how the first
    # version of this printed six syntax errors and checked nothing.
    unguarded=$(awk -v tool="$tool" '
        /^=== end/{
            uses = (body ~ ("(^|[^-[:alnum:]_./])" tool "[ \t]"))
            seen = (body ~ ("command -v " tool)) ||
                   (body ~ ("which " tool)) ||
                   (body ~ ("hash " tool))
            # The Install step naming a tool is it INSTALLING the tool, not
            # depending on one that may be absent.
            if (uses && !seen && label !~ /Install Lua tooling/) {
                sub(/^=== [0-9]*\t?/, "", label)
                print label
            }
            next
        }
        /^=== /{ label = $0; body = ""; next }
        { body = body $0 " " }
    ' .cisim-steps)

    if [ -n "$unguarded" ]; then
        echo "  PREFLIGHT FAIL  '$tool' is neither installed by the workflow"
        echo "                  nor guarded, in: $unguarded"
        echo "                  On a runner without it that step exits 127."
        preflight=1
    fi
done

if [ "$preflight" -ne 0 ]; then
    echo ""
    echo "A workflow step would fail on the runner with command-not-found."
    exit 1
fi

label=""
body=""
collecting=0

while IFS= read -r line; do
    case "$line" in
        "=== end")
            collecting=0

            if [[ "$label" =~ $SKIP_PATTERN ]]; then
                echo "  skip  $label  (needs the real tag push)"
                skipped=$((skipped + 1))
            else
                printf '  ....  %s\r' "$label"

                # THE RUNNER'S OWN CLOCK. 0.67.1.
                #
                # `timeout-minutes` is the constraint this script was blindest
                # to: a step that takes nine minutes here and is capped at
                # eight there passed locally and was killed on the runner,
                # which is exactly the "passes here, fails there" shape the
                # whole script exists to prevent. Enforced with a margin of
                # ZERO -- this machine is FASTER than a two-core runner, so a
                # step that only just fits here does not fit there.
                started=$(date +%s)

                if [ "${limit:-0}" != "0" ] && command -v timeout >/dev/null 2>&1; then
                    timeout "${limit}m" bash -c "$body" > step.log 2>&1
                    code=$?
                else
                    bash -c "$body" > step.log 2>&1
                    code=$?
                fi

                elapsed=$(( $(date +%s) - started ))

                if [ "$code" -eq 0 ]; then
                    # A STEP THAT ONLY JUST FITS IS A STEP THAT WILL NOT.
                    #
                    # The runner has two cores and this machine has more, so
                    # anything past two thirds of its budget here is over
                    # budget there. Said out loud rather than left to be
                    # discovered by a failed release.
                    if [ "${limit:-0}" != "0" ] \
                        && [ "$elapsed" -gt $(( limit * 40 )) ]; then

                        printf '  ok    %s  <-- %ss of a %sm budget; the runner is slower\n' \
                            "$label" "$elapsed" "$limit"
                    else
                        printf '  ok    %s\n' "$label"
                    fi

                    ran=$((ran + 1))
                elif [ "$code" -eq 124 ]; then
                    printf '  TIMEOUT  %s  (killed at %s minutes, as the runner would)\n' \
                        "$label" "$limit"
                    echo ''
                    tail -20 step.log | sed 's/^/        /'

                    if [ "${soft:-0}" = "1" ]; then
                        echo '        this step is continue-on-error, so the runner would'
                        echo '        not fail the job -- it would simply stop running.'
                        ran=$((ran + 1))
                    else
                        status=1
                        break
                    fi
                else
                    if [ "${soft:-0}" = "1" ]; then
                        # THE RUNNER DOES NOT FAIL ON THESE, SO NEITHER DOES
                        # THIS -- but silence is how a step stops being
                        # checked, so it is named.
                        printf '  warn  %s  (failed; continue-on-error, as on the runner)\n' \
                            "$label"
                        grep -vE 'OK$' step.log | sed 's/^/        /' | tail -12
                        ran=$((ran + 1))
                    else
                        printf '  FAIL  %s\n' "$label"
                        echo ''
                        # OK lines are the ones that did NOT fail, and a
                        # 25-line tail of a 200-file lint run shows nothing but
                        # those -- which is how a failing step got reported with
                        # no failure visible in it. 0.61.0.
                        grep -vE 'OK$' step.log | sed 's/^/        /' | tail -40
                        status=1
                        break
                    fi
                fi
            fi

            label=""
            body=""
            ;;
        "=== "*)
            label=$(printf '%s' "$line" | cut -f2)
            limit=$(printf '%s' "$line" | cut -f3)
            soft=$(printf '%s' "$line" | cut -f4)
            collecting=1
            body=""
            ;;
        *)
            if [ "$collecting" -eq 1 ]; then
                body="$body$line"$'\n'
            fi
            ;;
    esac
done < .cisim-steps

echo ""

if [ "$status" -eq 0 ]; then
    echo "Every simulated workflow step passed. ($ran ran, $skipped skipped)"
else
    echo "A workflow step failed HERE, which means it would fail on the runner."
fi

exit $status
'@

$EmbeddedBinary = [ordered]@{}

$EmbeddedBinary['Media\Logo.tga'] = @(
