############################################################
# IO HELPERS
############################################################

function Write-CNFile {
    param([string] $Relative, [string] $Content)

    $full = Join-Path $script:Root $Relative
    $dir  = Split-Path -Parent $full

    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    if (-not $Content.EndsWith("`n")) { $Content += "`n" }

    # Normalize to LF first, then decide.
    $Content = $Content -replace "`r`n", "`n"

    # Shell scripts MUST be LF. A CRLF shell script fails with
    # "$'\r': command not found", which reads like a corrupt file rather than
    # a line-ending problem. Same for anything a Linux CI runner executes.
    $lfOnly = @('.sh', '.yml', '.yaml')

    $extension = [System.IO.Path]::GetExtension($Relative)

    if ($lfOnly -notcontains $extension) {
        $Content = $Content -replace "`n", "`r`n"
    }

    $encoding = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($full, $Content, $encoding)
}

function Read-CNFile {
    param([string] $Relative)

    $full = Join-Path $script:Root $Relative

    if (-not (Test-Path -LiteralPath $full)) { return $null }

    return [System.IO.File]::ReadAllText($full)
}

function Test-CNWritable {
    $probe = Join-Path $script:Root ('.cn-write-test-' + [guid]::NewGuid().ToString('N') + '.tmp')

    try {
        [System.IO.File]::WriteAllText($probe, 'x')
        Remove-Item -LiteralPath $probe -Force
        return $true
    }
    catch {
        return $false
    }
}

function Assert-CNWritable {
    if (Test-CNWritable) { return }

    Write-Host ''
    Write-Host 'ERROR: this folder is not writable by the current process.' -ForegroundColor Red
    Write-Host "  $script:Root" -ForegroundColor DarkGray
    Write-Host ''
    Write-Host 'Fix: close this window, right-click PowerShell, "Run as administrator", then re-run.' -ForegroundColor Yellow
    Write-Host 'Better long-term fix: keep the source in a writable folder and junction it here:' -ForegroundColor Yellow
    Write-Host '  mklink /J "C:\Program Files (x86)\World of Warcraft\_retail_\Interface\AddOns\CompletionNavigator" "C:\dev\CompletionNavigator"' -ForegroundColor DarkGray
    Write-Host ''

    exit 1
}

# Lua files the CLIENT loads. Test tooling lives in the repository root and is
# emphatically not part of the addon: harness.lua stubs the entire client API,
# so loading it in game would replace live functions with fakes.
$script:NonAddonLua = @('harness.lua', 'bench.lua')

function Get-CNLuaFiles {
    # EVIDENCE IS NOT SOURCE.
    #
    # fixtures\captured.lua is a recording of what a live client returned,
    # written by `cn.ps1 fixtures` and read only by the harness. It is a .lua
    # file sitting in the tree, so this found it, `check` warned that it was
    # missing from the .toc, and `sync` would have listed it -- which would
    # hand the client a table of stub-audit data to load at login.
    #
    # Excluded by directory rather than by name: everything under fixtures\ is
    # evidence by definition.
    Get-ChildItem -LiteralPath $script:Root -Recurse -Filter '*.lua' -File |
        Where-Object { $_.FullName -notmatch '[\\/]_backups[\\/]' } |
        Where-Object { $_.FullName -notmatch '[\\/]fixtures[\\/]' } |
        Where-Object { $script:NonAddonLua -notcontains $_.Name } |
        ForEach-Object {
            $_.FullName.Substring($script:Root.Length).TrimStart('\', '/').Replace('/', '\')
        }
}

function Get-CNLoadOrder {
    $all = @(Get-CNLuaFiles)

    $ordered = New-Object System.Collections.Generic.List[string]

    foreach ($file in $script:RootOrder) {
        if ($all -contains $file) { $ordered.Add($file) | Out-Null }
    }

    # Any unlisted root-level file, alphabetically, after the fixed set.
    $all | Where-Object { $_ -notmatch '\\' -and $script:RootOrder -notcontains $_ } |
        Sort-Object | ForEach-Object { $ordered.Add($_) | Out-Null }

    foreach ($folder in $script:FolderOrder) {
        $all | Where-Object { $_ -like "$folder\*" } |
            Sort-Object | ForEach-Object { $ordered.Add($_) | Out-Null }
    }

    # Any other subfolder not in FolderOrder, last.
    $all | Where-Object {
            $_ -match '\\' -and
            ($script:FolderOrder -notcontains ($_ -split '\\')[0])
        } | Sort-Object | ForEach-Object { $ordered.Add($_) | Out-Null }

    return $ordered
}

function Resolve-CNModulePath {
    param([string] $ModuleName)

    if (-not $ModuleName) { return $null }

    if ($ModuleName -like '*.lua') {
        if (Test-Path -LiteralPath (Join-Path $script:Root $ModuleName)) { return $ModuleName }
    }

    $candidates = @(
        "Modules\$ModuleName.lua",
        "Providers\$ModuleName.lua",
        "$ModuleName.lua"
    )

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath (Join-Path $script:Root $candidate)) { return $candidate }
    }

    return $null
}

function Add-CNBlock {
    param([string] $Relative, [string] $Block, [string] $Marker = $script:AppendMark)

    $content = Read-CNFile $Relative

    if ($null -eq $content) { throw "File not found: $Relative" }

    $index   = $content.IndexOf($Marker)
    $trimmed = $Block.Trim("`r", "`n")

    if ($index -ge 0) {
        # Insert immediately above the marker line.
        $lineStart = $content.LastIndexOf("`n", $index)
        if ($lineStart -lt 0) { $lineStart = 0 } else { $lineStart += 1 }

        $content = $content.Substring(0, $lineStart) +
                   $trimmed + "`n`n" +
                   $content.Substring($lineStart)
    }
    else {
        $content = $content.TrimEnd() + "`n`n" + $trimmed + "`n"
    }

    Write-CNFile $Relative $content
}


############################################################
# GIT
############################################################

# git is frequently installed but absent from PATH -- GitHub Desktop ships
# its own copy, and the standalone installer does not always update PATH for
# an already-open shell. Look in the usual places before giving up.
function Resolve-CNGit {
    $command = Get-Command git -ErrorAction SilentlyContinue

    if ($command) { return $command.Source }

    $candidates = @(
        "$env:ProgramFiles\Git\cmd\git.exe",
        "${env:ProgramFiles(x86)}\Git\cmd\git.exe",
        "$env:LOCALAPPDATA\Programs\Git\cmd\git.exe",
        "$env:ProgramW6432\Git\cmd\git.exe"
    )

    # GitHub Desktop bundles git under a versioned folder.
    $desktopRoot = "$env:LOCALAPPDATA\GitHubDesktop"

    if (Test-Path -LiteralPath $desktopRoot) {
        Get-ChildItem -LiteralPath $desktopRoot -Filter 'app-*' -Directory -ErrorAction SilentlyContinue |
            Sort-Object Name -Descending |
            ForEach-Object {
                $candidates += (Join-Path $_.FullName 'resources\app\git\cmd\git.exe')
            }
    }

    foreach ($candidate in $candidates) {
        if ($candidate -and (Test-Path -LiteralPath $candidate)) {
            $binDirectory = Split-Path -Parent $candidate

            # Make it usable for the rest of this session, not just here.
            $env:PATH = "$binDirectory;$env:PATH"

            Write-Host "Found git at $candidate and added it to PATH for this session." -ForegroundColor DarkGray

            return $candidate
        }
    }

    return $null
}

function Assert-CNGit {
    $git = Resolve-CNGit

    if ($git) { return $git }

    Write-Host ''
    Write-Host 'git is not installed, or not on PATH.' -ForegroundColor Red
    Write-Host ''
    Write-Host 'Install it:' -ForegroundColor Yellow
    Write-Host '  winget install --id Git.Git -e --source winget' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host 'Then CLOSE and REOPEN PowerShell. An already-open shell keeps its' -ForegroundColor Yellow
    Write-Host 'old PATH, so git stays invisible until you restart it.' -ForegroundColor Yellow
    Write-Host ''

    return $null
}

############################################################
# COMMANDS
############################################################

function Invoke-CNInit {
    Assert-CNWritable

    $legacy = Join-Path $script:Root 'CompletionNavigator.lua'
    $hasTree = Test-Path -LiteralPath (Join-Path $script:Root 'Core.lua')

    if ($hasTree -and -not $Force) {
        Write-Host 'Core.lua already exists. Re-run with -Force to overwrite the whole tree.' -ForegroundColor Yellow
        Write-Host 'Existing SavedVariables are untouched either way.' -ForegroundColor DarkGray
        return
    }

    Invoke-CNBackup -Quiet

    foreach ($relative in $Embedded.Keys) {
        Write-CNFile $relative $Embedded[$relative]
        Write-Host "  wrote  $relative" -ForegroundColor DarkGray
    }

    # Artwork and anything else that is not text. Carried as base64 so a fresh
    # scaffold is complete and releasable -- without this, init produced a tree
    # whose own check failed on a missing IconTexture.
    foreach ($relative in $EmbeddedBinary.Keys) {
        $path = Join-Path $script:Root $relative
        $dir  = Split-Path -Parent $path

        if ($dir -and -not (Test-Path -LiteralPath $dir)) {
            New-Item -ItemType Directory -Path $dir -Force | Out-Null
        }

        [System.IO.File]::WriteAllBytes($path,
            [System.Convert]::FromBase64String($EmbeddedBinary[$relative]))

        Write-Host "  wrote  $relative" -ForegroundColor DarkGray
    }

    if (Test-Path -LiteralPath $legacy) {
        $retired = Join-Path $script:BackupDir 'CompletionNavigator.lua.single-file'
        New-Item -ItemType Directory -Path $script:BackupDir -Force | Out-Null
        Move-Item -LiteralPath $legacy -Destination $retired -Force
        Write-Host "  retired CompletionNavigator.lua -> _backups\CompletionNavigator.lua.single-file" -ForegroundColor DarkGray
    }

    Invoke-CNSync
    Write-Host ''
    Write-Host 'Scaffold complete. In game: /reload then /cn help' -ForegroundColor Green
}

function Invoke-CNSync {
    Assert-CNWritable

    $toc = Read-CNFile 'CompletionNavigator.toc'

    if ($null -eq $toc) { throw 'CompletionNavigator.toc not found. Run: .\cn.ps1 init' }

    # Bindings.xml is deliberately NOT listed. The client loads it directly
    # from the addon folder; putting it in the .toc routes it through the
    # FrameXML parser instead, which rejects <Binding> with
    # "Unrecognized XML: Binding".
    $files = Get-CNLoadOrder

    $block = ($script:BeginMark + "`n" + (($files) -join "`n") + "`n" + $script:EndMark)

    $startIndex = $toc.IndexOf($script:BeginMark)
    $endIndex   = $toc.IndexOf($script:EndMark)

    if ($startIndex -ge 0 -and $endIndex -gt $startIndex) {
        $head = $toc.Substring(0, $startIndex)
        $tail = $toc.Substring($endIndex + $script:EndMark.Length)
        $toc  = $head + $block + $tail
    }
    else {
        $toc = $toc.TrimEnd() + "`n`n" + $block + "`n"
    }

    Write-CNFile 'CompletionNavigator.toc' $toc

    Write-Host "Synced .toc with $($files.Count) Lua files." -ForegroundColor Green
    $files | ForEach-Object { Write-Host "  $_" -ForegroundColor DarkGray }
}

function Invoke-CNNew {
    Assert-CNWritable

    $kind = if ($Target) { $Target.ToLower() } else { '' }
    $itemName = if ($Name) { $Name } else { $Value }

    if (-not $itemName) {
        Write-Host 'Usage: .\cn.ps1 new <module|provider|data> <Name>' -ForegroundColor Yellow
        return
    }

    switch ($kind) {
        'module' {
            $relative = "Modules\$itemName.lua"
            $body = $Templates['Module'] -replace '__NAME__', $itemName `
                                          -replace '__STORE__', $itemName.ToLower() `
                                          -replace '__TYPE__', $itemName.ToUpper()
        }
        'provider' {
            $relative = "Providers\$itemName.lua"
            $body = $Templates['Provider'] -replace '__NAME__', $itemName
        }
        'data' {
            $relative = "Data\$itemName.lua"
            $body = $Templates['Data'] -replace '__NAME__', $itemName `
                                        -replace '__UPPER__', $itemName.ToUpper()
        }
        default {
            Write-Host 'Usage: .\cn.ps1 new <module|provider|data> <Name>' -ForegroundColor Yellow
            return
        }
    }

    if ((Test-Path -LiteralPath (Join-Path $script:Root $relative)) -and -not $Force) {
        Write-Host "$relative already exists. Use -Force to overwrite." -ForegroundColor Yellow
        return
    }

    Write-CNFile $relative $body

    Write-Host "Created $relative" -ForegroundColor Green

    Invoke-CNSync
}

function Invoke-CNCommand {
    Assert-CNWritable

    $cmdName = if ($Name) { $Name } else { $Target }

    if (-not $cmdName) {
        Write-Host 'Usage: .\cn.ps1 cmd <name> -Module <Module> [-Usage "<id>"] [-Help "..."] [-Order 50]' -ForegroundColor Yellow
        return
    }

    if (-not $Module) {
        Write-Host 'A target file is required: -Module <ModuleName|Providers\X|Commands.lua>' -ForegroundColor Yellow
        return
    }

    $relative = Resolve-CNModulePath $Module

    if (-not $relative) {
        Write-Host "Could not find a file for module '$Module'." -ForegroundColor Red
        Write-Host "Create it first: .\cn.ps1 new module $Module" -ForegroundColor Yellow
        return
    }

    $existing = Read-CNFile $relative

    if ($existing -match ('name\s*=\s*"' + [regex]::Escape($cmdName.ToLower()) + '"')) {
        Write-Host "/cn $cmdName is already registered in $relative." -ForegroundColor Yellow
        return
    }

    $block = $Templates['Command'] -replace '__CMD__', $cmdName.ToLower() `
                                    -replace '__USAGE__', ($Usage -replace '"', '\"') `
                                    -replace '__HELP__', (($Help -replace '"', '\"')) `
                                    -replace '__ORDER__', $Order

    Add-CNBlock -Relative $relative -Block $block

    Write-Host "Registered /cn $($cmdName.ToLower()) in $relative" -ForegroundColor Green
    Write-Host 'Fill in the handler, then /reload in game.' -ForegroundColor DarkGray
}

function Invoke-CNEvent {
    Assert-CNWritable

    $eventName = if ($Name) { $Name } else { $Target }

    if (-not $eventName) {
        Write-Host 'Usage: .\cn.ps1 event <EVENT_NAME> -Module <Module>' -ForegroundColor Yellow
        return
    }

    if (-not $Module) {
        Write-Host 'A target file is required: -Module <ModuleName>' -ForegroundColor Yellow
        return
    }

    $relative = Resolve-CNModulePath $Module

    if (-not $relative) {
        Write-Host "Could not find a file for module '$Module'." -ForegroundColor Red
        return
    }

    $eventName = $eventName.ToUpper()
    $existing  = Read-CNFile $relative

    if ($existing -match ('RegisterEvent\("' + [regex]::Escape($eventName) + '"')) {
        Write-Host "$eventName is already handled in $relative." -ForegroundColor Yellow
        return
    }

    $block = $Templates['Event'] -replace '__EVENT__', $eventName

    Add-CNBlock -Relative $relative -Block $block

    Write-Host "Registered $eventName in $relative" -ForegroundColor Green
}

function Invoke-CNData {
    Assert-CNWritable

    $kind = if ($Target) { $Target.ToLower() } else { '' }

    if ($kind -ne 'quest') {
        Write-Host 'Usage: .\cn.ps1 data quest <questID> -Name "Title" [-Expansion "TWW"] [-MapID 84] [-X 0.55] [-Y 0.42] [-Requires "123,456"]' -ForegroundColor Yellow
        return
    }

    $id = 0

    if (-not [int]::TryParse($Value, [ref] $id) -or $id -le 0) {
        Write-Host 'A positive quest ID is required.' -ForegroundColor Yellow
        return
    }

    $relative = 'Data\Quests.lua'
    $content  = Read-CNFile $relative

    if ($null -eq $content) { throw "$relative not found. Run: .\cn.ps1 init" }

    if ($content -match ('\[\s*' + $id + '\s*\]\s*=')) {
        Write-Host "Quest $id is already present in $relative." -ForegroundColor Yellow
        return
    }

    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add("    [$id] = {") | Out-Null

    if ($Name)      { $lines.Add('        name      = "' + ($Name -replace '"', '\"') + '",') | Out-Null }
    if ($Expansion) { $lines.Add('        expansion = "' + $Expansion + '",') | Out-Null }
    if ($MapID)     { $lines.Add("        mapID     = $MapID,") | Out-Null }
    if ($X)         { $lines.Add("        x         = $X,") | Out-Null }
    if ($Y)         { $lines.Add("        y         = $Y,") | Out-Null }

    if ($Requires) {
        $ids = ($Requires -split '[,\s]+' | Where-Object { $_ }) -join ', '
        $lines.Add("        requires  = { $ids },") | Out-Null
    }

    $lines.Add('    },') | Out-Null

    Add-CNBlock -Relative $relative -Block (($lines -join "`n")) -Marker $script:DataMark

    Write-Host "Added quest $id to $relative" -ForegroundColor Green
}

# ---------------------------------------------------------------------------
# HARVEST
# ---------------------------------------------------------------------------
#
# Closing the loop the design always described but never finished.
#
# The addon records the name, zone, coordinates and level of every quest you
# accept or turn in, permanently and account-wide. Until now the only way to
# get that out was /cn export, which prints it into a copy box -- so in
# practice it stayed in SavedVariables and the curated database stayed empty.
# That is what limits prerequisite forensics, and it is a tooling problem, not
# a data problem.
#
# This reads SavedVariables directly and folds anything new into
# Data\Quests.lua. Existing rows are never overwritten without -Force: curated
# data outranks observed data, which is the same source-ranking rule the addon
# itself applies.

# Extracts one balanced { ... } block starting at the first brace at or after
# $StartIndex. Lua tables nest, so a regex cannot do this correctly.
function Get-CNLuaBlock {
    param([string] $Text, [int] $StartIndex)

    $open = $Text.IndexOf('{', $StartIndex)

    if ($open -lt 0) { return $null }

    $depth    = 0
    $inString = $false
    $escaped  = $false

    for ($i = $open; $i -lt $Text.Length; $i++) {
        $char = $Text[$i]

        if ($escaped) { $escaped = $false; continue }

        if ($char -eq '\') { $escaped = $true; continue }

        if ($char -eq '"') { $inString = -not $inString; continue }

        if ($inString) { continue }

        if ($char -eq '{') { $depth++ }
        elseif ($char -eq '}') {
            $depth--

            if ($depth -eq 0) {
                return [PSCustomObject]@{
                    Body  = $Text.Substring($open + 1, $i - $open - 1)
                    End   = $i
                    Start = $open
                }
            }
        }
    }

    return $null
}

# Pulls [id] = { ... } records out of one SavedVariables table body.
function Get-CNSavedRecords {
    param([string] $Body)

    $records = @{}

    $index = 0

    while ($true) {
        $match = [regex]::Match($Body.Substring($index), '\[(\d+)\]\s*=\s*\{')

        if (-not $match.Success) { break }

        $id = [int] $match.Groups[1].Value

        $block = Get-CNLuaBlock -Text $Body -StartIndex ($index + $match.Index)

        if (-not $block) { break }

        $fields = @{}

        foreach ($field in [regex]::Matches($block.Body,
            '\["(\w+)"\]\s*=\s*("(?:[^"\\]|\\.)*"|[-\d.eE+]+|true|false)')) {

            $key   = $field.Groups[1].Value
            $value = $field.Groups[2].Value

            if ($value.StartsWith('"')) {
                $value = $value.Substring(1, $value.Length - 2) -replace '\\"', '"'
            }

            $fields[$key] = $value
        }

        # ARRAY FIELDS -- `["requires"] = { 123, 456 }`.
        #
        # The scalar matcher above cannot see these, which is why prerequisite
        # data harvested from real play could never reach Data\Quests.lua: the
        # addon wrote it, the toolkit could not read it, and nobody noticed
        # because both halves worked.
        foreach ($array in [regex]::Matches($block.Body,
            '\["(requires|unlocks|observedRequires)"\]\s*=\s*\{([^{}]*)\}')) {

            $ids = @()

            foreach ($number in [regex]::Matches($array.Groups[2].Value, '\d+')) {
                $ids += [int] $number.Value
            }

            if ($ids.Count -gt 0) {
                $fields[$array.Groups[1].Value + '_array'] = $ids
            }
        }

        if ($fields.Count -gt 0) { $records[$id] = $fields }

        $index = $block.End + 1

        if ($index -ge $Body.Length) { break }
    }

    return $records
}

# Where WoW keeps SavedVariables. Deriving it from the addon folder only works
# when the toolkit is running from inside AddOns -- and the recommended layout
# is a writable folder elsewhere with a junction back, precisely because
# Program Files is ACL-protected. So try the derivation, then the usual install
# locations.
function Get-CNSavedVariablesRoots {
    $roots = New-Object System.Collections.Generic.List[string]

    $candidate = $script:Root

    for ($i = 0; $i -lt 3; $i++) {
        $candidate = Split-Path -Parent $candidate

        if (-not $candidate) { break }
    }

    if ($candidate) {
        $roots.Add((Join-Path $candidate 'WTF\Account')) | Out-Null
    }

    foreach ($base in @($env:ProgramFiles, ${env:ProgramFiles(x86)}, 'C:\', 'D:\')) {
        if (-not $base) { continue }

        foreach ($flavour in @('_retail_', '_ptr_', '_classic_')) {
            $roots.Add((Join-Path $base "World of Warcraft\$flavour\WTF\Account")) | Out-Null
        }
    }

    return @($roots | Select-Object -Unique | Where-Object { Test-Path -LiteralPath $_ })
}

function Invoke-CNHarvest {
    Assert-CNWritable

    $saved = $null

    if ($Target) {
        if (-not (Test-Path -LiteralPath $Target)) {
            Write-Host "Not found: $Target" -ForegroundColor Yellow
            return
        }

        $saved = Get-Item -LiteralPath $Target
    }
    else {
        $roots = @(Get-CNSavedVariablesRoots)

        foreach ($root in $roots) {
            $found = Get-ChildItem -LiteralPath $root -Recurse -Filter 'CompletionNavigator.lua' -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending |
                Select-Object -First 1

            if ($found) { $saved = $found; break }
        }

        if (-not $saved) {
            Write-Host 'No SavedVariables found.' -ForegroundColor Yellow
            Write-Host ''

            if ($roots.Count -gt 0) {
                Write-Host '  Looked in:' -ForegroundColor DarkGray
                foreach ($root in $roots) { Write-Host "    $root" -ForegroundColor DarkGray }
            }
            else {
                Write-Host '  No WoW WTF\Account folder could be located.' -ForegroundColor DarkGray
            }

            Write-Host ''
            Write-Host '  Log in with the addon loaded and /reload once, then try again.' -ForegroundColor DarkGray
            Write-Host '  Or point at the file:  .\cn.ps1 harvest <path>' -ForegroundColor DarkGray
            return
        }
    }

    Write-Host "Reading $($saved.FullName)" -ForegroundColor DarkGray
    Write-Host ("  {0:N0} bytes, written {1}" -f $saved.Length,
        $saved.LastWriteTime.ToString('yyyy-MM-dd HH:mm')) -ForegroundColor DarkGray
    Write-Host ''

    $text = [System.IO.File]::ReadAllText($saved.FullName)

    $marker = [regex]::Match($text, '\["questHarvest"\]\s*=\s*\{')

    if (-not $marker.Success) {
        Write-Host 'No harvested quests in SavedVariables yet.' -ForegroundColor Yellow
        Write-Host '  The addon records quests as you accept and turn them in.' -ForegroundColor DarkGray
        return
    }

    $block = Get-CNLuaBlock -Text $text -StartIndex $marker.Index

    if (-not $block) {
        Write-Host 'questHarvest table is malformed; nothing was changed.' -ForegroundColor Red
        return
    }

    $harvested = Get-CNSavedRecords -Body $block.Body

    if ($harvested.Count -eq 0) {
        Write-Host 'No harvested quests found.' -ForegroundColor Yellow
        return
    }

    $relative = 'Data\Quests.lua'
    $existing = Read-CNFile $relative

    if ($null -eq $existing) { throw "$relative not found. Run: .\cn.ps1 init" }

    $added      = 0
    $skipped    = 0
    $unlocated  = 0
    $lines      = New-Object System.Collections.Generic.List[string]

    $merged = 0

    foreach ($id in ($harvested.Keys | Sort-Object)) {
        $record = $harvested[$id]

        if ($existing -match ('\[\s*' + $id + '\s*\]\s*=')) {
            # A ROW THAT EXISTS CAN STILL BE MISSING ITS CHAIN.
            #
            # Rows are usually added for a location long before enough
            # characters have walked a chain to make its prerequisites
            # believable. Skipping the whole row meant that evidence, once it
            # finally arrived, had nowhere to go.
            #
            # So: fill in `requires` where the row has none. Never replace one
            # that is already there -- curated data outranks observation, and
            # that rule is why this is an insert rather than an update.
            if (-not $record.ContainsKey('requires_array') -and
                $record.ContainsKey('observedRequires_array')) {

                $record['requires_array']    = $record['observedRequires_array']
                $record['requires_observed'] = $true
            }

            if ($record.ContainsKey('requires_array')) {
                $rowMatch = [regex]::Match($existing, '\[\s*' + $id + '\s*\]\s*=\s*\{')

                if ($rowMatch.Success) {
                    $rowBlock = Get-CNLuaBlock -Text $existing -StartIndex $rowMatch.Index

                    if ($rowBlock -and $rowBlock.Body -notmatch 'requires\s*=') {
                        $insert = '        requires  = { ' +
                            ($record.requires_array -join ', ') + ' },'

                        $existing = $existing.Substring(0, $rowBlock.Start + 1) +
                            "`n" + $insert + $existing.Substring($rowBlock.Start + 1)

                        $merged++
                        continue
                    }
                }
            }

            $skipped++
            continue
        }

        # A quest with no coordinates adds a name and nothing else. Useful,
        # but not what the static database exists for.
        if (-not ($record.ContainsKey('x') -and $record.ContainsKey('y'))) {
            $unlocated++

            if (-not $Force) { continue }
        }

        $lines.Add("    [$id] = {") | Out-Null

        if ($record.name) {
            $lines.Add('        name      = "' + ($record.name -replace '"', '\"') + '",') | Out-Null
        }

        if ($record.zone) { $lines.Add('        -- ' + $record.zone) | Out-Null }

        if ($record.mapID) { $lines.Add("        mapID     = $($record.mapID),") | Out-Null }

        if ($record.x -and $record.y) {
            $lines.Add("        x         = $($record.x),") | Out-Null
            $lines.Add("        y         = $($record.y),") | Out-Null
        }

        if ($record.requiresLevel) {
            $lines.Add("        requiresLevel = $($record.requiresLevel),") | Out-Null
        }

        if (-not $record.ContainsKey('requires_array') -and
            $record.ContainsKey('observedRequires_array')) {

            $record['requires_array']    = $record['observedRequires_array']
            $record['requires_observed'] = $true
        }

        if ($record.ContainsKey('requires_array')) {
            if ($record.ContainsKey('requires_observed')) {
                # Marked in the file, because the row now reads as curated data
                # and somebody -- probably me, in a year -- will want to know
                # which rows were only ever inferred from play.
                $lines.Add('        -- chain observed on three or more ' +
                    'characters; spot-check before trusting') | Out-Null
            }

            $lines.Add('        requires  = { ' +
                ($record.requires_array -join ', ') + ' },') | Out-Null
        }

        if ($record.ContainsKey('unlocks_array')) {
            $lines.Add('        unlocks   = { ' +
                ($record.unlocks_array -join ', ') + ' },') | Out-Null
        }

        $lines.Add('    },') | Out-Null

        $added++
    }

    Write-Host "Harvested in SavedVariables: $($harvested.Count)" -ForegroundColor White
    Write-Host "  already in $relative       $skipped" -ForegroundColor DarkGray
    Write-Host "  chains folded into existing rows $merged" -ForegroundColor $(if ($merged -gt 0) { 'Green' } else { 'DarkGray' })
    Write-Host "  without coordinates        $unlocated$(if (-not $Force -and $unlocated -gt 0) { '  (skipped; -Force includes them)' })" -ForegroundColor DarkGray
    Write-Host "  new rows to add            $added" -ForegroundColor $(if ($added -gt 0) { 'Green' } else { 'DarkGray' })
    Write-Host ''

    if ($added -eq 0 -and $merged -eq 0) {
        Write-Host 'Nothing to add.' -ForegroundColor Yellow
        return
    }

    Invoke-CNBackup -Quiet

    if ($merged -gt 0) {
        Write-CNFile $relative $existing

        Write-Host "Folded $merged prerequisite chain$(if ($merged -eq 1) { '' } else { 's' }) into existing rows." -ForegroundColor Green
    }

    if ($added -eq 0) {
        Write-Host ''
        Write-Host '  Next:  .\cn.ps1 check' -ForegroundColor DarkGray
        return
    }

    Add-CNBlock -Relative $relative -Block ($lines -join "`n") -Marker $script:DataMark

    Write-Host "Added $added quest$(if ($added -eq 1) { '' } else { 's' }) to $relative" -ForegroundColor Green
    Write-Host ''
    Write-Host '  Curated rows are never overwritten: if an ID is already present' -ForegroundColor DarkGray
    Write-Host '  it is left alone, because hand-checked data outranks observed data.' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  Next:  .\cn.ps1 check' -ForegroundColor DarkGray
}

function Invoke-CNVersion {
    Assert-CNWritable

    $new = if ($Target) { $Target } else { $Value }

    if (-not $new) {
        $toc = Read-CNFile 'CompletionNavigator.toc'
        $core = Read-CNFile 'Core.lua'

        $tocVersion  = if ($toc  -match '(?m)^##\s*Version:\s*(.+)$') { $Matches[1].Trim() } else { '?' }
        $coreVersion = if ($core -match 'CN\.version\s*=\s*"([^"]+)"') { $Matches[1] } else { '?' }

        Write-Host "toc:  $tocVersion"
        Write-Host "lua:  $coreVersion"

        if ($tocVersion -ne $coreVersion) {
            Write-Host 'MISMATCH. Fix with: .\cn.ps1 version <x.y.z>' -ForegroundColor Yellow
        }

        return
    }

    if ($new -notmatch '^\d+\.\d+\.\d+$') {
        Write-Host 'Version must look like 0.1.0' -ForegroundColor Yellow
        return
    }

    $toc = Read-CNFile 'CompletionNavigator.toc'
    $toc = [regex]::Replace($toc, '(?m)^##\s*Version:\s*.+$', "## Version: $new")
    Write-CNFile 'CompletionNavigator.toc' $toc

    $core = Read-CNFile 'Core.lua'
    $core = [regex]::Replace($core, 'CN\.version\s*=\s*"[^"]*"', ('CN.version     = "' + $new + '"'))
    Write-CNFile 'Core.lua' $core

    Write-Host "Version set to $new in both .toc and Core.lua." -ForegroundColor Green
}

function Invoke-CNBackup {
    param([switch] $Quiet)

    if (-not (Test-Path -LiteralPath (Join-Path $script:Root 'CompletionNavigator.toc'))) { return }

    New-Item -ItemType Directory -Path $script:BackupDir -Force | Out-Null

    $stamp   = Get-Date -Format 'yyyyMMdd-HHmmss'
    $archive = Join-Path $script:BackupDir "CompletionNavigator-$stamp.zip"

    $items = Get-ChildItem -LiteralPath $script:Root |
        Where-Object { $_.Name -ne '_backups' -and $_.Name -ne '.git' }

    if (-not $items) { return }

    Compress-Archive -Path $items.FullName -DestinationPath $archive -Force

    if (-not $Quiet) {
        Write-Host "Backup written: _backups\CompletionNavigator-$stamp.zip" -ForegroundColor Green
    }
    else {
        Write-Host "  backup  _backups\CompletionNavigator-$stamp.zip" -ForegroundColor DarkGray
    }
}

function Invoke-CNRestore {
    Assert-CNWritable

    if (-not (Test-Path -LiteralPath $script:BackupDir)) {
        Write-Host 'No backups exist.' -ForegroundColor Yellow
        return
    }

    $archive = Get-ChildItem -LiteralPath $script:BackupDir -Filter '*.zip' |
        Sort-Object LastWriteTime -Descending | Select-Object -First 1

    if (-not $archive) {
        Write-Host 'No backup archives found.' -ForegroundColor Yellow
        return
    }

    if (-not $Force) {
        Write-Host "Would restore: $($archive.Name)" -ForegroundColor Yellow
        Write-Host 'Re-run with -Force to overwrite the current files.' -ForegroundColor Yellow
        return
    }

    Expand-Archive -LiteralPath $archive.FullName -DestinationPath $script:Root -Force

    Write-Host "Restored $($archive.Name)" -ForegroundColor Green
}

function Get-CNGitHubToken {
    # A token turns 60 requests an hour into 5000. Read from the environment
    # first, then from a file the user can drop next to the toolkit.
    #
    # NEVER written by this script and never echoed. If it ends up in a file
    # it is because the user put it there deliberately.
    foreach ($name in 'CN_GITHUB_TOKEN', 'GITHUB_TOKEN', 'GH_TOKEN') {
        $value = [System.Environment]::GetEnvironmentVariable($name)

        if ($value) { return $value.Trim() }
    }

    $tokenFile = Join-Path $script:Root '.github-token'

    if (Test-Path $tokenFile) {
        $value = (Get-Content $tokenFile -Raw).Trim()

        if ($value) { return $value }
    }

    return $null
}

function Invoke-CNGitHubApi {
    param(
        [Parameter(Mandatory)] [string] $Uri,
        [int] $CacheSeconds = 25
    )

    # A cache, because the usual way to hit the rate limit is a person
    # pressing the same command repeatedly while waiting for a build. Two
    # calls per run against a budget of sixty an hour is about thirty runs;
    # somebody watching a release will do that in ten minutes.
    $cacheDir = Join-Path ([System.IO.Path]::GetTempPath()) 'cn-ci-cache'

    if (-not (Test-Path $cacheDir)) {
        New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null
    }

    $key   = [System.BitConverter]::ToString(
        [System.Security.Cryptography.MD5]::Create().ComputeHash(
            [System.Text.Encoding]::UTF8.GetBytes($Uri))).Replace('-', '')

    $cacheFile = Join-Path $cacheDir "$key.json"

    if ($CacheSeconds -gt 0 -and (Test-Path $cacheFile)) {
        $age = (Get-Date) - (Get-Item $cacheFile).LastWriteTime

        if ($age.TotalSeconds -lt $CacheSeconds) {
            $script:LastCallWasCached = $true

            return (Get-Content $cacheFile -Raw | ConvertFrom-Json)
        }
    }

    $headers = @{
        'User-Agent' = 'CompletionNavigator'
        'Accept'     = 'application/vnd.github+json'
    }

    $token = Get-CNGitHubToken

    if ($token) {
        $headers['Authorization'] = "Bearer $token"
    }

    $script:LastCallWasCached = $false

    try {
        $response = Invoke-WebRequest -Uri $Uri -Headers $headers -UseBasicParsing

        $script:RateRemaining = $response.Headers['X-RateLimit-Remaining']
        $script:RateReset     = $response.Headers['X-RateLimit-Reset']

        $response.Content | Set-Content -LiteralPath $cacheFile -Encoding UTF8

        return ($response.Content | ConvertFrom-Json)
    }
    catch {
        $status = $null

        if ($_.Exception.Response) {
            $status = [int] $_.Exception.Response.StatusCode
        }

        if ($status -eq 403 -or $status -eq 429) {
            # This is almost never "forbidden". It is the unauthenticated
            # budget of sixty requests an hour, spent.
            $resetText = 'shortly'

            try {
                $resetHeader = $_.Exception.Response.Headers['X-RateLimit-Reset']

                if ($resetHeader) {
                    $resetAt = [DateTimeOffset]::FromUnixTimeSeconds([int64] $resetHeader).ToLocalTime()
                    $minutes = [math]::Max(1, [math]::Ceiling(($resetAt - [DateTimeOffset]::Now).TotalMinutes))
                    $resetText = "in about $minutes minute(s), at $($resetAt.ToString('HH:mm'))"
                }
            }
            catch { }

            Write-Host ''
            Write-Host 'GitHub is rate-limiting this machine.' -ForegroundColor Yellow
            Write-Host "  Unauthenticated callers get 60 requests an hour. Yours resets $resetText." -ForegroundColor Yellow
            Write-Host ''
            Write-Host '  Two ways forward:' -ForegroundColor Cyan
            Write-Host '    1. Wait it out. Recent answers are cached for 25 seconds, so' -ForegroundColor Gray
            Write-Host '       re-running immediately no longer costs anything.' -ForegroundColor Gray
            Write-Host '    2. Use a token and get 5000 an hour instead:' -ForegroundColor Gray
            Write-Host '         $env:CN_GITHUB_TOKEN = "ghp_yourtoken"' -ForegroundColor White
            Write-Host '       A classic token with NO scopes ticked is enough for public' -ForegroundColor Gray
            Write-Host '       repositories. Create one at github.com/settings/tokens.' -ForegroundColor Gray
            Write-Host ''
            Write-Host "  Meanwhile: https://github.com/$script:Repo/actions" -ForegroundColor Cyan

            return $null
        }

        Write-Host "Could not reach the GitHub API: $($_.Exception.Message)" -ForegroundColor Yellow
        Write-Host "  https://github.com/$script:Repo/actions" -ForegroundColor Cyan

        return $null
    }
}

function Format-CNAge {
    param([string] $Timestamp)

    if (-not $Timestamp) { return '' }

    $started = [datetime]::Parse($Timestamp).ToUniversalTime()
    $span    = (Get-Date).ToUniversalTime() - $started

    if ($span.TotalHours -ge 1) {
        return ('{0:N0}h {1:N0}m' -f [math]::Floor($span.TotalHours), $span.Minutes)
    }

    return ('{0:N0}m' -f [math]::Max(0, $span.TotalMinutes))
}

function Resolve-CNRepo {
    # Prefer the actual remote. Hard-coding the upstream means a fork reports
    # somebody else's builds, which is worse than reporting none.
    $url = Invoke-CNGit @('config', '--get', 'remote.origin.url') 2>$null

    if ($url -and $url -match 'github\.com[:/](.+?)(?:\.git)?\s*$') {
        $script:Repo = $Matches[1].Trim()
    }

    return $script:Repo
}

# One invocation, followed to the end.
#
# The previous tool answered once and left you to press it again, and the way
# that ends is a 403 with no explanation of which 403 it is. Watching polls on
# a sane interval, stops when the run stops, and costs two calls a minute
# rather than two per keypress.
function Invoke-CNCIWatch {
    Resolve-CNRepo | Out-Null

    Write-Host ''
    Write-Host "Watching $script:Repo. Ctrl+C to stop." -ForegroundColor Cyan

    # WHICH VERSION THIS WORKING TREE IS. 0.67.2.
    #
    # `release X` then `ci -Watch` reads as one flow, and it is not: the watch
    # reports the newest run on GitHub, whatever that is. So a release that
    # never pushed a tag left the watch reporting the PREVIOUS version's run,
    # in the previous version's failure colour, with nothing anywhere saying
    # it was not the release just asked for. Twice, that looked exactly like
    # the new release failing.
    $expected = $null

    $tocPath = Join-Path $PWD 'CompletionNavigator.toc'

    if (Test-Path $tocPath) {
        $tocText = Get-Content $tocPath -Raw

        if ($tocText -match '(?m)^##\s*Version:\s*(.+)$') {
            $expected = $Matches[1].Trim()
        }
    }

    $warned = $false

    $interval = if (Get-CNGitHubToken) { 15 } else { 40 }

    while ($true) {
        $runs = Invoke-CNGitHubApi -Uri "https://api.github.com/repos/$script:Repo/actions/runs?per_page=1" -CacheSeconds 0

        if ($null -eq $runs) { return }

        $latest = $runs.workflow_runs | Select-Object -First 1

        if (-not $latest) {
            Write-Host 'No runs found.' -ForegroundColor Yellow
            return
        }

        $state = if ($latest.conclusion) { $latest.conclusion } else { $latest.status }

        $stamp = (Get-Date).ToString('HH:mm:ss')

        $colour = if ($latest.conclusion -eq 'success') { 'Green' }
                  elseif ($latest.conclusion) { 'Red' }
                  else { 'Yellow' }

        Write-Host ("  [{0}] {1,-22} {2,-12} {3}" -f `
            $stamp, $latest.display_title, $state, (Format-CNAge $latest.created_at)) -ForegroundColor $colour

        # THE RUN ON GITHUB IS NOT NECESSARILY THE RELEASE YOU JUST MADE.
        if ($expected -and -not $warned `
            -and ($latest.display_title -notmatch [regex]::Escape($expected))) {

            $warned = $true

            Write-Host ''
            Write-Host "  This is NOT a run of $expected, which is what this tree holds." -ForegroundColor Yellow
            Write-Host '  Nothing was pushed for it: check that .\cn.ps1 release succeeded' -ForegroundColor Yellow
            Write-Host '  and that the tag reached GitHub. What follows is an older run.' -ForegroundColor Yellow
            Write-Host ''
        }

        if ($latest.status -eq 'completed') {
            Write-Host ''

            if ($latest.conclusion -eq 'success') {
                Write-Host 'Done. The packager has uploaded to CurseForge.' -ForegroundColor Green
            }
            else {
                Write-Host "Finished as: $($latest.conclusion)" -ForegroundColor Red

                # THE LINK, HERE, NOW. Telling somebody to run a second
                # command to find out what broke is one round trip too many,
                # and 0.67.0 proved the second command could come back with
                # nothing.
                Write-Host "  $($latest.html_url)" -ForegroundColor Cyan
                Write-Host '  .\cn.ps1 ci names the failing step.' -ForegroundColor Gray
            }

            return
        }

        Start-Sleep -Seconds $interval
    }
}

function Invoke-CNCI {
    if ($Watch) {
        Invoke-CNCIWatch
        return
    }

    Resolve-CNRepo | Out-Null

    $runs = Invoke-CNGitHubApi -Uri "https://api.github.com/repos/$script:Repo/actions/runs?per_page=5"

    if ($null -eq $runs) { return }

    Write-Host ''
    Write-Host 'Recent workflow runs' -ForegroundColor Cyan

    foreach ($r in $runs.workflow_runs) {
        $colour = if ($r.conclusion -eq 'success') { 'Green' }
                  elseif ($r.conclusion -eq 'failure') { 'Red' }
                  elseif ($r.status -eq 'in_progress' -or $r.status -eq 'queued') { 'Yellow' }
                  else { 'Gray' }

        $state = if ($r.conclusion) { $r.conclusion } else { $r.status }

        Write-Host ('  {0,-22} {1,-12} {2}' -f `
            $r.display_title, $state, (Format-CNAge $r.created_at)) -ForegroundColor $colour
    }

    $latest = $runs.workflow_runs | Select-Object -First 1

    if (-not $latest) { return }

    Write-Host ''
    Write-Host "Latest: $($latest.display_title)   started $(Format-CNAge $latest.created_at) ago" -ForegroundColor Cyan

    $jobs = Invoke-CNGitHubApi -Uri $latest.jobs_url

    if ($null -eq $jobs) { return }

    # A RUN THAT FAILED SAYS SO AND SAYS WHERE, WHATEVER THE API RETURNED.
    #
    # 0.67.0 failed and this command printed one line -- "job 'release' is
    # completed" -- and then the API budget. No steps, no FAILED AT, and no
    # URL, because every one of those lives inside a loop over `$job.steps`
    # and that came back empty. The one command whose entire job is "tell me
    # what broke" told the author nothing at all, and did it silently, which
    # is worse than an error.
    #
    # The URL is printed FIRST and unconditionally on a failure, before
    # anything that depends on the shape of the response. 0.67.1.
    $conclusion = $latest.conclusion

    if ($conclusion -and $conclusion -ne 'success') {
        Write-Host ''
        Write-Host "This run $conclusion. The log is at:" -ForegroundColor Red
        Write-Host "  $($latest.html_url)" -ForegroundColor Cyan
    }

    foreach ($job in $jobs.jobs) {
        $jobState = if ($job.conclusion) { $job.conclusion } else { $job.status }

        Write-Host "  job '$($job.name)' is $jobState" -ForegroundColor Gray

        # STEPS CAN COME BACK EMPTY, and when they do that is itself the
        # finding. Re-asked once for the job on its own, because the list
        # endpoint has been seen to answer without them.
        $steps = $job.steps

        if (-not $steps -or @($steps).Count -eq 0) {
            $single = Invoke-CNGitHubApi -Uri (
                "https://api.github.com/repos/$script:Repo/actions/jobs/$($job.id)")

            if ($single) { $steps = $single.steps }
        }

        if (-not $steps -or @($steps).Count -eq 0) {
            Write-Host '  the API returned no step list for this job.' -ForegroundColor Yellow
            Write-Host "  Open the log: $($latest.html_url)" -ForegroundColor Cyan
            continue
        }

        $index = 0

        foreach ($step in $steps) {
            $index++

            $state = if ($step.conclusion) { $step.conclusion } else { $step.status }

            $colour = if ($step.conclusion -eq 'success') { 'DarkGray' }
                      elseif ($step.conclusion -eq 'failure') { 'Red' }
                      elseif ($step.status -eq 'in_progress') { 'Yellow' }
                      else { 'DarkGray' }

            $note = ''

            if ($step.status -eq 'in_progress' -and $step.started_at) {
                $running = Format-CNAge $step.started_at
                $note = "  <-- running for $running"
            }

            Write-Host ('  {0,-3} {1,-42} {2}{3}' -f $index, $step.name, $state, $note) -ForegroundColor $colour
        }

        $failed = $steps |
            Where-Object { $_.conclusion -eq 'failure' -or $_.conclusion -eq 'cancelled' } |
            Select-Object -First 1

        if ($failed) {
            Write-Host ''
            Write-Host "FAILED AT: $($failed.name) ($($failed.conclusion))" -ForegroundColor Red
            Write-Host "  $($latest.html_url)" -ForegroundColor Cyan
        }
        elseif ($jobState -eq 'failure' -or $jobState -eq 'cancelled') {
            # A JOB THAT FAILED WITH NO FAILED STEP IS A REAL CASE, and it has
            # exactly one common cause worth naming: the job hit its own
            # `timeout-minutes` while a step was still running, so nothing is
            # marked failed and the run is simply over.
            Write-Host ''
            Write-Host "The job $jobState with no step marked failed." -ForegroundColor Red
            Write-Host '  Usually the job-level timeout-minutes, hit while a step was running.' -ForegroundColor Gray
            Write-Host "  $($latest.html_url)" -ForegroundColor Cyan
        }
    }

    Write-Host ''

    if ($script:LastCallWasCached) {
        Write-Host '  (cached; re-running within 25s costs no API budget)' -ForegroundColor DarkGray
    }
    elseif ($script:RateRemaining) {
        $note = "  API budget remaining: $script:RateRemaining"

        if (-not (Get-CNGitHubToken)) {
            $note += ' of 60. Set $env:CN_GITHUB_TOKEN for 5000.'
        }

        $colour = if ([int] $script:RateRemaining -lt 10) { 'Yellow' } else { 'DarkGray' }

        Write-Host $note -ForegroundColor $colour
    }
}

function Invoke-CNCheck {
    $problems = 0

    Write-Host 'Completion Navigator :: check' -ForegroundColor Cyan
    Write-Host ''

    $toc = Read-CNFile 'CompletionNavigator.toc'

    if ($null -eq $toc) {
        Write-Host '  FAIL  CompletionNavigator.toc is missing.' -ForegroundColor Red
        return
    }

    if ($toc -notmatch [regex]::Escape($script:BeginMark)) {
        Write-Host '  FAIL  .toc is missing the CN:FILES markers. Re-run init or add them by hand.' -ForegroundColor Red
        $problems++
    }

    $listed = @()

    $startIndex = $toc.IndexOf($script:BeginMark)
    $endIndex   = $toc.IndexOf($script:EndMark)

    if ($startIndex -ge 0 -and $endIndex -gt $startIndex) {
        $inner = $toc.Substring($startIndex + $script:BeginMark.Length,
                                $endIndex - $startIndex - $script:BeginMark.Length)

        $listed = @($inner -split "`r?`n" |
            ForEach-Object { $_.Trim() } |
            Where-Object { $_ -and $_ -notmatch '^#' })
    }

    $onDisk = @(Get-CNLuaFiles)

    foreach ($file in $listed) {
        if (-not (Test-Path -LiteralPath (Join-Path $script:Root $file))) {
            Write-Host "  FAIL  .toc lists a missing file: $file" -ForegroundColor Red
            $problems++
        }
    }

    # The client loads Bindings.xml on its own. Listing it sends it to the
    # FrameXML parser, which errors with "Unrecognized XML: Binding".
    if ($listed -contains 'Bindings.xml') {
        Write-Host '  FAIL  Bindings.xml must not be listed in the .toc (run: .\cn.ps1 sync)' -ForegroundColor Red
        $problems++
    }

    foreach ($file in $onDisk) {
        if ($listed -notcontains $file) {
            Write-Host "  WARN  on disk but not in .toc: $file  (run: .\cn.ps1 sync)" -ForegroundColor Yellow
            $problems++
        }
    }

    # The .toc can point IconTexture at addon art. WoW fails silently on a
    # missing texture, so a typo here produces a blank icon and no error.
    if ($toc -match '(?m)^##\s*IconTexture:\s*(.+)$') {
        $iconPath = $Matches[1].Trim()

        if ($iconPath -match 'AddOns\\CompletionNavigator\\(.+)$') {
            $relativeIcon = $Matches[1] -replace '/', '\'

            $found = $false

            foreach ($extension in @('.tga', '.blp', '')) {
                if (Test-Path -LiteralPath (Join-Path $script:Root ($relativeIcon + $extension))) {
                    $found = $true
                    break
                }
            }

            if (-not $found) {
                Write-Host "  FAIL  IconTexture points at a missing file: $relativeIcon(.tga)" -ForegroundColor Red
                $problems++
            }
            else {
                Write-Host "  ok    IconTexture resolves to $relativeIcon.tga" -ForegroundColor DarkGray
            }
        }
    }

    # A HEADER FIELD PRESENT AND EMPTY IS NOT THE SAME AS ABSENT.
    #
    # `## X-Wago-ID:` with nothing after it sat in the .toc for many releases.
    # The packager reads that header to decide whether to publish to Wago, and
    # a blank value is a value: it is asked to upload to a project id of "".
    # An absent header is understood; an empty one has to be interpreted.
    #
    # Applies to every X- field, because the same trap is there for each.
    foreach ($match in [regex]::Matches($toc, '(?m)^##\s*(X-[A-Za-z0-9-]+)\s*:\s*$')) {
        Write-Host "  FAIL  .toc has $($match.Groups[1].Value) with no value." -ForegroundColor Red
        Write-Host '        Fill it in or delete the line; an empty header is not an absent one.' -ForegroundColor DarkGray
        $problems++
    }

    # Byte-order marks break some Lua parsers and look like garbage in game.
    foreach ($file in $onDisk) {
        $bytes = [System.IO.File]::ReadAllBytes((Join-Path $script:Root $file))

        if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
            Write-Host "  FAIL  UTF-8 BOM in $file" -ForegroundColor Red
            $problems++
        }
    }

    # Duplicate slash command registrations.
    $seen = @{}

    foreach ($file in $onDisk) {
        $content = Read-CNFile $file

        foreach ($match in [regex]::Matches($content, '(?m)^CN:RegisterCommand\s*\{\s*name\s*=\s*"([^"]+)"')) {
            $cmd = $match.Groups[1].Value

            if ($seen.ContainsKey($cmd)) {
                Write-Host "  FAIL  /cn $cmd registered twice ($($seen[$cmd]) and $file)" -ForegroundColor Red
                $problems++
            }
            else {
                $seen[$cmd] = $file
            }
        }
    }

    # TRANSLATIONS OF STRINGS THAT NO LONGER EXIST.
    #
    # The key IS the English string, which is what makes a missing translation
    # fall back to readable English instead of to a blank label. The price is
    # that rewording a string silently orphans every translation of it: nothing
    # errors, nothing is missing, the German player just quietly sees English
    # again. Locales\enUS.lua carries the canonical key list, and this fails
    # when a locale file translates something that is not on it.
    $canonical = Read-CNFile 'Locales\enUS.lua'

    if ($canonical) {
        $known = @{}

        foreach ($match in [regex]::Matches($canonical, '(?m)^\s*"((?:[^"\\]|\\.)*)",\s*$')) {
            $known[$match.Groups[1].Value] = $true
        }

        if ($known.Count -eq 0) {
            Write-Host '  FAIL  Locales\enUS.lua lists no keys.' -ForegroundColor Red
            $problems++
        }

        # A DUPLICATE IN THE CANONICAL LIST IS NOT HARMLESS.
        #
        # This file is the one authoritative answer to "which strings does the
        # addon use", and every coverage number printed below is a fraction of
        # its length. 0.45.0 listed two keys twice, so the list claimed 48
        # entries for 46 strings and every count reported against it was
        # wrong.
        $seenKeys = @{}
        $duplicateKeys = @()

        foreach ($match in [regex]::Matches($canonical, '(?m)^\s*"((?:[^"\\]|\\.)*)",\s*$')) {
            $key = $match.Groups[1].Value

            if ($seenKeys.ContainsKey($key)) {
                $duplicateKeys += $key
            }
            else {
                $seenKeys[$key] = $true
            }
        }

        if ($duplicateKeys.Count -gt 0) {
            foreach ($key in ($duplicateKeys | Sort-Object -Unique)) {
                Write-Host "  FAIL  Locales\enUS.lua lists `"$key`" more than once." -ForegroundColor Red
            }

            $problems++
        }

        $localeDir = Join-Path (Get-Location) 'Locales'

        if (Test-Path $localeDir) {
            $orphans = 0

            foreach ($localeFile in Get-ChildItem -Path $localeDir -Filter '*.lua') {
                if ($localeFile.Name -eq 'enUS.lua') { continue }

                $body = Get-Content -Raw -LiteralPath $localeFile.FullName

                foreach ($match in [regex]::Matches($body, '\["((?:[^"\\]|\\.)*)"\]\s*=')) {
                    $key = $match.Groups[1].Value

                    if (-not $known.ContainsKey($key)) {
                        Write-Host "  FAIL  $($localeFile.Name) translates `"$key`", which is not a key this addon uses." -ForegroundColor Red
                        $orphans++
                        $problems++
                    }
                }
            }

            # THE OTHER DIRECTION, WHICH IS THE ONE THAT BITES.
            #
            # The check above catches a locale file translating a key that no
            # longer exists. The failure that actually happens is the reverse:
            # somebody edits the English wording of a string, and because the
            # key IS the English string, every translation of it is silently
            # orphaned -- the addon carries on showing English to a German
            # player and nothing anywhere says so.
            #
            # A warning rather than a failure: a key with no translations yet
            # is the normal state of a new string, not a mistake.
            $translated = @{}

            # AND THE FORMAT SPECIFIERS HAVE TO MATCH. 0.79.0.
            #
            # A translation carrying %s where its key has %d throws inside
            # string.format at runtime -- in that language only, on the
            # machine of a player who cannot read the stack trace, and never
            # on the developer's. The lint checked that keys EXIST and never
            # that they are usable.
            #
            # Three of the keys added in 0.78.0 are format strings, which is
            # exactly the shape that trips this, and the translator export
            # invites hand-edited submissions.
            $specifierPattern = '%[-+ #0]*\d*\.?\d*[diouxXeEfgGqcs]'

            $mismatched = @()

            foreach ($localeFile in Get-ChildItem -Path $localeDir -Filter '*.lua') {
                if ($localeFile.Name -eq 'enUS.lua') { continue }

                $body = Get-Content -Raw -LiteralPath $localeFile.FullName

                foreach ($match in [regex]::Matches($body,
                        '\["((?:[^"\\]|\\.)*)"\]\s*=\s*"((?:[^"\\]|\\.)*)"')) {

                    $key   = $match.Groups[1].Value
                    $value = $match.Groups[2].Value

                    $translated[$key] = $true

                    $wanted = @([regex]::Matches($key, $specifierPattern) |
                        ForEach-Object { $_.Value } | Sort-Object)
                    $got    = @([regex]::Matches($value, $specifierPattern) |
                        ForEach-Object { $_.Value } | Sort-Object)

                    if (($wanted -join ',') -ne ($got -join ',')) {
                        $mismatched += "$($localeFile.Name): `"$key`" has " +
                            "$($got -join ' ') where the English has " +
                            "$($wanted -join ' ')"
                    }
                }

                # Keys whose value is not a plain string still count as
                # translated; only the specifier check needs the value.
                foreach ($match in [regex]::Matches($body, '\["((?:[^"\\]|\\.)*)"\]\s*=')) {
                    $translated[$match.Groups[1].Value] = $true
                }
            }

            if ($mismatched.Count -gt 0) {
                Write-Host "  FAIL  $($mismatched.Count) translation(s) would throw at runtime:" -ForegroundColor Red

                foreach ($line in $mismatched) {
                    Write-Host "          $line" -ForegroundColor Red
                }

                Write-Host '        A %s where the English has %d throws inside string.format,' -ForegroundColor DarkGray
                Write-Host '        in that language only.' -ForegroundColor DarkGray

                $problems++
            }
            else {
                Write-Host '  ok    every translation uses the same format specifiers' -ForegroundColor DarkGray
            }

            $untranslated = @()

            foreach ($key in $known.Keys) {
                if (-not $translated.ContainsKey($key)) { $untranslated += $key }
            }

            # A NOTE THAT NOBODY ACTS ON IS NOT A CHECK.
            #
            # This printed "1 of 46 strings have no translation in any locale"
            # for four consecutive releases and was scrolled past every time,
            # including by the author of the string. A key translated in NO
            # locale is not partial coverage -- it is a string that was added
            # and never handed to a translator, which is the exact thing this
            # lint was written for. So it fails, and it NAMES the string,
            # because "1 of 46" is not actionable and the name is.
            #
            # Partial coverage stays a note: a key translated into six
            # languages and not the seventh is ordinary work in progress.
            if ($untranslated.Count -gt 0) {
                Write-Host "  FAIL  $($untranslated.Count) of $($known.Count) strings have no translation in ANY locale:" -ForegroundColor Red

                foreach ($key in ($untranslated | Sort-Object)) {
                    Write-Host "          `"$key`"" -ForegroundColor Red
                }

                Write-Host '        Add them to every Locales\*.lua file, or remove them from' -ForegroundColor DarkGray
                Write-Host '        Locales\enUS.lua if the addon no longer uses them.' -ForegroundColor DarkGray

                $problems++
            }

            if ($orphans -eq 0) {
                Write-Host "  ok    every translation matches one of $($known.Count) live strings" -ForegroundColor DarkGray
            }
        }
    }

    # Version agreement.
    $core = Read-CNFile 'Core.lua'

    if ($core) {
        $tocVersion  = if ($toc  -match '(?m)^##\s*Version:\s*(.+)$') { $Matches[1].Trim() } else { $null }
        $coreVersion = if ($core -match 'CN\.version\s*=\s*"([^"]+)"') { $Matches[1] } else { $null }

        if ($tocVersion -and $coreVersion -and $tocVersion -ne $coreVersion) {
            Write-Host "  FAIL  version mismatch: .toc $tocVersion vs Core.lua $coreVersion" -ForegroundColor Red
            $problems++
        }

        # A cn.ps1 older than the tree it manages will scaffold a previous
        # release over the top and report success. That failure is otherwise
        # completely silent, so it is worth being loud about.
        if ($coreVersion -and (Compare-CNVersion $script:ToolkitVersion $coreVersion) -lt 0) {
            Write-Host "  FAIL  this cn.ps1 carries $script:ToolkitVersion but the tree is $coreVersion." -ForegroundColor Red
            Write-Host '        Running init would downgrade your source. Get the current cn.ps1.' -ForegroundColor Red
            $problems++
        }
        elseif ($coreVersion -eq $script:ToolkitVersion) {
            Write-Host "  ok    toolkit and tree agree at $script:ToolkitVersion" -ForegroundColor DarkGray
        }
        else {
            # THE OTHER DIRECTION, WHICH HAD NO BRANCH AT ALL.
            #
            # The check above catches a cn.ps1 OLDER than the tree, because
            # that one would downgrade source. The case that actually happens
            # is the reverse: a new cn.ps1 arrives, `init` refuses because
            # Core.lua already exists, and the tree is silently left a release
            # behind while every other line of this check reports on the old
            # source. That is exactly the silent failure the first branch was
            # written to prevent, and it went uncaught in 0.46.0 -- the run
            # printed "project page reviewed for 0.45.0" and nothing said why.
            Write-Host "  FAIL  this cn.ps1 carries $script:ToolkitVersion but the tree on disk is $coreVersion." -ForegroundColor Red
            Write-Host '        `init` will not overwrite an existing tree. Run:  .\cn.ps1 init -Force' -ForegroundColor Yellow
            Write-Host '        Your SavedVariables and _curseforge copy are untouched by it.' -ForegroundColor DarkGray
            $problems++
        }

        # THE PROJECT PAGE MUST BE CONSIDERED EVERY RELEASE.
        #
        # Not "updated" -- considered. A release with no user-visible change
        # legitimately needs no new copy, but that has to be a decision
        # someone made, not one that happened because nobody looked. It
        # happened because nobody looked, and the author had to ask.
        #
        # So the page carries the version it was last reviewed against, and
        # this fails until that matches the tree. Editing the description
        # updates it; deciding it needs no edit means bumping the marker,
        # which is a five-second acknowledgement that the question was asked.
        $reviewed = Read-CNFile '_curseforge\REVIEWED.txt'

        if ($null -eq $reviewed) {
            Write-Host '  FAIL  _curseforge\REVIEWED.txt is missing.' -ForegroundColor Red
            Write-Host '        The project page must be reviewed against each release.' -ForegroundColor Red
            $problems++
        }
        else {
            $reviewed = $reviewed.Trim()

            if ($coreVersion -and $reviewed -ne $coreVersion) {
                Write-Host "  FAIL  the project page was last reviewed for $reviewed; the tree is $coreVersion." -ForegroundColor Red
                Write-Host '        Update _curseforge\DESCRIPTION.md and SUMMARY.txt if this release' -ForegroundColor Red
                Write-Host '        changes anything a player would notice -- including how fast or' -ForegroundColor Red
                Write-Host '        how accurate it is -- then put the version in REVIEWED.txt.' -ForegroundColor Red
                $problems++
            }
            else {
                Write-Host "  ok    project page reviewed for $reviewed" -ForegroundColor DarkGray
            }
        }
    }

    # THE STUB AUDIT IS ONLY AS GOOD AS THE RECORDING BEHIND IT.
    #
    # harness.lua audits its own stubs against fixtures\captured.lua, which is
    # the strongest test in this project -- nine defects came from a stub that
    # modelled the world more simply than the world is. Until 0.46.0 a missing
    # recording was advisory everywhere, so the audit could be absent for
    # months while every run still printed ALL CHECKS PASSED.
    #
    # It cannot be blocking everywhere: CI has no game client and never will.
    # So it is blocking exactly where a recording is possible -- a machine with
    # World of Warcraft installed -- and silent where it is not.
    $fixture = Join-Path (Get-Location) 'fixtures\captured.lua'

    # Guarded: this probes Windows drive letters and throws outright on a
    # PowerShell host that has none. A check that cannot answer "is there a
    # client here" must answer "no" rather than stop the whole run.
    $roots = @()

    try { $roots = @(Get-CNSavedVariablesRoots) } catch { $roots = @() }

    $luacForFixture = Get-Command 'luac54.exe', 'luac.exe', 'luac', 'luac5.4', 'luac5.3' -ErrorAction SilentlyContinue |
        Select-Object -First 1

    # STRAY .lua FILES IN fixtures\ ARE NOT RECORDINGS.
    #
    # `cn.ps1 fixtures` writes exactly one file, captured.lua. Anything else
    # under fixtures\ was put there by hand, is read by nothing, and -- as
    # happened with a `captures.lua` that would not parse -- can look like a
    # broken part of the addon to any tool that walks the tree.
    $fixtureDir = Join-Path (Get-Location) 'fixtures'

    if (Test-Path -LiteralPath $fixtureDir) {
        $stray = @(Get-ChildItem -LiteralPath $fixtureDir -File -Filter '*.lua' -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -ne 'captured.lua' })

        foreach ($file in $stray) {
            Write-Host "  WARN  fixtures\$($file.Name) is not a file this toolkit writes." -ForegroundColor Yellow
            Write-Host '        Only fixtures\captured.lua is read by anything. Delete it.' -ForegroundColor DarkGray
            $problems++
        }
    }

    if (Test-Path -LiteralPath $fixture) {
        $recording = [System.IO.File]::ReadAllText($fixture)

        # DOES IT ACTUALLY LOAD?
        #
        # This block used to regex the file for a version number and report
        # "stub audit backed by a recording" on the strength of finding one.
        # Every recording ever written was malformed Lua -- the writer emitted
        # the block's interior without its braces -- so the audit had never
        # run, and this line said it had. A check that reads a file with a
        # regular expression is not a check that the file is loadable.
        if ($recording -notmatch '(?m)^return\s*\{') {
            Write-Host '  FAIL  fixtures\captured.lua is not loadable Lua (no `return {`).' -ForegroundColor Red
            Write-Host '        Re-run:  .\cn.ps1 fixtures' -ForegroundColor Yellow
            $problems++
        }
        elseif ($luacForFixture) {
            $parsed = Invoke-CNNative -Executable $luacForFixture.Source `
                -Arguments @('-p', $fixture) -Quiet

            if (-not $parsed.Ok) {
                Write-Host "  FAIL  fixtures\captured.lua does not parse: $($parsed.Output -join ' ')" -ForegroundColor Red
                Write-Host '        Re-run:  .\cn.ps1 fixtures' -ForegroundColor Yellow
                $problems++
            }
        }

        $recordedInterface =
            if ($recording -match '\["interface"\]\s*=\s*(\d+)') { [int]$Matches[1] } else { $null }

        $recordedBuild =
            if ($recording -match '\["build"\]\s*=\s*"([^"]+)"') { $Matches[1] } else { $null }

        $claimed =
            if ($toc -match '(?m)^##\s*Interface:\s*(\d+)') { [int]$Matches[1] } else { $null }

        if ($recordedInterface -and $claimed -and $recordedInterface -lt $claimed) {
            Write-Host "  FAIL  fixtures\captured.lua is from client $recordedInterface; the .toc claims $claimed." -ForegroundColor Red
            Write-Host '        Re-capture, or the stub audit is about a game that has been patched.' -ForegroundColor Red
            $problems++
        }
        elseif ($null -eq $recordedInterface) {
            Write-Host '  note  the recording predates 0.46.0 and carries no client version; re-capture when convenient' -ForegroundColor DarkGray
        }
        else {
            Write-Host "  ok    stub audit backed by a recording from client $recordedInterface (build $recordedBuild)" -ForegroundColor DarkGray
        }
    }
    elseif ($roots.Count -gt 0) {
        Write-Host '  FAIL  no fixtures\captured.lua, and World of Warcraft is installed on this machine.' -ForegroundColor Red
        Write-Host '        In game: /cn capture, then log out, then .\cn.ps1 fixtures' -ForegroundColor Red
        Write-Host '        Without it the harness stubs are unverified against any real client.' -ForegroundColor Red
        $problems++
    }
    else {
        Write-Host '  note  no game client on this machine; stub audit not possible here' -ForegroundColor DarkGray
    }

    # Optional real syntax check if a Lua binary is on PATH.
    $luac = Get-Command 'luac54.exe', 'luac.exe', 'luac', 'luac5.4', 'luac5.3' -ErrorAction SilentlyContinue |
        Select-Object -First 1

    if ($luac) {
        foreach ($file in $onDisk) {
            # Same trap as git: luac writes syntax errors to stderr, so under
            # $ErrorActionPreference = 'Stop' the first bad file would have
            # terminated the whole check instead of being reported.
            $result = Invoke-CNNative -Executable $luac.Source `
                -Arguments @('-p', (Join-Path $script:Root $file)) -Quiet

            if (-not $result.Ok) {
                Write-Host "  FAIL  $file :: $($result.Output -join ' ')" -ForegroundColor Red
                $problems++
            }
        }

        Write-Host "  ok    syntax checked with $($luac.Name)" -ForegroundColor DarkGray
    }
    else {
        Write-Host '  note  no luac on PATH; syntax not verified. (winget install DEVCOM.Lua)' -ForegroundColor DarkGray
    }

    Write-Host ''

    if ($problems -eq 0) {
        Write-Host "All checks passed. $($onDisk.Count) Lua files." -ForegroundColor Green
    }
    else {
        Write-Host "$problems problem(s) found." -ForegroundColor Yellow
    }

    return $problems
}

# Returns -1, 0 or 1. Non-numeric or missing parts sort low rather than
# throwing, because a version string is not worth crashing a build over.
function Compare-CNVersion {
    param([string] $Left, [string] $Right)

    $leftParts  = @(($Left  -split '\.') | ForEach-Object { [int]($_ -replace '\D', '0') })
    $rightParts = @(($Right -split '\.') | ForEach-Object { [int]($_ -replace '\D', '0') })

    for ($i = 0; $i -lt 3; $i++) {
        $l = if ($i -lt $leftParts.Count)  { $leftParts[$i] }  else { 0 }
        $r = if ($i -lt $rightParts.Count) { $rightParts[$i] } else { 0 }

        if ($l -lt $r) { return -1 }
        if ($l -gt $r) { return 1 }
    }

    return 0
}

function Invoke-CNList {
    $files = @(Get-CNLoadOrder)

    Write-Host ''
    Write-Host 'Load order' -ForegroundColor Cyan

    $index = 1

    foreach ($file in $files) {
        $size = (Get-Item -LiteralPath (Join-Path $script:Root $file)).Length
        Write-Host ("  {0,2}. {1,-32} {2,7} bytes" -f $index, $file, $size)
        $index++
    }

    Write-Host ''
    Write-Host 'Slash commands' -ForegroundColor Cyan

    foreach ($file in $files) {
        $content = Read-CNFile $file

        foreach ($match in [regex]::Matches($content, '(?ms)^CN:RegisterCommand\s*\{(?<body>.*?)^\}')) {
            $body = $match.Groups['body'].Value

            $cmd   = if ($body -match 'name\s*=\s*"([^"]*)"') { $Matches[1] } else { '?' }
            $usage = if ($body -match 'args\s*=\s*"([^"]*)"') { $Matches[1] } else { '' }
            $desc  = if ($body -match 'help\s*=\s*"([^"]*)"') { $Matches[1] } else { '' }

            Write-Host ("  /cn {0,-16} {1,-18} {2}" -f $cmd, $usage, $desc)
        }
    }

    Write-Host ''
    Write-Host 'Events' -ForegroundColor Cyan

    foreach ($file in $files) {
        $content = Read-CNFile $file

        foreach ($match in [regex]::Matches($content, '(?m)^CN:RegisterEvent\("([A-Z_]+)"')) {
            Write-Host ("  {0,-38} {1}" -f $match.Groups[1].Value, $file)
        }
    }

    Write-Host ''
}

function Invoke-CNSavedVars {
    # ...\_retail_\Interface\AddOns\CompletionNavigator -> ...\_retail_
    $retail = Split-Path -Parent (Split-Path -Parent (Split-Path -Parent $script:Root))
    $wtf    = Join-Path $retail 'WTF\Account'

    if (-not (Test-Path -LiteralPath $wtf)) {
        Write-Host "WTF folder not found at: $wtf" -ForegroundColor Yellow
        return
    }

    $found = Get-ChildItem -LiteralPath $wtf -Recurse -Filter 'CompletionNavigator.lua' -File -ErrorAction SilentlyContinue

    if (-not $found) {
        Write-Host 'No SavedVariables written yet. Log in and /reload once.' -ForegroundColor Yellow
        return
    }

    foreach ($file in $found) {
        Write-Host ("{0,10:N0} bytes  {1}  {2}" -f $file.Length, $file.LastWriteTime.ToString('yyyy-MM-dd HH:mm'), $file.FullName)
    }

    if ($Force) { & notepad.exe $found[0].FullName }
}

function Invoke-CNGitInit {
    Assert-CNWritable

    if (-not (Assert-CNGit)) { return }

    if (Test-Path -LiteralPath (Join-Path $script:Root '.git')) {
        Write-Host 'Already a git repository.' -ForegroundColor Yellow
        return
    }

    $ignore = @'
_backups/
*.zip
*.bak
Thumbs.db
desktop.ini
'@

    Write-CNFile '.gitignore' $ignore

    Push-Location $script:Root

    try {
        Invoke-CNGit @('init', '-b', 'main') -Quiet | Out-Null

        # Set the repository identity BEFORE the first commit. Inheriting a
        # machine-wide identity here silently stamps the wrong address onto
        # the initial commit, and correcting it afterwards means rewriting
        # history.
        $commitName  = if ($Name)  { $Name }  else { 'Travis A. Bryan I' }
        $commitEmail = if ($Email) { $Email } else { 'developer@dambeaverstudios.com' }

        Invoke-CNGit @('config', 'user.name', $commitName) -Quiet | Out-Null
        Invoke-CNGit @('config', 'user.email', $commitEmail) -Quiet | Out-Null

        Invoke-CNGit @('add', '-A') -Quiet | Out-Null
        Invoke-CNGit @('commit', '-m', 'Completion Navigator: initial commit') -Quiet | Out-Null

        Write-Host "Git repository initialized." -ForegroundColor Green
        Write-Host "  identity: $commitName <$commitEmail>" -ForegroundColor DarkGray
        Write-Host '  (override with -Name and -Email)' -ForegroundColor DarkGray
    }
    finally {
        Pop-Location
    }
}

function Invoke-CNPackage {
    $toc = Read-CNFile 'CompletionNavigator.toc'

    if ($null -eq $toc) {
        Write-Host 'CompletionNavigator.toc not found. Nothing to package.' -ForegroundColor Red
        return
    }

    $version = if ($toc -match '(?m)^##\s*Version:\s*(.+)$') { $Matches[1].Trim() } else { '0.0.0' }

    # Run the validator first: shipping a broken .toc to someone else wastes
    # their time, not yours.
    Write-Host 'Validating before packaging...' -ForegroundColor Cyan
    Invoke-CNCheck
    Write-Host ''

    # [System.IO.Path]::GetTempPath() works everywhere; $env:TEMP is not set
    # on every host PowerShell runs on.
    $staging = Join-Path ([System.IO.Path]::GetTempPath()) ("cn-package-" + [guid]::NewGuid().ToString('N'))
    $inner   = Join-Path $staging 'CompletionNavigator'

    New-Item -ItemType Directory -Path $inner -Force | Out-Null

    # Ship only what the game loads. The toolkit, backups, git metadata and
    # scratch folders are yours, not the recipient's.
    #
    # harness.lua matters most here: it stubs the entire client API, so a copy
    # in someone's AddOns folder would replace live functions with fakes.
    $excludedNames      = @('_backups', '.git', '.gitignore', '_to_delete',
                            '.github', '.pkgmeta', '_curseforge', '.luacheckrc',
                            'ROADMAP.md', 'harness.lua', 'bench.lua', 'pstest.sh',
                            'coverage.sh', 'luacov.stats.out', 'luacov.report.out')
    $excludedExtensions = @('.ps1', '.psm1', '.zip', '.bak')

    $shipped = 0

    Get-ChildItem -LiteralPath $script:Root |
        Where-Object {
            $excludedNames -notcontains $_.Name -and
            $excludedExtensions -notcontains $_.Extension
        } |
        ForEach-Object {
            Copy-Item -LiteralPath $_.FullName -Destination $inner -Recurse -Force
            $shipped++
        }

    New-Item -ItemType Directory -Path $script:BackupDir -Force | Out-Null

    $archiveName = "CompletionNavigator-$version.zip"
    $out         = Join-Path $script:BackupDir $archiveName

    Compress-Archive -Path $inner -DestinationPath $out -Force

    # Verify the archive really contains CompletionNavigator/*.toc at the
    # top level. Anything else will not load when it is unzipped.
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue

    $entries = $null

    try {
        $zip     = [System.IO.Compression.ZipFile]::OpenRead($out)
        $entries = @($zip.Entries | ForEach-Object { $_.FullName })
        $zip.Dispose()
    }
    catch {
        Write-Host "  WARN  could not read back the archive: $_" -ForegroundColor Yellow
    }

    Remove-Item -LiteralPath $staging -Recurse -Force

    Write-Host "Packaged: _backups\$archiveName" -ForegroundColor Green
    Write-Host "  version: $version"
    Write-Host "  top-level items: $shipped"

    if ($entries) {
        $hasToc = $entries | Where-Object { $_ -match '^CompletionNavigator/.*\.toc$' }

        if ($hasToc) {
            Write-Host "  structure: OK (CompletionNavigator\ at the root)" -ForegroundColor Green
        }
        else {
            Write-Host '  FAIL  the archive does not contain CompletionNavigator\*.toc at its root.' -ForegroundColor Red
        }

        Write-Host "  files in archive: $($entries.Count)"
    }

    Write-Host ''
    Write-Host 'Send that zip. The recipient unzips it into:' -ForegroundColor Cyan
    Write-Host '  <World of Warcraft>\_retail_\Interface\AddOns\' -ForegroundColor DarkGray
    Write-Host 'so they end up with ...\AddOns\CompletionNavigator\CompletionNavigator.toc' -ForegroundColor DarkGray
    Write-Host 'Then /reload, or restart the client if it was running.' -ForegroundColor DarkGray
}


# Native commands and $ErrorActionPreference = 'Stop' do not mix.
#
# On Windows PowerShell 5.1, stderr from a native command under 2>&1 arrives
# as ErrorRecord objects, and with the preference set to Stop the FIRST one
# terminates the script. git writes its ordinary progress to stderr, so
# `git push 2>&1` killed a release mid-way through a push that had actually
# succeeded. PowerShell 7 on Linux does not behave this way, which is exactly
# why it was not caught here.
#
# Every native invocation in this file goes through this function: the
# preference is neutralized for the duration, stderr is rendered as its
# message rather than its type name, and the real exit code comes back.
function Invoke-CNNative {
    param(
        [Parameter(Mandatory = $true)] [string] $Executable,
        [string[]] $Arguments = @(),
        [switch] $Quiet
    )

    $previousPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'

    $lines = New-Object System.Collections.Generic.List[string]
    $code  = 0

    try {
        $raw = & $Executable @Arguments 2>&1

        $code = if ($null -ne $LASTEXITCODE) { $LASTEXITCODE } else { 0 }

        foreach ($item in @($raw)) {
            if ($null -eq $item) { continue }

            $text = if ($item -is [System.Management.Automation.ErrorRecord]) {
                $item.Exception.Message
            }
            else {
                [string] $item
            }

            foreach ($part in ($text -split "`r?`n")) {
                if ($part.Trim()) { $lines.Add($part) | Out-Null }
            }
        }
    }
    catch {
        $lines.Add($_.Exception.Message) | Out-Null
        $code = 1
    }
    finally {
        $ErrorActionPreference = $previousPreference
    }

    if (-not $Quiet) {
        foreach ($line in $lines) {
            Write-Host "  $line" -ForegroundColor DarkGray
        }
    }

    return [PSCustomObject]@{
        Output   = @($lines)
        ExitCode = $code
        Ok       = ($code -eq 0)
    }
}

# The argument list is passed as ONE array, deliberately.
#
# With ValueFromRemainingArguments, PowerShell still binds by parameter-name
# prefix first -- so `Invoke-CNGit add -A` bound "-A" to the -Arguments
# parameter and failed with "Missing an argument for parameter 'Arguments'".
# git's flags cover most of the alphabet, so there is no safe parameter name.
# Wrapping them in an array removes the ambiguity entirely.
function Invoke-CNGit {
    param(
        [Parameter(Mandatory = $true, Position = 0)] [string[]] $GitArguments,
        [switch] $Quiet
    )

    return Invoke-CNNative -Executable 'git' -Arguments $GitArguments -Quiet:$Quiet
}

# Sorts version-like tags newest first. A plain string sort puts v0.9.0 above
# v0.15.0, which makes "newest remote tags" actively misleading.
function Sort-CNVersionTag {
    param([string[]] $Tags)

    return @($Tags | Sort-Object -Property @{ Expression = {
        $text = $_ -replace '^v', ''
        $parts = @(($text -split '\.') | ForEach-Object { [int]($_ -replace '\D', '0') })

        while ($parts.Count -lt 3) { $parts += 0 }

        ($parts[0] * 1000000) + ($parts[1] * 1000) + $parts[2]
    } } -Descending)
}

function Invoke-CNFixtures {
    # THE POINT OF THIS COMMAND.
    #
    # Nine defects in this addon came from a test stub that modelled the world
    # more simply than the world is. No amount of writing better stubs fixes
    # that, because the author of a stub does not know which part of reality he
    # simplified. The only cure is real data: /cn capture records what the live
    # client actually returned, and this lifts that recording out of
    # SavedVariables into fixtures\captured.lua, where the harness audits its
    # own stubs against it.
    #
    # ONLY the capture table is copied. SavedVariables also holds character
    # names, realms and play history, none of which belongs in a repository.
    Assert-CNWritable

    $saved = $null

    if ($Target) {
        if (-not (Test-Path -LiteralPath $Target)) {
            Write-Host "Not found: $Target" -ForegroundColor Yellow
            return
        }

        $saved = Get-Item -LiteralPath $Target
    }
    else {
        foreach ($root in @(Get-CNSavedVariablesRoots)) {
            $found = Get-ChildItem -LiteralPath $root -Recurse -Filter 'CompletionNavigator.lua' -File -ErrorAction SilentlyContinue |
                Sort-Object LastWriteTime -Descending |
                Select-Object -First 1

            if ($found) { $saved = $found; break }
        }

        if (-not $saved) {
            Write-Host 'No SavedVariables found.' -ForegroundColor Yellow
            Write-Host '  Log in, run /cn capture, log out, then try again.' -ForegroundColor DarkGray
            Write-Host '  Or point at the file:  .\cn.ps1 fixtures <path>' -ForegroundColor DarkGray
            return
        }
    }

    Write-Host "Reading $($saved.FullName)" -ForegroundColor DarkGray

    $text = [System.IO.File]::ReadAllText($saved.FullName)

    $marker = [regex]::Match($text, '\["capture"\]\s*=\s*\{')

    if (-not $marker.Success) {
        Write-Host 'No capture in SavedVariables.' -ForegroundColor Yellow
        Write-Host '  In game: /cn capture, then log out so the file is written.' -ForegroundColor DarkGray
        return
    }

    $block = Get-CNLuaBlock -Text $text -StartIndex $marker.Index

    if (-not $block) {
        Write-Host 'The capture table is malformed; nothing was written.' -ForegroundColor Red
        return
    }

    $target = Join-Path (Get-Location) 'fixtures'

    if (-not (Test-Path -LiteralPath $target)) {
        New-Item -ItemType Directory -Path $target | Out-Null
    }

    $stamp = (Get-Date).ToString('yyyy-MM-dd HH:mm')

    $lines = @(
        '-- fixtures/captured.lua',
        '-- Recorded from a live World of Warcraft client by /cn capture and',
        "-- lifted out of SavedVariables by cn.ps1 fixtures on $stamp.",
        '--',
        '-- DO NOT EDIT. This is evidence, not source. The harness audits its own',
        '-- stubs against it: a stub missing a field that reality had is a test',
        '-- failure here rather than a bug report later.',
        '',
        # BRACES. Get-CNLuaBlock returns the INTERIOR of the block -- which is
        # what its other two callers want, and which made every recording this
        # command has ever written begin `return` followed by a bare
        # `["worldPosition"] = {`. That is not Lua. It never loaded, so the
        # stub audit -- the strongest test in this project -- silently reported
        # "no recording present" and passed for as long as the feature has
        # existed, while `check` said a recording was backing it because it
        # only ever regex-scanned the text.
        'return {',
        $block.Body,
        '}'
    )

    $file = Join-Path $target 'captured.lua'

    [System.IO.File]::WriteAllText($file, ($lines -join "`n") + "`n")

    Write-Host "  wrote  fixtures\captured.lua ($($block.Body.Length) bytes)" -ForegroundColor Green
    Write-Host '  The harness picks it up automatically the next time it runs.' -ForegroundColor DarkGray
}

function Invoke-CNInterface {
    # WHAT TO DO WHEN THE GAME PATCHES.
    #
    # Every expansion and most major patches bump the interface number, and an
    # addon whose .toc is behind is shown as out of date -- which players read
    # as broken. The bump itself is trivial; remembering the four things that
    # go with it is not, and "I will remember" has already failed once in this
    # project's history.
    $toc = Read-CNFile 'CompletionNavigator.toc'

    $current = if ($toc -match '(?m)^##\s*Interface:\s*(\d+)') { $Matches[1] } else { '?' }

    $new = if ($Target) { $Target } else { $Value }

    if (-not $new) {
        Write-Host "Interface: $current" -ForegroundColor White
        Write-Host ''
        Write-Host '  Set a new one with:  .\cn.ps1 interface 120200' -ForegroundColor DarkGray
        Write-Host ''
        Write-Host '  The number is (major * 10000) + (minor * 100) + patch:' -ForegroundColor DarkGray
        Write-Host '  11.0.2 is 110002, 12.1.0 is 120100.' -ForegroundColor DarkGray
        return
    }

    if ($new -notmatch '^\d{5,6}$') {
        Write-Host 'An interface version looks like 120100.' -ForegroundColor Yellow
        return
    }

    Assert-CNWritable

    $toc = [regex]::Replace($toc, '(?m)^##\s*Interface:\s*\d+', "## Interface: $new")
    Write-CNFile 'CompletionNavigator.toc' $toc

    Write-Host "Interface set to $new (was $current)." -ForegroundColor Green
    Write-Host ''
    Write-Host 'The rest of the patch checklist, in order:' -ForegroundColor White
    Write-Host ''
    Write-Host '  1. Log in and run  /cn selftest' -ForegroundColor Gray
    Write-Host '     Fifteen checks against the live client. A renamed or removed' -ForegroundColor DarkGray
    Write-Host '     API shows up here as a FAIL rather than as a bug report.' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  2. Run  /cn capture  then  .\cn.ps1 fixtures' -ForegroundColor Gray
    Write-Host '     Re-records what the client actually returns. A patch that' -ForegroundColor DarkGray
    Write-Host '     changes the shape of a return value is caught by the suite' -ForegroundColor DarkGray
    Write-Host '     instead of by somebody playing.' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  3. Check  /cn errors  after half an hour of play' -ForegroundColor Gray
    Write-Host '     Failures inside the addon are caught so they cannot break' -ForegroundColor DarkGray
    Write-Host '     your session, which is also why they are invisible.' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  4. Run  .\cn.ps1 check  and  bash mutate.sh' -ForegroundColor Gray
    Write-Host ''
    Write-Host '  5. Only then bump the version and release.' -ForegroundColor Gray
}

function Invoke-CNContribution {
    # FOLDS A `/cn contribute` STRING INTO Data\Community.lua.
    #
    # The addon can produce the string and can import one in game; what was
    # missing was the path that gets a contribution from a player's issue into
    # the shipped package -- which is the only step that makes a contribution
    # worth anything to anybody else.
    #
    # Community rows are held apart from curated ones deliberately: they are
    # believed because several installs agreed, not because a human checked.
    # Merging the two files would be a one-line convenience that destroyed the
    # distinction permanently.
    Assert-CNWritable

    $text = if ($Target) { $Target } else { $Value }

    if (-not $text) {
        Write-Host 'Usage: .\cn.ps1 contribution "CN1 100:98,99 200:150"' -ForegroundColor Yellow
        Write-Host ''
        Write-Host '  The string comes from /cn contribute in game.' -ForegroundColor DarkGray
        return
    }

    $text = $text.Trim()

    if ($text -notmatch '^CN1\s+') {
        Write-Host 'Not a Completion Navigator export (expected it to start with CN1).' -ForegroundColor Red
        return
    }

    $entries = @{}
    $malformed = 0

    foreach ($token in ($text -replace '^CN1\s+', '') -split '\s+') {
        if (-not $token) { continue }

        if ($token -match '^(\d+):([\d,]+)$') {
            $questID = [int] $Matches[1]

            $ids = @()

            foreach ($id in ($Matches[2] -split ',')) {
                if ($id) { $ids += [int] $id }
            }

            if ($ids.Count -gt 0) { $entries[$questID] = $ids }
        }
        else {
            $malformed++
        }
    }

    if ($malformed -gt 0) {
        # Strict, exactly as the in-game importer is: a half-parsed
        # contribution silently teaches the addon a chain nobody wrote.
        Write-Host "$malformed malformed entry(ies); nothing was written." -ForegroundColor Red
        return
    }

    if ($entries.Count -eq 0) {
        Write-Host 'No entries in that string.' -ForegroundColor Yellow
        return
    }

    $relative = 'Data\Community.lua'
    $existing = Read-CNFile $relative

    if ($null -eq $existing) { throw "$relative not found. Run: .\cn.ps1 init" }

    $lines   = New-Object System.Collections.Generic.List[string]
    $added   = 0
    $skipped = 0

    foreach ($questID in ($entries.Keys | Sort-Object)) {
        if ($existing -match ('\[\s*' + $questID + '\s*\]\s*=')) {
            $skipped++
            continue
        }

        $ids = $entries[$questID] -join ', '

        $lines.Add("    [$questID] = { requires = { $ids }, sources = 1 },") | Out-Null

        $added++
    }

    Write-Host "Entries in the contribution: $($entries.Count)" -ForegroundColor White
    Write-Host "  already present            $skipped" -ForegroundColor DarkGray
    Write-Host "  new rows to add            $added" -ForegroundColor $(if ($added -gt 0) { 'Green' } else { 'DarkGray' })

    if ($added -eq 0) {
        Write-Host 'Nothing to add.' -ForegroundColor Yellow
        return
    }

    Invoke-CNBackup -Quiet

    Add-CNBlock -Relative $relative -Block ($lines -join "`n") -Marker '-- CN:DATA:COMMUNITY'

    Write-Host "Added $added row(s) to $relative" -ForegroundColor Green
    Write-Host ''
    Write-Host '  sources = 1 means ONE contributor agreed. Raise it as more' -ForegroundColor DarkGray
    Write-Host '  arrive; below two, a row does not belong in that file.' -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  Next:  .\cn.ps1 check' -ForegroundColor DarkGray
}

function Invoke-CNProvenance {
    # WHICH DATA ROWS HAS A HUMAN ACTUALLY CHECKED?
    #
    # Three sources now feed the quest database and they are not equally
    # trustworthy: rows somebody curated, rows folded in from observed play,
    # and rows contributed by other players' installs. The distinction is
    # carefully preserved at runtime -- /cn why says which kind it is quoting
    # -- and was invisible in the repository, where the decisions get made.
    #
    # Reports each group, and specifically the rows marked as observed, which
    # are the ones worth spot-checking against a wiki before a release.
    $quests = Read-CNFile 'Data\Quests.lua'

    if ($null -eq $quests) { throw "Data\Quests.lua not found. Run: .\cn.ps1 init" }

    $community = Read-CNFile 'Data\Community.lua'

    $curated      = 0
    $observed     = 0
    $observedIDs  = @()

    foreach ($match in [regex]::Matches($quests, '(?m)^\s*\[(\d+)\]\s*=\s*\{')) {
        $block = Get-CNLuaBlock -Text $quests -StartIndex $match.Index

        if (-not $block) { continue }

        if ($block.Body -match 'chain observed on') {
            $observed++

            # NAMED, NOT COUNTED.
            #
            # This reported three numbers and told you to spot-check -- and
            # then made you open the file and find the rows yourself. A
            # command that says "check these" without saying WHICH is a
            # command whose advice nobody takes.
            $name = if ($block.Body -match 'name\s*=\s*"([^"]*)"') { $Matches[1] } else { '' }

            $observedIDs += [PSCustomObject]@{
                ID   = [int]$match.Groups[1].Value
                Name = $name
            }
        }
        else {
            $curated++
        }
    }

    $contributed = 0

    if ($community) {
        $contributed = ([regex]::Matches($community, '(?m)^\s*\[(\d+)\]\s*=\s*\{')).Count
    }

    Write-Host 'Quest data by provenance:' -ForegroundColor White
    Write-Host ''
    Write-Host ("  curated, checked by hand     {0}" -f $curated) -ForegroundColor Green
    Write-Host ("  folded in from observed play {0}" -f $observed) -ForegroundColor Yellow
    Write-Host ("  contributed by players       {0}" -f $contributed) -ForegroundColor DarkYellow
    Write-Host ''

    if ($observed -gt 0) {
        Write-Host '  These held on three or more characters, which is good evidence and' -ForegroundColor DarkGray
        Write-Host '  is not the same as somebody having looked:' -ForegroundColor DarkGray
        Write-Host ''

        foreach ($row in ($observedIDs | Sort-Object ID)) {
            Write-Host ("    {0,-8} {1}" -f $row.ID, $row.Name) -ForegroundColor Yellow
        }

        Write-Host ''
        Write-Host '  Check one against a wiki, then delete its `chain observed on`' -ForegroundColor DarkGray
        Write-Host '  comment -- that comment IS the unchecked marker.' -ForegroundColor DarkGray
        Write-Host ''
    }

    if ($contributed -gt 0) {
        Write-Host '  Contributed rows live in Data\Community.lua and are published as' -ForegroundColor DarkGray
        Write-Host '  observations, never as curated data. Merging the two files would' -ForegroundColor DarkGray
        Write-Host '  destroy that distinction permanently.' -ForegroundColor DarkGray
        Write-Host ''
    }

    $total = $curated + $observed + $contributed

    if ($total -eq 0) {
        Write-Host '  Nothing yet. The database fills from play:' -ForegroundColor DarkGray
        Write-Host '    /cn harvestnow, log out, then .\cn.ps1 harvest' -ForegroundColor DarkGray
    }
}

function Invoke-CNRelease {
    Assert-CNWritable

    $new = if ($Target) { $Target } else { $Value }

    if (-not $new -or $new -notmatch '^\d+\.\d+\.\d+$') {
        Write-Host 'Usage: .\cn.ps1 release <x.y.z>' -ForegroundColor Yellow
        return
    }

    # ------------------------------------------------------------------
    # Everything that can refuse the release happens BEFORE anything is
    # written, cheapest and most fundamental first.
    #
    # An earlier version bumped the version files and then bailed on a missing
    # changelog section, which left the tree claiming a version whose source
    # was never scaffolded. Nothing downstream could then be trusted, and the
    # only signal was a yellow warning that scrolled past.
    # ------------------------------------------------------------------

    # 1. Does this cn.ps1 even carry the source being released? Checked before
    #    anything else, because every other diagnosis is misleading when the
    #    answer here is no.
    if ($script:ToolkitVersion -ne $new) {
        Write-Host "ERROR  This cn.ps1 carries version $script:ToolkitVersion, not $new." -ForegroundColor Red
        Write-Host ''
        Write-Host '  The addon source is embedded in this file. Releasing a version it' -ForegroundColor DarkGray
        Write-Host '  does not carry would tag whatever happens to be on disk.' -ForegroundColor DarkGray
        Write-Host ''
        Write-Host "  Either get the cn.ps1 for $new, or run:  .\cn.ps1 release $script:ToolkitVersion" -ForegroundColor Yellow
        return
    }

    # 2. Is git usable and is this a repository?
    if (-not (Assert-CNGit)) { return }

    if (-not (Test-Path -LiteralPath (Join-Path $script:Root '.git'))) {
        Write-Host 'Not a git repository. Run: .\cn.ps1 gitinit' -ForegroundColor Yellow
        return
    }

    # 3. Is the changelog ready? Checked before any file is touched.
    $changelog = Read-CNFile 'CHANGELOG.md'

    if ($changelog -and $changelog -notmatch [regex]::Escape("## [$new]")) {
        Write-Host "ERROR  CHANGELOG.md has no '## [$new]' section." -ForegroundColor Red
        Write-Host ''
        Write-Host '  Nothing has been changed. If the changelog on disk is stale, run:' -ForegroundColor DarkGray
        Write-Host '    .\cn.ps1 init -Force' -ForegroundColor Yellow
        Write-Host '  Or re-run with -Force to tag without a changelog entry.' -ForegroundColor DarkGray
        return
    }

    # 4. Does a tag already exist? git tag fails on a duplicate, and the
    #    failure is easy to miss in the middle of a release.
    Push-Location $script:Root

    try {
        $existing = @((Invoke-CNGit @('tag', '--list', "v$new") -Quiet).Output)

        if ($existing.Count -gt 0 -and -not $Force -and -not $Retag) {
            Write-Host "ERROR  Tag v$new already exists." -ForegroundColor Red
            Write-Host ''

            # THE COMMON CASE IS A FAILED BUILD, NOT A MISTAKE.
            #
            # A release whose workflow fails leaves the tag behind, so the
            # retry -- the whole point of fixing whatever failed -- is refused
            # by this guard. That happened four times in a row, and each time
            # the answer was two git commands typed by hand from a message
            # that scrolled past. Retrying a failed release is the normal
            # path; it should be one word, not a recipe.
            Write-Host '  If the last attempt failed and you are retrying, re-run with:' -ForegroundColor DarkGray
            Write-Host "    .\cn.ps1 release $new -Retag" -ForegroundColor Yellow
            Write-Host ''
            Write-Host '  That deletes the tag here and on the remote, then releases again.' -ForegroundColor DarkGray
            Write-Host '  Nothing has been changed.' -ForegroundColor DarkGray
            return
        }

        if ($existing.Count -gt 0 -and $Retag) {
            Write-Host "Replacing tag v$new." -ForegroundColor Yellow

            Invoke-CNGit @('tag', '-d', "v$new") -Quiet | Out-Null

            # The remote tag may not exist -- the push may be what failed --
            # so a failure here is expected and not worth stopping for.
            Invoke-CNGit @('push', '--delete', 'origin', "v$new") -Quiet | Out-Null
        }
    }
    finally {
        Pop-Location
    }

    # 5. Does it pass its own validator? A failing check must stop the
    #    release, not merely print in front of it.
    Write-Host 'Validating...' -ForegroundColor Cyan

    $problems = Invoke-CNCheck

    Write-Host ''

    if ($problems -gt 0 -and -not $Force) {
        Write-Host "ERROR  $problems problem(s) found; not releasing." -ForegroundColor Red
        Write-Host '  Nothing has been changed. Fix them, or re-run with -Force.' -ForegroundColor DarkGray
        return
    }

    # ------------------------------------------------------------------
    # Past this line, the tree gets written to.
    # ------------------------------------------------------------------

    $Target = $new
    Invoke-CNVersion

    Push-Location $script:Root

    try {
        Invoke-CNGit @('add', '-A') -Quiet | Out-Null

        # An empty commit is not an error here: init may have written exactly
        # what was already committed. The tag is what matters.
        Invoke-CNGit @('commit', '-m', "Release $new") | Out-Null

        Invoke-CNGit @('tag', "v$new") | Out-Null

        if (-not @((Invoke-CNGit @('tag', '--list', "v$new") -Quiet).Output)) {
            Write-Host "ERROR  Tag v$new was not created. Not pushing." -ForegroundColor Red
            return
        }

        $head = @((Invoke-CNGit @('rev-parse', '--short', 'HEAD') -Quiet).Output)[0]

        Write-Host "Tagged v$new at $head." -ForegroundColor Green

        # The packager derives the release type from a tag pointing at HEAD.
        # No tag there means it publishes as an alpha, which then hides behind
        # "Show alpha files" on CurseForge.
        $atHead = @((Invoke-CNGit @('tag', '--points-at', 'HEAD') -Quiet).Output)

        if ($atHead -notcontains "v$new") {
            Write-Host "ERROR  v$new does not point at HEAD; CurseForge would get an alpha." -ForegroundColor Red
            Write-Host "  tags at HEAD: $($atHead -join ', ')" -ForegroundColor DarkGray
            return
        }

        $remote = @((Invoke-CNGit @('remote') -Quiet).Output)

        if (-not $remote) {
            Write-Host 'No git remote configured, so nothing was pushed.' -ForegroundColor Yellow
            Write-Host '  git remote add origin <url>' -ForegroundColor DarkGray
            Write-Host '  git push -u origin main --tags' -ForegroundColor DarkGray
            return
        }

        if (-not (Invoke-CNGit @('push')).Ok) {
            Write-Host 'ERROR  git push failed. The tag exists locally but was not pushed.' -ForegroundColor Red
            Write-Host '  Recover with:  git push ; git push --tags' -ForegroundColor Yellow
            return
        }

        if (-not (Invoke-CNGit @('push', '--tags')).Ok) {
            Write-Host 'ERROR  git push --tags failed. CurseForge will not see this release.' -ForegroundColor Red
            Write-Host '  Recover with:  git push --tags' -ForegroundColor Yellow
            return
        }

        # PUSHED IS NOT PUBLISHED, AND THIS USED TO SAY IT WAS.
        #
        # The old line was "Pushed vX. GitHub Actions packages and uploads to
        # CurseForge." -- a statement about the future, in green, reading as an
        # outcome. It was wrong for three consecutive releases: the build was
        # failing at a step before the packager, so nothing was uploaded, and
        # the author reported all three as live because the tool said so.
        #
        # A release command may only report what it did. Everything after the
        # push belongs to a machine this command cannot see.
        # AND A PUSH THAT STARTS NO RUN IS A FAILED RELEASE. 0.67.2.
        #
        # The push can succeed and nothing happen: Actions disabled on the
        # repository, the workflow removed from the default branch, a tag
        # filter that no longer matches. The command then reported a healthy
        # push, `ci -Watch` reported the PREVIOUS version's run because that
        # is the newest one there is, and the release looked like a build
        # failure rather than like a build that never started.
        #
        # Asked once, after a pause. Not a poll: this is a yes/no about
        # whether the push was seen at all.
        Start-Sleep -Seconds 12

        $started = Invoke-CNGitHubApi `
            -Uri "https://api.github.com/repos/$script:Repo/actions/runs?per_page=5" `
            -CacheSeconds 0

        $mine = $null

        if ($started) {
            $mine = $started.workflow_runs |
                Where-Object { $_.display_title -match [regex]::Escape($new) } |
                Select-Object -First 1
        }

        if ($started -and -not $mine) {
            Write-Host ''
            Write-Host "WARNING  v$new was pushed and GitHub has started no run for it." -ForegroundColor Yellow
            Write-Host '  It may still appear a moment from now. If it does not, check:' -ForegroundColor DarkGray
            Write-Host '    1. Actions is enabled for this repository.' -ForegroundColor DarkGray
            Write-Host '    2. .github/workflows/release.yml is on the default branch.' -ForegroundColor DarkGray
            Write-Host '    3. Its trigger still matches this tag shape.' -ForegroundColor DarkGray
            Write-Host ''
            Write-Host '  Until a run exists, .\cn.ps1 ci -Watch is watching an OLDER release.' -ForegroundColor Yellow
        }

        Write-Host ''
        Write-Host "Pushed v$new. Nothing is published yet." -ForegroundColor Green
        Write-Host '  The build has to pass before CurseForge sees anything, and it' -ForegroundColor DarkGray
        Write-Host '  can fail after this command has succeeded. Watch it finish:' -ForegroundColor DarkGray
        Write-Host ''
        Write-Host '    .\cn.ps1 ci -Watch' -ForegroundColor Yellow
        Write-Host ''
        Write-Host '  (one command, follows the run to the end -- do not re-run ci' -ForegroundColor DarkGray
        Write-Host '   in a loop; that is how the API budget goes)' -ForegroundColor DarkGray
        Write-Host ''
        Write-Host '  Then confirm the file actually exists:  .\cn.ps1 doctor' -ForegroundColor DarkGray
    }
    finally {
        Pop-Location
    }
}

# Prints the whole release chain in one place. Written because diagnosing a
# release that silently did nothing meant assembling five separate commands
# by hand.
function Invoke-CNDoctor {
    Write-Host 'Completion Navigator :: doctor' -ForegroundColor Cyan
    Write-Host ''

    $toc  = Read-CNFile 'CompletionNavigator.toc'
    $core = Read-CNFile 'Core.lua'

    $tocVersion  = if ($toc  -match '(?m)^##\s*Version:\s*(.+)$') { $Matches[1].Trim() } else { '(none)' }
    $coreVersion = if ($core -match 'CN\.version\s*=\s*"([^"]+)"') { $Matches[1] } else { '(none)' }

    $luaCount = @(Get-CNLuaFiles).Count

    Write-Host 'Toolkit' -ForegroundColor White
    Write-Host "  cn.ps1 carries version   $script:ToolkitVersion"
    Write-Host "  cn.ps1 size              $((Get-Item $PSCommandPath).Length) bytes"
    Write-Host ''

    Write-Host 'Tree' -ForegroundColor White
    Write-Host "  .toc version             $tocVersion"
    Write-Host "  Core.lua version         $coreVersion"
    Write-Host "  Lua files on disk        $luaCount"

    $changelog = Read-CNFile 'CHANGELOG.md'

    $hasSection = $changelog -and $changelog -match [regex]::Escape("## [$coreVersion]")

    Write-Host ("  CHANGELOG [$coreVersion]" + (' ' * [Math]::Max(1, 15 - $coreVersion.Length)) +
        $(if ($hasSection) { 'present' } else { 'MISSING' })) `
        -ForegroundColor $(if ($hasSection) { 'Gray' } else { 'Red' })
    Write-Host ''

    if ((Compare-CNVersion $script:ToolkitVersion $coreVersion) -lt 0) {
        Write-Host '  This cn.ps1 is OLDER than the tree. init would downgrade your source.' -ForegroundColor Red
        Write-Host ''
    }

    if (-not (Test-Path -LiteralPath (Join-Path $script:Root '.git'))) {
        Write-Host 'Git' -ForegroundColor White
        Write-Host '  not a repository' -ForegroundColor Yellow
        return
    }

    if (-not (Assert-CNGit)) { return }

    Push-Location $script:Root

    try {
        Write-Host 'Git' -ForegroundColor White
        $head    = @((Invoke-CNGit @('rev-parse', '--short', 'HEAD') -Quiet).Output)[0]
        $subject = @((Invoke-CNGit @('log', '-1', '--pretty=%s') -Quiet).Output)[0]

        Write-Host "  HEAD                     $head $subject"

        $atHead = @((Invoke-CNGit @('tag', '--points-at', 'HEAD') -Quiet).Output)

        Write-Host ("  tags at HEAD             " +
            $(if ($atHead.Count) { $atHead -join ', ' } else { '(none)' })) `
            -ForegroundColor $(if ($atHead.Count) { 'Gray' } else { 'Yellow' })

        $dirty = @((Invoke-CNGit @('status', '--porcelain') -Quiet).Output)

        Write-Host ("  uncommitted changes      " +
            $(if ($dirty.Count) { "$($dirty.Count) file(s)" } else { 'none' }))

        $remote = @((Invoke-CNGit @('remote') -Quiet).Output)

        if (-not $remote) {
            Write-Host '  remote                   (none)' -ForegroundColor Yellow
            return
        }

        $remoteUrl = @((Invoke-CNGit @('remote', 'get-url', 'origin') -Quiet).Output)[0]

        Write-Host "  remote                   $remoteUrl"

        $lsRemote = Invoke-CNGit @('ls-remote', '--tags', 'origin') -Quiet

        $remoteTags = @()

        if ($lsRemote.Ok) {
            $remoteTags = Sort-CNVersionTag @($lsRemote.Output |
                ForEach-Object { ($_ -split 'refs/tags/')[-1] } |
                Where-Object { $_ -and $_ -notmatch '\^\{\}$' })
        }
        else {
            Write-Host '  (could not read remote tags)' -ForegroundColor Yellow
        }

        Write-Host ("  newest remote tags       " +
            $(if ($remoteTags.Count) { ($remoteTags | Select-Object -First 3) -join ', ' } else { '(none)' }))

        Write-Host ''

        $expected = "v$coreVersion"

        if ($remoteTags -contains $expected) {
            Write-Host "$expected is on the remote. If CurseForge has no file, check the Actions run." -ForegroundColor Green
        }
        else {
            Write-Host "$expected has NOT been pushed. CurseForge cannot have it." -ForegroundColor Yellow
            Write-Host "  Run:  .\cn.ps1 release $coreVersion" -ForegroundColor DarkGray
        }
    }
    finally {
        Pop-Location
    }
}


function Invoke-CNRelocate {
    $destination = if ($Target) { $Target } else { $Value }

    if (-not $destination) {
        Write-Host 'Usage: .\cn.ps1 relocate C:\dev\CompletionNavigator' -ForegroundColor Yellow
        Write-Host ''
        Write-Host 'Copies the source out of Program Files to a writable folder, then tells' -ForegroundColor DarkGray
        Write-Host 'you how to junction it back so the game still loads it. Working under' -ForegroundColor DarkGray
        Write-Host 'Program Files means every git commit needs an elevated shell.' -ForegroundColor DarkGray
        return
    }

    if (Test-Path -LiteralPath $destination) {
        $existing = @(Get-ChildItem -LiteralPath $destination -Force -ErrorAction SilentlyContinue)

        if ($existing.Count -gt 0 -and -not $Force) {
            Write-Host "$destination already exists and is not empty." -ForegroundColor Yellow
            Write-Host 'Re-run with -Force to copy into it anyway.' -ForegroundColor Yellow
            return
        }
    }
    else {
        New-Item -ItemType Directory -Path $destination -Force | Out-Null
    }

    $copied = 0

    Get-ChildItem -LiteralPath $script:Root -Force |
        Where-Object { $_.Name -ne '_backups' } |
        ForEach-Object {
            Copy-Item -LiteralPath $_.FullName -Destination $destination -Recurse -Force
            $copied++
        }

    # Verify rather than assume: compare Lua file counts on both sides.
    $sourceCount = @(Get-CNLuaFiles).Count

    $destinationCount = @(
        Get-ChildItem -LiteralPath $destination -Recurse -Filter '*.lua' -File -ErrorAction SilentlyContinue
    ).Count

    Write-Host "Copied $copied top-level items to $destination" -ForegroundColor Green
    Write-Host "  Lua files: $sourceCount here, $destinationCount there"

    if ($sourceCount -ne $destinationCount) {
        Write-Host '  FAIL  the copy is incomplete. Do not continue.' -ForegroundColor Red
        return
    }

    Write-Host '  copy verified' -ForegroundColor Green
    Write-Host ''
    Write-Host 'Now replace this folder with a junction. PowerShell cannot delete the' -ForegroundColor Cyan
    Write-Host 'directory it is currently running from, so run these from elsewhere,' -ForegroundColor Cyan
    Write-Host 'in an ADMINISTRATOR Command Prompt:' -ForegroundColor Cyan
    Write-Host ''
    Write-Host "  cd /d C:\" -ForegroundColor DarkGray
    Write-Host "  rmdir /S /Q `"$script:Root`"" -ForegroundColor DarkGray
    Write-Host "  mklink /J `"$script:Root`" `"$destination`"" -ForegroundColor DarkGray
    Write-Host ''
    Write-Host 'After that, work in the new folder. The game reads it through the' -ForegroundColor Cyan
    Write-Host 'junction, and git no longer needs an elevated shell.' -ForegroundColor Cyan
    Write-Host ''
    Write-Host "A backup of the current folder is in _backups if you want one first:" -ForegroundColor DarkGray
    Write-Host '  .\cn.ps1 backup' -ForegroundColor DarkGray
}


function Invoke-CNIcon {
    Assert-CNWritable

    $source = if ($Target) { $Target } else { $Value }

    if (-not $source) {
        # Default to the logo dropped into the CurseForge assets folder.
        $source = Join-Path $script:Root '_curseforge\logo.png'
    }

    if (-not (Test-Path -LiteralPath $source)) {
        Write-Host "Source image not found: $source" -ForegroundColor Yellow
        Write-Host 'Usage: .\cn.ps1 icon <path-to-png>' -ForegroundColor Yellow
        Write-Host 'Or drop logo.png into _curseforge\ and run: .\cn.ps1 icon' -ForegroundColor DarkGray
        return
    }

    # System.Drawing exists on Windows PowerShell but is unavailable on other
    # hosts, and it fails at first use rather than at load, so probing the
    # type is not enough -- actually try to use it.
    try {
        Add-Type -AssemblyName System.Drawing -ErrorAction Stop
        $null = New-Object System.Drawing.Bitmap(1, 1)
    }
    catch {
        Write-Host 'System.Drawing is not usable on this PowerShell host, so the' -ForegroundColor Red
        Write-Host 'TGA cannot be generated here.' -ForegroundColor Red
        Write-Host ''
        Write-Host 'Media\Logo.tga is committed to the repository, so unless you are' -ForegroundColor Yellow
        Write-Host 'replacing the artwork you do not need this command at all.' -ForegroundColor Yellow
        Write-Host ''
        Write-Host 'To replace it by hand: export a 128x128 uncompressed 32-bit TGA' -ForegroundColor DarkGray
        Write-Host 'and save it as Media\Logo.tga' -ForegroundColor DarkGray
        return
    }

    $mediaDirectory = Join-Path $script:Root 'Media'

    if (-not (Test-Path -LiteralPath $mediaDirectory)) {
        New-Item -ItemType Directory -Path $mediaDirectory -Force | Out-Null
    }

    $size = 128

    try {
        $original = [System.Drawing.Bitmap]::FromFile((Resolve-Path -LiteralPath $source))
    }
    catch {
        Write-Host "Could not read the image: $_" -ForegroundColor Red
        return
    }

    try {
        # WoW requires power-of-two dimensions. 128x128 is the standard for an
        # addon icon and stays crisp on the minimap button.
        $resized = New-Object System.Drawing.Bitmap($size, $size)

        $graphics = [System.Drawing.Graphics]::FromImage($resized)
        $graphics.InterpolationMode  = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.SmoothingMode      = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
        $graphics.PixelOffsetMode    = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $graphics.DrawImage($original, 0, 0, $size, $size)
        $graphics.Dispose()

        # Uncompressed 32-bit BGRA TGA, bottom-up. The client will not read a
        # PNG, and it fails silently rather than erroring.
        $pixels = New-Object 'System.Collections.Generic.List[byte]'

        for ($y = $size - 1; $y -ge 0; $y--) {
            for ($x = 0; $x -lt $size; $x++) {
                $pixel = $resized.GetPixel($x, $y)

                $pixels.Add($pixel.B)
                $pixels.Add($pixel.G)
                $pixels.Add($pixel.R)
                $pixels.Add($pixel.A)
            }
        }

        $header = [byte[]]@(
            0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0,
            ($size -band 0xFF), (($size -shr 8) -band 0xFF),
            ($size -band 0xFF), (($size -shr 8) -band 0xFF),
            32, 8
        )

        $output = Join-Path $mediaDirectory 'Logo.tga'

        $stream = [System.IO.File]::Create($output)
        $stream.Write($header, 0, $header.Length)
        $stream.Write($pixels.ToArray(), 0, $pixels.Count)
        $stream.Close()

        $resized.Dispose()

        Write-Host "Wrote Media\Logo.tga  ($size x $size, 32-bit uncompressed)" -ForegroundColor Green
        Write-Host '  used by the .toc IconTexture line and the minimap button'
        Write-Host '  /reload in game to see it'
    }
    finally {
        $original.Dispose()
    }

    Invoke-CNSync
}

function Invoke-CNOpen {
    Start-Process explorer.exe $script:Root
}

function Show-CNHelp {
    Write-Host ''
    Write-Host 'Completion Navigator toolkit' -ForegroundColor Cyan
    Write-Host "  $script:Root" -ForegroundColor DarkGray
    Write-Host ''
    Write-Host '  init                            Scaffold the modular tree (backs up first).'
    Write-Host '  sync                            Rewrite the .toc file list from what is on disk.'
    Write-Host '  check                           Validate .toc, BOMs, duplicate commands, versions, syntax.'
    Write-Host '  list                            Show load order, slash commands, and events.'
    Write-Host ''
    Write-Host '  new module <Name>               Create Modules\<Name>.lua and sync.'
    Write-Host '  new provider <Name>             Create Providers\<Name>.lua and sync.'
    Write-Host '  new data <Name>                 Create Data\<Name>.lua and sync.'
    Write-Host ''
    Write-Host '  cmd <name> -Module <M>          Register a /cn subcommand stub.'
    Write-Host '        [-Usage "<id>"] [-Help "text"] [-Order 50]'
    Write-Host '  event <EVENT> -Module <M>       Register an event handler stub.'
    Write-Host '  data quest <id> -Name "Title"   Add a curated quest row.'
    Write-Host '        [-Expansion X] [-MapID N] [-X 0.5] [-Y 0.5] [-Requires "1,2"]'
    Write-Host ''
    Write-Host '  version [x.y.z]                 Show or set the version in .toc and Core.lua.'
    Write-Host '  backup                          Zip the addon into _backups.'
    Write-Host '  restore -Force                  Restore the newest backup.'
    Write-Host '  package                         Build a distributable zip.'
    Write-Host '  savedvars [-Force]              Locate SavedVariables (-Force opens it).'
    Write-Host '  release <x.y.z>                Bump, commit, tag and push a release.'
    Write-Host '  ci [-Watch]                    GitHub Actions status; -Watch follows a run to the end.'
    Write-Host '  doctor                         Report the whole release chain state.'
    Write-Host '  harvest [path]                 Fold harvested quests from SavedVariables into Data.'
    Write-Host '  fixtures [path]                Lift a /cn capture recording out of SavedVariables for the tests.'
    Write-Host '  interface [number]             Show or set the game interface version, with the patch checklist.'
    Write-Host '  contribution "<CN1 ...>"       Fold a /cn contribute string into Data\Community.lua.'
    Write-Host '  provenance                     Which data rows are curated, observed, or contributed.'
    Write-Host '  relocate <path>                Copy the source out of Program Files.'
    Write-Host '  icon [path.png]                Convert a PNG into Media\Logo.tga for in-game use.'
    Write-Host '  gitinit                         Initialize git with a sane .gitignore.'
    Write-Host '  open                            Open the folder in Explorer.'
    Write-Host ''
    Write-Host 'Examples' -ForegroundColor Cyan
    Write-Host '  .\cn.ps1 init'
    Write-Host '  .\cn.ps1 new module Pets'
    Write-Host '  .\cn.ps1 cmd pets -Module Pets -Usage "<speciesID>" -Help "Check a battle pet." -Order 30'
    Write-Host '  .\cn.ps1 event PET_JOURNAL_LIST_UPDATE -Module Pets'
    Write-Host '  .\cn.ps1 data quest 8238 -Name "The Battle for Andorhal" -Expansion "Classic"'
    Write-Host '  .\cn.ps1 version 0.2.0; .\cn.ps1 check'
    Write-Host ''
}

############################################################
# DISPATCH
############################################################

switch ($Command.ToLower()) {
    'init'      { Invoke-CNInit }
    'sync'      { Invoke-CNSync }
    'check'     { Invoke-CNCheck | Out-Null }
    'list'      { Invoke-CNList }
    'new'       { Invoke-CNNew }
    'cmd'       { Invoke-CNCommand }
    'command'   { Invoke-CNCommand }
    'event'     { Invoke-CNEvent }
    'data'      { Invoke-CNData }
    'version'   { Invoke-CNVersion }
    'backup'    { Invoke-CNBackup }
    'restore'   { Invoke-CNRestore }
    'package'   { Invoke-CNPackage }
    'savedvars' { Invoke-CNSavedVars }
    'sv'        { Invoke-CNSavedVars }
    'harvest'   { Invoke-CNHarvest }
    'fixtures'  { Invoke-CNFixtures }
    'interface' { Invoke-CNInterface }
    'contribution' { Invoke-CNContribution }
    'provenance' { Invoke-CNProvenance }
    'release'   { Invoke-CNRelease }
    'ci'        { Invoke-CNCI }
    'actions'   { Invoke-CNCI }
    'doctor'    { Invoke-CNDoctor }
    'status'    { Invoke-CNDoctor }
    'relocate'  { Invoke-CNRelocate }
    'icon'      { Invoke-CNIcon }
    'gitinit'   { Invoke-CNGitInit }
    'git-init'  { Invoke-CNGitInit }
    'open'      { Invoke-CNOpen }
    'help'      { Show-CNHelp }
    default {
        Write-Host "Unknown command: $Command" -ForegroundColor Red
        Show-CNHelp
    }
}
